prompt ======================
prompt
create table SM.ADDRESS
(
  ID              NUMBER(27) not null,
  HOUSE           VARCHAR2(30),
  APPARTMENT      VARCHAR2(10),
  QUARTER         VARCHAR2(7),
  TANK            VARCHAR2(3),
  ROOM            VARCHAR2(15),
  STREETS_ID      NUMBER(27),
  TOWNAREA_ID     NUMBER(27),
  PROVINCEAREA_ID NUMBER(27),
  ADDON           VARCHAR2(1100),
  BTILITER        VARCHAR2(80),
  POSTCODE        CHAR(6),
  TMP             VARCHAR2(10),
  MAIN_ID         NUMBER,
  HOUSE_CHAR      VARCHAR2(3),
  TOWNNAMES_ID    NUMBER(27),
  CHANGE_DATE     DATE,
  CHANGE_DOC      NUMBER(27),
  REGIONS_ID      NUMBER(27),
  OFFICIAL_ADDR   VARCHAR2(1100)
)
tablespace USERS
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 7M
    next 1M
    minextents 1
    maxextents unlimited
  );
comment on table SM.ADDRESS
  is 'Адрес';
comment on column SM.ADDRESS.ID
  is 'ID';
comment on column SM.ADDRESS.HOUSE
  is 'Дом {LABEL:5,123,80,15,"Дом:" FIELD:54,123,42,15}';
comment on column SM.ADDRESS.APPARTMENT
  is 'Квартира {LABEL:140,123,80,15,"Квартира:" FIELD:195,123,42,15}';
comment on column SM.ADDRESS.QUARTER
  is 'Квартал  {LABEL:270,101,80,15,"Квартал:" FIELD:374,101,70,15}';
comment on column SM.ADDRESS.TANK
  is 'Корпус {LABEL:5,146,80,15,"Корпус:" FIELD:54,146,42,15}';
comment on column SM.ADDRESS.ROOM
  is 'Помещение {LABEL:127,146,80,15,"Помещение:" FIELD:195,146,42,15}';
comment on column SM.ADDRESS.STREETS_ID
  is 'Улица ID {LABEL:5,101,80,15,"Улица:" FIELD:105,99,149,19}';
comment on column SM.ADDRESS.TOWNAREA_ID
  is 'Район ID {LABEL:5,77,80,15,"Район города:" FIELD:105,75,149,19}';
comment on column SM.ADDRESS.PROVINCEAREA_ID
  is 'Район области ID {LABEL:5,28,80,15,"Район области:" FIELD:105,26,149,19}';
comment on column SM.ADDRESS.ADDON
  is 'Дополнение к адресу {LABEL:5,169,80,15,"Дополнение к адресу: " FIELD:123,169,322,15}';
comment on column SM.ADDRESS.BTILITER
  is 'Литера БТИ {LABEL:270,77,80,15,"Литера БТИ:" FIELD:374,77,70,15}';
comment on column SM.ADDRESS.POSTCODE
  is 'Почтовый индекс {LABEL:270,54,80,15,"Почтовый индекс:" FIELD:374,54,70,15}';
comment on column SM.ADDRESS.MAIN_ID
  is 'Главный адрес';
comment on column SM.ADDRESS.HOUSE_CHAR
  is 'Буквенное дополнение к номеру дома {FIELD:102,123,23,15}';
comment on column SM.ADDRESS.TOWNNAMES_ID
  is 'Населённый пункт {LABEL:5,52,80,15,"Населённый пункт:" FIELD:105,50,149,19}';
comment on column SM.ADDRESS.CHANGE_DATE
  is 'Дата, с которой вступает изменение в силу';
comment on column SM.ADDRESS.CHANGE_DOC
  is 'Документ, на основании которого внесено изменение';
comment on column SM.ADDRESS.REGIONS_ID
  is 'Субъект {LABEL:5,4,80,15,"Субъект:" FIELD:105,2,149,19} ';
alter table SM.ADDRESS
  add primary key (ID)
  using index 
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 3M
    next 1M
    minextents 1
    maxextents unlimited
  );
alter table SM.ADDRESS
  add constraint FK_ADDRESS_DOCUMENTS foreign key (CHANGE_DOC)
  references SM.DOCUMENTS (ID);
alter table SM.ADDRESS
  add constraint FK_ADDRESS_REGIONS_ID foreign key (REGIONS_ID)
  references SM.REGIONS (ID);
alter table SM.ADDRESS
  add constraint FK_ADDRESS_TOWNAREA_ID foreign key (TOWNAREA_ID)
  references SM.TOWNAREA (ID);
alter table SM.ADDRESS
  add constraint FK_ADDRESS_TOWNNAMES foreign key (TOWNNAMES_ID)
  references SM.TOWNNAMES (ID);
alter table SM.ADDRESS
  add constraint FK_MAIN_ID foreign key (MAIN_ID)
  references SM.ADDRESS (ID) on delete cascade;
alter table SM.ADDRESS
  add foreign key (PROVINCEAREA_ID)
  references SM.PROVINCEAREA (ID);
alter table SM.ADDRESS
  add foreign key (STREETS_ID)
  references SM.STREETS (ID);
create index SM.IDXADDRESSAREA on SM.ADDRESS (TOWNAREA_ID)
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 3M
    next 1M
    minextents 1
    maxextents unlimited
  );
create index SM.IDXADDRESSSTREET on SM.ADDRESS (STREETS_ID)
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 3M
    next 1M
    minextents 1
    maxextents unlimited
  );
create index SM.IDXADDRTWNNAME on SM.ADDRESS (TOWNNAMES_ID)
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 192K
    next 1M
    minextents 1
    maxextents unlimited
  );
create index SM.IDX_MAIN_ID on SM.ADDRESS (MAIN_ID)
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 256K
    next 1M
    minextents 1
    maxextents unlimited
  );
grant select, insert, update, delete on SM.ADDRESS to SM_ALLUSERS;
grant select on SM.ADDRESS to SM_ALL_SELECT;

