create table SM.FM_TABLES
(
  ID                    NUMBER(27) not null,
  TABLE_NAME            VARCHAR2(100) not null,
  TABLE_R               NUMBER(27),
  TYPE_ID               NUMBER(27),
  SUBTYPE               NUMBER(27),
  CAN_HISTORY           CHAR(1) default 'Y' not null,
  INTERNAL_TYPE         CHAR(1) default 'Y' not null,
  USE_IN_SEARCH         NUMBER(27) default 0,
  CREATION_NAME         VARCHAR2(50),
  CREATION_ROLE         VARCHAR2(50),
  CAN_COMPARE_ADDRESS   CHAR(1) default 'N',
  CROSS_LINKS_TABLE     CHAR(1) default 'N',
  GRANTABLE_BY_USERMAN  CHAR(1) default 'N',
  REF_COLUMN_SUBTYPE_ID VARCHAR2(60)
)
tablespace USERS
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
comment on column SM.FM_TABLES.TABLE_NAME
  is 'Название таблицы';
comment on column SM.FM_TABLES.TABLE_R
  is 'Ссылка на базовую таблицу для сущности (для субсущностей)';
comment on column SM.FM_TABLES.TYPE_ID
  is 'Идентификационный номер сущности';
comment on column SM.FM_TABLES.SUBTYPE
  is 'Идентификационный номер субсущности';
comment on column SM.FM_TABLES.CAN_HISTORY
  is 'Разрешено ли вести историю изменения значения полей';
comment on column SM.FM_TABLES.INTERNAL_TYPE
  is 'Внутренний тип';
comment on column SM.FM_TABLES.USE_IN_SEARCH
  is 'Показывать на первой странице поиска';
comment on column SM.FM_TABLES.CREATION_NAME
  is 'Название пункта в меню "Создать" главной панели SAUMI';
comment on column SM.FM_TABLES.CREATION_ROLE
  is 'Роль, позволяющая создать экземпляр данной сущности';
comment on column SM.FM_TABLES.CAN_COMPARE_ADDRESS
  is 'Возможность отображения на вкладке "Недвижимость" земельного участка';
comment on column SM.FM_TABLES.CROSS_LINKS_TABLE
  is 'Является ли таблицей перекрёстных ссылок';
comment on column SM.FM_TABLES.GRANTABLE_BY_USERMAN
  is 'Отображать в списке таблиц Менеджера пользователей для управления правами работы с данными этой сущности';
comment on column SM.FM_TABLES.REF_COLUMN_SUBTYPE_ID
  is 'Название поля базовой таблицы, по которому можно узнать подтип экземпляра данной сущности (OBJTYPES_ID, CLIENT_TYPES_ID  и т.д. )';
alter table SM.FM_TABLES
  add primary key (ID)
  using index 
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
alter table SM.FM_TABLES
  add constraint UK_FM_TAB_NAME unique (TABLE_NAME)
  using index 
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
alter table SM.FM_TABLES
  add constraint CHK_FMTABLE_CROSS_LINKS_TABLE
  check (CROSS_LINKS_TABLE IN ('Y','N'));
alter table SM.FM_TABLES
  add constraint CH_CAN_HISTORY
  check (CAN_HISTORY IN ('Y', 'N'));
alter table SM.FM_TABLES
  add constraint CS_FMTINTTYPE
  check (INTERNAL_TYPE IN ('Y', 'N'));
grant select on SM.FM_TABLES to SM_ALLUSERS;
grant select, insert, update, delete on SM.FM_TABLES to SM_ALL_SELECT;

