comment on column SM.FM_TAB_COLUMNS.SEARCH_FULL
  is 'Используется для поиска не часто';
comment on column SM.FM_TAB_COLUMNS.FROM_LIST
  is 'Разрешить выбор значения из списка имеющихся';
comment on column SM.FM_TAB_COLUMNS.LIST_SRC
  is 'Для FromList=''Y'' что подставить вместо значения колонки';
alter table SM.FM_TAB_COLUMNS
  add primary key (ID)
  using index 
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
alter table SM.FM_TAB_COLUMNS
  add constraint UK_FM_TABID_COLID unique (FM_TABLES_ID, COLUMNS_ID);
alter table SM.FM_TAB_COLUMNS
  add constraint FK_FM_TAB_COLUMNS_FM_TABLES_ID foreign key (FM_TABLES_ID)
  references SM.FM_TABLES (ID) on delete cascade;
alter table SM.FM_TAB_COLUMNS
  add constraint CH_FM_TAB_COLUMNS_FROM_LIST
  check (FROM_LIST  IN ('Y','N'));
alter table SM.FM_TAB_COLUMNS
  add constraint CH_FM_TAB_COLUMNS_HISTORY
  check (HISTORY IN ('Y','N'));
alter table SM.FM_TAB_COLUMNS
  add constraint CH_FM_TAB_COLUMNS_SEARCH_FULL
  check (SEARCH_FULL  IN ('Y','N'));
alter table SM.FM_TAB_COLUMNS
  add constraint CH_FM_TAB_COLUMNS_SEARCH_PART
  check (SEARCH_PART IN ('Y','N'));
create index SM.IDX_FM_TABCOLUMNSTCID on SM.FM_TAB_COLUMNS (FM_TABLES_ID, COLUMNS_ID)
  tablespace USERS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
grant select on SM.FM_TAB_COLUMNS to SM_ALLUSERS;
grant select, insert, update, delete on SM.FM_TAB_COLUMNS to SM_ALL_SELECT;

