  OPER_DATE       DATE,
  WRITE_DATE      DATE,
  END_DATE        DATE,
  OBJECT_ID       NUMBER(27),
  MOVEITEM_ID     NUMBER(27),
  STATE_ID        NUMBER(27),
  DESCRIPTION     VARCHAR2(2000),
  OPERATION       VARCHAR2(400),
  OBJECT          VARCHAR2(400),
  ACC             VARCHAR2(9),
  COST            NUMBER(27,2),
  SALDO           NUMBER(27,2),
  CURRENCY_ID     NUMBER(27),
  AMOUNT          NUMBER(27,3),
  UNIT_ID         NUMBER(27),
  DC              CHAR(1),
  CORR_FLAG       CHAR(1),
  REVERSAL_ROLE   VARCHAR2(100),
  REVERSALLINK_ID NUMBER(27),
  SEQ             NUMBER(27),
  DOCUM           VARCHAR2(1000),
  MOVESET_ID      NUMBER(27)
)
tablespace USERS
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
comment on table SM.MOVE_ACC
  is 'Учётные данные по казне';
comment on column SM.MOVE_ACC.ID
  is 'ID';
comment on column SM.MOVE_ACC.APPLY_DATE
  is 'Дата принятия к учёту {LABEL:2,20,150,15,"Дата принятия к учёту:" RFIELD:155,22,100,15}';
comment on column SM.MOVE_ACC.OPER_DATE
  is 'Фактическая дата изменения правового состояния (справочный смысл){LABEL:2,40,150,15,"Фактическая дата операции:" RFIELD:155,42,100,15}';
