  check (ACTION IN ('I','U','D'));
alter table SM.SM_CHANGES
  add constraint CS_CHNGVALS
  check (decode(OLD_VALUE_NUM,null,0,1)+decode(OLD_VALUE_STR,null,0,1)+ decode(OLD_VALUE_DATE,null,0,1)<2);
