  s.HideInReports as HideInReports,
  p.writedate as WRITEDATE,
  s.Verified as VERIFIED,
  s.MunReport_ID as MUNREPORT_ID,
  TO_NUMBER(null) as BASE_MOVE_ID,
  null as PARAMS,
  null as SQUARE,
  TO_CHAR(null) as SQUARE_MAP,
  TO_CHAR(null) as REGNO,
  i.SharePercent as SHARE_PERCENT,
  TO_NUMBER(null) as MAIN_MOVE_ID,
