prompt
prompt Creating function EXPANDDOC
prompt ===========================
prompt
create or replace function sm.ExpandDoc(DocID number) return varchar2 is
--
-- by XSGROUP ver. 11.03.2009
-- Функция расшифровывает название документа по его номеру
--
  res varchar2(4000);
  DocType varchar2(2000);
  DocNo varchar2(2000);
  DocDate varchar2(600);
  DocSubscrs varchar2(4000);
  KUMI_ID integer;
  GUID sm.doctypes.guid%type;
begin

  begin
    select
      nvl(dt.Guid,'NNN')
    into
      GUID
    from
      sm.doctypes dt,
      sm.documents doc
    where
      dt.id=doc.doctypes_id and
      doc.id=DocID;
  exception
    when others then
      GUID:='NNN';
  end;

  if GUID='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE' then
    -- обрабатываем случай "Неизвестного документа"
    res:='<Неизвестный документ>';
  else
    -- для всех документов, кроме "Неизвестного документа"
    -- ID текущего распорядителя
    KUMI_ID := sm.multiowning_pkg.GetCurrentOwnerID;

    -- Выбираем органы подписания документа в одну строку
    Docsubscrs:='';
    for xx in(select
                decode(Clients.Id, KUMI_ID, 0, 1) as PR,
                RTRIM(Clients.Name) As ClientName
              from
                Documents,
                Doc_Subscribers,
                Clients
              where
                Doc_Subscribers.Document_Id=Documents.Id and
                Clients.ID(+)=Doc_Subscribers.Client_Id and
                Documents.ID=DocID
              order by PR DESC)
    loop
      if LENGTH(Docsubscrs) != 0 then
        if LENGTH(DocSubscrs || ', ' || trim(xx.ClientName))>4000 then
          if LENGTH(DocSubscrs || ', ' ||'..')>4000 then
            exit;
          else
            Docsubscrs:=DocSubscrs || ', ' ||'..';
            exit;
          end if;
        else
          Docsubscrs:=DocSubscrs || ', ' || trim(xx.ClientName);
        end if;
      else
        Docsubscrs:=trim(xx.ClientName);
      end if;
    end loop;

    -- Выбираем тип документа, номер и дату
    select
      trim(DocTypes.NAME),
      Documents.Docno,
      to_char(Documents.Docdate,'DD.MM.YYYY')
    into
      DocType,
      DocNo,
      DocDate
    from
      Documents,
      DocTypes
    where
      DocTypes.ID=Documents.Doctypes_Id and
      Documents.ID=DocID;

    -- Объединяем внутренние переменные в результат
    res:=trim(DocType);

    if trim(DocNo) != '?' then
     res:= trim(res || ' №'||DocNo);
    end if;

    res:=res || ' от '||DocDate;

    if LENGTH(Docsubscrs) != 0 then
      res:=SUBSTR(res||' - '||Docsubscrs,1,4000);
    end if;

  end if;

  return(nvl(res,''));

end;
/
grant execute on SM.EXPANDDOC to SM_ALLUSERS;
grant execute on SM.EXPANDDOC to SM_ALL_SELECT;


