prompt
prompt Creating function GETPOSITIONMOVEID
prompt ===================================
prompt
create or replace function sm.GetPositionMoveID(ObjID NUMBER, MoveTypes_ID NUMBER, AClient_id in number default NULL, AFindLast in number default NULL) return NUMBER is
  Recv NUMBER(27,0);
begin
 /* 02/03/2016 Твердохлеб: [почта письмо от 02/03/2016] - добавил на вход клиента*/

  -- ищем действующие
  begin 
   SELECT max(mi.id) INTO Recv
   FROM Clients, 
     sm.movesets ms,
     sm.moveperiods mp,
     sm.moveitems mi
   WHERE
    ms.id=mp.moveset_id and
    mp.id=mi.moveperiod_id and
    ObjID=mi.object_id(+) and
    Clients.ID(+)=ms.client_id  and
    mp.sincedate(+)<=SYSDATE and
    nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=SYSDATE and
    ms.movetype_id(+)=MoveTypes_ID and
    (ms.client_id = AClient_id or AClient_id is null);

   EXCEPTION
   WHEN NO_DATA_FOUND THEN NULL;
  end;
  
  -- если нет ничего, и можно искать в предыдущих, то поищем
  if (Recv is null and AFindLast = 1)then
    begin
     select s.id
       into Recv
       from (   
             select max(mi.id) as id               
               from Clients, 
                    sm.movesets ms,
                    sm.moveperiods mp,
                    sm.moveitems mi
              where
                    ms.id = mp.moveset_id and
                    mp.id = mi.moveperiod_id and
                    ObjID = mi.object_id(+) and
                    Clients.ID(+) = ms.client_id  and
                    nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy')) <= SYSDATE and
                    ms.movetype_id(+) = MoveTypes_ID and
                    (ms.client_id = AClient_id or AClient_id is null)
              order by mp.enddate desc 
             ) s
       where rownum <= 1;       

     EXCEPTION
     WHEN NO_DATA_FOUND THEN NULL;
    end;
  end if;
  
  return(RTRIM(Recv));
end;
/
grant execute on SM.GETPOSITIONMOVEID to SM_ALLUSERS;
grant execute on SM.GETPOSITIONMOVEID to SM_ALL_SELECT;


prompt
prompt Creating function GETPURPOSE
prompt ============================
prompt
CREATE OR REPLACE FUNCTION SM.GetPurpose(ObjID IN NUMBER, CDATE IN DATE default SYSDATE) RETURN CHAR IS
 CURSOR curPur IS SELECT LeasePurpose.Name Purpose
 FROM
  sm.movesets ms,
  sm.moveperiods mp,
  sm.moveitems mi,
  sm.LeasePurpose
 WHERE
  ms.id=mp.moveset_id and
  mp.id=mi.moveperiod_id and
  mi.object_id=ObjID and
  mp.sincedate<=CDATE and
  nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=CDATE and
  mi.leasepurpose_id=LeasePurpose.ID
 ORDER BY ms.movetype_id DESC;

 CurrPurpose	curPur%ROWTYPE;


 Purpose sm.leasepurpose.name%type;
BEGIN

 OPEN curPur;
 FETCH curPur INTO CurrPurpose;

 While (not curPur%NOTFOUND) and (CurrPurpose.Purpose IS NULL) LOOP
  FETCH curPur INTO CurrPurpose;
 END LOOP;

 IF curPur%NOTFOUND THEN
  CLOSE curPur;
  Return NULL;
 ELSE
  CLOSE curPur;
  Return CurrPurpose.Purpose;
 END IF;

END;
/
grant execute on SM.GETPURPOSE to SM_ALLUSERS;
grant execute on SM.GETPURPOSE to SM_ALL_SELECT;


