prompt
prompt Creating view GMP_INFOVIEW
prompt ==========================
prompt
create or replace view sm.gmp_infoview as
select 
 ginfo.movesets_id, -- ИД ОД
 ginfo.obligationtype_id, -- ИД типа обязательства
 ginfo.charge_type, -- вид начисления (OBLIGATION, FINE, PERCENT)
 ginfo.charge_date, -- дата выгрузки сальдо по начислению
 ginfo.saldo, -- сальдо по начислению на дату выгрузки
 ginfo.rowcreatedate, --дата создания начисления
 ginfo.rowclosedate, --дата закрытия(полного погашения) начисления
 ginfo.rowdeletedate, -- дата удаления начисления
 gmp."GINFOID",gmp."CHANGESTATUS",gmp."TRANSFERDATE",gmp."UIN",gmp."BILLDATE",gmp."BILLFOR",gmp."KBK",gmp."OKATO",gmp."PAYERID",gmp."PAYERALTID",gmp."SUPPLIERNAME",gmp."SUPPLIERINN",gmp."SUPPLIERKPP",gmp."SUPPLIEROGRN",gmp."SUPPLIERACCOUNT",gmp."SUPPLIERACCOUNTKIND",gmp."SUPPLIERBANKBIK",gmp."PAYERSTATUS",gmp."PAYMENTTYPE",gmp."PAYMENTPURPOSE" --передаваемые реквизиты по начислению согласно "Форматы ГИС ГМП"
 --(Форматы взаимодействия ГИС ГМП с информационными системами участников)
from sm.gmp_chargeidinfo ginfo
inner join (
  select 
    gch.gmp_chargeidinfo_id gInfoID, 
    gch.changestatus, --Начисление.Статус
    gch.transferdate, --Дата передачи в ГИС ГМП
    b.supplierbillid UIN, -- Счет.Уникальный идентификатор начисления (УИН)
    b.billdate, --Счет.Дата выставления счета
    b.billfor, --Счет.Наименование(за что выставлено)
    gch.kbk, --Начисление.КБК
    gch.okato, --Начисление.ОКАТО (!!! копируется из sm.recepients.okato, начиная с v4.8.2 там может быть ОКТМО !!!)
    gch.unifiedpayeridentifier payerID, --Начисление.Единый идентификатор плательщика
    gch.altpayeridentifier payerAltID, --Начисление.Альтернативный идентификатор плательщика
    org.name supplierName, --Поставщик услуг.Наименование
    org.inn supplierINN, --Поставщик услуг.ИНН
    org.kpp supplierKPP, --Поставщик услуг.КПП
    org.ogrn supplierOGRN, --Поставщик услуг.ОГРН
    acc.account supplierAccount, --Поставщик услуг.Номер банковского счета 
    acc.kind supplierAccountKind, --Поставщик услуг.Тип банковского счета
    bnk.bik supplierBankBIK, --Поставщик услуг.БИК подразделения Банка 
    bdg.status payerStatus, --Статус плательщика
    bdg.paymenttype, --Тип платежа
    bdg.purpose paymentPurpose --Основание платежа  
  from sm.gmp_charge gch 
  inner join sm.gmp_bill b on gch.id=b.id
  inner join sm.gmp_organization org on b.supplierorginfo_id=org.id
  inner join sm.gmp_account acc on acc.id=org.gmp_account_id
  inner join sm.gmp_bank bnk on bnk.id=acc.gmp_bank_id
  inner join sm.gmp_budgetindex bdg on bdg.id=gch.gmp_budgetindex_id
  where gch.rowcreatedate=(
    select max(ggch.rowcreatedate) 
    from sm.gmp_charge ggch 
    where ggch.gmp_chargeidinfo_id=gch.gmp_chargeidinfo_id
    )
) gmp on gmp.gInfoID=ginfo.id
order by 
 ginfo.charge_date desc, 
 ginfo.movesets_id, 
 ginfo.obligationtype_id, 
 ginfo.charge_type;
grant select on SM.GMP_INFOVIEW to SM_ALL_SELECT;
grant select, insert, update, delete on SM.GMP_INFOVIEW to SM_GMP_COMMUNICATION;


