prompt
prompt Creating function GETPAYDATEFORPAYMENT
prompt ======================================
prompt
create or replace function sm.GetPayDateForPayment(PaymentID NUMBER) return date is
  Recv date;
  method_id number;
  
begin
 
 select pm.paymethod_id, pm.apply_date
 into method_id, Recv
 from sm.payments pm
 where pm.id=PaymentID;
 
  if (sm.getparametersimple('PAYMENT_USE_APPLY_DATE')='N' and method_id!=3) then
    Select d.docdate
    into Recv
    from sm.payments p,
         sm.documents d
    where p.id=PaymentID and
          d.id=p.documents_id;
  end if;
 
 return(Recv);

EXCEPTION
 WHEN OTHERS
     THEN RETURN null;

end; -- GetPayDateForPayment;
/
grant execute on SM.GETPAYDATEFORPAYMENT to SM_ALLUSERS;
grant execute on SM.GETPAYDATEFORPAYMENT to SM_ALL_SELECT;


prompt
prompt Creating function CALCFINE
prompt ==========================
prompt
CREATE OR REPLACE FUNCTION SM.CalcFine (ADate IN DATE, AMoveSet_id IN NUMBER, AOblType_id IN NUMBER, WhatsNeed IN STRING, WhatsCalc IN STRING default 'ALL') RETURN number IS
  charged number(27,2):=0.0;
  payed number(27,2):=0.0;
  RetVal number(27,2);

  CurFineChargeRow sm.CHARGES%ROWTYPE;
  CurFineCharge number;
  DaysTotal integer;
  DaysCharged integer;
  CalcDate date;
  CountTmp integer;
  --переменные для расчета пени исходя из 360дней (ст.365 ГК)
  old360 char(1); --
  calendar_type number;

BEGIN
--
-- XSGROUP ver. 13.05.2010
--
-- функция возвращает сумму платежей, начислений или сальдо финансового обязательства,
-- заданного параметрами: AMoveSet_id   - ID операции движения
--                        AObligType_id - ID типа обязательства
-- на 24.00 даты:         ADate
-- при значениях параметра WhatsNeed:
--                       'PAY'    - рассчитывается сумма платежей. начислений или сальдо по обязательству
--                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене
-- при значениях параметра WhatsCalc:
--                       'PAY'    - рассчитывается сумма платежей
--                       'CHARGE' - расчитывается сумма начислений
--                       'ALL'    - рассчитывается сальдо
--

 CalcDate:=trunc(ADate+1);

  --  Определяем платеж по рассрочке или нет
--- VVV -- 18.10.2012 -- Всегда использовать распределение (т.к. клиенты стали использовать распределение платежа)
--  Select Count(*) into CountTmp from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = AMoveSet_ID and ppd.OBLIGATIONTYPE_ID = AOblType_id and ROWNUM = 1;
   CountTmp := 1;

 -- проверяем, актуальность ОД, производился ли перерасчет обязательства по новым алгоритмам

 If sm.getmovesetenddate(AMoveSet_id)<=sysdate-30 then
    select count(*)
    into CountTmp
    from sm.payments_distribution pd,
         sm.payments p
    where pd.payments_id=p.id and
          p.movesets_id=AMoveSet_id;
 end if;

  --  Старый блок расчетов - без учета РАСПРЕДЕЛЕНИЯ платежей
 if CountTmp = 0 then

 IF RTRIM(WhatsNeed)='FINE' THEN -- начало старого блока расчётов по пене

   select nvl(sum(c.paysize),0)
   into Charged
   from (
         select
           cc.paysize     -- дополнительные начисления по пене
         from
          sm.charges cc
         where
          cc.movesets_id=AMoveSet_ID and
          cc.obligationtype_id =AOblType_id and
          cc.chargedate<CalcDate and
          cc.charge_type='FINE' and
          cc.document_id is not null

         union all

         select
           cc.paysize
         from
           sm.charges cc  -- автоматические начисления по пене, не переходящие через заданную дату
         where
           cc.movesets_id=AMoveSet_ID and
           cc.obligationtype_id =AOblType_id and
           cc.calperiod_start<CalcDate and
           cc.calperiod_end<CalcDate and
           cc.charge_type='FINE' and
           cc.document_id is null
          ) c;

    begin
      select *
      into CurFineChargeRow -- автоматические начисления, переходящие через заданную дату
      from
        sm.charges cc
      where
        cc.movesets_id=AMoveSet_ID and
        cc.obligationtype_id =AOblType_id and
        cc.calperiod_start<CalcDate and
        cc.calperiod_end>=CalcDate and
        cc.charge_type='FINE' and
        cc.document_id is null;

        DaysTotal:=CurFineChargeRow.CalPeriod_End-CurFineChargeRow.CalPeriod_Start+1;
        DaysCharged:=CalcDate-CurFineChargeRow.CalPeriod_Start;

        CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

        Charged := Charged + CurFineCharge;
      exception
      when NO_DATA_FOUND then null;
    end;

    select nvl(sum(p.sum),0)
    into Payed
    from (
         select  -- платежи по пене, кроме списания долга
           pp.sum
         from
           sm.payments pp
         where
           pp.Movesets_Id=AMoveSet_ID and
           pp.obligationtype_id =AOblType_id and
           pp.mainpay='N' and
           pp.paymethod_id<>3 and
           sm.Getpaydateforpayment(pp.id)<CalcDate

         union all

         select   -- платежи по пене - списание долга
           pp.sum
         from
           Payments pp
         where
           pp.Movesets_id=AMoveSet_id and
           pp.obligationtype_id =AOblType_id and
           pp.paymethod_id=3 and
           pp.MAINPAY='N' and
           pp.APPLY_DATE<CalcDate

        ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец старого блока расчётов по пене

  IF RTRIM(WhatsNeed)='PAY' THEN -- начало старого блока расчётов по обязательству

    select nvl(sum(PaySize),0)
    into Charged
    from
      sm.charges
    where
      Movesets_id=AMoveSet_id  and
      obligationtype_id =AOblType_id and
      CHARGE_TYPE != 'FINE' and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.sum),0)
    into Payed
    from (
          select  -- платежи по обязательству. кроме списания долга
            pp.sum
          from
            sm.payments pp
          where
            pp.Movesets_Id=AMoveSet_ID and
            pp.obligationtype_id =AOblType_id and
            pp.mainpay='Y' and
            pp.paymethod_id<>3 and
            sm.Getpaydateforpayment(pp.id)<CalcDate

          union all

          select   -- платежи по обязательству - списание долга
            pp.sum
          from
            Payments pp
          where
            pp.Movesets_id=AMoveSet_id and
            pp.obligationtype_id =AOblType_id and
            pp.paymethod_id=3 and
            pp.MAINPAY='Y' and
            pp.APPLY_DATE<CalcDate

           ) p;


    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец старого блока расчётов по обязательству

else -- Новый блок расчетов - по РАСПРЕДЕЛЕННЫМ платежам

 IF RTRIM(WhatsNeed)='FINE' THEN -- начало нового блока расчётов по пене

   select nvl(sum(c.paysize),0)
   into Charged
   from (
         select
           cc.paysize     -- дополнительные начисления по пене
         from
          sm.charges cc
         where
          cc.movesets_id=AMoveSet_ID and
          cc.obligationtype_id =AOblType_id and
          cc.chargedate<CalcDate and
          cc.charge_type='FINE' and
          cc.document_id is not null

         union all

         select
           cc.paysize
         from
           sm.charges cc  -- автоматические начисления по пене, не переходящие через заданную дату
         where
           cc.movesets_id=AMoveSet_ID and
           cc.obligationtype_id =AOblType_id and
           cc.calperiod_start<CalcDate and
           cc.calperiod_end<CalcDate and
           cc.charge_type='FINE' and
           cc.document_id is null
          ) c;

    begin
      select *
      into CurFineChargeRow -- автоматические начисления, переходящие через заданную дату
      from
        sm.charges cc
      where
        cc.movesets_id=AMoveSet_ID and
        cc.obligationtype_id =AOblType_id and
        cc.calperiod_start<CalcDate and
        cc.calperiod_end>=CalcDate and
        cc.charge_type='FINE' and
        cc.document_id is null;

      --проверим тип календаря
      select pd.calendar_type_id, op.old360
            into
                calendar_type, old360
            from
                sm.moveperiods mp,
                sm.paydocs pd,
                sm.oblig_periodical_presets opp,
                sm.obligations obl,
                sm.oblig_presets op
            where
                mp.moveset_id=AMoveSet_ID and
                pd.moveperiod_id=mp.id and
                pd.obligationtype_id=AOblType_id and
                mp.Sincedate in (select max(mpr.sincedate)
                                    from sm.moveperiods mpr
                                    where mpr.Sincedate<=ADate and
                                          mpr.moveset_id=AMoveSet_ID and
                                       exists (select * from sm.paydocs pds
                                               where pds.moveperiod_id=mpr.id and
                                                     pds.obligationtype_id=AOblType_id)) and
                opp.id=pd.oblig_periodical_presets_id and
                op.id=obl.oblig_presets_id and
                obl.obligationtype_id=AOblType_id and
                obl.moveset_id=AMoveSet_ID;

        if old360='Y' then
          DaysTotal:=CurFineChargeRow.CalPeriod_End-CurFineChargeRow.CalPeriod_Start+1;
          DaysCharged:=CalcDate-CurFineChargeRow.CalPeriod_Start;

          CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

          Charged := Charged + CurFineCharge;
        end if;

        if old360='N' then
          if calendar_type=365 then
            DaysTotal:=CurFineChargeRow.CalPeriod_End-CurFineChargeRow.CalPeriod_Start+1;
            DaysCharged:=CalcDate-CurFineChargeRow.CalPeriod_Start;

            CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

            Charged := Charged + CurFineCharge;
          end if;

          if calendar_type=360 then
            --интересные вещи творятся при переходе месяца с 31 на 1..сделаем для этого отдельный вариант =)
            If EXTRACT(DAY from ADate)=31 then
              DaysTotal:=1 + (EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_End) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));
              DaysCharged:=1 + (EXTRACT(YEAR FROM ADate-1) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM ADate-1)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM ADate-1)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));

              CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

              Charged := Charged + CurFineCharge;

            elsif (EXTRACT(DAY from ADate)=28 or EXTRACT(DAY from ADate)=29) and EXTRACT(MONTH from ADate)=2 and EXTRACT(DAY from Calcdate)=1 then
              DaysTotal:=1 + (EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_End) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));
              --получается так как мы считаем сальдо на 1 марта, то в феврале 30 дней, хотя сюда передается 28/29 в зависимости от года..
              if EXTRACT(DAY from ADate)=28 then
                DaysCharged:=3 + (EXTRACT(YEAR FROM ADate) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM ADate)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM ADate)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));
              else
                DaysCharged:=2 + (EXTRACT(YEAR FROM ADate) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM ADate)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM ADate)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));
              end if;

              CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

              Charged := Charged + CurFineCharge;

            else

              DaysTotal:=1 + (EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_End) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_End)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));
              DaysCharged:=1 + (EXTRACT(YEAR FROM ADate) - EXTRACT(YEAR FROM CurFineChargeRow.CalPeriod_Start))*360 + (EXTRACT(MONTH FROM ADate)-EXTRACT(MONTH FROM CurFineChargeRow.CalPeriod_Start))*30 + (EXTRACT(DAY FROM ADate)-EXTRACT(DAY FROM CurFineChargeRow.CalPeriod_Start));

              CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

              Charged := Charged + CurFineCharge;
            end if;
          end if;
        end if;

      exception
      when OTHERS then null;
    end;

    select nvl(sum(p.val),0)
    into Payed
    from (
         select  -- платежи по пене, кроме списания долга
           pd.val
         from
           sm.payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_Id=AMoveSet_ID and
           pp.obligationtype_id =AOblType_id and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.paymethod_id<>3 and
           sm.Getpaydateforpayment(pp.id)<CalcDate

         union all

         select   -- платежи по пене - списание долга
           pd.val
         from
           sm.Payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_id=AMoveSet_id and
           pp.obligationtype_id =AOblType_id and
           pp.paymethod_id=3 and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.APPLY_DATE<CalcDate

        ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец нового блока расчётов по пене

  IF RTRIM(WhatsNeed)='PAY' THEN -- начало нового блока расчётов по обязательству

    select nvl(sum(PaySize),0)
    into Charged
    from
      sm.charges
    where
      Movesets_id=AMoveSet_id  and
      obligationtype_id =AOblType_id and
      CHARGE_TYPE != 'FINE' and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.val),0)
    into Payed
    from (
          select  -- платежи по обязательству. кроме списания долга
            pd.val
          from
            sm.payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_Id=AMoveSet_ID and
            pp.obligationtype_id =AOblType_id and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type != 'FINE' and
            pp.paymethod_id<>3 and
            sm.Getpaydateforpayment(pp.id)<CalcDate

          union all

          select   -- платежи по обязательству - списание долга
            pd.val
          from
            sm.Payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_id=AMoveSet_id and
            pp.obligationtype_id =AOblType_id and
            pp.paymethod_id=3 and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type != 'FINE' and
            pp.APPLY_DATE<CalcDate

           ) p;


    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец нового блока расчётов по обязательству

end if;

END;   -- CalcFine
/
grant execute on SM.CALCFINE to SM_ALLUSERS;
grant execute on SM.CALCFINE to SM_ALL_SELECT;


prompt
prompt Creating view LIABILITIES
prompt =========================
prompt
CREATE OR REPLACE VIEW SM.LIABILITIES AS
SELECT
  mt.Name as MoveType,
  cl.ID as Client_ID,
  ms.id as Moveset_Id,
  cl.Name as Client_Name,
  ot.ID as ObligType_ID,
  ot.Name as ObligType_Name,
  CalcFine(TRUNC(SYSDATE),ms.id, ot.id ,'PAY') PaySize,
  CalcFine(TRUNC(SYSDATE),ms.id, ot.id ,'FINE') FineSize
FROM
 Clients cl,
 Movesets ms,
 MoveType mt,
 Obligationtype ot,
 Moveperiods mp,
 paydocs pd
WHERE
 ms.movetype_id=mt.id and
 ms.client_id=cl.id and
 mp.moveset_id=ms.id and
 pd.moveperiod_id=mp.id and
 pd.obligationtype_id=ot.id;
grant select on SM.LIABILITIES to SM_ALLUSERS;
grant select on SM.LIABILITIES to SM_ALL_SELECT;


prompt
prompt Creating view MY_STREETS
prompt ========================
prompt
create or replace view sm.my_streets as
select s.id, s.name ||' ('||nvl(t.name,'...')||')' as NAME
    from 
      sm.streets s,
      sm.townnames t
    where 
      t.id(+)=s.townnames_id;
grant select on SM.MY_STREETS to SM_ALLUSERS;
grant select on SM.MY_STREETS to SM_ALL_SELECT;


prompt
prompt Creating view OBJECTSIZNOS
prompt ==========================
prompt
create or replace view sm.objectsiznos as
select
 Buildings.Objects_ID ,
 States.Wear
FROM  
 Buildings,
 States
WHERE 
 Buildings.Objects_ID=States.Objects_ID(+) and States.CalcDate=(select max(CalcDate) from States where Objects_ID=Buildings.Objects_ID);
grant select on SM.OBJECTSIZNOS to SM_ALLUSERS;
grant select on SM.OBJECTSIZNOS to SM_ALL_SELECT;


prompt
prompt Creating view OUTSTANDINGDOCS
prompt =============================
prompt
CREATE OR REPLACE VIEW SM.OUTSTANDINGDOCS AS
SELECT Movements.ID, MoveType.Name "Movement", Documents.ConditionDate, Clients.ID "Client_ID", Clients.Name "ClientName", Documents.ID "DocID", Documents.DocNo, Documents.DocDate, Documents.Explanation, DocTypes.Name "DocType"
FROM 
 Documents,
 Movements,
 MoveType,
 Clients,
 DocTypes
WHERE 
 Documents.NeedConditionDoc='Y' and
 Documents.ConditionDate<SYSDATE and
 Documents.DocTypes_ID=DocTypes.ID and
 Movements.Documents_ID=Documents.ID and
 Movements.MoveType_ID=MoveType.ID and
 Movements.ClientsTo_ID=Clients.ID;
grant select on SM.OUTSTANDINGDOCS to SM_ALLUSERS;
grant select on SM.OUTSTANDINGDOCS to SM_ALL_SELECT;


