from SMFolder_s;
grant select on SM.SMFOLDER_V to SM_ALL_SELECT;


prompt
prompt Creating view SMHOST_ONLY_FOLDER_V
prompt ==================================
prompt
create or replace view sm.smhost_only_folder_v as
select
  NamedObject_ID_sequenceID_ id,
  Folder_folderName_ name,
  Folder_description_ description
from SMFolder_s
where Folder_userData1_ = 51;
grant select on SM.SMHOST_ONLY_FOLDER_V to SM_ALL_SELECT;


prompt
prompt Creating view SMHOST_V
prompt ======================
prompt
create or replace view sm.smhost_v as
