prompt Creating view SM_V_CHANGES
prompt ==========================
prompt
create or replace view sm.sm_v_changes as
select
   fm_tables.table_name,
   atc.column_name,
   substr(cc.comments,1,decode(instr(cc.comments,'{')-1,-1,length(cc.comments),instr(cc.comments,'{')-1)) as col_comments,
   c.id_value,
   c.action,
   c.old_value_num,
   c.old_value_str,
   c.old_value_date,
   c.change_date,
   c.change_doc,
   sm.Expanddoc(c.change_doc) as ExpandDoc,
   ru.username,
   ru.fullname,
   c.activation_date
  from
   sm_changes c,
   fm_tables,
   sys.all_tab_columns atc,
   registeredusers ru,
   all_col_comments cc
  where
   c.fm_tables_id=fm_tables.id and
   fm_tables.table_name=atc.table_name and
   c.column_id=atc.column_id and
   atc.owner='SM' and
   c.user_id=ru.id and
   cc.owner='SM' and
   cc.table_name=fm_tables.table_name and
   cc.column_name=atc.column_name;
grant select on SM.SM_V_CHANGES to SM_ALLUSERS;
grant select on SM.SM_V_CHANGES to SM_ALL_SELECT;


