   -- Y = true
   -- N = false
   FUNCTION is_role_enabled (role_name IN VARCHAR2)
      RETURN VARCHAR2;
   -- PRAGMA RESTRICT_REFERENCES (is_role_enabled,  trust);
END pk_utils;
/
grant execute on SM.PK_UTILS to SM_ALLUSERS;
grant execute on SM.PK_UTILS to SM_ALL_SELECT;


