prompt Creating function EXPANDADDR_STREETHOUS
prompt =======================================
prompt
CREATE OR REPLACE FUNCTION SM.EXPANDADDR_STREETHOUS(AddrID IN NUMBER) RETURN CHAR IS
Street sm.streets.name%type;
House sm.address.house%type;
House_char sm.address.house_char%type;
Tank sm.address.tank%type;
Addon sm.address.addon%type;
HCC integer;
Result varchar2(400);
TYPESTREET sm.streets.typestreet%type;
begin
 /* 05/08/2014 Твердохлеб: создал процедуру из текста присланного из БФТ - письмо от 01.04.2014 */
 
 Result :='';
 SELECT A.House, A.House_char, A.Tank, A.Addon, ST.Name, ST.TYPESTREET
     INTO  House, House_char, Tank, Addon, Street, TYPESTREET
     FROM sm.Address A, sm.Streets ST
     WHERE
       A.ID = AddrID and
       A.Streets_ID=ST.ID(+) ;
     
       IF STREET IS NOT NULL THEN
        Result:=SUBSTR(RTRIM(Result) || ' ' || TYPESTREET || '.'|| RTRIM(STREET) || ', ',1,1000);
       END IF;       

       IF House IS NOT NULL THEN
        Result:=SUBSTR(Result || 'д.' || TO_CHAR(House) ||', ',1,400);

        IF HOUSE_CHAR IS NOT NULL THEN
          Result:=SUBSTR(Result,1,length(Result)-2);
          HCC:=ASCII(Substr(House_char,1,1));

          IF (HCC>47 and HCC<58) THEN
            Result:=SUBSTR(Result ||'-/'|| RTRIM(House_char) ||', ',1,400);
          ELSE
            Result:=SUBSTR(Result || '-' || RTRIM(House_char) ||', ',1,400);
          END IF;
        END IF;

        IF NOT (TANK IS NULL) THEN
          Result:=SUBSTR(Result || 'корп.' || RTRIM(Tank) ||', ',1,400);
        END IF;

       END IF;
       Result:=SUBSTR(Result,1,length(Result)-2);
   return Result;
end;
/
grant execute on SM.EXPANDADDR_STREETHOUS to SM_ALLUSERS;
grant execute on SM.EXPANDADDR_STREETHOUS to SM_ALL_SELECT;


prompt
prompt Creating function EXPANDADDR
prompt ============================
prompt
CREATE OR REPLACE FUNCTION SM.EXPANDADDR(AddrID IN NUMBER, ShowTownArea IN NUMBER default 1) RETURN CHAR IS
Region sm.regions.name%type;
PArea sm.provincearea.name%type;
TownName sm.townnames.name%type;
TArea sm.townarea.name%type;
Quarter sm.address.quarter%type;
Room sm.address.room%type;
Appartment sm.address.appartment%type;
Addon sm.address.addon%type;
Blitera sm.address.btiliter%type;
RES varchar2(1000);
--
base_id number;
base_addr_id number;
OB_ID number;
OB_TYPE number;
--
BEGIN
 /* 25/05/2012 Твердохлеб: увеличил поле Литер БТИ до 50 символов*/
 /* 22/07/2012 Твердохлеб: увеличил поле Литер БТИ до 80 символов*/
 /* 05/08/2014 Твердохлеб: заменил текст процедуры на присланный из БФТ - письмо от 01.04.2014
    и скрестил старую процедуру с новой
 */
 /* 15/08/2014 Твердохлеб: для объектов из структуры убрал поиск адреса в главном объекте*/
 /* 18/08/2014 Твердохлеб: для всех объектов убрал вывод доп. адресов*/
 
 SELECT A.Quarter,A.Appartment,A.Room,A.Addon, PA.Name, TA.Name,TN.Name, R.Name, A.Btiliter
 INTO  Quarter,Appartment,Room,Addon, PArea, TArea,TownName, Region, Blitera
 FROM sm.Address A, sm.ProvinceArea PA, sm.TownArea TA, sm.Townnames TN, sm.Regions R
 WHERE
   A.ID in (select nvl(main_id,id) from sm.address where id = AddrID) and
   A.ProvinceArea_ID=PA.ID(+) and
   A.TOWNNAMES_ID=TN.ID(+) and
   A.TownArea_ID=TA.ID(+) and
   a.Regions_ID=r.Id(+);

  RES := '';
  RES := RES || SM.EXPANDADDR_STREETHOUS(AddrID);

  begin
  -- находим ID объекта и его тип
      SELECT ob.id, ob.objtypes_id INTO OB_ID, OB_TYPE FROM sm.objects ob WHERE ob.address_id = AddrID;
     /* IF OB_TYPE = 3 THEN
      -- здания
        SELECT o.id, addr.id
        INTO base_id, base_addr_id
        FROM sm.objects o, address addr
        WHERE o.id =
            (SELECT objects_id FROM sm.Buildings b
            WHERE b.basebuilding is null
            START WITH b.objects_id= OB_ID
            CONNECT BY PRIOR basebuilding=id)
            AND o.address_id = addr.id;
      END IF;*/

      IF OB_TYPE <> 3 THEN
      -- остальные объекты
        base_addr_id := AddrID;
      END IF;
  EXCEPTION
  -- клиенты
    WHEN NO_DATA_FOUND THEN
         base_addr_id := AddrID;
  END;

  -- формируем список дополнительных адресов по улице, дому, корпусу, если таковые имеются
  /*FOR xx IN (SELECT * FROM sm.address addr WHERE addr.main_id = base_addr_id)
  LOOP
     -- добавляем к результирующему адресу еще один дополнительный
     RES := RES || ' / ' || SM.EXPANDADDR_STREETHOUS(xx.id);
  END LOOP;*/

 RES := SUBSTR(RES || ', ',1,254);
 -- добавление оставшейся квартиру, помещение
 IF NOT (APPARTMENT IS NULL) THEN
  RES:=SUBSTR(RES || ' кв.' || TO_CHAR(APPARTMENT) ||', ',1,1000);
 END IF;

 IF NOT (ROOM IS NULL) THEN
  RES:=SUBSTR(RES || ' помещ.' || TO_CHAR(ROOM) ||', ',1,1000);
 END IF;
 
IF NOT (BLITERA IS NULL) THEN
  RES:=SUBSTR(RES || ' лит.' || TO_CHAR(BLITERA) || ', ',1,1000);
 END IF; 

 IF ShowTownArea=1 THEN

  IF NOT (TAREA IS NULL) THEN
   RES:=SUBSTR( RTRIM(TAREA) || ' округ, ' || RES  ,1,1000);
  END IF;

  IF NOT (TownName IS NULL) THEN
   RES:=SUBSTR( RTRIM(TownName) || ', ' || RES  ,1,1000);
  END IF;

  IF NOT (PAREA IS NULL) THEN
   RES:=SUBSTR(RTRIM(PAREA) || ', ' || RES ,1,1000);
  END IF;

  IF NOT (QUARTER IS NULL) THEN
   RES:=SUBSTR(RES || 'квартал '|| RTRIM(Quarter) || ', ' ,1,1000);
  END IF;
  
  if not (Region is null) then
   Res:=SUBSTR( RTRIM(Region) || ', ' || RES  ,1,1000);
  end if;
 END IF;



  IF NOT (Addon IS NULL) THEN
   Res:=SUBSTR(Res || RTRIM(Addon) || ', ',1,1000);
  END IF;

 RES:=RTRIM(RES);
 RES:=SUBSTR(RES,1,length(Res)-1);

 RETURN RES;
END;
/
grant execute on SM.EXPANDADDR to SM_ALLUSERS;
grant execute on SM.EXPANDADDR to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEBALANCEFINE
prompt ====================================
prompt
create or replace function sm.GetMoveBalanceFine(AMoveSet_ID NUMBER, ADate IN DATE default SYSDATE, AOblType_id IN NUMBER default NULL) return number
is
  charged number(27,2):=0.0;
  payed number(27,2):=0.0;
  CalcDate date;
  distr integer :=0;

BEGIN
/*23/07/2015 Твердохлеб: добавил входной параметр Тип обязательства*/

 CalcDate:=trunc(ADate+1);

  --  Определяем платеж по рассрочке или нет
--- VVV -- 18.10.2012 -- Всегда использовать распределение (т.к. клиенты стали использовать распределение платежа)
-- Select Count(*) into distr from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = AMoveSet_ID and ROWNUM = 1;
distr := 1;

select  nvl(sum(paysize), 0)  into  Charged
from  sm.charges cc
where  cc.movesets_id=AMoveSet_ID and
cc.charge_type='FINE' and
cc.chargedate<CalcDate and
(cc.obligationtype_id = AOblType_id or AOblType_id is null);

 if distr = 0 then
               select
                 --+ index(pp IDX_PMNT_MOVESET_ID)
                 nvl(sum(pp.sum),0)  into Payed
               from    sm.payments pp
               where pp.Movesets_Id=AMoveSet_ID
                   and  pp.mainpay='N'
                  and  sm.Getpaydateforpayment(pp.id)<CalcDate
                  and (pp.obligationtype_id = AOblType_id or AOblType_id is null);  -- <<<!!! TO OPTIMIZE
                   --and pp.APPLY_DATE<CalcDate; -- НЕ ГОДИТСЯ (пользователи делают  ошибки-расхождения дат, а результат вылазит совсем в другом месте...)
  else
              select nvl(sum(pd.VAL),0)  into Payed
               from
                 sm.payments pp,
                 sm.payments_distribution pd,
                 sm.payments_plan ppl,
                 sm.charges ch
               where
                 pp.Movesets_Id=AMoveSet_ID and
                 pd.payments_id = pp.id and
                 ppl.id = pd.payments_plan_id and
                 ch.id = ppl.charges_id and
                 ch.charge_type = 'FINE' and
                  sm.Getpaydateforpayment(pp.id)<CalcDate and
                  (pp.obligationtype_id = AOblType_id or AOblType_id is null);
 end if;
RETURN Payed - Charged;
END; -- GetMoveBalanceFine
/
grant execute on SM.GETMOVEBALANCEFINE to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCEFINE to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEBALANCEOBLIG
prompt =====================================
prompt
create or replace function sm.GetMoveBalanceOblig(AMoveSet_ID NUMBER, ADate IN DATE default SYSDATE, AOblType_id IN NUMBER default NULL) return number
is
  charged number(27,2):=0.0;
  payed number(27,2):=0.0;
  CalcDate date;
  distr integer :=0;

BEGIN
/*23/07/2015 Твердохлеб: добавил входной параметр Тип обязательства*/

CalcDate:=trunc(ADate+1);

  --  Определяем платеж по рассрочке или нет
--- VVV -- 18.10.2012 -- Всегда использовать распределение (т.к. клиенты стали использовать распределение платежа)
-- Select Count(*) into distr from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = AMoveSet_ID and ROWNUM = 1;
distr := 1;

select nvl(sum(PaySize),0)  into Charged
from  sm.charges c
where
  Movesets_id=AMoveSet_id  and
  CHARGE_TYPE != 'FINE' and
  CHARGEDATE<CalcDate and
  (c.obligationtype_id = AOblType_id or AOblType_id is null);

 if distr = 0 then
              select
              --+ index(pp IDX_PMNT_MOVESET_ID)
              nvl(sum(pp.sum),0)  into Payed
              from  sm.payments pp
              where  pp.Movesets_Id=AMoveSet_ID
                    and pp.mainpay='Y'
                    and sm.Getpaydateforpayment(pp.id) < CalcDate  -- <<<!!! TO OPTIMIZE
                    and (pp.obligationtype_id = AOblType_id or AOblType_id is null);
                   -- and pp.APPLY_DATE<CalcDate; -- НЕ ГОДИТСЯ (пользователи делают  ошибки-расхождения дат, а результат вылазит совсем в другом месте...)
 else
              select nvl(sum(pd.VAL),0)  into Payed
              from sm.payments pp,
										sm.payments_distribution pd,
										sm.payments_plan ppl,
										sm.charges ch
             where pp.Movesets_Id=AMoveSet_ID and
										pd.payments_id = pp.id and
										ppl.id = pd.payments_plan_id and
										ch.id = ppl.charges_id and
										ch.charge_type != 'FINE' and
										sm.Getpaydateforpayment(pp.id)<CalcDate and
                (pp.obligationtype_id = AOblType_id or AOblType_id is null);
 end if;
 RETURN Payed - Charged;
END; -- GetMoveBalanceOblig
/
grant execute on SM.GETMOVEBALANCEOBLIG to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCEOBLIG to SM_ALL_SELECT;


prompt
prompt Creating function REP_ARENDA_DATA
prompt =================================
prompt
create or replace function sm.REP_ARENDA_DATA(Flag varchar2, Adate date)
return REP_ARENDA_LIST pipelined as
  id NUMBER;
  reestr VARCHAR2(30);
  name_arenda VARCHAR2(512);
  name_co VARCHAR2(512);
  address VARCHAR2(512);
  name_leasepurpose VARCHAR2(512);
  name_doc VARCHAR2(512);
  name_doc_date VARCHAR2(30);
  name_doc_status VARCHAR2(512);
  id_county number;
  county VARCHAR2(256);
  square VARCHAR2(30);
  build_type VARCHAR2(100);
  paysize_property VARCHAR2(30);
  paysize_ground VARCHAR2(30);
  obligation_property VARCHAR2(30);
  obligation_ground VARCHAR2(30);
  fine_property VARCHAR2(30);
  comment_work VARCHAR2(512);
  name_date_recalc VARCHAR2(30);
  name_dopsog VARCHAR2(512);
  cost_property VARCHAR2(30);
  cost_ground VARCHAR2(30);
  cost_all VARCHAR2(30);
  ADateReq date;
  Adocset_id NUMBER(27);
  start_date DATE;
  end_date DATE;
  address_id number(27);
  OBJTYPES_ID number(27);
begin
  /* 30/10/2015 Твердохлеб: Данные для отчета Перечень договоров аренды по состоянию*/
  /* 13/11/2015 Твердохлеб: [50] -
  1.Прежде всего договора НЕ закрытые, последний период не закрыт
  2.И недвижимое и движимое должно попасть
  3.БЕЗ дубликатов - на арендуемом объекте не стоит галочка Дубликат*/

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  FOR
    qData IN (
              SELECT ms.ID as ID,
                     c.name as name_arenda,
                     MAX(o.ID) as reestr,
                     MAX(COALESCE(mp.DOCSET_ID, ms.DOCSET_ID)) AS Adocset_id,
                     MAX(mi.MOVEPERIOD_ID) MOVEPERIOD_ID,
                     SUM(mi.SQUARE) SQUARE,
                     MAX(mi.LEASEPURPOSE_ID) LEASEPURPOSE_ID
                FROM SM.MOVEITEMS mi
                JOIN SM.MOVEPERIODS mp ON mp.ID = mi.MOVEPERIOD_ID
                JOIN SM.MOVESETS ms ON ms.ID = mp.MOVESET_ID
                JOIN SM.CLIENTS c ON c.ID = ms.CLIENT_ID
                JOIN Objects o ON o.ID = mi.OBJECT_ID
               WHERE ms.MOVETYPE_ID IN (4)
                 AND mp.SINCEDATE <= ADateReq
                 AND (mp.ENDDATE >= ADateReq OR mp.ENDDATE IS NULL)
                 and (ms.find_dublicate = 'N' or ms.find_dublicate is null)
                 AND o.OBJTYPES_ID NOT IN(7)
               group by ms.ID, c.name
             )
  LOOP
    select o.OBJTYPES_ID,
           o.DESCRIPTION,
           o.address_id,
           SM.EXPANDADDR(o.ADDRESS_ID) AS address
      into OBJTYPES_ID,
           name_co,
           address_id,
           address
      from sm.objects o
     where o.id = qData.reestr;

    build_type := NULL;

    if (OBJTYPES_ID = 3) then
        begin
          SELECT bt.NAME,
                 SM.EXPANDADDR(b.ADDRESS_ID),
                 b.address_id
            INTO build_type,
                 address,
                 address_id
            FROM BUILDINGS b
            JOIN BUILDTYPES bt ON bt.ID = b.BUILDTYPES_ID
           WHERE b.OBJECTS_ID = qData.reestr;
           exception
           when NO_DATA_FOUND then
           null;
       end;
    end if;
    if (OBJTYPES_ID = 4) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.unconstr b
          where b.objects_id = qData.reestr;
          exception
           when NO_DATA_FOUND then
           null;
       end;
    end if;
    if (OBJTYPES_ID = 5) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.enginf b
          where b.objects_id = qData.reestr;
           exception
           when NO_DATA_FOUND then
           null;
       end;
     end if;
     if (OBJTYPES_ID = 7) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.grounds b
          where b.objects_id = qData.reestr;
          exception
           when NO_DATA_FOUND then
           null;
       end;
     end if;

    -- если есть назначение
    name_leasepurpose := NULL;
    if (qData.LEASEPURPOSE_ID is not null) then
      select l.name
        into name_leasepurpose
        from LEASEPURPOSE l
       where l.ID = qData.LEASEPURPOSE_ID;
    end if;

    id := qData.ID;
    reestr := qData.reestr;
    square := qData.square;
    name_arenda := qData.name_arenda;
    Adocset_id := qData.Adocset_id;
    county := '';
    name_doc := '';
    name_doc_date := '';
    id_county := NULL;
    name_doc_status := '';
    start_date := NULL;
    end_date := NULL;

    paysize_property := '';
    paysize_ground := '';
    obligation_property := '';
    obligation_ground := '';
    fine_property := '';
    comment_work := '';
    name_date_recalc := '';
    name_dopsog := '';
    cost_property := '0';
    cost_ground := '0';
    cost_all := '0';

    -- получим округ
    BEGIN
      SELECT t.id,
             t.NAME
        INTO id_county,
             county
        FROM SM.ADDRESS a
        JOIN SM.TOWNAREA t ON t.ID = a.TOWNAREA_ID
       WHERE a.ID = ADDRESS_ID;
      exception
         when no_data_found then null;
    END;

    IF (qData.Adocset_id IS NOT NULL) THEN
       -- получим данные по документу
      SELECT '№ ' || TRIM(d.DOCNO) || ' от ' || TO_CHAR(d.DOCDATE, 'DD.MM.YYYY'),
             d.STARTDATE,
             d.DATE_END
        INTO name_doc,
             start_date,
             end_date
        FROM DOCSET_MEMBERS dm
        JOIN DOCUMENTS d ON d.ID = dm.DOCUMENT_ID AND dm.DOCROLE_ID = 1
       WHERE dm.DOCSET_ID = qData.Adocset_id;

      IF (start_date is NOT NULL) THEN
        name_doc := name_doc || ', с ' || TO_CHAR(start_date, 'DD.MM.YYYY');
      END IF;
      IF (end_date is NOT NULL) THEN
        name_doc_date := TO_CHAR(end_date, 'DD.MM.YYYY');
      END IF;
    END IF;

    -- сформируем стоимости
    -- Арендная плата ежемесячная(имущество)
    BEGIN
      SELECT SUM(p.PAYSIZE)
        INTO paysize_property
        FROM SM.PAYDOCS p
       WHERE p.MOVEPERIOD_ID = qData.MOVEPERIOD_ID
         AND p.OBLIGATIONTYPE_ID = 81;
        exception
           when no_data_found then null;
    END;

    -- Арендная плата ежемесячная(имущество)
    BEGIN
      SELECT SUM(p.PAYSIZE)
        INTO paysize_ground
        FROM SM.PAYDOCS p
       WHERE p.MOVEPERIOD_ID = qData.MOVEPERIOD_ID
         AND p.OBLIGATIONTYPE_ID = 102;
        exception
           when no_data_found then null;
    END;

    -- Задолженность по аренде на (имущество)
    SELECT sm.GetMoveBalanceOblig(qData.ID,sysdate,81)
      INTO obligation_property
      FROM DUAL;

    -- Задолженность по аренде на (земля)
    SELECT sm.GetMoveBalanceOblig(qData.ID,sysdate,102)
      INTO obligation_ground
      FROM DUAL;

    -- Пеня (имущество)
    SELECT sm.GetMoveBalanceFine(qData.ID,sysdate,81)
      INTO fine_property
      FROM DUAL;

    -- стоимость за 1 кв.м. -имущество
    IF (square IS NOT NULL AND
        square <> 0 AND
        paysize_property IS NOT NULL AND
        paysize_property <> 0) THEN

        cost_property := ROUND(paysize_property/square,2);
    END IF;

    -- стоимость за 1 кв.м. -земля
    IF (square IS NOT NULL AND
        square <> 0 AND
        paysize_ground IS NOT NULL AND
        paysize_ground <> 0) THEN

        cost_ground := ROUND(paysize_ground/square,2);
    END IF;

    IF (cost_property IS NOT NULL) THEN
       cost_all := cost_property;
    END IF;

    IF (cost_ground IS NOT NULL) THEN
       cost_all := CAST(cost_all AS NUMBER) + CAST(cost_ground AS NUMBER);
    END IF;

    IF (obligation_property = '0') THEN
       obligation_property := '';
    END IF;

    IF (obligation_ground = '0') THEN
       obligation_ground := '';
    END IF;

    IF (fine_property = '0') THEN
       fine_property := '';
    END IF;

    IF (cost_all = '0') THEN
       cost_all := '';
    END IF;

    IF (cost_property = '0') THEN
       cost_property := '';
    END IF;

    IF (cost_ground = '0') THEN
       cost_ground := '';
    END IF;

    pipe row (REP_ARENDA(
                        id,
                        reestr,
                        name_arenda,
                        name_co,
                        address,
                        name_leasepurpose,
                        name_doc,
                        name_doc_date,
                        name_doc_status,
                        id_county,
                        county,
                        square,
                        build_type,
                        paysize_property,
                        paysize_ground,
                        obligation_property,
                        obligation_ground,
                        fine_property,
                        comment_work,
                        name_date_recalc,
                        name_dopsog,
                        cost_property,
                        cost_ground,
                        cost_all
      ));
  END LOOP;
  RETURN;
end REP_ARENDA_DATA;
/
grant execute on SM.REP_ARENDA_DATA to SM_ALLUSERS;
grant execute on SM.REP_ARENDA_DATA to SM_ALL_SELECT;


prompt
prompt Creating view V_REP_ARENDA_DATA
