prompt
create or replace view sm.v_rep_arenda_data as
select  cast(id as number)id
        , cast(reestr as number)reestr
        , name_co
        , name_arenda
        , address
        , name_leasepurpose
        , name_doc
        , name_doc_date
        , square
        , paysize_property
        , paysize_ground
        , obligation_property
        , obligation_ground
        , fine_property
        , cost_property
        , cost_ground
        , cost_all
    from TABLE (SM.REP_ARENDA_DATA(NULL,NULL));
