prompt
prompt Creating type REP_BEZVOZ_USE
prompt ============================
prompt
CREATE OR REPLACE TYPE SM."REP_BEZVOZ_USE"                                                                                                                                                                                                                               AS OBJECT (
  id NUMBER,
  reestr VARCHAR2(30),
  name_use VARCHAR2(512),
  name_co VARCHAR2(512),
  name_doc VARCHAR2(512),
  name_doc_date VARCHAR2(30),
  id_county number,
  county VARCHAR2(256),
  address VARCHAR2(512),
  square VARCHAR2(30),
  build_type VARCHAR2(100),
  act VARCHAR2(100),
  insurance VARCHAR2(100)
);
/

prompt
prompt Creating type REP_BEZVOZ_USE_LIST
prompt =================================
prompt
CREATE OR REPLACE TYPE SM."REP_BEZVOZ_USE_LIST"                                                                                                                                                                                                                               AS
TABLE OF SM.REP_BEZVOZ_USE;
/

prompt
prompt Creating function REP_BEZVOZ_USE_DATA
prompt =====================================
prompt
create or replace function sm.REP_BEZVOZ_USE_DATA(Flag varchar2, Adate date)
return REP_BEZVOZ_USE_LIST pipelined as
  id NUMBER;
  reestr VARCHAR2(30);
  name_use VARCHAR2(512);
  name_co VARCHAR2(512);
  name_doc VARCHAR2(512);
  name_doc_date VARCHAR2(30);
  id_county NUMBER;
  county VARCHAR2(256);
  address VARCHAR2(512);
  square VARCHAR2(30);
  build_type VARCHAR2(100);
  act VARCHAR2(100);
  insurance VARCHAR2(100);
  ADateReq date;
  Adocset_id NUMBER(27);
  start_date DATE;
  end_date DATE;
  address_id number(27);
begin
  /* 29/10/2015 Твердохлеб: Данные для отчета Перечень договоров безвозмездного пользования муниципальным имуществом по состоянию*/
  /* 13/11/2015 Твердохлеб: [50] - 
  1.Прежде всего договора НЕ закрытые, последний период не закрыт
  2.И недвижимое и движимое должно попасть
  3.БЕЗ дубликатов - на арендуемом объекте не стоит галочка Дубликат*/
  
  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  id := 1;
  FOR
    qData IN (
              SELECT o.ID,
                     o.DESCRIPTION,
                     o.address_id,
                     SM.EXPANDADDR(o.ADDRESS_ID) AS address,
                     mi.SQUARE,
                     c.NAME AS name_use,
                     COALESCE(mp.DOCSET_ID, ms.DOCSET_ID) AS Adocset_id,
                     o.OBJTYPES_ID
                FROM SM.MOVEITEMS mi
                JOIN SM.MOVEPERIODS mp ON mp.ID = mi.MOVEPERIOD_ID
                JOIN SM.MOVESETS ms ON ms.ID = mp.MOVESET_ID
                JOIN SM.CLIENTS c ON c.ID = ms.CLIENT_ID
                JOIN Objects o ON o.ID = mi.OBJECT_ID
               WHERE ms.MOVETYPE_ID IN (22)
                 AND mp.SINCEDATE <= ADateReq
                 AND (mp.ENDDATE >= ADateReq OR mp.ENDDATE IS NULL)
                 and (ms.find_dublicate = 'N' or ms.find_dublicate is null)
                 AND o.OBJTYPES_ID NOT IN(7)
             )
  LOOP
    address_id := qData.address_id;
    address := qData.address;
    build_type := NULL;  

    if (qData.OBJTYPES_ID = 3) then
        begin
          SELECT bt.NAME,
                 SM.EXPANDADDR(b.ADDRESS_ID),
                 b.address_id
            INTO build_type,
                 address,
                 address_id
            FROM BUILDINGS b
            JOIN BUILDTYPES bt ON bt.ID = b.BUILDTYPES_ID
           WHERE b.OBJECTS_ID = qData.ID;
           exception
           when NO_DATA_FOUND then
           null;
       end;
    end if;
    if (qData.OBJTYPES_ID = 4) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.unconstr b
          where b.objects_id = qData.ID;
          exception
           when NO_DATA_FOUND then
           null;
       end;
    end if;
    if (qData.OBJTYPES_ID = 5) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.enginf b
          where b.objects_id = qData.ID;
           exception
           when NO_DATA_FOUND then
           null;
       end;
     end if;
     if (qData.OBJTYPES_ID = 7) then
       begin
         select SM.EXPANDADDR(b.ADDRESS_ID),
                b.address_id
           into address,
                address_id
           from sm.grounds b
          where b.objects_id = qData.ID;
          exception
           when NO_DATA_FOUND then
           null;
       end;
     end if;  
     
    reestr := qData.ID;
    name_co := qData.DESCRIPTION;
    square := qData.square;
    name_use := qData.name_use;
    Adocset_id := qData.Adocset_id;
    county := '';
    name_doc := '';
    name_doc_date := '';
    id_county := NULL;
    act := '';
    insurance := '';
    start_date := NULL;
    end_date := NULL;

    -- получим округ
    BEGIN
      SELECT t.id,
             t.NAME
        INTO id_county,
             county
        FROM SM.ADDRESS a
        JOIN SM.TOWNAREA t ON t.ID = a.TOWNAREA_ID
       WHERE a.ID = ADDRESS_ID;
      exception
         when no_data_found then null;
    END;

    IF (qData.Adocset_id IS NOT NULL) THEN
       -- получим данные по документу
      SELECT '№ ' || TRIM(d.DOCNO) || ' от ' || TO_CHAR(d.DOCDATE, 'DD.MM.YYYY'),
             d.STARTDATE,
             d.DATE_END
        INTO name_doc,
             start_date,
             end_date
        FROM DOCSET_MEMBERS dm
        JOIN DOCUMENTS d ON d.ID = dm.DOCUMENT_ID AND dm.DOCROLE_ID = 1
       WHERE dm.DOCSET_ID = qData.Adocset_id;

      IF (start_date is NOT NULL) THEN
        name_doc := name_doc || ', с ' || TO_CHAR(start_date, 'DD.MM.YYYY');
      END IF;
      IF (end_date is NOT NULL) THEN
        name_doc_date := TO_CHAR(end_date, 'DD.MM.YYYY');
      END IF;
    END IF;

    pipe row (REP_BEZVOZ_USE(id,
                            reestr,
                            name_use,
                            name_co,
                            name_doc,
                            name_doc_date,
                            id_county,
                            county,
                            address,
                            square,
                            build_type,
                            act,
                            insurance));
    id := id + 1;
  END LOOP;
  RETURN;
end REP_BEZVOZ_USE_DATA;
/
grant execute on SM.REP_BEZVOZ_USE_DATA to SM_ALLUSERS;
grant execute on SM.REP_BEZVOZ_USE_DATA to SM_ALL_SELECT;


