prompt Creating function REP_FREE_PREMISESES_DATA
prompt ==========================================
prompt
create or replace function sm.REP_FREE_PREMISESES_DATA(Flag varchar2, Adate date)
return REP_FREE_PREMISESES_LIST pipelined as
  id NUMBER;
  id_county number;
  county VARCHAR2(256);
  reestr VARCHAR2(30);
  name_co VARCHAR2(512);
  address VARCHAR2(512);
  square VARCHAR2(30);
  build_type VARCHAR2(100);
  note VARCHAR2(100);
  ADateReq date;
begin
  /* 27/10/2015 Твердохлеб: Данные для отчета Перечень свободных  муниципальных помещений*/
  /* Свободные помещения. Условились считать свободными помещениями те объекты с категорией "здания и помещения", на которые оформлены только ОД Собственность МО и Казна. */
  /* 13/11/2015 Твердохлеб: [50] - Добавил наличие Бюджетного учета*/
  /* 13/11/2015 Твердохлеб: [50] - В форме Список свободных помещений придется добавить 
  условие - Тип строения не равен Квартира. Сейчас после добавки условия возможности наличия 
  Бюджетного учета в список насыпало тысячи квартир..*/
  
  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  id := 1;
  FOR
    qData IN (
              SELECT o.ID,
                     o.DESCRIPTION,
                     b.ADDRESS_ID,
                     SM.EXPANDADDR(b.ADDRESS_ID) AS address,
                     b.SQUARE,
                     bt.NAME AS build_type
                FROM Objects o
                JOIN BUILDINGS b ON b.OBJECTS_ID = o.ID
                JOIN BUILDTYPES bt ON bt.ID = b.BUILDTYPES_ID
               WHERE o.OBJTYPES_ID = 3
                 and bt.id <> 41
                 AND EXISTS(SELECT *
                              FROM SM.MOVEITEMS mi
                              JOIN SM.MOVEPERIODS mp ON mp.ID = mi.MOVEPERIOD_ID
                              JOIN SM.MOVESETS ms ON ms.ID = mp.MOVESET_ID
                             WHERE mi.OBJECT_ID = o.ID
                               AND ms.MOVETYPE_ID IN (1)
                               AND mp.SINCEDATE <= ADateReq
                               AND (mp.ENDDATE >= ADateReq OR mp.ENDDATE IS NULL)
                           )
                AND EXISTS(SELECT *
                              FROM SM.MOVEITEMS mi
                              JOIN SM.MOVEPERIODS mp ON mp.ID = mi.MOVEPERIOD_ID
                              JOIN SM.MOVESETS ms ON ms.ID = mp.MOVESET_ID
                             WHERE mi.OBJECT_ID = o.ID
                               AND ms.MOVETYPE_ID IN (10)
                               AND mp.SINCEDATE <= ADateReq
                               AND (mp.ENDDATE >= ADateReq OR mp.ENDDATE IS NULL)
                           )                   
                AND NOT EXISTS(SELECT *
                                 FROM SM.MOVEITEMS mi
                                 JOIN SM.MOVEPERIODS mp ON mp.ID = mi.MOVEPERIOD_ID
                                 JOIN SM.MOVESETS ms ON ms.ID = mp.MOVESET_ID
                                WHERE mi.OBJECT_ID = o.ID
                                  AND ms.MOVETYPE_ID NOT IN (1, 10, 29)
                                  AND mp.SINCEDATE <= ADateReq
                                  AND (mp.ENDDATE >= ADateReq OR mp.ENDDATE IS NULL)
                              )
             )
  LOOP
    reestr := qData.ID;
    name_co := qData.DESCRIPTION;
    address := qData.address;
    square := qData.square;
    build_type := qData.build_type;
    note := 'удовлетворительное';
    county := '';
    id_county := NULL;

    -- получим округ
    BEGIN
      SELECT t.id,
             t.NAME
        INTO id_county,
             county
        FROM SM.ADDRESS a
        JOIN SM.TOWNAREA t ON t.ID = a.TOWNAREA_ID
       WHERE a.ID = qData.ADDRESS_ID;
      exception
         when no_data_found then null;
    END;

    -- получим состояние
    BEGIN
      SELECT st.NAME
        INTO note
        FROM SM.STATES s
        JOIN SM.STATETYPES st ON st.ID = s.STATETYPES_ID
       WHERE s.CALCDATE <= ADateReq
         AND ROWNUM <= 1
    ORDER BY s.CALCDATE DESC;
      exception
         when no_data_found then null;
    END;

    pipe row (REP_FREE_PREMISESES(id, reestr, name_co, id_county, county, address, square, build_type, note));
    id := id + 1;
  END LOOP;
  RETURN;
end REP_FREE_PREMISESES_DATA;
/
grant execute on SM.REP_FREE_PREMISESES_DATA to SM_ALLUSERS;
grant execute on SM.REP_FREE_PREMISESES_DATA to SM_ALL_SELECT;


