prompt Creating package CALCFINE_PKG
prompt =============================
prompt
create or replace package sm.CalcFine_pkg is

  -- Author  : XSGROUP
  -- Created : 22.05.2010
  -- Purpose : процедуры и функции вычисления размера пени на определённую дату
  --           для кумулятивных начислений по пене, сделанных за период, внутри которого находится ADate
  --
  --           BEFORE : вычисляет часть начисленной пени до 24.00 часов даты ADate
  --           AFTER  : вычисляет часть начисленной пени с 00.00 часов даты, следующей за ADate


  function GetFinePart(                            -- возвращает рассчитанную часть пени
                       AMoveSetID number,          -- ID операции движения
                       AObligationTypeID number,   -- ID типа обязательства
                       ADate date,                 -- расчётная дата
                       What varchar2               -- что расчитывать
                       ) return number;
  PRAGMA RESTRICT_REFERENCES(GetFinePart, WNDS, WNPS);

  function GetFinePartComment(                     -- возвращает комментарий к рассчитанной части
                       AMoveSetID number,          -- ID операции движения
                       AObligationTypeID number,   -- ID типа обязательства
                       ADate date,                 -- расчётная дата
                       What varchar2               -- что расчитывать
                       ) return varchar2;
  PRAGMA RESTRICT_REFERENCES(GetFinePartComment, WNDS, WNPS);

  function GetFinePartBetween(                     -- возвращает рассчитанную часть пени одного и того же кумулятивного начисления между датами ADateStart и ADateEnd
                       AMoveSetID number,          -- ID операции движения
                       AObligationTypeID number,   -- ID типа обязательства
                       ADateStart date,            -- дата начала периода
                       ADateEnd  date              -- дата окончания периода
                       ) return number;
  PRAGMA RESTRICT_REFERENCES(GetFinePartBetween, WNDS, WNPS);

  function GetFinePartBetweenComment(              -- возвращает комментарий к рассчитанной части пени между датами ADateStart и ADateEnd
                       AMoveSetID number,          -- ID операции движения
                       AObligationTypeID number,   -- ID типа обязательства
                       ADateStart date,            -- дата начала периода
                       ADateEnd  date              -- дата окончания периода
                       ) return varchar2;
  PRAGMA RESTRICT_REFERENCES(GetFinePartBetween, WNDS, WNPS);


end;
/
grant execute on SM.CALCFINE_PKG to SM_ALLUSERS;
grant execute on SM.CALCFINE_PKG to SM_ALL_SELECT;


