prompt Creating package CHARGING_PKG
prompt =============================
prompt
create or replace package sm.CHARGING_PKG is

  -- Author  : XSGROUP
  -- Created : 21.10.2011 
  -- Purpose : Обеспечивает работу финансовых механизмов
  
  
  --Функция возвращает дату, соответствующую началу календарного периода определяемого параметром PeriodType для 
  --даты AnyDateOfPeriod входящий в этот период
  function GetPeriodFirstDay(
   PeriodType IN CHAR,      --Тип периода
   AnyDateOfPeriod IN DATE  --Анализируемая дата входящая в период
   ) return DATE;
  PRAGMA RESTRICT_REFERENCES(GetPeriodFirstDay, WNDS, WNPS); 
  
  --Функция возвращает дату, соответствующую окончанию календарного периода определяемого параметром PeriodType для 
  --даты AnyDateOfPeriod входящий в этот период
  function GetPeriodLastDay(
   PeriodType IN CHAR,      --Тип периода
   AnyDateOfPeriod IN DATE  --Анализируемая дата входящая в период
   ) return DATE;
  PRAGMA RESTRICT_REFERENCES(GetPeriodLastDay, WNDS, WNPS); 
  
  -- Функция возвращает количество периодов попадающих в заданный интервал (дробное значение)
  function GetPeriodsCount(
                           PeriodType in CHAR, -- тип периодичности 
                           SinceDate in date,  -- начало интервала
                           EndDate in date     -- конец интервала
                           ) return number;
  
  --Функция возвращает границы календарного периода определяемого параметром PeriodType для 
  --даты AnyDateOfPeriod входящий в этот период
  procedure GetPeriodBounds(
   PeriodType IN CHAR,      --Тип периода
   AnyDateOfPeriod IN DATE, --Анализируемая дата входящая в период
   FirstDay OUT DATE,       --Первый день периода
   LastDay OUT DATE);       --Последний день периода
  PRAGMA RESTRICT_REFERENCES(GetPeriodBounds, WNDS, WNPS);
  
  --функция возвращает дату переданную в качестве параметра увеличенной на размер одного периода
  function IncDate(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE            --Анализируемая дата входящая в период
   ) return DATE;
  PRAGMA RESTRICT_REFERENCES(IncDate, WNDS, WNPS); 

  --функция возвращает дату начала следующего периода
  function GetNextPeriod(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE            --Анализируемая дата входящая в период
   ) return DATE;
  PRAGMA RESTRICT_REFERENCES(GetNextPeriod, WNDS, WNPS);
     
  --Функция возвращает название календарного периода
  function GetPeriodName(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE            --Анализируемая дата входящая в период
   ) return varchar2;
  PRAGMA RESTRICT_REFERENCES(GetPeriodName, WNDS, WNPS);
  
  --Функция возвращает 'y' если дата принадлежит последнему периоду в году , 'N' - если нет
  function IsLastPeriodInYear(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE            --Анализируемая дата входящая в период
   ) return varchar2; 
  PRAGMA RESTRICT_REFERENCES(IsLastPeriodInYear, WNDS, WNPS);
  
  --Функция возвращает сумму оплаты для периода, соответствующего заданной дате расчёта, 
  --    исходя из годовой оплаты если дата принадлежит последнему периоду в году , 'N' - если нет
  function GetPeriodPaysize(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE,           --Анализируемая дата входящая в период
   YearlyPaySize number     --Размер оплаты за год
   ) return number; 
  PRAGMA RESTRICT_REFERENCES(GetPeriodPaysize, WNDS, WNPS);
  
  --Функция возвращает сумму оплаты для периода времени SinceDate - EndDate, исходя из годовой оплаты
  function GetPaysizeByDatePeriod(
                                  PeriodType IN VARCHAR2,  --Тип периода
