                                  EndDate in DATE,         --дата окончания периода времени 
                                  YearlyPaySize number     --Размер оплаты за год
                                 ) return number; 
  PRAGMA RESTRICT_REFERENCES(GetPaysizeByDatePeriod, WNDS, WNPS);
    
end CHARGING_PKG;
