prompt Creating package FULLRECALC_PKG
prompt ===============================
prompt
create or replace package sm.FULLRECALC_PKG is
-- Version of all financial logic:   11.12.2014 - 10:35

--
-- процедура расчета для традиционного свода расчетов
PROCEDURE FullRecalcCharges(AMoveSet_ID in number, AObligType_ID in number);
--

--
-- процедура расчета пени для традиционного свода расчетов
procedure FullRecalcFines(AMoveSet_ID in number, AObligType_ID in number, DelCharges IN CHAR default 'Y');
--

--
-- процедура расчета для для обязательства с рассрочкой платежа
PROCEDURE FullRecalcChargesCredit(AMoveSet_ID in number, AObligType_ID in number);
--

--
-- функция для определения ставки рефинансирования, действующая на дату CurDate
FUNCTION RefineRateOnDate(CurDate IN date) return number;
PRAGMA RESTRICT_REFERENCES(RefineRateOnDate, WNDS, WNPS);
--

--
-- функция определения размера процентов, которые должны быть начислены на дату A_PayDate
--     возвращает, кроме этого
--          prev_date_calc - дату предыдущего начисления процентов (реальную)
--          Comment_txt - комментарий к расчеты пени
FUNCTION PersentSizeForPayment(AMoveSet_ID number,AObligType_ID number,A_PayDate date,prev_date_calc in out date, Comment_txt out varchar2) return number;

--
-- функция определения размера пени, которая должна быть начислена на дату A_PayDate
--     возвращает, кроме этого
--          prev_date_calc - дату предыдущего начисления пени (реальную)
--          Comment_txt - комментарий к расчеты пени
-- Если (FINE_KIND='R' and charge_fine_assanction='N') - пеня от ставки рефинансирования на день оплаты,
--   то функция вернет размер части, на которую нужно умножить размер оплаты
--   комментарий также будет урезанный. Для формирования полного комментария нужно
--         Comment_txt:= Comment_txt || to_char(размер_оплаты) || '=' || to_char(размер_пени) || 'руб.'
FUNCTION FineSizeForCredit(AMoveSet_ID number, AObligType_ID number, A_Date date, obl_plan number, prev_date_calc out date, Comment_txt out varchar2, fact_charges char default 'Y', conditions_date date, PDIDpar number) return number;

--
-- функция возвращает ID условий по обязательству, действующих на дату A_PayDate
FUNCTION PAYDOC_ID_ON_DATE(AMoveSet_ID number,AObligType_ID number,A_PayDate date) return number;
PRAGMA RESTRICT_REFERENCES(PAYDOC_ID_ON_DATE, WNDS, WNPS);

FUNCTION PAYDOC_ID_FOR_FINE_ON_DATE(AMoveSet_ID number, AObligType_ID number, A_PayDate date) return number;
PRAGMA RESTRICT_REFERENCES(PAYDOC_ID_FOR_FINE_ON_DATE, WNDS, WNPS);


end;
/
grant execute on SM.FULLRECALC_PKG to SM_ALLUSERS;
grant execute on SM.FULLRECALC_PKG to SM_ALL_SELECT;


