prompt Creating package M
prompt ==================
prompt
CREATE OR REPLACE PACKAGE SM.M IS

  --Функция возвращает размер площади, на которую распространяется действие операций движения вида M_ID
  --на момент времени CDATE в здании или части здания B_ID
  --по отношению к субъекту C_ID (необязательный параметр)
  --если C_ID не указан, расчет будет произведен для всех ОД вида движения M_ID
  --Примечание: функция расчитывает площадь на основании оперций движения, оформленных на ветку B_ID и ниже
  --т.е. если операция была оформлена на вышестоящую ветку, она в результате не будет учтена
  FUNCTION used_square(cdate in date,   -- дата на которую произвести расчет
                       M_ID  IN NUMBER, -- вид движения
                       B_ID  IN NUMBER, -- BUILDINGS.ID здания или любой его части
                       c_id  IN NUMBER := null -- суьъект, на которого оформлены ОД
                       ) RETURN number;
  PRAGMA RESTRICT_REFERENCES(used_square, WNDS);


  --То же самое, что used_square, но с учетом ОД которые оформлены на вышестоящие ветки дерева
  FUNCTION used_square_from_top(cdate in date, -- дата на которую произвести расчет
                                M_ID  IN NUMBER, -- вид движения
                                B_ID  IN NUMBER, -- BUILDINGS.ID здания или любой его части
                                c_id  IN NUMBER := null -- суьъект, на которого оформлены ОД
                                ) RETURN number;
  PRAGMA RESTRICT_REFERENCES(used_square_from_top, WNDS);

  --То же самое, что used_square, но будут выбраны только ОД, у которых основание ОД равно tb_id
  --Целиком для зданий можно применять функцию с параметром tb_id равным -1.
  --Если tb_id установить равным -1, то в результат будут включены все площади оформленные
  --с основанием у которых TRANSFERBASIS.EXCLUDING='N' за вычетом тех,
  --у которых основанием с TRANSFERBASIS.EXCLUDING='Y',
  --т.е. будет сделан расчет с учетом движений включающих и исключающих площади из движения
  FUNCTION used_square_basis(cdate in date, -- дата на которую произвести расчет
                             M_ID  IN NUMBER, -- вид движения
                             B_ID  IN NUMBER, -- BUILDINGS.ID здания или любой его части
                             tb_id IN NUMBER -- основание движение TRANSFERBASES.ID
                             ) RETURN number;
  PRAGMA RESTRICT_REFERENCES(used_square_basis, WNDS);


  -- функция возвращвет значение приведенной площади объекта ОД (площадь на долю)
  FUNCTION get_share_square( MI_ID  IN NUMBER -- MoveItem.id
                             ) RETURN number;
  PRAGMA RESTRICT_REFERENCES(get_share_square, WNDS);

  --Функция проверяет возможность оформления движения объекта
  --Результат содержит:
  --  Y - оформление возможно
  --  N - оформление невозможно по причине, возвращаемой в параметре DESCR
  --  I - оформление возможно, но это может привести к нежелательным последствиям,
  --      комментарий к которым возвращается в параметре DESCR
  --Примечание: если объектом выступает часть помещения, которая еще не выделена в виде отдельного
  --объекта, то O_ID присваивается ID вышестоящего объекта, а в SQ заносится площадь,
  --которая будет выделена в виде части помещения
  FUNCTION m_validate(P_DATE        IN DATE, --дата начала будущего движения объекта
                      E_DATE        IN DATE, --дата окончания будущего движения объекта
                      M_ID          IN NUMBER, --вид движения будущего движения объекта
                      O_ID          IN NUMBER, --объект будущего движения
                      SQ            IN NUMBER, --площадь, которая будет участвовать в будущем движении
                      Share_Percent IN NUMBER, --доля права будущего движения
                      DESCR         OUT VARCHAR2, --расширенный текстовый результат-описание противоречия
                      v_id          number := null -- ???
                      ) RETURN CHARACTER;
  PRAGMA RESTRICT_REFERENCES(m_validate, WNDS);

  --Функция проверяет корректность ранее созданного движения объекта
  --Результат содержит:
  --  Y - оформление возможно
  --  N - оформление невозможно по причине, возвращаемой в параметре DESCR
  FUNCTION m_validate_stored(m_ID IN NUMBER, -- MOVEITEMS.ID проверяемого движения объекта
                             DESCR OUT VARCHAR2 --расширенный текстовый результат-описание противоречия
                             ) RETURN CHARACTER;
  PRAGMA RESTRICT_REFERENCES(m_validate_stored, WNDS);

  --служебная функция, не используйте в своих программах
  PROCEDURE l2(P_DATE IN OUT DATE,
               E_DATE IN OUT DATE,
               M_ID   IN NUMBER,
               O_ID   IN NUMBER);

  --служебная функция, не используйте в своих программах
  PROCEDURE m2t(P_DATE IN DATE,
                E_DATE IN DATE,
                M_ID   IN NUMBER,
                O_ID   IN NUMBER);

  --служебная функция, не используйте в своих программах
  procedure test;
END;
/
grant execute on SM.M to SM_ALLUSERS;
grant execute on SM.M to SM_ALL_SELECT;


