prompt
create or replace package sm.SDO_UTIL authid current_user as

  type ids is table of number index by binary_integer;
  TYPE columns_array IS TABLE OF VARCHAR2(32) INDEX BY BINARY_INTEGER;

  --SIMPLIFY_SCALE_FACTOR - число, множитель масштаба, используется при расчете генерализации
  --значение (0.265/1000)*4 соответствует четырем точкам экрана при разрешении 96 dpi
  SIMPLIFY_SCALE_FACTOR NUMBER := (0.265/1000)*4;


