   RETURN MDSYS.SDO_GEOMETRY
   DETERMINISTIC;

  procedure UpdateBoundsMetadata (in_table_name in VARCHAR default 'SD_OBJECT_GEOMETRIES',
                                  in_owner in VARCHAR default 'SM',
                                  TOLERANCE IN NUMBER default 0.05);
  procedure UpdateBoundsMetadataRowChanged(in_rowid in number,
                                           in_pk_name in VARCHAR default 'ID',
                                           in_table_name in VARCHAR default 'SD_OBJECT_GEOMETRIES',
                                           in_owner in VARCHAR default 'SM',
                                           TOLERANCE IN NUMBER default 0.05);
  procedure save_geometry (geometry in MDSYS.Sdo_Geometry, column_name in varchar2, id in number);
  procedure regenerate_geometry (main_geo_id in integer,
                                is_recalc_all_scales in CHAR,
                                column_names in columns_array default empty_columns_array);
  procedure regenerate_all_geometry;
  procedure disable_geometry_triggers;
  procedure enable_geometry_triggers;
  procedure on_add_collumn(column_name in varchar);
  procedure DropIndex(arg_table_name in varchar2, arg_column_name in varchar2, arg_owner in varchar2 default 'SM');
  procedure ReSnapRawTable(rawitem_id in number);
  procedure raise_not_object_exception;
  procedure log_message(msg in varchar2);
  function is_saumi_data_linked(in_dictionary_id in number, in_data_id in number) return number;
  function lazy_set_count_obj(din_count number) return number;
  function move(geom in mdsys.sdo_geometry, move_x in number, move_y in number) return mdsys.sdo_geometry;
  function scale(geom in mdsys.sdo_geometry, scale_x in number, scale_y in number) return mdsys.sdo_geometry;

end;
/
