prompt
create or replace package sm.SharesValue_PKG is
    -- XSGROUP ver. 4.7.5
    -- Purpose : набор функций для оформления участия в капитале хоз. обществ

    -- Функция возвращает сумму уже распределенных акций эмиссии OperSharesID на дату CalcDate
    Function GetSharesNumberSum(OperSharesID IN NUMBER, CalcDate IN DATE) RETURN NUMBER;

    -- Функция возвращает сумму акций эмиссии OperSharesID в собственности эмитента на дату CalcDate
    Function GetIssuerSharesNumberSum(OperSharesID IN NUMBER, CalcDate IN DATE) RETURN NUMBER;

    -- Функция возвращает сумму уже распределенных долей ЮЛ на дату CalcDate
    Function GetSharesAmountSum(OrgID IN NUMBER, CalcDate IN DATE) RETURN NUMBER;

    -- Функция рассчитывает и возвращает размер доли в рублях исходя из количества акций объекта ObjID (при акционерном уставном капитале)
    --Параметры:
    --  ObjID - ID объекта "Пакеты акций, доли в капитале";
    --  SharesNumber - количество акций;
    Function GetSharesValue(ObjID IN NUMBER, SharesNumber IN NUMBER) RETURN NUMBER;

    -- Функция рассчитывает и возвращает размер доли в рублях на дату CalcDate исходя из размера доли в процентах объекта ObjID (при долевом уставном капитале ЮЛ)
    --Параметры:
    --  ObjSharesID - ID объекта "Пакеты акций, доли в капитале";
    --  Amount - размер доли в процентах;
    --  CalcDate - дата;
    Function GetSharesNominalCost(ObjID IN NUMBER, Amount IN NUMBER, CalcDate IN DATE) RETURN NUMBER;

end;
/
