prompt Creating package UPDATE_DB_PKG
prompt ==============================
prompt
create or replace package sm.UPDATE_DB_PKG is

  -- Author  : XSGROUP
  -- Created : 07.02.2013
  -- Purpose : Вспомогательные процедуры для обновления БД

  type VarcharArray is table of varchar2(100) index by binary_integer;

  --функция возвращает мксимальное значение поля ID таблицы ATableName
  function GetMaxID(
   ATableName IN VARCHAR2 -- название таблицы
  ) return number;

  --процедура выполняет SQL команду
  procedure DoSQL(
   ASQLtext IN VARCHAR2 --текст SQL команды
  );

  --процедура переводит триггеры определённой таблицы из состояния ENABLED в состояние DISABLED
  procedure DisableTriggers(
   ATableName IN VARCHAR2  --название таблицы
   );

  --процедура перевода триггеров в состояние, в котором они находились перед выполнением DisableTriggers
  procedure EnableTriggers;

  --процедура переводит ограничения определённой таблицы из состояния ENABLED в состояние DISABLED
  procedure DisableConstraints(
   ATableName IN VARCHAR2  --название таблицы
  );

  --процедура перевода ограничений в состояние, в котором они находились перед выполнением DisableConstraints
  procedure EnableConstraints(
   ATableName IN VARCHAR2  --название таблицы
  );
  
  TriggerNames VarcharArray;    -- в этй таблице сохраняем имена триггеров, которые были ENABLED
  ConstraintNames VarcharArray; -- в этй таблице сохраняем имена ограничений, которые были ENABLED
  emptyTable VarcharArray;      -- для очистки TriggerNames, ConstraintNames
  
  --процедура устанавливает флажки "Поиск част.", "Поиск полн.", "Список"  для поля AColumn_name таблицы ATable_Name
  procedure PutFindChecks (
   ATable_Name varchar2,  --название таблицы
   AColumn_name varchar2, --название поля
   AHistory char,         --вести историю
   ASearch_part char,     --поиск част.
   ASearch_full char,     --поиск полн.
   AFromList char         --использовать список уже введённых значений  
  );
  
  --функция проверяет существование Oracle-объекта в БД, если существует - true, иначе - false
  function CheckExistance(
    AType varchar2,             --тип объекта (полностью) 
    AName varchar2,             --назание объекта
    DropIfExists boolean:=false --удалить ли, если существует, по умолчанию - не удалять
  ) return boolean;
  
end UPDATE_DB_PKG;
/
grant execute on SM.UPDATE_DB_PKG to SM_ALLUSERS;
grant execute on SM.UPDATE_DB_PKG to SM_ALL_SELECT;


