prompt Creating package XMLROSREESTR_PKG
prompt =================================
prompt
create or replace package sm.xmlRosreestr_pkg is
--Пакет для формирования XML-файлов для Росреестра
  -- Author  : XSGROUP
  -- Created : 01.12.2012
  --Ver      : 1

--функция проверяет наличие состояния объекта на указаннаю дату
--либо возвращает последнее известное при значении параметра UseEndStates=Y
--возможные возвраты
--0 состояние на указанную дату есть
function CheckStates(ObjectID number, VDate varchar2, UseEndStates number default 0) return number;

--функция возвращает дату последнего известного состояние
function GetMaxStates(ObjectID number) return varchar2;

--структура кадастрового номера
function GetKadastrStruct(ObjectID in number, key_pars char, usetabchar char default 'Y') return varchar2;

--процедура заполняет справочники
procedure InsertDictEl(v_TableName varchar2, v_DictName varchar2, v_code varchar2, v_root_code varchar2);

--функция формирует  имя файла для каждого типа
function GetNameFile(typefile number, v_reportDate string, ObjID number, v_lavel char) return varchar2;

--функция формирует номер дома
function ParsHouse(object_id number) return varchar2;


--функция определяет категорию ЗУ и возвращает условный код
--1:ЗСХ назнач. кроме СОД
--2: ЗСХН СОД
--3: Знаспунктов
--4: Земли промышленности
--5: Земли особоохран. тер-рий
--6: Земли лесного фонда
--7: Земли водного фонда
--8: объекты капстроит-ва.
function CheckObjType(ObjectID number) return number;



---функция возвращает тип АТО по коду субъекта
--1 Муниципальный р-н
--2 Субъект РФ
function GetSubType(v_code varchar2) return number;


--служебные
function GetTableID (v_tableName varchar2) return number;
function GetColumnID (n_tableID number, v_column_name varchar2) return number;
function GetChangeCode (v_Code varchar2) return number;
function GetColumnName (v_table_name varchar2, n_column_id number) return varchar2;


function CheckObjects(object_id number) return number;

--функция проверяет, является ли ID адреса - адресом правообладателя
function CheckAddressOwn(ID_Address number) return number;

--функция создает пустой xml пакет и возвращает его ID
function CreatEmptyXMLPackage(v_GUID varchar2, n_packeg_type number) return number;

function GetDescrChanges(ObjID number, beginDate date, endDate date) return varchar2;

--функция генерирует имя директории уникальное для имени файла
function GetDirectoryName(typefile number, v_reportDate string) return varchar2;

function GetGrountypesCode(ObjID number) return varchar2;

--функция возвращает последнее состояние 
function GetStateDate(ObjectID number, vReportDate varchar2) return varchar2;

function GetGroundRelease(ObjID number, key char) return varchar2;

--индикатор для отчетов
function IndOfUnload(n_ChangeID number) return number;

TYPE t_TablData IS TABLE OF NUMBER INDEX BY BINARY_INTEGER;
empty t_TablData;
ObjList t_TablData; --таблица для модифицируемых объектов
MovSet t_TablData; -- таблица для операций движения
Addres t_TablData; --для адресов

end xmlRosreestr_pkg;
/
grant execute on SM.XMLROSREESTR_PKG to SM_ALLUSERS;
grant execute on SM.XMLROSREESTR_PKG to SM_ALL_SELECT;


