prompt Creating function ADDMOVETYPE
prompt =============================
prompt
create or replace function sm.AddMoveType(
 FULLNAME IN VARCHAR2,
 SHORTNAME IN VARCHAR2,
 DOING IN VARCHAR2,
 COLOR IN NUMBER DEFAULT NULL) RETURN NUMBER
IS
 CurN integer; 
 MV_CNT integer;
begin

 select count(*) into MV_CNT from movetype; 
 select max(ID)+1 into CurN from movetype;
 
 insert into movetype(
   id, 
   name, 
   doing, 
   def_clientsto, 
   def_transferbasis, 
   def_doctype, 
   def_docsubscr, 
   use_subpurpose, 
   use_shares, 
   use_obligations, 
   use_autocalc, 
   square_policy, 
   short_name, 
   unbreaked, 
   registry, 
   exclusive_client, 
   hide_client, 
   need_state, 
   license, 
   map_color, 
   use_sharepercent, 
   show_transfbasis)
  values (
   CurN,
   FULLNAME, 
   doing, 
   null, 
   null, 
   null, 
   null, 
   'N', 
   'N', 
   'N', 
   'N', 
   'INTERSECT', 
   shortname, 
   'N', 
   'N', 
   'N', 
   'N', 
   'N', 
   rpad('#',MV_CNT,'#'), 
   color, 
   'N', 
   'N');
   
  update movetype set license=license||'#';

 return CurN; 
end;
/
grant execute on SM.ADDMOVETYPE to SM_ALL_SELECT;


