prompt Creating function GETMOVESETPERIODID
prompt ====================================
prompt
create or replace function sm.GetMoveSetPeriodId(AMoveSet_ID IN NUMBER, ADate Date) RETURN number
is
 res number(27);
begin

  -- Чувыкин 19.07.2024
  -- Возвращает moveperiods.id периода заданной операции движения, в который входит заданная дата. Если на заданную дату периодов у этой ОД не имелось, будет null

  begin
    select m.id
    into res
    from
      sm.Moveperiods m
    where
      m.Moveset_Id=AMoveSet_ID and
      m.sincedate <= ADate and
      (m.enddate >= ADate or
      m.enddate is null);
   exception
     when others then
       null;
   end;

  return res;

end;
/
grant execute on SM.GETMOVESETPERIODID to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEAMOUNTBYDATE
prompt =====================================
prompt
create or replace function sm.GetMoveAmountByDate(AMoveSet_ID NUMBER, AOblType_id NUMBER, ADate Date) return number
is
  Amount number(27,2):=0.00;

BEGIN
/*19.07.2024 Чувыкин - функция возвращает "Размер оплаты" из того периода заданной операции движения по заданному типу обязательства, в который входит заданная дата*/
begin
select pd.paysize
into Amount
    from  sm.paydocs pd
    where  pd.obligationtype_id = AOblType_id
      and pd.moveperiod_id = getmovesetperiodid(AMoveSet_ID, ADate);
    exception
     when others then
       null;
   end;

RETURN Amount;
END;
/
