prompt
prompt Creating function CALCCHARGES_DBP
prompt =================================
prompt
create or replace function sm.CALCCHARGES_DBP(MS_ID number, startdate date, enddate date, otype_id number) return number is
-- 08022022 - Чувыкин В.Э. - Функция возвращает сумму начислений нужного типа по конкретной операции движения за заданный будущий период

 Paysize number(27,2);
 res number(27,2);
 last_charge_date date;
 last_day_of_month number; 
 last_day_of_CHARGING number;
 pay_periodical char;
begin


select
max(ch.chargedate) into last_charge_date --вычисляется дата последнего начисления по обязательству, по этому начислению и будут считаться ДБП
from
Charges Ch
where
ch.charge_type = 'OBLIGATION'
and
ch.obligationtype_id = otype_id
and
ch.movesets_id = ms_id;

select
pd.periodical into pay_periodical --определяется периодичность начислений - Y-ежемесячные, Q-квартальные
from
Charges Ch
join paydocs pd
on ch.paydoc_id = pd.id
where
ch.charge_type = 'OBLIGATION'
and
ch.obligationtype_id = otype_id
and
ch.movesets_id = ms_id
and
ch.chargedate = last_charge_date
and 
rownum = 1;

select extract (day from to_date(enddate,'dd.mm.yyyy')) into last_day_of_CHARGING FROM DUAL;--определяется количество дней действия договора в его споледнем месяце
select extract (day from to_date(last_day(enddate),'dd.mm.yyyy')) into last_day_of_month FROM DUAL; --определяется количество дней последнего месяца договора

/*select
    ch.paysize into Paysize
    from
    Charges Ch
    where
    ch.charge_type = 'OBLIGATION'
    and
    ch.obligationtype_id = otype_id
    and
    ch.movesets_id = ms_id
    and
    ch.chargedate = last_charge_date
    and 
    rownum = 1
    ;*/
    
select sm.GetMoveAmountByDate(ms_id,81,startdate) into paysize from dual;
    

if pay_periodical = 'Y' then
    res := paysize * trunc(MONTHS_BETWEEN(trunc(enddate,'mm'),startdate)) + (paysize / last_day_of_month) * last_day_of_CHARGING;
    /*select
    ch.paysize * MONTHS_BETWEEN(enddate+1,startdate) into RES
    from
    Charges Ch
    where
    ch.charge_type = 'OBLIGATION'
    and
    ch.obligationtype_id = otype_id
    and
    ch.movesets_id = ms_id
    and
    ch.chargedate = last_charge_date
    and 
    rownum = 1
    ;*/
end if;

if pay_periodical = 'Q' then --пока отдел аренды не использует поквартальных начислений
    res := paysize * MONTHS_BETWEEN(enddate+1,startdate) / 3;
    /*select
    ch.paysize * MONTHS_BETWEEN(enddate+1,startdate) / 3 into RES
    from
    Charges Ch
    where
    ch.charge_type = 'OBLIGATION'
    and
    ch.obligationtype_id = otype_id
    and
    ch.movesets_id = ms_id
    and
    ch.chargedate = last_charge_date
    and 
    rownum = 1
    ;*/
end if;


return (RES);

end;
/
grant execute on SM.CALCCHARGES_DBP to SM_ALLUSERS;


prompt
prompt Creating function CALCFINEDAYS
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION SM.CalcFineDays (DATE_BEG IN DATE, DATE_END IN DATE) RETURN INTEGER IS
  RetValue integer;
  p1 integer;
  p2 integer;
  p3 integer;

BEGIN
--
-- XSGROUP ver. 4.8.0
-- Функция возвращает число дней между DATE_BEG и DATE_END.
-- Используется при расчете пени в том случае, когда в условиях обязательств для расчета принимается 360 дней в году.
--
   if trunc(DATE_END,'MONTH')=trunc(DATE_BEG,'MONTH') then
       -- если расчет пени идет в пределах месяца, то просто разницу дней, но максимум 30
       RetValue := LEAST(30, trunc(DATE_END)-trunc(DATE_BEG));
    else
       -- при переходе через границу месяца
       -- дней в первом месяце
       p1:=DATE_BEG-trunc(DATE_BEG,'MONTH')+1;
       if p1=1 then
             p1:=30;
       else
             p1:=Last_Day(DATE_BEG)-DATE_BEG+1;
       end if;
       -- дней в последнем месяце
       if DATE_END=Last_Day(DATE_END) then
              p2:=30;
       else
              p2:=DATE_END-trunc(DATE_END,'MONTH');
       end if;
       -- кол-во месяцев между первым и последним месяцами
       p3:= 30 * (MONTHS_BETWEEN(trunc(DATE_END,'MONTH'),trunc(DATE_BEG,'MONTH')) - 1);

       RetValue := p1+p2+p3;
   end if;

   RETURN RetValue;
END;
/
grant execute on SM.CALCFINEDAYS to SM_ALLUSERS;
grant execute on SM.CALCFINEDAYS to SM_ALL_SELECT;


prompt
prompt Creating function CALCFINEKBK
prompt =============================
prompt
CREATE OR REPLACE FUNCTION SM.CalcFineKBK (ADate IN DATE, AMoveSet_id IN NUMBER, AKBK_id IN NUMBER, WhatsNeed IN varchar2, WhatsCalc IN varchar2 default 'ALL') RETURN NUMBER IS
  charged number(27,4):=0.0;
  payed number(27,4):=0.0;
  RetVal number(27,4);

  CurFineChargeRow CHARGES%ROWTYPE;

  CurFineCharge number;
  DaysTotal integer;
  DaysCharged integer;

  CalcDate date;
BEGIN
--
-- XSGROUP 08.06.2009
--
-- функция возвращает сумму платежей, начислений или сальдо договора аренды,
-- заданного параметрами: AMoveSet_id   - ID операции движения
--                        AKBK_id - ID KBK
-- на 24.00 даты:         ADate
-- при значениях параметра WhatsNeed:
--                       'PAY'    - рассчитывается сумма платежей. начислений или сальдо по обязательству
--                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене
-- при значениях параметра WhatsCalc:
--                       'PAY'    - рассчитывается сумма платежей
--                       'CHARGE' - расчитывается сумма начислений
--                       'ALL'    - рассчитывается сальдо
--

 CalcDate:=trunc(ADate+1);


  /* IF RTRIM(WhatsNeed)='FINE' THEN -- начало блока расчётов по пене

   select nvl(sum(c.paysize),0)
   into Charged
   from (
         select
           cc.paysize     -- дополнительные начисления по пене
         from
          sm.charges cc
         where
          cc.movesets_id=AMoveSet_ID and
          nvl(cc.cls_kbk_id,0) =AKBK_id and
          cc.chargedate<CalcDate and
          cc.charge_type='FINE' and
          cc.document_id is not null

         union all

         select
           cc.paysize
         from
           sm.charges cc  -- автоматические начисления по пене, не переходящие через заданную дату
         where
           cc.movesets_id=AMoveSet_ID and
           nvl(cc.cls_kbk_id,0) =AKBK_id and
           cc.calperiod_start<CalcDate and
           cc.calperiod_end<CalcDate and
           cc.charge_type='FINE' and
           cc.document_id is null
          ) c;

    begin
      for yy in (
           select *
           from
               sm.charges cc
           where
              cc.movesets_id=AMoveSet_ID and
              nvl(cc.cls_kbk_id,0) =AKBK_id and
              cc.calperiod_start<CalcDate and
              cc.calperiod_end>=CalcDate and
              cc.charge_type='FINE' and
              cc.document_id is null )
      loop
        DaysTotal:=yy.CalPeriod_End-yy.CalPeriod_Start+1;
        DaysCharged:=CalcDate-yy.CalPeriod_Start;

        CurFineCharge := sm.calcfine_pkg.GetFinePart(AMoveSet_ID,yy.obligationtype_id,CalcDate-1,'BEFORE');
        --CurFineCharge := yy.PaySize * (DaysCharged/DaysTotal);

        Charged := Charged + CurFineCharge;
      end loop;

      exception
      when NO_DATA_FOUND then null;
    end;

    select nvl(sum(p.sum),0)
    into Payed
    from (
         select  -- платежи по пене, кроме списания долга
           pp.sum
         from
           sm.payments pp
         where
           pp.Movesets_Id=AMoveSet_ID and
           nvl(pp.cls_kbk_id,0) =AKBK_id and
           pp.mainpay='N' and
           pp.paymethod_id<>3 and
           sm.Getpaydateforpayment(pp.id)<CalcDate

         union all

         select   -- платежи по пене - списание долга
           pp.sum
         from
           Payments pp
         where
           pp.Movesets_id=AMoveSet_id and
           nvl(pp.cls_kbk_id,0) =AKBK_id and
           pp.paymethod_id=3 and
           pp.MAINPAY='N' and
           pp.APPLY_DATE<CalcDate

        ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец блока расчётов по пене

  IF RTRIM(WhatsNeed)='PAY' THEN -- начало блока расчётов по обязательству

    select nvl(sum(PaySize),0)
    into Charged
    from
      sm.charges
    where
      Movesets_id=AMoveSet_id  and
      nvl(cls_kbk_id,0) =AKBK_id and
      CHARGE_TYPE != 'FINE' and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.sum),0)
    into Payed
    from (
          select  -- платежи по обязательству. кроме списания долга
            pp.sum
          from
            sm.payments pp
          where
            pp.Movesets_Id=AMoveSet_ID and
            nvl(pp.cls_kbk_id,0) =AKBK_id and
            pp.mainpay='Y' and
            pp.paymethod_id<>3 and
            sm.Getpaydateforpayment(pp.id)<CalcDate

          union all

          select   -- платежи по обязательству - списание долга
            pp.sum
          from
            Payments pp
          where
            pp.Movesets_id=AMoveSet_id and
            nvl(pp.cls_kbk_id,0) =AKBK_id and
            pp.paymethod_id=3 and
            pp.MAINPAY='Y' and
            pp.APPLY_DATE<CalcDate

           ) p;


    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец блока расчётов по обязательству
    */
 IF RTRIM(WhatsNeed)='FINE' THEN -- начало блока расчётов по пене

   select nvl(sum(c.paysize),0)
   into Charged
   from (
         select
           cc.paysize     -- дополнительные начисления по пене
         from
          sm.charges cc
         where
          cc.movesets_id=AMoveSet_ID and
          nvl(cc.cls_kbk_id,0) =AKBK_id and
          cc.chargedate<CalcDate and
          cc.charge_type='FINE' and
          cc.document_id is not null

         union all

         select
           cc.paysize
         from
           sm.charges cc  -- автоматические начисления по пене, не переходящие через заданную дату
         where
           cc.movesets_id=AMoveSet_ID and
           nvl(cc.cls_kbk_id,0) =AKBK_id and
           cc.calperiod_start<CalcDate and
           cc.calperiod_end<CalcDate and
           cc.charge_type='FINE' and
           cc.document_id is null
          ) c;

    begin
      for yy in (
           select *
           from
               sm.charges cc
           where
              cc.movesets_id=AMoveSet_ID and
              nvl(cc.cls_kbk_id,0) =AKBK_id and
              cc.calperiod_start<CalcDate and
              cc.calperiod_end>=CalcDate and
              cc.charge_type='FINE' and
              cc.document_id is null )
      loop
        DaysTotal:=yy.CalPeriod_End-yy.CalPeriod_Start+1;
        DaysCharged:=CalcDate-yy.CalPeriod_Start;

        CurFineCharge := sm.calcfine_pkg.GetFinePart(AMoveSet_ID,yy.obligationtype_id,CalcDate-1,'BEFORE');
        --CurFineCharge := yy.PaySize * (DaysCharged/DaysTotal);

        Charged := Charged + CurFineCharge;
      end loop;

      exception
      when NO_DATA_FOUND then null;
    end;

    select nvl(sum(p.val),0)
    into Payed
    from (
         select  -- платежи по пене, кроме списания долга
           pd.val
         from
           sm.payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_Id=AMoveSet_ID and
           nvl(pp.cls_kbk_id,0) =AKBK_id and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.paymethod_id<>3 and
           sm.Getpaydateforpayment(pp.id)<CalcDate

         union all

         select   -- платежи по пене - списание долга
           pd.val
         from
           Payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_id=AMoveSet_id and
           nvl(pp.cls_kbk_id,0) =AKBK_id and
           pp.paymethod_id=3 and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.APPLY_DATE<CalcDate

        ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец блока расчётов по пене

  IF RTRIM(WhatsNeed)='PAY' THEN -- начало блока расчётов по обязательству

    select nvl(sum(PaySize),0)
    into Charged
    from
      sm.charges
    where
      Movesets_id=AMoveSet_id  and
      nvl(cls_kbk_id,0) =AKBK_id and
      CHARGE_TYPE != 'FINE' and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.val),0)
    into Payed
    from (
          select  -- платежи по обязательству. кроме списания долга
            pd.val
          from
            sm.payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
          where
            pp.Movesets_Id=AMoveSet_ID and
            nvl(pp.cls_kbk_id,0) =AKBK_id and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type != 'FINE' and
