prompt
prompt Creating function CALCFINEPLAN
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION SM.CalcFinePlan (ADate IN DATE, AMoveSet_id IN NUMBER, AOblType_id IN NUMBER) RETURN NUMBER IS
-------------------------------------------------------------------
-- XSGROUP ver. 4.8.0 update 4.9.0
-- Функция возвращает сумму пени
-- за период с даты последнего автоначисления пени по дату предполагаемого платежа (без автоначисленной суммы)
-- При этом имеется в виду, что от текущей даты до запрашиваемой условия начислений (сумма,размер пени,...) меняться не должны.
-- Нельзя использовать для обязательств с рассрочкой, поскольку функция не умеет вычислять пеню на проценты
--------------------------------------------------------------------
-- Параметры: AMoveSet_id   - ID операции движения
--                  AObligType_id  - ID типа обязательства
--                 ADate             - дата платежа
--------------------------------------------------------------------
  RetValue number(27,2);

  fineComments varchar2(1000);
  fineRate number(27,12):=0;
  strTmp varchar2(200);
  xTmp number(27,12):=0;
  yTmp number(27,12):=0;
  zTmp number(27,12):=0;

  lastFineChargeDate date;
  lastObligChargeDate date;
  lastObligChargeSize number(27,2):=0.0;

  currSaldo number(27,2):=0.0;
  lastpaysize number(27,2):=0;
  addFineVal number(27,2):=0.0;
  daysCount integer:=0;
  addDays integer:=0;
  daysInYear integer:=0;
  installmentPlanCount integer:=0;
  iBracketsBeg integer:=0;
  iBracketsEnd integer:=0;
  iPos integer:=0;
  iPos2 integer:=0;
  periodicalPresetsID number(27);
  presetsID number(27);
  fineKind char(1);
  fineOnDebt char(1);
  fineFixedDaily char(1);
  noFine char(1);
  stopFines char(1);
  fineOnLastDay char(1);
  lastDay date;
  calcDate date;
BEGIN
  RetValue := 0;
  calcDate := ADate;
  
  -- расчет на прошлое бесмысленен
  if  calcDate<=sysdate then
    RETURN RetValue;
  end if;  

  -- если обязательства с рассрочкой, то и не пытаемся доначислить пеню (...)
  Select count(p.id) into installmentPlanCount
         from sm.PAYMENTS_PLAN_DRAFT p, SM.OBLIGATIONS o
         where o.moveset_id=p.movesets_id and o.obligationtype_id=p.obligationtype_id and o.moveset_id=AMoveSet_id and o.obligationtype_id=AOblType_id;
  if installmentPlanCount > 0 then
    RETURN RetValue; --0
  end if;

begin
  --Дата и комментарий последнего автоначисления по пене
  Select fr.chargedate, fr.comments  into lastFineChargeDate, fineComments
  from (Select cc.chargedate, cc.comments
         from
           sm.charges cc
         where
           cc.movesets_id=AMoveSet_id
           and cc.obligationtype_id=AOblType_id
           and cc.charge_type='FINE'
           and cc.document_id is null
         order by cc.chargedate desc) fr
  where ROWNUM = 1;

  if lastFineChargeDate is null then
    RETURN RetValue; --0
  end if;

  --Дата и сумма последнего, до даты предполагаемого платежа, автоначисления по основному обязательству
  Select fr.chargedate, fr.paysize into lastObligChargeDate, lastObligChargeSize
  from (Select cc.chargedate, cc.paysize
         from
           sm.charges cc
         where
           cc.movesets_id=AMoveSet_id
           and cc.obligationtype_id=AOblType_id
           and cc.chargedate<=calcDate
           and cc.charge_type='OBLIGATION'
           and cc.document_id is null
         order by cc.chargedate desc) fr
  where ROWNUM = 1;

  if lastObligChargeDate is null then
    RETURN RetValue; --0
  end if;
  
  exception
    when NO_DATA_FOUND then RETURN RetValue;
  
end;  

  if calcDate <= lastFineChargeDate then
    RETURN RetValue; --0
  end if;

   -- Условия начисления пени
   select pd.calendar_type_id                  -- Принятое в условиях обязательств количество дней в году для расчета пени (365,360)
           , pd.oblig_periodical_presets_id     -- ID периодических параметров расчета
           , ob.oblig_presets_id                   -- ID параметров расчета
           , pd.fine_kind                            -- способ начисления пени: 'P',  'R', 'F'
           , pd.fineondebt                          -- база начисления пени: от долга ('Y') или от обязательства (т.е. от суммы последнего начисления по основному обязательству, без учета оплаты)
           , pd.finevaluefixed_daily              -- за каждый день просрочки ('Y') или за каждый факт
           , pd.no_fine                              -- пеня не начисляется ('Y')
   into daysInYear
        , periodicalPresetsID
        , presetsID
        , fineKind
        , fineOnDebt
        , fineFixedDaily
        , noFine
   from
           sm.Movesets ms,
           sm.PayDocs pd,
           sm.obligations ob,
           sm.obligationtype ot,
           sm.moveperiods mp
          where
            ms.id=ob.moveset_id and
            ot.id=ob.obligationtype_id and
            pd.obligationtype_id=ob.obligationtype_id and
            pd.moveperiod_id=mp.id and
            mp.moveset_id=ms.id and
            mp.SinceDate=(select max(m.SinceDate)
                          from
                            sm.moveperiods m,
                            sm.paydocs p,
                            sm.obligations o
                          where
                            p.moveperiod_id=m.id and
                            p.obligationtype_id=o.obligationtype_id and
                            o.id = ob.id and
                            o.moveset_id = m.moveset_id and
                            m.moveset_id = ms.id
                             and m.SinceDate <= calcDate
                          ) and
             ms.ID=AMoveSet_id and ot.id=AOblType_id and
             ROWNUM = 1;

  -- пеня не начисляется
  if noFine = 'Y' then
    RETURN RetValue; --0
  end if;

   --Коэффициент для расчета пени определяем по комментарию последнего автоначисления по пене:
   -- Ищем строку в первых круглых скобках
   iBracketsBeg := instr(fineComments, '(', 1, 1);
   iBracketsEnd := instr(fineComments, ')', 1, 1);
   strTmp := substr(fineComments, iBracketsBeg + 1, (iBracketsEnd - iBracketsBeg) - 1);
   if length(strTmp) > 1 then
     -- далее - в зависимости от способа начисления пени :
     -- если пеня зависит от ставки рефинансирования
     if fineKind = 'R' then
        -- определяем количество '/'
        iPos := instr(strTmp, '/', 1, 1);
        iPos2 := instr(strTmp, '/', 1, 2);
        if iPos2 = 0 then
            -- один '/'
            iPos := instr(strTmp, '/', 1, 1);
            if iPos > 0 then
               xTmp := to_number(substr(strTmp, 1, iPos-1), '999.999999999999');
               yTmp := to_number(substr(strTmp, iPos+1, length(strTmp)-iPos), '999.999999999999');
               if yTmp <> 0 then
                 fineRate := xTmp/yTmp;
               end if;
            end if;
        else
            -- два '/'
            iPos := instr(strTmp, '/', 1, 1);
            iPos2 := instr(strTmp, '/', 1, 2);
            if (iPos > 0 and iPos2 > 0) then
               xTmp := to_number(substr(strTmp, 1, iPos-1), '999.999999999999');
               yTmp := to_number(substr(strTmp, iPos+1, iPos2-1-iPos), '999.999999999999');
               zTmp := to_number(substr(strTmp, iPos2+1, length(strTmp)-iPos2), '999.999999999999');
               if (yTmp <> 0 and zTmp <> 0) then
                 fineRate := xTmp/yTmp/zTmp;
               end if;
            end if;
        end if;
     -- если пеня - фиксированный процент
     elsif fineKind = 'P' then
           fineRate := to_number(strTmp, '999.999999999999');
     -- если пеня - фиксированная сумма
     elsif fineKind = 'F' then
         fineRate := to_number(strTmp, '999999999999.99');
     end if;
   end if;

   if (nvl(fineRate,0) = 0) then
      return RetValue; --0
   end if;

   -- Начислять ли пеню на день оплаты
   Select (case when opp.charge_fine_method=1 then 1 else 0 end)
     into addDays
     from SM.Oblig_Periodical_Presets opp
     where opp.ID = nvl(periodicalPresetsID,0);

   -- Последний день договора
   select mp.enddate into lastDay
      from sm.moveperiods mp
      where
            mp.moveset_id = AMoveSet_id and
            mp.sincedate=(select max(m.sincedate) from sm.moveperiods m where m.moveset_id = mp.moveset_id);

   -- Начислять ли пеню после окончания договора
   if (lastDay <= calcDate and lastDay > lastFineChargeDate) then
       Select op.charge_fine_stopfines, op.fine_on_last_day
         into
              stopFines,        -- прекращать начисление пени после окончания договора
              fineOnLastDay  -- начислять ли пеню в последний день договора
         from SM.Oblig_Presets op
         where op.ID = nvl(presetsID,0);

       if (stopFines = 'Y') then
           if (fineOnLastDay = 'Y') then
               calcDate := lastDay;
           else
               calcDate := lastDay-1;
           end if;
       end if;
   end if;

   ---------------------------------------------------------------------------------------------------
   --Случай, когда оплата будет в том же периоде, что последнее автоначисление пени
   ---------------------------------------------------------------------------------------------------
   if lastObligChargeDate < lastFineChargeDate then
         -- если фиксированная пеня за каждый факт просрочки, то считаем, что пеня уже начислена (!?)
         if (fineKind = 'F' and fineFixedDaily = 'N') then
            RetValue := 0;
         else
           --Кол-во дней для доначисления пени в зависимости от принятого количества дней в году
           if (daysInYear <> 360) then
              daysCount := calcDate - lastFineChargeDate;
           else
              daysCount := sm.CalcFineDays(lastFineChargeDate, calcDate);
           end if;
           if (daysCount >= 0 or addDays >=0) then
               --daysCount := daysCount + addDays;

               -- База доначисления пени
               if (fineKind != 'F') then
                 if (fineOnDebt = 'Y') then
                     --Долг на начало периода доначисления пени
                     currSaldo := sm.CalcFine(lastFineChargeDate,AMoveSet_id,AOblType_id,'PAY','ALL');
                 else
                     --Сумма последнего начисления по основному обязательству, без учета оплаты
                     currSaldo := - lastObligChargeSize;
                 end if;
               else
                   -- Фиксированная сумма пени
                   currSaldo := - 1;
               end if;

               --Пеня
               RetValue := daysCount * fineRate * currSaldo;
           end if;
         end if;
   ---------------------------------------------------------------------------------------------------
   --Случай, когда оплата будет в одном из следующих периодов после последнего автоначисления пени
   ---------------------------------------------------------------------------------------------------
   else
         for xxx in (Select cc.finedate, cc.paysize
             from
               sm.charges cc
             where
               cc.movesets_id=AMoveSet_id
               and cc.obligationtype_id=AOblType_id
               and cc.chargedate > lastFineChargeDate
               and cc.chargedate <= lastObligChargeDate
               and cc.charge_type='OBLIGATION'
               and cc.document_id is null
             order by cc.chargedate
         )
         loop
             -- если фиксированная пеня за каждый факт просрочки
             if (fineKind = 'F' and fineFixedDaily = 'N') then
                 --Пеня
                 addFineVal := - fineRate;
             else
                 --Кол-во дней для доначисления пени в зависимости от принятого количества дней в году
                 if (daysInYear <> 360) then
                    daysCount := xxx.finedate - lastFineChargeDate;
                 else
                    daysCount := sm.CalcFineDays(lastFineChargeDate, xxx.finedate);
                 end if;

                 -- База доначисления пени
                 if (fineKind != 'F') then
                     if (fineOnDebt = 'Y') then
                         --Долг на начало периода доначисления пени
                         currSaldo := sm.CalcFine(lastFineChargeDate,AMoveSet_id,AOblType_id,'PAY','ALL');
                     else
                         --Сумма последнего начисления по основному обязательству, без учета оплаты
                         currSaldo := - xxx.paysize;
                     end if;
                 else
                     -- Фиксированная сумма пени
                     currSaldo := - 1;
                 end if;

                 --Пеня
                 addFineVal := daysCount * fineRate * currSaldo;
             end if;

             lastFineChargeDate := xxx.finedate;
             lastpaysize:=xxx.paysize;
             RetValue := RetValue + addFineVal;
         end loop;

         --Пеня за остаток дней до даты преполагаемого платежа (если НЕ фиксированная пеня за каждый факт просрочки)
         if (fineKind <> 'F' and fineFixedDaily <> 'N') then
             --Кол-во дней для доначисления пени в зависимости от принятого количества дней в году
             if (daysInYear <> 360) then
                daysCount := calcDate - lastFineChargeDate;
             else
                daysCount := sm.CalcFineDays(lastFineChargeDate, calcDate);
             end if;
             daysCount := daysCount + addDays;
             
              -- База доначисления пени
                 if (fineKind != 'F') then
                     if (fineOnDebt = 'Y') then
                         --Долг на начало периода доначисления пени
                         currSaldo := sm.CalcFine(lastFineChargeDate,AMoveSet_id,AOblType_id,'PAY','ALL');
                     else
                         --Сумма последнего начисления по основному обязательству, без учета оплаты
                         currSaldo := - lastpaysize;
                     end if;
                 else
                     -- Фиксированная сумма пени
                     currSaldo := - 1;
                 end if;

             --Пеня
             addFineVal := daysCount * fineRate * currSaldo;

             --Итого пеня
             RetValue := RetValue + addFineVal;
         end if;
   ---------------------------------------------------------------------------------------------------
   end if;

   RETURN RetValue;
END;
/
grant execute on SM.CALCFINEPLAN to SM_ALLUSERS;
grant execute on SM.CALCFINEPLAN to SM_ALL_SELECT;


prompt
prompt Creating function CALCFINEPLANLAST
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION SM.CalcFinePlanLast (ADate IN DATE, AMoveSet_id IN NUMBER, AOblType_id IN NUMBER) RETURN NUMBER IS
-------------------------------------------------------------------
-- XSGROUP ver. 4.8.1
-- Функция возвращает сумму пени
-- за период с даты последнего автоначисления пени, исключая начисление не текущую дату по дату предполагаемого платежа (без автоначисленной суммы)
-- При этом имеется в виду, что от текущей даты до запрашиваемой условия начислений (сумма,размер пени,...) меняться не должны.
-- Нельзя использовать для обязательств с рассрочкой, поскольку функция не умеет вычислять пеню на проценты
--------------------------------------------------------------------
-- Параметры: AMoveSet_id   - ID операции движения
--                  AObligType_id  - ID типа обязательства
--                 ADate             - дата платежа
--------------------------------------------------------------------
  RetValue number(27,2);

  fineComments varchar2(1000);
  fineRate number(27,12):=0;
  strTmp varchar2(200);
  xTmp number(27,12):=0;
  yTmp number(27,12):=0;
  zTmp number(27,12):=0;

  lastFineChargeDate date;
  lastObligChargeDate date;
  lastObligChargeSize number(27,2):=0.0;

  currSaldo number(27,2):=0.0;
 -- addFineVal number(27,2):=0.0;
  daysCount integer:=0;
  addDays integer:=0;
  daysInYear integer:=0;
  installmentPlanCount integer:=0;
  iBracketsBeg integer:=0;
  iBracketsEnd integer:=0;
  iPos integer:=0;
  iPos2 integer:=0;
  periodicalPresetsID number(27);
  presetsID number(27);
  fineKind char(1);
  fineOnDebt char(1);
  fineFixedDaily char(1);
  noFine char(1);
  stopFines char(1);
  fineOnLastDay char(1);
  lastDay date;
  calcDate date;
BEGIN
  RetValue := 0;
  calcDate := ADate;

  -- если обязательства с рассрочкой, то и не пытаемся доначислить пеню (...)
  Select count(p.id) into installmentPlanCount
         from sm.PAYMENTS_PLAN_DRAFT p, SM.OBLIGATIONS o
         where o.moveset_id=p.movesets_id and o.obligationtype_id=p.obligationtype_id and o.moveset_id=AMoveSet_id and o.obligationtype_id=AOblType_id;
  if installmentPlanCount > 0 then
    RETURN RetValue; --0
  end if;

  --Дата и комментарий последнего автоначисления по пене
  Select fr.chargedate, fr.comments  into lastFineChargeDate, fineComments
  from (Select cc.chargedate, cc.comments
         from
           sm.charges cc
         where
           cc.movesets_id=AMoveSet_id
           and cc.obligationtype_id=AOblType_id
           and cc.charge_type='FINE'
           and cc.document_id is null
         order by cc.chargedate desc) fr
  where ROWNUM = 1;

  if lastFineChargeDate is null then
    RETURN RetValue; --0
  end if;
  
    --Дата и сумма последнего, до даты предполагаемого платежа, автоначисления по основному обязательству
  Select fr.chargedate, fr.paysize into lastObligChargeDate, lastObligChargeSize
  from (Select cc.chargedate, cc.paysize
         from
           sm.charges cc
         where
           cc.movesets_id=AMoveSet_id
           and cc.obligationtype_id=AOblType_id
           and cc.chargedate<lastFineChargeDate
           and cc.charge_type='OBLIGATION'
           and cc.document_id is null
         order by cc.chargedate desc) fr
  where ROWNUM = 1;

  if lastObligChargeDate is null then
    RETURN RetValue; --0
  end if;
  
  -- определяем дату, после которой следует начать начисление пени 
  if instr(fineComments,'(на тек.момент)')<>0 then
     lastFineChargeDate:=to_date(substr(fineComments,instr(fineComments,' c ')+3 ,10))-1;
  end if;


  if calcDate <= lastFineChargeDate then
    RETURN RetValue; --0
  end if;

   -- Условия начисления пени
   select pd.calendar_type_id                  -- Принятое в условиях обязательств количество дней в году для расчета пени (365,360)
           , pd.oblig_periodical_presets_id     -- ID периодических параметров расчета
           , ob.oblig_presets_id                   -- ID параметров расчета
           , pd.fine_kind                            -- способ начисления пени: 'P',  'R', 'F'
           , pd.fineondebt                          -- база начисления пени: от долга ('Y') или от обязательства (т.е. от суммы последнего начисления по основному обязательству, без учета оплаты)
           , pd.finevaluefixed_daily              -- за каждый день просрочки ('Y') или за каждый факт
           , pd.no_fine                              -- пеня не начисляется ('Y')
   into daysInYear
        , periodicalPresetsID
        , presetsID
        , fineKind
        , fineOnDebt
        , fineFixedDaily
        , noFine
   from
           sm.Movesets ms,
           sm.PayDocs pd,
           sm.obligations ob,
           sm.obligationtype ot,
           sm.moveperiods mp
          where
            ms.id=ob.moveset_id and
            ot.id=ob.obligationtype_id and
            pd.obligationtype_id=ob.obligationtype_id and
            pd.moveperiod_id=mp.id and
            mp.moveset_id=ms.id and
            mp.SinceDate=(select max(m.SinceDate)
                          from
                            sm.moveperiods m,
                            sm.paydocs p,
                            sm.obligations o
                          where
                            p.moveperiod_id=m.id and
                            p.obligationtype_id=o.obligationtype_id and
                            o.id = ob.id and
                            o.moveset_id = m.moveset_id and
                            m.moveset_id = ms.id
                             and m.SinceDate <= calcDate
                          ) and
             ms.ID=AMoveSet_id and ot.id=AOblType_id and
             ROWNUM = 1;

  -- пеня не начисляется
  if noFine = 'Y' then
    RETURN RetValue; --0
  end if;

   --Коэффициент для расчета пени определяем по комментарию последнего автоначисления по пене:
   -- Ищем строку в первых круглых скобках
   iBracketsBeg := instr(fineComments, '(', 1, 1);
   iBracketsEnd := instr(fineComments, ')', 1, 1);
   strTmp := substr(fineComments, iBracketsBeg + 1, (iBracketsEnd - iBracketsBeg) - 1);
   if length(strTmp) > 1 then
     -- далее - в зависимости от способа начисления пени :
     -- если пеня зависит от ставки рефинансирования
     if fineKind = 'R' then
        -- определяем количество '/'
        iPos := instr(strTmp, '/', 1, 1);
        iPos2 := instr(strTmp, '/', 1, 2);
        if iPos2 = 0 then
            -- один '/'
            iPos := instr(strTmp, '/', 1, 1);
            if iPos > 0 then
               xTmp := to_number(substr(strTmp, 1, iPos-1), '999.999999999999');
               yTmp := to_number(substr(strTmp, iPos+1, length(strTmp)-iPos), '999.999999999999');
               if yTmp <> 0 then
                 fineRate := xTmp/yTmp;
               end if;
            end if;
        else
            -- два '/'
            iPos := instr(strTmp, '/', 1, 1);
            iPos2 := instr(strTmp, '/', 1, 2);
            if (iPos > 0 and iPos2 > 0) then
               xTmp := to_number(substr(strTmp, 1, iPos-1), '999.999999999999');
               yTmp := to_number(substr(strTmp, iPos+1, iPos2-1-iPos), '999.999999999999');
               zTmp := to_number(substr(strTmp, iPos2+1, length(strTmp)-iPos2), '999.999999999999');
               if (yTmp <> 0 and zTmp <> 0) then
                 fineRate := xTmp/yTmp/zTmp;
               end if;
            end if;
        end if;
     -- если пеня - фиксированный процент
     elsif fineKind = 'P' then
           fineRate := to_number(strTmp, '999.999999999999');
     -- если пеня - фиксированная сумма
     elsif fineKind = 'F' then
         fineRate := to_number(strTmp, '999999999999.99');
     end if;
   end if;

   if (nvl(fineRate,0) = 0) then
      return RetValue; --0
   end if;

   -- Начислять ли пеню на день оплаты
   Select (case when opp.charge_fine_method=1 then 1 else 0 end)
     into addDays
     from SM.Oblig_Periodical_Presets opp
     where opp.ID = nvl(periodicalPresetsID,0);

   -- Последний день договора
   select mp.enddate into lastDay
      from sm.moveperiods mp
      where
            mp.moveset_id = AMoveSet_id and
            mp.sincedate=(select max(m.sincedate) from sm.moveperiods m where m.moveset_id = mp.moveset_id);

   -- Начислять ли пеню после окончания договора
   if (lastDay <= calcDate and lastDay > lastFineChargeDate) then
       Select op.charge_fine_stopfines, op.fine_on_last_day
         into
              stopFines,        -- прекращать начисление пени после окончания договора
              fineOnLastDay  -- начислять ли пеню в последний день договора
         from SM.Oblig_Presets op
         where op.ID = nvl(presetsID,0);

       if (stopFines = 'Y') then
           if (fineOnLastDay = 'Y') then
               calcDate := lastDay;
           else
               calcDate := lastDay-1;
           end if;
       end if;
   end if;

   ---------------------------------------------------------------------------------------------------
   --Случай, когда оплата будет в том же периоде, что последнее автоначисление пени
   ---------------------------------------------------------------------------------------------------
 
         -- если фиксированная пеня за каждый факт просрочки, то считаем, что пеня уже начислена (!?)
         if (fineKind = 'F' and fineFixedDaily = 'N') then
            RetValue := 0;
         else
           --Кол-во дней для доначисления пени в зависимости от принятого количества дней в году
           if (daysInYear <> 360) then
              daysCount := calcDate - lastFineChargeDate;
           else
              daysCount := sm.CalcFineDays(lastFineChargeDate, calcDate);
           end if;
           if (daysCount >= 0 or addDays >=0) then
               --daysCount := daysCount + addDays;

               -- База доначисления пени
               if (fineKind != 'F') then
                 if (fineOnDebt = 'Y') then
                     --Долг на начало периода доначисления пени
                     currSaldo := sm.CalcFine(lastFineChargeDate+1,AMoveSet_id,AOblType_id,'PAY','ALL');
                 else
                     --Сумма последнего начисления по основному обязательству, без учета оплаты
                     currSaldo := - lastObligChargeSize;
                 end if;
               else
                   -- Фиксированная сумма пени
                   currSaldo := - 1;
               end if;

               --Пеня
               RetValue := daysCount * fineRate * currSaldo;
           end if;
         end if;
 

   RETURN RetValue;
END;
/
grant execute on SM.CALCFINEPLANLAST to SM_ALL_SELECT;


prompt
prompt Creating function CALCOBLIGATIONEX
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION SM.CalcObligationEx (AMoveperiods_id NUMBER)
RETURN TYPE_CALC_OBLIGATIONS_LIST PIPELINED AS
  ObligType VARCHAR2(50); --Периодичность обязательства
  FineDate INT; -- Порядковый номер дня начала начисления пени в месяце, указанном в поле FineMonths
  FinePercent NUMBER(27,2); -- Размер пени в процентах
  FineRFRPart NUMBER(27,2); -- Доля ставки рефинансирования ЦБ РФ (знаменатель)
  PaySize NUMBER(27,2); -- округлить до 2-х знаков
  Kind CHAR; --('A'); предоплата ('B')
  Purpose_ID NUMBER(27);-- ID записи из таблицы OBLIGATIONTYPE (тип обязательства)
  Recepient_ID NUMBER(27); -- Счет-получатель платежа (ID таблицы RECERIENTS)
  CalendarType NUMBER(27); -- Расчётное количество дней в году при начислении пени (365, 360)
  MainKBK_ID NUMBER(27); -- 90211105034040042120
  FineKBK_ID NUMBER(27); -- 90211105034040042120

  Amovetype_id number(27);
  AREFRATE NUMBER;
  fromdate DATE;
  todate DATE;
  count_day int;
BEGIN
   /* 15/07/2019 Твердохлеб: Процедура вызывается из Saumi-Pascal для расчета обязательств*/

   -- получим тип ОД
   begin
     select ms.MOVETYPE_ID
       into Amovetype_id
       from SM.MOVEPERIODS mp
       JOIN SM.MOVESETS ms on ms.ID = mp.MOVESET_ID
      where mp.ID = AMoveperiods_id;
    
    exception
       when NO_DATA_FOUND then
       null;
   end;

   -- Неосновантельное обогащение
   IF (Amovetype_id = 35) THEN
      -- получим текущую ставку рефенансирования
      begin
       SELECT q.REFRATE
         into AREFRATE
         FROM 
              (
               SELECT *
                 from SM.REFINRATES r
                where r.APPLY_DATE <= SYSDATE
                order BY r.APPLY_DATE DESC
              )q
        where ROWNUM = 1;
      
        exception
        when NO_DATA_FOUND then
                      null;
      end;

      -- получим период и количество дней использования
     /* begin
       select COALESCE(mp.ENDDATE, sysdate)
         from SM.MOVEPERIODS mp
        where mp.ID = AMoveperiods_id;
      
        exception
        when NO_DATA_FOUND then
                      null;
      end;*/
   END IF;

   pipe row (TYPE_CALC_OBLIGATIONS(
                                  ObligType,
                                  FineDate,
                                  FinePercent,
                                  FineRFRPart,
                                  PaySize,
                                  Kind,
                                  Purpose_ID,
                                  Recepient_ID,
                                  CalendarType,
                                  MainKBK_ID,
                                  FineKBK_ID
                                ));
RETURN;
end CalcObligationEx;
/

prompt
prompt Creating function CALC_LOST_PROFITS
prompt ===================================
prompt
create or replace function sm.CALC_LOST_PROFITS(MS_ID number, Adate date, startdate date, enddate date) return number is
-- 22122024 - Чувыкин В.Э. - Функция возвращает сумму упущенной выгоды по конкретной операции движения вида Безв.пользование
-- на вход:
-- Adate - дата актуальности, то есть дата, на которую считается упущенная выгода
-- startdate - дата начала действия договора БП, по ней из справочника Справедливой стоимости вычитывается ставка СпСт
-- enddate - дата окончания действия договора БП ЛИБО дата, по которую считается упущенная выгода

 cost_fair_value1 number(27,2);
 cost_fair_value number(27,2);
 all_cost_fair_value number(27,2);
 res number(27,2);
 last_charge_date date;
 last_day_of_1month number;
 days_of_CHARGING_1month number;
 last_day_of_month number;
 last_day_of_CHARGING number;
 pay_periodical char;

begin

 all_cost_fair_value := 0;
 cost_fair_value1:=0;
 cost_fair_value:=0;

for zzz in (

select 
 o.id,
 o.objtypes_id,
 mi.square
from sm.objects o
left join sm.moveitems mi on mi.object_id = o.id
left join sm.moveperiods mp on mp.id = mi.moveperiod_id
left join sm.movesets mv on mv.id = mp.moveset_id
where mv.id = MS_ID 
and mp.sincedate <= Adate and (mp.enddate >= Adate or mp.enddate is null)
)

loop

if startdate > '31.12.2018'
then
begin  
 select fv.cost_value
 into cost_fair_value1 
 from sm.fair_value fv 
 where fv.object_cat = zzz.objtypes_id 
 and fv.start_date<=startdate and fv.end_date>=startdate;
                exception
                when NO_DATA_FOUND then 
                cost_fair_value1:=0;
                end;
end if;

if startdate <= '31.12.2018'
then
begin  
 select fv.cost_value
 into cost_fair_value1 
 from sm.fair_value fv 
 where fv.object_cat = zzz.objtypes_id 
 and fv.start_date>='01.01.2018' and fv.end_date<='31.12.2018';
                exception
                when NO_DATA_FOUND then 
                cost_fair_value1:=0;
                end;
end if;

if zzz.objtypes_id = 3 
  then cost_fair_value := cost_fair_value1 * zzz.square;
end if;

if zzz.objtypes_id = 2
  then cost_fair_value := cost_fair_value1;
end if;

if zzz.objtypes_id = 1
  then cost_fair_value := 1;
end if;

if zzz.objtypes_id = 5
  then cost_fair_value := 1;
end if;

if zzz.objtypes_id = 7
  then cost_fair_value := 0;
end if;

all_cost_fair_value := all_cost_fair_value + cost_fair_value;

end loop;

select extract (day from to_date(last_day(startdate),'dd.mm.yyyy')) into last_day_of_1month FROM DUAL; --определяется количество дней первого месяца договора
select last_day_of_1month + 1 - extract(day from to_date(startdate,'dd.mm.yyyy')) into days_of_CHARGING_1month FROM DUAL;--определяется количество дней действия договора в его первом месяце

select extract (day from to_date(enddate,'dd.mm.yyyy')) into last_day_of_CHARGING FROM DUAL;--определяется количество дней действия договора в его поcледнем месяце
select extract (day from to_date(last_day(enddate),'dd.mm.yyyy')) into last_day_of_month FROM DUAL; --определяется количество дней последнего месяца договора

if ADate = startdate then --если расчет Упущенной выгоды идет с начала действия договора, то нужно еще произвести расчет по дням первого месяца действия договора
  res := all_cost_fair_value * trunc(MONTHS_BETWEEN(trunc(enddate,'mm'),Adate)) + (all_cost_fair_value / last_day_of_month) * last_day_of_CHARGING + (all_cost_fair_value / last_day_of_1month) * days_of_CHARGING_1month;
 end if; 
 
if ADate = startdate and MONTHS_BETWEEN(enddate,Adate)<1 then --если требуется рассчитать упущенную выгоду менее чем за один месяц и этот месяц - первый в сроке действия договора
  res := (all_cost_fair_value / last_day_of_1month) * days_of_CHARGING_1month;
 end if;  
 
if ADate <> startdate and MONTHS_BETWEEN(enddate,Adate)<1 then --если требуется рассчитать упущенную выгоду менее чем за один месяц и этот месяц - последний в сроке действия договора
  res := (all_cost_fair_value / last_day_of_month) * last_day_of_CHARGING;
 end if;   
  
if ADate <> startdate then --если расчет Упущенной выгоды производится с других дат, желательно с ровных начал периодов, то расчет по дням первого месяца действия договора не нужен
  res := all_cost_fair_value * trunc(MONTHS_BETWEEN(trunc(enddate,'mm'),Adate)) + (all_cost_fair_value / last_day_of_month) * last_day_of_CHARGING;
 end if;

if res<0 then res:=0; end if;

return (RES);

end;
/
grant execute on SM.CALC_LOST_PROFITS to SM_ALLUSERS;


