prompt
create or replace function sm.CALC_LOST_PROFITS_4TERM_CNTR(MS_ID number, Adate date, startdate date, enddate date) return number is
-- 210324 - Чувыкин В.Э. - Функция возвращает сумму упущенной выгоды по конкретной операции движения вида Безв.пользование - вариант для досрочно расторгнутых договоров БП

 cost_fair_value1 number(27,2);
 cost_fair_value number(27,2);
 all_cost_fair_value number(27,2);
 res number(27,2);
 last_charge_date date;
 last_day_of_1month number;
 days_of_CHARGING_1month number;
 last_day_of_month number;
 last_day_of_CHARGING number;
 pay_periodical char;

begin

 all_cost_fair_value := 0;
 cost_fair_value1:=0;
 cost_fair_value:=0;

for zzz in (

select
 o.id,
 o.objtypes_id,
 mi.square
from sm.objects o
left join sm.moveitems mi on mi.object_id = o.id
left join sm.moveperiods mp on mp.id = mi.moveperiod_id
left join sm.movesets mv on mv.id = mp.moveset_id
where mv.id = MS_ID
and mp.sincedate <= Adate and (mp.enddate >= Adate or mp.enddate is null)
)

loop

if startdate > '31.12.2018'
then
begin
 select fv.cost_value
 into cost_fair_value1
 from sm.fair_value fv
 where fv.object_cat = zzz.objtypes_id
 and fv.start_date<=startdate and fv.end_date>=startdate;
                exception
                when NO_DATA_FOUND then
                cost_fair_value1:=0;
                end;
end if;

if startdate <= '31.12.2018'
then
begin
 select fv.cost_value
 into cost_fair_value1
 from sm.fair_value fv
 where fv.object_cat = zzz.objtypes_id
 and fv.start_date>='01.01.2018' and fv.end_date<='31.12.2018';
                exception
                when NO_DATA_FOUND then
                cost_fair_value1:=0;
                end;
end if;

if zzz.objtypes_id = 3
  then cost_fair_value := cost_fair_value1 * zzz.square;
end if;

if zzz.objtypes_id = 2
  then cost_fair_value := cost_fair_value1;
end if;

if zzz.objtypes_id = 1
  then cost_fair_value := 1;
end if;

if zzz.objtypes_id = 5
  then cost_fair_value := 1;
end if;

if zzz.objtypes_id = 7
  then cost_fair_value := 0;
end if;

all_cost_fair_value := all_cost_fair_value + cost_fair_value;

end loop;

select extract (day from to_date(last_day(Adate),'dd.mm.yyyy')) into last_day_of_1month FROM DUAL; --определяется количество дней  месяца, когда  договор расторгали
select last_day_of_1month - extract(day from to_date(Adate,'dd.mm.yyyy')) into days_of_CHARGING_1month FROM DUAL;--определяется количество дней в месяце, когда договор расторгали, оставшихся после дня расторжения

select extract (day from to_date(enddate,'dd.mm.yyyy')) into last_day_of_CHARGING FROM DUAL;--определяется количество дней действия договора в его поcледнем месяце
select extract (day from to_date(last_day(enddate),'dd.mm.yyyy')) into last_day_of_month FROM DUAL; --определяется количество дней последнего месяца договора

  res := all_cost_fair_value * trunc(MONTHS_BETWEEN(trunc(enddate,'mm'),Adate)) + (all_cost_fair_value / last_day_of_month) * last_day_of_CHARGING + (all_cost_fair_value / last_day_of_1month) * days_of_CHARGING_1month;

return (RES);

end;
/
grant execute on SM.CALC_LOST_PROFITS_4TERM_CNTR to SM_ALLUSERS;


