prompt
prompt Creating function GETPOSITIONCLIENTIDBYDATE
prompt ===========================================
prompt
create or replace function sm.GetPositionClientIDByDate(ObjID NUMBER, MoveTypes_ID NUMBER, CDate IN DATE) return NUMBER is
--
-- by XS Group, ver. 4.8.0 (2012.10.15)
-- функция возвращает ID клиента на имя которого оформлено движения объекта ObjID,
-- вида движения MoveType_ID в момент времени CDate
--
  Recv NUMBER:=null;
  ObjType NUMBER;
  BaseBuildID NUMBER;
  BaseObjID NUMBER;
begin
  select ObjTypes_ID into ObjType from sm.Objects where ID=ObjID;
  
  -- если это "Пакеты акций, доли в капитале", 
  -- то право собственности определяем по ОД Собственность с субъектом -
  -- собстенником объекта "Пакеты акций, доли в капитале"

  if (ObjType = 21 and MoveTypes_ID = 1) then
      for x IN ( select 
                   ms.client_id ClientID 
                 from
                   sm.Movesets ms,
                   sm.moveitems mi,
                   sm.moveperiods mp
                 where
                   ms.movetype_id=MoveTypes_Id and
                   mp.moveset_id=ms.id and
                   mi.moveperiod_id=mp.id and
                   mi.object_id=ObjID and
                   exists (select * from sm.objshares osh where osh.owner_id=ms.client_id and osh.objects_id=mi.object_id) and
                   trunc(mp.sincedate)<=trunc(CDate) and
                  (trunc(mp.enddate)>=trunc(CDate) or mp.enddate is null)) 
      loop    
        Recv:=x.ClientID;    
        exit;
      end loop;    
      return(Recv);
  end if;

  --для всех прочих объектов
  for x IN ( select 
               ms.client_id ClientID 
             from
               sm.Movesets ms,
               sm.moveitems mi,
               sm.moveperiods mp
             where
               ms.movetype_id=MoveTypes_Id and
               mp.moveset_id=ms.id and
               mi.moveperiod_id=mp.id and
               mi.object_id=ObjID and
               trunc(mp.sincedate)<=trunc(CDate) and
              (trunc(mp.enddate)>=trunc(CDate) or mp.enddate is null)) 
  loop

    Recv:=x.ClientID;

    exit;
  end loop;
  

  if Recv is not null then
    return(Recv);
  end if;

  -- поищем в LINKS_MI_OBJECTS
  for x IN ( select 
               ms.client_id ClientID 
             from
               sm.Movesets ms,
               sm.moveitems mi,
               sm.moveperiods mp,
               sm.links_mi_objects mio
             where
               ms.movetype_id=MoveTypes_Id and
               mp.moveset_id=ms.id and
               mi.moveperiod_id=mp.id and
               mi.id=mio.moveitems_id and
               mio.objects_id=ObjID and
               trunc(mp.sincedate)<=trunc(CDate) and
              (trunc(mp.enddate)>=trunc(CDate) or mp.enddate is null)) 
  loop

    Recv:=x.ClientID;

    exit;
  end loop;
    
  if Recv is not null then
    return(Recv);
  end if;

 
 -- разбор случая, если это здание
 if ObjType = 3 then
   select 
     Basebuilding 
   into 
     BaseBuildID
   from 
     sm.Buildings
   where 
     Objects_ID=ObjID;

   if (BaseBuildID is not null) then
     select 
       Objects_ID 
     into 
       BaseObjID
     from 
       sm.Buildings
     where 
       ID=BaseBuildID;
       
     Return (sm.GetPositionClientIDByDate(BaseObjID,MoveTypes_ID,CDate));
   end if;
 end if;

 return(Recv);

exception
 when NO_DATA_FOUND then return null;

end;
/
grant execute on SM.GETPOSITIONCLIENTIDBYDATE to SM_ALLUSERS;
grant execute on SM.GETPOSITIONCLIENTIDBYDATE to SM_ALL_SELECT;


prompt
prompt Creating function CANMOVE
prompt =========================
prompt
create or replace function sm.CanMove(ObjID in NUMBER, MoveType_ID in NUMBER, CDate IN DATE) return varchar2 is
  Result varchar2(200);
 OBJTYPE INTEGER;
 KUMI_ID NUMBER(27);
 Doing VARCHAR2(250);
 S VARCHAR2(250);
 LOG_CHECK VARCHAR2(1); 
 SQ_POL VARCHAR2(15);
begin
  Result:=NULL;
  S:='';
  
  -- по балансодержанию и пользованию аналитику не производить !
  if MoveType_ID IN (2,3) THEN 
   Return(null);
  end if; 
  
  SELECT VALUE INTO LOG_CHECK FROM SM_SETTINGS WHERE KEY_NAME='LOG_CHECK';
  
  IF LOG_CHECK='N' THEN
   return(Result);
  END IF;
  
  SELECT ObjTypes_ID INTO OBJTYPE FROM Objects WHERE ID=ObjID;
  SELECT VALUE INTO KUMI_ID FROM SM_SETTINGS WHERE KEY_NAME='KUMI_ID';
  SELECT RTRIM(Doing) INTO Doing FROM MOVETYPE WHERE ID=MoveType_ID;
  SELECT SQUARE_POLICY INTO SQ_POL FROM MOVETYPE WHERE ID=MoveType_ID;

  --объект должен быть выделен по данному движению
--  IF MoveType_ID != 1 THEN
   IF nvl(GetPositionClientIDByDate(ObjID,MoveType_ID,CDate),0) != 0 THEN
 
    IF (SQ_POL='INTERSECT') or (OBJTYPE != 3) THEN 
     return (Doing || ' невозможна, так как объект уже участвует в подобной операции');
    ELSE
     return ('+' || Doing || ' возможна, но объект уже участвует в подобной операции. При этом на оформленную операцию будет выделена часть площадей.');
    END IF; 

   END IF;
--  END IF; 
  
  --теперь если это здание или помещение стоит проверить, 
  --а не проведена ли эта операция с частью объекта
  IF OBJTYPE=3 THEN
   --придется порыться со всеми подчиненными
   FOR ChildBuildings IN ( SELECT Objects_ID
                           FROM Buildings
                           WHERE Objects_ID != ObjID
                           START WITH Objects_ID= ObjID
                           CONNECT BY PRIOR ID=Basebuilding) LOOP
    IF nvl(GetPositionClientIDByDate(ChildBuildings.Objects_ID,MoveType_ID,CDate),0) != 0 THEN
      return (Doing || ' невозможна, так как часть объект уже участвует в подобной операции');
    END IF;
   END LOOP;                        
  END IF;
  
  --произволная проверка по видам движения
  IF MoveType_ID =1 THEN
   --при передаче в собственность проверить по всем типам
   IF nvl(GetPositionClientIDByDate(ObjID,2,CDate),0) != 0 THEN
    Result:='.';
    S:=S || 'объект у кого-то на балансе ';
   END IF;
   --3 пользование
   IF nvl(GetPositionClientIDByDate(ObjID,3,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в пользовании ';
   END IF;
   --4 аренда
   IF nvl(GetPositionClientIDByDate(ObjID,4,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в аренде ';
   END IF;
   --5 субаренда
   IF nvl(GetPositionClientIDByDate(ObjID,5,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в субаренде ';
   END IF;
   --6 строительство
   IF nvl(GetPositionClientIDByDate(ObjID,6,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на строительстве ';
   END IF;
   --7 приватизация
   IF nvl(GetPositionClientIDByDate(ObjID,7,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект в процессе приватизации(необходимо завершить его) ';
   END IF;
   --8 обслуживание
   IF nvl(GetPositionClientIDByDate(ObjID,8,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на обслуживании ';
   END IF;
   --9 учет
   IF nvl(GetPositionClientIDByDate(ObjID,9,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на обслуживании ';
   END IF;
   --10 управление
   IF nvl(GetPositionClientIDByDate(ObjID,10,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в управлении ';
   END IF;

   --11 арендный фонд
   IF nvl(GetPositionClientIDByDate(ObjID,11,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект зарегистрирован в арендном фонде ';
   END IF;
   
   IF Result='.' THEN 
    return ('Передача в собственность невозможна так как ' || S);   
   END IF;
   
  ELSIF MoveType_ID IN (2,3,6,7,8,9,10,11) THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return (Doing || ' невозможна, так как объект не в муниципальной собственности.');
   END IF;
  ELSIF MoveType_ID=3 THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return ('Передача в пользование невозможна, так как объект не в муниципальной собственности.');
   END IF;
  ELSIF (MoveType_ID=4) OR (MoveType_ID=5) THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return ('Передача в аренду/субаренду невозможна, так как объект не в муниципальной собственности.');
   END IF;
   IF nvl(GetPositionClientIDByDate(ObjID,11,CDate),0) != KUMI_ID THEN
    return ('Передача в аренду/субаренду невозможна, так как объект не входит в арендный фонд');
   END IF;
  END IF;

  return(Result);
end CanMove;
/
grant execute on SM.CANMOVE to SM_ALLUSERS;
grant execute on SM.CANMOVE to SM_ALL_SELECT;


prompt
prompt Creating function CANMOVE_OLD
prompt =============================
prompt
create or replace function sm.CanMove_OLD(ObjID in NUMBER, MoveType_ID in NUMBER, CDate IN DATE) return varchar2 is
  Result varchar2(200);
 OBJTYPE INTEGER;
 KUMI_ID NUMBER(27);
 Doing VARCHAR2(250);
 S VARCHAR2(250);
 LOG_CHECK VARCHAR2(1); 
 SQ_POL VARCHAR2(15);
begin
  Result:=NULL;
  S:='';
  
  -- по балансодержанию и пользованию аналитику не производить !
  if MoveType_ID IN (2,3) THEN 
   Return(null);
  end if; 
  
  SELECT VALUE INTO LOG_CHECK FROM SM_SETTINGS WHERE KEY_NAME='LOG_CHECK';
  
  IF LOG_CHECK='N' THEN
   return(Result);
  END IF;
  
  SELECT ObjTypes_ID INTO OBJTYPE FROM Objects WHERE ID=ObjID;
  SELECT VALUE INTO KUMI_ID FROM SM_SETTINGS WHERE KEY_NAME='KUMI_ID';
  SELECT RTRIM(Doing) INTO Doing FROM MOVETYPE WHERE ID=MoveType_ID;
  SELECT SQUARE_POLICY INTO SQ_POL FROM MOVETYPE WHERE ID=MoveType_ID;

  --объект должен быть выделен по данному движению
--  IF MoveType_ID != 1 THEN
   IF nvl(GetPositionClientIDByDate(ObjID,MoveType_ID,CDate),0) != 0 THEN
 
    IF (SQ_POL='INTERSECT') or (OBJTYPE != 3) THEN 
     return (Doing || ' невозможна, так как объект уже участвует в подобной операции');
    ELSE
     return ('+' || Doing || ' возможна, но объект уже участвует в подобной операции. При этом на оформленную операцию будет выделена часть площадей.');
    END IF; 

   END IF;
--  END IF; 
  
  --теперь если это здание или помещение стоит проверить, 
  --а не проведена ли эта операция с частью объекта
  IF OBJTYPE=3 THEN
   --придется порыться со всеми подчиненными
   FOR ChildBuildings IN ( SELECT Objects_ID
                           FROM Buildings
                           WHERE Objects_ID != ObjID
                           START WITH Objects_ID= ObjID
                           CONNECT BY PRIOR ID=Basebuilding) LOOP
    IF nvl(GetPositionClientIDByDate(ChildBuildings.Objects_ID,MoveType_ID,CDate),0) != 0 THEN
      return (Doing || ' невозможна, так как часть объект уже участвует в подобной операции');
    END IF;
   END LOOP;                        
  END IF;
  
  --произволная проверка по видам движения
  IF MoveType_ID =1 THEN
   --при передаче в собственность проверить по всем типам
   IF nvl(GetPositionClientIDByDate(ObjID,2,CDate),0) != 0 THEN
    Result:='.';
    S:=S || 'объект у кого-то на балансе ';
   END IF;
   --3 пользование
   IF nvl(GetPositionClientIDByDate(ObjID,3,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в пользовании ';
   END IF;
   --4 аренда
   IF nvl(GetPositionClientIDByDate(ObjID,4,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в аренде ';
   END IF;
   --5 субаренда
   IF nvl(GetPositionClientIDByDate(ObjID,5,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в субаренде ';
   END IF;
   --6 строительство
   IF nvl(GetPositionClientIDByDate(ObjID,6,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на строительстве ';
   END IF;
   --7 приватизация
   IF nvl(GetPositionClientIDByDate(ObjID,7,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект в процессе приватизации(необходимо завершить его) ';
   END IF;
   --8 обслуживание
   IF nvl(GetPositionClientIDByDate(ObjID,8,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на обслуживании ';
   END IF;
   --9 учет
   IF nvl(GetPositionClientIDByDate(ObjID,9,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то на обслуживании ';
   END IF;
   --10 управление
   IF nvl(GetPositionClientIDByDate(ObjID,10,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект у кого-то в управлении ';
   END IF;

   --11 арендный фонд
   IF nvl(GetPositionClientIDByDate(ObjID,11,CDate),0) != 0 THEN
    Result:='.';
    IF S != '' THEN
     S:=S || ', ';
    END IF; 
    S:=S || 'объект зарегистрирован в арендном фонде ';
   END IF;
   
   IF Result='.' THEN 
    return ('Передача в собственность невозможна так как ' || S);   
   END IF;
   
  ELSIF MoveType_ID IN (2,3,6,7,8,9,10,11) THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return (Doing || ' невозможна, так как объект не в муниципальной собственности.');
   END IF;
  ELSIF MoveType_ID=3 THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return ('Передача в пользование невозможна, так как объект не в муниципальной собственности.');
   END IF;
  ELSIF (MoveType_ID=4) OR (MoveType_ID=5) THEN
   IF nvl(GetPositionClientIDByDate(ObjID,1,CDate),0) != KUMI_ID THEN
    return ('Передача в аренду/субаренду невозможна, так как объект не в муниципальной собственности.');
   END IF;
   IF nvl(GetPositionClientIDByDate(ObjID,11,CDate),0) != KUMI_ID THEN
    return ('Передача в аренду/субаренду невозможна, так как объект не входит в арендный фонд');
   END IF;
  END IF;

  return(Result);
end;
/
grant execute on SM.CANMOVE_OLD to SM_ALL_SELECT;


prompt
prompt Creating function CHECKMIOBJSHARESORGTYPE
prompt =========================================
prompt
create or replace function sm.CheckMIObjSharesOrgType(A_ItemID in number) return integer is
 retval integer;
begin
  -- XS Group ver.23.04.2012
  -- служебная функция для допреквизитов MOVEITEMS с использованием SQL_OPTION 
  -- Если объект - "Пакет акций,доля", то проверяется организационно-правовая форма ЮЛ:
  -- если организационно-правовая форма МУ или МУП, то возвращает 0, иначе возвращает 1
 
  begin
    select
      count(*)
    into
      retval
    from
      sm.ObjShares o, sm.organisations org, sm.orgforms f
    where
      org.id=o.organisations_id 
      and f.id=org.orgform 
      and f.is_publicoffice<>'Y' and f.hasauthorizedfund<>'Y'
      and o.objects_id=A_ItemID;
      
    if (retval > 0) then
      retval:=1;
    else
      retval:=0;  
    end if;      
  end; 
 
  return retval;
  
end CheckMIObjSharesOrgType;
/
grant execute on SM.CHECKMIOBJSHARESORGTYPE to SM_ALLUSERS;
grant execute on SM.CHECKMIOBJSHARESORGTYPE to SM_ALL_SELECT;


prompt
prompt Creating function CHECKMIOBJSHARESTYPE
prompt ======================================
prompt
create or replace function sm.CheckMIObjSharesType(A_ItemID in number) return integer is
 retval integer;
  -- XS Group ver.20.08.2012
  -- служебная функция для допреквизита MOVEITEMS.SHARESNUMBER с использованием SQL_OPTION 
  -- Если объект - "Пакет акций,доля", то проверяется вид участия:
  -- если 'Акции' - возвращает 1, 
  -- если 'Доля'  - возвращает 2,
  -- иначе - возвращает 0
begin
  
  begin
    select
      decode(t.guid,'6B1E81B10EAD422697278563AD148DB7',1,'19BD2FD84F5E4B7D85575A1388CC0A24',2,0)
    into
      retval
    from
      sm.ObjShares o, sm.Sharetypes t
    where
      t.ID=o.sharetypes_id 
      and o.objects_id=A_ItemID;
  exception
    when NO_DATA_FOUND then
      retval:=0;
  end;  
    
  return(retval);  
  
end;
/
