prompt
prompt Creating function CHECKOBJECTUSING
prompt ==================================
prompt
create or replace function sm.CheckObjectUsing(AClientID NUMBER, AObjID IN NUMBER, MoveTypes_ID NUMBER,
                                            CDate IN DATE, EDate IN DATE,
                                            ExclMoveSetID IN NUMBER default null) return varchar2 is
  Recv varchar2(4000);
  RECV_LENGTH integer;  
  ObjType NUMBER(27,0);
  BaseBuildID NUMBER(27,0);
  BaseObjID NUMBER(27,0);
  MSID sm.movesets.id%type;
BEGIN

  RECV_LENGTH:=512; -- длина возвращаемого значения (до скольки символов будем урезать)

  Recv:=null;

  -- by XSGROUP ver. 29.04.2013
  --
  -- Производится проверка на соответствие использования объекта заданным клиентом
  --
  --    ClientID=-1 - требуется чтобы НЕ использовался
  --    возможный отрицательный ответ: 'Client.Name Date1[-Date2], ...'
  --
  --    ClientID=0 - требуется чтобы использовался
  --    возможный отрицательный ответ: NULL
  --    положительный ответ: '+'
  --
  --    ClientID=N - требуется чтобы использовался клиентом N
  --    возможный отрицательный ответ: 'Client.Name Date1[-Date2]'
  
  --    ExclMoveSetID - ID операции движения, которую следует исключить из проверки
  --    если ExclMoveSetID = null или -1, в отборе участвуют все ОД

  select ObjTypes_ID into ObjType from Objects where ID=AObjID;
  
  MSID:=nvl(ExclMoveSetID,-1);
 
  -- если это не здания и помещения - никаких проблем
  for jj IN ( select 
                Clients.ID ClientID, 
                Clients.Name ClientName, 
                mp.sincedate PostingDate, 
                mp.enddate
              from 
                sm.Clients, 
                sm.movesets ms,
                sm.moveperiods mp,
                sm.moveitems mi
              where
                ms.id=mp.moveset_id and
                mp.id=mi.moveperiod_id and
                AObjID=mi.object_id and
                Clients.ID=ms.client_id  and
                mp.sincedate(+)<=CDate and
                (nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy')))>=CDate and
                ms.movetype_id=MoveTypes_ID and
                ms.id<>MSID)

   LOOP
     if AClientID=-1 then
     --  ClientID=-1 - требуется чтобы НЕ использовался
     --  возможный отрицательный ответ: 'Client.Name Date1[-Date2], ...'
       if Recv IS NULL then 
         Recv:=''; 
       else 
         Recv:=RTRIM(Recv) || ', '; 
       end if;

       Recv:=Recv || RTRIM(jj.ClientName) || ' (с ' || TO_CHAR(jj.PostingDate);
       if jj.EndDate IS NOT NULL then 
         Recv:= Recv || ' по ' || TO_CHAR(jj.EndDate); 
       end if;
       
       Recv:= Recv || ')';
     else
       if AClientID=0 then 
         return('+'); 
       end if;
     
       if jj.ClientID = AClientID then
         --  ClientID=N - требуется чтобы использовался клиентом N
         --   возможный отрицательный ответ: 'Client.Name Date1[-Date2]'
         Recv:=Recv || RTRIM(jj.ClientName) || ' (с ' || TO_CHAR(jj.PostingDate);
         if jj.EndDate IS NOT NULL then 
           Recv:= Recv || ' по ' || TO_CHAR(jj.EndDate); 
         end if;
       
         Recv:= Recv || ')';
         
         
       end if;
     end if;
     -- проверим, не превышает ли результат заланную длину
     if length(Recv)>=RECV_LENGTH then -- урежем и выйдем
       Recv:=SUBSTR(Recv,1,RECV_LENGTH-30)||' ... (отображена часть списка)';
       return(TRIM(Recv));
     end if;

   END LOOP;

   if not Recv is null then
     return(TRIM(Recv));
   end if;

   -- разбор случая, если это здание
   if ObjType = 3 then
     select 
       Basebuilding 
     into 
       BaseBuildID
     from 
       Buildings
     where 
       Objects_ID=AObjID;

     if not (BaseBuildID is null) then
       select 
         Objects_ID 
       into 
         BaseObjID
       from 
         Buildings
       where 
         ID=BaseBuildID;
         
       return (CheckObjectUsing(AClientID,BaseObjID,MoveTypes_ID,CDate,EDate,ExclMoveSetID));
     end if;
    
   end if;

   return(RTRIM(Recv));

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN NULL;

END;
/
grant execute on SM.CHECKOBJECTUSING to SM_ALLUSERS;
grant execute on SM.CHECKOBJECTUSING to SM_ALL_SELECT;
grant execute on SM.CHECKOBJECTUSING to SM_CANMOVE;


prompt
prompt Creating function CHECKPRIVATESBORNYEAR
prompt =======================================
prompt
create or replace function sm.CheckPrivatesBornYear(A_ItemID in number) return number is
 retval number;
 k_val sm.sm_settings.KEY_TYPE%type;
begin
  -- by XS Group ver.17.03.2010
  -- служебная функция для допреквизита SQL_OPTION поля GROUNDS.BORNYEAR
  -- запрашивается значение параметра PRIVATES_BORNDATE_AS_YEAR
  -- если 'Y' - возвращает 1, если 'N' - возвращает 0
 
  begin
    select
      UPPER(trim(ss.VALUE))
    into
      k_val
    from
      sm.sm_settings ss
    where
      ss.KEY_NAME='PRIVATES_BORNDATE_AS_YEAR';
      
    if k_val='Y' then
      retval:=1;
    else
      retval:=0;  
    end if;      
  exception
    when NO_DATA_FOUND then
      retval:=0;  
  end; 
 
  return retval;
  
end;
/
grant execute on SM.CHECKPRIVATESBORNYEAR to SM_ALLUSERS;
grant execute on SM.CHECKPRIVATESBORNYEAR to SM_ALL_SELECT;


