prompt
create or replace function sm.CheckPrivatesBornDate(A_ItemID in number) return number is
 retval number;
begin
  -- by XS Group ver.17.03.2010
  -- служебная функция для допреквизита SQL_OPTION поля GROUNDS.BOR_DATE
  -- запрашивается значение параметра PRIVATES_BORNDATE_AS_YEAR
  -- если 'Y' - возвращает 0, если 'N' - возвращает 1
 
  select
    sm.CheckPrivatesBornYear(null)
