prompt
prompt Creating function GETDOCCERTIFICATEBYMOVEID
prompt ===========================================
prompt
create or replace function sm.GetDocCertificateByMoveID(MoveID NUMBER) return number is
  Recv number;
begin
 /* 02/12/2015 Твердохлеб: [138] - добавил новый документ Запись о гос.рег-ции права*/
 
 select s.document_id 
   INTO Recv
   from (
         SELECT
           dsm.document_id
         FROM
           sm.Movements m,
           sm.Docset_Members dsm,
           sm.Movesets ms,
           sm.documents d
         WHERE
           m.ID=MoveID and
           m.MoveSet_ID=ms.ID and
           ms.docset_id=dsm.docset_id and
           d.id = dsm.document_id and
           d.doctypes_id in (748,1742,3117) -- свидетельства
          order by d.doctypes_id desc 
         ) s
   where 
   rownum < 2;

  return(Recv);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end;
/
grant execute on SM.GETDOCCERTIFICATEBYMOVEID to SM_ALLUSERS;
grant execute on SM.GETDOCCERTIFICATEBYMOVEID to SM_ALL_SELECT;


prompt
prompt Creating function GETPURPOSEBYMOVETYPEID
prompt ========================================
prompt
CREATE OR REPLACE FUNCTION SM.GetPurposeByMoveTypeID(ObjID IN NUMBER, AMoveType_id IN NUMBER) RETURN CHAR IS
 Purpose CHAR(60);
BEGIN
 /* Твердохлеб : Получает назначение для конкретного типа ОД*/
 /* 02/04/2015 Твердохлеб оптимизировал запрос, ушел от курсора*/
 /* 18/05/2016 Твердохлеб: Добавил поиск назначения в пред закрытом периоде*/
 
 begin
   SELECT LeasePurpose.Name Purpose
     INTO Purpose
     FROM sm.Movements,
          sm.LeasePurpose
    WHERE Movements.Objects_ID = ObjID and
          Movements.MoveType_ID = AMoveType_id and
          Movements.LeasePurpose_ID = LeasePurpose.ID and
          Movements.PostingDate <= sysdate and
         (Movements.EndDate >= sysdate or Movements.EndDate IS NULL) and
          rownum <= 1;
    exception
    when NO_DATA_FOUND then
    null;
 end;
        
 if (Purpose is null) then
    begin
      select s.name_purpose
        INTO Purpose
        from (
              SELECT LeasePurpose.Name name_purpose              
                FROM sm.Movements,
                     sm.LeasePurpose
               WHERE Movements.Objects_ID = ObjID and
                     Movements.MoveType_ID = AMoveType_id and
                     Movements.LeasePurpose_ID = LeasePurpose.ID and
                     coalesce(Movements.EndDate, cast ('01.01.2050' as date)) <= sysdate
              order by Movements.EndDate desc 
              )s
        where rownum <= 1; 
      exception
       when NO_DATA_FOUND then
       null;
   end;
 end if;
        
 Return Purpose; 
END;
/
grant execute on SM.GETPURPOSEBYMOVETYPEID to SM_ALLUSERS;
grant execute on SM.GETPURPOSEBYMOVETYPEID to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJECTCOMMONNAME
prompt =====================================
prompt
create or replace function sm.GetObjectCommonName(Flag in char, ObjectsID in number) return varchar2 is
Result varchar2(4000);
ObjectType number;
B_Type number;
b_name varchar2(1000);
b_type_name varchar2(1000);
begin
/* 18.05.19 Чувыкин В.Э. НАИМЕНОВАНИЕ объекта любого типа по алгоритму, определенному Быкаревой В.Н. */

-- определение типа объекта
begin
   select
        o.objtypes_id
        into ObjectType
        from
        sm.objects o
        where
        o.id=ObjectsID;
        exception
        when NO_DATA_FOUND then
        null;
end;

--если прочее движимое
if ObjectType=1 then
begin
   select
         o.description
         into Result
         from
         sm.objects o
         where
         o.id=ObjectsID;
         exception
         when NO_DATA_FOUND then
         null;
end;
end if;

--если транспорт
if ObjectType=2 then
begin
   select
         tt.name || ' ' || brand.name || ' ' || t.model
         into Result
         from
             sm.objects o
             join transport t on t.objects_id = o.id
             join transptype tt on tt.id = t.transptype_id
             join brandnames brand on brand.id = t.brandnames_id
         where
         o.id=ObjectsID;
         exception
         when NO_DATA_FOUND then
         null;
end;
end if;

--если здания
if ObjectType=3 then
begin
   begin
   select
      b.levelname
      into result -- если есть наименование - отправляем в результат
      from
      sm.buildings b
      where
      b.objects_id=ObjectsID;
   exception
          when NO_DATA_FOUND then
          null;
   end;
   if result is null then -- если у объекта нет наименования, то...
    begin
     -- определяем тип строения
      select
        b.buildtypes_id into b_type
        from sm.buildings b
      where
        b.objects_id=ObjectsID;

      -- определяем название типа строения
      select
        bt.name into b_type_name
        from sm.buildings b
        join buildtypes bt on b.buildtypes_id = bt.id
      where
        b.objects_id=ObjectsID;

     -- расклады для разных типов
     if b_type in (523,322,381,553,552,570) then
       result := 'Нежилое помещение';
     end if;
     if b_type in (41,401,547) then
       result := b_type_name || ' - ' || GetPurposeByMoveTypeID(ObjectsID,1);
     end if;

    end;
    end if;
end;
end if;

--если незавершенное
if ObjectType=4 then
begin
   select
         u.name
         into Result
         from
         sm.unconstr u
         where
         u.objects_id=ObjectsID;
         exception
         when NO_DATA_FOUND then
         null;
end;
end if;

--если инженерка
if ObjectType=5 then
begin
   select
         e.name
         into Result
         from
         sm.enginf e
         where
         e.objects_id=ObjectsID;
         exception
         when NO_DATA_FOUND then
         null;
end;
end if;

--если земля
if ObjectType=7 then Result := 'Земельный участок';
end if;

return(Result);
end GetObjectCommonName;
/
grant execute on SM.GETOBJECTCOMMONNAME to SM_ALLUSERS;
grant execute on SM.GETOBJECTCOMMONNAME to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJECTCOMMONSQUARE
prompt =======================================
prompt
create or replace function sm.GetObjectCommonSquare(Flag in char, ObjectsID in number) return number is
Result number(27,2);
ObjectType number;
B_Type number;
b_name varchar2(1000);
b_type_name varchar2(1000);
begin
/* 18.05.19 Чувыкин В.Э. 
Флаг 1 - ПЛОЩАДЬ объекта любого типа по алгоритму, определенному Быкаревой В.Н.
Флаг 2 - для инженерки выведет ДЛИНУ, остальным пусто
Флаг 3 - для инженерки выведет ГЛУБИНУ, остальным пусто
Флаг 4 - для инженерки выведет ОБЪЕМ, остальным пусто
 */

-- определение типа объекта
begin
   select
        o.objtypes_id
        into ObjectType
        from
        sm.objects o
        where
        o.id=ObjectsID;
        exception
        when NO_DATA_FOUND then
        null;
end;

-- если ищется ПЛОЩАДЬ
if flag = '1' then
        --если здания
        if ObjectType=3 then
           begin
           select
              b.square 
              into result 
              from
              sm.buildings b
              where
              b.objects_id=ObjectsID;    
           exception
                  when NO_DATA_FOUND then
                  null;      
           end;

        end if;

        --если незавершенное
        if ObjectType=4 then
        begin
           select
                 u.square
                 into Result
                 from
                 sm.unconstr u
                 where
                 u.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;

        --если инженерка
        if ObjectType=5 then
        begin
           select
                 e.square
                 into Result
                 from
                 sm.enginf e
                 where
                 e.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;

        --если земля
        if ObjectType=7 then
        begin
           select
                 g.square
                 into Result
                 from
                 sm.grounds g
                 where
                 g.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;
end if;

-- если ищется ДЛИНА
if flag = '2' then
          --если инженерка
        if ObjectType=5 then
        begin
           select
                 e.length
                 into Result
                 from
                 sm.enginf e
                 where
                 e.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;

end if;
-- если ищется ГЛУБИНА
if flag = '3' then
          --если инженерка
        if ObjectType=5 then
        begin
           select
                 e.depth
                 into Result
                 from
                 sm.enginf e
                 where
                 e.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;

end if;
-- если ищется ГЛУБИНА
if flag = '4' then
          --если инженерка
        if ObjectType=5 then
        begin
           select
                 e.volume
                 into Result
                 from
                 sm.enginf e
                 where
                 e.objects_id=ObjectsID;
                 exception
                 when NO_DATA_FOUND then
                 null;
        end;
        end if;

end if;

return(Result);
end GetObjectCommonSquare;
/
grant execute on SM.GETOBJECTCOMMONSQUARE to SM_ALLUSERS;
grant execute on SM.GETOBJECTCOMMONSQUARE to SM_ALL_SELECT;


prompt
prompt Creating function CHECK_KADASTRNO
prompt =================================
prompt
create or replace function sm.Check_kadastrno(AFlag in varchar2, AKadastrNo in varchar2) return varchar2 is
  Result varchar2(4000);
  Aobjects_id int;
  
  KadNoBase varchar2(200); 
  
  cnt int;

obj_type varchar2(200);
obj_name varchar2(500);
obj_purpose varchar2(200);
obj_addr varchar2(300);
obj_offaddr varchar2(500);
obj_square number;
obj_regdoc varchar2(300);

begin
  /* 18/05/2017 Твердохлеб: [792] - проверяет наличие кадастрового номера в программе*/
-- Чувыкин 17032021 - добавление в строку результата реестровый номер объекта, ";" идет разделителем для екселя
-- Чувыкин 24082021 - много новых полей
-- Чувыкин 24082021 - разделитель ^ вместо ; из-за того, что ; много где используют в названиях объектов  
  Result := ';Нет';  
  if (AKadastrNo is null) then
    return(Result);
  end if;
   
  -- найдем реестровый номер
  begin
    select o.id
      into Aobjects_id
      from sm.objects o
     where trim(o.kadastrno) = trim(AKadastrNo)
       and rownum < 2;
      
    exception
    when NO_DATA_FOUND then 
    begin
        select o.objects_id
          into Aobjects_id
          from sm.buildings o
         where trim(o.kadastrno) = trim(AKadastrNo)
           and rownum < 2;
          
        exception
        when NO_DATA_FOUND then 
        begin
          select o.objects_id
            into Aobjects_id
            from sm.unconstr o
           where trim(o.kadastrno) = trim(AKadastrNo)
             and rownum < 2;
            
          exception
          when NO_DATA_FOUND then 
          begin
            select o.objects_id
              into Aobjects_id
              from sm.grounds o
             where trim(o.kadastrno) = trim(AKadastrNo)
               and rownum < 2;
              
            exception
            when NO_DATA_FOUND then 
            begin
              select o.objects_id
                into Aobjects_id
                from sm.enginf o
               where trim(o.kadastrno) = trim(AKadastrNo)
                 and rownum < 2;
                
              exception
              when NO_DATA_FOUND then 
              begin
                null;
              end;
            end;
          end;
        end;
    end;
  end;


-- найдем тип объекта -- Чувыкин В.Э. 240921
select ot.name into obj_type
from objects o
join objtypes ot on o.objtypes_id = ot.id
where o.id = Aobjects_id;

-- найдем наименование объекта -- Чувыкин В.Э. 240921
select getobjectcommonname(1,Aobjects_id) into obj_name from dual;

-- найдем назначение объекта -- Чувыкин В.Э. 240921
select GetPurposeByMoveTypeID(Aobjects_id,1) into obj_purpose from dual;

-- найдем адрес объекта -- Чувыкин В.Э. 240921
-- изменил на вывод адреса с "дополнением" -- Чувыкин В.Э. 020322
select ExpandAddr/*_as*/(o.address_id) into obj_addr
from objects o
where o.id = Aobjects_id;

-- найдем официальный адрес объекта -- Чувыкин В.Э. 240921
select Objects.Official_Addr into obj_offaddr from objects where objects.id = Aobjects_id;

-- найдем площадь объекта -- Чувыкин В.Э. 240921
select getobjectcommonsquare(1,Aobjects_id) into obj_square from dual;

-- найдем «Основной документ рег. права (собственность)» объекта -- Чувыкин В.Э. 240921
select ExpandDoc(sm.GetDocCertificateByMoveID(sm.GetPositionMoveID(Aobjects_id,1))) into obj_regdoc from dual;

  -- найдем кадастровый номер участка под объектом --Чувыкин В.Э. 170721
  begin
    select o.id
      into Aobjects_id
      from sm.objects o
     where trim(o.kadastrno) = trim(AKadastrNo)
       and rownum < 2;
      
    exception
    when NO_DATA_FOUND then 
    begin
        select b.kadastrno_base
          into KadNoBase
          from sm.buildings b
         where trim(b.kadastrno) = trim(AKadastrNo)
           and rownum < 2;
          
        exception
        when NO_DATA_FOUND then 
        begin
          select u.kadastrno_base
            into KadNoBase
            from sm.unconstr u
           where trim(u.kadastrno) = trim(AKadastrNo)
             and rownum < 2;
            
          /*exception
          when NO_DATA_FOUND then 
          begin
            select g.objects_id
              into Aobjects_id
              from sm.grounds g
             where trim(g.kadastrno) = trim(AKadastrNo)
               and rownum < 2;*/
              
            exception
            when NO_DATA_FOUND then 
            begin
              select e.kadastrno_base
                into KadNoBase
                from sm.enginf e
               where trim(e.kadastrno) = trim(AKadastrNo)
                 and rownum < 2;
                
              exception
              when NO_DATA_FOUND then 
              begin
                null;
              end;
            end;
          --end;
        end;
    end;
  end;





  cnt := 0;  
  if (Aobjects_id is not null and AFlag = '1') then
    select count(*)
     into cnt
     from sm.objects o
     join sm.moveitems mi on mi.object_id = o.id
     join sm.moveperiods mp on mp.id = mi.moveperiod_id
     join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 1 -- собственность
    where mp.sincedate <= sysdate
      and (mp.enddate >= sysdate or mp.enddate IS NULL)
      and o.id = Aobjects_id
      and mv.client_id = 5100;  
    
    /*if (cnt = 0) then
       Result := KadNoBase || ';' || Aobjects_id || ';' || obj_type || ';' || obj_name || ';' || obj_purpose || ';' || obj_addr || ';' || obj_offaddr || ';' || obj_square || ';' || obj_regdoc || ';' || 'Да,Не МО';    
    else
       Result := KadNoBase || ';' || Aobjects_id || ';' || obj_type || ';' || obj_name || ';' || obj_purpose || ';' || obj_addr || ';' || obj_offaddr || ';' || obj_square || ';' || obj_regdoc || ';' || 'Да,МО';  
    end if;  
  end if; */

    if (cnt = 0) then
       Result := KadNoBase || '^' || Aobjects_id || '^' || obj_type || '^' || obj_name || '^' || obj_purpose || '^' || obj_addr || '^' || obj_offaddr || '^' || obj_square || '^' || obj_regdoc || '^' || 'Да,Не МО';    
    else
       Result := KadNoBase || '^' || Aobjects_id || '^' || obj_type || '^' || obj_name || '^' || obj_purpose || '^' || obj_addr || '^' || obj_offaddr || '^' || obj_square || '^' || obj_regdoc || '^' || 'Да,МО';  
    end if;  
  end if; 

  
  if (Aobjects_id is not null and AFlag = '2') then
    select c.name
     into Result
     from sm.objects o
     join sm.moveitems mi on mi.object_id = o.id
     join sm.moveperiods mp on mp.id = mi.moveperiod_id
     join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 -- баланс
     join clients c on c.id = mv.client_id
    where mp.sincedate <= sysdate
      and (mp.enddate >= sysdate or mp.enddate IS NULL)
      and o.id = Aobjects_id; 
      
    /*if (Result is null) then
       Result := KadNoBase || ';' || Aobjects_id || ';' || obj_type || ';' || obj_name || ';' || obj_purpose || ';' || obj_addr || ';' || obj_offaddr || ';' || obj_square || ';' || obj_regdoc || ';' || 'Нет';  
    else
       Result := 'Баланс' || ' : ' || Result;
    end if;    
  end if;*/

    if (Result is null) then
       Result := KadNoBase || '^' || Aobjects_id || '^' || obj_type || '^' || obj_name || '^' || obj_purpose || '^' || obj_addr || '^' || obj_offaddr || '^' || obj_square || '^' || obj_regdoc || '^' || 'Нет';  
    else
       Result := 'Баланс' || ' : ' || Result;
    end if;    
  end if;
  
  if (Result = 'Нет' and Aobjects_id is not null and AFlag = '2') then
    Result := '';
    select o.id
     into Result
     from sm.objects o
     join sm.moveitems mi on mi.object_id = o.id
     join sm.moveperiods mp on mp.id = mi.moveperiod_id
     join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 10 -- Казна
    where mp.sincedate <= sysdate
      and (mp.enddate >= sysdate or mp.enddate IS NULL)
      and o.id = Aobjects_id; 
      
    /*if (Result is null) then
       Result := KadNoBase || ';' || Aobjects_id || ';' || obj_type || ';' || obj_name || ';' || obj_purpose || ';' || obj_addr || ';' || obj_offaddr || ';' || obj_square || ';' || obj_regdoc || ';' || 'Нет';  
    else
       Result := 'Казна';
    end if;    
  end if;*/

    if (Result is null) then
       Result := KadNoBase || '^' || Aobjects_id || '^' || obj_type || '^' || obj_name || '^' || obj_purpose || '^' || obj_addr || '^' || obj_offaddr || '^' || obj_square || '^' || obj_regdoc || '^' || 'Нет';  
    else
       Result := 'Казна';
    end if;    
  end if;
    
  return(Result);
end Check_kadastrno;
/
grant execute on SM.CHECK_KADASTRNO to SM_ALLUSERS;


prompt
prompt Creating function CHECK_OBJ_MUNPROP
prompt ===================================
prompt
create or replace function sm.Check_Obj_MunProp(Flag in char, ObjectsID in number, ADate date) return varchar2 is
Res varchar2(1);
Client_id number;
begin
/* 21.09.19 Чувыкин В.Э. - функция определяет, был ли объект ObjectsID в муниципальной собственности на дату ADate: 1 - был, 0 - не был*/

-- определение client_id субъекта ОД Собственность
begin 
select 
getpositionclientidbydate(ObjectsID,1,Adate)
into Client_id
from dual;
exception
when NO_DATA_FOUND then
null;
end;

-- 5100 это МО г. Краснодар
if Client_id=5100 then res:=1; else res:=0; end if;

return(Res);
end Check_Obj_MunProp;
/
