prompt
prompt Creating function COPYCALCPRESETS
prompt =================================
prompt
create or replace function sm.CopyCalcPresets(V_NamePresets varchar2, N_PresetsID number)return number
as pragma autonomous_transaction;
CurOblPres sm.oblig_presets%rowtype;
CurPeriodPres sm.oblig_periodical_presets%rowtype;
begin
 if trim(upper(V_NamePresets))='OBLIG_PRESETS' then
    select o.*
    into CurOblPres
    from sm.oblig_presets o
    where o.id=N_PresetsID;

  select sm.seqoblig_presets.nextval into CurOblPres.Id from dual;

  CurOblPres.Name:=CurOblPres.Name||' (Копия)';
  insert into sm.oblig_presets values CurOblPres;
  commit;
  return CurOblPres.Id;
 end if;

if trim(upper(V_NamePresets))='OBLIG_PERIODICAL_PRESETS' then
    select o.*
    into CurPeriodPres
    from sm.oblig_periodical_presets o
    where o.id=N_PresetsID;

  select sm.seqoblig_periodical_presets.nextval into CurPeriodPres.Id from dual;

  CurPeriodPres.Name:=CurPeriodPres.Name||' (Копия)';
  insert into sm.oblig_periodical_presets values CurPeriodPres;
  commit;
  return CurPeriodPres.Id;
end if;

exception
 when others then raise_application_error('ORA-20101',sqlerrm);
 rollback;
 return -1;
end;
/
grant execute on SM.COPYCALCPRESETS to SM_ALLUSERS;
grant execute on SM.COPYCALCPRESETS to SM_ALL_SELECT;


prompt
prompt Creating function COPYOBJECT
prompt ============================
prompt
create or replace function sm.CopyObject(ObjID NUMBER) return NUMBER
as pragma autonomous_transaction;

CopObj SM.OBJECTS%ROWTYPE; --исходный объект
NewCopObj SM.OBJECTS%ROWTYPE; --новый объект
PropObj SM.PROPERTY%ROWTYPE; --прочее имущество
TrspObj SM.Transport%ROWTYPE; --транспорт
BldObj SM.Buildings%ROWTYPE; --здания
tmpBldObj SM.Buildings%ROWTYPE; --tmp для здания (вложенные эл-ты)
GrnObj SM.Grounds%RoWTYPE; -- земля
TmpGrnObj SM.Grounds%RoWTYPE; -- для вложенных участков

UnkObj SM.Unconstr%ROWTYPE;--незавершенное строительство
EngObj SM.Enginf%ROWTYPE;--объекты инженерных инфр.
OrgObj SM.Organisations%ROWTYPE;--организации
Cli sm.Clients%ROWTYPE;



oldBldID number;
newIDObj number;
tmpIDAdr integer;
tmpIDDocSet integer;
tmpIDObj integer;
tmpBaseGR SM.GROUNDS.BASEGROUND%TYPE;
tmpBaseBld SM.Buildings.BASEBUILDING%TYPE;
tmpID number;
tmpObjID number;

NewDSet NUMBER;
oldIDMovset number;
oldIDMovper number;

TYPE m_SmplTable IS TABLE OF NUMBER INDEX BY BINARY_INTEGER;
Tabl m_SmplTable;

--подчиненные элементы табл Grouns (земельные участки)
CURSOR get_INCLground (id_grnd sm.Grounds.id%TYPE) is
  select g.id
  from sm.grounds g
  where g.baseground=id_grnd;
                  --функция регистрирует (копирует) адрес
                  function regAddress(Address_ID sm.address.id%type, ShortStr char default 'N' ) return number
                  is
                  AdrObj SM.ADDRESS%ROWTYPE; --адрес
                  begin
                     select A.*
                     into AdrObj
                     from sm.ADDRESS A
                     where A.id=Address_ID;
                      if ShortStr='Y' then
                      AdrObj.House:='';
                      AdrObj.Streets_Id:='';
                      AdrObj.Townarea_Id:='';
                      AdrObj.Provincearea_Id:='';



                      end if;

                     SELECT SM.Seqaddress.NEXTVAL INTO AdrObj.Id from dual;
                     INSERT INTO SM.ADDRESS VALUES AdrObj;
                  return(AdrObj.Id);
                  exception
                  when others then dbms_output.put_line(SQLERRM); return(-1);
                  end;



                  --функция копирует пакет документов
                  function CopyDocSet(DocSet_id sm.docsets.id%type) return number
                  is
                  CURSOR get_docinset (v_Dset SM.DOCSETS.ID%TYPE) is
                    select dm.document_id, dm.docrole_id
                    from sm.docset_members dm
                    where dm.docset_id=v_Dset;
                  NewDSet number(27);
                  begin
                       SELECT SM.Seqdocsets.NEXTVAL INTO NewDSet from dual;
                       INSERT INTO SM.DOCSETS (ID)
                              VALUES (NewDSet);

                    --определяем список привязанных документов
                     FOR v_doc IN get_docinset(DocSet_id) LOOP
                            INSERT INTO SM.DOCSET_MEMBERS (
                            DOCSET_ID,
                            DOCUMENT_ID,
                            DOCROLE_ID)
                            values(
                            NewDSet,
                            v_doc.document_id,
                            v_doc.docrole_id);

                    END LOOP;
                  return(NewDSet);
                  exception
                  when others then dbms_output.put_line(SQLERRM); return(-1);
                  end;


                  --функция создает новую запись в табл. Objects аналогичную ObjID
                  function CreateNewObj(ObjID sm.objects.id%type) return NUMBER
                  is
                  CopObj SM.OBJECTS%ROWTYPE; --исходный объект
                  NewID Number;
                  IsContainer char(1);

                  BEGIN
                  select t.*
                  into CopObj
                  from sm.objects t
                  where t.id=ObjID;



                  --создаем новый пакет документов, аналогичного содержания
                   if CopObj.Docset_Id is not null then
                   NewID:=CopyDocSet(CopObj.Docset_Id);
                   if nvl(NewID, -1)<>-1 then CopObj.Docset_Id:=NewID;
                   else return(-1);
                   end if;
                   end if;
                   NewID:=null;


                   --создаем новую запись об адресе объекта

                   if CopObj.Address_Id is not null then
                      if CopObj.Objtypes_Id=3 then
                      select CONTAINER
                      into IsContainer
                      from sm.BuildTypes
                      where ID=(select b.buildtypes_id
                                from sm.buildings b
                                where b.objects_id=ObjID);

                      if IsContainer='Y' then
                      NewID:=regAddress(CopObj.Address_Id, 'Y');
                      else
                      NewID:=regAddress(CopObj.Address_Id);
                      end if;
                      else
                      NewID:=regAddress(CopObj.Address_Id, 'Y');
                      end if;
                   if nvl(NewID, -1)<>-1 then CopObj.Address_Id:=NewID;
                   else return(-1);
                   end if;
                   end if;

                  SELECT SM.Seqobjects.NEXTVAL INTO CopObj.Id from dual;
                  INSERT INTO sm.Objects VALUES CopObj;
                 return(CopObj.Id);
                 exception
                 when others then dbms_output.put_line(SQLERRM); return(-1);
                 end;


                  --функция копируем состояние объекта
                  function CopyObjStates(Obj_ID sm.objects.id%type, NewObj_ID sm.objects.id%type) return NUMBER
                  is
                  StatObj SM.STATES%ROWTYPE; --состояние объекта
                  NewID number(27);
                  begin
                      for i in (select t.id from sm.states t where t.objects_id=Obj_ID)
                      LOOP
                        select s.*
                        into StatObj
                        from sm.States s
                        where s.id=i.id;

                               StatObj.Objects_Id:=NewObj_ID;
                               --создаем новый пакет документов.
                               if StatObj.Documents_Id is not null then
                               NewID:=CopyDocSet(StatObj.Documents_Id);
                               if nvl(NewID, -1)<>-1 then StatObj.Documents_Id:=NewID;
                               else return(-1);
                               end if;
                               end if;

                         SELECT sm.seqstates.nextval INTO StatObj.Id FROM DUAL;
                         StatObj.Writedate:=sysdate;
                         StatObj.Munreport_Id:='';
                         INSERT INTO SM.STATES VALUES StatObj;
                       END LOOP;
                   return(1);
                   exception
                   when others then dbms_output.put_line(SQLERRM); return(-1);
                   end;

                   --копируем операции движения (только собственность и балансодержание)
                   function CopyMovSet(Obj_ID sm.objects.id%type, NewObj_ID sm.objects.id%type) return NUMBER
                   is
                   CURSOR get_movitems (id_per sm.moveperiods.id%TYPE) is
                    select m.id
                    from sm.moveitems m
                    where m.moveperiod_id=id_per;

                   CURSOR get_movperiod (id_mvset sm.movesets.id%TYPE) is
                    select p.id
                    from sm.moveperiods p
                    where p.moveset_id=id_mvset;

                   MovSetObj SM.Movesets%ROWTYPE;
                   MovPerObj SM.Moveperiods%ROWTYPE;
                   MovItmObj SM.Moveitems%RowTYPE;
                   NewID Number(27);
                   begin
                       for i in (select t.MoveSet_ID
                                from sm.movements t
                                where t.MoveType_ID in (1,2)
                                and t.objects_id=Obj_ID)
                       LOOP
                          select ms.*
                          into MovSetObj
                          from sm.movesets ms
                          where ms.id=i.moveset_id;

                          oldIDMovSet:=MovSetObj.Id;
                          if MovSetObj.Docset_Id is not null then
                          NewID:=CopyDocSet(MovSetObj.Docset_Id);
                          if nvl(NewID, -1)<>-1 then MovSetObj.Docset_Id:=NewID;
                          else return(-1);
                          end if;
                          end if;

                          --создаем движение
                          SELECT SM.Seqmovesets.NEXTVAL INTO MovSetObj.Id FROM DUAL;
                          INSERT INTO SM.MOVESETS VALUES MovSetObj;

                          --опеределяем периоды в операции движения
                          FOR v_per IN get_movperiod(oldIDMovSet)
                               LOOP
                               select t.*
                               into Movperobj
                               from sm.moveperiods t
                               where t.id=v_per.id;

                               Movperobj.Moveset_Id:=MovSetObj.Id;
                               Movperobj.Docset_Id:=MovSetObj.Docset_Id;
                               Movperobj.Writedate:=sysdate;
                               oldIDMovper:=MovPerObj.Id;
                               select sm.seqmoveperiods.nextval INTO Movperobj.Id FROM DUAL;
                               INSERT INTO sm.moveperiods VALUES Movperobj;

                                      FOR v_itm IN get_movitems(oldIDMovper) LOOP
                                      select i.*
                                      INTO MovItmObj
                                      FROM sm.moveitems i
                                      where i.id=v_itm.id;
                                      MovItmObj.Object_Id:=NewObj_ID;
                                      MovItmObj.Moveperiod_Id:=MovPerObj.Id;

                                      select sm.seqmoveitems.nextval into MovItmObj.Id from dual;
                                      INSERT INTO SM.Moveitems VALUES MovItmObj;


                                      END LOOP;

                          END LOOP;

                      END LOOP;

                  return(1);
                  EXCEPTION
                  WHEN OTHERS THEN dbms_output.put_line(SQLERRM); return(-1);
                  end;




BEGIN
--загружаем исходный объект
select t.*
into CopObj
from sm.objects t
where t.id=ObjID;
if (CopObj.Objtypes_Id=1) or
   (CopObj.Objtypes_Id=2) or
   (CopObj.Objtypes_Id=3) or
   (CopObj.Objtypes_Id=4) or
   (CopObj.Objtypes_Id=5) or
   (CopObj.Objtypes_Id=6) or
   (CopObj.Objtypes_Id=7)
then
-- создаем новый
newIDObj:=CreateNewObj(ObjID);
if newIDObj=-1 then return(-1);end if;

select t.*
into NewCopObj
from sm.objects t
where t.id=newIDObj;
--объекты

    --Прочее движимое имущество. табл PROPERTY
     if (CopObj.Objtypes_Id=1) then
           select p.*
           into PropObj
           from sm.Property p
           where p.objects_id=ObjID;

           SELECT SM.Seqproperty.NEXTVAL INTO PropObj.Id from dual;
           PropObj.Objects_Id:=newIDObj;
           INSERT INTO SM.Property VALUES PropObj;
     end if;

     --Транспортные средства. табл TRANSPORT
     if (CopObj.Objtypes_Id=2) then
           select tr.*
           into TrspObj
           from sm.transport tr
           where tr.objects_id=ObjID;

           SELECT SM.Seqtransport.NEXTVAL INTO TrspObj.Id from dual;
           TrspObj.Objects_Id:=newIDObj;
           INSERT INTO SM.Transport VALUES TrspObj;

     end if;


 --Здания и помещения. табл BUILDINGS
        if (CopObj.Objtypes_Id=3) then
           select bl.*
           into BldObj
           from sm.buildings bl
           where bl.objects_id=ObjID;
           oldBldID:=BldObj.id;

           --select CONTAINER into IsContainer from sm.BuildTypes where ID=
           SELECT SM.Seqbuildings.NEXTVAL INTO BldObj.Id from dual;
           BldObj.Objects_Id:=newIDObj;
           select sm.objects.address_id into BldObj.Address_Id from sm.objects where objects.id=newIDObj;
           tmpBaseBld:=BldObj.Basebuilding;
           INSERT INTO SM.Buildings VALUES BldObj;

               --tmpBldObj
               if tmpBaseBld is null then
               --копируем струтуру если она есть

               Tabl(oldBldID):=BldObj.Id;
               FOR v_bld in (SELECT b.basebuilding
                                FROM sm.buildings b
                                START WITH b.basebuilding=oldBldID
                                CONNECT BY PRIOR b.id = b.basebuilding
                                group by b.basebuilding
                                order by b.basebuilding
                                )
                                LOOP

                                 For v_tmpBld in (SELECT b.id, b.objects_id
                                                  FROM sm.buildings b
                                                  where b.basebuilding=v_bld.basebuilding
                                                  START WITH b.basebuilding=oldBldID
                                                  CONNECT BY PRIOR b.id = b.basebuilding
                                                  order by b.basebuilding)
                                 LOOP
                                      select b.*
                                      into tmpBldObj
                                      From sm.buildings b
                                      where b.id=v_tmpBld.Id;

                                      tmpObjID:=CreateNewObj(v_tmpBld.Objects_Id);
                                      if tmpObjID=-1  then return(-1); end if;
                                         tmpBldObj.Objects_Id:=tmpObjID;
                                         select o.address_id into tmpBldObj.Address_Id from sm.objects o where o.id=tmpObjID;
                                         tmpBldObj.Basebuilding:=Tabl(v_bld.basebuilding);
                                         select seqbuildings.nextval into tmpBldObj.Id from dual;
                                         Tabl(v_tmpBld.Id):=tmpBldObj.Id;
                                         INSERT INTO sm.buildings VALUES tmpBldObj;
                                      --копируем состояние объекта
                                      tmpID:=CopyObjStates(v_tmpBld.Objects_Id,tmpObjID);
                                      if tmpID=-1 then return(-1);end if;
                                      --копируем операции движения объекта.
                                      tmpID:=CopyMovSet(v_tmpBld.Objects_Id,tmpObjID);
                                      if tmpID=-1 then return(-1);end if;

                                 END LOOP;

                  END LOOP;
                  end if;

           end if;


 --Незавершенное строительство UNCONSTR
       if (CopObj.Objtypes_Id=4) then
           select uk.*
           into UnkObj
           from SM.UNCONSTR uk
           where uk.objects_id=ObjID;

           SELECT SM.Sequnconstr.NEXTVAL INTO UnkObj.Id from dual;
           UnkObj.Objects_Id:=newIDObj;
           select sm.objects.address_id into UnkObj.Address_Id from sm.objects where objects.id=newIDObj;
           INSERT INTO SM.Unconstr VALUES unkObj;

       end if;

        --Инженерная инфраструктура ENGINF
       if (CopObj.Objtypes_Id=5) then
           select en.*
           into EngObj
           from SM.Enginf en
           where en.objects_id=ObjID;

           SELECT SM.Seqenginf.NEXTVAL INTO EngObj.Id from dual;
           EngObj.Objects_Id:=newIDObj;
           select sm.objects.address_id into EngObj.Address_Id from sm.objects where objects.id=newIDObj;
           INSERT INTO SM.Enginf VALUES EngObj;

       end if;

        --Организации ORGANISATION
       if (CopObj.Objtypes_Id=6) then
           select org.*
           into OrgObj
           from SM.ORGANISATIONS org
           where org.objects_id=ObjID;

           select cl.*
           into Cli
           from SM.Clients cl
           where cl.id=OrgObj.Clients_Id;
           tmpIDAdr:=regAddress(Cli.Address_Id);
           if nvl(tmpIDAdr, -1)<>-1 then Cli.Address_Id:=tmpIDAdr;
           else return(-1); end if;
           tmpID:=CopyDocSet(Cli.Regdoc_Id);
           if tmpID=-1 then return(-1);end if;
           cli.regdoc_id:=tmpID;
           Select sm.seqclients.nextval into cli.id from dual;
           INSERT INTO SM.CLIENTS VALUES Cli;
           OrgObj.Clients_Id:=cli.id;

           SELECT SM.Seqorganisations.NEXTVAL INTO OrgObj.Id from dual;
           OrgObj.Objects_Id:=newIDObj;
           INSERT INTO SM.ORGANISATIONS VALUES OrgObj;

       end if;

          --Земля Grounds
       if (CopObj.Objtypes_Id=7) then
           select g.*
           into GrnObj
           from SM.Grounds g
           where g.objects_id=ObjID;

           tmpBaseGR:=GrnObj.Baseground;
           tmpID:=GrnObj.Id;
           SELECT SM.Seqgrounds.NEXTVAL INTO GrnObj.Id from dual;
           GrnObj.Objects_Id:=newIDObj;
           select sm.objects.address_id into GrnObj.Address_Id from sm.objects where objects.id=newIDObj;
           INSERT INTO SM.Grounds VALUES GrnObj;


                  --проверяем есть ли вложенные участки и копируем их
                  if tmpBaseGR is null then
                    FOR v_gr IN get_INCLground(tmpID) LOOP
                    select g.*
                    INTO tmpGrnObj
                    FROM sm.grounds g
                    where g.id=v_gr.id;
                    tmpID:=CreateNewObj(tmpGrnObj.Objects_Id);
                    if tmpID=-1 then  return(-1); end if;


                    select t.address_id, t.docset_id
                    into tmpIDAdr, tmpIDDocSet
                    from sm.objects t
                    where t.id=tmpID;
                    TmpGrnObj.Address_Id:=tmpIDAdr;
                    TmpGrnObj.Objects_Id:=tmpID;
                    TmpGrnObj.Baseground:=GrnObj.Id;
                    SELECT sm.seqgrounds.nextval INTO TmpGrnObj.Id FROM Dual;
                    INSERT INTO SM.Grounds VALUES TmpGrnObj;
                    --копируем состояние объекта
                    tmpID:=CopyObjStates(tmpGrnObj.Objects_Id,tmpID);
                    if tmpID=-1 then return(-1);end if;
                    --копируем операции движения объекта.
                    tmpID:=CopyMovSet(tmpGrnObj.Objects_Id,tmpID);
                    if tmpID=-1 then return(-1);end if;

                    END LOOP;
                  end if;


       end if;
--копируем состояния
tmpID:=CopyObjStates(ObjID,newIDObj);
if tmpID=-1 then return(-1);end if;
--копируем операции движения объекта.
tmpID:=CopyMovSet(ObjID,newIDObj);
if tmpID=-1 then return(-1);end if;
COMMIT;
return(newIDObj);
else return(0);
end if;
EXCEPTION
WHEN OTHERS THEN ROLLBACK; dbms_output.put_line(SQLERRM);
raise_application_error(-20101,SQLERRM);
return(-1);
end ;
/
grant execute on SM.COPYOBJECT to VBYKAREVA;
grant execute on SM.COPYOBJECT to VPANOV;


prompt
prompt Creating function CREATE_DOC2021_2
prompt ==================================
prompt
create or replace function sm.create_doc2021_2 (Flag in char,
                                       Ais_import char default '1',
                                       Doc_number VARCHAR2 DEFAULT '1',
                                       doc_date DATE default NULL,
                                       info varchar2 default NULL,
                                       Adoc_id number default NULL,
                                       date_start date default null,
                                       date_end date default null,
                                       doc_number2 varchar2 default null,
                                       doc_date2 date default null,
                                       info2 varchar2 default NULL,
                                       Adoctype_id varchar2 default NULL,
                                       Adoctype_id2 varchar2 default NULL,
                                       Adoc_id2 varchar2 default NULL)RETURN NUMBER is
Adocset_id number(27);
Adocument_id number(27);
begin
   /* 15/04/2015 Создает документ для импорта:
      1 - пакет
      2 - документ
   */

   -- создадим документ
   if (Flag = '1') then
     -- создадим пакет документов
     Adocset_id := NULL;
     insert into sm.docsets (id)
          values (sm.seqdocsets.nextval);
      select sm.seqdocsets.currval
        into Adocset_id
        from dual;
   end if;

   -- добавим документ в пакет
   if (Adoc_id is null) then
     begin
     insert into documents (id, docno, docdate, doctypes_id, docsubscr_id, startdate, needconditiondoc,
                            conditiondate, conditiondoc, explanation, executed, body, subscribed_by,
                            subscribe_purpose, moved_user, date_start, date_end, file_extention)
          values (sm.seqdocuments.nextval, COALESCE(Doc_number,'1'), COALESCE(doc_date,CAST('01.01.2017' as DATE)), Adoctype_id, null, doc_date, 'N', null, null, substr(coalesce(info, 'создан процедурой импорта'), 0, 500),
                 'Y', null, '', '', '', date_start, date_end,'');
    --  exception
     --    when others then
      --        raise_application_error(-20101, 'objects - ' || TO_CHAR(info));

     end;
     Adocument_id := NULL;
     select sm.seqdocuments.currval
       into Adocument_id
       from dual;
   end if;

   if (Adoc_id is not null) then
     Adocument_id := Adoc_id;
   end if;

   if (Flag = '1') then
     insert into sm.docset_members (docset_id, document_id, docrole_id)
          values (Adocset_id, Adocument_id, 1);
   end if;

   -- если есть второй документ
   if (Adoc_id2 is null) then
     if (doc_number2 is not null and doc_date2 is not null) then
       insert into documents (id, docno, docdate, doctypes_id, docsubscr_id, startdate, needconditiondoc,
                              conditiondate, conditiondoc, explanation, executed, body, subscribed_by,
                              subscribe_purpose, moved_user, date_start, date_end, file_extention)
            values (sm.seqdocuments.nextval, doc_number2, doc_date2, Adoctype_id2, null, doc_date2, 'N', null, null, substr(coalesce(info2,'создан процедурой импорта'), 500),
                   'Y', null, '', '', '', null, null,'');

       Adocument_id := NULL;
       select sm.seqdocuments.currval
         into Adocument_id
         from dual;

       if (Flag = '1') then
         insert into sm.docset_members (docset_id, document_id)
              values (Adocset_id, Adocument_id);
       end if;
     end if;
   end if;

   if (Flag = '1') then
     return(Adocset_id);
   end if;

   if (Flag = '2') then
     return(Adocument_id);
   end if;
end create_doc2021_2;
/

prompt
prompt Creating function CREATE_OD2021
prompt ===============================
prompt
create or replace function sm.create_od2021
(Flag in char,
Aclient_id in number,
Aobject_id in number,
Amovetype_id in number,
Adate_accepted in date,
info varchar2 default NULL,
Ais_import char default '1',
Doc_number VARCHAR2 DEFAULT '1',
doc_date DATE default '01.01.2015',
info2 varchar2 default NULL,
Doc_number2 VARCHAR2 DEFAULT NULL,
doc_date2 DATE default NULL,
od_date_end date default null,
Adoc_id number default null,
Adoc_id2 number default null,
Adoctype_id number default null,
Adoctype_id2 number default null,
ATRANSFERBASIS_ID number default null)return char is
  Adocset_id number(27);
  AMoveset_id number(27);
  Amoveperiods_id number(27);
begin
   /* 16/04/2015 Создает ОД на объект*/

   -- теперь примем данный объект в собственность владельца БД
   -- создадим документ операции
   adocset_id := NULL;
   adocset_id := create_doc2021_2('1', Ais_import, Doc_number, doc_date, info, Adoc_id, null, null, Doc_number2, doc_date2, info2, Adoctype_id, Adoctype_id2, Adoc_id2);

   -- создадим ОД
   insert into sm.movesets(id, movetype_id, client_id, docset_id, transferbasis_id)
        values (sm.seqmovesets.nextval, Amovetype_id, Aclient_id, adocset_id, /*-100*/ATRANSFERBASIS_ID);

   AMoveset_id := NULL;
   select sm.seqmovesets.currval
     into AMoveset_id
     from dual;

   -- создадим период ОД
   insert into sm.moveperiods (id, moveset_id, sincedate, enddate, docset_id)
        values (sm.seqmoveperiods.nextval, AMoveset_id, Adate_accepted, od_date_end, adocset_id);

   Amoveperiods_id := NULL;
   select sm.seqmoveperiods.currval
     into Amoveperiods_id
     from dual;

   -- вставим объект
   insert into sm.moveitems(id, object_id, moveperiod_id)
        values (sm.seqmoveitems.nextval, Aobject_id, Amoveperiods_id);
   return('1');
end create_od2021;
/

prompt
prompt Creating function DECODEMONTHYEAR
prompt =================================
prompt
create or replace function sm.DecodeMonthYear(DecodedDate IN DATE) return varchar2 is
  i integer;
  S varchar2(15);
  S1 varchar2(15);
begin
  i:=TO_NUMBER(TO_CHAR(DecodedDate,'MM'));  
  IF i=1 THEN
   S:='Январь';
  ELSIF i=2 THEN
   S:='Февраль';
  ELSIF i=3 THEN
   S:='Март';
  ELSIF i=4 THEN
   S:='Апрель';
  ELSIF i=5 THEN
   S:='Май';
  ELSIF i=6 THEN
   S:='Июнь';
  ELSIF i=7 THEN
   S:='Июль';
  ELSIF i=8 THEN
   S:='Август';
  ELSIF i=9 THEN
   S:='Сентябрь';
  ELSIF i=10 THEN
   S:='Октябрь';
  ELSIF i=11 THEN
   S:='Ноябрь';
  ELSIF i=12 THEN
   S:='Декабрь';
  END IF;
 
 S1:= RTRIM(TO_CHAR(DecodedDate,'YYYY'));

 return(RTRIM(S||' '||S1||'г')); 
end DecodeMonthYear;
/
grant execute on SM.DECODEMONTHYEAR to SM_ALLUSERS;
grant execute on SM.DECODEMONTHYEAR to SM_ALL_SELECT;


prompt
prompt Creating function DECODEPERIODICAL_AS
prompt =====================================
prompt
create or replace function sm.DecodePeriodical_AS(Per varchar2)
  return varchar2 is
  res varchar2(100);
  -- Разработал Андрей Владимирович Солопко
  -- 2006-02-01  
begin

  res := '';
  select t.description
    INTO res
    from sm.obl_periodtypes t
   where t.periodical = Per;
  res := res || ':';
  return(nvl(res, ''));

end DecodePeriodical_AS;
/
grant execute on SM.DECODEPERIODICAL_AS to SM_ALLUSERS;
grant execute on SM.DECODEPERIODICAL_AS to SM_ALL_SELECT;


prompt
prompt Creating function EXISTBODYDOC
prompt ==============================
prompt
create or replace function sm.ExistBodyDoc(DocID in number) return char is
  exist_body char(1);
  doc_body blob;

begin
  exist_body:='Y';
  doc_body:=empty_blob();

  select d.body
  into doc_body
  from sm.documents d
  where d.id=DocID;

  if doc_body is null then
      exist_body:='N';
  elsif dbms_lob.getlength(doc_body)=0 then
      exist_body:='N';
  end if;

  return exist_body;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN 'N';

end;
/
grant execute on SM.EXISTBODYDOC to SM_ALLUSERS;
grant execute on SM.EXISTBODYDOC to SM_ALL_SELECT;


prompt
prompt Creating function EXPANDADDRSPOSTCODE
prompt =====================================
prompt
CREATE OR REPLACE FUNCTION SM.EXPANDADDRSPOSTCODE(AddrID IN NUMBER, ShowTownArea IN NUMBER default 1) RETURN VARCHAR2 IS
--
-- by XSGROUP 01.11.2008
-- функция возвращает расширенное описание адреса с включением в это описание почтового индекса
-- Если ShowTownArea=1, то в строку описания включается почтовый индекс и информация о районе города, области и т.д. (почтовые реквизиты адреса)
-- Порядок вывода соответствует почтовым требованиям
--

 Region sm.regions.name%Type;
 PArea sm.provincearea.name%Type;
 TownName sm.townnames.name%Type;
 TArea	sm.townarea.name%Type;
 Street	sm.streets.name%Type;
 Quarter	sm.address.quarter%Type;
 House		sm.address.house%Type;
 House_char sm.address.house_char%Type;
 Tank		sm.address.tank%Type;
 Room		sm.address.room%Type;
 Appartment	sm.address.appartment%Type;
 Addon	sm.address.addon%Type;
 RES	varchar2(4000);
 HCC integer;
 POSTCODE sm.address.postcode%Type;
BEGIN
 SELECT A.Quarter,A.House,A.House_char,A.Tank,A.Appartment,A.Room,A.Addon, PA.Name, TA.Name, ST.Name, TN.Name, R.Name, A.POSTCODE
 INTO  Quarter,House,House_char,Tank,Appartment,Room,Addon, PArea, TArea, Street, TownName, Region, POSTCODE
 FROM sm.Address A, sm.ProvinceArea PA, sm.TownArea TA, sm.Streets ST, sm.Townnames TN, sm.Regions R
 WHERE
   A.ID in (select nvl(main_id,id) from sm.address where id = AddrID) and
   A.ProvinceArea_ID=PA.ID(+) and
   A.TOWNNAMES_ID=TN.ID(+) and
   A.TownArea_ID=TA.ID(+) and
   A.Streets_ID=ST.ID(+) and
   a.Regions_ID=r.Id(+);

 RES:='';


 IF NOT (STREET IS NULL) THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM(STREET) || ', ',1,4000);
 END IF;

 IF NOT (HOUSE IS NULL) THEN --01
  RES:=SUBSTR(RES || ' д.' || TO_CHAR(House)|| ', ',1,4000);

  IF NOT (HOUSE_CHAR IS NULL) THEN
    RES:=SUBSTR(RES,1,length(Res)-2);
    HCC:=ASCII(Substr(House_char,1,1));
    IF (HCC>47 and HCC<58) THEN
      RES:=SUBSTR(RES ||'/'|| RTRIM(House_char)|| ', ',1,4000);
    ELSE
      RES:=SUBSTR(RES || RTRIM(House_char)|| ', ',1,4000);
    END IF;
  END IF;

  IF NOT (TANK IS NULL) THEN
    RES:=SUBSTR(RES,1,length(Res)-2);
    RES:=SUBSTR(RES || ' корп.' || RTRIM(Tank) || ', ',1,4000);
  END IF;


 END IF; --01;



 IF NOT (APPARTMENT IS NULL) THEN
  RES:=SUBSTR(RES || ' кв.' || TO_CHAR(APPARTMENT) || ', ',1,4000);
 END IF;

 IF NOT (ROOM IS NULL) THEN
  RES:=SUBSTR(RES || ' помещ.' || TO_CHAR(ROOM) || ', ',1,4000);
 END IF;

 IF NOT (QUARTER IS NULL) THEN
   RES:=SUBSTR(RES || 'квартал '|| RTRIM(Quarter) || ', ' ,1,4000);
  END IF;


 IF ShowTownArea=1 THEN--02

  IF NOT (TAREA IS NULL) THEN
   RES:=SUBSTR( RES || RTRIM(TAREA) || ', ',1,4000);
  END IF;

  IF NOT (TownName IS NULL) THEN
   RES:=SUBSTR( RES || RTRIM(TownName) || ', ',1,4000);
  END IF;

  IF NOT (PAREA IS NULL) THEN
   RES:=SUBSTR(RES || RTRIM(PAREA) || ', ',1,4000);
  END IF;

  if not (Region is null) then
   Res:=SUBSTR( RES || RTRIM(Region) || ', ',1,4000);
  end if;

  Res:=SUBSTR( RES || 'Россия, ',1,254);

  if not (POSTCODE is null) then
    Res:=SUBSTR( RES || RTRIM(POSTCODE) || ', ',1,4000);
  end if;

 END IF;--02

 IF NOT (ADDON IS NULL) THEN
  RES:=SUBSTR(RES || RTRIM(ADDON) || ', ',1,4000);
 END IF;

 RES:=RTRIM(RES);

 RES:=SUBSTR(RES,1,length(Res)-1);

 RETURN RES;

END;
/
grant execute on SM.EXPANDADDRSPOSTCODE to SM_ALLUSERS;
grant execute on SM.EXPANDADDRSPOSTCODE to SM_ALL_SELECT;


