prompt
CREATE OR REPLACE FUNCTION SM.EXPANDADDR_AS(AddrID IN NUMBER, ShowTownArea IN NUMBER default 1) RETURN CHAR IS
i integer;
  -- Разработал Андрей Владимирович Солопко
  -- 2005-02-01
PArea VARCHAR2(200);

Region VARCHAR2(200); -- Чувыкин 22.04.2021 - добавил вывод Субъекта Федерации, если таковой заполнен

TownName VARCHAR2(200);
TArea	VARCHAR2(200);
Street VARCHAR2(200);
TYPESTREET VARCHAR2(200);
Quarter	varchar2(200);
--House		INTEGER;
House		VARCHAR2(30);
House_char VARCHAR2(200);
Tank		VARCHAR2(200);
--Room		INTEGER;
Room		VARCHAR2(20);
--Appartment	INTEGER;
Appartment	VARCHAR2(20);
Addon	VARCHAR2(1100);--Чувыкин 20.12.17 увеличил с 700 до 1000, потом до 1100
--RES	varchar2(254);
RES	varchar2(500);
BTILITER VARCHAR2(80);
BEGIN
 SELECT A.Quarter,A.House,A.House_char,A.Tank,A.Appartment,A.Room,A.BTILITER,A.Addon, PA.Name, TA.Name, ST.Name, TN.Name, ST.TYPESTREET, r.name
 INTO  Quarter,House,House_char,Tank,Appartment,Room,BTILITER,Addon, PArea, TArea, Street, TownName, TYPESTREET, region
 FROM sm.Address A, sm.ProvinceArea PA, sm.TownArea TA, sm.Streets ST, sm.Townnames TN, sm.regions r
 WHERE
   A.ID in (select nvl(main_id,id) from sm.address where id = AddrID) and
   A.ProvinceArea_ID=PA.ID(+) and
   A.TOWNNAMES_ID=TN.ID(+) and
   A.TownArea_ID=TA.ID(+) and
   
   A.Regions_Id=r.id(+) and
   
   A.Streets_ID=ST.ID(+);

 RES:='';


 IF NOT (STREET IS NULL) THEN
  RES:=SUBSTR(RTRIM(RES) || ' ' || TYPESTREET || '.'|| RTRIM(STREET) || ', ',1,500);
 END IF;

 IF NOT (HOUSE IS NULL) THEN --01
  RES:=SUBSTR(RES || ' д.' || TO_CHAR(House)|| ', ',1,500);

  IF NOT (HOUSE_CHAR IS NULL) THEN
    RES:=SUBSTR(RES,1,length(Res)-2);
    RES:=SUBSTR(RES ||'-'|| RTRIM(House_char)|| ', ',1,500);
  END IF;

  IF NOT (TANK IS NULL) THEN
    RES:=SUBSTR(RES,1,length(Res)-2);
    RES:=SUBSTR(RES || ' корп.' || RTRIM(Tank) || ', ',1,500);
  END IF;


 END IF; --01;



 IF NOT (APPARTMENT IS NULL) THEN
  RES:=SUBSTR(RES || ' кв.' || TO_CHAR(APPARTMENT) || ', ',1,500);
 END IF;

-- IF NOT (ROOM IS NULL) THEN
--  RES:=SUBSTR(RES || ' помещ.' || TO_CHAR(ROOM) || ', ',1,500);
-- END IF;

--IF NOT (BTILITER IS NULL) THEN
--  RES:=SUBSTR(RES || ' лит.' || BTILITER || ', ',1,500);
-- END IF;

 IF ShowTownArea=1 THEN

  IF NOT (TAREA IS NULL) THEN
   RES:=' ' || SUBSTR( RTRIM(TAREA) || ' округ, ' || RES  ,1,500);
  END IF;

  IF NOT (TownName IS NULL) THEN
   RES:=SUBSTR( RTRIM(TownName) || ', ' || RES  ,1,500);
  END IF;

  IF NOT (PAREA IS NULL) THEN
   RES:=SUBSTR(RTRIM(PAREA) || ', ' || RES ,1,500);
  END IF;

  IF NOT (QUARTER IS NULL) THEN
   RES:=SUBSTR(RES || 'квартал '|| RTRIM(Quarter) || ', ' ,1,500);
  END IF;
 END IF;

-- IF NOT (ADDON IS NULL) THEN
--  RES:=SUBSTR(RES || RTRIM(ADDON) || ', ',1,500);
-- END IF;

  IF NOT (Region IS NULL) THEN
   RES:=SUBSTR(RTRIM(Region) || ', ' || RES ,1,500);
  END IF;


 RES:=RTRIM(RES);

 RES:=SUBSTR(RES,1,length(Res)-1);

 RETURN RES;

END;
/
grant execute on SM.EXPANDADDR_AS to SM_ALLUSERS;
grant execute on SM.EXPANDADDR_AS to SM_ALL_SELECT;


