prompt Creating function EXPANDDOCNOTPODP
prompt ==================================
prompt
create or replace function sm.ExpandDocNotPodp(DocID number) return varchar2 is
--
-- by XSGROUP 02.11.2008
-- Функция расшифровывает название документа по его номеру, без указания органа подписания
--

 res varchar2(4000);
 DocType varchar2(2000);
 DocNo varchar2(1000);
 DocDate varchar2(600);
 DocSubscrs varchar2(1000);
 KUMI_ID integer;
begin
-- ид текущего распорядителя
 KUMI_ID := sm.multiowning_pkg.GetCurrentOwnerID;
-- Выбираем органы подписания документа в одну строку
 Docsubscrs:='';
 for xx in(select
             decode(Clients.Id, KUMI_ID, 0, 1) as PR,
             RTRIM(Clients.Name) As ClientName
           from
             Documents,
             Doc_Subscribers,
             Clients
           where
             Doc_Subscribers.Document_Id=Documents.Id and
             Clients.ID(+)=Doc_Subscribers.Client_Id and
             Documents.ID=DocID
           order by PR DESC)
 loop
   if LENGTH(Docsubscrs) != 0 then
     --Ограничение на размер переменной (Molokovskikh S.V. 10.09.2014)
     if (LENGTH(Docsubscrs)+2+LENGTH(RTRIM(xx.ClientName))) < 1000 then
           Docsubscrs:=DocSubscrs || ', ' || RTRIM(xx.ClientName);   
     end if;
   else
     Docsubscrs:=RTRIM(xx.ClientName);
   end if;
 end loop;

-- Выбираем тип документа, номер и дату
 select
  RTRIM(DocTypes.NAME), ' №' ||
  RTRIM(Documents.Docno), ' от '||
  Documents.Docdate
 INTO
  DocType,
  DocNo,
  DocDate
 from
  Documents,
  DocTypes
 where
  DocTypes.ID=Documents.Doctypes_Id and
  Documents.ID=DocID;

-- Объединяем внутренние переменные в результат
  if LENGTH(Docsubscrs) != 0 then
    Docdate:= Docdate; -- || ' - ' || Docsubscrs;
  end if;

  res:=DocType;
  if DocNo != ' №?' then
   res:= res || DocNo;
  end if;
  res:=res || DocDate;

  return(nvl(res,''));

end;
/
grant execute on SM.EXPANDDOCNOTPODP to SM_ALLUSERS;
grant execute on SM.EXPANDDOCNOTPODP to SM_ALL_SELECT;


prompt
prompt Creating function EXPANDDOCSUBSCRS
prompt ==================================
prompt
create or replace function sm.ExpandDocSubscrs(DocID number) return varchar2 is
-- Функция расшифровывает органы подписания документа по его номеру
 DocSubscrs varchar2(500); 
 KUMI_ID integer;
begin
-- ид текущего распорядителя
 KUMI_ID := sm.multiowning_pkg.GetCurrentOwnerID;
-- Выбираем органы подписания документа в одну строку
 Docsubscrs:='';
 for xx in(select 
             decode(Clients.Id, KUMI_ID, 0, 1) as PR,
             RTRIM(Clients.Name) As ClientName
           from
             Documents,
             Doc_Subscribers,
             Clients
           where
             Doc_Subscribers.Document_Id=Documents.Id and
             Clients.ID(+)=Doc_Subscribers.Client_Id and
             Documents.ID=DocID
           order by PR DESC) 
 loop
   if LENGTH(Docsubscrs) != 0 then 
     Docsubscrs:=DocSubscrs || ', ' || RTRIM(xx.ClientName);
   else
     Docsubscrs:=RTRIM(xx.ClientName);
   end if;
 end loop;      

 return(nvl(Docsubscrs,''));
  
end;
/
