prompt
create or replace function sm.ExpandDoc_AS(DocID number) return varchar2 is
-- Функция сообщет дату окончания действия документа -Чувыкин
-- Разработал Андрей Владимирович Солопко - и назвал и описал хрен знает как                      
 res varchar2(800); 
 DocType varchar2(100);
 DocNo varchar2(100);
 DocDate date;
 DocSubscrs varchar2(500); 
begin
-- Выбираем тип документа, номер и дату
 select
  Documents.date_end
 INTO
  DocDate
 from
  Documents
 where
  Documents.ID=DocID;

-- Объединяем внутренние переменные в результат  
  
  res:= TO_CHAR(DocDate, 'DD.MM.YYYY');
   
  return(nvl(res,''));
  
end;
/
