prompt Creating function EXTRACTDOC
prompt ============================
prompt
create or replace function sm.EXTRACTDOC(ADocSet_ID NUMBER, ADocRole_ID NUMBER default 1 ) return varchar2 is
  Result varchar2(300);
-- функция извлекает документ с ролью ADocrole_ID  из  доксета с ID=ADocset_ID
-- по умолчанию и  звлекается главный документ

  DOCID number;
begin
  Result:='';
  DOCID:=0;
  for xxx in(select  docm.document_id ID
            from
              sm.docset_members docm
            where
              docm.docset_id=ADocSet_ID and
              docm.docrole_id=nvl(ADocRole_ID,1))
  loop
    DOCID:=xxx.ID;
  end loop;
    if nvl(DOCID,0)<>0 then
      Result:=sm.expanddoc(DOCID);
    end if;
  return(Result);
end EXTRACTDOC;
/
grant execute on SM.EXTRACTDOC to SM_ALL_SELECT;


