-- Разработал Андрей Владимирович Солопко  
-- 2005-02-01
begin
  Result:= substr(fio,instr(fio,' ')+1,1)||'.'||substr(fio,instr(fio,' ',1,2)+1,1)||'.'||substr(fio,1,instr(fio,' ')-1);  
  return(Result);
end FIO_AS;
