prompt
prompt Creating function GENERATEDATE
prompt ==============================
prompt
create or replace function sm.GenerateDate(num_x IN NUMBER, IntervalType IN NUMBER, START_DATE IN DATE) RETURN DATE IS
/*
 NUM_X - числа из таблицы num_x
 IntervalType - тип последовательности перебора дат
  1 - по годам
  2 - по кварталам
  3 - по месяцам
  4 - по неделям
  5 - по дням
 START_DATE - стартовая дата
  стартовая дата выравнивается в зависимости от типа последовательности 
*/
 S_DATE DATE;
begin
 S_DATE:=null;
 
 if IntervalType=1 then
  S_DATE:=TRUNC(START_DATE,'Y');
  S_DATE:=ADD_MONTHS(S_DATE,12*num_x);
 elsif IntervalType=2 then
  S_DATE:=TRUNC(START_DATE,'Q');
  S_DATE:=ADD_MONTHS(S_DATE,3*num_x);
 elsif IntervalType=3 then
  S_DATE:=TRUNC(START_DATE,'MM');
  S_DATE:=ADD_MONTHS(S_DATE,1*num_x);
 elsif IntervalType=4 then
  S_DATE:=TRUNC(START_DATE,'D');
  S_DATE:=S_DATE+7*num_x;
 elsif IntervalType=5 then
  S_DATE:=TRUNC(START_DATE,'DD');
  S_DATE:=S_DATE+num_x;
 end if;
 
 return (S_DATE);
 
end;
/
grant execute on SM.GENERATEDATE to SM_ALLUSERS;
grant execute on SM.GENERATEDATE to SM_ALL_SELECT;


