prompt Creating function GETALLPAYMENTSINFO
prompt ====================================
prompt
create or replace function sm.GetAllPaymentsInfo(OBLID in Number) return varchar2 is
  Result varchar2(4000);
------------------------------------------------------------------------------------
-- функция возвращает информацию для заголовка окна свода рассчётов по обязательству
-- by XSGROUP 29.03.2004
------------------------------------------------------------------------------------
  cnt  number;
  MSID number;
  OTID number;
  OblTypeName varchar2(200);
  ClientName  varchar2(200);
  DocDescr    varchar2(200);
begin

  Result:=null;

  select count(*) into cnt
    from sm.obligations
   where id=OBLID;

  if cnt<>0 then

    select obl.moveset_id,
           obl.obligationtype_id,
           ot.name,
           cl.name
      into MSID, OTID, OblTypeName, ClientName
      from sm.Obligations obl,
           sm.Obligationtype ot,
           sm.Movesets ms,
           sm.Clients cl
     where obl.id=OBLID
       and ot.id=obl.obligationtype_id
       and ms.id=obl.moveset_id
       and cl.id=ms.client_id;

    select sm.Expanddoc(dsm.document_id) into DocDescr
      from sm.Docset_Members dsm,
           sm.moveperiods mp
     where dsm.docrole_id=1
       and dsm.docset_id=mp.docset_id
       and mp.sincedate=(select max(mmp.sincedate)
                           from sm.moveperiods mmp
                          where mmp.moveset_id=mp.moveset_id)
       and mp.moveset_id=MSID;

    Result:='Расчеты по обязательству - '||rtrim(ltrim(ClientName));

    if DocDescr is not null then
      Result:=Result||' - '||rtrim(ltrim(DocDescr));
    end if;

  end if;
  return(Result);

end GetAllPaymentsInfo;
/
grant execute on SM.GETALLPAYMENTSINFO to SM_ALLUSERS;
grant execute on SM.GETALLPAYMENTSINFO to SM_ALL_SELECT;


