prompt Creating function GETALLPAYMENTSORD
prompt ===================================
prompt
create or replace function sm.GetAllPaymentsORD(ADocID in Number) return varchar2 is
------------------------------------------------------------------------------------  
-- by XSGROUP 07.08.2009
-- функция возвращает строку, задающую порядок вывода (сортировки)
-- платежей и дополнительных начислений
-- в окне свода расчётов по обязательству,
-- в случае, если они приходятся на одну дату
--
-- ADocID - ID документа - основания платежа или начисления
------------------------------------------------------------------------------------
  Result varchar2(4000);
  ADocNo sm.documents.docno%type;
  ADocDate varchar2(40);
  TotalLength number;
begin

  Result:=null;
  
  begin
    select
      trim(DOCNO),
      DOCNO,
      to_char(DOCDATE)
    into
      Result,
      ADocNo,
      ADocDate  
    from
      sm.documents doc
    where
      doc.id=ADocID;    
    exception
      when others then 
        null;
  end; 
  
  if Result is not null then
    Result:=Result||ADocdate;
    TotalLength:=length(ADocNo||ADocDate);
    Result:=LPAD(Result,TotalLength,'0');
  end if; 

  return(Result);
  
end;
/
grant execute on SM.GETALLPAYMENTSORD to SM_ALLUSERS;
grant execute on SM.GETALLPAYMENTSORD to SM_ALL_SELECT;


