prompt Creating function GETALLUSING_AS
prompt ================================
prompt
create or replace function sm.GETALLUSING_AS(MoveItemID NUMBER) return varchar2 is
  res varchar2(1000);
-- Разработал Андрей Владимирович Солопко (26-06-2006)
begin
  res:= '';
    for xxx in (select RTRIM(up.name) as upname
      from objectusing ou, moveitems mi, usingprupose up
      where ou.moveitem_id = mi.id and ou.usingpurpose = up.id and
      --ou.aux_sq = 'N' and
      ou.purp_area = 1 and
      ou.moveitem_id = MoveItemID
      group by up.name, ou.usingpurpose)
      loop
        if LENGTH(res) != 0 then 
          res:=res || ', ' || RTRIM(xxx.upname);
        else
          res:=RTRIM(xxx.upname);
        end if;
      end loop;
  return(nvl(Res,''));
end;
/
grant execute on SM.GETALLUSING_AS to SM_ALLUSERS;
grant execute on SM.GETALLUSING_AS to SM_ALL_SELECT;


prompt
prompt Creating function GETALLUSING_FULL_AS
prompt =====================================
prompt
create or replace function sm.GETALLUSING_FULL_AS(MovePeriodID NUMBER, ObjectID NUMBER) return varchar2 is
  res varchar2(5000);
--================================================================
--(c) Солопко Андрей Владимирович, 27.06.2008. Все права защищены.
-- Назначение основной/вспомогательной площади
--================================================================  
begin
  res:= '';
    for xxx in (
select
  mi.moveperiod_id mp_id,
  mi.object_id obj_id,
  pa.name pa_name,
  ou.square ou_square,
  sm.GETALLUSING_AS(mi.id) usng
from
  sm.moveitems mi,
  sm.objectusing ou,
  sm.purp_area pa
where
  mi.moveperiod_id = MovePeriodID and
  mi.object_id = ObjectID and
  mi.id = ou.moveitem_id and
  pa.id = ou.purp_area
order by
  pa.name DESC
      )
      loop
        if LENGTH(res) != 0 then 
          res:= res || '; ' || RTRIM(xxx.pa_name) || ' - ' || RTRIM(xxx.ou_square) || 'кв.м. - ' || RTRIM(xxx.usng);
        else
          res:= res || RTRIM(xxx.pa_name) || ' - ' || RTRIM(xxx.ou_square) || 'кв.м. - ' || RTRIM(xxx.usng);
        end if;
      end loop;
  return(nvl(Res,''));
end;
/
