prompt Creating function GETARENDATORCATEGORY
prompt ======================================
prompt
create or replace function sm.GetArendatorCategory(ClientID in number) return varchar2 is
  ArCat varchar2(500);
  
  bsnsmn char(1);
begin
  --01112023 Чувыкин - выводит категорию арендатора по заданному л\с клиента
begin
--ArCat:='';
select ac.name
into ArCat
from organisations org
left join arendators_category ac
on ac.id = org.arend_cat
where org.clients_id = ClientID;

exception
  when no_data_found then null;
end;

ArCat:=coalesce(ArCat,'Физлицо');

if ArCat = 'Физлицо' then
  begin
    select pr.businessman into bsnsmn from privates pr where pr.clients_id = ClientID;
    if bsnsmn = 'Y' then ArCat := 'ИП'; end if;
  end;
  
end if;

return ArCat;
end;
/
