prompt
prompt Creating function GETBANKITEMSSTATE
prompt ===================================
prompt
create or replace function sm.GetBankItemsState(BanlkItemsID in number)
return number is
  state number(27);
  sumPayments number(27,2);
  sumBankItems number(27,2);
  
begin
  sumPayments := 0.0;
  sumBankItems := 0.0;
  state:=0;

  select sum(p.sum),min(bi.sum_pp)
  into sumPayments, sumBankItems
  from sm.BankItems bi, 
  sm.Payments p 
  where bi.ID=BanlkItemsID and p.BankItems_ID=bi.ID;

  if sumBankItems=sumPayments and sumBankItems!=0 then
      state:=1;
  elsif sumBankItems>sumPayments and sumBankItems!=0 then
      state:=0;
	else 
			state	:= -1;
  end if;  
    
  return(state);
  
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN 0;
    
end GetBankItemsState;
/
grant execute on SM.GETBANKITEMSSTATE to SM_ALLUSERS;
grant execute on SM.GETBANKITEMSSTATE to SM_ALL_SELECT;


prompt
prompt Creating function GETBUILDFIRSTUPPERMOVEID
prompt ==========================================
prompt
create or replace function sm.getbuildfirstuppermoveid(ObjID in number, MoveTypeID in number, CDATE in date) return number is
  Result number;
-- возвращает операцию движения задданного типа у первого верхнего объекта, где 
-- встретилась ОД такого типа на заданную дату

begin

-- сначала смотрим ОД у текущего объекта
  Result:=null;
  for yy in (select m.id
             from sm.movesets m,
                  sm.moveperiods p,
                  sm.moveitems i
             where 
                i.object_id=ObjID and
                i.moveperiod_id=p.id and
                m.movetype_id=MoveTypeID and
                p.moveset_id=m.id and
                p.sincedate<=CDATE and
                ((p.enddate is null) or (p.enddate>=CDATE))
             )
  loop
    Result:=yy.ID;
  end loop;

  if not Result is null then 
    Return(Result);
  end if;

-- если у текущего нету ОД заданного типа на дату, то смотрим вышестоящие
  for xx in (select *
             from sm.buildings b
             connect by b.id=prior b.basebuilding
             start with b.objects_id=ObjID)
  loop
    if ( (xx.exists_since is null) and (xx.exists_end is null) ) or
       ( (xx.exists_since is null) and (xx.exists_end>CDATE) ) or
       ( (xx.exists_since<CDATE) and (xx.exists_end is null) )
    then
      Result:=0;
      for yy in (select m.id
                 from sm.movesets m,
                      sm.moveperiods p,
                      sm.moveitems i
                 where 
                   i.object_id=xx.objects_id and 
                   i.moveperiod_id=p.id and
                   m.movetype_id=MoveTypeID and
                   p.moveset_id=m.id and
                   p.sincedate<=CDATE and
                     ((p.enddate is null) or (p.enddate>=CDATE))
                 )
      loop
        Result:=yy.ID;
      end loop;
        
      if Result<>0 then 
        Exit;
      end if;
      
    end if;

  end loop;
  
  if Result=0 then 
    Result:=null;
  end if;
    
  return(Result);
end getbuildfirstuppermoveid;
/
grant execute on SM.GETBUILDFIRSTUPPERMOVEID to PUBLIC;
grant execute on SM.GETBUILDFIRSTUPPERMOVEID to SM_ALLUSERS;
grant execute on SM.GETBUILDFIRSTUPPERMOVEID to SM_ALL_SELECT;


prompt
prompt Creating function GETBUILDFIRSTUPPERMOVEIDEX
prompt ============================================
prompt
create or replace function sm.GetBuildFirstUpperMoveIDEx(AObject_ID in number, AMoveType_ID in number, ACurDate in Date default SYSDATE) return number is
  Result number;
begin

  -- by XSGROUP 20.08.2005
  -- для зданий и помещений  с указанным ID объекта возвращает ID движения данного объекта
  -- для указанного типа движения
  -- если для данного объекта движение указанного вида отсутствует - происходит проверка наличия
  -- такого типа движения для объекта верхнего уровня
  -- если ни у одного из объектов верхнего уровня такого типа движения не будет найдено - вернёт -1

  for xx in (SELECT b.objects_id as ID
             FROM sm.Buildings b
             START WITH b.objects_id=AObject_ID
             CONNECT BY PRIOR b.basebuilding=b.id)
  loop
    begin
      select
        mi.ID
      into
        Result
      from
        sm.moveitems mi,
        sm.moveperiods mp,
        sm.movesets ms
      where
        ms.movetype_id=AMoveType_ID and
        mi.object_id=xx.ID and
        mp.id=mi.moveperiod_id and
        ms.id=mp.moveset_id and
        (mp.sincedate<=ACurDate and
        mp.enddate>=ACurDate or mp.enddate is null);

    exception
      when NO_DATA_FOUND then
        Result:=-1;
    end;
    if Result<>-1 then
      goto quit_;
    end if;
  end loop;
  <<quit_>>
  return(Result);
end GetBuildFirstUpperMoveIDEx;
/
grant execute on SM.GETBUILDFIRSTUPPERMOVEIDEX to SM_ALLUSERS;
grant execute on SM.GETBUILDFIRSTUPPERMOVEIDEX to SM_ALL_SELECT;


