prompt Creating function GETBUILDING_BL_AS
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION SM.GetBuilding_Bl_AS(ObjID IN NUMBER) RETURN varchar2 IS
--================================================================
--(c) Солопко Андрей Владимирович, 26.06.2008. Все права защищены.
-- Благоустройство объекта
--================================================================
BL_ELECTRIC VARCHAR2(200);
BL_WATER VARCHAR2(200);
BL_HOT VARCHAR2(200);
BL_PHONE VARCHAR2(200);
BL_DRAIN VARCHAR2(200);
BL_HWATER VARCHAR2(200);
BL_TV VARCHAR2(200);
BL_LIFT VARCHAR2(200);
BL_GARBAGEBIN VARCHAR2(200);
BL_GAZ VARCHAR2(200);
BL_VENT VARCHAR2(200);
K2 NUMBER(27,3);
RES	VARCHAR2(500);
BEGIN

 SELECT
t.BL_ELECTRIC,t.BL_WATER,t.BL_HOT,t.BL_PHONE,t.BL_DRAIN,t.BL_HWATER,t.BL_TV,t.BL_LIFT,t.BL_GARBAGEBIN,t.BL_GAZ,t.BL_VENT		
 INTO
BL_ELECTRIC,BL_WATER,BL_HOT,BL_PHONE,BL_DRAIN,BL_HWATER,BL_TV,BL_LIFT,BL_GARBAGEBIN,BL_GAZ,BL_VENT
 FROM buildings t
 WHERE
  (t.objects_id = ObjID);

 K2:= 1.4;
 IF NOT (BL_DRAIN = 'Y') THEN
   K2:= K2 - 0.1;
 END IF;
 IF NOT (BL_HOT = 'Y') THEN
   K2:= K2 - 0.1;
 END IF;
 IF NOT (BL_ELECTRIC = 'Y') THEN
   K2:= K2 - 0.1;
 END IF;
 IF NOT (BL_WATER = 'Y') THEN
   K2:= K2 - 0.1;
 END IF;
 IF NOT (BL_HWATER = 'Y') THEN
   K2:= K2 - 0.1;
 END IF;

 RES:= '';
 
 IF (BL_ELECTRIC = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Эл') || ', ',1,500);
 END IF;
 IF (BL_WATER = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Вода') || ', ',1,500);
 END IF;
 IF (BL_HOT = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Отоп') || ', ',1,500);
 END IF;
 IF (BL_PHONE = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Тлф') || ', ',1,500);
 END IF;
 IF (BL_DRAIN = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Кнл') || ', ',1,500);
 END IF;
 IF (BL_HWATER = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Гор.вод.') || ', ',1,500);
 END IF;
 IF (BL_TV = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('ТВ') || ', ',1,500);
 END IF;
 IF (BL_LIFT = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Лфт') || ', ',1,500);
 END IF;
 IF (BL_GARBAGEBIN = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Мпр') || ', ',1,500);
 END IF;
 IF (BL_GAZ = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Газ') || ', ',1,500);
 END IF;
 IF (BL_VENT = 'Y') THEN
  RES:=SUBSTR(RTRIM(RES) || RTRIM('Внт') || ', ',1,500);
 END IF;

 RES:= RTRIM(RES);
 
 RES:= SUBSTR(RES, 1, length(Res) - 1) || ' [K2=' || K2 || ']';

 RETURN RES;

END;
/
grant execute on SM.GETBUILDING_BL_AS to SM_ALLUSERS;
grant execute on SM.GETBUILDING_BL_AS to SM_ALL_SELECT;


