prompt
prompt Creating function GETBUILDING_SQ_AS
prompt ===================================
prompt
create or replace function sm.GETBUILDING_SQ_AS(MoveItemID NUMBER) return number is
  res number;
-- Разработал Андрей Владимирович Солопко (Andy Solo)
-- 2006-07-19
     allres number;
     mlev number;
begin
     allres:= 0;
     res:= 0;
     SELECT max(LEVEL) into mlev
     from sm.buildings b
     START WITH b.id=MoveItemID
     CONNECT BY PRIOR b.id=basebuilding;
     for r in (
         SELECT
               LEVEL,
               sum(b.square) sq
         from sm.buildings b
         START WITH b.id=MoveItemID
         CONNECT BY PRIOR b.id=basebuilding
         group by LEVEL
         order by LEVEL
         )
     loop
     begin
          if (mlev = 1) then
            allres:= r.sq;
          end if;
          if (mlev = 2) then
            res:= r.level;
            if (res = 1) then
               allres:= r.sq;
            END IF;
            if (res = 2) then        
               allres:= allres - r.sq;
            END IF;
          end if;
          if (mlev = 3) then
            res:= r.level;
            if (res = 1) then
               allres:= r.sq;
            END IF;
            if (res = 3) then        
               allres:= allres - r.sq;
            END IF;
          end if;
          if (mlev = 4) then
            res:= r.level;
            if (res = 1) then
               allres:= r.sq;
            END IF;
            if (res = 4) then        
               allres:= allres - r.sq;
            END IF;
          end if;
          if (mlev = 5) then
            res:= r.level;
            if (res = 1) then
               allres:= r.sq;
            END IF;
            if (res = 5) then        
               allres:= allres - r.sq;
            END IF;
          end if;
     end;
     end loop;
     res:= allres;
     return(nvl(res, 0));
end;
/
grant execute on SM.GETBUILDING_SQ_AS to SM_ALLUSERS;
grant execute on SM.GETBUILDING_SQ_AS to SM_ALL_SELECT;


