prompt
prompt Creating function GETBUILDMOVEORD
prompt =================================
prompt
create or replace function sm.GetBuildMoveORD(AMovementsID number) return number is
  Result number(27,0);

-- by XSGROUP 19.10.2012
--
-- Функция возвращает число, задающее очередность, в соответствии с которой
-- должна выводиться строка описания операции движения в списке движений, отображаемых в структуре здания
-- для конкретного помещения
--
-- AMoveTypeID - ID из таблицы sm.MoveType
--
begin

  Result:=100; -- если обработать не удалось - выводится будет в последнюю очередь

  -- сортировка по умолчанию
  begin
    select --+ FIRST_ROWS
      Decode(ms.movetype_id,1,1,2,2,8,3,3,4,6,5,7,6,9,7,10,8,11,9,4,10,5,11,ms.movetype_id)
    into
      Result
    from
       sm.movesets ms,
       sm.moveperiods mp,
       sm.moveitems mi
    where
       ms.id=mp.moveset_id and
       mp.id=mi.moveperiod_id and
       mi.id=AMovementsID and rownum=1;     
  exception
    when others then
      Result:=100;
  end;
 
  return(Result);
  
end;
/
grant execute on SM.GETBUILDMOVEORD to SM_ALLUSERS;
grant execute on SM.GETBUILDMOVEORD to SM_ALL_SELECT;


prompt
prompt Creating function GETBUILDNINGSCOUNT
prompt ====================================
prompt
create or replace function sm.GETBUILDNINGSCOUNT(StartBuilding in number, BuildType in number, CDATE in date) return number is
  Result number;
-- возвращает количесвтво объектов нижнего уровня заданного типа, начиная с заданного уровня/здания
-- на заданую дату
begin
  result:=0;
  for xx in (select *
             from sm.buildings b
             connect by prior b.id=b.basebuilding
             start with b.id=StartBuilding)
  loop
    if xx.buildtypes_id=Buildtype then
      if ( (xx.exists_since is null) and (xx.exists_end is null) ) or
         ( (xx.exists_since is null) and (xx.exists_end>CDATE) ) or
         ( (xx.exists_since<CDATE) and (xx.exists_end is null) )
      then
        Result:=Result+1;
      end if;
    end if;
  end loop;
    
  return(Result);
end GETBUILDNINGSCOUNT;
/
grant execute on SM.GETBUILDNINGSCOUNT to SM_ALL_SELECT;


prompt
prompt Creating function GETBUILDNINGSCOUNTCLIENTBYDATE
prompt ================================================
prompt
create or replace function sm.GETBUILDNINGSCOUNTCLIENTBYDATE(StartBuilding in number, BuildType in number,
  MoveTypeID in number, CDATE in date, ClientsID in number) return number is
  Result number;
-- возвращает количесвтво объектов нижнего уровня заданного типа, начиная с заданного уровня/здания
-- причем с ОД заданного типа MOVETYPE на заданную дату CDATE у заданного клиента ClientID
begin
  result:=0;
  for xx in (select *
             from sm.buildings b
             connect by prior b.id=b.basebuilding
             start with b.id=StartBuilding)
  loop
    if xx.buildtypes_id=Buildtype then
      if getpositionclientidbydate(xx.objects_id, MoveTypeID, CDATE)=ClientsID then
        Result:=Result+1;
      end if;
    end if;
  end loop;
    
  return(Result);
end GETBUILDNINGSCOUNTCLIENTBYDATE;
/
grant execute on SM.GETBUILDNINGSCOUNTCLIENTBYDATE to SM_ALL_SELECT;


