prompt
create or replace function sm.GETBUILDNINGSCOUNTNOTCLNBYDATE(StartBuilding in number, BuildType in number,
  MoveTypeID in number, CDATE in date, ClientsID in number) return number is
  Result number;
-- возвращает количесвтво объектов нижнего уровня заданного типа, начиная с заданного уровня/здания
-- причем с ОД заданного типа MOVETYPE на заданную дату CDATE НЕ у заданного клиента ClientsID
begin
  result:=0;
  for xx in (select *
             from sm.buildings b
             connect by prior b.id=b.basebuilding
             start with b.id=StartBuilding)
