prompt
create or replace function sm.GETBUILDNINGSQURE(StartBuilding in number, BuildType in number, CDATE in date) return number is
  Result number(27,2);
-- возвращает площадь объектов нижнего уровня заданного типа, начиная с заданного уровня/здания
-- на заданую дату
begin
  result:=0;
  for xx in (select *
             from sm.buildings b
             connect by prior b.id=b.basebuilding
             start with b.id=StartBuilding)
  loop
    if xx.buildtypes_id=Buildtype then
      if ( (xx.exists_since is null) and (xx.exists_end is null) ) or
         ( (xx.exists_since is null) and (xx.exists_end>CDATE) ) or
