prompt
prompt Creating function GETBUILDS_AS
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION SM.GetBUILDS_AS(par_objects_id IN NUMBER) RETURN CHAR IS
RES  varchar2(1000);
  -- Разработал Андрей Владимирович Солопко
  -- 2006-10-24
b_name VARCHAR2(100);
b_LEVELNAME VARCHAR2(200);
b_square number;
l_name VARCHAR2(100);

BEGIN

select
sm.buildtypes.name b_name,
sm.buildings.LEVELNAME b_LEVELNAME,
sm.buildings.square b_square,
sm.leasepurpose.name l_name
into
b_name, b_LEVELNAME, b_square, l_name
from
sm.objects,
sm.movesets,
sm.moveperiods,
sm.moveitems,
sm.leasepurpose,
sm.docset_members,
sm.transferbasis,
sm.buildings,
sm.buildtypes
where
sm.objects.objtypes_id=3 and
sm.buildings.objects_id=sm.objects.id and
sm.buildings.buildtypes_id=sm.buildtypes.id(+) and
sm.docset_members.docset_id=sm.movesets.docset_id and
sm.docset_members.docrole_id=1 and
sm.transferbasis.id(+)=sm.movesets.transferbasis_id and
sm.movesets.id=sm.getbuildfirstuppermoveid(sm.objects.id, 1, SYSDATE) and
sm.movesets.movetype_id=1 and
sm.moveperiods.moveset_id=sm.movesets.id and
sm.moveitems.moveperiod_id=sm.moveperiods.id and
moveitems.object_id=objects.id and
sm.moveitems.leasepurpose_id=sm.leasepurpose.id(+) and
movesets.client_id=5100 and
sm.objects.id=par_objects_id;

RES:='';

IF (b_LEVELNAME IS NOT NULL) THEN
  RES:=SUBSTR((b_name || ' - ' || b_LEVELNAME || ' (Площадь - ' || TO_CHAR(b_square) ||' кв.м.)'),1,1000);
ELSE
  RES:=SUBSTR((b_name || ' - ' || l_name || ' (Площадь - ' || TO_CHAR(b_square) ||' кв.м.)'),1,1000);
END IF;

RES:=RTRIM(RES);
RES:=SUBSTR(RES,1,length(Res));
RETURN RES;

END;
/
grant execute on SM.GETBUILDS_AS to SM_ALLUSERS;
grant execute on SM.GETBUILDS_AS to SM_ALL_SELECT;


