prompt
prompt Creating function GETCHILDINFO
prompt ==============================
prompt
create or replace function sm.GetChildInfo(Flag in char, Aobject_id in number, Amovetype_id in number) return varchar2 is
  Result varchar2(4000);
  document varchar2(1024);
begin
  /*14/11/2018 Твердохлеб: выводит по нужной операции движения информацию по потомкам*/
  /*
    Flag:
         1 - наименование контрагента, владельца
         2 - основной документ
  */
  Result := '';
  for qq in(              
             select b.objects_id
               from sm.Buildings b
              start with b.objects_id = Aobject_id
              connect by prior b.id  = b.basebuilding
           )
  loop
    if (Flag IN ('1', '2')) then
       -- теперь по объектам ищем нужную информацию
       for yy in(              
                  select ms.client_id,
                         c.name,
                         mp.docset_id
                    from sm.moveitems mi
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets ms on ms.id = mp.moveset_id
                    join sm.clients c on c.id = ms.client_id
                   where mi.object_id = qq.objects_id
                     and ms.movetype_id = Amovetype_id
                )
       loop
          -- теперь по объектам ищем нужную информацию
          if (Flag = '1') then
            if (Result is null) then
               Result := yy.name;
            else
              if (INSTR(Result,yy.name,1,1) in('','0')) then
               Result := Result || chr(13) || yy.name;
              end if;  
            end if;                       
          end if;
          
          -- если основной документ операции
          if (Flag = '2') then
            -- найдем его
            begin
              select sm.expanddoc(dm.document_id) doc
                into document
                from sm.docset_members dm
                join sm.documents d on d.id = dm.document_id
                where dm.docset_id = yy.docset_id
                  and dm.docrole_id = 1;
              exception
              when NO_DATA_FOUND then
               null;
            end;
            
            if (Result is null) then
               Result := document;
            else
              if (INSTR(Result,document,1,1) in('','0')) then
               Result := Result || chr(13) || document;
              end if;  
            end if;                       
          end if;  
       end loop;    
    end if;      
  end loop;
  
  return(Result);
end GetChildInfo;
/
grant execute on SM.GETCHILDINFO to SM_ALLUSERS;


prompt
prompt Creating function GETCHILDINFOBYDATE
prompt ====================================
prompt
create or replace function sm.GetChildInfoByDate(Flag in char, Aobject_id in number, Amovetype_id in number, ADate date) return varchar2 is
  Result varchar2(4000);
  document varchar2(1024);
  i number(27);
begin
  /*141219 Чувыкин  -- функция следует из GetChildInfo и GetChildInfo_New, но теперь с задаваемой датой акуальности*/
  /*
    Flag:
         1 - наименование контрагента, владельца
         2 - основной документ
         3 - площадь по договору
         4 - основание операции движения
  */
  Result := '';
  i:=1;

  for qq in(
             -- запрос выстраивает ветку иерархии от заданного в функцию объекта
             select b.objects_id
               from sm.Buildings b
              start with b.objects_id = Aobject_id
              connect by prior b.id  = b.basebuilding
           )
  loop
    if (Flag IN ('1', '2', '3', '4')) then
       -- теперь по объектам ищем нужную информацию
       for yy in(
                  -- запрос возвращает контрагента из ПОСЛЕДНЕГО НЕЗАКРЫТОГО ПЕРИОДА ОД БП или Аренда
                  select ms.client_id,
                         c.name,
                         mp.docset_id,
                         mi.square,

                         t.name as name_transferbasis

                    from sm.moveitems mi
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets ms on ms.id = mp.moveset_id
                    join sm.clients c on c.id = ms.client_id

                    join sm.transferbasis t on t.id = ms.transferbasis_id

                   where mi.object_id = qq.objects_id
                     and ms.movetype_id = Amovetype_id
                     and mp.sincedate <= Adate
                     and (mp.enddate >= Adate or mp.enddate is null)
                )
       loop
          -- теперь по объектам ищем нужную информацию

          -- сборка строки с именами контрагентов
          if (Flag = '1') then
            if (Result is null) then
               Result := i || '. ' || yy.name;
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || yy.name;
              end;
            end if;
          end if;

          -- если основной документ операции
          if (Flag = '2') then
            -- найдем его
            begin
              -- запрос находит основной документ в пакете документов
              select sm.expanddoc(dm.document_id) doc
                into document
                from sm.docset_members dm
                join sm.documents d on d.id = dm.document_id
                where dm.docset_id = yy.docset_id
                  and dm.docrole_id = 1;
              exception
              when NO_DATA_FOUND then
               null;
            end;
            -- сборка строки с документами
            if (Result is null) then
               Result := i || '. ' || document || ' ';
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || document || ' ';
              end;
            end if;
          end if;

          -- сборка строки с площадями
          if (Flag = '3') then
            if (Result is null) then
               Result := i || '. ' || yy.square || ' кв.м';
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || yy.square || ' кв.м';
              end;
            end if;
          end if;

          -- сборка строки с основаниями
          if (Flag = '4') then
            if (Result is null) then
               Result := i || '. ' || yy.name_transferbasis || ' ';
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || yy.name_transferbasis || ' ';
              end;
            end if;
          end if;



       end loop;
    end if;
  end loop;

  return(Result);
end GetChildInfoByDate;
/
grant execute on SM.GETCHILDINFOBYDATE to SM_ALLUSERS;


prompt
prompt Creating function GETCHILDINFO_NEW
prompt ==================================
prompt
create or replace function sm.GetChildInfo_new(Flag in char, Aobject_id in number, Amovetype_id in number) return varchar2 is
