                    join sm.clients c on c.id = ms.client_id
                    
                    join sm.transferbasis t on t.id = ms.transferbasis_id
                    
                   where mi.object_id = qq.objects_id
                     and ms.movetype_id = Amovetype_id
                     and mp.enddate is null -- нужен только последний незакрытый период
                )
       loop
          -- теперь по объектам ищем нужную информацию
          
          -- сборка строки с именами контрагентов 
          if (Flag = '1') then
            if (Result is null) then
               Result := i || '. ' || yy.name;
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || yy.name;               
              end;              
            end if;
          end if;

          -- если основной документ операции
          if (Flag = '2') then
            -- найдем его
            begin
              -- запрос находит основной документ в пакете документов
              select sm.expanddoc(dm.document_id) doc
                into document
                from sm.docset_members dm
                join sm.documents d on d.id = dm.document_id
                where dm.docset_id = yy.docset_id
                  and dm.docrole_id = 1;
              exception
              when NO_DATA_FOUND then
               null;
            end;
            -- сборка строки с документами
            if (Result is null) then
               Result := i || '. ' || document || ' ';
            else
              begin
               i:=i+1;
               Result := Result || chr(13) || i || '. ' || document || ' '; 
              end;
            end if;         
          end if;
          
          -- сборка строки с площадями
          if (Flag = '3') then
            if (Result is null) then               
               Result := i || '. ' || yy.square || ' кв.м';
            else
              begin
               i:=i+1;             
               Result := Result || chr(13) || i || '. ' || yy.square || ' кв.м';            
              end;
            end if;
          end if;
         
          -- сборка строки с основаниями
          if (Flag = '4') then
            if (Result is null) then               
               Result := i || '. ' || yy.name_transferbasis || ' ';
            else
              begin
               i:=i+1;             
               Result := Result || chr(13) || i || '. ' || yy.name_transferbasis || ' ';            
              end;
            end if;
          end if;
         

          
       end loop;
    end if;
  end loop;

  return(Result);
end GetChildInfo_new;
/
grant execute on SM.GETCHILDINFO_NEW to SM_ALLUSERS;


prompt
prompt Creating function GETCLIENTALLMOVEID
prompt ====================================
prompt
create or replace function sm.GetClientAllMoveID(ObjID NUMBER, MoveTypes_ID NUMBER, AClient_id in number default NULL, MoveN in number default NULL) return varchar2 is
  Res varchar2(200);
  i number;
begin
-- 08042021 - Чувыкин В.Э. - возвращает Клиента операции движения одного вида (действующие), вытаскивает по номеру MoveN
  begin

   i:=1;

   for xxx in (
               SELECT Clients.Name C_name
               FROM Clients,
                 sm.movesets ms,
                 sm.moveperiods mp,
                 sm.moveitems mi
               WHERE
                ms.id=mp.moveset_id and
                mp.id=mi.moveperiod_id and
                ObjID=mi.object_id(+) and
                Clients.ID(+)=ms.client_id  and
                mp.sincedate(+)<=SYSDATE and
                nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=SYSDATE and
                ms.movetype_id(+)=MoveTypes_ID and
                (ms.client_id = AClient_id or AClient_id is null)
                order by mi.id --desc
               )
   loop

     if i = MoveN then
       RES := xxx.c_name;
     end if;

     i:=i+1;

   end loop;


   EXCEPTION
   WHEN NO_DATA_FOUND THEN NULL;
  end;

  return(RTRIM(Res));
end;
/
grant execute on SM.GETCLIENTALLMOVEID to SM_ALLUSERS;


prompt
prompt Creating function GETCLIENTBALANCE
prompt ==================================
prompt
create or replace function sm.GetClientBalance(AClient_ID NUMBER) return number is

--
-- XSGROUP 15.08.2006
--
-- функция возвращает сальдо по всем обязательствам клиента,
-- заданного параметром:  AClient_ID  - ID клиента
-- на текущую дату
--
--
  CURSOR Obligs IS
   select
     ob.moveset_id MSID,
     ob.obligationtype_id OTID
   from
     movesets ms,
     obligations ob
   where
     ob.moveset_id=ms.id and
     ms.client_id=AClient_ID;
     
  RetVal number(27,2);

begin

  RetVal:=0;
  FOR CurOblig IN Obligs LOOP
    RetVal:=RetVal+sm.Calcfine(sysdate,CurOblig.MSID,CurOblig.OTID,'PAY','ALL');
  END LOOP;

  IF RetVal IS NULL THEN
    RetVal:=0;
  END IF;

  return(RetVal);
end;
/
grant execute on SM.GETCLIENTBALANCE to SM_ALLUSERS;
grant execute on SM.GETCLIENTBALANCE to SM_ALL_SELECT;


