prompt Creating function GETCLIENTDIR_AS
prompt =================================
prompt
create or replace function sm.GetClientDir_AS(AClient_ID NUMBER) RETURN varchar2 IS
--================================================================
--(c) Солопко Андрей Владимирович, 26.06.2008. Все права защищены.
-- Руководитель, телефон
--================================================================
clienttype VARCHAR2(200);
director VARCHAR2(200);
dirphone VARCHAR2(200);
RES	varchar2(500);

begin

select 
  cln.clienttype
into
  clienttype
from
  sm.clients cln
where
  cln.id=AClient_ID;
  
IF (TRIM(clienttype) = 'Организации') THEN
select 
  org.director, org.dirphone
into
  director, dirphone
from
  sm.organisations org, sm.clients cln
where
  cln.id=AClient_ID and
  org.clients_id=cln.id;
END IF;

IF (TRIM(clienttype) = 'Частные лица') THEN
select 
  cln.name, prv.phone
into
  director, dirphone
from
  sm.privates prv, sm.clients cln
where
  cln.id=AClient_ID and
  prv.clients_id=cln.id;
END IF;
  
  IF NOT (TRIM(dirphone) IS NULL) THEN
    dirphone:= '(тел.' || TRIM(dirphone) || ')';
  END IF;  
  
  RES:= SUBSTR(TRIM(RES) || TRIM(director) || ' ' || TRIM(dirphone), 1, 500);
  RETURN RES;

end;
/
grant execute on SM.GETCLIENTDIR_AS to SM_ALLUSERS;
grant execute on SM.GETCLIENTDIR_AS to SM_ALL_SELECT;


prompt
prompt Creating function GETCLIENTNAMEBYDATE
prompt =====================================
prompt
create or replace function sm.GetClientNameByDate(ClientID in number, CalcDate in date default sysdate) return varchar2 is
  RetVal varchar2(4000);
  CurrNAME sm.clients.name%type;
  SubID  number;
  TableName varchar2(30);
  ColumnName varchar2(30);
  Name0 sm.clients.name%type;
begin
  -----------------------------------------------------------------
  -- By XSGROUP ver. 30.09.2009
  -- функция возвращает наименование субъекта права ClientID на дату CDate
  -----------------------------------------------------------------
  for cl_rec in ( select
                    CLNAME,
                    ITEM_ID,
                    TAB_NAME,
                    COL_NAME
                  from
                    (select 
                       cl.Name as CLNAME, 
                       o.ID as ITEM_ID,
                       'ORGANISATIONS' as TAB_NAME,
                       'NAME' as COL_NAME 
                     from
                       sm.clients cl,
                       sm.organisations o
                     where
                       cl.id=o.clients_id and
                       cl.id=ClientID
                       
                     union all
                     
                     select 
                       cl1.Name as CLNAME, 
                       pr.ID as ITEM_ID,
                       'PRIVATES' as TAB_NAME,
                       'FULLNAME' as COL_NAME
                     from
                       sm.clients cl1,
                       sm.privates pr
                     where
                       cl1.id=pr.clients_id and
                       cl1.id=ClientID)
                     
                     union
                       
                     select 
                       cl2.Name as CLNAME, 
                       ATO.ID as ITEM_ID,
                       'ATO' as TAB_NAME,
                       'FULLNAME' as COL_NAME
                     from
                       sm.clients cl2,
                       sm.ATO 
                     where
                       cl2.id=ATO.clients_id and
                       cl2.id=ClientID
                       
                 )
  loop
    CurrNAME:=cl_rec.CLNAME;
    SubID:=cl_rec.ITEM_ID;
    TableName:=cl_rec.TAB_NAME;
    ColumnName:=cl_rec.COL_NAME;
  end loop;              


  if CurrNAME is null then
    Return(null);
  end if;  

  for xx in (select *
             from
               sm.sm_v_changes ch
             where
               ch.ID_VALUE=SubID and
               ch.table_name=TableName and
               ch.column_name=ColumnName
             order by ch.change_date)
  loop
    Name0:=xx.old_value_str;
    if (xx.change_date)>trunc(CalcDate) then
      RetVal:=Name0;
      exit;
    end if;
  end loop;


  if RetVal is null then
    RetVal:=CurrNAME;
  end if;  
    
  Return(RetVal);

end;
/
grant execute on SM.GETCLIENTNAMEBYDATE to SM_ALLUSERS;
grant execute on SM.GETCLIENTNAMEBYDATE to SM_ALL_SELECT;


prompt
prompt Creating function GETCOSTHISTORY
prompt ================================
prompt
create or replace function sm.GetCostHistory(Flag in char, ObjectsID in number) return varchar2 is
Result varchar2(4000);
ObjectType number;
col_name varchar2(4000);

begin
/* 080719 Чувыкин - функция для вывода информации о последнем совершенном со стоимостью изменении */
/*
Флаги
1 - Кадастровая стоимость
2 - Первоначальная
3 - Остаточная
4 - Инвестиционная сметная
5 - Инвестиционная фактическая
*/
col_name :='';

if flag = 1 then col_name := 'CADASTRALVALUE'; end if;
if flag = 2 then col_name := 'STARTPAY'; end if;
if flag = 3 then col_name := 'PAY'; end if;
if flag = 4 then col_name := 'INVESTMENT_ESTIMATED_VALUE'; end if;
if flag = 5 then col_name := 'INVESTMENT_FACT_VALUE'; end if;



     select username || ' ' || activation_date || ' - ' || old_value_num
     into result
     from
                    (
                    select svc.old_value_num, svc.username, svc.activation_date
                    from sm_v_changes svc
                    inner join states s on svc.id_value = s.id
                    where svc.table_name = 'STATES' 
                      and svc.column_name = col_name
                      and s.objects_id = ObjectsID
                    order by svc.activation_date desc
                    )
     where rownum =1;                

return(Result);
end GetCostHistory;
/
grant execute on SM.GETCOSTHISTORY to SM_ALLUSERS;


prompt
prompt Creating function GETCOUNTWITHSHARES
prompt ====================================
prompt
create or replace function sm.GETCOUNTWITHSHARES(ByDate in char, WhatCnt in char, FirstDate in date,
  LastDate in date) return number is
/* возвращает кол-во организаций с долей муниципальной собственности
   Если ByDate='N' или не установлено, то возвращает всего на текущий момент
   иначе
   если WhatCnt='T' - всего на LastDate
        'V' - включено за период с FirstDate по LastDate
        иначе - исключено за тот же период
  */
  
  Result number;

  last_org number(27);
  cnt_beg number;
  cnt_end number;
begin
  Result:=0;

  if ByDate='N' or ByDate is null then
    last_org:=0;
    
    for xx in
     (select sum(t.incoming) i, sum(t.outgoing) o, s.id, s.organisation_id
      from sharemove t,
        shares s
      where 
        t.shares_id=s.id
      group by t.shares_id, s.id, s.organisation_id
      order by
        s.organisation_id)
    loop
      if (xx.i-xx.o)>0 and (last_org=0 or xx.organisation_id<>last_org) then
        Result:=Result+1;
        last_org:=xx.organisation_id;
      end if;    
    end loop;

  ELSE
    last_org:=0;
    cnt_beg:=0;
    for xx in
     (select sum(t.incoming) i, sum(t.outgoing) o, s.id, s.organisation_id org
      from sharemove t,
        shares s
      where 
        t.shares_id=s.id and
        t.movedate<FirstDate
      group by t.shares_id, s.id, s.organisation_id
      order by
        s.organisation_id)
    loop
      if (nvl(xx.i,0)-nvl(xx.o,0))>0 and (last_org=0 or xx.org<>last_org) then
        cnt_beg:=cnt_beg+1;
        last_org:=xx.org;        
      end if;    
    end loop;

    last_org:=0;
    cnt_end:=0;  
    for xx in
     (select sum(t.incoming) i, sum(t.outgoing) o, s.id, s.organisation_id org
      from sharemove t,
        shares s
      where 
        t.shares_id=s.id and
        t.movedate<=LastDate
      group by t.shares_id, s.id, s.organisation_id
      order by
        s.organisation_id)
    loop
      if (nvl(xx.i,0)-nvl(xx.o,0))>0 and (last_org=0 or xx.org<>last_org) then
        cnt_end:=cnt_end+1;
        last_org:=xx.org;        
      end if;    
    end loop;
  
    if RTrim(WhatCnt)='T' then
      Result:=cnt_end;
    else
      if RTrim(WhatCnt)='V' then
        if cnt_end-cnt_beg>0 then
          Result:=cnt_end-cnt_beg;
        else 
          Result:=0;
        end if;
      else
        if cnt_end-cnt_beg<0 then
          Result:=-(cnt_end-cnt_beg);
        else 
          Result:=0;
        end if;
      end if;    
    end if;
    
  end if;
  
  return(Result);
end GETCOUNTWITHSHARES;
/
grant execute on SM.GETCOUNTWITHSHARES to SM_ALL_SELECT;


