prompt
prompt Creating function GETDEBTDAYS
prompt =============================
prompt
CREATE OR REPLACE FUNCTION SM.GetDebtDays (AMoveSet_id IN NUMBER, AOblType_id IN NUMBER, ADate IN DATE default sysdate) RETURN NUMBER IS
    DayDolg number;
    CalcDate date;
    Saldo number;
    DateDolg date;
    
    -- XSGROUP 22.09.2009 (ver.4.6.5)
    -- Функция рассчитывает количество дней просрочки в обязательстве типа AOblType_id
    --                                 операции движения AMoveSet_id
    --                                 на дату ADate
    --
    -- Просрочкой считаем количество дней, в течении которого сальдо оставалось отрицательным 
    -- Для этого перебираем все начисления от даты ADate и ранее, 
    --       до тех пор пока не обнаружим первое начисление, когда сальдо еще было неотрицательым
    -- 
BEGIN
  CalcDate:=trunc(ADate);
  Saldo:=0;
  DateDolg:=sysdate;
  for xx in (select ch.chargedate
             from sm.charges ch
             where ch.movesets_id=AMoveSet_id and ch.obligationtype_id=AOblType_id and ch.chargedate<=ADate
             order by ch.chargedate desc) -- перебираем все начисления, сортируя даты начислений по убыванию
  loop
    Saldo:=sm.calcfine(xx.chargedate,AMoveSet_id, AOblType_id, 'PAY','ALL'); -- определяем сальдо на дату начисления
    if Saldo<0 then -- считаем дату начисления датой образования долга
       DateDolg:=xx.chargedate;
    else
       exit; -- найдена дата начисления, после которой сальдо оставалось отрицательным
    end if;
  end loop;
  
  DayDolg:=trunc(CalcDate-DateDolg); 
  
  if DayDolg<0 then
    DayDolg:=0;
  end if;

  RETURN DayDolg;

END;
/
grant execute on SM.GETDEBTDAYS to SM_ALLUSERS;
grant execute on SM.GETDEBTDAYS to SM_ALL_SELECT;


prompt
prompt Creating function GETDEBTDAYSMS
prompt ===============================
prompt
CREATE OR REPLACE FUNCTION SM.GetDebtDaysMS (AMoveSet_id IN NUMBER, ADate IN DATE default sysdate) RETURN NUMBER IS
    DayDolg number;
    CalcDate date;
    max_day number;
    

    -- XSGROUP 22.09.2009 (ver.4.6.5)
    -- Функция рассчитывает количество дней просрочки в обязательстве типа AOblType_id
    --                                 операции движения AMoveSet_id
    --                                 на дату ADate
    --
    -- Просрочкой считаем количество дней, в течении которого сальдо оставалось отрицательным
    -- Для этого перебираем все начисления от даты ADate и ранее,
    --       до тех пор пока не обнаружим первое начисление, когда сальдо еще было неотрицательым
    --
BEGIN
  max_day:=0;
 
 CalcDate:=trunc(ADate);
 
 for xx in (select obl.obligationtype_id 
            from sm.obligations obl 
            where obl.moveset_id=AMoveSet_ID)
 loop
    select sm.GetDebtDays(AMoveSet_ID,xx.obligationtype_id,CalcDate) 
    into DayDolg
    from dual;
    
    if DayDolg>max_day then
        max_day:=DayDolg;
    end if;
 end loop;   
 
  RETURN max_day;

END;
/
grant execute on SM.GETDEBTDAYSMS to SM_ALLUSERS;
grant execute on SM.GETDEBTDAYSMS to SM_ALL_SELECT;


