prompt Creating function GETDOCBYMOVEID2
prompt =================================
prompt
create or replace function sm.GetDocByMoveID2(MoveID NUMBER) return number is
  Recv number;
  movetype_id number(27);
  share_num number(27);
  share_denom number(27);
begin
 /* 02/03/2016 Твердохлеб: [почта письмо от 02/03/2016] - если операция списания и не всей доли, то документ не показываем*/
 
 SELECT 
        dsm.document_id,
        ms.movetype_id,
        mi.share_num,
        mi.share_denom 
   INTO Recv,
        movetype_id,
        share_num,
        share_denom
   FROM 
        sm.Docset_Members dsm,
        sm.Movesets ms,
        sm.moveperiods mp,
        sm.moveitems mi
 WHERE
   ms.id=mp.moveset_id and
   mp.id=mi.moveperiod_id and
   mi.id=MoveID and
   ms.docset_id=dsm.docset_id and
   dsm.docrole_id=1;
 
  -- если списание
  if (movetype_id = 19)then
    -- если доля не 1/1, т.е. не полное списание
    if (share_num <> 1 or share_denom <> 1) then
       Recv := NULL;
    end if;
  end if; 
  return(Recv);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;
  
end;
/
grant execute on SM.GETDOCBYMOVEID2 to SM_ALLUSERS;


