prompt
prompt Creating function GETDOCDESCRIPTION
prompt ===================================
prompt
create or replace function sm.GetDocDescription(A_Doc_ID number) return varchar2 is
 
-- by XSGROUP 17.09.2014
--
-- Функция возврата описания  документа A_Doc_ID
-- 
 Result     varchar2(4000);
 MainDocID  number;
 
 DocType    doctypes.name%type;        -- тип документа
 DocNo      documents.docno%type;      -- номер документа
 DocDate    documents.docdate%type;    -- дата документа
 DateStart  documents.date_start%type; -- дата начала договора
 DateEnd    documents.date_end%type;   -- дата окончания договора
 
 DefaultDocNo varchar2(60);
 MaxLen     number:=50;
 GUID       sm.doctypes.guid%type; 
begin 
 
  if A_Doc_ID is null then return null; end if;
  
  DefaultDocNo:=RTRIM(LTRIM(sm.getparameter('DEFAULT_DOCNUM')));
  
  select
    dt.NAME, 
    doc.Docno, 
    doc.Docdate,
    doc.date_start,
    doc.date_end,
    dt.GUID 
  INTO
    DocType,
    DocNo,
    DocDate,
    DateStart,  
    DateEnd,
    GUID    
  from
    sm.Documents doc,
    sm.DocTypes  dt
  where
    dt.ID=doc.Doctypes_Id and
    doc.ID=A_Doc_ID;
  
  if GUID='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE' then
    -- особый случай - Неизвестный документ
    Result:='<Неизвестный документ>';
  else
    -- все прочие типы документов
    Result:=RTRIM(LTRIM(DocType));
    if length(Result)>MaxLen then
      Result:=RTRIM(LTRIM(SUBSTR(Result,1,MaxLen-2)))||'..';
    end if;
    
    if not DefaultDocNo is null then
      if RTRIM(LTRIM(DocNo))<>DefaultDocNo then
        Result:=Result||' №'||RTRIM(LTRIM(DocNo));
      end if;  
    end if;
    
    Result:=Result||' от '||to_char(DocDate,'DD.MM.YYYY');
    
    if DateStart is not null then
      Result:=Result||', действует с '||to_char(DateStart,'DD.MM.YYYY');
      
      if DateEnd is not null then
        Result:=Result||' по '||to_char(DateEnd,'DD.MM.YYYY');
      end if;  
    end if; 
  end if;
  
  return(nvl(Result,''));
  
end GetDocDescription;
/
grant execute on SM.GETDOCDESCRIPTION to SM_ALLUSERS;
grant execute on SM.GETDOCDESCRIPTION to SM_ALL_SELECT;


prompt
prompt Creating function GETDOCINDICATOR
prompt =================================
prompt
create or replace function sm.GetDocIndicator(DocID in number) return number is
 i integer;
 /*
 Значение возвращаемое индикатором
 
 --Цветовая гамма 16 цветов
 0 Black, 
 1 Maroon, 
 2 Green, 
 3 Olive, 
 4 Navy, 
 5 Purple, 
 6 Teal, 
 7 DkGray,
 8 LtGray, 
 9 Red, 
 10 Lime, 
 11 Yellow, 
 12 Blue, 
 13 Fuchsia, 
 14 Aqua, 
 15 White
 
 --Стили начертания
 16 - Bold (жирный)
 32 - StrikeOut (зачеркнутый)
 64 - Underline (подчеркнутый)
 128 - Italic (наклон)
 */
begin
 
 i:=0;
 
 for xx in (select conditiondate, conditiondoc from documents where id=DocID) loop
  if xx.conditiondate is not null then
   if (xx.conditiondate<sysdate) and (xx.conditiondoc is null) then i:=9; --red
   elsif (xx.conditiondoc is not null) then i:=6; --green 
   elsif (xx.conditiondate is not null) then i:=12; --blue
   end if;
  end if;
 end loop;

 return(i); 
end;
/
grant execute on SM.GETDOCINDICATOR to SM_ALLUSERS;
grant execute on SM.GETDOCINDICATOR to SM_ALL_SELECT;


prompt
prompt Creating function GETDOCLIST
prompt ============================
prompt
create or replace function sm.GETDOCLIST(ADocSet_id  in NUMBER) return varchar2 is
  Result varchar2(4000);
  i NUMBER;
  --функция возвращает список документов из пакета, включая главный
  --ADocSet_id - ID таблицы DocSets
  /*24/10/2011 Твердохлеб: сделал сортировку по дате документа*/
  /*31/10/2011 Твердохлеб: сначало идет основной документ а потом сортировка по дате документа*/
 begin
   i:=1;
   Result:='';
    for xx1 in (
              select sm.expanddoc(dsm.document_id) doc
                from sm.docset_members dsm
                join sm.documents d on d.id = dsm.document_id
                where dsm.docset_id = ADocSet_id and dsm.docrole_id = 1
             order by d.docdate
             )
   loop
     Result:=Result || to_char(i)||'. '||xx1.doc|| ' ' || chr(13);
     i:=i+1;
   end loop;

   for xx2 in (
              select sm.expanddoc(dsm.document_id) doc
                from sm.docset_members dsm
                join sm.documents d on d.id = dsm.document_id
                where dsm.docset_id = ADocSet_id and (dsm.docrole_id <> 1 or dsm.docrole_id is null)
             order by d.docdate
             )
   loop
     Result:=Result || to_char(i)||'. '||xx2.doc|| ' ' || chr(13);
     i:=i+1;
   end loop;
  return(Result);
end GETDOCLIST;
/
grant execute on SM.GETDOCLIST to SM_ALLUSERS;
grant execute on SM.GETDOCLIST to SM_ALL_SELECT;


prompt
prompt Creating function GETDOCLISTEX
prompt ==============================
prompt
create or replace function sm.GetDocListEx(ADocSet_id  in NUMBER) return varchar2 is
  Result varchar2(1000);
  i NUMBER;
  --функция возвращает список документов из пакета, включая главный
  --ADocSet_id - ID таблицы DocSets
 begin
   i:=1;
   Result:='';
   for xx in (select
                sm.expanddoc(dsm.document_id) doc
              from
                sm.docset_members dsm
              where
                dsm.docset_id=ADocSet_id
              order by dsm.docrole_id)

   loop
     Result:=Result || to_char(i)||'. '||xx.doc||chr(13);
     i:=i+1;
   end loop;
