prompt
prompt Creating function GETENGINF_AS
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION SM.GetENGINF_AS(par_objects_id IN NUMBER) RETURN CHAR IS
RES	varchar2(500);
  -- Разработал Андрей Владимирович Солопко
  -- 2006-10-24
A_LENGTH VARCHAR2(100);
A_WIDTH VARCHAR2(100);
A_SQUARE number;
BEGIN
 SELECT A.LENGTH,A.WIDTH,A.SQUARE
 into A_LENGTH,A_WIDTH,A_SQUARE
 FROM sm.ENGINF A
 WHERE
 OBJECTS_ID = par_objects_id;

 RES:='';
 
 IF NOT (A_LENGTH IS NULL) THEN
  RES:=SUBSTR(RES || ' (Длина - ' || TO_CHAR(A_LENGTH) || ' м.)',1,500);
 END IF;
 IF NOT (A_WIDTH IS NULL) THEN
  RES:=SUBSTR(RES || ' (Ширина - ' || TO_CHAR(A_WIDTH) || ' м.)',1,500);
 END IF;
 IF NOT (A_SQUARE IS NULL) THEN
  RES:=SUBSTR(RES || ' (Площадь - ' || TO_CHAR(A_SQUARE) || ' кв.м.)',1,500);
 END IF;

 RES:=RTRIM(RES);
 
 RES:=SUBSTR(RES,1,length(Res));

 RETURN RES;

END;
/
grant execute on SM.GETENGINF_AS to SM_ALLUSERS;
grant execute on SM.GETENGINF_AS to SM_ALL_SELECT;


