prompt
create or replace function sm.GetFinRate return T_FINRATE_L pipelined as
 id number(27);
 apply_date date;
 refrate number;

begin
id:=1;

for xxx in (
            select r.apply_date,
                   r.refrate
            from refinrates r
            order by r.apply_date desc
           )

loop
   apply_date := xxx.apply_date;
   refrate := xxx.refrate;
   pipe row (T_FINRATE(
                            id, 
                            apply_date,
                            refrate                            
                            )
             );
    id := id + 1;
 end loop;

  return;
end GetFinRate;
/

prompt
prompt Creating function GETFIRSTMOVIEDBUILDOBJIDBYDATE
prompt ================================================
prompt
create or replace function sm.GetFirstMoviedBuildObjIDByDate(ObjID NUMBER, MoveTypes_ID NUMBER, CDate IN DATE) return NUMBER is
--
--by XSGROUP ver. 31.10.2008
--функция возвращает ID объекта, на который оформлено движение MoveType_ID
--в момент времени CDate
--для зданий и помещений будет найден объект верхнего уровня,
-- если на сам объект явно не оформлена операция движения данного типа
--
  Recv NUMBER:=null;
  ObjType NUMBER;
  BaseBuildID NUMBER;
  BaseObjID NUMBER;
begin

  for x IN  (select
               mi.object_id
             from
               sm.movesets ms,
               sm.moveperiods mp,
               sm.moveitems mi
             where
               ms.id=mp.moveset_id and
               mp.id=mi.moveperiod_id and
               mi.object_id=ObjID and
               ms.movetype_id=MoveTypes_Id and
               mp.sincedate<=CDate and
               nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=CDate
             )
  loop

    Recv:=x.object_id;

    exit;
  end loop;

 if Recv is not null then
   return(Recv);
 end if;

 select ObjTypes_ID into ObjType from sm.Objects where ID=ObjID;

 -- разбор случая, если это здание
 if ObjType = 3 then
   select
     Basebuilding
   into
     BaseBuildID
   from
     sm.Buildings
   where
     Objects_ID=ObjID;

   if (BaseBuildID is not null) then
     select
       Objects_ID
     into
       BaseObjID
     from
       sm.Buildings
     where
       ID=BaseBuildID;

     Return (sm.GetFirstMoviedBuildObjIDByDate(BaseObjID,MoveTypes_ID,CDate));
   end if;
 end if;

 return(Recv);

exception
 when NO_DATA_FOUND then return null;

end;
/
grant execute on SM.GETFIRSTMOVIEDBUILDOBJIDBYDATE to SM_ALLUSERS;
grant execute on SM.GETFIRSTMOVIEDBUILDOBJIDBYDATE to SM_ALL_SELECT;


