prompt
prompt Creating function GETFIRSTWORKDATE
prompt ==================================
prompt
create or replace function sm.GetFirstWorkDate(ADate in date) return date is
-- Функция возвращает ближайший рабочий банковский день
 
  cursor holidays is select *  from sm.Holidays h where h.holidaydate >= ADate order by h.holidaydate;
  nearest_holiday holidays%ROWTYPE; 
 
  d1  date;
  d2  date;
  n   integer;
  cnt integer;
  is_workday char(1);
  curdate date;

begin
--- Обязательно всегда и везде контролировать корректность параметров (при null - входила в бесконечный цикл!!!)
if ADate is null then
	  return null;
end if;
	
 --берем входящую дату 
 select to_date(to_char(ADate,'dd.mm.yyyy'),'dd.mm.yyyy') into curdate from dual;---16.04.2014 Morozova 
-- curdate :=ADate; 

 open holidays;
 fetch holidays into nearest_holiday;
 
 loop
  -- расчитываем день недели (0-воскресенье)
    d1 := curdate;
    d2 := round(d1,'DAY');
    n  := (d1 - d2) + 1;
    if n < 0 then
      n := 7 + n;
    end if;

 -- если текущая дата явно описана как рабочая, вовзвращаем как рабочий
  if (nearest_holiday.holidaydate = curdate) and (nearest_holiday.workday='Y')  then return curdate; end  if;
-- если текущая дата не выходной и не праздничная, вовзвращаем как рабочий
  if (n not in (6,0)) and (nvl(nearest_holiday.holidaydate,curdate+1)!=curdate) then return curdate; end  if;
-- дальше двигаем текущую дату вперед
  if  (nearest_holiday.holidaydate = curdate) then  fetch holidays into nearest_holiday; end if; -- ищем очередную запись в таблице праздников
  
  curdate := curdate+1;
 end loop;
 
 close holidays;

end GetFirstWorkDate;
/
grant execute on SM.GETFIRSTWORKDATE to SM_ALLUSERS;
grant execute on SM.GETFIRSTWORKDATE to SM_ALL_SELECT;


prompt
prompt Creating function GETFULLOBJECTADRESS
prompt =====================================
prompt
create or replace function sm.GETFULLOBJECTADRESS(ObjID number) return varchar2 is
  Result varchar2(1000);
Objtyp number(27);
AddrID number(27);
begin
  select o.objtypes_id into Objtyp
  from objects o
  where o.id=ObjID;

  AddrID:=0;

  if Objtyp=3 then
    select address_id into AddrID
    from sm.buildings t
    where t.objects_id=ObjID;
  end if;

  if Objtyp=4 then
    select address_id into AddrID
    from sm.unconstr t
    where t.objects_id=ObjID;
  end if;

  if Objtyp=5 then
    select address_id into AddrID
    from sm.enginf t
    where t.objects_id=ObjID;
  end if;

  if Objtyp=6 then
    select Cl.address_id into AddrID
    from sm.organisations org,
         sm.Clients cl
    where org.objects_id=ObjID
      and org.Clients_Id=Cl.Id;
  end if;

  if Objtyp=7 then
    select address_id into AddrID
    from sm.grounds t
    where t.objects_id=ObjID;
  end if;

  if AddrID<>0 then
    select sm.expandaddr(AddrID) into Result
    from dual;
  end if;

  return(Result);
end GETFULLOBJECTADRESS;
/
grant execute on SM.GETFULLOBJECTADRESS to SM_ALLUSERS;
grant execute on SM.GETFULLOBJECTADRESS to SM_ALL_SELECT;


prompt
prompt Creating function GETFULLOBJECTDESCRIPTION
prompt ==========================================
prompt
create or replace function sm.GETFULLOBJECTDESCRIPTION(ObjID number) return varchar2 is
  Result varchar2(800);
-- Функция возврата полного описания объекта в зависимости от типа одной строкой
descr varchar(800);
res varchar(500);
obj_t number;
begin

 SELECT description, objtypes_id INTO descr, obj_t
 FROM Objects
 WHERE
  ID=ObjID;

-- Имущество
 if obj_t=1 then
   select  pn.name || ' ' || p.model into Descr
   from sm.property p, sm.propnames pn
   where p.propnames_id= pn.id and p.objects_id=ObjID;
   Result:=descr;
 end if;

-- Транспорт
 if obj_t=2 then
   select tt.name || ' Модель ' || tr.model || ' / Год выпуска ' || tr.relyear || ' / Фед.номер ' || tr.fedno || ' / Номер двигателя ' || tr.motorno || ' / Шасси ' || tr.chassisno  into Descr
   from transport tr, transptype tt
   where tr.objects_id=ObjID and tr.transptype_id=tt.id;
   Result:=descr;
 end if;

-- Здания и помещения
 if obj_t=3 then
   select bt.name || ' площадью ' || b.square || ' кв.м. ' || ' / Кол-во этажей ' || b.floorcount || ' / По адресу ' || sm.expandaddr(b.address_id) into Descr
   from sm.buildings b, sm.buildtypes bt
   where b.basebuilding is null and
      b.buildtypes_id(+)=bt.id and
      b.objects_id=ObjID;
   Result:=descr;
 end if;

-- Незаверш. строит.
 if obj_t=4 then
   select 'Объект незавершенного строительства ' || ut.name || ' / Строительный номер ' || ut.buildno || ' / Начало строителства ' || ut.startyear || ' / По адресу ' || sm.expandaddr(ut.address_id) into Descr
   from sm.unconstr ut
   where ut.objects_id=ObjID;
   Result:=descr;
 end if;

-- Инженерн. инфрастр.
 if obj_t=5 then
   select en.name || ' / Тип ' || et.name || ' / Группа ' || ig.name || ' / Длина ' || en.length || ' / Ширина ' || en.width || ' / Площадью ' || en.square || ' / Год ввода ' || en.enteryear || ' / По адресу ' || sm.expandaddr(en.address_id) into Descr
   from sm.enginf en, sm.enginftypes et, sm.infgroups ig
   where en.enginftypes_id=et.id(+) and
     en.infgroups_id=ig.id(+) and
     en.objects_id=ObjID;
   Result:=descr;
 end if;

-- Организации
 if obj_t=6 then
   select og.name || f.name || ' / ИНН ' || Cl.inn || ' / Руководитель ' || og.director || ' / По адресу ' || sm.expandaddr(Cl.address_id) into Descr
   from sm.organisations og, sm.orgforms f, sm.Clients cl
   where og.orgform=f.id 
     and og.objects_id=ObjID
     and Cl.Id=og.Clients_Id;
   Result:=descr;
 end if;

-- Земельные участки
 if obj_t=7 then
   select gt.name || ' Площадью ' || g.square || ' / По адресу '|| sm.expandaddr(g.address_id) into Descr
   from sm.grounds g, sm.groundtypes gt
   where g.groundtypes_id=gt.id(+) and g.objects_id=ObjID;
   Result:=descr;
 end if;

  return(RTRIM(Result));
end GETFULLOBJECTDESCRIPTION;
/
grant execute on SM.GETFULLOBJECTDESCRIPTION to SM_ALLUSERS;
grant execute on SM.GETFULLOBJECTDESCRIPTION to SM_ALL_SELECT;


