prompt Creating function GETGENERALNAME
prompt ================================
prompt
create or replace function sm.GETGENERALNAME(ObjectID in number, Obj_Type character) return varchar2 is
--Чувыкин В.Э. май2017  функция собирает поле "Наименование общее" для следующих типов объектов:
-- при obj_type=1 для прочего движимого по приниципу Название+Модель
-- при obj_type=2 для транспорта по принципу Тип+Марка+Модель
  name_ varchar2(100);
  model varchar2(100);
  
  type_ varchar2(100);
  marka varchar2(100);
     
  genname varchar2(100);
begin
if Obj_Type='1' then
  begin
  select PropNames.Name
    into Name_
    from sm.PropNames, sm.Property
  where PropNames.ID=Property.PropNames_ID and Property.Objects_Id=ObjectID;
  
  select Property.Model
    into Model
    from sm.Property
  where Property.Objects_id=ObjectID;
  
  genname := Name_ || ' ' || Model;
  return genname;
  end;
end if;

if Obj_Type = '2' then
  begin

  select TranspType.Name
    into Type_
    from sm.TranspType, sm.Transport
  where TranspType.ID=Transport.TranspType_ID and Transport.Objects_Id=ObjectID;

  select BrandNames.Name
    into Marka
    from sm.BrandNames, sm.Transport
  where BrandNames.ID=Transport.BrandNames_ID and Transport.Objects_Id=ObjectID;
  
  select Transport.Model
    into Model
    from sm.Transport
  where Transport.Objects_id=ObjectID;
  
  genname := Type_ || ' ' || Marka || ' ' || Model;
  return genname;
  end;
end if;

end;
/
grant execute on SM.GETGENERALNAME to SM_ALLUSERS;


