prompt Creating function GETGROUNDSLIST
prompt ================================
prompt
create or replace function sm.GETGROUNDSLIST(Client_id  in NUMBER) return varchar2 is
  Result varchar2(4000);
  i NUMBER;
  --функция возвращает перечень Земельных учасков, находяшихся на балансе у заданного Субъекта права
 begin
   i:=1;
   Result:='';
    for xx1 in (
              SELECT
t1.ID PRIMARY_ID
, sm.GetObjectKadastrNo('1', t1.ID) SEL20

FROM
SM.OBJECTS t1
WHERE
(t1.ID in (SELECT 
 Objects.ID
FROM 
 sm.Objects
WHERE 
 EXISTS (
  SELECT 
   MoveItems.ID
  FROM 
   sm.MoveItems,
   sm.MovePeriods,
   sm.MoveSets,
   sm.movements MI_MV
  WHERE 
   MI_MV.MoveItem_ID=MoveItems.id and
   MI_MV.OBJECTS_ID=Objects.ID and
   MoveItems.MovePeriod_ID=MovePeriods.ID and
MovePeriods.MoveSet_ID=MoveSets.ID and
   MoveSets.ID IN (
    SELECT 
     MoveSets.ID
    FROM 
     sm.MoveSets
    WHERE 
     MOVESETS.CLIENT_ID IN (Client_id) and
     MOVESETS.MOVETYPE_ID IN (20) and
     sm.GetMoveSetEndDate(MoveSets.ID) IS NULL
)
) and
 OBJECTS.OBJTYPES_ID IN (7)

))
ORDER BY t1.ID

             )
   loop
     Result:=Result /*|| to_char(i)||'. '*/||trim(xx1.sel20)/*|| ' ' || chr(13)*/;
     i:=i+1;
   end loop;


  return(Result);
end GETGROUNDSLIST;
/

prompt
prompt Creating function GETGROUPPURPOSE
prompt =================================
prompt
create or replace function sm.GetGroupPurpose(Aobject_id in number) return varchar2 is
  Result varchar2(4000);
  lp_id number(27);
  lp_id_sob number(27);
  lp_id_spis number(27);

  RN number(27);
begin
  /*311219 Чувыкин - Выводит название группы назначений из ОД Собственность*/
  /*090119 Чувыкин - и из ОД Списание, если есть назначение из обоих ОД, то возьмем первое непустое значение*/

  Result := '';

   -- определяем id назначения из Собственности 
   begin
   select lp.id
   into lp_id_sob
   from
   leasepurpose lp
   join moveitems mi on mi.leasepurpose_id = lp.id
   where
   mi.id = getpositionmoveid(Aobject_id,1);
                exception
                when NO_DATA_FOUND then 
                lp_id_sob:=null;
                end;


   -- определяем id назначения из Списания 
   begin
   select lp.id
   into lp_id_spis
   from
   leasepurpose lp
   join moveitems mi on mi.leasepurpose_id = lp.id
   where
   mi.id = getpositionmoveid(Aobject_id,19);
                exception
                when NO_DATA_FOUND then 
                lp_id_spis:=null;
                end;

   
   lp_id:=coalesce(lp_id_sob,lp_id_spis);

   --определим число звеньев иерархии
   select max(rownum)
   into RN
   from
   leasepurpose lp
   connect by lp.id = prior lp.root
   start with lp.id = lp_id;

    for qq in(
               -- запрос выстраивает ветку иерархии вверх от определенного выше назначения
              select lp.name, lp.id, level
              from
              leasepurpose lp
              connect by lp.id = prior lp.root
              start with lp.id = lp_id
              )
    loop
      begin
        if qq.id = lp_id and qq.level = RN-1 then result:=null; end if;
        if qq.id <> lp_id and qq.level = RN-1 then result:=qq.name; end if;
      end;
    end loop;

    return(Result);
end GetGroupPurpose;
/
grant execute on SM.GETGROUPPURPOSE to SM_ALLUSERS;


prompt
prompt Creating function GETINICIALFIO
prompt ===============================
prompt
create or replace function sm.GetInicialFIO(ClientID NUMBER, WhereIns NUMBER default 1) return varchar2 is
  Res VARCHAR2(50);
  --
  -- by xsgroup 06.06.2010 г.
  -- Для организаций функция возвращает фамилию с инициалами руководителя,
  -- Для физических лиц - фамилию с инициалами самого физического лица.
  -- Нужный клиент задаётся с помощю параметра ClientID + ID клиента,
  -- Если WhereIns=1, то инициалы будут помещены перед фамилией,
  -- Если WhereIns=2, то инициалы будут помещены после фамилии
  -- В том случае, если ФИО заданы полностью, то первое слово считается фамилией.
  --
  
  fio sm.organisations.director%Type;
  cltp VARCHAR2(50);
begin
 Res:=' ';
 SELECT cl.clienttype INTO cltp 
 FROM sm.clients cl 
 WHERE cl.id=ClientID;
 
 if instr(cltp, 'Юр')<>0 then
   SELECT org.director INTO fio
   FROM sm.organisations org
   WHERE
      org.clients_id=ClientID;
 else
    SELECT pr.fullname INTO fio
    FROM sm.privates pr
    WHERE
       pr.clients_id=ClientID;
 end if;

 if trim(fio) is null then
      return(res);
      
 end if;   
     
 if Instr(fio, '.', 1,1)<>0 and Instr(fio, '.', 1,2)<>0 then 
     if  WhereIns=2 and Instr(ltrim(fio), '.', 1,1)=2 then
             fio:=ltrim(fio);
             Res:=substr(fio, Instr(fio, '.', 1,2)+1, length(fio) - Instr(fio, '.', 1,2));
             cltp:=substr(fio, 1, Instr(fio, '.', 1,2));
             Res:=Res || cltp;
         elsif WhereIns=1 and Instr(ltrim(fio), '.', 1,1)<>2 then
               fio:=ltrim(fio);
               Res:=substr(fio, 1, instr(fio, ' '));
               cltp:=substr(fio, instr(fio, ' ')+1, length(fio)-instr(fio, ' '));
               Res:=cltp || Res;
     else      
         Res:=fio;
     end if;
 elsif instr(trim(fio), ' ')=0 then
       Res:=fio;
 else
        
        fio:=ltrim(fio);
        Res:=substr(fio, 1, instr(fio, ' ')); 
        fio:=substr(fio, instr(fio, ' ')+1, length(fio)-instr(fio, ' '));
        fio:=ltrim(fio);
        cltp:=substr(fio, 1, 1) || '. ';
        if instr(trim(fio), ' ')<>0 then
           fio:=substr(fio, instr(fio, ' ')+1, length(fio)-instr(fio, ' '));
           fio:=ltrim(fio);
           cltp:=cltp || substr(fio,1,1) || '. ';
        end if;
        if WhereIns=2 then
           Res:=Res || cltp;
        else
           Res:=cltp || Res;
        end if;
 end if;
 return(res);
 
EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN ' ';

end;
/
grant execute on SM.GETINICIALFIO to SM_ALLUSERS;
grant execute on SM.GETINICIALFIO to SM_ALL_SELECT;


