prompt
prompt Creating function GETITEMNAME
prompt =============================
prompt
create or replace function sm.GetItemName(AObjType in number, AObjectID in number) return varchar2 is
  
  -- By XSGROUP 28.04.2012 
  -- Функция возврата описания экземпляров сущностей SAUMI
  -- Если строка Result пустая, то будет использоваться значение, сфорированное исполнимым модулем SAUMI
  
  Result varchar2(4000);
  date_var date;
  
  MaxDocNameLenfth integer default 100; -- максимальная длина строки описания документа  
  itmp number(27);

begin
  Result:=null;

  ------------------------------------------------------------------------------------------------
  if AObjType=1 then -- объекты

    select description
    into Result
    from sm.objects
    where id=AObjectID;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=2 then -- документы

    select trim(sm.expanddoc(AObjectID))
    into Result
    from dual;

    if length(Result)>MaxDocNameLenfth then
      Result:=substr(Result,1,MaxDocNameLenfth)||'...';
    end if;

    return (trim(Result));

  end if;
  -------------------------------------------------------------------------------------------------
  if AObjType=3 then -- клиенты

    select name
    into Result
    from sm.clients
    where id=AObjectID;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=4 then -- ценные бумаги                      -------------TO DELETE !!!!!!-------------------

    select RTRIM(organisations.name) || ', ' || RTRIM(sharetypes.name) || ' (' || RTRIM(ShareCategory.Name) || ') - ' || TO_CHAR(Nominal) || 'руб.'
    into Result
    from
      sm.shares,
      sm.sharetypes,
      sm.sharecategory,
      sm.organisations
    where
      organisation_id=organisations.id and
      sharetypes.id=sharetype_id and
      sharecategory.id=sharecategory_id and
      shares.id=AObjectID;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=8 then -- операция с ценными бумагами-------------TO DELETE !!!!!!-------------------

    select decode(SIGN(outgoing-incoming),-1,'Куплено: ','Продано: ')||RTRIM(organisations.name) || ', ' || RTRIM(sharetypes.name) || ' (' || RTRIM(ShareCategory.Name) || ') - ' || TO_CHAR(Nominal) || 'руб.'
    into Result
    from
      sm.shares,
      sm.sharetypes,
      sm.sharecategory,
      sm.organisations,
      sm.sharemove
    where
      organisation_id=organisations.id and
      sharetypes.id=sharetype_id and
      sharecategory.id=sharecategory_id and
      shares.id=sharemove.shares_id and
      sharemove.id=AObjectID;

    return (trim(Result));

  end if;

  ------------------------------------------------------------------------------------------------
  if AObjType=9 then -- операция движения

    for xx in (
                select '1' ORD, RTRIM(movetype.name)||'  '|| RTRIM(sm.objects.description)|| ' - ' ||RTRIM(Clients.Name) DESCR
                from
                  sm.movetype,
                  sm.objects,
                  sm.clients,
                  sm.movesets,
                  sm.moveitems,
                  sm.moveperiods
                where
                  movesets.id=AObjectID and
                  movetype.id=movesets.movetype_id and
                  clients.id=movesets.client_id and
                  moveperiods.moveset_id = movesets.id and
                  moveitems.moveperiod_id=moveperiods.id and
                  objects.id=moveitems.object_id

                UNION

                select '2' ORD, RTRIM(movetype.name)||'  (без объектов) - ' ||RTRIM(Clients.Name) DESCR
                from
                  sm.movetype,
                  sm.clients,
                  sm.movesets
                where
                  movesets.id=AObjectID and
                  movetype.id=movesets.movetype_id and
                  clients.id=movesets.client_id

                ORDER BY ORD
               )
    loop
      Result:=xx.DESCR;
      exit;
    end loop;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=25 then -- движение объекта

    select RTRIM(movetype.name) || ', '||share_num||'/'||share_denom || ' - ' || RTRIM(objects.description) || ' - ' || RTRIM(Clients.Name)
    into Result
    from
      sm.movetype,
      sm.objects,
      sm.clients,
      sm.movesets ms,
      sm.moveperiods mp,
      sm.moveitems mi
    where
      ms.id=mp.moveset_id and
      mp.id=mi.moveperiod_id and
      mi.id=AObjectID and
      movetype.id=ms.movetype_id and
      clients.id=ms.client_id and
      objects.id=mi.object_id;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=27 then -- льготы

    begin
      select 'Льгота' || decode(instr(discharge_type,'FINE'),0,'',' по пене')||' '||' c '||to_char(sincedate,'DD.MM.YYYY')||'@, '||to_char(Discount_value*100,'FM990.999')||'%',enddate
      into
        Result,
        date_var
      from
        sm.Discounts
      where ID=AObjectID;
    exception
       when others then
          Result:=null;
    end;
    if date_var is null then
      Result:=REPLACE(Result,'@,',',');
    else
      Result:=REPLACE(Result,'@,',' по '||to_char(date_var,'DD.MM.YYYY')||',');
    end if;

    return (trim(Result));

  end if;

  ------------------------------------------------------------------------------------------------
  if AObjType=28 then -- отсрочки

    begin
      select 'Отсрочка '||REPLACE('до '||nvl(to_char(deffer_date,'DD.MM.YYYY'),'01.01.0001'),'до 01.01.0001','(на неопределенный срок)')||' за период начислений с '||to_char(charge_sincedate,'DD.MM.YYYY'),charge_enddate
      into
        Result,
        date_var
      from
        sm.Deffers
      where ID=AObjectID;
    exception
       when others then
          Result:=null;
    end;

    if date_var is not null then
      Result:=Result||' по '||to_char(date_var,'DD.MM.YYYY');
    end if;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=31 then -- операции с УК

    select 
           RTRIM(organisations.name) 
           ||' - ' ||RTRIM(opertype.code) 
           ||' ' ||to_char(opershares.operdate,'DD.MM.YYYY') 
           || (case when opershares.code is not null then ' рег. №' || RTRIM(opershares.code) else '' end)
           ||' ' ||RTRIM(sharetypes.name) 
           ||' ' ||RTRIM(ShareCategory.Name)
    into Result
    from
      sm.opershares,
      sm.opertype,
      sm.sharetypes,
      sm.sharecategory,
      sm.organisations
    where
      opershares.organisations_id=organisations.id and
      opertype.id=opershares.opertype_id and
      sharetypes.id(+)=opershares.sharetypes_id and
      sharecategory.id(+)=opershares.sharecategory_id and
      opershares.id=AObjectID;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=61 then -- платежи

    begin
      select "SUM" || ' руб. ' || RTRIM(sm.ExpandDoc(DOCUMENTS_ID))
      into Result
      from sm.Payments
      where ID=AObjectID;
    exception
       when others then
          Result:='<не существует>';
    end;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  if AObjType=501 then -- начисления

    begin
      select ChargeDate || ' '||nvl(Comments,'начислено')||' :'||PaySize||'р.'||decode(CHARGE_TYPE,'FINE','(пеня)','')
      into Result
      from
        sm.Charges
      where ID=AObjectID;
    exception
       when others then
          Result:=null;
    end;

    return (trim(Result));

  end if;
  ------------------------------------------------------------------------------------------------
  Select count(*) into itmp from SM.FM_TABLES where TABLE_NAME = 'UNITGROUP';
  if (itmp) > 0 then      
    Select TYPE_ID into itmp from SM.FM_TABLES where TABLE_NAME = 'UNITGROUP';
    if AObjType=itmp then -- Группы единиц измерения
  
      begin
        select NAME 
        into Result
        from
          sm.UNITGROUP
        where ID=AObjectID;
      exception
         when others then
            Result:=null;
      end;
  
      return (trim(Result));
  
    end if;    
  end if;
  ------------------------------------------------------------------------------------------------
  Select count(*) into itmp from SM.FM_TABLES where TABLE_NAME = 'UNIT';
  if (itmp) > 0 then   
    Select TYPE_ID into itmp from SM.FM_TABLES where TABLE_NAME = 'UNIT';
    if AObjType=itmp then -- Единицы измерения
  
      begin
        select SHORT 
        into Result
        from
          sm.UNIT
        where ID=AObjectID;
      exception
         when others then
            Result:=null;
      end;
  
      return (trim(Result));
  
    end if;    
  end if;
  ------------------------------------------------------------------------------------------------

  return(null); -- если не реализовано для AObjType - вернём пустую строку

end;
/
grant execute on SM.GETITEMNAME to SM_ALLUSERS;
grant execute on SM.GETITEMNAME to SM_ALL_SELECT;


prompt
prompt Creating function GETLASTSTATEDATE
prompt ==================================
prompt
create or replace function sm.GetLastStateDate(flag in CHAR, OBJ_ID IN NUMBER, A_DATE IN DATE) return DATE is
  result Date;
begin
  --17.04.2020 Чувыкин - функция выводит дату присвоения последней стоимости на заданную дату актуальности
  -- флаг 1 - кдастровой
  -- флаг 2 - балансовой (первоначальной)
  -- флаг 3 - остаточной

if flag = 1 then
  begin
  select max(s.calcdate)
  into result
  from sm.states s
  where s.objects_id=OBJ_ID
     and s.calcdate<=A_DATE
     and s.cadastralvalue is not null;
         exception
         when NO_DATA_FOUND then
         null;
  end;       
end if;

if flag = 2 then
  begin
  select max(s.calcdate)
  into result
  from sm.states s
  where s.objects_id=OBJ_ID
     and s.calcdate<=A_DATE
     and s.startpay is not null;
         exception
         when NO_DATA_FOUND then
         null;
  end;       
end if;

if flag = 3 then
  begin
  select max(s.calcdate)
  into result
  from sm.states s
  where s.objects_id=OBJ_ID
     and s.calcdate<=A_DATE
     and s.pay is not null;
         exception
         when NO_DATA_FOUND then
         null;
  end;       
end if;

  return result;

end GetLastStateDate;
/
grant execute on SM.GETLASTSTATEDATE to SM_ALLUSERS;


prompt
prompt Creating function GETLINE_AS
prompt ============================
prompt
create or replace function sm.GetLine_AS(Str varchar2, Ind int) return varchar2
is
  Separator constant varchar2(2) := chr(13) || chr(10);
  I1 int := instr(Separator || Str || Separator, Separator, 1, Ind);
  I2 int := instr(Separator || Str || Separator, Separator, 1, Ind + 1);
-- Разработал Андрей Владимирович Солопко  
-- 2004-08-27
begin
  return   substr(Separator || Str || Separator, I1 + length(Separator), I2 - I1 - length(Separator));
end GetLine_AS;
/
grant execute on SM.GETLINE_AS to SM_ALLUSERS;
grant execute on SM.GETLINE_AS to SM_ALL_SELECT;


