prompt Creating function GETMAINDOC
prompt ============================
prompt
create or replace function sm.GETMAINDOC(ADocSet_id  in NUMBER) return varchar2 is
  Result varchar2(1000);
  i NUMBER;
  --функция возвращает главный документ
  --ADocSet_id - ID таблицы DocSets
   /*24/10/2011 Твердохлеб: сделал сортировку по дате документа*/
 begin
   i:=1;
   Result:='';
   for xx in (
               select sm.expanddoc(dsm.document_id) doc
                 from sm.docset_members dsm
                 join sm.documents d on d.id = dsm.document_id
                where dsm.docset_id = ADocSet_id
                  and dsm.docrole_id = 1 --главный документ
             order by d.docdate
             )

   loop
     Result:=Result || to_char(i)||'. '||xx.doc||chr(13);
     i:=i+1;
   end loop;
  return(Result);
end GETMAINDOC;
/
grant execute on SM.GETMAINDOC to SM_ALLUSERS;
grant execute on SM.GETMAINDOC to SM_ALL_SELECT;


