create or replace function sm.GetMonthName(GDate in DATE) return varchar2 is
  Result varchar2(20);
  RD DATE;
  r integer;
begin
  RD:=trunc(GDate,'MONTH');
  r:=MONTHS_BETWEEN(RD,trunc(RD,'YEAR'))+1;
  
  select decode(R,1,'Январь',2,'Февраль',3,'Март',4,'Апрель',5,'Май',6,'Июнь',7,'Июль',8,'Август',9,'Сентябрь',10,'Октябрь',11,'Ноябрь',12,'Декабрь','???') into Result from dual;
  return(Result);
end GetMonthName;
/
grant execute on SM.GETMONTHNAME to SM_ALL_SELECT;


prompt
prompt Creating function GETMONUMENTTYPE
prompt =================================
prompt
create or replace function sm.GetMonumentType(ObjectID in number) return varchar2 is
  MonumentType varchar2(100);
  ObjType number(27);
  ParentID number(27);
begin
  -- Чувыкин В.Э. - 15.01.2019 - возвращает название типа памятника для объекта

     MonumentType:=null;
     ObjType:=null;
     ParentID:=null;
-- выясним тип объекта
     select O.Objtypes_id
       into ObjType
       from sm.Objects O
      where O.Id=ObjectID;
      -- если это здание-помещение
      if ObjType = 3 THEN
      begin
         --выясняем, есть ли у него родитель (по всей иерархии)
         ParentID:=ObjectID;
         begin
           --while ParentID is not null 
           loop
             select B1.OBJECTS_ID
               into ParentID
               from sm.Buildings B1
               where B1.ID = (select B.BASEBUILDING
                               from sm.Buildings B
                              where B.OBJECTS_ID = ParentID);                               
           end loop;
                 exception
                 when NO_DATA_FOUND then null;
                     
         end;

         -- если у здания-помещения родителя нет
         if (ParentID is null) then
           --MonumentType:='Родителя нет';
          select MT.NAME
           into MonumentType
           from sm.MonumentTypes MT
           join sm.Objects O on O.MNTYPE_ID = MT.ID
          where O.Id=ObjectID;

         -- если у здания-помещения родитель нашелся
         else
           --MonumentType:='Родитель есть';
         select MT.NAME
           into MonumentType
           from sm.MonumentTypes MT
           join sm.Objects O on O.MNTYPE_ID = MT.ID
         where O.Id=ParentID;
         end if;

      end;
      -- если объект всех остальных категорий
      else
         select MT.NAME
           into MonumentType
           from sm.MonumentTypes MT
           join sm.Objects O on O.MNTYPE_ID = MT.ID
          where O.Id=ObjectID;

      end if;

  return MonumentType;
end;
/
grant execute on SM.GETMONUMENTTYPE to SM_ALLUSERS;
grant execute on SM.GETMONUMENTTYPE to SM_ALL_SELECT;


