prompt
prompt Creating function GETMOVESETLASTPERIODID
prompt ========================================
prompt
create or replace function sm.GetMoveSetLastPeriodId(AMoveSet_ID IN NUMBER) RETURN number
is
 res number(27);
begin

  -- Чувыкин 12.07.2024
  -- Возвращает moveperiods.id открытого периода заданной операции движения
  
  -- Чувыкин 24.10.2024
  -- Возвращает moveperiods.id самого нового по дате открытия, то есть последнего периода заданной операции движения - и НЕ ВАЖНО, открыт он или закрыт

  begin
    /*select m.id
    into res
    from
      sm.Moveperiods m
    where
      m.Moveset_Id=AMoveSet_ID and
      m.enddate is null;*/

select 
  m.id into res
from
  sm.Moveperiods m
where 
 m.moveset_id = AMoveSet_ID
 and
 m.sincedate=
    (select 
      max(m.sincedate)
    from
      sm.Moveperiods m
    where
      m.Moveset_Id=AMoveSet_ID);      
      
      
   exception
     when others then
       null;
   end;

  return res;

end;
/
grant execute on SM.GETMOVESETLASTPERIODID to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEAMOUNT
prompt ===============================
prompt
create or replace function sm.GetMoveAmount(AMoveSet_ID NUMBER, AOblType_id NUMBER) return number
is
  Amount number(27,2):=0.00;

BEGIN
/*12.07.2024 Чувыкин - функция возвращает "Размер оплаты" из последнего периода заданной операции движения по заданному типу обязательства*/
begin
select pd.paysize
into Amount
    from  sm.paydocs pd
    where  pd.obligationtype_id = AOblType_id
      and pd.moveperiod_id = getmovesetlastperiodid(AMoveSet_ID);
    exception
     when others then
       null;
   end;

RETURN Amount;
END;
/
grant execute on SM.GETMOVEAMOUNT to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEAMOUNTDYDATE
prompt =====================================
prompt
create or replace function sm.GetMoveAmountDyDate(AMoveSet_ID NUMBER, AOblType_id NUMBER, ADate Date) return number
is
  Amount number(27,2):=0.00;

BEGIN
/*19.07.2024 Чувыкин - функция возвращает "Размер оплаты" из того периода заданной операции движения по заданному типу обязательства, в который входит заданная дата*/
begin
select pd.paysize
into Amount
    from  sm.paydocs pd
    where  pd.obligationtype_id = AOblType_id
      and pd.moveperiod_id = getmovesetperiodid(AMoveSet_ID, ADate);
    exception
     when others then
       null;
   end;

RETURN Amount;
END;
/
grant execute on SM.GETMOVEAMOUNTDYDATE to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEBALANCE
prompt ================================
prompt
create or replace function sm.GetMoveBalance(AMoveSet_ID NUMBER, WhatsNeed VARCHAR2, ABalanceDate IN DATE default SYSDATE) return number is
  RetVal number(27,2);

  Charged number(27,2);
  Payed number(27,2);
 
begin
  --
  -- XSGROUP 17.11.2006
  --
  -- функция возвращает сальдо по по всем обязательства операции движения,
  -- заданной параметром:   AMoveSet_ID  - ID операции движения
  -- на 24.00 даты:         ABalanceDate                       
  -- при значениях параметра WhatsNeed:
  --                       'PAY'    - рассчитывается сумма платежей. начислений или сальдо по обязательству
  --                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене

  RetVal:=0;

  for xx in (select ch.obligationtype_id OTID from sm.charges ch where ch.movesets_id=AMoveSet_ID
             union
             select p.obligationtype_id OTID from sm.payments p where p.movesets_id=AMoveSet_ID)
  loop
   
    RetVal:=RetVal+sm.calcfine(ABalanceDate,AMoveSet_ID,xx.OTID,WhatsNeed,'ALL');
   
  end loop;

  IF RetVal IS NULL THEN
    RetVal:=0;
  END IF;

  return(RetVal);
  
end;
/
grant execute on SM.GETMOVEBALANCE to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCE to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEBALANCEALL
prompt ===================================
prompt
create or replace function sm.GetMoveBalanceAll(AMoveSet_ID NUMBER, ADate IN DATE default SYSDATE, AOblType_id IN NUMBER default NULL) return number
is
  charged number(27,2):=0.0;
  payed number(27,2):=0.0;
  CalcDate date;
  distr integer :=0;

BEGIN
/*23/07/2015 Твердохлеб: добавил входной параметр Тип обязательства*/

 CalcDate:=trunc(ADate+1);


select nvl(sum(PaySize),0)  into Charged
from  sm.charges c
where  Movesets_id=AMoveSet_id  and
  CHARGEDATE<CalcDate
  and (c.obligationtype_id = AOblType_id or AOblType_id is null);

select
  --+ index(pp IDX_PMNT_MOVESET_ID)
  nvl(sum(pp.sum),0)  into Payed
from  sm.payments pp
where  pp.Movesets_Id=AMoveSet_ID
  and sm.Getpaydateforpayment(pp.id)<CalcDate  -- <<<!!! TO OPTIMIZE
  -- and pp.APPLY_DATE<CalcDate  -- НЕ ГОДИТСЯ (пользователи делают  ошибки-расхождения дат, а результат вылазит совсем в другом месте...)
  and (pp.obligationtype_id = AOblType_id or AOblType_id is null);

RETURN Payed - Charged;
END;
/
grant execute on SM.GETMOVEBALANCEALL to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCEALL to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEBALANCEDETAIL
prompt ======================================
prompt
create or replace function sm.GetMoveBalanceDetail(AMoveSet_ID NUMBER, WhatsNeed VARCHAR2, ABalanceDate IN DATE, WhatsCalc IN STRING default 'ALL') return number is
  RetVal number(27,2);

  Charged number(27,2);
  Payed number(27,2);
 
begin
  --
  -- XSGROUP 14.12.2009
  --
  -- функция возвращает сальдо по по всем обязательства операции движения,
  -- заданной параметром:   AMoveSet_ID  - ID операции движения
  -- на 24.00 даты:         ABalanceDate                       
  -- при значениях параметра WhatsNeed:
  --                       'PAY'    - рассчитывается сумма платежей. начислений или сальдо по обязательству
  --                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене
  -- при значениях параметра WhatsCalc:
  --                       'PAY'    - рассчитывается сумма платежей
  --                       'CHARGE' - расчитывается сумма начислений
  --                       'ALL'    - рассчитывается сальдо
  --
  
  RetVal:=0;

  for xx in (select ch.obligationtype_id OTID from sm.charges ch where ch.movesets_id=AMoveSet_ID
             union
             select p.obligationtype_id OTID from sm.payments p where p.movesets_id=AMoveSet_ID)
  loop
   
    RetVal:=RetVal+sm.calcfine(ABalanceDate,AMoveSet_ID,xx.OTID,WhatsNeed,WhatsCalc);
   
  end loop;

  IF RetVal IS NULL THEN
    RetVal:=0;
  END IF;

  return(RetVal);
  
end;
/
grant execute on SM.GETMOVEBALANCEDETAIL to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCEDETAIL to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEBALANCEOBLTYPE
prompt =======================================
prompt
create or replace function sm.GetMoveBalanceOblType(AMoveSet_ID NUMBER, WhatsNeed VARCHAR2, ABalanceDate IN DATE default SYSDATE, AOblType_id IN NUMBER) return number is
  RetVal number(27,2);

  Charged number(27,2);
  Payed number(27,2);
 
begin
  /* 23/07/2015 Твердохлеб: является копией функци GetMoveBalance, но на вход еще получает тип обязательства*/
  --
  -- XSGROUP 17.11.2006
  --
  -- функция возвращает сальдо по по всем обязательства операции движения,
  -- заданной параметром:   AMoveSet_ID  - ID операции движения
  -- на 24.00 даты:         ABalanceDate                       
  -- при значениях параметра WhatsNeed:
  --                       'PAY'    - рассчитывается сумма платежей. начислений или сальдо по обязательству
  --                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене
 
 RetVal:=0;

  for xx in (select ch.obligationtype_id OTID 
               from sm.charges ch 
              where ch.movesets_id = AMoveSet_ID
                and (ch.obligationtype_id = AOblType_id or AOblType_id is null)
             union
             select p.obligationtype_id OTID 
               from sm.payments p 
              where p.movesets_id = AMoveSet_ID
                and (p.obligationtype_id = AOblType_id or AOblType_id is null)
              )
  loop
   
    RetVal:=RetVal+sm.calcfine(ABalanceDate,AMoveSet_ID,xx.OTID,WhatsNeed,'ALL');
   
  end loop;

  IF RetVal IS NULL THEN
    RetVal:=0;
  END IF;

  return(RetVal);
  
end;
/
grant execute on SM.GETMOVEBALANCEOBLTYPE to SM_ALLUSERS;
grant execute on SM.GETMOVEBALANCEOBLTYPE to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVECHARGESBYPER
prompt =====================================
prompt
create or replace function sm.GetMoveChargesByPer(AMoveSet_ID NUMBER, StartDate DATE, EndDate DATE, AOblType_id NUMBER, Ch_Type char default null) return number
is
  charged number(27,2):=0.0;

BEGIN
/*01/11/2023 Чувыкин: функция возвращает начисления по заданной операции движения, по заданному типу обязательству из нее, за заданный период*/

if Ch_Type is null then
  begin
    select nvl(sum(PaySize),0)  into Charged
    from  sm.charges c
    where  Movesets_id=AMoveSet_id
      and CHARGEDATE>=StartDate
      and CHARGEDATE<=EndDate
      and (c.obligationtype_id = AOblType_id);
  end;
end if;

if Ch_Type = '1' then
  begin
    select nvl(sum(PaySize),0)  into Charged
    from  sm.charges c
    where  Movesets_id=AMoveSet_id
      and CHARGEDATE>=StartDate
      and CHARGEDATE<=EndDate
      and (c.obligationtype_id = AOblType_id)
      and (c.charge_type = 'OBLIGATION');
  end;
end if;

if Ch_Type = '2' then
  begin
    select nvl(sum(PaySize),0)  into Charged
    from  sm.charges c
    where  Movesets_id=AMoveSet_id
      and CHARGEDATE>=StartDate
      and CHARGEDATE<=EndDate
      and (c.obligationtype_id = AOblType_id)
      and (c.charge_type = 'FINE');
  end;
end if;

RETURN Charged;
END;
/
grant execute on SM.GETMOVECHARGESBYPER to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEDESCRIPTION
prompt ====================================
prompt
create or replace function sm.GetMoveDescription(AMovementsID number) return varchar2 is
  Result varchar2(4000);

-- by XSGROUP 15.10.2012
-- Edit 11.08.2014 (4.8.5) opt.
--
-- Функция формирует описание движения для отображения в столбце Операция на вкладке Движение окна свойств Объекта
-- AMovementsID - значение поля ID из View MOVWMENTS
--
--
  MT_NAME sm.movetype.name%type;
begin
  select
     MoveType.Name
  into
     MT_NAME
  from
    SM.MoveType,
    sm.movesets ms,
    sm.moveperiods mp,
    sm.moveitems mi
  where
    ms.id=mp.moveset_id and
    mp.id=mi.moveperiod_id and
    ms.movetype_id=MoveType.ID and
    mi.id=AMovementsID and rownum=1;

    Result:=trim(MT_NAME);
  return(Result);
end;
/
grant execute on SM.GETMOVEDESCRIPTION to SM_ALLUSERS;
grant execute on SM.GETMOVEDESCRIPTION to SM_ALL_SELECT;


