prompt Creating function GETMOVEMENTSINDICATOR
prompt =======================================
prompt
create or replace function sm.GetMovementsIndicator(MoveID IN NUMBER) RETURN NUMBER
is
 Result number;
 ST1 DATE;
 ST2 DATE;
Begin
 Result:=0;

 select mp.sincedate, mp.enddate 
 INTO ST1, ST2 
 from 
  sm.moveperiods mp,
  sm.moveitems mi 
 where 
  mp.id=mi.moveperiod_id and
  mi.id=MoveID;
  
 if (ST1<=SYSDATE) and (ST2 IS NULL or ST2>=SYSDATE) THEN
  Result:=0;
 ELSE
  Result:=7;
 END IF;

 return(Result);
 exception
  when NO_DATA_FOUND then return(9); -- красный
End;
