prompt
prompt Creating function GETMOVEOBJECT
prompt ===============================
prompt
create or replace function sm.GetMoveObject(Flag varchar2, AObject_id number, Adate date, AFullDoc varchar2, ListMoveId varchar2)
return TypeMoveExtractObjectList pipelined as
ADateReq date;
ANumber number(27);
Name_move varchar2(255);
Period varchar2(255);
Address varchar2(510);
Docs varchar2(3000);
j number(27);
begin
  /* 22/10/2013 Твердохлеб: Возвращает список ОД для объекта:
     Flag: 1 - все ОД
           2 - текущие ОД
     AFullDoc: 1 - Только основной документ
               2 - все документы
  */
  --raise_application_error(-20000, ListMoveId || 'qqq');
  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  ANumber := 0;
  for i in (
                select mv.movetype_id,
                       mp.sincedate,
                       mp.enddate,
                       t.name,
                       c.name as fullname,
                       mp.docset_id,
                       mt.name as name_move
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id
                  join sm.movetype mt on mt.id = mv.movetype_id
                  left join sm.transferbasis t on t.id = mv.transferbasis_id
                  left join clients c on c.id = mv.client_id
                 where (
                        Flag = '1'
                        or
                        Flag = '2' and mp.sincedate <= ADateReq and (mp.enddate >= ADateReq or mp.enddate is null)
                       )
                   and o.id = Aobject_id
                   -- and mv.movetype_id in (1,2,10,19,17,18,14,28,27)
                   and INSTR(','|| ListMoveId ||',',','|| mv.movetype_id ||',',1,1) <> 0 -- ищем нужные ОД
              order by 2,1
     )
 loop
   ANumber := ANumber + 1;
   Name_move := i.name_move;
   if (i.movetype_id = 1) then
     Name_move := 'Передача в собственность';
   elsif (i.movetype_id = 2) then
     Name_move := 'Передача на баланс(' || i.name || ')';
   elsif (i.movetype_id = 10) then
     Name_move := 'Передача в казну';
   elsif (i.movetype_id = 19) then
     Name_move := 'Списание (исключение из Реестра)';
   elsif (i.movetype_id = 28) then
     Name_move := '«Фонд особо ценного имущества» - Включение в перечень особо ценного движимого имущества';
   elsif (i.movetype_id = 17) then
     Name_move := 'Определение статуса жилищного фонда(' || i.name || ')';
   elsif (i.movetype_id = 18) then
     Name_move := 'Включение в маневренный фонд';
   elsif (i.movetype_id = 14) then
     Name_move := 'Передача на хранение';
   else
     Name_move := i.name_move;
   end if;
   Period := to_char(i.sincedate, 'DD.MM.YYYY');
   if i.enddate is not null then
      Period := Period || ' - ' || to_char(i.enddate, 'DD.MM.YYYY');
   end if;
   Address := i.fullname;
   Docs := '';
   j := 1;
   for docs_ IN (
                 select sm.expanddoc(dm.document_id) doc
                   from sm.docset_members dm
                   join sm.documents d on d.id = dm.document_id
                  where dm.docset_id = i.docset_id
                    and (AFullDoc = '1' and dm.docrole_id = 1 or AFullDoc = '2')
               order by d.DOCDATE
                )
   loop
      Docs := Docs || to_char(j)||'. '||docs_.doc||chr(13);
      j := j + 1;
   end loop;
   pipe row (TypeMoveExtractObject(ANumber, Name_move, Period, Address, Docs, i.sincedate));
  end loop;
 return;
end;
/
grant execute on SM.GETMOVEOBJECT to SM_ALLUSERS;
grant execute on SM.GETMOVEOBJECT to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVEPAYSBYPER
prompt ==================================
prompt
create or replace function sm.GetMovePaysByPer(AMoveSet_ID NUMBER, StartDate DATE, EndDate DATE, AOblType_id NUMBER, Ch_Type char default null) return number
is
  Payed number(27,2):=0.0;

BEGIN
/*01/11/2023 Чувыкин: функция возвращает платежи по заданной операции движения, по заданному типу обязательству из нее, за заданный период*/

if Ch_Type is null then
  begin
    select
      nvl(sum(pp.sum),0)  into Payed
    from sm.payments pp
    where pp.Movesets_Id=AMoveSet_id
      and sm.Getpaydateforpayment(pp.id)>=StartDate
      and sm.Getpaydateforpayment(pp.id)<=EndDate
      and (pp.obligationtype_id = AOblType_id);
  end;
end if;

if Ch_Type = '1' then
  begin
    select
      nvl(sum(pp.sum),0)  into Payed
    from sm.payments pp
    where pp.Movesets_Id=AMoveSet_id
      and sm.Getpaydateforpayment(pp.id)>=StartDate
      and sm.Getpaydateforpayment(pp.id)<=EndDate
      and (pp.obligationtype_id = AOblType_id)
      and (pp.mainpay = 'Y');
  end;
end if;

if Ch_Type = '2' then
  begin
    select
      nvl(sum(pp.sum),0)  into Payed
    from sm.payments pp
    where pp.Movesets_Id=AMoveSet_id
      and sm.Getpaydateforpayment(pp.id)>=StartDate
      and sm.Getpaydateforpayment(pp.id)<=EndDate
      and (pp.obligationtype_id = AOblType_id)
      and (pp.mainpay = 'N');
  end;
end if;


RETURN Payed;
END;
/
grant execute on SM.GETMOVEPAYSBYPER to SM_ALLUSERS;


prompt
prompt Creating function GETMOVEPERIODMAINDOCID
prompt ========================================
prompt
create or replace function sm.GetMovePeriodMainDocID(A_moveperiodID number) return number is

--
-- by XSGROUP 17.09.2014
--
  Result number;
  DSID number;
begin
  Result:=null;
  
   begin
    select
      mp.docset_id
    into
      DSID
    from
      sm.moveperiods mp
    where
      mp.id=A_moveperiodID;
      
   exception
     when NO_DATA_FOUND then
       null;
   end;
  

  if DSID is null then
    return (0);
  end if;

  -- находим первый документ, которому присвоена роль=1 ("Основной документ")
  select
    document_id
  into
    Result
  from
    sm.docset_members dsm
  where
    rownum=1 and
    dsm.docrole_id=1 and
    dsm.docset_id=DSID; 

  return(nvl(Result,0));

end GetMovePeriodMainDocID;
/
grant execute on SM.GETMOVEPERIODMAINDOCID to SM_ALLUSERS;
grant execute on SM.GETMOVEPERIODMAINDOCID to SM_ALL_SELECT;


