prompt
create or replace function sm.GetMovePeriodDocDescr(A_MovePeriodID number) return varchar2
is

DocID number(27);
Retval varchar2(4000);
begin
 Retval:='';
  if A_MovePeriodID is null then return null; end if;
  
  DocID:=sm.GetMovePeriodMainDocID(A_MovePeriodID);
  if nvl(DocID,-1)<>-1 then 
   Retval:=sm.GetDocDescription(DocID);   
  end if;
return Retval;  
exception
 when others then return null;  
end;
