prompt
prompt Creating function GETMOVESETMAINDOCID
prompt =====================================
prompt
create or replace function sm.GetMoveSetMainDocID(AMoveSetID number) return number is

--
-- by XSGROUP 26.12.2005
--
-- Функция возврата ID основного документа для операции движения
-- AMoveSetID - значение поля ID из таблицы MoveSets
--
-- Сначала производится попытка найти документ, в названии типа которого
-- имеется слово 'ДОГОВОР', если такой документ в пакете имеется, 
-- возвращается ID этого документа;
-- если такой документ в пакете отсутствует,
-- возвращается ID документа, docrole_id которого = 1
-- (главного документа пакета)
--


  Result number;

begin

  Result:=null;
  
  begin
    select 
      dsm.document_id 
    into
      Result  
    from 
      sm.docset_members dsm,
      sm.documents doc,
      sm.doctypes dt 
    where
      rownum=1 and
      dsm.document_id=doc.id and
      dt.id=doc.doctypes_id and
      dsm.docrole_id=1 and 
-- Исправил Андрей Владимирович Солопко (26.05.2006)
--      UPPER(dt.name) like '%ДОГОВОР%' and
      dsm.docset_id=(select ms.docset_id 
                     from sm.MoveSets ms
                     where ms.id=AMoveSetID);
  exception
    when NO_DATA_FOUND then
      select 
        document_id 
      into
        Result  
      from 
        sm.docset_members dsm 
      where
        rownum=1 and
        dsm.docrole_id=1 and 
        dsm.docset_id=(select ms.docset_id 
                       from sm.MoveSets ms
                       where ms.id=AMoveSetID);
  end;
                   
  return(nvl(Result,0));
  
end GetMoveSetMainDocID;
/
grant execute on SM.GETMOVESETMAINDOCID to SM_ALLUSERS;
grant execute on SM.GETMOVESETMAINDOCID to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVESETMAINDOCDESCRIPTION
prompt ==============================================
prompt
create or replace function sm.GetMoveSetMainDocDescription(AMoveSetID number) return varchar2 is
 
-- by XSGROUP 11.03.2009
--
-- Функция возврата описания основного документа операции движения
-- AMoveSetID - значение поля ID из таблицы MoveSets
-- 
 Result     varchar2(4000);
 MainDocID  number;
 
 DocType    doctypes.name%type;        -- тип документа
 DocNo      documents.docno%type;      -- номер документа
 DocDate    documents.docdate%type;    -- дата документа
 DateStart  documents.date_start%type; -- дата начала договора
 DateEnd    documents.date_end%type;   -- дата окончания договора
 
 DefaultDocNo varchar2(60);
 MaxLen     number:=50;
 GUID       sm.doctypes.guid%type; 
begin
  
  MainDocID:=sm.GetMoveSetMainDocID(AMoveSetID);
  
  DefaultDocNo:=RTRIM(LTRIM(sm.getparameter('DEFAULT_DOCNUM')));
  
  select
    dt.NAME, 
    doc.Docno, 
    doc.Docdate,
    doc.date_start,
    doc.date_end,
    dt.GUID 
  INTO
    DocType,
    DocNo,
    DocDate,
    DateStart,  
    DateEnd,
    GUID    
  from
    Documents doc,
    DocTypes  dt
  where
    dt.ID=doc.Doctypes_Id and
    doc.ID=MainDocID;
  
  if GUID='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE' then
    -- особый случай - Неизвестный документ
    Result:='<Неизвестный документ>';
  else
    -- все прочие типы документов
    Result:=RTRIM(LTRIM(DocType));
    if length(Result)>MaxLen then
      Result:=RTRIM(LTRIM(SUBSTR(Result,1,MaxLen-2)))||'..';
    end if;
    
    if not DefaultDocNo is null then
      if RTRIM(LTRIM(DocNo))<>DefaultDocNo then
        Result:=Result||' №'||RTRIM(LTRIM(DocNo));
      end if;  
    end if;
    
    Result:=Result||' от '||to_char(DocDate,'DD.MM.YYYY');
    
    if DateStart is not null then
      Result:=Result||', действует с '||to_char(DateStart,'DD.MM.YYYY');
      
      if DateEnd is not null then
        Result:=Result||' по '||to_char(DateEnd,'DD.MM.YYYY');
      end if;  
    end if; 
  end if;
  
  return(nvl(Result,''));
  
end GetMoveSetMainDocDescription;
/
grant execute on SM.GETMOVESETMAINDOCDESCRIPTION to SM_ALLUSERS;
grant execute on SM.GETMOVESETMAINDOCDESCRIPTION to SM_ALL_SELECT;


prompt
prompt Creating function GETMOVESETMAINDOCPERSACC
prompt ==========================================
prompt
create or replace function sm.GetMoveSetMainDocPersAcc(AMoveSetID number) return varchar2 is


-- Функция возврата Лицевого счета из основного документа операции движения
-- AMoveSetID - значение поля ID из таблицы MoveSets
--
 Result     varchar2(4000);
 MainDocID  number;

 DocType    doctypes.name%type;        -- тип документа
 DocNo      documents.docno%type;      -- номер документа
 DocDate    documents.docdate%type;    -- дата документа
 DateStart  documents.date_start%type; -- дата начала договора
 DateEnd    documents.date_end%type;   -- дата окончания договора
 PersAccount    documents.pers_account%type;   -- дата окончания договора

 DefaultDocNo varchar2(60);
 MaxLen     number:=50;
 GUID       sm.doctypes.guid%type;
begin

  MainDocID:=sm.GetMoveSetMainDocID(AMoveSetID);

  DefaultDocNo:=RTRIM(LTRIM(sm.getparameter('DEFAULT_DOCNUM')));

  select
    dt.NAME,
    doc.Docno,
    doc.Docdate,
    doc.date_start,
    doc.date_end,
    doc.pers_account,
    dt.GUID
  INTO
    DocType,
    DocNo,
    DocDate,
    DateStart,
    DateEnd,
    PersAccount,
    GUID
  from
    Documents doc,
    DocTypes  dt
  where
    dt.ID=doc.Doctypes_Id and
    doc.ID=MainDocID;

  if GUID='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE' then
    -- особый случай - Неизвестный документ
    Result:='<Неизвестный документ>';
  else
    -- все прочие типы документов
    Result:=PersAccount;
  end if;

  return(nvl(Result,''));

end GetMoveSetMainDocPersAcc;
