prompt =========================================
prompt
create or replace function sm.GetMoveSetMainDocUst_AS(AMoveSetID number) return varchar2 is
-- 
--   Andrey Solopko (Andy Solo)
--       Krasnodar, Russia
-- E-mail: andrey_solopko@mail.ru
--  An Andy Solo Company Release
-- 
 Result     varchar2(4000);
 MainDocID  number;
 
 DocNo      documents.ust_date_num%type;    
 DocDate    documents.ust_date_start%type;  
 
 DefaultDocNo varchar2(60);
 MaxLen     number:=50; 
begin
  
  MainDocID:=sm.GetMoveSetMainDocID(AMoveSetID);
  
  DefaultDocNo:=RTRIM(LTRIM(sm.getparameter('DEFAULT_DOCNUM')));
  
  select
    doc.ust_date_num, 
    doc.ust_date_start
  INTO
    DocNo,
    DocDate
  from
    Documents doc,
    DocTypes  dt
  where
    dt.ID=doc.Doctypes_Id and
    doc.ID=MainDocID;
  
  Result:='';

  if DocDate is not null then
    Result:=Result||'Договор зарегистрирован в юстиции с '||to_char(DocDate,'DD.MM.YYYY');
    
  if not DefaultDocNo is null then
    if RTRIM(LTRIM(DocNo))<>DefaultDocNo then
      Result:=Result||' под №'||RTRIM(LTRIM(DocNo));
    end if;  
  end if;

  else
    Result:='Договор в юстиции не зарегистрирован.';
  end if; 

  return(nvl(Result,''));
  
end GetMoveSetMainDocUst_AS;
/
