prompt
prompt Creating function GETMOVE_SQ_AS
prompt ===============================
prompt
create or replace function sm.GetMove_SQ_AS(APerID IN NUMBER, AObjTyp IN NUMBER) return number is
  res number;
  tempres number;
-- Разработал Андрей Владимирович Солопко (14.06.2006)
begin
  res:= 0;
  for r in
    (select mi.id
    from sm.moveitems mi
    where mi.moveperiod_id = APerID)
    loop
      begin
        select
          nvl(sum(ou.square), 0) into tempres
        from
          sm.objectusing ou, sm.moveitems mi,
          sm.movements mv, sm.objects ob
        where
          ou.moveitem_id = mi.id and
          mv.MoveItem_ID = mi.id and
          mv.OBJECTS_ID = ob.id and
          ob.objtypes_id = AObjTyp and
          ou.moveitem_id = r.id;
      end;
      res:= res + tempres;
    end loop;
  return(nvl(res, 0));
end;
/
grant execute on SM.GETMOVE_SQ_AS to SM_ALLUSERS;
grant execute on SM.GETMOVE_SQ_AS to SM_ALL_SELECT;


