prompt
prompt Creating function GETOBJECTCOST
prompt ===============================
prompt
create or replace function sm.GetObjectCost(OBJ_ID IN NUMBER, COST_DATE IN DATE, COST_TYPE IN CHARACTER) RETURN NUMBER
--возвращает финансовые параметры имущества на заданный момент

-- Ver. 4.8.5 (24.03.2015)
-- !! расчет амортизации производится только для имущества с известной нормой амортизации
-- расчет амортизации производится линейным методом

-- 12/04/2013 Твердохлеб: добавил обработку флага D
-- 18/06/2013 Чувыкин: округление результата до сотых при флаге D
-- 02/07/2013 Твердохлеб: добавил обработку флага F - рыночная стоимость с учетом доли

-- OBJ_ID - ID объекта
-- COST_DATE - дата расчета стоимости
-- COST_TYPE - 'B' - первоначальная (восстановительная) стоимость (балансовая), 
--             'R' - остаточная стоимость
--             'T' - оценочная стоимость
--             'W' - износ в рублях
--             'P' - износ в процентах
--             'U' - удельный показатель кадастровой стоимости земельного участка (УПКСЗ) 
--             'K' - кадастровая стоимость (для ЗУ)
--             'L' - стоимость земельного участка
--             'D' - кадастровая стоимость с учетом доли (для ЗУ)
--             'F' - рыночная стоимость с учетом доли (для ЗУ)
--             'G' - первоначальная стоимость с учетом доли (для ЗУ)
IS
 bl number(27,2);
 r number(27,2);
 c number(27,6);
 d DATE;
 StatesID number(27);
 StatesDate date;
 gr_sq sm.grounds.square%type;
 l_wearnorm sm.objects.wearnorm%type;
 l_calcdate sm.states.calcdate%type;
 l_startpay sm.states.startpay%type;
 l_pay sm.states.pay%type;
 l_ratable sm.states.ratable%type;
 l_kadastr_cost sm.states.kadastr_cost%type;
 l_cadastralvalue sm.states.cadastralvalue%type; 
 l_IS_USING char(1);
 l_wearcalcmethod_id sm.objects.wearcalcmethod_id%type;
 l_obTypeID sm.objects.objtypes_id%type;
 l_wear sm.states.wear%type;
 l_cost_land sm.states.cost_land%type;
 Ashare_num sm.moveitems.share_num%type;
 Ashare_denom sm.moveitems.share_denom%type; 
begin
 d:=trunc(cost_date);
 c:=null;
  begin
   select max(s.calcdate) into StatesDate
   from sm.states s where s.objects_id=OBJ_ID
   and s.calcdate<=d;

   select s.id into StatesID
   from sm.states s where s.objects_id=OBJ_ID and
   s.calcdate=StatesDate;
  exception
    when others then null;
  end;
  
 if StatesID is not null then  
  begin
   select
     objects.objtypes_id,
     objects.wearnorm,
     states.calcdate,
     states.startpay,
     states.pay,
     states.ratable,
     IS_USING,
     wearcalcmethod_id,
     states.kadastr_cost,
     states.cadastralvalue,
     states.wear,
     states.cost_land
   into
     l_obTypeID,
     l_wearnorm,
     l_calcdate,
     l_startpay,
     l_pay,
     l_ratable,
     l_IS_USING,
     l_wearcalcmethod_id,
     l_kadastr_cost,
     l_cadastralvalue,    
     l_wear,
     l_cost_land
   from
     sm.states,
     sm.objects
   where
     objects.id=states.objects_id and
     states.id=StatesID;
     
   if (l_wearnorm IS NULL) or (l_IS_USING='N') then
    r:=l_pay;
   else
     if l_wearcalcmethod_id=1 then 
       -- норма амортизации установлена от остаточной стоимости
       r:=l_pay-(l_pay*((l_wearnorm/100)/12))*trunc(MONTHS_BETWEEN(d,l_calcdate));
     else
       -- норма амортизации установлена от первоначальной (восстановительной) стоимости 
       r:=l_pay-(l_startpay*((l_wearnorm/100)/12))*trunc(MONTHS_BETWEEN(d,l_calcdate));
     end if;
   end if; 

   if (r<0) then
     r:=0.00;
   end if;
    
   bl:=l_startpay;
   
  if COST_TYPE='T' then
   c:=l_ratable;  
  elsif COST_TYPE='R' then
   c:=r;
  elsif COST_TYPE='B' then
   c:=bl;
   --if bl=0 then --comment Ver. апрель.2012
   -- c:=null; --comment Ver. апрель.2012
   --end if; --comment Ver. апрель.2012
  elsif COST_TYPE='W' then     
      c:=bl-r;
  elsif COST_TYPE='P' then
    if l_obTypeID=4 then 
     return l_wear;
    else
   --if bl=0 then --comment Ver. апрель.2012
   -- c:=null; --comment Ver. апрель.2012
   --else --comment Ver. апрель.2012
     if (bl <> 0) then
       c:=((bl-r)/bl)*100;
     end if;
    end if;    
  elsif COST_TYPE='U' then
   c:=l_kadastr_cost;
  elsif COST_TYPE='K' then
   if l_cadastralvalue is not null then
     c:=l_cadastralvalue;
   elsif l_kadastr_cost is not null then
     select
       g.square
     into
       gr_sq
     from
       sm.grounds g
     where
       g.objects_id=obj_id;
     if gr_sq is null then
       return null;
     else
       c:=round(gr_sq*l_kadastr_cost,2);  
     end if;    
   end if;   
   elsif COST_TYPE='D' then
   c := 0; 
   -- получим кадастровую стоимость 
   Select sm.GetObjectCost(OBJ_ID,COST_DATE,'K')
     into c 
     from dual;
   Ashare_num := 1;
   Ashare_denom := 1;
   begin
       select m.share_num,
              m.share_denom
         into Ashare_num,
              Ashare_denom     
         from sm.movements m
        where m.MoveType_ID = 1
          and m.POSTINGDATE <= COST_DATE
          and (m.EndDate >= COST_DATE or m.EndDate is null) 
          and m.OBJECTS_ID = OBJ_ID 
          and rownum < 2;
       exception
       when NO_DATA_FOUND then
       null;           
   end;   
   c:= c * Ashare_num / Ashare_denom; 
   c := round(c,2);     
  elsif COST_TYPE='F' then
     Ashare_num := 1;
     Ashare_denom := 1;
     begin
       select m.share_num,
              m.share_denom
         into Ashare_num,
              Ashare_denom     
         from sm.movements m
        where m.MoveType_ID = 1
          and m.POSTINGDATE <= COST_DATE
          and (m.EndDate >= COST_DATE or m.EndDate is null) 
          and m.OBJECTS_ID = OBJ_ID 
          and rownum < 2;
       exception
       when NO_DATA_FOUND then
       null;           
     end;   
     c := l_ratable;
     c := c * Ashare_num / Ashare_denom; 
     c := round(c, 2);  
     if c is null then
       c := 0; 
     end if;
  elsif COST_TYPE='G' then
     c := NULL;
     Select sm.GetObjectCost(OBJ_ID,COST_DATE,'D')
      into c 
      from dual; 
     if c is null or c = 0 then
       Select sm.GetObjectCost(OBJ_ID,COST_DATE,'F')
        into c 
        from dual; 
     end if;              
  elsif COST_TYPE='L' then
     c := l_cost_land;
  end if;
  
  if c is not null  then
   return c;   
  end if;
exception
  when others then null;
end;  
end if;  

 
 return c;
end;
/
grant execute on SM.GETOBJECTCOST to SM_ALLUSERS;
grant execute on SM.GETOBJECTCOST to SM_ALL_SELECT;


prompt
prompt Creating function ISOBJINTREASURY
prompt =================================
prompt
create or replace function sm.IsObjInTreasury(ObjID in NUMBER, DateApply in DATE) return CHAR is
  Result CHAR(1) := 'N';
  mdID NUMBER := 0;
  mcID NUMBER := 0;
  aMvType CHAR(1)  := 'C';
  begDate Date;
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция Определяет в Казне ли объект на заданную дату ПО ОПЕРАТИВНЫМ ДАННЫМ
---------------------
  --ищем приход в казну
  BEGIN                  
            Select  zzz.ID, zzz.SINCEDATE  into mdID, begDate
            from (Select ms.ID, mp.SINCEDATE 
                      from SM.MOVESETS ms 
                      inner join SM.MOVEPERIODS mp on mp.MOVESET_ID = ms.ID
                      inner join SM.MOVEITEMS mi on mi.MOVEPERIOD_ID = mp.ID
                      where mi.OBJECT_ID = ObjID
                          and mp.SINCEDATE < DateApply            
                          --and NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) >= DateApply        --and (mp.ENDDATE >= DateApply  or mp.ENDDATE IS NULL)
                          and exists (Select mt.ID from SM.MOVETYPE mt where mt.ID=ms.MOVETYPE_ID and mt.ISTREASURY = 'D')
                        --  and ms.CLIENT_ID=(select distinct VALUE FROM sm.SM_SETTINGS WHERE UPPER(sm.SM_SETTINGS.KEY_NAME)='KUMI_ID')
                      order by mp.SINCEDATE desc, NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) desc, mp.WRITEDATE desc, mp.ID desc) zzz 
             where ROWNUM=1;                                        
  EXCEPTION
         When NO_DATA_FOUND then
                NULL;
  END;
  
  if (mdID >0) then
    --ищем выход их казны
    BEGIN                  
              Select zzz.ID  into mcID
              from (Select ms.ID 
              from SM.MOVESETS ms 
              inner join SM.MOVEPERIODS mp on mp.MOVESET_ID = ms.ID
              inner join SM.MOVEITEMS mi on mi.MOVEPERIOD_ID = mp.ID
              where mi.OBJECT_ID = ObjID
                  and mp.SINCEDATE < DateApply and mp.SINCEDATE >= begDate 
                  and exists (Select mt.ID from SM.MOVETYPE mt where mt.ID=ms.MOVETYPE_ID and mt.ISTREASURY='C')
                  and ms.CLIENT_ID<>(select distinct VALUE FROM sm.SM_SETTINGS WHERE UPPER(sm.SM_SETTINGS.KEY_NAME)='KUMI_ID')
                  order by mp.SINCEDATE desc, NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) desc, mp.WRITEDATE desc, mp.ID desc) zzz 
              where ROWNUM=1;
    EXCEPTION
           When NO_DATA_FOUND then
                  NULL;
    END;  
    
    if (mcID > 0) then
      Result := 'N';
    else
      Result := 'Y';
    end if; 
    
  end if;  
  
  return(Result);

end IsObjInTreasury;
/
grant execute on SM.ISOBJINTREASURY to SM_ALLUSERS;
grant execute on SM.ISOBJINTREASURY to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCBEG
prompt ==============================
prompt
create or replace function sm.GetObjAccBeg(ObjID in NUMBER, DateBeg in DATE, caca VARCHAR2) return NUMBER is
  Result NUMBER(29,2);
  bOk CHAR(1) := 'N';
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает начальную стоимость объекта по ОПЕРАТИВНЫМ ДАННЫМ  по определенному счету на определенную дату.
--    параметр ObjID - ID объекта учета
--    параметр DateBeg - дата
--    параметр caca - счет бухгалтерский. В ряде случаев только часть счета
---------------------
  Result := 0;

   BEGIN    
            --ПО СТЕЙТАМ
            --Определяем, в казне ли объект
            Select sm.IsObjInTreasury(ObjID, DateBeg)  into bOk from dual;             
            --Если в казне, то стоимость объекта определяем по ближайшему стейту на заданную дату. Если не в казне, то стоимость ноль.
            if (bOk = 'Y') then
                if (caca like '%104%') then
                      Select inst.cost  into Result
                      from ( Select (-1)*(NVL(st.STARTPAY,NVL(sm.GetObjectCost(ObjID, DateBeg, 'K'),0)) - NVL(NVL(st.PAY,st.STARTPAY),NVL(sm.GetObjectCost(ObjID, DateBeg, 'K'),0))) as cost
                           from  SM.STATES st where st.OBJECTS_ID = ObjID and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0
                           and
                           ( st.CALCDATE = (Select MAX(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = ObjID and stt.CALCDATE <= DateBeg and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0)
                           OR
                           st.CALCDATE = (Select MIN(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = ObjID and stt.CALCDATE > DateBeg and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0) )
                           order by st.CALCDATE ) inst
                      where ROWNUM = 1;
                else
                      Select inst.cost  into Result
                      from ( Select NVL(st.STARTPAY,NVL(sm.GetObjectCost(ObjID, DateBeg, 'K'),0)) as cost
                           from  SM.STATES st where st.OBJECTS_ID = ObjID and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0
                           and
                           ( st.CALCDATE = (Select MAX(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = ObjID and stt.CALCDATE <= DateBeg and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0)
                           OR
                           st.CALCDATE = (Select MIN(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = ObjID and stt.CALCDATE > DateBeg and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0) )
                           order by st.CALCDATE ) inst
                      where ROWNUM = 1;
                end if;                
            end if;                  
            ------------------------------------------            
  EXCEPTION
         When NO_DATA_FOUND then
                NULL;
  END;
  return(NVL(Result,0));

end GetObjAccBeg;
/
grant execute on SM.GETOBJACCBEG to SM_ALLUSERS;
grant execute on SM.GETOBJACCBEG to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCBEGACC
prompt =================================
prompt
create or replace function sm.GetObjAccBegAcc(ObjID in NUMBER, DateBeg in DATE, caca VARCHAR2) return NUMBER is
  Result NUMBER(29,2);
  bOk CHAR(1) := 'N';
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает начальную стоимость объекта по определенному счету на определенную дату.
--    параметр ObjID - ID объекта учета
--    параметр DateBeg - дата
--    параметр caca - счет бухгалтерский. В ряде случаев только часть счета
---------------------
  Result := 0;

   BEGIN    
            --ПО УЧЕТНЫМ ДАННЫМ
            Select macaca.SALDO into Result
            from ( Select maca.SALDO, maca.DC 
                         from (Select mac.SALDO, mac.DC from SM.MOVE_ACC mac 
                                      where mac.OBJECT_ID = ObjID 
                                      and  (mac.APPLY_DATE < DateBeg   )-- OR (mac.APPLY_DATE = DateBeg-1 and mac.reversal_role = 'Сторнирующая (красн.)') OR (mac.APPLY_DATE = DateBeg-1 and mac.reversal_role = 'Исправляющая'))
                                      and  substr(mac.ACC,1,length(caca))=caca
                                      order by mac.APPLY_DATE desc, mac.OPER_DATE desc, mac.END_DATE desc, NVL(mac.MOVEITEM_ID, 0) desc, mac.WRITE_DATE desc , mac.ID desc) maca
                        where ROWNUM = 1 ) macaca;
  EXCEPTION
         When NO_DATA_FOUND then
                NULL;
  END;
  return(NVL(Result,0));

end GetObjAccBegAcc;
/
grant execute on SM.GETOBJACCBEGACC to SM_ALLUSERS;
grant execute on SM.GETOBJACCBEGACC to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCMOVE
prompt ===============================
prompt
create or replace function sm.GetObjAccMove(ObjID in NUMBER, DateBeg in DATE, DateEnd in DATE, caca VARCHAR2, DCType in varchar2) return NUMBER is
  Result NUMBER(29,2);
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает суммарный оборот для объекта ПО УЧЕТНЫМ ДАННЫМ по счету в определенном периоде.
--    параметр ObjID - ID объекта учета
--    параметр DateBeg - начало периода
--    параметр DateEnd - окончание периода
--    параметр caca - счет бухгалтерский. В ряде случаев только часть счета!!! поэтому ниже: ...substr(macaca.ACC,1,length(caca))=caca...
--    параметр DCType - тип движения (D)
---------------------
  Result := 0;

   BEGIN 
            Select NVL(SUM(macaca.cost),0)  into Result
            from SM.MOVE_ACC macaca 
            where macaca.object_id=ObjID 
            and (macaca.apply_date>=DateBeg -- OR (macaca.apply_date=DateBeg and macaca.reversal_role!='Сторнирующая (красн.)') 
                   ) 
            and macaca.apply_date<=DateEnd 
            and substr(macaca.ACC,1,length(caca))=caca
            and macaca.dc=DCType;

  EXCEPTION
         When NO_DATA_FOUND then
                NULL;
  END;
  return(NVL(Result,0));

end GetObjAccMove;
/
grant execute on SM.GETOBJACCMOVE to SM_ALLUSERS;
grant execute on SM.GETOBJACCMOVE to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCEND
prompt ==============================
prompt
create or replace function sm.GetObjAccEnd(ObjID in NUMBER, DateBeg in DATE, DateEnd in DATE, caca VARCHAR2) return number is
  Result Number;
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает стоимость объекта ПО ПОЛУ-ОПЕРАТИВНЫМ ДАННЫМ  по счету на конец определенной даты.
--    параметр ObjID - ID объекта учета
--    параметр DateEnd - дата
---------------------
      Result := GetObjAccBeg(ObjID, DateBeg, caca) + GetObjAccMove(ObjID, DateBeg, DateEnd, caca, 'D') + GetObjAccMove(ObjID, DateBeg, DateEnd, caca, 'C');      
      return(Result);
end GetObjAccEnd;
/
grant execute on SM.GETOBJACCEND to SM_ALLUSERS;
grant execute on SM.GETOBJACCEND to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCENDACC
prompt =================================
prompt
create or replace function sm.GetObjAccEndAcc(ObjID in NUMBER, DateBeg in DATE, DateEnd in DATE, caca VARCHAR2) return number is
  Result Number;
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает стоимость объекта ПО УЧЕТНЫМ ДАННЫМ  по счету на конец определенной даты.
--    параметр ObjID - ID объекта учета
--    параметр DateEnd - дата
----------------------
      --Result := GetObjAccBeg(ObjID, DateEnd+1, caca);      
      Result := GetObjAccBegAcc(ObjID, DateBeg, caca) + GetObjAccMove(ObjID, DateBeg, DateEnd, caca, 'D') + GetObjAccMove(ObjID, DateBeg, DateEnd, caca, 'C');      
      return(Result);
end GetObjAccEndAcc;
/
grant execute on SM.GETOBJACCENDACC to SM_ALLUSERS;
grant execute on SM.GETOBJACCENDACC to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJACCNAME
prompt ===============================
prompt
create or replace function sm.GetObjAccName(ObjID in Number) return varchar2 is
  Result varchar2(200);
  resTmp varchar(2000);
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция возвращает Описание объекта для отчета "Оборотно-сальдовая ведомость по движению имущества в казне".
--    параметр ObjID - ID объекта учета
---------------------
  select
  substr(trim(t1.Description), 1, 200) || (case when t1.Regno is not null then ' ('||'Рег.№ '||trim(t1.Regno)||')' when t1.Invno is not null then ' ('||'Инв.№ '||trim(t1.Invno)||')' else ' ('||'Идент.№ '||to_char(t1.ID)||')' end)
  into resTmp
  from sm.objects t1 where t1.id=ObjID;
  
  Result := substr(trim(resTmp), 1, 200);  -- ver. 4.8.0

  return(Result);

end GetObjAccName;
/
grant execute on SM.GETOBJACCNAME to SM_ALLUSERS;
grant execute on SM.GETOBJACCNAME to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJECTCOST2
prompt ================================
prompt
create or replace function sm.GetObjectCost2(OBJ_ID IN NUMBER, COST_DATE IN DATE, COST_TYPE IN CHARACTER) RETURN NUMBER
--возвращает финансовые параметры имущества на заданный момент

-- Ver. 4.8.5 (24.03.2015)
-- !! расчет амортизации производится только для имущества с известной нормой амортизации
-- расчет амортизации производится линейным методом

-- 12/04/2013 Твердохлеб: добавил обработку флага D
-- 18/06/2013 Чувыкин: округление результата до сотых при флаге D
-- 02/07/2013 Твердохлеб: добавил обработку флага F - рыночная стоимость с учетом доли

-- OBJ_ID - ID объекта
-- COST_DATE - дата расчета стоимости
-- COST_TYPE - 'B' - первоначальная (восстановительная) стоимость (балансовая), 
--             'R' - остаточная стоимость
--             'T' - оценочная стоимость
--             'W' - износ в рублях
--             'P' - износ в процентах
--             'U' - удельный показатель кадастровой стоимости земельного участка (УПКСЗ) 
--             'K' - кадастровая стоимость (для ЗУ)
--             'L' - стоимость земельного участка
--             'D' - кадастровая стоимость с учетом доли (для ЗУ)
--             'F' - рыночная стоимость с учетом доли (для ЗУ)
--             'G' - первоначальная стоимость с учетом доли (для ЗУ)
--             'S' - Инвестиционная стоимость (сметная)
--             'Q' - Инвестиционная стоимость (фактическая)
IS
 bl number(27,2);
 r number(27,2);
 c number(27,6);
 d DATE;
 StatesID number(27);
 StatesDate date;
 gr_sq sm.grounds.square%type;
 l_wearnorm sm.objects.wearnorm%type;
 l_calcdate sm.states.calcdate%type;
 l_startpay sm.states.startpay%type;
 l_pay sm.states.pay%type;
 l_ratable sm.states.ratable%type;
 l_kadastr_cost sm.states.kadastr_cost%type;
 l_cadastralvalue sm.states.cadastralvalue%type; 
 l_IS_USING char(1);
 l_wearcalcmethod_id sm.objects.wearcalcmethod_id%type;
 l_obTypeID sm.objects.objtypes_id%type;
 l_wear sm.states.wear%type;
 l_cost_land sm.states.cost_land%type;
 l_INVESTMENT_ESTIMATED_VALUE sm.STATES.INVESTMENT_ESTIMATED_VALUE%type;
 l_INVESTMENT_FACT_VALUE sm.STATES.INVESTMENT_FACT_VALUE%type;
 Ashare_num sm.moveitems.share_num%type;
 Ashare_denom sm.moveitems.share_denom%type; 
begin
 /* 30/05/2016 Твердохлеб: Для сотимости сделал так: ищем первую запись где заполнено соответствующее поле*/
 /* 08/07/2019 Твердохлею: Добавил доп стоимости Инвестиционная стоимость (сметная) Инвестиционная стоимость (фактическая)*/

 d := trunc(cost_date);
 c := null;
  begin
 /*  select max(s.calcdate) 
     into StatesDate
     from sm.states s 
    where s.objects_id = OBJ_ID
      and s.calcdate <= d;

   select s.id 
     into StatesID
     from sm.states s 
    where s.objects_id = OBJ_ID 
      and s.calcdate = StatesDate;*/
   
    for xxST in (
        select
               st.id StatesID,
               o.objtypes_id as l_obTypeID,
               o.wearnorm as  l_wearnorm,
               st.calcdate as l_calcdate,
               st.startpay as l_startpay,
               st.pay as l_pay,
               st.ratable as l_ratable,
               st.is_using as l_is_using,
               o.wearcalcmethod_id as l_wearcalcmethod_id,
               st.kadastr_cost as l_kadastr_cost,
               st.cadastralvalue as l_cadastralvalue,
               st.wear as l_wear,
               st.cost_land as l_cost_land,
               st.INVESTMENT_ESTIMATED_VALUE AS l_INVESTMENT_ESTIMATED_VALUE,
               st.INVESTMENT_FACT_VALUE as l_INVESTMENT_FACT_VALUE 
          from sm.states st,
               sm.objects o
         where st.objects_id = OBJ_ID
           and o.id = st.objects_id 
           and st.calcdate <= d
        order by st.calcdate DESC
                 )
      loop            
          -- COST_TYPE - 'B' - первоначальная (восстановительная) стоимость (балансовая),      
          if  COST_TYPE = 'B' then
              if (xxST.l_startpay is not null) then
                StatesID := xxST.StatesID;
                exit;
              end if;                
          end if;
         
          -- 'R' - остаточная стоимость 
          if  COST_TYPE = 'R' then
              if (xxST.l_wearnorm IS NULL) or (xxST.l_is_using = 'N') then
                  if (xxST.l_pay is not null) then
                     StatesID := xxST.StatesID;
                     exit;
                  end if;
               else
                 if l_wearcalcmethod_id = 1 then 
                   if (xxST.l_pay is not null) then
                     StatesID := xxST.StatesID;
                     exit;
                   end if; 
                 else
                   if (xxST.l_startpay is not null) then
                     StatesID := xxST.StatesID;
                     exit;
                   end if;
                 end if;
               end if;                
          end if;
          
          -- 'T' - оценочная стоимость
          if  COST_TYPE = 'T' then
              if (xxST.l_ratable is not null) then
                StatesID := xxST.StatesID;
                exit;
              end if;                
          end if;
          
          -- 'W' - износ в рублях
          if  COST_TYPE = 'W' then
              if (xxST.l_startpay is not null or xxST.l_pay is not null) then
                StatesID := xxST.StatesID;
                exit;
              end if;                
          end if;
          
         -- 'P' - износ в процентах
         if  COST_TYPE = 'P' then
           if l_obTypeID = 4 then 
             if (xxST.l_wear is not null) then
                StatesID := xxST.StatesID;
                exit;
              end if;  
           else
             if (xxST.l_startpay is not null or xxST.l_pay is not null) then
                StatesID := xxST.StatesID;
                exit;
              end if; 
           end if; 
          end if; 
          
        -- 'U' - удельный показатель кадастровой стоимости земельного участка (УПКСЗ)  
        if  COST_TYPE = 'U' then
            if (xxST.l_kadastr_cost is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                
        end if;    
        
        -- 'K' - кадастровая стоимость (для ЗУ)
        if  COST_TYPE = 'K' then
            if (xxST.l_cadastralvalue is not null or xxST.l_kadastr_cost is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                
        end if; 
        
        -- 'L' - стоимость земельного участка 
        if  COST_TYPE = 'L' then
            if (xxST.l_cost_land is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                
        end if;
        
        -- 'D' - кадастровая стоимость с учетом доли (для ЗУ)
        if  COST_TYPE = 'D' then
            if (xxST.l_cadastralvalue is not null or xxST.l_kadastr_cost is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                 
        end if;
        
        -- 'F' - рыночная стоимость с учетом доли (для ЗУ)
        if  COST_TYPE = 'F' then
            if (xxST.l_ratable is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                 
        end if;    
        
        -- 'G' - первоначальная стоимость с учетом доли (для ЗУ) 
        if  COST_TYPE = 'G' then
            if (xxST.l_ratable is not null or xxST.l_cadastralvalue is not null or xxST.l_kadastr_cost is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                 
        end if;
        
        -- 'S' Инвестиционная стоимость (сметная) 
        if  COST_TYPE = 'S' then
            if (xxST.l_INVESTMENT_ESTIMATED_VALUE is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                 
        end if;
        
        -- 'Q' - Инвестиционная стоимость (фактическая) 
        if  COST_TYPE = 'Q' then
            if (xxST.l_INVESTMENT_FACT_VALUE is not null) then
              StatesID := xxST.StatesID;
              exit;
            end if;                 
        end if;    
      end loop;   
 
  exception
    when others then null;
  end;
  
 if StatesID is not null then  
  begin
   select
     objects.objtypes_id,
     objects.wearnorm,
     states.calcdate,
     states.startpay,
     states.pay,
     states.ratable,
     IS_USING,
     wearcalcmethod_id,
     states.kadastr_cost,
     states.cadastralvalue,
     states.wear,
     states.COST_LAND,
     STATES.INVESTMENT_ESTIMATED_VALUE,
     STATES.INVESTMENT_FACT_VALUE
   into
     l_obTypeID,
     l_wearnorm,
     l_calcdate,
     l_startpay,
     l_pay,
     l_ratable,
     l_IS_USING,
     l_wearcalcmethod_id,
     l_kadastr_cost,
     l_cadastralvalue,    
     l_wear,
     l_cost_land,
     l_INVESTMENT_ESTIMATED_VALUE,
     l_INVESTMENT_FACT_VALUE
   from
     sm.states,
     sm.objects
   where
     objects.id = states.objects_id and
     states.id = StatesID;
     
   if (l_wearnorm IS NULL) or (l_IS_USING='N') then
    r:=l_pay;
   else
     if l_wearcalcmethod_id=1 then 
       -- норма амортизации установлена от остаточной стоимости
       r:=l_pay-(l_pay*((l_wearnorm/100)/12))*trunc(MONTHS_BETWEEN(d,l_calcdate));
     else
       -- норма амортизации установлена от первоначальной (восстановительной) стоимости 
       r:=l_pay-(l_startpay*((l_wearnorm/100)/12))*trunc(MONTHS_BETWEEN(d,l_calcdate));
     end if;
   end if; 

   if (r<0) then
     r:=0.00;
   end if;
    
   bl:=l_startpay;
   
  if COST_TYPE='T' then
   c:=l_ratable;  
  elsif COST_TYPE='R' then
   c:=r;
  elsif COST_TYPE='B' then
   c:=bl;
   --if bl=0 then --comment Ver. апрель.2012
   -- c:=null; --comment Ver. апрель.2012
   --end if; --comment Ver. апрель.2012
  elsif COST_TYPE='W' then     
      c:=bl-r;
  elsif COST_TYPE='P' then
    if l_obTypeID=4 then 
     return l_wear;
    else
   --if bl=0 then --comment Ver. апрель.2012
   -- c:=null; --comment Ver. апрель.2012
   --else --comment Ver. апрель.2012
     if (bl <> 0) then
       c:=((bl-r)/bl)*100;
     end if;
    end if;    
  elsif COST_TYPE='U' then
   c:=l_kadastr_cost;
  elsif COST_TYPE='K' then
   if l_cadastralvalue is not null then
     c:=l_cadastralvalue;
   elsif l_kadastr_cost is not null then
     select
       g.square
     into
       gr_sq
     from
       sm.grounds g
     where
       g.objects_id=obj_id;
     if gr_sq is null then
       return null;
     else
       c:=round(gr_sq*l_kadastr_cost,2);  
     end if;    
   end if;   
   elsif COST_TYPE='D' then
   c := 0; 
   -- получим кадастровую стоимость 
   Select sm.GetObjectCost(OBJ_ID,COST_DATE,'K')
     into c 
     from dual;
   Ashare_num := 1;
   Ashare_denom := 1;
   begin
       select m.share_num,
              m.share_denom
         into Ashare_num,
              Ashare_denom     
         from sm.movements m
        where m.MoveType_ID = 1
          and m.POSTINGDATE <= COST_DATE
          and (m.EndDate >= COST_DATE or m.EndDate is null) 
          and m.OBJECTS_ID = OBJ_ID 
          and rownum < 2;
       exception
       when NO_DATA_FOUND then
       null;           
   end;   
   c:= c * Ashare_num / Ashare_denom; 
   c := round(c,2);     
  elsif COST_TYPE='F' then
     Ashare_num := 1;
     Ashare_denom := 1;
     begin
       select m.share_num,
              m.share_denom
         into Ashare_num,
              Ashare_denom     
         from sm.movements m
        where m.MoveType_ID = 1
          and m.POSTINGDATE <= COST_DATE
          and (m.EndDate >= COST_DATE or m.EndDate is null) 
          and m.OBJECTS_ID = OBJ_ID 
          and rownum < 2;
       exception
       when NO_DATA_FOUND then
       null;           
     end;   
     c := l_ratable;
     c := c * Ashare_num / Ashare_denom; 
     c := round(c, 2);  
     if c is null then
       c := 0; 
     end if;
  elsif COST_TYPE='G' then
     c := NULL;
     Select sm.GetObjectCost(OBJ_ID,COST_DATE,'D')
      into c 
      from dual; 
     if c is null or c = 0 then
       Select sm.GetObjectCost(OBJ_ID,COST_DATE,'F')
        into c 
        from dual; 
     end if;              
  elsif COST_TYPE='L' then
     c := l_cost_land;
  elsif COST_TYPE='S' then
     c := l_INVESTMENT_ESTIMATED_VALUE;
  elsif COST_TYPE='Q' then
     c := l_INVESTMENT_FACT_VALUE;
  end if;
  
  if c is not null  then
   return c;   
  end if;
exception
  when others then null;
end;  
end if;  

 
 return c;
end;
/
grant execute on SM.GETOBJECTCOST2 to SM_ALLUSERS;


prompt
prompt Creating function GETOBJECTDESCRIPTION
prompt ======================================
prompt
create or replace function sm.GetObjectDescription(ObjID NUMBER) return VARCHAR2 is
  Recv VARCHAR2(1000);
begin

 SELECT description INTO Recv
 FROM Objects
 WHERE 
  ID=ObjID;

 return(RTRIM(Recv));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;
  
end GetObjectDescription;
/
grant execute on SM.GETOBJECTDESCRIPTION to SM_ALLUSERS;
