prompt
prompt Creating function GETOBJECTDOC
prompt ==============================
prompt
create or replace function sm.GetObjectDoc(Adoctypes_id in NUMBER, Aobject_id in NUMBER) return varchar2 is
  Result varchar2(2000);
  i NUMBER;
-- 20.07.2019 Чувыкин -- функция выводит список документов нужного вида, прикрепленных к объекту 
-- при наличии прирепленного скана (в т.ч. и внешнего) пишет (Scan)
-- 06.06.2022 Чувыкин -- при типе документа -1 выводит ВСЕ документы пакета, отстортированные в хронологическом порядке
 begin
   i:=1;
   Result:='';

 if Adoctypes_id = -1 then -- выводятся все документы пакета
   begin
     for xx in (
              select
                sm.expanddoc(dsm.document_id) doc,
                d.docdate,
                d.file_extention fe,
                d.file_scan fs
              from
                objects o
                join docsets ds on o.docset_id = ds.id
                join sm.docset_members dsm on dsm.docset_id = ds.id
                join documents d on dsm.document_id = d.id
              where
                o.id = Aobject_id
              order by
                d.docdate)

     loop
       if (xx.fe is not null) or (xx.fs is not null) then
        Result:=Result || ' ' ||to_char(i)||'. (Scan) '||xx.doc||chr(13);
        else 
        Result:=Result || ' ' ||to_char(i)||'. '||xx.doc||chr(13);
       end if;
       i:=i+1;
     end loop;
     
   end;
 else -- выводятся документы пакета заданного типа
   begin
     for xx in (
                select
                  sm.expanddoc(dsm.document_id) doc,
                  d.file_extention fe,
                  d.file_scan fs
                from
                  objects o
                  join docsets ds on o.docset_id = ds.id
                  join sm.docset_members dsm on dsm.docset_id = ds.id
                  join documents d on dsm.document_id = d.id
                where
                  o.id = Aobject_id and d.doctypes_id = Adoctypes_id)

     loop
       if (xx.fe is not null) or (xx.fs is not null) then
        Result:=Result || ' ' ||to_char(i)||'. (Scan) '||xx.doc||chr(13);
        else 
        Result:=Result || ' ' ||to_char(i)||'. '||xx.doc||chr(13);
       end if;
       i:=i+1;
     end loop;     
   end;

 end if;

   /*for xx in (
              select
                sm.expanddoc(dsm.document_id) doc,
                d.file_extention fe,
                d.file_scan fs
              from
                objects o
                join docsets ds on o.docset_id = ds.id
                join sm.docset_members dsm on dsm.docset_id = ds.id
                join documents d on dsm.document_id = d.id
              where
                o.id = Aobject_id and d.doctypes_id = Adoctypes_id)

   loop
     if (xx.fe is not null) or (xx.fs is not null) then
      Result:=Result || to_char(i)||'. (Scan) '||xx.doc||chr(13);
      else 
      Result:=Result || to_char(i)||'. '||xx.doc||chr(13);
     end if;
     i:=i+1;
   end loop;*/

  return(Result);
end GetObjectDoc;
/
grant execute on SM.GETOBJECTDOC to SM_ALLUSERS;


prompt
prompt Creating function GETOBJECTFEATURES
prompt ===================================
prompt
create or replace function sm.GetObjectFeatures(Flag in char, ObjectsID in number) return varchar2 is
Result varchar2(4000);
ObjectType number;
begin
/* 070719 Чувыкин - функция для вывода свойств объекта в несвойственных отчетах */

/* Флаг
1 - поиск Вида объекта инженерки
2 - поиск ГРуппы инженерки
3 - поиск VIN транспорта
4 - поиск типа транспорта
*/

-- определение типа объекта
begin
select
o.objtypes_id
into
ObjectType
from
sm.objects o
where
o.id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;

--если инженерка
if ObjectType=5 then
    begin      
        -- поиск вида объекта инженерки
        if flag = 1 then
        select
          et.name
          into
          Result
        from
          sm.enginf e inner join enginftypes ET on Et.ID = e.enginftypes_id
        where
          e.objects_id=ObjectsID;
        end if;

        -- поиск группы инженерки
        if flag = 2 then
        select
          EG.NAME
          into
          Result
        from
          sm.enginf e inner join Infgroups EG on EG.ID = e.infgroups_id
        where
          e.objects_id=ObjectsID;
        end if;

        exception
        when NO_DATA_FOUND then
        null;
    end;
end if;

--если транспорт
if ObjectType=2 then
    begin      
        -- поиск VIN
        if flag = 3 then
        select
          t.ps_vin
          into
          Result
        from
          transport t
        where
          t.objects_id=ObjectsID;
        end if;

        -- поиск типа транспорта
        if flag = 4 then
        select
          tt.name
          into
          Result
        from
          transport t inner join transptype tt on t.transptype_id = tt.id
        where
          t.objects_id=ObjectsID;
        end if;

        exception
        when NO_DATA_FOUND then
        null;
    end;
end if;

return(Result);
end GetObjectFeatures;
/
grant execute on SM.GETOBJECTFEATURES to SM_ALLUSERS;


