prompt
prompt Creating function GETOBJECTINDICATOR
prompt ====================================
prompt
create or replace function sm.GetObjectIndicator(ObjID IN NUMBER) RETURN NUMBER IS

 /*
 Значение возвращаемое индикатором

 --Цветовая гамма 16 цветов
 0 Black,
 1 Maroon,
 2 Green,
 3 Olive,
 4 Navy,
 5 Purple,
 6 Teal,
 7 DkGray,
 8 LtGray,
 9 Red,
 10 Lime,
 11 Yellow,
 12 Blue,
 13 Fuchsia,
 14 Aqua,
 15 White

 --Стили начертания
 16 - Bold (жирный)
 32 - StrikeOut (зачеркнутый)
 64 - Underline (подчеркнутый)
 128 - Italic (наклон)
 */
    KUMI_ID integer;
    Client_ID number:=null;
    OWNER_ID number:=null; 
    cnt integer := null;
begin
  /* 21/11/2017 Твердохлеб: [000] - добавил обработку ОД «Учет» */
  
  -- если ОД Учет
  -- с основанием «Постановка на учет бесхозяйного объекта»
  -- дата окончания периода не указана
  Cnt := null;
  begin
     Select
       op.movetype_id
     into
       Cnt  
     from
       sm.object_position op
     where
       op.movetype_id = 9 and
       op.object_id = ObjID;
         
     exception
     when NO_DATA_FOUND then
       null;   
  end;
 
  if (Cnt is not null and Cnt <> 0) then
     cnt := null;
     begin
       select count(*)
         into cnt
         from sm.movesets ms 
         join sm.moveperiods mp on mp.moveset_id = ms.id
         join sm.moveitems mi on mi.moveperiod_id = mp.id
        where ms.movetype_id = 9
          and mi.object_id = ObjID
          and mp.enddate is null
          and ms.transferbasis_id = 2874;
       exception
       when NO_DATA_FOUND then
         null;   
     end;
      
     if (Cnt is not null and Cnt <> 0) then
        return(3);
     end if;
  end if;   
  
  -- Получаем ид текущего распорядителя
  KUMI_ID := sm.multiowning_pkg.GetCurrentOwnerID;
  
  -- собственник
  Owner_ID:=nvl(sm.Getpositionclientid(ObjID,1),0);
  if (Owner_ID<>KUMI_ID) and (Owner_ID<>0) then
    return(12);-- синий
  end if;
     
  -- Если сдан в аренду, то зеленым  
  if sm.Getpositionclientid(ObjID,4) is not null then
    return(6); -- темно-зеленый
  end if;
  
  -- Если объект в арендном фонде, но не сдан в аренду - выделить красным цветом
  /*Client_ID:=sm.Getpositionclientid(ObjID, 11);
  if (Client_ID is not null) and (Client_ID=KUMI_ID) then
    return(9); --красный
  end if;*/

  -- Если в безв.пользовании, то красным  - Чувыкин 290525
  if sm.Getpositionclientid(ObjID,22) is not null then
    return(9); -- темно-зеленый
  end if;
    -- Если в концесс, то коричнево-бордовый  - Чувыкин 290525
  if sm.Getpositionclientid(ObjID,34) is not null then
    return(1); -- коричнево-бордовый
  end if;
      
  -- Если собственником является не КУМИ - выделить синим цветом
  if (Owner_ID <> KUMI_ID) then     
    return(12);-- синий
  else 
    return(0); -- чёрный 
  end if;
 
exception         
    -- в случае любой ошибки молча возврящаем желтый цвет
    when others then return(11);
end;
/
grant execute on SM.GETOBJECTINDICATOR to SM_ALLUSERS;
grant execute on SM.GETOBJECTINDICATOR to SM_ALL_SELECT;


