prompt
prompt Creating function GETOBJECTOFFADDR
prompt ==================================
prompt
create or replace function sm.GetObjectOffAddr(ObjID NUMBER) return VARCHAR2 is
  Recv VARCHAR2(1000);
  OffAddr VARCHAR2(1000);
  OBjAddr VARCHAR2(1000);
  Addon VARCHAR2(1000);
begin
-- Чувыкин 190421 - если есть официальный адрес - выводится только он, если его нет - то обычный рабочий адрес объекта
 begin
   select o.official_addr
   into OffAddr 
   from objects o 
   where o.id = ObjID;
   EXCEPTION
   WHEN NO_DATA_FOUND THEN RETURN NULL;
 end;
 Recv := OffAddr;
 
if Recv is null then
begin  
   begin
     select ExpandAddr_as(o.address_id)
     into ObjAddr 
     from objects o 
     where o.id = ObjID;
     EXCEPTION
     WHEN NO_DATA_FOUND THEN RETURN NULL;
   end;
   begin
     select a.addon 
     into Addon
     from address a
     join objects o on a.id = o.address_id
     where o.id = ObjID;
     EXCEPTION
     WHEN NO_DATA_FOUND THEN RETURN NULL;
   end;
      
   if Addon is not null
     then Recv:= ObjAddr || ', ' || Addon;
     else Recv := ObjAddr;
   end if;
   
   
   --Recv := ObjAddr;
end;   
end if;

return(RTRIM(Recv));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end GetObjectOffAddr;
/
grant execute on SM.GETOBJECTOFFADDR to SM_ALLUSERS;


prompt
prompt Creating function GETOBJECTSFEATURESFROMMS
prompt ==========================================
prompt
create or replace function sm.GETOBJECTSFEATURESFROMMS(Flag Char, Movesets_id  in NUMBER) return varchar2 is
  Result varchar2(4000);
  i NUMBER;
  objaddr number;
  --100225 Чувыкин - функция возвращает список объектов, их адресов, площадей из заданной операции движения

 begin
   i:=1;
   Result:='';
    for xx in (
                SELECT
                t3.ID
                , t3.Description
                --, sm.ExpandAddr(t3.address_id) Objaddr

                FROM
                 SM.OBJECTS t3
                WHERE
                (t3.ID in (SELECT
                 Objects.ID
                FROM
                 sm.Objects
                WHERE
                 EXISTS (
                  SELECT
                   MoveItems.ID
                  FROM
                   sm.MoveItems,
                   sm.MovePeriods,
                   sm.MoveSets,
                   sm.movements MI_MV
                  WHERE
                   MI_MV.MoveItem_ID=MoveItems.id and
                   MI_MV.OBJECTS_ID=Objects.ID and
                   MoveItems.MovePeriod_ID=MovePeriods.ID and
                MovePeriods.MoveSet_ID=MoveSets.ID and
                   MoveSets.ID IN (
                    SELECT
                     MoveSets.ID
                    FROM
                     sm.MoveSets
                    WHERE
                     MOVESETS.ID=Movesets_id
                )
                )

                ))
             )
   loop
     
     if flag = 1 then Result:=Result || to_char(i)||') '||trim(xx.description)|| '; '; end if;
     
     if flag = 2 then 
       begin
        select o.address_id into objaddr from objects o where o.id = xx.id;
        Result:=Result || to_char(i)||') '||sm.ExpandAddr(objaddr)|| '; ';
       EXCEPTION
       WHEN NO_DATA_FOUND THEN
         Result:=Result || to_char(i)||') '||'Нет адреса'|| '; ';         
       end;         
     end if;
     
     if flag = 3 then Result:=Result || to_char(i)||') '||sm.GetObjectCommonSquare(1,xx.id)|| '; '; end if;     
     
     i:=i+1;
     
   end loop;

  return(Result);
end GETOBJECTSFEATURESFROMMS;
/
grant execute on SM.GETOBJECTSFEATURESFROMMS to SM_ALLUSERS;


prompt
prompt Creating function GETOBJECTSFROMMOVESET
prompt =======================================
prompt
create or replace function sm.GETOBJECTSFROMMOVESET(Movesets_id  in NUMBER) return varchar2 is
  Result varchar2(4000);
  i NUMBER;
  --функция возвращает список объектов (идентификатор, описание) из заданной операции движения

 begin
   i:=1;
   Result:='';
    for xx in (
                SELECT
                t3.ID
                , t3.Description

                FROM
                 SM.OBJECTS t3
                WHERE
                (t3.ID in (SELECT 
                 Objects.ID
                FROM 
                 sm.Objects
                WHERE 
                 EXISTS (
                  SELECT 
                   MoveItems.ID
                  FROM 
                   sm.MoveItems,
                   sm.MovePeriods,
                   sm.MoveSets,
                   sm.movements MI_MV
                  WHERE 
                   MI_MV.MoveItem_ID=MoveItems.id and
                   MI_MV.OBJECTS_ID=Objects.ID and
                   MoveItems.MovePeriod_ID=MovePeriods.ID and
                MovePeriods.MoveSet_ID=MoveSets.ID and
                   MoveSets.ID IN (
                    SELECT 
                     MoveSets.ID
                    FROM 
                     sm.MoveSets
                    WHERE 
                     MOVESETS.ID=Movesets_id
                )
                )

                ))
             )
   loop
     Result:=Result || to_char(i)||'. '||xx.id|| ', ' ||trim(xx.description)|| '. ';
     i:=i+1;
   end loop;

  return(Result);
end GETOBJECTSFROMMOVESET;
/
grant execute on SM.GETOBJECTSFROMMOVESET to SM_ALLUSERS;


prompt
prompt Creating function GETOBJECTSLIST
prompt ================================
prompt
create or replace function sm.GetObjectsList(addr_id in number) return varchar2 is

-- Функция возвращает список объектов недвижимости находящихся на земельном участке.
-- %param addr_id ID адреса земельного участка.
-- %return        Список объектов недвижимости в виде строки, через запятую.

  Result varchar2(4000);
  cursor c1(a_id number) is
                        select
                          t.description
                        from
                          sm.objects t,
                          sm.buildings b,
                          sm.buildtypes bt,
                          sm.grounds gr
                        where
                          t.objtypes_id = 3 and
                          b.objects_id = t.id and
                          b.buildtypes_id = bt.id and
                          bt.container = 'Y' and
                          gr.address_id=a_id and
                          b.KADASTRNO like gr.KADASTRNO||'%'

                        union all

                        select
                          t.description
                        from
                          sm.objects t,
                          sm.enginf en,
                          sm.grounds gr
                        where
                          (t.objtypes_id = 5) and
                          en.objects_id=t.id and
                          gr.address_id=a_id and
                          en.kadastrno like gr.KADASTRNO||'%'
                          
                         union all

                        select
                          t.description
                        from
                          sm.objects t,
                          sm.unconstr un,
                          sm.grounds gr
                        where
                          (t.objtypes_id = 4) and
                          un.objects_id=t.id and
                          gr.address_id=a_id and
                          un.kadastrno like gr.KADASTRNO||'%'  
                          ;
                          
  rec varchar2(150);
  p number := 0;
begin
  Result := '';
  open c1(addr_id);
  loop
    fetch c1 into rec;
    exit when c1%notfound;
    p := inStr(Rec,'Отдельностоящее',1);
    if (p=1) then
      Rec := 'Отдельностоящее здание'||SubStr(Rec,16,Length(Rec));
    end if;
    Result := Result || trim(rec) || ', ';
  end loop;
  close c1;
  Result := SubStr(Result, 1, Length(Result)-2);
  return(Result);
end GetObjectsList;
/
grant execute on SM.GETOBJECTSLIST to SM_ALLUSERS;
grant execute on SM.GETOBJECTSLIST to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJECTSTATUS
prompt =================================
prompt
create or replace function sm.GetObjectStatus(ObjectsId in number, status_type in character) return number
is
  maxdate date;
  maxwrdate date;
  res number;
begin

-- вычисление даты позднейшего состояния  
 select max(states.calcdate) 
   into maxdate
   from states 
  where states.objects_id=ObjectsId;
 
 select max(states.writedate) 
   into maxwrdate
   from states 
  where states.objects_id=ObjectsId;

-- вычисление Среднесписочной численности
if status_type=1 then
  begin
     select states.workersnumber
     into res
     from states
     where states.objects_id=ObjectsId and states.calcdate=maxdate and states.writedate=maxwrdate;
     return res;
  end;
end if;  
-- вычисление Первоначальной стоимости
if status_type=2 then
  begin
     select states.startpay
     into res
     from states
     where states.objects_id=ObjectsId and states.calcdate=maxdate and states.writedate=maxwrdate;
     return res;
  end;
end if;  
-- вычисление Остаточной стоимости
if status_type=3 then
  begin
     select states.pay
     into res
     from states
     where states.objects_id=ObjectsId and states.calcdate=maxdate and states.writedate=maxwrdate;
     return res;
  end;
end if;
-- вычисление Количества акций
if status_type=4 then
  begin
     select states.sharesnumber
     into res
     from states
     where states.objects_id=ObjectsId and states.calcdate=maxdate and states.writedate=maxwrdate;
     return res;
  end;
end if;
-- вычисление Номинальной стоимости акций\доли или Размера капитала\фонда
if status_type=5 then
  begin
     select states.nominalcost
     into res
     from states
     where states.objects_id=ObjectsId and states.calcdate=maxdate and states.writedate=maxwrdate;
     return res;
  end;  
end if;  
end GetObjectStatus;
/
grant execute on SM.GETOBJECTSTATUS to SM_ALLUSERS;
grant execute on SM.GETOBJECTSTATUS to SM_ALL_SELECT;


prompt
prompt Creating function GETOBJECTYEAR
prompt ===============================
prompt
create or replace function sm.GetObjectYEAR(Flag in char, ObjectsID in number) return varchar2 is
Result varchar2(4000);
ObjectType number;
begin
/* 20.06.20 Чувыкин В.Э. - функция возвращает Год ввода или Год выпуска объекта */

-- определение типа объекта
begin
select
o.objtypes_id
into
ObjectType
from
sm.objects o
where
o.id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;

--если прочее движимое
if ObjectType=1 then
begin
select
p.dateissue
into
Result
from
sm.property p
where
p.objects_id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;
end if;
--если транспорт
if ObjectType=2 then
begin
select
t.relyear
into
Result
from
sm.transport t
where
t.objects_id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;
end if;
--если здания
if ObjectType=3 then
begin
select
b.enteryear
into
Result
from
sm.buildings b
where
b.objects_id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;
end if;
--если ЗУ
if ObjectType=7 then result:=null;
end if;
--если незавершенное
if ObjectType=4 then
begin
select
u.startyear
into
Result
from
sm.unconstr u
where
u.objects_id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;
end if;
--если инженерка
if ObjectType=5 then
begin
select
e.enteryear
into
Result
from
sm.enginf e
where
e.objects_id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;
end if;

return(Result);
end GetObjectYEAR;
/
grant execute on SM.GETOBJECTYEAR to SM_ALLUSERS;


prompt
prompt Creating function GETOBJOWNERINFO
prompt =================================
prompt
create or replace function sm.GetObjOwnerInfo(ObjID number, QueryDate DATE) return varchar2 is
  --Result varchar2;

--
-- Функция возвращает информацию о владельце объекта ObjID на дату QueryDate
--
  Result varchar2(4000);
  msInfo varchar2(2000);
  clientInfo varchar2(2000);
  qDate date;
  clientsID number(27);
begin
  Result:='';
  qDate := trunc(QueryDate);
  for x in (select
               ms.client_id,
               (case when ms.movetype_id=1 then tb.name else mt.name end) as TypeName,
               mp.sincedate
             from
               sm.Movesets ms,
               sm.Moveitems mi,
               sm.Moveperiods mp,
               sm.Movetype mt,
               sm.Transferbasis tb
             where
               ms.movetype_id in (Select t.ID from sm.movetype t where t.ObjRightHolding = 'Y') and ms.movetype_id = 1 and
               mt.id=ms.movetype_id and
               tb.id=ms.transferbasis_id and
               mp.moveset_id = ms.id and mi.moveperiod_id = mp.id and mi.object_id = ObjID and
               mp.sincedate<= qDate and nvl(mp.EndDate, qDate) >= qDate
             order by mp.sincedate desc, ms.ID desc
              )
  loop
      if (x.client_id is not null) then
        clientsID := x.client_id;
        msInfo := rtrim(x.typename) || ' c ' || to_char(trunc(x.sincedate));
        exit;
      end if;
  end loop;

  if (clientsID is null) then
        clientsID := sm.multiowning_pkg.GetCurrentOwnerID();
  end if;

  select
          (case
                when c.client_types_id=3 then a.fullname
                when c.client_types_id=2 then o.fullname
                when c.client_types_id=1 then p.fullname || decode(p.businessman, 'Y', ' ИП', '')
           end)
        into clientInfo
        from
          sm.clients c, sm.organisations o, sm.ato a, sm.privates p
        where
          c.id=clientsID and
          o.clients_id(+)=c.id and
          a.clients_id(+)=c.id and
          p.clients_id(+)=c.id;

  Result :=  msInfo || ' - ' || Rtrim(clientInfo);

  return(Result);

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN null;


end GetObjOwnerInfo;
/

prompt
prompt Creating function GETOBJSTATEID
prompt ===============================
prompt
create or replace function sm.GetObjStateID(ObjID NUMBER, CDATE DATE default SYSDATE) return number is
  Recv Number;
begin

  -- By XSGROUP ver.03.03.2008
  -- функция возвращает ID последнего зарегистрированного состояния объекта ObjID на дату CDate
  
  select STID
  into Recv
  from (
        select st.id as STID
        from
          sm.states st
        where
          st.objects_id=ObjID and 
          st.calcdate<=CDate
        order by calcdate desc
        )
   where rownum=1;
   
   return(Recv);

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN null;
  
end GetObjStateID;
/
grant execute on SM.GETOBJSTATEID to SM_ALLUSERS;
grant execute on SM.GETOBJSTATEID to SM_ALL_SELECT;


