prompt
prompt Creating function GETOBLIGATIONBALANCE
prompt ======================================
prompt
create or replace function sm.GetObligationBalance(AMoveset_ID NUMBER, AOblType_ID NUMBER) return number is


  RetVal number(27,2);
  Charged number(27,2);
  Payed number(27,2);

begin

  RetVal:=0;
    select nvl(sum(PaySize),0) into Charged
    from charges
    where
      movesets_id=AMoveset_ID and
      obligationtype_id=AOblType_ID and
      CHARGEDATE<Trunc(Sysdate+1) and
      charge_type!='FINE';

    select nvl(sum("SUM"),0) into Payed
    from Payments
    where
      movesets_id=AMoveset_ID and
      payments.obligationtype_id=AOblType_ID and
      APPLY_DATE<Trunc(Sysdate+1) and
      Mainpay ='Y';

    RetVal:=RetVal+Payed-Charged;

  IF RetVal IS NULL THEN
    RetVal:=0;
  END IF;

  return(RetVal);
end;
/
grant execute on SM.GETOBLIGATIONBALANCE to SM_ALL_SELECT;


prompt
prompt Creating function GETOBLIGRECEPIENT_ID
prompt ======================================
prompt
create or replace function sm.GetObligRecepient_id(AMoveset_ID NUMBER, AOblType_ID NUMBER) return number is
  RetVal number;

  -- XSGROUPE 09.11.2009
  -- Функция возвращает значение ID получателя платежа для обязательства типа AOblType_ID в ОД AMoveset_ID
  -- (поле "РАСЧЕТНЫЙ СЧЕТ")
  -- используем условия по обязательству в последнем периоде
  --
  MaxSinceDate sm.moveperiods.sincedate%type;
  MP_ID sm.moveperiods.id%type;
  CNT number;
begin

    RetVal:=null;
    

    for xx in (select * from sm.moveperiods p where p.moveset_id=AMoveset_ID order by p.sincedate desc)
    loop
      MP_ID:=xx.ID;
     
      select count(*)
      into
        CNT
      from
        dual
      where
        EXISTS (select * from sm.paydocs pd where pd.moveperiod_id=MP_ID);
        
      if CNT>0 then  
        exit;
      end if;
    end loop;
    
    for xx in (select * from sm.paydocs pd  where pd.moveperiod_id=MP_ID)
    loop
      RetVal:=xx.clients_id;
      exit;
    end loop;
              
          
  return(RetVal);

   exception
     When NO_DATA_FOUND then return null;

end;
/
grant execute on SM.GETOBLIGRECEPIENT_ID to SM_ALLUSERS;
grant execute on SM.GETOBLIGRECEPIENT_ID to SM_ALL_SELECT;


prompt
prompt Creating function GETOBLIGATIONOKATO
prompt ====================================
prompt
create or replace function sm.GetObligationOKATO(AMoveset_ID NUMBER, AOblType_ID NUMBER) return varchar2 is
  RetVal varchar2(4000);--sm.recepients.okato%type;

  -- XSGROUPE 26.10.2009
  -- Функция возвращает значение ОКАТО для обязательства типа AOblType_ID в ОД AMoveset_ID
  -- Значение ОКАТО берется из характеристик  получателя платежа
  -- (поле "РАСЧЕТНЫЙ СЧЕТ")
  -- условий по обязательству в последнем периоде
  --

begin

  RetVal:=null;
  
    select rc.okato 
    into RetVal
    from sm.recepients rc
    where rc.id=nvl(sm.getobligrecepient_id(AMoveset_ID,AOblType_ID),-1);

  
  return(RetVal);

  exception
     When NO_DATA_FOUND then return null;

end;
/
