grant execute on SM.GETOBLIGATIONOKATO to SM_ALL_SELECT;


prompt
prompt Creating function GETOBLIGPRESETID
prompt ==================================
prompt
create or replace function sm.GetObligPresetID(AObligTypeID in number) return number is
  --
  --  by XSGROUP ver. 05.05.2010
  --  функция врозвращает ID из таблицы OBLIG_PRESETS
  --  соответствующий данному типу обязательства
  --
  result number;
begin

  select nvl(ot.default_oblig_presets_id,0)
  into result
  from
    sm.obligationtype ot
  where
    ot.id=AObligTypeID;

  if Result=0 then
  -- если дефолтный OBLIG_PRESET для данного типа обязательства не назначен
  -- берём первый по порядку
    select obp.id
    into Result
    from
      ( select *
        from
          sm.oblig_presets
        order by ID
       ) obp
    where
      rownum=1;
  end if;

  return(Result);

end;
/
grant execute on SM.GETOBLIGPRESETID to SM_ALLUSERS;
grant execute on SM.GETOBLIGPRESETID to SM_ALL_SELECT;


