prompt
prompt Creating function GETORGTYPEBYDATE
prompt ==================================
prompt
create or replace function sm.GetOrgtypebyDate(n_ClientID number, A_date date, is_client char default 'N') return number
is
retval number(27);
OrgID number(27);
curDate date default to_date('01.01.1900');
curOrgType number(27);
FirstOrgType number(27);
BeginPeriod date;
EndPeriod date;
cursor GetChangeHistory(A_OrgID number)
is 
  select * 
   from ( 
         select o.orgtype_id ORGTYPE_ID, to_date('31.12.3000') ADATE
         from sm.organisations o
         where o.id=A_OrgID
         union all
         select v.old_value_num ORGTYPE_ID, trunc(v.change_date) ADATE
         from sm.sm_v_changes v
         where v.table_name='ORGANISATIONS' and v.column_name='ORGTYPE_ID' and v.id_value=A_OrgID                
     ) 
  order by ADate;  
  histor_1 GetChangeHistory%rowtype; 
begin
  if n_ClientID is not null and
     A_date is not null then

   if is_client='Y' then 
    select o.id
    into OrgID
    from sm.organisations o
    where o.clients_id=n_ClientID;
   else
    OrgID:=n_ClientID;
   end if;
    
    Open GetChangeHistory(OrgID);
    fetch GetChangeHistory into histor_1; 
   -- FirstOrgType:=histor_1.orgtype_id;  
    BeginPeriod:=to_date('01.01.1900');
    LOOP  
      exit when GetChangeHistory%notfound;
      
      if histor_1.adate<>to_date('01.01.1900') then 
         EndPeriod:=trunc(histor_1.adate)-1;
      else
         EndPeriod:=to_date('01.01.1900');
      end if;      
      curOrgType:=histor_1.orgtype_id; 
      
      if A_date>=BeginPeriod and A_date<=EndPeriod then retval:=curOrgType; exit; end if;
      BeginPeriod:=histor_1.adate;
      
      fetch GetChangeHistory into histor_1; 
    end loop;  
        
   close GetChangeHistory;
  else
   return(-1);
  end if;
return retval;
exception
when others then return (-1);
end;
/
grant execute on SM.GETORGTYPEBYDATE to SM_ALLUSERS;
grant execute on SM.GETORGTYPEBYDATE to SM_ALL_SELECT;


prompt
prompt Creating function GETOWNINGCAPTION
prompt ==================================
prompt
create or replace function sm.GetOwningCaption(padnum in number default 1) return varchar2 authid current_user is
  --
  -- функция возвращает наименование вида базовой собственности,
  -- преобразовав его в соответствии с заданным падежом
  --
  Result varchar2(200);
  S varchar2(2000);
begin

  select sms.value into S from sm.Sm_Settings sms where sms.key_name='KUMI_OWNING';
  if S is null then
    S:='муниципальная';
  end if;
  
  if padnum=1 then
    S:=REPLACE(S,'ная','ная'); --именительный
  elsif padnum=2 then
    S:=REPLACE(S,'ная','ной'); --родительный
  elsif padnum=3 then
    S:=REPLACE(S,'ная','ной'); --дательный
  elsif padnum=4 then
    S:=REPLACE(S,'ная','ную'); --винительный
  elsif padnum=5 then
    S:=REPLACE(S,'ная','ной'); --творительный
  elsif padnum=6 then
    S:=REPLACE(S,'ная','ной'); --предложный
  end if;
  
  result:=S;
  
  return(Result);
end GetOwningCaption;
/
grant execute on SM.GETOWNINGCAPTION to SM_ALLUSERS;
grant execute on SM.GETOWNINGCAPTION to SM_ALL_SELECT;


prompt
prompt Creating function GET_OD_DATA
prompt =============================
prompt
create or replace function sm.GET_OD_DATA(Aobject_id in integer, Amovetype_id in integer, Flag varchar2) return varchar2 is
res varchar2(4000);
i number;
begin
-- изм 20.07.2019 Чувыкин - включена сборка строки со счетами забалансового учета
-- изм 01.07.2020 Чувыкин - помимо учетного счета заб.учета добавлен вариант учетного счета концессии и т.д. по другим возможным ОД
-- изм 17.12.2021 Чувыкин - добавлен по флагу 10 вывод предыдущих субъектов операций, а также вся информация по прошлым ОД выводится в виде сборных строк

  i:=1;
  res := '';

  -- текущие значения
  if (Flag in ('1','2','3','4')) then
    for xxx in (
                select t.name as name_transferbasis,
                       mi.leasepurpose_id,
                       mp.account_zabuch,
                       mp.account_concession,
                       mi.share_num,
                       mi.share_denom,
                       ms.client_id
                  from sm.moveperiods mp
                  join sm.moveitems mi on mi.moveperiod_id = mp.id
                  join sm.movesets ms on ms.id = mp.moveset_id
                  join sm.transferbasis t on t.id = ms.transferbasis_id
                 where ms.movetype_id = Amovetype_id
                   and mi.object_id = Aobject_id
                   and mp.sincedate <= sysdate
                   and (mp.enddate >= sysdate or mp.enddate is null)
               )
    loop
       --основание
       if (trim(Flag) = '1') then
         res := xxx.name_transferbasis;
       end if;
       --назначение
       if (trim(Flag) = '2') then
         select l.name
           into res
           from sm.leasepurpose l where l.id = xxx.leasepurpose_id;
       end if;
       --учетный счет
       if (trim(Flag) = '3') then
         --res := xxx.account_zabuch; --вариант без сборки номерованной строки
         -- счет заб.учета
         if Amovetype_id = 31 then
         Res:=Res || to_char(i)||'. '||xxx.account_zabuch||chr(13);     
         i:=i+1;
         end if;
         -- счет концессии   
         if Amovetype_id = 34 then
         Res:=Res || to_char(i)||'. '||xxx.account_concession||chr(13);     
         i:=i+1;
         end if;
   
       end if;
       --доля собственности
       if (trim(Flag) = '4' and xxx.client_id = 5100) then
         res := xxx.share_num || '/' || xxx.share_denom;
       end if;
    end loop;
  end if;
  
  -- предыдущие значения
  if (Flag in ('5','6','7','8','10')) then
    for xxx in (
                select s.name_transferbasis,
                       s.leasepurpose_id,
                       s.account_zabuch,
                       s.share_num,
                       s.share_denom,
                       s.client_id,
                       s.org_name,
                       s.lp_name
                  from ( 
                        select t.name as name_transferbasis,
                               mi.leasepurpose_id,
                               mp.account_zabuch,
                               mi.share_num,
                               mi.share_denom,
                               ms.client_id,
                               org.name org_name,
                               lp.name lp_name
                          from sm.moveperiods mp
                          join sm.moveitems mi on mi.moveperiod_id = mp.id
                          join sm.movesets ms on ms.id = mp.moveset_id
                          join sm.transferbasis t on t.id = ms.transferbasis_id
                          join sm.clients cl on cl.id = ms.client_id
                          left join sm.organisations org on org.clients_id = cl.id
                          left join sm.leasepurpose lp on lp.id = mi.leasepurpose_id
                         where ms.movetype_id = Amovetype_id
                           and mi.object_id = Aobject_id
                           and coalesce(mp.enddate, cast('01.01.2050' as date)) <= sysdate
                      order by mp.enddate desc
                        ) s   
                 --where rownum <=1   -- закомментировано, так как предыдущих операций одного вида может быть несколько! поэтому собирается строка из значений                    
               )
    loop
       --основание
       if (trim(Flag) = '5') then
         Res:=Res || to_char(i)||'. '||xxx.name_transferbasis||chr(13);
          i:=i+1;
       end if;
       --назначение
       if (trim(Flag) = '6') then
         Res:=Res || to_char(i)||'. '||xxx.lp_name||chr(13);
       i:=i+1;  
       end if;
       --счет збалансовый учет
       if (trim(Flag) = '7') then
         --res := xxx.account_zabuch;
               Res:=Res || to_char(i)||'. '||xxx.account_zabuch||chr(13);
       i:=i+1;  
       end if;
       --доля собственности
       if (trim(Flag) = '8' and xxx.client_id = 5100) then
         Res:=Res || to_char(i)||'. '||xxx.share_num || '/' || xxx.share_denom||chr(13);
          i:=i+1;
       end if;
       
       --бывшие субъекты операций
       if (trim(Flag) = '10') then        
         Res:=Res || to_char(i)||'. '||trim(xxx.org_name)||'. ';
       i:=i+1;  
       end if;
       
    end loop;
  end if;
  
  return(res);
end GET_OD_DATA;
/
grant execute on SM.GET_OD_DATA to SM_ALLUSERS;
grant execute on SM.GET_OD_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GETPARENTINFO
prompt ===============================
prompt
create or replace function sm.GetParentInfo(Flag in char, Aobject_id in number, Amovetype_id in number) return varchar2 is
  Result varchar2(4000);
  document varchar2(1024);
  parent_id number(27);
begin
  /*03052019 Чувыкин: выводит по нужной операции движения информацию об объекте. Если информации таковой нет, то инфа берется по родителю -  ОТДЕЛЬНОСТОЯЩЕМУ зданию*/
  /*
    Flag:
         1 - основной документ
         2 - основание операции движения
  */
  Result := '';
  
  -- Сначала проверим, не оформлены ли на объект нужные операции, если да, сразу снимем результат
  if (Flag = '1') then
  begin 
   result := ExpandDoc(sm.GetDocByMoveID(sm.GetPositionMoveID(Aobject_id,Amovetype_id)));
   exception
              when NO_DATA_FOUND then
               null;
  end;
  end if;
  
  if (Flag = '2') then
  begin 
   result := GET_OD_DATA (Aobject_id,Amovetype_id,'1');
   exception
              when NO_DATA_FOUND then
               null;
  end;             
  end if;
  
  
  if Result is null then -- если на задаваемый объект ничего не оформлено, ищем отдельностоящего хозяина
             
             select b.objects_id
             into parent_id -- id отдельностоящего хозяина
               from sm.Buildings b
               where b.basebuilding is null
               start with b.objects_id = Aobject_id
               connect by prior b.basebuilding = b.id;

    if (Flag IN ('1', '2')) then
       -- теперь по объектам ищем нужную информацию
       for yy in(
                  -- запрос основание ОД и id пакета документов ПОСЛЕДНЕГО НЕЗАКРЫТОГО ПЕРИОДА переданной в функцию ОД 
                  select 
                         mp.docset_id,
                         t.name as name_transferbasis

                    from sm.moveitems mi
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets ms on ms.id = mp.moveset_id
                    
                    join sm.transferbasis t on t.id = ms.transferbasis_id

                   where mi.object_id = parent_id
                     and ms.movetype_id = Amovetype_id
                     and mp.enddate is null -- нужен только последний незакрытый период
                )
       loop

         if (Flag = '1') then
            -- найдем его
            begin
              -- запрос находит основной документ в пакете документов
              select sm.expanddoc(dm.document_id) doc
                into document
                from sm.docset_members dm
                join sm.documents d on d.id = dm.document_id
                where dm.docset_id = yy.docset_id
                  and dm.docrole_id = 1;
              exception
              when NO_DATA_FOUND then
               null;
            end;
            Result := document;
          end if;

          if (Flag = '2') then
               Result := yy.name_transferbasis ;
          end if;

       end loop;
    end if;
  end if;
  return(Result);
end GetParentInfo;
/
grant execute on SM.GETPARENTINFO to SM_ALLUSERS;


prompt
prompt Creating function GETPAYDISTRIBUTEDSUM
prompt ======================================
prompt
create or replace function sm.GetPayDistributedSum(APaymentID in number, AObligationID in number, WHAT in varchar2) return number is
--
-- by XSGROUP ver. 17.05.2010
--
-- функция возвращает распределённую сумму платежа
-- APaymentID     - ID платежа
-- AObligationID  - ID обязательства
-- WHAT           - что возвращать:
--  'ALL'         - всю распределённую сумму   
--  'OBLIGATION'  - сумму, распределённую на погашение основного обязательства
--  'FINE'        - сумму, распределённую на погашение пени
--  'PERCENT'     - сумму, распределённую на погашение процентов по рассрочке
--  'OTHER'       - сумму, распределённую на дополнительные начисления по основному обязательству

result number(27,2);
begin
  
  if WHAT='ALL' then
  
    result:=sm.GetPayDistributedSum(APaymentID,AObligationID,'OTHER')+
            sm.GetPayDistributedSum(APaymentID,AObligationID,'OBLIGATION')+
            sm.GetPayDistributedSum(APaymentID,AObligationID,'FINE')+
            sm.GetPayDistributedSum(APaymentID,AObligationID,'PERCENT');
    return (result);
  
  end if;
  
  begin
  select nvl(sum(pd.val),0)
  into
    result
  from
    sm.payments p,
    sm.payments_distribution pd,
    sm.payments_plan pp,
    sm.charges ch,
    sm.obligations o
  where
    p.id=APaymentID and
    pd.payments_id=p.id and
    pp.id=pd.payments_plan_id and
    ch.id=pp.charges_id and
    o.id=AObligationID and
    ch.obligationtype_id=o.obligationtype_id and
    ch.Movesets_Id=o.moveset_id and
    trim(ch.charge_type)=WHAT;
  exception
    when NO_DATA_FOUND then
    return (0.00);
  end;
  
  return(result);
      
end;
/
grant execute on SM.GETPAYDISTRIBUTEDSUM to SM_ALLUSERS;
grant execute on SM.GETPAYDISTRIBUTEDSUM to SM_ALL_SELECT;


prompt
prompt Creating function GETPAYMENTCOMMENT
prompt ===================================
prompt
create or replace function sm.GetPaymentComment(PAYMENTS_ID IN NUMBER) RETURN VARCHAR2 as
  CommentStr VARCHAR2(4000);
  DOC_DESCR VARCHAR2(4000);
  PAY_CHAR VARCHAR2(1);
  PAYMETHOD_ID number;
begin
 --
 --  XSGROUP 15.01.2005г. - 13.05.2010
 --  функция возвращает строку комментария к платежам
 --  отображаемом в окне свода расчётов по обязательству
 --  клиента  SAUMI
 --
 select sm.ExpandDoc(documents_id),
        mainpay,
        paymethod_id
   into DOC_DESCR,
        PAY_CHAR,
        PAYMETHOD_ID
   from sm.payments p
  where p.id=PAYMENTS_ID;

  CommentStr:=DOC_DESCR;

  if PAY_CHAR='Y' then
    if PAYMETHOD_ID=3 then
      CommentStr:='(Списание основн. долга) - '||CommentStr;
    else 
      CommentStr:='Оплата - '||CommentStr;  
    end if;
  else
    if PAYMETHOD_ID=3 then
      CommentStr:='(Списание долга по пене) - '||CommentStr;
    else 
      CommentStr:='Оплата - '||CommentStr;  
    end if;
  end if;

 return CommentStr;

end;
/
grant execute on SM.GETPAYMENTCOMMENT to SM_ALLUSERS;
grant execute on SM.GETPAYMENTCOMMENT to SM_ALL_SELECT;


prompt
prompt Creating function GETPERIODNAME
prompt ===============================
prompt
create or replace function sm.GetPeriodName(PeriodType IN VARCHAR2, GDate in DATE) return varchar2 is
  Result varchar2(20);
  RD DATE;
  r integer;
  y integer;
begin
 RD:=trunc(GDate,'MONTH');
 r:=MONTHS_BETWEEN(RD,trunc(RD,'YEAR'))+1;
 y:=2000+MONTHS_BETWEEN(trunc(RD,'YEAR'),'01.01.2000')/12;

 if (PeriodType='Y') or (PeriodType='M') THEN
  select decode(R,1,'Январь',2,'Февраль',3,'Март',4,'Апрель',5,'Май',6,'Июнь',7,'Июль',8,'Август',9,'Сентябрь',10,'Октябрь',11,'Ноябрь',12,'Декабрь','???') || TO_CHAR(y) into Result from dual;
  return(Result);
 ELSIF PeriodType='Q' THEN
  select decode(R,1,'1 кв.',2,'1 кв.',3,'1 кв.',4,'2 кв.',5,'2 кв.',6,'2 кв.',7,'3 кв.',8,'3 кв.',9,'3 кв.',10,'4 кв.',11,'4 кв.',12,'4 кв.','???') || ' ' || TO_CHAR(y) into Result from dual;
  return(Result);
 ELSIF PeriodType='H' THEN
  select decode(R,1,'1 полуг.',2,'1 полуг.',3,'1 полуг.',4,'1 полуг.',5,'1 полуг.',6,'1 полуг.',7,'2 полуг.',8,'2 полуг.',9,'2 полуг.',10,'2 полуг.',11,'2 полуг.',12,'2 полуг.','???') || ' ' || TO_CHAR(y) into Result from dual;
  return(Result);
 ELSIF PeriodType='G' THEN
  select TO_CHAR(y) || ' г.' into Result from dual;
  return(Result);
 END IF;
end GetPeriodName;
/
grant execute on SM.GETPERIODNAME to SM_ALL_SELECT;


prompt
prompt Creating function GETPERIODNAMEEX
prompt =================================
prompt
create or replace function sm.GetPeriodNameEx(PeriodType IN NUMBER, GDate in DATE) return varchar2 is
  Result varchar2(20);
  RD DATE;
  r integer;
  y integer;
begin
 if PeriodType>3 then
  return('['||to_char(GDate,'DD.MM.YYYY')||'] ' || to_char(GDate));
 else
  RD:=trunc(GDate,'MONTH');
  r:=MONTHS_BETWEEN(RD,trunc(RD,'YEAR'))+1;
  y:=2000+MONTHS_BETWEEN(trunc(RD,'YEAR'),'01.01.2000')/12;

  if (PeriodType=3) THEN
   select decode(R,1,'Январь',2,'Февраль',3,'Март',4,'Апрель',5,'Май',6,'Июнь',7,'Июль',8,'Август',9,'Сентябрь',10,'Октябрь',11,'Ноябрь',12,'Декабрь','???') into Result from dual;
   return('['||to_char(GDate,'DD.MM.YYYY')||'] ' || Result || ' ' || TO_CHAR(y) || 'г.');
  ELSIF PeriodType=2 THEN
   select decode(R,1,'1 кв.',2,'1 кв.',3,'1 кв.',4,'2 кв.',5,'2 кв.',6,'2 кв.',7,'3 кв.',8,'3 кв.',9,'3 кв.',10,'4 кв.',11,'4 кв.',12,'4 кв.','???') || ' ' || TO_CHAR(y) into Result from dual;
   return('['||to_char(GDate,'DD.MM.YYYY')||'] ' || Result);
  ELSIF PeriodType=1 THEN
   select TO_CHAR(y) || ' г.' into Result from dual;
   return('['||to_char(GDate,'DD.MM.YYYY')||'] ' || Result);
  END IF;

 end if;

end GetPeriodNameEx;
/
grant execute on SM.GETPERIODNAMEEX to SM_ALLUSERS;
grant execute on SM.GETPERIODNAMEEX to SM_ALL_SELECT;


