prompt Creating function GETPOSITION
prompt =============================
prompt
create or replace function sm.GetPosition(ObjID NUMBER, MoveTypes_ID NUMBER) return varchar2 is
  Recv VARCHAR2(150);
  todate date;
begin

 SELECT Clients.Name INTO Recv
 FROM Clients
 WHERE
  ID=GetPositionClientID(Objid,Movetypes_Id);

 select o.exists_end
   into todate
   from sm.objects o
  where o.id = ObjId;

 if (todate is not null) then
   if (sysdate > todate) then
     Recv := '';
   end if;
 end if;

  return(RTRIM(Recv));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN ' ';

end GetPosition;
/
grant execute on SM.GETPOSITION to SM_ALLUSERS;
grant execute on SM.GETPOSITION to SM_ALL_SELECT;


prompt
prompt Creating function GETPOSITIONALLMOVEID
prompt ======================================
prompt
create or replace function sm.GetPositionAllMoveID(ObjID NUMBER, MoveTypes_ID NUMBER, AClient_id in number default NULL, MoveN in number default NULL) return NUMBER is
  Res NUMBER(27,0);
  i number;
begin
-- 27092020 - Чувыкин В.Э. - возвращает операции движения одного вида (действующие), вытаскивает по номеру MoveN
  begin
   
   i:=1;
   
   for xxx in ( 
               SELECT mi.id mi_id
               FROM Clients,
                 sm.movesets ms,
                 sm.moveperiods mp,
                 sm.moveitems mi
               WHERE
                ms.id=mp.moveset_id and
                mp.id=mi.moveperiod_id and
                ObjID=mi.object_id(+) and
                Clients.ID(+)=ms.client_id  and
                mp.sincedate(+)<=SYSDATE and
                nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=SYSDATE and
                ms.movetype_id(+)=MoveTypes_ID and
                (ms.client_id = AClient_id or AClient_id is null)
                order by mi.id --desc
               )
   loop
   
     if i = MoveN then
       RES := xxx.mi_id;
     end if;
     
     i:=i+1; 
      
   end loop;


   EXCEPTION
   WHEN NO_DATA_FOUND THEN NULL;
  end;

  return(RTRIM(Res));
end;
/
grant execute on SM.GETPOSITIONALLMOVEID to SM_ALLUSERS;


