prompt Creating function GETPOSITIONCLIENTBYDATE
prompt =========================================
prompt
create or replace function sm.GetPositionClientByDate(ObjID NUMBER, MoveTypes_ID NUMBER, ADate Date) return varchar2 is
  Recv varchar2(150);
begin
-- выводит субъекта последней по сроку завершения операции движения заданного типа на заданном объекте
select * INTO Recv from ( 
 SELECT clients.name 
 FROM sm.Clients,
      sm.movesets ms,
      sm.moveperiods mp,
      sm.moveitems mi
 WHERE
  ms.id=mp.moveset_id and
  mp.id=mi.moveperiod_id and
  ObjID=mi.object_id(+) and
  Clients.ID(+)=ms.client_id and
  mp.sincedate(+)<=SYSDATE and
  nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=ADATE and
  ms.movetype_id(+)=MoveTypes_ID
  order by mp.enddate desc)
where rownum = 1;
  
  return(Recv);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end;
/
grant execute on SM.GETPOSITIONCLIENTBYDATE to SM_ALLUSERS;


prompt
prompt Creating function GETPOSITIONCLIENTWITHEXISTS
prompt =============================================
prompt
create or replace function sm.GetPositionClientWithExists(ObjID NUMBER, MoveTypes_ID NUMBER, CDate IN DATE) return NUMBER is

--by XS Group, ver. 09.06.2008
--функция возвращает ID клиента на имя которого оформлено движения объекта ObjID,
-- вида движения MoveType_ID в момент времени CDate
-- с учетом существования части здания в здании: таблица BUILDINGS поля EXISTS_SINCE и EXISTS_END

  Recv NUMBER:=null;
  ObjType NUMBER;
  BaseBuildID NUMBER;
  BaseObjID NUMBER;
begin
  for x IN ( select 
               ms.client_id ClientID 
             from
               sm.Movesets ms,
               sm.moveitems mi,
               sm.moveperiods mp
             where
               ms.movetype_id=MoveTypes_Id and
               mp.moveset_id=ms.id and
               mi.moveperiod_id=mp.id and
               mi.object_id=ObjID and
               trunc(mp.sincedate)<=trunc(CDate) and
              (trunc(mp.enddate)>=trunc(CDate) or mp.enddate is null)) 
  loop

    Recv:=x.ClientID;

    exit;
  end loop;

 if Recv is not null then
   return(Recv);
 end if;

 select ObjTypes_ID into ObjType from sm.Objects where ID=ObjID;
 
 -- разбор случая, если это здание
 if ObjType = 3 then
   select 
     Basebuilding 
   into 
     BaseBuildID
   from 
     sm.Buildings b
   where 
     Objects_ID=ObjID
     and 
     (b.exists_since <= CDate or b.exists_since is null)
     and 
     (b.exists_end >= CDate or b.exists_end is null) ;

   if (BaseBuildID is not null) then
     select 
       Objects_ID 
     into 
       BaseObjID
     from 
       sm.Buildings
     where 
       ID=BaseBuildID;
       
     Return (sm.GetPositionClientIDByDate(BaseObjID,MoveTypes_ID,CDate));
   end if;
 end if;

 return(Recv);

exception
 when NO_DATA_FOUND then return null;

end;
/
grant execute on SM.GETPOSITIONCLIENTWITHEXISTS to SM_ALL_SELECT;


