prompt
create or replace function sm.GetPositionMoveIDByDate(ObjID NUMBER, MoveTypes_ID NUMBER, CDate IN DATE) return NUMBER is

-- Чувыкин В.Э. 090619
-- функция возвращает MoveItems.ID операции движения, оформленной на объекте ObjID,
-- вида движения MoveType_ID в момент времени CDate
--
  Recv NUMBER:=null;
  
begin

    select
               mi.id MoveID into recv
             from
               sm.Movesets ms,
               sm.moveitems mi,
               sm.moveperiods mp
             where
               ms.movetype_id=MoveTypes_Id and
               mp.moveset_id=ms.id and
               mi.moveperiod_id=mp.id and
               mi.object_id=ObjID and
               trunc(mp.sincedate)<=trunc(CDate) and
              (trunc(mp.enddate)>=trunc(CDate) or mp.enddate is null)
              and rownum = 1;

 return(Recv);

exception
 when NO_DATA_FOUND then return null;

end;
