prompt
prompt Creating function GETPOSITIONMOVEIDBYTRBASROOT
prompt ==============================================
prompt
create or replace function sm.GetPositionMoveIDByTrBasROOT(ObjID NUMBER, MoveTypes_ID NUMBER, AClient_id in number default NULL, TransBasRoot number) return NUMBER is
mi_id NUMBER(27,0);
  Res NUMBER(27,0);

begin
-- 24072022 - Чувыкин В.Э. - возвращает операции движения одного вида (действующие), вытаскивает по id ветки справочника оснований ОД
  begin
   

               SELECT mi.id into mi_id
               FROM Clients,
                 sm.movesets ms,
                 sm.moveperiods mp,
                 sm.moveitems mi
               WHERE
                ms.id=mp.moveset_id and
                mp.id=mi.moveperiod_id and
                ObjID=mi.object_id(+) and
                Clients.ID(+)=ms.client_id  and
                mp.sincedate(+)<=SYSDATE and
                nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=SYSDATE and
                ms.movetype_id(+)=MoveTypes_ID and
                (ms.client_id = AClient_id or AClient_id is null) and
                ms.TRANSFERBASIS_ID IN (SELECT ID FROM SM.TRANSFERBASIS START WITH ID=TransBasRoot CONNECT BY PRIOR ID=ROOT) and
                rownum = 1             
                ; 
 
       RES := mi_id;


   EXCEPTION
   WHEN NO_DATA_FOUND THEN NULL;
  end;

  return(RTRIM(Res));
end;
/
grant execute on SM.GETPOSITIONMOVEIDBYTRBASROOT to SM_ALLUSERS;


