prompt
prompt Creating function GETPOSITIONMOVETRBASISIDBYDATE
prompt ================================================
prompt
create or replace function sm.GetPositionMoveTrBasisIDByDate(ObjID NUMBER, MoveTypes_ID NUMBER, CDate in date) return NUMBER is
--функция возвращает ID основания операции движения, оформленной с объектом ObjID,
-- вида движения MoveType_ID в на дату CDate
  Recv NUMBER(27,0);
  ObjType NUMBER(27,0);
  BaseBuildID NUMBER(27,0);
  BaseObjID NUMBER(27,0);
begin
 Recv:=NULL;

 SELECT ObjTypes_ID INTO ObjType FROM Objects WHERE ID=ObjID;
 -- если это не здания и помещения - никаких проблем

  for x IN (
   select --+ FIRST_ROWS
     m.TRANSFBASIS_ID TrBasisID 
   from
    Movements m
   where
    m.MoveType_ID=MoveTypes_Id and
    m.OBJECTS_ID=ObjID and
    m.POSTINGDATE<=CDate and
    (m.EndDate is null or m.EndDate>=CDate)) loop

   Recv:=x.TrBasisID;

   exit;
  end loop;


 IF not Recv IS NULL THEN
  return(Recv);
 END IF;

 -- разбор случая, если это здание
 IF ObjType = 3 THEN
  SELECT Basebuilding INTO BaseBuildID
  FROM Buildings
  WHERE Objects_ID=ObjID;

  IF NOT (BaseBuildID IS NULL) THEN
   SELECT Objects_ID INTO BaseObjID
   FROM Buildings
   WHERE ID=BaseBuildID;
   Return (GetPositionMoveTrBasisIDByDate(BaseObjID,MoveTypes_ID,CDate));

  END IF;
 END IF;

 return(RTRIM(Recv));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end;
/
grant execute on SM.GETPOSITIONMOVETRBASISIDBYDATE to SM_ALLUSERS;
grant execute on SM.GETPOSITIONMOVETRBASISIDBYDATE to SM_ALL_SELECT;


prompt
prompt Creating function GETPOSITIONSTARTDATE
prompt ======================================
prompt
create or replace function sm.GetPositionStartDate(ObjID NUMBER, MoveTypes_ID NUMBER) return date is
  Recv DATE;
begin

 SELECT max(mp.sincedate) INTO Recv
 FROM sm.Clients, 
      sm.movesets ms,
      sm.moveperiods mp,
      sm.moveitems mi
 WHERE
  ms.id=mp.moveset_id and
  mp.id=mi.moveperiod_id and
  ObjID=mi.object_id(+) and
  Clients.ID(+)=ms.client_id and
  mp.sincedate(+)<=SYSDATE and
  nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>=SYSDATE and
  ms.movetype_id(+)=MoveTypes_ID;

  return(Recv);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end;
/
grant execute on SM.GETPOSITIONSTARTDATE to SM_ALLUSERS;
grant execute on SM.GETPOSITIONSTARTDATE to SM_ALL_SELECT;


