prompt
prompt Creating function GETPROFIT
prompt ===========================
prompt
create or replace function sm.GetProfit (Flag in char, AMovesets_id in number) return number is
  Result number;
begin
  /*Получает прибыль
    Flag 1 - прибыли за год
         2 - 25 %  от прибыли
         3 - ежемесясный платеж    
  */  
  for xxx in (
              select mp.profit
                from sm.moveperiods mp
               where mp.moveset_id = AMovesets_id
                 and mp.sincedate <= sysdate
                 and (mp.enddate >= sysdate or mp.enddate is null)
              )
  loop 
     if (trim(flag) = '1') then
       Result := xxx.profit;          
     elsif (trim(flag) = '2') then
       Result := round(xxx.profit/4,2); 
     elsif (trim(flag) = '3') then
       Result := round(xxx.profit/9,2);
     end if;                  
  end loop;                        
  return(Result);
end GetProfit;
/
grant execute on SM.GETPROFIT to SM_ALL_SELECT;


prompt
prompt Creating function GETPROPERTY_AS
prompt ================================
prompt
CREATE OR REPLACE FUNCTION SM.GetProperty_AS(par_objects_id IN NUMBER) RETURN CHAR IS
RES	varchar2(1000);
  -- Разработал Андрей Владимирович Солопко
  -- 2009-10-06
  aserialnum VARCHAR2(500);
  -- adateissue date;
  adateissue INTEGER;
  adateinput date;
  ainfo VARCHAR2(3000);
BEGIN
  SELECT sm.property.serialnum, sm.property.dateissue, sm.property.dateinput, sm.property.info
  INTO aserialnum, adateissue, adateinput, ainfo
  FROM sm.property
  WHERE
  OBJECTS_ID = par_objects_id;

  RES:='';
 
  IF NOT (aserialnum IS NULL) THEN
    RES:=SUBSTR(RES || ' (Заводской номер - ' || aserialnum || ')',1,500);
  END IF;
  IF NOT (adateissue IS NULL) THEN
    RES:=SUBSTR(RES || ' (Дата выпуска - ' || TO_CHAR(adateissue) || ')',1,500);
  END IF;
  IF NOT (adateinput IS NULL) THEN
    RES:=SUBSTR(RES || ' (Дата ввода в эксплуатацию - ' || TO_CHAR(adateinput) || ')',1,500);
  END IF;
  IF NOT (ainfo IS NULL) THEN
    RES:=SUBSTR(RES || ' (Доп. инф. - ' || ainfo || ')',1,500);
  END IF;

  RES:=RTRIM(RES);
 
  RES:=SUBSTR(RES,1,length(Res));

  RETURN RES;

END;
/
grant execute on SM.GETPROPERTY_AS to SM_ALLUSERS;
grant execute on SM.GETPROPERTY_AS to SM_ALL_SELECT;


prompt
prompt Creating function GETREALDISCOUNTSIZE
prompt =====================================
prompt
create or replace function sm.GetRealDiscountSize(sdate in DATE, edate in DATE, charge_type VARCHAR2, ms_id NUMBER, obl_id NUMBER, d_value NUMBER) return NUMBER is
  Result number(27,2);
  c_type VARCHAR2(10);
begin
  --вспомогательная функция для отчетов по льготам
  --и поиска фактически недоначисленных средств

  --преобразовываем значения из таблицы disconts в аналогичные значения таблицы charges
  select decode(charge_type,'MAIN','OBLIGATION','FINE','FINE') into c_type from dual;

  
  --выбираем начисления, которые попадают в период действия льготы
  --суммируем сумму начисления и сумму скидки и узнаем тем самым сумму без льготы
  select sum(c.discountsize+c.paysize) into Result from sm.charges c
      where c.discountsize is not null and
          c.movesets_id=ms_id and
          c.obligationtype_id=obl_id and
          RTRIM(c.charge_type)=c_type and
          ((c.calperiod_start<=edate) or (edate is null)) and
          (c.calperiod_end>=sdate);

  --вычисляем сумму для этой конкретной льготы 
  --так сделано для того чтобы решить вопрос с пересекающимися льготами
  --когда процент скидки суммируется и в discountsize помещается уже полная скидка
  Result :=Result*d_value;
            
  return(Result);
  
end GetRealDiscountSize;
/
grant execute on SM.GETREALDISCOUNTSIZE to SM_ALLUSERS;
grant execute on SM.GETREALDISCOUNTSIZE to SM_ALL_SELECT;


prompt
prompt Creating function GETROOTDOCTYPEID
prompt ==================================
prompt
create or replace function sm.GetRootDoctypeID(ACurrDoctypeID in number) return number is
  Result number;
  RootID number;
  Reserving_flag char(1);
begin

  -- by XSGROUP 24.01.2009
  -- функция находит корневой тип документа
  -- для  типа документа ACurrDoctypeID,
  -- у которого выставлен флажок резервирования номера документа (reserving='Y') 
  --
  
  select
    nvl(dt.reserving,'N'),
    nvl(dt.root,0)
  into 
    Reserving_flag,
    RootID 
  from
    sm.doctypes dt
  where
    dt.id=ACurrDoctypeID;
  -- если для данного типа документа укстановлено резервирование номеров - возвращаем его ID  
  if Reserving_flag='Y' then
    return(ACurrDoctypeID);
  end if;
  
  -- если у данного типа документа нет вышележащего уровня - возвращаем его ID
  if RootID=0 then
    return(ACurrDoctypeID);
  end if;
  
  select
    nvl(dt.reserving,'N')
  into 
    Reserving_flag 
  from
    sm.doctypes dt
  where
    dt.id=RootID;
  
  -- если у вышестоящего уровня установлено резервирование номеров - возвращаем ID этого уровня  
  -- иначе - возвращаем ID исходного типа документа
  if Reserving_flag='Y' then
    return(RootID);
  else
    return(ACurrDoctypeID);
  end if;
     
end GetRootDoctypeID;
/
grant execute on SM.GETROOTDOCTYPEID to SM_ALLUSERS;
grant execute on SM.GETROOTDOCTYPEID to SM_ALL_SELECT;


