                and cha.moveset_id = decode(A_MS_ID, null, cha.moveset_id, 0, cha.moveset_id, A_MS_ID)
                and cha.moveset_id = decode(A_MSTYPE_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.movetype_id=A_MSTYPE_ID and ROWNUM=1))
                and cha.moveset_id = decode(A_CLIENT_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.client_id=A_CLIENT_ID and ROWNUM=1))
          )
     loop
        Saldo := Saldo + xx.summ; 
     end loop;  
   end if;     
 
   -- начислено
   if upper(A_TypeCalc) = 'CHARGE' then
      for xx in (select sum(cha.summ) summ
                  from sm.charge_applies cha 
                  where cha.apply_date > A_Date_Start and cha.apply_date <= A_Date_End
                        and cha.obligtype_id = A_ObligationType_ID
                        and nvl(cha.cls_kbk_id, 0) = decode(A_KBK_ID, null, nvl(cha.cls_kbk_id, 0), 0, nvl(cha.cls_kbk_id, 0), nvl(A_KBK_ID,0))   
                        and cha.charge_type = A_ChargeType
                        and NVL(cha.CHARGE_ID,0) <> 0 
                        and cha.moveset_id = decode(A_MS_ID, null, cha.moveset_id, 0, cha.moveset_id, A_MS_ID)
                and cha.moveset_id = decode(A_MSTYPE_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.movetype_id=A_MSTYPE_ID and ROWNUM=1))
                and cha.moveset_id = decode(A_CLIENT_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.client_id=A_CLIENT_ID and ROWNUM=1))
                  )
       loop
           Saldo := Saldo + xx.summ;
       end loop;
   end if;
   
   -- оплачено
   if upper(A_TypeCalc) = 'PAY' then
     for xx in (select sum(case when pd.id is not null then pd.val when decode(pp.mainpay, 'N', 'F', 'O') = A_ChargeType then cha.summ else 0 end) summ
                from sm.charge_applies cha, 
                        sm.Payments pp, 
                        sm.payments_distribution pd,
                        sm.payments_plan ppl,
                        sm.charges ch
                where pp.id(+) = cha.payment_id 
                       and pd.payments_id(+) = pp.id
                       and ppl.id(+) = pd.payments_plan_id 
                       and ppl.charges_id = ch.id(+)                
                       and cha.apply_date > A_Date_Start and cha.apply_date <= A_Date_End
                       and cha.obligtype_id = A_ObligationType_ID
                       and nvl(cha.cls_kbk_id, 0) = decode(A_KBK_ID, null, nvl(cha.cls_kbk_id, 0), 0, nvl(cha.cls_kbk_id, 0), nvl(A_KBK_ID,0)) 
                       and (case when pd.id is not null then decode (trim(ch.charge_type), 'FINE', 'F', 'O') else decode(pp.mainpay, 'N', 'F', 'O') end) = A_ChargeType
                       and NVL(cha.CHARGE_ID,0) = 0 and NVL(cha.PAYMENT_ID,0) <> 0 
                       and cha.moveset_id = decode(A_MS_ID, null, cha.moveset_id, 0, cha.moveset_id, A_MS_ID)
                and cha.moveset_id = decode(A_MSTYPE_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.movetype_id=A_MSTYPE_ID and ROWNUM=1))
                and cha.moveset_id = decode(A_CLIENT_ID, null, cha.moveset_id, (select ms.id from sm.movesets ms where ms.id=cha.moveset_id and ms.client_id=A_CLIENT_ID and ROWNUM=1))
                               )
      loop
        Saldo := Saldo + xx.summ;
      end loop;
   end if;
   
   return(Saldo);
end;
/
grant execute on SM.GETSALDOCHARGEAPPLIESSKD to SM_ALLUSERS;
grant execute on SM.GETSALDOCHARGEAPPLIESSKD to SM_ALL_SELECT;


prompt
prompt Creating function GETSALDOCHARGE_APPLIES
prompt ========================================
prompt
create or replace function sm.GetSaldoCharge_Applies(
        A_Date_Start in date,
        A_Date_End in date,
        A_ObligationType_ID in number, 
        A_ChargeType in varchar2,
        A_KBK_ID in number,
        A_TypeCalc in varchar2)
        return number 
is

--    функция возвращает сальдо по виду начисления обязательства на указанную дату.
--    параметр A_TypeCalc - вид расчета:
--                Deb - дебет
--                Kredit - кредит
--                Charge - начисления
--                Pay - оплата
  
  Saldo number(27,2);
  SaldoMS number(27,2);
  MS_prev number;
  A_Date date; -- дата, на которую расчитывается сальдо по проводкам
  
begin
  Saldo :=0;
  MS_prev := 0;
  SaldoMS := 0;
  
  if upper(A_TypeCalc) = 'DEB' or  upper(A_TypeCalc) = 'KREDIT' then
     select case when A_Date_Start is not null then A_Date_Start else A_Date_End end into A_Date from dual;

     for xx in (select 
                 cha.charge_type,
                 cha.obligtype_id,
                 cha.moveset_id,
                 sum(case when cha.charge_type in ('Y', 'N') then -cha.summ else cha.summ end) summ
          from sm.charge_applies cha
          where cha.apply_date <= A_Date
                and cha.obligtype_id = A_ObligationType_ID 
                and nvl(cha.cls_kbk_id, 0) = A_KBK_ID
                and decode(cha.charge_type, 'O','O','F','F','Y','O','N','F') = A_ChargeType
                and upper(trim(cha.description)) <> 'КОРРЕКТИРУЮЩАЯ ПРОВОДКА'
--                and (cha.charge_id is not null or cha.payment_id is not null)
          group by  cha.charge_type, cha.obligtype_id, cha.moveset_id
          order by cha.moveset_id)
     loop
       if MS_prev <> xx.moveset_id then
            MS_prev := xx.moveset_id;  
           
            if SaldoMS > 0 and upper(A_TypeCalc) = 'DEB' then
               Saldo := Saldo + SaldoMS;
            end if;
            
            if SaldoMS < 0 and upper(A_TypeCalc) = 'KREDIT' then
               Saldo := Saldo + SaldoMS;
            end if;  
            
            SaldoMS := 0;
        end if;
        
        SaldoMS := SaldoMS + xx.summ;       
     end loop;
     
     if SaldoMS > 0 and upper(A_TypeCalc) = 'DEB' then
       Saldo := Saldo + SaldoMS;
     end if;
    
     if SaldoMS < 0 and upper(A_TypeCalc) = 'KREDIT' then
       Saldo := Saldo + SaldoMS;
     end if;  
                 
  end if;
   
   
 
 -- начислено
   if upper(A_TypeCalc) = 'CHARGE' then
      for xx in (select 
                         cha.charge_type,
                         cha.obligtype_id,
                         cha.moveset_id,
                         sum(cha.summ) summ
                  from sm.charge_applies cha
                  where cha.apply_date between A_Date_Start and A_Date_End
                        and cha.obligtype_id = A_ObligationType_ID
                        and nvl(cha.cls_kbk_id, 0) = A_KBK_ID
--                        and cha.charge_id is not null 
                        and cha.charge_type = A_ChargeType
                        and upper(trim(cha.description)) <> 'КОРРЕКТИРУЮЩАЯ ПРОВОДКА'
                             group by  cha.charge_type, cha.obligtype_id, cha.moveset_id)
       loop
           Saldo := Saldo + xx.summ;
       end loop;
   end if;
   
 -- оплачено
   if upper(A_TypeCalc) = 'PAY' then
     for xx in (select 
                       decode (cha.charge_type, 'Y', 'O', 'N', 'F'),
                       cha.obligtype_id,
                       cha.moveset_id,
                       sum(cha.summ) summ
                from sm.charge_applies cha
                where cha.apply_date between A_Date_Start and A_Date_End
                      and cha.obligtype_id = A_ObligationType_ID
                      and nvl(cha.cls_kbk_id, 0) = A_KBK_ID
                      and A_ChargeType =  decode (cha.charge_type, 'Y', 'O', 'N', 'F')
                      and upper(trim(cha.description)) <> 'КОРРЕКТИРУЮЩАЯ ПРОВОДКА'
--                      and cha.payment_id is not null   
                group by  cha.charge_type, cha.obligtype_id, cha.moveset_id)
      loop
           Saldo := Saldo + xx.summ;
      end loop;
   
   end if;
   
  return(Saldo);
end;
/
grant execute on SM.GETSALDOCHARGE_APPLIES to SM_ALLUSERS;
grant execute on SM.GETSALDOCHARGE_APPLIES to SM_ALL_SELECT;


prompt
prompt Creating function GETSDOAREABYTABLE
prompt ===================================
prompt
create or replace function sm.GetSDOAreaByTable(Owner in varchar2,
                                             TableName in varchar2,
                                             SDOField in varchar2,
                                             KeyField in varchar2, 
                                             SDO_ID in number)
-- Вычисление площади/длины объекта SDO_Geometry
-- %author XSGROUP - HAWK
-- %created 25.04.05 15:49
-- %param Owner Схема в которой храниться таблица 
-- %param TableName Таблица с геоданными
-- %param SDOField Поле с геоданными в таблице 
-- %param KeyField Ключевое поле по которому устанавливается связь с объектами SAUMI
-- %param SDO_ID Идентификатор объекта карты для которого необходимо найти площадь/длину
-- %return Площадь/длину объекта карты
return number as
  sq number;
  c number;
  rc number;
  sqlt varchar2(1000);
begin
  sqlt:='';
  sqlt:=sqlt||'declare ';
  sqlt:=sqlt||'  function GetSDOArea(SDO_ID in number) ';
  sqlt:=sqlt||'  return number as ';
  sqlt:=sqlt||'    geom mdsys.sdo_geometry; ';
  sqlt:=sqlt||'    dim mdsys.sdo_dim_array; ';
  sqlt:=sqlt||'  begin ';
  sqlt:=sqlt||'    select '||SDOField||' into geom from '||Owner||'.'||TableName||' where '||KeyField||'=SDO_ID; ';
  sqlt:=sqlt||'    select diminfo into dim from all_sdo_geom_metadata where table_name=upper('''||TableName||''') ';
  sqlt:=sqlt||'      and owner=upper('''||Owner||'''); ';
  sqlt:=sqlt||'    return abs(sdo_geom.sdo_area(geom, dim)); ';
  sqlt:=sqlt||'  end; ';
  sqlt:=sqlt||'begin ';
  sqlt:=sqlt||'  :sq := GetSDOArea('||to_char(SDO_ID)||'); ';
  sqlt:=sqlt||'end;';

  c := DBMS_SQL.OPEN_CURSOR;
  DBMS_SQL.PARSE( c, sqlt, DBMS_SQL.NATIVE);
  DBMS_SQL.bind_variable( c, 'sq', 0);
  rc := dbms_sql.execute(c);
  DBMS_SQL.variable_value( c, 'sq', sq);
  DBMS_SQL.CLOSE_CURSOR(c);

  return sq;
end;
/
grant execute on SM.GETSDOAREABYTABLE to SM_ALLUSERS;
grant execute on SM.GETSDOAREABYTABLE to SM_ALL_SELECT;


prompt
prompt Creating function GETSDOAREABYTYPESUBTYPE
prompt =========================================
prompt
create or replace function sm.GetSDOAreaByTypeSubtype(TypeID in number,
                                                   SubtypeID in number, 
                                                   SDO_ID in number)
-- Вычисление площади/длины объекта SDO_Geometry из слоя SM.SD_Layers
-- %author XSGROUP - HAWK
-- %created 25.04.05 16:03
-- %param TypeID Тип обработчика/данных SAUMI для слоя с геоданными
-- %param SubtypeID Подтип обработчика/данных SAUMI для слоя с геоданными
-- %param SDO_ID Идентификатор объекта карты для которого необходимо найти площадь/длину
-- %return Площадь/длину объекта карты
return number as
  Owner varchar2(1000);
  TableName varchar2(1000);
  SDOField varchar2(1000);
  KeyField varchar2(1000);
begin
  select Scheme, Table_Name, SDO_Column, Prim_Key
    into Owner, TableName, SDOField, KeyField
    from sm.sd_layers
   where type_id = TypeID
     and subtype_id = SubtypeID;

  return sm.getsdoareabytable(Owner, TableName, SDOField, KeyField, SDO_ID);
end;
/
grant execute on SM.GETSDOAREABYTYPESUBTYPE to SM_ALLUSERS;
grant execute on SM.GETSDOAREABYTYPESUBTYPE to SM_ALL_SELECT;


prompt
prompt Creating function GETSHARESCOUNTHAVING
prompt ======================================
prompt
create or replace function sm.GetSharesCountHaving(ShareID IN NUMBER) return NUMBER is
 x number(27,2);
 iSharedType numeric(27);
begin
 /*Если тип ЦБ доля, то берем не количество а сумму*/
 x:=0;
 --получим тип ЦБ
 select s.sharetype_id
   into iSharedType
   from sm.shares s
  where s.id = ShareID;
 --если доля, то берем не количество а сумму
 if (iSharedType = 61) then
     select inc.cnt - outg.cnt SharesTotal
     into x
     from
      (select nvl(SUM(ShareMove.Sum),0) cnt
       from SM.ShareMove, SM.Shares
       where
        ShareMove.Shares_ID=Shares.ID and
        Shares.ID=ShareID and
        Incoming>0
      ) inc,
      (select nvl(SUM(ShareMove.Sum),0) cnt
       from SM.ShareMove, SM.Shares
       where
        ShareMove.Shares_ID=Shares.ID and
        Shares.ID=ShareID and
        Outgoing>0
      ) outg;
       x := round(x,2);
 end if;
 if (x = 0) then
     select inc.cnt - outg.cnt SharesTotal
    -- decode(nvl(o.authcapital,0),0,'?',
    --  to_char(round(((inc.cnt - outg.cnt)*Shares.Nominal / o.authcapital*100),2)) || '%') SharesPercent
     into x
     from
      (select nvl(SUM(ShareMove.Incoming),0) cnt
       from SM.ShareMove, SM.Shares
       where
        ShareMove.Shares_ID=Shares.ID and
        Shares.ID=ShareID and
        Incoming>0
      ) inc,
      (select nvl(SUM(ShareMove.Outgoing),0) cnt
       from SM.ShareMove, SM.Shares
       where
        ShareMove.Shares_ID=Shares.ID and
        Shares.ID=ShareID and
        Outgoing>0
      ) outg;
 end if;
 return x;
end;
/
grant execute on SM.GETSHARESCOUNTHAVING to SM_ALLUSERS;
grant execute on SM.GETSHARESCOUNTHAVING to SM_ALL_SELECT;


prompt
prompt Creating function GETSQUAREOFCHILDS
prompt ===================================
prompt
create or replace function sm.getsquareofchilds(build_id in number, cdate in date) return number is
 s number;
begin
 -- функция возвращает суммарную площадь помещений ближайшего низлежащего уровня в здании
 -- у которых у которых basebuilding=build_id на дату cdate
  select sum(square) into s from sm.buildings b, sm.objects o
  where
      o.id=b.objects_id and
      basebuilding=build_id and
      nvl(o.exists_since,cdate) <= cdate and
      nvl(o.exists_end,cdate) >= cdate;

 return s;
end;
/
grant execute on SM.GETSQUAREOFCHILDS to SM_ALLUSERS;
grant execute on SM.GETSQUAREOFCHILDS to SM_ALL_SELECT;


prompt
prompt Creating function GETSTATEINFO
prompt ==============================
prompt
create or replace function sm.GetStateInfo(STID in Number) return varchar2 is
  Result  varchar2(4000);
  
  -- Author  : XSGROUP
  -- Created : 21.01.2006  
  -- Purpose : формирует строку описания состояния с ID=STID
  -- Modified : XSGROUP ver. 07.06.2012
     
  CalcDate     Date;
  StartPay     sm.states.startpay%type;
  Pay          sm.states.pay%type;
  Status       sm.statetypes.name%type;
  isUsed       varchar2(10);
  StartPayName sm.sm_settings.value%type;
  PayName      sm.sm_settings.value%type;
  RatableName  sm.sm_settings.value%type;
  Ratable      sm.states.ratable%type;
  UPKSZ        sm.states.kadastr_cost%type;
  ObjTypeID    sm.objects.objtypes_id%type;
  IsGround     boolean;
  speciallyvalued sm.states.speciallyvalued%type; --ver. 07.06.2012
begin

  StartPayName:=GetParameter('OBJSTATE_STARTPAY_NAME');
  PayName:=GetParameter('OBJSTATE_PAY_NAME');
  RatableName:=GetParameter('OBJSTATE_RATABLE_NAME');
  
  select
    st.calcdate,  
    st.startpay, 
    st.pay,      
    stt.name,    
    st.is_using,
    o.objtypes_id,
    st.Ratable,
    st.kadastr_cost,
    st.speciallyvalued 
  into
    CalcDate,
    StartPay,
    Pay,
    Status,
    IsUsed,
    ObjTypeID,
    Ratable,
    UPKSZ,
    speciallyvalued 
  from
    sm.States st,
    sm.Statetypes stt,
    sm.objects o
  where
    st.id=STID and
    st.objects_id=o.id and
    st.statetypes_id=stt.id;
  
  IsGround:=(ObjTypeID=7);
  
  Result:='';
  
   
  if IsGround then
    Result:=to_char(CalcDate,'DD.MM.YYYY')||': УПКСЗ:';
    
    if UPKSZ is null then
      Result:=Result||'--';
    else
      Result:=Result||UPKSZ||'р./кв.м.';   
    end if;
    
    result:=Result||', '||RatableName||':';
    
    if Ratable is null then
      Result:=Result||'--';
    else
      Result:=Result||Ratable||'р.';
    end if;
    
  else
    begin
      if Rtrim(IsUsed)='Y' then
        IsUsed:='в экспл.';
      end if;
    
      Result:=to_char(CalcDate,'DD.MM.YYYY')||': '||StartPayName||':'||StartPay||'р., '||PayName||':'||Pay||'р., '||Status;
      if IsUsed='в экспл.' then
        Result:=Result||', '||IsUsed;
      end if;
    end;
  end if;  
  
  --ver. 07.06.2012
  if Rtrim(speciallyvalued)='Y' then        
        if (length(trim(Result)) > 0) then
           Result:=Result||', '||'особо ценное имущество';
        else
            Result:='особо ценное';
        end if;
  end if;
   
  return(Result);
  
  exception
    when OTHERS then
      Result:='';
      return (Result);
       
end GetStateInfo;
/
grant execute on SM.GETSTATEINFO to SM_ALLUSERS;
grant execute on SM.GETSTATEINFO to SM_ALL_SELECT;


prompt
prompt Creating function GETTOWNAREA
prompt =============================
prompt
create or replace function sm.GetTownArea(ObjectsID in number) return varchar2 is
Result varchar2(500);
begin
/* 12/12/2022 Чувыкин В.Э. функция возвращает внутригородской округ из адреса объекта */

begin
select
ta.name
into
result
from
sm.objects o
left join address a on o.address_id = a.id
left join townarea ta on ta.id = a.townarea_id
where
o.id=ObjectsID;
exception
when NO_DATA_FOUND then
null;
end;



return(Result);
end GetTownArea;
/
grant execute on SM.GETTOWNAREA to SM_ALLUSERS;


prompt
prompt Creating function GETUINGMP
prompt ===========================
prompt
create or replace function sm.GetUINGMP(n_movesetID number, n_obligationTypeID number, v_ChargeType varchar2, is_separate char default 'N') return varchar2
is
vUIN sm.gmp_bill.supplierbillid%type;
retval varchar2(50);
A_ParamSetTab varchar2(50);
begin
  if n_movesetID is null or
    n_obligationTypeID is null then 
  return('');
  end if;
  
---Если параметр v_ChargeType null выводи УИН для сальдо одной строкой 
 A_ParamSetTab:=sm.Getparameter('GMP_CHARGE_SALDO');
 if A_ParamSetTab is null then return(''); end if;
 
 if A_ParamSetTab='SUM' then 
    begin
           select o.obligation_uin
           into vUIN
           from sm.obligations o
           where o.moveset_id=n_movesetID and
           o.obligationtype_id=n_obligationTypeID; 
    exception
         when others then return('');
    end;
 end if;
 
 --FINEAPART - пеня отдельной строкой, а основной долг и проценты вместе;
if (A_ParamSetTab='FINEAPART') then 
     if (v_ChargeType='FINE') then
        begin
             select obl.fine_uin
             into vUIN
             from sm.obligations obl
             where obl.moveset_id=n_movesetID and
             obl.obligationtype_id=n_obligationTypeID;
        exception                
          when others then  return('');
        end;              
     end if;
     if ((v_ChargeType='OBLIGATION') or ((v_ChargeType='PERCENT'))) then
        begin
             select obl.obligation_uin
             into vUIN
             from sm.obligations obl
             where obl.moveset_id=n_movesetID and
             obl.obligationtype_id=n_obligationTypeID;
        exception                    
          when others then return('');
        end;              
     end if;
end if; --end FINEAPART  
  
  --APART - все виды начислений отдельными строками.
if (A_ParamSetTab='APART') then 
    if (v_ChargeType='FINE') then
        begin
             select obl.fine_uin
             into vUIN
             from sm.obligations obl
             where obl.moveset_id=n_movesetID and
             obl.obligationtype_id=n_obligationTypeID;
        exception                   
          when others then return('');
        end;              
     end if;
      if (v_ChargeType='OBLIGATION')  then
        begin
             select obl.obligation_uin
             into vUIN
             from sm.obligations obl
             where obl.moveset_id=n_movesetID and
             obl.obligationtype_id=n_obligationTypeID;
        exception                  
          when others then  return('');
        end;              
     end if;
     if (v_ChargeType='PERCENT') then
        begin
             select obl.percent_uin
             into vUIN
             from sm.obligations obl
             where obl.moveset_id=n_movesetID and
             obl.obligationtype_id=n_obligationTypeID;
        exception         
          when others then return('');
        end;              
     end if;
end if; --end APART
 
if (is_separate='Y' and length(vUIN)=20) then
 retval:=substr(vUIN,1,7)||' '||substr(vUIN,8,1)||' '||substr(vUIN,9,3)||' '||substr(vUIN,12,3)||' '||substr(vUIN,15,3)||' '||substr(vUIN,18,3);
else
 retval:=vUIN;
end if;

return(retval); 
exception
  when others then 
  return('');
end;
/
grant execute on SM.GETUINGMP to SM_ALLUSERS;
grant execute on SM.GETUINGMP to SM_ALL_SELECT;


prompt
prompt Creating function GETUINGMPBYCHARGEID
prompt =====================================
prompt
create or replace function sm.GetUINGMPbyChargeID(n_chargeID number,  v_ChargeType varchar2) return varchar2
is
vUIN sm.gmp_bill.supplierbillid%type;
A_MovesetID number(27);
A_ObligTypeID number(27);
begin
   if n_chargeID is null then return(''); end if;
   
   select c.movesets_id,c.obligationtype_id
   into   A_MovesetID, A_ObligTypeID
   from sm.charges c
   where c.id=n_chargeID;
   vUIN:=sm.Getuingmp(A_MovesetID,A_ObligTypeID,v_ChargeType);
      
 return(vUIN);
exception
  when others then return('');
end;
/
grant execute on SM.GETUINGMPBYCHARGEID to SM_ALLUSERS;
grant execute on SM.GETUINGMPBYCHARGEID to SM_ALL_SELECT;


