prompt Creating function GETUSERNAME
prompt =============================
prompt
CREATE OR REPLACE Function SM.GetUserName RETURN varchar2 IS
 FULLNAME registeredusers.fullname%type;
Begin
 Select RegisteredUsers.FullName INTO FULLNAME FROM RegisteredUsers Where USERNAME=USER;
 RETURN FULLNAME;
EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN 'Пользователь не зарегистрирован';
End;
/
grant execute on SM.GETUSERNAME to SM_ALLUSERS;
grant execute on SM.GETUSERNAME to SM_ALL_SELECT;


