prompt Creating function GETVALIDATESTORED
prompt ===================================
prompt
create or replace function sm.GetValidateStored(Amove_id in number) return varchar2 is
  Result  varchar2(4000):=null;
  S varchar2(4000);
  Descr  varchar2(4000);
begin
  Descr:=null;
  
  S:=sm.M.m_validate_stored(Amove_id,Descr);
  if S='Y' then
    Return(null);
  end if; 
   
  Result:=Descr;
  return(Result);
  
end GetValidateStored;
/
grant execute on SM.GETVALIDATESTORED to SM_ALLUSERS;
grant execute on SM.GETVALIDATESTORED to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_ACTUALPAY
prompt ==========================================
prompt
create or replace function sm.Get_ais_object_actualpay(Flag varchar2, AObject_id number, Adate date)
return TYPE_AIS_OBJECT_STATES_LIST pipelined as
 Id number(27); -- уникальный генерируемый идентификатор
 CALCDATE DATE;-- дата расчета
 STARTPAY number(27,2);-- первоначальная стоимость
 PAY NUMBER(27,2); -- остаточная стоимость
 CADASTRALVALUE number(27,2); -- кадастровая стоимость
 RATABLE number(27,2); -- оценочная стоимость
 ----CADASTRALVALUE number(27,2); -- кадастровая стоимость
 NOMINALCOST number(27,2); -- Номинальная стоимость пакета акций(доли), руб.; Размер уставного(складочного) капитала (уставного фонда) ЮЛ, руб.
 WORKERSNUMBER integer;--NUMBER(27,2); -- Среднесписочная численность работников
 ----PAY NUMBER(27,2); -- остаточная стоимость
 ADateReq date;
 
begin
  /* 26/01/2015 Твердохлеб: Формирует данные для АИС: состояние объектов*/

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  -- состояние объекта
  Id := 1;
  for
     xxx in (
             /*select s.id, cast(s.calcdate as date) calcdate, s.startpay, s.pay, s.cadastralvalue, s.ratable,
                    s.nominalcost, s.workersnumber
               from sm.states s
              where s.objects_id = AObject_id
                and s.calcdate <= ADateReq
              order by 2*/

              select s.id, cast(s.calcdate as date) calcdate, s.startpay, s.pay, s.cadastralvalue, s.ratable,
                    s.nominalcost, s.workersnumber
               from sm.states s
              where s.objects_id = AObject_id
                and s.calcdate = (select max(s.calcdate)
                                         from states s
                                         where s.objects_id = AObject_id
                                         and s.calcdate <= ADateReq)


            )
  loop
    calcdate := xxx.calcdate;
    startpay := xxx.startpay;
    pay := xxx.pay;
    --cadastralvalue := xxx.cadastralvalue;
    --ratable := xxx.ratable;
    ----cadastralvalue := xxx.cadastralvalue;
    --nominalcost := xxx.nominalcost;
    --workersnumber := xxx.workersnumber;
    ----pay := xxx.pay;

    if (startpay is null) then
      startpay := 0;
    end if;
    if (pay is null) then
      pay := 0;
    end if;
    /*if (cadastralvalue is null) then
      cadastralvalue := 0;
    end if;
    if (ratable is null) then
      ratable := 0;
    end if;
    if (nominalcost is null) then
      nominalcost := 0;
    end if;
    if (workersnumber is null) then
      workersnumber := 0;
    end if;*/

    pipe row (TYPE_AIS_OBJECT_STATES(Id, calcdate, startpay, pay, cadastralvalue, ratable, nominalcost, workersnumber));
    Id := Id + 1;
  end loop;
   return;
end Get_ais_object_actualpay;
/

prompt
prompt Creating function REP_OBJECT_DESCRIPTION
prompt ========================================
prompt
create or replace function sm.REP_OBJECT_DESCRIPTION(Flag varchar2, ObjID number) return varchar2 is
  Result varchar2(8000);
  /* 15/06/2014 Твердохлеб: Функция возврата описания объекта в зависимости 
                от типа одной строкой*/
  /* 26/01/2015 Твердохлеб: При флаге = 1, условие в зданиях, только родители, игнорируется*/
                
descr varchar(8000);
obj_t number;
begin

 SELECT o.description, o.objtypes_id 
   INTO descr, obj_t
   FROM Objects o
  WHERE ID = ObjID;

-- Имущество
 if obj_t = 1 then
   select  pn.name || ' ' || p.model into Descr
     from sm.property p, sm.propnames pn
     where p.propnames_id = pn.id 
       and p.objects_id = ObjID;
   Result := descr;
 end if;

-- Транспорт
 if obj_t = 2 then
   select tt.name || ' Модель ' || tr.model || ' / Год выпуска ' || tr.relyear || ' / Фед.номер ' || tr.fedno || ' / Номер двигателя ' || tr.motorno || ' / Шасси ' || tr.chassisno  into Descr
     from transport tr, transptype tt
     where tr.objects_id = ObjID 
       and tr.transptype_id = tt.id;
   Result := descr;
 end if;

-- Здания и помещения
 if obj_t = 3 then
   select bt.name || ' площадью ' || b.square || ' кв.м. ' || ' / Кол-во этажей ' || b.floorcount || ' / По адресу ' || sm.expandaddr(b.address_id) into Descr
     from sm.buildings b, sm.buildtypes bt
    where (b.basebuilding is null and Flag is null or Flag = '1') 
      and b.buildtypes_id(+) = bt.id 
      and b.objects_id = ObjID;
   Result := descr;
 end if;

-- Незаверш. строит.
 if obj_t = 4 then
   select 'Объект незавершенного строительства ' || ut.name || ' / Строительный номер ' || ut.buildno || ' / Начало строителства ' || ut.startyear || ' / По адресу ' || sm.expandaddr(ut.address_id) into Descr
     from sm.unconstr ut
    where ut.objects_id = ObjID;
   Result := descr;
 end if;

-- Инженерн. инфрастр.
 if obj_t = 5 then
   select en.name || ' / Тип ' || et.name || ' / Группа ' || ig.name || ' / Длина ' || en.length || ' / Ширина ' || en.width || ' / Площадью ' || en.square || ' / Год ввода ' || en.enteryear || ' / По адресу ' || sm.expandaddr(en.address_id) into Descr
     from sm.enginf en, sm.enginftypes et, sm.infgroups ig
     where en.enginftypes_id = et.id(+) 
       and en.infgroups_id = ig.id(+) 
       and en.objects_id = ObjID;
   Result := descr;
 end if;

-- Организации
 if obj_t = 6 then
   select og.name || f.name || ' / ИНН ' || Cl.inn || ' / Руководитель ' || og.director || ' / По адресу ' || sm.expandaddr(Cl.address_id) into Descr
   from sm.organisations og, sm.orgforms f, sm.Clients cl
   where og.orgform = f.id 
     and og.objects_id = ObjID
     and Cl.Id = og.Clients_Id;
   Result := descr;
 end if;

-- Земельные участки
 if obj_t=7 then
   select gt.name || ' (' || sm.expandaddr_as(g.address_id,0) || ' - ' || g.square || ' кв.м.)' into Descr
     from sm.grounds g, sm.groundtypes gt
    where g.groundtypes_id = gt.id(+) 
      and g.objects_id = ObjID;
   Result := descr;
 end if;

  return(RTRIM(Result));
end REP_OBJECT_DESCRIPTION;
/
grant execute on SM.REP_OBJECT_DESCRIPTION to SM_ALLUSERS;
grant execute on SM.REP_OBJECT_DESCRIPTION to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_DATA
prompt =====================================
prompt
create or replace function sm.Get_ais_object_data(Flag varchar2,
                                               AClient_id number, 
                                               AObjectType_id number, 
                                               AMoveType_id number, 
                                               AObject_id number, 
                                               Adate date,
                                               filtersearch_json varchar2 default null)
return TYPE_AIS_OBJECT_DATA_LIST pipelined as
 AReestr number(27);-- реестровый номер
 AKadNo varchar2(50); -- кадастровый номер
 ADescriptions  varchar2(4000); -- описание объекта
 AName varchar2(4000); -- наименование
 ASquare number(10,2); -- площадь
 AEnterYear integer; -- год ввода
 ALength number(10,2); -- длина для инженерки
 AAddress varchar2(4000); -- адрес
 ABasDocProp varchar2(4000); -- основной документ собственности
 ARegDocProp varchar2(4000); -- основной документ регистрации права (собственность)
 ABasDocBal varchar2(4000);  -- основной документ балансодержания
 ARegDocBal varchar2(4000);  -- основной документ регистрации права (балансодержание)
 ABasDocRich varchar2(4000); -- основной документ особо ценного имущества
 ABCost number(27,6); -- балансовая стоимость
 ARCost number(27,6); -- остаточная стоимость
 AIsRealeState varchar2(10); -- является недвижимостью
 AIsKRD varchar2(1); -- принадлежит Краснодару
 ADateReq date;
 AAddress_id number(27);
 AAddress_building_id number(27);
 Id number(27);
 Owner_id number(27);
 Akadastr_no varchar2(100);
 Adescription varchar2(100);
 AaddressF varchar2(100);
 Aprovincearea varchar2(100);
 Atownnames varchar2(100);
 Astreet varchar2(100);
 Ahouse varchar2(100);
 Aappartment varchar2(100);
 err_code varchar2(100);
 err_msg varchar2(200);
 filtersearch_json2 varchar2(8000);
 obj json;
 tempdata json_value;
 
 Aokof varchar2(100);
 Amodel varchar2(100);
 Adateissue varchar2(100);
 Ainvno varchar2(100);
 Aserialnum varchar2(100);
 Ainfo varchar2(100);
 
 Arelyear varchar2(100);
 Afedno varchar2(100);
 Amotorno varchar2(100);
 Achassisno varchar2(100);
 Abodyno varchar2(100);
 Avin varchar2(100);
begin
  /* 26/01/2015 Твердохлеб: Формирует данные для АИС*/
  /* 22/01/2019 Твердохлеб: Добавил входной параметр фильтрация по критериям*/
  
  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;
  
  if (AClient_id = 5100 and filtersearch_json is null) then
     return;
  end if;
  
  -- все параметры в формате json
  -- 
  -- обрабатываем следующие критерии поиска
  -- кадастровый номер kadastr_no
  -- описание description
  -- адрес address
  -- район области provincearea
  -- населенный пункт townnames
  -- улица street
  -- дом house
  -- квартира appartment
  
  -- Reestr реестровый номер
  -- okof окоф
  -- name наименование объекта
  -- model модель
  -- dateissue год
  -- invno инвентарный номер
  -- serialnum заводской номер
  -- info доп. инфо
  
  -- пример
  --{
  -- "kadastr_no":"23:4300",
  -- "description":"",
  -- "address":"",
  -- "provincearea":"",
  -- "townnames":"",
  -- "street":"",
  -- "house":"",
  -- "appartment":""
  -- }
  
  filtersearch_json2 := trim(filtersearch_json);  
  if (filtersearch_json2 is not null) then
    begin
         obj := json(filtersearch_json2);
         if (obj is not null) then
           if(obj.exist('kadastr_no')) then
             tempdata := obj.get('kadastr_no');
             Akadastr_no := tempdata.get_string;
           end if;
           if (obj.exist('description')) then
             tempdata := obj.get('description');
             Adescription := tempdata.get_string;
           end if;
           if (obj.exist('address')) then
             tempdata := obj.get('address');
             AaddressF := tempdata.get_string;
           end if;
           if (obj.exist('provincearea')) then
             tempdata := obj.get('provincearea');
             Aprovincearea := tempdata.get_string;
           end if;
           if (obj.exist('townnames')) then
             tempdata := obj.get('townnames');
             Atownnames := tempdata.get_string;
           end if;
           if (obj.exist('appartment')) then
             tempdata := obj.get('appartment');
             Aappartment := tempdata.get_string;
           end if;  
           if (obj.exist('street')) then
             tempdata := obj.get('street');
             Astreet := tempdata.get_string;
           end if; 
           if (obj.exist('house')) then
             tempdata := obj.get('house');
             Ahouse := tempdata.get_string;
           end if;   
           
           if (obj.exist('reestr')) then
             tempdata := obj.get('reestr');
             Areestr := tempdata.get_string;
           end if;   
           if (obj.exist('okof')) then
             tempdata := obj.get('okof');
             Aokof := tempdata.get_string;
           end if;     
           if (obj.exist('name')) then
             tempdata := obj.get('name');
             Aname := tempdata.get_string;
           end if;   
           if (obj.exist('model')) then
             tempdata := obj.get('model');
             Amodel := tempdata.get_string;
           end if;   
           if (obj.exist('dateissue')) then
             tempdata := obj.get('dateissue');
             Adateissue := tempdata.get_string;
           end if;   
           if (obj.exist('invno')) then
             tempdata := obj.get('invno');
             Ainvno := tempdata.get_string;
           end if;   
           if (obj.exist('serialnum')) then
             tempdata := obj.get('serialnum');
             Aserialnum := tempdata.get_string;
           end if;   
           if (obj.exist('info')) then
             tempdata := obj.get('info');
             Ainfo := tempdata.get_string;
           end if; 
           
           if (obj.exist('relyear')) then
             tempdata := obj.get('relyear');
             Arelyear := tempdata.get_string;
           end if;           
           if (obj.exist('fedno')) then
             tempdata := obj.get('fedno');
             Afedno := tempdata.get_string;
           end if;           
           if (obj.exist('motorno')) then
             tempdata := obj.get('motorno');
             Amotorno := tempdata.get_string;
           end if; 
           if (obj.exist('chassisno')) then
             tempdata := obj.get('chassisno');
             Achassisno := tempdata.get_string;
           end if;
           if (obj.exist('bodyno')) then
             tempdata := obj.get('bodyno');
             Abodyno := tempdata.get_string;
           end if;
           if (obj.exist('vin')) then
             tempdata := obj.get('vin');
             Avin := tempdata.get_string;
           end if;   
         end if;                 
      end;
  end if;  

  -- объект должен иметь определенную ОД (по умолчанию быть на балансе)
  for
     xxx in (
             
             select o.id,
                    o.address_id,
                    o.description,
                    o.invno,
                    o.okof
               from 
                    (
                        select distinct o.id,
                                        o.address_id,
                                        o.description,
                                        o.invno,
                                        o.okof_new as okof
                                   from sm.objects o
                                  where AClient_id = 5100 -- если пользователь ДМС
                                    and o.objtypes_id = AObjectType_id
                                    and (o.id = AObject_id or AObject_id is null)
                                    and not exists(
                                                    select o2.id
                                                     from sm.movesets ms2
                                                     join sm.moveperiods mp2 on mp2.moveset_id = ms2.id
                                                     join sm.moveitems mi2 on mi2.moveperiod_id = mp2.id
                                                     join sm.objects o2 on o2.id = mi2.object_id
                                                    where ms2.movetype_id = 1
                                                      and (ms2.client_id = 5100)
                                                      and mp2.sincedate <= ADateReq
                                                      and (mp2.enddate >= ADateReq or mp2.enddate is null)
                                                      and (o2.id = o.id)
                                                  )              
                                 union   
                                 select distinct o.id,
                                        o.address_id,
                                        o.description,
                                        o.invno,
                                        o.okof
                                   from sm.movesets ms
                                   join sm.moveperiods mp on mp.moveset_id = ms.id
                                   join sm.moveitems mi on mi.moveperiod_id = mp.id
                                   join sm.objects o on o.id = mi.object_id
                                  where ms.movetype_id = AMoveType_id
                                    and (ms.client_id = AClient_id)
                                    and mp.sincedate <= ADateReq
                                    and (mp.enddate >= ADateReq or mp.enddate is null)
                                    and o.objtypes_id = AObjectType_id
                                    and (o.id = AObject_id or AObject_id is null)                                    
                    )o 
              where (AClient_id = 5100 and filtersearch_json2 is null and rownum <= 0 
                     or
                     AClient_id = 5100 and filtersearch_json2 is not null and rownum <= 100
                     or 
                     AClient_id <> 5100)
                and (
                     filtersearch_json2 is null 
                     or
                     filtersearch_json2 is not null
                     and ( 
                           (Adescription is null or lower(o.description) like '%' || lower(Adescription) || '%')
                           and  
                           (Akadastr_no is null or (
                                                       exists(select b.id from sm.buildings b where b.objects_id = o.id and lower(b.kadastrno) like '%' || lower(Akadastr_no) || '%')
                                                       or 
                                                       exists(select b.id from sm.unconstr b where b.objects_id = o.id and lower(b.kadastrno) like '%' || lower(Akadastr_no) || '%')
                                                       or 
                                                       exists(select b.id from sm.enginf b where b.objects_id = o.id and lower(b.kadastrno) like '%' || lower(Akadastr_no) || '%')
                                                     )
                           )
                           and 
                           (AaddressF is null or (
                                                     exists(select b.id 
                                                              from sm.buildings b 
                                                             where b.objects_id = o.id 
                                                               and lower(sm.expandaddr(b.address_id)) like '%' || lower(AaddressF) || '%')
                                                     or 
                                                     exists(select b.id 
                                                              from sm.unconstr b 
                                                             where b.objects_id = o.id 
                                                               and lower(sm.expandaddr(b.address_id)) like '%' || lower(AaddressF) || '%')
                                                     or 
                                                     exists(select b.id 
                                                              from sm.enginf b 
                                                             where b.objects_id = o.id 
                                                               and lower(sm.expandaddr(b.address_id)) like '%' || lower(AaddressF) || '%')
                                                    )
                          )
                          and 
                          (Aprovincearea is null or (
                                                       exists(select b.id 
                                                                from sm.buildings b 
                                                                join sm.address a on a.id = b.address_id
                                                                join sm.provincearea r on r.id = a.provincearea_id
                                                               where b.objects_id = o.id 
                                                                 and lower(r.name) like '%' || lower(Aprovincearea) || '%')
                                                       or 
                                                       exists(select b.id 
                                                                from sm.unconstr b 
                                                                join sm.address a on a.id = b.address_id
                                                                join sm.provincearea r on r.id = a.provincearea_id
                                                               where b.objects_id = o.id 
                                                                 and lower(r.name) like '%' || lower(Aprovincearea) || '%')
                                                       or 
                                                       exists(select b.id 
                                                                from sm.enginf b 
                                                                join sm.address a on a.id = b.address_id
                                                                join sm.provincearea r on r.id = a.provincearea_id
                                                               where b.objects_id = o.id 
                                                                 and lower(r.name) like '%' || lower(Aprovincearea) || '%')
                                                    )
                           )  
                           and
                           (Atownnames is null or (
                                                     exists(select b.id 
                                                              from sm.buildings b 
                                                              join sm.address a on a.id = b.address_id
                                                              join sm.townnames r on r.id = a.townnames_id
                                                             where b.objects_id = o.id 
                                                               and lower(r.name) like '%' || lower(Atownnames) || '%')
                                                     or 
                                                     exists(select b.id 
                                                              from sm.unconstr b 
                                                              join sm.address a on a.id = b.address_id
                                                              join sm.townnames r on r.id = a.townnames_id
                                                             where b.objects_id = o.id 
                                                               and lower(r.name) like '%' || lower(Atownnames) || '%')
                                                     or 
                                                     exists(select b.id 
                                                              from sm.enginf b 
                                                              join sm.address a on a.id = b.address_id
                                                              join sm.townnames r on r.id = a.townnames_id
                                                             where b.objects_id = o.id 
                                                               and lower(r.name) like '%' || lower(Atownnames) || '%')
                                                    ) 
                           )  
                           and
                           (Astreet is null or (
                                                 exists(select b.id 
                                                          from sm.buildings b 
                                                          join sm.address a on a.id = b.address_id
                                                          join sm.streets r on r.id = a.streets_id
                                                         where b.objects_id = o.id 
                                                           and lower(r.name) like '%' || lower(Astreet) || '%')
                                                 or 
                                                 exists(select b.id 
                                                          from sm.unconstr b 
                                                          join sm.address a on a.id = b.address_id
                                                          join sm.streets r on r.id = a.streets_id
                                                         where b.objects_id = o.id 
                                                           and lower(r.name) like '%' || lower(Astreet) || '%')
                                                 or 
                                                 exists(select b.id 
                                                          from sm.enginf b 
                                                          join sm.address a on a.id = b.address_id
                                                          join sm.streets r on r.id = a.streets_id
                                                         where b.objects_id = o.id 
                                                           and lower(r.name) like '%' || lower(Astreet) || '%')
                                                )
                           )  
                           and
                           (Ahouse is null or (
                                                 exists(select b.id 
                                                          from sm.buildings b 
                                                          join sm.address a on a.id = b.address_id
                                                         where b.objects_id = o.id 
                                                           and lower(a.house) like '%' || lower(Ahouse) || '%')
                                                 or 
                                                 exists(select b.id 
                                                          from sm.unconstr b 
                                                          join sm.address a on a.id = b.address_id
                                                         where b.objects_id = o.id 
                                                           and lower(a.house) like '%' || lower(Ahouse) || '%')
                                                 or 
                                                 exists(select b.id 
                                                          from sm.enginf b 
                                                          join sm.address a on a.id = b.address_id
                                                         where b.objects_id = o.id 
                                                           and lower(a.house) like '%' || lower(Ahouse) || '%')
                                                )
                            )
                            and
                            (Aappartment is null or (
                                                       exists(select b.id 
                                                                from sm.buildings b 
                                                                join sm.address a on a.id = b.address_id
                                                               where b.objects_id = o.id 
                                                                 and lower(a.appartment) like '%' || lower(Aappartment) || '%')
                                                       or 
                                                       exists(select b.id 
                                                                from sm.unconstr b 
                                                                join sm.address a on a.id = b.address_id
                                                               where b.objects_id = o.id 
                                                                 and lower(a.appartment) like '%' || lower(Aappartment) || '%')
                                                       or 
                                                       exists(select b.id 
                                                                from sm.enginf b 
                                                                join sm.address a on a.id = b.address_id
                                                               where b.objects_id = o.id 
                                                                 and lower(a.appartment) like '%' || lower(Aappartment) || '%')
                                                      )  
                            )  
                            and
                            (Areestr is null or (
                                                 lower(TO_CHAR(o.id)) like '%' || lower(Areestr) || '%'
                                                )  
                            )
                            and
                            (Aokof is null or (
                                               lower((o.okof)) like '%' || lower(Aokof) || '%'  
                                             )  
                            ) 
                            and
                            (Aname is null or (
                                               exists(select b.id 
                                                        from sm.property b
                                                        join sm.propnames pn on pn.id = b.propnames_id
                                                       where b.objects_id = o.id 
                                                         and lower(pn.name) like '%' || lower(Aname) || '%') 
                                             )  
                            ) 
                            and
                            (Amodel is null or (
                                               exists(select b.id 
                                                        from sm.property b
                                                       where b.objects_id = o.id 
                                                         and lower(b.model) like '%' || lower(Amodel) || '%')
                                              )  
                            )  
                            and
                            (Adateissue is null or (
                                                   exists(select b.id 
                                                            from sm.property b
                                                           where b.objects_id = o.id 
                                                             and lower(TO_CHAR(b.dateissue)) like '%' || lower(Adateissue) || '%')
                                                  )  
                            )  
                            and
                            (Ainvno is null or (
                                               lower((o.invno)) like '%' || lower(Ainvno) || '%' 
                                              )  
                            ) 
                            and
                            (Aserialnum is null or (
                                                   exists(select b.id 
                                                            from sm.property b
                                                           where b.objects_id = o.id 
                                                             and lower((b.serialnum)) like '%' || lower(Aserialnum) || '%')
                                                  )  
                            ) 
                            and
                            (Ainfo is null or (
                                               exists(select b.id 
                                                        from sm.property b
                                                       where b.objects_id = o.id 
                                                         and lower((b.info)) like '%' || lower(Ainfo) || '%')
                                              )  
                            )
                            and
                            (Arelyear is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower(TO_CHAR(b.relyear)) like '%' || lower(Arelyear) || '%')
                                              )  
                            )
                            and
                            (Afedno is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower((b.fedno)) like '%' || lower(Afedno) || '%')
                                              )  
                            )
                            and
                            (Amotorno is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower((b.motorno)) like '%' || lower(Amotorno) || '%')
                                              )  
                            )
                            and
                            (Achassisno is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower((b.chassisno)) like '%' || lower(Achassisno) || '%')
                                              )  
                            )
                            and
                            (Abodyno is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower((b.bodyno)) like '%' || lower(Abodyno) || '%')
                                              )  
                            )
                            and
                            (Avin is null or (
                                                 exists(select b.id 
                                                          from sm.transport b
                                                         where b.objects_id = o.id 
                                                           and lower((b.ps_vin)) like '%' || lower(Avin) || '%')
                                              )  
                            )                                                                                                                                                                                                                                                                                                                       
                         )
                    )
               order by 1
            )
  loop
    AIsKRD := '0';
    -- реестровый номер
    Aname := null;
    AReestr := xxx.id;
    id := AReestr;
    -- кадастровый номер
    select sm.GetObjectKadastrNo('1',id)
    into AKadNo
    from dual;
    
    -- выставляем флаг, принадлежит ли объект МО г.Краснодар
    select GetPositionClientID(AReestr,1) 
    into Owner_id
    from dual;
    if (Owner_id = 5100) then AIsKRD := '1';
    end if;
    
    -- описание
    select sm.rep_object_description('1', AReestr)
      into ADescriptions
      from dual;
    ADescriptions := xxx.description;

    -- получим адрес объекта
    AAddress_id := xxx.address_id;
    if (AObjectType_id = 3) then
      AAddress_building_id := NULL;
      select b.address_id
        into AAddress_building_id
        from sm.buildings b
       where b.objects_id = AReestr;
       if (AAddress_building_id is not null) then
         AAddress_id := AAddress_building_id;
       end if;
    end if;

    /*select sm.expandaddr_as(AAddress_id)
        into AAddress
        from dual;*/

        select sm.expandaddr(AAddress_id)
        into AAddress
        from dual;

    -- наименование для разных типов объектов
    if (AObjectType_id = 3) then
      select b.levelname
        into AName
        from sm.buildings b
       where b.objects_id = AReestr;
    end if;

    if (AObjectType_id = 5) then
      select e.name
        into AName
        from sm.EngInf e
       where e.objects_id = AReestr;
    end if;

    if (AObjectType_id = 4) then
      select u.name
        into AName
        from sm.Unconstr u
       where u.objects_id = AReestr;
    end if;

    -- "Является недвижимым имуществом" для разных типов объектов
    AIsRealeState:=NULL;

    if (AObjectType_id = 2) then
      select t.isrealestate
        into AIsRealeState
        from sm.transport t
       where t.objects_id = AReestr;
       if AIsRealeState = 'Y' then
         AIsRealeState:='Да';
       end if;
       if AIsRealeState = 'N' then
         AIsRealeState:='Нет';
       end if;
    end if;

    if (AObjectType_id = 3) then
      select b.isrealestate
        into AIsRealeState
        from sm.buildings b
       where b.objects_id = AReestr;
       if AIsRealeState = 'Y' then
         AIsRealeState:='Да';
       end if;
       if AIsRealeState = 'N' then
         AIsRealeState:='Нет';
       end if;
    end if;

    if (AObjectType_id = 5) then
      select e.isrealestate
        into AIsRealeState
        from sm.EngInf e
       where e.objects_id = AReestr;
       if AIsRealeState = 'Y' then
         AIsRealeState:='Да';
       end if;
       if AIsRealeState = 'N' then
         AIsRealeState:='Нет';
       end if;
    end if;

    -- площадь для разных типов объектов
    if (AObjectType_id = 3) then
      select b.square
        into ASquare
        from sm.buildings b
       where b.objects_id = AReestr;
    end if;

    if (AObjectType_id = 5) then
      select e.square
        into ASquare
        from sm.EngInf e
       where e.objects_id = AReestr;
    end if;

    -- год ввода для разных типов объектов
    if (AObjectType_id = 3) then
      select b.enteryear
        into AEnterYear
        from sm.buildings b
       where b.objects_id = AReestr;
    end if;

    if (AObjectType_id = 5) then
      select e.enteryear
        into AEnterYear
        from sm.EngInf e
       where e.objects_id = AReestr;
    end if;

    -- длина для инженерки
    ALength := null;
    if (AObjectType_id = 5) then
      select e.length
        into ALength
        from sm.EngInf e
       where e.objects_id = AReestr;
    end if;

    -- основной документ собственности
    select sm.ExpandDoc(sm.GetDocByMoveID(sm.GetPositionMoveID(ID,1)))
    into ABasDocProp
    from dual;
    -- основной документ регистрации права (собственность)
    select sm.ExpandDoc(sm.GetDocCertificateByMoveID(sm.GetPositionMoveID(ID,1)))
    into ARegDocProp
    from dual;
    -- основной документ балансодержания
    select sm.ExpandDoc(sm.GetDocByMoveID(sm.GetPositionMoveID(ID,2)))
    into ABasDocBal
    from dual;
    -- основной документ регистрации права (балансодержание)
    select sm.ExpandDoc(sm.GetDocCertificateByMoveID(sm.GetPositionMoveID(ID,2)))
    into ARegDocBal
    from dual;
    -- основной документ особо ценного имущества
    select sm.ExpandDoc(sm.GetDocByMoveID(sm.GetPositionMoveID(ID,28)))
    into ABasDocRich
    from dual;

    -- балансовая стоимость
    select sm.GetObjectCost2(id,sysdate,'B')
    into ABCost
    from dual;
    -- остаточная стоимость
    select sm.GetObjectCost2(id,sysdate,'R')
    into ARCost
    from dual;

    pipe row (TYPE_AIS_OBJECT_DATA(Id,
                                   AReestr,
                                   AKadNo,
                                   ADescriptions,
                                   AName,
                                   ASquare,
                                   AEnterYear,
                                   ALength,
                                   AAddress,
                                   xxx.invno,
                                   ABCost,
                                   ARCost,
                                   ABasDocProp,
                                   ARegDocProp,
                                   ABasDocBal,
                                   ARegDocBal,
                                   ABasDocRich,
                                   AIsRealeState,
                                   AIsKRD,
                                   xxx.okof));
  end loop;
   return;
end Get_ais_object_data;
/
grant execute on SM.GET_AIS_OBJECT_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_MOVE_DATA
prompt ==========================================
prompt
create or replace function sm.Get_Ais_Object_Move_Data(Flag varchar2, AObject_id number, AMoveType_id in varchar2)
return TYPE_AIS_OBJECT_MOVEDATA_LIST2 pipelined as
 name_od varchar2(200);
 SubjName varchar2(300); --наименование организации - субъекта ОД
 MainDoc varchar2(4000); --основной документ в пакете ОД (согласно сложившейся практике в Аренде и БП ставят Договор)
begin
  /* 01/02/2019 Чувыкин: Формирует данные для АИС: Наименование субъекта права ОД, основной док пакета ОД - все по конкретному объекту*/
  for
     xxx in (
              select 
                    mt.id,
                    mt.name
               from movetype mt              
              where INSTR(','||AMoveType_id||',',','||to_char(mt.id)||',',1,1) <> 0
            )
  loop
      name_od := xxx.name;
      SubjName := null;
      MainDoc := null;
      
      select GetPosition(AObject_id,xxx.id) 
        into SubjName
        from dual;
      SubjName := trim(SubjName);  
        
      select ExpandDoc(GetDocByMoveID(GetPositionMoveID(AObject_id, xxx.id))) 
        into MainDoc
        from dual; 
      MainDoc := trim(MainDoc); 
      
      if (SubjName is not null or MainDoc is not null) then
        pipe row (TYPE_AIS_OBJECT_MOVEDATA2( 
                                           name_od,
                                           SubjName,
                                           MainDoc
                                           ));
      end if;
  end loop;
  return;
end Get_Ais_Object_Move_Data;
/
grant execute on SM.GET_AIS_OBJECT_MOVE_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_PROPERTY_DATA
prompt ==============================================
prompt
create or replace function sm.Get_ais_object_property_data(Flag varchar2,
                                                        AClient_id number, 
                                                        AObjectType_id number, 
                                                        AMoveType_id number, 
                                                        AObject_id number, 
                                                        Adate date,
                                                        filtersearch_json varchar2 default null)
return TYPE_AIS_OBJECT_PROP_DATA_LIST pipelined as
begin
  /* 04/02/2015 Твердохлеб: Формирует данные для АИС: прочее движимое*/
  /* 22/01/2019 Твердохлеб: Добавил входной параметр фильтрация по критериям*/
  -- объект должен иметь определенную ОД (по умолчанию быть на балансе)
  for
     xxx in (
             select *
               from TABLE (sm.get_ais_object_data(Flag, AClient_id, AObjectType_id, AMoveType_id, AObject_id, Adate, filtersearch_json))
             )
  loop
    for
        yyy in (
                 select p.propnames_id,
                        p.model,
                        p.info,
                        p.dateissue,
                        p.dateinput,
                        p.serialnum,
                        o.okof_new,
                        pn.name,
                        pn.propgroups_id
                   from sm.property p
                   join sm.objects o on o.id = p.objects_id
                   join sm.propnames pn on pn.id = p.propnames_id
                  where p.objects_id = xxx.Id
                )
     loop
        pipe row (TYPE_AIS_OBJECT_PROPERTY_DATA(
                                               xxx.Id, -- уникальный генерируемый идентификатор
                                               xxx.Reestr,-- реестровый номер
                                               xxx.Descriptions,-- описание объекта
                                               xxx.Address, -- адрес
                                               xxx.invno, -- инвентарный номер
                                               yyy.okof_new, -- окоф
                                               yyy.name, -- наименование
                                               yyy.propnames_id, -- наименование
                                               yyy.model, -- модель
                                               yyy.dateissue, -- год
                                               yyy.dateinput, -- дата ввода в эксплуатацию
                                               yyy.serialnum, -- заводской номер
                                               yyy.info, -- доп. инфо
                                               yyy.propgroups_id, -- группа
                                               xxx.BasDocProp, -- основной документ собственности
						                                   xxx.BasDocBal,  -- основной документ балансодержания
						                                   xxx.BasDocRich, -- основной документ особо ценного имущества
                                               xxx.ABCost, -- балансовая стоимость
                                               xxx.ARCost, -- остаточная стоимость
                                               xxx.IsKRD

                                               ));

      end loop;
  end loop;
  return;
end Get_ais_object_property_data;
/
grant execute on SM.GET_AIS_OBJECT_PROPERTY_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_STATES
prompt =======================================
prompt
create or replace function sm.Get_ais_object_states(Flag varchar2, AObject_id number, Adate date)
return TYPE_AIS_OBJECT_STATES_LIST pipelined as
 Id number(27); -- уникальный генерируемый идентификатор
 CALCDATE DATE;-- дата расчета
 STARTPAY number(27,2);-- первоначальная стоимость
 PAY NUMBER(27,2); -- остаточная стоимость
 CADASTRALVALUE number(27,2); -- кадастровая стоимость
 RATABLE number(27,2); -- оценочная стоимость
 --CADASTRALVALUE number(27,2); -- кадастровая стоимость
 NOMINALCOST number(27,2); -- Номинальная стоимость пакета акций(доли), руб.; Размер уставного(складочного) капитала (уставного фонда) ЮЛ, руб.
 WORKERSNUMBER integer;--NUMBER(27,2); -- Среднесписочная численность работников
 --PAY NUMBER(27,2); -- остаточная стоимость
 ADateReq date;
 
begin
  /* 26/01/2015 Твердохлеб: Формирует данные для АИС: состояние объектов*/

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  -- состояние объекта
  Id := 1;
  for
     xxx in (
             select s.id, cast(s.calcdate as date) calcdate, s.startpay, s.pay, s.cadastralvalue, s.ratable,
                    s.nominalcost, s.workersnumber
               from sm.states s
              where s.objects_id = AObject_id
                and s.calcdate <= ADateReq
              order by 2
            )
  loop
    calcdate := xxx.calcdate;
    startpay := xxx.startpay;
    pay := xxx.pay;
    cadastralvalue := xxx.cadastralvalue;
    ratable := xxx.ratable;
    --cadastralvalue := xxx.cadastralvalue;
    nominalcost := xxx.nominalcost;
    workersnumber := xxx.workersnumber;
    --pay := xxx.pay;

    if (startpay is null) then
      startpay := 0;
    end if;
    if (pay is null) then
      pay := 0;
    end if;
    if (cadastralvalue is null) then
      cadastralvalue := 0;
    end if;
    if (ratable is null) then
      ratable := 0;
    end if;
    if (nominalcost is null) then
      nominalcost := 0;
    end if;
    if (workersnumber is null) then
      workersnumber := 0;
    end if;

    pipe row (TYPE_AIS_OBJECT_STATES(Id, calcdate, startpay, pay, cadastralvalue, ratable, nominalcost, workersnumber));
    Id := Id + 1;
  end loop;
   return;
end Get_ais_object_states;
/
grant execute on SM.GET_AIS_OBJECT_STATES to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_OBJECT_TRANSPORT_DATA
prompt ===============================================
prompt
create or replace function sm.Get_ais_object_transport_data(Flag varchar2,
                                                         AClient_id number, 
                                                         AObjectType_id number, 
                                                         AMoveType_id number, 
                                                         AObject_id number, 
                                                         Adate date,
                                                         filtersearch_json varchar2 default null)
return TYPE_AIS_OBJECT_TRAN_DATA_LIST pipelined as
begin
  /* 04/02/2015 Твердохлеб: Формирует данные для АИС: транспорт*/

  -- объект должен иметь определенную ОД (по умолчанию быть на балансе)
  for
     xxx in (
             select *
               from TABLE (sm.get_ais_object_data(Flag, AClient_id, AObjectType_id, AMoveType_id, AObject_id, Adate, filtersearch_json))
             )
  loop
    for
        yyy in (
                 select t.relyear,
                        t.fedno,
                        t.motorno,
                        t.chassisno,
                        t.bodyno,
                        t.ps_vin as vin
                   from sm.transport t
                  where t.objects_id = xxx.Id
                )
     loop
       begin 
       pipe row (TYPE_AIS_OBJECT_TRANSPORT_DATA(
                                               xxx.Id, -- уникальный генерируемый идентификатор
                                               xxx.Reestr,-- реестровый номер
                                               xxx.Descriptions,-- описание объекта
                                               xxx.Address, -- адрес
                                               yyy.relyear, -- год выпуска
                                               xxx.invno, -- инвентарный номер
                                               yyy.fedno, -- гос номер
                                               yyy.motorno, -- номер двигателя
                                               yyy.chassisno, -- номер шасси
                                               yyy.bodyno, -- номер кузова
                                               yyy.vin,
                                               xxx.BasDocProp, -- основной документ собственности
                                               xxx.BasDocBal,  -- основной документ балансодержания
                                               xxx.BasDocRich,  -- основной документ особо ценного имущества
                                               xxx.ABCost, -- балансовая стоимость
                                               xxx.ARCost, -- остаточная стоимость
                                               xxx.IsRealeState, -- является недвижимостью
                                               xxx.IsKRD,
                                               xxx.okof
                                               ));
         exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.Id));
            end;
         end;   
      end loop;
  end loop;

  return;
end Get_ais_object_transport_data;
/
grant execute on SM.GET_AIS_OBJECT_TRANSPORT_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_ORG_DATA
prompt ==================================
prompt
create or replace function sm.Get_ais_org_data(Flag varchar2, AClient_id number)
return TYPE_AIS_ORG_DATA_LIST pipelined as
 
 Id number(27); -- уникальный идентификатор
 Name_ varchar2(150); -- наименование
 
 FullName varchar2(300); --полное наименование
 HeadCo varchar2(150); -- головная организация
 OPF varchar2(50); --ОПФ
 
 Client_id number(27);
 Director varchar2(50); -- руководитель
 Directorpost varchar2(100); -- должность
 Dirphone varchar2(30); -- телефон руководителя
 Accountant varchar2(50); -- бухгалтер
 Accphone varchar2(30); -- телефон бухгалтера
 INN CHAR(20); -- ИНН
 OKONH CHAR(20);-- ОКОНХ
 OKPO CHAR(20); -- ОКПО
 OKOGU NUMBER(15); -- ОКОГУ
 OKATO VARCHAR2(15); -- ОКАТО
 OKVED VARCHAR2(150); -- ОКВЭД
 OGRN VARCHAR2(13); -- ОГРН
 KPP VARCHAR2(9); -- КПП
 BIK VARCHAR2(20); -- БИК
 BANKNAME VARCHAR2(70); --БАНК
 ACCOUNT VARCHAR2(42); -- счет
 CORRACCOUNT VARCHAR2(42); -- кор.счет
 E_MAIL VARCHAR2(60); -- E_MAIL
begin
  /* 02/02/2015 Твердохлеб: Формирует данные для АИС: Субъекты права*/

  -- объект должен иметь определенную ОД (по умолчанию быть на балансе)
  for
     xxx in (
             select o.objects_id as id,
                    o.id as client_id,
                    o.name,
                    
                    o.fullname, --полное наименование
                    oo.name as headco, -- головная организация
                    orf.name as opf, --ОПФ
                    
                    o.Director, -- руководитель
                    o.Directorpost, -- должность
                    o.Dirphone, -- телефон руководителя
                    o.Accountant, -- бухгалтер
                    o.Accphone, -- телефон бухгалтера
                    coalesce(o.INN,c.INN) as INN, -- ИНН
                    coalesce(o.OKONH,c.OKONH)OKONH,-- ОКОНХ
                    coalesce(o.OKPO,c.OKPO)OKPO, -- ОКПО
                    o.OKOGU, -- ОКОГУ
                    o.OKATO, -- ОКАТО
                    c.OKVED_NEW OKVED, -- ОКВЭД
                    o.OGRN, -- ОГРН
                    c.KPP, -- КПП
                    coalesce(o.BIK,c.BIK)BIK, -- БИК
                    coalesce(o.BANKNAME,c.BANKNAME)BANKNAME, --БАНК
                    coalesce(o.ACCOUNT,c.ACCOUNT)ACCOUNT, -- счет
                    coalesce(o.CORRACCOUNT,c.CORRACCOUNT)CORRACCOUNT, -- кор.счет
                    c.E_MAIL -- E_MAIL
               from sm.clients c
               join sm.organisations o on o.clients_id = c.id
               join sm.orgforms orf on o.orgform = orf.id
               join sm.organisations oo on o.headcompany = oo.id

              where c.id = AClient_id

            )
  loop
    Id := xxx.Id; -- уникальный идентификатор
    Client_id := xxx.Client_id;
    Name_ := xxx.name;
    
    FullName := xxx.fullname; --полное наименование
    Headco := xxx.headco; -- головная организация
    OPF := xxx.opf; --ОПФ

    Director := xxx.Director; -- руководитель
    Directorpost := xxx.Directorpost; -- должность
    Dirphone := xxx.Dirphone; -- телефон руководителя
    Accountant := xxx.Accountant; -- бухгалтер
    Accphone := xxx.Accphone; -- телефон бухгалтера
    INN := xxx.INN; -- ИНН
    OKONH := xxx.OKONH;-- ОКОНХ
    OKPO := xxx.OKPO; -- ОКПО
    OKOGU := xxx.OKOGU; -- ОКОГУ
    OKATO := xxx.OKATO; -- ОКАТО
    OKVED := xxx.OKVED; -- ОКВЭД
    OGRN := xxx.OGRN; -- ОГРН
    KPP := xxx.KPP; -- КПП
    BIK := xxx.BIK; -- БИК
    BANKNAME := xxx.BANKNAME; --БАНК
    ACCOUNT :=  xxx.ACCOUNT; -- счет
    CORRACCOUNT := xxx.CORRACCOUNT; -- кор.счет
    E_MAIL := xxx.E_MAIL; -- E_MAIL

    pipe row (TYPE_AIS_ORG_DATA( Id, -- уникальный идентификатор
                                 Client_id,
                                 Name_,
                                 
                                 FullName, --полное наименование
                                 HeadCo,  -- головная организация
                                 OPF,  --ОПФ
                                 
                                 Director, -- руководитель
                                 Directorpost, -- должность
                                 Dirphone, -- телефон руководителя
                                 Accountant, -- бухгалтер
                                 Accphone, -- телефон бухгалтера
                                 INN, -- ИНН
                                 OKONH,-- ОКОНХ
                                 OKPO, -- ОКПО
                                 OKOGU, -- ОКОГУ
                                 OKATO, -- ОКАТО
                                 OKVED, -- ОКВЭД
                                 OGRN, -- ОГРН
                                 KPP, -- КПП
                                 BIK, -- БИК
                                 BANKNAME, --БАНК
                                 ACCOUNT, -- счет
                                 CORRACCOUNT, -- кор.счет
                                 E_MAIL -- E_MAIL
                                 ));
  end loop;

   return;
end Get_ais_org_data;
/
grant execute on SM.GET_AIS_ORG_DATA to SM_ALL_SELECT;


prompt
prompt Creating function GET_AIS_REP_BUILDINGS
prompt =======================================
prompt
create or replace function sm.Get_ais_rep_buildings(Flag varchar2, AClient_id number, AObjectType_id number, AMoveType_id number, AObject_id number, Adate date)
return TYPE_AIS_REP_BUILDINGSLIST pipelined as
 Reestr number(27); -- реестровый номер
 Descriptions  varchar2(8000); -- описание объекта
 Address varchar2(2000); -- адрес
 DateReq date;
 Address_id number(27);
 Address_building_id number(27);
 Invno varchar2(50);
 Id number(27);
 CALCDATE DATE;-- дата расчета
 STARTPAY number(27,2);-- первоначальная стоимость
 RATABLE number(27,2); -- оценочная стоимость
 CADASTRALVALUE number(27,2); -- кадастровая стоимость
 NOMINALCOST number(27,2); -- Номинальная стоимость пакета акций(доли), руб.; Размер уставного(складочного) капитала (уставного фонда) ЮЛ, руб.
 WORKERSNUMBER NUMBER(27,2); -- Среднесписочная численность работников
 PAY NUMBER(27,2); -- остаточная стоимость
 ADateReq date;
begin
  /* 09/02/2017 Твердохлеб: Формирует данные для АИС для выписки*/

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  -- объект должен иметь определенную ОД (по умолчанию быть на балансе)
  for
     xxx in (
             select distinct o.id,
                    o.address_id,
                    o.description,
                    o.invno
               from sm.movesets ms
               join sm.moveperiods mp on mp.moveset_id = ms.id
               join sm.moveitems mi on mi.moveperiod_id = mp.id
               join sm.objects o on o.id = mi.object_id
              where ms.movetype_id = AMoveType_id
                and ms.client_id = AClient_id
                and mp.sincedate <= ADateReq
                and (mp.enddate >= ADateReq or mp.enddate is null)
                and o.objtypes_id = AObjectType_id
                and (o.id = AObject_id or AObject_id is null)
               order by 1
            )
  loop
    -- реестровый номер
    Reestr := xxx.id;
    Invno := xxx.invno;
    id := Reestr;
    -- описание
    select sm.rep_object_description('1', Reestr)
      into Descriptions
      from dual;
    Descriptions := xxx.description;

    -- получим адрес объекта
    Address_id := xxx.address_id;
    if (AObjectType_id = 3) then
      Address_building_id := NULL;
      select b.address_id
        into Address_building_id
        from sm.buildings b
       where b.objects_id = Reestr;
       if (Address_building_id is not null) then
         Address_id := Address_building_id;
       end if;
    end if;

    select sm.expandaddr_as(Address_id)
        into Address
        from dual;

    for
     xxx in (
             select s.id, cast(s.calcdate as date) calcdate, s.startpay, s.ratable,
                    s.cadastralvalue, s.nominalcost, s.workersnumber, s.pay
               from sm.states s
              where s.objects_id = AObject_id
                and s.calcdate <= ADateReq
              order by 2
            )
    loop
      calcdate := xxx.calcdate;
      startpay := xxx.startpay;
      ratable := xxx.ratable;
      cadastralvalue := xxx.cadastralvalue;
      nominalcost := xxx.nominalcost;
      workersnumber := xxx.workersnumber;
      pay := xxx.pay;

      if (startpay is null) then
        startpay := 0;
      end if;
      if (ratable is null) then
        ratable := 0;
      end if;
      if (cadastralvalue is null) then
        cadastralvalue := 0;
      end if;
      if (nominalcost is null) then
        nominalcost := 0;
      end if;
      if (workersnumber is null) then
        workersnumber := 0;
      end if;
      if (pay is null) then
        pay := 0;
      end if;
      pipe row (TYPE_AIS_REP_BUILDINGS(Id, Reestr, Descriptions, Address, Invno, calcdate, startpay, ratable, cadastralvalue, nominalcost, workersnumber, pay));
      Id := Id + 1;
    end loop;
  end loop;
   return;
end Get_ais_rep_buildings;
/
grant execute on SM.GET_AIS_REP_BUILDINGS to SM_ALLUSERS;


