prompt
create or replace function sm.Get_authorized_capital(Flag in varchar2, AClient_id in number, Adate in date)
return varchar2 is
  Result varchar2(50);
  ADateReq date;
  Aorganisations_id number(27);
begin
  /* 26/03/2014 Твердохлеб: Функция возвращает уставной капитал/фонд для организации*/

  Result := 0;

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;
  
  select o.id
    into Aorganisations_id
    from sm.organisations o
