prompt
prompt Creating function GET_DESCRIPT_SHARE_OBJ
prompt ========================================
prompt
create or replace function sm.Get_Descript_Share_Obj (Flag in varchar2, Aobject in number) return varchar2  is
  Result varchar2(1000);
  Name_sharecategory varchar2(80);
  Name_sharetypes varchar2(80);
  Name_organisations varchar2(500);
  Asharetypes_id number(27);
begin
  /* 01/02/2014 Твердохлеб: Формирует описание объекта Акции, для выписки*/
  Result :='';
  select c.name,
         t.name,
         o.fullname,
         t.id
    into Name_sharecategory,
         Name_sharetypes,
         Name_organisations,
         Asharetypes_id  
    from sm.objshares s
    join sm.opershares p on p.id = s.opershares_id
    left join sm.sharecategory c on c.id = p.sharecategory_id
    left join sm.sharetypes t on t.id = p.sharetypes_id
    left join sm.organisations o on o.id = s.organisations_id
   where s.objects_id = Aobject;
   
  if (Asharetypes_id = 1) then 
     Result := Name_sharetypes || ' ' || Name_sharecategory || ' - ' || Name_organisations;    
  end if;
  if (Asharetypes_id = 61) then 
    Result := Name_sharetypes || ' в уставном (складочном) капитале ' || Name_sharecategory || ' - ' || Name_organisations;
  end if;      
  return(Result);
end ;
/
grant execute on SM.GET_DESCRIPT_SHARE_OBJ to SM_ALLUSERS;
grant execute on SM.GET_DESCRIPT_SHARE_OBJ to SM_ALL_SELECT;


