prompt
create or replace function sm.Get_ku_record_count(Flag in char) return number is
  Result number(27);
  cnt number(27) := 0;
begin
  /* 24/02/2016 Формирует количество выгружаемых данных*/

  Result := 0;

  select count(*)
    into cnt
    from sm.dc_ku_objects;
  cnt := coalesce(cnt, 0);
  Result := Result + cnt;

  select count(*)
    into cnt
    from sm.dc_ku_clients;
  cnt := coalesce(cnt, 0);
  Result := Result + cnt;

  select count(*)
    into cnt
    from sm.dc_ku_movements;
  cnt := coalesce(cnt, 0);
  Result := Result + cnt;

  return(Result);
end Get_ku_record_count;
/
