          from grounds g
          where g.objects_id = AObject_id;         
          -- проверим, была ли история по этому реквизиту у данного объекта
                begin
                select old_value_str
                into result
                from sm_v_changes svc
                inner join grounds g on svc.id_value = g.id
                where svc.column_name = 'KADASTRNO' 
                  and g.objects_id = AObject_id 
                  and rownum = 1;
                exception
                when NO_DATA_FOUND then 
                result:='N'; -- если истории изменений не было (пусто в CHANGES по этому реквизиту для заданного объекта)
                end;
          
             if result <> 'N' then  -- если история изменений имеется
              begin
              select old_value_str 
              into result
              from (
                    select old_value_str
                    from sm_v_changes svc
                    inner join grounds g on svc.id_value = g.id
                    where svc.table_name = 'GROUNDS' 
                      and svc.column_name = 'KADASTRNO' 
