                    order by svc.change_date
                    )
              where rownum = 1;
                        exception
              when NO_DATA_FOUND then -- случай, если дата актуальности позже даты последнего изменения - тогда берем в результат текущее значение
              result := current_value;
              end;
            end if;
                         --вставка, чтобы быстро удовлетворить задание Быкаревой
             if result = 'N' then result := current_value; end if;
                              
          end;          
      end if;
      
  end;
  end if;

  --if result is null then result := 'N'; end if;    
  return(Result);
end Get_Retro_Data;
/
grant execute on SM.GET_RETRO_DATA to SM_ALL_SELECT;


