prompt
prompt Creating function HAVEEMPTYPERIODS
prompt ==================================
prompt
create or replace function sm.HaveEmptyPeriods(AMoveSet_ID IN NUMBER) RETURN number
as
  res number;
  cnt number;
begin
  
  -- Author: XSGROUP 11.11.2005
  -- функция проверяет наличие безобъектных периодов
  -- у операции движения, у которой ID=AMoveSet_ID
  -- если такие периоды имеются - возвращает 1,
  -- если безобъектных периодов нет - возвращает 0

  res:=0;

  select 
    count(*)
  into cnt   
  from 
    sm.moveperiods mp
  where
    mp.moveset_id=AMoveSet_ID and
    not exists (select * 
                from sm.moveitems mi
                where mi.moveperiod_id=mp.id);
  if cnt<>0 then
    res:=1;
  end if;              

  return(res); 
  
end HaveEmptyPeriods;
/
grant execute on SM.HAVEEMPTYPERIODS to SM_ALLUSERS;
grant execute on SM.HAVEEMPTYPERIODS to SM_ALL_SELECT;


prompt
prompt Creating function HAVESUBSTRINGS
prompt ================================
prompt
create or replace function sm.HaveSubstrings(WhereSearch in varchar2, WhatSearch in varchar2) return integer is

  -- Author  : XSGROUP
  -- Created : 22.06.2005 14:22:12
  -- Purpose : Функция ищет вхождение частей строки WhatSearch, разделённых пробелами,
  --           в строке WhereSearch (без учёта регистра букв).
  --           Если все части строки WhatSearch встречаются в строке WhereSearch - функция вернёт 1
  --           Если хотя бы одна из частей строки WhatSerch в строке WhereSearch отсутствует - функция вернёт 0      

  Result integer;
  pos integer;
  TargetS varchar2(4000);
  s1 varchar2(4000);
  s2 varchar2(4000);
begin

  Result:=0;
  
  --не будем тратить время на пустые значения
  if WhereSearch is null or WhatSearch is null then
    return(Result);
  end if;
  
  -- переведём всё в верхний регистр и подрежем конечные пробелы 
  TargetS:=UPPER(RTRIM(LTRIM(WhereSearch)));
  s1:=UPPER(RTRIM(LTRIM(WhatSearch)));
  
  -- уберём повторяющиеся пробелы
  while instr(s1,'  ')<>0 loop
    s1:=replace(s1,'  ',' ');
  end loop;
  
  
  while s1 is not null loop
    pos:=instr(s1,' ');
    if pos=0 then 
      pos:=length(s1);
    end if; 
     
    s2:=RTRIM(LTRIM(substr(s1,1,pos)));
    s1:=substr(s1,pos+1,length(s1));
    if instr(TargetS,s2)>0 then
      Result:=1;
    else
      Result:=0;
      goto exit_func;  
    end if;
  end loop;
  
  <<exit_func>>  
  return(Result);
  
end HaveSubstrings;
/
grant execute on SM.HAVESUBSTRINGS to SM_ALLUSERS;
grant execute on SM.HAVESUBSTRINGS to SM_ALL_SELECT;


prompt
prompt Creating function IMPORT_KUBANKOM
prompt =================================
prompt
create or replace function sm.Import_kubankom(Flag in char)
return type_sql_command_list pipelined as
 Id number(27); -- уникальный генерируемый идентификатор
 Type_command char(1); -- тип команды S,I,U,D
 Sql_text varchar2(32767);-- команда
 objects_id varchar2(30);
 objecttype varchar2(255);
 description varchar2(2000);
 regno varchar2(30);
 address varchar2(2000);
 region varchar2(512);
 provincearea varchar2(512);
 city varchar2(512);
 townnames varchar2(512);
 street varchar2(512);
 house varchar2(100);
 name_obj varchar2(1000);
 cat_zu varchar2(512);
 kadastrno varchar2(22);
 square varchar2(30);
 startpay varchar2(30);
 pay varchar2(30);
 cadastr_cost varchar2(30);
 share_all varchar2(100);
 table_name_object varchar2(80) := 'objects';
 table_name_clients varchar2(80) := 'clients';
 table_name_movements varchar2(80) := 'movements';
begin
  /* 22/02/2016 Процедура формирует sql команды для импорта в АИС Кубаньком*/

  -- сначала запустим команды удаления
  id := 1;
  Type_command := 'D';
  Sql_text := 'delete from ' || table_name_object || ';';

  pipe row (type_sql_command(
                             Id, -- уникальный генерируемый идентификатор
                             Type_command,-- тип команды S,I,U,D
                             Sql_text-- команда
                         ));

  id := 2;
  Type_command := 'D';
  Sql_text := 'delete from ' || table_name_clients || ';';

  pipe row (type_sql_command(
                             Id, -- уникальный генерируемый идентификатор
                             Type_command,-- тип команды S,I,U,D
                             Sql_text-- команда
                         ));

  id := 3;
  Type_command := 'D';
  Sql_text := 'delete from ' || table_name_movements || ';';

  pipe row (type_sql_command(
                             Id, -- уникальный генерируемый идентификатор
                             Type_command,-- тип команды S,I,U,D
                             Sql_text-- команда
                         ));
  id := id + 1;
  

  -- идем по уже заполненной структуре выгрузк, отвечает процедура fill_ku_import
  for qObject in (
                 select  id as objects_id,
                         objecttype,
                         description,
                         regno,
                         address,
                         region,
                         provincearea,
                         city,
                         townnames,
                         street,
                         house,
                         name_obj,
                         cat_zu,
                         kadastrno,
                         square,
                         startpay,
                         pay,
                         cadastr_cost,
                         share_all
                   from sm.dc_ku_objects o
                   order by o.id
                 )
  loop
   objects_id := TO_CHAR(qObject.objects_id);
   objecttype := qObject.objecttype;
   description := trim(replace(qObject.description, '''', '"'));
   regno := TO_CHAR(qObject.regno);
   address := replace(qObject.address, '''', '"');
   region := replace(qObject.region, '''', '"');
   provincearea := replace(qObject.provincearea, '''', '"');
   city := replace(qObject.city, '''', '"');
   townnames := replace(qObject.townnames, '''', '"');
   street := replace(qObject.street, '''', '"');
   house := replace(qObject.house, '''', '"');
   name_obj := replace(qObject.name_obj, '''', '"');
   cat_zu := qObject.cat_zu;
   kadastrno := qObject.kadastrno;
   square := replace(TO_CHAR(qObject.square), ',', '.');
   startpay := replace(TO_CHAR(qObject.startpay), ',', '.');
   pay := replace(TO_CHAR(qObject.pay), ',', '.');
   cadastr_cost := replace(TO_CHAR(qObject.cadastr_cost), ',', '.');
   share_all := qObject.share_all;

   Type_command := 'I';
   Sql_text := 'insert into ' || table_name_object || '(id, objecttype, description, regno, address, region, provincearea, city, townnames, street, house, name_obj, cat_zu, kadastrno, square, startpay, pay, cadastr_cost, share_all)
                       values (' || objects_Id ||
                           ',''' || objecttype ||
                           ''',''' || description ||
                           ''',' || regno ||
                           ',''' || address ||
                           ''',''' || region ||
                           ''',''' || provincearea ||
                           ''',''' || city ||
                           ''',''' || townnames ||
                           ''',''' || street ||
                           ''',''' || house ||
                           ''',''' || name_obj ||
                           ''',''' || cat_zu ||
                           ''',''' || kadastrno ||
                           ''',' || square ||
                           ',' || startpay ||
                           ',' || pay ||
                           ',' || cadastr_cost ||
                           ',''' || share_all || ''');';
     pipe row (type_sql_command(
               Id, -- уникальный генерируемый идентификатор
               Type_command,-- тип команды S,I,U,D
               Sql_text-- команда
           ));
   id := id + 1;
  end loop;

  -- выгружаем клиента
  for qClient in (
                  select c.id as clients_id,
                         c.clienttype,
                         c.name
                    from dc_ku_clients c
                 )
  loop
   Type_command := 'I';
   Sql_text := 'insert into ' || table_name_clients || '(id, clienttype, name)
                       values (' || TO_CHAR(qClient.clients_id) ||
                           ',''' || qClient.clienttype ||
                           ''',''' || qClient.name || ''');';
     pipe row (type_sql_command(
               Id, -- уникальный генерируемый идентификатор
               Type_command,-- тип команды S,I,U,D
               Sql_text-- команда
           ));
   id := id + 1;
  end loop;

  -- операции движения
   for qMovements in (
                      select m.id as moveperiods_id,
                             m.objects_id,
                             m.clients_id,
                             m.type_agreement,
                             m.transfbasis,
                             m.clientsfrom,
                             m.startdate,
                             m.enddate,
                             m.doc_number,
                             m.doc_date,
                             m.acting_type
                        from dc_ku_movements m
                     )
  loop
   Type_command := 'I';
   Sql_text := 'insert into ' || table_name_movements || '(id, objects_id, clients_id, type_agreement, transfbasis, clientsfrom, startdate, enddate, doc_number, doc_date, acting_type)
                       values (' || qMovements.moveperiods_id ||
                           ',' || qMovements.objects_id ||
                           ',' || qMovements.clients_id ||
                           ',''' || trim(qMovements.type_agreement) ||
                           ''',''' || qMovements.transfbasis ||
                           ''',''' || qMovements.clientsfrom ||
                           ''',''' || TO_CHAR(qMovements.startdate, 'YYYY-MM-DD') ||
                           ''',' || case
                                     when qMovements.enddate is null
                                     then 'NULL'
                                     else '''' || TO_CHAR(qMovements.enddate, 'YYYY-MM-DD') || ''''
                                    end   ||
                           ',''' || trim(qMovements.doc_number) ||
                           ''',''' || TO_CHAR(qMovements.doc_date, 'YYYY-MM-DD') ||
                           ''',''' || qMovements.acting_type || ''');';
     pipe row (type_sql_command(
               Id, -- уникальный генерируемый идентификатор
               Type_command,-- тип команды S,I,U,D
               Sql_text-- команда
           ));
   id := id + 1;
  end loop;

  return;
end Import_kubankom;
/
grant execute on SM.IMPORT_KUBANKOM to SM_ALL_SELECT;


