prompt Creating function ISLEAPYEAR
prompt ============================
prompt
CREATE OR REPLACE FUNCTION SM.IsLeapYear (forYear IN NUMBER)
  RETURN BOOLEAN
IS
--- Високосный ли год
  p_b_leap_year   BOOLEAN := FALSE;

BEGIN
  IF     (MOD (forYear, 4) = 0)
     AND ((MOD (forYear, 100) <> 0) OR (MOD (forYear, 400) = 0))
  THEN
     p_b_leap_year := TRUE;
  END IF;

  RETURN p_b_leap_year;
END;
/
grant execute on SM.ISLEAPYEAR to SM_ALLUSERS;
grant execute on SM.ISLEAPYEAR to SM_ALL_SELECT;


