prompt
prompt Creating function ISOBJINTREASURYACC
prompt ====================================
prompt
create or replace function sm.IsObjInTreasuryAcc(ObjID in NUMBER, DateApply in DATE) return CHAR is
  Result CHAR(1) := 'N';
  mdID NUMBER := 0;
  mcID NUMBER := 0;
  aMvType CHAR(1)  := 'C';
  inDate Date;
begin
---------------------
-- XSGROUP ver. 4.8.0
--    Функция Определяет в Казне ли объект на заданную дату ПО УЧЕТНЫМ ДАННЫМ
--------------------- 
 --ищем последний приход в казну
   BEGIN                  
            Select  zzz.ID, zzz.APPLY_DATE  into mdID, inDate
            from (Select mac.ID, mac.APPLY_DATE 
                      from SM.MOVE_ACC mac
                      where mac.OBJECT_ID = ObjID
                          and mac.APPLY_DATE < DateApply    
                          and mac.ACC like '0108%'   and mac.DC = 'D' and mac.description not like 'ПЕРЕОЦ%'
                          and mac.REVERSAL_ROLE <> 'Сторнированная'  and mac.REVERSAL_ROLE <> 'Сторнирующая (красн.)'  
                          order by mac.APPLY_DATE desc, mac.OPER_DATE, NVL(mac.END_DATE, '01.01.3000') desc, mac.ID desc ) zzz 
             where ROWNUM=1;                                        
  EXCEPTION
         When NO_DATA_FOUND then
                NULL;
  END;
  
  if (mdID >0) then
    --ищем выход их казны после прихода
    BEGIN                  
            Select  zzz.ID  into mcID
            from (Select mac.ID
                      from SM.MOVE_ACC mac
                      where mac.OBJECT_ID = ObjID
                          and mac.APPLY_DATE < DateApply    and mac.APPLY_DATE <= inDate
                          and mac.ACC like '0108%'   and mac.DC = 'С' and mac.description not like 'ПЕРЕОЦ%'
                          order by mac.APPLY_DATE desc, mac.OPER_DATE, NVL(mac.END_DATE, '01.01.3000') desc, mac.ID desc ) zzz 
             where ROWNUM=1;                                        
    EXCEPTION
           When NO_DATA_FOUND then
                  NULL;
    END;  
    
    if (mcID > 0) then
      Result := 'N';
    else
      Result := 'Y';
    end if; 
    
  end if;  
  
  return(Result);

end IsObjInTreasuryAcc;
/
grant execute on SM.ISOBJINTREASURYACC to SM_ALLUSERS;
grant execute on SM.ISOBJINTREASURYACC to SM_ALL_SELECT;


prompt
prompt Creating function IS_PARENT_USED
prompt ================================
prompt
CREATE OR REPLACE FUNCTION SM.is_parent_used(cdate in date,M_ID IN NUMBER,B_ID IN NUMBER,
	c_id IN NUMBER := null) RETURN number  IS
  is_used number;
BEGIN
  -- функция проверяет наличие предка у помещения c id=B_ID, участвующего в движении M_ID
  -- на дату cdate
  -- если такой предок имеется - возвращает 1
  -- иначе - 0
  is_used:=0;
  for b in (select (nvl(b.square,0)) square, mi.Square m_square, ms.movetype_id,ms.client_id clientsto_id,
		 mp.sincedate postingdate,mp.enddate,b.id id
	from sm.movesets ms,
       sm.moveperiods mp,
       sm.moveitems mi,
	     (select bw.id, bw.objects_id, bw.square from sm.buildings bw
	    	connect by prior bw.basebuilding= bw.id
	    	start with bw.id=b_id) b
	where ms.id=mp.moveset_id 
    and mp.id=mi.moveperiod_id
    and mi.object_id=b.objects_id 
    and m_id=ms.movetype_id
    and b.id<>b_id
		and (cdate>=mp.sincedate and (cdate<=mp.enddate or mp.enddate is null)))
	loop
    if b.square=b.m_square then
      is_used:=1;
      exit;
    end if;
  end loop;

  return is_used;
  exception
    when others then
	  	return is_used;
END;
/
grant execute on SM.IS_PARENT_USED to SM_ALLUSERS;
grant execute on SM.IS_PARENT_USED to SM_ALL_SELECT;


