prompt Creating function WRAP_DOCNO
prompt ============================
prompt
create or replace function sm.WRAP_DOCNO(ADOCTYPE IN NUMBER, NUM IN VARCHAR2) RETURN VARCHAR2
is
  prefix sm.doctypes.num_prefix%type; 
  suffix sm.doctypes.num_suffix%type;
  res varchar2(4000);
begin
  -- by XSGROUP 24.01.2009
  -- функция фозвращает номер документа "обрамляя" его префиксом и суффиксом
  -- заданным для данного типа документа
  select 
    nvl(t.num_prefix,''), 
    nvl(t.num_suffix,'')
  into 
    prefix, 
    suffix
  from 
    sm.doctypes t
  where 
    t.id=adoctype;

 
  res:=prefix || num || suffix;
  return (res);
  
end;
/
grant execute on SM.WRAP_DOCNO to SM_ALLUSERS;
grant execute on SM.WRAP_DOCNO to SM_ALL_SELECT;


prompt
prompt Creating function QUERYDOCNUM
prompt =============================
prompt
create or replace function sm.QueryDocNum( ADoctype_ID IN NUMBER ) return VARCHAR2
is

-- by XSGROUP,  ver, 24.01.2009
-- резервирование номеров документов
-- на вход передается тип
-- возвращает номер документа или пустую строку

  PRAGMA AUTONOMOUS_TRANSACTION;
  i integer;
  Need1 CHARACTER(1);
  DoctypeID number;
Begin

  --отработан общий алгоритм резервирования
  --для частных случаев требуется дополнительная обработка
  
  -- получаем ID типа документа, с которым будем работать
  DoctypeID:=sm.Getrootdoctypeid(ADocType_ID);
    
  --проверяем, а для этого документа полагается резервирование
  select 
    nvl(dt.RESERVING,'N') 
  into 
    Need1 
  from 
    sm.DOCTYPES dt
  where 
    dt.ID=DocTypeID;
    

  if Need1 = 'N' then
   --не полагается, тогда возвращаю пустую строку
    Return('');
  end if;

 --считаем сколько просроченных документов нашего типа
  for RSV in (select 
                rdm.DOCNO, rdm.ID
              from 
                sm.RESERVED_DOC_NUM rdm
              where
                rdm.DOCTYPE_ID=DoctypeID and
                rdm.RESERVING_EXPIRE<SYSDATE
              order by 
                rdm.RESERVING_EXPIRE)
  LOOP
    update RESERVED_DOC_NUM set RESERVING_EXPIRE=SYSDATE+1 where id=RSV.id;
    commit;
    
    Return(sm.Wrap_docno(ADoctype_ID,to_char(RSV.DocNo)));
  END LOOP;
  
  --если зарезервированных номеров нет, поищем в DOCNUMS
  --проверю, для него ведется нумерация?
  select 
    count(*) 
  into
     i 
  from 
    sm.DOCNUMS dn
  where 
    dn.DOCTYPES_ID=DocTypeID;

  IF i>0 THEN      
   --вернуть только первую строку с самым большим значением(!!!тригер DOCTYPES_POST может добавить сколько угодно строк)
    select 
      CURR_NO 
    into i
    from (
          select *
          from
            sm.DOCNUMS dn
          where dn.DOCTYPES_ID=DoctypeID 
          order by dn.CURR_NO desc
          ) 
    where
      rownum=1;
      
    update sm.DOCNUMS dn set dn.CURR_NO=i+1 where dn.DOCTYPES_ID=DocTypeID;
      
  ELSE
    i:=0;
  END IF;

    i:=i+1;

   --зарезирвировать
    insert into RESERVED_DOC_NUM(ID,DOCTYPE_ID,DOCNO,RESERVING_TIME,RESERVING_EXPIRE)
    values(seqReserve_Doc_Num.Nextval,DoctypeID,i,sysdate,sysdate+1);
    commit;
    return(sm.Wrap_Docno(ADoctype_ID,to_char(i)));

 
End;
/
grant execute on SM.QUERYDOCNUM to SM_ALLUSERS;
grant execute on SM.QUERYDOCNUM to SM_ALL_SELECT;


prompt
prompt Creating function REPLACE_CHAR
prompt ==============================
prompt
create or replace function sm.replace_char(str in varchar2) return varchar2 is
  Result varchar2(8000);
  len number(27);
  str1 varchar2(1);
  str2 varchar2(1);
begin
  Result := trim(str);
  Result := replace(Result,chr(09),'');
  Result := trim(Result);
  Result := replace(Result,chr(10),'');
  Result := replace(Result,chr(13),'');
  Result := replace(Result,' ','');
  Result := replace(Result,' ','');
  Result := replace(Result,'
','');

  len := length(Result);
  str1 := substr(Result,1,1);
  str2 := substr(Result,2,1);

  if (len > 1 and str1 = '1' and str2 = ' ')then
    Result := substr(Result,1,1) || substr(Result,3,len);
  end if;

  return(Result);
end replace_char;
/

prompt
prompt Creating function REPL_LOAD_DOCUMENTS
prompt =====================================
prompt
create or replace function sm.repl_load_documents(Flag in char, Aid_documents in number, Aid_documents_type number, Adocset_id number) RETURN NUMBER IS
is_create char(1) := '0';
docset_id number(27);
document_id number(27);
file_scan varchar2(4000) := '';
iRes number(27);
dirSaumiFilesFromAis varchar2(2048);
begin
   /* 11/02/2015 Загружает данные документов:
      1 - с созданием пакета документа
      2 - без пакета документов
   */

   if (Flag = '1') then
      -- если пакет не передали
      if (Adocset_id is null) then
         is_create := '0';
      end if;
      if (Adocset_id is not null) then
         docset_id := Adocset_id;
         is_create := '1';
      end if;
   end if;

   if (Flag = '2') then
     is_create := '1';
   end if;

   select directory_path
     into dirSaumiFilesFromAis
     from dba_directories
    where upper(directory_name) = 'DIRSAUMIFILESFROMAIS';

   for
      xxx in (
              select dl.doc_number, dl.doc_date, dl.doctypes_id, dl.id_documents_type,
                     dl.startdate, dl.doc_path, dl.doc_filename_oracle, dd.comment_
                from sm.dc_documents_detail dd
                join sm.dc_documents_load_docs dl on dl.id_documents_detail = dd.id_documents_detail
               where dd.id_documents = Aid_documents
                 and (dl.id_documents_type = Aid_documents_type or Aid_documents_type is null)
              )
   loop
     begin
       -- создадим пакет
       if (is_create = '0') then
          insert into sm.docsets (id)
               values (sm.seqdocsets.nextval);
          select sm.seqdocsets.currval
            into docset_id
            from dual;
          is_create := '1';
       end if;


       -- добавим в описание путь к файлу скану документа
       file_scan := '';
       if (xxx.doc_filename_oracle is not null) then
          file_scan := dirSaumiFilesFromAis || xxx.doc_filename_oracle;
       end if;

       -- добавим документ в пакет
       insert into documents (id, docno, docdate, doctypes_id, docsubscr_id, startdate, needconditiondoc,
                              conditiondate, conditiondoc, explanation, executed, body, subscribed_by,
                              subscribe_purpose, moved_user, date_start, date_end, ust_date_start,
                              ust_date_num, ust_date_check, file_extention, file_scan)
            values (sm.seqdocuments.nextval, xxx.doc_number, xxx.doc_date, coalesce(xxx.doctypes_id,1264), null, xxx.startdate, 'N', null, null, xxx.comment_,
                   'Y', null, '', '', '', null, null, null, '', 1, '', file_scan);

       select sm.seqdocuments.currval
         into document_id
         from dual;

       if (Flag = '1') then
         insert into sm.docset_members (docset_id, document_id, docrole_id)
              values (docset_id, document_id, null);
       end if;
     end;
     -- если нужен документ, то берем только первый
     if (Flag = '2') then
         return document_id;
     end if;
   end loop;

   if (docset_id is null) then
     docset_id := 1;
   end if;

   if (document_id is null) then
     document_id := 1;
   end if;

   if (Flag = '1') then
      iRes := docset_id;
   else
      iRes := document_id;
   end if;

   return iRes;
end repl_load_documents;
/
grant execute on SM.REPL_LOAD_DOCUMENTS to SM_ALL_SELECT;


prompt
prompt Creating function REPORTINHERITED
prompt =================================
prompt
create or replace function sm.ReportInherited (ReportID NUMBER, DataType NUMBER) return varchar2 is
  CurrID INTEGER;
begin
 if ReportID=DataType then
  return 'Y';
 end if;

 SELECT Inherited INTO CurrID FROM ReportsTree WHERE ID=DataType;

 WHILE CurrID != ReportID LOOP
  SELECT Inherited INTO CurrID FROM ReportsTree WHERE ID=CurrID;
 END LOOP;

 if CurrID IS NULL then
  return 'N';
 else
  return 'Y';
 end if;

EXCEPTION
  WHEN NO_DATA_FOUND THEN return 'N';

end ReportInherited;
/
grant execute on SM.REPORTINHERITED to SM_ALLUSERS;
grant execute on SM.REPORTINHERITED to SM_ALL_SELECT;


prompt
prompt Creating function REP_BEZVOZINFO
prompt ================================
prompt
create or replace function sm.Rep_BezvozInfo(AData date) return TYPE_REP_BEZVOZINFO_LIST pipelined as
 Id number(27); 
 --KBK varchar2(50); 
 BorrowerName varchar2(1000); 
 --ContractNum varchar2(1000); 
 --ContractDate date;
 FirstPeriodDate date; 
 PeriodEndDate date;
 --BorrowerCategory varchar2(500); 
 Rent_sum_0101 number(27,2); 
 Rent_sum_cntrct_0101_Adate number(27,2);
 Rent_sum_cntrct_Q_Adate number(27,2);
 Rent_sum_Termcntrct_0101_Adate number(27,2);
 Rent_sum_Termcntrct_Q_Adate number(27,2);
 Monthly_Recognised_Profit number(27,2); 
 Fair_Value_Balance number(27,2); 
 
 YearStartDate date;
 Q_StartDate date;
 
 docstartdate date;
 docenddate date;


begin
/*14032025 - Чувыкин В.Э. - отчет "Информация о договорах безвозмездного пользования*/

YearStartDate:='01.01.2026';
Q_StartDate:='01.01.2026';

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям
SELECT
t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name BorrowerName  -- Наименование Ссудодателя
, t2.inn BorrowerInn-- ИНН Ссудодателя
, sm.GetArendatorCategory(t2.id) BorrowerCat --Категория Ссудодателя
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД БП
, t4.docdate DocDate -- дата договора БП
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора БП
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора БП
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор БП
from
SM.MOVETYPE t1
, SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
(t8.MoveType_ID=t1.ID)
 and (t2.ID=t8.Client_ID)
 and (t8.transferbasis_id=t3.ID)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
 MoveSets.ID
FROM
 sm.MoveSets
WHERE
 MOVESETS.FIND_DUBLICATE = 'N' and
 MOVESETS.MOVETYPE_ID IN (22) and
 ((sm.GetMoveSetEndDate(MoveSets.ID) >= YearStartDate and sm.GetMoveSetEndDate(MoveSets.ID) <= AData) or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL) and
 (sm.GetMoveSetSinceDate(MoveSets.ID) <= AData)

))
order by BorrowerName
-- конец запроса
)

loop
    Rent_sum_0101:=0;
    Rent_sum_cntrct_0101_Adate:=0;
    Rent_sum_cntrct_Q_Adate:=0;
    Rent_sum_Termcntrct_0101_Adate:=0;
    Rent_sum_Termcntrct_Q_Adate:=0;
    Monthly_Recognised_Profit:=0;
    Fair_Value_Balance:=0;
     
--Расчет столбца "Остаточная справедливая стоимость права пользования на весь период действия договоров по состоянию на начало года"
   --если договор-документ уже истек к началу года, то справедливая стоимоcть всегда 0
   if xxx.docenddate < YearStartDate then
            Rent_sum_0101 :=0;
   end if;
   -- если договор-документ еще не истек на начало года, то считать упущенную выгоду на начало года
   -- у тех договоров, что еще не существовали на начало года, УпВ будет 0
   if xxx.docenddate >= YearStartDate then 
   Rent_sum_0101:= CALC_LOST_PROFITS(xxx.ms_id, YearStartDate, xxx.docstartdate, xxx.docenddate);
   end if;

--Расчет столбца "Справедливая стоимость по договорам безвозмездного пользования, заключенным с начала года и по отчетную дату на весь период их действия - С НАЧАЛА ГОДА ПО ОТЧЕТНУЮ ДАТУ"
   if xxx.docstartdate>=YearStartDate and xxx.docstartdate<=AData then
    Rent_sum_cntrct_0101_Adate:=CALC_LOST_PROFITS(xxx.ms_id, xxx.docstartdate, xxx.docstartdate, xxx.docenddate);
   end if;
   
--Расчет столбца "Справедливая стоимость по договорам безвозмездного пользования, заключенным с начала года и по отчетную дату на весь период их действия - ЗА ОТЧЕТНЫЙ КВАРТАЛ"  
   if xxx.docstartdate>=Q_StartDate and xxx.docstartdate<=AData then
    Rent_sum_cntrct_Q_Adate:=CALC_LOST_PROFITS(xxx.ms_id, xxx.docstartdate, xxx.docstartdate, xxx.docenddate);
   end if;

--дополнительные столбцы с датами договора и периодов
   docstartdate:=xxx.docstartdate;
   docenddate:=xxx.docenddate;
   
   FirstPeriodDate:=xxx.sel9;
   PeriodEndDate:=sm.GetMoveSetEndDate(xxx.ms_id);
   
--Расчет столбца "Сумма справедливой стоимости, подлежащая списанию, в связи с расторжением договоров безвозмездного пользования - С НАЧАЛА ГОДА ПО ОТЧЕТНУЮ ДАТУ"
   if PeriodEndDate>=YearStartDate and PeriodEndDate<=AData and PeriodEndDate<docenddate then
    Rent_sum_Termcntrct_0101_Adate:=CALC_LOST_PROFITS_4TERM_CNTR(xxx.ms_id, PeriodEndDate, xxx.docstartdate, xxx.docenddate);
   end if;
   
--Расчет столбца "Сумма справедливой стоимости, подлежащая списанию, в связи с расторжением договоров безвозмездного пользования - ЗА ОТЧЕТНЫЙ КВАРТАЛ"  
   if PeriodEndDate>=Q_StartDate and PeriodEndDate<=AData and PeriodEndDate<docenddate then
    Rent_sum_Termcntrct_Q_Adate:=CALC_LOST_PROFITS_4TERM_CNTR(xxx.ms_id, PeriodEndDate, xxx.docstartdate, xxx.docenddate);
   end if;
   
--Расчет столбца "Сумма справедливой стоимости ежемесячно признанных доходов (упущенная выгода)"
   --для договоров, досрочно расторгнутых в период с начала года до отчетной даты
   if PeriodEndDate>=YearStartDate and PeriodEndDate<=AData and PeriodEndDate<docenddate then
    Monthly_Recognised_Profit:=CALC_LOST_PROFITS(xxx.ms_id, YearStartDate, xxx.docstartdate, PeriodEndDate);
   end if;
   --для договоров, истекших в период с начала года до отчетной даты
   if docenddate>=YearStartDate and docenddate<=AData then
    Monthly_Recognised_Profit:=CALC_LOST_PROFITS(xxx.ms_id, YearStartDate, xxx.docstartdate, docenddate);
   end if;
   --для договоров, c незакрытым периодом и с еще не истекшим договором и заключенных до начала года
   if PeriodEndDate is null and docenddate>AData and docstartdate<YearStartDate then
    Monthly_Recognised_Profit:=CALC_LOST_PROFITS(xxx.ms_id, YearStartDate, xxx.docstartdate, AData);
   end if;
   --для договоров, c незакрытым периодом и с еще не истекшим договором и заключенных уже в этом году
   if PeriodEndDate is null and docenddate>AData and docstartdate>=YearStartDate then
    Monthly_Recognised_Profit:=CALC_LOST_PROFITS(xxx.ms_id, xxx.docstartdate, xxx.docstartdate, AData);
   end if;
  
--Расчет столбца "Остаток справедливой стоимости по договорам безвозмездного пользования"  
   Fair_Value_Balance:=CALC_LOST_PROFITS(xxx.ms_id, AData+1, xxx.docstartdate, xxx.docenddate);   
      

   pipe row (TYPE_REP_BEZVOZINFO(
                           id,
                           '92111105034040900120',
                           xxx.borrowername,                          
                           xxx.ArDoc,
                           xxx.docdate,
                           docstartdate,
                           docenddate,
                           FirstPeriodDate,
                           PeriodEndDate,
                           xxx.borrowercat,
                           Rent_sum_0101,
                           Rent_sum_cntrct_0101_Adate,
                           Rent_sum_cntrct_Q_Adate,
                           Rent_sum_Termcntrct_0101_Adate,
                           Rent_sum_Termcntrct_Q_Adate,
                           Monthly_Recognised_Profit,
                           Fair_Value_Balance                      
                           )
             );
                      

    id := id + 1;
 end loop;

  return;

end Rep_BezvozInfo;
/
