                                         null,--GetMoveBalanceAll(GetMoveSetId(xxx.object_id,4),'01.01.2023'),
                                         null,--GetMoveChargesByPer(GetMoveSetId(xxx.object_id,4), '01.01.2023', '31.03.2023', 102),
                                         null,--GetMovePaysByPer(GetMoveSetId(xxx.object_id,4), '01.01.2023', '31.03.2023', 102),
                                         null,--GetMoveChargesByPer(GetMoveSetId(xxx.object_id,4), '01.04.2023', '30.06.2023', 102),
                                         null,--GetMovePaysByPer(GetMoveSetId(xxx.object_id,4), '01.04.2023', '30.06.2023', 102),
                                         null,--GetMoveChargesByPer(GetMoveSetId(xxx.object_id,4), '01.07.2023', '30.09.2023', 102),
                                         null,--GetMovePaysByPer(GetMoveSetId(xxx.object_id,4), '01.07.2023', '30.09.2023', 102),
                                         null,--GetMoveChargesByPer(GetMoveSetId(xxx.object_id,4), '01.10.2023', '31.12.2023', 102),
                                         null--GetMovePaysByPer(GetMoveSetId(xxx.object_id,4), '01.10.2023', '31.12.2023', 102)
                                         )
             );*/



    id := id + 1;
 end loop;

  return;

end Rep_Contracts_Charges_Pays_3;
