prompt
prompt Creating function REP_CREDIT_REMAINDER
prompt ======================================
prompt
create or replace function sm.REP_CREDIT_REMAINDER(Flag varchar2, TownArea number, Fromdate date, Todate date)
return REPCREDITREMAINDERLIST pipelined as
  id NUMBER;
  name_contractor VARCHAR2(512);
  kbk VARCHAR2(20);  
  remainder_before_1 number(18,2);
  remainder_before_2 number(18,2);
  remainder_before_3 number(18,2);  
  move_1 number(18,2);
  move_2 number(18,2);
  decrease number(18,2);  
  remainder_after_1 number(18,2);
  remainder_after_2 number(18,2);
  remainder_after_3 number(18,2);
  charges number(18,2);
  payments number(18,2);
  fromdate_current date;
  remainder_before_current number(18,2);
begin
  /* 25/06/2018 Твердохлеб: Отчет Кредиторская задолженность
                Эта таблица действует только в рамках переплаты. 
                Мы показываем начальную переплату (столб D), сколько начислено за период (G) и сколько переплаты 
                осталось на конец периода (J). Если за период начислено (G) меньше, чем переплаты на начало периода (D), 
                то мы просто указываем сколько переплаты осталось (J) (пример - Татьяна ООО пеня). 
                Однако, если за период начислено (G) больше, чем была переплата на начало периода (D), 
                то в столбе G мы отразим не всю сумму начисления, а только вплоть числа перплаты - в остатке на конец 
                периода показываем 0, а разница, которая осталась уйдет в таблицу по долгам (пример - Аганикян).
  */
  
  -- зная период мы можем вычислить последний отчетный период
  SELECT TRUNC(Todate, 'Q') AS D into fromdate_current FROM DUAL;

  -- получим список действующих ОД
  -- за период с начала года по указанную дату
  id := 1;
  
  for 
      qClient in
              (
               select distinct
                      q.movesets_id,
                      q.clients_id,
                      q.name_client
                 from 
                      (
                        select  distinct
                                ms.id as movesets_id,
                                cl.id as clients_id,
                                cl.name as name_client,
                                sm.CalcFine(Fromdate-1, ms.id, ot.ID,'PAY','CHARGE') CHARGES_START,
                                sm.CalcFine(Fromdate-1, ms.id, ot.ID,'PAY','PAY') PAYMENTS_START
                           from sm.movesets ms                          
                           join sm.clients cl on cl.id = ms.client_id   
                           join sm.obligations o on o.moveset_id = ms.id
                           join sm.obligationtype ot on ot.id = o.obligationtype_id              
                          where ms.movetype_id = 4
                            and exists(select mp.id
                                         from sm.moveperiods mp
                                         join sm.moveitems mi on mi.moveperiod_id = mp.id
                                         join sm.objects o on o.id = mi.object_id
                                         join sm.address a on a.id = o.address_id
                                        where mp.moveset_id = ms.id
                                          and (a.townarea_id = TownArea or TownArea = -1 or TownArea is null)
                                          and rownum <= 1
                                      )
                            and exists(select mp.id
                                         from sm.moveperiods mp
                                        where mp.moveset_id = ms.id
                                          and (mp.enddate >= '01.01.2014' or mp.enddate is null)
                                          and rownum <= 1
                                      )
                           /* and mp.sincedate <= Todate 
                            and (mp.enddate >= Fromdate or mp.enddate is null) */
                            and ms.find_dublicate <> 'Y'
                            and ot.id = 81 -- Аренда имущества
                       order by name_client 
                      ) q     
                  where abs(coalesce(q.CHARGES_START,0) - coalesce(q.PAYMENTS_START,0)) > 0        
              )
  loop
        for
           xxx in (
                   select                           
                          q.type_calc,
                          q.CHARGES_START, 
                          q.PAYMENTS_START, 
                          q.CHARGES_END,  
                          q.PAYMENTS_END,
                          q.CHARGES_CURRENT_START,
                          q.PAYMENTS_CURRENT_START 
                     from 
                          (
                           select '1CHARGE' type_calc,
                                  sm.CalcFine(Fromdate-1, qClient.movesets_id, ot.ID,'PAY','CHARGE') CHARGES_START, 
                                  sm.CalcFine(Fromdate-1, qClient.movesets_id, ot.ID,'PAY','PAY') PAYMENTS_START, 
                                  sm.CalcFine(Todate, qClient.movesets_id, ot.ID,'PAY','CHARGE') CHARGES_END,  
                                  sm.CalcFine(Todate, qClient.movesets_id, ot.ID,'PAY','PAY') PAYMENTS_END,
                                  sm.CalcFine(fromdate_current-1, qClient.movesets_id, ot.ID,'PAY','CHARGE') CHARGES_CURRENT_START, 
                                  sm.CalcFine(fromdate_current-1, qClient.movesets_id, ot.ID,'PAY','PAY') PAYMENTS_CURRENT_START 
                             from sm.obligations o
                             join sm.obligationtype ot on ot.id = o.obligationtype_id
                            where o.moveset_id = qClient.movesets_id
                              and ot.id = 81 -- Аренда имущества  
                           union all    
                           select '2FINE' as type_calc,
                                  sm.CalcFine(Fromdate-1, qClient.movesets_id, ot.ID,'FINE','CHARGE') CHARGES_START, 
                                  sm.CalcFine(Fromdate-1, qClient.movesets_id, ot.ID,'FINE','PAY') PAYMENTS_START, 
                                  sm.CalcFine(Todate, qClient.movesets_id, ot.ID,'FINE','CHARGE') CHARGES_END, 
                                  sm.CalcFine(Todate, qClient.movesets_id, ot.ID,'FINE','PAY') PAYMENTS_END,
                                  sm.CalcFine(fromdate_current-1, qClient.movesets_id, ot.ID,'FINE','CHARGE') CHARGES_CURRENT_START, 
                                  sm.CalcFine(fromdate_current-1, qClient.movesets_id, ot.ID,'FINE','PAY') PAYMENTS_CURRENT_START
                             from sm.obligations o
                             join sm.obligationtype ot on ot.id = o.obligationtype_id
                            where o.moveset_id = qClient.movesets_id
                              and ot.id = 81 -- Аренда имущества                           
                           )q
                      where (coalesce(q.CHARGES_START, 0) - coalesce(q.PAYMENTS_START, 0)) < 0        
                )
      loop
         name_contractor := qClient.name_client;    
         kbk := NULL;  
         remainder_before_1 := NULL;
         remainder_before_2 := NULL;
         remainder_before_3 := NULL;
         move_1 := NULL;
         move_2 := NULL;
         decrease := NULL;  
         remainder_after_1 := NULL;
         remainder_after_2 := NULL;
         remainder_after_3 := NULL;
         
         -- найдем кбк
         if (xxx.type_calc = '1CHARGE') then
           begin
             select k.name
                    into kbk
               from sm.movesets ms
               join sm.moveperiods mp on mp.moveset_id = ms.id
               join sm.obligations o on o.moveset_id = ms.id
               join sm.obligationtype ot on ot.id = o.obligationtype_id
               join sm.paydocs p on p.obligationtype_id = ot.id and p.moveperiod_id = mp.id
               join sm.cls_kbk k on k.id = p.main_cls_kbk_id
              where ms.id = qClient.movesets_id
                and ot.id = 81 -- Аренда имущества
                and mp.sincedate = (select max(mp.sincedate) from sm.moveperiods mp where mp.moveset_id = qClient.movesets_id); 
           exception
            when NO_DATA_FOUND then
            null;
           end;
         end if;  
         
          if (xxx.type_calc = '2FINE') then
           begin
              name_contractor := name_contractor || ' (пени)';
              select k.name
                into kbk
               from sm.movesets ms
               join sm.moveperiods mp on mp.moveset_id = ms.id
               join sm.obligations o on o.moveset_id = ms.id
               join sm.obligationtype ot on ot.id = o.obligationtype_id
               join sm.paydocs p on p.obligationtype_id = ot.id and p.moveperiod_id = mp.id
               join sm.cls_kbk k on k.id = p.fine_cls_kbk_id
              where ms.id = qClient.movesets_id
                and ot.id = 81 -- Аренда имущества
                and mp.sincedate = (select max(mp.sincedate) from sm.moveperiods mp where mp.moveset_id = qClient.movesets_id);  
            exception
            when NO_DATA_FOUND then
            null;
           end;
         end if;
         
         -- если есть переплата, то есть смысл идти дальше, так как мы работаем только с переплатами 
         -- D
         remainder_before_1 := coalesce(xxx.CHARGES_START, 0) - coalesce(xxx.PAYMENTS_START, 0);
         
         if (remainder_before_1 < 0) then
            remainder_before_1 := abs(remainder_before_1);
            -- G
            charges := coalesce(xxx.CHARGES_END, 0) - coalesce(xxx.CHARGES_START, 0);
            -- оплата без номерации
            payments := coalesce(xxx.PAYMENTS_END, 0) - coalesce(xxx.PAYMENTS_START, 0);
          
            move_1 := charges;
            
            -- Если за период начислено (G) меньше, чем переплаты на начало периода (D), 
            -- то мы просто указываем сколько переплаты осталось (J) (пример - Татьяна ООО пеня)
            if (move_1 < remainder_before_1) then
              -- J
              remainder_after_1 := remainder_before_1 - move_1;
            elsif (move_1 >= remainder_before_1) then
              -- Однако, если за период начислено (G) больше, чем была переплата на начало периода (D), 
              -- то в столбе G мы отразим не всю сумму начисления, а только вплоть числа перплаты - в остатке на конец 
              -- периода показываем 0, а разница, которая осталась уйдет в таблицу по долгам (пример - Аганикян).
              -- G
              move_1 := remainder_before_1;
              -- J
              remainder_after_1 := 0;
            end if;
              
            -- Столбец H дублируется со столбцом G, так как пока что периоды совпадают.
            -- если период уже не первый квартал, то смотрим сколько погашено за текущий квартал 
            move_2 := move_1; 
            
            -- если на начало текущего квартала нет переплаты, то и гасить нечего
            remainder_before_current := coalesce(xxx.CHARGES_CURRENT_START, 0) - coalesce(xxx.PAYMENTS_CURRENT_START, 0);
            if (remainder_before_current >= 0) then
              move_2 := 0;
            else  
              remainder_before_current := abs(remainder_before_current);       
              -- если есть переплата, то работаем также как и для колонки G
              -- начислено за текущий квартал
              move_2 := coalesce(xxx.CHARGES_END, 0) - coalesce(xxx.CHARGES_CURRENT_START, 0);
              
              if (move_2 < remainder_before_current) then
                move_2 := move_2;
              elsif (move_2 >= remainder_before_current) then
                move_2 := remainder_before_current;             
              end if;
            end if;    
            
            pipe row (REPCREDITREMAINDER(
                                      id,
                                      name_contractor,
                                      kbk,  
                                      remainder_before_1,
                                      remainder_before_2,
                                      remainder_before_3,
                                      move_1,
                                      move_2,
                                      decrease,  
                                      remainder_after_1,
                                      remainder_after_2,
                                      remainder_after_3
                                       ));
            id := id + 1;                           
         end if;              
      end loop;
  end loop;  
      
  RETURN;
end REP_CREDIT_REMAINDER;
/

prompt
prompt Creating function REP_DBP
prompt =========================
prompt
create or replace function sm.Rep_DBP(AData date) return TYPE_REP_DBP_LIST pipelined as
 Id number(27);
 DBP number(27,2);
 AmountByDate number(27,2);
 Remaining_months integer;
 Remaining_days integer;
 EndDayOfControlMonth integer;

begin
/*08022022 - Чувыкин В.Э. - отчет "Доходы будущих периодов" за Аренду имущества*/

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям

SELECT

t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование арендатора
, t2.inn ArInn-- ИНН арендатора
, sm.GetArendatorCategory(t2.id) ArCat --Категория арендатора
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД Аренда
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора аренды
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора аренды
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор аренды

FROM
SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
 (t2.ID=t8.Client_ID)
 and
 (t8.transferbasis_id=t3.ID)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
                   MoveSets.ID
                  FROM
                   sm.MoveSets
                  WHERE
                   EXISTS (
                            SELECT
                             Obligations.ID
                            FROM
                             SM.Obligations,
                             sm.MoveSets OMS
                            WHERE
                             EXISTS ( SELECT
                                       Charges.ID
                                      FROM
                                       sm.Charges,
                                       sm.Obligations CHOBL
                                      WHERE
                                       CHARGES.CLS_KBK_ID IN (SELECT ID FROM SM.CLS_KBK START WITH ID=39 CONNECT BY PRIOR ID=ROOT)
                                       and
                                       CHOBL.ID=Obligations.ID
                                       and
                                       CHOBL.MoveSet_ID=Charges.MoveSets_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       )
                             and
                             OMS.ID=MoveSets.ID
                             and
                             SM.Obligations.MoveSet_ID=OMS.ID
                  ) and
                   MOVESETS.MOVETYPE_ID IN (4) and
                   (sm.GetMoveSetEndDate(MoveSets.ID) >= AData or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL)
                   
                   /*sm.GetMoveSetEndDate(MoveSets.ID) IS NULL*/ /*and -- убрал условие того, что должны выбираться только открытые на отчетную дату договора
                   sm.GetMoveSetMainDocID(MoveSets.ID) IN (SELECT
                                                           Documents.ID
                                                           FROM
                                                           sm.Documents
                                                           WHERE
                                                           DOCUMENTS.DATE_END > AData)*/

                  ))
order by Arname
-- конец запроса
)

loop
   -- если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты на 3 года вперед
   -- изменения 2024: если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода - 0
   if xxx.docenddate < AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, add_months(AData,36), 81);
         DBP :=0;
   end if;

   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   if xxx.docenddate >= AData then
   DBP := CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 81);
   end if;
   
   AmountByDate := sm.GetMoveAmountByDate(xxx.ms_id,81,Adata);
   
   Remaining_months := trunc(MONTHS_BETWEEN(xxx.docenddate, AData));
   --Remaining_days := to_date(xxx.docenddate) - to_date(AData);
   EndDayOfControlMonth := extract(day from AData);
   --select extract(day from date AData) into EndDayOfPrevLastMonth from dual;
   if EndDayOfControlMonth = 30 
     then
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 2;
     else 
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 1;    
   end if;
   
   pipe row (TYPE_REP_DBP(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.arcat,
                           xxx.ArDoc,
                           xxx.docstartdate,
                           AmountByDate,
                           Remaining_months,
                           Remaining_days,
                           DBP                          
                           )
             );

    id := id + 1;
 end loop;

  return;

end REP_DBP;
/
grant execute on SM.REP_DBP to SM_ALLUSERS;


prompt
prompt Creating function REP_DBP_EXT
prompt =============================
prompt
create or replace function sm.Rep_DBP_EXT(AData date) return TYPE_REP_DBP_EXT_LIST pipelined as
 Id number(27);
 DBP number(27,2);
 DBP0101 number(27,2);
 DBP_after_FirstDayofYear number(27,2);
 DBP_Q number(27,2);
 ChargesOnADate number(27,2);
 AmountByDate number(27,2);
 Remaining_months integer;
 Remaining_days integer;
 EndDayOfControlMonth integer;
 FirstDayofYear date;
 Q date;

begin
/*200625 - Чувыкин В.Э. - расширенный отчет "Доходы будущих периодов" за Аренду имущества*/

id:=1;
FirstDayofYear:='01.01.2026'; --заданное начало года
Q:='01.01.2026'; -- начало отчетного квартала

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям

SELECT

t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование арендатора
, t2.inn ArInn-- ИНН арендатора
, sm.GetArendatorCategory(t2.id) ArCat --Категория арендатора
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД Аренда
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора аренды
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора аренды
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор аренды

FROM
SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
 (t2.ID=t8.Client_ID)
 and
 (t8.transferbasis_id=t3.ID)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
                   MoveSets.ID
                  FROM
                   sm.MoveSets
                  WHERE
                   EXISTS (
                            SELECT
                             Obligations.ID
                            FROM
                             SM.Obligations,
                             sm.MoveSets OMS
                            WHERE
                             EXISTS ( SELECT
                                       Charges.ID
                                      FROM
                                       sm.Charges,
                                       sm.Obligations CHOBL
                                      WHERE
                                       CHARGES.CLS_KBK_ID IN (SELECT ID FROM SM.CLS_KBK START WITH ID=39 CONNECT BY PRIOR ID=ROOT)
                                       and
                                       CHOBL.ID=Obligations.ID
                                       and
                                       CHOBL.MoveSet_ID=Charges.MoveSets_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       )
                             and
                             OMS.ID=MoveSets.ID
                             and
                             SM.Obligations.MoveSet_ID=OMS.ID
                  ) and
                   MOVESETS.MOVETYPE_ID IN (4) and
                   (sm.GetMoveSetEndDate(MoveSets.ID) >= AData or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL)

                   /*sm.GetMoveSetEndDate(MoveSets.ID) IS NULL*/ /*and -- убрал условие того, что должны выбираться только открытые на отчетную дату договора
                   sm.GetMoveSetMainDocID(MoveSets.ID) IN (SELECT
                                                           Documents.ID
                                                           FROM
                                                           sm.Documents
                                                           WHERE
                                                           DOCUMENTS.DATE_END > AData)*/

                  ))
order by Arname
-- конец запроса
)

loop

   DBP_after_FirstDayofYear:=null;
   DBP_Q:=null;
   -- если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты на 3 года вперед
   -- изменения 2024: если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода - 0
   if xxx.docenddate < AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, add_months(AData,36), 81);
         DBP :=0;
   end if;
   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   if xxx.docenddate >= AData then
   DBP := CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 81);
   end if;
   
   -- расчет текущего начисления доходов по договору на отчетную дату, для договоров еще открытых на задаваемую отчетную дату
   if xxx.docenddate >= AData then
   ChargesOnADate := GetMoveChargesByPer(xxx.ms_id, ADD_MONTHS(to_date(xxx.docstartdate, 'dd.mm.yyyy'), -1), AData, 81, 1);
   end if;   
   -- расчет текущего начисления доходов по договору на отчетную дату, для договоров уже закрытых  - 0
   if xxx.docenddate < AData then
   ChargesOnADate := 0;
   end if;  
     
   -- если договор еще открыт на задаваемую отчетную дату, расчет дохода будущего периода с начала года до конца действия договора
   if xxx.docenddate >= AData then
   DBP0101 := CALCCHARGES_DBP(xxx.ms_id, FirstDayofYear, xxx.docenddate, 81);
   end if;  
   -- если договор уже закрыт на задаваемую отчетную дату, расчет дохода будущего периода  - 0
   if xxx.docenddate < AData then
   DBP0101 := 0;
   end if;

   --для договоров, открытых после начала года
   -- если договор еще открыт на задаваемую отчетную дату, расчет дохода будущего периода на весь период действия договора
   if (xxx.docstartdate >= FirstDayofYear) AND (xxx.docenddate >= AData) then
   DBP_after_FirstDayofYear := CALCCHARGES_DBP(xxx.ms_id, xxx.docstartdate, xxx.docenddate, 81);
   end if;  
   -- если договор уже закрыт на задаваемую отчетную дату, расчет дохода будущего периода  - 0
   if (xxx.docstartdate >= FirstDayofYear) AND (xxx.docenddate < AData) then
   DBP_after_FirstDayofYear := 0;
   end if;
   
   --для договоров, открытых в отчетном квартале
   -- если договор еще открыт на задаваемую отчетную дату, расчет дохода будущего периода на весь период действия договора
   if (xxx.docstartdate >= Q) AND (xxx.docenddate >= AData) then
   DBP_Q := CALCCHARGES_DBP(xxx.ms_id, xxx.docstartdate, xxx.docenddate, 81);
   end if;  
   -- если договор уже закрыт на задаваемую отчетную дату, расчет дохода будущего периода  - 0
   if (xxx.docstartdate >= Q) AND (xxx.docenddate < AData) then
   DBP_Q := 0;
   end if;
   
   --Арендная плата на отчетную дату
   AmountByDate := sm.GetMoveAmountByDate(xxx.ms_id,81,Adata);

   --Осталось месяцев и дней
   Remaining_months := trunc(MONTHS_BETWEEN(xxx.docenddate, AData));
   --Remaining_days := to_date(xxx.docenddate) - to_date(AData); 
   EndDayOfControlMonth := extract(day from AData);
   --select extract(day from date AData) into EndDayOfPrevLastMonth from dual;
   if EndDayOfControlMonth = 30
     then
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 2;
     else
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 1;
   end if;

   pipe row (TYPE_REP_DBP_EXT(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.arcat,
                           xxx.ArDoc,
                           xxx.docstartdate,
                           AmountByDate,
                           Remaining_months,
                           Remaining_days,
                           DBP,
                           DBP0101,
                           ChargesOnADate,
                           DBP_after_FirstDayofYear,
                           DBP_Q
                           )
             );

    id := id + 1;
 end loop;

  return;

end REP_DBP_EXT;
/
grant execute on SM.REP_DBP_EXT to SM_ALLUSERS;


prompt
prompt Creating function REP_DBP_GROUNDS
prompt =================================
prompt
create or replace function sm.Rep_DBP_Grounds(AData date) return TYPE_REP_DBP_LIST pipelined as
 Id number(27);
 DBP number(27,2);
 AmountByDate number(27,2);
 Remaining_months integer;
 Remaining_days integer;
  EndDayOfControlMonth integer;

begin
/*12112024 - Чувыкин В.Э. - отчет "Доходы будущих периодов" за Аренду земли*/

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям

SELECT

t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование арендатора
, t2.inn ArInn-- ИНН арендатора
, sm.GetArendatorCategory(t2.id) ArCat --Категория арендатора
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД Аренда
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора аренды
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора аренды
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор аренды

FROM
SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
 (t2.ID=t8.Client_ID)
 and
 (t8.transferbasis_id=t3.ID)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
                   MoveSets.ID
                  FROM
                   sm.MoveSets
                  WHERE
                   EXISTS (
                            SELECT
                             Obligations.ID
                            FROM
                             SM.Obligations,
                             sm.MoveSets OMS
                            WHERE
                             EXISTS ( SELECT
                                       Charges.ID
                                      FROM
                                       sm.Charges,
                                       sm.Obligations CHOBL
                                      WHERE
                                       CHARGES.CLS_KBK_ID IN (SELECT ID FROM SM.CLS_KBK START WITH /*ID=39*/ ID=166 OR ID=186 CONNECT BY PRIOR ID=ROOT)
                                       and
                                       CHOBL.ID=Obligations.ID
                                       and
                                       CHOBL.MoveSet_ID=Charges.MoveSets_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       )
                             and
                             OMS.ID=MoveSets.ID
                             and
                             SM.Obligations.MoveSet_ID=OMS.ID
                  ) and
                   MOVESETS.MOVETYPE_ID IN (4) and
                   (sm.GetMoveSetEndDate(MoveSets.ID) >= AData or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL)
                    

                  ))
order by Arname
-- конец запроса
)

loop
   -- если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода - 0
   if xxx.docenddate < AData then
      DBP :=0;
   end if;

   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   
   /*if xxx.docenddate >= AData then

   /*select 
    CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 102) + CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 192) + CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 212) into DBP
   from dual;*/
   /*end if;*/
   
   select 
    sm.GetMoveAmountByDate(xxx.ms_id,102,Adata) + sm.GetMoveAmountByDate(xxx.ms_id,192,Adata) + sm.GetMoveAmountByDate(xxx.ms_id,212,Adata) into AmountByDate
   from dual;
   
    if xxx.docenddate >= AData then  
   DBP:=AmountByDate  *MONTHS_BETWEEN(xxx.docenddate,AData) / 3;
   end if;
   
   Remaining_months := trunc(MONTHS_BETWEEN(xxx.docenddate, AData));
   --Remaining_days := to_date(xxx.docenddate) - to_date(AData);
   EndDayOfControlMonth := extract(day from AData);
   --select extract(day from date AData) into EndDayOfPrevLastMonth from dual;
   if EndDayOfControlMonth = 30 
     then
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 2;
     else 
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 1;    
   end if;
   
   pipe row (TYPE_REP_DBP(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.arcat,
                           xxx.ArDoc,
                           xxx.docstartdate,
                           AmountByDate,
                           Remaining_months,
                           Remaining_days,
                           DBP
                           )
             );

    id := id + 1;
 end loop;

  return;

end REP_DBP_Grounds;
/
grant execute on SM.REP_DBP_GROUNDS to SM_ALLUSERS;


prompt
prompt Creating function REP_FULLDOCLIST_1
prompt ===================================
prompt
create or replace function sm.REP_FULLDOCLIST_1(Aobject_id in number, Amovetype_id  in NUMBER, Aobjtypes_list in varchar2, Adate in date,ADocrole_id IN number, Amovesets_id in number default null) return varchar2 is
  Result varchar2(10000);
  bFind CHAR(1);
  ADateReq DATE;
  i NUMBER;
  /* 16.10.2011 Твердохлеб */
  -- функция возвращает список документов из пакета, включая главный + если есть родитель,
  -- то берет документы по Собственности и Балансосодержателю по родителю, главному.
  -- по предыдущим периодам !!!
 /* 15/07/2015 Твердохлеб: убрал во втором запросе документов условие выводить одну запись*/
 /* 01/02/2016 Твердохлеб: в запросах теперь получаем сначала пред. период и только потом ищем документы*/
 
 begin
   i := 1;
   Result := '';
   bFind := '0';
   if (Adate is null) THEN
      ADateReq := sysdate;
   else
      ADateReq := ADate;
   end if;
   
   -- найдем период ОД последний до нашей даты
   select max(coalesce(mp.enddate,cast('31.12.2050' as date)))
     into ADateReq
     from sm.objects o
     join sm.moveitems mi on mi.object_id = o.id
     join sm.moveperiods mp on mp.id = mi.moveperiod_id
     join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
    where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
      and coalesce(mp.enddate,cast('31.12.2050' as date)) < ADateReq
      and mv.client_id = 5100
      and o.id = Aobject_id;
       
   -- выбираем данные по периоду операции движения(сначала идет основной)
   if (ADocrole_id = 1 or ADocrole_id is NULL) then
      for main_1 IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
                   and mp.sincedate <= ADateReq
                   and mp.enddate >= ADateReq
                   and o.id = Aobject_id
                   and dm.DOCROLE_ID = 1 --основной документ
                   and rownum <= 1
                   and mv.client_id = 5100
                   and (mv.id = Amovesets_id or Amovesets_id is null)
              order by mp.enddate DESC, d.docdate
                 )
       loop
          bFind := '1';
          Result:=Result || ' ' || to_char(i)||'. '||main_1.doc||chr(13);
          i:=i+1;
       end loop;
    end if;    
              
    -- выбираем данные по периоду операции движения(остальные по хронологии)
    for main_2 IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
                   and mp.sincedate <= ADateReq
                   and mp.enddate >= ADateReq
                   and o.id = Aobject_id
                   and NVL(dm.DOCROLE_ID,-1) >= NVL(ADocrole_id,-1)
                   and NVL(dm.DOCROLE_ID,-1) <= NVL(ADocrole_id,3000000000)
                   and NVL(dm.docrole_id,-1) <> 1 --все кроме основного
                   and mv.client_id = 5100
                   and (mv.id = Amovesets_id or Amovesets_id is null)
              order by mp.enddate DESC, d.docdate
                 )
    loop
       bFind := '1';
       Result:=Result || ' ' || to_char(i)||'. '||main_2.doc||chr(13);
       i:=i+1;
    end loop;
    -- если данные не нашли, то смотрим если есть родитель, то берем документы от него
    if (bFind = '0') then
        -- проверим есть ли родитель
        FOR exists_ in (
                        SELECT b2.*
                          FROM sm.BUILDINGS b1
                          JOIN sm.BUILDINGS b2 on b2.ID = b1.BASEBUILDING
                         where b1.OBJECTS_ID = Aobject_id

                       )
        loop
            -- если нашли, то смотрим документы рекурсивно вверх
            SELECT sm.REP_FULLDOCLIST_1 (exists_.objects_id,Amovetype_id,Aobjtypes_list,ADateReq,ADocrole_id, Amovesets_id) into Result
              from dual;
        end loop;
    end if;
  return(Result);
end REP_FULLDOCLIST_1;
/
grant execute on SM.REP_FULLDOCLIST_1 to SM_ALLUSERS;
grant execute on SM.REP_FULLDOCLIST_1 to SM_ALL_SELECT;


prompt
prompt Creating function REP_FULLDOCLIST_2
prompt ===================================
prompt
create or replace function sm.REP_FULLDOCLIST_2(Aobject_id in number, Amovetype_id  in NUMBER, Aobjtypes_list in varchar2, Adate in date,ADocrole_id IN number, Aclient_id in number default null, Amovesets_id in number default null) return varchar2 is
  Result varchar2(10000);
  bFind CHAR(1);
  ADateReq DATE;
  i NUMBER;
  /* 01.11.2011 Твердохлеб */
  -- функция возвращает список документов из пакета, включая главный + если есть родитель,
  -- то берет документы по Собственности и Балансосодержателю по родителю, главному.
  -- по текущим периодам
  /* 01/03/2016 Твердохлеб: добавил на вход client_id, так как одновременно может быть собственныик 5100 с долей и с другой долей другой клнент.
     и теперь ищем документы конкретного клиента
  */
  
 begin
   i := 1;
   Result := '';
   bFind := '0';
   if (Adate is null) THEN
      ADateReq := sysdate;
   else
      ADateReq := ADate;
   end if;
   -- выбираем данные по периоду операции движения(сначала идет основной)
   if (ADocrole_id = 1 or ADocrole_id is NULL) then
      for main_1 IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
                   and mp.sincedate<= ADateReq
                   and (mp.enddate>= ADateReq or mp.enddate IS NULL)
                   and o.id = Aobject_id
                   and dm.DOCROLE_ID = 1 --основной документ
                   and (mv.client_id = Aclient_id or Aclient_id is null)
                   and (mv.id = Amovesets_id or Amovesets_id is null)
              order by d.DOCDATE
                 )
       loop
          bFind := '1';
          Result:=Result || ' ' || to_char(i)||'. '||main_1.doc||chr(13);
          i:=i+1;
       end loop;
    end if;
    -- выбираем данные по периоду операции движения(остальные по хронологии)
    for main_2 IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
                   and mp.sincedate<= ADateReq
                   and (mp.enddate>= ADateReq or mp.enddate IS NULL)
                   and o.id = Aobject_id
                   and NVL(dm.DOCROLE_ID,-1) >= NVL(ADocrole_id,-1)
                   and NVL(dm.DOCROLE_ID,-1) <= NVL(ADocrole_id,3000000000)
                   and NVL(dm.docrole_id,-1) <> 1 --все кроме основного
                   and (mv.client_id = Aclient_id or Aclient_id is null)
                   and (mv.id = Amovesets_id or Amovesets_id is null)
              order by d.DOCDATE
                 )
    loop
       bFind := '1';
       Result:=Result || ' ' || to_char(i)||'. '||main_2.doc||chr(13);
       i:=i+1;
    end loop;
    -- если данные не нашли, то смотрим если есть родитель, то берем документы от него
    if (bFind = '0') then
        -- проверим есть ли родитель
        FOR exists_ in (
                        SELECT b2.*
                          FROM sm.BUILDINGS b1
                          JOIN sm.BUILDINGS b2 on b2.ID = b1.BASEBUILDING
                         where b1.OBJECTS_ID = Aobject_id

                       )
        loop
            -- если нашли, то смотрим документы рекурсивно вверх
            SELECT sm.REP_FULLDOCLIST_2 (exists_.objects_id,Amovetype_id,Aobjtypes_list,ADateReq,ADocrole_id, Aclient_id, Amovesets_id) into Result
              from dual;
        end loop;
    end if;
  return(Result);
end REP_FULLDOCLIST_2;
/
grant execute on SM.REP_FULLDOCLIST_2 to SM_ALLUSERS;
grant execute on SM.REP_FULLDOCLIST_2 to SM_ALL_SELECT;


prompt
prompt Creating function REP_FULLDOCLIST
prompt =================================
prompt
create or replace function sm.REP_FULLDOCLIST  (Aobject_id in number, Amovetype_id  in NUMBER, Aobjtypes_list in varchar2, Adate in date,ADocrole_id IN number, Aclient_id in number default NULL, Amovesets_id in number default null) return varchar2 is
  Result varchar2(10000);
  cnt number(27);
  ADateReq date;

  /* 01.11.2011 Твердохлеб */
  -- функция возвращает список документов из пакета, включая главный + если есть родитель,
  -- то берет документы по Собственности и Балансосодержателю по родителю, главному.
  /* 01/03/2016 Твердохлеб: добавил на вход client_id, так как одновременно может быть собственныик 5100 с долей и с другой долей другой клнент.
     и теперь ищем документы конкретного клиента
  */
    
 begin
   -- определим, если текущий собственник объекта является МО г.Краснодар
   -- то запускаем выборку по текущим периодам
   -- иначе это выбывшие объекты и мы работаем по предыдущим периодам
   cnt := 0;
   if (Adate is null) THEN
      ADateReq := sysdate;
   else
      ADateReq := ADate;
   end if;
   
   -- если у самого объекта собственности нет, то проверим у родителей
   -- идем по самому объекту и его родителям
   for xxx in (
             select Aobject_id as objects_id
               from dual
             union  
             select b.objects_id
               from sm.Buildings b
              start with b.objects_id = Aobject_id
              connect by prior  b.basebuilding  = b.id
             )
   loop   
     if (cnt = 0) then
       select count(*)
         into cnt
         from sm.objects o
         join sm.moveitems mi on mi.object_id = o.id
         join sm.moveperiods mp on mp.id = mi.moveperiod_id
         join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 1 -- собственность
        where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 -- ищем нужные типы объектов
          and mp.sincedate <= ADateReq
          and (mp.enddate >= ADateReq or mp.enddate IS NULL)
          and o.id = xxx.objects_id
          and mv.client_id = 5100; 
      end if;  
   end loop;

   
   if (cnt = 0) then
      select sm.rep_fulldoclist_1(Aobject_id, Amovetype_id, Aobjtypes_list, Adate, ADocrole_id, Amovesets_id)
        into Result
        from dual;
   end if;

   -- есть МО г. Краснодар
   if (cnt > 0) then
      select sm.rep_fulldoclist_2(Aobject_id, Amovetype_id, Aobjtypes_list, Adate, ADocrole_id, Aclient_id, Amovesets_id)
        into Result
        from dual;
   end if;
  return(Result);
end REP_FULLDOCLIST;
/
grant execute on SM.REP_FULLDOCLIST to SM_ALLUSERS;
grant execute on SM.REP_FULLDOCLIST to SM_ALL_SELECT;


prompt
prompt Creating function REP_EXTRACT_SHARE
prompt ===================================
prompt
create or replace function sm.REP_EXTRACT_SHARE (Aobject_id in number, Amovetype_id  in NUMBER, Aobjtypes_list in varchar2, Adate in date, isFullDoc in char, Aclient_id in number default NULL)
return type_extract_share_list pipelined as
  doc varchar2(10000);
  ADateReq date;
  ADateReq_loc date;  
  ADocrole_id number(27);     
 begin
   /* 30/03/2016 Твердохлеб: [390] - возвращает основные документы объекта, по долям*/
   /* 13/04/2016 Твердохлеб: [418] - учел поиск родителея, если нет собственности на самом объекте*/
   
   ADocrole_id := NULL;
   if (isFullDoc = '0')then
      ADocrole_id := 1;
   end if;

   if (Adate is null) THEN
      ADateReq := sysdate;
   else
      ADateReq := ADate;
   end if;
   
   select max(coalesce(mp.enddate, ADateReq))
     into ADateReq_loc
     from sm.objects o
     join sm.moveitems mi on mi.object_id = o.id
     join sm.moveperiods mp on mp.id = mi.moveperiod_id
     join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id --нужная ОД
    where INSTR(','||Aobjtypes_list||',',','||o.objtypes_id||',',1,1) <> 0 --ищем нужные типы объектов
      and coalesce(mp.enddate,ADateReq) <= ADateReq
      and mv.client_id = 5100
      and o.id = Aobject_id;
   
   -- если не нашли собственность на самом объекте,
   -- то посмотрим на родителе
   if (ADateReq_loc is null) then
        -- проверим есть ли родитель
        FOR exists_ in (
                        SELECT b2.*
                          FROM sm.BUILDINGS b1
                          JOIN sm.BUILDINGS b2 on b2.ID = b1.BASEBUILDING
                         where b1.OBJECTS_ID = Aobject_id

                       )
        loop            
          for xxx in (
                      select id_movesets,
                             share_num,
                             share_denom,
                             doc 
                        from TABLE (sm.REP_EXTRACT_SHARE (exists_.objects_id,Amovetype_id,Aobjtypes_list,ADateReq,isFullDoc, Aclient_id))
                     )
           loop               
             pipe row (type_extract_share(xxx.id_movesets, xxx.share_num, xxx.share_denom, xxx.doc));
           end loop;        
        end loop;
   else   
     ADateReq := ADateReq_loc;   
  
     for xxx in (select mv.id as Amovesets_id,
                        mi.share_num,
                        mi.share_denom
                   from sm.moveitems mi
                   join sm.moveperiods mp on mp.id = mi.moveperiod_id
                   join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = Amovetype_id
                  where mp.sincedate <= ADateReq
                    and (mp.enddate >= ADateReq or mp.enddate IS NULL)
                    and mi.object_id = Aobject_id
                    and mv.client_id = 5100
                  )
     loop  
       select sm.rep_fulldoclist(Aobject_id, Amovetype_id, Aobjtypes_list, Adate ,ADocrole_id, Aclient_id, xxx.Amovesets_id)
         into doc
         from dual;
       
       pipe row (type_extract_share(xxx.amovesets_id, xxx.share_num, xxx.share_denom, doc));
     end loop;  
   end if;  
   
   return; 
end REP_EXTRACT_SHARE;
/
grant execute on SM.REP_EXTRACT_SHARE to SM_ALLUSERS;


prompt
prompt Creating function REP_EXTRACT_BUILDINGS
prompt =======================================
prompt
create or replace function sm.rep_extract_buildings(Flag in char, Aobject_id in varchar2)
return /*number*/ sm.T_REP_EXTRACT_BUILDINGS_LIST3 pipelined as
reestr_doc varchar2(4000);
rightholder varchar2(4000);
rightholder_doc varchar2(4000);
fond_spetionsl_doc varchar2(4000);
calc_date_kadastr date;
calc_date_starpay date;
calc_date_costpay date;
costObjectKadastr varchar2(255);
costObjectStartPay varchar2(255);
costObjectCostPay varchar2(255);
begin
  /*10/12/2018 Твердохлеб формирует данные для выписки*/

 for xxx in (select
                      o.id obj,
                      sm.getusername username,
                      o.id reestr, --реестр
                      cast((case when (b.levelname = '' or b.levelname is null) then '' else b.levelname end) as varchar2(500)) descript, --описание
                      (case when (a.Addon is null or a.addon = '') then sm.ExpandAddr_as(o.address_id) else (sm.ExpandAddr_as(o.address_id) || ', '|| a.Addon)  end)ObjAddr , -- адрес
                      a.btiliter, --литера
                      b.kadastrno, --кадастровый номер
                      b.square square_,
                      cast(0 as numeric(10,2)) length_,
                      cast(0 as numeric(27,2)) depth_,
                      cast(0 as numeric(27,2)) volume_,
                      cast(0 as numeric(10,2)) width_,
                      cast((case when b.BASEBUILDING is null then cast(b.floorcount as varchar(100)) else b.floorcount_in end)as varchar2(100)) fl ,--этажность
                      b.enteryear enteryear, --год ввода в эксплуатацию
                      b.info, --доп информация
                      (cast(sm.getobjectcost2(o.id,sysdate,'B') as varchar2(20))) as costObject, --первоначальная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'R') as varchar2(20))) as costObjectRem, --остаточная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'K') as varchar2(20))) as costObjectKadastr, --кадастровая стоимость
                      bt."NAME" typeObj,
                      b.living_square, --жилая площадь
                      cast(NULL as numeric(27,2)) AreaConstr, --площадь застройки
                      cast(NULL as varchar2(255)) DegreRead,--степень застройки
                      bm.name material,
                      bt.id id_btType,
                      o.invno,
                      o.objtypes_id,
                      coalesce(o.EXISTS_END, TO_DATE('31.12.2050','DD.MM.YYYY')) EXISTS_END
                  from sm.objects o
                  join sm.buildings b on b.objects_id = o.id
                  JOIN SM.BUILDTYPES bt ON bt.ID = b.BUILDTYPES_ID
                  join sm.address a on a.id = o.address_id
                  left join sm.buildmaterials bm on bm.id = b.buildmaterial_id
                  where
                  o.objtypes_id = 3 --здание и помещения
                  and
                  INSTR(','||Aobject_id||',',','||to_char(o.id)||',',1,1) <> 0
                  union
                  select
                      o.id obj,
                      sm.getusername username,
                      o.id reestr, --реестр
                      u.name descript, --описание
                      (case when (a.Addon is null or a.addon = '') then sm.ExpandAddr_as(o.address_id) else (sm.ExpandAddr_as(o.address_id) || ', '|| a.Addon)  end)ObjAddr , -- адрес
                      a.btiliter, --литера
                      u.kadastrno, --кадастровый номер
                      u.square square_,
                      cast(0 as numeric(10,2)) length_,
                      cast(0 as numeric(27,2)) depth_,
                      cast(0 as numeric(27,2)) volume_,
                      cast(0 as numeric(10,2)) width_,
                      cast(0 as varchar2(100)) fl, --этажность
                      u.startyear enteryear, --год ввода в эксплуатацию
                      u.info, --доп информация
                      (cast(sm.getobjectcost2(o.id,sysdate,'B') as varchar2(20))) as costObject, --первоначальная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'R') as varchar2(20))) as costObjectRem, --остаточная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'K') as varchar2(20))) as costObjectKadastr, --кадастровая стоимость
                      '' typeObj,
                      cast(NULL as numeric(27,2)) living_square, --жилая площадь
                      u.AreaConstr,
                      u.DegreRead,
                      cast(NULL as varchar2(30)) material,
                      cast(NULL as numeric(27)) id_btType,
                      o.invno,
                      o.objtypes_id,
                      coalesce(o.EXISTS_END, TO_DATE('31.12.2050','DD.MM.YYYY')) EXISTS_END
                  from
                  sm.objects o
                  join sm.unconstr u on u.objects_id = o.id
                  join sm.address a on a.id = o.address_id
                  where
                  o.objtypes_id = 4 --Незавершенное строительство
                  and
                  INSTR(','||Aobject_id||',',','||to_char(o.id)||',',1,1) <> 0
                  union
                  select
                      o.id obj,
                      sm.getusername username,
                      o.id reestr, --реестр
                      e.name descript, --описание
                      (case when (a.Addon is null or a.addon = '') then sm.ExpandAddr_as(o.address_id) else (sm.ExpandAddr_as(o.address_id) || ', '|| a.Addon)  end)ObjAddr , -- адрес
                      a.btiliter, --литера
                      e.kadastrno, --кадастровый номер
                      e.square square_,
                      e.length length_,
                      e.depth depth_,
                      e.volume volume_,
                      e.width width_,
                      cast(0 as varchar2(100)) fl, --этажность
                      e.enteryear enteryear, --год ввода в эксплуатацию
                      e.material info, --доп информация
                      (cast(sm.getobjectcost2(o.id,sysdate,'B') as varchar2(20))) as costObject, --первоначальная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'R') as varchar2(20))) as costObjectRem, --остаточная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'K') as varchar2(20))) as costObjectKadastr, --кадастровая стоимость
                      et."NAME" typeObj,
                      cast(NULL as numeric(27,2)) living_square, --жилая площадь
                      cast(NULL as numeric(27,2)) AreaConstr,
                      cast(NULL as varchar2(255)) DegreRead,
                      cast(NULL as varchar2(30)) material,
                      cast(NULL as numeric(27)) id_btType,
                      o.invno,
                      o.objtypes_id,
                      coalesce(o.EXISTS_END, TO_DATE('31.12.2050','DD.MM.YYYY')) EXISTS_END
                  from
                  sm.objects o
                  join sm.enginf e on e.objects_id = o.id
                  JOIN SM.ENGINFTYPES et ON et.ID = e.ENGINFTYPES_ID
                  join sm.address a on a.id = o.address_id
                  where
                  o.objtypes_id = 5 --Инженерная инфраструктура
                  and
                  INSTR(','||Aobject_id||',',','||to_char(o.id)||',',1,1) <> 0
                )
   loop
     reestr_doc := '';     
     for y in (      
               select q.doc 
                 into reestr_doc
                 from TABLE (sm.rep_extract_share (xxx.obj,1,'3,4,5',NULL,1,5100))q
              )
     loop
        reestr_doc := reestr_doc || y.doc || chr(13);
     end loop;         
     
     -- первоначальная  
     begin
       select max(s.calcdate) DateCost
         into calc_date_starpay
         from sm.states s
        where s.objects_id = xxx.obj
          and s.startpay <> 0;
        
       exception
        when NO_DATA_FOUND then
        null; 
     end;
     
     costObjectStartPay := trim(to_char(xxx.costObject, '999999999999.99'));
     if (costObjectStartPay  = '.00') then       
       costObjectStartPay := '0.00';
     end if;
     if costObjectStartPay is null then       
       costObjectStartPay := '<Нет>';
     else
       if (calc_date_starpay is not null) then
         costObjectStartPay := costObjectStartPay || ' на дату ' ||  to_char(calc_date_starpay, 'DD.MM.YYYY');       
       end if;
     end if;
     
     -- остаточная стоимость  
     begin
       select DateCost
         into calc_date_costpay
         from 
             (
                select DateCost, row_number() over (order by order_num) as cnt
                  from (
                        select 
                             max(s.calcdate) DateCost, '1' order_num
                           from 
                             sm.states s
                           where s.objects_id = xxx.obj
                             and s.pay is not null
                        union 
                        select 
                             max(s.calcdate) DateCost, '2' order_num
                           from 
                             sm.states s
                           where s.objects_id = xxx.obj
                      )   
                     where DateCost is not null            
             )
           where cnt = 1;                     
       exception
        when NO_DATA_FOUND then
        null; 
     end;
     
     costObjectCostPay := trim(to_char(xxx.costObjectRem, '999999999999.99'));
     if (costObjectCostPay  = '.00') then       
       costObjectCostPay := '0.00';
     end if;
     if costObjectCostPay is null then       
       costObjectCostPay := '<Нет>';
     else
       if (calc_date_costpay is not null) then
         costObjectCostPay := costObjectCostPay || ' на дату ' ||  to_char(calc_date_costpay, 'DD.MM.YYYY');       
       end if;
     end if;
     
     -- кадастровая стоимость  
     begin
       select max(s.calcdate) DateCost
         into calc_date_kadastr
         from sm.states s
        where s.objects_id = xxx.obj
          and s.cadastralvalue  <> 0;
        
       exception
        when NO_DATA_FOUND then
        null; 
     end;
     
     costObjectKadastr := trim(to_char(xxx.costObjectKadastr, '999999999999.99'));
     if (costObjectKadastr  = '.00') then       
       costObjectKadastr := '0.00';
     end if;
     if costObjectKadastr is null then       
       costObjectKadastr := '<Нет>';
     else
       if (calc_date_kadastr is not null) then
         costObjectKadastr := costObjectKadastr || ' на дату ' ||  to_char(calc_date_kadastr, 'DD.MM.YYYY');    
       end if;
     end if;

     begin
        select fullname
          into rightholder
          from 
               (
                select
                      1 as order_num,
                      og.id, 
                      og.fullname 
                    from 
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 442 --МУ
                    where 
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE 
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)                                     
                    union
                    select
                      2 as order_num,
                      og.id, 
                      og.fullname 
                    from 
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 443 --МУП
                    where 
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE 
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)                        
                    union 
                    select
                    3 as order_num,
                    -1 id,
                    'казна муниципального образования город Краснодар' fullname 
                    from dual
                    order by order_num                 
               )
          where rownum < 2;
        
       exception
        when NO_DATA_FOUND then
        null; 
     end;
     
     rightholder_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,2,'3,4,5',NULL,NULL) doc
       into rightholder_doc
       from dual;
       
     fond_spetionsl_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,28,'3,4,5',NULL,NULL) doc
       into fond_spetionsl_doc
       from dual;  
      
     pipe row (T_REP_EXTRACT_BUILDINGS3(
                                        xxx.obj,
                                        xxx.username,
                                        xxx.descript,
                                        xxx.ObjAddr,
                                        xxx.btiliter,
                                        xxx.kadastrno,
                                        xxx.square_,
                                        xxx.enteryear,
                                        costObjectStartPay,
                                        costObjectCostPay,
                                        costObjectKadastr,
                                        xxx.typeObj,
                                        xxx.living_square,
                                        xxx.invno,
                                        xxx.objtypes_id,
                                        reestr_doc,
                                        rightholder, 
                                        rightholder_doc,
                                        xxx.info,
                                        fond_spetionsl_doc,
                                        xxx.AreaConstr,
                                        xxx.DegreRead,
                                        trim(to_char(xxx.length_, '999999999999.99')),
                                        trim(to_char(xxx.depth_, '999999999999.99')),
                                        trim(to_char(xxx.volume_, '999999999999.99')),
                                        trim(to_char(xxx.width_, '999999999999.99')),
                                        xxx.fl,
                                        xxx.material,
                                        TO_CHAR(xxx.exists_end,'DD.MM.YYYY')
                                      ));
   end loop;
end rep_extract_buildings;
/
grant execute on SM.REP_EXTRACT_BUILDINGS to SM_ALLUSERS;


prompt
prompt Creating function REP_EXTRACT_PROPERTY
prompt ======================================
prompt
create or replace function sm.rep_extract_property(Flag in char, Aobject_id in varchar2)
return /*number*/ sm.T_REP_EXTRACT_PROPLIST pipelined as
descript varchar2(4000);
reestr_doc varchar2(4000);
rightholder varchar2(4000);
rightholder_doc varchar2(4000);
fond_spetionsl_doc varchar2(4000);
calc_date_starpay date;
calc_date_costpay date;
costObjectStartPay varchar2(255);
costObjectCostPay varchar2(255);
begin
  /*18/12/2018 Чувыкин - формирует данные для выписки в АИС по прочему движимому*/

 for xxx in (select
                      o.id obj,
                      sm.getusername username,
                      o.id reestr, --реестр
                      p.propnames_id, -- наименование
                      p.info, -- дополнительная информация
                      o.invno, -- инвентарный номер
                      p.serialnum, -- заводской номер
                      p.dateissue, -- год выпуска
                      p.dateinput, -- дата ввода в эксплуатацию                                            
                      (cast(sm.getobjectcost2(o.id,sysdate,'B') as varchar2(20))) as costObject, --первоначальная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'R') as varchar2(20))) as costObjectRem, --остаточная стоимость
                      coalesce(o.EXISTS_END, TO_DATE('31.12.2050','DD.MM.YYYY')) EXISTS_END
                  from sm.objects o
                  join sm.property p on p.objects_id = o.id
                  join sm.propnames pn on pn.id = p.propnames_id
                  where
                  o.objtypes_id = 1 --прочее движимое
                  and
                  INSTR(','||Aobject_id||',',','||to_char(o.id)||',',1,1) <> 0

                )
   loop
     -- описание объекта
    select sm.rep_object_description('1',xxx.obj)
      into descript
      from dual;

     -- документ-основание включения в реестр
     reestr_doc := '';
     for y in (
               select q.doc
                 into reestr_doc
                 from TABLE (sm.rep_extract_share (xxx.obj,1,'1',NULL,1,5100))q
              )
     loop
        reestr_doc := reestr_doc || y.doc || chr(13);
     end loop;

     -- первоначальная (балансовая)
     begin
       select max(s.calcdate) DateCost
         into calc_date_starpay
         from sm.states s
        where s.objects_id = xxx.obj
          and s.startpay <> 0;

       exception
        when NO_DATA_FOUND then
        null;
     end;

     
     costObjectStartPay := trim(to_char(xxx.costobject, '999999999999.99'));
     if (costObjectStartPay  = '.00') then       
       costObjectStartPay := '0.00';
     end if;
     if costObjectStartPay is null then
       costObjectStartPay := '<Нет>';
     else
       if (calc_date_starpay is not null) then
         costObjectStartPay := costObjectStartPay || ' на дату ' ||  to_char(calc_date_starpay, 'DD.MM.YYYY');
       end if;
     end if;

     -- остаточная стоимость
     begin
       select DateCost
         into calc_date_costpay
         from
             (
                select DateCost, row_number() over (order by order_num) as cnt
                  from (
                        select
                             max(s.calcdate) DateCost, '1' order_num
                           from
                             sm.states s
                           where s.objects_id = xxx.obj
                             and s.pay is not null
                        union
                        select
                             max(s.calcdate) DateCost, '2' order_num
                           from
                             sm.states s
                           where s.objects_id = xxx.obj
                      )
                     where DateCost is not null
             )
           where cnt = 1;
       exception
        when NO_DATA_FOUND then
        null;
     end;

     costObjectCostPay := trim(to_char(xxx.costObjectRem, '999999999999.99'));
     if (costObjectCostPay  = '.00') then       
       costObjectCostPay := '0.00';
     end if;
     if costObjectCostPay is null then
       costObjectCostPay := '<Нет>';
     else
       if (calc_date_costpay is not null) then
         costObjectCostPay := costObjectCostPay || ' на дату ' ||  to_char(calc_date_costpay, 'DD.MM.YYYY');
       end if;
     end if;

     -- определение правообладателя
     begin
        select fullname
          into rightholder
          from
               (
                select
                      1 as order_num,
                      og.id,
                      og.fullname
                    from
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 442 --МУ
                    where
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)
                    union
                    select
                      2 as order_num,
                      og.id,
                      og.fullname
                    from
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 443 --МУП
                    where
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)
                    union
                    select
                    3 as order_num,
                    -1 id,
                    'казна муниципального образования город Краснодар' fullname
                    from dual
                    order by order_num
               )
          where rownum < 2;

       exception
        when NO_DATA_FOUND then
        null;
     end;

     -- документы-основания возниконовения права
     rightholder_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,2,'1',NULL,NULL) doc
       into rightholder_doc
       from dual;

     -- основание включения в перечень ОЦДИ
     fond_spetionsl_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,28,'1',NULL,NULL) doc
       into fond_spetionsl_doc
       from dual;

     pipe row (t_rep_extract_property(

                                        xxx.obj,
                                        xxx.username,
                                        descript,
                                        xxx.info,
                                        xxx.invno,
                                        xxx.serialnum,
                                        xxx.dateissue,
                                        xxx.dateinput,
                                        costObjectStartPay,
                                        costObjectCostPay,
                                        reestr_doc,
                                        rightholder,
                                        rightholder_doc,
                                        fond_spetionsl_doc
                                      ));
   end loop;
end rep_extract_property;
/

prompt
prompt Creating function REP_EXTRACT_TRANSPORT
prompt =======================================
prompt
create or replace function sm.rep_extract_transport(Flag in char, Aobject_id in varchar2)
return /*number*/ sm.T_REP_EXTRACT_TRANSPORTLIST pipelined as
descript varchar2(4000);
reestr_doc varchar2(4000);
rightholder varchar2(4000);
rightholder_doc varchar2(4000);
fond_spetionsl_doc varchar2(4000);
calc_date_starpay date;
calc_date_costpay date;
costObjectStartPay varchar2(255);
costObjectCostPay varchar2(255);
begin
  /*17/12/2018 Чувыкин - формирует данные для выписки в АИС по транспорту*/

 for xxx in (select
                      o.id obj,
                      sm.getusername username,
                      o.id reestr, --реестр
                      o.invno, -- инвентарный номер 
                      t.motorno, -- номер двигателя
                      t.chassisno, -- номер шасси
                      t.bodyno, -- номер кузова
                      t.ps_vin as vin, -- VIN
                      t.fedno, -- госномер
                      t.relyear, -- год выпуска
                      (cast(sm.getobjectcost2(o.id,sysdate,'B') as varchar2(20))) as costObject, --первоначальная стоимость
                      (cast(sm.getobjectcost2(o.id,sysdate,'R') as varchar2(20))) as costObjectRem, --остаточная стоимость
                      coalesce(o.EXISTS_END, TO_DATE('31.12.2050','DD.MM.YYYY')) EXISTS_END
                  from sm.objects o
                  join sm.transport t on t.objects_id = o.id
                  where
                  o.objtypes_id = 2 --транспорт
                  and
                  INSTR(','||Aobject_id||',',','||to_char(o.id)||',',1,1) <> 0
               
                )
   loop
     -- описание объекта
     select tt.name || ' ' || bn.name ||' ' || tr.model 
     into descript
     from transport tr
     join brandnames bn on tr.brandnames_id = bn.id
     join transptype tt on tr.transptype_id = tt.id
     where tr.objects_id = xxx.obj;
    
    /*select sm.rep_object_description('1',xxx.obj)
      into descript
      from dual;*/

     -- документ-основание включения в реестр
     reestr_doc := '';
     for y in (
               select q.doc
                 into reestr_doc
                 from TABLE (sm.rep_extract_share (xxx.obj,1,'2',NULL,1,5100))q
              )
     loop
        reestr_doc := reestr_doc || y.doc || chr(13);
     end loop;

     -- первоначальная (балансовая)
     begin
       select max(s.calcdate) DateCost
         into calc_date_starpay
         from sm.states s
        where s.objects_id = xxx.obj
          and s.startpay <> 0;

       exception
        when NO_DATA_FOUND then
        null;
     end;

     costObjectStartPay := trim(to_char(xxx.costObject, '999999999999.99'));
     if (costObjectStartPay  = '.00') then       
       costObjectStartPay := '0.00';
     end if;
     if costObjectStartPay is null then
       costObjectStartPay := '<Нет>';
     else
       if (calc_date_starpay is not null) then
         costObjectStartPay := costObjectStartPay || ' на дату ' ||  to_char(calc_date_starpay, 'DD.MM.YYYY');
       end if;
     end if;

     -- остаточная стоимость
     begin
       select DateCost
         into calc_date_costpay
         from
             (
                select DateCost, row_number() over (order by order_num) as cnt
                  from (
                        select
                             max(s.calcdate) DateCost, '1' order_num
                           from
                             sm.states s
                           where s.objects_id = xxx.obj
                             and s.pay is not null
                        union
                        select
                             max(s.calcdate) DateCost, '2' order_num
                           from
                             sm.states s
                           where s.objects_id = xxx.obj
                      )
                     where DateCost is not null
             )
           where cnt = 1;
       exception
        when NO_DATA_FOUND then
        null;
     end;

     costObjectCostPay := trim(to_char(xxx.costObjectRem, '999999999999.99'));
     if (costObjectCostPay  = '.00') then       
       costObjectCostPay := '0.00';
     end if;
     if costObjectCostPay is null then
       costObjectCostPay := '<Нет>';
     else
       if (calc_date_costpay is not null) then
         costObjectCostPay := costObjectCostPay || ' на дату ' ||  to_char(calc_date_costpay, 'DD.MM.YYYY');
       end if;
     end if;

     -- определение правообладателя
     begin
        select fullname
          into rightholder
          from
               (
                select
                      1 as order_num,
                      og.id,
                      og.fullname
                    from
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 442 --МУ
                    where
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)
                    union
                    select
                      2 as order_num,
                      og.id,
                      og.fullname
                    from
                    sm.objects o
                    join sm.moveitems mi on mi.object_id = o.id
                    join sm.moveperiods mp on mp.id = mi.moveperiod_id
                    join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 2 --балансосодержатель
                    join sm.clients c on c.id = mv.client_id
                    join sm.organisations og on og.clients_id = c.id --and og.orgform = 443 --МУП
                    where
                    o.id = xxx.obj
                    and
                    mp.sincedate<=SYSDATE
                    and
                    (mp.enddate>=SYSDATE or mp.enddate IS NULL)
                    union
                    select
                    3 as order_num,
                    -1 id,
                    'казна муниципального образования город Краснодар' fullname
                    from dual
                    order by order_num
               )
          where rownum < 2;

       exception
        when NO_DATA_FOUND then
        null;
     end;

     -- документы-основания возниконовения права
     rightholder_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,2,'2',NULL,NULL) doc
       into rightholder_doc
       from dual;
       
     -- основание включения в перечень ОЦДИ  
     fond_spetionsl_doc := '';
     Select sm.Rep_fulldoclist (xxx.obj,28,'2',NULL,NULL) doc
       into fond_spetionsl_doc
       from dual;

     pipe row (t_rep_extract_transport(
     
                                        xxx.obj,
                                        xxx.username,
                                        descript,
                                        xxx.invno,
                                        xxx.motorno,
                                        xxx.chassisno,
                                        xxx.bodyno,
                                        xxx.vin,
                                        xxx.fedno,
                                        xxx.relyear,
                                        costObjectStartPay,
                                        costObjectCostPay,
                                        reestr_doc,
                                        rightholder,
                                        rightholder_doc,
                                        fond_spetionsl_doc
                                      ));
   end loop;
end rep_extract_transport;
/

prompt
prompt Creating function REP_FAIRVALUE
prompt ===============================
prompt
create or replace function sm.Rep_FairValue(AData date) return TYPE_REP_LOSTPROFIT_LIST pipelined as
 Id number(27);
 DBP number(27,2);
 AmountByDate number(27,2);
 Coeff varchar2(1000);
 Remaining_months integer;
 Remaining_days integer;
 EndDayOfControlMonth integer;
 PeriodEndDate date;
 ObjectsList1 varchar2(8000);
 ObjectsList2 varchar2(8000);
 ObjectsList3 varchar2(8000);

begin
/*20122024 - Чувыкин В.Э. - отчет "Упущенная выгода от справедливой стоимости" за Безвозмездное пользование*/

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям
SELECT
t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование Пользователя
, t2.inn ArInn-- ИНН Пользователя
, sm.GetArendatorCategory(t2.id) ArCat --Категория Пользователя
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД БП
, t4.docdate DocDate -- дата договора БП
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора БП
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора БП
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор БП
from
SM.MOVETYPE t1
, SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
(t8.MoveType_ID=t1.ID)
 and (t2.ID=t8.Client_ID)
 and (t8.transferbasis_id=t3.ID)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT 
 MoveSets.ID
FROM 
 sm.MoveSets
WHERE 
 MOVESETS.FIND_DUBLICATE = 'N' and
 MOVESETS.MOVETYPE_ID IN (22) and
 (sm.GetMoveSetEndDate(MoveSets.ID) >= AData or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL) and
 (sm.GetMoveSetSinceDate(MoveSets.ID) <= AData)

))
order by Arname
-- конец запроса
)

loop
   if xxx.docenddate < AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, add_months(AData,36), 81);
         DBP :=0;
   end if;

   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   if xxx.docenddate >= AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 81);
   DBP:= CALC_LOST_PROFITS(xxx.ms_id, Adata, xxx.docstartdate, xxx.docenddate);
   --dbp:=888;
   end if;
   
   Coeff := CALC_LOST_PROFITS_COEFF(xxx.ms_id, Adata, xxx.docstartdate);
   PeriodEndDate:=sm.GetMoveSetEndDate(xxx.ms_id);

   --AmountByDate := null;--sm.GetMoveAmountByDate(xxx.ms_id,81,Adata);
   AmountByDate:=CALC_LOST_PROFITS_BY_MONTH(xxx.ms_id, AData, xxx.docstartdate);

   Remaining_months := trunc(MONTHS_BETWEEN(xxx.docenddate, AData));
   --Remaining_days := to_date(xxx.docenddate) - to_date(AData);
   EndDayOfControlMonth := extract(day from AData);
   --select extract(day from date AData) into EndDayOfPrevLastMonth from dual;
   if EndDayOfControlMonth = 30
     then
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 2;
     else
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 1;
   end if;

   /*ObjectsList1:=GETOBJECTSFEATURESFROMMS(1,xxx.ms_id);
   ObjectsList2:=GETOBJECTSFEATURESFROMMS(2,xxx.ms_id);
   ObjectsList3:=GETOBJECTSFEATURESFROMMS(3,xxx.ms_id);*/

   pipe row (TYPE_REP_LOSTPROFIT(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.arcat,
                           xxx.ArDoc,
                           xxx.docdate,
                           xxx.docstartdate,
                           xxx.docenddate,
                           PeriodEndDate,
                           Coeff,
                           AmountByDate,
                           Remaining_months,
                           Remaining_days,
                           DBP,
                           '',
                           '',
                           ''
                           /*ObjectsList1,
                           ObjectsList2,
                           ObjectsList3*/
                           )
             );

    id := id + 1;
 end loop;

  return;

end REP_FairValue;
/
grant execute on SM.REP_FAIRVALUE to SM_ALLUSERS;


prompt
prompt Creating function REP_FAIRVALUEXE
prompt =================================
prompt
create or replace function sm.Rep_FairValueXE(AData date) return TYPE_REP_LOSTPROFIT_LIST pipelined as
 Id number(27);
 DBP number(27,2);
 AmountByDate number(27,2);
 Coeff varchar2(1000);
 Remaining_months integer;
 Remaining_days integer;
 EndDayOfControlMonth integer;
 PeriodEndDate date;
 ObjectsList1 varchar2(8000);
 ObjectsList2 varchar2(8000);
 ObjectsListSq varchar2(8000);

begin
/*20122024 - Чувыкин В.Э. - отчет "Упущенная выгода от справедливой стоимости" за Безвозмездное пользование*/

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям
SELECT
t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование Пользователя
, t2.inn ArInn-- ИНН Пользователя
, sm.GetArendatorCategory(t2.id) ArCat --Категория Пользователя
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД БП
, t4.docdate DocDate -- дата договора БП
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора БП
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора БП
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор БП
from
SM.MOVETYPE t1
, SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
(t8.MoveType_ID=t1.ID)
 and (t2.ID=t8.Client_ID)
 and (t8.transferbasis_id=t3.ID)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
 MoveSets.ID
FROM
 sm.MoveSets
WHERE
 MOVESETS.FIND_DUBLICATE = 'N' and
 MOVESETS.MOVETYPE_ID IN (22) and
 (sm.GetMoveSetEndDate(MoveSets.ID) >= AData or sm.GetMoveSetEndDate(MoveSets.ID) IS NULL) and
 (sm.GetMoveSetSinceDate(MoveSets.ID) <= AData)

))
order by Arname
-- конец запроса
)

loop

   if xxx.docenddate < AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, add_months(AData,36), 81);
         DBP :=0;
   end if;

   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   if xxx.docenddate >= AData then
   --DBP := CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 81);
   DBP:= CALC_LOST_PROFITS(xxx.ms_id, Adata, xxx.docstartdate, xxx.docenddate);
   --dbp:=888;
   end if;

   Coeff := CALC_LOST_PROFITS_COEFF(xxx.ms_id, Adata, xxx.docstartdate);
   PeriodEndDate:=sm.GetMoveSetEndDate(xxx.ms_id);

   --AmountByDate := null;--sm.GetMoveAmountByDate(xxx.ms_id,81,Adata);
   AmountByDate:=CALC_LOST_PROFITS_BY_MONTH(xxx.ms_id, AData, xxx.docstartdate);

   Remaining_months := trunc(MONTHS_BETWEEN(xxx.docenddate, AData));
   --Remaining_days := to_date(xxx.docenddate) - to_date(AData);
   EndDayOfControlMonth := extract(day from AData);
   --select extract(day from date AData) into EndDayOfPrevLastMonth from dual;
   if EndDayOfControlMonth = 30
     then
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 2;
     else
   Remaining_days := to_date(xxx.docenddate) - add_months(AData,floor(MONTHS_BETWEEN(xxx.docenddate,AData))) + 1;
   end if;

   ObjectsList1:=GETOBJECTSFEATURESFROMMS(1,xxx.ms_id);
   ObjectsList2:=GETOBJECTSFEATURESFROMMS(2,xxx.ms_id);
   ObjectsListSq:=GETOBJECTSFEATURESFROMMS(3,xxx.ms_id);

   pipe row (TYPE_REP_LOSTPROFIT(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.arcat,
                           xxx.ArDoc,
                           xxx.docdate,
                           xxx.docstartdate,
                           xxx.docenddate,
                           PeriodEndDate,
                           Coeff,
                           AmountByDate,
                           Remaining_months,
                           Remaining_days,
                           DBP,
                           ObjectsList1,
                           ObjectsList2,
                           ObjectsListSq
                           )
             );

    id := id + 1;
 end loop;

  return;

end REP_FairValueXE;
/
grant execute on SM.REP_FAIRVALUEXE to SM_ALLUSERS;


prompt
prompt Creating function REP_HISTORY
prompt =============================
prompt
create or replace function sm.Rep_History(D1 Date, D2 Date) return T_HISTTYPE_L pipelined as
 Id number(27);
 Object_Id number(27);
 column_name varchar2(30);
 action varchar2(16);
 old_value varchar2(512);
 new_value varchar2(2048);

begin
/*130721 - Чувыкин В.Э. - отчет по изменениям, произведенным пользователями*/
/*181024 - Чувыкин В.Э. - в отчет добавлены изменения по длине инж.инфр-ры*/

id:=1;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям
   select *
   from sm_v_changes svc
   where svc.change_date between D1 and D2
   and svc.column_name in ('SQUARE','KADASTRNO','ADDRESS_ID','OFFICIAL_ADDR','DESCRIPTION','LENGTH')
   order by svc.username asc, svc.change_date--, svc.column_name
-- конец запроса
)

loop

-- определяем текущее значение реквизита, претерпевшего изменения, а также реестровый номер объекта, на котором произошли изменения

-- площадь
   if xxx.table_name = 'BUILDINGS' and xxx.column_name = 'SQUARE' 
     then 
       begin
       select b.square 
       into new_value
       from BUILDINGS b where b.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select b.objects_id 
       into Object_Id
       from BUILDINGS b where b.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;
   if xxx.table_name = 'ENGINF' and xxx.column_name = 'SQUARE' 
     then 
       begin
       select e.square 
       into new_value
       from ENGINF e where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select e.objects_id 
       into Object_Id
       from ENGINF e where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;
   if xxx.table_name = 'GROUNDS' and xxx.column_name = 'SQUARE' 
     then
       begin
       select g.square 
       into new_value
       from GROUNDS g 
       where g.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select g.objects_id 
       into Object_Id
       from GROUNDS g where g.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
 
   end if;
   if xxx.table_name = 'UNCONSTR' and xxx.column_name = 'SQUARE' 
     then 
       begin
       select u.square
       into new_value 
       from UNCONSTR u 
       where u.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select u.objects_id 
       into Object_Id
       from UNCONSTR u where u.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;

-- длина для инженерки
   if xxx.table_name = 'ENGINF' and xxx.column_name = 'LENGTH' 
     then 
       begin
       select e.length 
       into new_value
       from ENGINF e where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select e.objects_id 
       into Object_Id
       from ENGINF e where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;

--кадастровый номер
   if xxx.table_name = 'OBJECTS' and xxx.column_name = 'KADASTRNO' 
     then 
       begin
       select o.kadastrno 
       into new_value
       from OBJECTS o where o.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select o.id 
       into Object_Id
       from OBJECTS o where o.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;
   if xxx.table_name = 'BUILDINGS' and xxx.column_name = 'KADASTRNO' 
     then 
       begin
       select b.KADASTRNO 
       into new_value
       from BUILDINGS b where b.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select b.objects_id 
       into Object_Id
       from BUILDINGS b where b.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       
   end if;
   if xxx.table_name = 'ENGINF' and xxx.column_name = 'KADASTRNO' 
     then 
       begin
       select e.KADASTRNO 
       into new_value
       from ENGINF e 
       where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
       begin
       select e.objects_id 
       into Object_Id
       from ENGINF e where e.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;
   if xxx.table_name = 'GROUNDS' and xxx.column_name = 'KADASTRNO' 
     then
       begin
       select g.KADASTRNO 
       into new_value
       from GROUNDS g 
       where g.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;

       end;
       begin
       select g.objects_id 
       into Object_Id
       from GROUNDS g where g.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
 
   end if;
   if xxx.table_name = 'UNCONSTR' and xxx.column_name = 'KADASTRNO' 
     then 
       begin
       select u.kadastrno
       into new_value 
       from UNCONSTR u 
       where u.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
        end;
       begin
       select u.objects_id 
       into Object_Id
       from UNCONSTR u where u.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;

   end if;

--адрес
   if xxx.table_name = 'OBJECTS' and xxx.column_name = 'ADDRESS_ID' 
     then 
       begin
       select expandaddr(o.address_id)
       into new_value
       from objects o where o.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
   end if;

--официальный адрес
   if xxx.table_name = 'OBJECTS' and xxx.column_name = 'OFFICIAL_ADDR' 
     then 
       begin
       select o.official_addr 
       into new_value
       from objects o where o.id = xxx.id_value;
              exception
              when NO_DATA_FOUND then null;
       end;
   end if;

--описание\наименование    
   if xxx.table_name = 'OBJECTS' and xxx.column_name = 'DESCRIPTION' 
     then 
       begin
       select o.description 
       into new_value
       from objects o where o.id = xxx.id_value;
       exception
              when NO_DATA_FOUND then null;
       end;
   end if;

-- именуем реквизиты, претерпевшие изменения
   if xxx.column_name = 'SQUARE' then column_name := 'ПЛОЩАДЬ'; end if;
   if xxx.column_name = 'KADASTRNO' then column_name := 'КАДАСТРОВЫЙ НОМЕР'; end if;
   if xxx.column_name = 'ADDRESS_ID' then column_name := 'АДРЕС'; end if;
   if xxx.column_name = 'OFFICIAL_ADDR' then column_name := 'ОФИЦ.АДРЕС'; end if;
   if xxx.column_name = 'DESCRIPTION' then column_name := 'ОПИСАНИЕ\НАИМЕНОВАНИЕ'; end if;
   if xxx.column_name = 'LENGTH' then column_name := 'ДЛИНА'; end if;

-- вычисляем фазу действия
   if xxx.action = 'U' then action := 'Изменение'; end if;  
   if xxx.action = 'I' then action := 'Вставка'; end if;  
   if xxx.action = 'D' then action := 'Удаление'; end if;  

-- вычисление старого значение
   old_value := NULL;
   if xxx.old_value_num is not null then old_value := xxx.old_value_num;
     end if;
   if xxx.old_value_str is not null then old_value := xxx.old_value_str;
     end if;
   if xxx.old_value_date is not null then old_value := xxx.old_value_date;
     end if;
   
   pipe row (T_HISTTYPE(
                       id,
                       Object_Id,--id объекта
                       xxx.table_name,
                       column_name,
                       action,
                       old_value,
                       new_value,
                       xxx.change_doc,
                       xxx.expanddoc, --документ-основание изменений
                       xxx.fullname, --автор изменений
                       xxx.change_date --дата изменений
                       )
             );

    id := id + 1;
 end loop;

  return;

end Rep_History;
/
grant execute on SM.REP_HISTORY to SM_ALLUSERS;


prompt
prompt Creating function REP_ORGANISATION_DATA
prompt =======================================
prompt
create or replace function sm.Rep_organisation_data(Flag varchar2, AObject_id number, Adate date, FBasisIn varchar2, FBasisOut varchar2)
return TypeOrganisationDataList pipelined as
 Ogrn_date_reg varchar2(255);--ОГРН, дата государственной регистрации
 Inn varchar2(12); -- ИНН
 Count_share varchar2(255); --Количество акций
 Nom_cost_share varchar2(255); --Номинальная стоимость акции  (руб.)
 Nom_cost_share_shares_ms varchar2(255); --Номинальная стоимость доли муниципальной собственности в уставном капитале (руб.)
 Share_shares_ms varchar2(255); --Доля муниципальной собственности в уставном капитале (%)
 Authorized_capital varchar2(255); --уставной капитал
 Statutory_capital varchar2(255); --уставной фонд
 Initial_cost varchar2(255); -- Первоначальная стоимость основных средств
 Residual_cost varchar2(255); -- Остаточная стоимость основных средств
 Average_list varchar2(255); -- Среднесписочная численность
 Address_obj varchar2(2000); -- адрес
 Documents_basis_in varchar2(5000); -- Документы-основания включения в Реестр 
 Documents_basis_out varchar2(5000); -- Документы-основания исключения из Реестра
 ADateReq date;
 AClient_id number(27);
 Aorganisations_id number(27);
 hasauthorizedfund char(1);
 regdoc_id number(27);
 i number(27);
 DateCost date;
 hasauthcapital char(1);
 objects_id number(27);
 is_jsc char(1);
begin
  /* 04/04/2014 Твердохлеб: Возвращает данные для отчета Выписка субъекты*/

  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  -- получим
  -- Полное наименование хозяйственного общества или товарищества
  select coalesce(og.ogrn,'') || ', ' || to_char(c.exists_since,'DD.MM.YYYY'),
         sm.expandaddr_as(c.address_id),
         c.id,
         og.id,
         og.inn,
         f.hasauthorizedfund,
         c.regdoc_id,
         f.hasauthcapital,
         f.is_jsc
    into Ogrn_date_reg,
         Address_obj,
         AClient_id,
         Aorganisations_id,
         Inn,
         hasauthorizedfund,
         regdoc_id,
         hasauthcapital,
         is_jsc
    from sm.organisations og
    join sm.clients c on c.id = og.clients_id
    join sm.orgforms f on f.id = og.orgform
   where og.objects_id = AObject_id;


  -- получим уставной капитал
  begin
    select sm.get_authorized_capital(NULL, AClient_id, NULL)
      into Authorized_capital
      from dual;  
    exception
    when NO_DATA_FOUND then
    null;
  end;
  
  if (hasauthorizedfund = 'Y') then
    Statutory_capital := Authorized_capital;
    Authorized_capital := 0;
  end if;
  
  -- получим долю Базового собственника
  select sm.orgstate_and_share_pkg.GetMunicipalShare(Aorganisations_id,ADateReq,'N',NULL),
         sm.orgstate_and_share_pkg.GetMunicipalShare(Aorganisations_id,ADateReq,'P',NULL),
         sm.orgstate_and_share_pkg.GetMunicipalShare(Aorganisations_id,ADateReq,'C',NULL)
    into Count_share,
         Share_shares_ms,
         Nom_cost_share_shares_ms
    from dual;
 
 -- если ООО
 if (hasauthcapital = 'Y' and is_jsc = 'N') then
    -- найдем объект пакеты акций и для него введенное значение
    select s.objects_id
      into objects_id
      from sm.objshares s
      join sm.opershares o on o.id = s.opershares_id
     where s.organisations_id = Aorganisations_id
       and o.opertype_id IN (3) 
       and rownum <= 1
       and o.operdate <=ADateReq 
     order by o.operdate desc;
     
     select sm.OrgState_And_Share_PKG.GetObjSharesStateValue(objects_id,ADateReq,'P')
       into Share_shares_ms
       from dual;
 end if;
    
 select to_char(sm.getobjectcost2(AObject_id,ADateReq,'B'), '9999999999.99'), --первоначальная стоимость
        to_char(sm.getobjectcost2(AObject_id,ADateReq,'R'), '9999999999.99') --остаточная стоимость 
   into Initial_cost,
        Residual_cost      
   from dual;       
   
 select max(s.calcdate)
   into DateCost
   from sm.states s
  where s.objects_id = AObject_id
    and s.calcdate <= ADateReq;
  
  if (Initial_cost is not null and Initial_cost <> '0') then
     Initial_cost := Initial_cost || ' на ' || to_char(DateCost, 'DD.MM.YYYY');
  end if;
  if (Residual_cost is not null and Residual_cost <> '0') then   
     Residual_cost := Residual_cost || ' на ' || to_char(DateCost, 'DD.MM.YYYY');
  end if;
 
  select sm.orgstate_and_share_pkg.GetOrgStateValue(Aorganisations_id,ADateReq,'W')
    into Average_list 
    from dual;  
 
  if (Average_list is not null and Average_list <> 0) then
     Average_list := Average_list || ' на ' || to_char(DateCost, 'DD.MM.YYYY');
  end if;
         
  Documents_basis_in := '';       
  Documents_basis_out := '';
  
  i:= 1;
  -- если Документы-основания включения в Реестр показать только главный документ
  if (FBasisIn = '1') then
     /*  for docs in (
                    select sm.expanddoc(m.document_id) doc
                      from sm.docsets d
                      join sm.docset_members m on m.docset_id = d.id
                      join sm.documents dc on dc.id = m.document_id
                     where d.id = regdoc_id 
                       and m.docrole_id = 1
                  order by dc.docdate     
                   )
       loop
            Documents_basis_in := to_char(i) || '.' || docs.doc || chr(13);    
            i := i + 1;     
       end loop;*/
       select sm.rep_fulldoclist(AObject_id,1,'6',ADateReq,'1')
         into Documents_basis_in
         from dual;             
  end if;
  -- если Документы-основания включения в Реестр показать все документы
  if (FBasisIn = '2') then
    /* for docs in (
                  select sm.expanddoc(m.document_id) doc
                    from sm.docsets d
                    join sm.docset_members m on m.docset_id = d.id
                    join sm.documents dc on dc.id = m.document_id
                   where d.id = regdoc_id 
                order by m.docrole_id, dc.docdate     
                 )
     loop
          Documents_basis_in := Documents_basis_in || to_char(i) || '.' || docs.doc || chr(13);    
          i := i + 1;     
     end loop; 
     */ 
       select sm.rep_fulldoclist(AObject_id,1,'6',ADateReq,NULL)
         into Documents_basis_in
         from dual;      
  end if;
  
  i := 1;
  -- если Документы-основания исключения из Реестра показать только главный документ
  if (FBasisOut = '1') then 
     for docs IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 19 --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where o.objtypes_id = 6
                   and mp.sincedate<= ADateReq
                   and (mp.enddate>= ADateReq or mp.enddate IS NULL)
                   and o.id = Aobject_id
                   and dm.DOCROLE_ID = 1
                   and rownum <= 1
              order by d.docdate
                 )
    loop
       Documents_basis_out := Documents_basis_out || to_char(i) || '. ' || docs.doc || chr(13);    
       i:=i+1;
    end loop;           
  end if;
  -- если Документы-основания исключения из Реестра показать все документы
  if (FBasisOut = '2') then
     for docs IN (
                select sm.expanddoc(dm.document_id) doc
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets mv on mv.id = mp.moveset_id and mv.movetype_id = 19 --нужная ОД
                  join sm.docset_members dm on dm.docset_id = mp.docset_id
                  join sm.documents d on d.id = dm.document_id
                 where o.objtypes_id = 6
                   and mp.sincedate<= ADateReq
                   and (mp.enddate>= ADateReq or mp.enddate IS NULL)
                   and o.id = Aobject_id
                   --and rownum <= 1
              order by dm.docrole_id, d.docdate
                 )
    loop
       Documents_basis_out := Documents_basis_out || to_char(i) || '. ' || docs.doc || chr(13);    
       i:= i + 1;
    end loop;   
  end if;    
    
  Nom_cost_share := nvl(Nom_cost_share,0);
  Nom_cost_share_shares_ms := nvl(Nom_cost_share_shares_ms,0);
  Share_shares_ms := nvl(Share_shares_ms,0);
  Count_share := nvl(Count_share,0);
  Authorized_capital := nvl(Authorized_capital,0);
  Statutory_capital := nvl(Statutory_capital,0);
  Initial_cost := nvl(Initial_cost,0);
  Residual_cost := nvl(Residual_cost,0);
  Average_list := nvl(Average_list,0);
  pipe row (TypeOrganisationData( 
                               Ogrn_date_reg,--ОГРН, дата государственной регистрации
                               Count_share, --Количество акций
                               Nom_cost_share, --Номинальная стоимость акции  (руб.)
                               Nom_cost_share_shares_ms, --Номинальная стоимость доли муниципальной собственности в уставном капитале (руб.)
                               Share_shares_ms, --Доля муниципальной собственности в уставном капитале (%),
                               Authorized_capital, --уставной капитал
                               Statutory_capital, --уставной фонд
                               Initial_cost, -- Первоначальная стоимость основных средств
                               Residual_cost, -- Остаточная стоимость основных средств
                               Average_list, -- Среднесписочная численность
                               Address_obj, -- адрес
                               Documents_basis_in, -- Документы-основания включения в Реестр
                               Documents_basis_out -- Документы-основания исключения из Реестра
                           ));
  return;
end Rep_organisation_data;
/
grant execute on SM.REP_ORGANISATION_DATA to SM_ALLUSERS;
grant execute on SM.REP_ORGANISATION_DATA to SM_ALL_SELECT;


prompt
prompt Creating function REP_ORG_CHARGES
prompt =================================
prompt
create or replace function sm.Rep_ORG_Charges(AData1 date, AData2 date, kbk_id number, AREND_CAT_id number) return number is
  Result number;

begin
-- Чувыкин - 24062022 - начисления по всем юрлицам по заданному КБК за заданный период
SELECT
sum(t3.PaySize) into result
/*ChargeDate SEL0, 
t3.PaySize SEL1
, Comments SEL2
, sm.getobligationokato(t3.movesets_id, t3.obligationtype_id) SEL3
, Decode(RTRIM(Charge_Type),'FINE','Пеня','OBLIGATION','Обязательство') SEL4
, t1.name SEL5
, t2.NAME||' ('||t2.DESCRIPTION||')' SEL6
, t3.ID PRIMARY_ID
, t5.Name SEL7_8
, sm.GetMoveSetMainDocDescription(t6.ID) SEL8_9*/
FROM
SM.OBLIGATIONTYPE t1
, SM.CLS_KBK t2
, SM.CHARGES t3
, SM.OBLIGATIONS t4
, SM.CLIENTS t5
, SM.MOVESETS t6
WHERE
(t3.obligationtype_id=t1.ID)
 and (t2.ID(+)=t3.CLS_KBK_ID)
 and (t4.MoveSet_ID=t3.MoveSets_ID and
t4.ObligationType_ID=t3.ObligationType_ID)
 and (t5.ID=t6.Client_ID)
 and (t6.ID(+)=t3.MoveSets_ID)
 and (t3.ID in (SELECT 
 Charges.ID
FROM 
 sm.Charges,
 sm.Obligations CHOBL
WHERE 
 CHARGES.CHARGEDATE>=AData1 AND CHARGES.CHARGEDATE<=AData2 and
 CHARGES.CLS_KBK_ID IN (
  SELECT ID FROM SM.CLS_KBK START WITH ID=kbk_id CONNECT BY PRIOR ID=ROOT
) and
 Charges.MoveSets_ID IN (
  SELECT 
   MoveSets.ID
  FROM 
   sm.MoveSets
  WHERE 
   MoveSets.Client_ID IN (
    SELECT 
     Clients.ID
    FROM 
     sm.Clients,
     sm.Organisations
    WHERE 
     CLIENTS.CLIENT_TYPES_ID IN (2) and
     --ORGANISATIONS.ORGFORM IN (847, 938, 977, 1058, 937, 462, 443, 442, 521, 1098, 1158, 850, 872, 825, 877, 763, 544, 744, 785, 1057, 845, 805, 1079, 784, 848, 764, 543, 545, 541, 501, 481, 1078, 582, 663, 917, 743, 703, 745, 1077, 683, 723, 562, 851, 897, 542, 997, 873, 1178, 849) and
   
     sm.Organisations.Clients_ID=Clients.ID and
        ORGANISATIONS.AREND_CAT = AREND_CAT_id 
) and
   MOVESETS.MOVETYPE_ID IN (4)
) and
 CHOBL.MoveSet_ID=Charges.MoveSets_ID and
CHOBL.ObligationType_ID=Charges.ObligationType_ID

))
ORDER BY ChargeDate, Charge_Type, t3.ID;


  return result;

end Rep_ORG_Charges;
/
grant execute on SM.REP_ORG_CHARGES to SM_ALLUSERS;


prompt
prompt Creating function REP_ORG_DBP
prompt =============================
prompt
create or replace function sm.Rep_ORG_DBP(AData date,kbk_id number, AREND_CAT_id number) return number is
  Result number;
  Org_DBP number (27,2);
  id number (27);

begin
/*27062022 - Чувыкин В.Э. - Доходы будущих периодов от договоров с ЮРлицами */

id:=1;
Org_DBP:=0;

for xxx in (
-- запрос извлекающий данные об объектах по заданным условиям

SELECT

t8.ID MS_ID -- идентификатор операции движения, movesets.id
, t2.Name ArName  -- Наименование арендатора
, t2.inn ArInn-- ИНН арендатора
, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL9 -- Начало ОД Аренда
, sm.ExpandDoc_AS2(t4.ID) DocStartDate --дата начала договора аренды
, sm.ExpandDoc_AS(t4.ID) DocEndDate --дата конца договора аренды
, sm.GetMoveSetMainDocDescription(t8.ID) ArDoc -- Договор аренды

FROM
SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
, SM.organisations
WHERE
 (t2.ID=t8.Client_ID)
 and
 (t8.transferbasis_id=t3.ID)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and
 (t5.Document_id=t4.id and t5.Docrole_id=1 and t5.Docset_id=t8.DocSet_id)
 and
 t2.CLIENT_TYPES_ID IN (2) and 
      sm.Organisations.Clients_ID=t2.ID and
    ORGANISATIONS.AREND_CAT = AREND_CAT_id and
 (t8.ID in (SELECT
                   MoveSets.ID
                  FROM
                   sm.MoveSets
                  WHERE
                   EXISTS (
                            SELECT
                             Obligations.ID
                            FROM
                             SM.Obligations,
                             sm.MoveSets OMS
                            WHERE
                             EXISTS ( SELECT
                                       Charges.ID
                                      FROM
                                       sm.Charges,
                                       sm.Obligations CHOBL
                                      WHERE
                                       CHARGES.CLS_KBK_ID IN (SELECT ID FROM SM.CLS_KBK START WITH ID=kbk_id CONNECT BY PRIOR ID=ROOT)
                                       and
                                       CHOBL.ID=Obligations.ID
                                       and
                                       CHOBL.MoveSet_ID=Charges.MoveSets_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       and
                                       CHOBL.ObligationType_ID=Charges.ObligationType_ID
                                       )
                             and
                             OMS.ID=MoveSets.ID
                             and
                             SM.Obligations.MoveSet_ID=OMS.ID
                  ) and
                   MOVESETS.MOVETYPE_ID IN (4) and
                   sm.GetMoveSetEndDate(MoveSets.ID) IS NULL /*and -- убрал условие того, что должны выбираться только открытые на отчетную дату договора
                   sm.GetMoveSetMainDocID(MoveSets.ID) IN (SELECT
                                                           Documents.ID
                                                           FROM
                                                           sm.Documents
                                                           WHERE
                                                           DOCUMENTS.DATE_END > AData)*/

                  ))
order by Arname
-- конец запроса
)

loop
   -- если договор уже закрыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты на 3 года вперед
   if xxx.docenddate < AData then
   Org_DBP := Org_DBP + CALCCHARGES_DBP(xxx.ms_id, AData, add_months(AData,36), 81);
   end if;

   -- если договор еще открыт на задаваемую отчетную дату, то доход будущего периода считается с отчетной даты до конца действия договора
   if xxx.docenddate >= AData then
   Org_DBP := Org_DBP + CALCCHARGES_DBP(xxx.ms_id, AData, xxx.docenddate, 81);
   end if;

   /*pipe row (TYPE_REP_DBP(
                           id,
                           xxx.arinn,
                           xxx.arname,
                           xxx.ArDoc,
                           xxx.docstartdate,
                           DBP
                           )
             );*/

    id := id + 1;
    
 end loop;

  result := Org_DBP;
  return result;

end REP_Org_DBP;
/
grant execute on SM.REP_ORG_DBP to SM_ALLUSERS;


