prompt
create or replace function sm.Rep_Person_Payments(AData1 date, AData2 date, kbk_id number) return number is
  Result number;

begin
-- Чувыкин - 27062022 - платежи всех ФИЗлиц по заданному КБК за заданный период

SELECT

sum(t4.SUM) into result

FROM
SM.DOCUMENTS t1
, SM.CLIENTS t2
, SM.PAYMETHODS t3
, SM.PAYMENTS t4
WHERE
(t1.ID=t4.Documents_ID)
 and (Payer_ID=t2.ID(+))
 and (t3.ID=t4.paymethod_id)
 and (t4.ID in (SELECT
 Payments.ID
FROM
 sm.Payments
WHERE
 payer_id IN (
  SELECT
   Clients.ID
  FROM
   sm.Clients,
   sm.Organisations
  WHERE
   CLIENTS.CLIENT_TYPES_ID IN (1) --and
   --ORGANISATIONS.ORGFORM IN (938, 977, 937, 1098, 1158, 850, 872, 825, 847, 877, 763, 544, 744, 785, 1057, 845, 805, 1058, 462, 443, 442, 1079, 848, 784, 764, 541) and
   --sm.Organisations.Clients_ID=Clients.ID
) and
 PAYMENTS.APPLY_DATE>=AData1 AND PAYMENTS.APPLY_DATE<=AData2 and
 PAYMENTS.CLS_KBK_ID IN (
  SELECT ID FROM SM.CLS_KBK START WITH ID=kbk_id CONNECT BY PRIOR ID=ROOT
)

));

  return result;

end Rep_Person_Payments;
/
grant execute on SM.REP_PERSON_PAYMENTS to SM_ALLUSERS;


