prompt Creating function REP_PERSON_STARTSALDO
prompt =======================================
prompt
create or replace function sm.Rep_Person_StartSaldo(AData1 date, kbk_id number) return number is
  Result number;

begin
-- Чувыкин - 27062022 - входящий остаток или начальное сальдо всех ФИЗлиц по заданному КБК на заданную дату

SELECT
--t8.ID PRIMARY_ID
--, t1.Name SEL0
--, t2.Name SEL1
--, t3.Name SEL2
--, (select MIN(SinceDate) from sm.Moveperiods m where m.Moveset_Id=t8.ID) SEL3
--, sm.GetMoveSetEndDate(t8.ID) SEL4
--, sm.ExpandDoc_AS2(t4.ID) SEL5
--, sm.ExpandDoc_AS(t4.ID) SEL6
--, sm.GetMoveSetMainDocDescription(t8.ID) SEL7
--, sm.GetMoveBalanceOblig(t8.ID,AData1) SEL11
--, sm.GetMoveBalanceFine(t8.ID,AData1) SEL12
--, sm.GetMoveBalanceAll(t8.ID,AData1) SEL13
sum(sm.GetMoveBalanceAll(t8.ID,AData1)) into result
FROM
SM.MOVETYPE t1
, SM.CLIENTS t2
, SM.TRANSFERBASIS t3
, SM.DOCUMENTS t4
, SM.DOCSET_MEMBERS t5
, SM.MOVESETS t8
WHERE
(t8.MoveType_ID=t1.ID)
 and (t2.ID=t8.Client_ID)
 and (t8.transferbasis_id=t3.ID)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t5.Document_id=t4.id and
t5.Docrole_id=1 and
t5.Docset_id=t8.DocSet_id)
 and (t8.ID in (SELECT
 MoveSets.ID
FROM
 sm.MoveSets
WHERE
 EXISTS (
  SELECT
   Obligations.ID
  FROM
   SM.Obligations,
   sm.MoveSets OMS
  WHERE
   EXISTS (
    SELECT
     Charges.ID
    FROM
     sm.Charges,
     sm.Obligations CHOBL
    WHERE
     CHARGES.CLS_KBK_ID IN (
  SELECT ID FROM SM.CLS_KBK START WITH ID=kbk_id CONNECT BY PRIOR ID=ROOT
) and
     CHOBL.ID=Obligations.ID and
     CHOBL.MoveSet_ID=Charges.MoveSets_ID and
CHOBL.ObligationType_ID=Charges.ObligationType_ID and
     CHOBL.ObligationType_ID=Charges.ObligationType_ID
) and
   OMS.ID=MoveSets.ID and
   SM.Obligations.MoveSet_ID=OMS.ID
) and
 MoveSets.Client_ID IN (
  SELECT
   Clients.ID
  FROM
   sm.Clients
  WHERE
   CLIENTS.CLIENT_TYPES_ID IN (1) 
) and
 MOVESETS.MOVETYPE_ID IN (4)

));

  return result;

end Rep_Person_StartSaldo;
/
grant execute on SM.REP_PERSON_STARTSALDO to SM_ALLUSERS;


prompt
prompt Creating function REP_SHARE_DATA
prompt ================================
prompt
create or replace function sm.Rep_share_data(Flag varchar2, AObject_id number, Adate date)
return TypeShareDataList pipelined as
 Name_owner varchar2(255);-- Полное наименование хозяйственного общества или товарищества
 Ogrn_date_reg varchar2(255);--ОГРН, дата государственной регистрации
 Count_share varchar2(255); --Количество акций
 Nom_cost_share varchar2(255); --Номинальная стоимость акции  (руб.)
 Nom_cost_share_shares_ms varchar2(255); --Номинальная стоимость доли муниципальной собственности в уставном капитале (руб.)
 Share_shares_ms number(27,6); --Доля муниципальной собственности в уставном капитале (%)
 Authorized_capital varchar2(255); --уставной капитал/фонд
 Address_obj varchar2(2000); -- адрес
 Aopershares_id number(27);
 ADateReq date;
 AClient_id number(27);
 Aorganisations_id number(27);
 hasauthcapital char(1);
begin
  /* 14/03/2014 Твердохлеб: Возвращает данные для отчета Выписка Акции, доли в уставном капитале*/
  /* 02/02/2016 Твердохлеб: получение количества акций и номинальной сотимости перевел на свои запросы с уточнением что они не должны быть равны 0*/
  
  if (Adate is null) THEN
     ADateReq := sysdate;
  else
     ADateReq := ADate;
  end if;

  -- получим
  -- Полное наименование хозяйственного общества или товарищества
  select og.fullname,
         coalesce(og.ogrn,'') || ', ' || to_char(c.exists_since,'DD.MM.YYYY'),
         o.opershares_id,
         sm.expandaddr_as(c.address_id),
         c.id,
         og.id,
         f.hasauthcapital
    into Name_owner,
         Ogrn_date_reg,
         Aopershares_id,
         Address_obj,
         AClient_id,
         Aorganisations_id,
         hasauthcapital
    from sm.objshares o
    join sm.organisations og on og.id = o.organisations_id
    join sm.clients c on c.id = og.clients_id
    join sm.orgforms f on f.id = og.orgform
   where o.objects_id = AObject_id;

  -- если есть опреации с ЦБ, то получим стоимость акции последнего выпуска
  if (Aopershares_id is not null) then
      select s.nominal
        into Nom_cost_share
        from ( 
          select to_char(o.nominal) nominal            
            from sm.opershares o
           where o.id = Aopershares_id
             and o.operdate <= ADateReq             
           order by o.operdate DESC) s
       where rownum <= 1;
  end if;
  
 
  -- получим уставной капитал
  begin
    select sm.get_authorized_capital(NULL, AClient_id, NULL)
      into Authorized_capital
      from dual;  
    exception
    when NO_DATA_FOUND then
    null;
  end;
  
  -- проверим есть ли на наш объект на указанную дату право собственности
  for
      xx in (
             select * 
               from ( 
                  select mp.sincedate,
                         nvl(mp.enddate, '01.01.2050') enddate
                    from sm.movesets ms
                    join sm.moveperiods mp on mp.moveset_id = ms.id
                    join sm.moveitems mi on mi.moveperiod_id = mp.id 
                   where ms.movetype_id = 1 
                     and mi.object_id = AObject_id 
                     and ms.client_id = 5100
                   order by mp.sincedate desc 
                   )
             where rownum <= 1 
             )
   loop 
       if (ADateReq < xx.sincedate or ADateReq > xx.enddate) then
           ADateReq :=xx.sincedate;
       end if; 
   end loop; 

--raise_application_error(-20000, Aorganisations_id || ' ' ||ADateReq);
  -- получим долю Базового собственника
  select sm.orgstate_and_share_pkg.GetMunicipalShare(Aorganisations_id,ADateReq,'P',NULL)
    into Share_shares_ms
    from dual;
 
  begin
  select SHARESNUMBER
    into Count_share
    from (                
      select st.SHARESNUMBER
        from sm.states st
       where st.objects_id = AObject_id and
             coalesce(st.SHARESNUMBER,0) <> 0 and
             st.calcdate <= ADateReq
       order by st.calcdate DESC)s
    where rownum <= 1;
    exception
    when NO_DATA_FOUND then
    null;    
  end; 
  
  begin 
  select NOMINALCOST
    into Nom_cost_share_shares_ms
    from (                
      select st.NOMINALCOST
        from sm.states st
       where st.objects_id = AObject_id and
             coalesce(st.NOMINALCOST,0) <> 0 and
             st.calcdate <= ADateReq
       order by st.calcdate ASC/*DESC*/)s
    where rownum <= 1; 
    exception
    when NO_DATA_FOUND then
    null;       
 end;
         
 -- если ООО
 if (hasauthcapital = 'Y') then
    begin 
      select amount
        into Share_shares_ms
        from (                
          select st.amount
            from sm.states st
           where st.objects_id = AObject_id and
                 coalesce(st.amount,0) <> 0 and
                 st.calcdate <= ADateReq
           order by st.calcdate DESC)s
        where rownum <= 1;
        exception
        when NO_DATA_FOUND then
        null;
    end;                    
  end if;
       
  Nom_cost_share := nvl(Nom_cost_share,0);
  Nom_cost_share_shares_ms := nvl(Nom_cost_share_shares_ms,0);
  Share_shares_ms := nvl(Share_shares_ms,0);
  Count_share := nvl(Count_share,0);
  pipe row (TypeShareData(Name_owner, Ogrn_date_reg, Count_share, Nom_cost_share, Nom_cost_share_shares_ms, Share_shares_ms, Authorized_capital, Address_obj));
  return;
end Rep_share_data;
/
grant execute on SM.REP_SHARE_DATA to SM_ALLUSERS;
grant execute on SM.REP_SHARE_DATA to SM_ALL_SELECT;


prompt
prompt Creating function REP_TEST
prompt ==========================
prompt
create or replace function sm.Rep_TEST(AData1 date, AData2 date, kbk_id number) return number is
  Result number;

begin
-- Чувыкин - 24062022 - начисления по всем юрлицам по заданному КБК за заданный период
SELECT
sum(t3.PaySize) into result
/*ChargeDate SEL0, 
t3.PaySize SEL1
, Comments SEL2
, sm.getobligationokato(t3.movesets_id, t3.obligationtype_id) SEL3
, Decode(RTRIM(Charge_Type),'FINE','Пеня','OBLIGATION','Обязательство') SEL4
, t1.name SEL5
, t2.NAME||' ('||t2.DESCRIPTION||')' SEL6
, t3.ID PRIMARY_ID
, t5.Name SEL7_8
, sm.GetMoveSetMainDocDescription(t6.ID) SEL8_9*/
FROM
SM.OBLIGATIONTYPE t1
, SM.CLS_KBK t2
, SM.CHARGES t3
, SM.OBLIGATIONS t4
, SM.CLIENTS t5
, SM.MOVESETS t6
WHERE
(t3.obligationtype_id=t1.ID)
 and (t2.ID(+)=t3.CLS_KBK_ID)
 and (t4.MoveSet_ID=t3.MoveSets_ID and
t4.ObligationType_ID=t3.ObligationType_ID)
 and (t5.ID=t6.Client_ID)
 and (t6.ID(+)=t3.MoveSets_ID)
 and (t3.ID in (SELECT 
 Charges.ID
FROM 
 sm.Charges,
 sm.Obligations CHOBL
WHERE 
 CHARGES.CHARGEDATE>=AData1 AND CHARGES.CHARGEDATE<=AData2 and
 CHARGES.CLS_KBK_ID IN (
  SELECT ID FROM SM.CLS_KBK START WITH ID=kbk_id CONNECT BY PRIOR ID=ROOT
) and
 Charges.MoveSets_ID IN (
  SELECT 
   MoveSets.ID
  FROM 
   sm.MoveSets
  WHERE 
   MoveSets.Client_ID IN (
    SELECT 
     Clients.ID
    FROM 
     sm.Clients,
     sm.Organisations
    WHERE 
     CLIENTS.CLIENT_TYPES_ID IN (2) and
     --ORGANISATIONS.ORGFORM IN (847, 938, 977, 1058, 937, 462, 443, 442, 521, 1098, 1158, 850, 872, 825, 877, 763, 544, 744, 785, 1057, 845, 805, 1079, 784, 848, 764, 543, 545, 541, 501, 481, 1078, 582, 663, 917, 743, 703, 745, 1077, 683, 723, 562, 851, 897, 542, 997, 873, 1178, 849) and
     sm.Organisations.Clients_ID=Clients.ID
) and
   MOVESETS.MOVETYPE_ID IN (4)
) and
 CHOBL.MoveSet_ID=Charges.MoveSets_ID and
CHOBL.ObligationType_ID=Charges.ObligationType_ID

))
ORDER BY ChargeDate, Charge_Type, t3.ID;


  return result;

end Rep_TEST;
/

