prompt
create or replace function sm.ShowInList(ObjID in NUMBER, ObjType IN NUMBER) return number is
  OT number(1);
  HL char(1);
begin
  OT:=ObjType;
  if ObjType=0 then   select ObjType into OT from Objects where ID=ObjID;  end if;
  
  if OT != 3 then
   return(1);
  else 
   select buildtypes.container into HL 
   from buildtypes, buildings
   where 
    buildings.buildtypes_id=buildtypes.id and
    buildings.objects_id=ObjID;
    if HL='Y' then return(1); else return(0); end if;
  end if;
end ShowInList;
