prompt Creating function SIZEBODYDOC
prompt =============================
prompt
create or replace function sm.SizeBodyDoc(DocID in number) return number is
  Size_body number;
  doc_body blob; 
  
begin
  Size_body:=0;
  doc_body:=empty_blob();
  
  select d.body
  into doc_body
  from sm.documents d
  where d.id=DocID;
  
  if doc_body is null then
      Size_body:=0;
  elsif dbms_lob.getlength(doc_body)=0 then
      Size_body:=0;
  else
      Size_body:=trunc(dbms_lob.getlength(doc_body)/1024,2);    
  end if;    
  
  return Size_body;
  
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN null; 
  
end;
/
grant execute on SM.SIZEBODYDOC to SM_ALLUSERS;
grant execute on SM.SIZEBODYDOC to SM_ALL_SELECT;


