prompt Creating function UNWRAP_DOCNO
prompt ==============================
prompt
create or replace function sm.UNWRAP_DOCNO(ADOCTYPE IN NUMBER, NUM IN varchar2) RETURN VARCHAR2
is
 -- by XSGROUP 15.05.2009
 -- функция "очищает" номер документа от префикса и суффикса для данного типа документовъ
 -- для передачи "чистого" номера в процедуру ReturnDocNo
 --
 prefix sm.doctypes.num_prefix%type; 
 suffix sm.doctypes.num_suffix%type; 
 res    varchar2(400);
 T_NUM  varchar2(400); 
begin
 
 T_NUM:=trim(NUM);
 
 select 
   nvl(t.num_prefix,''), 
   nvl(t.num_suffix,'')
 into 
   prefix, 
   suffix
 from 
   sm.doctypes t
 where 
   t.id=adoctype;

 if (prefix is null) and (suffix is null) then
   return(T_NUM);  
 end if;
 
 if (prefix is null) and (suffix is not null) then
   
   res:=substr(T_NUM,1,length(T_NUM)-length(suffix));
   return(res);
 end if;

 if (prefix is not null) and (suffix is null) then
   res:=substr(T_NUM,length(prefix)+1,length(T_NUM)-length(prefix));
   return(res);
 end if;

 res:=substr(T_NUM,length(prefix)+1,length(T_NUM)-length(prefix)-length(suffix));
 return (res);
 
end;
/
grant execute on SM.UNWRAP_DOCNO to SM_ALLUSERS;
grant execute on SM.UNWRAP_DOCNO to SM_ALL_SELECT;


prompt
prompt Creating procedure CALCBUILDCHILDSBYMOVETYPE
prompt ============================================
prompt
create or replace procedure sm.CALCBUILDCHILDSBYMOVETYPE(BuildID in number, BuildType in number, MoveType in number,
  Client number, MoveDate in date, Cnt in out number, ParentInclude char) as
-- Считает количество зданий и помещений заданного типа на заданную дату с заданной ОД у определенного здания/уровня
-- Возвращает результата в Cnt
  Incl char;
  IsklCnt number;
  CurCnt number;
  CurBuildType number(27);
  CurID number(27);  
begin
  
  Incl:='N';
  IsklCnt:=0;  
  
-- Если родитель уже имеет ОД данного типа и у текущего объекта нет ОД, исключающей верхнюю, то суммируем
  if ParentInclude='Y' then

    for yy in  (select t.*
                from sm.movements t,
                  sm.buildings b
                where 
                  b.objects_id=t.objects_id and
                  b.id=BuildID and                                      
/*                  (t.movetype_id in (select cw_movetype_id 
                                    from sm.policyerrors e
                                    where e.movetype_id=Movetype) or */
                   (t.movetype_id=Movetype and t.Clientsto_Id != Client) and
                  t.postingdate<=MoveDate and (t.enddate is null or t.enddate>=MoveDate))
    loop
      IsklCnt:=IsklCnt+1;
    end loop;
    
  end if;
  
-- Смотрим сначала движения родительского здания/помещения
  CurCnt:=0;
  for yy in (select b.*
             from sm.movements t,
               sm.buildings b
             where 
               b.objects_id=t.objects_id and
               t.clientsto_id=Client and
               b.id=BuildID and                                      
               t.movetype_id=Movetype and
               t.postingdate<=MoveDate and (t.enddate is null or t.enddate>=MoveDate))
  loop
-- Так как мы уже в цикле, значит есть как минимум одна ОД заданного типа и несмотря на тип объекта
-- нужно проверять детей
    if IsklCnt=0 then
      Incl:='Y';
    end if;
    
    if yy.buildtypes_id=Buildtype then
      Cnt:=Cnt+1;    
      sys.dbms_output.put_line(yy.objects_id);
    end if;
    
    CurCnt:=CurCnt+1;
  end loop;
  
-- Если у родительского здания/помещения нет ОД данного типа, но его верхний уровень их имеет,то все равно надо включать
  if CurCnt=0 and ParentInclude='Y' then
    select b.objects_id, b.buildtypes_id into CurID, CurBuildType
    from sm.buildings b
    where b.id=BuildID;
    
    if (CurBuildType=BuildType) and (IsklCnt=0) then
      Cnt:=Cnt+1;        
      sys.dbms_output.put_line(curid);      
    end if;  
  end if;
             
-- А потом уже "детей"
  for yy in (select * 
             from sm.buildings b
             where 
               b.basebuilding=BuildID and                                      
               (b.exists_since is null or b.exists_since<=MoveDate) and
               (b.exists_end is null or b.exists_end>=MoveDate) )               
  loop
    CALCBUILDCHILDSBYMOVETYPE(yy.id, Buildtype, Movetype, Client, MoveDate, Cnt, Incl);
  end loop;
  
end CALCBUILDCHILDSBYMOVETYPE;
/
grant execute on SM.CALCBUILDCHILDSBYMOVETYPE to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGEDICTHASH
prompt =================================
prompt
create or replace procedure sm.ChangeDictHash(TBL_NAME in VARCHAR2, NEW_HASH in NUMBER) as
 tempHASH number(27);
begin
  select DICTIONARIES.HASH_CODE into tempHASH
  from DICTIONARIES
  where Upper(TABLE_NAME)=Upper(TBL_NAME);

  if not nvl(tempHash,-1)=NEW_HASH then
    update DICTIONARIES D
    set D.HASH_CODE=NEW_HASH
    where Upper(TABLE_NAME)=Upper(TBL_NAME);
    commit;
  END IF;
exception
  when no_data_found then
  begin
    insert into DICTIONARIES (ID,TABLE_NAME, HASH_CODE, IS_STATIC)
    values (sm.seqdictionaries.nextval,Upper(TBL_NAME), NEW_HASH, 'Y');
    commit;
  end;
end CHANGEDICTHASH;
/
grant execute on SM.CHANGEDICTHASH to SM_ALLUSERS;
grant execute on SM.CHANGEDICTHASH to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGELEASEPURPOSE
prompt =====================================
prompt
create or replace procedure sm.ChangeLeasePurpose as

begin
  /* 18/07/2024 Чувыкин: меняет "Целевое назначение" в ОД заданного типа на заданном списке объектов*/

  for xxx in
             (select *
                from TMP_IMPORT_COST t)
  loop
 
      -- в ОД Забалансовый учет и Бюджетный учет (или каких надо) изменяем "Целевое назначение" со старого на новое
      -- Сооружение (д) 5184
      -- Сооружение (н) 5229
      for yyy in (
                   select mi.id
                     from sm.movesets ms
                     join sm.moveperiods mp on mp.moveset_id = ms.id
                     join sm.moveitems mi on mi.moveperiod_id = mp.id
                    where ms.movetype_id in (29,31)
                      and mi.object_id = xxx.object_id
                      
                     and mp.sincedate <= sysdate
                      and (mp.enddate >= sysdate or mp.enddate is null)
                 )
      loop
         begin
           update moveitems mi set mi.leasepurpose_id = 5229 where mi.leasepurpose_id = 5184 and mi.id = yyy.id;     
          
           exception
            when others then begin
              raise_application_error (-20101, xxx.object_id);
            null;
          end;
         end;
      end loop;
  end loop;

  delete from TMP_IMPORT_COST;
end ChangeLeasePurpose;
/

prompt
prompt Creating procedure CHANGEMIOBJSTATE
prompt ===================================
prompt
create or replace procedure sm.ChangeMIObjState(
                                                                 ObjID in number,
                                                                 StateID in number,
                                                                 StateDate in date,
                                                                 DocID in number,
                                                                 SharesNumberD in numeric,
                                                                 AmountD in numeric,
                                                                 NominalCostD in numeric,
                                                                 MoveItemsID in number,
                                                                 oldMIID in number)
  as
--
-- XSGROUP ver. 4.7.5
-- Процедура сохраняет состояние объекта типа 21
--(количественные, изменяемые со временем характеристик объекта)
--
-- Количественные параметры представляют собой значение  значение нового состояния
--
  curStateID number(27); --ID состояния на дату текущего изменения
  newDocSets_ID number(27);
  nTmp number(27);
  nDocIDTmp number(27);
  nDocTypeIDTmp number(27);
begin
   select objtypes_id into nTmp from sm.objects o where o.id=ObjID;
   if (nTmp <> 21) then
           raise_application_error(-20101,'Недопустимый тип объекта для выполнения данной процедуры.');
   end if;

   curStateID:=StateID;

   --создаем DOCSET   
   select sm.seqdocsets.nextval into newDocSets_ID from dual;
   insert into sm.docsets ds values(newDocSets_ID);

   --Если известен Документ, помещаем его в созданный DOCSET
   -- Неизвестный документ
   select count(*) into nDocTypeIDTmp from sm.doctypes t where t.guid = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE';
   if (nDocTypeIDTmp > 0) then
       select t.id into nDocTypeIDTmp from sm.doctypes t where t.guid = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE';
   else
      raise_application_error(-20101,'Не найден тип документа ''Неизвестный документ'' ' || chr(10)
                                          || 'с глобальным уникальным идентификатором ''8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE'''
                                          ||' необходимый для выполнения данной процедуры.');
   end if;

   select count(*) into nDocIDTmp from sm.documents t where t.doctypes_id=nDocTypeIDTmp;
   if (nDocIDTmp > 0) then
      select t.id into nDocIDTmp from sm.documents t where t.doctypes_id=nDocTypeIDTmp;
   else
      raise_application_error(-20101,'Не найден документ ''Неизвестный документ'' ' || chr(10)
                                          || 'с глобальным уникальным идентификатором типа ''8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE'''
                                          ||' необходимый для выполнения данной процедуры.');
   end if;

   insert into sm.docset_members
       (docset_id, document_id, docrole_id)
     values
       (newDocSets_ID, nvl(DocID,nDocIDTmp), 1);


   if (curStateID is not null) then  
       update sm.STATES
          set
             DOCUMENTS_ID = newDocSets_ID,
             AMOUNT =                     (case when AmountD is not null
                                                          then AmountD
                                                          else AMOUNT
                                                          end),
             NOMINALCOST =             (case when NominalcostD is not null
                                                         then NominalcostD
                                                         else NOMINALCOST
                                                         end),
             SHARESNUMBER =           (case when SharesnumberD is not null
                                                         then SharesnumberD
                                                         else SHARESNUMBER
                                                         end),
					    CALCDATE =	StateDate			
        where id = curStateID;

   else
      select sm.seqstates.nextval into curStateID from dual;

      insert into sm.STATES
         (ID, CALCDATE, DOCUMENTS_ID, OBJECTS_ID, AMOUNT, NOMINALCOST, SHARESNUMBER)
       values
         (curStateID, StateDate, newDocSets_ID, ObjID,
         AmountD,
         NominalcostD,
         SharesnumberD
         );

   end if;

   --заполним правильно ссылки в MOVEITEMS.STATE_ID
   -- в новом "движении" ОД собственость
   if (MoveItemsID is not null) then
      update sm.moveitems mi set mi.state_id=curStateID where mi.id=MoveItemsID;
   end if;
   if (oldMIID is not null) then
     -- в движении ОД прежнего собственника в случае продажи
     update sm.moveitems mi set mi.state_id=curStateID where mi.id=oldMIID;
   end if;

end;  --- END  ChangeMIObjState
/
grant execute on SM.CHANGEMIOBJSTATE to SM_ALLUSERS;
grant execute on SM.CHANGEMIOBJSTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGEMIOWNEROBJSTATE
prompt ========================================
prompt
create or replace procedure sm.ChangeMIOwnerObjState(
                                                                 isMSCall in char,
                                                                 ObjID in number,
                                                                 StateDate in date, StateDatePrev in date,
                                                                 DocID in number,
                                                                 SharesNumberD in numeric,
                                                                 AmountD in numeric,
                                                                 NominalCostD in numeric,
                                                                 MoveItemsID in number)
  as
--
-- XSGROUP ver. 4.7.5
-- Процедура приводит в соответствие состояние и "движение"  объекта "Пакеты акций, доли в капитале"
-- в ОД "Собственность" акционера (участника)
-- (количественные, изменяемые со временем характеристик объекта)
--
-- Количественные параметры представляют собой дельту (на сколько изменится значение)
-- isMSCall - флаг, если 'Y' - значит процедура вызывается из ОД
--
  nTmp number(27);

  newMPEnd date;

  oldSTID number(27);
  oldMSID number(27);
  oldMPID number(27);
  oldMIID number(27);

  newSTID number(27);
  newMPID number(27);
  newMIID number(27);
  newDSID number(27);

  sharesNumberOLD number(27,6);
  amountOLD number(27,6);
  nominalCostOLD number(27,6);

  sharesNumberNew number(27,6);
  amountNew number(27,6);
  nominalCostNew number(27,6);

  ObjSharesOwnerID number(27);
begin
    select objtypes_id into nTmp from sm.objects o where o.id=ObjID;
    if (nTmp <> 21) then
           raise_application_error(-20101,'Недопустимый тип объекта для выполнения данной процедуры.');
    end if;

    -- Собственник (акционер, участник, учредитель)
    select osh.owner_id into ObjSharesOwnerID from sm.objshares osh where osh.objects_id=ObjID;
    if (ObjSharesOwnerID is null) then
         raise_application_error(-20101,'Не установлен собственник (акционер, участник, учредитель) объекта "Пакеты акций, доли в капитале".');
    end if;

    --Находим соответсвующее предыдущему состоянию "движение" и состояние
    for xxMI in (
      select
        ms.id as kumiMSID,
        mp.id as kumiMPID,
        mi.id as kumiMIID,
        mi.state_id as kumiSTID
      from
        sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
      where
        mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
        mp.sincedate = (select max(mmp.sincedate) -- !!!
                             from
                                sm.moveitems mmi, sm.moveperiods mmp, sm.movesets mms
                              where
                                mmi.moveperiod_id = mmp.id and mmp.moveset_id = mms.id and
                                mmp.sincedate <= StateDatePrev and  -- !!!
                                mmi.object_id=mi.object_id and
                                mms.id=ms.id) and
        mi.object_id=ObjID and
        ms.client_id=ObjSharesOwnerID  
               )
    loop
       if (xxMI.kumiMSID is not null)
        then
           oldMSID := xxMI.kumiMSID;
           oldMPID := xxMI.kumiMPID;
           oldMIID := xxMI.kumiMIID;
           oldSTID := xxMI.kumiSTID;
           exit;
        end if;
    end loop;

    if (oldMPID is null or oldMIID is null) then
         raise_application_error(-20101,'Не удалось найти движение объекта "Пакеты акций, доли в капитале".');
    end if;
    if (oldSTID is null) then 
         raise_application_error(-20101,'Не удалось найти состояние объекта "Пакеты акций, доли в капитале".');
    end if;

    --Находим значения предыдущего состояния 
    select
        st.sharesnumber, st.amount, st.nominalcost
    into
        sharesNumberOLD, AmountOLD, NominalcostOLD
    from sm.states st where st.id=oldSTID;


    --Вычисляем значения для нового состояния и "движения" объекта
    sharesNumberNew := (case when (SharesnumberOLD is not null or SharesnumberD is not null)
                                                     then (nvl(SharesnumberOLD,0)+nvl(SharesnumberD,0))
                                                     else SharesnumberOLD
                                                     end);
    amountNew :=          (case when (AmountOLD is not null or AmountD is not null)
                                                      then (nvl(AmountOLD,0)+nvl(AmountD,0))
                                                      else AmountOLD
                                                      end);
    nominalCostNew :=    (case when (NominalcostOLD is not null or NominalcostD is not null)
                                                     then (nvl(NominalcostOLD,0)+nvl(NominalcostD,0))
                                                     else NominalcostOLD
                                                     end);


    --если новые значения уходят в минус - это ошибка (попытка продать сверх имеющегося количества)
    if (nvl(sharesNumberNew,0) < 0
        OR (amountNew < 0 and abs(amountNew)>0.000001)
        OR nominalCostNew < 0
        ) then
         raise_application_error(-20101,'Недостаточное количество объекта для совершения операции.');

    --иначе приводим в соответствие состояние и "движение" объекта
    else
       --Находим ID состояния на дату нового "движения"
       select count(*) into nTmp from sm.states st where st.objects_id = ObjID and st.calcdate =   StateDatePrev;     
       if (nTmp > 0) then
         select st.ID into newSTID from sm.states st where st.objects_id = ObjID and st.calcdate =   StateDatePrev;     
       end if;

       --ищем соответствующее "движение"
       if (newSTID is not null and oldMSID is not null) then
          for xxMI in (
          select
            mi.id as kumiMIID
          from
            sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
          where
            mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
            ms.id = oldMSID and
            mi.state_id = newSTID and
            ms.client_id=ObjSharesOwnerID   
                   )
          loop
           if (xxMI.kumiMIID is not null)
            then
               newMIID := xxMI.kumiMIID;
               exit;
            end if;
          end loop;
       end if;


       -- если период уже существует, сохраняем новые значения
       if (newMIID is not null) then

           update sm.moveitems mi
             set
                 amount = amountNew,
                 nominalcost = nominalCostNew,
                 sharesnumber = sharesNumberNew
	           where id = newMIID;

           -- сохраняем новую дату периода ОД
           if StateDatePrev <> StateDate then
						 update SM.MOVEPERIODS set SINCEDATE = StateDate where MOVESET_ID = oldMSID and SINCEDATE = StateDatePrev;
           end if;

       -- если нет периода, создаем новый
       else
           -- определяем дату окончания нового периода
           if (amountNew = 0 or nominalCostNew = 0) then
               newMPEnd := StateDate;
               amountNew := 0;  
               nominalCostNew := 0;  
               sharesNumberNew := 0; 
           else
               for xxST in (
                select
                  st.SHARESNUMBER as SHARESNUMBER,
                  st.AMOUNT as AMOUNT,
                  st.NOMINALCOST as NOMINALCOST,
                  st.calcdate as nextStateDate
                from
                  sm.states st
                where
                  st.objects_id = ObjID and
                  st.calcdate > StateDate
                order by st.calcdate
                         )
              loop
                  if (xxST.SHARESNUMBER is not null or
                     xxST.AMOUNT is not null or
                     xxST.NOMINALCOST is not null)                  
                  then
                     -- дата окончания нового периода
                     newMPEnd := trunc(xxST.nextStateDate) - 1;
                     exit;
                  end if;
               end loop;
           end if;

           -- получим ID нового периода
           select sm.seqmoveperiods.nextval into newMPID from dual;

           -- создаём новый доксет
           select sm.seqdocsets.nextval into newDSID from dual;
           insert into sm.docsets ds values(newDSID);

           --создаём новый период
           insert into sm.moveperiods (id,
                                     SinceDate,
                                     EndDate,
                                     MOVESET_ID,
                                     DOCSET_ID,
                                     PREV_MOVEPERIOD_ID)
                             values (newMPID,
                                     StateDate,
                                     newMPEnd,
                                     oldMSID,
                                     newDSID,
                                     oldMPID);

           --устанавливаем ID предыдущего периода у следующего за созданным периодом
           update sm.moveperiods mpp set mpp.PREV_MOVEPERIOD_ID=newMPID where mpp.PREV_MOVEPERIOD_ID=oldMPID and mpp.id<>newMPID;

           --устанавливаем дату окончания у предыдущего периода
           update sm.moveperiods mpp set mpp.EndDate=StateDate-1 where mpp.id=oldMPID;

           -- копируем объекты из предыдущего периода
           for yy in (select * from sm.Moveitems mi where mi.moveperiod_id=oldMPID)
           loop

              -- получим ID нового "движения"
              select sm.seqmoveitems.nextval into newMIID from dual;
              insert into sm.Moveitems mi (id,
                                           LEASEPURPOSE_ID,
                                           MOVEPERIOD_ID,
                                           OBJECT_ID,
                                           PARAMS,
                                           PRICE,
                                           SHARE_DENOM,
                                           SHARE_NUM,
                                           SHAREPERCENT,
                                           --STATE_ID,
                                           amount,
                                           unit_id,
                                           currency_id,
                                           nominalcost,
                                           sharesnumber,
                                           singlepricecurr
                                           )
                                   values (newMIID,
                                           yy.leasepurpose_id,
                                           newMPID,
                                           yy.object_id,
                                           yy.params,
                                           null,
                                           yy.share_denom,
                                           yy.share_num,
                                           yy.sharepercent,
                                           --null,  --state_id
                                           amountNew,
                                           yy.unit_id,
                                           yy.currency_id,
                                           nominalCostNew,
                                           sharesNumberNew,
                                           null
                                           );
           end loop;

           -- копируем документы в пакет документов нового периода
           for yy in (select * from sm.docset_members dsm inner join sm.moveperiods mp on mp.docset_id=dsm.docset_id where mp.id=oldMPID)
           loop
              insert into sm.Docset_Members dsm (docset_id,document_id,docrole_id) values (newDSID,yy.document_id,yy.docrole_id);
           end loop;

           -- условия обязательств не копируем

      end if;    --end    -- если нет периода, создаем новый

      -- Изменяем состояние объекта на дату нового периода - передаем значение нового состояния
      -- если процедура вызвана при сохранении ОД
      if (isMSCall = 'Y') then
           sm.ChangeMIObjState(
                                    ObjID,
                                    newSTID,
                                    StateDate,
                                    DocID,
                                    sharesNumberNew,
                                    amountNew,
                                    nominalCostNew,
                                    MoveItemsID,
                                    newMIID
                                    );

      -- если процедура вызвана при сохранении операции с УК
      else
           sm.ChangeMIObjState(
                                    ObjID,
                                    newSTID,
                                    StateDate,
                                    DocID,
                                    sharesNumberNew,
                                    amountNew,
                                    nominalCostNew,
                                    newMIID,
                                    null
                                    );

      end if;

      --корректировка последующих состояний
      update
          sm.states
       set
          AMOUNT =                 (case when ((AMOUNT is not null or AmountD is not null) and (nvl(AMOUNT,0)+nvl(AmountD,0))>=0)
                                                        then (nvl(AMOUNT,0)+nvl(AmountD,0))
                                                        else AMOUNT
                                                        end),
          NOMINALCOST =         (case when ((NOMINALCOST is not null or NominalcostD is not null) and (nvl(NOMINALCOST,0)+nvl(NominalcostD,0))>=0)
                                                        then (nvl(NOMINALCOST,0)+nvl(NominalcostD,0))
                                                        else NOMINALCOST
                                                        end),
          SHARESNUMBER =       (case when ((SHARESNUMBER is not null or SharesnumberD is not null) and (nvl(SHARESNUMBER,0)+nvl(SharesnumberD,0))>=0)
                                                        then (nvl(SHARESNUMBER,0)+nvl(SharesnumberD,0))
                                                        else SHARESNUMBER
                                                        end)
        where
          objects_id = ObjID and
          calcdate > StateDate;

      --корректировка последующих "движений"
      --if (isMSCall = 'Y') then
          update
              sm.Moveitems
           set
              AMOUNT =                 (case when ((AMOUNT is not null or AmountD is not null) and (nvl(AMOUNT,0)+nvl(AmountD,0))>=0)
                                                            then (nvl(AMOUNT,0)+nvl(AmountD,0))
                                                            else AMOUNT
                                                            end),
              NOMINALCOST =         (case when ((NOMINALCOST is not null or NominalcostD is not null) and (nvl(NOMINALCOST,0)+nvl(NominalcostD,0))>=0)
                                                            then (nvl(NOMINALCOST,0)+nvl(NominalcostD,0))
                                                            else NOMINALCOST
                                                            end),
              SHARESNUMBER =       (case when ((SHARESNUMBER is not null or SharesnumberD is not null) and (nvl(SHARESNUMBER,0)+nvl(SharesnumberD,0))>=0)
                                                            then (nvl(SHARESNUMBER,0)+nvl(SharesnumberD,0))
                                                            else SHARESNUMBER
                                                            end)
            where
              OBJECT_ID = ObjID and
              MOVEPERIOD_ID in (select mp.id from sm.moveperiods mp where mp.moveset_id=oldMSID and mp.sincedate>StateDate);
      --end if;

   end if;     --END иначе приводим в соответствие состояние и "движение" объекта

end;   --- END  ChangeMIOwnerObjState
/
grant execute on SM.CHANGEMIOWNEROBJSTATE to SM_ALLUSERS;
grant execute on SM.CHANGEMIOWNEROBJSTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGEOBJSTATES
prompt ==================================
prompt
create or replace procedure sm.ChangeObjStates(
  saction in char,          	-- insert = 'i', update = 'u', deletе - процедура не вызывается
  objid in number,        		-- moveitems.objects_id
  stateid_p in number,  		-- moveitems.state_id
  statedate in date,      		-- moveperiods.sincedate
  docsetid in number,    		-- не используется
  sharesnumberd in numeric, 	-- moveitems.sharesnumber
  sharesprevnumberd in numeric, -- не используется
  amountd in numeric,       	-- moveitems.amount
  nominalcostd in numeric, 		-- не используется
  docid in number,            	-- основной документ в пакете периода, при вызове из кода не передается
  moveitemsid in number   		--moveitems.id
  
  --old-значения: если saction='i', то null; иначе - прежние значения до исправления
  --sharesnumberp in numeric, -- прежнее количество акций при участии акциями,
  --amountp in numeric, -- прежний % доли при долевом участии
  --sincedatep in date  -- прежнее начало периода
                                               )
   as
--
-- XSGROUP ver. 4.7.5  p. 30.11.2012
-- Процедура вызывает изменение состояний объекта
--(количественных, изменяемых со временем характеристик объекта)
-- только для объектов типа 21 ("Пакеты акций, доли в капитале")
--
-- Количественные параметры представляют собой новое значение MoveItems
--
  StateID number(27);
  curStateID number(27); --ID состояния на дату текущего изменения
  nTmp number(27);
  d DATE;
	dBefore DATE;
  orgform	sm.orgforms%ROWTYPE;
  nCost number(27,2);

  sharesNumberPREV number(27,6);
  amountPREV number(27,6);
  nominalCostPREV number(27,2);
  sharesNumberCUR number(27,6);
  amountCUR number(27,6);
  nominalCostCUR number(27,2);

  sharesNumberNEWD number(27,6);
  amountNEWD number(27,6);
  nominalCostNEWD number(27,2);

  nSharesNumber number(27,6);
  nNominal number(27,2);
  OrgID number(27);

  SharesNumberD_v number(27,6);
  AmountD_v number(27,6);
  NominalCostD_v number(27,2);
  nCapital number(27,2);

  msID number(27);
begin
   --Только для объектов типа 21 ("Пакеты акций, доли в капитале")
  select objtypes_id into nTmp from sm.objects o where o.id=ObjID;
  if (nTmp = 21) then
		if (MoveItemsID is null) then
        raise_application_error(-20101,'Не задан ID движения для изменения состояния объекта.');
		end if;

    -- текущая ОД
    select min(mp.moveset_id) into msID from sm.moveitems mi, sm.moveperiods mp where mi.moveperiod_id = mp.id and mi.id=MoveItemsID;
    if (msID is null) then
       raise_application_error(-20101,'Не удалось определить ID текущей ОД.');
    end if;

		d:=trunc(StateDate);
    StateID := StateID_p;

    --Если отчуждение (продажа) собственности ------------------
    if (SharesNumberD < 0 or AmountD < 0 --or NominalCostD < 0
       ) then
        if (sAction = 'U') then
          return;  -- !!!!!!!!!!!!!!!! ЗАГЛУШКА - корректировка не работает

          --if (SinceDateP is null) then
          --   raise_application_error(-20101,'Не известно прежнее значение начала периода.');
          --end if;
          --dBefore := SinceDateP;

        end if;

        --Находим соответсвующее предыдущему состоянию "движение" и состояние
        for xMI in (
          select
            mi.sharesnumber,
            mi.amount,
            mi.nominalcost
          from
            sm.moveitems mi, sm.moveperiods mp
          where
            mi.moveperiod_id = mp.id and
            mp.sincedate = (select max(mmp.sincedate) -- !!!
                                 from
                                    sm.moveitems mmi, sm.moveperiods mmp
                                  where
                                    mmi.moveperiod_id = mmp.id and
                                    mmp.sincedate < NVL(dBefore, d) and  -- !!!
                                    mmi.object_id=mi.object_id and
                                    mmp.moveset_id=mp.moveset_id) and
            mi.object_id=ObjID and
            mp.moveset_id=msID
                   )
        loop
               sharesNumberPREV := xMI.sharesNumber;
               amountPREV := xMI.amount;
               nominalcostPREV := xMI.nominalcost;
               exit;
        end loop;

       if (sharesNumberPREV is not null) then
          sharesNumberPREV := sharesNumberPREV*(-1);
       end if;
       if (amountPREV is not null) then
          amountPREV := amountPREV*(-1);
       end if;
       if (nominalcostPREV is not null) then
          nominalcostPREV := nominalcostPREV*(-1);
       end if;

    -- если приобретение собственности
    else
    		--Находим текущую (на самом деле прежнюю!)  дату State-а   -- <<<< !!!!!!!!!!!!!!!!!!!!
    		select count(*) into nTmp from SM.STATES st  where st.ID = StateID;
    		if (nTmp > 0) then
    					 select trunc(st.CALCDATE)  into dBefore from SM.STATES st where st.ID = StateID;
    		end if;

    end if;


    -- Определяем номинал и ID эмитента
		select nvl(opsh.nominal,0), opsh.organisations_id into nNominal, OrgID
					from sm.opershares opsh, sm.objshares obsh
					where opsh.id=obsh.opershares_id and obsh.objects_id=ObjID;

    -- Определяем параметры орг-прав-формы, чтобы далее различать случаи акций/долей/уФ/УП
		select f.* into orgform
		from
			    sm.organisations org, sm.orgforms f
		where
			    f.id=org.orgform and org.id=OrgID;

    -- Для Акционерной формы - все определяем через количество акций (несмотря на др.переданные аргументы - они передаются "прошлые")
    if  orgform.IS_JSC = 'Y' then
					if (nNominal = 0) then
						 raise_application_error(-20101, 'Неизвестен номинал акций на ' ||to_char(d, 'dd.MM.yyyy') );
					end if;
					SharesNumberD_v := SharesNumberD;
					AmountD_v := 0;
					NominalCostD_v := 0;
		else
					SharesNumberD_v := 0;
					AmountD_v :=  AmountD;
					NominalCostD_v := 0;
    end if;

    -- если указали только количество акций, вычислим долю и ном.ст-ть
    if (nvl(SharesNumberD_v,0) <> 0
         and (nvl(NominalCostD_v,0) = 0 or nvl(AmountD_v,0) = 0)
         ) then

          -- общее количество выпущенных акций
          nSharesNumber := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID,d,'N'),0);
	        if (nSharesNumber <> 0) then
              if (nvl(NominalCostD_v,0) = 0 ) then
                 -- вычисляем номин. стоимость
                 NominalCostD_v := round(SharesNumberD_v * nNominal, 2);
              end if;
              if (nvl(AmountD_v,0) = 0) then
                  --уставный капитал хоз.общества
                  nCapital := nvl(SM.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, d, 'C'),0);
                  if (nCapital <> 0) then
                     -- вычисляем количество %
                     AmountD_v := round(NominalCostD_v * 100 / nCapital, 6);
                  end if;
              end if;
          else
              raise_application_error(-20101, 'Неизвестно общее количество выпущенных акций на ' ||to_char(d, 'dd.MM.yyyy') );
          end if;
    -- если указали только долю, вычислим ном.ст-ть
    elsif (nvl(AmountD_v,0) <> 0
         and nvl(NominalCostD_v,0) = 0
         ) then

          --уставный капитал хоз.общества
          nCapital := nvl(SM.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, d, 'C'),0);
          if (nCapital <> 0) then
             -- вычисляем ном.ст-ть
             NominalCostD_v := round(AmountD_v / 100 * nCapital, 2);
          else
              raise_application_error(-20101, 'Неизвестен размер уставного капитала на ' ||to_char(d, 'dd.MM.yyyy') );
          end if;
    end if;

    --Если отчуждение (продажа) собственности ------------------
    if (SharesNumberD_v < 0 or AmountD_v < 0 or NominalCostD_v < 0) then

  		if (sAction <> 'U') then
               --Приводим в соответствие "движение" объекта - ПЕРЕДАЕМ ДЕЛЬТУ (на сколько изменится значение)
               sm.ChangeMIOwnerObjState(
                                                   'Y', -- флаг, что процедура вызвана из ОД
                                                   ObjID,
                                                   d,  d,    -- <<< NVL(dBefore, d) --dBefore is null в данном случае
                                                   DocID,
                                                   SharesNumberD_v - nvl(sharesNumberPREV, 0),
                                                   AmountD_v - nvl(amountPREV, 0),
                                                   NominalCostD_v - nvl(nominalCostPREV, 0),
                                                   MoveItemsID
                                                   );

  		-- корректировка ранее введенных значений
  		else
               -- прежние значения
               --if (sharesNumberCUR is not null) then
               --   sharesNumberCUR := sharesNumberP;
               --end if;
               --if (amountCUR is not null) then
               --   amountCUR := amountP;
               --end if;

               --вычисление недостающих прежних значений
               -- amountCUR
               -- nominalcostCUR


               -- если что-то изменилось
               if (SharesNumberD_v <> sharesNumberCUR or AmountD_v <> amountCUR or NominalCostD_v <> nominalcostCUR
  							   OR dBefore <> d) then

                  --Вычисляем ДЕЛЬТУ (на сколько изменится значение)
                   sharesNumberNEWD := (case when (SharesNumberD_v is not null or sharesNumberCUR is not null)
                                                                     then (nvl(SharesNumberD_v,0)-nvl(sharesNumberCUR,0))
                                                                     else 0
                                                                     end);
                   amountNEWD :=          (case when (AmountD_v is not null or amountCUR is not null)
                                                                      then (nvl(AmountD_v,0)-nvl(amountCUR,0))
                                                                      else 0
                                                                      end);
                   nominalCostNEWD :=    (case when (NominalCostD_v is not null or nominalcostCUR is not null)
                                                                     then (nvl(NominalCostD_v,0)-nvl(nominalcostCUR,0))
                                                                     else 0
                                                                     end);


                   --Приводим в соответствие "движение" объекта - ПЕРЕДАЕМ ДЕЛЬТУ (на сколько изменится значение)
                   sm.ChangeMIOwnerObjState(
                                                       'Y', -- флаг, что процедура вызвана из ОД
                                                       ObjID,
                                                       d,     NVL(dBefore, d),  -- <<<
                                                       DocID,
                                                       (case when sharesNumberNEWD=0 then null else sharesNumberNEWD end),
                                                       (case when amountNEWD=0 then null else amountNEWD end),
                                                       (case when nominalCostNEWD=0 then null else nominalCostNEWD end),
                                                       MoveItemsID
                                                       );
               end if; -- конец если что-то изменилось
  		end if; -- конец корректировки ранее введенных значений

    -- если приобретение собственности----------------------
    else
								--Находим ID состояния на дату текущего изменения
                if (d <>  dBefore and sAction = 'U') then
												select count(*) into nTmp from sm.states st where  st.ID =  StateID;
												if (nTmp > 0) then
													select st.ID into curStateID from sm.states st where  st.ID = StateID;
												end if;
								else
												select count(*) into nTmp from sm.states st where   st.objects_id = ObjID and  st.calcdate = d;
												if (nTmp > 0) then
													select st.ID into curStateID from sm.states st where   st.objects_id = ObjID and  st.calcdate = d;
												end if;
								end if;

								--Изменяем состояние объекта на дату операции - ПЕРЕДАЕМ ЗНАЧЕНИЕ НОВОГО СОСТОЯНИЯ
								sm.ChangeMIObjState(
																			ObjID,
																			curStateID,
																			d,
																			DocID,
																			SharesNumberD_v,
																			AmountD_v,
																			NominalCostD_v,   --p. 30.11.2012   (case when nvl(NominalCostD_v,0) <> 0 then NominalCostD_v else nCost end),
																			MoveItemsID,
																			null);

    end if;  -- если отчуждение/приобретение собственности
  end if; -- конец if (nTmp = 21)
end;    --- END  ChangeObjStates
/
grant execute on SM.CHANGEOBJSTATES to SM_ALLUSERS;
grant execute on SM.CHANGEOBJSTATES to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGESTATE
prompt ==============================
prompt
create or replace procedure sm.ChangeState(OperTypeID in number,
                                                                 sAction in char,  -- вид действия ('I'-insert, 'U'-update, 'D'-delete)
                                                                 ObjID in number,  -- ID объекта 
                                                                 StateDate in date, -- дата состояния
                                                                 DocsetID in number, DocID in number,  -- пакет документов, ID документа
                                                                 SharesNumberPREV in numeric, SharesNumberD in numeric, SharesNumberNEW in numeric,  -- общее количество акций
                                                                 SharesPrevNumberPREV in numeric, SharesPrevNumberD in numeric, SharesPrevNumberNEW in numeric,  -- в т.ч. количество привилегированных акций
                                                                 NominalCostPREV in numeric, NominalCostD in numeric, NominalCostNEW in numeric,  -- номинальная стоимость, руб.
                                                                 GoldStockOwnerIDPREV in number, GoldStockOwnerIDNEW in number  -- ID владельца "Золотой акции"
                                                                 )
  as
--
-- XSGROUP ver. 4.7.5
-- Процедура сохраняет состояние объекта - ЮЛ
--
-- Количественные параметры представляют собой 
-- предыдущее значение (PREV), 
-- РАЗНИЦУ между новым и прежним значением (D)
-- и новое значение (NEW)
--
  curStateID number(27); --ID состояния на дату текущего изменения
  d DATE;
  nTmp number;
  newDocSets_ID number(27);

begin

   d:=trunc(StateDate);   

   --Проверки, чтобы значения не уходили в минус после совершения операции
   if (sAction<>'D') then
      if ((SharesNumberD is not null or nvl(SharesnumberPREV,0)<>0 or SharesnumberNEW is not null) and
         (nvl(SharesnumberPREV,0)+nvl(SharesNumberD,0)+nvl(SharesnumberNEW,0))<0
         ) then
           raise_application_error(-20101,'На дату операции ЮЛ имеет недостаточное количество выпущенных акций.' ||SharesnumberPREV||'<>'||SharesNumberD);
      end if;
      if ((SharesPrevNumberD is not null or nvl(SharesPrevNumberPREV,0)<>0 or SharesPrevNumberNEW is not null) and
         (nvl(SharesPrevNumberPREV,0)+nvl(SharesPrevNumberD,0)+nvl(SharesPrevNumberNEW,0))<0
         ) then
           raise_application_error(-20101,'На дату операции ЮЛ имеет недостаточное количество выпущенных привилегированных акций'||SharesPrevNumberPREV||'<>'||SharesPrevNumberD);
      end if;
      if ((NominalCostD is not null or nvl(NominalCostPREV,0)<>0 or NominalcostNEW is not null) and
         (nvl(NominalCostPREV,0)+nvl(NominalCostD,0)+nvl(NominalcostNEW,0))<0
         ) then
           raise_application_error(-20101,'На дату операции ЮЛ имеет недостаточную номинальную стоимость уставного (складочного) капитала (уставного фонда)');
      end if;
   end if;
   
   --Находим ID состояния на дату текущего изменения
   select count(*) into nTmp from sm.states st where st.objects_id = ObjID and st.calcdate = StateDate;
   if (nTmp > 0) then
      select st.ID into curStateID from sm.states st where st.objects_id = ObjID and st.calcdate = StateDate;
   end if;
  
    --Создаем DOCSET, если требуется
   if (DocsetID is null) then
       select sm.seqdocsets.nextval into newDocSets_ID from dual;
       insert into sm.docsets ds values(newDocSets_ID);
  
       --Если известен Документ, помещаем его в созданный DOCSET
       if (DocID is not null) then
         insert into sm.docset_members
           (docset_id, document_id, docrole_id)
         values
           (newDocSets_ID, DocID, 1);
       end if;
   end if;   

   if (curStateID is not null) then
       update sm.STATES
          set
             --CALCDATE =	d,		
             --DOCUMENTS_ID = nvl(DocsetID, newDocSets_ID), 
             SHARESNUMBER =           (case when (SharesnumberPREV is not null or nvl(SharesnumberD,0)<>0 or SharesnumberNEW is not null)
                                                         then (nvl(SharesnumberPREV,0)+nvl(SharesnumberD,0)+nvl(SharesnumberNEW,0))
                                                         else SHARESNUMBER
                                                         end),
             SHARESPREVNUMBER =     (case when (SharesPrevNumberPREV is not null or nvl(SharesPrevNumberD,0)<>0 or SharesPrevNumberNEW is not null)
                                                         then (nvl(SharesPrevNumberPREV,0)+nvl(SharesPrevNumberD,0)+nvl(SharesPrevNumberNEW,0))
                                                         else SHARESPREVNUMBER
                                                         end),
             NOMINALCOST =             (case when (NominalcostPREV is not null or nvl(NominalcostD,0)<>0 or NominalcostNEW is not null)
                                                         then (nvl(NominalcostPREV,0)+nvl(NominalcostD,0)+nvl(NominalcostNEW,0))
                                                         else NOMINALCOST
                                                         end),       
             GOLDSTOCKOWNER_ID =   (case when OperTypeID=8 
                                                        then GoldStockOwnerIDNEW  
                                                        else nvl(GoldStockOwnerIDNEW, nvl(GoldStockOwnerIDPREV, GOLDSTOCKOWNER_ID)) 
                                                        end) 
        where id = curStateID;
        
   else
       select sm.seqstates.nextval into curStateID from dual;

       insert into sm.STATES
         (ID, CALCDATE, DOCUMENTS_ID, OBJECTS_ID, SHARESNUMBER, SHARESPREVNUMBER, NOMINALCOST, GOLDSTOCKOWNER_ID)
       values
         (curStateID, d, nvl(DocsetID, newDocSets_ID), ObjID,
         (case when (SharesnumberPREV is not null or SharesnumberNEW is not null)
                                                         then (nvl(SharesnumberPREV,0)+nvl(SharesnumberNEW,0))
                                                         else SharesnumberD
                                                         end),
         (case when (SharesPrevNumberPREV is not null or SharesPrevNumberNEW is not null)
                                                         then (nvl(SharesPrevNumberPREV,0)+nvl(SharesPrevNumberNEW,0))
                                                         else SharesPrevNumberD
                                                         end),
         (case when (NominalcostPREV is not null or NominalcostNEW is not null)
                                                         then (nvl(NominalcostPREV,0)+nvl(NominalcostNEW,0))
                                                         else NominalcostD
                                                         end),         
         (case when OperTypeID=8 
                                                         then GoldStockOwnerIDNEW   
                                                         else nvl(GoldStockOwnerIDNEW, nvl(GoldStockOwnerIDPREV, null))
                                                         end) 
         );
         
   end if;

   --запомним ID для сохранения в OPERSHARES.STATES_ID
   sm.opershares_pkg.stateIDs(sm.opershares_pkg.stateIDs.count+1) := curStateID;

   --корректировка последующих состояний
   update
      sm.states
   set
      SHARESNUMBER =       (case when (SHARESNUMBER is not null or SharesnumberNEW is not null)
                                                    then (nvl(SHARESNUMBER,0)+nvl(SharesnumberNEW,0))
                                                    else SHARESNUMBER
                                                    end),
      SHARESPREVNUMBER = (case when (SHARESPREVNUMBER is not null or SharesPrevNumberNEW is not null)
                                                    then (nvl(SHARESPREVNUMBER,0)+nvl(SharesPrevNumberNEW,0))
                                                    else SHARESPREVNUMBER
                                                    end),
      NOMINALCOST =         (case when (NOMINALCOST is not null or NominalCostNEW is not null)
                                                    then (nvl(NOMINALCOST,0)+nvl(NominalCostNEW,0))
                                                    else NOMINALCOST
                                                    end),
      GOLDSTOCKOWNER_ID = (case when OperTypeID=8 
                                                   then GoldStockOwnerIDNEW  
                                                   else nvl(GoldStockOwnerIDNEW, nvl(GoldStockOwnerIDPREV, GOLDSTOCKOWNER_ID)) 
                                                   end)  
    where
      objects_id = ObjID and
      calcdate > d;

end;
/
grant execute on SM.CHANGESTATE to SM_ALLUSERS;
grant execute on SM.CHANGESTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure CHANGEORGSTATES
prompt ==================================
prompt
create or replace procedure sm.ChangeORGStates(
                                                                      OperTypeID in number,
                                                                      sAction in char,
                                                                      ObjID in number,
                                                                      StateDateNEW in date, StateDateOLD in date,
                                                                      DocsetID in number, DocID in number,
                                                                      SharesNumberNEW in numeric, SharesNumberOLD in numeric,
                                                                      SharesPrevNumberNEW in numeric, SharesPrevNumberOLD in numeric,
                                                                      NominalCostNEW in numeric, NominalCostOLD in numeric,
                                                                      GoldStockOwnerIDNEW in number
                                                                      )
   as
--
-- XSGROUP ver. 4.7.5
-- Процедура вызывает изменение состояний объекта -ЮЛ
--(количественных, изменяемых со временем свойств объекта)
--
-- Количественные параметры представляют собой новые и прежние (старые) значения Операции с УК.
--
  msgText varchar2(200);

  -- новые значения текущей операции
  sharesNumber_NEW number(27,6);
  sharesPrevNumber_NEW number(27,6);
  nominalCost_NEW number(27,2);

  -- прежние (старые) значения текущей операции
  sharesNumber_OLD number(27,6);
  sharesPrevNumber_OLD number(27,6);
  nominalCost_OLD number(27,2);

  -- предыдущие значения до даты текущей операции
  sharesNumber_PREV number(27,6);
  sharesPrevNumber_PREV number(27,6);
  nominalCost_PREV number(27,2);
  goldstockownerID_PREV number(27);

  --РАЗНИЦА между прежним и новым значением
  sharesNumber_DEV number(27,6);
  sharesPrevNumber_DEV number(27,6);
  nominalCost_DEV number(27,2);
  --
  curOperTypeID number(27);  -- ID текущей операции
  date_PREV date;                  -- дата предыдущего состояния

begin

  sharesNumber_NEW := SharesNumberNEW;
  sharesPrevNumber_NEW := SharesPrevNumberNEW;
  nominalCost_NEW := NominalCostNEW;

  sharesNumber_OLD := SharesNumberOLD;
  sharesPrevNumber_OLD := SharesPrevNumberOLD;
  nominalCost_OLD := NominalCostOLD;

  --Если "расходные" операции
  if (OperTypeID in (4,6,11)) then
     if (sharesNumber_NEW is not null) then
        sharesNumber_NEW := sharesNumber_NEW*(-1);
     end if;
     if (sharesNumber_OLD is not null) then
        sharesNumber_OLD := sharesNumber_OLD*(-1);
     end if;

     if (sharesPrevNumber_NEW is not null) then
        sharesPrevNumber_NEW := sharesPrevNumber_NEW*(-1);
     end if;
     if (sharesPrevNumber_OLD is not null) then
        sharesPrevNumber_OLD := sharesPrevNumber_OLD*(-1);
     end if;

     if (nominalCost_NEW is not null) then
        nominalCost_NEW := nominalCost_NEW*(-1);
     end if;
     if (nominalCost_OLD is not null) then
        nominalCost_OLD := nominalCost_OLD*(-1);
     end if;
  end if;

  if (OperTypeID=7 and sAction='D') then
    -- Удаление операции "выпуск золотой акции" подобно операции "погашение золотой акции"
    curOperTypeID := 8;
  else
    curOperTypeID := OperTypeID;
  end if;

  ----------------------------------------
  -- Insert операции с УК
  if (sAction = 'I') then
      date_PREV := StateDateNEW;


  -- Update операции с УК
  elsif (sAction = 'U' ) then

      -- дата предыдущего состояния (<=  date_PREV)
      if (StateDateNEW > StateDateOLD        -- если сдвиг даты вперед
         OR StateDateNEW = StateDateOLD    -- или дата не изменилась
         ) then
          date_PREV := StateDateOLD;
      else                                                -- если сдвиг даты назад
          date_PREV := StateDateNEW;
      end if;

      -- Поиск предыдущего значения с "золотой акцией" (до даты операции)
      for xxST in (
                        select * from sm.states st
                          where
                            st.objects_id = ObjID and
                            st.calcdate < date_PREV
                          order by st.calcdate DESC
                       )
      loop    
          if (xxST.sharesNumber is not null or
             xxST.sharesPrevNumber is not null or
             xxST.nominalCost is not null or
             xxST.GOLDSTOCKOWNER_ID is not null)    
          then      
             goldstockownerID_PREV := xxST.GOLDSTOCKOWNER_ID;
             exit;
          end if;
      end loop;

      -- отмена прежних значений операции начиная со следующего состояния
      update
        sm.states
      set
        SHARESNUMBER =       (case when (SHARESNUMBER is not null or sharesNumber_OLD is not null)
                                                      then (nvl(SHARESNUMBER,0) - nvl(sharesNumber_OLD,0))
                                                      else SHARESNUMBER
                                                      end),
        SHARESPREVNUMBER = (case when (SHARESPREVNUMBER is not null or sharesPrevNumber_OLD is not null)
                                                      then (nvl(SHARESPREVNUMBER,0) - nvl(sharesPrevNumber_OLD,0))
                                                      else SHARESPREVNUMBER
                                                      end),
        NOMINALCOST =         (case when (NOMINALCOST is not null or nominalCost_OLD is not null)
                                                      then (nvl(NOMINALCOST,0) - nvl(nominalCost_OLD,0))
                                                      else NOMINALCOST
                                                      end),
        GOLDSTOCKOWNER_ID = nvl(goldstockownerID_PREV,GOLDSTOCKOWNER_ID)
      where
        objects_id = ObjID and
        calcdate >= StateDateOLD;

  -- Delete операции с УК
  else

      -- для операций с "золотой акцией"
      if (curOperTypeID = 7) then
          goldstockownerID_PREV := null;
      elsif (curOperTypeID = 8) then
          -- Поиск предыдущего значения (до даты операции)
          for xxST in (
                            select * from sm.states st
                              where
                                st.objects_id = ObjID and
                                st.calcdate < StateDateOLD
                              order by st.calcdate DESC
                           )
          loop
              if (xxST.sharesNumber is not null or
                  xxST.sharesPrevNumber is not null or
                  xxST.nominalCost is not null or
                  xxST.GOLDSTOCKOWNER_ID is not null)    
              then      
                 goldstockownerID_PREV := xxST.GOLDSTOCKOWNER_ID;
                 exit;
              end if;
          end loop;
      end if; -- end  для операций с "золотой акцией"

      -- отмена прежних значений операции
      update
        sm.states
      set
        SHARESNUMBER =       (case when (SHARESNUMBER is not null or sharesNumber_OLD is not null)
                                                      then (nvl(SHARESNUMBER,0) - nvl(sharesNumber_OLD,0))
                                                      else SHARESNUMBER
                                                      end),
        SHARESPREVNUMBER = (case when (SHARESPREVNUMBER is not null or sharesPrevNumber_OLD is not null)
                                                      then (nvl(SHARESPREVNUMBER,0) - nvl(sharesPrevNumber_OLD,0))
                                                      else SHARESPREVNUMBER
                                                      end),
        NOMINALCOST =         (case when (NOMINALCOST is not null or nominalCost_OLD is not null)
                                                      then (nvl(NOMINALCOST,0) - nvl(nominalCost_OLD,0))
                                                      else NOMINALCOST
                                                      end),
      GOLDSTOCKOWNER_ID = (case when OperTypeID=7
                                                   then null
                                                   else nvl(goldstockownerID_PREV,GOLDSTOCKOWNER_ID)
                                                   end)
      where
        objects_id = ObjID and
        calcdate >= StateDateOLD;  -- начиная с текущего состояния

      return; -- все, выход !!!

  end if; -- end if sAction
  ----------------------------------------
  if (sAction <> 'D') then
      -- Поиск предыдущего значения (до даты операции)
      for xxST in (
        select
          st.SHARESNUMBER as SHARESNUMBER,
          st.SHARESPREVNUMBER as SHARESPREVNUMBER,
          st.NOMINALCOST as NOMINALCOST,
          st.GOLDSTOCKOWNER_ID as GOLDSTOCKOWNER_ID
        from
          sm.states st
        where
          st.objects_id = ObjID and
          st.calcdate <= date_PREV
        order by st.calcdate DESC
                 )
      loop
          sharesNumber_PREV := xxST.SHARESNUMBER;
          sharesPrevNumber_PREV := xxST.SHARESPREVNUMBER;
          nominalCost_PREV := xxST.NOMINALCOST;
          if (curOperTypeID <> 7) then
             goldstockownerID_PREV := xxST.GOLDSTOCKOWNER_ID;
          else
             goldstockownerID_PREV := null;
          end if;

          if (xxST.sharesNumber is not null or
              xxST.sharesPrevNumber is not null or
              xxST.nominalCost is not null or
              xxST.GOLDSTOCKOWNER_ID is not null)    
          then                              
             exit;
          end if;
      end loop;

      --Проверки допустимости совершения операций
      if (sAction<>'D') then
        if (curOperTypeID=4 and nvl(nominalCost_PREV,0)<=0) then
           raise_application_error(-20101,'Невозможно выполнить операцию погашения,' ||chr(13) ||
                                                    'т.к. на дату операции не сформирован уставный (складочный) капитал (уставный фонд) ЮЛ');
        end if;
        if (curOperTypeID in (5,6,10,11) and nvl(nominalCost_PREV,0)<=0) then
           if (curOperTypeID in (6,11)) then
             msgText := 'Невозможно выполнить операцию уменьшения';
           else
             msgText := 'Невозможно выполнить операцию увеличения';
           end if;
           if (curOperTypeID in (5,10)) then
             msgText := msgText||' номинальной стоимости';
           else
             msgText := msgText||' уставного фонда';
           end if;
           raise_application_error(-20101, msgText ||',' ||chr(13) ||
                                                    'т.к. на дату операции не сформирован уставный (складочный) капитал (уставный фонд) ЮЛ');
        end if;
      end if;

      --Изменение состояния объекта на дату операции
      sm.ChangeState(curOperTypeID,
                             sAction,
                             ObjID,
                             StateDateNEW,
                             DocsetID, DocID,
                             SharesNumber_PREV, sharesNumber_DEV, SharesNumber_NEW,
                             SharesPrevNumber_PREV, sharesPrevNumber_DEV, SharesPrevNumber_NEW,
                             NominalCost_PREV, nominalCost_DEV, NominalCost_NEW,
                             GoldStockOwnerID_PREV, GoldStockOwnerIDNEW);

  end if;     -- end if (sAction<>'D')

end;
/
grant execute on SM.CHANGEORGSTATES to SM_ALLUSERS;
grant execute on SM.CHANGEORGSTATES to SM_ALL_SELECT;


prompt
prompt Creating procedure CLEANFROMDATE
prompt ================================
prompt
create or replace procedure sm.CleanFromDate(AMoveSet in number, AobligType in number, Adate date)
is
----------------------------------------------- 13.09.2013 -------------------------------------------------------------------------------------------------------------------------
--- Подчистка результатов прежних насчислений после какой-то даты. ---

--- Служит для устранения проблем с остающимися от прежних расчетов данными, 
--         которые не удается "опознать" и при необходимости удалить основным алгоритмом расета
--         (который и так по этому как-раз поводу сильно усложнен).

--- Применяется при разовых принудительных пересчетах обязательств, типа - при оформлении льгот либо отсрочек 
--        (что может иметь место задним числом).   

--- По сути таким образом -  реализация "тотального" удаления начислений, 
--   НО:
--       - Только с оределенной даты
--       - Только в определенных случаях (а ни в коем случае не еженочьно)
--       - С учетом закрытости периода (т.е. где надо - со сторнированием) (<<< -- Реализуется в триггере  CHARGES_ACC_DELETE)
--- Удаление при этом производится не точно с указанной даты, а с начала периода начислений в который попадает данная дата.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  dDate date ;
	pType char(1);
  c number(27);
BEGIN
          begin
               -- Находим тип периоичности и далее - первую дату периода
               Select pd.periodical into pType 
               from sm.paydocs pd 
               where pd.obligationtype_id = AobligType 
               and pd.moveperiod_id = (Select max(mp.ID) from sm.moveperiods mp where mp.moveset_id = AMoveSet and Adate between  mp.sincedate 
               and nvl(mp.enddate, to_date( '01.01.3000','dd.MM.yyyy'))  );
    			       
          exception 
          --- 28.04.2014 Morozova   в случае, когда льгота или отсрочка начинаются ранее даты начала ОД, то запрос ничего не возвращает
          --- следовательно, выбираем тип периодичности самого первого периода ОД
          when no_data_found then
                   --- 12.05.2014 Morozova   при удалении ОД не находит ИД периодов, если имеется отсрочка/льгота ранее даты начала ОД
                   ---select sm.getmovesetsincedate(AMoveSet) into dDate from dual;
                   
                   -- 26.03.2015 Zaitsev находим первый период, в котором начинается обязательство со льготой, а не просто 1й период ОД
                   -- т.к. в первом периоде ОД может и не быть обязательства со льготой, и тогда опять NO_DATA_FOUND
                   select min(mp.sincedate) into dDate from sm.moveperiods mp, sm.paydocs pd where mp.moveset_id=AMoveSet and mp.id=pd.moveperiod_id
                                            and pd.obligationtype_id=AobligType;
                                            
                   Select count(mp.ID) into c from sm.moveperiods mp where mp.moveset_id = AMoveSet
                                      and dDate between  mp.sincedate and nvl(mp.enddate, to_date( '01.01.3000','dd.MM.yyyy'));
                                      
                   if c > 0 and dDate >= Adate then    --- 05.06.2014 Morozova                   
                       Select pd.periodical into pType
                       from sm.paydocs pd
                       where pd.obligationtype_id = AobligType
                       and pd.moveperiod_id = (Select mp.ID from sm.moveperiods mp where mp.moveset_id = AMoveSet
                                      and dDate between  mp.sincedate and nvl(mp.enddate, to_date( '01.01.3000','dd.MM.yyyy')));                     
                   end if;
          end;
       
					dDate := sm.charging_pkg.GetPeriodFirstDay(pType, Adate);

					-- Удаляем все начисления после даты начала периода, в который попадает указанная дата:
					Delete from sm.charges ch where ch.movesets_id = AMoveSet and ch.obligationtype_id = AobligType and ch.finedate >= dDate and ch.document_id is null;

END; -- CleanFromDate;
/
grant execute on SM.CLEANFROMDATE to SM_ALLUSERS;
grant execute on SM.CLEANFROMDATE to SM_ALL_SELECT;


prompt
prompt Creating procedure CLOSEMOVE
prompt ============================
prompt
create or replace procedure sm.closemove(MoveTypeID in number, ObjID in number , CloseDate in date) is
--
-- XSGROUP ver. 25.01.2013
-- процедура закрывает предыдущее движение указанного типа для указанного объекта,
-- если в периоде движения участвует несколько объектов,
-- открывается новый период движения и оставшиеся движения объектов переносятся в него
-- применяется только для тех операций движения, у которых дата начала более ранняя, чем CloseDate
--
  cnt           integer;
  NewDocSetID   number;
  NewPeriodID   number;
  NewMoveItemID number;
  ExprStr       varchar2(4000);
  CurUserName   sm.registeredusers.fullname%type;
  CloseDateStr  varchar2(30);
  ----------
  function GetInsertExpr(SeqvName in varchar2, TableName in varchar2, ID_Value in number) return varchar2
  is
    str varchar2(4000);
  begin
    str:='insert into '||'sm.'||TableName||' select sm.'||SeqvName||'.nextval, '||chr(10);
    for xx in (select
                 atc.column_name
               from
                 all_tab_columns atc
               where
                 atc.table_name=Upper(TableName) and
                 atc.owner='SM' and
                 atc.column_name<>'ID'
               order by
                 atc.column_id)
    loop
      str:=str||xx.column_name||','||chr(10);
    end loop;
      -- убираем последнюю запятую
      str:=SUBSTR(str,1,length(str)-2);
      str:=str||' from '||Upper(TableName)||' where ID='||to_char(ID_Value);
      return(str);
  end GetInsertExpr;
  -----------
  function GetNewDSID(OldDSID in number) return number
  is
    NewDSID number;
  begin
    -- создаём новый доксет
    insert into sm.docsets values (sm.seqdocsets.nextval);
    select sm.seqdocsets.currval into NewDSID from dual;

    -- переносим в него документы из старого доксета
    for old_dsm in (select
                      dsm.*
                   from
                      sm.docset_members dsm
                   where
                      dsm.docset_id=OldDSID
                   )
    loop
      insert into sm.docset_members dsm values (NewDSID,old_dsm.document_id,old_dsm.docrole_id);
    end loop;

    return(NewDSID);
  end GetNewDSID;
  ------------
  function GetCorrectedUserName return varchar2 
  is
    FullUserName sm.registeredusers.fullname%type;
    len integer;
  begin
    select
      atc.DATA_LENGTH
    into
      len
    from
      all_tab_columns atc
    where
      atc.OWNER='SM' and
      atc.TABLE_NAME='MOVEPERIODS' and
      atc.COLUMN_NAME='CHANGEDBY';  
  
   SELECT ru.FullName INTO FullUserName FROM RegisteredUsers ru WHERE ru.UserName=USER;
   
   return(SUBSTR(FullUserName,1,len));
  
  end GetCorrectedUserName;
  ------------
  procedure CloseDirectMovements is
  -- закрывает движения объектов, оформленные непосредственно с текущим объектом
  -- учитываются только объекты, не входящие в имущественный комплекс
  -- ищем движения данного объекта, чъи периоды начинаются с даты закрытия
  -- (они образуются автоматически при удалении первого объекта из ОД)
  begin
    for xx in (select 
                 mv.* 
               from 
                 sm.movements mv 
               where 
                 mv.OBJECTS_ID=ObjID and 
                 mv.MoveType_ID=MoveTypeID and
                 mv.MV_OBJECTS_ID is null and 
                 mv.POSTINGDATE=CloseDate
               )
    loop             
      if sm.getmovesetsincedate(xx.moveset_id)<=CloseDate-1 then
        -- удаляем движение объекта
        delete from sm.Moveitems mi where mi.id=xx.id;
        -- имеются ли ещё движения объектов в этом периоде?
        select count(mi.id)
        into cnt
        from
          sm.moveperiods mp,
          sm.moveitems mi
        where
          mp.id=mi.moveperiod_id and
          mp.id=xx.moveperiod_id;
        -- если нет - удаляем период
        if cnt=0 then
          delete from sm.moveperiods mp where mp.id=xx.moveperiod_id;
        end if;
      end if;
    end loop;
    
    -- ищем движения объекта, чьи периоды заканчиваются позже даты закрытия
    -- учитываются только объекты, не входящие в имущественный комплекс
    for yy in  (select
                  mi.*,
                  ms.id msid,
                  mp.docset_id dsid
                from
                  sm.movesets ms,
                  sm.moveperiods mp,
                  sm.moveitems mi
                where
                  mp.moveset_id = ms.ID and
                  mi.moveperiod_id = mp.id and
                  ms.MoveType_ID=MoveTypeID and
                  mi.object_id=ObjID and
                  (mp.enddate is null or mp.enddate > CloseDate-1)
                )         
    loop
      if sm.getmovesetsincedate(yy.msid)<=CloseDate-1 then
        -- проверим, назначены ли обязательства в этом периоде
        select count(*) into cnt from sm.paydocs pd where pd.moveperiod_id=yy.moveperiod_id;
        if cnt<>0 then
          raise_application_error(-20101,'Невозможно выполнить требование политики операций - закрыть предыдущее движение объекта.'||chr(10)||'Обнаружены назначенные обязательства.'||
                   chr(10)||'Необходимо будет закрыть предыдущее движение вручную.');
        end if;
        -- закрываем период
        update sm.moveperiods set enddate = CloseDate-1 where id=yy.moveperiod_id;
        NewPeriodID:=0;
        -- оставшиеся объекты (если они есть) переносим в новый период
        for zz in (select mi.*
                     from
                       sm.moveitems mi
                     where
                       mi.object_id<>ObjID and
                       mi.moveperiod_id=yy.moveperiod_id
                  )
        loop
          if NewPeriodID=0 then
            -- создаём новый пакет документов и переносим в него документы из текущего периода
            NewDocSetID:=GetNewDSID(yy.dsid);
            -- создаём новый период движения
            ExprStr:=GetInsertExpr('SEQMOVEPERIODS','MOVEPERIODS',yy.moveperiod_id)||chr(10);
            Dbms_Output.put_line(ExprStr);
            ExprStr:=REPLACE(ExprStr,'DOCSET_ID',to_char(NewDocSetID));
            ExprStr:=REPLACE(ExprStr,'SINCEDATE',chr(39)||CloseDateStr||chr(39));
            ExprStr:=REPLACE(ExprStr,'ENDDATE','null');
            ExprStr:=REPLACE(ExprStr,'PREV_MOVEPERIOD_ID',to_char(yy.moveperiod_id));
            ExprStr:=REPLACE(ExprStr,'CHANGEDBY',chr(39)||CurUserName||chr(39));
            ExprStr:=REPLACE(ExprStr,'WRITEDATE','sysdate');
    
            sm.update_db_pkg.DoSQL(ExprStr);
            select sm.seqmoveperiods.currval into NewPeriodID from dual;
          end if;
          -- переносим объекты в новый период
          ExprStr:=GetInsertExpr('SEQMOVEITEMS','MOVEITEMS',zz.id)||chr(10);
          ExprStr:=REPLACE(ExprStr,'MOVEPERIOD_ID',to_char(NewPeriodID));
          sm.update_db_pkg.DoSQL(ExprStr);
          select sm.Seqmoveitems.currval into NewMoveItemID from dual;
          -- вносим записи в таблицу objectusing
          for old_ou in (select *
                         from
                           sm.objectusing ou
                         where
                           ou.moveitem_id=zz.id
                        )
          loop
            ExprStr:=GetInsertExpr('SEQOBJECTUSING','OBJECTUSING',zz.id)||chr(10);
            ExprStr:=REPLACE(ExprStr,'MOVEITEM_ID',to_char(NewMoveItemID));
            ExprStr:=REPLACE(ExprStr,'where ID=','where MOVEITEM_ID=');
            sm.update_db_pkg.DoSQL(ExprStr);
          end loop;
        end loop;
      end if;  
    end loop;
  end; -- CloseDirectMovements;
  ------------
  procedure CloseCP_ItemsMovements is
  -- закрывает движения объектов, оформленные через участие в составе имущественного комплекса
  -- ищем движения данного объекта, чъи периоды начинаются с даты закрытия
  -- (они образуются автоматически при закрытия движения первого объекта из имущественного комплекса)
  begin
    for xx in (select
                 mv.*
               from
                 sm.movements mv
               where
                 mv.MV_OBJECTS_ID=ObjID and
                 mv.MoveType_ID=MoveTypeID and
                 mv.POSTINGDATE=CloseDate
               )  
    loop
      delete from sm.Links_Mi_Objects lmo where lmo.moveitems_id=xx.moveitem_id and lmo.objects_id=ObjID;
    end loop;
    
    -- ищем движения объекта, чьи периоды заканчиваются позже даты закрытия
    -- учитываются только объекты, входящие в имущественный комплекс
    for yy in  (select
                  mv.*,
                  mp.docset_id dsid
                from
                  sm.movements mv,
                  sm.moveperiods mp
                where
                  mv.MV_OBJECTS_ID=ObjID and
                  mv.MoveType_ID=MoveTypeID and
                  mv.MovePeriod_ID=mp.id and
                 (mv.enddate is null or mv.enddate > CloseDate-1)     
                )         
    loop
      if sm.getmovesetsincedate(yy.moveset_id)<=CloseDate-1 then
        -- проверим, назначены ли обязательства в этом периоде
        select count(*) into cnt from sm.paydocs pd where pd.moveperiod_id=yy.moveperiod_id;
        if cnt<>0 then
          raise_application_error(-20101,'Невозможно выполнить требование политики операций - закрыть предыдущее движение объекта.'||chr(10)||'Обнаружены назначенные обязательства.'||
                   chr(10)||'Необходимо будет закрыть предыдущее движение вручную.');
        end if;
        -- закрываем период
        update sm.moveperiods set enddate = CloseDate-1 where id=yy.moveperiod_id;
        NewPeriodID:=0;
        -- оставшиеся объекты (т.е. имущественный комплекс-контейнер для данного объекта) переносим в новый период
        for zz in (select mi.*
                     from
                       sm.moveitems mi
                     where
                       mi.object_id<>ObjID and
                       mi.moveperiod_id=yy.moveperiod_id
                  )
        loop
          if NewPeriodID=0 then
            -- создаём новый пакет документов и переносим в него документы из текущего периода
            NewDocSetID:=GetNewDSID(yy.dsid);
            -- создаём новый период движения
            ExprStr:=GetInsertExpr('SEQMOVEPERIODS','MOVEPERIODS',yy.moveperiod_id)||chr(10);
            Dbms_Output.put_line(ExprStr);
            ExprStr:=REPLACE(ExprStr,'DOCSET_ID',to_char(NewDocSetID));
            ExprStr:=REPLACE(ExprStr,'SINCEDATE',chr(39)||CloseDateStr||chr(39));
            ExprStr:=REPLACE(ExprStr,'ENDDATE','null');
            ExprStr:=REPLACE(ExprStr,'PREV_MOVEPERIOD_ID',to_char(yy.moveperiod_id));
            ExprStr:=REPLACE(ExprStr,'CHANGEDBY',chr(39)||CurUserName||chr(39));
            ExprStr:=REPLACE(ExprStr,'WRITEDATE','sysdate');
    
            sm.update_db_pkg.DoSQL(ExprStr);
            select sm.seqmoveperiods.currval into NewPeriodID from dual;
          end if;
          -- переносим объекты в новый период
          ExprStr:=GetInsertExpr('SEQMOVEITEMS','MOVEITEMS',zz.id)||chr(10);
          ExprStr:=REPLACE(ExprStr,'MOVEPERIOD_ID',to_char(NewPeriodID));
          sm.update_db_pkg.DoSQL(ExprStr);
          select sm.Seqmoveitems.currval into NewMoveItemID from dual;
          -- вносим записи в таблицу objectusing
          for old_ou in (select *
                         from
                           sm.objectusing ou
                         where
                           ou.moveitem_id=zz.id
                        )
          loop
            ExprStr:=GetInsertExpr('SEQOBJECTUSING','OBJECTUSING',zz.id)||chr(10);
            ExprStr:=REPLACE(ExprStr,'MOVEITEM_ID',to_char(NewMoveItemID));
            ExprStr:=REPLACE(ExprStr,'where ID=','where MOVEITEM_ID=');
            sm.update_db_pkg.DoSQL(ExprStr);
          end loop; --for old_o
          -- переносим в список объектов имущественного комплекса все объекты, кроме текущего
          for lmo_list in (select mio.objects_id
                           from
                             sm.links_mi_objects mio
                           where
                             mio.moveitems_id=zz.id and
                             mio.objects_id<>ObjID  
                           )
          loop
            insert into sm.links_mi_objects (moveitems_id,objects_id) values (NewMoveItemID,lmo_list.objects_id);                
          end loop; --for lmo_list
        end loop; --for zz
      end if;  
    end loop; --for yy
  end; --CloseCP_ItemsMovements;  
  ------------  
begin

  CloseDateStr:=to_char(CloseDate,'DD.MM.YYYY');
  
  -- укоротим полное имя пользователя до размерности поля CHANGEDBY таблицы MOVEPERIODS
  CurUserName:=GetCorrectedUserName;
  -- закроем все движения, оформленные непосредственно на данный объект
  CloseDirectMovements;
  -- закроем все движения, распространённые на данный объект через вхождение его в имущ. комплекс
  CloseCP_ItemsMovements;
  
end;
/
grant execute on SM.CLOSEMOVE to SM_ALLUSERS;
grant execute on SM.CLOSEMOVE to SM_ALL_SELECT;


prompt
prompt Creating procedure CLOSE_SOC_NAIM
prompt =================================
prompt
create or replace procedure sm.Close_soc_naim(Flag char) is
 Aenddate date;
begin
   -- получим объекты у которых открыт соц найм
   for xxx in (
               select mp.id as movepriod_id,
                      mp.sincedate,
                      mi.object_id
                 from sm.movesets ms
                 join sm.moveperiods mp on mp.moveset_id = ms.id
                 join sm.moveitems mi on mi.moveperiod_id = mp.id
                where ms.movetype_id = 27 -- соц найм
                  and mp.enddate is null -- с открытым периодом
                  --and mi.object_id = 22037
               )
   loop
     -- найдем по данному объекту собственность 5100
     -- собсвтенность должна быть закрыта
     Aenddate := NULL;
     begin
       select mp.enddate
         into Aenddate
         from sm.movesets ms
         join sm.moveperiods mp on mp.moveset_id = ms.id
         join sm.moveitems mi on mi.moveperiod_id = mp.id
        where ms.movetype_id = 1 -- собственность
          and mp.enddate is not null -- с закрытым периодом
          and mp.sincedate <= xxx.sincedate -- периоды соц найма и собсвенности перессекаются
          and mp.enddate >= xxx.sincedate
          and mi.object_id = xxx.object_id -- наш объект
          and ms.client_id = 5100 -- наш собственник
          and rownum <= 1;
        exception
        when NO_DATA_FOUND then
        null;
     end;
     -- если находим такую собственность
     if (Aenddate is not null) then
        -- поментим что изменили
        update sm.moveperiods mp
           set mp.enddate_old = sysdate
         where mp.id = xxx.movepriod_id;
        -- выставим новое
        update sm.moveperiods mp
           set mp.enddate = Aenddate
         where mp.id = xxx.movepriod_id;
     end if;
   end loop;
end Close_soc_naim;
/
grant execute on SM.CLOSE_SOC_NAIM to SM_ALL_SELECT;


prompt
prompt Creating procedure CREATEBACKUPSCRIPT
prompt =====================================
prompt
create or replace procedure sm.CreateBackUpScript(AObjName in varchar2, APthName in varchar2) is
  ScriptText CLOB;
  IsExists char(1);
  NewName varchar2(100);
begin

  -- by XS_GROUP, 03.10.2008
  -- процедура делает резервную копию 
  -- процедуры, функции, пакета или триггера БД
  -- и сохраняет скрипт в таблице X_BACKUPS

  NewName:=UPPER(TRIM(AObjName));

  ScriptText:='';
  for x in (SELECT distinct type
             FROM user_source
             WHERE
               name = NewName
             ORDER BY type)
  loop
    IsExists:='N';
    ScriptText:=ScriptText||'create or replace ';
    for xx in (SELECT line, text
               FROM user_source
               WHERE
                  name = NewName and
                  type=x.type
               ORDER BY line)
    loop

     IsExists:='Y';
     ScriptText:=ScriptText||xx.text;

    end loop;

    if IsExists <>'N' then
      ScriptText:=ScriptText||'/'||chr(13)||chr(13);
    end if;
  end loop;
  if ScriptText is not null then
    insert into sm.X_BACKUPS (backup_date, pth_name, name, script) values (sysdate,APthName,NewName,ScriptText);
    commit;
  end if;

end CreateBackUpScript;
/
grant execute on SM.CREATEBACKUPSCRIPT to SM_ALL_SELECT;


prompt
prompt Creating procedure CREATE_MASS_BUDG
prompt ===================================
prompt
create or replace procedure sm.CREATE_MASS_BUDG(Flag in varchar2) is
begin
 /*
 Необходимо автоматически принять к Бюджетному учету (создать операцию движения «Бюджетный учет») объекты c оформленной на
 них операцией движения КАЗНА, где целевое назначение операции взято из ветки РЕЕСТР \ ЖИЛИЩНЫЙ ФОНД, по следующему
 алгоритму:
      - Если объект находится в собственности (оформлена операция движения «Собственность») МО г. Краснодар до 30.09.2010
      включительно, то основанием для принятия к учету будет Документ: «Справка от 30.09.2010». При этом на объект должна
      быть оформлена операция движения Казна (действующая, период открытия не важен). Начало периода операции движения
      «Бюджетный учет» будет равно 30.09.2010. Дата закрытия – отсутствует.
*/
 for
     xxx in (
              select b.objects_id,
                     b.square
                from buildings b
               where /*b.buildtypes_id = 41 --квартиры
                 and*/ exists (
                              select *
                                 from moveitems mi
                                 join moveperiods mp on mp.id = mi.moveperiod_id
                                 join movesets ms on ms.id = mp.moveset_id
                                where mi.object_id = b.objects_id
                                  and ms.movetype_id = 1 --собственность
                                  and mp.sincedate <= '30.09.2010'
                                  and mp.enddate is null
                                  and ms.client_id = 5100 --МО Краснодар
                             )
                  and exists (
                              select *
                                 from moveitems mi
                                 join moveperiods mp on mp.id = mi.moveperiod_id
                                 join movesets ms on ms.id = mp.moveset_id
                                where mi.object_id = b.objects_id
                                  and ms.movetype_id = 10 --казна
                                  --and mp.sincedate <= '30.09.2010'
                                  and mp.enddate is null
                                  and ms.client_id = 5100 --МО Краснодар
                                  and mi.leasepurpose_id in (5230,2993,2121,2142,2163,2243,2524)
                             )
                  and not exists (
                              select *
                                 from moveitems mi
                                 join moveperiods mp on mp.id = mi.moveperiod_id
                                 join movesets ms on ms.id = mp.moveset_id
                                where mi.object_id = b.objects_id
                                  and ms.movetype_id = 29 --бюджетный учет
                                  --and mp.sincedate <= '30.09.2010'
                                  and mp.enddate is null
                                  and ms.client_id = 5100 --МО Краснодар
                             )
     )
   loop
      insert into sm.docsets (id)
           values (sm.seqdocsets.nextval);
      insert into sm.docset_members (docset_id,document_id,docrole_id)
           values (sm.seqdocsets.currval, 2807626, 1);--Справка от 30.09.2010

      -- 29 - Бюджетный учет
      -- 5100 МО .г Краснодар
      -- 421 - Муниципальная собственность
      insert into sm.movesets (id,movetype_id,client_id,docset_id,transferbasis_id,sharemove_id,hideinreports,verified,munreport_id)
           values (sm.seqmovesets.nextval, 29, 5100, sm.seqdocsets.currval, 421, NULL, 'N', 'Y', NULL);

      insert into sm.moveperiods (id,sincedate,enddate,moveset_id,docset_id,prev_moveperiod_id,changedby,writedate)
          values (sm.seqmoveperiods.nextval, '30.09.2010', NULL, sm.seqmovesets.currval, sm.seqdocsets.currval ,null ,USER ,sysdate);
      -- 5182 - жилые помещения
      insert into sm.MoveItems (id,object_id,moveperiod_id,leasepurpose_id,square,params,share_num,share_denom,price,state_id)
           values (sm.seqmoveitems.nextval,xxx.objects_id, sm.seqmoveperiods.currval, 5182,xxx.square,NULL,1,1,NULL,NULL);

      insert into sm.object_position (client_id,object_id,movetype_id) values (5100,xxx.objects_id,29);
      --вставим связку с ОД для дочерних элементов квартир, которые не являются квартирами
      for yyy in (
                  select b.objects_id
                    from buildings b
                   where exists (select * from buildings b2 where b2.id = b.basebuilding and b2.objects_id = xxx.objects_id)
                     and b.buildtypes_id <> 41
                  )
      loop
        insert into sm.object_position (client_id,object_id,movetype_id) values (5100,yyy.objects_id,29);
      end loop;
  end loop;

end CREATE_MASS_BUDG;
/
grant execute on SM.CREATE_MASS_BUDG to SM_ALL_SELECT;


