prompt
create or replace procedure sm.create_od2022Kazna(Aobject_id in number, Aclient_id in number, Amovetype_id in number, Asincedate in date, Adocument_id in number, Atransferbasis_id in number, Aaccount_zabuch varchar, id_import number) is
  adocset_id number(27);
  amoveset_id number(27);
  amoveperiods_id number(27);
begin
  -- создадим ОД
  ---------------------------------------------------------------------------------------------------------
  -- создадим пакет
  adocset_id := NULL;
  select sm.seqdocsets.nextval
    into adocset_id
    from dual;
  insert into sm.docsets (id)
       values (adocset_id);
  insert into sm.docset_members (docset_id, document_id, docrole_id)
      values (adocset_id, Adocument_id, 1);

  amoveset_id := NULL;
  select sm.seqmovesets.nextval
    into amoveset_id
    from dual;
  insert into sm.movesets(id, movetype_id, client_id, docset_id, transferbasis_id, id_import)
       values (amoveset_id, Amovetype_id, Aclient_id, adocset_id, Atransferbasis_id, id_import);


   -- создадим период ОД
   Amoveperiods_id := NULL;
