     into Amoveperiods_id
     from dual;
   insert into sm.moveperiods (id, moveset_id, sincedate, docset_id, account_zabuch, id_import)
        values (Amoveperiods_id, amoveset_id, Asincedate, adocset_id, Aaccount_zabuch, id_import);

   -- вставим объект
   insert into sm.moveitems(id, object_id, moveperiod_id, id_import)
        values (sm.seqmoveitems.nextval, Aobject_id, amoveperiods_id, id_import);
        
            /*exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(Aobject_id));
            end;*/
   ---------------------------------------------------------------------------------------------------------
end create_od2022Kazna;
/

