prompt
prompt Creating procedure CREATE_OD_IMPORT
prompt ===================================
prompt
create or replace procedure sm.create_od_import(Flag in char, id_movetype in number, documents_id in number, base in varchar2, id_base_default in number,  id_client in number, id_object in number, sincedate in date, id_import in number) is
  adocset_id number(27);
  amoveset_id number(27);
  transferbasis_id number(27);
  amoveperiods_id number(27);
begin
  -- создадим ОД Баланс
  ---------------------------------------------------------------------------------------------------------
  -- создадим пакет
  adocset_id := NULL;
  select sm.seqdocsets.nextval
    into adocset_id
    from dual;
  insert into sm.docsets (id)
       values (adocset_id);
  insert into sm.docset_members (docset_id, document_id, docrole_id)
      values (adocset_id, documents_id, 1);

  transferbasis_id := NULL;
  if (base is not null) then
    -- найдем данные
    begin
      select p.id
        into transferbasis_id
        from sm.transferbasis p
       where p.name like '%' || base || '%';
      exception
      when no_data_found then null;
    end;
  end if;

  amoveset_id := NULL;
  select sm.seqmovesets.nextval
    into amoveset_id
    from dual;
  insert into sm.movesets(id, movetype_id, client_id, docset_id, transferbasis_id, id_import)
       values (amoveset_id, id_movetype, id_client, adocset_id, coalesce(transferbasis_id, id_base_default), id_import);


   -- создадим период ОД
   Amoveperiods_id := NULL;
   select sm.seqmoveperiods.nextval
     into Amoveperiods_id
     from dual;
   insert into sm.moveperiods (id, moveset_id, sincedate, docset_id, id_import)
        values (Amoveperiods_id, amoveset_id, sincedate, adocset_id, id_import);

   -- вставим объект
   insert into sm.moveitems(id, object_id, moveperiod_id, id_import)
        values (sm.seqmoveitems.nextval, id_object, amoveperiods_id, id_import);
   ---------------------------------------------------------------------------------------------------------
end create_od_import;
/
grant execute on SM.CREATE_OD_IMPORT to SM_ALL_SELECT;


