prompt ==================================
prompt
create or replace procedure sm.FullRecalcFines(AMoveSet_ID in number, AObligType_ID in number, DelCharges IN CHAR default 'Y')
IS
  CHARGE_OLD_ACCOUNT_VIEW char(1);
  cnt number;
begin

  select count(*)
  into cnt
  from sm.payments_plan_draft ppd
  where ppd.obligationtype_id=AObligType_ID and
        ppd.movesets_id=AMoveSet_ID;

  if cnt>0 then
    sm.fullrecalc_pkg.FullRecalcChargesCredit(AMoveSet_ID,AObligType_ID); -- credit
  else
   		sm.fullrecalc_pkg.FullRecalcCharges(AMoveSet_ID,  AObligType_ID);
  end if;
      
end;
/
grant execute on SM.FULLRECALCFINES to SM_ALLUSERS;
grant execute on SM.FULLRECALCFINES to SM_ALL_SELECT;


prompt
prompt Creating procedure DELCUSTOMCHARGE
prompt ==================================
prompt
create or replace procedure sm.DelCustomCharge (ChargeID in number) is
  AMoveSet_ID number;
  AOblType_ID number;
  ACalcDate date;
begin
  -------------------------------------------------
  -- by XSGROUP ver. 19.05.2010
  -- процедура удаления дополнительного начисления
  -------------------------------------------------
  select 
    movesets_id,
    obligationtype_id,
    trunc(finedate)  
  into 
    AMoveSet_ID,
    AOblType_ID,
    ACalcDate
  from 
   sm.charges
  where
   ID=ChargeID;
  
  delete from sm.Charges 
  where
   (ID=ChargeID and
   trim(CHARGE_TYPE)='OTHER')
   or
   (ID=ChargeID and
   trim(CHARGE_TYPE)='FINE' and
   DOCUMENT_ID is not null)
   or
  (ID=ChargeID and
   trim(CHARGE_TYPE)='PERCENT' and
   DOCUMENT_ID is not null);

  update 
    sm.obligations o 
  set 
    o.recalc_actual_date=(ACalcDate-1) 
  where
    o.moveset_id=AMoveSet_ID and
    o.obligationtype_id=AOblType_ID;
    
  sm.FullRecalcFines(AMoveSet_ID,AOblType_ID);

end;
/
grant execute on SM.DELCUSTOMCHARGE to SM_ALL_SELECT;
grant execute on SM.DELCUSTOMCHARGE to SM_CANCHARGE;
grant execute on SM.DELCUSTOMCHARGE to SM_CANMOVE;
grant execute on SM.DELCUSTOMCHARGE to SM_CANPAY;


prompt
prompt Creating procedure DELETEFROMMOVEMENT
prompt =====================================
prompt
create or replace procedure sm.DeleteFromMovement(MoveItemID in number, MV_ObjectID in number) is
--------------------------------------------
-- by XSGROUP ver.09.04.2013
-- Процедура предназначена для удаления движения объекта из БД
-- парамеры:
-- MoveItemID - ID из таблицы MOVEITEMS
-- MV_ObjectID - ID объекта, если движение объекта оформлено через движение имущественного комплекса
--               если движение оформлено непосредственно на сам объект - NULL
--
-- Если в результате удаления движения объекта образуется безобъектноая операция движения
-- она также удаляется
--
-- Данная процедура вызывается из окна свойств объекта при удалении движения на вкладке Движение
--
--------------------------------------------
  MI_ID sm.moveitems.id%type; 
  MP_ID sm.moveperiods.id%type;
  MS_ID sm.movesets.id%type;
  ItemsCnt number;
  PeriodsCnt number;
begin
  
  begin
    select
      mi.id,
      mp.id,
      ms.id
    into
      MI_ID,
      MP_ID,
      MS_ID
    from
      sm.movesets ms,
      sm.moveperiods mp,
      sm.moveitems mi
    where
      ms.id=mp.moveset_id and
      mp.id=mi.moveperiod_id and
      mi.id=MoveItemID and
      rownum=1;  
  exception
    when others then
      goto quit_proc;
  end;
  
  if MI_ID is null then
    goto quit_proc;
  end if;  
  
 begin
  
    if MV_ObjectID is null then
      delete from sm.moveitems mi where mi.id=MI_ID;
      
      if MP_ID is null then
        commit;
        goto quit_proc;
      end if;  
    else
      delete from sm.links_mi_objects lio where lio.moveitems_id=MI_ID and lio.objects_id=MV_ObjectID;
      commit;
      goto quit_proc; 
    end if;
    
    select count(*) 
    into ItemsCnt
    from 
      sm.moveitems mi
    where
      mi.moveperiod_id=MP_ID;
        
    if ItemsCnt=0 then
      delete from sm.moveperiods mp where mp.id=MP_ID;
      
      if MS_ID is null then
        commit;
        goto quit_proc;
      end if;  
    else
      commit;
      goto quit_proc;
    end if;
    
    select count(*) 
    into PeriodsCnt
    from 
      sm.moveperiods mp
    where
      mp.moveset_id=MS_ID;
    
    if PeriodsCnt=0 then
      delete from sm.movesets ms where ms.id=MS_ID;
      commit;
    else
      commit;
      goto quit_proc;
    end if;
  
  exception
  
   when others then
       raise_application_error(-20101,sqlerrm);
      rollback;
      
  end;
  
  <<quit_proc>>
  null;
  
end;
/
grant execute on SM.DELETEFROMMOVEMENT to SM_ALLUSERS;
grant execute on SM.DELETEFROMMOVEMENT to SM_ALL_SELECT;


