prompt
create or replace procedure sm.Delete_import(Flag in char, Aid_import in number) is
begin
   delete from dc_property_import d where d.id_import = Aid_import;
   delete from moveitems d where d.id_import = Aid_import;
   delete from moveperiods d where d.id_import = Aid_import;
   delete from movesets d where d.id_import = Aid_import;
   delete from states d where d.id_import = Aid_import;
   delete from objects o where o.id_import = Aid_import;
end Delete_import;
/
grant execute on SM.DELETE_IMPORT to SM_ALLUSERS;
grant execute on SM.DELETE_IMPORT to SM_ALL_SELECT;


prompt
prompt Creating procedure DROPEMPTYSTATE
prompt =================================
prompt
create or replace procedure sm.DropEmptyState(StateID in number)
as
--
-- XSGROUP ver. 23.04.2012
-- Процедура удаляет состояние объекта, 
-- если все характеристики состояния объекта пустые и нет ссылок на данное состояние
--
  nTmp number(27);
begin
  if (StateID is not null) then
    for xx in (select * from sm.states where id=StateID)
    loop
       if (
          xx.pay is null and 
          xx.wear is null and 
          xx.statetypes_id=1 and 
          xx.startpay is null and 
          xx.ratable is null and 
          xx.is_using='Y' and 
          xx.kadastr_cost is null and 
          nvl(xx.amount,0)=0 and 
          xx.cadastralvalue is null and 
          nvl(xx.nominalcost,0)=0 and 
          nvl(xx.sharesnumber,0)=0 and 
          nvl(xx.sharesprevnumber,0)=0 and 
          xx.workersnumber is null and 
          xx.goldstockowner_id is null 
          --and xx.speciallyvalued is null 
          ) then    
          
            select count(*) into nTmp from sm.moveitems t where t.state_id=StateID;
            if (nTmp >0) then
              exit;
            end if;
            
            select count(*) into nTmp from sm.opershares t where t.states_id=StateID;
            if (nTmp >0) then
              exit;
            end if;
            
            delete states where id = StateID;
       end if;    
    end loop;        
  end if;
end;
/
grant execute on SM.DROPEMPTYSTATE to SM_ALLUSERS;
grant execute on SM.DROPEMPTYSTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure EXPORT_DOCUMENTS
prompt ===================================
prompt
create or replace procedure sm.Export_documents(Flag in char) is
  l_file      UTL_FILE.FILE_TYPE;
  l_buffer    RAW(32767);
  l_amount    BINARY_INTEGER := 32767;
  l_pos       NUMBER := 1;
  l_blob      BLOB;
  l_blob_len  NUMBER;
  filename    varchar2(255) := '';
  path        varchar2(255) := 'D:\docs\Export_saumi';
  path2       varchar2(255) := '\\192.168.173.10\docs\Export_saumi';
  fullpath    varchar2(512) := '';
BEGIN
  begin
  dbms_java.grant_permission('SM', 'SYS:java.io.FilePermission', path || '\', 'read,write');
  end;
  
  for
    xxx in (           
            SELECT d.id, d.file_extention, d.body
              FROM sm.objects o
              join sm.docset_members m on m.docset_id = o.docset_id
              join sm.documents d on d.id = m.document_id
             WHERE o.objtypes_id <> 7
               and d.body is not null
               and dbms_lob.getlength(d.body) <> 0
               and d.file_scan is null
               and d.file_extention is not null
               and d.docdate >= cast('01.07.2015' as date)  
               --and rownum <=10             
            )   
  loop
    l_blob := xxx.body;
    filename := xxx.id || '.' || xxx.file_extention;
    fullpath := path2 || '\' || filename; 
    l_blob_len := DBMS_LOB.getlength(l_blob);

    -- Open the destination file.
    l_file := UTL_FILE.fopen('DIREXPORTDOC' ,filename ,'wb', 32767);
    l_pos := 1;
    
    WHILE l_pos < l_blob_len LOOP
      DBMS_LOB.read(l_blob, l_amount, l_pos, l_buffer);
      UTL_FILE.put_raw(l_file, l_buffer, TRUE);
      l_pos := l_pos + l_amount;
    END LOOP;

    -- Close the file.
    UTL_FILE.fclose(l_file);
    
    -- обнулим блоб
    update sm.documents d
       set d.body = NULL,
           d.file_extention = NULL,
           d.file_scan = fullpath
     where d.id = xxx.id;       
  end loop;
  
   for
    xxx in (
              SELECT d.id, d.file_extention, d.body
                FROM sm.moveperiods mp
                join sm.movesets ms on ms.id = mp.moveset_id
                join sm.docset_members m on m.docset_id = mp.docset_id
                join sm.documents d on d.id = m.document_id
               WHERE ms.movetype_id = 1
                 and d.body is not null
                 and dbms_lob.getlength(d.body) <> 0
                 and d.file_scan is null
                 and d.file_extention is not null
                 and d.docdate >= cast('01.07.2015' as date)         
            )   
  loop
    l_blob := xxx.body;
    filename := xxx.id || '.' || xxx.file_extention;
    fullpath := path2 || '\' || filename; 
    l_blob_len := DBMS_LOB.getlength(l_blob);

    -- Open the destination file.
    l_file := UTL_FILE.fopen('DIREXPORTDOC' ,filename ,'wb', 32767);
    l_pos := 1;

    WHILE l_pos < l_blob_len LOOP
      DBMS_LOB.read(l_blob, l_amount, l_pos, l_buffer);
      UTL_FILE.put_raw(l_file, l_buffer, TRUE);
      l_pos := l_pos + l_amount;
    END LOOP;

    -- Close the file.
    UTL_FILE.fclose(l_file);
    
    -- обнулим блоб
    update sm.documents d
       set d.body = NULL,
           d.file_extention = NULL,
           d.file_scan = fullpath
     where d.id = xxx.id;       
  end loop;  
end Export_documents;
/

prompt
prompt Creating procedure FILLOBJECTPOSITION_ALL
prompt =========================================
prompt
create or replace procedure sm.FillObjectPosition_all AS
 cnt number; 
  begin
    delete from sm.object_position;
    -- добавим объекты которые участвуют на прямую в ОД на текущую дату.
    for xx in (select order_item,
                      movetype_id,
                      client_id,
                      object_id 
                 from (
                       select distinct 
                              '1' as order_item,
                              ms.movetype_id,
                              ms.client_id,
                              mi.object_id 
                         from sm.movesets ms
                         join sm.moveperiods mp on mp.moveset_id = ms.id
                         join sm.moveitems mi on mi.moveperiod_id = mp.id
                        where trunc(mp.sincedate) <= sysdate 
                          and (trunc(mp.enddate) >= sysdate or mp.enddate is null)
                          and ms.client_id = 5100
                       union 
                       select distinct 
                              '2' as order_item,
                              ms.movetype_id,
                              ms.client_id,
                              mi.object_id 
                         from sm.movesets ms
                         join sm.moveperiods mp on mp.moveset_id = ms.id
                         join sm.moveitems mi on mi.moveperiod_id = mp.id
                        where trunc(mp.sincedate) <= sysdate 
                          and (trunc(mp.enddate) >= sysdate or mp.enddate is null)
                          and ms.client_id <> 5100
                      )q
                 --where q.object_id = 74489
                 order by 1 
             )    
    loop           
       cnt := 0; 
       select count(*)
         into cnt
         from sm.object_position o 
        where o.object_id = xx.object_id 
          and o.movetype_id = xx.MOVETYPE_ID;
       if (cnt = 0) then        
         insert into sm.object_position (client_id,object_id,movetype_id) values (XX.CLIENT_ID,xx.object_id,XX.MOVETYPE_ID);
       end if; 
    end loop; 

    -- если объект находится внутри другого объекта то он тоже должен быть в этой связке
    -- найдем объекты у которых есть родитель
    for yy in (
             select b.objects_id
               from sm.buildings b
              where b.basebuilding is not null 
               )
    loop
      
    -- выбираем родителей
    for qq in(
             select b.objects_id
               from sm.Buildings b
              start with b.objects_id = yy.objects_id
              connect by prior  b.basebuilding  = b.id
           )
     loop
         -- идем по всем ОД родителя, наследуем
         for zz in(         
                 select ms.movetype_id,
                        ms.client_id
                   from sm.Buildings b
                   join sm.moveitems mi on mi.object_id  = b.objects_id
                   join sm.moveperiods mp on mi.moveperiod_id = mp.id
                   join sm.movesets ms on ms.id = mp.moveset_id
                  where trunc(mp.sincedate)<=sysdate 
                    and (trunc(mp.enddate)>=sysdate or mp.enddate is null)
                    and mi.object_id = qq.objects_id             
                 )
        loop
           cnt := 0; 
           select count(*)
             into cnt
             from sm.object_position o 
            where o.object_id = yy.objects_id 
              and o.movetype_id = zz.MOVETYPE_ID;
          if (cnt = 0) then  
            insert into sm.object_position (client_id,object_id,movetype_id) values (zz.CLIENT_ID,yy.objects_id,zz.MOVETYPE_ID);      
          end if;     
       end loop;
     end loop;          
    end loop;                
  end FillObjectPosition_all;
/
grant execute on SM.FILLOBJECTPOSITION_ALL to SM_ALL_SELECT;


prompt
prompt Creating procedure FILL_KU_IMPORT
prompt =================================
prompt
create or replace procedure sm.fill_ku_import(flag in char)
is
id number(27);
Aaddress_id number (27);
address varchar2(2000) := '';
region varchar2(512) := '';
provincearea varchar2(512) := '';
city varchar2(512) := '';
townnames varchar2(512) := '';
street varchar2(512) := '';
house varchar2(100) := '';
refprovarea_id number(27);
square number(27,2) := 0;
cat_zu varchar2(512) := '';
Ashare_num number(27) := 1;
Ashare_denom number(27) := 1;
Ashare_all varchar2(100) := '';
name_obj varchar2(1000) := '';
startpay number(27,2) := 0;
pay number(27,2) := 0;
cadastr_cost number(27,2) := 0;
objecttype varchar2(255) :='';
transfbasis_name varchar2(80) := '';
transfbasis_all varchar2(4000) := '';
Aacting_type varchar2(255) := '';
doc_number varchar2(50) := '';
doc_date date;
is_insert char(1) := '0';
doctypes_id number(27);
doc_contents varchar2(4000) := '';
clientsfrom varchar2(512) := '';
moveperiods_id number(27);
enddate date;
iCount number(27) := 1;
Akadastrno varchar2(80) := '';
begin
  /* 21/02/2016 - процедура заполняет структуру выгрузки для программы репликации с Кубаньком */
  /*
     Данные для загрузки: здания (отдельностоящие),
                          незавершенное строительство,
                          земельные участки.
     Все объекты должны находиться/находилсиь в муниципальной собственности г. Краснодар, которые существуют в программном комплексе «Saumi».
     Объекты должны находиться в собственности, балансодержание, аренде.
  */

  -- очистим хранилище выгрузки
  delete from sm.dc_ku_movements;
  delete from sm.dc_ku_objects;
  delete from sm.dc_ku_clients;

  -- формируем запрос
  -- ищем все объекты, которые находятся на дату запроса в собственности
  for qData in (
                select
                       o.id as objects_id, -- объект
                       o.objtypes_id,
                       o.description, -- описание
                       o.id as regno, -- реестровый номер
                       o.address_id, -- адрес
                       o.kadastrno, -- кадастровый номер
                       mi.share_num,
                       mi.share_denom
                  from sm.objects o
                  join sm.moveitems mi on mi.object_id = o.id
                  join sm.moveperiods mp on mp.id = mi.moveperiod_id
                  join sm.movesets ms on ms.id = mp.moveset_id
                  join sm.movetype mt on mt.id = ms.movetype_id
                 where o.objtypes_id in (3,4,7)
                   and ms.movetype_id = 1
                   and ms.client_id = 5100
                  /* and (o.objtypes_id IN (3) and (exists (select *
                                                            from sm.buildings b
                                                           where b.objects_id = o.id
                                                             and b.basebuilding is null))
                         or o.objtypes_id in (4,7)
                       )*/
                   and mp.sincedate <= sysdate
                   and (mp.enddate >= sysdate or mp.enddate is null)
                   --and o.id = 38457
                 order by o.id 
                )
  loop
     Aaddress_id := NULL;
     address := '';
     region := '';
     provincearea := '';
     city := '';
     townnames := '';
     street := '';
     house := '';
     square := 0;
     refprovarea_id := NULL;
     cat_zu := '';
     Ashare_num := 1;
     Ashare_denom := 1;
     Ashare_all := '';
     name_obj := '';
     startpay := 0;
     pay := 0;
     cadastr_cost := 0;
     objecttype := '';
     transfbasis_name := '';
     doc_number := '';
     doc_date := NULL;
     Aacting_type := 'Недействующий';
     doc_contents := '';
     doctypes_id := NULL;
     is_insert := '0';
     clientsfrom := '';
     moveperiods_id := NULL;
     transfbasis_all := '';
     enddate := NULL;
     Akadastrno := qData.Kadastrno;

    -- если такого объекта еще нет
    -- то вставим его
    begin
      id := NULL;
      select o.id
        into id
        from sm.dc_ku_objects o
       where o.id = qData.objects_id;
      exception
          when no_data_found then null;
    end;

    -- если не нашли
    if (id is null) then
       select t.name -- тип объекта
         into objecttype
         from sm.objtypes t
        where t.id = qData.objtypes_id;

       select coalesce(sm.getObjectCost(qData.objects_id, sysdate,'B'), 0) as startpay, -- первоначальная стоимость
              coalesce(sm.getObjectCost(qData.objects_id, sysdate,'R'), 0) as pay, -- остаточная стоимость
              coalesce(sm.getObjectCost(qData.objects_id, sysdate,'D'), 0) as cadastr_cost -- кадастровая стоимость с учетом доли
         into startpay,
              pay,
              cadastr_cost
         from dual;

       -- сформируем полный адрес
       -- в зависимости от типа объекта получаем адрес и площадь
       -- если здания
       if (qData.objtypes_id = 3) then
         begin
           select b.address_id,
                  b.square,
                  b.levelname,
                  coalesce(Akadastrno, b.kadastrno)
             into Aaddress_id,
                  square,
                  name_obj,
                  Akadastrno
             from sm.buildings b
            where b.objects_id = qData.objects_id;
            exception
              when no_data_found then
              null;
         end;
       end if;

       -- если незавершенное
       if (qData.objtypes_id = 4) then
         begin
           select b.address_id,
                  b.square,
                  b.name,
                  coalesce(Akadastrno, b.kadastrno)
             into Aaddress_id,
                  square,
                  name_obj,
                  Akadastrno
             from sm.unconstr b
            where b.objects_id = qData.objects_id;
            exception
              when no_data_found then
              null;
         end;
       end if;

       if (qData.objtypes_id = 7) then
         begin
           select b.address_id,
                  b.square,
                  t.name,
                  'Земельный участок',
                  coalesce(Akadastrno, b.kadastrno)
             into Aaddress_id,
                  square,
                  cat_zu,
                  name_obj,
                  Akadastrno
             from sm.grounds b
             left join sm.groundtypes t on t.id = b.groundtypes_id
            where b.objects_id = qData.objects_id;
            exception
              when no_data_found then
                null;
         end;
       end if;

       square := coalesce(square,0);

       if (name_obj is null) then
         name_obj := qData.Description;
       end if;

       Aaddress_id := coalesce(qData.address_id, Aaddress_id);
       -- если нашли адрес
       -- то сформируем общий, а также его части отдельно
       if (Aaddress_id is not null) then
          select sm.expandaddr (Aaddress_id)
            into address
            from dual;

          select a.house, st.name, pa.name, tn.name, tn.refprovarea_id, r.name
            into house, street, provincearea, city, refprovarea_id, region
            from sm.address a,
                 sm.provincearea pa,
                 sm.townnames tn,
                 sm.regions r,
                 sm.streets st
           where
             a.id in (select nvl(main_id,id)
                        from sm.address
                       where id = Aaddress_id) and
             a.provincearea_id = pa.id(+) and
             a.townnames_id = tn.id(+) and
             a.regions_id = r.id(+) and
             a.streets_id = st.id(+);

          -- если не город
          if (refprovarea_id <> 5) then
            townnames := city;
            city := '';
          end if;
       end if;

       -- доля в собственности
       Ashare_num := coalesce(qData.share_num, 1);
       Ashare_denom := coalesce(qData.share_denom, 1);
       Ashare_all := Ashare_num || '/' || Ashare_denom;

       insert into sm.dc_ku_objects(id, objecttype, description, regno, address, region, provincearea, city, townnames, street, house, name_obj,
                                    cat_zu, kadastrno, square, startpay, pay, cadastr_cost, share_all)
            values (qData.objects_id, objecttype, qData.description, qData.regno, address, region, provincearea, city, townnames, street, house, name_obj,
                                    cat_zu, Akadastrno, square, startpay, pay, cadastr_cost, ashare_all);
    end if;

    -- теперь вставляем период ОД, причем если есть периоды ОД с одинаковыми документами основания
    -- то мы такие периоды склеиваем в один
    -- например есть 2 ОД оформленные 2-мя разными операциями движения, при этом сбъект 1 и документы одни, но разные периоды
    -- такое может быть например для аренды, водоканал, куча периодов хотя договор один
    -- смотрим ОД: собственность, Балансодержание, Аренда
    for qMovesets in (
                      select ms.movetype_id,
                             mt.name as type_agreement, -- Тип договора
                             c.clienttype, -- тип клиента
                             c.id as clients_id, -- клиент
                             c.name || ', ИНН:' || c.inn as name_client, -- название клиента
                             ms.transferbasis_id, -- основание
                             wm_concat (ms.id) as list_movesets_id -- операция движения
                        from sm.moveitems mi
                        join sm.moveperiods mp on mp.id = mi.moveperiod_id
                        join sm.movesets ms on ms.id = mp.moveset_id
                        join sm.movetype mt on mt.id = ms.movetype_id
                        join sm.clients c on c.id = ms.client_id
                       where mi.object_id = qData.Objects_Id -- наш объект
                         and ms.movetype_id IN (1,2,4) -- наши ОД
                         and ms.find_dublicate = 'N'
                        -- and ms.movetype_id = 4
                       group by ms.movetype_id, mt.name, c.clienttype, c.id, 5, 6, 7, c.name || ', ИНН:' || c.inn, ms.transferbasis_id
                     )
     loop
        -- теперь вставляем клиента
        -- если такого клиента еще нет
        -- то вставим его
        begin
          id := NULL;
          select o.id
            into id
            from sm.dc_ku_clients o
           where o.id = qMovesets.clients_id;
          exception
              when no_data_found then null;
        end;

        -- если не нашли
        if (id is null) then
          insert into sm.dc_ku_clients (id,clienttype,name)
               values (qMovesets.Clients_Id, qMovesets.clienttype, qMovesets.name_client);
        end if;

        begin
          id := NULL;
          select o.id
            into id
            from sm.dc_ku_movements o
           where INSTR(',' || TO_CHAR(qMovesets.list_movesets_id) || ',', ',' || o.movesets_id  || ',' ,1 ,1) <> 0
             and rownum <=1;

          exception
              when no_data_found then null;
        end;

        --
        if (id is null) then

          -- получим основание
          begin
              select o.name
                into transfbasis_name
                from sm.transferbasis o
               where o.id = qMovesets.transferbasis_id;
              exception
                  when no_data_found then null;
          end;

          -- идем по всем периодам и склеиваем их
          is_insert := '1';
          enddate := NULL;
          for qMovePeriods in (
                         select mp.id as moveperiods_id,
                                mp.moveset_id,
                                mp.docset_id as docset_id,
                                mp.sincedate as startdate,
                                mp.enddate,
                                sm.expanddoc(d.id) as doc_contents,
                                d.docno as doc_number,
                                d.docdate as doc_date,
                                d.doctypes_id
                           from sm.moveperiods mp
                           join sm.moveitems mi on mi.moveperiod_id = mp.id
                           join sm.docset_members m on m.docset_id = mp.docset_id and m.docrole_id = 1
                           join sm.documents d on d.id = m.document_id
                          where INSTR(',' || TO_CHAR(qMovesets.list_movesets_id) || ',', ',' || mp.moveset_id || ',' ,1 ,1) <> 0
                            and mi.object_id = qData.objects_id
                          order by mp.sincedate
                       )
         loop
           transfbasis_all := '';
           Aacting_type := 'Недействующий';
           if (sysdate between qMovePeriods.startdate and coalesce(qMovePeriods.enddate, sysdate)) then
             Aacting_type := 'Действующий';
           end if;

           -- если уже последующие периоды, то будем проверять - вставка как нового или склеиваем
           if (is_insert = '0') then
              -- если следующий период по документам равен предыдущему
              if (doc_contents = trim(qMovePeriods.doc_contents) and
                  doc_number = trim(qMovePeriods.doc_number) and
                  doc_date = qMovePeriods.doc_date and
                  doctypes_id = qMovePeriods.doctypes_id and
                  enddate = qMovePeriods.Startdate - 1) then
                  -- значит просто продлим
                  update sm.dc_ku_movements m
                     set m.enddate = qMovePeriods.enddate,
                         m.acting_type = Aacting_type
                   where m.id = moveperiods_id;
                  enddate := coalesce(qMovePeriods.enddate, '31.12.2050');
              else
                  is_insert := '1';
              end if;
           end if;

           -- если первый период или документы по периодам не равны
           if (is_insert = '1') then
             is_insert := '0';-- сбросим флаг вставки, по умолчанию не вставляем

             -- запоминаем параметры
             doc_contents := trim(qMovePeriods.doc_contents);
             doc_number := trim(qMovePeriods.doc_number);
             doc_date := qMovePeriods.doc_date;
             doctypes_id := qMovePeriods.doctypes_id;
             moveperiods_id := qMovePeriods.moveperiods_id;
             enddate := coalesce(qMovePeriods.enddate, '31.12.2050');

             if (transfbasis_name = '') then
               transfbasis_all := qMovePeriods.doc_contents;
             else
               transfbasis_all := transfbasis_name || ',' || qMovePeriods.doc_contents;
             end if;

             -- найдем кто был субъектом ОД до нас
             -- ищем для каждого периода, так как: например отдали в аренду клиенту 1, потом клиенту 2, потом снова клиенту 1
             -- у них будут разные предыдущие
             clientsfrom := '';
             begin
                 select s.clientsfrom
                   into clientsfrom
                   from (
                         select (c.name || ', ИНН:' || c.inn) as clientsfrom -- название клиента
                           from sm.moveitems mi
                           join sm.moveperiods mp on mp.id = mi.moveperiod_id
                           join sm.movesets ms on ms.id = mp.moveset_id
                           join sm.clients c on c.id = ms.client_id
                          where mi.object_id = qData.objects_id
                            and ms.movetype_id = qMovesets.Movetype_Id
                            and ms.client_id <> qMovesets.Clients_Id
                            and mp.sincedate < qMovePeriods.startdate
                            order by mp.sincedate desc
                         )s
                   where rownum <= 1;
                 exception
                      when no_data_found then null;
             end;

             insert into sm.dc_ku_movements (id, objects_id, clients_id, type_agreement, transfbasis, clientsfrom, startdate, enddate, doc_number, doc_date, acting_type,
                                           movesets_id, movetype_id, list_movesets_id)
                  values (qMovePeriods.moveperiods_id, qData.objects_id, qMovesets.Clients_Id, qMovesets.type_agreement, transfbasis_all, clientsfrom, qMovePeriods.startdate, qMovePeriods.enddate,
                          doc_number, doc_date, Aacting_type, qMovePeriods.moveset_id, qMovesets.movetype_id, qMovesets.list_movesets_id);
           end if;
         end loop;
       end if;
     end loop;
     iCount := iCount + 1;
  end loop;
end fill_ku_import;
/
grant execute on SM.FILL_KU_IMPORT to SM_ALL_SELECT;


prompt
prompt Creating procedure FULLRECALCCHARGES
prompt ====================================
prompt
create or replace procedure sm.FullRecalcCharges(AMoveSet_ID in number)

is
  cnt number;
begin
	
---VVV  14.12.2012 -- Профилактически вставляем удаленные из приложения Планы Платежей как часть  сохранения начислений до даты начала пересчета.
-- Insert into SM.PAYMENTS_PLAN(id,charges_id,obligations_id,finedate,val,payments_plan_draft_id,comments/*, MAIN_PLAN_ID*/ )
-- Select  sm.seqpayments_plan.nextval, ch.ID, (Select o.ID from  sm.OBLIGATIONS o where o.MOVESET_ID= ch.MOVESETS_ID and o.OBLIGATIONTYPE_ID=ch.OBLIGATIONTYPE_ID), ch.FINEDATE, ch.PAYSIZE, null, ch.COMMENTS/*, ch. */
--        from SM.CHARGES ch where not exists (Select * from SM.PAYMENTS_PLAN pp where pp.CHARGES_ID = ch.ID);

  for obl_type_list in (select DISTINCT(pd.obligationtype_id) as OblType
                        from
                          paydocs pd,
                          moveperiods mp
                        where
                          pd.moveperiod_id=mp.id and
                          mp.moveset_id=AMoveSet_ID)
  LOOP --for obl_type_list
     select count(*)
     into cnt
     from sm.payments_plan_draft ppd
     where ppd.obligationtype_id=obl_type_list.OblType and
           ppd.movesets_id=AMoveSet_ID;
     
      if cnt>0 then
         sm.fullrecalc_pkg.FullRecalcChargesCredit(AMoveSet_ID,obl_type_list.OblType);
      else
         sm.fullrecalc_pkg.FullRecalcCharges(AMoveSet_ID,obl_type_list.OblType);
      end if;
	
  END LOOP;
  
end; -- FullRecalcCharges;
/
grant execute on SM.FULLRECALCCHARGES to SM_ALLUSERS;
grant execute on SM.FULLRECALCCHARGES to SM_ALL_SELECT;


