prompt
prompt Creating procedure IMPORT_COPY_OD
prompt =================================
prompt
create or replace procedure sm.import_copy_od as
Adocument_id number(27) := 6120552;
Adocument_id_1 number(27) := 6175646 ;
Adocument_id_2 number(27) := 6120552 ;
Adocument_id_3 number(27) := 6120835 ;
Adocument_id_4 number(27) := 6163594 ;
Adocument_id_5 number(27) := 6120835 ;

Adocset_id_mp_4_new number(27);
Adocset_id_ms_4_new number(27);
Amoveperiods_id_mp_4_new number(27);
Amovesets_id_4_new number(27);

Adocset_id_mp_4 number(27);
Adocset_id_ms_4 number(27);
Amoveperiods_id_mp_4 number(27);
Amovesets_id_4 number(27);

Adocset_id_mp_31_new number(27);
Adocset_id_ms_31_new number(27);
Amoveperiods_id_mp_31_new number(27);
Amovesets_id_31_new number(27);

Adocset_id_mp_31 number(27);
Adocset_id_ms_31 number(27);
Amoveperiods_id_mp_31 number(27);
Amovesets_id_31 number(27);
begin
  /* 24/11/2019 Твердохлеб: Импортирует стоимость по объекту*/

  for xxx in
             (select *
                from sm.tmp_import_od t
                where t.object_id <> 376569)
  loop
     Adocset_id_mp_4 := null;
     Adocset_id_ms_4 := null;
     Amoveperiods_id_mp_4 := null;
     Amovesets_id_4 := null;

     -- Аренда
     begin
       select ms.id,
              mp.id,
              mp.docset_id,
              ms.docset_id
         into Amovesets_id_4,
              Amoveperiods_id_mp_4,
              Adocset_id_mp_4,
              Adocset_id_ms_4
         from sm.movesets ms
         join sm.moveperiods mp on mp.moveset_id = ms.id
         join sm.moveitems mi on mi.moveperiod_id = mp.id
        where ms.movetype_id = 4
          and ms.client_id = 20343
          and mp.enddate is null
          and mi.object_id = xxx.object_id;

       -- закроем период
       begin
       update sm.moveperiods mp
          set mp.enddate = '29.10.2020'
        where mp.id = Amoveperiods_id_mp_4;

        exception
       when others then raise_application_error(-20101, TO_CHAR(xxx.object_id));
      end;

       update sm.docset_members m
          set m.docrole_id = null
        where m.docset_id = Adocset_id_mp_4;

       insert into sm.docset_members (docset_id, document_id, docrole_id)
       values (Adocset_id_mp_4, Adocument_id, 1);

       exception
       when no_data_found then null;-- raise_application_error(-20101, TO_CHAR(xxx.object_id));
     end;

     Adocset_id_mp_31 := null;
     Adocset_id_ms_31 := null;
     Amoveperiods_id_mp_31 := null;
     Amovesets_id_31 := null;

     -- Забалансовый учет
     begin
       select ms.id,
              mp.id,
              mp.docset_id,
              ms.docset_id
         into Amovesets_id_31,
              Amoveperiods_id_mp_31,
              Adocset_id_mp_31,
              Adocset_id_ms_31
         from sm.movesets ms
         join sm.moveperiods mp on mp.moveset_id = ms.id
         join sm.moveitems mi on mi.moveperiod_id = mp.id
        where ms.movetype_id = 31
          and ms.client_id = 20343
          and mp.enddate is null
          and mi.object_id = xxx.object_id;

       -- закроем период
       begin
       update sm.moveperiods mp
          set mp.enddate = '29.10.2020'
        where mp.id = Amoveperiods_id_mp_31;

       exception
       when others then raise_application_error(-20101, TO_CHAR(xxx.object_id));
      end;

       update sm.docset_members m
          set m.docrole_id = null
        where m.docset_id = Adocset_id_mp_31;

       insert into sm.docset_members (docset_id, document_id, docrole_id)
       values (Adocset_id_mp_31, Adocument_id_1, 1);

       insert into sm.docset_members (docset_id, document_id)
