     if (Adocset_id_ms_4 is not null) then
       Adocset_id_ms_4_new := null;
       select sm.seqdocsets.nextval
         into Adocset_id_ms_4_new
         from dual;

       insert into sm.docsets (ID)
       values (Adocset_id_ms_4_new);

       INSERT INTO SM.DOCSET_MEMBERS
        (
          DOCSET_ID
         ,DOCUMENT_ID
         ,DOCROLE_ID
        )
       select Adocset_id_ms_4_new,
              m.document_id,
              null--m.docrole_id
         from sm.docset_members m
        where m.docset_id = Adocset_id_ms_4
          and m.document_id <> Adocument_id;

       insert into sm.docset_members (docset_id, document_id, docrole_id)
         values (Adocset_id_ms_4_new, Adocument_id_3, 1);
     end if;

