prompt
prompt Creating procedure IMPORT_COST
prompt ==============================
prompt
create or replace procedure sm.import_cost as
Adocument_id number(27) := 7950291         ;
Adocument_id_1 number(27) := 7950291         ;
Adocument_id_2 number(27) := 7950291         ;
Adocset_id number(27);
begin
  /* 30/09/2019 Твердохлеб: Импортирует стоимость по объекту*/
  
  for xxx in 
             (select * 
                from TMP_IMPORT_COST t)
  loop
       -- создадим пакет
      adocset_id := NULL;
      select sm.seqdocsets.nextval
        into adocset_id
        from dual;
      
      insert into sm.docsets (id)
           values (adocset_id);
      -- документы в Состояние
      insert into sm.docset_members (docset_id, document_id, docrole_id)
           values (adocset_id, Adocument_id, 1);
      /*insert into sm.docset_members (docset_id, document_id)
           values (adocset_id, Adocument_id_1);  
      insert into sm.docset_members (docset_id, document_id)
           values (adocset_id, Adocument_id_2);*/ 
      
      -- добавим новое состояние
begin
      INSERT INTO SM.STATES (
                             ID, PAY, WEAR, CALCDATE, DOCUMENTS_ID, STATETYPES_ID, OBJECTS_ID, CHANGEDBY, STARTPAY, WRITEDATE, MUNREPORT_ID, RATABLE, IS_USING, KADASTR_COST, 
                             COST_LAND, CADASTRALVALUE, NOMINALCOST, SHARESNUMBER, SHARESPREVNUMBER, WORKERSNUMBER, GOLDSTOCKOWNER_ID, AMOUNT, CHANGE_DATE, CHANGE_DOC, 
                             SPECIALLYVALUED, ID_IMPORT, NOMINALCOST_OLD, INVESTMENT_ESTIMATED_VALUE, INVESTMENT_FACT_VALUE
                            )
           VALUES (sm.seqstates.nextval, xxx.pay, NULL, '01.08.2026', Adocset_id, 1, xxx.object_id, '', xxx.startpay, SYSDATE, NULL, NULL, 'N', NULL, NULL, xxx.kadastrpay, NULL, NULL, NULL, NULL, NULL, 
                   NULL, SYSDATE, Adocument_id, NULL, NULL, NULL, NULL, NULL);

    exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end;

end;      
                   
      -- теперь добавим в пакеты ОД Забалансовый учет и Бюджетный учет документы    
      for yyy in (
                   select distinct mp.docset_id
                     from sm.movesets ms
                     join sm.moveperiods mp on mp.moveset_id = ms.id
                     join sm.moveitems mi on mi.moveperiod_id = mp.id                     
                    where ms.movetype_id in (29,31) 
                      and mi.object_id = xxx.object_id
                      and mp.sincedate <= sysdate
                      and (mp.enddate >= sysdate or mp.enddate is null)
                 )
      loop
         begin
           -- документы в ОД
           insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id);
           /*insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id_1);
           insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id_2);*/
           exception
            when others then begin
            --raise_application_error (-20101, xxx.object_id);
            null;
          end; 
         end;
      end loop;                    
  end loop;
  
  delete from TMP_IMPORT_COST;        
end import_cost;
/

prompt
prompt Creating procedure IMPORT_COST2
prompt ===============================
prompt
create or replace procedure sm.import_cost2 as
Adocument_id number(27) := 5874094;
Adocset_id number(27);
amoveset_id number(27);
id_import number(27) := 1;
id_movetype number(27) := 31;
id_client number(27);
Amoveperiods_id number(27);
transferbasis_id number(27) := 421; -- Муниципальное имущество
sincedate varchar2(10) := '16.06.2020';
LEASEPURPOSE_ID number(27) := 5182; --жилые помещения
ACCOUNT_ZABUCH VARCHAR2(21) := '26.53';
begin
  /* 30/09/2019 Твердохлеб: Импортирует забалансовый учет*/
  
  for xxx in 
             (select * 
                from TMP_IMPORT_ZAB t)
  loop 
    id_client := null;
    select c.id
    into id_client
    from clients c
    where replace_char(c.name) = xxx.client
    and rownum < 2;
    
    -- создадим пакет
    adocset_id := NULL;
    select sm.seqdocsets.nextval
      into adocset_id
      from dual;
        
    insert into sm.docsets (id)
         values (adocset_id);
    insert into sm.docset_members (docset_id, document_id, docrole_id)
         values (adocset_id, Adocument_id, 1);
      
    -- создадим ОД
    amoveset_id := NULL;
    select sm.seqmovesets.nextval
      into amoveset_id
      from dual;
      
    insert into sm.movesets(id, movetype_id, client_id, docset_id, transferbasis_id, id_import)
         values (amoveset_id, id_movetype, id_client, adocset_id, transferbasis_id, id_import);

     -- создадим период ОД
     Amoveperiods_id := NULL;
     select sm.seqmoveperiods.nextval
       into Amoveperiods_id
       from dual;
     insert into sm.moveperiods (id, moveset_id, sincedate, docset_id, ACCOUNT_ZABUCH, id_import)
          values (Amoveperiods_id, amoveset_id, sincedate, adocset_id, ACCOUNT_ZABUCH, id_import);

     -- вставим объект
     insert into sm.moveitems(id, object_id, moveperiod_id, LEASEPURPOSE_ID, id_import)
          values (sm.seqmoveitems.nextval, xxx.object_id, amoveperiods_id, LEASEPURPOSE_ID, id_import);      
                     
    
    delete from TMP_IMPORT_ZAB;
  end loop;      
end import_cost2;
/

prompt
prompt Creating procedure IMPORT_COST2023
