prompt
create or replace procedure sm.import_cost2023 as
Adocument_id number(27) := 7448784 ; --основной документ Состояния - Служебка
Adocument_id_1 number(27) := 7448758 ; --бухсправка в ОД
--Adocument_id_2 number(27) := 7448758 ; -- бухсправка в ОД
Adocset_id number(27);
begin
  /* 30/09/2019 Твердохлеб: Импортирует стоимость по объекту*/
  --модифицирована на случай, когда в пакеты документов Забалансового и Бюджетного учета помещаются иные документы

  for xxx in
             (select *
                from TMP_IMPORT_COST t)
  loop
       -- создадим пакет
      adocset_id := NULL;
      select sm.seqdocsets.nextval
        into adocset_id
        from dual;

      insert into sm.docsets (id)
           values (adocset_id);
      insert into sm.docset_members (docset_id, document_id, docrole_id)
           values (adocset_id, Adocument_id, 1);
     insert into sm.docset_members (docset_id, document_id)
           values (adocset_id, Adocument_id_1);
    /*insert into sm.docset_members (docset_id, document_id, docrole_id)
           values (adocset_id, Adocument_id_1,1); */         
      /*insert into sm.docset_members (docset_id, document_id, docrole_id)
           values (adocset_id, Adocument_id_2, 1);*/

      -- добавим новое состояние
begin
      INSERT INTO SM.STATES (
                             ID, PAY, WEAR, CALCDATE, DOCUMENTS_ID, STATETYPES_ID, OBJECTS_ID, CHANGEDBY, STARTPAY, WRITEDATE, MUNREPORT_ID, RATABLE, IS_USING, KADASTR_COST,
                             COST_LAND, CADASTRALVALUE, NOMINALCOST, SHARESNUMBER, SHARESPREVNUMBER, WORKERSNUMBER, GOLDSTOCKOWNER_ID, AMOUNT, CHANGE_DATE, CHANGE_DOC,
                             SPECIALLYVALUED, ID_IMPORT, NOMINALCOST_OLD, INVESTMENT_ESTIMATED_VALUE, INVESTMENT_FACT_VALUE
                            )
           VALUES (sm.seqstates.nextval, xxx.pay, NULL, '29.12.2024', Adocset_id, 1, xxx.object_id, '', xxx.startpay, SYSDATE, NULL, NULL, 'N', NULL, NULL, xxx.kadastrpay, NULL, NULL, NULL, NULL, NULL,
                   NULL, SYSDATE, Adocument_id, NULL, NULL, NULL, NULL, NULL);

    exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end;
end;

      -- теперь добавим в пакеты ОД Забалансовый учет и/или Бюджетный учет документы
      for yyy in (
                   select distinct mp.docset_id
                     from sm.movesets ms
                     join sm.moveperiods mp on mp.moveset_id = ms.id
                     join sm.moveitems mi on mi.moveperiod_id = mp.id
                    where ms.movetype_id in (29,31)
                      and mi.object_id = xxx.object_id
                      and mp.sincedate <= sysdate
                      and (mp.enddate >= sysdate or mp.enddate is null)
                 )
      loop
         begin
           insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id);
           insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id_1);
           /*insert into sm.docset_members (docset_id, document_id)
           values (yyy.docset_id, Adocument_id_2);*/
           exception
            when others then begin
            --raise_application_error (-20101, xxx.object_id);
            null;
          end;
         end;
      end loop;
  end loop;

  delete from TMP_IMPORT_COST;
end import_cost2023;
/

