prompt Creating procedure IMPORT_COST_2026
prompt ===================================
prompt
create or replace procedure sm.import_cost_2026 as
Adocument_id number(27) := 1448062        ;
Adocset_id number(27);
v_count integer;
begin
  /* 30/09/2019 Твердохлеб: Импортирует стоимость по объекту*/
  
  for xxx in 
             (select * 
                from TMP_IMPORT_COST t)
  loop
       -- создадим пакет
      adocset_id := NULL;
      select sm.seqdocsets.nextval
        into adocset_id
        from dual;
      
      insert into sm.docsets (id)
           values (adocset_id);
      -- документы в Состояние
      insert into sm.docset_members (docset_id, document_id, docrole_id)
           values (adocset_id, Adocument_id, 1);

      -- проверим, есть ли уже состояние на дату импортируемой стоимости      
      SELECT COUNT(*)
      INTO v_count
      FROM sm.states St
      WHERE st.objects_id = xxx.object_id and st.calcdate = xxx.kadno_date;

      -- если сосотояния на импортируемую дату нет, то добавим новое состояние
      IF v_count = 0 THEN
      begin
            INSERT INTO SM.STATES (
                                   ID, PAY, WEAR, CALCDATE, DOCUMENTS_ID, STATETYPES_ID, OBJECTS_ID, CHANGEDBY, STARTPAY, WRITEDATE, MUNREPORT_ID, RATABLE, IS_USING, KADASTR_COST, 
                                   COST_LAND, CADASTRALVALUE, NOMINALCOST, SHARESNUMBER, SHARESPREVNUMBER, WORKERSNUMBER, GOLDSTOCKOWNER_ID, AMOUNT, CHANGE_DATE, CHANGE_DOC, 
                                   SPECIALLYVALUED, ID_IMPORT, NOMINALCOST_OLD, INVESTMENT_ESTIMATED_VALUE, INVESTMENT_FACT_VALUE
                                  )
                 VALUES (sm.seqstates.nextval, xxx.pay, NULL, xxx.kadno_date, Adocset_id, 1, xxx.object_id, '', xxx.startpay, SYSDATE, NULL, NULL, 'N', NULL, NULL, xxx.kadastrpay, NULL, NULL, NULL, NULL, NULL, 
                         NULL, SYSDATE, Adocument_id, NULL, NULL, NULL, NULL, NULL);

          exception
                   when others then begin
                     raise_application_error(-20101, TO_CHAR(xxx.object_id));
                  end;

      end;
      end if;      
                                    
  end loop;
  
  delete from TMP_IMPORT_COST;        

end import_cost_2026;
/

prompt
prompt Creating procedure IMPORT_DATA
prompt ==============================
prompt
create or replace procedure sm.import_data(
  flag in char,
  id_import in char,
  inv_num in varchar2,
  okof in varchar2,
  prop_names in varchar2,
  name_obj in varchar2,
  year_ in varchar2,
  date_input in varchar2,
  serial_number in varchar2,
  state_date in varchar2,
  state_initial_cost in varchar2,
  state_remaining_cost in varchar2,
  state_condition in varchar2,
  state_doc in varchar2,
  property_client in varchar2,
  property_base in varchar2,
  property_sincedate in varchar2,
  property_doc in varchar2,
  balance_client in varchar2,
  balance_base in varchar2,
  balance_sincedate in varchar2,
  balance_doc in varchar2,
  valuable_client in varchar2,
  valuable_base in varchar2,
  valuable_sincedate in varchar2,
  valuable_doc in varchar2)
as
  id number(27);
  aobject_id number(27);
  propnames_id number(27);
  statetypes_id number(27);
  adocset_id number(27);
  state_initial_cost_loc varchar2(80);
  state_remaining_cost_loc varchar2(80);  
begin
  /* 15/02/2016 Импортируем данные*/
  /* 29/03/2016 [392] - убрал формирование описание по объекту + добавил колонку заводской номер*/
  /* 13/04/2016 [392] - добавил неиспользуемые(забытые) колонки - okof year_ date_input*/

  select sm.g_id_property_import.nextval
    into id
    from dual;

  insert into sm.dc_property_import(
              id,
              id_import,
              inv_num,
              okof,
              prop_names,
              name_obj,
              year_,
              date_input,
              serial_number,
              state_date,
              state_initial_cost,
              state_remaining_cost,
              state_condition,
              state_doc,
              property_client,
              property_base,
              property_sincedate,
              property_doc,
              balance_client,
              balance_base,
              balance_sincedate,
              balance_doc,
              valuable_client,
              valuable_base,
              valuable_sincedate,
              valuable_doc
  )
  values(
              id,
              id_import,
              inv_num,
              okof,
              prop_names,
              name_obj,
              year_,
              date_input,
              serial_number,
              state_date,
              state_initial_cost,
              state_remaining_cost,
              state_condition,
              state_doc,
              property_client,
              property_base,
              property_sincedate,
              property_doc,
              balance_client,
              balance_base,
              balance_sincedate,
              balance_doc,
              valuable_client,
              valuable_base,
              valuable_sincedate,
              valuable_doc
  );

  -- теперь загрузим переданную запись
  -- создадим объект
  begin
    -- создадим объект
    Aobject_id := NULL;
    select sm.seqobjects.nextval
      into Aobject_id
      from dual;

    adocset_id := NULL;
      select sm.seqdocsets.nextval
        into adocset_id
        from dual;
    insert into sm.docsets (id)
           values (adocset_id);

    insert into sm.objects (id, objtypes_id, description, docset_id, invno, id_import, id_property_import, okof)
         values (Aobject_id, 1, substr(NAME_OBJ, 0, 300), adocset_id, substr(inv_num, 0, 50), id_import, id, case when okof = '' then NULL else okof end);
    -- exception
    -- when others then begin
    --     raise_application_error(-20101, 'objects - ' || TO_CHAR(id));
    -- end;
  end;

  -- создадим проче движимое
  begin
    if (prop_names is not null) then
      -- найдем данные
      begin
        select p.id
          into propnames_id
          from sm.propnames p
         where p.name like '%' || prop_names || '%';
        exception
        when no_data_found then null;
      end;
    end if;

    Execute immediate ('alter trigger Property_Obj disable');
    insert into sm.property (id, model, objects_id, propnames_id, serialnum, dateissue, dateinput)
         values (seqproperty.nextval, substr(name_obj, 0, 120), aobject_id, coalesce(propnames_id, 22270), serial_number, year_, date_input);
    Execute immediate ('alter trigger Property_Obj enable');
    -- exception
    -- when others then begin
    --     raise_application_error(-20101, 'property - ' || TO_CHAR(id));
    -- end;
  end;

  -- добавим состояние по объекту
  begin
      if (state_condition is not null)then
        begin
          select p.id
            into statetypes_id
            from sm.statetypes p
           where p.name like '%' || state_condition || '%';
          exception
          when no_data_found then null;
        end;
      end if;

      -- создадим пакет
      adocset_id := NULL;
      select sm.seqdocsets.nextval
        into adocset_id
        from dual;
      insert into sm.docsets (id)
           values (adocset_id);
      insert into sm.docset_members (docset_id, document_id, docrole_id)
          values (adocset_id, state_doc, 1);


      state_initial_cost_loc := replace(state_initial_cost, ' ', '');  
      state_remaining_cost_loc := replace(state_remaining_cost, ' ', ''); 
           
      -- создадим состояние объекта
      insert into sm.states (id, objects_id, calcdate, documents_id, startpay, pay, statetypes_id, id_import)
           values (sm.seqstates.nextval, aobject_id, state_date, adocset_id, coalesce(cast(state_initial_cost_loc as number(27,2)),0), coalesce(cast(state_remaining_cost_loc as number(27,2)),0), coalesce(statetypes_id,1), id_import);
      -- exception
      -- when others then begin
      --     raise_application_error(-20101, 'states - ' || TO_CHAR(id));
      -- end;
   end;

  -- создадим ОД собственность
  if (property_doc is not null
     and property_client is not null
     and property_sincedate is not null) then
     create_od_import(NULL, 1, property_doc, property_base, 421, property_client, Aobject_id, property_sincedate, id_import);
  end if;
  ------------------------------------------------------------------------------------------------------------------------

  -- создадим ОД Баланс
  if (balance_doc is not null
     and balance_client is not null
     and balance_sincedate is not null) then
     create_od_import(NULL, 2, balance_doc, balance_base, 436, balance_client, Aobject_id, balance_sincedate, id_import);
  end if;
  ------------------------------------------------------------------------------------------------------------------------

  -- создадим ОД Оформление операции движения "Фонд особо ценного имущества" (может не быть)
  if (valuable_doc is not null
     and valuable_client is not null
     and valuable_sincedate is not null) then
     create_od_import(NULL, 28, valuable_doc, valuable_base, 421, valuable_client, Aobject_id, valuable_sincedate, id_import);
  end if;
  ------------------------------------------------------------------------------------------------------------------------
end import_data;
/
grant execute on SM.IMPORT_DATA to SM_ALLUSERS;
grant execute on SM.IMPORT_DATA to SM_ALL_SELECT;


prompt
prompt Creating procedure IMPORT_DATA_KADASTR
prompt ======================================
prompt
create or replace procedure sm.import_data_kadastr(
  flag in char,
  Aid_import in number,
  reestr_num number,
  kadastrno_old in varchar2,
  kadastrno_new in varchar2,
  Acomment2 in varchar2)
as
is_find_new char(1):= '1'; 
Akadastrno_old varchar2 (22) := '';
Aobjtypes_id number(27);
begin
  /* 12/10/2016 Импортируем данные по кадасторвым номерам*/
  
  if (Aid_import is null) then
    RETURN;
  end if;
  
  if (reestr_num is null) then
    RETURN;
  end if;  
  
  if (kadastrno_new is null or 
      trim(kadastrno_new) = '' or 
      trim(upper(kadastrno_new)) = 'НЕТ' or
      trim(upper(kadastrno_new)) = 'В БАЗЕ'
      ) then      
      is_find_new := '0';
  end if;    
  
  -- если новый номер не найден
  -- то просто выставим комментарий
  Execute immediate ('ALTER TABLE sm.objects DISABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.BUILDINGS DISABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.UNCONSTR DISABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.ENGINF DISABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.GROUNDS DISABLE ALL TRIGGERS');
  
  if (is_find_new = '0') then
    update sm.objects o
       set o.id_import_kadastr = Aid_import,
           o.comment2 = Acomment2
     where o.id = reestr_num
       and o.id_import_kadastr is null;                
  else
    -- получим старый номер
    Akadastrno_old := '';
    select o.kadastrno,
           o.objtypes_id
      into Akadastrno_old,
           Aobjtypes_id
      from sm.objects o
     where o.id = reestr_num;
    
    update sm.objects o
       set o.kadastrno_old = Akadastrno_old
     where o.id = reestr_num
       and o.id_import_kadastr is null;
       
     update sm.objects o
       set o.id_import_kadastr = Aid_import,
           o.comment2 = Acomment2,
           o.kadastrno = kadastrno_new
     where o.id = reestr_num;        
       
     if (Aobjtypes_id = 3) then
         update sm.BUILDINGS b
            set b.kadastrno = kadastrno_new
          where b.objects_id = reestr_num; 
     end if;
     
     if (Aobjtypes_id = 4) then
         update sm.UNCONSTR b
            set b.kadastrno = kadastrno_new
          where b.objects_id = reestr_num; 
     end if;
     
     if (Aobjtypes_id = 5) then
         update sm.ENGINF b
            set b.kadastrno = kadastrno_new
          where b.objects_id = reestr_num; 
     end if;
     
     if (Aobjtypes_id = 7) then
         update sm.GROUNDS b
            set b.kadastrno = kadastrno_new
          where b.objects_id = reestr_num; 
     end if;
         
  end if;     
  Execute immediate ('ALTER TABLE sm.objects ENABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.BUILDINGS ENABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.UNCONSTR ENABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.ENGINF ENABLE ALL TRIGGERS');
  Execute immediate ('ALTER TABLE sm.GROUNDS ENABLE ALL TRIGGERS');
end import_data_kadastr;
/
grant execute on SM.IMPORT_DATA_KADASTR to SM_ALLUSERS;


