prompt
prompt Creating procedure IMPORT_KADASTR_DATE
prompt ======================================
prompt
create or replace procedure sm.import_kadastr_date as

ObjectType number(27);
begin
  --26042024 Чувыкин - импорт даты присвоения кадастрового номера
  for xxx in
             (select *
                from TMP_IMPORT_COST t)
  loop
     
      -- определение типа объекта
      begin
      select
      o.objtypes_id 
      into
      ObjectType
      from
      sm.objects o
      where
      o.id=xxx.object_id;
      exception
      when NO_DATA_FOUND then
      null; 
      end;

begin
      if ObjectType = 3 then
        begin
          update sm.buildings set sm.buildings.kadno_date = xxx.kadno_date where sm.buildings.objects_id = xxx.object_id;
        exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end; 
        end;     
      end if;

      if ObjectType = 5 then
        begin
          update sm.enginf set sm.enginf.kadno_date = xxx.kadno_date where sm.enginf.objects_id = xxx.object_id;
        exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end; 
        end;     
      end if;
      
      if ObjectType = 7 then
        begin
          update sm.grounds set sm.grounds.kadno_date = xxx.kadno_date where sm.grounds.objects_id = xxx.object_id;
        exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end; 
        end;     
      end if;      

      if ObjectType = 4 then
        begin
          update sm.unconstr set sm.unconstr.kadno_date = xxx.kadno_date where sm.unconstr.objects_id = xxx.object_id;
        exception
             when others then begin
               raise_application_error(-20101, TO_CHAR(xxx.object_id));
            end; 
        end;     
      end if; 
            
end;

  end loop;

  delete from TMP_IMPORT_COST;
end import_kadastr_date;
/

prompt
prompt Creating procedure LOAD_DOCS_SCAN
prompt =================================
prompt
create or replace procedure sm.load_docs_scan(Flag in char default '1') is
  strLoadFrom varchar2(2000) := 'd:\scans\';
  strLoadTo varchar2(2000) := 'd:\docs\';
  strLoadToIP varchar2(2000) := '\\192.168.173.10\docs\';
  i number(27);

  v_file utl_file.file_type;
  v_file_log utl_file.file_type;
  filename varchar2(512) := '';
  filename_new varchar2(512) := '';
  fullpath varchar2(1024) := '';
  strLine varchar2(1024);
  strErr varchar2(2000);

  id_documents number(27);
  id_object number(27);
  number_deal varchar2(30);
  doc_number varchar2(40);
  doc_date date;
  seria_1 varchar2(20);
  seria_2 varchar2(20);
  Odoc_number varchar2(40) := '-1';
  Odoc_date date;
  Oseria_1 varchar2(20);
  Oseria_2 varchar2(2);
  is_file_tag_open char(1) := '0';
  is_file_tag_close char(1) := '0';
  name_files varchar2(255);
  doc_type number(27);
  sql_ varchar2(255);
  pos number(27);
  Adocset_id number(27);
  is_find_doc char(1);
  is_find_obj char(1);
  j number(27);
begin
  /* 25/05/2015 Загружает сканы документов из архива в медиаархив*/

  -- получим список файлов для загрузки
  begin
    dbms_java.grant_permission('SM', 'SYS:java.io.FilePermission', strLoadFrom || '-', 'read,write');
    get_dir_list(strLoadFrom);
  end;

  -- теперь идем по списку файлов и загружаем файлы
  for
   xxx in (
           select a.filename,
                  a.fullpath
             from sm.ais_dir_list a
            where a.is_directory = '1'
              and a.fullpath is not null
            order by 1
           )
  loop
    fullpath := xxx.fullpath;
    if (fullpath is not null) then
      get_dir_list(fullpath || '\');
      for
         yyy in (
                 select a.filename,
                        a.fullpath
                   from sm.ais_dir_list a
                  where a.filename like '%.ini'
                    and a.is_directory = '0'
                    and a.fullpath = xxx.fullpath || '\' || a.filename
                  order by 1
                 )
      loop
        filename := yyy.filename;
        fullpath := xxx.fullpath || '\';

        begin
          if (filename is not null) then
            -- откроем файл
            sql_ := 'CREATE OR REPLACE DIRECTORY test AS ''' || fullpath || '''';
            EXECUTE IMMEDIATE sql_;

            v_file := utl_file.fopen('TEST', filename, 'r');

            i := 0;
            is_file_tag_open := '0';
            is_file_tag_close := '0';
            number_deal := '';
            -- читаем файл
            while (i = 0 and v_file.id is not null)
            loop
              -- читаем файл
              begin
                utl_file.get_line(v_file, strLine);
              exception
                when no_data_found then
                  i := 1;
              end;

              if (strLine is not null) then
                -- проверим что за тег
                strLine := strLine;
                if (trim(strLine) = '[file]') then
                   is_file_tag_open := '1';
                end if;

                -- если тег начала найден
                if (is_file_tag_open = '1') then
                  if (trim(strLine) LIKE '%[number_deal]%' and number_deal is null) then
                     pos := INSTR(trim(strLine),':',1,1);
                     number_deal := trim(substr(strLine, pos + 1,length(strLine)));
                     if (number_deal = '' or number_deal = '0') then
                       number_deal := NULL;
                     end if;
                  end if;
                  if (trim(strLine) LIKE '[name_files]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     name_files := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[type]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     doc_type := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[seria_1]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     seria_1 := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[seria_2]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     seria_2 := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[number]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     doc_number := trim(substr(strLine, pos + 1,length(strLine)));
                     if (doc_number = '' or doc_number = '0') then
                       doc_number := 'б/н';
                     end if;
                  end if;
                  if (trim(strLine) LIKE '[date]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     doc_date := substr(strLine, pos + 1,length(strLine));
                  end if;

                  if (trim(strLine) LIKE '[Oseria_1]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     Oseria_1 := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[Oseria_2]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     Oseria_2 := substr(strLine, pos + 1,length(strLine));
                  end if;
                  if (trim(strLine) LIKE '[Onumber]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     Odoc_number := trim(substr(strLine, pos + 1,length(strLine)));
                  end if;
                  if (trim(strLine) LIKE '[Odate]%') then
                     pos := INSTR(trim(strLine),':',1,1);
                     Odoc_date := substr(strLine, pos + 1,length(strLine));
                  end if;

                  if (trim(strLine) = '[/file]') then
                     is_file_tag_close := '1';
                  end if;
                end if;

                -- если найдены оба тега
                if (is_file_tag_open = '1' and is_file_tag_close = '1') then
                  if (number_deal = '' or number_deal is null or number_deal = 0) then
                    raise_application_error (-20101,'Не заполнен номер дела:' || filename);
                  end if;
                   -- найдем документы в базе данных
                   id_documents := NULL;
                   -- свидетельство
                   if (doc_type = 748 and name_files is not null) then
                      id_object := NULL;
                      is_find_doc := '0';
                      is_find_obj := '0';

                      -- найдем документ
                      for xxx in (
                                    select d.id
                                      from sm.documents d
                                     where d.docno LIKE '%' || doc_number || '%'
                                       and d.docdate = doc_date
                                       and d.doctypes_id IN (748, 1742)
                                     order by d.doctypes_id desc
                                  )
                      loop
                        id_documents := xxx.id;
                        is_find_doc := '1';

                        if (is_find_obj = '0') then
                          -- найдем объект
                          begin
                             id_object := NULL;
                             select s.object_id
                               into id_object
                               from (
                                   select DISTINCT mi.object_id as object_id, coalesce(mp.enddate, cast('31.12.2050' as date))
                                     from docset_members d
                                     join sm.moveperiods mp on mp.docset_id = d.docset_id
                                     join sm.moveitems mi on mi.moveperiod_id = mp.id
                                    where d.document_id = id_documents
                                    order by 2 DESC
                                    )s
                               where rownum <= 1;
                             exception
                              when no_data_found then begin
                                is_find_obj := '0';
                                select s.object_id
                                  into id_object
                                  from (
                                        select DISTINCT mi.object_id as object_id, coalesce(mp.enddate, cast('31.12.2050' as date))
                                          from docset_members d
                                          join sm.movesets ms on ms.docset_id = d.docset_id
                                          join sm.moveperiods mp on mp.moveset_id = ms.id
                                          join sm.moveitems mi on mi.moveperiod_id = mp.id
                                         where d.document_id = id_documents
                                         order by 2 DESC
                                       )s
                               where rownum <= 1;
                                exception
                                when no_data_found then
                                  is_find_obj := '0';
                              end;
                              when others then
                              raise_application_error (-20101,'Ошибка поиска объекта в папке:' || number_deal || ' документ: '|| id_documents || ' № ' || doc_number);
                          end;

                          if (id_object is not null) then
                            is_find_obj := '1';
                            filename_new := number_deal || '_' || id_documents || '.pdf';
                            --utl_file.fcopy('TEST', name_files, 'DOCS_SCAN', filename_new);
                            j := File_API.copy (fullpath || name_files, strLoadTo || filename_new);
                            update sm.documents d
                               set d.file_scan = strLoadToIP || filename_new,
                                   d.folder = coalesce(number_deal, cast(d.id as varchar2(30)))
                             where d.id = id_documents;
                            update sm.objects o
                               set o.folder = coalesce(o.folder, number_deal)
                             where o.id = id_object;
                           end if;
                         end if;
                      end loop;

                      -- если не нашли, то пробуем найти по старому значению номера
                      -- свидетельства если оно есть
                      if (is_find_doc = '0') then
                        is_find_obj := '0';
                        for xxx in (
                                      select d.id
                                        from sm.documents d
                                       where d.docno LIKE '%' || Odoc_number || '%'
                                         and d.docdate = Odoc_date
                                         and d.doctypes_id IN (748, 1742)
                                       order by d.doctypes_id desc
                                    )
                        loop
                          id_documents := xxx.id;
                          is_find_doc := '1';

                          -- если нашли документ, то обновим номера
                          update sm.documents d
                             set d.docno = seria_1 || '-' || seria_2 || ' ' || doc_number,
                                 d.docdate = doc_date
                           where d.id = id_documents;

                          if (is_find_obj = '0') then
                            -- найдем объект
                            begin
                             id_object := NULL;
                             select s.object_id
                               into id_object
                               from (
                                   select DISTINCT mi.object_id as object_id, coalesce(mp.enddate, cast('31.12.2050' as date))
                                     from docset_members d
                                     join sm.moveperiods mp on mp.docset_id = d.docset_id
                                     join sm.moveitems mi on mi.moveperiod_id = mp.id
                                    where d.document_id = id_documents
                                    order by 2 DESC
                                    )s
                               where rownum <= 1;
                             exception
                              when no_data_found then begin
                                is_find_obj := '0';
                                select s.object_id
                                  into id_object
                                  from (
                                        select DISTINCT mi.object_id as object_id, coalesce(mp.enddate, cast('31.12.2050' as date))
                                          from docset_members d
                                          join sm.movesets ms on ms.docset_id = d.docset_id
                                          join sm.moveperiods mp on mp.moveset_id = ms.id
                                          join sm.moveitems mi on mi.moveperiod_id = mp.id
                                         where d.document_id = id_documents
                                         order by 2 DESC
                                       )s
                               where rownum <= 1;
                                exception
                                when no_data_found then
                                  is_find_obj := '0';
                              end;
                              when others then
                              raise_application_error (-20101,'Ошибка поиска объекта в папке:' || number_deal || ' документ: '|| id_documents || ' № ' || doc_number);
                            end;

                            if (id_object is not null) then
                              is_find_obj := '1';
                              filename_new := number_deal || '_' || id_documents || '.pdf';
                              --utl_file.fcopy('TEST', name_files, 'DOCS_SCAN', filename_new);
                              j := File_API.copy (fullpath || name_files, strLoadTo || filename_new);
                              update sm.documents d
                                 set d.file_scan = strLoadToIP || filename_new,
                                     d.folder = coalesce(number_deal, cast(d.id as varchar2(30)))
                               where d.id = id_documents;
                              update sm.objects o
                                 set o.folder = coalesce(o.folder, number_deal)
                               where o.id = id_object;
                             end if;
                           end if;
                        end loop;
                      end if;

                      if (is_find_doc = '0')then
                         raise_application_error (-20101,'Не найден документ в папке:' || number_deal || ' документ: № ' || doc_number);
                      end if;

                      if (is_find_obj = '0') then
                         raise_application_error(-20101,'Не найден объект в папке:' || number_deal || ' документ: '|| id_documents || ' № ' || doc_number);
                      end if;
                   end if;

                   -- тех паспорт
                   if (doc_type IN (1546,1792,2452) and name_files is not null) then
                     if (id_object is not null) then
                        -- найдем у объекта пакет
                        Adocset_id := NULL;
                        begin
                          select o.docset_id
                            into Adocset_id
                            from sm.objects o
                           where o.id = id_object;
                          exception
                          when no_data_found then
                            begin
                             -- создадим документ
                             insert into sm.docsets (id)
                             values (sm.seqdocsets.nextval);
                             select sm.seqdocsets.currval
                               into Adocset_id
                               from dual;
                             -- привяжем к объекту
                             update sm.objects o
                                set o.docset_id = Adocset_id
                              where o.id = id_object;
                            end;
                        end;
                        -- поищем документ если уже такой загружали
                        begin
                          select d.id
                            into id_documents
                            from sm.documents d
                           where d.docno LIKE '%' || doc_number || '%'
                             and d.docdate = doc_date
                             and d.folder = number_deal
                             and d.doctypes_id = doc_type
                             and rownum <= 1;
                          exception
                          when no_data_found then
                            begin
                             -- создадим документ
                             select sm.seqdocuments.nextval
                               into id_documents
                               from dual;

                             filename_new := number_deal || '_' || id_documents || '.pdf';

                             -- добавим документ в пакет
                             begin
                               insert into documents (id, docno, docdate, doctypes_id, docsubscr_id, startdate, needconditiondoc,
                                                      conditiondate, conditiondoc, explanation, executed, body, subscribed_by,
                                                      subscribe_purpose, moved_user, date_start, date_end, ust_date_start,
                                                      ust_date_num, ust_date_check, file_extention, file_scan, folder)
                                    values (id_documents, doc_number, doc_date, doc_type, null, doc_date, 'N', null, null, null,
                                           'Y', null, '', '', '', null, null, null, '', 1, '', strLoadToIP || filename_new, number_deal);
                                exception
                                  when others then
                                       raise_application_error(-20101,'Ошибка создания документа в папке:' || number_deal || ' № ' || doc_number);
                             end;
                            end;
                        end;
                        -- добавим документ в наш пакет
                        begin
                          select m.document_id
                            into id_documents
                            from sm.docset_members m
                           where m.docset_id = Adocset_id
                             and m.document_id = id_documents;
                          exception
                          when no_data_found then
                          begin
                            insert into sm.docset_members (docset_id, document_id, docrole_id)
                                 values (Adocset_id, id_documents, null);
                          end;
                        end;
                        -- добавим объекту
                        filename_new := number_deal || '_' || id_documents || '.pdf';
                        --utl_file.fcopy('TEST', name_files, 'DOCS_SCAN', filename_new);
                        j := File_API.copy (fullpath || name_files, strLoadTo || filename_new);
                     end if;
                   end if;
                   is_file_tag_open := '0';
                   is_file_tag_close := '0';
                   --number_deal := '';
                   doc_number := '';
                   doc_date := NULL;
                   seria_1 := '';
                   seria_2 := '';
                   Odoc_number := '-1';
                   Odoc_date := NULL;
                   Oseria_1 := '';
                   Oseria_2 := '';
                   name_files := '';
                   doc_type := 0;
                end if;
              end if;
              strLine := '';
            end loop;
            utl_file.fclose(v_file);
          end if;
          -- исключение
         /* exception
          when others then
             utl_file.fclose(v_file);
             exit;
          raise;*/
        end;
      end loop;
     end if;
  end loop;
end load_docs_scan;
/
grant execute on SM.LOAD_DOCS_SCAN to SM_ALL_SELECT;


