prompt
prompt Creating procedure PUTCUSTOMCHARGE
prompt ==================================
prompt
create or replace procedure sm.PutCustomCharge (PaySize in number, AMoveSet_ID in number, AOblType_ID in number, DocID in number, AChargeDate in DATE, ChargeComment in varchar2, AFineDate in date) is
 S varchar2(100);
begin

  if ChargeComment is null then
   S:='Начислено: ' || RTRIM(ExpandDoc(DocID));
  else
   S:=ChargeComment;
  end if;

  insert into Charges (chargedate, movesets_id, obligationtype_id, document_id, comments, paysize, charge_type, Finedate)
  values
    (AChargeDate, AMoveSet_ID, AOblType_ID, DocID, S, Paysize, 'OTHER', AFineDate);

  FullRecalcFines(AMoveSet_ID, AOblType_ID);

end PutCustomCharge;
/
grant execute on SM.PUTCUSTOMCHARGE to SM_ALL_SELECT;
grant execute on SM.PUTCUSTOMCHARGE to SM_CANMOVE;
grant execute on SM.PUTCUSTOMCHARGE to SM_CANPAY;


prompt
prompt Creating procedure RECALCALLCHARGES
prompt ===================================
prompt
create or replace procedure sm.RecalcAllCharges
 is
TMP_recalc_start_date DATE;
Arecalc_start_date  DATE;
 BEGIN
	 
 Arecalc_start_date := to_date(SM.Getparametersimple('RECALC_START_DATE'), 'dd.MM.yyyy');
-----------------------------------------------------------------------------------------------
 for X IN (select ms.ID
					from Movesets ms, Moveperiods mp
					where
						ms.id=mp.moveset_id and
						mp.id in ( select id
											 from  Moveperiods
											 where
												 SINCEDATE<=sysdate and
												(ENDDATE>=sysdate-30 or ENDDATE is null)
											)
					order by ms.ID )
 LOOP  --000
				begin
					---- !!! Диагностика !!! В норме - закомментировать!!! -----
--	   					        insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
--								      values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'Начинаю пересчет ОД ' || to_char(X.ID), 'RecalcAllCharges', 'TEST(/JOB)', 3, 3, 2, X.ID, null, 'N');
--											commit;
					-------END ---Диагностика --------------------------------------------------	

-- VVV -- 15.12.2013 -- При тотальном расчете (что делает данная функция) - учитывать только последние события ведущие к пересчету! (TODO: + глобальную установку )
					Select 	max(ob.recalc_start_date) into TMP_recalc_start_date from sm.obligations ob where ob.moveset_id = X.ID;
					if Arecalc_start_date = to_date('01.01.3000','dd.MM.yyyy') then 	
						    Arecalc_start_date := SYSDATE -1;
					end if;	 
					Update sm.obligations ob set 	ob.recalc_start_date = Arecalc_start_date  where ob.moveset_id = X.ID;		

          					 SM.FullRecalcCharges(X.ID);    --- <<< СОБСТВЕННО РАСЧЕТ !!! ---

-- VVV -- 15.12.2013 -- Возвращаем дату
					Update sm.obligations ob set 	ob.recalc_start_date = TMP_recalc_start_date where ob.moveset_id = X.ID;		
			
				exception
						when others then
								 insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
								 values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'Ошибка при полном пересчете в ОД ' || to_char(X.ID), 'RecalcAllCharges', 'JOB', 3, 3, 2, X.ID, null, 'N');
				end;
				commit;
END LOOP; --0
------------ После всего - батчевые подчистки:
------- Добавлено 4.7.3  Подчищаем Учетные Данные по расчетам для удаленных "первоисточников" ("осиротевших" учетных записей) -----
---  SM.OBLIG_ACC_PKG.ReviseAllChargeApplies; -- <<< 29.05.2013 Закомментировано до выяснения проблем применения на "старых" данных
END; -- RecalcAllCharges
/
grant execute on SM.RECALCALLCHARGES to SM_ALLUSERS;
grant execute on SM.RECALCALLCHARGES to SM_ALL_SELECT;


prompt
prompt Creating procedure RECALCALLFINES
prompt =================================
prompt
create or replace procedure sm.RecalcAllFines is
  -- by XSGROUP ver. 19.05.2010
  -- процедура пересчитывает пеню для ВСЕХ начислений, включая НЕАКТУАЛЬНЫЕ
  -- если для данного обязательства CHARGE_FINE_STOPFINES=N
CHARGE_FINE_STOPFINES char(1);
DEFAULT_CHARGE_FINE_STOPFINES char(1) := 'Y';

begin
  
  for ob in (select * from sm.obligations)
  loop
				begin
								select nvl(trim(op.CHARGE_FINE_STOPFINES), DEFAULT_CHARGE_FINE_STOPFINES)
								into
									CHARGE_FINE_STOPFINES
								from
									sm.OBLIG_PRESETS op
								where
									op.id=ob.OBLIG_PRESETS_ID;
							exception
								when NO_DATA_FOUND then
									CHARGE_FINE_STOPFINES:=DEFAULT_CHARGE_FINE_STOPFINES;
				end; 
		         
				if CHARGE_FINE_STOPFINES='N' then
					       sm.Fullrecalcfines(ob.Moveset_id, ob.Obligationtype_id);
					       commit;
				end if;
  end loop;

end; -- RecalcAllFines
/
grant execute on SM.RECALCALLFINES to SM_ALLUSERS;
grant execute on SM.RECALCALLFINES to SM_ALL_SELECT;


prompt
prompt Creating procedure RECALCALLOBJPOSITIONS
prompt ========================================
prompt
create or replace procedure sm.RecalcAllObjPositions is
--
--  by XSGROUP ver. 15.06.2010
--  Процедура заполняет таблицу OBJECT_POSITION
--
begin

  delete from sm.OBJECT_POSITION;
  commit;
  
  for xx in (select --+ FIRST_ROWS
               sm.getpositionclientidbydate(ob.obj_id,mv.id,sysdate) as  CL_ID, mv.id as MT_ID, ob.OBJ_ID as OBJ_ID 
             from
               (select 
                  o.id OBJ_ID 
                from 
                  sm.objects o
                ) ob,
               (select 
                  mt.id 
                from 
                  sm.movetype mt) mv              )
    loop                 
      if xx.CL_ID is not null then
        insert into sm.object_position (client_id,object_id,movetype_id) values (xx.CL_ID,xx.OBJ_ID,xx.MT_ID);
        commit;
      end if;  
    end loop;

 
end;
/
grant execute on SM.RECALCALLOBJPOSITIONS to SM_ALLUSERS;
grant execute on SM.RECALCALLOBJPOSITIONS to SM_ALL_SELECT;


prompt
prompt Creating procedure RECALCMIBALANCEOBJSTATE
prompt ==========================================
prompt
create or replace procedure sm.RecalcMIBalanceObjState(
                                                                 ObjID in number,
                                                                 StateDate in date, StateDatePrev in date,
                                                                 DocID in number,
                                                                 ShareType in char)
  as
--
-- XSGROUP ver. 4.7.5
-- Процедура пересчитывает долю (при участии акциями) и стоимость объекта ObjID "Пакеты акций, доли в капитале" на дату StateDate
-- в ОД "Балансодержание",
-- при этом в случае участия акциями количество акций остается неизменным,
--            а в случае долевого участия - размер доли остается неизменным.
-- Параметры
--  StateDate: дата операции с УК
--  StateDatePrev: при корректировке операций с УК - это прежняя (до корректировки) StateDate, при создании новой операции с УК = StateDate
--  DocID: документ-основание изменений
--  ShareType: 'N' - участие акциями, 'P' - долевое участие
--
  nTmp number(27);

  newMPEnd date;

  oldSTID number(27);
  oldMPID number(27);
  oldMIID number(27);

  newSTID number(27);
  newMPID number(27);
  newMIID number(27);
  newDSID number(27);

  sharesNumberOLD number(27,6);
  amountOLD number(27,6);
  nominalCostOLD number(27,6);

  sharesNumberNew number(27,6);
  amountNew number(27,6);
  nominalCostNew number(27,6);

  ObjSharesOwnerID number(27);
  OrgID number(27);
  nCost number(27,2);

  datePrev date;
  dateSince date;
  nNominal number;
begin
  select objtypes_id into nTmp from sm.objects o where o.id=ObjID;
  if (nTmp <> 21) then
         raise_application_error(-20101,'Недопустимый тип объекта для выполнения данной процедуры.');
  end if;

  -- Собственник (акционер, участник, учредитель), ЮЛ
  select osh.owner_id, osh.organisations_id
     into
         ObjSharesOwnerID, OrgID
     from
         sm.objshares osh
     where
         osh.objects_id=ObjID;
  if (ObjSharesOwnerID is null) then
       raise_application_error(-20101,'Не установлен собственник (акционер, участник, учредитель) объекта "Пакеты акций, доли в капитале".');
  end if;
  if (OrgID is null) then
     raise_application_error(-20101, 'Не указано юридическое лицо (эмитент) в объекте.');
  end if;

  if (StateDate < StateDatePrev) then
     datePrev := StateDate;
  else
     datePrev := StateDatePrev;
  end if;
  
  for xxxMS in (
      select
        ms.id 
      from
        sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
      where
        mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
        mp.sincedate<= datePrev and
        mi.object_id=ObjID and
        ms.movetype_id=2
  ) loop
        --Находим предыдущее "движение" - состояние
        for xxMI in (
          select
            ms.id as MSID,
            mp.id as MPID,
            mi.id as MIID,
            mi.state_id as STID,
            mi.sharesnumber as sharesnumber,
            mi.amount as amount,
            mi.nominalcost as nominalcost
          from
            sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
          where
            mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
            mp.sincedate = (select max(mmp.sincedate) -- !!!
                                 from
                                    sm.moveitems mmi, sm.moveperiods mmp, sm.movesets mms
                                  where
                                    mmi.moveperiod_id = mmp.id and mmp.moveset_id = mms.id and
                                    mmp.sincedate <= datePrev and  -- !!! StateDatePrev
                                    mmi.object_id=mi.object_id and
                                    mms.id=ms.id) and
            mi.object_id=ObjID and
            ms.id=xxxMS.id
                   )
        loop
           oldMPID := xxMI.MPID;
           oldMIID := xxMI.MIID;
           oldSTID := xxMI.STID;
    
           sharesNumberOLD := xxMI.sharesnumber;
           amountOLD := xxMI.Amount;
           nominalcostOLD := xxMI.Nominalcost;
           exit;
        end loop;


        -- УК(УФ) ЮЛ
        nCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, StateDate, 'C'),0);
        if (nCost <= 0) then
           raise_application_error(-20101, 'Не сформирован уставный капитал '||chr(10)
                                                  ||'юридического лица (эмитента) на ' ||to_char(StateDate, 'dd.MM.yyyy') ||'. ');
        end if;

        -- Вычисляем значения для следующего периода
        -- Если участие акциями
        if (ShareType = 'N') then
            if (sharesNumberOLD is not null) then
                if (nvl(sharesNumberOLD, 0) <> 0) then
                   nNominal := nominalcostOLD / sharesNumberOLD;
                else
                   nNominal := 0;
                end if;

                -- рассчет размера доли в % и руб. по количеству акций
                nominalCostNew := round(sharesNumberOLD * nNominal, 6);
                amountNew := round(nominalCostNew * 100 / nCost, 6);
                sharesNumberNew := sharesNumberOLD;
            end if;

        -- Если участие долями
        else
            -- рассчет размера доли в руб. по количеству %
            nominalCostNew := round(nCost * amountOLD / 100, 6);
            amountNew := amountOLD;
            sharesNumberNew := null;

        end if; -- end Вычисляем значения для следующего периода


        --Находим ID состояние на дату операции с УК ( на прежнюю дату)
        select count(*) into nTmp from sm.states st where st.objects_id = ObjID and st.calcdate = StateDatePrev;   
        if (nTmp > 0) then
           select st.ID into newSTID from sm.states st where st.objects_id = ObjID and st.calcdate =  StateDatePrev; 
        end if;

        --ищем соответствующее "движение"  на дату операции с УК ( на прежнюю дату) 
        for xxMI in (
        select
          mi.id as miID
        from
          sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
        where
          mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
          ms.id = xxxMS.ID and
          mi.object_id = ObjID and mp.sincedate =  StateDatePrev and
          ms.id=xxxMS.id
                 )
        loop
         if (xxMI.miID is not null)
          then
             newMIID := xxMI.miID;
             exit;
          end if;
        end loop;
              
        -- если период уже существует, сохраняем новые значения
        if (newMIID is not null) then
               -- Если участие акциями
               if (ShareType = 'N') then
                 update sm.moveitems mi
                   set
                       amount = amountNew,
                       nominalcost = nominalCostNew
      	           where id = newMIID;

               -- Если участие долями
               else
                 update sm.moveitems mi
                   set
                       nominalcost = nominalCostNew
      	           where id = newMIID;
               end if;

               -- если изменилась дата периода ОД
               if StateDatePrev <> StateDate then              
    						 update SM.MOVEPERIODS set SINCEDATE = StateDate where MOVESET_ID = xxxMS.ID and SINCEDATE = StateDatePrev;
               end if;

        -- если нет периода, создаем новый
        else              
              -- определяем дату окончания нового периода
               if (amountNew = 0 or nominalCostNew = 0) then
                   newMPEnd := StateDate;
                   amountNew := 0;  
                   nominalCostNew := 0; 
                   sharesNumberNew := 0; 
               else
                    select
                      count(mp.ID) into nTmp
                    from
                      sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
                    where
                      mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
                      ms.id = xxxMS.ID and
                      mi.object_id = ObjID and mp.sincedate >  StateDate and
                      ms.id=xxxMS.id;   
                    if (nTmp <> 0) then
                        select
                          mp.sincedate into newMPEnd
                        from
                          sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
                        where
                          mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
                          ms.id = xxxMS.ID and
                          mi.object_id = ObjID and mp.sincedate >  StateDate and
                          ms.id=xxxMS.id;
                          
                        newMPEnd := trunc(newMPEnd) -1;
                    end if;         
               end if;

               -- получим ID нового периода
               select sm.seqmoveperiods.nextval into newMPID from dual;

               -- создаём новый доксет
               select sm.seqdocsets.nextval into newDSID from dual;
               insert into sm.docsets ds values(newDSID);

               --создаём новый период
               insert into sm.moveperiods (id,
                                         SinceDate,
                                         EndDate,
                                         MOVESET_ID,
                                         DOCSET_ID,
                                         PREV_MOVEPERIOD_ID)
                                 values (newMPID,
                                         StateDate,
                                         newMPEnd,
                                         xxxMS.ID, 
                                         newDSID,
                                         oldMPID);

               --устанавливаем ID предыдущего периода у следующего за созданным периодом
               update sm.moveperiods mpp set mpp.PREV_MOVEPERIOD_ID=newMPID where mpp.PREV_MOVEPERIOD_ID=oldMPID and mpp.id<>newMPID;

               --устанавливаем дату окончания у предыдущего периода
               update sm.moveperiods mpp set mpp.EndDate=StateDate-1 where mpp.id=oldMPID;

               -- копируем объекты из предыдущего периода
               for yy in (select * from sm.Moveitems mi where mi.moveperiod_id=oldMPID)
               loop

                  -- получим ID нового "движения"
                  select sm.seqmoveitems.nextval into newMIID from dual;
                  insert into sm.Moveitems mi (id,
                                               LEASEPURPOSE_ID,
                                               MOVEPERIOD_ID,
                                               OBJECT_ID,
                                               PARAMS,
                                               PRICE,
                                               SHARE_DENOM,
                                               SHARE_NUM,
                                               SHAREPERCENT,
                                               STATE_ID,  -- !!!
                                               amount,
                                               unit_id,
                                               currency_id,
                                               nominalcost,
                                               sharesnumber,
                                               singlepricecurr
                                               )
                                       values (newMIID,
                                               yy.leasepurpose_id,
                                               newMPID,
                                               yy.object_id,
                                               yy.params,
                                               null,
                                               yy.share_denom,
                                               yy.share_num,
                                               yy.sharepercent,
                                               null,  --state_id -- !!!
                                               amountNew,
                                               yy.unit_id,
                                               yy.currency_id,
                                               nominalCostNew,
                                               sharesNumberNew,
                                               null
                                               );
               end loop;

               -- копируем документы в пакет документов нового периода
               for yy in (select * from sm.docset_members dsm inner join sm.moveperiods mp on mp.docset_id=dsm.docset_id where mp.id=oldMPID)
               loop
                  insert into sm.Docset_Members dsm (docset_id,document_id,docrole_id) values (newDSID,yy.document_id,yy.docrole_id);
               end loop;

               -- условия обязательств не копируем

        end if;    --end    -- если нет периода, создаем новый

        -- Пересчет "движений" - состояний (на всякий случай начиная с самой ранней даты)
        for xxxMI in (
             select * from Moveitems
             where
                OBJECT_ID = ObjID and
                MOVEPERIOD_ID in (select mp.id from sm.moveperiods mp where mp.moveset_id=xxxMS.ID and mp.sincedate>datePrev)     
              )
        loop
            -- Дата "движения" - состояния
            select p.sincedate into dateSince from sm.moveperiods p where p.id = xxxMI.Moveperiod_Id;
    
            -- Уставный капитал ЮЛ
            nCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, dateSince, 'C'),0);
            if (nCost <= 0) then
               raise_application_error(-20101, 'Не сформирован уставный капитал '||chr(10)
                                                    ||'юридического лица (эмитента) на ' ||to_char(dateSince, 'dd.MM.yyyy') ||'. ');
            end if;
    
            --Находим ID состояния
            select count(*) into nTmp from sm.states st where st.objects_id = ObjID and st.calcdate = dateSince; 
            if (nTmp > 0) then
               select st.ID into newSTID from sm.states st where st.objects_id = ObjID and st.calcdate =  dateSince;     
            end if;
    
            -- Если участие акциями
            if (ShareType = 'N') then
                if (nvl(xxxMI.Sharesnumber, 0) <> 0) then
                   nNominal := xxxMI.Nominalcost / xxxMI.Sharesnumber;
                else
                   nNominal := 0;
                end if;
    
                -- рассчет размера доли в % и руб. по количеству акций
                nominalCostNew := round(xxxMI.Sharesnumber * nNominal, 6);
                amountNew := round(nominalCostNew * 100 / nCost, 6);
    
                --корректировка последующих "движений"
                update sm.Moveitems set AMOUNT = amountNew, NOMINALCOST = nominalCostNew where id = xxxMI.id;
    
            -- Если участие долями
            else
                -- рассчет размера доли в руб. по количеству %
                nominalCostNew := round(nCost * xxxMI.Amount / 100, 6);
    
                --корректировка последующих "движений"
                update sm.Moveitems set NOMINALCOST = nominalCostNew where id = xxxMI.id;
    
            end if;
    
        end loop;
    
  end loop; -- for xxxMS

end;   --- END  RecalcMIBalanceObjState
/
grant execute on SM.RECALCMIBALANCEOBJSTATE to SM_ALLUSERS;
grant execute on SM.RECALCMIBALANCEOBJSTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure RECALCMIOWNEROBJSTATE
prompt ========================================
prompt
create or replace procedure sm.RecalcMIOwnerObjState(
                                                                 ObjID in number,
                                                                 StateDate in date, StateDatePrev in date,
                                                                 DocID in number,
                                                                 ShareType in char)
  as
--
-- XSGROUP ver. 4.7.5
-- Процедура пересчитывает долю (при участии акциями) и стоимость объекта ObjID "Пакеты акций, доли в капитале" на дату StateDate,
-- при этом в случае участия акциями количество акций остается неизменным, 
--            а в случае долевого участия - размер доли остается неизменным. 
-- Параметры
--  StateDate: дата операции с УК
--  StateDatePrev: при корректировке операций с УК - это прежняя (до корректировки) StateDate, при создании новой операции с УК = StateDate
--  DocID: документ-основание изменений
--  ShareType: 'N' - участие акциями, 'P' - долевое участие
--
  nTmp number(27);

  newMPEnd date;

  oldSTID number(27);
  oldMSID number(27);
  oldMPID number(27);
  oldMIID number(27);

  newSTID number(27);
  newMPID number(27);
  newMIID number(27);
  newDSID number(27);

  sharesNumberOLD number(27,6);
  amountOLD number(27,6);
  nominalCostOLD number(27,6);

  sharesNumberNew number(27,6);
  amountNew number(27,6);
  nominalCostNew number(27,6);

  ObjSharesOwnerID number(27);
  OrgID number(27);
  nCost number(27,2);  
  
  datePrev date;
  dateSince date;
  nNominal number;
begin
    select objtypes_id into nTmp from sm.objects o where o.id=ObjID;
    if (nTmp <> 21) then
           raise_application_error(-20101,'Недопустимый тип объекта для выполнения данной процедуры.');
    end if;

    -- Собственник (акционер, участник, учредитель), ЮЛ
    select osh.owner_id, osh.organisations_id 
       into 
           ObjSharesOwnerID, OrgID 
       from 
           sm.objshares osh 
       where 
           osh.objects_id=ObjID;
    if (ObjSharesOwnerID is null) then
         raise_application_error(-20101,'Не установлен собственник (акционер, участник, учредитель) объекта "Пакеты акций, доли в капитале".');
    end if;
    if (OrgID is null) then
       raise_application_error(-20101, 'Не указано юридическое лицо (эмитент) в объекте.');
    end if;    
    
    if (StateDate < StateDatePrev) then
       datePrev := StateDate;
    else
       datePrev := StateDatePrev;    
    end if;

    --Находим предыдущее "движение" - состояние
    for xxMI in (
      select
        ms.id as kumiMSID,
        mp.id as kumiMPID,
        mi.id as kumiMIID,        
        mi.state_id as kumiSTID,
        mi.sharesnumber as sharesnumber,
        mi.amount as amount,
        mi.nominalcost as nominalcost
      from
        sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
      where
        mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
        mp.sincedate = (select max(mmp.sincedate)
                             from
                                sm.moveitems mmi, sm.moveperiods mmp, sm.movesets mms
                              where
                                mmi.moveperiod_id = mmp.id and mmp.moveset_id = mms.id and
                                mmp.sincedate <= datePrev and  -- !!! StateDatePrev
                                mmi.object_id=mi.object_id and
                                mms.id=ms.id) and
        mi.object_id=ObjID and
        ms.client_id=ObjSharesOwnerID  
               )
    loop
       oldMSID := xxMI.kumiMSID;
       oldMPID := xxMI.kumiMPID;
       oldMIID := xxMI.kumiMIID;
       oldSTID := xxMI.kumiSTID;
       
       sharesNumberOLD := xxMI.sharesnumber;
       amountOLD := xxMI.Amount;
       nominalcostOLD := xxMI.Nominalcost;
       exit;
    end loop;


    -- Если найдено предыдущее "движение" - состояние
    if (oldMSID is not null) then
        -- УК(УФ) ЮЛ    
        nCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, StateDate, 'C'),0);
        if (nCost <= 0) then
           raise_application_error(-20101, 'Не сформирован уставный капитал '||chr(10)
                                                  ||'юридического лица (эмитента) на ' ||to_char(StateDate, 'dd.MM.yyyy') ||'. ');
        end if;
                    
        -- Вычисляем значения для следующего периода
        -- Если участие акциями
        if (ShareType = 'N') then
            if (sharesNumberOLD is not null) then 
                if (nvl(sharesNumberOLD, 0) <> 0) then     
                   nNominal := nominalcostOLD / sharesNumberOLD;
                else
                   nNominal := 0;
                end if;
                                           
                -- рассчет размера доли в % и руб. по количеству акций 
                nominalCostNew := round(sharesNumberOLD * nNominal, 6);
                amountNew := round(nominalCostNew * 100 / nCost, 6);      
                sharesNumberNew := sharesNumberOLD;         
            end if;
           
        -- Если участие долями
        else
            -- рассчет размера доли в руб. по количеству % 
            nominalCostNew := round(nCost * amountOLD / 100, 6);      
            amountNew := amountOLD;
            sharesNumberNew := null;
       
        end if; -- end Вычисляем значения для следующего периода                                                              
    
    
        --Находим ID состояние на дату операции с УК ( на прежнюю дату) 
        select count(*) into nTmp from sm.states st where st.objects_id = ObjID and st.calcdate = StateDatePrev;     
        if (nTmp > 0) then
           select st.ID into newSTID from sm.states st where st.objects_id = ObjID and st.calcdate =  StateDatePrev;     
        end if;
    
        --ищем соответствующее "движение"
        if (newSTID is not null and oldMSID is not null) then
              for xxMI in (
              select
                mi.id as kumiMIID
              from
                sm.moveitems mi, sm.moveperiods mp, sm.movesets ms
              where
                mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and
                ms.id = oldMSID and
                mi.state_id = newSTID and
                ms.client_id=ObjSharesOwnerID  
                       )
              loop
               if (xxMI.kumiMIID is not null)
                then
                   newMIID := xxMI.kumiMIID;
                   exit;
                end if;
              end loop;
        end if;
    
    
        -- если период уже существует, сохраняем новые значения
        if (newMIID is not null) then
               -- Если участие акциями
               if (ShareType = 'N') then
                 update sm.moveitems mi
                   set
                       amount = amountNew,
                       nominalcost = nominalCostNew
      	           where id = newMIID;
                   
               -- Если участие долями    
               else
                 update sm.moveitems mi
                   set
                       nominalcost = nominalCostNew
      	           where id = newMIID;           
               end if;  
    
               -- если изменилась дата периода ОД
               if StateDatePrev <> StateDate then
    						 update SM.MOVEPERIODS set SINCEDATE = StateDate where MOVESET_ID = oldMSID and SINCEDATE = StateDatePrev;
               end if;
    
        -- если нет периода, создаем новый
        else
               -- определяем дату окончания нового периода
               if (amountNew = 0 or nominalCostNew = 0) then
                   newMPEnd := StateDate;
                   amountNew := 0;  
                   nominalCostNew := 0;  
                   sharesNumberNew := 0; 
               else
                   for xxST in (
                    select
                      st.SHARESNUMBER as SHARESNUMBER,
                      st.AMOUNT as AMOUNT,
                      st.NOMINALCOST as NOMINALCOST,
                      st.calcdate as nextStateDate
                    from
                      sm.states st
                    where
                      st.objects_id = ObjID and
                      st.calcdate > StateDate
                    order by st.calcdate
                             )
                  loop
                      if (xxST.SHARESNUMBER is not null or
                         xxST.AMOUNT is not null or
                         xxST.NOMINALCOST is not null)          
                      then
                         -- дата окончания нового периода
                         newMPEnd := trunc(xxST.nextStateDate) - 1;
                         exit;
                      end if;
                   end loop;
               end if;
    
               -- получим ID нового периода
               select sm.seqmoveperiods.nextval into newMPID from dual;
    
               -- создаём новый доксет
               select sm.seqdocsets.nextval into newDSID from dual;
               insert into sm.docsets ds values(newDSID);
    
               --создаём новый период
               insert into sm.moveperiods (id,
                                         SinceDate,
                                         EndDate,
                                         MOVESET_ID,
                                         DOCSET_ID,
                                         PREV_MOVEPERIOD_ID)
                                 values (newMPID,
                                         StateDate,
                                         newMPEnd,
                                         oldMSID,
                                         newDSID,
                                         oldMPID);
    
               --устанавливаем ID предыдущего периода у следующего за созданным периодом
               update sm.moveperiods mpp set mpp.PREV_MOVEPERIOD_ID=newMPID where mpp.PREV_MOVEPERIOD_ID=oldMPID and mpp.id<>newMPID;
    
               --устанавливаем дату окончания у предыдущего периода
               update sm.moveperiods mpp set mpp.EndDate=StateDate-1 where mpp.id=oldMPID;
    
               -- копируем объекты из предыдущего периода
               for yy in (select * from sm.Moveitems mi where mi.moveperiod_id=oldMPID)
               loop
    
                  -- получим ID нового "движения"
                  select sm.seqmoveitems.nextval into newMIID from dual;
                  insert into sm.Moveitems mi (id,
                                               LEASEPURPOSE_ID,
                                               MOVEPERIOD_ID,
                                               OBJECT_ID,
                                               PARAMS,
                                               PRICE,
                                               SHARE_DENOM,
                                               SHARE_NUM,
                                               SHAREPERCENT,
                                               --STATE_ID,
                                               amount,
                                               unit_id,
                                               currency_id,
                                               nominalcost,
                                               sharesnumber,
                                               singlepricecurr
                                               )
                                       values (newMIID,
                                               yy.leasepurpose_id,
                                               newMPID,
                                               yy.object_id,
                                               yy.params,
                                               null,
                                               yy.share_denom,
                                               yy.share_num,
                                               yy.sharepercent,
                                               --null,  --state_id
                                               amountNew,
                                               yy.unit_id,
                                               yy.currency_id,
                                               nominalCostNew,
                                               sharesNumberNew,
                                               null
                                               );
               end loop;
    
               -- копируем документы в пакет документов нового периода
               for yy in (select * from sm.docset_members dsm inner join sm.moveperiods mp on mp.docset_id=dsm.docset_id where mp.id=oldMPID)
               loop
                  insert into sm.Docset_Members dsm (docset_id,document_id,docrole_id) values (newDSID,yy.document_id,yy.docrole_id);
               end loop;
    
               -- условия обязательств не копируем
    
        end if;    --end    -- если нет периода, создаем новый
    
        -- Изменяем состояние объекта на дату периода - передаем значение состояния
        sm.ChangeMIObjState(
                                        ObjID,
                                        newSTID,
                                        StateDate,
                                        DocID,
                                        sharesNumberNew,
                                        amountNew,
                                        nominalCostNew,
                                        newMIID,
                                        null
                                        );
    end if; -- end Если найдено предыдущее "движение" - состояние

    -- Пересчет "движений" - состояний (на всякий случай начиная с самой ранней даты)
    for xxxMI in (
         select * from Moveitems
         where
            OBJECT_ID = ObjID and
            MOVEPERIOD_ID in (select mp.id from sm.moveperiods mp where mp.moveset_id=oldMSID and mp.sincedate>datePrev)
          )
    loop      
        -- Дата "движения" - состояния
        select p.sincedate into dateSince from sm.moveperiods p where p.id = xxxMI.Moveperiod_Id;
        
        -- Уставный капитал ЮЛ
        nCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, dateSince, 'C'),0);
        if (nCost <= 0) then
           raise_application_error(-20101, 'Не сформирован уставный капитал '||chr(10)
                                                ||'юридического лица (эмитента) на ' ||to_char(dateSince, 'dd.MM.yyyy') ||'. ');
        end if;
                    
        -- Если участие акциями
        if (ShareType = 'N') then 
            if (nvl(xxxMI.Sharesnumber, 0) <> 0) then     
               nNominal := xxxMI.Nominalcost / xxxMI.Sharesnumber;
            else
               nNominal := 0;
            end if;
                          
            -- рассчет размера доли в % и руб. по количеству акций 
            nominalCostNew := round(xxxMI.Sharesnumber * nNominal, 6);  
            amountNew := round(nominalCostNew * 100 / nCost, 6);
            
            --корректировка последующих "движений"
            update sm.Moveitems set AMOUNT = amountNew, NOMINALCOST = nominalCostNew where id = xxxMI.id;
      
            --корректировка последующих состояний
            update sm.states set AMOUNT = amountNew, NOMINALCOST = nominalCostNew where id = xxxMI.State_Id;             
         
        -- Если участие долями
        else
            -- рассчет размера доли в руб. по количеству % 
            nominalCostNew := round(nCost * xxxMI.Amount / 100, 6);              
            
            --корректировка последующих "движений"
            update sm.Moveitems set NOMINALCOST = nominalCostNew where id = xxxMI.id;
      
            --корректировка последующих состояний
            update sm.states set NOMINALCOST = nominalCostNew where id = xxxMI.State_Id; 
       
        end if;
        
    end loop;

end;   --- END  RecalcMIOwnerObjState
/
grant execute on SM.RECALCMIOWNEROBJSTATE to SM_ALLUSERS;
grant execute on SM.RECALCMIOWNEROBJSTATE to SM_ALL_SELECT;


