prompt Creating procedure REPL_LOAD_STATES_DATA
prompt ========================================
prompt
create or replace procedure sm.repl_load_states_data(Flag in char, Aid_documents in number, Areest number) is
Adocset_id number(27);
begin
   /* 11/02/2015 Загружает данные о состоянии объекта из кэша АИС*/

   for
      xxx in (
              select ds.calcdate, ds.startpay, ds.ratable, ds.kadastr_cost,
                     ds.workersnumber, ds.nominalcost, ds.pay
                from sm.dc_documents_detail dd
                join sm.dc_documents_states ds on ds.id_documents_detail = dd.id_documents_detail
               where dd.id_documents = Aid_documents
              )
   loop
     begin
       Adocset_id := sm.repl_load_documents('1', Aid_documents, 7, null);
       insert into sm.states (
          id,
          calcdate,
          objects_id,
          startpay,
          ratable,
          cadastralvalue,
          nominalcost,
          workersnumber,
          documents_id,
          pay
       )
       values(
          seqstates.nextval,
          xxx.calcdate,
          Areest,
          xxx.startpay,
          xxx.ratable,
          xxx.kadastr_cost,
          xxx.nominalcost,
          xxx.workersnumber,
          Adocset_id,
          xxx.pay
       );
     end;
   end loop;
end repl_load_states_data;
/
grant execute on SM.REPL_LOAD_STATES_DATA to SM_ALL_SELECT;


prompt
prompt Creating procedure REPL_LOAD_BUILDINGS_DATA
prompt ===========================================
prompt
create or replace procedure sm.repl_load_buildings_data(Flag in char, Aid_documents in number, Aclient_id in number) is
f_iud_master char(1) := 'I';
Achange_doc number(27);
begin
   /* 11/02/2015 Загружает данные по Зданиям и помещениям из кэша АИС в базу данных*/

   -- изменения по шапке (реквизиты)
   for
      xxx in (
                select b.reestr,
                       b.invno,
                       b.square
                  from sm.dc_buildings b
                 where b.id_documents = Aid_documents
              )
  loop
     -- если вставка нового объекта
     if (xxx.reestr = -1) then
        f_iud_master := 'I';
     -- если изменение реквизитов существующего объекта
     elsif (xxx.reestr <> -1) then
        f_iud_master := 'U';

        -- получим документ на изменение реквизитов
        Achange_doc := sm.repl_load_documents('2', Aid_documents, 1, null);

        update sm.objects o
           set o.invno = coalesce(trim(xxx.invno), o.invno),
               o.change_doc = Achange_doc
         where o.id = xxx.reestr;
         
         update sm.buildings o
           set o.square = coalesce(xxx.square, o.square)
         where o.objects_id = xxx.reestr;
     end if;

     -- загрузим сотояние по объекту
     repl_load_states_data (null, Aid_documents, xxx.reestr);
  end loop;
end repl_load_buildings_data;
/
grant execute on SM.REPL_LOAD_BUILDINGS_DATA to SM_ALL_SELECT;


