prompt
prompt Creating procedure REPL_LOAD_ORGANISATIONS_DATA
prompt ===============================================
prompt
create or replace procedure sm.repl_load_organisations_data(Flag in char, Aid_documents in number, Aclient_id in number) is
f_iud_master char(1) := 'I';
Areestr number(27);
Aregdoc_id number(27);
iRes number(27);
begin
   /* 11/02/2015 Загружает данные по Инженернq инфраструктуре из кэша АИС в базу данных*/

   -- изменения по шапке (реквизиты)
   for
      xxx in (
                select b.client_id,
                       
                       b.fullname,
                
                       b.director,
                       b.directorpost, b.dirphone, b.accountant, b.accphone, b.inn,
                       b.okonh, b.okpo, b.okogu, b.okato, b.okved, b.ogrn, b.kpp, b.bik, b.bankname,
                       b.account, b.corraccount, b.e_mail
                  from sm.dc_organisations b
                 where b.id_documents = Aid_documents
              )
  loop
     -- если вставка нового объекта
     if (xxx.client_id = -1) then
        f_iud_master := 'I';
     -- если изменение реквизитов существующего объекта
     elsif (xxx.client_id <> -1) then
        f_iud_master := 'U';

        Aregdoc_id := NULL;
        select c.regdoc_id
          into Aregdoc_id
          from sm.clients c
         where c.id = xxx.client_id;

        if (Aregdoc_id is not null) then
          iRes := sm.repl_load_documents('1', Aid_documents, 6, Aregdoc_id);
        end if;

        update sm.clients c
           set c.inn = coalesce(trim(xxx.inn), c.inn),
               c.okonh = coalesce(trim(xxx.okonh), c.okonh),
               c.okpo = coalesce(trim(xxx.okpo), c.okpo),
               c.OKVED_NEW = coalesce(trim(xxx.okved), c.okved),
               c.bankname = coalesce(trim(xxx.bankname), c.bankname),
               c.kpp = coalesce(trim(xxx.kpp), c.kpp),
               c.account = coalesce(trim(xxx.account), c.account),
               c.corraccount = coalesce(trim(xxx.corraccount), c.corraccount),
               c.bik = coalesce(trim(xxx.bik), c.bik),
               c.e_mail = coalesce(trim(xxx.e_mail), c.e_mail),
               c.regdoc_id = coalesce(Aregdoc_id, c.regdoc_id)
         where c.id = xxx.client_id;

         update sm.organisations o
            set o.okonh = coalesce(trim(xxx.okonh), o.okonh),
                o.okpo = coalesce(trim(xxx.okpo), o.okpo),
                o.bankname = coalesce(trim(xxx.bankname), o.bankname),
                o.account = coalesce(trim(xxx.account), o.account),
                o.corraccount = coalesce(trim(xxx.corraccount), o.corraccount),
                o.bik = coalesce(trim(xxx.bik), o.bik),
                
                o.fullname = coalesce(trim(xxx.fullname), o.fullname),
                
                o.director = coalesce(trim(xxx.director), o.director),
                o.dirphone = coalesce(trim(xxx.dirphone), o.dirphone),
                o.accountant = coalesce(trim(xxx.accountant), o.accountant),
                o.accphone = coalesce(trim(xxx.accphone), o.accphone),
                o.directorpost = coalesce(trim(xxx.directorpost), o.directorpost),
                o.okogu = coalesce(xxx.okogu, o.okogu),
                o.okato = coalesce(xxx.okato, o.okato),
                o.ogrn = coalesce(xxx.ogrn, o.ogrn)
          where o.clients_id = xxx.client_id;
     end if;

     select o.objects_id
       into Areestr
       from sm.organisations o
      where o.clients_id = xxx.client_id;
     -- загрузим состояние по объекту
     repl_load_states_data (null, Aid_documents, Areestr);
  end loop;
end repl_load_organisations_data;
/
grant execute on SM.REPL_LOAD_ORGANISATIONS_DATA to SM_ALL_SELECT;


prompt
prompt Creating procedure REPL_LOAD_PROPERTY_DATA
prompt ==========================================
prompt
create or replace procedure sm.repl_load_property_data(Flag in char, Aid_documents in number, Aclient_id in number) is
f_iud_master char(1) := 'I';
Apropgroups_id number(27);
Apropsections_id number(27);
Achange_doc number(27);
begin
   /* 11/02/2015 Загружает данные по Прочему движимому имуществу из кэша АИС в базу данных*/

   -- изменения по шапке (реквизиты)
   for
      xxx in (
                select b.reestr, b.invno, b.okof, b.propnames_id, b.model, b.dateissue, b.dateinput,
                       b.serialnum, b.info
                  from sm.dc_property b
                 where b.id_documents = Aid_documents
              )
  loop
     Apropgroups_id := null;
     Apropsections_id := null;

     if (xxx.propnames_id is not null) then
        select p.propgroups_id
          into Apropgroups_id
          from sm.propnames p
         where p.id = xxx.propnames_id;
        if (Apropgroups_id is not null) then
          select p.propsections_id
            into Apropsections_id
            from sm.propgroups p
           where p.id = Apropgroups_id;
        end if;
     end if;

     -- если вставка нового объекта
     if (xxx.reestr = -1) then
        f_iud_master := 'I';
     -- если изменение реквизитов существующего объекта
     elsif (xxx.reestr <> -1) then
        -- получим документ на изменение реквизитов
        Achange_doc := sm.repl_load_documents('2', Aid_documents, 5, null);

        f_iud_master := 'U';
        update sm.objects o
           set o.invno = coalesce(trim(xxx.invno), o.invno),
               o.okof = coalesce(xxx.okof, o.okof),
               o.change_doc = Achange_doc
         where o.id = xxx.reestr;
        update sm.property p
           set p.model = coalesce(trim(xxx.model), p.model),
               p.info = coalesce(trim(xxx.info), p.info),
               p.propnames_id = coalesce(xxx.propnames_id, p.propnames_id),
               p.dateissue = coalesce(xxx.dateissue, p.dateissue),
               p.dateinput = coalesce(xxx.dateinput, p.dateinput),
               p.serialnum = coalesce(trim(xxx.serialnum), p.serialnum),
               p.change_doc = Achange_doc
         where p.objects_id = xxx.reestr;
     end if;

     -- загрузим сотояние по объекту
     repl_load_states_data (null, Aid_documents, xxx.reestr);
  end loop;
end repl_load_property_data;
/
grant execute on SM.REPL_LOAD_PROPERTY_DATA to SM_ALL_SELECT;


