create or replace procedure sm.repl_load_transport_data(Flag in char, Aid_documents in number, Aclient_id in number) is
f_iud_master char(1) := 'I';
Achange_doc number(27);
begin
   /* 11/02/2015 Загружает данные по Транспортным средствам из кэша АИС в базу данных*/

   -- изменения по шапке (реквизиты)
   for
      xxx in (
                select b.reestr,
                       b.invno,
                       b.relyear,
                       b.fedno,
                       b.motorno,
                       b.chassisno,
                       b.bodyno,
                       b.vin
                  from sm.dc_transport b
                 where b.id_documents = Aid_documents
              )
  loop
     -- если вставка нового объекта
     if (xxx.reestr = -1) then
        f_iud_master := 'I';
     -- если изменение реквизитов существующего объекта
     elsif (xxx.reestr <> -1) then
        f_iud_master := 'U';

        -- получим документ на изменение реквизитов
        Achange_doc := sm.repl_load_documents('2', Aid_documents, 4, null);

        update sm.objects o
           set o.invno = coalesce(trim(xxx.invno), o.invno),
               o.change_doc = Achange_doc
         where o.id = xxx.reestr;

         update sm.transport o
           set o.relyear = trim(xxx.relyear),--coalesce(trim(xxx.relyear), o.relyear),
               o.fedno = coalesce(trim(xxx.fedno), o.fedno),
               o.motorno = coalesce(trim(xxx.motorno), o.motorno),
               o.chassisno = coalesce(trim(xxx.chassisno), o.chassisno),
               o.bodyno = coalesce(trim(xxx.bodyno), o.bodyno),
               o.ps_vin = coalesce(trim(xxx.vin), o.ps_vin),
               o.change_doc = Achange_doc
         where o.objects_id = xxx.reestr;
     end if;

     -- загрузим сотояние по объекту
     repl_load_states_data (null, Aid_documents, xxx.reestr);
  end loop;
end repl_load_transport_data;
/
