prompt
prompt Creating procedure REPL_LOAD_DATA_FROM_AIS
prompt ==========================================
prompt
create or replace procedure sm.repl_load_data_from_ais(Flag in char) is
Aerr varchar2(4000) := '';
filename varchar2(255) := '';
v_file utl_file.file_type;
v_sqlcommand varchar2(8000) := '';
is_create char(1) := '0';
date_import varchar(20);
begin
  /* 11/02/2015 Загружает данный из кэша АИС в базу данных*/

  date_import := to_char(sysdate, 'DD.MM.YYYY HH24:MI:SS');
  -- идем по документам
  for
     xxx in (
              select d.id_documents, d.id_documents_type, d.client_id
                from sm.dc_documents d
             )
  loop
     begin
       -- теперь сформируем ответ
       if (is_create = '0') then
         is_create := '1';
         filename := to_char(sysdate, 'YYYYMMDDHH24MISS');
         filename := filename || '_replication_ora';
         v_file := utl_file.fopen('DIRREPLTO', filename || '.repl', 'w');
       end if;

       -- Здания и помещения
       if (xxx.id_documents_type = 1) then
         repl_load_buildings_data (NULL, xxx.id_documents, xxx.client_id);
       end if;
       -- Инженерная инфраструктура
       if (xxx.id_documents_type = 2) then
         repl_load_enginf_data (NULL, xxx.id_documents, xxx.client_id);
       end if;
       -- Незавершенное строительство
       if (xxx.id_documents_type = 3) then
         repl_load_unconstr_data (NULL, xxx.id_documents, xxx.client_id);
       end if;
       -- Транспортные средства
       if (xxx.id_documents_type = 4) then
         repl_load_transport_data (NULL, xxx.id_documents, xxx.client_id);
       end if;
       -- Прочее движимое имущество
       if (xxx.id_documents_type = 5) then
         repl_load_property_data (NULL, xxx.id_documents, xxx.client_id);
       end if;
       -- Организации
       if (xxx.id_documents_type = 6) then
         repl_load_organisations_data (NULL, xxx.id_documents, xxx.client_id);
       end if;

       -- помечаем что загрузили
       update sm.dc_documents d
          set d.is_repl = '1'
        where d.id_documents = xxx.id_documents;

       v_sqlcommand := 'use WebDb; exec set_documents_status_from_oracle 1, ' || xxx.id_documents || ', ''' || date_import || '''' || ', null';
       utl_file.put_line(v_file, v_sqlcommand);
       exception
           when others then
             begin
               -- если не загрузили, то пишем текст ошибки
               Aerr := 'Number: ' || sqlcode;
               Aerr := Aerr || ' Message: ' || sqlerrm;
               update sm.dc_documents d
                  set d.err = Aerr
                where d.id_documents = xxx.id_documents;
                v_sqlcommand := 'use WebDb; exec set_documents_status_from_oracle 2, ' || xxx.id_documents || ', ''' || date_import || '''' || ', ''' || Aerr || '''';
                utl_file.put_line(v_file, v_sqlcommand);
             end;
     end;
  end loop;
  if (is_create = '1') then
    utl_file.fclose(v_file);
    utl_file.fcopy('DIRREPLTO', filename || '.repl', 'DIRREPLTOARCHIVE', filename || '.repl');
    utl_file.fcopy('DIRREPLTO', filename || '.repl', 'DIRREPLTOMSSQL', filename || '.repl');
    utl_file.fremove('DIRREPLTO', filename || '.repl');
  end if;
end repl_load_data_from_ais;
/
grant execute on SM.REPL_LOAD_DATA_FROM_AIS to SM_ALL_SELECT;


prompt
prompt Creating procedure REPL_START_REPLICATION
prompt =========================================
prompt
create or replace procedure sm.repl_start_replication(Flag in char) is
  strReplFrom varchar2(2000) := 'd:\ais\Project\Replication\Oracle\';
  strReplIn varchar2(20) := 'In';
  strReplOut varchar2(20) := 'Out';
  strReplInFull varchar2(2000);
  i number(27);

  v_file utl_file.file_type;
  v_file_log utl_file.file_type;
  v_sqlcommand varchar2(8000) := '';
  filename varchar2(512) := '';
  iCommand number(27);
  strErr varchar2(2000);
begin
  /* 09/02/2015 Открывает каталог загрузки данных, загружает файлы, запускает обработку загруженных данных из АИС*/
  /* 25/05/2015 Добавил при выборке файлов признак, что это файл*/

  -- получим список файлов для загрузки
  begin
    strReplInFull := strReplFrom || strReplIn;
    dbms_java.grant_permission('SM', 'SYS:java.io.FilePermission', strReplInFull || '\', 'read,write');
    get_dir_list(strReplInFull || '\');
    delete from dc_documents d where d.is_repl = '1';
    update dc_documents d set d.err = null;
  end;

  -- теперь идем по списку файлов и загружаем файлы, разбиваем на команды и загружаем команды в базу данных
  iCommand := 1;
  for
     xxx in (
             select a.filename filename
               from sm.ais_dir_list a
              where a.is_directory = '0'
             )
  loop
    filename := xxx.filename;
    begin
      if (filename is not null) then
        -- откроем файл
        v_file := utl_file.fopen('DIRREPLFROM', filename, 'r');
        -- создадим файл лог
        v_file_log := utl_file.fopen('DIRREPLFROMARCHIVE', filename || '.log', 'w');
        utl_file.put_line(v_file_log, 'Start:');
        utl_file.put_line(v_file_log, '--------------------------------------------------------');

        i := 0;
        -- читаем файл
        while (i = 0 and v_file.id is not null)
        loop
          -- читаем файл
          begin
            utl_file.get_line(v_file, v_sqlcommand);
          exception
            when no_data_found then
              i := 1;
          end;

          if (v_sqlcommand is not null) then
            -- запустим на исполнение команду
            begin
               EXECUTE IMMEDIATE v_sqlcommand;
               strErr := 'Command ' || cast(iCommand as varchar2) || ': успех.';
               utl_file.put_line(v_file_log, strErr);
               utl_file.put_line(v_file_log, '--------------------------------------------------------');
              exception
                when others then begin
                   strErr := 'Error command: ' || cast(iCommand as varchar2);
                   utl_file.put_line(v_file_log, strErr);
                   strErr := 'Number error: ' || SQLCODE;
                   utl_file.put_line(v_file_log, strErr);
                   strErr := 'Message: ' || SQLERRM;
                   utl_file.put_line(v_file_log, strErr);
                   strErr := 'Command: ';
                   utl_file.put_line(v_file_log, strErr);
                   utl_file.put_line(v_file_log, v_sqlcommand);
                   utl_file.put_line(v_file_log, '--------------------------------------------------------');
                end;
            end;
          end if;
          iCommand := iCommand + 1;
          v_sqlcommand := '';
        end loop;
        utl_file.fclose(v_file);
        utl_file.fclose(v_file_log);
        utl_file.fcopy('DIRREPLFROM', filename, 'DIRREPLFROMARCHIVE', filename);
        utl_file.fremove('DIRREPLFROM', filename);
      end if;
      -- исключение
      exception
      when others then
         utl_file.fclose(v_file);
         utl_file.fclose(v_file_log);
         exit;
      raise;
    end;
  end loop;

  -- обработаем данные
  begin
     sm.repl_load_data_from_ais(null);
  end;
end repl_start_replication;
/
grant execute on SM.REPL_START_REPLICATION to SM_ALL_SELECT;


