prompt
prompt Creating procedure SETMONUMENTBYPARENT
prompt ======================================
prompt
create or replace procedure sm.SetMonumentByParent(Flag in varchar2, AObjects_id in numeric) is
begin
 /* 07/11/2013 Твердохлеб: Процедура выставляет признак памятник по родителю*/
 /*
   1 - Обновить признак памятник от родителя
   2 - Обновить признак памятник детям
 */
--RAISE_APPLICATION_ERROR(-20000, ' ' || TO_CHAR(Flag)|| ' ' ||TO_CHAR(AObjects_id) ) ;
if (Flag = '1') then
  for yyy in (
              select o.id
                from sm.objects o
                join sm.buildings b on b.objects_id = o.id
               where (o.id = AObjects_id or AObjects_id is null)
                 and b.basebuilding is not null
             )
  loop
    for xxx in (
              select is_monument
                from (
                      select b.basebuilding, o.is_monument
                        from sm.Buildings b
                        join sm.objects o on o.id = b.objects_id
                       where b.objects_id <> yyy.id
                        start with b.objects_id = yyy.id
                       connect by prior b.basebuilding  = b.id
                     )
               where basebuilding is null
              )
    loop
       update sm.objects o
          set o.is_monument = xxx.is_monument,
              o.is_update = '1'
        where o.id = yyy.id;
    end loop;
  end loop;
end if;
if (Flag = '2') then
  for yyy in (
              select o.id, o.is_monument
                from sm.objects o
                join sm.buildings b on b.objects_id = o.id
               where (o.id = AObjects_id or AObjects_id is null)
             )
  loop
    for xxx in (
              select b.objects_id, o.is_monument
                from sm.Buildings b
                join sm.objects o on o.id = b.objects_id
               where b.objects_id <> yyy.id
                start with b.objects_id = yyy.id
               connect by prior b.id = b.basebuilding
              )
    loop
       update sm.objects o
          set o.is_monument = yyy.is_monument,
              o.is_update = '1'
        where o.id = xxx.objects_id;
    end loop;
  end loop;
end if;
exception
when no_data_found then null;
end SetMonumentByParent;
/
grant execute on SM.SETMONUMENTBYPARENT to SM_ALLUSERS;
grant execute on SM.SETMONUMENTBYPARENT to SM_ALL_SELECT;


prompt
prompt Creating procedure SET_BUILDINGS_NEW_PARENT
prompt ===========================================
prompt
create or replace procedure sm.Set_buildings_new_parent(Aobjects_id in number,objects_parent_old in number,objects_parent_new in number) is
 Abasebuilding_1 number;
 Abasebuilding_2 number;
 Aparent_new number;
begin
  --получим родителя нашего объекта
  select b.basebuilding
    into Abasebuilding_1
    from sm.buildings b
   where b.objects_id = Aobjects_id;
   
  --получим идентификатор старого родителя
  select b.id
    into Abasebuilding_2
    from sm.buildings b
   where b.objects_id = objects_parent_old;   
  
  if (Abasebuilding_1 <> Abasebuilding_2) then
    RAISE_APPLICATION_ERROR(-20000, 'не верные родители');
  end if;   
    
  --получим идентификатор нового родителя
  select b.id
    into Aparent_new
    from sm.buildings b
   where b.objects_id = objects_parent_new;
     
  --если все равны, значит заменяем родителя на нового
  update sm.buildings o
     set o.basebuilding = Aparent_new
   where o.objects_id = Aobjects_id;   
  
end Set_buildings_new_parent;
/
grant execute on SM.SET_BUILDINGS_NEW_PARENT to SM_ALL_SELECT;


prompt
prompt Creating procedure SET_KADASTR_COAST_FROM_EXCEL
prompt ===============================================
prompt
create or replace procedure sm.set_kadastr_coast_from_excel(kadastr_no varchar2, coast varchar2, state_date varchar2)
as
adocset_id number(27);
state_doc number(27) := 5213434;
aobject_id number(27);
StatesDate date;
Acalcdate date;
Akadastr_no varchar2(100);
bFind char(1) := '1';
begin

   /*12/10/2018 Твердохлеб: обновляем кадастровую стоимость*/

   Akadastr_no := replace(kadastr_no,'"','');

   if (Akadastr_no is null) then
     raise_application_error(-20101, 'Не указан кадастровый номер');
   end if;

   if (coast is null) then
     insert into dc_log_error (id,message,id_import)
          values (seqlogerror.nextval, 'Не указана стоимость ' || Akadastr_no, 1000);
     return;
     --raise_application_error(-20101, 'Не указана стоимость ' || kadastr_no);
   end if;

   if (state_date is null) then
     insert into dc_log_error (id,message,id_import)
          values (seqlogerror.nextval, 'Не указана дата ' || Akadastr_no, 1000);
     return;
     --raise_application_error(-20101, 'Не указана дата ' || kadastr_no);
   end if;

   if (state_doc is null) then
     raise_application_error(-20101, 'Не указан документ ' || Akadastr_no);
   end if;

   Acalcdate := cast(state_date as date);

   -- найдем документ
   begin
      aobject_id := null;
      select p.objects_id
        into aobject_id
        from (
                select g.objects_id
                  from sm.grounds g
                  where trim(g.kadastrno) = trim(Akadastr_no)
                union
                select g.objects_id
                  from sm.buildings g
                  where trim(g.kadastrno) = trim(Akadastr_no)
                union
                select g.objects_id
                  from sm.unconstr g
                  where trim(g.kadastrno) = trim(Akadastr_no)
                union
                select g.objects_id
                  from sm.enginf g
                  where trim(g.kadastrno) = trim(Akadastr_no)
             )p;
     exception
      when no_data_found then null;

      when TOO_MANY_ROWS THEN
      begin
        insert into dc_log_error (id,message,id_import)
          values (seqlogerror.nextval, 'Найдено более одного объекта в системе ' || Akadastr_no, 1000);
        return;
      end;
   end;

   if (aobject_id is null) then
     insert into dc_log_error (id,message,id_import)
          values (seqlogerror.nextval, 'Объект не найден ' || Akadastr_no, 1000);
     return;
     --raise_application_error(-20101, 'Объект не найден ' || Akadastr_no);
   end if;

   -- создадим пакет
   adocset_id := NULL;
   select sm.seqdocsets.nextval
     into adocset_id
     from dual;

   insert into sm.docsets (id)
        values (adocset_id);
   insert into sm.docset_members (docset_id, document_id, docrole_id)
        values (adocset_id, state_doc, 1);

   select max(s.calcdate)
     into StatesDate
     from sm.states s
    where s.objects_id = aobject_id;

   if (StatesDate is null) then
     insert into dc_log_error (id,message,id_import)
          values (seqlogerror.nextval, 'Дата состояния не найдена ' || Akadastr_no, 1000);
     bFind := '0';
     --raise_application_error(-20101, 'Дата состояния не найдена ' || Akadastr_no);
   end if;

   -- по просьбе Быкаревой делаем всегда отдельной строкой
   bFind := 0;
   if (bFind = '1') then
     insert into sm.states (ID,
                            PAY,
                            WEAR,
                            CALCDATE,
                            DOCUMENTS_ID,
                            STATETYPES_ID,
                            OBJECTS_ID,
                            CHANGEDBY,
                            STARTPAY,
                            WRITEDATE,
                            MUNREPORT_ID,
                            RATABLE,
                            IS_USING,
                            KADASTR_COST,
                            COST_LAND,
                            CADASTRALVALUE,
                            NOMINALCOST,
                            SHARESNUMBER,
                            SHARESPREVNUMBER,
                            WORKERSNUMBER,
                            GOLDSTOCKOWNER_ID,
                            AMOUNT,
                            CHANGE_DATE,
                            CHANGE_DOC,
                            SPECIALLYVALUED,
                            ID_IMPORT,
                            NOMINALCOST_OLD
                           )
            select  sm.seqstates.nextval,
                    PAY,
                    WEAR,
                    Acalcdate,
                    adocset_id,
                    STATETYPES_ID,
                    OBJECTS_ID,
                    CHANGEDBY,
                    STARTPAY,
                    WRITEDATE,
                    MUNREPORT_ID,
                    RATABLE,
                    IS_USING,
                    KADASTR_COST,
                    COST_LAND,
                    coast,
                    NOMINALCOST,
                    SHARESNUMBER,
                    SHARESPREVNUMBER,
                    WORKERSNUMBER,
                    GOLDSTOCKOWNER_ID,
                    AMOUNT,
                    CHANGE_DATE,
                    CHANGE_DOC,
                    SPECIALLYVALUED,
                    1000,
                    NOMINALCOST_OLD
             from sm.states s
             where s.objects_id = aobject_id
               and s.calcdate = StatesDate;
     else
          insert into sm.states (id, objects_id, calcdate, documents_id, startpay, pay, CADASTRALVALUE, statetypes_id, id_import)
           values (sm.seqstates.nextval, aobject_id, Acalcdate, adocset_id, NULL, NULL, coast, 1, 1000);
     end if;

end set_kadastr_coast_from_excel;
/

