prompt
prompt Creating procedure SET_REALESTATE
prompt =================================
prompt
create or replace procedure sm.SET_REALESTATE(ObjType in numeric) is
begin
   /*Реквизит-флажок «Является недвижимым имуществом» для объектов типа
     «Инженерная инфраструктура»  необходимо оставить активным для объектов,
     которые прошли государственную регистрацию, т.е. у которых в операциях
     движения «Собственность» и(или) «Передача на баланс» в пакетах документов
     имеются документы вида «Свидетельство» или «Свидетельство о гос. рег-ции
     права». Для остальных объектов при необходимости активизация данного
     реквизита-флажка будет осуществлена вручную. Кроме того, данный
     реквизит-флажок необходимо добавить в свойства объектов типа
     «Незавершенное строительство» и активизировать его аналогично объектам
     типа «Инженерная инфраструктура».*/

     /* 28/07/2015 Твердохлеб: Добавил условие <> 'Y'*/
     /* 18/01/2016 Твердохлеб: [260] Кроме того, при анализе данного реквизита необходимо учитывать, 
        что теперь подтверждением регистрации права кроме документов вида «Свидетельство» и «Свидетельство о гос.рег-ции права» 
        является документ «Запись о гос.рег-ции права».*/
        
     -- идем по всем ОД Собственность и Баланс
     -- где есть наш тип объекта
     for xxx in (
                  select mp.docset_id,
                         mi.object_id
                    from sm.movesets ms
                    join sm.moveperiods mp on mp.moveset_id = ms.id
                    join sm.moveitems mi on mi.moveperiod_id = mp.id
                    join sm.objects o on o.id = mi.object_id
                   where ms.movetype_id in (1,2)
                     and o.objtypes_id = ObjType
                )
      loop
         -- проверим наличие документов свидетельство
         -- или
         -- Свидетельство о гос. рег-ции права
         for yyy in (
                     select *
                       from sm.docset_members dm
                       join sm.documents d on d.id = dm.document_id and d.doctypes_id in (748, 1742,3117)
                      where dm.docset_id = xxx.docset_id
                    )
         loop
            if (ObjType = 5) then
               update sm.enginf e
                  set e.isrealestate = 'Y'
                where e.objects_id = xxx.object_id
                  and e.isrealestate <> 'Y';
            end if;
            if (ObjType = 4) then
               update sm.unconstr e
                  set e.isrealestate = 'Y'
                where e.objects_id = xxx.object_id
                  and e.isrealestate <> 'Y';
            end if;
         end loop;
      end loop;
end SET_REALESTATE;
/
grant execute on SM.SET_REALESTATE to SM_ALL_SELECT;


prompt
prompt Creating procedure SET_RIGHTS_SELECT
prompt ====================================
prompt
CREATE OR REPLACE PROCEDURE SM.SET_RIGHTS_SELECT
AS
sqlStatement varchar2(512);
cnt integer;
BEGIN
   for xxx in
      (select a.OBJECT_NAME,
              a.OBJECT_TYPE
         from all_objects a
         where  owner = 'SM'
       order by a.OBJECT_TYPE
      )
      loop
        if (xxx.OBJECT_TYPE = 'FUNCTION') then
            sqlStatement :=  'grant execute on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            EXECUTE immediate sqlStatement;
        end if;

        if (xxx.OBJECT_TYPE = 'TABLE') then
            cnt := 0;
            select count(*)
              into cnt
              from sm.fm_tables t
             where t.table_name = xxx.OBJECT_NAME;

            if (cnt > 0) then
              sqlStatement :=  'grant select on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            else
              sqlStatement :=  'grant select,Insert,update,delete on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            end if;

            EXECUTE immediate sqlStatement;
        end if;

        if (xxx.OBJECT_TYPE = 'PROCEDURE') then
            sqlStatement :=  'grant execute on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            EXECUTE immediate sqlStatement;
        end if;

        if (xxx.OBJECT_TYPE = 'PACKAGE') then
            sqlStatement :=  'grant execute on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            EXECUTE immediate sqlStatement;
        end if;

        if (xxx.OBJECT_TYPE = 'PACKAGE BODY') then
            sqlStatement :=  'grant execute on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            EXECUTE immediate sqlStatement;
        end if;

        if (xxx.OBJECT_TYPE = 'VIEW') then
            sqlStatement :=  'grant select on SM.'||xxx.OBJECT_NAME||' to SM_ALL_SELECT';
            EXECUTE immediate sqlStatement;
        end if;
      end loop;
END;
/
grant execute on SM.SET_RIGHTS_SELECT to SM_ALL_SELECT;


