prompt
prompt Creating package body CALCFINE_PKG
prompt ==================================
prompt
create or replace package body sm.CALCFINE_PKG is
  function GetChargeFineMethod(
                               AMoveSetID number,
                               AObligationTypeID number,
                               ADate date,
                               Calendar_type out number, --new АЦК 101 (для расчета пени исходя из 360 дней)
                               old360 out char --new АЦК 101
                               )return number is
    res number;
    DFAULT_CHARGE_FINE_METHOD number:=2;
    end_ms date;
  begin

    begin
      select nvl(sm.getmovesetenddate(AMoveSetID),to_date('01.01.3000','dd.MM.yyyy'))
      into end_ms
      from dual;

      if ADate<=end_ms then
            select nvl(opp.charge_fine_method,DFAULT_CHARGE_FINE_METHOD), pd.calendar_type_id, op.old360
            into
                 res, calendar_type, old360
            from
                sm.moveperiods mp,
                sm.paydocs pd,
                sm.oblig_periodical_presets opp,
                sm.obligations obl,
                sm.oblig_presets op
            where
                mp.moveset_id=AMoveSetID and
                pd.moveperiod_id=mp.id and
                pd.obligationtype_id=AObligationTypeID and
                mp.Sincedate in (select max(mpr.sincedate)
                                    from sm.moveperiods mpr
                                    where mpr.Sincedate<=ADate and
                                          mpr.moveset_id=AMoveSetID and
                                       exists (select * from sm.paydocs pds
                                               where pds.moveperiod_id=mpr.id and
                                                     pds.obligationtype_id=AObligationTypeID)) and
                --(mp.Enddate>=ADate or mp.Enddate is null) and
                opp.id=pd.oblig_periodical_presets_id and
                op.id=obl.oblig_presets_id and
                obl.obligationtype_id=AObligationTypeID and
                obl.moveset_id=AMoveSetID;
      else
            select nvl(opp.charge_fine_method,DFAULT_CHARGE_FINE_METHOD), pd.calendar_type_id, op.old360
            into
                 res, calendar_type, old360
            from
                sm.moveperiods mp,
                sm.paydocs pd,
                sm.oblig_periodical_presets opp,
                sm.obligations obl,
                sm.oblig_presets op
            where
                mp.moveset_id=AMoveSetID and
                pd.moveperiod_id=mp.id and
                pd.obligationtype_id=AObligationTypeID and
                mp.Sincedate in (select max(mpr.sincedate)
                                    from sm.moveperiods mpr
                                    where --mpr.Sincedate<=ADate and
                                          mpr.moveset_id=AMoveSetID and
                                       exists (select * from sm.paydocs pds
                                               where pds.moveperiod_id=mpr.id and
                                                     pds.obligationtype_id=AObligationTypeID)) and
                --mp.Enddate=end_ms and
                opp.id=pd.oblig_periodical_presets_id and
                op.id=obl.oblig_presets_id and
                obl.obligationtype_id=AObligationTypeID and
                obl.moveset_id=AMoveSetID;

      end if;
    exception
        when NO_DATA_FOUND then
          res:=DFAULT_CHARGE_FINE_METHOD;
          calendar_type:=365;
    end;

    return(res);

  end;

------------------------------------------------------------------------------
  procedure GetFineParamsBetween(
                          AMoveSetID number,
                          AObligationTypeID number,
                          ADateStart date,
                          ADateEnd date,
                          Paysize out number,
                          PeriodStart out date,
                          PeriodEnd out date,
                          PerComment out varchar2
                         ) is
  begin

    begin
      select
        ch.paysize,
        ch.calperiod_start,
        ch.calperiod_end,
        ch.comments
      into
        Paysize,
        PeriodStart,
        PeriodEnd,
        PerComment
      from
        sm.charges ch
      where
        ch.charge_type='FINE'and
        ch.calperiod_start<=ADateStart and
        ch.calperiod_end>=ADateEnd and -- изменено 09.2014 Медведева (двойное начисление пени, если окончание - конец периода начисления пени)
        ch.movesets_id=AMoveSetID and
        ch.obligationtype_id=AObligationTypeID;
    exception
      when NO_DATA_FOUND then
        Paysize:=null;
        PeriodStart:=null;
        PeriodEnd:=null;
        PerComment:=null;
    end;
  end;
-------------------------------------------------------------------------------
  procedure GetFineParams(
                          AMoveSetID number,
                          AObligationTypeID number,
                          ADate date,
                          --NEW новый параметр Chargedate
                          Chargedate out date,
                          Paysize out number,
                          PeriodStart out date,
                          PeriodEnd out date,
                          PerComment out varchar2
                         ) is
  begin

    begin
      select
        ch.chargedate,--NEW новый параметр Chargedate
        ch.paysize,
        ch.calperiod_start,
        ch.calperiod_end,
        ch.comments
      into
        Chargedate, --NEW новый параметр Chargedate
        Paysize,
        PeriodStart,
        PeriodEnd,
        PerComment
      from
        sm.charges ch
      where
        rownum=1 and
        ch.charge_type='FINE'and
       -- ch.calperiod_start<=ADate+1 and
        ch.calperiod_start<=ADate and
        ch.calperiod_end>=ADate and
        ch.movesets_id=AMoveSetID and
        ch.obligationtype_id=AObligationTypeID;
    exception
      when NO_DATA_FOUND then
        Chargedate:=null;--NEW новый параметр Chargedate
        Paysize:=null;
        PeriodStart:=null;
        PeriodEnd:=null;
        PerComment:=null;
    end;

  end;

-------------------------------------------------------------------------------
  function GetDelayDays(
                        What varchar2,
                        ADate date,
                        PeriodStart date,
                        PeriodEnd date,
                        calendar_type number,
                        old360 char
                        ) return number is
  Days number;
  CalcDate date;
  begin

    if old360='Y' then
      if Upper(What)='BEFORE' then
        Days:=ADate-PeriodStart+1;
      elsif Upper(What)='AFTER' then
        Days:=PeriodEnd-ADate;
      else
        return(null);
      end if;
    end if;

    if old360='N' then
      if calendar_type=365 then
        if Upper(What)='BEFORE' then
          Days:=ADate-PeriodStart+1;
        elsif Upper(What)='AFTER' then
          Days:=PeriodEnd-ADate;
        else
          return(null);
        end if;
      end if;

      if calendar_type=360 then
        if Upper(What)='BEFORE' then
        Days:=1+ (EXTRACT(YEAR FROM ADate) - EXTRACT(YEAR FROM PeriodStart))*360 + (EXTRACT(MONTH FROM ADate)-EXTRACT(MONTH FROM PeriodStart))*30 + (EXTRACT(DAY FROM ADate)-EXTRACT(DAY FROM PeriodStart));
        elsif Upper(What)='AFTER' then
        CalcDate:=ADate+1;
        Days:=1+ (EXTRACT(YEAR FROM PeriodEnd) - EXTRACT(YEAR FROM CalcDate))*360 + (EXTRACT(MONTH FROM PeriodEnd)-EXTRACT(MONTH FROM CalcDate))*30 + (EXTRACT(DAY FROM PeriodEnd)-EXTRACT(DAY FROM CalcDate));
        else
          return(null);
        end if;
      end if;
    end if;

    return(Days);

  end;

-------------------------------------------------------------------------------
  function GetFinePart(
                       AMoveSetID number,
                       AObligationTypeID number,
                       ADate date,
                       What varchar2
                       ) return number is

  FineValue sm.charges.paysize%type;
  Chargedate date;--NEW новый параметр Chargedate
  Old360 char(1);--NEW новый параметр
  calendar_type number; --NEW размер календаря
  FinePeriodStart date;
  FinePeriodEnd date;
  FineComment sm.charges.comments%type;
  --MoveEnd date;
  --NNN integer := 1;
  --OnLastDay char(1) := 'Y';

  FinePeriodDays number;
  DelayDays number;
  CHARGE_FINE_METHOD number;

  --Periodical char(1);
  str varchar2(200);
  begin

    CHARGE_FINE_METHOD:=GetChargeFineMethod(AMoveSetID,AObligationTypeID,ADate,calendar_type,old360);
-- NEW 17.12.2013 Суслова, запись № 298 в Контроле
--NEW новый параметр  Chargedate
    GetFineParams(AMoveSetID,AObligationTypeID,ADate, Chargedate,
                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);
--было:    GetFineParams(AMoveSetID,AObligationTypeID,ADate,
--                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);

 --
 --NEW выходим когда дата начисления совпадает с датой окончания периода начисления пени
   if calendar_type=360 and old360='N' then
     if FineValue is not null then
       if ((CHARGE_FINE_METHOD=1) and (Chargedate=ADate)) or ((CHARGE_FINE_METHOD=2) and (Chargedate=ADate)) then
       --было так:
       --    if (CHARGE_FINE_METHOD=1) and (FinePeriodEnd+1=ADate) then
         return (null);
       end if;
     end if;
   else
     if FineValue is not null then
       if (CHARGE_FINE_METHOD=1) and (Chargedate=ADate) then
         return(null);
       end if;
     end if;
   end if;
   --
    if FineValue is null then
      return(null);
    end if;

   ---- Если период - последний и ЗАКРЫТЫЙ, и НЕТ условия что на последний день начисляется пеня -
   ---        - то НЕ прибавлять 1 (NNN)  (иначе - расчет для промежуточных дат в своде В ТАКОМ периоде - неверен!).
  ---    ^V^ 21.06.2012 V^V --Почему-то именно этот код приводит к ошибкам в последнем периоде (против того что заявлено!) Пока отключаем!!!
---   Select max(NVL(mp.ENDDATE, to_date('01.01.1900'))) into MoveEnd from SM.MOVEPERIODS mp where mp.MOVESET_ID = AMoveSetID;
---   Select ops.FINE_ON_LAST_DAY into OnLastDay
---          from SM.OBLIG_PRESETS ops
---          inner join SM.OBLIGATIONS ob on ob.OBLIG_PRESETS_ID = ops.Id
---          where OB.MOVESET_ID = AMoveSetID and OB.OBLIGATIONTYPE_ID = AObligationTypeID;
---   if trunc(FinePeriodEnd) = trunc(MoveEnd)  and  OnLastDay = 'N' then
---       NNN := 0;
---   end if;

-- изменено 09.2014 Медведева (при расчете пени принимать 360 дней в году)
   str:=replace(FineComment,substr(FineComment, instr(FineComment,'д*')));
   FinePeriodDays:=To_number(substr(str,instr(str,' ',-1)+1));
-- было
  --  FinePeriodDays:=FinePeriodEnd-FinePeriodStart       +  NNN; --- <<< Здесь NNN{1/0}!

    if FinePeriodDays<2 then
      return(FineValue);
    end if;

    DelayDays:=LEAST(FinePeriodDays,Getdelaydays(What,ADate,FinePeriodStart,FinePeriodEnd,calendar_type,old360));

    if nvl(DelayDays,0)<1 then
      return(null);
    end if;

    FineValue:=FineValue/FinePeriodDays*DelayDays;
    return(FineValue);

  end;
-------------------------------------------------------------------------------
  function GetFinePartComment(
                       AMoveSetID number,
                       AObligationTypeID number,
                       ADate date,
                       What varchar2
                       ) return varchar2 is

  FineValue sm.charges.paysize%type;
  FinePartValue sm.charges.paysize%type;
  Chargedate date;--NEW новый параметр Chargedate
  calendar_type number;--NEW 101
  old360 char(1);--NEW 101
  FinePeriodStart date;
  FinePeriodEnd date;
  FineComment sm.charges.comments%type;

  CHARGE_FINE_METHOD number;

  Comments_part sm.charges.comments%type;
  FinePeriodDays number;
  DelayDays number;

  astr_pos number;
  equal_pos number;
  str varchar2(200);
  begin
  --NEW новый параметр Chargedate
    GetFineParams(AMoveSetID,AObligationTypeID,ADate,Chargedate,
                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);

    CHARGE_FINE_METHOD:=GetChargeFineMethod(AMoveSetID,AObligationTypeID,ADate,calendar_type,old360); --101
--было:
--    GetFineParams(AMoveSetID,AObligationTypeID,ADate,
--                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);

    if FineValue is null then
      return(null);
    end if;

    FinePartValue:=GetFinePart(AMoveSetID,AObligationTypeID,ADate,What);
-- изменено 09.2014 Медведева (при расчете пени принимать 360 дней в году)
    --FinePeriodDays:=FinePeriodEnd-FinePeriodStart+1;
    str:=replace(FineComment,substr(FineComment, instr(FineComment,'д*')));
    FinePeriodDays:=To_number(substr(str,instr(str,' ',-1)+1));

    if FinePeriodDays<2 then
      return(FineComment);
    end if;

    DelayDays:=LEAST(FinePeriodDays,Getdelaydays(What,ADate,FinePeriodStart,FinePeriodEnd,calendar_type,old360));

    if nvl(DelayDays,0)<1 then
      return(null);
    end if;

    astr_pos:=instr(FineComment,'*',1,1);
    equal_pos:=instr(FineComment,'=',1,1);
    Comments_part:=substr(FineComment,astr_pos,equal_pos-astr_pos+1);

    if DelayDays=1 then
      if Upper(What)='BEFORE' then
        FineComment:='Пеня: за '||to_char(ADate,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';
      elsif Upper(What)='AFTER' then
        FineComment:='Пеня: за '||to_char(ADate+1,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';
      end if;
      return(FineComment);
    end if;

    if Upper(What)='BEFORE' then
      FineComment:='Пеня: c '||to_char(FinePeriodStart,'dd.MM.yyyy')||' по '||to_char(ADate,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';
    elsif Upper(What)='AFTER' then
     FineComment:='Пеня: c '||to_char(ADate+1,'dd.MM.yyyy')||' по '||to_char(FinePeriodEnd,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';
    else
      FineComment:=null;
    end if;

    return (FineComment);

  end;
-------------------------------------------------------------------------------
  function GetFinePartBetween(
                       AMoveSetID number,
                       AObligationTypeID number,
                       ADateStart date,
                       ADateEnd  date
                       ) return number is

  FineValue sm.charges.paysize%type;
  FinePeriodStart date;
  FinePeriodEnd date;
  FineComment sm.charges.comments%type;

  --переменные для расчета типа календаря
  CHARGE_FINE_METHOD number;
  calendar_type number;
  old360 char(1);

  FinePeriodDays number;
  DelayDays number;
  str varchar2(200);
  begin

    if ADateStart>ADateEnd then  -- бессмысленность расчёта - выходим
      return(null);
    end if;

    GetFineParamsBetween(AMoveSetID,AObligationTypeID,ADateStart,ADateEnd,
                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);

    CHARGE_FINE_METHOD:=GetChargeFineMethod(AMoveSetID,AObligationTypeID,ADateStart,calendar_type,old360); --101


    if (FineValue is not null) then -- обе даты расчётного периода принадлежат одному и тому же кумулятивному начислению пени
   -- изменено 09.2014 Медведева (при расчете пени принимать 360 дней в году)
     --FinePeriodDays:=FinePeriodEnd-FinePeriodStart+1;
      str:=replace(FineComment,substr(FineComment, instr(FineComment,'д*')));
      FinePeriodDays:=To_number(substr(str,instr(str,' ',-1)+1));


      if FinePeriodDays<2 then
        return(FineValue);
      end if;

      if old360='N' then
        DelayDays:=LEAST(FinePeriodDays,Getdelaydays('BEFORE',ADateEnd,ADateStart,ADateEnd,calendar_type,old360));
      else
        DelayDays:=LEAST(FinePeriodDays,ADateEnd-ADateStart+1);
      end if;

   --   if old360='Y' then
   --    DelayDays:=LEAST(FinePeriodDays,ADateEnd-ADateStart+1);
        if DelayDays<1 then
          return(null);
        end if;
   --     end if;


      FineValue:=FineValue/FinePeriodDays*DelayDays;
        return(FineValue);

    else
      return(null);
    end if;

  end;
-------------------------------------------------------------------------------

  function GetFinePartBetweenComment(
                       AMoveSetID number,
                       AObligationTypeID number,
                       ADateStart date,
                       ADateEnd  date
                       ) return varchar2 is

  FineValue sm.charges.paysize%type;
  FinePartValue sm.charges.paysize%type;
  FinePeriodStart date;
  FinePeriodEnd date;
  FineComment sm.charges.comments%type;

  --переменные для определения типа календаря
  CHARGE_FINE_METHOD number;
  calendar_type number;
  old360 char(1);

  Comments_part sm.charges.comments%type;
  FinePeriodDays number;
  DelayDays number;

  astr_pos number;
  equal_pos number;
  str varchar2(200);

  begin

    if ADateStart>ADateEnd then -- бессмысленность расчёта - выходим
      return(null);
    end if;

    GetFineParamsBetween(AMoveSetID,AObligationTypeID,ADateStart,ADateEnd,
                  FineValue,FinePeriodStart,FinePeriodEnd,FineComment);

    CHARGE_FINE_METHOD:=GetChargeFineMethod(AMoveSetID,AObligationTypeID,ADateStart,calendar_type,old360); --101

    if (FineValue is not null) then -- обе даты расчётного периода принадлежат одному и тому же кумулятивному начислению пени
   -- изменено 09.2014 Медведева (при расчете пени принимать 360 дней в году)
     --FinePeriodDays:=FinePeriodEnd-FinePeriodStart+1;
      str:=replace(FineComment,substr(FineComment, instr(FineComment,'д*')));
      FinePeriodDays:=To_number(substr(str,instr(str,' ',-1)+1));

      if FinePeriodDays<2 then
        return(FineComment);
      end if;

    --  DelayDays:=LEAST(FinePeriodDays,ADateEnd-ADateStart+1);

      if old360='N' then
        DelayDays:=LEAST(FinePeriodDays,Getdelaydays('BEFORE',ADateEnd,ADateStart,ADateEnd,calendar_type,old360));
      else
        DelayDays:=LEAST(FinePeriodDays,ADateEnd-ADateStart+1);
      end if;

   --   if old360='Y' then
   --     DelayDays:=LEAST(FinePeriodDays,ADateEnd-ADateStart+1);
        if DelayDays<1 then
          return(null);
        end if;
   --   end if;

    FinePartValue:=FineValue/FinePeriodDays*DelayDays;

    astr_pos:=instr(FineComment,'*',1,1);
    equal_pos:=instr(FineComment,'=',1,1);
    Comments_part:=substr(FineComment,astr_pos,equal_pos-astr_pos+1);

    if DelayDays=1 then
      FineComment:='Пеня: за '||to_char(ADateEnd,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';
      return(FineComment);
    end if;

    FineComment:='Пеня: c '||to_char(ADateStart,'dd.MM.yyyy')||' по '||to_char(ADateEnd,'dd.MM.yyyy')||' '||to_char(DelayDays)||'д'||Comments_part||To_char(FinePartValue,'FM99999990.00')||'руб';

    return (FineComment);

    else
      return(null);
    end if;

  end;
------------------------------------------------------------------------------

begin
  null;
end;    ---- END    CALCFINE_PKG  ---------
/
grant execute on SM.CALCFINE_PKG to SM_ALLUSERS;
grant execute on SM.CALCFINE_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body CHARGING_PKG
prompt ==================================
prompt
create or replace package body sm.CHARGING_PKG is
--------------------------------------------------------
function GetPeriodFirstDay(
 PeriodType IN CHAR,      
 AnyDateOfPeriod IN DATE  
 ) return DATE is
 
 NDate DATE;
 CurrDate DATE;
 res DATE;  
begin

 CurrDate := AnyDateOfPeriod;

  IF (PeriodType='Y') or (PeriodType='M') THEN 
    Res:=TRUNC(CurrDate,'MONTH');
  ELSIF (PeriodType='Q') THEN
    NDate:=TRUNC(CurrDate,'MONTH');

    Res := ADD_MONTHS(trunc(NDate,'YEAR'), trunc(TRUNC(MONTHS_BETWEEN(NDate,trunc(NDate,'YEAR')))/3)*3);
  ELSIF (PeriodType='H') THEN
    NDate:=TRUNC(CurrDate,'MONTH');

    Res:= ADD_MONTHS(trunc(NDate,'YEAR'), trunc(TRUNC(MONTHS_BETWEEN(NDate,trunc(NDate,'YEAR')))/6)*6);
  ELSIF (PeriodType='G') THEN
    Res := trunc(CurrDate,'YEAR');
  END IF;
  
  Return(res);
  
end;
--------------------------------------------------------
function GetPeriodLastDay(
  PeriodType IN CHAR,      
  AnyDateOfPeriod IN DATE  
  ) return DATE is
 
  FirstDate DATE;
  CurrDate DATE;
  res DATE;  
begin

 CurrDate := AnyDateOfPeriod;
 FirstDate := GetPeriodFirstDay(PeriodType,AnyDateOfPeriod);
 
  IF (PeriodType='Y') or (PeriodType='M') THEN 
    Res:=LAST_DAY(CurrDate);
  ELSIF (PeriodType='Q') THEN

    Res  := ADD_MONTHS(FirstDate,3)-1;
  ELSIF (PeriodType='H') THEN

    Res:= ADD_MONTHS(FirstDate,6)-1;
  ELSIF (PeriodType='G') THEN
    Res  := ADD_MONTHS(FirstDate,12)-1;
  END IF;
  
  Return(Res);
  
end;
--------------------------------------------------------
function GetPeriodsCount(
                           PeriodType in CHAR, -- тип периодичности 
                           SinceDate in date,  -- начало интервала
                           EndDate in date     -- конец интервала
                           ) return number is
  curDate date;
  cnt number := 0;
  totalDaysInPeriod number ;
  factDaysInPeriod number;
begin
  
  CurDate:=SinceDate;
  loop
    totalDaysInPeriod := GetPeriodLastDay(PeriodType, curDate)+1 - GetPeriodFirstDay(PeriodType, curDate);
    factDaysInPeriod := least(EndDate+1, GetPeriodLastDay(PeriodType, curDate)+1 ) - 
                        greatest (SinceDate, GetPeriodFirstDay(PeriodType, curDate) );
    cnt := cnt + factDaysInPeriod/totalDaysInPeriod;
    curDate := GetNextPeriod(PeriodType,CurDate);
    exit when CurDate>EndDate;
                         
  end loop;
 
  return cnt;
end;
--------------------------------------------------------
procedure GetPeriodBounds(
  PeriodType IN CHAR, 
  AnyDateOfPeriod IN DATE,
  FirstDay OUT DATE,
  LastDay OUT DATE) is 

  NDate DATE;
  CurrDate DATE;
begin

  FirstDay:=Getperiodfirstday(PeriodType,AnyDateOfPeriod);
  LastDay:=Getperiodlastday(PeriodType,AnyDateOfPeriod);
  
end; 

--------------------------------------------------------
function GetPeriodName(PeriodType IN VARCHAR2, GDate in DATE) return varchar2 is
  Result varchar2(20);
  RD DATE;
  r integer;
  y integer;
begin

  RD:=trunc(GDate,'MONTH');
  r:=MONTHS_BETWEEN(RD,trunc(RD,'YEAR'))+1;
 --  y:=2000+MONTHS_BETWEEN(trunc(RD,'YEAR'), to_date('01.01.2000','dd.MM.yyyy'))/12;   -- <<< Зачем оно так нада была, и приводило _иногда_ к совершенно глючной ошибке в ORACLE 
	y := EXTRACT(YEAR FROM GDate);
 
  if (PeriodType='Y') or (PeriodType='M') THEN
   select decode(R,1,'Январь',2,'Февраль',3,'Март',4,'Апрель',5,'Май',6,'Июнь',7,'Июль',8,'Август',9,'Сентябрь',10,'Октябрь',11,'Ноябрь',12,'Декабрь','???') || ' ' || TO_CHAR(y) || 'г.' into Result from dual;
   return(Result);
  ELSIF PeriodType='Q' THEN
   select decode(R,1,'1 кв.',2,'1 кв.',3,'1 кв.',4,'2 кв.',5,'2 кв.',6,'2 кв.',7,'3 кв.',8,'3 кв.',9,'3 кв.',10,'4 кв.',11,'4 кв.',12,'4 кв.','???') || ' ' || TO_CHAR(y) into Result from dual;
   return(Result);
  ELSIF PeriodType='H' THEN
   select decode(R,1,'1 полуг.',2,'1 полуг.',3,'1 полуг.',4,'1 полуг.',5,'1 полуг.',6,'1 полуг.',7,'2 полуг.',8,'2 полуг.',9,'2 полуг.',10,'2 полуг.',11,'2 полуг.',12,'2 полуг.','???') || ' ' || TO_CHAR(y) into Result from dual;
   return(Result);
  ELSIF PeriodType='G' THEN
   select TO_CHAR(y) || ' г.' into Result from dual;
   return(Result);
  END IF;
   
end GetPeriodName;

-------------------------------------------------------- 
 
function IncDate(
  PeriodType IN VARCHAR2,  --Тип периода
  GDate in DATE            --Анализируемая дата входящая в период
  ) return DATE is
begin

  IF (PeriodType='Y') or (PeriodType='M') THEN
    return ADD_MONTHS(GDate,1);
  ELSIF (PeriodType='Q') THEN
    return ADD_MONTHS(GDate,3);
  ELSIF (PeriodType='H') THEN
    return ADD_MONTHS(GDate,6);
  ELSIF (PeriodType='G') THEN
    return ADD_MONTHS(GDate,12);
  END IF;
  
end;
   
--------------------------------------------------------

function GetNextPeriod(
  PeriodType IN VARCHAR2,  --Тип периода
  GDate in DATE            --Анализируемая дата входящая в период
  ) return DATE is 

  FirstDay DATE;
  LastDay DATE; 
begin

  GetPeriodBounds(PeriodType,GDate,FirstDay,LastDay);
  FirstDay := IncDate(PeriodType,FirstDay);
  
  return FirstDay;
  
end;

--------------------------------------------------------

function IsLastPeriodInYear(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE            --Анализируемая дата входящая в период
   ) return varchar2 is
   
   FirstDay DATE;
   LastDay DATE;
   YearFirstDayCurPeriod DATE;
   YearFirstDayNextPeriod DATE;
begin

  GetPeriodBounds(PeriodType,GDate,FirstDay,LastDay);
  
  YearFirstDayCurPeriod:=trunc(FirstDay,'YEAR');
  YearFirstDayNextPeriod:=trunc(IncDate(PeriodType,FirstDay),'YEAR');
  
  if YearFirstDayCurPeriod=YearFirstDayNextPeriod then
    return('N');
  else
    return('Y');
  end if;  

end;   

--------------------------------------------------------

function GetPeriodPaysize(
   PeriodType IN VARCHAR2,  --Тип периода
   GDate in DATE,           --Анализируемая дата входящая в период
   YearlyPaySize number     --Размер оплаты за год
   ) return number is
  IsDateOfLastPeriod boolean; 
  CurDate date;

  DaysInYear integer;
  S number(27,2);
  tmp number(27,2);
--- >>>  retval number(27,6);  <<<  18.03.2013 - вернули к прежней точности.
  retval number(27,2);
	DaysInPeriod integer;
	
begin
 
  IsDateOfLastPeriod:=(IsLastPeriodInYear(PeriodType,GDate)='Y');

  DaysInYear := GetPeriodLastDay('G',GDate)+1 - GetPeriodFirstDay('G',GDate);
 	
  IF not IsDateOfLastPeriod THEN
		     DaysInPeriod := GetPeriodLastDay(PeriodType,GDate) + 1 - GetPeriodFirstDay(PeriodType,GDate);
				 retval :=  YearlyPaySize * (DaysInPeriod / DaysInYear);
  else
				 S:=0;
         CurDate:=trunc(GDate,'YEAR');
				 while not (IsLastPeriodInYear(PeriodType,CurDate)='Y') loop
								DaysInPeriod := GetPeriodLastDay(PeriodType,CurDate) + 1 - GetPeriodFirstDay(PeriodType,CurDate);
							  tmp:=  YearlyPaySize * (DaysInPeriod / DaysInYear);
							  S:=S+tmp; 
								 CurDate:=GetNextPeriod(PeriodType,CurDate);  
				 end loop;
				 retval := YearlyPaySize - S;
  end if;    

 	return retval;

end;    

--------------------------------------------------------  
function GetPaysizeByDatePeriod(
   PeriodType IN VARCHAR2,  --Тип периода
   SinceDate in DATE,       --дата начала периода времени
   EndDate in DATE,         --дата окончания периода времени 
   YearlyPaySize number     --Размер оплаты за год
   ) return number is

  curDate date;
  cnt number := 0;
  totalDaysInPeriod number ;
  factDaysInPeriod number;
  lastDay date;
begin
  
  curDate:=SinceDate;
  loop
    lastDay := GetPeriodLastDay(PeriodType, curDate);
    totalDaysInPeriod := lastDay+1 - GetPeriodFirstDay(PeriodType, curDate);
    factDaysInPeriod := least(EndDate+1, lastDay+1 ) - 
                        greatest (SinceDate, GetPeriodFirstDay(PeriodType, curDate) );
    cnt := cnt + GetPeriodPaysize(PeriodType, lastDay, YearlyPaySize) * (factDaysInPeriod/totalDaysInPeriod);
    curDate := GetNextPeriod(PeriodType,CurDate);
    exit when CurDate>EndDate;
                         
  end loop;
 
  return cnt;
end;
--------------------------------------------------------  
begin
  null;
END; -------------- CHARGING_PKG ---------------------------------
/
grant execute on SM.CHARGING_PKG to SM_ALLUSERS;
grant execute on SM.CHARGING_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body FINE_PERCENT_ON_DATE_PKG
prompt ==============================================
prompt
create or replace package body sm.FINE_PERCENT_ON_DATE_PKG is

----------------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- Дополнительные действия для поступившего [либо "вновь распределяемого"] платежа.
 -- ( Если платеж связан с основанием с условиями начисления пени на день платежа, или на продажу с рассрочкой
 --   - происходит еще начисление пени и процентов соответственно. )
        -- Параметры:
             -- PayID      -- Идентификатор рассматриваемого платежа
             --PayDate    -- Дата начисления
             --ObligTypeID SM.OBLIGATIONTYPE.ID%type;         -- ID типа обязательства
             --MoveSetID   SM.MOVESETS.ID%type;                   -- Оно нада чобы знать  к чему оно все относится
procedure ADD_PERCENTS_AND_FINES(PayPalnID SM.PAYMENTS_PLAN.ID%type,
PayPlanDate date, PayDate date, MoveSetID number, ObligTypeID number, FilledByDraftID number )
 is

    HasWrite boolean := false;                                           -- Возвращаемый функцией признак что запись процентов или пени состоялась
    ObligID SM.CHARGES.ID%type;                                  -- ID Обязательства
   ObligGroup number(1);                                                 -- 1 - простое (тогда выходим); 2 - с рассрочкой (тогда начисляем проценты и пеню); 3 - с пеней определенной на день оплаты (тогда начисляем пеню).
   PayDatePrev SM.PAYMENTS.WRITEDATE%type;  -- Дата предыдущего платежа
   PayPlanDatePrev date;                                                 -- Дата предыдущего плана поступления
   ChargeUseHolidays char(1);
   Comment_txt varchar2(1000);                                    -- Комментарий к начислениям
   ValToWrite number(27, 2);                                          -- Сумма начисляемых процентов или пени
   MultiplyValToWrite number(27, 9);                            -- Доля пени о суммы платежа - (если пеня на день оплаты)
   PDID number;                                                                  -- ID PayDocs-а - условий на период

   ChargesDate date;                                                          -- Дата окончания периода за который пишется начисление
   PrevChargesDate date;                                                 -- Дата начала периода за который пишется начисление
   MainKBKID SM.PAYDOCS.MAIN_CLS_KBK_ID%type;
   FineKBKID SM.PAYDOCS.FINE_CLS_KBK_ID%type;
   PercentKBKID SM.PAYDOCS.PERCENT_CLS_KBK_ID%type;
   itmp integer;
   PercentPeriodStart date;
   PercentPeriodEnd date;
   PercentFineDate date;                                                 -- Дата начала начисления пени на процент - может не совпадать с концом периода из-за выходных
   DateCreditStart date;
   DateMovePeriodStart date;
   FineCreditPpersent char(1);                                        --  Начислять ли пеню на проценты
   PayPlanPercent integer;                                              -- ID плана для здесь же начисленных %
   Fact_Charge char(1) := 'N';
   NoFine char(1) := 'N';
   ValToUse number(27,2);
   ChargeType varchar2(10);
  NoCalcPercent char(1) := 'N';                                                   -- Флаг что проценты ваащще-то чиста канкретна нада начислять
	FineOnPayDay integer :=2;                                                     -- 1 - Пеня начисляется за каждый неполный день просрочки платежа. 2 - Пеня начисляется за каждый полный день просрочки платежа начислять"}
  APercent_Instant char(1) := 'N';
 begin

--       if PayVal = 0 then Fact_Charge := 'N';
--       end if;

------------------------  CНАЧАЛА ДОБЫВАЕМ РЯД ПАРАМЕТРОВ  ------------------------------

          Select  count(*) into itmp
          from  SM.OBLIGATIONS ob
          inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
          where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;
          if itmp = 1 then
                  Select  ob.ID,
                   case when (Exists(Select * from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = MoveSetID and ppd.OBLIGATIONTYPE_ID = ObligTypeID )) then 2 when op.CHARGE_FINE_ASSANCTION  =  'Y' then 3 else 1 end,
									 op.percents_instant 
                  into  ObligID,   ObligGroup, APercent_Instant
                  from  SM.OBLIGATIONS ob
                  inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
                  where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;
           else
                 --Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
                 --values (sysdate, 'err1 - no Presets found', 'FINE_PERCENT_ON_DATE_PKG.ADD_PERCENTS_AND_FINES', 'SM', 2, 2, 1, PayPalnID, 5, 'N');
                 RETURN;
          end if;

         -- Определяем параметры из условий обязательств и пресетов,  политику в отношении праздников,  коды КБК ...
          Select  count(*)  into itmp --  Сначала - условия на дату погашаемого периода!!! (<<< 01.08.2012)
          from SM.PAYMENTS_PLAN pp
					inner join SM.CHARGES ch on ch.ID= pp.CHARGES_ID
          inner join SM.PAYDOCS pd on pd.ID = ch.PAYDOC_ID
					inner join  SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID
					inner join  SM.OBLIG_PERIODICAL_PRESETS op on op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
          where  pp.ID = PayPalnID;
          if itmp = 1 then
                     Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID, NVL(pd.PERCENT_CLS_KBK_ID, pd.MAIN_CLS_KBK_ID),  op.CHARGE_FINE_METHOD
										     into PDID, NoCalcPercent, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, ChargeUseHolidays, MainKBKID, FineKBKID, PercentKBKID, FineOnPayDay
									  from SM.PAYMENTS_PLAN pp
										inner join SM.CHARGES ch on ch.ID= pp.CHARGES_ID
										inner join SM.PAYDOCS pd on pd.ID = ch.PAYDOC_ID
										inner join  SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID
										inner join  SM.OBLIG_PERIODICAL_PRESETS op on op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
										where  pp.ID = PayPalnID;
         else
									 Select  count(*)  into itmp
										from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
										where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
										and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
										and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;
										if itmp = 1 then
															 Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID, op.CHARGE_FINE_METHOD
																	 into PDID, NoCalcPercent, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, ChargeUseHolidays, MainKBKID, FineKBKID, FineOnPayDay
																from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
																where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
																and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
																and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;
										else
														 Select  count(*)  into itmp
															from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
															where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
															and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
															and  ( NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
																																			 where   pd2.moveperiod_id(+)=mp2.id
																																			 and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
																																			 and  pd2.Periodical != 'N')
																																			 or  mp.ENDDATE is null);
																		if itmp = 1 then
																										Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID, op.CHARGE_FINE_METHOD
																												 into PDID, NoCalcPercent, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, ChargeUseHolidays, MainKBKID, FineKBKID, FineOnPayDay
																										from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
																										where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
																										and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
																										and ( NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
																																														where   pd2.moveperiod_id(+)=mp2.id
																																														and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
																																														and  pd2.Periodical != 'N')
																																														or  mp.ENDDATE is null);
																			 else
																										 --Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
																										 --values (sysdate, 'err2 - no MovePeriod found', 'FINE_PERCENT_ON_DATE_PKG.ADD_PERCENTS_AND_FINES', 'SM', 2, 2, 1, PayPalnID, 5, 'N');
																										 RETURN; -- ???
																				 end if;
										end if;
					end if;

    -- Вид начисления
    Select count(*)  into  itmp
           from SM.PAYMENTS_PLAN pp
           inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
           where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
           and pp.ID = PayPalnID;
    if itmp = 1 then
                 Select trim(ch.CHARGE_TYPE)  into  ChargeType
                 from SM.PAYMENTS_PLAN pp
                 inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                 where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
                 and pp.ID = PayPalnID;
        else
                 --Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
                 --values (sysdate, 'err3 no PayPlan found', 'FINE_PERCENT_ON_DATE_PKG.ADD_PERCENTS_AND_FINES', 'SM', 2, 2, 1, PayPalnID, 5, 'N');
                 RETURN; -- ???
     end if;

    -- Дату предыдущего платежа
         Select MAX(NVL((CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end) ,pm.WRITEDATE))  into PayDatePrev
         from SM.PAYMENTS pm,
                   sm.documents d,
                  sm.sm_settings_tab st
         where pm.MOVESETS_ID = MoveSetID
         and   d.id=pm.documents_id and st.key_name = 'PAYMENT_USE_APPLY_DATE'
         and pm.OBLIGATIONTYPE_ID = ObligTypeID and NVL(
        (CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end)  --sm.getpaydateforpayment(pm.ID)
         ,pm.WRITEDATE) <= PayDate; -- <<<18.06.2012 добавлено =, иначе - платеж сегодняши=ним числом оставался "невидим", и проценты начислялись повторно от предыдущего события.

     if PayDatePrev is null then
           PayDatePrev := to_date('01.01.1900','dd.mm.yyyy');   --############### DateCreditStart?;
		 else  --- VVV 25.05.2012 -- Для прогнозных начислений "на сегодня" - не учитывалась установка начислять или нет пеню и % на день оплаты.
			        --- Соответственно, при установке "не начислять" (2) - период начисления на сегодня начинался на день позже, и один день процентов терялся.
					if FineOnPayDay = 2 then
							 PayDatePrev := PayDatePrev - 1;
				  end if;
      end if;

    -- Дату предыдущего  плана
    Select MAX(NVL(ppd.FINEDATE, pp.FINEDATE))  into PayPlanDatePrev
           from SM.PAYMENTS_PLAN pp
           inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
           left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
           where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
           and NVL(ppd.FINEDATE, pp.FINEDATE) < PayPlanDate
           and (pp.PAYMENTS_PLAN_DRAFT_ID is not null or ch.CHARGE_TYPE = 'OTHER' or  ObligGroup=3);

    if PayPlanDatePrev is null then
            PayPlanDatePrev := NVL(DateCreditStart, DateMovePeriodStart);
    end if;

    -- Опредеоляем период начисления:
    PrevChargesDate := PayPlanDatePrev;
    if (PayPlanDate > PayDate) then ChargesDate :=  PayDate; else  ChargesDate :=  PayPlanDate; end if;

------------------------ НАЧИНАЕМ СОБСТВЕННО НАЧИСЛЕНИЯ ------------------------

   if ObligGroup in ( 1, 2) then
              -- Если по обязательству с рассрочкой, то сначала - начисляем и пишем проценты, потом - начисляем и пишем пеню.
             if  ObligGroup = 2 then
                  -- Пишем проценты
                        -- Корректируем (или нет) контрольную дату периода под праздники
                        if ChargeUseHolidays='Y' then
                                 PercentFineDate := SM.GetFirstWorkDate(PayPlanDate-1)+1;
                        else
                                 PercentFineDate := PayPlanDate;
                        end if;
                       ----------------------------------- А вообще их начислять? -----------------------------------------
                        if  NoCalcPercent = 'N'  
													and APercent_Instant = 'N'    --- <<< 03.04.2013 - для процентов по графику - не начислять прогнозные
													then 

                                 -- Предварительно разбираемся с началом - концом периода для процентов
                                 if (SM.GetFirstWorkDate(PayPlanDatePrev-1)+1 >  PayDatePrev+1) then PercentPeriodStart := PayPlanDatePrev-1; else PercentPeriodStart := PayDatePrev;  end if;
                                 if (PayPlanDate <  PayDate and PayPlanDate > PercentPeriodStart) then PercentPeriodEnd := PayPlanDate - 1; else PercentPeriodEnd := PayDate - 1; end if; -- <<<18.06.2012 -- от PayDate отнимаем день - если на сегодня - НЕ НАДО %

                                 --- 03.10.2011 --- Исключение [абсурдных?] повторяющихся начислений будущих процентов при _прошедших_ периодах --
                                 -- ValToWrite := sm.PAYMENTS_DISTRIBUTE_PKG.PercentSizeForPayment(MoveSetID, ObligTypeID, PercentPeriodEnd, PercentPeriodStart, Comment_txt);
                                 if PercentPeriodStart <= PayPlanDate then
                                       ValToWrite := sm.PAYMENTS_DISTRIBUTE_PKG.PercentSizeForPayment(MoveSetID, ObligTypeID, PercentPeriodEnd, PercentPeriodStart, Comment_txt, 1);
                                 else
--                                        ValToWrite := sm.PAYMENTS_DISTRIBUTE_PKG.PercentSizeForPayment(MoveSetID, ObligTypeID, PercentPeriodEnd, PercentPeriodStart, Comment_txt, 1);
                                     ValToWrite := 0;
                                 end if;
                                 --- END --- 03.10.2011 -----

                                 if ValToWrite <> 0 then
                                       -- Проверяем на дубль (при неполной оплате периода прогнозный процент может начислиться снова)
                                       itmp := 0;
                                       Select count(*) into itmp from SM.CHARGES ch
                                           inner join SM.PAYMENTS_PLAN pp on pp.CHARGES_ID = ch.ID
                                           where trunc(ch.FINEDATE) = trunc(PercentFineDate)
                                           and ch.PAYDOC_ID = PDID
                                           and TRIM(SUBSTR(ch.COMMENTS,1, INSTR(ch.COMMENTS, ')' ))) = TRIM(Comment_txt)
                                           and ch.MOVESETS_ID = MoveSetID and OBLIGATIONTYPE_ID = ObligTypeID
                                           and ch.PAYSIZE= ValToWrite
                                           and TRIM(ch.CHARGE_TYPE) = 'PERCENT' ;

                                          if itmp = 0 then
   --                                                 Comment_txt := Comment_txt || ' (прогноз)';
                                                    Insert into SM.CHARGES(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                                                   values (sm.seqcharges.nextval, trunc(PercentFineDate), trunc(PercentFineDate), PDID, Comment_txt, ValToWrite, 'PERCENT', MoveSetID, ObligTypeID,  trunc(PrevChargesDate), trunc(ChargesDate), PercentKBKID,  Fact_Charge);
                                                    Insert into SM.PAYMENTS_PLAN(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                                                   values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, ObligID, PercentFineDate, ValToWrite, FilledByDraftID, Comment_txt, null);
                                                    HasWrite := true;
                                                   Select seqpayments_plan.currval  into PayPlanPercent from DUAL;

                                                   -- Пишем пеню
                                                   if NoFine = 'N' then
                                                           -- Сначала - на только-что начисленный процент
                                                           if (FineCreditPpersent = 'Y')  and  (PercentPeriodEnd - PercentPeriodStart) > 1 then
                                                                     ValToWrite :=  SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPlanPercent, PayDatePrev, Comment_txt, 'N', PayPlanDate,   PDID);
  --                                                                   Comment_txt := Comment_txt || ' (прогноз на тек.дату)';
                                                                      -- raise_application_error(-20001,'Пеня на процент насчиталась - ' || to_char(ValToWrite));
                                                                     if ValToWrite <> 0 then
                                                                               Insert into sm.charges(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                                                                               values (sm.seqcharges.nextval, PayDate, PayPlanDate, PDID, Comment_txt, ValToWrite, 'FINE', MoveSetID, ObligTypeID, PrevChargesDate, ChargesDate, FineKBKID, Fact_Charge);
                                                                                Insert into sm.payments_plan(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                                                                               values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, ObligID, ChargesDate, ValToWrite, FilledByDraftID, Comment_txt,  PayPlanPercent);
                                                                                 HasWrite := true;
                                                                     end if;
                                                           end if;
                                                   end if;
                                          else
                                                 HasWrite := true;
                                          end if;
                                  end if;
                        end if;
              end if;
             -- Пишем пеню
             -- Теперь - пеня на основное начисление
                -- Если оно - не первоначальный взнос на условиях предоплаты (т.е. FilledByDraft is not null)
              if NoFine = 'N'  then  
      --                 if FilledByDraftID is not null or ChargeType = 'OTHER' then
                              ValToWrite :=  SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPalnID, PayDatePrev, Comment_txt, 'N', PayPlanDate,   PDID );
  --                             Comment_txt := Comment_txt || ' (прогноз на тек.дату)';
                                --raise_application_error(-20001,'Пеня на основное начисление насчиталась - ' || to_char(ValToWrite));
                               if ValToWrite <> 0 then
                                         Insert into sm.charges(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                                         values (sm.seqcharges.nextval, PayDate, PayPlanDate, PDID, Comment_txt, ValToWrite, 'FINE', MoveSetID, ObligTypeID, PrevChargesDate, ChargesDate, FineKBKID, Fact_Charge);
                                          Insert into sm.payments_plan(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                                         values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, ObligID, ChargesDate, ValToWrite, FilledByDraftID, Comment_txt, PayPalnID);
                                           HasWrite := true;
                               end if;
     --                 end if;
             end if;
   end if;

   -- Если по обязательству с условиями начисления пени на день платежа - определяем и пишем пеню
   if ObligGroup = 3 and NoFine = 'N' then

              if Fact_Charge = 'N' then
                   Select pp.VAL into ValToUse
                   from SM.PAYMENTS_PLAN pp where pp.ID = PayPalnID;
              end if;
              
               ---- 22.07.2014 Morozova проверяем сальдо на текущий день             
              select nvl(sum(pp.val),0) into ValToUse
              from sm.payments_plan pp
                   inner join sm.charges ch
                   on ch.id = pp.charges_id
              where ch.movesets_id = MoveSetID and ch.obligationtype_id = ObligTypeID
                    and ch.charge_type in ('OBLIGATION', 'OTHER', 'PERCENT')
                    and ch.chargedate <= PayDate;
                    
              select ValToUse - nvl(sum(p.sum),0) into ValToUse
              from sm.payments p
              where p.movesets_id = MoveSetID and p.obligationtype_id = ObligTypeID
                    and p.mainpay='Y' 
                    and (p.apply_date <= PayDate or (p.writedate <= PayDate and (Select Value from SM.sm_settings_tab where KEY_NAME='PAYMENT_USE_APPLY_DATE' ) = 'N'));
               
              if ValToUse > 0 then   -- если есть долг, пишем пеню
                    -- MultiplyValToWrite := SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPalnID, PayPlanDatePrev, Comment_txt, 'N');
                    -- ValToWrite :=  ValToUse * MultiplyValToWrite;
                    -- Здесь (для прогнозных начислений) - вся сумма уже посчитана в FineSizeForCredit()!!!
                    ValToWrite := SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPalnID, PayPlanDatePrev, Comment_txt, 'N', PayPlanDate, PDID);
          --          Comment_txt := Comment_txt || ' на сумму долга ' || to_char(ValToUse) || ' = ' || to_char(ValToWrite) || ' руб.'; -- (прогноз на тек.дату)';
          --          Comment_txt := Comment_txt || ' на сумму долга за ' ||  to_char(PrevChargesDate, 'dd.MM.yyyy') || ' - ' ||  to_char(ChargesDate, 'dd.MM.yyyy');
                    Comment_txt := Comment_txt || ' на сумму долга от ' ||  to_char(PayPlanDate, 'dd.MM.yyyy');
                    Comment_txt := Comment_txt || ' (на тек.дату)'; -- (прогноз на тек.дату)'; -- -- ДЛЯ РАДУЖНОГО - "прогноз" УБРАТЬ !!!

                    -- Пишем пеню
                     if ValToWrite <> 0 then
                               Insert into sm.charges(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                               values (sm.seqcharges.nextval, PayDate, PayPlanDate, PDID, Comment_txt, ValToWrite, 'FINE', MoveSetID, ObligTypeID, PrevChargesDate, ChargesDate, FineKBKID, Fact_Charge);
                                Insert into sm.payments_plan(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                               values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, ObligID, ChargesDate, ValToWrite, FilledByDraftID, Comment_txt, PayPalnID);
                                 HasWrite := true;
                     end if;
             end if;
   end if;

 end; -- End ADD_PERCENTS_AND_FINES

--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
     -- Формирование начислений пени для условий "пеня как часть ставки рефинансирования на день оплаты (ст395 ГК)",
     --  или процентов и пени - для продажи в рассрочку.
        -- Параметры:
             -- MoveSetID        -- Нада чобы знать чо к чему относится
            -- PayDate               -- Дата платежа
 Procedure CALC_PERSENS_FINES_FOR_DATE(MoveSetID  SM.MOVESETS.ID%type, ObligTypeID SM.OBLIGATIONTYPE.ID%type, CurrDate date)
   is

   PayPalnID number := 0;                         -- Прошлый ID - для определения факта смены очередного плана
  FineAsSanction char(1);
  FineKind char(1) := '-' ;
  itmp integer;
	LastDate date;
	LastPayDate date;
	ValToWrite number(27,2) := 0;
	PDID integer;
	MPID integer;
	MainKBKID integer;
	Comment_txt varchar2(400);
	DraftID integer;
	ObligID integer;
--  WasFinesOnDate boolean;

  begin

-- Добываем для начала некоторые параметры
  select count(*)  into itmp
  from sm.oblig_presets op, sm.obligations ob
  where op.id=ob.oblig_presets_id and
        ob.obligationtype_id=ObligTypeID and
        ob.moveset_id=MoveSetID;
 if itmp = 1 then
        select op.charge_fine_assanction  into FineAsSanction
          from sm.oblig_presets op, sm.obligations ob
          where op.id=ob.oblig_presets_id and
                ob.obligationtype_id=ObligTypeID and
                ob.moveset_id=MoveSetID;
else
        -- Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
        -- values (sysdate, 'err1', 'FINE_PERCENT_ON_DATE_PKG.CALC_PERSENS_FINES_FOR_DATE', 'SM', 2, 2, 1, PayPalnID, 5, 'N');
         RETURN; -- ???
end if;

 -- Удаляем только начисления плановые по пени и процентам и дальше расчитываем их снова
    delete from sm.charges ch where trim(ch.CHARGE_TYPE) != 'OBLIGATION' and
                                        ch.factcharge='N' and
                                        ch.obligationtype_id=ObligTypeID and
                                        ch.movesets_id=MoveSetID
																				and ch.document_id is null ;

-- Организуем выборку еще незакрытых планов поступлений, для которых будем создавать проценты и пени на дату
    for pay_plan  in
    (
          Select pp.ID,
          NVL(ppd.FINEDATE, pp.FINEDATE) as FINEDATE,
          (pp.VAL - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)) as PlanVal,
          trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID, pp.PAYMENTS_PLAN_DRAFT_ID
          from SM.PAYMENTS_PLAN pp
          inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
          left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
          where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
 and  pp.VAL >  NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)
          --and pp.FINEDATE > NVL((Select max(p.APPLY_DATE) from SM.PAYMENTS_DISTRIBUTION pdistr inner join  SM.PAYMENTS p on p.ID=pdistr.payments_id  where pdistr.PAYMENTS_PLAN_ID = pp.ID), to_date('01.01.1917'))
          --and pp.FINEDATE > NVL((Select max(p.APPLY_DATE) from SM.PAYMENTS p  where p.MOVESETS_ID = MoveSetID and p.OBLIGATIONTYPE_ID = ObligTypeID), to_date('24.10.1917'))
------------------  !!!         and pp.FINEDATE > NVL((Select max(p.APPLY_DATE) from SM.PAYMENTS p  where p.MOVESETS_ID = MoveSetID and p.OBLIGATIONTYPE_ID = ObligTypeID and p.apply_date <= CurrDate ), to_date('24.10.1917'))
					 -- ^^^ 11.07.2012 --- добавлена часть   / and p.apply_date <= CurrDate /  - для расчетов на прошлую дату. Тесты прошло.
					 -- ^^^ 16.08.2012 -- Убрано, т.к. исключало ранние планы погашения что не всегда правильно. (период по ставке рефинанс. и затем твердый % при "на день оплаты" - вот и нарушен порядок)
          and (trim(ch.CHARGE_TYPE) in ('OBLIGATION', 'OTHER')  or (trim(ch.CHARGE_TYPE) = 'PERCENT' and pp.PAYMENTS_PLAN_DRAFT_ID is null))
          and  ch.FACTCHARGE = 'Y'
          and
         (
              pp.FINEDATE < CurrDate
         or
             (
             NVL((
                       Select max(pp2.FINEDATE)
                       from SM.PAYMENTS_PLAN pp2
                       inner join SM.CHARGES ch2 on ch2.ID = pp2.CHARGES_ID
                       where ch2.MOVESETS_ID = MoveSetID and ch2.OBLIGATIONTYPE_ID = ObligTypeID
                       and pp2.FINEDATE < pp.FINEDATE
                       ), to_date('01.01.1900','dd.MM.yyyy')) <= CurrDate
                       and pp.FINEDATE > CurrDate
             )
         )
         ------------------------------
--       UNION ALL
--            Select pp.ID,
--            NVL(ppd.FINEDATE, pp.FINEDATE) as FINEDATE,
--            (pp.VAL - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)) as PlanVal,
--            trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID, pp.PAYMENTS_PLAN_DRAFT_ID
--           from SM.PAYMENTS_PLAN pp
--            inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
--            left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
--            where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
--            and ch.CHARGE_TYPE = 'OBLIGATION'
--            and  pp.FINEDATE = (Select max(ppp.FINEDATE) from SM.PAYMENTS_PLAN ppp inner join SM.CHARGES chh on chh.ID = ppp.CHARGES_ID where chh.MOVESETS_ID = MoveSetID and chh.OBLIGATIONTYPE_ID = ObligTypeID and chh.CHARGE_TYPE = 'OBLIGATION')
--            and  (Select max(ppp.FINEDATE) from SM.PAYMENTS_PLAN ppp inner join SM.CHARGES chh on chh.ID = ppp.CHARGES_ID where chh.MOVESETS_ID = MoveSetID and chh.OBLIGATIONTYPE_ID = ObligTypeID and chh.CHARGE_TYPE = 'OBLIGATION')
--						           <  NVL((Select max(p.APPLY_DATE) from SM.PAYMENTS p  where p.MOVESETS_ID = MoveSetID and p.OBLIGATIONTYPE_ID = ObligTypeID), to_date('07.11.1917'))
         ------------------------------
         order by  FINEDATE
     )
     loop
          -- Прверка относится ли Период Начисления к периоду ОД с условием начисления пени по ставке рефинансирования на день оплаты.
               select count(*) into itmp
                from  sm.paydocs pd,  sm.moveperiods mp
                where   pd.moveperiod_id(+)=mp.id
                  and mp.moveset_id=MoveSetID and pd.obligationtype_id=ObligTypeID
                  --and  pd.Periodical != 'N'
                  and mp.SINCEDATE <= trunc(pay_plan.FINEDATE) and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy'))  > trunc(pay_plan.FINEDATE);
             if itmp = 1 then
                              select pd.FINE_KIND into FineKind
                                from  sm.paydocs pd,  sm.moveperiods mp
                                where   pd.moveperiod_id(+)=mp.id
                                  and mp.moveset_id=MoveSetID and pd.obligationtype_id=ObligTypeID
                                  --and  pd.Periodical != 'N'
                                  and mp.SINCEDATE <= trunc(pay_plan.FINEDATE) and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy'))  > trunc(pay_plan.FINEDATE);
             else
                                    select count(*) into itmp
                                      from  sm.paydocs pd,  sm.moveperiods mp
                                      where   pd.moveperiod_id(+)=mp.id
                                        and mp.moveset_id=MoveSetID and pd.obligationtype_id=ObligTypeID
                                        --and  pd.Periodical != 'N'
                                        and (mp.ENDDATE = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                                        where   pd2.moveperiod_id(+)=mp2.id
                                                                        and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
                                                                        --and  pd2.Periodical != 'N'
                                                                        )
                                                                        or mp.ENDDATE is null);
                                   if itmp = 1 then
                                          select pd.FINE_KIND into FineKind
                                            from  sm.paydocs pd,  sm.moveperiods mp
                                            where   pd.moveperiod_id(+)=mp.id
                                              and mp.moveset_id=MoveSetID and pd.obligationtype_id=ObligTypeID
                                              --and  pd.Periodical != 'N'
                                             and (NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                                        where   pd2.moveperiod_id(+)=mp2.id
                                                                        and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
                                                                        --and  pd2.Periodical != 'N'
                                                                        )
                                                                        or mp.ENDDATE is null);
                                    end if;
             end if;

           -- Вызов функции доп.начислений PAYMENT_IN_ADDITIONS.
           -- ( В ней: Если платеж - по обязательству с процентами, или с условием начисления пени на день оплаты - то формируем начисления [процентов и] пени)
           if (pay_plan.ID <>  PayPalnID
                    and ( (pay_plan.CHARGE_TYPE ='OBLIGATION' and pay_plan.PAYMENTS_PLAN_DRAFT_ID is not null)
                         or pay_plan.CHARGE_TYPE in ('OTHER', 'PERCENT')
                         or (FineAsSanction = 'Y'  and FineKind = 'R')))    then

										 PayPalnID := pay_plan.ID;

                    ADD_PERCENTS_AND_FINES(pay_plan.ID, trunc(pay_plan.FINEDATE), trunc(CurrDate), MoveSetID, pay_plan.OBLIGATIONTYPE_ID, pay_plan.PAYMENTS_PLAN_DRAFT_ID );

             end if;
              -----<<< К ниже 14.02.2012 <<< -----------------------------
						 LastDate := pay_plan.FINEDATE - 1;
						 ValToWrite := pay_plan.PlanVal;
						 DraftID := pay_plan.PAYMENTS_PLAN_DRAFT_ID;
						 -----------------------------------------------------------------------
      end loop;
	    -----<<< 14.02.2012 <<< --- Начисление процентов на непогашенный остаток долга после последних сроков начисления до полного погашения ---------------------------
			---------------------------------- Однако, если закрыть договор (датой окончания в последнем периоде)	- тогда ничего начисляться не будет
			        begin
                      Select  pd.ID, pd.MAIN_CLS_KBK_ID, mp.ID  into  PDID, MainKBKID, MPID
                      from SM.PAYDOCS pd
											inner join SM.MOVEPERIODS mp  on mp.ID = pd.MOVEPERIOD_ID
                      where mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
                      and mp.sincedate  = (Select max(mp2.sincedate) from SM.MOVEPERIODS mp2 where mp2.MOVESET_ID=MoveSetID)
											and ROWNUM < 2; -- На случай 2-х последних периодов на одну дату --
											-- Проверяем не закрыт ли договор, и если закрыт - проценты не начисляем
											Select count(*) into itmp from SM.MOVEPERIODS mp where mp.ID = 	MPID 	and mp.ENDDATE is null;
											if itmp != 0  then
														Select  ob.ID into ObligID from SM.OBLIGATIONS ob where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;
														--- VVV 10.04.2012 VVV -- Без этого при наличии платежей после последнего срока погашения - % на сегодня считался не от платежа а от срока.
														Select max(SM.GetPayDateForPayment(pm.ID)) into LastPayDate from SM.PAYMENTS pm where pm.MOVESETS_ID =  MoveSetID and pm.OBLIGATIONTYPE_ID = ObligTypeID;
                            if ( LastPayDate > LastDate OR LastDate is null) then
															        LastDate := LastPayDate -1;
														end if; 	---

													 ValToWrite := sm.PAYMENTS_DISTRIBUTE_PKG.PercentSizeForPayment(MoveSetID, ObligTypeID, trunc(CurrDate), trunc(LastDate), Comment_txt, 1);

													 if ValToWrite <> 0 then  --- <<< 02.04.2012 <<<
																		Insert into SM.CHARGES(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
																									 values (sm.seqcharges.nextval, trunc(CurrDate), trunc(CurrDate), PDID, Comment_txt, ValToWrite, 'PERCENT', MoveSetID, ObligTypeID,  trunc(LastDate), trunc(CurrDate), MainKBKID,  'N');
																		Insert into SM.PAYMENTS_PLAN(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
																									 values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, ObligID, trunc(CurrDate), ValToWrite, DraftID, Comment_txt, null);
														end if;

										 end if;
	   	  		 exception  -- <<<  07.03.2012 <<< -Заглушено на момент, когда во вновь создаваемом (пеоследнем) периоде нет обязательств...
                     when others then
                     NULL;
   	  			end;
   ------------------------------------
   end;

END;     ---- END    FINE_PERCENT_ON_DATE_PKG ----
/
grant execute on SM.FINE_PERCENT_ON_DATE_PKG to SM_ALLUSERS;
grant execute on SM.FINE_PERCENT_ON_DATE_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body FULLRECALC_PKG
prompt ====================================
prompt
create or replace package body sm.FULLRECALC_PKG is

-- Дата закрытия отчетного периода
G_CloseDate date := to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy');

FUNCTION PAYDOC_ID_FOR_CHARGES(CHARGES_ID IN NUMBER) return number;
FUNCTION DSCNT_FOR_CHARGES(CHARGES_ID IN NUMBER) return number;

-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
PROCEDURE FullRecalcCharges(AMoveSet_ID in number, AObligType_ID in number)
--
-- процедура расчета для традиционного свода расчетов
--
--Пеня исчисляется в днях от конца периода
is
  c integer;
  cc integer;
  idNext integer;
  FirstCharge char(1) := 'Y';               -- признак самого первого начисления
  FirstCharge_Period char(1);   -- признак первого исправленного начисления
  A_comments varchar2(100);
  A_corr_flag char(1);
  A_chargedate date;
  A_reversal_role varchar2(100);

  CurCurrency NUMBER; --текущий курс у.е.

  Days      INTEGER; --дней календарного периода в текущем периоде начислений
  CurrDate    DATE;
  CurrPeriodPay  NUMBER(27,2);
  CurPeriodExpl varchar2(200);
  CurExpl varchar2(500);
  ADate Date;
  DaysInPeriod integer;
  PrevDate Date;
  PeriodPay number(27,6);
  Kind char(1);
  CHARGE_METHOD integer;
  CHARGE_LASTDAY char(1);
  CHARGE_FIRST_DAY integer;
  CHARGE_FIRST_N integer; -- 11.12.2014 MAV
	PERIOD_FIRST_DAY integer;
  CHARGE_FORWARD char(1);
  CHARGE_USE_HOLYDAYS_str char(1);
  CH_DATE DATE; --дата начисления
  perchar char(1); --периодичность последнего периода
  TOTAL_STOP boolean;
  CHARGE_USE_HOLYDAYS boolean;
  CurPayDoc_ID number(27);
  DefferStop Char(1) := 'N';  -- Один раз (для каждой отсрочки) срабатывающий флаг что отсрочка кончилась

  cursor pp (MSID number, oblig_type_id NUMBER)  is
    select PERIODICAL
    from SM.paydocs pd
    inner join SM.moveperiods mp on pd.moveperiod_id=mp.id
    where pd.obligationtype_id=oblig_type_id and
      mp.sincedate=(select max(mmp.sincedate) from sm.moveperiods mmp where mmp.moveset_id=mp.moveset_id
                           and exists (Select * from SM.PAYDOCS pdd where pdd.moveperiod_id=mmp.id)) -- <<< 29.10.2014 MAV (иначе последний период без начислений представлял начисления непериодическими)
      and mp.moveset_id=MSID;

  PeriodFirstDay DATE;
  PeriodLastDay DATE;

  CurrPeriodFirstDay DATE;
  CurrPeriodLastDay DATE;

  CurrMovePeriodFirstDay DATE;

  ChargeFineDate Date;

  --параметры
  OncePayDate DATE;

  PaySize NUMBER(27,2);          -- размер оплаты
	tmppaysize NUMBER(27,2);
  FineDate integer;
  FineDate_ByOblig integer;
  FineMonths integer;

  IsYearlyPaysize boolean;       -- размер оплаты указан как сумма за год
  IsLastPeriodInYear boolean;    -- последний ли период в году
  LastInYearFineDate integer;    -- дни начала начисления пени для последнего периода в году
  LastInYearFineMonths integer;  -- месяцы начала начисления пени для последнего периода в году

  ObName Varchar2(200);
  Periodical CHAR(1);
  FObligationType_ID integer;
  Recepient_ID integer;

  FirstPeriod boolean;
  FirstFirstPeriod boolean := true; -- Признак _самого_ первого периода
  ChargeTo integer;

  MV_StartDate DATE;               -- Начало операции движения (договора)
  MV_EndDate DATE;               -- конец операции движения (договора)
  CH_EarlyDate DATE;         -- Дата самого раннего начисления по ОД. (Используется для подчистки при сдвигах начала ОД.)

  DISCOUNT NUMBER;
  DISCOUNT_SUM NUMBER;
  PrevFineDate date;
  DISCOUNTEDIN number; --15.10.2014 Morozova

  DEFFER_DATE DATE;             -- отсрочка до даты...
  DEFFER_START_DATE DATE;             -- дата начала отсрочки...
  DEFFER_END_DATE DATE;             -- дата окончания отсрочки...

  KBK_ID NUMBER;                -- Код бюджетной классификации

  PDID NUMBER;                  -- ссылка на PAIDOCS

	ARecalc_Start_Date date;
  A_PERCENTS_INSTANT char(1) := 'N';

  v_SqlCode varchar2(2000);
  NotCharge char(1) default 'N';
  v_ProcName varchar2(250);
  PartialPeriod char(1) := 'N'; --- 24.07.2014 Morozova начисление за полный период равными долями, за неполный - из расчета суммы за год и кол-ва дней за год
  tempDate DATE := Null;
  block_first_two char(1) := 'N'; -- первый и второй периоды оплаты делать одновременно на условиях первого (11.12.2014)

  cursor ACT(MSID number,OTID number, STOP_DATE date) is
    SELECT *
    FROM (
           select
             'START_PERIOD' as ACTION_TYPE,
             mp.sincedate as ACTION_DATE,
             3 as ORD,
             to_number(null)  as DISCOUNT_VALUE,
             pd.id as PDID,
             pd.OncePayDate as OncePayDate,
             pd.PaySize as PaySize,
             pd.FineDate as FineDate_ByOblig,
             pd.FineMonths as FineMonths,
             mp.sincedate as Postingdate,
             mp.Enddate as Enddate,
             ot.Name as ObName,
             pd.Periodical as Periodical,
             pd.ObligationType_ID as ObligationType_ID,
             pd.Clients_ID as Clients_ID,
             pd.redirect_paydoc_id as redirect_paydoc_id,
             pd.Kind as Kind,
             pd.currency as currency,
             nvl(pd.is_yearly_paysize,'N') as IsYearlyPaysize,
             pd.last_finedate as LastInYearFineDate,
             pd.last_finemonths as LastInYearFineMonths,
             pd.main_cls_kbk_id as MainKBK,
             --mp.oblig_periodical_presets_id as period_presets
             pd.oblig_periodical_presets_id as period_presets
           from
             paydocs pd,
             moveperiods mp,
             ObligationType ot
           where
             mp.moveset_id=MSID and
             pd.moveperiod_id=mp.id and
             ot.id=pd.obligationtype_id and
             pd.obligationtype_id=OTID

           union all

           select
             'END_PERIOD' as ACTION_TYPE,
             nvl(mp.enddate+1,to_date('01.01.3000','DD.MM.YYYY')) as ACTION_DATE,
             2 as ORD,
             to_number(null)  as DISCOUNT_VALUE,
             to_number(null) as PDID,
             to_date(null) as OncePayDate,
             to_number(null) as PaySize,
             to_number(null) as FineDate_ByOblig,
             to_number(null) as FineMonths,
             to_date(null) as Postingdate,
             to_date(null) as Enddate,
             TO_CHAR(null) as ObName,
             TO_CHAR(null) as Periodical,
             to_number(null) as ObligationType_ID,
             to_number(null) as Clients_ID,
             to_number(null) as redirect_paydoc_id,
             TO_CHAR(null) as Kind,
             to_Char(null) as currency,
             to_char(null) as IsYearlyPaysize,
             to_number(null) as LastInYearFineDate,
             to_number(null) as LastInYearFineMonths,
             to_number(null) as MainKBK,
             to_number(null) as period_presets
           from
             paydocs pd,
             moveperiods mp
           where
             mp.moveset_id=MSID and
             pd.moveperiod_id=mp.id and
             pd.obligationtype_id=OTID

           union all

           select
            'DSCNT_START' as ACTION_TYPE,
            ds.sincedate as ACTION_DATE,
            0 as ORD,
            ds.discount_value as DISCOUNT_VALUE,
            to_number(null) as PDID,
            to_date(null) as OncePayDate,
            to_number(null) as PaySize,
            to_number(null) as FineDate_ByOblig,
            to_number(null) as FineMonths,
            to_date(null) as Postingdate,
            to_date(null) as Enddate,
            TO_CHAR(null) as ObName,
            TO_CHAR(null) as Periodical,
            to_number(null) as ObligationType_ID,
            to_number(null) as Clients_ID,
            to_number(null) as redirect_paydoc_id,
            TO_CHAR(null) as Kind,
            to_Char(null) as currency,
            to_char(null) as IsYearlyPaysize,
            to_number(null) as LastInYearFineDate,
            to_number(null) as LastInYearFineMonths,
            to_number(null) as MainKBK,
            to_number(null) as period_presets
          from
            discounts ds
          where
            ds.moveset_id=MSID and
            ds.obligationtype_id=OTID and
            ds.Discharge_Type='MAIN'

           union all

          select
            'DSCNT_STOP' as ACTION_TYPE,
            nvl(ds.enddate+1,to_date('01.01.3000','DD.MM.YYYY')) as ACTION_DATE,
            4 as ORD,
            ds.discount_value as DISCOUNT_VALUE,
            to_number(null) as PDID,
            to_date(null) as OncePayDate,
            to_number(null) as PaySize,
            to_number(null) as FineDate_ByOblig,
            to_number(null) as FineMonths,
            to_date(null) as Postingdate,
            to_date(null) as Enddate,
            TO_CHAR(null) as ObName,
            TO_CHAR(null) as Periodical,
            to_number(null) as ObligationType_ID,
            to_number(null) as Clients_ID,
            to_number(null) as redirect_paydoc_id,
            TO_CHAR(null) as Kind,
            to_Char(null) as currency,
            to_char(null) as IsYearlyPaysize,
            to_number(null) as LastInYearFineDate,
            to_number(null) as LastInYearFineMonths,
            to_number(null) as MainKBK,
            to_number(null) as period_presets
          from
            discounts ds
          where
            ds.moveset_id=MSID and
            ds.obligationtype_id=OTID and
            ds.Discharge_Type='MAIN' and
            ds.enddate is not null

           union all

           select
            'DEFFER_START' as ACTION_TYPE,
            df.charge_sincedate as ACTION_DATE,
            1 as ORD,
            to_number(null) as DISCOUNT_VALUE,
            to_number(null) as PDID,
            nvl(df.deffer_date,to_date('01.01.3000','DD.MM.YYYY')) as OncePayDate,
            to_number(null) as PaySize,
            to_number(null) as FineDate_ByOblig,
            to_number(null) as FineMonths,
            to_date(null) as Postingdate,
            to_date(null) as Enddate,
            TO_CHAR(null) as ObName,
            TO_CHAR(null) as Periodical,
            to_number(null) as ObligationType_ID,
            to_number(null) as Clients_ID,
            to_number(null) as redirect_paydoc_id,
            TO_CHAR(null) as Kind,
            to_Char(null) as currency,
            to_char(null) as IsYearlyPaysize,
            to_number(null) as LastInYearFineDate,
            to_number(null) as LastInYearFineMonths,
            to_number(null) as MainKBK,
            to_number(null) as period_presets
          from
            deffers df
          where
            df.moveset_id=MSID and
            df.obligationtype_id=OTID

           union all

           select
            'DEFFER_STOP' as ACTION_TYPE,
            nvl(df.charge_enddate+1,to_date('01.01.3000','DD.MM.YYYY')) as ACTION_DATE,
            0 as ORD,
            to_number(null) as DISCOUNT_VALUE,
            to_number(null) as PDID,
            to_date(null) as OncePayDate,
            to_number(null) as PaySize,
            to_number(null) as FineDate_ByOblig,
            to_number(null) as FineMonths,
            to_date(null) as Postingdate,
            to_date(null) as Enddate,
            TO_CHAR(null) as ObName,
            TO_CHAR(null) as Periodical,
            to_number(null) as ObligationType_ID,
            to_number(null) as Clients_ID,
            to_number(null) as redirect_paydoc_id,
            TO_CHAR(null) as Kind,
            to_Char(null) as currency,
            to_char(null) as IsYearlyPaysize,
            to_number(null) as LastInYearFineDate,
            to_number(null) as LastInYearFineMonths,
            to_number(null) as MainKBK,
            to_number(null) as period_presets
          from
            deffers df
          where
            df.moveset_id=MSID and
            df.obligationtype_id=OTID

           union all

          select
            'CHARGE_STOP' as ACTION_TYPE,
            STOP_DATE as ACTION_DATE,
            0 as ORD,
            to_number(null) as DISCOUNT_VALUE,
            to_number(null) as PDID,
            to_date(null) as OncePayDate,
            to_number(null) as PaySize,
            to_number(null) as FineDate_ByOblig,
            to_number(null) as FineMonths,
            to_date(null) as Postingdate,
            to_date(null) as Enddate,
            TO_CHAR(null) as ObName,
            TO_CHAR(null) as Periodical,
            to_number(null) as ObligationType_ID,
            to_number(null) as Clients_ID,
            to_number(null) as redirect_paydoc_id,
            TO_CHAR(null) as Kind,
            to_Char(null) as currency,
            to_char(null) as IsYearlyPaysize,
            to_number(null) as LastInYearFineDate,
            to_number(null) as LastInYearFineMonths,
            to_number(null) as MainKBK,
            to_number(null) as period_presets
          from
            dual
          ) x

          order by ACTION_DATE, ORD;

  pdl_1 ACT%rowtype;
  pdl_2 ACT%rowtype;

  ChargingActive boolean;

  moved_paysize number := 0;
  moved_comment varchar2(100) := '';

  CalPeriodStartDate date;
  CalPeriodEndDate date;


  PayDocRedir_Flag CHAR(1);
  RedirPaydoc_ID number(27);
  ChargeMoveSet_ID number(27);
  ChargeObligType_ID number(27);

  FORWARD_ADD_MONTHS number;
  FORWARD_DATE date;
  CHARGE_FINE_STOPFINES CHAR(1);
  CHARGE_OLD_ACCOUNT_VIEW char(1);

  OBLIG_ID number(27);
  ActionTypeDescription varchar2(400) := '';


BEGIN

    MV_EndDate := sm.Getmovesetenddate(AMoveSet_ID);

    ---- Вариант для ЧИТЫ.
		---- Сверхрадикальный вариант - НЕ ДЕЛАЕМ начислений для законченных ОД. Только пени... (18.01.2012)
--		if MV_EndDate is not null  and MV_EndDate <=  sysdate then
--			  FullRecalcFines(AMoveSet_ID, AObligType_ID,'N');
--				return;
--	  end if; --- END вариант для Читы.

  G_CloseDate := to_date(sm.getparametersimple('ENDPERIOD'),'DD.MM.YYYY');
  MV_StartDate := sm.Getmovesetsincedate(AMoveSet_ID);

  TOTAL_STOP := false;
  -- отсрочка до даты не используется
  DEFFER_DATE := NULL;

  begin
    select op.charge_forward, op.charge_forward_months, op.charge_first_day,op.charge_first_n, op.period_first_day, op.charge_lastday, op.charge_fine_stopfines, op.charge_old_account_view, obl.ID, obl.RECALC_START_DATE, op.percents_instant, op.Partial_Period, op.block_first_two

    into CHARGE_FORWARD, FORWARD_ADD_MONTHS, CHARGE_FIRST_DAY, CHARGE_FIRST_N,  PERIOD_FIRST_DAY,  CHARGE_LASTDAY, CHARGE_FINE_STOPFINES, CHARGE_OLD_ACCOUNT_VIEW, OBLIG_ID, ARecalc_Start_Date, A_PERCENTS_INSTANT, PartialPeriod, block_first_two
    from sm.oblig_presets op,
         sm.obligations obl
    where op.id=obl.oblig_presets_id and
          obl.moveset_id=AMoveSet_ID and
          obl.obligationtype_id=AObligType_ID;

    exception
    when others then
			    insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
          values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'Не смогли получить параметры обязательства типа ' || to_char(AObligType_ID) ||  ' в ОД ' || to_char(AMoveSet_ID), 'FULLRECALC_PKG.FullRecalcCharges()', user, 3, 3, 2, AMoveSet_ID, null, 'N');
          RETURN; -- не смогли полчить параметры обязательства - выходим
  end;

----- Некоторые обще-профилактические подчистки <<< 11.02.2012 <<<
-- !!! Если кому покажется плохим стиль бороться с последствиями вместо причин, так я вам один умный мысль скажу:
--   - Не всегда, но чаще чем кажется, бывает лучше в ОДНОМ месте прибить дефект, чем рыться во МНОЖЕСТВЕ причин его возникновения, БЕЗ ГАРАНТИИ что знаешь их все. Аднака.
    --  Удаляем ранее сделанные распределения платежей, иначе мусор искажает повторное формирование расперделений.
   Delete  from SM.PAYMENTS_DISTRIBUTION pd where PAYMENTS_ID in
          (
          Select pm.ID  from SM.PAYMENTS pm
          where pm.MOVESETS_ID = AMoveset_ID and pm.OBLIGATIONTYPE_ID = AObligtype_ID
                and pm.paymethod_id <> 3
                and ((pm.apply_date >= ARecalc_Start_Date and sm.getparameter('PAYMENT_USE_APPLY_DATE') = 'Y') --- 21.02.2014 Morozova  иначе удалялись распределенные платежи до ARecalc_Start_Date
                     or exists (select * from sm.documents ds
                                 where ds.id = pm.documents_id
                                   and ds.docdate >= ARecalc_Start_Date and sm.getparameter('PAYMENT_USE_APPLY_DATE') = 'N'))
          );

 --- 13.03.2014 Morozova удаляем все распределения платежей, если они вызваны списанием долга
    Delete  from SM.PAYMENTS_DISTRIBUTION pd where PAYMENTS_ID in
          (
          Select pm.ID  from SM.PAYMENTS pm
          where pm.MOVESETS_ID = AMoveset_ID and pm.OBLIGATIONTYPE_ID = AObligtype_ID and pm.paymethod_id = 3
                and ((pm.apply_date >= ARecalc_Start_Date and sm.getparameter('PAYMENT_USE_APPLY_DATE') = 'Y') --- 13.04.2015 Morozova  иначе удалялись распределенные платежи до ARecalc_Start_Date
                     or exists (select * from sm.documents ds
                                 where ds.id = pm.documents_id
                                   and ds.docdate >= ARecalc_Start_Date and sm.getparameter('PAYMENT_USE_APPLY_DATE') = 'N'))
          );

		--  Восстанавливаем почему-угодно отсутствующие планы погашения к начислениям.
		INSERT INTO SM.PAYMENTS_PLAN(ID,CHARGES_ID,OBLIGATIONS_ID,FINEDATE,VAL)
				Select SM.SEQPAYMENTS_PLAN.NEXTVAL, ch.ID,  OBLIG_ID,  ch.finedate,   ch.paysize
				from SM.CHARGES ch
				where   ch.MOVESETS_ID = AMoveset_ID and ch.OBLIGATIONTYPE_ID = AObligtype_ID
				and not exists (Select * from SM.PAYMENTS_PLAN ppl where ppl.charges_id = ch.ID);
--------------------END подчисток --------------------


  FORWARD_DATE:=add_months(trunc(sysdate),FORWARD_ADD_MONTHS);

  -- инициализация
  --определиться до какого момента будет формироваться расчет
  --если не установлена конечная дата последнего периода, то принимаем её равной концу календарного периода

  --периодичность последнего обязательства
    open pp(AMoveSet_ID,AObligType_ID);
    fetch pp into perchar;
    if pp%notfound or (perchar='T')or(perchar='N') then
      perchar:='N';
    end if;
    close pp;

     -- ADate - дата, до которой производить начисление
    -- Если CHARGE_FORWARD=Y, то начислять вплоть до окончания договора

    if CHARGE_FORWARD='Y' then
      if (MV_EndDate is Null) then
        ADate:=FORWARD_DATE;
      else
        -- 10.03.2011 ADate:=MV_EndDate+1; -- Общий вариант --
        ADate:=MV_EndDate + 5; -- 10.03.2011 -- Общий вариант -- Начисление на 5 дней вперед - для сигнализации о предстоящем сроке платежа --
        -- ADate:= LEAST(MV_EndDate+1, FORWARD_DATE); -- "Алтайский" вариант --
      end if;
--	  elsif  (MV_EndDate is Null OR MV_EndDate >= FORWARD_DATE) and perchar<>'N' then   --- <<< 29.06.2012 ------
--        ADate:=FORWARD_DATE;
    elsif CHARGE_FORWARD='N' then
      if (MV_EndDate is Null) then
        if not perchar='N' then
          ADate:=charging_pkg.GetNextPeriod(perchar, trunc(sysdate));
        else
          ADate:=trunc(sysdate);
        end if;
      else
        if not perchar='N' then
          ADate:=LEAST(MV_EndDate+1,charging_pkg.GetNextPeriod(perchar,trunc(sysdate)));
        else
          ADate:=LEAST(MV_EndDate+1,trunc(sysdate));
        end if;
      end if;
    end if;

  -- Коэффициент льготы
    DISCOUNT:=1;

    ChargingActive := False; -- расчет не производить до первого START_PERIOD
    FirstCharge := 'Y';       --* определяем самое первое начисление   !!! 23.09.2011 - перенесено сюда!


     -- отбираем обязательства для данного movesets.id  текущего типа
    Open ACT(AMoveSet_ID,AObligType_ID,ADate);
    fetch ACT into pdl_1; -- очередная строка - текущий период начислений
    fetch ACT into pdl_2; -- следующая строка (чтобы знать дату окончания текущего периода начислений)

		---- MAIN LOOP !!!!!!!! ------------------------------------------------------------------------------
    LOOP  --for pdl
      exit when ACT%notfound;

 if (pdl_1.Action_Date = '01.08.2014' or pdl_1.Action_Date = '11.08.2014') then
   FirstCharge := FirstCharge;
 end if;
 
       --*Писарев - если периодичность не стандартная - ничего не трогаем.
      if pdl_1.Periodical not in ('Y','Q','T','G','N','H') then

              begin
                 --проверяем, указана ли процедура для расчета
                  v_SqlCode:= ' select o.callprocname  '||
                          ' from sm.obl_periodtypes o '||
                          ' where o.periodical='''||pdl_1.Periodical ||'''';
                 execute immediate v_SqlCode into v_ProcName;

                 --Формат передачи аргументов: paydocID, ACTION_TYPE
                 if  v_ProcName is not null then
                   v_SqlCode:='begin '||v_ProcName||'('||pdl_1.PDID||','''||pdl_1.ACTION_TYPE||''','||pdl_1.ACTION_DATE||'); end;';
                   execute immediate v_SqlCode;
                 end if;

                 goto continue_clause;
              exception
                when others then goto continue_clause;
              end;
       end if;
      --*Писарев end;


      CurrPeriodFirstDay:=pdl_1.ACTION_DATE;
      CurrPeriodLastDay:=pdl_2.ACTION_DATE-1;

      -- начало периода операции движения - установим параметры обязательства
      if pdl_1.ACTION_TYPE='START_PERIOD' Then
                  OncePayDate:=pdl_1.OncePayDate;
                  PaySize:=pdl_1.PaySize;
                  FineDate_ByOblig:=GREATEST(nvl(pdl_1.FineDate_ByOblig,1),1);
	   		          FineDate := FineDate_ByOblig;
                  FineMonths:=GREATEST(nvl(pdl_1.FineMonths,1),1);
                  ObName:=pdl_1.ObName;
                  Periodical:=pdl_1.Periodical;
                  FObligationType_ID:=pdl_1.ObligationType_ID;
                  Recepient_ID:=pdl_1.Clients_ID;
                  ChargeTo:=pdl_1.redirect_paydoc_id;
                  Kind:=pdl_1.Kind;
                  CurrMovePeriodFirstDay:=pdl_1.ACTION_DATE;
                  ChargingActive := true;
                  FirstPeriod:=true;
                  LastInYearFineDate:=pdl_1.LastInYearFineDate ;
                  LastInYearFineMonths:=pdl_1.LastInYearFineMonths;
                  IsYearlyPaysize:=(pdl_1.IsYearlyPaysize='Y');
                  KBK_ID:=pdl_1.MainKBK;
                  CurPayDoc_ID:=pdl_1.PDID;

                  PayDocRedir_Flag:='N';
                  RedirPaydoc_ID:=Null;
                  ChargeMoveSet_ID:=AMoveSet_ID;
                  ChargeObligType_ID:=FObligationType_ID;

                  -- параметры расчетов
                  select opp.charge_method, opp.charge_use_holydays
                  into CHARGE_METHOD, CHARGE_USE_HOLYDAYS_str
                  from sm.oblig_periodical_presets opp
                  where opp.id=pdl_1.period_presets;

                  if CHARGE_OLD_ACCOUNT_VIEW='N' then
                    CHARGE_METHOD:=1;
                  end if;

                  if CHARGE_USE_HOLYDAYS_str='Y' then
                    CHARGE_USE_HOLYDAYS:=true;
                  else
                    CHARGE_USE_HOLYDAYS:=false;
                  end if;

                  -- Переназначение начисления при субаренде
                  if ChargeTo is not null then
                       PayDocRedir_Flag:='Y';
                       RedirPaydoc_ID:=pdl_1.PDID;
                       CurPayDoc_ID:=ChargeTo;

                       select mp.moveset_id, pd.obligationtype_id
                       into ChargeMoveSet_ID, ChargeObligType_ID
                       from
                        paydocs pd,
                        moveperiods mp
                       where
                        pd.moveperiod_id=mp.id and
                        pd.id=ChargeTo;
                   end if;

                --- FirstCharge := 'Y';       --* определяем самое первое начисление   !!! 23.09.2011 - вынесено вперед!
                 FirstCharge_Period := 'Y'; --* определяем первое начисление
       end if;

	 -- Удаление начислений ПОСЛЕ даты закрытия периода			-- VVV 12.07.2012
	 Delete from SM.CHARGES ch where ch.MOVESETS_ID = AMoveset_ID and ch.OBLIGATIONTYPE_ID = AObligtype_ID
	  and ch.document_id is null and ch.charge_type <> 'OTHER'
	 and ch.CHARGEDATE > G_CloseDate
	 AND ch.CHARGEDATE > ARecalc_Start_Date  --- <<< 14.12.2012 -- Не трогать до даты пересчета!!!
	 AND ch.PAYDOC_ID = pdl_1.PDID -- <<< 25.06.2013 -- Удаляем ТОЛЬКО по "своему" основанию (+ перенесено в цикл).
	 AND NOT EXISTS (Select /*+INDEX(CA IDX_CHRG_APPL_CHRGID)*/ * from SM.CHARGE_APPLIES ca where ca.CHARGE_ID = ch.ID and ca.APPLY_DATE <=  G_CloseDate)  -- <<< 18.02.2013 -- Не трогать имеющих Учетные данные в закр. периоде
   AND (ch.paydoc_id is null or
               exists (select * from sm.paydocs pd where pd.id=ch.paydoc_id and pd.periodical in ('Y','Q','T','G','N','H'))); --*Писарев

    ---- удаляем техническое начисление если оно сделано по несоответствующему paydoc  --12.11.2014
    delete from sm.charges ch
    where ch.id in (select ch.id
                    from sm.charges ch
                    --- inner join sm.moveperiods mp on mp.moveset_id = ch.movesets_id  -- <<< 17.11.2014 MAV (При нескольких периодах - ниже период находился ВСЕГДА)
                    where ch.paysize = 0 and ch.movesets_id = AMoveset_ID and ch.OBLIGATIONTYPE_ID = AObligtype_ID
                          and not exists (select * from sm.paydocs pd where pd.id = ch.paydoc_id
                                         and pd.moveperiod_id in (Select id from SM.MOVEPERIODS mpp where mpp.moveset_id = ch.movesets_id)) -- <<< 17.11.2014 MAV
                          and ch.document_id = (select max((Select max(d.ID) from SM.DOCUMENTS d inner join SM.DOCTYPES  dt
                                                on dt.ID=d.DOCTYPES_ID and dt.GUID = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE')) from dual));
      -- конец периода операции движения - отключим расчет
      if pdl_1.ACTION_TYPE='END_PERIOD' Then
        ChargingActive := false;
      end if;

      -- начало действия льготы
      if pdl_1.ACTION_TYPE='DSCNT_START' Then
           DISCOUNT:=DISCOUNT-pdl_1.DISCOUNT_VALUE;
							     --  VVV 15.08.2013  Удаление начислений в период действия льготы
                   Delete from SM.CHARGES ch where ch.MOVESETS_ID = AMoveset_ID and ch.OBLIGATIONTYPE_ID = AObligtype_ID
                   and ch.charge_type <> 'OTHER' and ch.document_id is null
                   and ch.CHARGEDATE > G_CloseDate
                   AND ch.CHARGEDATE > ARecalc_Start_Date    -- Не трогать до даты пересчета!!!
                   AND ch.PAYDOC_ID = CurPayDoc_ID                --  Удаляем ТОЛЬКО по "своему" основанию (+ перенесено в цикл).
                   AND ch.CHARGEDATE >= pdl_1.ACTION_DATE
                   AND ch.calperiod_end > pdl_1.ACTION_DATE  ---04.06.2014 Morozova
                   AND NVL(ch.DISCOUNTSIZE, 0) <> CurrPeriodPay * NVL(pdl_1.DISCOUNT_VALUE, 0)
                   AND ch.CHARGEDATE NOT IN (Select df.DEFFER_DATE from SM.DEFFERS df where df.MOVESET_ID = AMoveset_ID  and DF.OBLIGATIONTYPE_ID =  AObligtype_ID)
                   AND INSTR(ch.comments, '(коэфф' )  > 0	 ;  -- <<< ^^^ 21.08.2013 -- Не трогать написанные наперед отсрочкой и вообщебез льгот
                   --- ^^^ ---
      end if;

      --конец действия льготы
      if pdl_1.ACTION_TYPE='DSCNT_STOP' Then
        DISCOUNT:=DISCOUNT+pdl_1.DISCOUNT_VALUE;
      end if;

      --начало действия отсрочки
      if pdl_1.ACTION_TYPE='DEFFER_START' Then
						 DEFFER_START_DATE := pdl_1.ACTION_DATE;
						 DEFFER_DATE:=pdl_1.OncePayDate;
						 ----- <<<< 15.02.2012 <<< -- Исправлен недочет 7-го патча от 10.02.2012  (то что ниже)
						 Select max(defr.charge_enddate) into DEFFER_END_DATE --- <<< 11.03.2012 -- Добавлен max(...) - оказалось, оформляют по N отсрочек с одной даты...
						 from deffers defr
             where  defr.moveset_id=AMoveset_ID and  defr.obligationtype_id=AObligType_ID and defr.charge_sincedate = DEFFER_START_DATE;
      end if;

      --конец действия отсрочки
      if pdl_1.ACTION_TYPE='DEFFER_STOP' Then

             DEFFER_DATE:=NULL;
             DefferStop := 'Y'; -- Один раз (для каждой отсрочки) срабатывающий флаг что отсрочка кончилась
      end if;

      if pdl_1.ACTION_TYPE='CHARGE_STOP' Then
						--для тех, у кого начисления делаются предш. месяцем проверяем возможность сделать начисление на след. период
							if Kind='P' then
									 TOTAL_STOP:=true;   --выходим, только сделав ещё одно начисление
							 else
									 GOTO end_charging_clause;
							end if;
      end if;

      -- если расчет неактивен - переходим к следующему периоду начислений
      -- !!!!! проверить корректность на конец договора
      if (not ChargingActive) or (pdl_1.ACTION_DATE > ADate) then -- <<< 01.12.2011 (было - MV_EndDate)
        GOTO continue_clause;
      end if;

      -- для тех кто по графику - ничего считать не надо - перейти к следующему периоду начислений
      IF (periodical='T') THEN
          GOTO continue_clause;
      end if;

------------- For Periodical obligations !!!   --------------------------------------------------------------------------
IF Periodical!='N' THEN
  CurrDate:=CurrPeriodFirstDay;

       ------ Цикл перебора периодов между CurrDate и EndDate(начало следующего) обязателсьство -----------
  WHILE CurrDate<=CurrPeriodLastDay
   LOOP
          --размер периодического начисления
          PeriodPay:=PaySize;

          -- последний ли период в году?
          IsLastPeriodInYear:=(charging_pkg.IsLastPeriodInYear(Periodical,CurrDate)='Y');
          --Запрашиваем границы календарного периода
          charging_pkg.GetPeriodBounds(Periodical,CurrDate,PeriodFirstDay, PeriodLastDay);
          --Общее количество дней в календарном периоде
          DaysInPeriod:=(PeriodLastDay-PeriodFirstDay)+1;

          --Считаем сколько дней календарного периода в текущем периоде начислений
            Days:=LEAST(PeriodLastDay,CurrPeriodLastDay) - GREATEST(PeriodFirstDay,CurrPeriodFirstDay)+1;

          -- Для заполнения полей CALPERIOD_START и CALPERIOD_END
          CalPeriodStartDate:= GREATEST(PeriodFirstDay,CurrPeriodFirstDay);
          CalPeriodEndDate:=LEAST(PeriodLastDay,CurrPeriodLastDay);

  /*          if IsYearlyPaysize then
                 PeriodPay:=charging_pkg.GetPeriodPaysize(Periodical,CurrDate,PeriodPay);
          end if;*/

          --- 24.07.2014 Morozova  зададим фиксированную сумму начисления для ежеквартальных начислений при указанной сумме за год
          --- берутся только ежеквартальные начисления после 01.01.2013 г. (как было заявлено в письме - Нефтеюганск)
          if IsYearlyPaysize and pdl_1.action_date >= to_date('01.01.2013') and Periodical = 'Q' and Days/DaysInPeriod = 1 and PartialPeriod = 'Y' then
            PeriodPay := PeriodPay / 4;
          elsif (not IsYearlyPaysize) and pdl_1.action_date >= to_date('01.01.2013') and Periodical = 'Q' and Days/DaysInPeriod <> 1  and PartialPeriod = 'Y' then
            --- а также для неполного квартала расчитаем платеж за квартал исходя из кол-ва дней за год
            PeriodPay := charging_pkg.GetPeriodPaysize(Periodical,CurrDate,PeriodPay * 4);
          elsif IsYearlyPaysize then
            PeriodPay := charging_pkg.GetPeriodPaysize(Periodical,CurrDate,PeriodPay);
          end if;

          --CurrPeriodPay - размер начисления за текущий период начислений
          CurrPeriodPay := PeriodPay * (Days/DaysInPeriod);

          --Комментарий к начислению
          CurPeriodExpl := moved_comment || RTRIM(Lower(charging_pkg.GetPeriodName(Periodical,CurrDate)));
          moved_comment := '';

          -- если период начислений не захватывает полный календарный период,
          -- показать за сколько дней начислено
--           if Days - DaysInPeriod != 0 then
                CurPeriodExpl:=CurPeriodExpl || ' (' || TO_CHAR(Days) || ' дн., с ' || to_char(CalPeriodStartDate,'dd.MM.yyyy') ||  ' по ' || to_char(CalPeriodEndDate,'dd.MM.yyyy') || ')';
--					else
--               CurPeriodExpl:=CurPeriodExpl || ' (' || TO_CHAR(Days) || ' дн. )';
--          end if;

          -- укорачиваем наименование обязательства до 30 символов
          CurExpl:=SUBSTR(RTRIM(ObName),1,30);
          if LENGTH(CurExpl)=30 then
            CurExpl:=CurExpl||'..';
          end if;

          CurExpl:=CurExpl || ' - ' || CurPeriodExpl;


          --Добавим к сумме начисления перенесенные с прошлых периодов
          CurrPeriodPay:=CurrPeriodPay+moved_paysize;
          moved_paysize := 0;

          -- внесение информации о начислении
  --        IF CurrPeriodPay != 0 THEN --- <<< 05.03.2012 <<<

           --расчитываем дату начисления пени
           -- если это последний период в году и установлены для него свои параметры даты начисления пени,
           -- то дата начисления пени устанавливается особо
           if IsLastPeriodInYear
											 and LastInYearFineDate is not null
											 and LastInYearFineMonths is not null then
			      								ChargeFineDate:=ADD_MONTHS(PeriodFirstDay, LastInYearFineMonths-1) + LastInYearFineDate - 1;
			        				-- если первый период (начало договора) и начало после срока платежа - сместим на начало договора
											if FirstFirstPeriod and CurrMovePeriodFirstDay>ChargeFineDate then
							  			  		ChargeFineDate:=CurrMovePeriodFirstDay;
											end if;
            else
										-- для всех периодов в году, кроме последнего
										if Kind='B' then  -- <<< Оплата в текущем периоде 
													 -- если указано 29-31 число - корректируем дату исполнения обязательства по плате (она же  дата начисления пени) - на последнее возможное число периода)
													if  FineDate_ByOblig > 28 then
                              Select LEAST(EXTRACT(DAY from LAST_DAY(ADD_MONTHS(PeriodFirstDay,FineMonths-1))), FineDate_ByOblig)  into FineDate from dual;
													end if;
													--при предоплате
													--если в первый период (начало договора) оказалось после срока платежа
													if (FirstFirstPeriod
														     and (CurrMovePeriodFirstDay > ADD_MONTHS(PeriodFirstDay,FineMonths-1)+FineDate-1)
														    and CurrMovePeriodFirstDay = MV_StartDate ) -- <<< 17.10.2013 -- чтобы условите работало для реально первых начислений в договоре (а не для обязательств возникших в последующих периодах, те - по условиям для периодов)
														 then
																	if CHARGE_FIRST_DAY = 1
																		then -- устанавливаем первое начисление равным началу договора
																					ChargeFineDate:=CurrMovePeriodFirstDay;
																	elsif CHARGE_FIRST_DAY = 2 then -- устанавливаем первое начисление N дней от начала договора
                                          if CHARGE_FIRST_N is null then 
