												if  FineDate_ByOblig > 28 then
															Select LEAST(EXTRACT(DAY from LAST_DAY(ADD_MONTHS(PeriodFirstDay,FineMonths-1) + 1)), FineDate_ByOblig)  into FineDate from dual;
												end if;
												 --для постоплаты просто добавляем один период
													ChargeFineDate:=charging_pkg.IncDate(Periodical,PeriodFirstDay);
													ChargeFineDate:=ADD_MONTHS(ChargeFineDate,FineMonths-1)+FineDate-1;

										elsif Kind='P' then -- <<< Оплата в предыдущем периоде (предоплата)
												-- если указано 29-31 число - корректируем дату исполнения обязательства по плате (она же  дата начисления пени) - на последнее возможное число периода)
												if  FineDate_ByOblig > 28 then
															Select LEAST(EXTRACT(DAY from LAST_DAY(ADD_MONTHS(PeriodFirstDay,FineMonths-1)-1)), FineDate_ByOblig)  into FineDate from dual;
												end if;
                        -- Ниже - блок учитывающий настройки CHARGE_FIRST_DAY внесен только 11.12.2014
                        --при предоплате
                        --  первый период (начало договора) всегда после срока платежа
                        if (FirstFirstPeriod and CurrMovePeriodFirstDay = MV_StartDate ) then
                                if CHARGE_FIRST_DAY = 1
                                  then -- устанавливаем первое начисление равным началу договора
                                        ChargeFineDate:=CurrMovePeriodFirstDay;
                                elsif CHARGE_FIRST_DAY = 2 then -- устанавливаем первое начисление N дней от начала договора
                                        if CHARGE_FIRST_N is null then 
