                                        else
                                           ChargeFineDate := ADD_MONTHS(CurrMovePeriodFirstDay,FineMonths-1) + CHARGE_FIRST_N; -- <<< 11.12.2014
                                        end if; 
                                        -- Если указано - первый и второй периоды оплаты делать одновременно на условиях первого (11.12.2014)
                                        if (block_first_two = 'Y')  then  -- <<< 11.12.2014
                                           tempDate := ChargeFineDate; -- <<< tempDate будет использована однократно похзже
                                        end if;     
                                elsif CHARGE_FIRST_DAY = 3 then
                                        moved_paysize := CurrPeriodPay; -- переносим на следующее начисление
                                        moved_comment := CurPeriodExpl || ', ';
                                       --- V-V-V- MAV 16.10.2014 V-V-V ---
                                       -- Подчистка начислений в "перепрыгиваемый" период - на случай смены политики с 1 на 3 (или др.)
                                       for chCurr1 in
                                         (Select ch.ID from SM.CHARGES ch
                                            where ch.Movesets_id=AMoveset_ID
                                                and ch.obligationtype_id=AObligType_ID
                                                and ch.document_id is null
                                                and ch.CHARGE_TYPE = 'OBLIGATION'
                                                and trunc(ch.transtime) <= G_CloseDate --- 26.06.2014 Morozova сторнируются только введенные в закрытом периоде
                                                and ch.paydoc_id = CurPayDoc_ID
                                                and ch.calperiod_start = CalPeriodStartDate
                                                and ch.calperiod_end = CalPeriodEndDate
                                                and ch.paysize = CurrPeriodPay
                                                and ch.chargedate >= CalPeriodStartDate
                                            )
                                          loop
                                               OBLIG_ACC_PKG.StornoCharge(chCurr1.ID);
                                          end loop;
                                        -- А затем - собственно удаление начислений
                                        Delete from SM.CHARGES ch
                                          where ch.Movesets_id=AMoveset_ID
                                                and ch.obligationtype_id=AObligType_ID
                                                and ch.document_id is null
