                                                and ch.paydoc_id = CurPayDoc_ID
                                                and ch.calperiod_start = CalPeriodStartDate
                                                and ch.calperiod_end = CalPeriodEndDate
                                                and ch.paysize = CurrPeriodPay
                                                and ch.chargedate >= CalPeriodStartDate;
                                        ---- END Подчистка начислений в "перепрыгиваемый" период --
                                        goto next_date_clause;
                                elsif CHARGE_FIRST_DAY = 4 then -- <<< 05.09.2013 << -- если начало договора после срока в тек. месяце - то - последним днем месяца
                                        ChargeFineDate := last_day (CurrDate) +1;
                                end if;
                        -- VVV 16.10.2013 -- Для следующих периодов начинающихся после даты начисления в них же - своя логика...
                         elsif  FirstPeriod /*and (CurrMovePeriodFirstDay > ADD_MONTHS(PeriodFirstDay,FineMonths-1)+FineDate-1)*/ then
                                if PERIOD_FIRST_DAY = 1 then -- устанавливаем первое начисление равным началу периода
                                        ChargeFineDate:=CurrMovePeriodFirstDay;
                                elsif PERIOD_FIRST_DAY = 2 then -- устанавливаем первое начисление N дней от начала периода
--                                        ChargeFineDate := ADD_MONTHS(CurrMovePeriodFirstDay,FineMonths-1)+FineDate-1;
                                        if (tempDate is null) then
																					 ChargeFineDate := ADD_MONTHS(CurrMovePeriodFirstDay,FineMonths-1)+FineDate-1;
                                        else  
                                           ChargeFineDate := tempDate;
                                           tempDate := null;
                                        end if;   
                                elsif PERIOD_FIRST_DAY = 3 then
                                        moved_paysize := CurrPeriodPay; -- переносим на следующее начисление
                                        moved_comment := CurPeriodExpl || ', ';
                                       --- V-V-V- MAV 16.10.2014 V-V-V ---
                                       -- Подчистка начислений в "перепрыгиваемый" период - на случай смены политики с 1 на 3 (или др.)
                                       for chCurr1 in
