                                            )
                                          loop
                                               OBLIG_ACC_PKG.StornoCharge(chCurr1.ID);
                                          end loop;
                                        -- А затем - собственно удаление начислений
                                        Delete from SM.CHARGES ch
                                          where ch.Movesets_id=AMoveset_ID
                                                and ch.obligationtype_id=AObligType_ID
                                                and ch.document_id is null
