                                        ---- END Подчистка начислений в "перепрыгиваемый" период --
                                        goto next_date_clause;
                                elsif PERIOD_FIRST_DAY = 4 then -- <<< 05.09.2013 << -- если начало договора/периода после срока в тек. месяце - то - последним днем месяца
                                        ChargeFineDate := last_day (CurrDate) +1;
                                elsif  PERIOD_FIRST_DAY = 5 then -- <<< 17.10.2013 << -- !!! Начисляем как обычно (в этом случае ПРОСРОЧЕННОЙ!!!)  датой!!!
                                        ChargeFineDate := ADD_MONTHS(PeriodFirstDay, FineMonths-1) + FineDate-1;
                                end if;
                         else
                         -- обычный период при предоплате - убавляем на 1 месяц
                            ChargeFineDate:=ADD_MONTHS(trunc(PeriodFirstDay),-1) + FineDate-1;
