						if ChargeFineDate is null then
	                  insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
                    values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'ChargeFineDate is null в ОД ' || to_char(AMoveSet_ID), 'FULLRECALC_PKG.FullRecalcCharges()', user, 3, 3, 2, AMoveSet_ID, null, 'N');
					  end if;

           --определение даты начисления за текущий период
            IF CHARGE_METHOD IN (1,2,3,4,5,6) THEN
              CH_DATE:=trunc(CurrDate,'MONTH');

              IF CHARGE_METHOD=2 THEN
                CH_DATE:=charging_pkg.GetNextPeriod(Periodical,CurrDate)-1;
              ELSIF CHARGE_METHOD=3 THEN
                CH_DATE:=charging_pkg.GetNextPeriod(Periodical,CurrDate);
              ELSIF CHARGE_METHOD=4 THEN
                CH_DATE:=LAST_DAY(CH_DATE);
              ELSIF CHARGE_METHOD=5 THEN
                CH_DATE:=ADD_MONTHS(CH_DATE,1);
              ELSIF CHARGE_METHOD=6 THEN
                CH_DATE:=TRUNC(ChargeFineDate,'MONTH');
              END IF;

            END IF; --(1,2,3,4,5,6)

            if CHARGE_METHOD=7 then
                  CH_DATE:=ChargeFineDate;
            elsif CHARGE_METHOD = 8 then
                  CH_DATE:=ChargeFineDate - 1; -- + 1;  -- <<< 31.05.2012 <<< ??? Почему было +1 ??? - прямо противоположное требуемому -------------
             end if;

            if CHARGE_LASTDAY='Y' then
              --все начисления выходящие за пределы действия договора делать последним днем договора
              CH_DATE:=LEAST(CH_DATE,nvl(MV_EndDate,ADate));
             -- IF CHARGE_FINE_STOPFINES='Y' THEN
             -- !!! 17.06.2011 - не надо начислять пеню с окончания периода - она - со своей даты, даже после окончания договора.  ChargeFineDate:=LEAST(ChargeFineDate,nvl(MV_EndDate,ADate));
             -- END IF;
            end if;

          --Льготы
          DISCOUNT_SUM:=null;
          IF DISCOUNT<>1 THEN
            DISCOUNT_SUM:=CurrPeriodPay;
            CurrPeriodPay:=CurrPeriodPay*DISCOUNT; -- начисление с учётом скидки
            DISCOUNT_SUM:=DISCOUNT_SUM-CurrPeriodPay; -- сумма скидки

            CurExpl:=nvl(CurExpl,'') || ' (коэфф. '||TO_CHAR(DISCOUNT,'FM99999990.999999') || ')';
          END IF;

         --если в у.е - пересчитываем на рубли по курсу
          if pdl_1.currency='Y' then
            CurCurrency:=GetCurrencyCourse(CH_DATE,CurPayDoc_ID);
            CurrPeriodPay:=CurrPeriodPay*CurCurrency;
            CurExpl:=nvl(CurExpl,'') || ' (курс: ' || TO_CHAR(CurCurrency) ||')';
          end if;

          if DEFFER_DATE IS NOT NULL then
            CH_DATE := DEFFER_DATE;
            ChargeFineDate := DEFFER_DATE;
          end if;

          if CHARGE_USE_HOLYDAYS and ChargeFineDate is not null then --17.04.2014 Morozova
             --если дата конца срока оплаты попала на нерабочий день - смещаем эту дату на ближайший рабочий
						  --- VVV Так суббота (да и любой единичный праздник) - становилась днем начисления !!! Как оно работало??? (Чтобы понедельник сдвигался на вторник? - так не нада оно...)
                ChargeFineDate:=sm.GetFirstWorkDate(ChargeFineDate-1)+1;
						 --- VVV А так - всегда следующий рабочий день. (Что пеня со следующего за ним дня - это другая история).
						 ---   ChargeFineDate := sm.GetFirstWorkDate(ChargeFineDate);
          end if;

          ----- Дополнительно расшифровываем начисление --- ФИГНЯ, АДНАКА, ПОКА ПОЛУЧИЛАСЬ. НАДА ПЕРЕДЕЛАТЬ
          if trunc(CH_DATE) = trunc(pdl_1.ACTION_DATE)  then
                    -- конец периода операции движения - отключим расчет
                   if pdl_1.ACTION_TYPE='END_PERIOD' Then
                     ActionTypeDescription := ' (Окончание периода)';
                    --начало периода
                  elsif pdl_1.ACTION_TYPE='START_PERIOD' Then
                      ActionTypeDescription := ' (Начало периода)';
                    --начало действия льготы
                  elsif pdl_1.ACTION_TYPE='DSCNT_START' Then
                   ActionTypeDescription := ' (Начало льготы)';
                    --конец действия льготы
                    elsif pdl_1.ACTION_TYPE='DSCNT_STOP' Then
                      ActionTypeDescription := ' (Окончание льготы)';
                    --начало действия отсрочки
                    elsif pdl_1.ACTION_TYPE='DEFFER_START' Then
                      ActionTypeDescription := ' (Начало отсрочки)';
                     --конец действия льготыis_multi_subject is_multi_subject is_multi_subject
                    elsif pdl_1.ACTION_TYPE='DEFFER_STOP'  and DefferStop = 'Y'  Then
                      ActionTypeDescription := ' (Окончание отсрочки)';
                     elsif pdl_1.ACTION_TYPE='CHARGE_STOP' Then
                       ActionTypeDescription := ' (Срок начисления)';
                    end if;
          end if;
          CurExpl := CurExpl || ActionTypeDescription;
          ActionTypeDescription := '';
          DefferStop := 'N';

--- VVV 14.12.2012 --Не делаем начислений до даты начала пересчета. Делаем только после нее------
if CH_DATE <= ARecalc_Start_Date	then
		GOTO	next_date_clause;
end if;
