      END LOOP; --WHILE CurrDate
       --если конец периода изменений
      IF CurrDate>=NVL(CurrPeriodLastDay, ADate) THEN
        CurrDate:=CurrDate+1;
      END IF;


-------------------------------- For NON-periodical obligations -------------------------------------------------------------------------------------
   ELSIF (Periodical='N'  and OncePayDate is not Null) THEN
      if (CHARGE_FORWARD='Y') or (OncePayDate<=SYSDATE) then
       ChargeFineDate:=OncePayDate;

       --- 15.10.2014 Morozova  находим действующую льготу на дату начисления
       begin
         select 1 - ds.discount_value into DISCOUNTEDIN
         from sm.discounts ds
         where ds.moveset_id = ChargeMoveSet_ID
                 and ds.obligationtype_id = ChargeObligType_ID
                 and ds.discharge_type = 'MAIN'
                 and OncePayDate between ds.sincedate and nvl(ds.enddate, to_date('01.01.3000'));
       exception
         when no_data_found then
           DISCOUNTEDIN := 1;
         when others then
           DISCOUNTEDIN :=  DISCOUNT;
       end;

       -- укорачиваем наименование обязательства до 30 символов
       CurExpl:=SUBSTR(RTRIM(ObName),1,30);
       if LENGTH(CurExpl)=30 then
         CurExpl:=CurExpl||'..';
       end if;

       DISCOUNT_SUM:=null;

       CurrPeriodPay:=PaySize;

--       IF DISCOUNT<>1 THEN
       if DISCOUNTEDIN <> 1 then   ---15.10.2014 Morozova
         DISCOUNT_SUM:=CurrPeriodPay;
         CurrPeriodPay:=CurrPeriodPay*DISCOUNTEDIN; --  15.10.2014 Morozova DISCOUNT начисление с учётом скидки
         DISCOUNT_SUM:=DISCOUNT_SUM-CurrPeriodPay; -- сумма скидки

         CurExpl:=nvl(CurExpl,'') || ' (коэфф. '||TO_CHAR(DISCOUNTEDIN,'FM99999990.999999') || ')'; ---15.10.2014 Morozova DISCOUNT
       END IF;

--- VVV 14.12.2012 --Не делаем начислений до даты начала пересчета. Делаем только после нее------
if OncePayDate <= ARecalc_Start_Date	then
		GOTO	continue_clause;
end if;
--- ^^^ ------------------------------------------------------------------------------------------------------------------------------------


       --если в у.е - пересчитываем на рубли по курсу
       if pdl_1.currency='Y' then
         CurCurrency:=GetCurrencyCourse(CH_DATE,CurPayDoc_ID);
         CurrPeriodPay:=CurrPeriodPay*CurCurrency;
         CurExpl:=nvl(CurExpl,'') || ' (курс: ' || TO_CHAR(CurCurrency) ||')';
       end if;

        if CHARGE_USE_HOLYDAYS and ChargeFineDate is not null then --17.04.2014 Morozova
             --если дата конца срока оплаты попала на нерабочий день - смещаем эту дату на ближайший рабочий
