  ---------------
--*     Морозова
     select  --+INDEX(cr IDX_CHG_MOVESET_ID)
     count (*) into c
		 FROM SM.Charges cr
     where cr.movesets_id = ChargeMoveSet_ID  and cr.obligationtype_id = ChargeObligType_ID
               and cr.document_id is null  and cr.charge_type = 'OBLIGATION'
							 and cr.PAYDOC_ID = NVL(RedirPaydoc_ID, CurPayDoc_ID); -- <<< 24.06.2013 -- Только ради Субаренды добавлен RedirPaydoc_ID (к тому же 1-м номером)

      if c = 1  then -- VVV Есть запись - правим.
				       select  --+INDEX(cr IDX_CHG_MOVESET_ID)
							 ID into c  FROM SM.Charges cr
											 where cr.movesets_id = ChargeMoveSet_ID  and cr.obligationtype_id = ChargeObligType_ID
																 and cr.document_id is null and cr.charge_type = 'OBLIGATION'
							                   and cr.PAYDOC_ID = NVL(RedirPaydoc_ID, CurPayDoc_ID);
                  Update  SM.CHARGES set  CHARGEDATE = OncePayDate , COMMENTS=CurExpl,
                  PAYSIZE=CurrPeriodPay, FINEDATE=ChargeFineDate,
                   PAYDOC_ID=NVL(RedirPaydoc_ID, CurPayDoc_ID), CLS_KBK_ID=KBK_ID where ID = c;

                  Update SM.PAYMENTS_PLAN pp set FINEDATE=ChargeFineDate, VAL = CurrPeriodPay  where  PP.CHARGES_ID = c;

                  SM.OBLIG_ACC_PKG.RecalcChargesApplies( c,
                               OncePayDate, ChargeMoveSet_ID, null, CurExpl, CurrPeriodPay, 'OBLIGATION',
                               ChargeObligType_ID, ChargeFineDate, DISCOUNT_SUM, NVL(RedirPaydoc_ID, CurPayDoc_ID),
                               CalPeriodStartDate, CalPeriodEndDate,
                               KBK_ID, PayDocRedir_Flag, RedirPaydoc_ID, OBLIG_ID, null, null, 'Y');

		  elsif c > 1 then  -- VVV АНОМАЛИЯ - больше 1 записи - подчищаем...
			         Delete from SM.CHARGES cr where cr.movesets_id = ChargeMoveSet_ID
               and cr.obligationtype_id = ChargeObligType_ID
               and cr.document_id is null  and cr.charge_type = 'OBLIGATION'
							 and cr.PAYDOC_ID = NVL(RedirPaydoc_ID, CurPayDoc_ID)
							 and cr.ID <> (Select MAX(cr2.ID) from SM.CHARGES cr2 where cr2.movesets_id = ChargeMoveSet_ID and cr2.obligationtype_id = ChargeObligType_ID
               and cr2.document_id is null  and cr2.charge_type = 'OBLIGATION'  and cr2.PAYDOC_ID = NVL(RedirPaydoc_ID, CurPayDoc_ID)
							 and  cr2.ID <> cr.ID )
							 AND  cr.chargedate > ARecalc_Start_Date; ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.


			elsif c=0 then  -- VVV Не было записи - заводим.
               select sm.seqcharges.nextval into idNext from dual;

                if pdl_1.ACTION_TYPE<>'DEFFER_START'  or (pdl_1.ACTION_TYPE='DEFFER_STOP'  and DefferStop = 'Y') or pdl_1.ACTION_TYPE='DSCNT_START'  or pdl_1.ACTION_TYPE='DSCNT_STOP'  then
									-- внесение информации о начислении единовременного обязательства
                  INSERT INTO Charges (id, chargedate, movesets_id, document_id, comments, paysize, charge_type, obligationtype_id, Finedate, Discountsize,Paydoc_Id,Cls_Kbk_Id,Redir_Flag,Redir_Paydoc_Id, calperiod_start,Calperiod_End)
                     VALUES(idNext, OncePayDate, ChargeMoveSet_ID, null, CurExpl,  --- || ' ---' || FirstCharge_Period ,
                                      CurrPeriodPay,'OBLIGATION', ChargeObligType_ID,ChargeFineDate,
                                      DISCOUNT_SUM,NVL(RedirPaydoc_ID, CurPayDoc_ID),KBK_ID,PayDocRedir_Flag,RedirPaydoc_ID,
                                       CurrPeriodFirstDay, CurrPeriodLastDay ); -- <<< 02.10.2014 MAV Заполнение полей CALPERIOD_START и CALPERIOD_END
                     ----- Пишем сопровждающий начисление план его погашения ----
                    select count (*) into cc from sm.payments_plan t
                           where t.obligations_id = OBLIG_ID
                                 and t.finedate = ChargeFineDate
                                 and t.val = CurrPeriodPay;
                  if cc = 0 then  --*
                     INSERT INTO SM.PAYMENTS_PLAN(ID,CHARGES_ID,OBLIGATIONS_ID,FINEDATE,VAL)
                           VALUES(SM.SEQPAYMENTS_PLAN.NEXTVAL,idNext,OBLIG_ID,ChargeFineDate,CurrPeriodPay);
                  end if;        --*

                  -- вызываем процедуру сторнирования проводок, если произошло первое изменение начисления
                 if FirstCharge_Period = 'Y' then
                      SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext,
                                       OncePayDate, ChargeMoveSet_ID, null, CurExpl, CurrPeriodPay, 'OBLIGATION',
                                       ChargeObligType_ID, ChargeFineDate, DISCOUNT_SUM, NVL(RedirPaydoc_ID, CurPayDoc_ID), CalPeriodStartDate,
                                       CalPeriodEndDate, KBK_ID, PayDocRedir_Flag, RedirPaydoc_ID, OBLIG_ID, null, null, FirstCharge);
                  end if;

                         if G_CloseDate >= OncePayDate then
                              -- закрытый бухгалтерский период
                              A_comments := 'Исправляющая: ';
                              A_corr_flag :='Y';
                              A_chargedate := trunc(sysdate);
                              A_reversal_role := 'Исправляющая';
                         else
                              A_comments := '';
                              A_corr_flag := 'N';
                              A_chargedate := OncePayDate;
                              A_reversal_role := '';
                         end if;

                        -- ищем, была ли весена исправляющая проводка в открытом периоде с имеющимся начислением,
                        -- если да, то больше ее не вносим
                        select count(*) into c
                        from sm.charge_applies cha
                           where cha.moveset_id = ChargeMoveSet_ID
                               and cha.obligtype_id = ChargeObligType_ID
                               and trim(cha.charge_type) = 'O'
                               and cha.apply_date > G_CloseDate
                               and (trim(cha.reversal_role) = 'Исправляющая' or cha.reversal_role is null)
                               and cha.charge_id = idNext;

                         -- добавляем проводку для начисления
--												 if (A_chargedate <= SYSDATE) then -- <<< 07.12.2012 НЕ пишем учетных данных для будущих "начислений"!!! (уж не говоря что такое сами эти "начисления"...)
-- 04.06.2013 -- Пусть пишутся и на будущее, поскольку: 1. Это все-таки не проводки а фиг знает что (и соответственно относиться к ним можно по-разному) 2. Поскольку  "уч.данные" пишутся и из триггеров, то кто будет потом их формировать (для доп.нач., платежей...)
												 if c = 0 and CurrPeriodPay <> 0 then--- 17.02.2014 Morozova  then
                         		 insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
																																	description, charge_id, corr_flag, cls_kbk_id, obligations_id,
																																	payments_distribution_id, reversal_role, reversallink_id, payment_id)
																	 values (sm.seqcharge_applies.nextval, A_chargedate, CurrPeriodPay, ChargeObligType_ID, ChargeMoveSet_ID,
																																	'O', A_comments || CurExpl, idNext, A_corr_flag,  KBK_ID,
																																	null, null, A_reversal_role, null, null);
												end if;
                 FirstCharge_Period := 'N';
                 end if;
     end if;           --*

     ---------------------------------------------------------------------------------------------
   end if; -- (CHARGE_FORWARD='Y')or(OncePayDate<=SYSDATE)
   FirstCharge := 'N';
   END IF;

     <<continue_clause>>
     PrevFineDate:=ChargeFineDate;
 		 -- VVV 09.10.2012 -- Событие могло быть одним из "неполноценных", а перебивает присваиванием ниже (pdl_1:=pdl_2) ВСЕ параметры. Частично восстанавливаем.
		 if pdl_2.currency is null then
			   pdl_2.currency := pdl_1.currency;
	   end if;
    pdl_1:=pdl_2;
    fetch ACT into pdl_2;
-- commit;  --- <<< 22.06.2012
   END LOOP; --for pdl
   <<end_charging_clause>>
   close ACT;

  FullRecalcFines(AMoveSet_ID, AObligType_ID ,'Y');
 --- commit;  --- <<< 22.06.2012 -Нельзя - при вызове в триггерах - ошибка!

END FullRecalcCharges;



---------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------------------------------------
------------------------------- Пересчет пеней для обязательства. ---------------------------------------------
---------------------------------------------------------------------------------------------------------------------------------
procedure FullRecalcFines( AMoveSet_ID in number, AObligType_ID in number, DelCharges IN CHAR default 'Y')
IS
c integer;                 --* служебная
idNext integer;            --* ID начисления пени
FirstCharge char(1);       --* самое первое начисление
FirstCharge_Period char(1);        --* первое измененное начисление пени
A_reversal_role varchar2(100); --* роль проводки

  Saldo number(27,2);
  --SaldoCharges number(27,2);
	SaldoChargesNoFine number(27,2);
  TmpSum number(27,2) := 0;
	 --SaldoPayments number(27,2);
  FinePercent number;
  PrevMoment DATE;

  PayDelay integer;
--	PayDelay_2 integer := 0; -- На случай если период разорвется на високосный и невисокосный <<<НЕ НАДА!!! -- Нет периодов начислений переходящих через год!
	DaysInYear integer;
--	DaysInYear_2 integer := 0; -- На случай если период разорвется на високосный и невисокосный <<<НЕ НАДА!!! -- Нет периодов начислений переходящих через год!
  Multi number;

  FineSize number(27,2);
  FinePart number;
  CurExpl varchar2(200);
  FineExpl varchar2(200);
  CurRefinRate number; -- текущая учётная ставка ЦБ
  RefPart number;      -- доля учётной ставки ЦБ
  CHARGE_METHOD integer;
  CHARGE_FINE_METHOD integer;
  CHARGE_SHOW_FDATE char(1);
  CHARGE_FINE_STOPFINES char(1);
	A_FINE_ON_LAST_DAY char(1);
  cm varchar2(100);
  DISCOUNT number(27,2);
  DISCOUNT_SUM number(27,2);
  CALENDAR_TYPE number(27);

  p1 integer;
  p2 integer;
  p3 integer;
 p4 integer;
 c1 integer;
  curPDID sm.paydocs.id%type;
  curKBK_ID sm.paydocs.fine_cls_kbk_id%type;  --Код бюджетной классификации

  Expl_Date Date;
  PrevMomentActionType varchar2(60);

  FINEONDEBT char(1);
  FINE_KIND char(1);
  FINEVALUEFIXED_DAILY char(1);
  FINEVALUEFIXED number(27,2);
  CHARGE_FINE_ASSANCTION CHAR(1);
  CHARGE_LASTDAY char(1);
  OBLIG_ID number(27);
  NO_FINE char(1);
  NO_FINE_PERIOD char(1);
	NO_FINE_FOREVER char(1);  -- Флаг что (если 'Y') сумма обязательств накопленная в периоды "без начисления пени" (NO_FINE='Y') и в дальнейшем не участвуют в базе для пени.
 Cur_paysize number(27,2);
  AMovePeriod_ID number(27);
  itmp integer;
 PeriodSinceDate date;
 WasFinesOnDate boolean := false;           -- Флаг что в обязательстве встречалась (в любом из периодов!) пеня на день оплаты от ставки рефинансирования.
 NowOnDate boolean := false;
 mpMinDate date;
 MoveSetStart date := SM.GetMovesetSinceDate(AMoveSet_ID);
 AOld360 char(1);

ARecalc_Start_Date	date;
A_ADDCHARGE_NO_FINE_FOREVER char(1);
AFINE_BY_CHARGEDATE char(1) := 'N';

APercents_Instant char(1) := 'N';
ADistrDirect char(1) := 'N';
PrevPeriodPresets number(27) := null;  -- 30.01.2014 Morozova задаем предыдущие параметры настроек обязательства для периода
AMainPay varchar2(1);
APeriodFirstDay number(27) := null; -- 12.09.2014 Morozova первый день начисления для периода (не начала ОД)
AFineOnSt395 char(1) := 'N';  --- 22.12.2014 Morozova
ALastChargeDate date := sm.getmovesetenddate(AMoveSet_ID); ---27.12.2014 Morozova
PassedLastDay boolean := false;  ---27.12.2014 Morozova

  rPorog10 number (27,2);
  flagalgorithm char(1);
  percent integer;
  charge_sum_control number (27,2);
  FineSizeOld number(27,2);
  ACTION_TYPE_OLD varchar2(100);
Action_Date_old date;
BEGIN

 /* 18/11/2014 Твердохлеб: [50] По договору 14791: отдел аренды решил следовать методике "огранчивать пеню 10ю процентами" внедренной по заданию Н.Елатенцевой, попросили ее вернуть, как в 4.7.5.*/
  
 -- коэффициент льготы
 DISCOUNT:=1;

  CHARGE_FINE_METHOD:=0;
  CHARGE_METHOD:=0;
  CHARGE_SHOW_FDATE:='';
  FINE_KIND:='';

  begin
    select op.charge_fine_stopfines, op.charge_fine_assanction, op.charge_lastday, ob.id, op.NO_FINE_FOREVER, op.FINE_ON_LAST_DAY, ob.RECALC_START_DATE, op.ADDCHARGE_NO_FINE_FOREVER, op.percents_instant, op.distrdirect, FINE_BY_CHARGEDATE
    , op.period_first_day, op.OLD360 -- 12.09.2014 Morozova
    , op.fine_on_st395  -- 22.12.2014
    into CHARGE_FINE_STOPFINES, CHARGE_FINE_ASSANCTION, CHARGE_LASTDAY, OBLIG_ID, NO_FINE_FOREVER, A_FINE_ON_LAST_DAY, ARecalc_Start_Date, A_ADDCHARGE_NO_FINE_FOREVER, APercents_Instant, ADistrDirect, AFINE_BY_CHARGEDATE
    , APeriodFirstDay, AOld360 -- 12.09.2014 Morozova 
    , AFineOnSt395  -- 22.12.2014
    from sm.oblig_presets op, sm.obligations ob
    where op.id=ob.oblig_presets_id and
          ob.obligationtype_id=AObligType_ID and
          ob.moveset_id=AMoveSet_ID;
  exception
    when others then
      RETURN; -- не нашли параметров обязательства (например, если обязательство уже удалено)- не сможем рассчитать, поэтому выйдем
   end;

  cm:=''; --комментарий к строке "Долг"

  curPDID:=null;

--* Морозова

--*  if DelCharges='Y' then
------------------------------------------------------------
--*    delete from charges where Movesets_id=AMoveset_ID
--*                          and obligationtype_id=AObligType_ID
--*                          and CHARGE_TYPE = 'FINE'
--*                          and document_id is null;
------------------------------------------------------------
--*  end if;

---- 01.12.2011 -- Для профилактики подчищаем первые начисления по пене - не имеющие предыдущих обязательств (такое бывает напр. после удаления  начислений "по графику")
---- 19.03.2012 -- Добавлено: И пени начисленные ДО начала сделки.
 if DelCharges='Y' then
     -- Цикл - для сторнирования учетных данных
    for chCurr in
     (
				Select ch.ID from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and
																						 ( not exists (Select * from SM.CHARGES ch2 where ch2.Movesets_id=AMoveset_ID and ch2.obligationtype_id=AObligType_ID
																																						 and ch2.CHARGE_TYPE <> 'FINE'
																																						 and ch2.CHARGEDATE < ch.CHARGEDATE))  
																	 and ch.CHARGEDATE > ARecalc_Start_Date
                                   and ch.chargedate < G_CloseDate
                                   and ch.chargedate <> trunc(sysdate)  --- 24.01.2014 Morozova Не выбираем для старнирования начисление пени текущим днем
					union
					Select ch.ID from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and ( INSTR(ch.comments, '(на тек.м'  )  > 0 )
  --                                 and ch.CHARGEDATE > ARecalc_Start_Date  05.03.2014 Morozova -- при ночном пересчете не удалялась текущая пеня за прошлый день
                                   and ch.chargedate < G_CloseDate
                                   and ch.chargedate <> trunc(sysdate)   --- 24.01.2014 Morozova Не выбираем для старнирования начисление пени текущим днем
					union
					Select ch.ID from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and (ch.FINEDATE < (Select min(mp.SINCEDATE) from SM.MOVEPERIODS mp inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID=mp.ID
																																		where mp.MOVESET_ID = AMoveset_ID and ch.PAYDOC_ID = pd.ID and pd.obligationtype_id = AObligType_ID) )
 																	 and ch.CHARGEDATE > ARecalc_Start_Date 
                                   and ch.chargedate < G_CloseDate
                                   and ch.chargedate <> trunc(sysdate)    --- 24.01.2014 Morozova Не выбираем для старнирования начисление пени текущим днем
          union  --- 28.01.2014 Morozova добавляем блок сторнирования пени, если в параметрах указано не начислять пеню
          Select ch.ID from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
                                   and ch.document_id is null
                                   and ch.CHARGE_TYPE = 'FINE'
                                   and ch.chargedate < G_CloseDate
                                   and exists (Select * from SM.MOVEPERIODS mp inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID=mp.ID 
                                                                    where mp.MOVESET_ID = AMoveset_ID and ch.PAYDOC_ID = pd.ID and pd.obligationtype_id = AObligType_ID
                                                                           and pd.no_fine = 'Y') 
                                    and ch.CHARGEDATE > ARecalc_Start_Date
                                   and ch.chargedate <> trunc(sysdate)
     )
      loop
           OBLIG_ACC_PKG.StornoCharge(chCurr.ID);
      end loop;
       -- А затем - собственно удаление
 				Delete from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and
																						 ( not exists (Select * from SM.CHARGES ch2 where ch2.Movesets_id=AMoveset_ID and ch2.obligationtype_id=AObligType_ID
																																						 and ch2.CHARGE_TYPE <> 'FINE'
																																						 and ch2.CHARGEDATE < ch.CHARGEDATE))
  																 and ch.CHARGEDATE > ARecalc_Start_Date ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.                                 
                                   and ch.chargedate < trunc(sysdate); --- 24.01.2014   Morozova  удаляем начисления пени до текущей даты

					Delete from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and ( INSTR(ch.comments, '(на тек.м'  )  > 0);
 --                                 and ch.CHARGEDATE > ARecalc_Start_Date;  05.03.2014 Morozova -- при ночном пересчете не удалялась текущая пеня за прошлый день
   
					Delete from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and (ch.FINEDATE < (Select min(mp.SINCEDATE) from SM.MOVEPERIODS mp inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID=mp.ID
																																		where mp.MOVESET_ID = AMoveset_ID and ch.PAYDOC_ID = pd.ID and pd.obligationtype_id = AObligType_ID) )
																  and ch.CHARGEDATE > ARecalc_Start_Date ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.                                 
                                   and ch.chargedate < trunc(sysdate);  --- 24.01.2014   Morozova  удаляем начисления пени до текущей даты
          -----28.01.2014 Morozova  Удаляем начисление пени, если в обязательстве указано не начислять пеню
          Delete from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
                                   and ch.document_id is null
                                   and ch.CHARGE_TYPE = 'FINE'
                                   and ch.chargedate < G_CloseDate  --- 27.03.2014 Morozova
                                   and exists (Select * from SM.MOVEPERIODS mp inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID=mp.ID 
                                                                    where mp.MOVESET_ID = AMoveset_ID and ch.PAYDOC_ID = pd.ID and pd.obligationtype_id = AObligType_ID
                                                                           and pd.no_fine = 'Y') 
                                    and ch.CHARGEDATE > ARecalc_Start_Date
                                   and ch.chargedate < trunc(sysdate) ;
                                   
--- VVV -- 12.04.2013 ---- Удаление всех начислений по пене сделанных до текущей транзакции (после даты разрешенного пересчета [09.12.2013 и притом в открытом периоде])
    for chCurr in
     (
				Select ch.ID from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and ch.TRANSTIME <  SYSTIMESTAMP - 1/20000 
                                   and ch.chargedate < G_CloseDate -- 07.08.2014 Morozova исключаем сторнирование из открытого бух периода
--																	and ch.CHARGEDATE > to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy')  -- <<< 09.12.2013 и притом в открытом периоде - НЕТ! Противоречит "оперативности"
																	 and ch.CHARGEDATE > ARecalc_Start_Date                                   
                                   and ch.chargedate < trunc(sysdate)    --- 24.01.2014 Morozova Не выбираем для старнирования начисление пени текущим днем
	     )
      loop
           OBLIG_ACC_PKG.StornoCharge(chCurr.ID);
      end loop;
     -- А затем - собственно удаление
 			Delete from SM.CHARGES ch where ch.Movesets_id=AMoveset_ID  and ch.obligationtype_id=AObligType_ID
																	 and ch.document_id is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and ch.TRANSTIME <  SYSTIMESTAMP- 1/20000 --- 22.05.2014 Morozova  меньшен интервал с 1/2000 до 1/20000, иначе не удалялась пеня если один платеж изменялся в течении 1 мин
--																	and ch.CHARGEDATE > to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy')  -- <<< 09.12.2013 и притом в открытом периоде - НЕТ! Противоречит "оперативности"
																	 and ch.CHARGEDATE > ARecalc_Start_Date ;                                 
                    --               and ch.chargedate < trunc(sysdate);  --- 24.01.2014   Morozova  удаляем начисления пени до текущей даты
--- END подчистки------------------------------------
 end if;


  CALENDAR_TYPE:=365;
  Saldo:=0;
	--SaldoCharges := 0;
	SaldoChargesNoFine := 0;
	--SaldoPayments := 0;
  FinePercent:=0;
  CurRefinRate:=0;
  RefPart:=0;
  PrevMoment:=null;
  PrevMomentActionType:=null;
  FirstCharge := 'Y';
  FirstCharge_Period := 'Y'; -- задаем первое изменение начисления пени

  for Action IN (
  select
	    ID,   --- <<< 15.03.2012 <<< --- Добавлен для  качественного упорядочения событий, приходящихся на один день.
      ORD,
			ODR_DATE,
			ODR_DATE2,
      ACTION_DATE,
      ACTION_TYPE,    -- CHARGE, PAYMENT, NEW_PERIOD, CURR_MOMENT ...
      CHARGE_SUM,
      PAYMENT_SUM,
      FINEPERCENT,    -- пеня по периоду (как процент)
      REFINEPART,     -- пеня по периоду (как доля учётной ставки ЦБ)
      DISCOUNT_VALUE, -- величина льготы
      REFINRATE_VALUE,-- учётная ставка ЦБРФ
      CALENDAR_TYPE,  -- тип календаря (кол-во дней в году) для исчисления пени
      FINEONDEBT,     -- База для определения процента пени - от долга (умолч.'Y') / от суммы арендной платы ('N')
      FINE_KIND,      -- Способ исчисления пени: 'P'-процент (по умолчанию), 'R'-ставка рефинансирования, 'F'-фиксированная сумма
      FINEVALUEFIXED_DAILY, -- Фиксированная ставка пени за каждый день просрочки исполнения обязательств (Y) или штраф за факт просрочки (N)
      FINEVALUEFIXED, -- Фиксированная сумма пени
      PAYDOC_ID,      -- ссылка на условия обязательства
      KBK_ID,         -- ссылка на справочник Кодов бюджетной классификации
      period_presets,  -- ссылка на парметры расчета в периоде
      Cur_paysize,
      NO_FINE,
			PAYER_ID  -- Ссылка на плательщика - нужна на самом деле [пока] всего лишь для определения фиктивных (корректирующих) платежей.
    FROM
    (
    select
		  ch.ID,
      30 as ORD,  --3
--      case when ch.paysize >= 0 then NVL(ch.FINEDATE, ch.CHARGEDATE) else ch.chargedate  end as ODR_DATE,---06.06.2014 Morozova 
			NVL(ch.FINEDATE, ch.CHARGEDATE) as ODR_DATE,  -- <<< 13.04.2012 << -- при выборе момента начисления обязательства отличного от 7 (напр.2) - пеня по ставке рефинансирования могла теряться
			NVL(ch.CALPERIOD_END, ch.CHARGEDATE) as ODR_DATE2,
--      case when ch.paysize >= 0 then NVL(ch.FINEDATE, ch.CHARGEDATE) else ch.chargedate end as ACTION_DATE,  ---06.06.2014 Morozova добавлено условие позволяющее исключить начисление пени на отрицательное начисление
      NVL(ch.FINEDATE, ch.CHARGEDATE) as ACTION_DATE,
     'CHARGE'  as ACTION_TYPE,
      ch.PAYSIZE as CHARGE_SUM,
      TO_NUMBER(NULL) as PAYMENT_SUM,
      pd.FINEPERCENT as FINEPERCENT,
      pd.REFINRATEPART as REFINEPART,
      TO_NUMBER(NULL) as DISCOUNT_VALUE,
      TO_NUMBER(NULL) as REFINRATE_VALUE,
      pd.CALENDAR_TYPE_ID as CALENDAR_TYPE,
      pd.FINEONDEBT as FINEONDEBT,
      pd.FINE_KIND as FINE_KIND,
      pd.FINEVALUEFIXED_DAILY as FINEVALUEFIXED_DAILY,
       pd.FINEVALUEFIXED as FINEVALUEFIXED,
      pd.ID as PAYDOC_ID, --TO_NUMBER(NULL) as PAYDOC_ID,
      pd.FINE_CLS_KBK_ID as KBK_ID,
      pd.OBLIG_PERIODICAL_PRESETS_ID as period_presets,
      pd.PAYSIZE as Cur_paysize,   --- 06.06.2014 Morozova or ch.paysize < 0 Добавлено условие or ch.paysize > = 0  для исключения начисления пени на отрицательное начисление
     (Case when ch.FINEDATE is null then 'Y' else pd.no_fine end)  as NO_FINE, -- <<< 13.04.2013  --  -- Начисления  без пени - считаем что пеню не начислять (срабатывает для доп. начислений)
			(Case when ch.CHARGE_TYPE = 'OBLIGATION' then 1 when ch.CHARGE_TYPE = 'OTHER' then 2 when ch.CHARGE_TYPE = 'PERCENT' then 3 else 0 end) as PAYER_ID  -- <<< 19.04.2013 -- Значение задействовано налево!!! - для  'CHARGE'  определяет тип начисления
	 from
      sm.charges ch,
			SM.PAYDOCS pd
    where
		 pd.ID (+)= ch.PAYDOC_ID and
     ch.Movesets_ID=AMoveSet_ID and
     ch.obligationtype_id=AObligType_ID and
     ch.charge_type not in ('FINE','BOUND_START','BOUND_END') --and
--     ch.finedate is not null

    union all

    select
		  ID,
      40 as ORD,  --4
			sm.GetPayDateForPayment(p.Id)  as ODR_DATE,
			p.APPLY_DATE as ODR_DATE2,
      sm.GetPayDateForPayment(p.Id) as ACTION_DATE,
      'PAYMENT' as ACTION_TYPE,
      TO_NUMBER(NULL) as CHARGE_SUM,
      (p."SUM") as PAYMENT_SUM,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			PAYER_ID as PAYER_ID
    from
      sm.Payments p
    where
      Movesets_ID=AMoveSet_ID and
      obligationtype_id=AObligType_ID and
      MAINPAY<>'N' and
      paymethod_id<>3

    union all

    select
 		  ID,
     44 as ORD,  --4
			sm.GetPayDateForPayment(Payments.Id)  as ODR_DATE,
			APPLY_DATE as ODR_DATE2,
      sm.GetPayDateForPayment(Payments.Id) as ACTION_DATE, -- платёж - списание долга по основному обязательству
      'PAYMENT' as ACTION_TYPE,
      TO_NUMBER(NULL) as CHARGE_SUM,
      (payments."SUM") as PAYMENT_SUM,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			PAYER_ID as PAYER_ID
    from
      sm.Payments
    where
      Movesets_ID=AMoveSet_ID and
      obligationtype_id=AObligType_ID and
      MAINPAY<>'N' and
      paymethod_id=3

    union all

    select
		  ID,
      42 as ORD,  --4
			sm.GetPayDateForPayment(Payments.Id)  as ODR_DATE,
			APPLY_DATE as ODR_DATE2,
     sm.GetPayDateForPayment(Payments.Id) as ACTION_DATE, -- платёж - списание долга по пене (на сальдо не влияет)
      'PAYMENT_FINE' as ACTION_TYPE,
      TO_NUMBER(NULL) as CHARGE_SUM,
      (payments."SUM") as PAYMENT_SUM,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			PAYER_ID as PAYER_ID
    from
      sm.Payments
    where
      Movesets_ID=AMoveSet_ID and
      obligationtype_id=AObligType_ID and
      MAINPAY='N' and
      paymethod_id=3

    union all

    select
--		  pd.ID,
       mp.ID,
      1 as ORD,  --0
     decode(pd.KIND,'A',mp.SinceDate,'B',mp.SinceDate,'N',mp.SinceDate,'P', ADD_MONTHS(TRUNC(sm.charging_pkg.GetPeriodFirstDay(pd.periodical, mp.SinceDate),'MONTH'),-1)+pd.finedate-1) ODR_DATE,
			mp.SINCEDATE  as ODR_DATE2,
      decode(pd.KIND,'A',mp.SinceDate,'B',mp.SinceDate,'N',mp.SinceDate,'P', ADD_MONTHS(TRUNC(sm.charging_pkg.GetPeriodFirstDay(pd.periodical, mp.SinceDate),'MONTH'),-1)+pd.finedate-1) ACTION_DATE,
      'NEW_PERIOD' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      pd.FinePercent,
      pd.refinratepart as REFINEPART,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      pd.calendar_type_id as CALENDAR_TYPE,
      pd.FINEONDEBT as FINEONDEBT,
      pd.FINE_KIND as FINE_KIND,
      pd.FINEVALUEFIXED_DAILY as FINEVALUEFIXED_DAILY,
      pd.FINEVALUEFIXED as FINEVALUEFIXED,
      pd.id as PAYDOC_ID,
      pd.fine_cls_kbk_id as KBK_ID,
       pd.oblig_periodical_presets_id as period_presets,
      pd.paysize as Cur_paysize,
      pd.no_fine as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from
      sm.paydocs pd,
      sm.moveperiods mp
    where
      pd.moveperiod_id(+)=mp.id and
      mp.moveset_id=AMoveSet_ID and
      pd.obligationtype_id=AObligType_ID and
      Periodical <> 'N'

    union all

    select
		  mp.ID,
      0 as ORD,  --0
--			NVL(ch.CHARGEDATE,mp.SINCEDATE) as ODR_DATE,
--      NVL(ch.CHARGEDATE,mp.SINCEDATE) as ACTION_DATE,
			mp.SINCEDATE as ODR_DATE,
			NVL(ch.CALPERIOD_END, mp.SINCEDATE) as ODR_DATE2,
     mp.SINCEDATE as ACTION_DATE,
      'NEW_PERIOD' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      pd.FinePercent,
      pd.refinratepart as REFINEPART,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      pd.calendar_type_id as CALENDAR_TYPE,
      pd.FINEONDEBT as FINEONDEBT,
      pd.FINE_KIND as FINE_KIND,
      pd.FINEVALUEFIXED_DAILY as FINEVALUEFIXED_DAILY,
      pd.FINEVALUEFIXED as FINEVALUEFIXED,
      pd.id as PAYDOC_ID,
      pd.fine_cls_kbk_id as KBK_ID,
       pd.oblig_periodical_presets_id as period_presets,
      pd.paysize as Cur_paysize,
      pd.no_fine as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from
      sm.charges ch,
      sm.paydocs pd,
      sm.moveperiods mp
    where
      ch.paydoc_id=pd.id and
      pd.moveperiod_id(+)=mp.id and
      mp.moveset_id=AMoveSet_ID and
      pd.obligationtype_id=AObligType_ID and
      Periodical = 'N'
			AND  CH.CHARGE_TYPE  not in ('FINE','BOUND_START','BOUND_END') -- <<< 13.04.2012 <<<--

    union all

    select
      0 as ID,
			60 as ORD, --6
      trunc(sysdate) as ODR_DATE,
 			to_date('01.01.1917','dd.MM.yyyy')  as ODR_DATE2,
      trunc(sysdate) as ACTION_DATE,
      'CURR_MOMENT' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from dual

    union all

    select
      0 as ID,
     50 as ORD, --5
      Getmovesetenddate(AMoveSet_ID) as ODR_DATE,
 			to_date('01.01.1917','dd.MM.yyyy')  as ODR_DATE2,
      Getmovesetenddate(AMoveSet_ID) as ACTION_DATE,
      'LASTDAY' as ACTION_TYPE,
      (Select max(PAYSIZE) from SM.CHARGES ch where ch.MOVESETS_ID = AMoveSet_ID and ch.OBLIGATIONTYPE_ID = AObligType_ID
			                              and ch.CHARGE_TYPE = 'OBLIGATION' and ch.CHARGEDATE = Getmovesetenddate(AMoveSet_ID)) as CHARGE_SUM,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from dual

    union all

    select
      ds.ID,
      20 as ORD, --2
      ds.sincedate as ODR_DATE,
  		to_date('01.01.1917','dd.MM.yyyy')  as ODR_DATE2,
     ds.sincedate as ACTION_DATE,
      'DSCNT_START' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      ds.discount_value as DISCOUNT_VALUE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from
      sm.discounts ds
    where
      ds.moveset_id=AMoveSet_ID and
      ds.obligationtype_id=AObligType_ID and
      ds.Discharge_Type='FINE'

    union all

    select
      ds.ID,
      70 as ORD, --7
      nvl(ds.enddate+1,to_date('01.01.3000','dd.MM.yyyy')) as ODR_DATE,
 			to_date('01.01.1917', 'dd.mm.yyyy')  as ODR_DATE2,
      nvl(ds.enddate+1,to_date('01.01.3000','dd.MM.yyyy')) as ACTION_DATE,
      'DSCNT_STOP' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      ds.discount_value as DISCOUNT_VALUE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from
      sm.discounts ds
    where
      ds.moveset_id=AMoveset_id and
      ds.obligationtype_id=AObligType_ID and
      ds.Discharge_Type='FINE' and
      ds.enddate is not null

    union all

    select
      0 as ID,
      10 as ORD, --1
      rt.apply_date as ODR_DATE,
  		to_date('01.01.1917','dd.MM.yyyy')  as ODR_DATE2,
     rt.apply_date as ACTION_DATE,
      'NEW_REFINRATE' as ACTION_TYPE,
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      TO_NUMBER(NULL),
      rt.refrate as REFINRATE_VALUE,
      TO_NUMBER(NULL) as CALENDAR_TYPE,
      '' as FINEONDEBT,
      '' as FINE_KIND,
      '' as FINEVALUEFIXED_DAILY,
      TO_NUMBER(NULL) as FINEVALUEFIXED,
      TO_NUMBER(NULL) as PAYDOC_ID,
      TO_NUMBER(NULL) as KBK_ID,
      TO_NUMBER(NULL) as period_presets,
      TO_NUMBER(NULL) as Cur_paysize,
      '' as NO_FINE,
			TO_NUMBER(NULL) as PAYER_ID
    from
      sm.refinrates rt
      where rt.apply_date >= MoveSetStart  --  ((Select min(mp.sincedate) from SM.MOVEPERIODS mp where mp.moveset_id = AMoveset_id))
   ) x
  order by x.ODR_DATE, x.ORD, ODR_DATE2 desc, x.ID
 ) loop

 FineSize := 0;		-- <<< 14.01.2013 -- Иначе случалось, что прежнее значение ошибочно использовалось повторно при пене "не от долга" когда пени не должно было быть.
 if (Action.Action_Date = '27.02.2013') then
   FineSize := 0;
 end if;
 Action_Date_old :=Action.Action_Date;
   
	 -- Начисления до начала периода (часто - начальное сальдо) -  считаем что пеню нада.
	 -- Хотя, в этом варианте есть дефект - вдруг начальное сальдо доп.начислением ДО начала ОД, а пеню на первый период не начислять?
	 -- Но, в общем, не надо начислять ДО начала первого периода операции движения. Первым днем - правильно. Т.е. неправильный вариант - на неправильный вариант...
	if NO_FINE is null
		OR (Action.ACTION_TYPE = 'CHARGE' -- <<< 10.01.2012 -- Выбираем  условия по периоду, к которому относится начисление, а не по периоду. куда оно попадает хронологически
    		   and Action.Charge_Sum >= 0) ---05.06.2014 Morozova на отрицательное начисление пеня не начисляется
		then       -- PrevMoment is null and Action.ACTION_TYPE='CHARGE' then
	------				NO_FINE := 'N';
                NO_FINE := NVL(Action.NO_FINE, 'N');
	else
			NO_FINE :=  NO_FINE_PERIOD;				-- <<< 12.04.2013 <<< Чтобы отдельные начисления попадающие не в свой период не портили погоду...
	end if;

--- VVV 14.12.2012 --Не делаем начислений до даты начала пересчета. Делаем только после нее------
if Action.ACTION_DATE <= ARecalc_Start_Date then   
		GOTO	CHARGESS_PASS_END;
end if;
--- ^^^ ------------------------------------------------------------------------------------------------------------------------------------

----------------  (4.7.1) Для начислений Какое бы событие там ни было - определяем начало текущего периода,
----- и если в периоде опрелено обязательство, дату начала подкорректируем под нее ------------------------
--------------  Заодно добываем ID текущего периода - оно нада в блоке ниже ------------------------
           Select count(*) into itmp from SM.MOVEPERIODS mp where mp.MOVESET_ID = AMoveSet_ID 
					         and ((mp.SINCEDATE <= Action.ACTION_DATE and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > Action.ACTION_DATE) --- 27.03.2014 Morozova 
									 OR (mp.SINCEDATE =  Action.ACTION_DATE and nvl(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = Action.ACTION_DATE)) ;     -- <<< 21.10.2013 -- Добавлена обработка периода начинающегося и заканчивающегося в один день.
           if itmp = 1 then
                      Select ID, SINCEDATE into AMovePeriod_ID, PeriodSinceDate from SM.MOVEPERIODS mp where mp.MOVESET_ID = AMoveSet_ID  
											        and ((mp.SINCEDATE <= Action.ACTION_DATE and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > Action.ACTION_DATE)
									            OR (mp.SINCEDATE =  Action.ACTION_DATE and nvl(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = Action.ACTION_DATE));
                      -- Проверяем определено ли в периоде обязательство
                     Select count(*) into itmp  from SM.PAYDOCS pd inner join SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID  where  mp.ID = AMovePeriod_ID;
                      if PrevMoment < PeriodSinceDate
                                    and itmp > 0
                                    and ((CHARGE_FINE_ASSANCTION='Y' or (CHARGE_FINE_STOPFINES='N'   and Action.ACTION_TYPE = 'LASTDAY'  ))  and FINE_KIND = 'R' )
                      then
                                 PrevMoment := PeriodSinceDate;
                      end if;
           elsif  itmp > 1 then
                                  Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
                                  values (sysdate, 'Проверьте даты периодов - похоже есть наложения в ОД ' || to_char(AMoveSet_ID) || ' на ' || to_char(Action.ACTION_DATE,'DD.MM.YYYY'), 'Ora FULLRECALC_PKG.FullRecalcFines', 'SM', 2, 2, 1, AMovePeriod_ID, 5, 'N');
                                  GOTO   NEXT_ACTION;

           elsif  itmp = 0 and (CHARGE_FINE_STOPFINES='Y' and AFineOnSt395 = 'N') then --- 29.12.2014 Morozova  ничего не делаем для стандартных условий начисления пени
--           elsif  itmp = 0 and CHARGE_FINE_STOPFINES='Y' then
                          null; --GOTO   NEXT_ACTION;
					 elsif  itmp = 0 and CHARGE_FINE_STOPFINES='N' then -- Для событий после закрытого договора - выбираем последний период.
					        Select min(mp.SINCEDATE) into mpMinDate from SM.MOVEPERIODS mp where mp.MOVESET_ID = AMoveSet_ID;
									if 	 mpMinDate > Action.ACTION_DATE then
									      Select ID, SINCEDATE into AMovePeriod_ID, PeriodSinceDate from SM.MOVEPERIODS mp where mp.ID = (Select min(mp2.ID) from SM.MOVEPERIODS mp2  where mp2.MOVESET_ID = AMoveSet_ID and mp2.SINCEDATE = (Select min(mp3.SINCEDATE) from SM.MOVEPERIODS mp3 where mp3.MOVESET_ID = AMoveSet_ID)) ;
					        else
									     Select ID, SINCEDATE into AMovePeriod_ID, PeriodSinceDate from SM.MOVEPERIODS mp where mp.ID = (Select max(mp2.ID) from SM.MOVEPERIODS mp2  where mp2.MOVESET_ID = AMoveSet_ID and mp2.SINCEDATE = (Select max(mp3.SINCEDATE) from SM.MOVEPERIODS mp3 where mp3.MOVESET_ID = AMoveSet_ID)) ;
									end if;
									-- Проверяем определено ли в периоде обязательство
								 Select count(*) into itmp  from SM.PAYDOCS pd inner join SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID  where  mp.ID = AMovePeriod_ID;
                      if PrevMoment < PeriodSinceDate
                                    and itmp > 0
                                    and ((CHARGE_FINE_ASSANCTION='Y' or (CHARGE_FINE_STOPFINES='N'   and Action.ACTION_TYPE = 'LASTDAY'  ))  and FINE_KIND = 'R' )
                      then
                                 PrevMoment := PeriodSinceDate;
                      end if;
           end if;
 ---------------------------------- ВЕТКА В РАСПРЕДЕЛЕНИЕ ПЛАТЕЖЕЙ ------------------------------------------------------------
	-- VVV 03.10.2012 Подчистка начислений, которые могут остаться от прежних расчетов при смене "политики" настройками
  --- 30.01.2014 Morozova  добавлено условие смены параметров начисления обязательств в периодах PrevPeriodPresets <> Action.Period_Presets
          if  ((CHARGE_FINE_ASSANCTION='Y' or  PrevPeriodPresets <> Action.Period_Presets or CALENDAR_TYPE <> Action.Calendar_Type)
                 and Action.ACTION_TYPE='NEW_PERIOD' ) then
	               Delete from SM.CHARGES ch where ch.MOVESETS_ID=AMoveset_ID and ch.OBLIGATIONTYPE_ID=AObligType_ID
																	 and ch.DOCUMENT_ID is null
																	 and ch.CHARGE_TYPE = 'FINE'
																	 and ch.CHARGEDATE >= Action.ACTION_DATE
																	 and  ch.COMMENTS not like '%на день платежа%'
										 							 AND  ch.chargedate > ARecalc_Start_Date;     ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
                 ----- 30.01.2014  Morozova  чистим начисления пени, которые могли остаться по несуществующему платежу
                 Delete from SM.CHARGES ch where ch.MOVESETS_ID=AMoveset_ID and ch.OBLIGATIONTYPE_ID=AObligType_ID
                                   and ch.DOCUMENT_ID is null
                                   and ch.CHARGE_TYPE = 'FINE'
                                   and ch.CHARGEDATE >= Action.ACTION_DATE
                                   and  ch.COMMENTS  like '%на день платежа%'
                                   and ch.chargedate not in 
                                           (select pm.apply_date from sm.payments pm
                                            where pm.paydoc_id = ch.paydoc_id  
                                                and pm.movesets_id = ch.movesets_id
                                                and pm.obligationtype_id = ch.obligationtype_id)
                                    AND  ch.chargedate > ARecalc_Start_Date;	--- VVV 19.10.2012 -- Заодно уточняем сальдо, иначе - при чередовании периодов с разным принципом начисления пени, и условием- на день оплаты - не учитывались перплаты на этот момент).
--	       if Saldo = 0 then
--					     Saldo := SM.CalcFine(Action.ACTION_DATE-1, AMoveset_ID, AObligType_ID, 'PAY');
--				end if;
  end if;
  PrevPeriodPresets := Action.Period_Presets;   --- 30.01.2014 Morozova
 -- Если начисление по ставке рефинансировыания НА ДЕНЬ ОПЛАТЫ - то [пере]расчет пени производить _распределением платежей!
  if  (CHARGE_FINE_ASSANCTION='Y'  and ((Action.ACTION_TYPE= 'CHARGE' and Action.Fine_Kind = 'R') OR (Action.ACTION_TYPE not in ( 'CHARGE','CURR_MOMENT', 'NEW_REFINRATE')  and FINE_KIND = 'R')))  then
--  if  (CHARGE_FINE_ASSANCTION='Y'  and FINE_KIND = 'R')  then
         -- ЗДЕСЬ ВЫЗОВ ПРОЦЕДУРЫ ПЕРЕРАСПРЕДЕЛЕНИЯ ПЛАТЕЖЕЙ
				 if (Action.ACTION_TYPE='NEW_PERIOD' OR Action.ACTION_TYPE='PAYMENT' OR Action.ACTION_TYPE='LASTDAY') then  -- <<< 02.10.2012 <<
                 sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(AMovePeriod_ID, AObligType_ID, 'Y');
				 end if;
         -- НАЧИСЛЕНИЕ ПРОЦЕНТОВ И ПЕНИ НА СЕГОДНЯ (Флаг, начисление - вне цикла в конце функции)
         WasFinesOnDate := true;
				 NowOnDate := true;  -- Флаг используется позже -  что эта сумма относится к периоду ждущему оплаты, и не участвует в текущем начислении пени.

         GOTO   NEXT_ACTION; --END_OF_LOOP;
  end if;
	NowOnDate := false;
    --- блок статьи 395 ГК РФ ---30.12.2014 Morozova              
  if AFineOnSt395 = 'Y' and Action.ACTION_TYPE in ('CURR_MOMENT', 'PAYMENT', 'CHARGE') 
    and Action.Action_Date > ALastChargeDate and PassedLastDay = true then
      if Action.Action_Type = 'CHARGE' and Action.Payer_Id = 1 then  --- если последнее автоматическое начисление выходит за пределы договора 
        goto NEXT_ACTION;
      end if;            
      FinePart := 360;
      -- находим ставку рефинансирования, действующую на дату 
      select rt.refrate into FINEVALUEFIXED
      from  sm.refinrates rt
      where rt.apply_date = (Select max(rt2.apply_date) from SM.refinrates rt2 where rt2.apply_date < Action.Action_Date-1);
      FinePercent := FINEVALUEFIXED;
      FINE_KIND := 'R';
      CALENDAR_TYPE := 360;
      RefPart := 360;  
  end if;
 ------ (/4.7.1)------------------------------------------------------------------------------------------------------------------------------------------

 if (Saldo <= 0) and (PrevMoment is not null) then --- <<< 05.03.2012 <<< Добавлено равенство

    ---- VVV 21.10.2014 MAV Перенесено вперед ради более раннего опрелеления Expl_Date, которое теперь используется при расчете периода для "360/30" 
     Expl_Date:=Action.ACTION_DATE-1;
     if (CHARGE_FINE_METHOD=1 and (Action.ACTION_TYPE='PAYMENT' OR Action.ACTION_TYPE='PAYMENT_FINE')) OR
        (CHARGE_FINE_METHOD=1 and Action.ACTION_TYPE='CURR_MOMENT') OR
        (CHARGE_FINE_METHOD=1 and Action.ACTION_TYPE='LASTDAY')
        OR ( CHARGE_FINE_METHOD=2 and Action.ACTION_TYPE='LASTDAY')--- <<<< 10.02.2012 <<< 
        then
       Expl_Date:=Action.ACTION_DATE;
     end if;

		 if CALENDAR_TYPE = 365 then --задержка из расчета 365(/366) дней в году
     			-- <<< 23.03.2012 <<< -- Проверяем, и если период начисления попадает в  високосный и невисокосный год - делим его на 2 и вычисляем по отдельности.
					-- ^^^^^ НЕ НАДА!!! -- Нет периодов начислений переходящих через год! (Но остался вариант с разделением - сохранен на сервере)
						PayDelay:=trunc(Action.ACTION_DATE)-trunc(PrevMoment);
						if SM.IsLeapDate(Action.ACTION_DATE) then
									DaysInYear := 366;
						else
									DaysInYear := 365;
						end if;
     elsif CALENDAR_TYPE = 360 then --задержка из расчета 360 дней в году
				   DaysInYear := 360;
           if (AOld360 = 'Y') then -- <<< 21.10.2014 MAV
               if trunc(Action.ACTION_DATE,'MONTH')=trunc(PrevMoment,'MONTH') then
                      -- если расчет пени идет в пределах месяца, то просто разницу дней, но максимум 30
                       PayDelay:=LEAST(30, trunc(Action.ACTION_DATE)-trunc(PrevMoment));
               else

    ---------------------------- ПРЕЖНИЙ ВАРИАНТ (одна из нескольких методик реализации способа 360/30) ------------------------------------
                  -- при переходе через границу месяца
                       -- дней в первом месяце
                      p1:=PrevMoment-trunc(PrevMoment,'MONTH')+1;
                      if p1=1 then
                          p1:=30;
                      else
                          p1:=Last_Day(PrevMoment)-PrevMoment+1;
                      end if;

                       -- дней в последнем месяце
                      if Action.ACTION_DATE=Last_Day(Action.ACTION_DATE) then
                         p2:=30;
                      else
                         p2:=Action.ACTION_DATE-trunc(Action.ACTION_DATE,'MONTH');
                      end if;

     ------------------- 19.06.2012  ПОПЫТКА СЧИТАТЬ НЕПОЛНЫЕ МЕСЯЦЫ ПРОПОРЦИОНАЛЬНО 30/месяц -----------------------------------------------------------
     --------------  (ни одной общепринятой методикой не описан, но наиболее логичен. (Получилось хорошо!!! но - не по методикам...)) ------------
                    -- при переходе через границу месяца
                       -- дней в первом месяце
    --									p1 := ROUND((Last_Day(PrevMoment)-PrevMoment+1)  * (30 / to_number(initcap(to_char(Last_Day(PrevMoment),'DD')))));
                       -- дней в последнем месяце
    --								   p2 := ROUND((Action.ACTION_DATE- trunc(Action.ACTION_DATE,'MONTH')) *  (30 / to_number(initcap(to_char(Last_Day(Action.ACTION_DATE),'DD')))));
    ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

                       -- кол-во месяцев между первым и последним месяцами
                      p3 := 30 * (MONTHS_BETWEEN(trunc(Action.ACTION_DATE,'MONTH'), trunc(PrevMoment, 'MONTH')) - 1);
                      PayDelay:= p1+p2+p3;
                    end if;  
                  else
                     -- Old360 == false <<< 21.10.2014 MAV
                     
                    PayDelay :=/* 1 + */ --- 01.04.2015 Morozova  учитываем ниже в подсчете дней в первом месяце
                      (EXTRACT(YEAR FROM Expl_Date)- EXTRACT(YEAR FROM PrevMoment))*360 + 
                      (EXTRACT(MONTH FROM Expl_Date)-EXTRACT(MONTH FROM PrevMoment) - 1)*30;   --- 01.04.2015 Morozova -1 полный месяц, для дальнейшего подсчета дней в начале и конце                                            
                     --- 01.04.2015 Morozova Считаем дни в первом месяце в начале периода ... расчет аналогичен расчету на сайте http://www.arbitr.ru/vas/calc395/
                     if (EXTRACT(DAY FROM last_day(PrevMoment)) = EXTRACT(DAY FROM PrevMoment)
                           and EXTRACT(DAY FROM PrevMoment) > 30) then
                       p1 := 0;                     
                     else
                       p1 := 30 - EXTRACT(DAY FROM PrevMoment) + 1;                       
                     end if;   
                     
                     --- 01.04.2015 Morozova Считаем дни в последнем месяце месяце 
                     if CHARGE_FINE_METHOD = 1 and (Action.ACTION_TYPE='PAYMENT' OR Action.ACTION_TYPE= 'PAYMENT_FINE')
                       or (CHARGE_FINE_METHOD=1 and (Action.ACTION_TYPE='CURR_MOMENT' or Action.ACTION_TYPE='LASTDAY' ))
                       OR (CHARGE_FINE_METHOD=2 and Action.ACTION_TYPE='LASTDAY' and A_FINE_ON_LAST_DAY = 'Y' )
                        then
                       p2 := EXTRACT(DAY FROM Expl_Date) - 1;    --- компенсируется ниже                  
                     else
                       p2 := EXTRACT(DAY FROM Expl_Date) ;
                     end if;           
                     PayDelay := PayDelay + p1 + p2;    
                  end if; -- end if Old360  
   else
          RAISE_APPLICATION_ERROR(-20101, 'Неизвестный тип календаря CALENDAR_TYPE='||CALENDAR_TYPE);
   end if;


   -- Если пеню начислять и на день оплаты, то - период начисления пени должен сдвигаться на день вперед (окончание)
   -- а начало - только если за день начала начисления пени не начислялась пеня же по прежним основаниям...
   if (CHARGE_FINE_METHOD=1 and (Action.ACTION_TYPE='PAYMENT' OR Action.ACTION_TYPE= 'PAYMENT_FINE'))  then
     if PrevMomentActionType is not null and PrevMomentActionType='PAYMENT' and Action.ACTION_DATE=(PrevMoment-1) then
       PayDelay:=0;
     else
       PayDelay:=PayDelay+1;
     end if;
   elsif  CHARGE_FINE_METHOD=1 and (Action.ACTION_TYPE='CURR_MOMENT' or Action.ACTION_TYPE='LASTDAY')
          OR (CHARGE_FINE_METHOD=2 and Action.ACTION_TYPE='LASTDAY' and A_FINE_ON_LAST_DAY = 'Y' )   -- <<< 10.02.2012 <<< -- День конца начислений - начислять пеню <<< 21.02.2012 <<< - Если флаг
			    then
     PayDelay:=PayDelay+1;
   end if;


   -- игнорируем изменение учётной ставки, если используется фиксированный процент или сумма пени
   if (Action.ACTION_TYPE = 'NEW_REFINRATE' and FINE_KIND != 'R' ) or (CHARGE_FINE_ASSANCTION = 'Y' and  FINE_KIND = 'R') then
        GOTO NEXT_ACTION;
   end if;

   -- игнорируем события, которые не приводят к начислению пени при фиrсированной ставке пени - штаф за факт просрочки
  if (FINE_KIND='F' and FINEVALUEFIXED_DAILY='N') then
     GOTO NEXT_ACTION;
  end if;


-- если ставка рефинансирования меняется, и пеня на неполный день (т.е. на день начисления тоже) - то ставку брать вчерашнюю
-- (т.к. на день начисления она уже другая, и прошлая задолженность будет "оштрафована" по новой ставке!). НЕ ПРОВЕРЕНО - ПОТОМУ ОТКЛЮЧЕНО
 if Action.ACTION_TYPE='NEW_REFINRATE'  and  CHARGE_FINE_METHOD = 1
	 and Action.Fine_Kind = 'R'  -- <<< 05.07.2013 -- Иначе ставка рефинансирования в ряде случаев использовалась как фикс. процент
	 then
          select
           rt.refrate as REFINRATE_VALUE into FinePercent
          from  sm.refinrates rt
           where rt.apply_date = (Select max(rt2.apply_date) from SM.refinrates rt2 where rt2.apply_date < Action.Action_Date-1);
elsif (nvl(Action.FinePercent,0) > 0) -- <<< 11.07.2013 -- Добавлено условие на is not null, а то пеня переставала начисляться.
AND Action.ACTION_TYPE<> 'NEW_PERIOD' -- <<< 24.07.2013 - Иначе расчет "хвоста" перед началом нового периода шел по новой ставке
AND PayDelay > 0 -- <<< 24.07.2013 - Чтобы не влияли неначисляемые события (когда в один день начисления по разным условиям, и начисляется сначала по последним)
and AFINE_BY_CHARGEDATE = 'Y'    --- 24.09.2014 Morozova изменяем величину процента, если считать пеню по условиям периода За которое начисление
then 
			 FinePercent := Action.FinePercent;			   -- <<< 05.07.2013 -- Иначе ставка рефинансирования в ряде случаев использовалась как фикс. процент
 end if;

-- VVV 06.11.2012 -- Вместо FINE_KIND (фиксируемого для текущего периода) стало использоваться текущее значение для данного начисления
-- - на случай когда по времени начисления попадали "не в свой" период - чтобы условия для них выполнялись по "их" периоду

   -- определяем РАЗМЕР пени в зависимости от вида пени
   if  ((Action.ACTION_TYPE= 'CHARGE' and Action.Fine_Kind = 'P'  and AFINE_BY_CHARGEDATE='Y') 
		 OR (Action.ACTION_TYPE<> 'CHARGE' and FINE_KIND = 'P')
		 OR (Action.ACTION_TYPE= 'CHARGE' and Action.Fine_Kind  is null and FINE_KIND = 'P')  -- <<< 29.01.2013 -- без этого не начислялись пени при доп.начислениях
		 OR (Action.ACTION_TYPE= 'CHARGE' and  AFINE_BY_CHARGEDATE='N'  and FINE_KIND = 'P'))  -- <<< 09.07.2013 -- если по текущим условиям - то определяем по FINE_KIND 
		 then -- процент
							FinePart:=FinePercent/100; 
							if fineondebt='Y' then
												FineExpl:=PayDelay || 'д*(' || to_char(FinePart,'FM990.9999999')|| ')*' || - Saldo || 'руб';
												FineSize:=-Saldo * PayDelay * FinePart; -- размер пени
							else
								     if (MoveSetStart <> PrevMoment)    and Saldo <> 0  then -- <<< 06.12.2012 Давлено Saldo <> 0 - как предохранитель хоть размер и не от Saldo, но это признак обоснованности начисления пени.
												FineExpl:=PayDelay || 'д*(' || to_char(FinePart,'FM990.9999999')|| ')*' || Cur_paysize  || 'руб';
												FineSize:=Cur_paysize * PayDelay * FinePart; -- размер пени
											end if;
							end if;
              FineSizeOld := FineSize;       
   elsif ((Action.ACTION_TYPE= 'CHARGE' and Action.Fine_Kind = 'R' and AFINE_BY_CHARGEDATE='Y') 
	   OR (Action.ACTION_TYPE<> 'CHARGE' and FINE_KIND = 'R')
		 OR (Action.ACTION_TYPE= 'CHARGE' and Action.Fine_Kind  is null and FINE_KIND = 'R')  -- <<< 29.01.2013 -- без этого не начислялись пени при доп.начислениях
		 OR (Action.ACTION_TYPE= 'CHARGE' and   AFINE_BY_CHARGEDATE='N'  and FINE_KIND = 'R'))  -- <<< 09.07.2013 -- если по текущим условиям - то определяем по FINE_KIND 
		 then  -- ставка рефинансирования

			  --- <<< 23.03.2012 <<< --- Правильно применяем дневную долю  процента для високосного года и способа расчета (360/точно)
        -- Здесь мы берем на себя наглость определить, являлось ли значение введенное пользователем в поле
				--  "доля ставки рефинансирования" - приведением годовой ставки на один день
				--      (что теперь будет отрабатываться автоматом - введенное значение игнорируем),
				-- ИЛИ Это действительно дополнительный мультиплексор!!! (как правило он должен быть не большим, например - 1/3 ставки)
				--      (тогда он будет применен дополнительно к автоматически определяемой дневной ставке).
				-- ИЛИ Это дневной процент уже совмещенный с мультиплексором
				--     (тогда он будет применен прямо...)
	--- 			TODO: Закончить это место при необходимости разбив на 2 периода если PayDelay_2 <> 0  <<< НЕ НАДА!!! (Нет периодов начисления ПЕРЕХОДЯЩИХ через год!)
if RefPart = 0 then
	 RefPart := nvl(Action.REFINEPART, RefPart);
end if;
				if (RefPart >= 365 and RefPart <= 366) then -- Указано число дней в году - игнорируем
						 Multi := 1;
				elsif (RefPart > 10)	then 	-- Если указали явно не мультиплексор, но и не число дней в году - значит имели в виду уже посчитанное значение с [предполагаемым] мультиплексоро
           --- 24.09.2014 Morozova берем долю ставки, если указано что пеня по условия периода ЗА которое начисление	
					 if Action.ACTION_TYPE= 'CHARGE' and AFINE_BY_CHARGEDATE='Y' and Action.Fine_Kind = 'R' and Action.REFINEPART is not null then
               DaysInYear := Action.REFINEPART;
             else
               DaysInYear := RefPart;  -- оперируем DaysInYear т.к. проще формировать комментарий...
             end if;
					
--						 DaysInYear := RefPart;  -- оперируем DaysInYear т.к. проще формировать комментарий... ---24.09.2014 Morozova
						 Multi := 1;
				else
						-- Multi := nvl(Action.REFINEPART, RefPart);  -- RefPart;RefPart;
            	 Multi := RefPart;   --- 05.02.2014 Morozova вернула с версии 4.7.5,  чтоб не проподала пеня до конца месяца старого периода
				end if;

			--- И собственно определение процента от ставки:
      -- Профилактика отсутствия ставки рефинансирования (до первого факта ее изменения по ходу расчетов)
			if (CurRefinRate is null OR CurRefinRate=0)  and Action.ACTION_DATE is not null then
				    begin
            					  Select r.REFRATE into CurRefinRate from SM.REFINRATES r where r.APPLY_DATE = (Select max(rr.APPLY_DATE) from SM.REFINRATES rr where rr.APPLY_DATE < Action.ACTION_DATE);
						exception
                      when NO_DATA_FOUND then
												    RAISE_APPLICATION_ERROR(-20101, 'На дату ['|| TO_CHAR(Action.ACTION_DATE, 'dd.MM.yyyy') || '] отсутствует значение стаки рефинансирования. ');
						end;
			end if;
     
      if (DaysInYear<> 0 and Multi<>0) then   -- <<< 11.07.2013 -- Иначе после других предшествующих изменений получали деление на 0
      		  FinePart := CurRefinRate/(DaysInYear * Multi * 100);
      else
      			FinePart := 0;	
      end if;			
			
			-- И далее- размера пени.
      if fineondebt='Y' and RefPart <> 0 then
							if Multi <> 1 then
										FineExpl:=PayDelay || 'д*('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')*' || - Saldo  || 'руб';
							else
										FineExpl:=PayDelay || 'д*('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')*' || - Saldo  || 'руб';
							end if;
						 FineSize:=-Saldo*PayDelay * FinePart; -- размер пени
       elsif RefPart <> 0   and ( MoveSetStart <> PrevMoment)     and Saldo <> 0  then -- <<< 06.12.2012 Давлено Saldo <> 0 - как предохранитель хоть размер и не от Saldo, но это признак обоснованности начисления пени.
							if Multi <> 1 then
										FineExpl:=PayDelay || 'д*('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')*' || Cur_paysize  || 'руб';
							else
										FineExpl:=PayDelay || 'д*('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')*' || Cur_paysize  || 'руб';
							end if;
						 FineSize:=PayDelay*Cur_paysize*FinePart; -- размер пени
       end if;
       
        -- Твердохлеб 02/01/2014
        -- если пеня получается по значению больше чем 10% от ежемесячной арендной платы,
        -- то тогда Пеня = 10 % от ежемес.арендной платы.
        -- получим период в который попадпет пеня
        -- только для аренды
        FineSizeOld := FineSize;
        if (AObligType_ID = 81 and FineSize > 0) then 
            flagalgorithm := NULL;
            percent := NULL;
            begin
              select mp.flagalgorithm,
                     mp.percent
                into flagalgorithm,
                     percent
                from sm.moveperiods mp
                join sm.movesets ms on ms.id = mp.moveset_id
               where mp.moveset_id = AMoveSet_ID
                 and mp.sincedate <= Action.ACTION_DATE
                 and (mp.enddate >= Action.ACTION_DATE or mp.enddate is null);
              exception
              when no_data_found then null;
            end;
            if percent = 0 or percent is null then
               percent := 10;
            end if; 
            -- если стоит отметка ограничивать 10-ю процентами
            charge_sum_control := NULL;
            if (flagalgorithm = 'Y') then
              -- контрольное начисление в месяц за аренду
              charge_sum_control := Action.CHARGE_SUM;
              if (charge_sum_control is not null) then
                 select c.paysize
                   into charge_sum_control
                   from sm.charges c
                  where c.movesets_id = AMoveSet_ID
                    and c.obligationtype_id = AObligType_ID
                    and c.calperiod_start <= (PrevMoment)
                    and c.calperiod_end >= (PrevMoment)
                    and c.charge_type = 'OBLIGATION'
                    and rownum < 2;       
              end if; 
              --если новый период, то это разрыв и следовательно найдем сколько было начисленно за этот период
              --либо после разрыва возьмем только не учтенное начисление
              if (((Action.ACTION_TYPE = 'NEW_PERIOD' or Action.ACTION_TYPE = 'NEW_REFINRATE'))
                   or
                   (ACTION_TYPE_OLD = 'NEW_PERIOD' or ACTION_TYPE_OLD = 'NEW_REFINRATE')
              ) then
                --запоминаем, если делали разрыв то в последующем при расчет пени не учитывать уже учтенное начисление
                ACTION_TYPE_OLD := Action.ACTION_TYPE;
                --если не разры а после, то обнуляем старое значение чтобы не сработало еще раз
                if (Action.ACTION_TYPE <> 'NEW_PERIOD' and Action.ACTION_TYPE <> 'NEW_REFINRATE') then
                  ACTION_TYPE_OLD := NULL;
                end if;
              end if; 
              if (charge_sum_control is not null
                  and charge_sum_control <> 0
                  and Saldo <> 0) then
                  rPorog10 := charge_sum_control * percent / 100;
                  if (FineSize > rPorog10) then
                      FineSize := rPorog10;
                     -- raise_application_error(-20101,TO_CHAR(Action.Action_Date) || ' ' || TO_CHAR(FineSize));
                  end if;
              end if;                                                    
            end if;                           
        end if;               
   elsif Saldo <> 0 then -- фиксированная сумма пени  ---23.03.2015 Morozova  на нулевую сумму пеня не начисляется
				if FINEVALUEFIXED_DAILY='Y' then --фиксированная сумма за каждый день просрочки
						 FinePart:=FINEVALUEFIXED;
						 FineExpl:=PayDelay || 'д*(' ||to_char(FinePart,'FM990.9999999') || ')руб';
						 FineSize:=PayDelay*FinePart; -- размер пени
				else -- штраф за факт просрочки
						 FineExpl:='(' || to_char(FINEVALUEFIXED,'FM990.9999999')|| ')руб';
