                 --               and TRIM(SUBSTR(cr.COMMENTS,1, INSTR(cr.COMMENTS, '(' ))) = TRIM(SUBSTR(CurExpl,1, INSTR(CurExpl, '(' ))) -- 16.01.2012 -- Не работало для комментариев без скобок!
                                 and TRIM(SUBSTR(cr.COMMENTS,1, DECODE(INSTR(cr.COMMENTS, '(' ),0,LENGTH(cr.COMMENTS),INSTR(cr.COMMENTS, '(' )))) = TRIM(SUBSTR(CurExpl,1, DECODE(INSTR(CurExpl, '(' ),0,LENGTH(CurExpl),INSTR(CurExpl, '(' ))))
																 and cr.paysize = FineSize
