															end if;             --*

															if FirstCharge_Period = 'Y' then
															SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext,
																							 Action.ACTION_DATE, AMoveSet_ID, null, CurExpl, FineSize, 'FINE',
																							 AObligType_ID, null, DISCOUNT_SUM, CurPDID, Action.ACTION_DATE,
																							 Action.ACTION_DATE, CurKBK_ID, null, null, OBLIG_ID, null, null, FirstCharge);
															end if;

															if G_CloseDate >= Action.ACTION_DATE then
																		A_reversal_role := 'Исправляющая';
															else
																		A_reversal_role := '';
															end if;

															SM.OBLIG_ACC_PKG.PartitioningChargesAppliesFine(CurExpl, Action.ACTION_DATE, Action.ACTION_DATE,
																										FineSize, AObligType_ID,
																										AMoveSet_ID, idNext, CurKBK_ID, 'F',
																										null, A_reversal_role, null);

												      FirstCharge_Period := 'N';   --* первое исправленное начисление пени состоялось
												 end if;              --*
												 FirstCharge := 'N';
								 end if;
				 end if;
  end if;

  -- Увеличение сальдо на размер платежа (т.е. уменьшение базы начисления пени)
	-- Исключая сумму платежа разнесенного по обязательствам периодов с (CHARGE_FINE_ASSANCTION='Y'  and FINE_KIND = 'R' )
  if Action.ACTION_TYPE = 'PAYMENT'  then
    
          --- 24.12.2014 Morozova сравниваем указанный кбк в платеже с кбк по пене
          select count(*) into itmp
          from sm.payments pm
          where pm.id = Action.ID          
          and exists (select * from sm.paydocs pd where pd.moveperiod_id = AMovePeriod_ID and pd.obligationtype_id = AObligType_ID and pm.cls_kbk_id = pd.fine_cls_kbk_id)
          and not exists (select * from sm.paydocs pd where pd.moveperiod_id = AMovePeriod_ID and pd.obligationtype_id = AObligType_ID and pm.cls_kbk_id = pd.main_cls_kbk_id);
          
          select trim(pm.mainpay) into AMainPay from sm.payments pm where pm.id = Action.Id;
          --- 08.05.2014 Morozova распределяем платеж, если он требует распределения
          --- и уменьшаем сумму платежа на сумму ушедшею на погашение пени
           if AMainPay ='D'  or (Saldo < 0 and SaldoChargesNoFine < 0 and AMainPay = 'Y' and Action.Payment_Sum > 0)  then  ---18.06.2014 Morozova добавлено условие распределения основного платежа
              sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(AMovePeriod_ID, AObligType_ID, 'N');
              Select nvl(sum(pd.val),0)  into TmpSum  from SM.PAYMENTS_DISTRIBUTION pd
                        inner join SM.PAYMENTS_PLAN pp on  pp.ID = pd.PAYMENTS_PLAN_ID
                        inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                        where pd.PAYMENTS_ID = Action.ID and trim(ch.charge_type) = 'FINE';
              Action.Payment_Sum := Action.Payment_Sum - TmpSum;
          elsif itmp = 1 then  --- 24.12.2014 Morozova если кбк у платежа совпадает с кбк по пене и он уходит полностью на пеню 
            -- Action.Payment_Sum := 0; -- 12/11/2015 Твердохлеб [24] убрал
            
            -- 12/11/2015 Твердохлеб [24] продублировал ветку выше чтобы вернуть алгоритм 475
            ---------------------------------------------------------------------------------------------------            
            sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(AMovePeriod_ID, AObligType_ID, 'N');
              Select nvl(sum(pd.val),0)  into TmpSum  from SM.PAYMENTS_DISTRIBUTION pd
                        inner join SM.PAYMENTS_PLAN pp on  pp.ID = pd.PAYMENTS_PLAN_ID
                        inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                        where pd.PAYMENTS_ID = Action.ID and trim(ch.charge_type) = 'FINE';
             Action.Payment_Sum := Action.Payment_Sum - TmpSum;
            ---------------------------------------------------------------------------------------------------              
          end if;
   
--		    if  NowOnDate then  -- <<< Если платеж в период "на день оплаты" - то учитываем только его остаток от разноски по начислениям периода "на день оплаты" (уже сделанной выше))
          if WasFinesOnDate then --- 08.05.2014 Morozova
                Select  NVL(sum(pd.val), 0)  into TmpSum from SM.PAYMENTS_DISTRIBUTION pd
								inner join SM.PAYMENTS_PLAN pp on  pp.ID = pd.PAYMENTS_PLAN_ID
								inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
								inner join SM.PAYDOCS pu on pu.ID = ch.PAYDOC_ID   AND pu.FINE_KIND = 'R'  --<<< !!! Только по периодам с % ставки реф. на день платежа
								where pd.PAYMENTS_ID = Action.ID;
                  -- 16/11/2015 Твердохлеб [24] убрал and ch.chargedate < Action.Action_Date;  --- 26.03.2014 Morozova   иначе выбирались распределения платежа будущих начислений после даты платежа;
             --   if Saldo + TmpSum <> 0 and Action.Payment_Sum - TmpSum <> 0 then   ---  10.04.2014 Morozova добавлен if. учитываем переход через 0 сальдо, когда несколько платежей гасят долг и выводят сальдо в положительное
                   Action.Payment_Sum := Action.Payment_Sum - TmpSum;
               -- end if;
				   else
               /*
                -- 12/11/2015 Твердохлеб [24] убрал
                Select  NVL(sum(pd.val), 0)  into TmpSum from SM.PAYMENTS_DISTRIBUTION pd
								inner join SM.PAYMENTS_PLAN pp on  pp.ID = pd.PAYMENTS_PLAN_ID
								inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
								where pd.PAYMENTS_ID = Action.ID
                      and ch.finedate > ch.chargedate and AFINE_BY_CHARGEDATE='N';
             */  
             -- 12/11/2015 Твердохлеб [24] продублировал ветку выше чтобы вернуть алгоритм 475             
             ---------------------------------------------------------------------------------------------------
             Select  NVL(sum(pd.val), 0)  into TmpSum from SM.PAYMENTS_DISTRIBUTION pd
								inner join SM.PAYMENTS_PLAN pp on  pp.ID = pd.PAYMENTS_PLAN_ID
								inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
								inner join SM.PAYDOCS pu on pu.ID = ch.PAYDOC_ID   AND pu.FINE_KIND = 'R'  --<<< !!! Только по периодам с % ставки реф. на день платежа
								where pd.PAYMENTS_ID = Action.ID;
                 -- 16/11/2015 Твердохлеб [24] убрал and ch.chargedate < Action.Action_Date;  --- 26.03.2014 Morozova   иначе выбирались распределения платежа будущих начислений после даты платежа;
             --   if Saldo + TmpSum <> 0 and Action.Payment_Sum - TmpSum <> 0 then   ---  10.04.2014 Morozova добавлен if. учитываем переход через 0 сальдо, когда несколько платежей гасят долг и выводят сальдо в положительное
                   Action.Payment_Sum := Action.Payment_Sum - TmpSum;
               -- end if;    
             ---------------------------------------------------------------------------------------------------                  
          end if; 

--- 18.06.2014 Morozova  блок учета суммы на которую пеня не начисляется
         if  Saldo + Action.Payment_Sum >= 0 and SaldoChargesNoFine < 0 then
              SaldoChargesNoFine := SaldoChargesNoFine + Action.Payment_Sum + Saldo; 
              if SaldoChargesNoFine > 0 then
                Saldo := SaldoChargesNoFine;
                SaldoChargesNoFine := 0;
              else
                Saldo := 0;                
              end if;  
              Action.Payment_Sum := 0 ;
          elsif TmpSum = 0 and  Saldo > 0 or -SaldoChargesNoFine < Action.Payment_Sum  then
              Action.Payment_Sum :=  SaldoChargesNoFine + Action.Payment_Sum;
              SaldoChargesNoFine := 0;
          elsif TmpSum > 0 then
               Saldo := Saldo; 
            /* 16/11/2015 Твердохлеб [24] 
              Saldo := Saldo + TmpSum;
              SaldoChargesNoFine := SaldoChargesNoFine + Action.Payment_Sum - TmpSum;
              Action.Payment_Sum := 0;*/
          elsif (Action.Payment_Sum < 0 and NO_FINE = 'Y') or
                (Action.Payment_Sum > 0 and SaldoChargesNoFine < 0 and SaldoChargesNoFine + Action.Payment_Sum <=0 and NO_FINE_FOREVER = 'Y') then
              SaldoChargesNoFine := SaldoChargesNoFine + Action.Payment_Sum;
              Action.Payment_Sum := 0;
          end if;
        
  --					SaldoPayments := SaldoPayments + Action.Payment_Sum;
             if (A_ADDCHARGE_NO_FINE_FOREVER = 'Y') then    --- <<< 25.02.2013  Добавлен учет флага
--                        if  (Action.PAYER_ID is not null  OR  NO_FINE_FOREVER = 'N')	  then
                        if  (Action.PAYER_ID is not null  OR  NO_FINE_FOREVER = 'N' or (Action.PAYER_ID is null and Action.Payment_Sum <= 0))	  then   ---18.06.2014 Morozova добавлено условие or (Action.PAYER_ID is null and Action.Payment_Sum = 0)
                                 Saldo := Saldo + Action.Payment_Sum;
                        else			 -- <<< При встрече корректирующего  (фиктивного) платежа - приводим сальдо к откорректированному значению
                                  Saldo := Saldo + SaldoChargesNoFine + Action.Payment_Sum;
                        end if;
              else
--                        if  (Action.PAYER_ID is not null  OR  NO_FINE_FOREVER = 'N')
                        if  (Action.PAYER_ID is not null  OR  NO_FINE_FOREVER = 'N' or (Action.PAYER_ID is null and Action.Payment_Sum <= 0))	   ---18.06.2014
                           and  -1*(Saldo + SaldoChargesNoFine) > Action.Payment_Sum  then --- <<< 10.01.2013 ---  Вариант исключающий грубую ситуацию с неначисленим пени после полной оплаты периодов с пеней и без.
                                 Saldo := Saldo + Action.Payment_Sum;
                        else			 -- <<< При встрече корректирующего  (фиктивного) платежа - приводим сальдо к откорректированному значению
                                  Saldo := Saldo + SaldoChargesNoFine + Action.Payment_Sum;
                        end if;
             end if;
  end if;
  -- ??????? Обработка корректировки сальдо ПО ПЕНЕ
  if Action.ACTION_TYPE = 'PAYMENT_FINE'  and Action.PAYER_ID is null then
       NULL;
  end if;

  -- начало действия льготы
  if Action.ACTION_TYPE = 'DSCNT_START' then
       DISCOUNT := DISCOUNT - Action.DISCOUNT_VALUE;
  end if;

  -- конец действия льготы
  if Action.ACTION_TYPE = 'DSCNT_STOP' then
       DISCOUNT := DISCOUNT + Action.DISCOUNT_VALUE;
  end if;

  -- если прекращать начисление пени последним днем договора (ОД)
  if (Action.ACTION_TYPE = 'LASTDAY')  then
		  if  (CHARGE_FINE_STOPFINES = 'Y' and AFineOnSt395 = 'N')  then --- 29.12.2014 Morozova  and AFineOnSt395 = 'N'
--		  if  (CHARGE_FINE_STOPFINES = 'Y')  then
              EXIT;
			else  -- <<< 23.05.2012 <<< Иначе если после окончания договора еще были начисления по оплате, то пеня начислялась на сумму без последнего начисления.
							 if (NO_FINE = 'N' and Action.Charge_Sum > 0)   --   OR  NO_FINE_FOREVER = 'N'   -- <<< ??? 21.06.2012 <<< Зачем это было?
								    and CHARGE_FINE_ASSANCTION = 'Y'   and FINE_KIND = 'R'    then   -- <<< 21.06.2012 <<< Наращивать - только при "на день платежа" <<< 09.10.2012 -добавлено FINE_KIND = 'R'
										 Saldo := Saldo - Action.Charge_Sum;
							 elsif NO_FINE = 'Y'  then
											 SaldoChargesNoFine := SaldoChargesNoFine - Action.Charge_Sum;
			--				 end if;  --- <<<< 17.02.2012 <<< Код ниже включен в IF (как elsif) - был автономным, и при NO_FINE_FOREVER = 'N'  и Action.Charge_Sum < 0 сальдо уменьшалось дважды.
							 elsif Action.Charge_Sum < 0 then
									 Saldo := Saldo  - Action.Charge_Sum + SaldoChargesNoFine;
							 end if;
	    end if;
      PassedLastDay := true;  --- 30.12.2014 Morozova
  end if;

  -- прекращать начисление пени сегодня
  if (Action.ACTION_TYPE = 'CURR_MOMENT') then
    EXIT;
  end if;

  if (Action.ACTION_TYPE = 'BOUND_END') then
    EXIT;
  end if;
 <<END_OF_LOOP>>
  null;
 END LOOP;

  -- НАЧИСЛЕНИЕ ПРОЦЕНТОВ И ПЕНИ НА СЕГОДНЯ
if  WasFinesOnDate then
        sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(AMovePeriod_ID, AObligType_ID, 'N');   --- <<< 07.03.2012 -- <<<  Закомментировано в пользу варианта ниже -  Для захвата платежей до начала периода
 --	         SM.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(OBLIG_ID);     -- <<< 13.03.2012 <<< Возвращено к варианту  выше - предыдущий охватывал неправильно период....
        sm.FINE_PERCENT_ON_DATE_PKG.CALC_PERSENS_FINES_FOR_DATE(AMoveSet_ID, AObligType_ID, sysdate);
else
        sm.PAYMENTS_DISTRIBUTE_PKG.SetIsCalcFineNeed(false);
             sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(AMovePeriod_ID, AObligType_ID, 'N');  --- <<< 07.03.2012 -- <<<  Закомментировано в пользу варианта ниже - Для захвата платежей до начала периода
 --	         SM.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(OBLIG_ID);     -- <<< 13.03.2012 <<< Возвращено к варианту выше - предыдущий охватывал неправильно период....
        sm.PAYMENTS_DISTRIBUTE_PKG.SetIsCalcFineNeed(true);
end if;

			 -- VVV -- 10.12.2013 -- подчистка "некорректных" зависших пероводок (случалось по пене при повторном открытии периода)
			-- НЕ НАДО! 17.12.2013 (Оставил на всякий случай) 
--			Delete from sm.CHARGE_APPLIES cha  where  cha.moveset_id = AMoveSet_ID  -- and  cha.APPLY_DATE  >  to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy') -- 11.12.2013 - Ослабление оправдвно
--					AND cha.reversal_role = 'Сторнированная'
--					AND not exists (Select * from SM.CHARGES ch where ch.ID = cha.charge_id) and cha.payment_id is null
--					AND not exists (Select * from SM.CHARGE_APPLIES cha2 where cha2.ID = cha.reversallink_id OR (cha2.charge_id = cha.charge_id and cha2.reversal_role = 'Сторнирующая'));
--			 -- VVV -- 10.12.2013 -- подчистка "некорректных" зависших пероводок (случалось по пене при повторном открытии периода)
--			Delete from sm.CHARGE_APPLIES cha  where  cha.moveset_id = AMoveSet_ID  -- and  cha.APPLY_DATE  >  to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy')  -- 11.12.2013 - Ослабление оправдвно
--					AND cha.reversal_role = 'Сторнирующая'
--					AND not exists (Select * from SM.CHARGES ch where ch.ID = cha.charge_id) and cha.payment_id is null
--					AND not exists (Select * from SM.CHARGE_APPLIES cha2 where cha2.ID = cha.reversallink_id OR (cha2.charge_id = cha.charge_id and cha2.reversal_role = 'Сторнированная'));
--			 -- VVV -- 12.12.2013 -- подчистка "некорректных" зависших пероводок (случалось по пене при повторном открытии периода)
--			Delete from sm.CHARGE_APPLIES cha  where  cha.moveset_id = AMoveSet_ID  -- and  cha.APPLY_DATE  >  to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy')  -- 11.12.2013 - Ослабление оправдвно
--					AND cha.reversal_role = 'Исправляющая'
--					AND not exists (Select * from SM.CHARGES ch where ch.ID = cha.charge_id) and cha.payment_id is null
--					AND not exists (Select * from SM.CHARGE_APPLIES cha2 where cha2.ID = cha.reversallink_id OR (cha2.charge_id = cha.charge_id and cha2.reversal_role = 'Сторнирующая'));

END FullRecalcFines;



------------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------------------------------------------------------------------------------------------------
------------- процедура расчета для оплаты в рассрочку по основному обязательству --------------------
PROCEDURE FullRecalcChargesCredit(AMoveSet_ID in number, AObligType_ID in number)
is

 c integer;                    --*
A_comments varchar2(100);
A_corr_flag char(1);
A_chargedate date;
A_reversal_role varchar2(100);


  CHARGE_USE_HOLYDAYS_str char(1);
  CHARGE_USE_HOLYDAYS boolean;
  ChargeFineDate Date;
--параметры
  OncePayDate DATE;
  A_PaySize Number(27,2);          -- размер оплаты
  ObName Varchar2(200);
  Periodical CHAR(1);
  ADate date;
  PrevFineDate date;

  KBK_ID NUMBER;                -- Код бюджетной классификации
  KBK_Percent NUMBER;
	
  PDID NUMBER;                  -- ссылка на PAIDOCS

  Fine_Kind char(1);
  CreditSize number(27,2);
  CreditCountMonth number;
  CreditStartDate date;
  CreditFirstPayDate date;
  CreditPercent sm.PAYDOCS.creditpercent%type;
  CreditPercentOnDebt char(1);
  CreditPercentConst char(1);
  CreditPercentByDays char(1);
  CreditReinratePart number(27);

  OBLIG_ID number(27);
  ACTUAL_DATE date;
  CREDIT_CHARGE_ID number(27);
  period_presets number(27);

  no_fine char(1);
  no_creditpercent char(1);
  fineoncreditpersent char(1);

  CurrCreditPercent number(27,2);
  CurrFineCreditPercent number(27,2);
  DayByPersent number;

  CurRefinRate number(27,2);
  creditpercentpart number(27,10);

  creditrefinratepart_num number(27);
  creditrefinratepart_denom number(27);

  prev_ChargeDate date;
  prev_saldo number(27,2);
  prev_date_calc date;
  Comment_txt sm.charges.comments%type;
  on_sum number(27,2);
  itmp integer;
 DaysInYear integer := 365;
 ARecalc_Start_Date date;
 APercent_Instant char(1) := 'N';

BEGIN

  G_CloseDate := to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy');

    begin
        Select ob.ID, ob.recalc_actual_date, ob.recalc_start_date
        into OBLIG_ID, ACTUAL_DATE, ARecalc_Start_Date
        from sm.obligations ob
        where ob.moveset_id=AMoveSet_ID and
              ob.obligationtype_id=AObligType_ID;

 -- условия рассрочки
           select   pd.creditstartdate,
                   pd.id,
                   pd.OncePayDate,
                   pd.PaySize,
                   pd.fine_kind,
                   pd.creditsize,
                   pd.creditcountmonth,
                   pd.creditfirstpaydate,
                   pd.creditpercent,
                   pd.creditpercentondebt,
                   pd.creditpercentconst,
                   pd.creditpercentbydays,
                   pd.creditrefinratepart_num,
                   pd.creditrefinratepart_denom,
                   ot.Name,
                   pd.Periodical,
                   pd.main_cls_kbk_id as MainKBK, NVL(pd.percent_cls_kbk_id, pd.main_cls_kbk_id)  as PercentKBK,
                   NVL(pd.oblig_periodical_presets_id, 1),
                   pd.no_fine no_fine,
                   pd.no_creditpercent no_creditpercent,
                   pd.fineoncreditpersent fineoncreditpersent
          into     CreditStartDate,
                   PDID,
                   OncePayDate,
                   A_PaySize,
                   Fine_Kind,
                   CreditSize,
                   CreditCountMonth,
                   CreditFirstPayDate,
                   CreditPercent,
                   CreditPercentOnDebt,
                   CreditPercentConst,
                   CreditPercentByDays,
                   creditrefinratepart_num,
                   creditrefinratepart_denom,
                   ObName,
                   Periodical,
                   KBK_ID,  KBK_Percent,
                   period_presets,
                   no_fine,
                   no_creditpercent,
                   fineoncreditpersent
          from
                   paydocs pd,
                   moveperiods mp,
                   ObligationType ot
          where
                   mp.moveset_id=AMoveSet_ID and
                   pd.moveperiod_id=mp.id and
                   ot.id=pd.obligationtype_id and
                   pd.obligationtype_id=AObligType_ID and
                   mp.prev_moveperiod_id is null;
     exception
      when others then
        RETURN; -- не нашли параметров обязательства - не сможем рассчитать, поэтому выйдем
   end;

    -- параметры расчетов
  begin
              select NVL(opp.charge_use_holydays, 'N')
            into CHARGE_USE_HOLYDAYS_str
            from sm.oblig_periodical_presets opp
            where opp.id=period_presets;

          select op.percents_instant
           into APercent_Instant
           from sm.obligations obl,
                sm.oblig_presets op
           where obl.moveset_id=AMoveSet_ID and
               obl.obligationtype_id=AObligType_ID and
               op.id = obl.oblig_presets_id;
    exception
      when others then
        RETURN; -- не нашли параметров обязательства - не сможем рассчитать, поэтому выйдем
   end;

    if CHARGE_USE_HOLYDAYS_str='Y' then
          CHARGE_USE_HOLYDAYS:=true;
    else
          CHARGE_USE_HOLYDAYS:=false;
    end if;

-- TMP!!! ????????????????????? 27.10.2011 условие внизу фактически снято ???
--      (По-видимому попытка персчитывать оптимальней - только после даты расчета давала побочные эффекты...)
ACTUAL_DATE := null;
    if ACTUAL_DATE is null then
    -- Удаляем все начисления по обязательству
 ------------------------------------------------------------------------------------------------------
--* Морозова
--* удаляем только плановые начисления по обязательству

      delete from sm.charges ch
      where ch.movesets_id=AMoveSet_ID
               and ch.obligationtype_id=AObligType_ID
               and ch.document_id is null and ch.charge_type <> 'OTHER'
               and ch.factcharge = 'N'
							 AND ch.CHARGEDATE > ARecalc_Start_Date;  ---<<< 14.12.2012  --Удаляем начисления только после даты начала пересчета. ------
 ----------------------------------------------------------------------------------------------------------
        -- ADate - дата, до которой производить расчет плана
        ADate:=add_months(trunc(CreditStartDate),CreditCountMonth);

--* Морозова
--- <<< 11.05.2012 <<< Упрощена проверка, ниже сделана обработка обновления существующего (иначе создавались дубли).
       select  --+INDEX(cr IDX_CHG_MOVESET_ID)
       count (*) into c FROM SM.Charges cr
         where cr.paydoc_id = PDID
               and cr.comments = 'Сумма по договору'
                and cr.charge_type = 'OBLIGATION'
               and cr.movesets_id = AMoveSet_ID
               and cr.obligationtype_id = AObligType_ID;

   if c = 0 then    --*

    -- удаляем начисление основной суммы кредита по обязательству в рассрочке,
    -- если оно было заведено ренее и имеет комментарий не "Сумма по договору"
        delete from sm.charges ch
        where ch.movesets_id=AMoveSet_ID
              and ch.obligationtype_id = AObligType_ID
							and ch.document_id is null 
              and ch.charge_type in ( 'OBLIGATION', 'PERCENT')
              and ch.paydoc_id = PDID
              and nvl(ch.Cls_Kbk_Id, 0) = nvl(KBK_ID,0)
              and trim(ch.comments) <> 'Сумма по договору'
							AND  ch.chargedate > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.


        -- делаем начисление по рассрочке и план платежа по предоплате
        select sm.seqcharges.nextval
        into CREDIT_CHARGE_ID
        from dual;

        Insert into sm.charges(id,chargedate,paydoc_id,comments,paysize,charge_type,finedate,movesets_id,obligationtype_id,calperiod_start,calperiod_end,cls_kbk_id)
               values(CREDIT_CHARGE_ID,CreditStartDate,PDID,'Сумма по договору', A_PaySize,'OBLIGATION',null,AMoveSet_ID,AObligType_ID,CreditStartDate,ADate,KBK_ID);
       -------- Отражаем начисление в Учетных данных
--* Морозова
       SM.OBLIG_ACC_PKG.RecalcChargesApplies(CREDIT_CHARGE_ID,
                         CreditStartDate, AMoveSet_ID, null, 'Сумма по договору', A_PaySize, 'OBLIGATION',
                         AObligType_ID, null, null, PDID, CreditStartDate,
                         ADate, KBK_ID, null, null, OBLIG_ID);

      if G_CloseDate >= CreditStartDate then
                      A_comments := 'Исправляющая: ';
                      A_corr_flag :='Y';
                      A_chargedate := trunc(sysdate);
                      A_reversal_role := 'Исправляющая';
         else
                      A_comments := '';
                      A_corr_flag := 'N';
                      A_chargedate := CreditStartDate;
                      A_reversal_role := '';
         end if;

          insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                payments_distribution_id, reversal_role, reversallink_id, payment_id)
          values (sm.seqcharge_applies.nextval, A_chargedate, A_PaySize, AObligType_ID, AMoveSet_ID,
                                                'O', A_comments || 'Сумма по договору', CREDIT_CHARGE_ID, A_corr_flag,  KBK_ID,
                                                null, null, A_reversal_role, null, null);

   else  ---  Уже есть -
        delete from sm.charges ch
        where ch.movesets_id=AMoveSet_ID
              and ch.obligationtype_id = AObligType_ID
							and ch.document_id is null 
              and ch.charge_type =  'PERCENT'
              and ch.paydoc_id = PDID
							AND  ch.chargedate > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.


							 select  --+INDEX(ch IDX_CHG_MOVESET_ID)     -- сохраняем его ID
							 ch.id into CREDIT_CHARGE_ID
								from sm.charges ch
								where ch.paydoc_id = PDID
											 and ch.comments = 'Сумма по договору'
--											 and ch.paysize = A_PaySize
											 and ch.charge_type = 'OBLIGATION'
											 and ch.finedate is null
											 and ch.movesets_id = AMoveSet_ID
											 and ch.obligationtype_id = AObligType_ID;
							-- Проверяем на более точное совпадение..
							 select  --+INDEX(cr IDX_CHG_MOVESET_ID)
							 count (*) into c FROM SM.Charges cr
								 where cr.paydoc_id = PDID
											 and cr.comments = 'Сумма по договору'
											 and cr.paysize = A_PaySize
											 and cr.charge_type = 'OBLIGATION'
											 and cr.finedate is null
											 and cr.movesets_id = AMoveSet_ID
											 and cr.obligationtype_id = AObligType_ID
											 and cr.calperiod_end = ADate
											 and nvl(cr.Cls_Kbk_Id, 0) = nvl(KBK_ID,0);

					      if c = 0 then --- Есть, но не точно такой - update-аем существующее начисление (и учетные данные)
							      	 Update SM.CHARGES ch set ch.PAYSIZE = A_PaySize, ch.CALPERIOD_END = ADate, ch.CLS_KBK_ID = KBK_ID where ID = CREDIT_CHARGE_ID;
											 -- VVV 10.12.2012 Добавлено: (Case when G_CloseDate >= CreditStartDate* * *
							      	 Update SM.CHARGE_APPLIES cha set cha.SUMM = A_PaySize, cha.APPLY_DATE = (Case when G_CloseDate >= CreditStartDate then  cha.APPLY_DATE else CreditStartDate end ), cha.CLS_KBK_ID = KBK_ID where cha.CHARGE_ID = CREDIT_CHARGE_ID; -- << 07.12.2012  CreditStartDate  вместо ADate
				        end if;
   end if;         --*
        prev_ChargeDate:=creditstartdate;
        prev_saldo:=CreditSize;
        DayByPersent:=0;
        on_sum:=0;

      ----- Пишем сопровждающий начисление план его погашения ----
			-- Первоначальный взнос -  Часть плаена
--      select count(*) into c from sm.payments_plan t
--       where t.obligations_id = OBLIG_ID
--          and t.finedate = OncePayDate
--            and t.val = (A_PaySize-CreditSize)
--            and t.payments_plan_draft_id is null
--            and t.comments = 'Первоначальный взнос';
			   Delete from  SM.PAYMENTS_PLAN where 	OBLIGATIONS_ID = OBLIG_ID and CHARGES_ID = CREDIT_CHARGE_ID  and PAYMENTS_PLAN_DRAFT_ID is null  and COMMENTS = 'Первоначальный взнос'
										 							 AND  FINEDATE > ARecalc_Start_Date;     ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
--       if c = 0 then  --* Морозова
					if (A_PaySize-CreditSize)>0  AND OncePayDate > ARecalc_Start_Date then -- <<< 28.10.2013 Без OncePayDate > ARecalc_Start_Date повтроно начислялся Первонач.Взнос 
									 Insert into sm.payments_plan(id, charges_id, obligations_id, finedate, val, payments_plan_draft_id, COMMENTS)
											 values(sm.seqpayments_plan.nextval, CREDIT_CHARGE_ID, OBLIG_ID, OncePayDate, (A_PaySize-CreditSize), null, 'Первоначальный взнос');
					end if;
 --      end if;        --*

        -- заполнение плана
        for xx in (select *
                   from sm.payments_plan_draft dd
                   where dd.obligationtype_id=AObligType_ID and
                         dd.movesets_id=AMoveSet_ID
                   order by dd.finedate)
        loop
                   ChargeFineDate:=xx.finedate;
                   if CHARGE_USE_HOLYDAYS then
                    --если дата конца срока оплаты попала на нерабочий день - смещаем эту дату на ближайший рабочий
										 -- ChargeFineDate:=sm.GetFirstWorkDate(xx.finedate-1)+1;  ---<<<< Так суббота (да и любой единичный праздник) - становилась днем начисления !!! Как оно работало???
										 -- (Чтобы понедельник сдвигался на вторник? - так не нада оно...)
												ChargeFineDate:=sm.GetFirstWorkDate(xx.finedate); -- <<< А так - всегда следующий рабочий день. (Что пеня со следующего за ним дня - это другая история).
                  end if;
									--- <<< 23.03.2012 <<< --- Правильно применяем долю ставки рефинансирования для високосного года при "точном" методе
									if SM.IsLeapDate(xx.finedate-1) then   -- <<< 25.02.2013 было ChargeFineDate, но давало дефект при переходе между високосным и невисокосным годами (TODO:  еще доработать!!!)
										    DaysInYear := 366;
									else
										    DaysInYear := 365;
									end if;

                  Comment_txt:='Планируемое погашение за период с '|| to_char(prev_ChargeDate,'dd.MM.yyyy') ||' по '||to_char(xx.finedate-1,'dd.MM.yyyy');

                --* Морозова
                select count(*) into c from sm.payments_plan t
                where t.obligations_id = OBLIG_ID
                  and t.finedate = ChargeFineDate
                  and t.val = xx.val
                  and t.payments_plan_draft_id = xx.id
                 and t.comments = Comment_txt;
										 -- <<< 04.04.2012 <<< -- При смене условий - могли оставаться прежние планы под тот же драфт...
										 Delete from SM.PAYMENTS_PLAN pp where pp.PAYMENTS_PLAN_DRAFT_ID = xx.id
																and  pp.finedate <> ChargeFineDate  -- <<< Вот оно - возможное расхождение.
															  and pp.val = xx.val
															  and pp.comments = Comment_txt
										 						AND  pp.FINEDATE > ARecalc_Start_Date;     ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.

                 if c = 0 then  --* Морозова
											 insert into sm.payments_plan(id,charges_id,obligations_id,finedate,val,payments_plan_draft_id,comments)
														 values (sm.seqpayments_plan.nextval,CREDIT_CHARGE_ID,OBLIG_ID,ChargeFineDate,xx.val,xx.id,Comment_txt);
									end if;   --*

                   if no_creditpercent='N' then
													 -- процент по плану
															if CREDITPERCENTCONST='Y' then -- твердый процент
																	creditpercentpart:=creditpercent/100; -- в день
															else -- от ставки рефинансирования на день оплаты
																	CurRefinRate:=RefineRateOnDate(ChargeFineDate);
																	creditpercent:=CurRefinRate*CREDITREFINRATEPART_NUM/(CREDITREFINRATEPART_DENOM);
																	creditpercentpart:=creditpercent/100;
															end if;
															DayByPersent:=xx.finedate-prev_ChargeDate;
															if CreditPercentOnDebt='Y' then
																 CurrCreditPercent:=prev_saldo * DayByPersent * creditpercentpart / DaysInYear;
															else
																 CurrCreditPercent:=CREDITSIZE * DayByPersent * creditpercentpart / DaysInYear;
															end if;
															prev_saldo:=prev_saldo-xx.val;

															update sm.payments_plan_draft d set d.PERCENT_VAL=CurrCreditPercent where d.id=xx.id;

															-- VVV 03.04.2013 Фиксированный процент - пишем начисление процентов сразу
															if APercent_Instant = 'Y' then
--                                       percentAdded := PAYMENT_ADD_PERCENTS(pay_plan.ID, trunc( pay_plan.FINEDATE), trunc(PayDate), PayPlanPrevDate,
--																			              MoveSetID, pay_plan.OBLIGATIONTYPE_ID, pay_plan.PAYMENTS_PLAN_DRAFT_ID, 'Y',  PayDescr, PayID, FirstCharge );
    --                                                 Comment_txt := Comment_txt || ' (прогноз)';
		                                               Comment_txt:='Проценты на сумму ' || to_char(prev_saldo) || ' за '||to_char(DayByPersent) || 'дн. (c '|| to_char(prev_ChargeDate+1,'dd.MM.yyyy') ||' по '|| to_char(xx.finedate,'dd.MM.yyyy') ||')';

                                                    Insert into SM.CHARGES(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                                                   values (sm.seqcharges.nextval, trunc( xx.finedate), trunc( xx.finedate), PDID, Comment_txt, CurrCreditPercent, 'PERCENT', AMoveSet_ID, AObligType_ID,  trunc(prev_ChargeDate), trunc( xx.finedate), KBK_Percent,  'Y');
                                                    Insert into SM.PAYMENTS_PLAN(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                                                   values (sm.seqpayments_plan.nextval, sm.seqcharges.currval, OBLIG_ID, trunc( xx.finedate), CurrCreditPercent, xx.id, Comment_txt, null);
 															end if;

                   end if;
                   prev_ChargeDate:=xx.finedate;
        end loop;

       -- ЗДЕСЬ ВЫЗОВ ПРОЦЕДУРЫ ПЕРЕРАСПРЕДЕЛЕНИЯ ПЛАТЕЖЕЙ
        sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(OBLIG_ID);
         -- НАЧИСЛЕНИЕ ПРОЦЕНТОВ И ПЕНИ НА СЕГОДНЯ
        sm.FINE_PERCENT_ON_DATE_PKG.CALC_PERSENS_FINES_FOR_DATE(AMoveSet_ID,AObligType_ID,sysdate);

     else     -- <- ACTUAL_DATE is NOT null
        if ACTUAL_DATE>trunc(sysdate) then
            ACTUAL_DATE:=trunc(sysdate);
        end if;
        -- удаляем только начисления плановые по пени и процентам и расчитываем их снова
        --delete from sm.charges ch where ch.charge_type!='OBLIGATION' and
        --                                ch.factcharge='N' and
        --                                ch.obligationtype_id=AObligType_ID and
        --                               ch.movesets_id=AMoveSet_ID;
        -- удаляем начислени процентов и пени после даты актуальности
--*        delete from sm.charges ch where
--*                                         ch.movesets_id=AMoveSet_ID
--*                                         and ch.obligationtype_id=AObligType_ID
--*                                         and ch.charge_type!='OBLIGATION'
--*                                         and ch.chargedate>ACTUAL_DATE
--*                                         and ch.document_id is null;

         -- ЗДЕСЬ ВЫЗОВ ПРОЦЕДУРЫ ПЕРЕРАСПРЕДЕЛЕНИЯ ПЛАТЕЖЕЙ
        sm.PAYMENTS_DISTRIBUTE_PKG.PAYMENTS_DISTRIBUTE(OBLIG_ID);
          -- НАЧИСЛЕНИЕ ПРОЦЕНТОВ И ПЕНИ НА СЕГОДНЯ
       sm.FINE_PERCENT_ON_DATE_PKG.CALC_PERSENS_FINES_FOR_DATE(AMoveSet_ID,AObligType_ID, sysdate);

     end if;

  ACTUAL_DATE:=trunc(sysdate);
  update sm.obligations o set o.recalc_actual_date=ACTUAL_DATE where o.id=OBLIG_ID;

 END FullRecalcChargesCredit;




