FUNCTION PAYDOC_ID_FOR_CHARGES(CHARGES_ID IN NUMBER) return number is
  Result number;
  cnt number;
  charge_date date;
  flag number;
  itmp integer;
--
-- функция возвращает ID условий для начисления
--
BEGIN

  Result:=null;


  select count(*) into itmp
    from sm.charges ch
    where ch.id=CHARGES_ID;
  if itmp = 1 then
          select nvl(ch.document_id,0), ch.chargedate
          into cnt, charge_date
          from sm.charges ch
          where ch.id=CHARGES_ID;
   else
         RETURN 0;
  end if;

  if cnt=0 then
        select pd.id
        into Result
        from  sm.paydocs pd,
              sm.charges ch
        where pd.id=ch.paydoc_id and
              ch.id=CHARGES_ID;
  else
       flag:=0; -- не нашли условия до даты начисления
       for xx in (select mp.sincedate, pd.id
                  from sm.paydocs pd,
                       sm.moveperiods mp,
                       sm.charges ch
                  where ch.id=CHARGES_ID and
                        ch.movesets_id=mp.moveset_id and
                        pd.moveperiod_id=mp.id and
                        pd.obligationtype_id=ch.obligationtype_id
                  order by mp.sincedate)
       loop
         if xx.sincedate<=charge_date then
            Result:=xx.id;
            flag:=1;
         else
            if flag=0 then
               Result:=xx.id;
               flag:=1;
            end if;
         end if;
       end loop;

  end if;

  RETURN Result;

  exception
    when others then
      Result:=null;

END PAYDOC_ID_FOR_CHARGES;


