FUNCTION PAYDOC_ID_ON_DATE(AMoveSet_ID number, AObligType_ID number, A_PayDate date) return number is
  Result number(27);
  cnt number;
  --charge_date date;
  flag number;
  itmp integer;
--
-- функция возвращает ID условий по обязательству, действующих на дату A_PayDate
--
BEGIN

Result := null;

  select count(*) into itmp
             from
                  sm.PAYDOCS pd,
                  sm.MOVEPERIODS mp
             where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                   and  pd.moveperiod_id=mp.id
                   and mp.SINCEDATE < A_PayDate and NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy') )> A_PayDate;
  if itmp = 1 then
        select pd.ID into Result
                     from
                          sm.PAYDOCS pd,
                          sm.MOVEPERIODS mp
                     where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                           and pd.moveperiod_id=mp.id
                           and mp.SINCEDATE < A_PayDate and NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy') )> A_PayDate;
  else
         RETURN 0;
  end if;

RETURN Result;

  exception
    when others then
       return null;

END PAYDOC_ID_ON_DATE;


--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
-- функция возвращает ID условий по обязательству, действующих на дату A_PayDate ДЛЯ ЦЕЛЕЙ НАЧИСЛЕНИЯ ПЕНИ-
-- (отличается тем что для пени используются последние действовавшие условия, даже если на данный момент (период) обязательств нет вообще! )
FUNCTION PAYDOC_ID_FOR_FINE_ON_DATE(AMoveSet_ID number, AObligType_ID number, A_PayDate date) return number is
  Result number(27);
  cnt number;
  flag number;
  itmp integer;

BEGIN

Result := null;

  select count(*) into itmp
             from
                  sm.PAYDOCS pd,
                  sm.MOVEPERIODS mp
             where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                   and  pd.moveperiod_id=mp.id
                 and mp.SINCEDATE <= A_PayDate and NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) > A_PayDate;

  if itmp = 1 then
       select pd.ID into Result
             from
                  sm.PAYDOCS pd,
                  sm.MOVEPERIODS mp
             where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                   and pd.moveperiod_id=mp.id
                 and mp.SINCEDATE <= A_PayDate and NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) > A_PayDate;
 else
        select count(*) into itmp
             from
                  sm.PAYDOCS pd,
                  sm.MOVEPERIODS mp
             where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                  and  pd.moveperiod_id=mp.id
                 and   ( nvl(mp.ENDDATE,to_date('01.01.3000','DD.MM.YYYY')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                            where   pd2.moveperiod_id(+)=mp2.id
                                                            and mp2.moveset_id=AMoveSet_ID and pd2.obligationtype_id=AObligType_ID
                                                            and  pd2.Periodical != 'N')
                                                            or mp.ENDDATE is null);
           if itmp = 1 then
                         select pd.ID into Result
                         from
                              sm.PAYDOCS pd,
                              sm.MOVEPERIODS mp
                         where AMoveSet_ID=mp.MOVESET_ID and pd.OBLIGATIONTYPE_ID=AObligType_ID
                               and pd.moveperiod_id=mp.id
                             and (nvl(mp.ENDDATE,to_date('01.01.3000','DD.MM.YYYY')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                                      where   pd2.moveperiod_id(+)=mp2.id
                                                                      and mp2.moveset_id=AMoveSet_ID and pd2.obligationtype_id=AObligType_ID
                                                                      and  pd2.Periodical != 'N')
                                                                      or mp.ENDDATE is null);
            else
                    RETURN 0;
            end if;
end if;

RETURN Result;

  exception
    when others then
       return null;

END PAYDOC_ID_FOR_FINE_ON_DATE;


