FUNCTION DSCNT_FOR_CHARGES(CHARGES_ID IN NUMBER) return number is
  Result NUMBER(27,4);
--
-- функция возвращает значение коэффициента льготы для начисления
--

BEGIN

  Result:=1;

  for xx in (select ds.discount_value
             from sm.discounts ds,
                  sm.charges ch
             where ch.id= CHARGES_ID and
                   ds.moveset_id=ch.movesets_id and
                   ds.obligationtype_id=ch.obligationtype_id and
                   ch.chargedate >= ds.sincedate and
                   ch.chargedate<=ds.enddate)
   loop
     Result:=Result-xx.discount_value;
   end loop;

  if result<0 then
     result:=0;
  end if;

  RETURN Result;

END DSCNT_FOR_CHARGES;


--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
FUNCTION DSCNT_ON_DATE(AMoveSet_ID number,AObligType_ID number,A_Date date, What varchar) return number is
  Result NUMBER(27,4);
--
-- функция возвращает значение коэффициента льготы
---     What='MAIN'         по обязательству
--      What='FINE'               по пени
-- на дату A_Date
--

BEGIN

  Result:=1;

  for xx in (select ds.discount_value
             from sm.discounts ds
             where ds.moveset_id=AMoveSet_ID and
                   ds.obligationtype_id=AObligType_ID and
                   ds.discharge_type=trim(What) and
                   A_Date >= ds.sincedate and
                   A_Date<=ds.enddate)
   loop
     Result:=Result-xx.discount_value;
   end loop;

  if result<0 then
     result:=0;
  end if;

  RETURN Result;

END DSCNT_ON_DATE;


--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------
-- функция возвращает значение коэффициента льготы для начисления
FUNCTION RefineRateOnDate(CurDate IN date) return number is
  Result NUMBER(27,2);
  itmp integer;

BEGIN
 select rt.refrate
 into Result
 from sm.refinrates rt
 where rt.apply_date in
       nvl((select max(f.apply_date) from sm.refinrates f where f.apply_date<=CurDate),(select min(f.apply_date) from sm.refinrates f));

 RETURN Result;

 exception
    when others then
      Result:=null;

END RefineRateOnDate;


