FUNCTION PersentSizeForPayment(AMoveSet_ID number, AObligType_ID number, A_PayDate date, prev_date_calc in out date, Comment_txt out varchar2) return number is
  Result NUMBER(27,2);
--
-- функция возвращает размер процентов, которые должны быть начислены на дату A_PayDate
--
paysize NUMBER(27,2);
oncepaydate date;
main_cls_kbk_id NUMBER(27);
fineoncreditpersent char(1);
creditsize NUMBER(27,2);
creditcountmonth  NUMBER(27);
creditstartdate date;
creditfirstpaydate date;
creditpercent NUMBER(27,4);
creditpercentondebt char(1);
creditpercentconst char(1);
creditpercentbydays char(1);
creditrefinratepart_num NUMBER(27);
creditrefinratepart_denom NUMBER(27);

 OBLIG_ID number(27);
 cur_dept number(27,2);
 prev_pay date;
 creditpercentpart number(27,10);
 CurRefinRate number(27,2);
 DayByPersent number;
 on_sum number(27,2);
 itmp integer;
 DaysInYear integer := 365;

BEGIN

 Result:=0;

 select count(*) into itmp
   from sm.obligations obl
   where obl.moveset_id=AMoveSet_ID and
       obl.obligationtype_id=AObligType_ID;
  if itmp = 1 then
         select obl.id
         into OBLIG_ID
         from sm.obligations obl
         where obl.moveset_id=AMoveSet_ID and
             obl.obligationtype_id=AObligType_ID;
  else
         RETURN 0;
  end if;

 select count(*) into itmp
  from sm.paydocs pd,
      sm.moveperiods mp
 where pd.moveperiod_id=mp.id and
      pd.obligationtype_id=AObligType_ID and
      mp.moveset_id=AMoveSet_ID;
  if itmp = 1 then
             select pd.paysize,
                  pd.oncepaydate,
                  pd.main_cls_kbk_id,
                  pd.fineoncreditpersent,
                  pd.creditsize,
                  pd.creditcountmonth,
                  pd.creditstartdate,
                  pd.creditfirstpaydate,
                  pd.creditpercent,
                  pd.creditpercentondebt,
                  pd.creditpercentconst,
                  pd.creditpercentbydays,
                  pd.creditrefinratepart_num,
                  pd.creditrefinratepart_denom
           into
                  paysize,
                  oncepaydate,
                  main_cls_kbk_id,
                  fineoncreditpersent,
                  creditsize,
                  creditcountmonth,
                  creditstartdate,
                  creditfirstpaydate,
                  creditpercent,
                  creditpercentondebt,
                  creditpercentconst,
                  creditpercentbydays,
                  creditrefinratepart_num,
                  creditrefinratepart_denom
           from sm.paydocs pd,
                sm.moveperiods mp
           where pd.moveperiod_id=mp.id and
                pd.obligationtype_id=AObligType_ID and
                mp.moveset_id=AMoveSet_ID;
else
          RETURN 0;
  end if;


 cur_dept:= creditsize;
 prev_pay:= creditstartdate-1;
 prev_date_calc:=creditstartdate-1;


 for xx in (select pd.val,
                   sm.getpaydateforpayment(p.id) paydate,
                   pp.finedate,
                   ch.charge_type
            from sm.payments_distribution pd,
                   sm.payments_plan pp,
                   sm.payments p,
                   sm.charges ch
            where pd.payments_plan_id=pp.id and
                   pp.obligations_id=OBLIG_ID and
                   p.id=pd.payments_id and
                   (ch.CHARGE_TYPE='OBLIGATION' or ch.CHARGE_TYPE='PERCENT') and
                   ch.id=pp.CHARGES_ID and
                   pp.payments_plan_draft_id is not null and
                   sm.getpaydateforpayment(p.id)<=A_PayDate
            order by  sm.getpaydateforpayment(p.id), pp.finedate)
         loop
           if xx.charge_type = 'OBLIGATION' then
                cur_dept:=cur_dept-xx.val;
           end if;
           prev_pay:=xx.paydate;
         end loop;

   if cur_dept > 0 and A_PayDate > prev_pay then

					if SM.IsLeapDate(A_PayDate) then
								DaysInYear := 366;
					else
								DaysInYear := 365;
					end if;

       -- процент по плану
       if CREDITPERCENTCONST='Y' then -- твердый процент
           creditpercentpart:=creditpercent/(DaysInYear*100); -- в день
       else -- от ставки рефинансирования на день оплаты
           CurRefinRate:=RefineRateOnDate(A_PayDate);
           creditpercent:=CurRefinRate*CREDITREFINRATEPART_NUM/CREDITREFINRATEPART_DENOM;
           creditpercentpart:=creditpercent/(DaysInYear*100);
       end if;
       DayByPersent:=A_PayDate-prev_pay;
       if CreditPercentOnDebt='Y' then
            Result:=cur_dept*DayByPersent*creditpercentpart;
           on_sum:=cur_dept;
       else
           Result:=CREDITSIZE*DayByPersent*creditpercentpart;
           on_sum:=CREDITSIZE;
       end if;
       prev_date_calc:=prev_pay;
       Comment_txt:='Проценты на сумму '|| to_char(on_sum) || ' за '|| to_char(A_PayDate-prev_date_calc) || 'дн. (c '||to_char(prev_date_calc+1,'dd.MM.yyyy') ||' по '|| to_char(A_PayDate,'dd.MM.yyyy') ||')';

   end if;


 RETURN Result;

-- exception
--    when others then
      -- ??? Result:=null;
 --     RETURN 0;

END PersentSizeForPayment;


-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FUNCTION FineSizeForCredit(AMoveSet_ID number, AObligType_ID number, A_Date date, obl_plan number, prev_date_calc out date, Comment_txt out varchar2, fact_charges char default 'Y', conditions_date date, PDIDpar number) return number is
  Result NUMBER(27,9);

c integer;            --*
idNext integer;       --*
FirstCharge char(1);  --* самое первое начисление
FirstCharge_Period char(1);
A_reversal_role varchar2(100);

-- finepercent NUMBER(27,2);
  finepercent NUMBER(27,9);
 RefPart number(27);
 calendar_type number(27);
 fine_cls_kbk_id number(27);
 fine_kind char(1);
 fineondebt char(1);
 finevaluefixed_daily char(1);
 finevaluefixed number(27,2);
 no_fine char(1);
 period_presets number(27);
 OBLIG_ID number(27);
 charge_fine_method number;
 charge_fine_stopfines char(1);
-- vrpaymnt_reduce_creditmonths
 charge_fine_assanction char(1);
 DISCOUNT number(27,2);

 curr_saldo number(27,2);
 curr_saldo_plan number(27,2);
 Saldo number(27,2);
 prev_pay date;
 DayByFine number;
 plan_finedate date;
 --CurRefinRate number(27,2);
 CurRefinRate number(27,9);
 cnt number;

 p1 number;
 p2 number;
 p3 number;

 -- FinePart number(27,2);
 FinePart number(27,9);
 --FineExpl varchar2(50);
 FineExpl varchar2(100);
 FineSize number(27,9);
 Expl_Date date;
 prev_charges date;

 ch_finedate date;
 ch_type sm.charges.charge_type%type;
 ChargeType varchar2(10);
 itmp integer  := 0;
 DaysInYear integer := 365;
 Multi number;
 IsReal char(1) := 'Y';
 PDID number(27) := PDIDpar;
 ARecalc_Start_Date date;

BEGIN

FirstCharge := 'Y';
FirstCharge_Period := 'Y';
   Result:=0;

-- VVV 30.10.2012 -- добыча PDID теперь практически надобится, осталено на всякий пожарный
if PDID is null or PDID = 0 then
-- PDID:=PAYDOC_ID_ON_DATE(AMoveSet_ID,AObligType_ID,A_Date); -- Условия - на день закрываемого обязательства, а не на день платежа!
  PDID:=PAYDOC_ID_FOR_FINE_ON_DATE(AMoveSet_ID, AObligType_ID, conditions_date + 1);
--
  if PDID is null or PDID = 0 then
         -- Пеню есть смысл считать за прошлые периоды - по условиям последнего соглашения сторон - это ЧАЩЕ ВСЕГО (но не обязательно!) юридически более состоятельная позиция.
         --            Поэтому, если не нашлось условий на заказанную дату (а их возможно и не нада было искать - см.выше) - то БЕРЕМ НА ТЕКУЩУЮ.
          PDID:=PAYDOC_ID_FOR_FINE_ON_DATE(AMoveSet_ID, AObligType_ID, sysdate);
          if PDID is null or PDID = 0 then
                  RETURN 0;
        end if;
  end if;
end if;

   select count(*) into itmp
   from sm.obligations obl,
        sm.oblig_presets op
   where obl.moveset_id=AMoveSet_ID and
       obl.obligationtype_id=AObligType_ID and
       op.id = obl.oblig_presets_id;
if itmp = 1 then
          select obl.id, op.charge_fine_stopfines,op.charge_fine_assanction, obl.RECALC_START_DATE
           into OBLIG_ID, charge_fine_stopfines, charge_fine_assanction, ARecalc_Start_Date
           from sm.obligations obl,
                sm.oblig_presets op
           where obl.moveset_id=AMoveSet_ID and
               obl.obligationtype_id=AObligType_ID and
               op.id = obl.oblig_presets_id;
else
         RETURN 0;
  end if;

  IF A_Date < ARecalc_Start_Date  THEN RETURN 0;  END IF; --- <<< 14.12.2012 Не начислять до даты пересчета!!!


   select pd.finepercent,
          pd.refinratepart, -- Доля ставки рефинансирования
          pd.calendar_type_id, -- Тип календаря (360/точный (365(/366)))
          pd.fine_cls_kbk_id, -- КБК
          pd.fine_kind, -- Способ исчисления пени: 'P'-процент (по умолчанию), 'R'-ставка рефинансирования, 'F'-фиксированная сумма
          pd.fineondebt, -- база для определения процента пени - от долга (умолч.'y') / от суммы арендной платы ('n')
          pd.finevaluefixed_daily, -- фиксированная пеня за каждый день просрочки исполнения обязательств (умолч. 'y')/за факт просрочки независимо от дней просрочки (штраф) ('n')
          pd.finevaluefixed, -- размер фиксированной пени или штрафа.
          pd.no_fine, -- нет пени ('y'), по умолч. 'n'
          pd.oblig_periodical_presets_id -- общие для всего периода договора настройки для фин.обязательств - чаще всего общие предустановки, но могут быть заданы индивидуально для од+периода.
   into   finepercent,
          RefPart,
          calendar_type,
          fine_cls_kbk_id,
          fine_kind,
          fineondebt,
          finevaluefixed_daily,
          finevaluefixed,
          no_fine,
          period_presets
   from sm.paydocs pd
   where
         pd.id=PDID;

      -- параметры расчетов
 select count(*) into itmp
   from sm.oblig_periodical_presets opp
   where opp.id=period_presets;
if itmp = 1 then
         select opp.charge_fine_method
         into charge_fine_method
         from sm.oblig_periodical_presets opp
         where opp.id=period_presets;
else
         RETURN 0;
  end if;

  select count(*) into itmp
   from sm.payments_plan pp
   inner join SM.CHARGES ch on ch.ID=pp.CHARGES_ID
   where pp.id=obl_plan;
  if itmp = 1 then
           select pp.val,
                  pp.finedate, trim(ch.CHARGE_TYPE)
           into curr_saldo_plan,
                plan_finedate, ChargeType
           from sm.payments_plan pp
           inner join SM.CHARGES ch on ch.ID=pp.CHARGES_ID
           where pp.id=obl_plan;
 else
         RETURN 0;
  end if;

   curr_saldo:=curr_saldo_plan;

    --------------------- А вот нечего начислять если дата плана еще не наступила!!! ------------------------------
   IF  plan_finedate > A_Date  THEN RETURN 0; END IF;

   prev_pay:=plan_finedate;
   Comment_txt:='';
   ------------

   -- проверяем не нужно ли начислять штраф за просрочку
  if (FINE_KIND='F' and FINEVALUEFIXED_DAILY='N') then
     -- проверяем был ли начисления пени на план
     select count(*)
     into cnt
     from sm.payments_plan pp
     where pp.main_plan_id=obl_plan;
     -- если пеня не начислялась, то проверяем, а надо ли, иначе все - штраф второй раз не начисляется
     if cnt=0 then
             -- определяем сальдо по периоду на дату начисления пени, может, уже все заплатили
             Saldo:=-curr_saldo;
             for pay in (select pd.val
									 from sm.payments_distribution pd,
												sm.payments p
									 where pd.PAYMENTS_PLAN_ID=obl_plan and
												 pd.payments_id=p.id and
												 sm.getpaydateforpayment(p.id)<plan_finedate)
             loop
                  Saldo:=Saldo+pay.val;
             end loop;
             -- начисляем штраф, если долг по периоду
             if (Saldo<0) then
                  FineSize:=FINEVALUEFIXED;
                  Comment_txt:='Штраф: за просрочку платежа на '||to_char(plan_finedate,'DD.MM.YY')||'г. '||  to_char(FineSize) || 'руб.';
                  prev_date_calc:=plan_finedate;
                  Result:=FineSize;
             end if;
         end if;
     return Result;
  end if;


  for xx in (
  select t.*
            from (select
            Case  when (Select Value from SM.sm_settings_tab where KEY_NAME='PAYMENT_USE_APPLY_DATE' ) = 'N' and (Select paymethod_id from sm.payments where ID = p.id )!=3
            then  (Select d.docdate
                           from sm.payments p2,
                           sm.documents d
                           where p2.id=p.ID and
                           d.id=p.documents_id)
          else  (Select apply_date from sm.payments where ID = p.id)  end     paydate,

                         pd.val,
                         pp.finedate,
                         'OBLIGATION' type_pay
                  from sm.payments p,
                       sm.payments_distribution pd,
                       sm.payments_plan pp
                  where
                       p.id=pd.payments_id and
                       pd.payments_plan_id=pp.id and
                       pp.id=obl_plan
                        
  union all
                   select
             Case  when (Select Value from SM.sm_settings_tab where KEY_NAME='PAYMENT_USE_APPLY_DATE' ) = 'N' and (Select paymethod_id from sm.payments where ID = p.id )!=3
            then  (Select d.docdate
                           from sm.payments p2,
                           sm.documents d
                           where p2.id=p.ID and
                           d.id=p.documents_id)
          else    (Select apply_date from sm.payments where ID = p.id)  end     paydate,
                          pd.val,
                          pp.finedate,
                          'FINE' type_pay
                   from sm.payments p,
                        sm.payments_distribution pd,
                        sm.payments_plan pp,
                        sm.charges ch
                   where
                        p.id=pd.payments_id and
                        pd.payments_plan_id=pp.id and
                        ch.id=pp.charges_id and
                        ch.factcharge='Y' and
                        ch.charge_type='FINE' and
                        pp.MAIN_PLAN_ID=obl_plan
                  ) t
            where t.paydate<=A_Date
            order by t.paydate, t.finedate
            )
  loop
       if xx.type_pay='OBLIGATION' then
          curr_saldo:=curr_saldo-xx.val;
       end if;
       prev_pay:=xx.paydate;    --дата предыдущего платежа (предыдущего начисления пени, связанного с платежом)
  end loop;

  curr_saldo:=-curr_saldo;

  if prev_pay<plan_finedate then
      prev_pay:=plan_finedate;
  end if;

    if FINE_KIND='R' and charge_fine_assanction='Y' then
     prev_pay:=plan_finedate;
  end if;

  if  curr_saldo < 0 and A_date > prev_pay then
        -- проверяем не нужно ли было сделать начисления пени в связи с изменение ставки рефинансирования
        -- определяем последнее начисление пени до этой даты, если отслеживается ставка рефинансирования
        if  FINE_KIND='R' and charge_fine_assanction='N' then
          begin
           select max(pln.finedate) into prev_charges
                     from sm.payments_plan pln
                     inner join SM.CHARGES ch on ch.ID = pln.CHARGES_ID
                      and  ch.MOVESETS_ID = AMoveSet_ID and ch.OBLIGATIONTYPE_ID =  AObligType_ID
                      and ch.CHARGE_TYPE = 'FINE' and ch.FACTCHARGE = 'Y'
                      where  pln.finedate < A_Date; 
            exception
                      when NO_DATA_FOUND then prev_charges:=prev_pay;
            end;

                if (prev_charges is not null
                      and prev_charges > prev_pay) then
                            prev_pay := prev_charges;
                else
                        prev_charges:=prev_pay;
                end if;

           if (prev_charges=prev_pay) then
               for xx in (select *
                         from sm.refinrates r
                         where r.apply_date >= prev_charges and r.apply_date < A_date
                         order by r.apply_date)
               loop
                   FineSize:=FineSizeForCredit(AMoveSet_ID, AObligType_ID, xx.apply_date, obl_plan, prev_date_calc, Comment_txt,'N', conditions_date, PDID);
                   Select count(*) into itmp from SM.CHARGES ch
                   inner join SM.PAYMENTS_PLAN pp on pp.CHARGES_ID = ch.ID
                   where ch.chargedate = xx.apply_date and ch.paydoc_id = PDID
                   and ch.Comments = Comment_txt || ' - При изм.ставки на ' || to_char(xx.refrate) || ' от ' || to_char(xx.apply_date,'DD.MM.YYYY')
                   and PP.MAIN_PLAN_ID = obl_plan;
                   if itmp = 0 then
                           if FineSize > 0 then

                           --* Морозова
                           select  --+INDEX(cr IDX_CHG_MOVESET_ID)
                           count(*) into c
                           from sm.charges cr
                           where cr.chargedate = xx.apply_date
                                 and cr.paydoc_id = PDID
                                 and trim(cr.comments) = Comment_txt || ' - При изм.ставки на ' ||
                                               to_char(xx.refrate) || ' от ' ||
                                               to_char(xx.apply_date,'DD.MM.YYYY')
                                 and nvl(cr.paysize, 0) = nvl(FineSize, 0)
                                 and cr.charge_type = 'FINE'
                                 and cr.movesets_id = AMoveSet_ID
                                 and cr.obligationtype_id = AObligType_ID
                                 and nvl(cr.calperiod_start, trunc(sysdate)) = nvl(prev_charges, trunc(sysdate))
                                 and nvl(cr.calperiod_end, trunc(sysdate)) = nvl(xx.apply_date, trunc(sysdate))
                                 and nvl(cr.cls_kbk_id, 0) = nvl(fine_cls_kbk_id, 0)
                                 and cr.factcharge = 'Y';
                            --
                              if c = 0 then

                               select sm.seqcharges.nextval into idNext from dual;
                                insert into sm.charges(id, chargedate, finedate, paydoc_id,comments,paysize,charge_type,movesets_id,obligationtype_id,calperiod_start,calperiod_end,cls_kbk_id,factcharge)
--*                                 values(sm.seqcharges.nextval,xx.apply_date,PDID, Comment_txt || ' - При изм.ставки на ' || to_char(xx.refrate) || ' от ' || to_char(xx.apply_date,'DD.MM.YYYY'), FineSize,'FINE',AMoveSet_ID, AObligType_ID,prev_charges,xx.apply_date,fine_cls_kbk_id,'Y');
                                    values(idNext,xx.apply_date,xx.apply_date,PDID, Comment_txt || ' - При изм.ставки на ' || to_char(xx.refrate) || ' от ' || to_char(xx.apply_date,'DD.MM.YYYY'),
																		FineSize,'FINE',AMoveSet_ID, AObligType_ID,prev_charges,xx.apply_date,fine_cls_kbk_id,
																		-- fact_charges  -- <<< Текущий вариант (ниже) приводит к начислению настоящей пени на прогнозные проценты. Включение же fact_charges приводит к тому что и пеня на план.погашения становится прогнозой. TODO: разобраться * * *
																		IsReal );
                               ----- Пишем сопровождающий начисление план его погашения ----
                               select count(*) into c
                                from sm.payments_plan
                                where charges_id = idNext
                                      and obligations_id = OBLIG_ID
                                      and nvl(finedate, trunc(sysdate)) = nvl(xx.apply_date, trunc(sysdate))
                                      and nvl(val, 0) = nvl(FineSize, 0)
                                      and PAYMENTS_PLAN_DRAFT_ID is null
                                      and trim(comments) = trim(Comment_txt)
                                      and nvl(main_plan_id, 0) = nvl(obl_plan, 0);
                               --*
                                if c = 0 then
                                      insert into sm.payments_plan(id,charges_id,obligations_id,finedate,val,PAYMENTS_PLAN_DRAFT_ID,comments,main_plan_id)
                                         values(sm.seqpayments_plan.nextval,idNext, OBLIG_ID, xx.apply_date, FineSize, null,Comment_txt, obl_plan);
                                 end if;       --*

                                ----- Отражаем начисление в Учетных Данных
                                if FirstCharge_Period = 'Y' then
                                 SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext,
                                         xx.apply_date, AMoveSet_ID, null,
                                         Comment_txt || ' - При изм.ставки на ' || to_char(xx.refrate) || ' от ' || to_char(xx.apply_date,'DD.MM.YYYY'),
                                         FineSize, 'FINE',
                                         AObligType_ID, null, null, PDID, prev_charges,
                                         xx.apply_date, fine_cls_kbk_id, null, null, OBLIG_ID, 'Y',  null, 'Y', 'Y');  --- <<< 17.04.2012 <<< ---Добавлены 3 последних опционных параметра - иначе часть начислений стиралась...
                                end if;

                                 if G_CloseDate >= xx.apply_date then
                                      A_reversal_role := 'Исправляющая';
                                 else
                                      A_reversal_role := '';
                                 end if;
                                  SM.OBLIG_ACC_PKG.PartitioningChargesAppliesFine(
                                             Comment_txt|| ' - При изм.ставки на ' || to_char(xx.refrate) || ' от ' || to_char(xx.apply_date,'DD.MM.YYYY') ,
                                             prev_charges,xx.apply_date,
                                             FineSize, AObligType_ID,
                                             AMoveSet_ID, idNext, fine_cls_kbk_id, 'F',
                                            null, A_reversal_role, null);

                               FirstCharge_Period := 'N';
                              end if;          --*
                              FirstCharge := 'N';
                              prev_charges := xx.apply_date;
                           end if;
                    end if;
                   itmp := 0;
               end loop;
               prev_pay:=prev_charges;
           end if;
        end if;

      Expl_Date:=A_DATE-1;
      CurRefinRate:=RefineRateOnDate(Expl_Date);
      if CALENDAR_TYPE=365 then --задержка из расчета 365 дней в году
              DayByFine:=trunc(A_Date)-trunc(prev_pay);
			        --- <<< 23.03.2012 <<< --- Правильно применяем дневную долю  процента для високосного года и способа расчета (360/точно)
							if SM.IsLeapDate(A_Date) then
										DaysInYear := 366;
							else
										DaysInYear := 365;
							end if;
      elsif CALENDAR_TYPE=360 then --задержка из расчета 360 дней в году
						DaysInYear := 360;
            if trunc(A_Date,'MONTH')=trunc(prev_pay,'MONTH') then
             -- если расчет пени идет в пределах месяца, то просто разницу дней, но максимум 30
                 DayByFine:=LEAST(30, trunc(A_Date)-trunc(prev_pay));
            else
            -- при переходе через границу месяца
               -- дней в первом месяце
               p1:=prev_pay-trunc(prev_pay,'MONTH')+1;
               if p1=1 then
                     p1:=30;
               else
                     p1:=Last_Day(prev_pay)-prev_pay+1;
               end if;
               -- дней в последнем месяце
               if A_Date=Last_Day(A_Date) then
                      p2:=30;
               else
                      p2:=A_Date-trunc(A_Date,'MONTH');
               end if;
               -- кол-во месяцев между первым и последним месяцами
               p3:= 30 * (MONTHS_BETWEEN(trunc(A_Date,'MONTH'),trunc(prev_pay,'MONTH')) - 1);

              DayByFine:= p1+p2+p3;
           end if;
       else
            RAISE_APPLICATION_ERROR(-20101, 'Неизвестный тип календаря CALENDAR_TYPE='||CALENDAR_TYPE);
       end if;

       -- Не надо так?
       if CHARGE_FINE_METHOD=1  then
           if prev_pay=plan_finedate then
             DayByFine:=DayByFine+1;
             Expl_Date:=A_DATE;
          end if;
       end if;

       -- определяем размер пени в зависимости от вида пени
       if FINE_KIND='P' then -- процент
            if fineondebt='Y' then
                FinePart:=FinePercent/100;
                FineExpl:=DayByFine || 'д*' || to_char(FinePart,'FM990.9999999')|| '*' || - curr_saldo || 'руб';
                FineSize:=-DayByFine*curr_saldo*FinePart; -- размер пени
            else
                FinePart:=FinePercent/100;
                FineExpl:=DayByFine || 'д*' || to_char(FinePart,'FM990.9999999')|| '*' || curr_saldo_plan || 'руб';
                FineSize:=DayByFine*curr_saldo_plan*FinePart; -- размер пени
            end if;
       elsif FINE_KIND='R' then -- ставка рефинансирования
			--- <<< 23.03.2012 <<< --- Правильно применяем дневную долю  процента для високосного года и способа расчета (360/точно)
				-- Здесь мы берем на себя наглость определить, являлось ли значение введенное пользователем в поле
				--  "доля ставки рефинансирования" - приведением годовой ставки на один день
				--      (что теперь будет отрабатываться автоматом - введенное значение игнорируем),
				-- ИЛИ Это действительно дополнительный мультиплексор!!! (как правило он должен быть не большим, например - 1/3 ставки)
				--      (тогда он будет применен дополнительно к автоматически определяемой дневной ставке).
				-- ИЛИ Это дневной процент уже совмещенный с мультиплексором
				--     (тогда он будет применен прямо...)
				if (RefPart >= 360 and RefPart <= 366) then -- Указано число дней в году - игнорируем
						 Multi := 1;
				elsif (RefPart > 10)	then 	-- Если указали явно не мультиплексор, но и не число дней в году - значит имели в виду уже посчитанное значение с [предполагаемым] мультиплексором
						 DaysInYear := RefPart;  -- оперируем DaysInYear т.к. проще формировать комментарий...
						 Multi := 1;
				else
						Multi := RefPart;
				end if;

						if charge_fine_assanction='N'  then
               if RefPart <> 0 then
                         FinePart:=CurRefinRate/(DaysInYear * Multi * 100); --- <<< 23.03.2012 <<<
												 if fineondebt='Y' then
													    if Multi <> 1 then
																		FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')'|| '*' || - curr_saldo  || 'руб';
															else
																		FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')'|| '*' || - curr_saldo  || 'руб';
															end if;
                              FineSize:=-curr_saldo*DayByFine*FinePart; -- размер пени
                         else
 													    if Multi <> 1 then
																		FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')'|| '*' || curr_saldo_plan  || 'руб';
															else
																		FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')'|| '*' ||curr_saldo_plan  || 'руб';
															end if;
                              FineSize:=curr_saldo_plan*DayByFine*FinePart; -- размер пени
                         end if;
               else
                        FinePart := 0;
                        FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/ !!!ОШИБКА часть ставки рефинансирования указана 0!!! ';
                        FineSize:=0; -- размер пени
                end if;
            else
               if RefPart <> 0 then
                         --FinePart:=CurRefinRate/(RefPart*100);
												 FinePart:=CurRefinRate/(DaysInYear * Multi * 100); --- <<< 23.03.2012 <<<
                         FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||')'; ---- || '*'  || - curr_saldo  || 'руб';    -- ??? Было без суммы ??;
                         FineSize:=DayByFine*FinePart; -- размер пени
                         if fact_charges='N' then -- Если не по платежу, (т.е. прогнозное) - то вычисляем уже полную сумму!!! Учитывать при вызовах данной функции!!!
                                if fineondebt='Y' then
																			if Multi <> 1 then
																						FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')'|| '*' || - curr_saldo  || 'руб';
																			else
																						FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')'|| '*' || - curr_saldo  || 'руб';
																			end if;
																			FineSize:=-FineSize*curr_saldo;
                                else
																			if Multi <> 1 then
																						FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(RefPart)||'/'||to_char(DaysInYear)||')'|| '*' || curr_saldo_plan  || 'руб';
																			else
																						FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/'||to_char(DaysInYear)||')'|| '*' ||curr_saldo_plan  || 'руб';
																			end if;
                                     FineSize:=FineSize*curr_saldo_plan;
                                 end if;
                         end if;
                else
                       FinePart := 0;
                       FineExpl:=DayByFine || 'д*' ||'('||to_Char(CurRefinRate/100,'FM990.9999999')||'/ !!!ОШИБКА часть ставки рефинансирования указана 0!!! ';
                       FineSize:=0; -- размер пени
                end if;
            end if;

       else -- фиксированная сумма пени
            if FINEVALUEFIXED_DAILY='Y' then --фиксированная сумма за каждый день просрочки
                 FinePart:=FINEVALUEFIXED;
                 FineExpl:=DayByFine || 'д*' ||to_char(FinePart,'FM990.9999999') || 'руб';
                 FineSize:=DayByFine*FinePart; -- размер пени
            end if;
       end if;

      if FineSize>0 then
             Result:=FineSize;
            prev_date_calc := prev_pay;
            if FINE_KIND='R' and charge_fine_assanction='Y' and fact_charges='Y'  then
              Comment_txt:='Пеня: c '||prev_pay||' по '||to_char(Expl_Date,'DD.MM.YYYY')||' '||  FineExpl;
            else
              Comment_txt:='Пеня: c '||prev_pay||' по '||to_char(Expl_Date,'DD.MM.YYYY')||' '||  FineExpl  ||'=' || to_char(FineSize,'FM99999999999990.99') || 'руб';
            end if;
       end if;

  end if;

  Return Result;

end FineSizeForCredit;

END;  -- END FULLRECALC_PKG
/
grant execute on SM.FULLRECALC_PKG to SM_ALLUSERS;
grant execute on SM.FULLRECALC_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body GIS_LOADED_OBJECTS
prompt ========================================
prompt
create or replace package body sm.GIS_LOADED_OBJECTS is

IDTables    TablesArray;
Empty       TablesArray;

------------------------------------------------------------------
function InsertID(tableName in varchar2,
                   objId in number)  return number is
  i number;
begin
  if (not tableName is null) and (not objID is null) then        
    i := IDTables.count;
    for x in 1..i loop
      if IDTables(x).TableName = tableName then
        IDTables(x).Items(objId) := 'Y';
        return objId;
      end if;
    end loop;
    IDTables(i+1).TableName := tableName;
    IDTables(i+1).Items(objId) := 'Y';
  end if;
  return objId;
end;
------------------------------------------------------------------
procedure InsertID(tableName in varchar2, IDs in IDsVArray) is
  i number;
  Items IDsArray;
  finded boolean := false;
begin
  if (not tableName is null) then
    i := IDTables.count;
    for x in 1..i loop
      if IDTables(x).TableName = tableName then
        Items := IDTables(x).Items;
        finded := true;
        Exit;
      end if;
    end loop;
    if not finded then
      IDTables(i+1).TableName := tableName;
      Items := IDTables(i+1).Items;
    end if;  
    
    for x in 1..IDs.count loop
      if (not IDs(x) is null) then
        Items(IDs(x)) := 'Y';
      end if;
    end loop;
  end if;
end;
------------------------------------------------------------------
procedure Clear is
begin
  IdTables := Empty;
end;
------------------------------------------------------------------
procedure Remove(tableName in varchar2) is
begin
  for x in 1..IDTables.count loop
    if IDTables(x).TableName = tableName then
      IDTables.delete(x);
      return;
    end if;
  end loop;
end;
------------------------------------------------------------------
function Loaded(tableName in varchar2,
                objId in number) return varchar2 is
begin
  if (not tableName is null) and (not objID is null) then 
  
    for x in 1..IDTables.count loop
      if (IDTables(x).TableName = tableName) and
          (IDTables(x).Items(objId) = 'Y') then
        return 'Y';
      end if;
    end loop;
  
    return 'N';
  end if;
exception
  when no_data_found then
    return 'N';
end;
------------------------------------------------------------------
begin
  -- Initialization
  null;
end GIS_LOADED_OBJECTS;
/
grant execute on SM.GIS_LOADED_OBJECTS to SM_ALLUSERS;
grant execute on SM.GIS_LOADED_OBJECTS to SM_ALL_SELECT;


prompt
prompt Creating package body GMP_PKG
prompt =============================
prompt
create or replace package body sm.GMP_PKG is
----------------------------------------------------------------------
Function GetGMPUIN(AMovesetID in number,
                  AObligationTypeID in number,
                  AChargeType in varchar2) return varchar2
is
retval varchar2(20);
tmpUINFine varchar2(20);
tmpUINPerc varchar2(20);
begin
    if AMovesetID is not null and
       AObligationTypeID is not null
    then
      begin
         select o.obligation_uin         into retval
         from sm.obligations o
         where o.moveset_id=AMovesetID and
         o.obligationtype_id=AObligationTypeID;
      exception
        when NO_DATA_FOUND then retval:=GenerateGMPUin(AMovesetID,'OBLIGATION');
        when others then null;
      end;
       if retval is null then
           update sm.obligations o set o.obligation_uin=retval
           where o.moveset_id=AMovesetID and o.obligationtype_id=AObligationTypeID and o.obligation_uin is null;

           --УИН по пене.
           begin
             select o.fine_uin
             into tmpUINFine
             from sm.obligations o
             where o.moveset_id=AMovesetID and
             o.obligationtype_id=AObligationTypeID;
           exception
             when NO_DATA_FOUND then
                 tmpUINFine:=GenerateGMPUin(AMovesetID,'FINE',retval);
                 update sm.obligations o set o.fine_uin=tmpUINFine
                 where o.moveset_id=AMovesetID and o.obligationtype_id=AObligationTypeID and o.fine_uin is null;
             when others then null;
           end;

          --по процентам
           begin
             select o.percent_uin
             into tmpUINPerc
             from sm.obligations o
             where o.moveset_id=AMovesetID and
             o.obligationtype_id=AObligationTypeID;
           exception
             when NO_DATA_FOUND then
                 tmpUINPerc:=GenerateGMPUin(AMovesetID,'PERCENT',retval);
                 update sm.obligations o set  o.percent_uin=tmpUINPerc
                 where o.moveset_id=AMovesetID and o.obligationtype_id=AObligationTypeID and o.percent_uin is null;
            when others then null;
           end;

         if AChargeType='FINE' then retval:=tmpUINFine; end if;
         if AChargeType='PERCENT' then retval:=tmpUINPerc; end if;

       end if;
    end if;
return(retval);
end GetGMPUIN;
----------------------------------------------------------------------------------
procedure ClearNotTransferData(A_ChargeStatus number)
is
begin
 if A_ChargeStatus in (1,2,3,4)  then
 for i in (select gc.id gChrID, gb.id gBillID, gbi.id gBudIndID, gor.id gOrgID, gac.id gAccID,   gbk.id gBankID
            from sm.gmp_charge gc,
            sm.gmp_bill gb,
            sm.gmp_budgetindex gbi,
            sm.gmp_organization gor,
            sm.gmp_account gac,
            sm.gmp_bank gbk
            where gc.id=gb.id
            and gc.gmp_budgetindex_id=gbi.id
            and gb.supplierorginfo_id=gor.id
            and gor.gmp_account_id=gac.id
            and gac.gmp_bank_id=gbk.id
            and gc.transferdate is null
            and gc.changestatus=A_ChargeStatus)
  loop
    delete from sm.gmp_charge c where c.id=i.gchrid;
    delete from sm.gmp_bill b where b.id=i.gbillid;
    delete from sm.gmp_organization o where o.id=i.gorgid;
    delete from sm.gmp_account a where a.id=i.gaccid;    
    delete from sm.gmp_bank b where b.id=i.gbankid;
    delete from sm.gmp_budgetindex b where b.id=i.gbudindid; 
   
   
   if A_ChargeStatus=1 then
     delete from sm.gmp_chargeidinfo chi where chi.id in (select distinct gcr.gmp_chargeidinfo_id from sm.gmp_charge gcr where gcr.id=i.gchrid);
   end if; 
  end loop;
 end if;
end;
---------------------------------------------------------------------------------
procedure registrMessage(A_MessTxt varchar2, A_ProcName varchar2, A_ParamName varchar2 default null,
  A_paramValue number default null)
is
l_cnt integer;
begin    
 --чтобы избавиться от дублирующих сообщений, будет проверять наличие ошибки по тексту.
 select count(*)
 into l_cnt
 from sm.gmp_messages m
 where trim(m.text_message)=trim(A_MessTxt); 
 
 if l_cnt=0 then 
   insert into sm.gmp_messages
                (id, text_message, proc_name, msg_critical, msg_type, msg_kind, data_table, data_id)
              values
                (sm.seqgmp_messages.nextval,A_MessTxt,A_ProcName,3,3,1,A_ParamName,A_paramValue);              
  end if;              
end;                
----------------------------------------------------------------------------------
Function CalcCharge (ADate in date,
                     AMoveSet_id in number,
                     AOblType_id in number,
                     WhatsNeed in string,
                     WhatsCalc in string default 'ALL'
                    ) return number
is
  charged number(27,2):=0.0;
  payed number(27,2):=0.0;
  RetVal number(27,2);

  CurFineChargeRow sm.CHARGES%ROWTYPE;
  CurFineCharge number;
  DaysTotal integer;
  DaysCharged integer;
  CalcDate date;

begin
-- функция возвращает сумму платежей (используя распределение), начислений или сальдо финансового обязательства,
-- заданного параметрами: AMoveSet_id   - ID операции движения
--                        AObligType_id - ID типа обязательства
-- на 24.00 даты:         ADate
-- при значениях параметра WhatsNeed:
--                       'OBLIGATION' - рассчитывается сумма платежей. начислений или сальдо по обязательству (без процентов!!!)
--                       'FINE'   - рассчитывается сумма платежей. начислений или сальдо по пене
--                       'PERCENT'- рассчитываются проценты
-- при значениях параметра WhatsCalc:
--                       'PAY'    - рассчитывается сумма платежей
--                       'CHARGE' - расчитывается сумма начислений
--                       'ALL'    - рассчитывается сальдо
--
 CalcDate:=trunc(ADate+1);

 IF RTRIM(WhatsNeed)='FINE' THEN -- начало нового блока расчётов по пене

   select nvl(sum(c.paysize),0)
   into Charged
   from (
         select
           cc.paysize     -- дополнительные начисления по пене
         from
          sm.charges cc
         where
          cc.movesets_id=AMoveSet_ID and
          cc.obligationtype_id =AOblType_id and
          cc.chargedate<CalcDate and
          cc.charge_type='FINE' and
          cc.document_id is not null

         union all

         select
           cc.paysize
         from
           sm.charges cc  -- автоматические начисления по пене, не переходящие через заданную дату
         where
           cc.movesets_id=AMoveSet_ID and
           cc.obligationtype_id =AOblType_id and
           cc.calperiod_start<CalcDate and
           cc.calperiod_end<CalcDate and
           cc.charge_type='FINE' and
           cc.document_id is null
          ) c;

    begin
      select *
      into CurFineChargeRow -- автоматические начисления, переходящие через заданную дату
      from
        sm.charges cc
      where
        cc.movesets_id=AMoveSet_ID and
        cc.obligationtype_id =AOblType_id and
        cc.calperiod_start<CalcDate and
        cc.calperiod_end>=CalcDate and
        cc.charge_type='FINE' and
        cc.document_id is null;

        DaysTotal:=CurFineChargeRow.CalPeriod_End-CurFineChargeRow.CalPeriod_Start+1;
        DaysCharged:=CalcDate-CurFineChargeRow.CalPeriod_Start;

        CurFineCharge := CurFineChargeRow.PaySize * (DaysCharged/DaysTotal);

        Charged := Charged + CurFineCharge;
      exception
      when OTHERS then null;
    end;

    select nvl(sum(p.val),0)
    into Payed
    from (
         select  -- платежи по пене, кроме списания долга
           pd.val
         from
           sm.payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_Id=AMoveSet_ID and
           pp.obligationtype_id =AOblType_id and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.paymethod_id<>3 and
           sm.Getpaydateforpayment(pp.id)<CalcDate

         union all

         select   -- платежи по пене - списание долга
           pd.val
         from
           sm.Payments pp,
           sm.payments_distribution pd,
           sm.payments_plan ppl,
           sm.charges ch
         where
           pp.Movesets_id=AMoveSet_id and
           pp.obligationtype_id =AOblType_id and
           pp.paymethod_id=3 and
           pd.payments_id = pp.id and
           ppl.id = pd.payments_plan_id and
           ch.id = ppl.charges_id and
           ch.charge_type = 'FINE' and
           pp.APPLY_DATE<CalcDate
        ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец нового блока расчётов по пене

  IF RTRIM(WhatsNeed)='OBLIGATION' THEN -- начало нового блока расчётов по обязательству (без %!!!)

    select nvl(sum(PaySize),0) --nvl(sum(pp.val),0)  --
    into Charged
    from
      --sm.payments_plan pp,
      sm.charges ch
    where
      Movesets_id=AMoveSet_id  and
      obligationtype_id=AOblType_id and
      CHARGE_TYPE in ('OBLIGATION','OTHER') and
      --pp.charges_id=ch.id and pp.finedate<CalcDate and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.val),0)
    into Payed
    from (
          select  -- платежи по обязательству. кроме списания долга
            pd.val
          from
            sm.payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_Id=AMoveSet_ID and
            pp.obligationtype_id =AOblType_id and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type in ('OBLIGATION','OTHER') and
            pp.paymethod_id<>3 and
            sm.Getpaydateforpayment(pp.id)<CalcDate

          union all

          select   -- платежи по обязательству - списание долга
            pd.val
          from
            sm.Payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_id=AMoveSet_id and
            pp.obligationtype_id =AOblType_id and
            pp.paymethod_id=3 and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type in ('OBLIGATION','OTHER') and
            pp.APPLY_DATE<CalcDate
           ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец нового блока расчётов по обязательству (без %!!!)

  IF RTRIM(WhatsNeed)='PERCENT' THEN -- начало нового блока расчётов по PERCENT

    select nvl(sum(PaySize),0)
    into Charged
    from
      sm.charges
    where
      Movesets_id=AMoveSet_id  and
      obligationtype_id =AOblType_id and
      CHARGE_TYPE = 'PERCENT' and
      CHARGEDATE<CalcDate;

    select nvl(sum(p.val),0)
    into Payed
    from (
          select  -- платежи по PERCENT. кроме списания долга
            pd.val
          from
            sm.payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_Id=AMoveSet_ID and
            pp.obligationtype_id =AOblType_id and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type = 'PERCENT' and
            pp.paymethod_id<>3 and
            sm.Getpaydateforpayment(pp.id)<CalcDate

          union all

          select   -- платежи по PERCENT - списание долга
            pd.val
          from
            sm.Payments pp,
            sm.payments_distribution pd,
            sm.payments_plan ppl,
            sm.charges ch
         where
            pp.Movesets_id=AMoveSet_id and
            pp.obligationtype_id =AOblType_id and
            pp.paymethod_id=3 and
            pd.payments_id = pp.id and
            ppl.id = pd.payments_plan_id and
            ch.id = ppl.charges_id and
            ch.charge_type = 'PERCENT' and
            pp.APPLY_DATE<CalcDate
           ) p;

    if WhatsCalc='PAY' then
      RetVal:=Payed;
    end if;
    if WhatsCalc='CHARGE' then
      RetVal:=Charged;
    end if;
    if WhatsCalc='ALL' then
      RetVal:=Payed-Charged;
    end if;

    RETURN RetVal;

  END IF; -- конец нового блока расчётов по PERCENT

end CalcCharge;

----------------------------------------------------------------------
Function GetCheckDigitForBillID(xChargeCode in varchar2,
                                xWeightNum in number
                               ) return number
is
 nSum number;
 cTmp char(1);
 nTmp number;
 nWeigth number;
 --
 -- Функция возвращает Контрольную сумму для УИН
 --
begin
  nSum := 0;
  for  i in 1..length(xChargeCode)
  loop
    cTmp := substr(xChargeCode, i, 1);

    -- Значение разряда
    if (cTmp in ('1','2','3','4','5','6','7','8','9','0')) then
      nTmp := to_number(cTmp);
    else
      select count(*) into nTmp from sm.gmp_alphaorder a where (a.rus = upper(cTmp) OR a.lat = upper(cTmp));
      if (nTmp = 0) then
        registrMessage('При формировании контрольной суммы УИН ' ||xChargeCode ||' в таблице GMP_ALPHAORDER не найдена буква '||cTmp,
                       'GMP_PKG.GetCheckDigitForBillID');        
        nSum := -1;
        exit;
      end if;
      select a.norder into nTmp from sm.gmp_alphaorder a where (a.rus = upper(cTmp) OR a.lat = upper(cTmp));
      nTmp := mod(nTmp, 10);
    end if;

    -- Вес разряда
    if (i > 10) then
      nWeigth := (i+xWeightNum)-10;
    else
      nWeigth := i+xWeightNum;
    end if;

    nSum := nSum + nTmp * nWeigth;
  end loop;

  return(nSum);
end GetCheckDigitForBillID;
----------------------------------------------------------------------
Function GetSupplierBillID(AObligationTypeID in number,
                           AMovesetID in number,
                           AChargeParam in varchar2,
                           AChargeType in varchar2
                           ) return varchar2

is
 retval varchar2(20);
 -- Функция возвращает Уникальный Идентификатор счёта (Начисления) (УИН)
begin
  if (AObligationTypeID is null or
      AMovesetID is null or
      AChargeParam is null)
  then
    registrMessage('Не удалось получить УИН, т.к. не передан один из обязательных параметров: OBLIGATIONTYPE_ID, MOVESET_IS или GMP_CHARGE_SALDO',
                    'GMP_PKG.GetSupplierBillID','sm.movesets', AMovesetID);   
      retval:='';
  end if;

  --если все одной сумммой.
  if (AChargeParam='SUM') then
      begin
         select obl.obligation_uin
         into retval
         from sm.obligations obl
         where obl.moveset_id=AMovesetID and
         obl.obligationtype_id=AObligationTypeID;
      exception
        when NO_DATA_FOUND then
          retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
        when others then null;
      end;
    if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);  end if;
  end if; --end SUM

  --FINEAPART - пеня отдельной строкой, а основной долг и проценты вместе;
  if (AChargeParam='FINEAPART') then
     if (AChargeType='FINE') then
        begin
             select obl.fine_uin
             into retval
             from sm.obligations obl
             where obl.moveset_id=AMovesetID and
             obl.obligationtype_id=AObligationTypeID;
        exception
          when NO_DATA_FOUND then
              retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
          when others then null;
        end;
         if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType); end if;
     end if;
     if (AChargeType='OBLIGATION') then
        begin
             select obl.obligation_uin
             into retval
             from sm.obligations obl
             where obl.moveset_id=AMovesetID and
             obl.obligationtype_id=AObligationTypeID;
        exception
          when NO_DATA_FOUND then
              retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
          when others then null;
        end;
        if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);  end if;
     end if;
  end if; --end FINEAPART


  --APART - все виды начислений отдельными строками.
  if (AChargeParam='APART') then
    if (AChargeType='FINE') then
        begin
             select obl.fine_uin
             into retval
             from sm.obligations obl
             where obl.moveset_id=AMovesetID and
             obl.obligationtype_id=AObligationTypeID;
        exception
          when NO_DATA_FOUND then
              retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
          when others then null;
        end;
       if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);  end if;
     end if;
     if (AChargeType='OBLIGATION') then
        begin
             select obl.obligation_uin
             into retval
             from sm.obligations obl
             where obl.moveset_id=AMovesetID and
             obl.obligationtype_id=AObligationTypeID;
        exception
          when NO_DATA_FOUND then
              retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
          when others then null;
        end;
       if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType); end if;
     end if;
     if (AChargeType='PERCENT') then
        begin
             select obl.percent_uin
             into retval
             from sm.obligations obl
             where obl.moveset_id=AMovesetID and
             obl.obligationtype_id=AObligationTypeID;
        exception
          when NO_DATA_FOUND then
              retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType);
          when others then null;
        end;
         if retval is null then  retval:=GetGMPUIN(AMovesetID,AObligationTypeID,AChargeType); end if;
     end if;
  end if; --end APART
 return(retval);
end GetSupplierBillID;
