Function GetUnifiedPayerID(xPayer in sm.clients%ROWTYPE,
                           xChargeID in number
                           ) return varchar2
is
 retval varchar2(25);
 sSnils varchar2(11);
 sInn varchar2(10);
 --
 -- Функция возвращает Единый Идентификатор Плательщика
 --
begin
  -- ЮЛ
  if (xPayer.client_types_id <> 1) then
    if (xPayer.inn is not null) then
      sInn := substr(trim(xPayer.inn), 1, 10);
      if (length(trim(sInn)) = 10) then
        if (xPayer.kpp is not null) then
          if (length(trim(xPayer.kpp)) = 9) then

            retval := '2'||sInn||trim(xPayer.kpp);

          else
            registrMessage('Ошибка в КПП плательщика '||xPayer.Name||': КПП должен быть 9-символьным',
              'GMP_PKG.GetUnifiedPayerID','sm.movesets', xChargeID);            
          end if;
        else
           registrMessage('Не указан КПП плательщика '||xPayer.Name,
            'GMP_PKG.GetUnifiedPayerID','sm.movesets', xChargeID);         
        end if;
      else
          registrMessage('Ошибка в ИНН плательщика '||xPayer.Name||': ИНН ЮЛ должен быть 10-символьным',
          'GMP_PKG.GetUnifiedPayerID','sm.movesets', xChargeID);       
      end if;
    else
      registrMessage('Не указан ИНН плательщика '||xPayer.Name,
        'GMP_PKG.GetUnifiedPayerID','sm.movesets', xChargeID);     
    end if;
  -- ФЛ
  else
    begin
    select t.snils into sSnils from sm.privates t where t.clients_id = xPayer.id;
      exception
      when OTHERS then null;
    end;
    if (sSnils is not null) then
      if (length(trim(sSnils)) = 11) then

        retval := '1'||trim(sSnils);

      else
        registrMessage('Ошибка в СНИЛС плательщика '||xPayer.Name||': СНИЛС должен быть 11-символьным',
          'GMP_PKG.GetUnifiedPayerID','sm.movesets', xChargeID);       
      end if;
    end if;

  end if;

  return(retval);
end GetUnifiedPayerID;
----------------------------------------------------------------------
Function GetAltPayerID(xPayerName in varchar2,
                      xPayerInn in varchar2,
                      xPasportNo in varchar2,
                      xCitizenship in varchar2,
                      xChargeID in number
                      ) return varchar2
is
 retval varchar2(25);
 sPasportno varchar2(20);
 sCitizenship varchar2(3);
 nTmp number;
 --
 -- Функция возвращает Альтернативный Идентификатор Плательщика (ФЛ)
 --
begin
  if (xPayerInn is not null) then
    if (length(trim(xPayerInn)) <> 12) then
      registrMessage('Ошибка в ИНН плательщика '||xPayerName||': ИНН физ. лица должен быть 12-символьным',
        'GMP_PKG.GetAltPayerID','sm.movesets', xChargeID);      
    else
      retval := '21' ||lpad(trim(xPayerInn), 20, '0') ||'643';
    end if;

  else
    sPasportno := trim(xPasportNo);
    sCitizenship := trim(xCitizenship);
    if (sPasportno is not null and sCitizenship is not null) then
      select count(*) into nTmp from sm.privates t where trim(t.pasportno) = xPasportno;
      if (nTmp > 1) then
        sPasportno := null;
        registrMessage('Неуникальный номер ' ||xPasportno ||' паспорта плательщика '||xPayerName,
          'GMP_PKG.GetAltPayerID','sm.movesets', xChargeID);        
      end if;
    else
      registrMessage('Не указан ни один из идентифицирующих реквизитов плательщика '||xPayerName||': СНИЛС/ ИНН/ серия и номер паспорта, гражданство)',
        'GMP_PKG.GetAltPayerID','sm.movesets', xChargeID);     
    end if;

    if (sPasportno is not null and xCitizenship is not null) then
      sPasportno := replace(sPasportno, '№', '');
      sPasportno := replace(sPasportno, '-', '');
      sPasportno := replace(sPasportno, ' ', '');
      retval := '01' ||lpad(sPasportno, 20, '0') ||lpad(xCitizenship, 3, '0');
    end if;
  end if;

  return(retval);
end GetAltPayerID;
