Procedure SaveInsUpdCharge(
                           xChangestatus in varchar2,
                           vkbk in varchar2,
                           xChargedate in date,
                           xComments in varchar2,
                           xPaysize in number,
                           recepients in sm.recepients%ROWTYPE,
                           payerType in varchar2,
                           supplierBillID in varchar2,
                           unifiedPayerID in varchar2,
                           altPayerID in varchar2,
                           chargeIDInfoID in number
                           )
as
 --
 -- Процедура формирует информацию о добавленном или измененном начислении SAUMI
 -- и сохраняет ее в таблицах с префиксом GMP_ в названии
 -- для последующей передачи в ГИС ГМП
 --
  gmpChargeID NUMBER(27);
  gmpBudgetindexID NUMBER(27);
  gmpAccountID NUMBER(27);
  gmpSupplierOrgID NUMBER(27);
  gBankID NUMBER(27);

begin

  select sm.seqgmp_budgetindex.nextval into gmpBudgetindexID from dual;

  insert into sm.gmp_budgetindex
    (id, status, paymenttype, purpose, taxperiod, taxdocnumber, taxdocdate)
  values
    (gmpBudgetindexID, payerType, 'ПЛ', 'ТП', '0', '0', '0');


  select sm.SEQGMP_CHARGE.nextval into gmpChargeID from dual;

  insert into sm.GMP_CHARGE
    (id,
    changestatus,
    treasurebranch,
    kbk,
    okato,
    gmp_budgetindex_id,
    applicationid, altpayeridentifier, unifiedpayeridentifier,
    rowcreatedate,gmp_chargeidinfo_id)
  values
    (gmpChargeID,
    xChangestatus,
    gNameOFK,
    vkbk,
    nvl(replace(recepients.okato_old, ' '), ' '),
    gmpBudgetindexID,
    null, altPayerID, unifiedPayerID,
    sysdate, chargeIDInfoID);

  --gBankID := sm.seqgmp_bank.nextval;

  select sm.seqgmp_bank.nextval into gBankID from dual;

  insert into sm.gmp_bank
    (id, name, correspondentbankaccount, bik)
  values
    (gBankID, recepients.bankname, recepients.corraccount, recepients.bik);

  --gmpAccountID := sm.seqgmp_account.nextval;
  select sm.seqgmp_account.nextval into gmpAccountID from dual;

  insert into sm.gmp_account
    (id, account, subaccount, gmp_bank_id, kind)
  values
    (gmpAccountID, recepients.account, null, gBankID, '1');

  --gmpSupplierOrgID := sm.seqgmp_organization.nextval;
  select sm.seqgmp_organization.nextval into gmpSupplierOrgID from dual;

  insert into sm.gmp_organization
    (id, name, inn, kpp, ogrn, gmp_account_id)
  values
    (gmpSupplierOrgID, recepients.name, recepients.inn, recepients.kpp, recepients.ogrn, gmpAccountID);

  insert into sm.GMP_BILL
    (id, supplierbillid, mainsupplierbillid, version, billdate, validuntil, supplierorginfo_id, billfor, totalamount)
  values
    (gmpChargeID, supplierBillID, null, gVersion, xChargedate, null, gmpSupplierOrgID, substr(xComments, 1, 255), xPaysize);

  commit;
end SaveInsUpdCharge;
----------------------------------------------------------------------
Procedure SaveDeletedCharge(xID in number)
as
 --
 -- Процедура сохраняет информацию об удаленном начислении SAUMI
 -- в таблицах с префиксом GMP_ в названии
 -- для последующей передачи в ГИС ГМП
 --
  gmpChargeID NUMBER(27);
  gmpBudgetindexID NUMBER(27);
  gmpAccountID NUMBER(27);
  gmpSupplierOrgID NUMBER(27);
  gmpBankID NUMBER(27);

  oldBudgetindexID NUMBER(27);
  oldAccountID NUMBER(27);
  oldSupplierOrgID NUMBER(27);
  oldBankID NUMBER(27);
  gmpCh sm.gmp_charge%ROWTYPE;
begin
      -- GMP_CHARGE --------------
      select * into gmpCh from (select t.*
                      from sm.gmp_charge t
                      where t.gmp_chargeidinfo_id = xID  --and t.changestatus != '3' -- ???
                      order by t.changestatus desc)
        where rownum = 1;

      select t.gmp_budgetindex_id into oldBudgetindexID from sm.GMP_CHARGE t where t.id = gmpCh.id;

      --gmpBudgetindexID := sm.seqgmp_budgetindex.nextval;
      select sm.seqgmp_budgetindex.nextval into gmpBudgetindexID from dual;

      insert into sm.gmp_budgetindex
        (id, status, paymenttype, purpose, taxperiod, taxdocnumber, taxdocdate)
      select
        gmpBudgetindexID, t.status, t.paymenttype, t.purpose, t.taxperiod, t.taxdocnumber, t.taxdocdate
        from sm.gmp_budgetindex t where t.id = oldBudgetindexID;

      --gmpChargeID := sm.SEQGMP_CHARGE.nextval;
      select sm.SEQGMP_CHARGE.nextval into gmpChargeID from dual;


      insert into sm.GMP_CHARGE
        (id,
        changestatus,
        treasurebranch,
        kbk,
        okato,
        gmp_budgetindex_id,
        applicationid, altpayeridentifier, unifiedpayeridentifier,
        rowcreatedate, gmp_chargeidinfo_id)
      values
        (gmpChargeID,
        '3',
        gmpCh.treasurebranch,
        gmpCh.kbk,
        gmpCh.okato,
        gmpBudgetindexID,
        gmpCh.applicationid, gmpCh.altpayeridentifier, gmpCh.unifiedpayeridentifier,
        sysdate, gmpCh.gmp_chargeidinfo_id);

      -- GMP_BILL --------------
      select bl.supplierorginfo_id, o.gmp_account_id, a.gmp_bank_id
        into oldSupplierOrgID, oldAccountID, oldBankID
        from sm.GMP_BILL bl
        inner join sm.gmp_organization o on o.id = bl.supplierorginfo_id
        inner join sm.gmp_account a on a.id = o.gmp_account_id
        inner join sm.gmp_bank bk on bk.id = a.gmp_bank_id
        where bl.id = gmpCh.ID;

      --gmpBankID := sm.seqgmp_bank.nextval;
      select sm.seqgmp_bank.nextval into gmpBankID from dual;

      insert into sm.gmp_bank
        (id, name, correspondentbankaccount, bik)
      select
        gmpBankID, t.name, t.correspondentbankaccount, t.bik
        from sm.gmp_bank t where t.id = oldBankID;

      --gmpAccountID := sm.seqgmp_account.nextval;
      select sm.seqgmp_account.nextval into gmpAccountID from dual;

      insert into sm.gmp_account
        (id, account, subaccount, gmp_bank_id, kind)
      select
        gmpAccountID, t.account, t.subaccount, gmpBankID, t.kind
        from sm.gmp_account t where t.id = oldAccountID;

      --gmpSupplierOrgID := sm.seqgmp_organization.nextval;
      select sm.seqgmp_organization.nextval into gmpSupplierOrgID from dual;

      insert into sm.gmp_organization
        (id, name, inn, kpp, ogrn, gmp_account_id)
      select
        gmpSupplierOrgID, t.name, t.inn, t.kpp, t.ogrn, gmpAccountID
        from sm.gmp_organization t where t.id = oldSupplierOrgID;

      insert into sm.GMP_BILL
        (id, supplierbillid, mainsupplierbillid, version, billdate, validuntil, supplierorginfo_id, billfor, totalamount)
      select
        gmpChargeID, t.supplierbillid, t.mainsupplierbillid, gVersion, t.billdate, t.validuntil, gmpSupplierOrgID, t.billfor, t.totalamount
        from sm.GMP_BILL t where t.id = gmpCh.id;

      COMMIT;
end SaveDeletedCharge;
