create or replace package body sm.KFX_PKG is
FUNCTION GETFX1_ID(NUM_KFX_ID IN NUMBER, KFX_Dict1_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
-- 
-- функция возвращает значение коэффициента, основанного на одном справочнике
-- заданного параметром:  NUM_KFX_ID   - ID коэффициента
--                        KFX_Dict1_ID - ID элемента справочника 
-- на заданную дату:      ForDate
--
BEGIN

   Result:=null;

   for xx in (select * from sm.kfxvalues kv  where
                                               kv.kfx_id=NUM_KFX_ID and 
                                               kv.dict1_id=kfx_dict1_id and
                                               kv.dict2_id is null and
                                               kv.dict3_id is null and
                                               kv.since_date<=fordate order by kv.since_date desc)
   loop
     Result:=xx.kfx_value;
     exit;
   end loop; 

   RETURN Result;
 
END GETFX1_ID;
--------------------------------------------------------------------------------------
FUNCTION GETFX2_ID(NUM_KFX_ID IN NUMBER, KFX_Dict1_ID IN NUMBER, KFX_Dict2_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
--
-- функция возвращает значение коэффициента, основанного на двух справочниках
-- заданного параметром:  NUM_KFX_ID   - ID коэффициента
--                        KFX_Dict1_ID - ID элемента из первого справочника 
--                        KFX_Dict2_ID - ID элемента из второго справочника 
-- на заданную дату:      ForDate
--
BEGIN

   Result:=null;

   for xx in (select * from sm.kfxvalues kv  where 
                                               kv.kfx_id=NUM_KFX_ID and
                                               kv.dict1_id=KFX_DICT1_ID and
                                               kv.dict2_id=KFX_Dict2_ID and
                                               kv.dict3_id is null and
                                               kv.since_date<=fordate order by kv.since_date desc)
   loop
     Result:=xx.kfx_value;
     exit;
   end loop; 
   
   RETURN Result;
  
END GETFX2_ID;
--------------------------------------------------------------------------------------
FUNCTION GETFX3_ID(NUM_KFX_ID IN NUMBER, KFX_Dict1_ID IN NUMBER, KFX_Dict2_ID IN NUMBER, KFX_Dict3_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
--
-- функция возвращает значение коэффициента, основанного на трёх справочниках
-- заданного параметром:  NUM_KFX_ID   - ID коэффициента
--                        KFX_Dict1_ID - ID элемента из первого справочника 
--                        KFX_Dict2_ID - ID элемента из второго справочника 
--                        KFX_Dict3_ID - ID элемента из третьего справочника 
-- на заданную дату:      ForDate
--
BEGIN

   Result:=null;

   for xx in (select * from sm.kfxvalues kv  where 
                                               kv.kfx_id=NUM_KFX_ID and
                                               kv.dict1_id=KFX_DICT1_ID and
                                               kv.dict2_id=KFX_Dict2_ID and
                                               kv.dict3_id=KFX_Dict3_ID and
                                               kv.since_date<=fordate order by kv.since_date desc)
   loop
     Result:=xx.kfx_value;
     exit;
   end loop; 
   
   RETURN Result;
  
END GETFX3_ID;
--------------------------------------------------------------------------------------

FUNCTION GETFX1(Name_KFX IN Varchar2, KFX_Dict1_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
  KFX_ID NUMBER(27);
--
-- функция возвращает значение коэффициентаб основанного на одном справочнике
-- заданного параметром:  NAME_KFX  - краткое наименование коэффициента
--                        KFX_Dict1_ID - ID элемента справочника 
-- на заданную дату:      ForDate
--
BEGIN

  Result:=null;

  begin
    select kv.id
    into KFX_ID
    from 
      sm.kfxnames kv
    where 
      kv.shortname=NAME_KFX and
      rownum<2;
  
    Result:=GETFX1_ID(KFX_ID,KFX_Dict1_ID, ForDate);
  exception
    when others then
      Result:=null;  
  end;  
  
  RETURN Result;
  
END GETFX1;
--------------------------------------------------------------------------------------
FUNCTION GETFX2(NAME_KFX IN VARCHAR2, KFX_Dict1_ID IN NUMBER, KFX_Dict2_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
  KFX_ID NUMBER(27);
--
-- функция возвращает значение коэффициента, основанного на двух справочниках
-- заданного параметром:  NAME_KFX  - краткое название коэффициента
--                        KFX_Dict1_ID - ID элемента из первого справочника 
--                        KFX_Dict2_ID - ID элемента из второго справочника 
-- на заданную дату:      ForDate
--
BEGIN

  Result:=null;
 
  begin
    select kv.id
    into KFX_ID
    from 
      sm.kfxnames kv
    where 
      kv.shortname= NAME_KFX and
      rownum<2;
  
    Result:=GETFX2_ID(KFX_ID,KFX_Dict1_ID, KFX_Dict2_ID, ForDate);
  exception
    when others then
      Result:=null;  
  end;
    
  RETURN Result;
 
END GETFX2;
--------------------------------------------------------------------------------------
FUNCTION GETFX3(NAME_KFX IN VARCHAR2, KFX_Dict1_ID IN NUMBER, KFX_Dict2_ID IN NUMBER, KFX_Dict3_ID IN NUMBER, ForDate IN DATE) return number is
  Result sm.kfxvalues.kfx_value%Type;
  KFX_ID NUMBER(27);
--
-- функция возвращает значение коэффициента, основанного на трёх справочниках
-- заданного параметром:  NAME_KFX  - краткое название коэффициента
--                        KFX_Dict1_ID - ID элемента из первого справочника 
--                        KFX_Dict2_ID - ID элемента из второго справочника 
--                        KFX_Dict3_ID - ID элемента из третьего справочника 
-- на заданную дату:      ForDate
--
BEGIN

  Result:=null;
 
  begin
    select kv.id
    into KFX_ID
    from 
      sm.kfxnames kv
    where 
      kv.shortname= NAME_KFX and
      rownum<2;
  
    Result:=GETFX3_ID(KFX_ID,KFX_Dict1_ID, KFX_Dict2_ID, KFX_Dict3_ID, ForDate);
  exception
    when others then
      Result:=null;  
  end;
    
  RETURN Result;
 
END GETFX3;
--------------------------------------------------------------------------------------
end KFX_PKG;
