  ---------------------------------------------------------------------
  FUNCTION DescribeMoveList(mlist IN varchar2, WithMoveType in char := 'N')
    RETURN varchar2 is
    s  varchar2(100);
    s1 varchar2(100);
    i  integer;
    n  integer;
    r  varchar2(100);
  begin
    r := '';
    s := ltrim(rtrim(mlist)) || ' ';
    i := instr(s, ' ');
    while i <> 0 loop
      s1 := substr(s, 1, i - 1);
      s  := substr(s, i + 1);
      n  := to_number(s1);

      if WithMoveType = 'Y' then
        select rtrim(movetype.name) || ' с ' || PostingDate ||
               decode(EndDate, null, '', ' по' || Enddate) || ' ' ||
               rtrim(clients.name)
          into s1
          from sm.clients, sm.movements, sm.movetype
         where movetype.id = movements.movetype_id and
               clientsto_id = clients.id and movements.id = n;
      else
        select rtrim(clients.name) || ' с ' || PostingDate ||
               decode(EndDate, null, '', ' по ' || Enddate)
          into s1
          from sm.clients, sm.movements
         where clientsto_id = clients.id and movements.id = n;
      end if;

      r := r || s1 || ', ';
      i := instr(s, ' ');
    end loop;

    if length(r) > 0 then
      r := substr(r, 1, length(r) - 2);
    end if;

    return r;
  end;

END;
/
grant execute on SM.M to SM_ALLUSERS;
grant execute on SM.M to SM_ALL_SELECT;


prompt
prompt Creating package body MOVE_ACC_PKG
prompt ==================================
prompt
create or replace package body sm.MOVE_ACC_PKG is

CloseDate DATE := SM.Getparameter('ENDPERIOD') ;


---------------------------------------------------------------------------------------------------------------------------------------------------------
-----Сторнирование записи в  MOVE_ACC на дату------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure STORNO(moveAcc NUMBER, dateAcc DATE)
   is
begin
    Insert into SM.MOVE_ACC (ID, APPLY_DATE,  OPER_DATE,  WRITE_DATE, END_DATE,  OBJECT_ID, MOVEITEM_ID, STATE_ID, DESCRIPTION, OPERATION, OBJECT, ACC, SALDO, COST,CURRENCY_ID,AMOUNT,UNIT_ID, DC, CORR_FLAG, REVERSAL_ROLE, REVERSALLINK_ID, SEQ, DOCUM, MOVESET_ID)
         Select SM.SEQMOVE_ACC.NEXTVAL, CloseDate+1, dateAcc, sysdate, CloseDate+1,  OBJECT_ID, MOVEITEM_ID, STATE_ID, 'Сторнировано: ' || DESCRIPTION, OPERATION, OBJECT, ACC, SALDO-COST,   -1*COST,CURRENCY_ID, -1*AMOUNT,UNIT_ID, DC, 'Y', 'Сторнирующая (красн.)', ID, SEQ, DOCUM, MOVESET_ID
         from SM.MOVE_ACC where ID = moveAcc;
    Update SM.MOVE_ACC set CORR_FLAG = 'Y', REVERSAL_ROLE='Сторнированная', REVERSALLINK_ID = SM.SEQMOVE_ACC.CURRVAL, OPER_DATE=dateAcc, END_DATE=CloseDate  where  ID = moveAcc;
end;

---------------------------------------------------------------------------------------------------------------------------------------------------------
----- Отражение движения обьекта  MOVE_ACC на дату------------------
----- Кроме основного применения по факту участию объекта в операции (moveID),
-----      -   срабатывает и для внесистемных записей по поводу переоценки (astateID при moveID is null).
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure OBJ_MOVE_ACC (moveID NUMBER, obID NUMBER, astateID NUMBER, dAcc DATE, dEnd DATE, nCost NUMBER, nSald NUMBER, aDescr VARCHAR2, aOper VARCHAR2, aObj VARCHAR2, aAcc VARCHAR2, amvtype CHAR, aSeq NUMBER, aDocum VARCHAR2, msID NUMBER)
is
 itmp2 NUMBER := 0;
 amID NUMBER(27);
 amDate DATE;
 amCost NUMBER(27,2) := 0;
 shortAcc VARCHAR2(3) := substr(aAcc,2,3);
 rRole VARCHAR(200) := '-';

begin
          -- Только если есть оборот
          --if nCost = 0 then
          --      RETURN;
          --end if;

          if (moveID is null and astateID > 0) then -- вариант при переоценке
                  Select count(*) into itmp2  from SM.MOVE_ACC ma where ma.STATE_ID = astateID and ma.MOVEITEM_ID is null
                            and ma.SEQ = aSeq and ma.DC = amvtype and ma.ACC like '%' || shortAcc || '%';
          elsif (moveID > 0)  then -- основной вариант - по поводу участия объекта в операции
                  Select count(*) into itmp2  from SM.MOVE_ACC ma where ma.MOVEITEM_ID = moveID
                            and ma.SEQ = aSeq and ma.DC = amvtype and ma.ACC like '%' || shortAcc || '%';
          end if;

                     ------------------
                     --(случай довольно редкий, когда списывали без учета амортизации, затем добавили 104 счет и прежнее списание нужно удалить)
                                --- предварительно - проверка и возможно сторнирование ранее написанных учетных записей по прежним периодам:                                
                                ----- 28.10.2008 --не обязательно по прежним периодам, не обязательно Не было учетных данных
                                for xprev in (Select ma.ID
                                        from SM.MOVE_ACC ma
                                        where ma.MOVEITEM_ID = moveID
                                        and (ma.REVERSAL_ROLE <> 'Сторнирующая (красн.)' and ma.REVERSAL_ROLE <> 'Сторнированная')
                                        and ma.ACC like '%' || shortAcc || '%' and ma.DC = amvtype
                                        and ma.apply_date <= CloseDate+1  -- 28.10.2008 было < когда этот цикл был только для случая "--Не было учетных данных - написать -- В закрытом периоде"
                                        and ma.cost <> nCost
                                        and ma.SEQ <> aSeq and ma.SEQ=0
                                        order by ma.WRITE_DATE desc)
                                loop
                                       STORNO( xprev.ID,  dAcc);  -- 28.10.2008 в открытом периоде тоже сторнируем, хотя лучше удалять
                                end loop;
                      -------------------------
                      
          if itmp2 = 0 then -- Не было учетных данных - написать
                     -- В закрытом периоде
                     if dAcc <=  CloseDate then -- 13.10.2011 -- считаем, что ЗП включительно по CloseDate --if dAcc < CloseDate then
                          Insert into SM.MOVE_ACC (ID, APPLY_DATE,  OPER_DATE, WRITE_DATE, END_DATE, OBJECT_ID, MOVEITEM_ID, STATE_ID, DESCRIPTION, OPERATION, OBJECT, ACC, SALDO, COST,CURRENCY_ID,AMOUNT,UNIT_ID, DC, CORR_FLAG, REVERSAL_ROLE, REVERSALLINK_ID, SEQ, DOCUM, MOVESET_ID)
                             values(SM.SEQMOVE_ACC.NEXTVAL, CloseDate+1, dAcc, sysdate, dEnd, obID, moveID, astateID, 'Поздним периодом: ' || aDescr, aOper, aObj, aAcc, nSald, nCost, null, 1, null, amvtype, 'Y', 'Поздним периодом', null, aSeq, aDocum, msID);
                     else -- В открытом периоде
                           Insert into SM.MOVE_ACC (ID, APPLY_DATE,  OPER_DATE,  WRITE_DATE, END_DATE,  OBJECT_ID, MOVEITEM_ID, STATE_ID, DESCRIPTION, OPERATION, OBJECT, ACC, SALDO, COST,CURRENCY_ID,AMOUNT,UNIT_ID, DC, CORR_FLAG, REVERSAL_ROLE, REVERSALLINK_ID, SEQ, DOCUM, MOVESET_ID)
                             values(SM.SEQMOVE_ACC.NEXTVAL, dAcc, dAcc, sysdate, dEnd, obID, moveID, astateID, aDescr, aOper, aObj, aAcc, nSald, nCost, null, 1, null, amvtype, 'N', '-', null, aSeq, aDocum, msID);
                     end if;
                     commit work;
                     
            elsif itmp2 > 0 then -- Уже есть учетные данные - сверить, и если изменились - переписать.
                  -- Находим прежнюю запись, или последнюю из ИСПРАВЛЯЮЩИХ - если уже было[и] сторнирование[ия] (реализация повторных сторнирований).
                      if (moveID is null and astateID > 0) then -- вариант при переоценке
                              BEGIN
                                  Select mac.ID, mac.APPLY_DATE,  mac.COST, mac.REVERSAL_ROLE  into amID, amDate, amCost, rRole
                                  from (Select ma.ID, ma.APPLY_DATE,  ma.COST, ma.REVERSAL_ROLE
                                  from SM.MOVE_ACC ma
                                  where ma.STATE_ID = astateID and ma.MOVEITEM_ID is null
                                  and (ma.REVERSAL_ROLE <> 'Сторнирующая (красн.)' and ma.REVERSAL_ROLE <> 'Сторнированная')
                                  and ma.ACC like '%' || shortAcc || '%' and ma.DC = amvtype and ma.SEQ = aSeq
                                  order by ma.WRITE_DATE desc) mac
                                  where ROWNUM=1;
                              EXCEPTION
                                     When NO_DATA_FOUND then
                                            NULL;
                              END;
                      elsif (moveID > 0) then -- основной вариант - по поводу участия объекта в операции
                              BEGIN
                                  Select mac.ID, mac.APPLY_DATE,  mac.COST, mac.REVERSAL_ROLE  into amID, amDate, amCost, rRole
                                  from (Select ma.ID, ma.APPLY_DATE,  ma.COST, ma.REVERSAL_ROLE
                                  from SM.MOVE_ACC ma
                                  where ma.MOVEITEM_ID = moveID
                                  and (ma.REVERSAL_ROLE <> 'Сторнирующая (красн.)' and ma.REVERSAL_ROLE <> 'Сторнированная')
                                  and ma.ACC like '%' || shortAcc || '%' and ma.DC = amvtype and ma.SEQ = aSeq
                                  order by ma.WRITE_DATE desc) mac
                                  where ROWNUM=1;
                               EXCEPTION
                                     When NO_DATA_FOUND then
                                            NULL;
                              END;
                      end if;

                      -- Обе даты в открытом периоде - ничего не исправляем, сумму и изменяем учетную и оперативную даты
                     if  (amDate <> dAcc or amCost <> nCost)  and amDate > CloseDate and dAcc > CloseDate then
                             Update SM.MOVE_ACC set APPLY_DATE = dAcc, OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE= dEnd, COST= nCost, SALDO= nSald where  ID = amID;

                     -- Обе даты в закрытом периоде
                     elsif  amDate <= CloseDate and dAcc <= CloseDate then
                             if amDate <> dAcc and amCost = nCost  and rRole  <> 'Сторнированная'  and rRole <> 'Сторнирующая (красн.)'    then --  изменилась только дата -  только уточняем оперативную дату
                                    if (rRole = 'Исправляющая'  OR rRole = 'Поздним периодом') then
                                       Update SM.MOVE_ACC set OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE= dEnd  where  ID = amID;
                                    else
                                       Update SM.MOVE_ACC set REVERSAL_ROLE='Сдвинута дата в закрытом периоде', OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE= dEnd  where  ID = amID;
                                    end if;
                             elsif amDate = dAcc and amCost = nCost then --  изменилась только дата (сначала изменили, затем вернули прежнее значение)
                                    Update SM.MOVE_ACC set OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE= dEnd  where  ID = amID;
                             elsif  amCost <> nCost then -- изменилась сумма - типичное сторнирование прежней записи
                                    MOVE_ACC_PKG.STORNO(amID, dAcc);
                                    Insert into SM.MOVE_ACC (ID, APPLY_DATE,  OPER_DATE,  WRITE_DATE, END_DATE, OBJECT_ID, MOVEITEM_ID, STATE_ID, DESCRIPTION, OPERATION, OBJECT, ACC, SALDO, COST,CURRENCY_ID,AMOUNT,UNIT_ID, DC, CORR_FLAG, REVERSAL_ROLE, REVERSALLINK_ID, SEQ, DOCUM, MOVESET_ID)
                                     values(SM.SEQMOVE_ACC.NEXTVAL, CloseDate+1, dAcc, sysdate, dEnd, obID, moveID, astateID, 'Исправление: ' || aDescr, aOper, aObj, aAcc, nSald, nCost, null, 1, null, amvtype, 'Y', 'Исправляющая', amID, aSeq, aDocum, msID);
                             end if;

                     -- Сдвиг даты из закрытого в открытый период - типичное сторнирование прежней записи
                     elsif amDate <= CloseDate and dAcc > CloseDate then
                            MOVE_ACC_PKG.STORNO(amID, dAcc);
                            Insert into SM.MOVE_ACC (ID, APPLY_DATE,  OPER_DATE,  WRITE_DATE, END_DATE,  OBJECT_ID, MOVEITEM_ID, STATE_ID, DESCRIPTION, OPERATION, OBJECT, ACC, SALDO, COST,CURRENCY_ID,AMOUNT,UNIT_ID, DC, CORR_FLAG, REVERSAL_ROLE, REVERSALLINK_ID, SEQ, DOCUM, MOVESET_ID)
                             values(SM.SEQMOVE_ACC.NEXTVAL, dAcc, dAcc, sysdate, dEnd, obID, moveID, astateID, 'Исправление: ' || aDescr, aOper, aObj, aAcc, nSald, nCost, null, 1, null, amvtype, 'Y', 'Исправляющая', amID, aSeq, aDocum, msID);

                     -- Сдвиг даты из открытого в закрытый период - в закрытом ничего не трогаем, метим запись "Поздним периодом", и "сдвигаем" ее на начало периода (для максимальной достовености)
                     elsif amDate > CloseDate and dAcc <= CloseDate and rRole  <> 'Сторнированная'  and rRole <> 'Сторнирующая (красн.)'  then   --  and rRole <> 'Исправляющая'
                            if (rRole = 'Исправляющая') then
                                Update SM.MOVE_ACC set  APPLY_DATE=CloseDate+1, OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE=dEnd, COST= nCost, SALDO= nSald where  ID = amID;
                            else
                                Update SM.MOVE_ACC set  REVERSAL_ROLE= 'Поздним периодом', APPLY_DATE=CloseDate+1, OPER_DATE=dAcc, WRITE_DATE=sysdate, END_DATE=dEnd, COST= nCost, SALDO= nSald where  ID = amID;
                            end if;  

                     end if;
                     commit work;

            end if;

end;

---------------------------------------------------------------------------------------------------------------------------------------------------------
-----Формируем/корректируем записи ПО ПЕРЕОЦЕНКАМ сделанным ВНЕ операций  В ПЕРИОД нахождения в Казне    ------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure OVERVALUE(stcurID NUMBER, stcurCALCDATE DATE, stcurOBJECTS_ID NUMBER, stcurSTARTPAY NUMBER, stcurPAY NUMBER, stcurWEAR NUMBER, curAcc VARCHAR2, stCurDOCSET_ID NUMBER)
   is
 nID NUMBER;
 cDC CHAR(1);
 nCost NUMBER := 0;
 nSaldPrev NUMBER := 0;
 aDescr VARCHAR2(1960);
 aObj VARCHAR2(400);
 aAcc VARCHAR2(9);
 aMvType CHAR(1);
 nSeq NUMBER := 0;
 endDate DATE;
 itmp NUMBER := 0;
 nMIID NUMBER := null; -- 0 -- 27.10.2011 - 
 aDocum VARCHAR2(1000);

BEGIN
             --- Находим последнюю предыдущую (по времени, относительно даты стэйта) Учетную запись.
             --- ( Чтобы во-первых - проверить в казне ли объект, а во вторых - заодно получить от нее требуемые дальше параметры)
             -- Учитываем, что объект в казне (MOVEITEM_ID>0 и DC = 'D') может переоцениваться множество раз (MOVEITEM_ID=null и DC in ('D','C'))
              if (curAcc = '104') then
                   BEGIN
                         Select macaca.ID, macaca.DC, macaca.SALDO, macaca.SEQ, macaca.MOVEITEM_ID  into nID, cDC, nSaldPrev, nSeq, nMIID
                         from
                           (Select mac.ID, mac.DC, mac.SALDO, mac.SEQ, mac.MOVEITEM_ID
                            from SM.MOVE_ACC mac
                            where mac.OBJECT_ID = stCurOBJECTS_ID
                             and mac.OPER_DATE < stCurCALCDATE  -- было <= не помним зачем. Давало отсутствие еще одной переоценивающей записи при выбытии
                             and mac.ACC like '%104%'
                             and mac.REVERSAL_ROLE  <> 'Сторнированная'  and mac.REVERSAL_ROLE  <> 'Сторнирующая (красн.)'                             
                             and mac.STATE_ID <> stcurID ---27.10.2011 Иначе при сдвиге даты стэйта вперед - находился он же, и переоценивать было нечего
                          order by mac.APPLY_DATE desc, mac.OPER_DATE desc, mac.END_DATE desc, mac.WRITE_DATE desc, mac.ID desc
                           ) macaca
                         where ROWNUM = 1;
                   EXCEPTION
                            When NO_DATA_FOUND then --NULL;
                                     nID := null;
                                     cDC := 'D';
                                     nSaldPrev := 0;
                                     nSeq := 0;
                                     nMIID := null;
                    END;
              else
                  BEGIN
                         Select macaca.ID, macaca.DC, macaca.SALDO, macaca.SEQ, macaca.MOVEITEM_ID  into nID, cDC, nSaldPrev, nSeq, nMIID
                         from
                           (Select mac.ID, mac.DC, mac.SALDO, mac.SEQ, mac.MOVEITEM_ID
                           from SM.MOVE_ACC mac
                           where mac.OBJECT_ID = stCurOBJECTS_ID
                            and mac.OPER_DATE < stCurCALCDATE
                            and mac.ACC like '%108%'
                            and mac.REVERSAL_ROLE  <> 'Сторнированная'  and mac.REVERSAL_ROLE  <> 'Сторнирующая (красн.)'                             
                            and mac.STATE_ID <> stcurID ---27.10.2011 Иначе при сдвиге даты стэйта вперед - находился он же, и переоценивать было нечего
                           order by mac.APPLY_DATE desc, mac.OPER_DATE desc, mac.END_DATE desc, mac.WRITE_DATE desc, mac.ID desc
                           ) macaca
                         where ROWNUM = 1;
                   EXCEPTION
                            When NO_DATA_FOUND then NULL;
                   END;

             end if;
           
             
  --        if (stcurID = 11506) then  ---- <<<< TEST 
  --               raise_application_error(-20001,'Q_uquququq - ' || to_char(nID));
  --        end if;
  --        if (stcurID = 11506) then  ---- <<<< TEST 
  --               NULL;
  --        end if;
             
             BEGIN
              -- Проверяем в казне ли объект на дату оценки (стэйта), и изменилась ли стоимость
              --if ((cDC = 'D' and curAcc = '108') OR (cDC = 'C' and curAcc = '104')) then
              if ((nMIID is null) OR (nMIID is not null and ((cDC = 'D' and curAcc = '108') OR (cDC = 'C' and curAcc = '104')))) then

                     if (stCurDOCSET_ID >0) then
                          Select TRIM(dt.NAME) || ' № ' || TRIM(d.DOCNO)  || ' от ' || TO_CHAR(d.DOCDATE, 'dd.MM.yyyy') into aDocum
                                 from SM.DOCUMENTS d
                                 inner join SM.DOCTYPES dt on dt.ID=d.DOCTYPES_ID
                                 WHERE d.ID = (Select MIN(dsm.DOCUMENT_ID) from SM.DOCSET_MEMBERS dsm where dsm.DOCSET_ID=stCurDOCSET_ID and dsm.DOCROLE_ID = 1);
                     end if;

                    -- счет 108 --
                    if (curAcc = '108' and nSaldPrev <> stCurSTARTPAY) then  -- Если последняя предыдущая по времени учетная запись говорит что объект в казне:
                           --- Добываем требуемые параметры
                           if (nSaldPrev >  stCurSTARTPAY) then
                                aMvType := 'C';
                                nCost := stCurSTARTPAY - nSaldPrev;
                                Select ot.ACC_TREASURY_C into aAcc from SM.OBJTYPES ot inner join SM.OBJECTS ob on ob.OBJTYPES_ID = ot.ID and ob.ID = stCurOBJECTS_ID;
                           else
                                aMvType := 'D';
                                nCost := stCurSTARTPAY - nSaldPrev;
                                Select ot.ACC_TREASURY_D into aAcc from SM.OBJTYPES ot inner join SM.OBJECTS ob on ob.OBJTYPES_ID = ot.ID and ob.ID = stCurOBJECTS_ID;
                           end if;

                           aDescr := 'ПЕРЕОЦЕНКА на ' || to_char(stCurCALCDATE,'dd.MM.yyyy') || ' с: ' || to_char(nSaldPrev) ||' на: ' ||  to_char(stCurSTARTPAY);
                           if (length(trim(aDocum)) >0 ) then
                              aDescr := aDescr || ' по ' || aDocum;
                           end if;
                           aObj :=  sm.GetObjAccName(stCurOBJECTS_ID);

                           -- Определяем Дату конца "движения" (END_DATE) переоценки по наличию стейтов позже данной переоценки
                           Select count(*) into itmp
                            from SM.STATES st
                            where st.OBJECTS_ID = stcurOBJECTS_ID and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0 and st.CALCDATE > stCurCALCDATE;
                           if (itmp > 0) then
                               Select  zzz.CALCDATE-1 into endDate
                               from ( Select st.CALCDATE from SM.STATES st
                                where st.OBJECTS_ID = stcurOBJECTS_ID and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0 and st.CALCDATE > stCurCALCDATE
                                order by st.CALCDATE, st.WRITEDATE, st.ID ) zzz
                               where ROWNUM=1;
                           else
                               endDate := stCurCALCDATE - 1; --To_date('01.01.3000','dd.MM.yyyy');
                           end if;

                           ---  Собственно отражение в учете факта переоценки. (Дата конца "движения" такая, чтобы впоследствии обеспечить правильный порядок выборки)
                           OBJ_MOVE_ACC(null, stCurOBJECTS_ID, stCurID, stCurCALCDATE, endDate, nCost, stCurSTARTPAY,  aDescr, aDescr, aObj,  aAcc, aMvType, nSeq, aDocum, null);

                     -- счет 104 --
                     elsif (curAcc = '104' and nSaldPrev <> stcurWEAR) then  -- Если последняя предыдущая по времени учетная запись говорит что объект в казне:
                           --- Добываем требуемые параметры
                           if (nSaldPrev >  stcurWEAR) then
                                aMvType := 'C';
                                nCost := stcurWEAR - nSaldPrev;
                                Select ot.ACC_TREASURY_WEAR into aAcc from SM.OBJTYPES ot inner join SM.OBJECTS ob on ob.OBJTYPES_ID = ot.ID and ob.ID = stCurOBJECTS_ID;
                           else
                                aMvType := 'D';
                                nCost := stcurWEAR - nSaldPrev;
                                Select ot.ACC_TREASURY_WEAR into aAcc from SM.OBJTYPES ot inner join SM.OBJECTS ob on ob.OBJTYPES_ID = ot.ID and ob.ID = stCurOBJECTS_ID;
                           end if;

                           aDescr := 'ПЕРЕОЦЕНКА на ' || to_char(stCurCALCDATE,'dd.MM.yyyy') || ' с: ' || to_char(nSaldPrev) ||' на: ' ||  to_char(stcurWEAR) ;
                           if (length(trim(aDocum)) >0 ) then
                              aDescr := aDescr || ' по ' || aDocum;
                           end if;
                           aObj :=  sm.GetObjAccName(stCurOBJECTS_ID);

                           -- Определяем Дату конца "движения" (END_DATE) переоценки
                           Select count(*) into itmp
                            from SM.STATES st
                            where st.OBJECTS_ID = stcurOBJECTS_ID and NVL(st.PAY, NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue))) > 0 and st.CALCDATE > stCurCALCDATE;
                           if (itmp > 0) then
                               Select  zzz.CALCDATE-1 into endDate
                               from ( Select st.CALCDATE from SM.STATES st
                                where st.OBJECTS_ID = stcurOBJECTS_ID and NVL(st.PAY, NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue))) > 0 and st.CALCDATE > stCurCALCDATE
                                order by st.CALCDATE, st.WRITEDATE, st.ID ) zzz
                               where ROWNUM=1;
                           else
                               endDate := stCurCALCDATE - 1; --To_date('01.01.3000','dd.MM.yyyy');
                           end if;

                           ---  Собственно отражение в учете факта переоценки. (Дата конца "движения" такая, чтобы впоследствии обеспечить правильный порядок выборки)
                           OBJ_MOVE_ACC(null, stCurOBJECTS_ID, stCurID, stCurCALCDATE, endDate, nCost, stcurWEAR,  aDescr, aDescr, aObj,  aAcc, aMvType, nSeq, aDocum, null);
                    end if;
              end if;
              EXCEPTION
                      When NO_DATA_FOUND then NULL;
             END;

END;

--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
----- Формирование учетных данных для определенной операци движения по движению имущества казны ----------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- Проверяем отраженность в Учетных Данных информации для всех связок с объектами, и вносим коррективы, для чего:
  -- Проходим по всем периодам.
       -- Проходим по всем объектам в периоде
          -- Выясняем происходит ли при таком стечении обстоятельств движение по казне,
            -- и вызываем ф-ю собственно фиксации Учетных Данных
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 Procedure UPDATE_MOVE_ACC(MoveSetID  NUMBER)
   is

 itmp NUMBER := 0;
 idtmp NUMBER := 0;
 nCost NUMBER(27,2) := 0;
 nSald NUMBER(27,2) := 0;
 aDescr VARCHAR2(2000) ;
 aOper VARCHAR2(1000) ;
 aObj VARCHAR2(400);
 aAcc VARCHAR2(9);
 astateID NUMBER(27);
 aMvType CHAR(1);
 aMvTypePrev CHAR(1) := 'Z';
 aMvTypeID NUMBER(27);
 wear NUMBER(27,2) := 0;
 wearPart NUMBER(27,2) := 0;
 wearSald NUMBER(27,2) := 0;
 aAccWear VARCHAR2(9);
 nRest NUMBER(27,2) := 0;
 aDocum VARCHAR2(1000) ;

begin
     Select mt.ISTREASURY, mt.ID,
                  TRIM(mt.NAME) || ' по ' || (Select TRIM(dt.NAME) || ' № ' || TRIM(d.DOCNO)  || ' от ' || TO_CHAR(d.DOCDATE, 'dd.MM.yyyy') from SM.DOCUMENTS d inner join SM.DOCTYPES dt on dt.ID=d.DOCTYPES_ID WHERE d.ID = (Select MIN(dsm.DOCUMENT_ID) from SM.DOCSET_MEMBERS dsm where dsm.DOCSET_ID=ms.DOCSET_ID and dsm.DOCROLE_ID = 1 )),
                  (Select TRIM(dt.NAME) || ' № ' || TRIM(d.DOCNO)  || ' от ' || TO_CHAR(d.DOCDATE, 'dd.MM.yyyy') from SM.DOCUMENTS d inner join SM.DOCTYPES dt on dt.ID=d.DOCTYPES_ID WHERE d.ID = (Select MIN(dsm.DOCUMENT_ID) from SM.DOCSET_MEMBERS dsm where dsm.DOCSET_ID=ms.DOCSET_ID and dsm.DOCROLE_ID = 1 ))
                  into  aMvType, aMvTypeID, aOper, aDocum
                  from SM.MOVETYPE mt inner join SM.MOVESETS ms on ms.MOVETYPE_ID = mt.ID
                  where ms.ID=MoveSetID;

     for pereCur  in
     (
          Select mp.ID, mp.SINCEDATE, NVL(mp.ENDDATE, To_date('01.01.3000','dd.MM.yyyy')) as ENDDATE, mp.WRITEDATE
          from SM.MOVEPERIODS mp
          where mp.MOVESET_ID = MoveSetID
          order by mp.SINCEDATE
     )
      loop
                 for obCur  in
                 (
                      Select mi.ID as miID, ob.ID as obIDa, (CASE when aMvType = 'C' then ot.ACC_TREASURY_C else ot.ACC_TREASURY_D end) as obAcc,
                      trim(NVL(ot.ACC_TREASURY_WEAR, '')) as obAccWear,
                      sm.GetObjAccName(ob.ID)  as obDescr
                      from SM.MOVEITEMS mi
                      inner join SM.OBJECTS ob on ob.ID = mi.OBJECT_ID
                      inner join SM.OBJTYPES ot on ot.ID = ob.OBJTYPES_ID
                      where mi.MOVEPERIOD_ID = pereCur.ID
                 )
                 loop
                        -- Если операция характера ВЫБЫТИЯ, то проверить что последняя
                        -- предыдущая (из участвующих в движении Казны) операция с ТЕМ ЖЕ ОБЪЕКТОМ -
                        --  - НЕ выбытия (включения может и не быть).
                        BEGIN
                               Select  zzz.ISTREASURY  into  aMvTypePrev
                               from ( Select mt.ISTREASURY
                                             from SM.MOVETYPE mt
                                             inner join SM.MOVESETS ms on ms.MOVETYPE_ID = mt.ID
                                             inner join SM.MOVEPERIODS mp on mp.MOVESET_ID = ms.ID
                                             inner join SM.MOVEITEMS mi on mi.MOVEPERIOD_ID = mp.ID
                                             where mi.OBJECT_ID = obCur.obIDa
                                             and (mt.ISTREASURY = 'D'
                                                        OR (mt.ISTREASURY = 'C'  and mt.ID not in (1) )
                                                        OR (mt.ISTREASURY = 'C'  and mt.ID in (1) and ms.Client_Id <> (select distinct VALUE FROM SM_SETTINGS WHERE UPPER(SM_SETTINGS.KEY_NAME)='KUMI_ID')) )  --   sm.Getparameter('KUMI_ID')))
                                              and ( mp.SINCEDATE < pereCur.SINCEDATE
                                                    OR (mp.SINCEDATE = pereCur.SINCEDATE and NVL(mp.ENDDATE, to_date('01.01.1900','dd.MM.yyyy')) < pereCur.ENDDATE and mp.ID <> pereCur.ID) )   -- Здесь открытую дату делаем гарантированно попадающей в выборку
                                              order by mp.SINCEDATE desc, NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy')) desc, mp.WRITEDATE desc, mp.ID desc ) zzz -- А здесь открытую дату делаем гарантированно первой в выборке
                               where ROWNUM=1;
                        EXCEPTION
                               When NO_DATA_FOUND then
                                      NULL;
                         END;
                        nSald := 0;
                         -- Отражаем движение только если операция - ввод в казну, или ПЕРВАЯ операция характера выбытия из казны после включения в казну.
                         -- D вслед за D -> сама выливается в переоценку, если стоимость изменилась, здесь просто игнорируется. НО - это (еще раз... :-( ) только для поштучного учета.
                        if ((aMvType = 'D' and  aMvTypePrev <> 'D') or (aMvType = 'C' and aMvTypePrev = 'D' )) then
                                  Select count(*) into itmp from  SM.STATES st where st.OBJECTS_ID = obCur.obida  and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue))>0;
                                  if itmp > 0 then -- Дальше - если есть состояние, если нет "состояния" - неоткуда и стоимость-то взять, так и писать нечего...
                                            nCost := 0;
                                            Select inst.ID, inst.cost, inst.rest  into astateID, nCost, nRest
                                            from ( Select st.ID, NVL(st.STARTPAY,NVL(sm.GetObjectCost(obCur.obIDa, pereCur.SINCEDATE, 'K'),0)) as cost, NVL(NVL(st.PAY,st.STARTPAY),NVL(sm.GetObjectCost(obCur.obIDa, pereCur.SINCEDATE, 'K'),0)) as rest
                                                 from  SM.STATES st where st.OBJECTS_ID = obCur.obida and NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0
                                                 and
                                                 ( st.CALCDATE = (Select MAX(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = obCur.obida and stt.CALCDATE <= pereCur.SINCEDATE and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0)
                                                 OR
                                                 st.CALCDATE = (Select MIN(stt.CALCDATE) from SM.STATES stt where stt.OBJECTS_ID = obCur.obida and stt.CALCDATE > pereCur.SINCEDATE and NVL(stt.STARTPAY,NVL(stt.KADASTR_COST,stt.CadastralValue))>0) )
                                                 order by st.CALCDATE ) inst
                                            where ROWNUM = 1;

                                            -----------  Определяем износ -----------------------------------------------------------------
                                            wear := nCost - nRest;
                                            wearPart := 0;
                                            wearSald := 0;

                                            -- Устанавливаем Сальдо (!!! Вариант ниже - пригоден только для движения ЦЕЛЫХ объектов. Для количественного учета - надо будет брать оборот из MOVEITEMS!!!)
                                            if (aMvType = 'D') then
                                                    nSald := nCost;
                                            else
                                                    nSald := 0;
                                                    nCost := - nCost;
                                            end if;

                                            aAcc := obCur.obAcc;
                                            aAccWear := obCur.obAccWear;
                                            aObj  := obCur.obDescr;
                                           aDescr := SUBSTR((aOper || ' - ' || obCur.obDescr), 1, 1960);

                                            ------------  Собственно отражение в учете позиции участия объекта в движении -------------
                                            if (wear = 0) then
                                                   OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, nCost, nSald,  aDescr, aOper, aObj, aAcc, aMvType, 0, aDocum, MoveSetID);

                                            ------------  Отражение в учете амортизации -------------------------------------------------------
                                            else
                                                  ------------ при поступлении в казну
                                                  if (aMvType = 'D' ) then
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, -wear, -wear,  'АМОРТИЗАЦИЯ ' || aDescr, aOper, aObj, aAccWear, 'C', 0, aDocum, MoveSetID);
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, nCost, nSald,  aDescr, aOper, aObj, aAcc, 'D', 0, aDocum, MoveSetID);
                                                  ------------  при смене собственника
                                                  elsif (aMvType = 'C' and aMvTypeID <> 2) then
                                                       -- находим сальдо амортизации в MOVE_ACC
                                                       select sm.GetObjAccBeg(obCur.obida, pereCur.SINCEDATE, aAccWear)*(-1) into wearSald from dual;
                                                       -----------  Определяем износ
                                                       Select NVL(sm.GetObjectCost(obCur.obIDa, pereCur.SINCEDATE, 'W'),0)  into wear  from dual;
                                                       -- вычисляем размер доначисления амортизации
                                                       if (wearSald <> 0) then
                                                          wearPart := wear - wearSald;
                                                       -- если сальдо не найдено, то берем амортизацию за все время пребывания в казне
                                                       else
                                                          wearPart := wear;
                                                       end if;

                                                       ------------  Собственно отражение в учете амортизации
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, -wearPart, -wear, 'Доначисление АМОРТИЗАЦИИ при списании имущества ' || aDescr, aOper, aObj, aAccWear, 'C', 0, aDocum, MoveSetID);
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, wear, 0, 'Списание АМОРТИЗАЦИИ при списании имущества ' || aDescr, aOper, aObj, aAccWear, 'D', 0, aDocum, MoveSetID);

                                                       ------------ Собственно отражение в учете позиции участия объекта в движении
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, -wear, -nCost - wear,  'Списание на сумму АМОРТИЗАЦИИ ' || aDescr, aOper, aObj, aAcc, 'C', 1, aDocum, MoveSetID);
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, -(-nCost - wear), 0,  'Списание остаточной стоимости ' || aDescr, aOper, aObj, aAcc, 'C', 2, aDocum, MoveSetID);
                                                       --либо одной проводкой --OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, nCost, nSald,  aDescr, aOper, aObj, aAcc, 'C', 0, aDocum, MoveSetID);

                                                  ------------  при передаче на баланс
                                                  elsif (aMvType = 'C' and aMvTypeID = 2) then
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, wear, 0,  'Списание АМОРТИЗАЦИИ при передаче на баланс ' || aDescr, aOper, aObj, aAccWear, 'D', 0, aDocum, MoveSetID);
                                                       OBJ_MOVE_ACC(obCur.miID, obCur.obIDa, astateID, pereCur.SINCEDATE, pereCur.ENDDATE, nCost, nSald,  aDescr, aOper, aObj, aAcc, 'C', 0, aDocum, MoveSetID);
                                                  end if;
                                            end if;
                                            -------------------------------------------------------------------
                                  end if;
                        end if;
                  end loop;
      end loop;
end;


---------------------------------------------------------------------------------------------------------------------------------------------------------
--- Формирование учетных данных для всех операций движения по движению имущества казны,
--  начиная  с какой-то даты написания операций ---
-- По завершению в SM.SM_SETTINGS_TAB записывается дата последнего запуска процедуры в параметр LAST_MOVEACC_START
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure UPDATE_MOVE_ACC(fromDate DATE)
 is
begin

    -------------  Основной цикл: ---------
    -------------  Пишем для всех операций их представление -------------------------------------------------------------------
     for moveCurr  in
     (
          Select ms.ID
          from SM.MOVESETS ms
          inner join SM.MOVEPERIODS mp on mp.MOVESET_ID = ms.ID
          inner join SM.MOVETYPE mt on mt.ID = ms.MOVETYPE_ID
          where  (mt.ISTREASURY = 'D'
                      OR (mt.ISTREASURY = 'C'  and mt.ID not in (1) )
                      OR (mt.ISTREASURY = 'C'  and mt.ID in (1) and ms.Client_Id <> (select distinct VALUE FROM SM_SETTINGS WHERE UPPER(SM_SETTINGS.KEY_NAME)='KUMI_ID')) )  --   sm.Getparameter('KUMI_ID')))
 --         and mp.writedate >= fromDate -- <<< Так было бы оптимальней, если бы изменялись даты при правке STATE-ов, а так - в общем случае бесполезно...
           order by mp.SINCEDATE, NVL(mp.ENDDATE, to_date('01.01.3000','dd.MM.yyyy') ), mp.WRITEDATE, mp.ID
     )
      loop
            UPDATE_MOVE_ACC(moveCurr.ID);
      end loop;

    -------------  Дополнительный цикл: ---------для всех бух.счетов
     ------------ Удаление/сторнирование Учетных Данных для не существующих (скореее всего удаленных) на заданный момент, либо удаленных почему-либо связок с объектами -------
     for accCurr  in
     (
          Select ma.ID, ma.APPLY_DATE
          from SM.MOVE_ACC ma
          where  ((ma.MOVEITEM_ID is not null and not exists (Select * from SM.MOVEITEMS mi where mi.ID = ma.MOVEITEM_ID))
               OR
            (ma.MOVEITEM_ID is null and not exists (Select * from SM.STATES st where st.ID = ma.STATE_ID))
               OR
            (ma.STATE_ID is not null and not exists (Select * from SM.STATES st where st.ID = ma.STATE_ID))
               OR
            (ma.MOVEITEM_ID is null and sm.IsObjInTreasury(ma.OBJECT_ID, ma.APPLY_DATE)='N' and not exists
            (Select * from SM.MOVE_ACC macaca where macaca.OBJECT_ID = ma.OBJECT_ID and macaca.APPLY_DATE = ma.APPLY_DATE and macaca.MOVEITEM_ID is not null and macaca.DC = 'D' and macaca.ID<>ma.ID
              and macaca.OPER_DATE <= ma.OPER_DATE )                                                       and not exists
            (Select * from SM.MOVE_ACC caca where caca.OBJECT_ID = ma.OBJECT_ID and caca.APPLY_DATE = ma.APPLY_DATE and caca.MOVEITEM_ID is not null and caca.DC = 'C' and caca.ID<>ma.ID
               and caca.OPER_DATE >= ma.OPER_DATE )
             )
--            OR
--            (ma.MOVEITEM_ID is null and sm.IsObjInTreasury(ma.OBJECT_ID, ma.APPLY_DATE)='N' and not exists
--            (Select * from SM.MOVE_ACC caca where caca.OBJECT_ID = ma.OBJECT_ID and caca.APPLY_DATE = ma.APPLY_DATE and caca.MOVEITEM_ID is not null and caca.DC = 'C' and caca.ID<>ma.ID
--               and caca.OPER_DATE > ma.OPER_DATE )
--             )
             OR
            (ma.MOVEITEM_ID is null and sm.IsObjInTreasury(ma.OBJECT_ID, ma.APPLY_DATE)='Y' and  ma.MOVESET_ID is not null and not exists
            (Select * from SM.MOVESETS musia where musia.ID = ma.MOVESET_ID)
             )
             OR
            (ma.MOVEITEM_ID is null and  ma.MOVESET_ID is null and exists
            (Select * from SM.MOVE_ACC ca where ca.OBJECT_ID = ma.OBJECT_ID and ma.APPLY_DATE =ca.APPLY_DATE and ca.MOVEITEM_ID is null and sm.IsObjInTreasury(ca.OBJECT_ID, ca.APPLY_DATE)='Y' and  ca.MOVESET_ID is not null and not exists
            (Select * from SM.MOVESETS pusia where pusia.ID = ca.MOVESET_ID))
             )
            )
          order by ma.APPLY_DATE desc, ma.OPER_DATE desc, ma.END_DATE desc, ma.WRITE_DATE desc, ma.ID desc
     )
      loop
            if accCurr.APPLY_DATE > CloseDate then --- В открытом периоде - просто удалить
                 Delete from SM.MOVE_ACC where ID=accCurr.ID;
            else
                 MOVE_ACC_PKG.STORNO(accCurr.ID, CloseDate+1); -- Иначе - сторнировать
            end if;
      end loop;


    -------------  Дополнительный цикл: ---------
    ------------ Формируем/корректируем записи ПО ПЕРЕОЦЕНКАМ сделанным ВНЕ операций  В ПЕРИОД нахождения в Казне -----------
      for stCur  in
      (
          Select
              st.ID, st.CALCDATE, st.OBJECTS_ID,
              NVL(st.STARTPAY, NVL(sm.GetObjectCost(st.OBJECTS_ID, st.CALCDATE, 'K'),0)) as STARTPAY,
              NVL(NVL(st.PAY, st.STARTPAY), NVL(sm.GetObjectCost(st.OBJECTS_ID, st.CALCDATE, 'K'),0)) as PAY,
              NVL(st.documents_id,0) as DOCSET_ID
          from SM.STATES st
          where NVL(st.STARTPAY, NVL(st.KADASTR_COST,st.CadastralValue)) > 0
              -- и рассматривать только если есть еще стэйты, и данный - не первый.
              and exists (Select * from SM.STATES stOther where stOther.OBJECTS_ID = st.OBJECTS_ID and stOther.CALCDATE< st.CALCDATE)
              -- и рассматривать только если есть включения объекта в казну РАНЬШЕ переоценки.
              --and exists (Select * from SM.MOVE_ACC mac where mac.OBJECT_ID = st.OBJECTS_ID and  mac.OPER_DATE < st.CALCDATE)
              --и рассматривать только если объект все еще в казне - нельзя, т.к. возможен случай необходимости переоценки при выходе из казны
              and (sm.IsObjInTreasury(st.OBJECTS_ID, st.CALCDATE) = 'Y' OR exists (Select * from SM.MOVE_ACC mac where mac.OBJECT_ID = st.OBJECTS_ID and mac.APPLY_DATE = st.CALCDATE and mac.DC='C' and mac.ACC like '0108%'  ) )
          order by st.CALCDATE, st.WRITEDATE, st.ID
      )
      loop
          -- счет 108 --
          MOVE_ACC_PKG.OVERVALUE(stCur.ID, stCur.CALCDATE, stcur.OBJECTS_ID, stcur.STARTPAY, stcur.PAY, (-1)*(stcur.STARTPAY - stcur.PAY), '108', stCur.DOCSET_ID);
          -- счет 104 --
          MOVE_ACC_PKG.OVERVALUE(stCur.ID, stCur.CALCDATE, stcur.OBJECTS_ID, stcur.STARTPAY, stcur.PAY, (-1)*(stcur.STARTPAY - stcur.PAY), '104', stCur.DOCSET_ID);
      end loop;

      -------------------- Фиксируем факт формирования Учетных Данных -----------------------
      update SM.SM_SETTINGS_TAB set value = to_char(SYSDATE, 'dd.MM.yyyy HH24:MI:SS') where KEY_NAME = 'LAST_MOVEACC_START';
      commit;
end;



---------------------------------------------------------------------------------------------------------------------------------------------------------
-----Формирование учетных данных для всех операций движения по движению имущества казны ------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure UPDATE_MOVE_ACC
   is
begin
      CloseDate  := Getparameter('ENDPERIOD') ;
      UPDATE_MOVE_ACC(TO_DATE(Getparameter('ENDPERIOD'), 'dd.MM.yyyy' ));

      --Это освежает статистику после обновления данных
      execute immediate('ANALYZE TABLE SM.MOVE_ACC COMPUTE STATISTICS');
end;
--------------------------------------------------------------------
--------------------------------------------------------------------


Function GetVerInfo return number is
begin

  return(1);

end;
--------------------------------------------------------------------

end; -- пакета
/
grant execute on SM.MOVE_ACC_PKG to SM_ALLUSERS;
grant execute on SM.MOVE_ACC_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body MULTIOWNING_PKG
prompt =====================================
prompt
create or replace package body sm.MultiOwning_Pkg is

  CURRENT_OWNER NUMBER(27):=null;
  CURRENT_OWNER_NAME VARCHAR2(255):=null;
  countOwner NUMBER(27);

  function GetCurrentOwnerID RETURN NUMBER is
  begin
     if CURRENT_OWNER is null then -- если базовый собственник не задан, то ошибка
         raise_application_error(-20101, 'Базовый собственник не определен');
     end if;
     return CURRENT_OWNER;
  end;

  function GetCurrentOwnerName RETURN VARCHAR2 is
  begin
     if CURRENT_OWNER is null then -- если базовый собственник не задан, то ошибка
         raise_application_error(-20101, 'Базовый собственник не определен');
     end if;
     return CURRENT_OWNER_NAME;
  end;
 
  -- возвращает ID распорядителя текущего базового собственника
  function GetCurentOwnerAuthKUMI_ID RETURN NUMBER is
    RetVal number;
  begin
     if CURRENT_OWNER is null then -- если базовый собственник не задан, то ошибка
         raise_application_error(-20101, 'Базовый собственник не определен');
     end if;
     
     RetVal:=null;
     -- поищем среди организаций, связанных с АТО
     for xx in (select o.clients_id from sm.ATO a, sm.Organisations o where a.clients_id=CURRENT_OWNER and o.clients_id=a.authorized_kumi_id)
     loop
       RetVal:=xx.clients_id;
     end loop;
     
     if RetVal is null then
       -- проверим, возможно этот базовый собственник сам распоряжается своим имуществом
       for xx in (select o.Clients_Id from sm.organisations o where o.clients_id=CURRENT_OWNER)
       loop
         RetVal:=xx.clients_id;
       end loop;
     end if;
     
     Return(nvl(RetVal,-1));
  end;
  
  procedure SetCurrentOwner(CLIENT_ID IN NUMBER) is
   fake varchar2(255);
   clientName sm.clients.name%type;
   clID sm.clients.id%type;
  begin
     if CLIENT_ID is null then -- если базовый собственник не задан, то ошибка
         raise_application_error(-20101, 'Базовый собственник не определен');
     end if;
     clID := CLIENT_ID;
     
     -- проверяем достаточно ли у данного пользователя прав быть распорядителем выбранного базового собственника
     select count(*) into countOwner from sm.User_Owner_Agents uoa where uoa.client_id=clID;
     if countOwner=0 then -- если прав не достаточно
         -- пытаемся сформировать красивое сообщение об ошибке
         select count(*) into countOwner from sm.clients c where c.id = clID;
         if countOwner=0 then
             clientName := to_char(clID);
         else
             select c.name into clientName from sm.clients c where c.id = clID;
         end if;
         -- вот и ошибка
         raise_application_error(-20101, 'Не достаточно прав быть агентом для базового собственника: '||clientName);
     end if;
     
     -- прав быть распорядителем достаточно
     -- сохраняем данные распорядителя
     CURRENT_OWNER:=CLIENT_ID;
     select nvl(OWNERSHIP_NAME,NAME) into CURRENT_OWNER_NAME from sm.CLIENTS where ID=CLIENT_ID;
  end;

begin
    -- инициализация
    -- получить идентификатор базового собственника из настроек (базовый собственник по умолчанию)
    select VALUE into CURRENT_OWNER from sm.SM_SETTINGS_TAB where KEY_NAME='KUMI_ID';
    
    if CURRENT_OWNER is not null then-- если идентификатор существует
        -- проверить достаточно ли у текущего пользователя прав быть агентом
        select count(*) into countOwner from sm.USER_OWNER_AGENTS uoa where uoa.client_id=CURRENT_OWNER;
    else
        -- сразу ясно прав не достаточно :)
        countOwner:=0;
    end if;

    if countOwner=0 then -- если прав не достаточно
        -- смотрим может ли данный пользователь быть хоть чьим нибудь распорядителем
        select count(*) into countOwner from sm.user_owner_agents;
        if countOwner>0 then -- если может
            -- пусть будет агентом распорядителем первого попавшегося базового собственника
            select client_id into CURRENT_OWNER from sm.User_Owner_Agents where rownum=1;
        end if;
    end if;
    -- устанавливаем выбранного базового собственника
    SetCurrentOwner(CURRENT_OWNER);
end;
/
grant execute on SM.MULTIOWNING_PKG to SM_ALLUSERS;
grant execute on SM.MULTIOWNING_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body OBJPOSITION_PKG
prompt =====================================
prompt
create or replace package body sm.OBJPOSITION_PKG is
  -------------------------------------------------------------------------
  procedure FillObjectPosition(AObjectID in number) is
    CL_ID number;  
  begin
  
    for xx in (select o.id OBJ_ID from sm.objects o where o.id=AObjectID
               union
               select b.objects_id OBJ_ID
               from sm.Buildings b
               start with b.objects_id=AObjectID
               connect by prior b.id=b.basebuilding)
    loop           
      delete from sm.object_position op where op.object_id=xx.OBJ_ID; 
      
      for yy in (select * from sm.movetype)
      loop
        CL_ID:=sm.Getpositionclientidbydate(xx.OBJ_ID,yy.ID,sysdate);
        if CL_ID is not null then
          insert into sm.object_position (client_id,object_id,movetype_id) values (CL_ID,xx.OBJ_ID,yy.ID);
        end if;  
      end loop;
    end loop;
    
  end;
  -------------------------------------------------------------------------  
  procedure FillObjectPositionByMSID(AMovesetID in number) is
  begin
  
    for xx in (
              select 
                 mi.object_id
               from
                 sm.moveitems mi,
                 sm.moveperiods mp
              where
                 mi.moveperiod_id=mp.id and
                 mp.moveset_id=AMovesetID
                 
              UNION
              -- добавлено, чтобы не были "забыты" объекты, входящие в Имущественные комплексы
              select 
                 mio.objects_id
               from
                 sm.links_mi_objects mio,
                 sm.moveitems mi,
                 sm.moveperiods mp
              where
                 mio.moveitems_id=mi.id and
                 mi.moveperiod_id=mp.id and
                 mp.moveset_id=AMovesetID
                 )
    loop
      FillObjectPosition(xx.object_id);           
    end loop;
    
  end;
  -------------------------------------------------------------------------  
  procedure FullRecalcObjectPosition is
  begin
  
    execute immediate('truncate table OBJECT_POSITION');  
    
    for xx in (select o.id OBJ_ID 
               from sm.objects o
               where o.objtypes_id<>3
               union
               select b.objects_id OBJ_ID
               from sm.Buildings b
               where b.basebuilding is null)
    loop
      FillObjectPosition(xx.obj_id);
      commit;           
    end loop;
    
  end;
  -------------------------------------------------------------------------
  
begin
  null;
end OBJPOSITION_PKG;
/
grant execute on SM.OBJPOSITION_PKG to SM_ALLUSERS;
grant execute on SM.OBJPOSITION_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body OBLIG_ACC_PKG
prompt ===================================
prompt
create or replace package body sm.OBLIG_ACC_PKG is

G_CloseDate DATE := to_date(GetparameterSimple('ENDPERIOD'), 'dd.MM.yyyy') ;

---------------------------------------------------------------------------------------------------------------------------------------------------------
-----Сторнирование записи в  charge_applies  на дату------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure STORNO(chAcc NUMBER, dateAcc DATE)
   is
begin
      Insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type, description, charge_id,
       corr_flag, cls_kbk_id, obligations_id, payments_distribution_id, reversal_role, reversallink_id, payment_id)
       Select SM.SEQCHARGE_APPLIES.nextval, trunc(dateAcc),  - c.summ, c.obligtype_id, c.moveset_id, c.charge_type,
			              (CASE when (INSTR(c.description, 'Сторнирующая: ') = 0) then 'Сторнирующая: ' else '' end) || trim(c.description),   c.charge_id,
                    'Y',  c.cls_kbk_id, null, null, 'Сторнирующая', chAcc, c.payment_id
        from SM.CHARGE_APPLIES c where ID = chAcc;

    Update SM.CHARGE_APPLIES set CORR_FLAG = 'Y',
		                                                               description = 'Сторнированная: ' || replace(replace(description, 'Сторнированная: '),  'Сторнирован: '),
		                                                              REVERSAL_ROLE='Сторнированная',
																																	REVERSALLINK_ID = SM.SEQCHARGE_APPLIES.currval
																																	where  ID = chAcc;
end;

---------------------------------------------------------------------------------------------------------------------------------------------------------
-----Сторнирование записей в  charge_applies  для начисления на дату------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure StornoCharge(Achrg NUMBER)
   is

dTmp DATE;
iTmp integer;

begin

G_CloseDate  := to_date(GetparameterSimple('ENDPERIOD'), 'dd.MM.yyyy') ;

    ---------- Сторнируем записи Учетных Данных для не существующих (скорее всего удаленных) Операций Движения ---------
      for accCurr  in
      (
          Select ca.ID, ca.APPLY_DATE, ca.REVERSAL_ROLE, ca.REVERSALLINK_ID
          from SM.CHARGE_APPLIES ca
          where  ca.CHARGE_ID = Achrg
      )
      loop
				    -- Если сторнирующая - проверить может сторнированная оказалась в открытом периоде
						--   - тогда удалять и ее. Иначе - сторнирующие НЕ УДАЛЯТЬ в открытом периоде.
				    if (accCurr.REVERSAL_ROLE = 'Сторнирующая' and accCurr.REVERSALLINK_ID > 0)  then
									 Select count(*) into iTmp from SM.CHARGE_APPLIES ca2 where ca2.ID = accCurr.REVERSALLINK_ID;
									 if (iTmp > 0) then
														Select ca2.APPLY_DATE into dTmp from SM.CHARGE_APPLIES ca2 where ca2.ID = accCurr.REVERSALLINK_ID;
										else
														dTmp := accCurr.APPLY_DATE;
										end if;
						end if;

						if (accCurr.APPLY_DATE > G_CloseDate  and accCurr.REVERSAL_ROLE <> 'Сторнирующая') -- В открытом периоде не сторнирующие
							   -- или сторнирующие - но сторнированая тоже в откр. периоде (открыли период поторно)
							 OR (accCurr.REVERSAL_ROLE <> 'Сторнирующая' and dTmp > G_CloseDate)
						then --- В открытом периоде - просто удалить
                Delete from SM.CHARGE_APPLIES where ID=accCurr.ID;
 --               NULL;
            else
                 OBLIG_ACC_PKG.STORNO(accCurr.ID, G_CloseDate+1); -- Иначе - сторнировать
            end if;
      end loop;

 end;



---------------------------------------------------------------------------------------------------------------------------------------------------------
--- Подчищает Учетные Данные по расчетам для удаленных "первоисточников" ("осиротевших" учетных записей) ---
---------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure ReviseAllChargeApplies
 is

dTmp DATE;

begin

G_CloseDate  := to_date(GetparameterSimple('ENDPERIOD'), 'dd.MM.yyyy') ;

    ---------- Сторнируем записи Учетных Данных для не существующих (скорее всего удаленных) Операций Движения ---------
      for accCurr  in
      (
          Select ca.ID, ca.APPLY_DATE, ca.REVERSAL_ROLE, ca.REVERSALLINK_ID
          from SM.CHARGE_APPLIES ca
          where  not exists (Select * from SM.MOVESETS ms where ms.ID = ca.MOVESET_ID)
					OR 	(PAYMENT_ID is null  and REVERSAL_ROLE is null and not exists (Select * from SM.CHARGES ch where ch.ID = ca.CHARGE_ID))
      )
      loop
 				    -- Если сторнирующая - проверить может сторнированная - оказалась в открытом периоде - тогда - удалять и ее.
						-- Иначе - сторнирующие НЕ УДАЛЯТЬ в открытом периоде.
				    begin
									if (SUBSTR(accCurr.REVERSAL_ROLE,1,12) = 'Сторнирующая' and accCurr.REVERSALLINK_ID > 0)  then
											 Select ca2.APPLY_DATE into dTmp from SM.CHARGE_APPLIES ca2 where ca2.ID = accCurr.REVERSALLINK_ID;
									end if;
						exception
							   when NO_DATA_FOUND then
								 dTmp := to_date('01.01.1900','dd.MM.yyyy');
						end;

						if (accCurr.APPLY_DATE > G_CloseDate  and accCurr.REVERSAL_ROLE <> 'Сторнирующая') -- В открытом периоде не сторнирующие
							 -- или сторнирующие - но сторнированая тоже в откр. периоде (открыли период поторно)
							 OR (accCurr.REVERSAL_ROLE <> 'Сторнирующая' and dTmp > G_CloseDate)
						then --- В открытом периоде - просто удалить
                 Delete from SM.CHARGE_APPLIES where ID=accCurr.ID;
--					        NULL;
            else
                 OBLIG_ACC_PKG.STORNO(accCurr.ID, G_CloseDate+1); -- Иначе - сторнировать
            end if;
      end loop;

end;


------------------------------------------------------------------------------------------------------------------------------------------
----- Процедура "расщепляет"  Учетные Записи для пени по границе месяца. ---------------------------------------------
----- Смысл такого действия - то что для бухгалтерии во всех случаях нужно сальдо и обороты НА ГРАНИЦУ ПЕРИОДА (месяца, квартала, года).
----  Соответствено, пеня должна попадать той чстью, которая приходится на отчетный период...
Procedure PartitioningChargesAppliesFine(Comments in varchar2,
                                        calperiod_start in date,
                                        Calperiod_End in date,
                                        PaySize in number,
                                        A_ObligationType_ID in number,
                                        MoveSets_ID in number,
                                        Charge_ID in number,
                                        cls_kbk_id in number,
                                        ChType char,
                                        A_Charges_applies_ID number,
                                        A_Reversal_Role varchar2
                                        , A_payID in number default null)
is
 -- CorrSumm number(27,2); -- <<< 22.11.2011 <<< Осталось от прошлого? (CorrSumm не используется)
 CurDate DATE;
 NextDate DATE;
 CurPaySize number(27,2) := 0;
 SumPaySize number(27,2) := 0;
 A_Comments varchar2(150);
 n integer;
 astr_pos integer;
 equal_pos integer;
 Comments_part sm.charges.comments%type;
 ARecalc_Start_Date date;
begin
    	--- 30.03.2015 Morozova дата с которой ведется перерасчет
      Select ob.RECALC_START_DATE into ARecalc_Start_Date
      from SM.OBLIGATIONS ob 
      where ob.moveset_id = MoveSets_ID and ob.obligationtype_id = A_ObligationType_ID;
      
	    G_CloseDate  := to_date(GetparameterSimple('ENDPERIOD'), 'dd.MM.yyyy') ;
      -- для пени - делаем разбивку по границам месяцев (для правильного исчисления сальдо по пене на конец месяца
      CurDate:=CALPERIOD_START;
      
      --- 17.02.2014 Morozova Удалим проводки по пене, по данному начислению если они были исправляющими в открытом периоде
      delete from sm.charge_applies cha
             where cha.moveset_id = MoveSets_ID
                   and cha.obligtype_id = A_ObligationType_ID
                   and trim(cha.charge_type) = 'F' --- <<< Это было закомментировано самой Надей, и уничтожались все проводки
                   and cha.apply_date > G_CloseDate                   
                   and cha.charge_id = Charge_ID
                   and cha.description like '%(по поводу начисления)%'
                   and (cha.reversal_role = 'Исправляющая' or cha.reversal_role is null) ;

      astr_pos:=instr(Comments,'*',1,1);
      equal_pos:=instr(Comments,'=',1,1);
      Comments_part:=substr(Comments,astr_pos,equal_pos-astr_pos+1);
      while true loop
        -- расчитаем дату конца текущего месяца
        NextDate:=TRUNC(ADD_MONTHS(CurDate,1),'MONTH')-1;

        -- если конец текущего месяце позже или совпадает с концом периода
        -- размером оплаты за этот период назначается оставшаяся сумма
        if NextDate>=Calperiod_End then
            NextDate:=NVL(Calperiod_End, to_date('01.01.3000','dd.MM.yyyy')); --- <<< 22.02.2012 -- Предохранитель от уплывания даты за границы дат
            CurPaySize :=PaySize - SumPaySize;

            -- количество дней чтобы сформировать правильный комментарий
            n:=NextDate-CurDate+1;
            if n=0 then
                n:=1;
            end if;

        else
            -- количество дней
            n:=NextDate-CurDate+1;
            if n=0 then
                n:=1;
            end if;

            -- расчитываем размер оплаты за не последний период
            CurPaySize:=PaySize/(calperiod_end-calperiod_start+1)*n;
            -- суммируем уже учтенную оплату для корректного расчета суммы последнего периода
            SumPaySize:=SumPaySize+CurPaySize;
        end if;
        
        if CurDate < ARecalc_Start_Date then -- 30.03.2015 Morozova  если дана начала расчета пени меньше даты перерасчета
          goto goto_next;
        end if;

        if n=1 then
             A_Comments:='Пеня: за '||CurDate||' ('||to_char(n)||'д'||Comments_part||To_char(CurPaySize,'FM99999990.00')||'р., - часть от ' || to_char(PaySize) || 'р.)';
        else
             A_Comments:='Пеня: c '||CurDate||' по '||NextDate||' ('||to_char(n)||'д'||Comments_part||To_char(CurPaySize,'FM99999990.00') ||'р., - часть от ' || to_char(PaySize) || 'р.)';
        end if;
        ----------------------------------------------------новый блок
 --          if (NextDate<=G_CloseDate) then  -- <<< 19.02.2013 <<< Это исключало написание исправляющих записей по пене
--                   NULL;   -- CorrSumm:=CorrSumm+CurPaySize; -- <<< 22.11.2011 <<< Осталось от прошлого? (CorrSumm не используется)
 --          else
                     if CurPaySize is null then  -- <<< 22.11.2011 <<<  Защита от как-то возникавшего NULL.
                             CurPaySize := 0;
                     end if;
                     ----------------------------------------------------старый блок
                     if G_CloseDate < NextDate then
                        insert into Charge_Applies(ID,Apply_Date,Summ,ObligType_ID,MoveSet_ID,Description,Charge_Type,Charge_ID,Corr_Flag,cls_kbk_id, Reversal_Role, Reversallink_Id, Payment_Id)
                             values(seqcharge_applies.nextval,NextDate,CurPaySize, A_ObligationType_ID,MoveSets_ID,A_comments, ChType, Charge_ID,'N', cls_kbk_id, A_Reversal_Role, A_Charges_applies_ID, A_PayID);
                     else
                        insert into Charge_Applies(ID,Apply_Date,Summ,ObligType_ID,MoveSet_ID,Description,Charge_Type,Charge_ID,Corr_Flag,cls_kbk_id, Reversal_Role, Reversallink_Id, Payment_Id)
                             values(seqcharge_applies.nextval,trunc(sysdate),CurPaySize, A_ObligationType_ID,MoveSets_ID,'Исправляющая: ' || A_comments, ChType, Charge_ID,'Y', cls_kbk_id, 'Исправляющая', A_Charges_applies_ID, A_PayID);
                     end if;
                     ----------------------------------------------------новый блок
 --          end if;
         <<goto_next>>
        ----------------------------------------------------старый блок
        CurDate := NVL(NextDate, to_date('31.12.2999','dd.MM.yyyy')) +1; --- <<< 22.02.2012 -- Предохранитель от уплывания даты за границы дат

        exit when CurDate>CALPERIOD_END;
      end loop;

end;


--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
------------- Формирование/корректировка Учетных Записей для начисления. -----------------------------
Procedure RecalcChargesApplies(A_charges_id in number,
       A_chargedate in date, A_movesets_id in number,
       A_document_id in number, A_comments in varchar2,
       A_paysize in Number, A_charge_type_Orig in varchar2,
       A_obligationtype_id in number, A_Finedate in date,
       A_Discountsize in number, A_Paydoc_Id in number,
       A_calperiod_start in date, A_Calperiod_End in date,
       A_Cls_Kbk_Id in number, A_Redir_Flag in char,
       A_redir_paydoc_id in  number,
       A_OBLIG_ID in number, A_factCharge in char default null
       , A_PayID in number default null
       , A_FirstCharges in char default 'N'
       , A_FINE_FOR_PERCENT in char default 'N')
is
 c integer;
 A_charges_id_old number(27);
 A_charge_type_short char(1);
  A_comment_old varchar2(500);
 A_charge_type varchar2(100);
 A_apply_date DATE;
 A_summ NUMBER(27,2);
 ARecalc_Start_Date date;

begin

  select replace(TRIM(A_charge_type_Orig), 'PERCENT', 'OBLIGATION') into A_charge_type from dual;
  select decode(upper(trim(A_charge_type)), 'OBLIGATION','O','F') into A_charge_type_short from dual;

   G_CloseDate  := to_date(GetparameterSimple('ENDPERIOD'), 'dd.MM.yyyy') ;
   ---- Если бухгалтерски-существенные параметры не изменились - то только Update-аем прочие атрибуты, и все.  (19.01.2012)
  if A_charges_id > 0  and G_CloseDate < A_chargedate then
		 Select count(*)  into c
			 from SM.CHARGE_APPLIES ch
			 where ch.charge_id = A_charges_id
						and ((ch.reversal_role is null  and ch.apply_date = A_chargedate)  OR  (trim(ch.reversal_role)='Исправляющая'  and ch.apply_date >= A_chargedate))
						and ch.summ = A_paysize and ch.charge_type = A_charge_type_short;
			if ( c=1) then
							 Update SM.CHARGE_APPLIES ch
									set ch.description = A_comments, ch.cls_kbk_id = A_Cls_Kbk_Id
									where ch.charge_id = A_charges_id
												and ((ch.reversal_role is null  and ch.apply_date = A_chargedate)  OR  (trim(ch.reversal_role)='Исправляющая'  and ch.apply_date >= A_chargedate))
												and ch.summ = A_paysize and ch.charge_type = A_charge_type_short;
								Return;	 -- << И ВСЕ!
			 end if;
  end if;
  ---- Если бух параметры не изменились в закрытом бух периоде, то выходим 
  ---- 28.03.2014 Morozova 
 if A_charges_id > 0  and G_CloseDate > A_chargedate and A_charge_type_short='O' then
		 Select count(*)  into c
			 from SM.CHARGE_APPLIES ch
			 where ch.charge_id = A_charges_id       
						and ((ch.reversal_role is null  and ch.apply_date = A_chargedate)  OR  (trim(ch.reversal_role)='Исправляющая'  and ch.apply_date >= A_chargedate))
						and ch.summ = A_paysize and ch.charge_type = A_charge_type_short;
			if ( c = 1) then
								Return;	 -- << И ВСЕ!
			 end if;
  end if;

  -- ищем одинаковые записи
  select    --+INDEX(cr IDX_CHG_MOVESET_ID)
  nvl(min(id), 0), count(*) into A_charges_id_old,  c
  from sm.charges cr
      where cr.movesets_id = A_movesets_iD
           and nvl(cr.document_id, 0) = nvl(A_document_id, 0)
           and TRIM(cr.charge_type) = TRIM(A_charge_type_Orig)
           and nvl(cr.finedate, trunc(sysdate)) = nvl(A_Finedate,trunc(sysdate))
           and cr.obligationtype_id = A_obligationtype_id
           and nvl(cr.discountsize,0) = nvl(A_Discountsize,0)
           and cr.paydoc_id = A_Paydoc_Id
           and (  (nvl(cr.calperiod_start, trunc(sysdate)) = nvl(A_calperiod_start, trunc(sysdate))
                 and nvl(cr.calperiod_start, trunc(sysdate)) = nvl(A_Calperiod_End, trunc(sysdate))
                 and cr.charge_type='PERCENT')
              OR    nvl(trim(cr.comments), '') = nvl(trim(A_comments), '')  )
           and nvl(cr.Cls_Kbk_Id,0) = nvl(A_Cls_Kbk_Id,0)
           and nvl(cr.redir_flag,'N') = nvl(A_Redir_Flag,'N')
           and nvl(cr.redir_paydoc_id, 0) = nvl(A_redir_paydoc_id, 0)
           and nvl(cr.factcharge, 'Y') = nvl(A_factCharge, 'Y')
					 and cr.id <> nvl(A_charges_id, 0)  -- <<< 22.03.2012 <<< Добавлено последнее условие. А то удалялось первое начисление при 0-вой сумме.
					 AND cr.PAYSIZE <> 0;  -- <<< 18.02.2013  - Чтобы не принимались за прошлые сторнирующие записи

-- если A_paysize = 0 (сальдо больше 0) То запись не добавлена, но при с = 1 есть запись по пене в начислениях
	     Select ob.RECALC_START_DATE into  ARecalc_Start_Date
             from SM.OBLIGATIONS ob where ob.ID = A_OBLIG_ID;


    -- удаляем все начисления по обязательству, если они  оказались начисленными датой,
    -- позже срока окончания действия договора в результате изменения окончания срока договора
    -- или ранее начала ОД
   if A_FINE_FOR_PERCENT = 'N' then
											-- удаляем ранние начисления по пене, если добавляемое начисление по пене вызвано удалением платежа
										 delete from sm.charges ch
										 where ch.movesets_id = A_movesets_iD
													 and ch.obligationtype_id = A_obligationtype_id
													 and TRIM(cH.charge_type) = TRIM(A_charge_type_Orig)
													 and ch.calperiod_start between A_calperiod_start and A_calperiod_end
													     and ch.calperiod_end between A_calperiod_start and A_calperiod_end
													 and (ch.charge_type = 'FINE' OR ch.charge_type = 'OBLIGATION')
													 AND ch.paydoc_id = A_Paydoc_Id    -- <<< Удаляем только сделанное по  "своему"  основанию!
--													 AND ch.calperiod_end > A_chargedate  -- 27.01.2014 --- Morozova иначе удалялись начисления у которых дата начисления попадала в следующий период ОД
													 and A_FINE_FOR_PERCENT = 'N'
                           and ch.document_id is null and ch.charge_type <> 'OTHER'
													 and ch.id <> nvl(A_charges_id, 0)
													 AND nvl(ch.redir_paydoc_id, 0) = nvl(A_redir_paydoc_id, 0) -- <<< 25.06.2013 -- Иначе субаренда стирала другую субаренду на тот же день
												 AND ch.CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.

										 -- начисление новое,  поэтому удаляем все начисления, после даты нового начисления
										delete from sm.charges ch
										 where ch.movesets_id = A_movesets_iD
													 and ch.obligationtype_id = A_obligationtype_id
													 and TRIM(ch.charge_type) = TRIM(A_charge_type_Orig)
													 and ch.chargedate > A_chargedate 
													 and ( ch.calperiod_start > A_chargedate and ch.charge_type = 'OBLIGATION' --- 04.06.2014 Morozova 
													   or (ch.calperiod_end > A_chargedate and ch.charge_type = 'FINE'))  -- 27.01.2014 --- Morozova иначе удалялись начисления у которых дата начисления попадала в следующий период ОД
--													 AND ch.calperiod_end >= A_chargedate  -- 08.12.2011 --- без этого удалялись наперед сделанные начисления по концу ОТСРОЧКИ (если дата отсрочки была в следующем периоде).
                           and ch.id <> nvl(A_charges_id,0)													 
													 AND ch.paydoc_id = A_Paydoc_Id    -- <<< Удаляем только сделанное по  "своему"  основанию!
													 and A_FINE_FOR_PERCENT = 'N'  --- <<< 18.04.2012 <<< Иначе стирались начисления пени по изм. ставки рефинансирования при рассрочке...
                           and ch.document_id is null and ch.charge_type <> 'OTHER'
													 and (ch.TRANSTIME < (systimestamp - 0.0001)  --- <<< 27.03.2012 <<< -- предохранитель от стирания начислений за прошлый квартал,
														 OR (not (INSTR(ch.COMMENTS, 'дн.)') > 0)) )  ---      если период начинается не с начала квартала, а начисление назначено на будущий период ("...следующего квартала...")
													 AND nvl(ch.redir_paydoc_id, 0) = nvl(A_redir_paydoc_id, 0) -- <<< 25.06.2013 -- Иначе субаренда стирала другую субаренду на тот же день
												 AND ch.CHARGEDATE > ARecalc_Start_Date;  ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
          end if;
          
            if c = 1 then
								 -- удаляем старое начисления, если сальдо положительным (сумма начисления 0)
								 delete from sm.charges ch
								 where ch.id = A_charges_id_old and A_paysize = 0
  	 							     and ch.document_id is null and ch.charge_type <> 'OTHER'
                      AND  ch.chargedate > ARecalc_Start_Date;    ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
                      
               -- если начисление корректировалось (изменилась дата начисления),
               -- то в транзакции будет два начисления удаляем предыдущее начисление
               delete from sm.charges ch
               where ch.id = A_charges_id_old
  	 							     and ch.document_id is null and ch.charge_type <> 'OTHER'
 						  	AND  ch.chargedate > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
           else
               -- удаляем начисления, если на дату нового начисления уже имелись старые // TODO: 02.12.2011 - а при отсрочке - все отсроченные пишутся в 1 день!
              delete from sm.charges ch
              where ch.movesets_id = A_movesets_iD
                     and ch.obligationtype_id = A_obligationtype_id
                     and TRIM(cH.charge_type) = TRIM(A_charge_type_Orig)
                     and ch.chargedate = A_chargedate and ch.id <> nvl(A_charges_id, 0)
  	 							   and ch.document_id is null and ch.charge_type <> 'OTHER'
                     AND ch.paydoc_id = A_Paydoc_Id  ---28.01.2014
										 and ch.TRANSTIME < (systimestamp - 0.0001)   --- <<< 27.03.2012 <<< -- еще предохранитель от стирания начислений за прошлый квартал
										 AND ch.CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.

            end if;

             -- удаляем проводки, которые сформированы в открытом бухгалтерском периоде
             -- и не имеют соответствующих начислений
--- ???????????? А вот тут какая-то нестыковочка-с-с-с-.. !!!!!!!!!!!!!!
-- ### 16.12.2013 ### TEMP MARK ----------------------------
             delete from sm.charge_applies cha
             where cha.moveset_id = A_movesets_iD
                   and cha.obligtype_id = A_obligationtype_id
                   and trim(cha.charge_type) not in ('Y', 'N', 'D')
                   and trim(cha.charge_type) = A_charge_type_short --- <<< Это было закомментировано самой Надей, и уничтожались все проводки
                   and cha.apply_date > G_CloseDate
                   and cha.charge_id is not null
                   and not exists (select * from sm.charges ch
                                          where ch.movesets_id=A_movesets_iD
                                                and ch.obligationtype_id = A_obligationtype_id
                                                and ch.id = nvl(cha.charge_id, 0)  --07.04.2015 Morozova перенесено сюда условие
                                                and ch.paysize <> 0  --- 17.02.2014 Morozova   	
-- 						and TRIM(ch.charge_type) = TRIM(A_charge_type_Orig)  --- <<<  13.12.2011 <<< Иначе процентами стирались обязательства.
                                                and ch.factcharge = 'Y')                                                
                   and (trim(cha.reversal_role)='Исправляющая' or cha.reversal_role is null ); ---- 05.08.2014 Morozova исключаем удаление сторнированных и сторнирующих записей
--                   and trim(NVL(cha.reversal_role,'-')) <> 'Сторнирующая'; --- <<< Добавлено 14.10.2011, иначе удалялись сторнирующие записи при повторном изменении значения

         -- удаляем из payments_plan записи для обязательств с россрочкой у которых нет записи в payments_plan_draft
         delete from sm.payments_plan pp
         where pp.obligations_id = A_OBLIG_ID
               and (trim(A_comments) = 'Сумма по договору'
                   or TRIM(A_charge_type_Orig)='PERCENT')
               and pp.charges_id <> nvl(A_charges_id, 0)
               and not exists (select *
                               from sm.payments_plan_draft pd
                               where pd.obligationtype_id = A_obligationtype_id
                                     and pd.movesets_id = A_movesets_iD
                                     and pd.id = nvl(pp.payments_plan_draft_id, 0))
               and pp.payments_plan_draft_id is not null
							AND pp.FINEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.



   -------------------- ОТКРЫТЫЙ бухгалтерский период -----------------------------------------------------------------------------------------------------------
   if G_CloseDate < A_chargedate then
               -- удаляем сторнированные проводки, если apply_date находится в открытом периоде
               delete from sm.charge_applies cha
               where cha.moveset_id = A_movesets_iD
                   and cha.obligtype_id = A_obligationtype_id
                   and trim(cha.charge_type) = A_charge_type_short
                   and cha.apply_date > G_CloseDate
                   and trim(cha.reversal_role) = 'Сторнированная';
                   -- and cha.apply_date >= A_chargedate;   -- <<< ??? так оставались некоторые сторнированные записи
-- ### 16.12.2013 ### TEMP MARK ----------------------------
               -- удаляем сторнирующие проводки в открытом периоде, если им нет соответствующих сторнированных
              delete from sm.charge_applies cha
               where cha.moveset_id = A_movesets_iD
                   and cha.obligtype_id = A_obligationtype_id
                   and trim(cha.charge_type) = A_charge_type_short
                   and cha.apply_date > G_CloseDate
                   and trim(cha.reversal_role) = 'Сторнирующая'
                   and nvl(cha.reversallink_id, 0) not in (select id from sm.charge_applies cha1
                                                          where cha1.moveset_id = A_movesets_iD
                                                             and cha1.obligtype_id = A_obligationtype_id
                                                             and trim(cha1.charge_type) = A_charge_type_short
                                                             and trim(cha1.reversal_role) = 'Сторнированная'
																														 and cha1.apply_date<= G_CloseDate);

							-- VVV 12.02.2013 -- Удаляем нулевые проводки (почему бы они ни образовались) ---
							delete from sm.charge_applies cha
               where cha.moveset_id = A_movesets_iD
 									 and cha.summ = 0;
                   
               --- 07.04.2015 Morozova  удаляем проводки в открытом буж периоде, которые не имеют соответствующего начисления
               delete from sm.charge_applies cha
               where cha.moveset_id = A_movesets_iD
                   and cha.obligtype_id = A_obligationtype_id
 									 and cha.charge_id is null
                   and cha.reversal_role is null
                   and trim(cha.charge_type) in ('O', 'F')
                   and cha.apply_date > G_CloseDate;

                   -- сторнируем проводки по пене, разбитые по месяцам, и дата начисления которых попадает в закрытый период
                   -- (обычно начисления по пене договора, дата конца которого находится в закрытом периоде)
                   for xxrow in (select * from sm.charge_applies cha
                            where cha.moveset_id = A_movesets_iD
                                 and (TRIM(cha.charge_type) = A_charge_type_short
                                      OR (TRIM(cha.charge_type) = 'F' and A_FirstCharges = 'Y' and A_charge_type_Orig <>'PERCENT'))
		--	AND  TRIM(cha.charge_type) = 'F'
                                 and cha.obligtype_id = A_obligationtype_id
                                 and cha.corr_flag = 'N'
                                 and cha.apply_date <= G_CloseDate
                                 and cha.apply_date > ARecalc_Start_Date  --- 23.03.2015 Morozova
                                 and ((cha.apply_date between A_calperiod_start and A_Calperiod_End and A_charge_type_short = 'F')
                                  OR cha.apply_date > A_chargedate
                                  OR nvl(cha.charge_id, 0) not in (select id from sm.charges ch
                                                           where ch.movesets_id=A_movesets_iD                                                                
                                                                 and ch.obligationtype_id = A_obligationtype_id
                                                                 and ch.chargedate <= ARecalc_Start_Date --- 23.03.2015 Morozova исключаем сторнирование проводок до даты recalc_start_date
                                                                 and ch.factcharge = 'Y')
                                  OR (cha.charge_id = A_charges_id_old and cha.corr_flag = 'N'))
                            order by cha.id)
                   loop

                        -- ищем, была ли проводка просторнированна в открытом периоде с имеющимся начислением,
                        -- если да, то больше ее не сторнируем
                        select count(*) into c
                        from sm.charge_applies cha
                        where cha.reversallink_id = xxrow.id
                                 and cha.moveset_id = A_movesets_iD
                                 and TRIM(cha.charge_type) = A_charge_type_short
                                 and cha.obligtype_id = A_obligationtype_id
                                 and cha.corr_flag = 'Y'
                                 and cha.apply_date > G_CloseDate;

												if c > 0 then goto next_step; end if;

												 if length(xxrow.description) > 0 then
															A_comment_old := replace(replace(replace(replace(xxrow.description, 'Сторнирующая начисление: '), 'Сторнирующая: '), 'Сторнированная: '), 'Сторнированная - ');
												 end if;
                         update sm.charge_applies cha
                         set -- cha.charge_id = null, --<<< 07.12.2012 Что эта была? (Ссылка должна оставаться всегда!)
                             cha.reversal_role = 'Сторнированная',
                             cha.description =  'Сторнированная: ' || A_comment_old,
														 cha.corr_flag = 'Y'  -- <<< 18.02.2012 - ????????
                         where cha.id = xxrow.id;

                         -- сторнируем проводку
                         insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                        description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                        payments_distribution_id, reversal_role, reversallink_id, payment_id)
                         values (sm.seqcharge_applies.nextval, trunc(sysdate), -xxrow.summ, xxrow.obligtype_id,
                                                        A_movesets_iD, xxrow.charge_type,
                                                        'Сторнирующая: ' || A_comment_old,   A_charges_id,
                                                        'Y',  xxrow.cls_kbk_id, null, null, 'Сторнирующая', xxrow.id, A_PayID);
                         <<next_step>>
                         null;
                   end loop;

       if A_paysize = 0 then
           -- удаляем начисления по пене, если сальдо по обязательству >= 0
           delete from sm.charges ch
           where ch.movesets_id=A_movesets_iD
                 and ch.obligationtype_id = A_obligationtype_id
                 and TRIM(cH.charge_type) = TRIM(A_charge_type_Orig)
                 and A_charge_type_Orig = 'FINE'
  	 							     and ch.document_id is null and ch.charge_type <> 'OTHER'
                and ch.chargedate = A_chargedate
								AND ch.CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
      end if;

			---- Подправляем старую проводку (17.01.2012)
			Update SM.CHARGE_APPLIES ch
			    set ch.apply_date = A_chargedate, ch.summ = A_paysize
			    where ch.charge_id = A_charges_id  and ( trim(ch.reversal_role)='Исправляющая' or ch.reversal_role is null )
					              and (ch.apply_date <> A_chargedate OR ch.summ <> A_paysize);

   end if;

   ------------------ ЗАКРЫТЫЙ бухгалтерский период -------------------------------------------------------------------------------------------------------------------------------
    if G_CloseDate >= A_chargedate and nvl(A_charges_id, 0) >= 0 then --- 02.04.2014 Morozova  A_paysize <> 0 and 
             for xxrow in (
                           select cha.ID, cha.description, cha.cls_kbk_id, cha.charge_type, cha.obligtype_id, cha.summ, cha.apply_date, cha.charge_id
                           from sm.charge_applies cha
																where cha.moveset_id = A_movesets_id
																and TRIM(cha.charge_type) = A_charge_type_short
																and cha.obligtype_id = A_obligationtype_id
--			                          and cha.corr_flag = 'N' --  <<< 18.02.2012 - ????????
																and (trim(cha.reversal_role)='Исправляющая' OR cha.reversal_role is null)
																and cha.apply_date <= G_CloseDate
																and cha.apply_date <> trunc(sysdate)
																and (
															    (cha.apply_date between A_calperiod_start and A_Calperiod_End and A_charge_type_short = 'F' and A_charges_id is not null)  --11.08.2014 Morozova добавлено условие A_charges_id is not null
																	OR (cha.apply_date > A_chargedate and nvl(cha.charge_id, 0) >= nvl(A_charges_id, 0)-- and A_calperiod_start is not null)---28.01.2014 Morozova  иначе удалялись проводки с прошлого периода начисляемые в будущем периоде
																	   and nvl(cha.charge_id,0) not in (select id from sm.charges ch where ch.movesets_id = A_movesets_iD  --06.08.2014  Morozova
                                                      and ch.obligationtype_id = A_obligationtype_id 
                                                      and trim(ch.charge_type) = TRIM(A_charge_type_Orig)))
  																	OR (cha.apply_date > nvl(sm.getmovesetenddate(A_movesets_iD), trunc(sysdate))
                                      and nvl(cha.charge_id, 0) IN (select id from sm.charges ch --- 18.03.2014 Morozova  добавили условия несторнирования доп.начислений, если они внесены после даты закрытия ОД
                                                      where ch.movesets_id=A_movesets_iD and ch.document_id is null
                                                            and ch.obligationtype_id = A_obligationtype_id
                                                            and ch.calperiod_start is null --- 26.03.2014 Morozova
                                                            and cha.apply_date = A_chargedate
                                                            and TRIM(cH.charge_type) = TRIM(A_charge_type_Orig)
                                                            and TRIM(cH.charge_type) <> 'OTHER'))
																	OR (cha.apply_date = A_chargedate and cha.payment_id is not null)
                                  or (cha.apply_date = A_chargedate and A_calperiod_start is null  and A_calperiod_end is null  --- 12.02.2014 Morozova при изменении параметров единовременного обязательства
                                               and nvl(cha.charge_id, 0) IN (select id from sm.charges ch  
                                                      where ch.movesets_id=A_movesets_iD and ch.document_id is null
                                                            and ch.obligationtype_id = A_obligationtype_id
                                                            and TRIM(cH.charge_type) = TRIM(A_charge_type_Orig)
                                                            and TRIM(cH.charge_type) = 'OBLIGATION'))
																	OR (cha.charge_id is null and  cha.apply_date > ARecalc_Start_Date  ---23.03.2015  Morozova -- сторнируем только после даты перерасчета
																		 and cha.id not in (select cha1.reversallink_id from sm.charge_applies cha1
																																where cha1.moveset_id = A_movesets_ID
																																	 and cha1.obligtype_id = A_obligationtype_id
																																	 and trim(cha1.charge_type) = A_charge_type_short
																																	 and cha1.reversallink_id is not null))
																)
--		  											OR (cha.charge_id = A_charges_id_old and cha.corr_flag = 'N') --  <<< 18.02.2012 - Похоже, так????????
                          union
                               select cha.ID, cha.description, cha.cls_kbk_id, cha.charge_type, cha.obligtype_id, cha.summ, cha.apply_date, cha.charge_id
                               from sm.charge_applies cha
                                    where cha.moveset_id=A_movesets_iD
                                           and cha.obligtype_id = A_obligationtype_id
                                           and TRIM(cha.charge_type) = A_charge_type_short
                                           and cha.corr_flag = 'N'
                                           and cha.apply_date <= G_CloseDate
                                           and cha.apply_date <= A_chargedate
                                           and cha.apply_date > ARecalc_Start_Date  --- 24.03.2015 Morozova
                                           and cha.apply_date <> trunc(sysdate)
                                           and A_calperiod_start is NOT null
                                           and nvl(cha.charge_id, 0) not in (select id from sm.charges ch
                                                    where ch.movesets_id=A_movesets_iD
                                                          and ch.obligationtype_id = A_obligationtype_id
                                                          and (TRIM(cH.charge_type) = TRIM(A_charge_type_Orig) or TRIM(cH.charge_type) = TRIM('OTHER'))
                                                          and ch.factcharge = 'Y')
                                           and A_FirstCharges = 'Y'
                                           and (trim(cha.reversal_role)='Исправляющая' OR cha.reversal_role is null)  -- <<< 07.12.2012
                          union
                               --- 13.08.2014 Morozova
                               --- выбираем доп. начисления, которые не имеют своих проводок (если таковые имеются)
                               select 0, ch.comments, ch.cls_kbk_id, ch.charge_type, ch.obligationtype_id, ch.paysize, ch.chargedate, ch.id
                               from sm.charges ch
                                    where ch.movesets_id=A_movesets_iD
                                           and ch.obligationtype_id = A_obligationtype_id                                           
                                           and ch.factcharge = 'Y'   ---  09.02.2014 Morozova  только для фактических доп начислений
                                           and (((TRIM(ch.charge_type) = 'OTHER' or TRIM(ch.charge_type) = 'OBLIGATION') and A_charge_type_short='O') 
                                                                        or ( TRIM(ch.charge_type) = 'FINE' and A_charge_type_short='F'))
                                           and ch.document_id is not null
                                           and ch.id not in ( select nvl(cha.charge_ID, 0)
                                                                from sm.charge_applies cha
                                                                      where cha.moveset_id=A_movesets_iD
                                                                           and cha.obligtype_id = A_obligationtype_id
                                                                           and TRIM(cha.charge_type) = A_charge_type_short)
                                    and A_FirstCharges = 'Y'
												ORDER BY APPLY_DATE
                        )
             loop
                 if xxrow.id > 0 then
                        -- ищем, была ли проводка просторнированна в открытом периоде с имеющимся начислением,
                        -- если да, то больше ее не сторнируем
                        select count(*) into c
                        from sm.charge_applies cha
                        where cha.reversallink_id = xxrow.id
                                 and cha.moveset_id = A_movesets_iD
                                 and TRIM(cha.charge_type) = A_charge_type_short
                                 and cha.obligtype_id = A_obligationtype_id
                                 and cha.corr_flag = 'Y'
                                 and cha.apply_date > G_CloseDate;
                        if c > 0 then goto next_step; end if;

                         --     всем проводкам, соответствующим этим начислениям,
                         --     проставить признак "сторнированная"
                         --     и обнулить ID начисления

                         A_comment_old := replace(xxrow.description, 'Исправляющая', 'Исправл.');
                         A_comment_old := replace(xxrow.description, 'Сторнированная - ');
                         A_comment_old := replace(xxrow.description, 'Сторнированная: ');
                         update sm.charge_applies cha
                         set  -- cha.charge_id = -1,  --<<< 07.12.2012 Что эта была? (Ссылка должна оставаться всегда!)
                             cha.reversal_role = 'Сторнированная'
                             , cha.description =  'Сторнированная: ' || A_comment_old
														 , cha.corr_flag = 'Y'  -- <<< 18.02.2012 - ????????
 --                             , cha.payment_id = null -- <<< 07.12.2012 Почему-то  payment_id заполнялся в null???
                         where cha.id = xxrow.id;
                         
                         --     добавить проводку с признаком "Старнирующая"
                         --     (реквизиты сторнированной, но с отриц суммой)
                         --     указать ссылку на сторнируемую проводку
                         insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                        description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                        payments_distribution_id, reversal_role, reversallink_id, payment_id)
                         values (sm.seqcharge_applies.nextval, trunc(sysdate), -xxrow.summ, xxrow.obligtype_id,
                                                        A_movesets_id, xxrow.charge_type,
                                                         'Сторнирующая: ' || A_comment_old,  A_charges_id,
                                                        'Y',  xxrow.cls_kbk_id, null, null, 'Сторнирующая'
                                                        , xxrow.id, A_PayID);
                        
                        --- 07.02.2014 Morozova                               
                        --- ищем, была ли весена исправляющая проводка в открытом периоде с имеющимся начислением,
                        --- если да, то больше ее не вносим
                        select count(*) into c
                        from sm.charge_applies cha
                           where cha.moveset_id = A_movesets_iD
                               and cha.obligtype_id = A_obligationtype_id
                               and trim(cha.charge_type) = A_charge_type_short
                               and cha.apply_date > G_CloseDate
                               and (trim(cha.reversal_role) = 'Исправляющая' or cha.reversal_role is null)
                               and cha.charge_id = A_charges_id;
                        if c > 0 or A_paysize <> 0 or nvl(A_charges_id, 0) = 0 then goto next_step; end if;   ---26.05.2014 Morozova добавлено условие or nvl(A_charges_id,0) = 0
                        
                        ---	 Занесение исправляющей проводки -- (17,01,2012) ---
                            insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                            description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                            payments_distribution_id, reversal_role, reversallink_id, payment_id)
                            values (sm.seqcharge_applies.nextval, trunc(sysdate), A_paysize, A_obligationtype_id, A_movesets_id,  A_charge_type_short,
                                             'Исправляющая: ' || TRIM(A_comments), A_charges_id, 'N',  A_Cls_Kbk_Id, null, null, 'Исправляющая', xxrow.id, A_PayID);

                 else
                            --- 08.08.2014 Morozova  Занесение исправляющей проводки для доп. начисления -- 
                            insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                            description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                            payments_distribution_id, reversal_role, reversallink_id, payment_id)
                            values (sm.seqcharge_applies.nextval,  trunc(sysdate), xxrow.summ, xxrow.obligtype_id, A_movesets_id,  A_charge_type_short,
                                             'Исправляющая: ' || TRIM(xxrow.description), xxrow.charge_id, 'N',  xxrow.cls_kbk_id,
                                              null, null, 'Исправляющая', null, null);
                 end if;   
                 <<next_step>>
                 null; 
             end loop;
             --- если по единовременному обязательству в закрытом бух периоде была просторнирована проводка, то в открытом бух периоде правим исправляющую  
             --- если таковой нет, то выбираем сторнирующую проводку и заводим исправляющую  Morozova 23.01.2014)
             BEGIN
                  select cha.id into c
                  from sm.charge_applies cha
                           where cha.moveset_id = A_movesets_iD
                               and cha.obligtype_id = A_obligationtype_id
                               and trim(cha.charge_type) = A_charge_type_short
                               and A_charge_type_short = 'O'
                               and cha.apply_date > G_CloseDate
                               and (trim(cha.reversal_role) = 'Исправляющая' or cha.reversal_role is null)
                               and cha.charge_id = A_charges_id
                               and A_Calperiod_Start is null;
                 
                    Update SM.CHARGE_APPLIES cha
                    set cha.apply_date = trunc(sysdate), cha.summ = A_paysize
                    where cha.id = c;
             exception
                when no_data_found then
                  c := 0;
    /*            when others then              
                       c := 2;
                       insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
                       values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'Ошибка при поиске действующих(исправляющих) проводок ' ||A_movesets_iD, 'RecalcChargesApplies', '', 3, 3, 2, A_movesets_iD, null, 'N');
    */         end;
             
             begin
               if c = 0 and  A_paysize <> 0 then
                    select cha.reversallink_id into c
                    from sm.charge_applies cha
                           where cha.moveset_id = A_movesets_iD
                               and cha.obligtype_id = A_obligationtype_id
                               and trim(cha.charge_type) = A_charge_type_short
                               and A_charge_type_short = 'O'
                               and cha.apply_date > G_CloseDate
                               and trim(cha.reversal_role) = 'Сторнирующая'
                               and cha.charge_id = A_charges_id
                               and A_Calperiod_Start is null
                               and trim(substr(cha.description, length('Сторнирующая: '), length(cha.description)-length('Сторнирующая:'))) =  TRIM(A_comments);                                    
                      insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                              description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                              payments_distribution_id, reversal_role, reversallink_id, payment_id)
                      values (sm.seqcharge_applies.nextval, trunc(sysdate), A_paysize, A_obligationtype_id, A_movesets_id,  A_charge_type_short,
                                               'Исправляющая: ' || TRIM(A_comments), A_charges_id, 'N',  A_Cls_Kbk_Id, null, null, 'Исправляющая', c, A_PayID);  
                end if;
              exception
                when no_data_found then
                  null;
     /*           when others then
                       insert into SM.X_SM_MESSAGES ms (ID, MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED)
                       values (SM.SEQX_SM_MESSAGES_ERR.nextval, sysdate, 'Ошибка при поиске сторнирующих проводок ' ||A_movesets_iD, 'RecalcChargesApplies', '', 3, 3, 2, A_movesets_iD, null, 'N');
     */         end;                    

    end if;
end;

END; ----------- пакета OBLIG_ACC_PKG -------------------------------
/
