prompt
prompt Creating package body ORGSTATE_AND_SHARE_PKG
prompt ============================================
prompt
create or replace package body sm.OrgState_And_Share_PKG is
-------------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetOrgGoldStockOwnerID(OrgID IN NUMBER, StateDate IN DATE) RETURN NUMBER
--Возвращает ID владельца специального права для заданного ЮЛ на заданную дату
--Параметры:
--  OrgID - ID организации
--  StateDate - дата
IS
  d DATE;
  nClientID number(27);
  nTmp number(27);
  stateValue number(27);
begin
  d:=trunc(StateDate);
  
  Select count(*) into nTmp from sm.Organisations t where t.ID = OrgID;
  if (nTmp > 0) then
    Select t.CLIENTS_ID into nClientID from sm.Organisations t where t.ID = OrgID;
  else
    return null;  
  end if; 
  
  for xOBJ in (
      select
        org.objects_id
      from
        sm.organisations org
      where
        org.id=OrgID
                )
  loop

      for xxST in (
        select
          st.GOLDSTOCKOWNER_ID 
        from
          sm.states st
        where
          st.objects_id = xOBJ.objects_id and
          st.calcdate<=d
        order by st.calcdate DESC
                 )
      loop   
          stateValue := xxST.GOLDSTOCKOWNER_ID; 
          exit;
      end loop;
      
  end loop;  
  return stateValue;
end;


-----------------------------------------------------------------------------------------------------------------------------------------------------
Function GetOrgStateValue(OrgID IN NUMBER, StateDate IN DATE, StateType IN CHARACTER) RETURN NUMBER 
--Возвращает определенный показатель деятельности хоз.общества в рублях на заданную дату
--Параметры:
--  OrgID - ID организации (хоз.общества)
--  StateDate - дата
--  StateType -
--                  'W' - (WorkersNumber) среднесписочная численность;
--                  'C' - (NominalCost) размер уставного капитала, руб;
--                  'N' - (SharesNumber) общее количество выпущенных акций, шт.;
--                  'S' - (SharesPrevNumber) количество выпущенных привилегированных акций, шт.;
IS
  stateValue number;
  d DATE;
begin
  d:=trunc(StateDate);

  for xOBJ in (
      select
        org.objects_id
      from
        sm.organisations org
      where
        org.id=OrgID
                )
  loop

      for xxST in (
        select
          st.WORKERSNUMBER,
          st.NOMINALCOST,
          st.SHARESNUMBER,
          st.SHARESPREVNUMBER
        from
          sm.states st
        where
          st.objects_id = xOBJ.objects_id and
          st.calcdate<=d
        order by st.calcdate DESC
                 )
      loop            
          if StateType='W' then
             stateValue := xxST.WORKERSNUMBER;
          elsif StateType='C' then
             stateValue := xxST.NOMINALCOST;
          elsif StateType='N' then
             stateValue := xxST.SHARESNUMBER;
          elsif StateType='S' then
             stateValue := xxST.SHARESPREVNUMBER;
          end if;
      
          if stateValue is not null  then
             return stateValue;
          end if;
      end loop;

  end loop;

  return stateValue;
end;



-------------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetOrgObjectSumCost(OrgID IN NUMBER, StateDate IN DATE, StateType IN CHARACTER) RETURN NUMBER
-- Вычисляет балансовую или остаточную стоимость ОС (собственности базового собственника) на балансе определенного ЮЛ в рублях на заданную дату
-- Параметры:
--  OrgID - ID организации
--  StateDate - дата
--  StateType -
--                  'B' - (StartPay) Первоначальная (восстановительная) (балансовая) ст-ть;
--                  'R' - (Pay) Остаточная стоимость, руб.
IS
  costValue number(27,2);
  sumValue number(27,2) := 0.00;
  d DATE;
  strFieldName varchar2(200);
  nClientID number(27);
  nTmp number(27);
  nTmpValue number(27,2);
  TYPE cv_type IS REF CURSOR;
  cv cv_type;
  nKumiID number(27);
begin
  d:=trunc(StateDate); 

  if StateType='B' then
     strFieldName := 'sum(sm.GetObjectCost(obj.ID, ''' || to_char(d) || ''', ''B''))';
  elsif StateType='R' then
     strFieldName := 'sum(sm.GetObjectCost(obj.ID, ''' || to_char(d) || ''', ''R''))';
  else
    return null;
  end if;
  
  Select count(*) into nTmp from sm.Organisations t where t.ID = OrgID;
  if (nTmp > 0) then
    Select t.CLIENTS_ID into nClientID from sm.Organisations t where t.ID = OrgID;
  else
    return null;  
  end if; 
  
  nKumiID := sm.multiowning_pkg.GetCurrentOwnerID(); 
  if (nKumiID is not null) then  
    open cv for 
        'select ' ||
          strFieldName || 
        'from ' ||
        '  sm.Objects obj ' ||
        ' where ' ||
        ' obj.objtypes_id<>22 and ' || 
        '  obj.ID in (select i.Object_ID from sm.MoveItems i, sm.MovePeriods p, sm.Movesets s ' ||
           ' where i.MovePeriod_ID=p.id and p.MoveSet_ID=s.ID '
           || ' and p.SinceDate<=''' || to_char(d) 
           || ''' and nvl(p.EndDate,''' || to_char(d) || ''')>=''' || to_char(d) 
           || ''' and s.MoveType_ID=2 and s.Client_ID=' || to_char(nClientID) || ') and '||
        '  obj.ID in (select i.Object_ID from sm.MoveItems i, sm.MovePeriods p, sm.Movesets s ' ||
           ' where i.MovePeriod_ID=p.id and p.MoveSet_ID=s.ID '
           || ' and p.SinceDate<=''' || to_char(d) 
           || ''' and nvl(p.EndDate,''' || to_char(d) || ''')>=''' || to_char(d) 
           || ''' and s.MoveType_ID=1 and s.Client_ID=' || to_char(nKumiID) || ') '; 
      /*  '  obj.ID in (select mv.Objects_ID from sm.Movements mv where mv.PostingDate<=''' || to_char(d) 
           || ''' and nvl(mv.EndDate,''' || to_char(d) || ''')>=''' || to_char(d) 
           || ''' and mv.MoveType_ID=2 and mv.CLientsTo_ID=' || to_char(nClientID) || ' and '||
                    ' mv.mv_objects_id is null and '||  -- только объекты, которые не входят в имущественный комплекс
        ' sm.getpositionclientidbydate(mv.Objects_id,1,'''|| to_char(d) ||''')= '||to_char(nKumiID) || ') ';
                
    /*   '  exists (select * from sm.Movements mv1 where mv.Objects_id=mv1.Objects_id and mv1.PostingDate<=''' || to_char(d) 
           || ''' and nvl(mv1.EndDate,''' || to_char(d) || ''')>=''' || to_char(d) 
           || ''' and mv1.MoveType_ID=1 and mv1.CLientsTo_ID=' || to_char(nKumiID) || ')) ';*/
   
   loop
      fetch cv into nTmpValue;
      exit when cv%notfound;
      if cv%rowcount =1 then  
        if nTmpValue is not null  then
           sumValue := sumValue + nTmpValue;
        end if;
      end if;
    end loop;
     
    if sumValue is not null then
       costValue := sumValue;
    end if;
  end if;
      
  return costValue;
end;

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetOrgObjectCost(OrgID IN NUMBER, StateDate IN DATE, StateType IN CHARACTER) RETURN NUMBER
-- Возвращает балансовую или остаточную стоимость ОС ЮЛ в рублях на заданную дату:
--
--    Сначала ищет значение стоимости на заданную дату в таблице States,
--    если не найдено, то вызывается ф-ция GetOrgObjectSumCost, вычисляющая суммарную стоимость объектов собственности базового собственника на балансе данного ЮЛ  на заданную дату.
--
-- Параметры:
--  OrgID - ID организации
--  StateDate - дата
--  StateType -
--                  'B' - (StartPay) Первоначальная (восстановительная) (балансовая) ст-ть;
--                  'R' - (Pay) Остаточная стоимость, руб.
IS
  costValue number(27,2);
  sumValue number(27,2) := 0.00;
  nObjID number(27);
  hasAuth char(1);
begin  
  --Сначала поищем значение стоимости в States
--  select org.objects_id into nObjID from sm.organisations org where org.id=OrgID;  --x ver. 4.8.5 
--  costValue := sm.GetObjectCost(nObjID, StateDate, StateType); --x ver. 4.8.5

  --Если в States значения не найдено
 --Не для хоз.обществ -- ver. 4.8.5               
  select f.hasauthcapital into hasAuth from sm.organisations org, sm.orgforms f where org.orgform=f.id and org.id=OrgID;
  if (hasAuth <> '1') then                  
    -- попытаемся вычислить суммарную стоимость объектов собственности базового собственника на балансе данного ЮЛ
    sumValue := sm.OrgState_and_Share_PKG.GetOrgObjectSumCost(OrgID, StateDate, StateType);
    
    if sumValue is not null then
      costValue := sumValue;
    end if;
  end if;
       
  return costValue;
end;

----------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetMunicipalShare(OrgID IN NUMBER, CalcDate IN DATE, UnitType IN CHARACTER, ShareCategory IN CHARACTER) RETURN NUMBER
-- Возвращает размер доли базового собственника в капитале заданного хоз.общества в заданных ед.изм. (штуках акций,%, рублях) на заданную дату
-- Параметры:
--          OrgID - ID организации (хоз.общества)
--          CalcDate - дата
--          UnitType - ед.изм. доли ('N' - шт.; 'P' - %; 'C' - руб.)
--          ShareCategory - категория акций, если UnitType='N' ('O' - простые; 'S' - привилегированные; null - все категории)
IS
  d DATE;
  strFieldName varchar2(200);
  strCategoryFilter varchar2(200) := '';
  nShare number(27,6);
  nVal number(27,6);
  nSumVal number(27,6) := 0.000000;
  nATOShare number(27,2);
  nCapital number(27,2);
  TYPE cv_type IS REF CURSOR;
  cv cv_type;
  ccv cv_type;
  nObjID number(27);
  nSharecategoryID number(27);
  nKumiID number(27);
  iTmp integer;
begin
 
  d:=trunc(CalcDate);

  --акций, штук
  if UnitType='N' then
    strFieldName := 'st.SHARESNUMBER';

    if (ShareCategory in ('O','S')) then

      --Категория акций "Привилегированные"
      Select t.ID into nSharecategoryID from sm.ShareCategory t where t.guid like '3C417627105E4339BBF88AA979254BAD';
      if (nSharecategoryID is null) then
         raise_application_error(-20101,'В справочнике категорий акций и ЦБ отсутствует запись ''Привилегированные'' с GUID=' || '3C417627105E4339BBF88AA979254BAD');
      end if;

      --Категория акций "Простые"
      Select t.ID into nSharecategoryID from sm.ShareCategory t where t.guid like 'F363F1CE9CF440BAA9B635EFE1676677';
      if (nSharecategoryID is null) then
         raise_application_error(-20101,'В справочнике категорий акций и ЦБ отсутствует запись ''Простые'' с GUID=' || 'F363F1CE9CF440BAA9B635EFE1676677');
      end if;

      if (nSharecategoryID is not null) then
        strCategoryFilter := ' and osh.sharecategory_id = ' || to_char(nSharecategoryID);
      end if;

    end if;

  --доля в %
  elsif UnitType='P' then

    --определим орг.правовую форму ЮЛ
    Select count(*) into iTmp
    from
      sm.organisations org, sm.orgforms f
    where
      org.id=OrgID and f.id=org.orgform and f.is_publicoffice<>'Y' and f.hasauthorizedfund<>'Y';

    -- если орг.правовая форма ЮЛ - не МУ и не МУП
    if (iTmp > 0) then
        --номинальная стоимость доли базового собственника
        nATOShare := SM.OrgState_And_Share_PKG.GetMunicipalShare(OrgID, CalcDate, 'C', null);

        if (nATOShare is not null and nATOShare <> 0) then
          --уставный капитал хоз.общества
          nCapital := SM.OrgState_And_Share_PKG.GetOrgStateValue(OrgID, CalcDate, 'C');
          if (nCapital is not null and nCapital <> 0) then
            --доля базового собственника в капитале хоз.общества (%)
            nShare := nATOShare * 100 / nCapital;
          end if;
        end if;

    -- если МУ или МУП
    else
        --%  участия определяем по ОД Собственность c Пакетом данного ЮЛ
        Select mi.amount   --SM.OrgState_And_Share_PKG.GetObjSharesStateValue(o.objects_id, CalcDate, 'P')
           into nShare
        from
           sm.ObjShares o,
           sm.Movesets ms,
           sm.moveitems mi,
           sm.moveperiods mp
        where
           ms.movetype_id=1 and
           mp.moveset_id=ms.id and
           mi.moveperiod_id=mp.id and
           mi.object_id=o.objects_id and
           ms.client_id=sm.multiowning_pkg.GetCurrentOwnerID() and
           trunc(mp.sincedate)<=trunc(CalcDate) and
          (trunc(mp.enddate)>=trunc(CalcDate) or mp.enddate is null)

           and o.organisations_id=OrgID
           and o.owner_id=sm.multiowning_pkg.GetCurrentOwnerID();
--           and sm.GetPositionClientIDByDate(o.objects_id, 1, CalcDate)=sm.multiowning_pkg.GetCurrentOwnerID();

    end if;
    return nShare;

  --доля в руб.
  elsif UnitType='C' then
    strFieldName := 'st.NOMINALCOST';

  else
    return null;

  end if;

  nKumiID := sm.multiowning_pkg.GetCurrentOwnerID();

  if (nKumiID is not null and OrgID is not null) then
      open cv for
          'select ' ||
          '  osh.objects_id ' ||
          'from ' ||
          '  sm.objshares osh ' ||
          'where ' ||
          '  osh.owner_id=' || to_char(nKumiID) || ' and ' ||
          '  osh.organisations_id=' || to_char(OrgID)
            || strCategoryFilter;
      loop
        fetch cv into nObjID;
        exit when cv%notfound;
        if cv%rowcount > 0 then

          open ccv for
            'select ' ||
              strFieldName ||
            ' from ' ||
            '  sm.states st ' ||
            ' where ' ||
            '  st.objects_id=' || to_char(nObjID) || ' and ' ||
            '  st.calcdate<=''' || to_char(d) || '''' || 
            ' order by st.calcdate DESC';
          loop
            fetch ccv into nVal;
            exit when ccv%notfound;
            if ccv%rowcount > 0 then

              if nVal is not null  then
                nSumVal := nSumVal + nvl(nVal, 0);
                exit;
              end if;

            end if;
          end loop;


        end if;
      end loop;
  end if;

  if (nSumVal is not null) then
     nShare := nSumVal;

     if (UnitType = 'C') then
        nShare := round(nShare,2);
     end if;
  end if;

  return nShare;
end;


----------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetObjSharesStateValue(ObjID IN NUMBER, StateDate IN DATE, StateType IN CHARACTER) RETURN NUMBER
-- Возвращает свойства объекта "Пакеты акций, доли в капитале" на заданную дату
-- Параметры:
-- ObjID - ID объекта
-- StateDate - дата 
--  StateType -      'P' - (Amount) размер доли, процент
--                   'N' - (SharesNumber) количество акций или др. ЦБ в пакете, штук (может быть дробное!!!)
--                   'C' - (NominalCost) номинальная стоимость доли, руб.
IS
 stateValue number;
 d DATE;
begin

 d := trunc(StateDate);
 stateValue := null;
 for B in (
   select
     st.amount,
     st.sharesnumber,
     st.nominalcost
   from
     sm.states st
   where
     st.objects_id=ObjID and     
     st.calcdate<=d order by st.calcdate DESC)
 loop
     if (StateType='P') then
       stateValue := B.AMOUNT;
     elsif (StateType='N') then
       stateValue := B.SHARESNUMBER;
     elsif (StateType='C') then
       stateValue := nvl(B.NOMINALCOST,0);     
     end if;
    
     if stateValue is not null  then
       return stateValue;
     end if;
 end loop;
     
 return stateValue;
end;

----------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------
end;
/
grant execute on SM.ORGSTATE_AND_SHARE_PKG to SM_ALLUSERS;
grant execute on SM.ORGSTATE_AND_SHARE_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body PAYMENTS_DISTRIBUTE_PKG
prompt =============================================
prompt
create or replace package body sm.PAYMENTS_DISTRIBUTE_PKG is

------ В качестве документации:     В коде (и БД) используются следующие признаки направления разнесения платежа:
------  'Y'- основной долг;  'N'- пеня; 'P'- проценты; 'D'- распределяемый на все; 'M'- распределяемый между осн.долгом и процентами.

IsCalcFineNeed boolean := true;
G_CloseDate date := to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy');


-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Procedure SetIsCalcFineNeed( setparam boolean)  is
BEGIN
      IsCalcFineNeed := setparam;
END;


--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- функция возвращает размер процентов, которые должны быть начислены НА ПЕРИОД переданных дат.
-- (За основу бралась более сложная ф-я из FULLRECALC_PKG - в этой проще с периодом)
FUNCTION PercentSizeForPayment(AMoveSet_ID number, AObligType_ID number, A_PayDate date, prev_date_calc date, Comment_txt out varchar2, IsChargeOnPayDate NUMBER) return number is
  Result NUMBER(27,2);

creditsize NUMBER(27,2);
creditpercent NUMBER(27,12);
creditpercentondebt char(1);
creditpercentconst char(1);
creditrefinratepart_num NUMBER(27);
creditrefinratepart_denom NUMBER(27);

 OBLIG_ID number(27);
 cur_dept number(27,2);
  prev_pay date;
 creditpercentpart number(27,14);
 CurRefinRate number(27,2);
 DayByPersent number;
 on_sum number(27,2);
 OtherDebt number(27,2);
itmp integer;
tmp_val number(27,2);
DateToSumPayments  DATE;
DaysInYear integer := 365;
NoCreditpercent CHAR(1) := 'N'; 

BEGIN

 Result:=0;

select count(*) into itmp
   from sm.obligations obl
   where obl.moveset_id=AMoveSet_ID and obl.obligationtype_id=AObligType_ID;
if itmp = 1 then
         select obl.id
         into OBLIG_ID
         from sm.obligations obl
         where obl.moveset_id=AMoveSet_ID and obl.obligationtype_id=AObligType_ID;
else
          RETURN 0;
  end if;

select count(*) into itmp
 from sm.paydocs pd,
      sm.moveperiods mp
 where pd.moveperiod_id=mp.id and
      mp.moveset_id=AMoveSet_ID and
      pd.obligationtype_id = AObligType_ID;
if itmp = 1 then
           select
                  pd.creditsize,
                  pd.creditpercent,
                  pd.creditpercentondebt,
                  pd.creditpercentconst,
                  pd.creditrefinratepart_num,
                  pd.creditrefinratepart_denom,
									pd.no_creditpercent 
           into
                  creditsize,
                  creditpercent,
                  creditpercentondebt,
                  creditpercentconst,
                  creditrefinratepart_num,
                  creditrefinratepart_denom,
									NoCreditpercent
           from sm.paydocs pd,
                sm.moveperiods mp
           where pd.moveperiod_id=mp.id and
                mp.moveset_id=AMoveSet_ID and
                pd.obligationtype_id = AObligType_ID;
else
         RETURN 0;
end if;

if NoCreditpercent = 'Y' then
	     RETURN 0;
end if;

			 
---------------- Учет доп.начислений ---------------
 select count(*) into itmp
 from SM.CHARGES ch
 where ch.MOVESETS_ID = AMoveSet_ID and ch.OBLIGATIONTYPE_ID = AObligType_ID
 and trim(ch.CHARGE_TYPE) =  'OTHER'
 and ch.FINEDATE <= A_PayDate;
if itmp > 0 then
        Select Sum(ch.PAYSIZE) into OtherDebt
         from SM.CHARGES ch
         where ch.MOVESETS_ID = AMoveSet_ID and ch.OBLIGATIONTYPE_ID = AObligType_ID
         and trim(ch.CHARGE_TYPE) =  'OTHER'
         and ch.FINEDATE <= A_PayDate;
  end if;
 ---------------------------------------------------------------
cur_dept:= creditsize + NVL(OtherDebt, 0) ;

 prev_pay:= prev_date_calc;
-- Проценты на день опаты по старому долгу, или уже уменьшенные
if (IsChargeOnPayDate=1) then  -- по старому долгу
    DateToSumPayments := A_PayDate;
else --уже уменьшенные
    DateToSumPayments := A_PayDate +1;
end if;
------- Сумма оплаты до периода начисления процентов
select SUM(NVL(pd.val,0))  into tmp_val
  from sm.payments_distribution pd,
         sm.payments_plan pp,
         sm.payments p,
         sm.charges ch,
         sm.documents d,
         sm.sm_settings_tab st
  where pd.payments_plan_id=pp.id and
         pp.obligations_id = OBLIG_ID and
         p.id=pd.payments_id and
         d.id=p.documents_id and st.key_name = 'PAYMENT_USE_APPLY_DATE' and
         trim(ch.charge_type) in ('OBLIGATION', 'OTHER')  and
         ch.id=pp.CHARGES_ID and
         pp.PAYMENTS_PLAN_DRAFT_ID is not null and
         (CASE when (st.value = 'N' and p.paymethod_id!=3) then d.docdate else p.Apply_Date end) < DateToSumPayments;
  if tmp_val is not null then
      cur_dept := cur_dept - tmp_val;
  end if;
----------------------------------------------------------------------------------------------
      --- <<< 23.03.2012 <<< --- Правильно применяем дневную долю  процента для високосного года
      if SM.IsLeapDate(A_PayDate) then
            DaysInYear := 366;
      else
            DaysInYear := 365;
      end if;

   if cur_dept>0 and A_PayDate>prev_pay then
       -- процент по плану
       if creditpercentconst='Y' then -- твердый процент
           creditpercentpart:=creditpercent/(DaysInYear * 100); -- в день
       else -- от ставки рефинансирования на день оплаты
           CurRefinRate:=FULLRECALC_PKG.RefineRateOnDate(A_PayDate);
           creditpercentpart:=CurRefinRate*creditrefinratepart_num/(creditrefinratepart_denom * DaysInYear * 100);
       end if;
       DayByPersent:=A_PayDate-prev_pay;
       if CreditPercentOnDebt='Y' then
           Result:=cur_dept*DayByPersent*creditpercentpart;
           on_sum:=cur_dept;
       else
           Result:=creditsize*DayByPersent*creditpercentpart;
           on_sum:=creditsize;
       end if;

       Comment_txt:='Проценты на сумму ' || to_char(on_sum) || ' за '||to_char(A_PayDate-prev_pay) || 'дн. (c '|| to_char(prev_pay+1,'dd.MM.yyyy') ||' по '|| to_char(A_PayDate,'dd.MM.yyyy') ||')';

   end if;

 RETURN Result;

END PercentSizeForPayment;

--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- Дополнительные действия для поступившего [либо "вновь распределяемого"] платежа.
 -- ( Если платеж связан с основанием на продажу с рассрочкой
 --   - происходит еще начисление процентов. )
        -- Параметры:
             -- PayID      -- Идентификатор рассматриваемого платежа
             --PayDate SM.PAYMENTS.WRITEDATE%type;           -- Дата текущего обрабатываемого платежа
             --ObligTypeID SM.OBLIGATIONTYPE.ID%type;         -- ID типа обязательства
             --MoveSetID   SM.MOVESETS.ID%type;                   -- Оно нада чобы знать  к чему оно все относится
Function PAYMENT_ADD_PERCENTS(PayPalnID SM.PAYMENTS_PLAN.ID%type, PayPlanDate date, PayDate date,   PayPlanDatePrevParam date,
MoveSetID number, ObligTypeID number, FilledByDraftID number,  Fact_Charge char, PaymentDescription varchar2 , PayID in number
, FirstCharge in varchar2)  return boolean
 is
c integer;        --*
idNext integer;   --*
A_comments varchar2(100);
A_corr_flag char(1);
A_chargedate date;
A_reversal_role varchar2(100);

    HasWrite boolean := false;                                           -- Возвращаемый функцией признак что запись процентов или пени состоялась
    ObligID SM.CHARGES.ID%type;                                  -- ID Обязательства
   ObligGroup number(1);                                                 -- 1 - простое (тогда выходим); 2 - с рассрочкой (тогда начисляем проценты и пеню); 3 - с пеней определенной на день оплаты (тогда начисляем пеню).
   PayDatePrev date;                                                          -- Дата предыдущего платежа
   PayPlanDatePrev date := PayPlanDatePrevParam;     --  Дата предыдущего плана поступления
   ChargeUseHolidays char(1);
   Comment_txt varchar2(400);                                      -- Комментарий к начислениям
   ValToWrite number(27, 2);                                          -- Сумма начисляемых процентов или пени
   PDID number;                                                                  -- ID PayDocs-а - условий на период

   ChargesDate date;                                                          -- Дата окончания периода за который пишется начисление
   PrevChargesDate date;                                                 -- Дата начала периода за который пишется начисление
   MainKBKID SM.PAYDOCS.MAIN_CLS_KBK_ID%type := null;
   FineKBKID SM.PAYDOCS.FINE_CLS_KBK_ID%type := null;
   PercentKBKID SM.PAYDOCS.PERCENT_CLS_KBK_ID%type := null;
   itmp integer := 0;
   PercentPeriodStart date;
   PercentPeriodEnd date;
   PercentFineDate date;                                                 -- Дата начала начисления пени на процент - может не совпадать с концом периода из-за выходных
   DateCreditStart date;
   DateCreditEnd date;                           -- Дата последнего из периодических платежей
   ChargeType varchar2(10);
  NoCalcPercent char(1) := 'N';                                                   -- Флаг что проценты ваащще-то чиста канкретна нада начислять
  IsChargeOnPayDate NUMBER := 2;               --1 - пеня начисляется за каждый неполный день просрочки платежа. 2 - пеня начисляется за каждый полный день просрочки платежа
  applyDate date; ---- дата проводки 05.12.2014 Morozova
 begin

------------------------  CНАЧАЛА ДОБЫВАЕМ РЯД ПАРАМЕТРОВ  ------------------------------

G_CloseDate := to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy');

--- выбираем дату проводки платежа  05.12.2014 Morozova
select pm.apply_date
into applyDate
from sm.payments pm
where pm.id = PayID;
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
         -- Определяем параметры из условий обязательств и пресетов,  политику в отношении праздников,  коды КБК ...
          Select  count(*)  into itmp
          from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
          where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
          and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
          and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;  --27.03.2014 Morozova
          if itmp = 1 then
                     Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID,  NVL(pd.PERCENT_CLS_KBK_ID, pd.MAIN_CLS_KBK_ID) , op.CHARGE_FINE_METHOD
										      into PDID, NoCalcPercent, DateCreditStart, ChargeUseHolidays, MainKBKID, FineKBKID, PercentKBKID, IsChargeOnPayDate
                      from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
                      where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
                      and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
                      and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;
          else
                   Select  count(*)  into itmp
                    from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
                    where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
                    and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
                    and (NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                            where   pd2.moveperiod_id(+)=mp2.id
                                                            and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
                                                            and  pd2.Periodical != 'N')
                                                            or mp.ENDDATE is null);
                          if itmp = 1 then
                                          Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID, NVL(pd.PERCENT_CLS_KBK_ID, pd.MAIN_CLS_KBK_ID) , op.CHARGE_FINE_METHOD
																					     into PDID, NoCalcPercent, DateCreditStart, ChargeUseHolidays, MainKBKID, FineKBKID, PercentKBKID, IsChargeOnPayDate
                                          from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
                                          where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
                                          and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
                                          and (NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
                                                                                  where   pd2.moveperiod_id(+)=mp2.id
                                                                                  and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
                                                                                  and  pd2.Periodical != 'N')
                                                                                  or mp.ENDDATE is null);
                          elsif PayPlanDate = to_date('01.01.3000', 'dd.mm.yyyy') then    --- Morozova 16,01,2014 
                          --- выбираем параметры обязательства в закрытой ОД для начисления % до полного погашения долга                          
                              Select  pd.ID, NVL(trim(pd.NO_CREDITPERCENT), 'N'), pd.CREDITSTARTDATE, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID,  NVL(pd.PERCENT_CLS_KBK_ID, pd.MAIN_CLS_KBK_ID) , op.CHARGE_FINE_METHOD
                                                        into PDID, NoCalcPercent, DateCreditStart, ChargeUseHolidays, MainKBKID, FineKBKID, PercentKBKID, IsChargeOnPayDate
                                                        from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
                                                        where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
                                                        and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
                                                        and mp.SINCEDATE <= PayDate ;
                          ------------------------------
                          else
                                           Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
                                           values (sysdate, 'err2 - no MovePeriod found', 'FINE_PERCENT_ON_DATE_PKG.ADD_PERCENTS_AND_FINES', 'SM', 2, 2, 1, PayPalnID, 5, 'N');
                                           RETURN false; -- ???
                          end if;
          end if;
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  if  NoCalcPercent = 'Y' then RETURN false;
  end if;


----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
   begin
     Select  ob.ID,
         case when (Exists(Select * from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.OBLIGATIONTYPE_ID = ObligTypeID and ppd.MOVESETS_ID = MoveSetID)) then 2 when op.CHARGE_FINE_ASSANCTION  =  'Y' then 3 else 1 end
          into  ObligID,   ObligGroup
          from  SM.OBLIGATIONS ob
          inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
          where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;

      -- Вид начисления
      Select trim(ch.CHARGE_TYPE)  into  ChargeType
           from SM.PAYMENTS_PLAN pp
           inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
           where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
           and pp.ID = PayPalnID;
    exception
         when NO_DATA_FOUND then  RETURN false;
    end;

   -- Дату предыдущего платежа
     begin
             Select max( NVL( (CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end),  pm.WRITEDATE)) into PayDatePrev
             from SM.PAYMENTS pm,
                        sm.documents d,
                        sm.sm_settings_tab st
            where pm.MOVESETS_ID = MoveSetID and pm.OBLIGATIONTYPE_ID = ObligTypeID
                 and d.id=pm.documents_id and st.key_name = 'PAYMENT_USE_APPLY_DATE'
                 and NVL( (CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end),  pm.WRITEDATE) < PayDate;
      exception
            when NO_DATA_FOUND then  PayDatePrev := to_date('01.01.1900','dd.mm.yyyy');
      end;
     if  PayDatePrev is null then  -- <<<< Added 12.12.2011 so not always exception above produces appropriate result.
           PayDatePrev := to_date('01.01.1900','dd.mm.yyyy');
     end if;

	  -- <<< 09.04.2012 <<<   -- Дата последнего срока нужна для начисления процентов при НЕСКОЛЬКИХ платежах ПОСЛЕ последнего срока
		begin
						 Select --+ INDEX(ch  IDX_CHG_MOVESET_ID)
						 max(NVL(ppd.FINEDATE, pp.FINEDATE)) into DateCreditEnd
						 from SM.PAYMENTS_PLAN pp
						 inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
						 inner join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
						 where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID;
			exception
					 when NO_DATA_FOUND then  DateCreditEnd := to_date('01.01.3000','dd.MM.yyyy');
			end;
 
      --- 16.01.2014 Morozova
      if PayPlanDate = to_date('01.01.3000', 'dd.mm.yyyy') then  DateCreditEnd := to_date('01.01.3000','dd.MM.yyyy'); end if;
     
		-- Дату предыдущего  плана <--- ЗАМЕНЕНО НА ПЕРЕДАВАЕМОЕ В ПАРАМЕТРЕ ЗНАЧЕНИЕ ОТ ПРЕДЫДУЩЕГО ВЫЗОВА
     if PayPlanDatePrev is null then
            begin
                 Select --+ INDEX(ch  IDX_CHG_MOVESET_ID)
                   max(NVL(ppd.FINEDATE, pp.FINEDATE)) into PayPlanDatePrev
                   from SM.PAYMENTS_PLAN pp
                   inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                   left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
                   where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
                   and NVL(ppd.FINEDATE, pp.FINEDATE) < PayPlanDate
                  and (pp.PAYMENTS_PLAN_DRAFT_ID is not null  or  trim(ch.CHARGE_TYPE) = 'OTHER');
            exception
                 when NO_DATA_FOUND then  PayPlanDatePrev := DateCreditStart;
            end;
     end if;
     if PayPlanDatePrev is null then
               PayPlanDatePrev := DateCreditStart;
     end if;

     --- 20.01.2014 Morozova
     --- Если платеж проходит датой позже последней даты плана погашения задолженности, после которой нет следующих начислений %%
     --- устанавливаем пердыдущую дату начисления %% датой последнего платежа (т.к. именно при нем происходило последнее начисление) 
     if trunc(PayPlanDate) = trunc(to_date('01.01.3000', 'dd.mm.yyyy')) then
               PayPlanDatePrev := PayDatePrev;
     end if;

     -- Опредеоляем период начисления:
    PrevChargesDate := PayPlanDatePrev;
    if (PayPlanDate > PayDate) then ChargesDate :=  PayDate; else  ChargesDate :=  PayPlanDate; end if;
		-- <<< 29.02.2012 <<< Если все-таки ChargesDate пустая (например - начисления по графику - PayDate  нету...)
		if ChargesDate is null then ChargesDate := sysdate; end if;

------------------------ НАЧИНАЕМ СОБСТВЕННО НАЧИСЛЕНИЯ ------------------------

 if  ObligGroup = 2 then
          -- Пишем проценты
                -- Корректируем (или нет) контрольную дату периода под праздники
                if ChargeUseHolidays='Y' then
                         PercentFineDate := SM.GetFirstWorkDate(PayPlanDate-1)+1;
                else
                         PercentFineDate := PayPlanDate;
                end if;
             -- Предварительно разбираемся с началом - концом периода для процентов
             if IsChargeOnPayDate = 1 then -- начислять включая день погашения
                     if ((SM.GetFirstWorkDate(PayPlanDatePrev-1) +1 >  PayDatePrev +1) OR PayDatePrev = to_date('01.01.1900','dd.MM.yyyy') ) then PercentPeriodStart :=PayPlanDatePrev-1; else PercentPeriodStart := PayDatePrev;  end if;
                     if (PayPlanDate >  PayDate) then PercentPeriodEnd := PayDate; else PercentPeriodEnd := PayPlanDate-1; end if;
									   if (DateCreditEnd = PayPlanDate) then PercentPeriodEnd := PayDate; end if; -- <<< 09.04.2012 <<< для начисления процентов при НЕСКОЛЬКИХ платежах ПОСЛЕ последнего срока
              else -- оставить день погашения на следующий период (соответственно, остаток долга для % в этот день будет меньше)
                     if ((SM.GetFirstWorkDate(PayPlanDatePrev-1) +1 >  PayDatePrev ) OR PayDatePrev = to_date('01.01.1900','dd.MM.yyyy') ) then PercentPeriodStart :=PayPlanDatePrev-1; else PercentPeriodStart := PayDatePrev-1;  end if;
                     if (PayPlanDate >  PayDate) then PercentPeriodEnd := PayDate-1; else PercentPeriodEnd := PayPlanDate-1; end if;
									   if (DateCreditEnd = PayPlanDate) then PercentPeriodEnd := PayDate-1; end if; -- <<< 09.04.2012 <<< для начисления процентов при НЕСКОЛЬКИХ платежах ПОСЛЕ последнего срока
	             end if;
               if (PayPlanDatePrev >=  PayPlanDate OR PercentPeriodStart >= PercentPeriodEnd OR PercentPeriodStart = to_date('01.01.1900','dd.MM.yyyy')) then
                        return false;
               end if;

              ValToWrite := PercentSizeForPayment(MoveSetID, ObligTypeID, PercentPeriodEnd, PercentPeriodStart, Comment_txt, IsChargeOnPayDate);

                if ValToWrite <> 0 then
                        Comment_txt := Comment_txt || ' в связи с п/п ' || PaymentDescription;
                 --* Морозова
                             c := 0;
                             select  --+INDEX(cr IDX_CHG_MOVESET_ID)
                                           count (*) into c
                             FROM SM.Charges cr
                             where cr.movesets_id = MoveSetID
                                   and cr.obligationtype_id = ObligTypeID
                                   and cr.chargedate = PayDate
                                   and cr.document_id is null
  --                                 and trim(cr.comments) = trim(Comment_txt) --!!!!!!!!!!!!!!!!!   07.11.2011
                                   and TRIM(SUBSTR(cr.comments, INSTR(cr.comments, '('), INSTR(cr.comments, ')')-INSTR(cr.comments, '('))) = TRIM(SUBSTR(Comment_txt,INSTR(cr.comments, '('), INSTR(Comment_txt, ')')-INSTR(cr.comments, '(')))
 --                                  and cr.paysize = ValToWrite
                                   and nvl(cr.finedate, trunc(sysdate)) = nvl(PercentFineDate, trunc(sysdate))
                                   and trim(cr.charge_type) = 'PERCENT'
                                   and cr.paydoc_id = PDID
                                   and nvl(cr.calperiod_start, trunc(sysdate)) = nvl(PrevChargesDate, trunc(sysdate))
                                   and nvl(cr.calperiod_end, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                      and nvl(cr.Cls_Kbk_Id,0) = nvl(MainKBKID,0)
                                   and nvl(cr.factcharge, 'N') = nvl(Fact_Charge, 'N');


                        if c = 0 then    --* Морозова
                                  select sm.seqcharges.nextval into idNext from dual;    --*

                                  Insert into SM.CHARGES(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                                 values (idNext, trunc(PayDate), trunc(PercentFineDate), PDID, Comment_txt, ValToWrite, 'PERCENT', MoveSetID, ObligTypeID,  trunc(PrevChargesDate), trunc(ChargesDate), PercentKBKID,  Fact_Charge);
                                 ----- Пишем сопровждающий начисление план его погашения ----
                                  select count(*) into c
                                  from SM.PAYMENTS_PLAN
                                  where  CHARGES_ID = idNext
                                         and OBLIGATIONS_ID = ObligID
                                         and nvl(FINEDATE, trunc(sysdate)) = nvl(PercentFineDate, trunc(sysdate))
                                         and nvl(VAL, 0) = nvl(ValToWrite, 0)
                                         and nvl(PAYMENTS_PLAN_DRAFT_ID, 0) = nvl(FilledByDraftID, 0)
                                         and nvl(COMMENTS, '') = nvl(Comment_txt, '')
                                         and MAIN_PLAN_ID is null;
                                  if c = 0 then  --* Морозова
                                          Insert into SM.PAYMENTS_PLAN(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                               values (sm.seqpayments_plan.nextval, idNext, ObligID, PercentFineDate, ValToWrite, FilledByDraftID, Comment_txt, null);
                                  end if;        --*
                                   ----- Отражаем начисление в Учетных данных ----
                                  --*     Морозова
        --*                          if FirstCharge = 'Y' then
                                SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext, applyDate, ---PayDate  05.12.2014
                                                   MoveSetID, null, Comment_txt, ValToWrite, 'PERCENT',--'OBLIGATION', --
                                                   ObligTypeID, PercentFineDate, null,PDID, PrevChargesDate,
                                                   ChargesDate, MainKBKID, null, null, ObligID, Fact_Charge, PayID, FirstCharge);
        --*                          end if;

                                   if G_CloseDate >= PayDate then
                                        A_comments := 'Исправляющая: ';
                                        A_corr_flag :='Y';
                                        A_chargedate := trunc(sysdate);
                                        A_reversal_role := 'Исправляющая';
                                   else
                                        A_comments := '';
                                        A_corr_flag := 'N';
                                        A_chargedate := PayDate;
                                        A_reversal_role := '';
                                   end if;

 --                                  if (A_chargedate <= SYSDATE) then -- <<< 07.12.2012 Не пишем учетных данных для будущих "начислений" (уж не говоря что такое сами эти "начисления"...)
-- 04.06.2013 -- Пусть пишутся и на будущее, поскольку: 1. Это все-таки не проводки а фиг знает что (и соответственно относиться к ним можно по-разному) 2. Поскольку  "уч.данные" пишутся и из триггеров, то кто будет потом их формировать (для доп.нач., платежей...)
																						 insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
																																						description, charge_id, corr_flag, cls_kbk_id, obligations_id,
																																						payments_distribution_id, reversal_role, reversallink_id, payment_id)
																						 values (sm.seqcharge_applies.nextval, applyDate, ValToWrite, ObligTypeID, MoveSetID,  ---  A_chargedate  --05.12.2014 Morozova
																																						'O', A_comments || Comment_txt, idNext, A_corr_flag,  MainKBKID,
																																						ObligID, null, A_reversal_role, null,    null); -- ???  -- <<< 07.12.2012 - НЕ!!! пишем ID платежа, ведь запись - про начисление.
--																	 end if;
                                   ----------------------------------------------
                                  HasWrite := true;
                        end if;          --*
                end if;
 end if;

Return  HasWrite;
end;



