--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- Дополнительные действия для поступившего [либо "вновь распределяемого"] платежа.
 -- ( Если платеж связан с основанием с условиями начисления пени на день платежа, или на продажу с рассрочкой
 --   - происходит еще начисление пени и процентов соответственно. )
        -- Параметры:
             -- PayID      -- Идентификатор рассматриваемого платежа
             --PayDate SM.PAYMENTS.WRITEDATE%type;           -- Дата текущего обрабатываемого платежа
             --ObligTypeID SM.OBLIGATIONTYPE.ID%type;         -- ID типа обязательства
             --MoveSetID   SM.MOVESETS.ID%type;                   -- Оно нада чобы знать  к чему оно все относится
Function ADD_FINES(PayVal in SM.PAYMENTS.SUM%type, PayPalnID SM.PAYMENTS_PLAN.ID%type,
                                        PayPlanDate date, PayDate date, MoveSetID number, ObligTypeID number, FilledByDraftID number,
                                        PayID in number, FirstCharge in varchar2  )  return boolean
 is
c integer;
idNext integer;
A_reversal_role varchar2(100);
    HasWrite boolean := false;                                           -- Возвращаемый функцией признак что запись процентов или пени состоялась
    ObligID SM.CHARGES.ID%type;                                  -- ID Обязательства
   ObligGroup number(1);                                                 -- 1 - простое (тогда выходим); 2 - с рассрочкой (тогда начисляем проценты и пеню); 3 - с пеней определенной на день оплаты (тогда начисляем пеню).
   PayDatePrev SM.PAYMENTS.WRITEDATE%type;  -- Дата предыдущего платежа
   PayPlanDatePrev date;                                                 -- Дата предыдущего плана поступления
   PayPlanDatePrevForFineTmp  date;
   ChargeUseHolidays char(1);
   Comment_txt varchar2(1000);                                    -- Комментарий к начислениям
   ValToWrite number(27, 2);                                          -- Сумма начисляемых процентов или пени
   MultiplyValToWrite number(27, 9);                            -- Доля пени о суммы платежа - (если пеня на день оплаты)
   PDID number;                                                                  -- ID PayDocs-а - условий на период

	 ChargeRealDate date;                                                   -- Дата начисления к которому пеня (может отличаться от даты пени если не 7 способ)
   ChargesDate date;                                                          -- Дата окончания периода за который пишется начисление
   PrevChargesDate date;                                                 -- Дата начала периода за который пишется начисление
   MainKBKID SM.PAYDOCS.MAIN_CLS_KBK_ID%type;
   FineKBKID SM.PAYDOCS.FINE_CLS_KBK_ID%type;
   itmp integer;
   DateCreditStart date;
   DateMovePeriodStart date;
   FineCreditPpersent char(1) := 'Y';                                        --  Начислять ли пеню на проценты
   Fact_Charge char(1) := 'Y';
   NoFine char(1) := 'N';
   ValToUse number(27,2);
   ChargeType varchar2(10);
   FineKind char(1);
   FineAsSanction char(1);
	 IsCredit char(1) := 'N';
	ARecalc_Start_Date date;

 begin

       if (not IsCalcFineNeed) then
				      return false;
			end if;

       if PayVal = 0 then Fact_Charge := 'N';
       end if;

------------------------  CНАЧАЛА ДОБЫВАЕМ РЯД ПАРАМЕТРОВ  ------------------------------

	  select count(*) into itmp
				from  SM.OBLIGATIONS ob
				inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
				where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;
   if itmp = 1 then
         Select  ob.ID,
          case when (Exists(Select * from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.OBLIGATIONTYPE_ID = ObligTypeID and ppd.MOVESETS_ID = MoveSetID)) then 2 when op.CHARGE_FINE_ASSANCTION  =  'Y' then 3 else 1 end,
          op.CHARGE_FINE_ASSANCTION, ob.RECALC_START_DATE
          into  ObligID,   ObligGroup, FineAsSanction, ARecalc_Start_Date
          from  SM.OBLIGATIONS ob
          inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
          where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID;
   else
         RETURN false;
   end if;

 ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
         -- Определяем параметры из условий обязательств и пресетов,  политику в отношении праздников,  коды КБК ...
          Select  count(*)  into itmp --  Сначала - условия на дату погашаемого периода!!! (<<< 01.08.2012)
          from SM.PAYMENTS_PLAN pp
					inner join SM.CHARGES ch on ch.ID= pp.CHARGES_ID
          inner join SM.PAYDOCS pd on pd.ID = ch.PAYDOC_ID
					inner join  SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID
					inner join  SM.OBLIG_PERIODICAL_PRESETS op on op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
          where  pp.ID = PayPalnID;
          if itmp = 1 then
                     Select  pd.ID, pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, pd.Fine_Kind, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID
										      into PDID, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, FineKind, ChargeUseHolidays, MainKBKID, FineKBKID
									 from SM.PAYMENTS_PLAN pp
										inner join SM.CHARGES ch on ch.ID= pp.CHARGES_ID
										inner join SM.PAYDOCS pd on pd.ID = ch.PAYDOC_ID
										inner join  SM.MOVEPERIODS mp on pd.MOVEPERIOD_ID=mp.ID
										inner join  SM.OBLIG_PERIODICAL_PRESETS op on op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
										where  pp.ID = PayPalnID;
          else
									Select  count(*)  into itmp --- Потом- на дату платежа
									from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
									where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
									and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
									and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;
									if itmp = 1 then
														 Select  pd.ID, pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, pd.Fine_Kind, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID
																	into PDID, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, FineKind, ChargeUseHolidays, MainKBKID, FineKBKID
															 from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
															where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
															and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
															and mp.SINCEDATE <= PayDate and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayDate;
									else
													 Select  count(*)  into itmp
														from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
														where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
														and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
														and (NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
																																		where   pd2.moveperiod_id(+)=mp2.id
																																		and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
																																		and  pd2.Periodical != 'N')
																																		or mp.ENDDATE is null);
														if itmp = 1 then
																					 Select  pd.ID, pd.CREDITSTARTDATE, pd.FINEONCREDITPERSENT, pd.NO_FINE, mp.SINCEDATE, pd.Fine_Kind, op.CHARGE_USE_HOLYDAYS, pd.MAIN_CLS_KBK_ID, pd.FINE_CLS_KBK_ID
																								into PDID, DateCreditStart, FineCreditPpersent, NoFine, DateMovePeriodStart, FineKind, ChargeUseHolidays, MainKBKID, FineKBKID
																						from SM.PAYDOCS pd, SM.MOVEPERIODS mp,sm.OBLIG_PERIODICAL_PRESETS op
																						where pd.MOVEPERIOD_ID=mp.ID and op.ID = pd.OBLIG_PERIODICAL_PRESETS_ID
																						and mp.MOVESET_ID=MoveSetID and pd.OBLIGATIONTYPE_ID=ObligTypeID
																						and (NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) = (Select max(mp2.ENDDATE) from sm.paydocs pd2,  sm.moveperiods mp2
																																										where   pd2.moveperiod_id(+)=mp2.id
																																										and mp2.moveset_id=MoveSetID and pd2.obligationtype_id=ObligTypeID
																																										and  pd2.Periodical != 'N')
																																										or mp.ENDDATE is null);
															else
																						 RETURN false;
															end if;
                      end if;
          end if;
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

      if NoFine = 'Y' then RETURN false;
      end if;
     -- Корректируем ObligGroup для "не-ставки" рефинансирования
      if (ObligGroup = 3 and FineKind <>  'R') then
                 ObligGroup := 0; -- Ничо не делаем
     end if;

    -- Вид начисления
    select count(*) into itmp
           from SM.PAYMENTS_PLAN pp
           inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
           where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
           and pp.ID = PayPalnID;
    if itmp = 1 then
           Select trim(ch.CHARGE_TYPE)  into  ChargeType
                 from SM.PAYMENTS_PLAN pp
                 inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                 where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
                 and pp.ID = PayPalnID;
   else
         RETURN false;
    end if;

     if (FineCreditPpersent = 'N') and ChargeType = 'PERCENT' then RETURN true;
     end if;


   -- Дату предыдущего платежа
    Select MAX(NVL((CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end),pm.WRITEDATE)) into PayDatePrev
          from SM.PAYMENTS pm,
          sm.documents d,
          sm.sm_settings_tab st
          where pm.MOVESETS_ID = MoveSetID
          and d.id=pm.documents_id and st.key_name = 'PAYMENT_USE_APPLY_DATE'
          and pm.OBLIGATIONTYPE_ID = ObligTypeID
          and NVL((CASE when (st.value = 'N' and pm.paymethod_id!=3) then d.docdate else pm.Apply_Date end),pm.WRITEDATE) < PayDate;
    if PayDatePrev is null then
           PayDatePrev := to_date('01.01.1900','dd.mm.yyyy');   -- DateCreditStart ???;
     end if;

    -- Дату предыдущего  плана
		Select   --+INDEX(ch IDX_CHG_MOVESET_ID)
			MAX(NVL(ppd.FINEDATE, pp.FINEDATE))  into PayPlanDatePrev
			 from SM.CHARGES ch
			 inner join SM.PAYMENTS_PLAN pp on ch.ID = pp.CHARGES_ID
			 inner join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
			 where  ch.MOVESETS_ID = MoveSetID  and ch.OBLIGATIONTYPE_ID = ObligTypeID
			 and  NVL(ppd.FINEDATE, pp.FINEDATE) < PayDate;
    if PayPlanDatePrev is null   then
					  Select   --+INDEX(ch IDX_CHG_MOVESET_ID)
									MAX(greatest(ch.FINEDATE, ch.CHARGEDATE))  into PayPlanDatePrev
									 from SM.CHARGES ch
									 where  ch.MOVESETS_ID = MoveSetID  and ch.OBLIGATIONTYPE_ID = ObligTypeID
									 and  ch.FINEDATE  < PayDate
									 and  ch.CHARGEDATE  < PayDate
							  	 and ( trim(ch.CHARGE_TYPE) in ('OTHER', 'OBLIGATION', 'FINE'));
					  Select   --+INDEX(ch IDX_CHG_MOVESET_ID)
									ch.CHARGEDATE   into  ChargeRealDate
									 from SM.CHARGES ch
									 inner join SM.PAYMENTS_PLAN pp on pp.CHARGES_ID = ch.ID
									 where  pp.ID =  PayPalnID;

									if  PayPlanDatePrev is null   then
																		PayPlanDatePrev := NVL(DateCreditStart, DateMovePeriodStart);
									end if;
		else
				  IsCredit 	:= 'Y';
    end if;


     -- Опредеоляем период начисления:
    PrevChargesDate := PayPlanDatePrev;
    if (PayPlanDate > PayDate) then ChargesDate :=  PayDate; else  ChargesDate :=  PayPlanDate; end if;
		-- <<< 29.02.2012 <<< Если все-таки ChargesDate пустая (например - начисления по графику - PayDate, PayPlanDate -  нету...)
		if ChargesDate is null then ChargesDate := sysdate; end if;
		-- VVV 19.11.2012 -- Иначе при единовременых начислениях (продажа) период инвертировался.
		if ChargesDate <= PrevChargesDate then ChargesDate := PayDate;  end if;

------------------------ НАЧИНАЕМ СОБСТВЕННО НАЧИСЛЕНИЯ ------------------------

   if ObligGroup in ( 1, 2) then
              -- Пишем пеню
             -- Теперь - пеня на исходное начисление
                -- Если оно - не первоначальный взнос на условиях предоплаты (т.е. FilledByDraft is not null)
              if FilledByDraftID is not null or ChargeType in ('OTHER', 'PERCENT') then
                    MultiplyValToWrite :=  SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPalnID, PayDatePrev, Comment_txt,  'Y',  PayPlanDate, PDID); --<< 02.08.2012  PayPlanDate(not Prev)
                    if FineAsSanction = 'Y' and FineKind = 'R' then
                        ValToWrite := MultiplyValToWrite * PayVal;
                    else
                        ValToWrite := MultiplyValToWrite;
                    end if;
                    if ValToWrite <> 0 then
                      --* Морозова
                             select   --+INDEX(cr IDX_CHG_MOVESET_ID)
                                   count (*) into c FROM SM.Charges cr
                             where cr.chargedate = PayDate
                                   and cr.movesets_id = MoveSetID
                                   and cr.document_id is null
                                   and trim(cr.comments) = trim(Comment_txt) || ' (при платеже)'
                                   and cr.paysize = ValToWrite
                                   and nvl(cr.finedate, trunc(sysdate)) = nvl(PayPlanDate, trunc(sysdate))
                                   and trim(cr.charge_type) = 'FINE'
                                   and cr.obligationtype_id = ObligTypeID
                                   and cr.paydoc_id = PDID
                                   and nvl(cr.calperiod_start, trunc(sysdate)) = nvl(PrevChargesDate, trunc(sysdate))
                                   and nvl(cr.calperiod_end, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                   and nvl(cr.Cls_Kbk_Id,0) = nvl(FineKBKID,0)
                                   and nvl(cr.factcharge, 'N') = nvl(Fact_Charge, 'N');
 									if c > 1 then   --- <<< 12.10.2012 <<< -- Для придания коду суперустойчивости, если ранее уже как-то начислилось 2 пени - то - удаляем и начисляем по-новой! (TODO: Уч.Данные)
										    Delete from SM.CHARGES   where chargedate = PayDate
                                   and movesets_id = MoveSetID
                                   and document_id is null
                                   and trim(comments) = trim(Comment_txt) || ' (при платеже)'
                                   and paysize = ValToWrite
                                   and nvl(finedate, trunc(sysdate)) = nvl(PayPlanDate, trunc(sysdate))
                                   and trim(charge_type) = 'FINE'
                                   and obligationtype_id = ObligTypeID
                                   and paydoc_id = PDID
                                   and nvl(calperiod_start, trunc(sysdate)) = nvl(PrevChargesDate, trunc(sysdate))
                                   and nvl(calperiod_end, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                   and nvl(Cls_Kbk_Id,0) = nvl(FineKBKID,0)
                                   and nvl(factcharge, 'N') = nvl(Fact_Charge, 'N')
								                  AND CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
											c := 0;
									end if;
                          if c = 0 then     --* Морозова
                          select sm.seqcharges.nextval into idNext from dual;   --*

                                 Insert into sm.charges(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                               values (idNext, PayDate, PayPlanDate, PDID, Comment_txt || ' (при платеже)', ValToWrite, 'FINE', MoveSetID, ObligTypeID, PrevChargesDate, ChargesDate, FineKBKID, Fact_Charge);
                                 ----- Пишем сопровждающий начисление план его погашения ----
                               select count(*) into c
                                from sm.payments_plan
                                where   CHARGES_ID = idNext
                                        and OBLIGATIONS_ID = ObligID
                                        and nvl(FINEDATE, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                        and nvl(VAL, 0) = nvl(ValToWrite, 0)
                                        and nvl(PAYMENTS_PLAN_DRAFT_ID, 0) = nvl(FilledByDraftID, 0)
                                        and nvl(COMMENTS, '') = nvl(Comment_txt, '')
                                        and nvl(MAIN_PLAN_ID, 0) = nvl(PayPalnID, 0);
                                if c = 0 then  --* Морозова
                                Insert into sm.payments_plan(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                               values (sm.seqpayments_plan.nextval, idNext, ObligID, ChargesDate, ValToWrite, FilledByDraftID, Comment_txt, PayPalnID);
                                end if;        --*

                                ----- Отражаем начисление в Учетных данных ----
                               --* Морозова
                                if FirstCharge = 'Y' then
                                SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext,
                                           PayDate, MoveSetID, null, Comment_txt, ValToWrite, 'FINE',
                                           ObligTypeID, PayPlanDate, null, PDID, PrevChargesDate,
                                           ChargesDate, FineKBKID, null, null, ObligID, Fact_Charge, PayID, FirstCharge, 'Y');
                                end if;

                           if G_CloseDate >= PayDate then
                                A_reversal_role := 'Исправляющая';
                           else
                                A_reversal_role := '';
                           end if;

                           SM.OBLIG_ACC_PKG.PartitioningChargesAppliesFine(Comment_txt, PrevChargesDate, ChargesDate,
                                  ValToWrite, ObligTypeID,
                                  MoveSetID, idNext, FineKBKID, 'F',
                                  null, A_reversal_role, PayID);
                                --*
                                ---------------------------------------------------------------------------

                                HasWrite := true;
                          end if;              --*
                    end if;
            end if;

   elsif (ObligGroup = 3) then
   -- Если по обязательству с условиями начисления пени на день платежа - определяем и пишем пеню
             if Fact_Charge = 'N' then
                   Select pp.VAL into ValToUse  from SM.PAYMENTS_PLAN pp where pp.ID = PayPalnID;
              else
                   ValToUse := PayVal;
             end if;

            MultiplyValToWrite := SM.FULLRECALC_PKG.FineSizeForCredit(MoveSetID, ObligTypeID, PayDate, PayPalnID, PayPlanDatePrev, Comment_txt,  'Y',  PayPlanDate, PDID); --<< 02.08.2012  PayPlanDate(not Prev)
            if (FineKind =  'R') then
                    ValToWrite :=  ValToUse * MultiplyValToWrite;
										if IsCredit = 'N' then
                           Comment_txt := Comment_txt || ' на сумму долга ' || to_char(ValToUse) || ' от начисления за ' || to_char(ChargeRealDate,'dd.MM.yyyy') || ' = ' || to_char(ValToWrite) || ' руб.';
										else
						               Comment_txt := Comment_txt || ' на сумму долга ' || to_char(ValToUse) || ' = ' || to_char(ValToWrite) || ' руб.';
										end if;
            else
                    ValToWrite := MultiplyValToWrite;
              --      Comment_txt := Comment_txt || ' на сумму долга ' || to_char(ValToUse) || ' = ' || to_char(ValToWrite) || ' руб.';
            end if;

           --- 11.07.2014 Morozova  для начислений пени в день платежа по ставке рефинансирования, если все параметры одинаовы (случилось при отсрочке) 
           --- проверяем наличие записи в плане платежей по пене на начисление по плану 
           select count(*) into itmp 
           from SM.PAYMENTS_PLAN pp
           inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
           where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
                 and pp.main_plan_id = PayPalnID;

            -- Пишем пеню
             if ValToWrite <> 0 then
                   --* морозова
                   select   --+INDEX(cr IDX_CHG_MOVESET_ID)
                                   count (*) into c FROM SM.Charges cr
                             where cr.chargedate = PayDate
                                   and cr.movesets_id = MoveSetID
                                   and cr.document_id is null
                                   and trim(cr.comments) = trim(Comment_txt) || ' (на день платежа)'
                                   and cr.paysize = ValToWrite
                                   and nvl(cr.finedate, trunc(sysdate)) = nvl(PayPlanDate, trunc(sysdate))
                                   and trim(cr.charge_type) = 'FINE'
                                   and cr.obligationtype_id = ObligTypeID
                                   and cr.paydoc_id = PDID
                                   and nvl(cr.calperiod_start, trunc(sysdate)) = nvl(PrevChargesDate, trunc(sysdate))
                                   and nvl(cr.calperiod_end, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                   and nvl(cr.Cls_Kbk_Id,0) = nvl(FineKBKID,0)
                                   and nvl(cr.factcharge, 'N') = nvl(Fact_Charge, 'N');
 									if c > 1 and itmp <> 0 then   --- <<< 12.10.2012 <<< -- Для придания коду суперустойчивости, если ранее уже как-то начислилось 2 пени - то - удаляем и начисляем по-новой! (TODO: Уч.Данные)
										    Delete from SM.CHARGES where chargedate = PayDate
                                   and movesets_id = MoveSetID
                                   and document_id is null
                                   and trim(comments) = trim(Comment_txt) || ' (на день платежа)'
                                   and paysize = ValToWrite
                                   and nvl(finedate, trunc(sysdate)) = nvl(PayPlanDate, trunc(sysdate))
                                   and trim(charge_type) = 'FINE'
                                   and obligationtype_id = ObligTypeID
                                   and paydoc_id = PDID
                                   and nvl(calperiod_start, trunc(sysdate)) = nvl(PrevChargesDate, trunc(sysdate))
                                   and nvl(calperiod_end, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                   and nvl(Cls_Kbk_Id,0) = nvl(FineKBKID,0)
                                   and nvl(factcharge, 'N') = nvl(Fact_Charge, 'N')
								                  AND CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.
												c := 0;
									end if;
                 if c = 0 or itmp = 0 then    --* Морозова  --- 11.07.2014 Morozova  для начислений пени в день платежа по ставке рефинансирования, если все параметры одинаовы (случилось при отсрочке) 
                       select sm.seqcharges.nextval into idNext from dual;

                         Insert into sm.charges(ID, CHARGEDATE, FINEDATE, PAYDOC_ID, COMMENTS, PAYSIZE, CHARGE_TYPE, MOVESETS_ID, OBLIGATIONTYPE_ID, CALPERIOD_START, CALPERIOD_END, CLS_KBK_ID, FACTCHARGE)
                                       values (idNext, PayDate, PayPlanDate, PDID, Comment_txt || ' (на день платежа)', ValToWrite, 'FINE', MoveSetID, ObligTypeID, PrevChargesDate, ChargesDate, FineKBKID, Fact_Charge);
                                ----- Пишем сопровждающий начисление план его погашения ----
                         select count(*) into c
                                from sm.payments_plan
                                where   CHARGES_ID = idNext
                                        and OBLIGATIONS_ID = ObligID
                                        and nvl(FINEDATE, trunc(sysdate)) = nvl(ChargesDate, trunc(sysdate))
                                        and nvl(VAL, 0) = nvl(ValToWrite, 0)
                                        and nvl(PAYMENTS_PLAN_DRAFT_ID, 0) = nvl(FilledByDraftID, 0)
                                        and nvl(COMMENTS, '') = nvl(Comment_txt, '')
                                        and nvl(MAIN_PLAN_ID, 0) = nvl(PayPalnID, 0);
                        if c = 0 then   --* Морозова
                        Insert into sm.payments_plan(ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL, PAYMENTS_PLAN_DRAFT_ID, COMMENTS, MAIN_PLAN_ID)
                                       values (sm.seqpayments_plan.nextval, idNext, ObligID, ChargesDate, ValToWrite, FilledByDraftID, Comment_txt, PayPalnID);
                        end if;        --*

                       ----- Отражаем начисление в Учетных данных ----
                        --* Морозова
                        if FirstCharge = 'Y' then
                        SM.OBLIG_ACC_PKG.RecalcChargesApplies(idNext,
                                           PayDate, MoveSetID, null, Comment_txt, ValToWrite, 'FINE',
                                           ObligTypeID, PayPlanDate, null, PDID, PrevChargesDate,
                                           ChargesDate, FineKBKID, null, null, ObligID, Fact_Charge, PayID, FirstCharge, 'Y');  -- <<< 20120816 !!!
                        end if;

                          if G_CloseDate >= PayDate then
                                A_reversal_role := 'Исправляющая';
                           else
                                A_reversal_role := '';
                           end if;

                           SM.OBLIG_ACC_PKG.PartitioningChargesAppliesFine(Comment_txt, PrevChargesDate, ChargesDate,
                                  ValToWrite, ObligTypeID,
                                  MoveSetID, idNext, FineKBKID, 'F',
                                  null, A_reversal_role, PayID);

                        HasWrite := true;
                  end if;              --*
             end if;
   end if;

  Return  HasWrite;
 end;



--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--- Выделенный в отдельную функцию цикл распределения платежей (т.к. вызывается рекурсивно из PAYMENT_DISTRIBUTE_SINGLE -----------
Procedure PAYMENTS_PROCEED(AMovesetID in number, AObligtypeID in number, Abegdate date, Aenddate date)
is
	ntmp number;
	KBK_main integer;
	KBK_fine integer;
	KBK_percent integer;
	MAINPAY char(1);
	dTmp date;
  PayDistrPolicy CHAR(3) := 'NPY';
	A_PAY_DISTR_PRIM_BY_DATE char(1) := 'Y';
	APercents_Instant char(1) := 'N';
 ADistrDirect char(1) := 'N';
 AOBLIG_ID number;

begin
    --	Находим условия
			Select  count(*) into ntmp
			from  SM.OBLIGATIONS ob
			inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
			where ob.MOVESET_ID = AMovesetID and ob.OBLIGATIONTYPE_ID = AObligtypeID;
			if ntmp = 1 then
							Select  op.PAY_DISTR_PRIM_BY_DATE, op.percents_instant, op.DistrDirect, ob.ID  into A_PAY_DISTR_PRIM_BY_DATE, APercents_Instant, ADistrDirect, AOBLIG_ID

							from  SM.OBLIGATIONS ob
							inner join SM.OBLIG_PRESETS op on op.ID = ob.OBLIG_PRESETS_ID
							where ob.MOVESET_ID = AMovesetID and ob.OBLIGATIONTYPE_ID = AObligtypeID;
			end if;

   -- Основной цикл по платежам...
     for PayCurr  in
     (
          Select pm.ID,
							(Case when pm.SUM >0
								then (pm.SUM - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pm.ID ),0))
								else  (pm.SUM + NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pm.ID ),0))
								end)  as PayVal,
              sm.getpaydateforpayment(pm.ID) as apply_date,
              pm.CLS_KBK_ID,  pm.MAINPAY, pm.SUM, pm.DOCUMENTS_ID
          from SM.PAYMENTS pm
          where  pm.MOVESETS_ID = AMovesetID and pm.OBLIGATIONTYPE_ID = AObligtypeID
          and (
					         pm.SUM > 0  and  (pm.SUM > NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pm.ID ),0))
									 OR
					         pm.SUM < 0  and  (pm.SUM < NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pm.ID ),0))
									 )
					and sm.getpaydateforpayment(pm.ID) > Abegdate  and (sm.getpaydateforpayment(pm.ID) <= Aenddate -- <<< 26.09.2012 <<<Без  <"="  платеж в последний день периода выпадал из  разноски.
            or (sm.getpaydateforpayment(pm.ID) > sm.getmovesetenddate(AMovesetID) and Aenddate > sm.getmovesetenddate(AMovesetID) ))  --- 20.05.2014 Morozova  иначе платежи не распределялись, внесенные после закрытия ОД (при условии начислений в предшествующем периоде)  --31.07.2014and Aenddate > sm.getmovesetenddate(AMovesetID) 
            order by NVL(sm.getpaydateforpayment(pm.ID), NVL(pm.APPLY_DATE, pm.WRITEDATE)),  decode(pm.MAINPAY, 'Y', 1, 'M', 2, 'P', 3, 'N', 4 )  , pm.ID
     )
     loop

							-- 17.08.2011  Определяем КБК, чтобы разнести платеж по правильным КБК (не важно что бы они там вводили в качестве SM.PAYMENTS.MAINPAY)
							-- (Здесь - внутри цикла, т.к. снаружи нет привязки к дате.)
									Select  count(*)  into ntmp
									from SM.PAYDOCS pd, SM.MOVEPERIODS mp, SM.OBLIG_PERIODICAL_PRESETS opp
									where pd.MOVEPERIOD_ID=mp.ID and opp.ID=pd.OBLIG_PERIODICAL_PRESETS_ID
									and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
									and mp.SINCEDATE <= PayCurr.apply_date and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayCurr.apply_date;
									if (ntmp = 1)   then
												 Select pd.main_cls_kbk_id, pd.fine_cls_kbk_id,     (Case when pd.CREDITSIZE>0 then NVL(pd.percent_cls_kbk_id, pd.main_cls_kbk_id) else pd.main_cls_kbk_id end),  opp.PAY_DISTR_POLICY   into KBK_main, KBK_fine, KBK_percent , PayDistrPolicy
												 from SM.PAYDOCS pd, SM.MOVEPERIODS mp, SM.OBLIG_PERIODICAL_PRESETS opp
													where pd.MOVEPERIOD_ID=mp.ID and opp.ID=pd.OBLIG_PERIODICAL_PRESETS_ID
													and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
													and mp.SINCEDATE <= PayCurr.apply_date and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayCurr.apply_date;
									else   --- <<< 19.03.2012 <<< -- Если в нужную дату не попал, то ищем ближайшую сверху (почему? - при всей бестолковости ситуации это наименее бестолково...)
																		Select  min(mp.SINCEDATE)  into dTmp
																		from SM.PAYDOCS pd, SM.MOVEPERIODS mp
																		where pd.MOVEPERIOD_ID=mp.ID
																		and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
																		and mp.SINCEDATE > PayCurr.apply_date and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) > PayCurr.apply_date;
																		if (dTmp is not null)   then
																						  Select pd.main_cls_kbk_id, pd.fine_cls_kbk_id,     (Case when pd.CREDITSIZE>0 then NVL(pd.percent_cls_kbk_id, pd.main_cls_kbk_id) else pd.main_cls_kbk_id end),  opp.PAY_DISTR_POLICY   into KBK_main, KBK_fine, KBK_percent , PayDistrPolicy
	                      											 from SM.PAYDOCS pd, SM.MOVEPERIODS mp, SM.OBLIG_PERIODICAL_PRESETS opp
													                    where pd.MOVEPERIOD_ID=mp.ID and opp.ID=pd.OBLIG_PERIODICAL_PRESETS_ID
																							and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
																							and mp.SINCEDATE = dTmp;
																	  else   --- <<< 23.10.2013 <<< -- Если и сверху нету (платеж после окончания ОД), то ищем ближайшую снизу
																									Select  max(mp.SINCEDATE)  into dTmp
																									from SM.PAYDOCS pd, SM.MOVEPERIODS mp
																									where pd.MOVEPERIOD_ID=mp.ID
																									and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
																									and mp.SINCEDATE < PayCurr.apply_date and NVL(mp.ENDDATE, to_date('01.01.3000', 'dd.mm.yyyy')) < PayCurr.apply_date;
																									if (dTmp is not null)   then
																														Select pd.main_cls_kbk_id, pd.fine_cls_kbk_id,     (Case when pd.CREDITSIZE>0 then NVL(pd.percent_cls_kbk_id, pd.main_cls_kbk_id) else pd.main_cls_kbk_id end),  opp.PAY_DISTR_POLICY   into KBK_main, KBK_fine, KBK_percent , PayDistrPolicy
																														 from SM.PAYDOCS pd, SM.MOVEPERIODS mp, SM.OBLIG_PERIODICAL_PRESETS opp
																														where pd.MOVEPERIOD_ID=mp.ID and opp.ID=pd.OBLIG_PERIODICAL_PRESETS_ID
																														and mp.MOVESET_ID=AMovesetID and pd.OBLIGATIONTYPE_ID=AObligtypeID
																														and mp.SINCEDATE = dTmp;
																									else
																												NULL; -- <<< ??? Сюда - диагностическое сообщение что не можем определить КБК
																									end if;
                                    end if; ---
                  end if;

								 Select (Case   when KBK_fine = KBK_main and NVL(KBK_percent,KBK_main) = KBK_main  then PayCurr.MAINPAY
								                            when PayCurr.cls_kbk_id =  KBK_fine AND  KBK_fine <> KBK_main then 'N'
																						when (PayCurr.cls_kbk_id =  KBK_main AND  KBK_percent <> KBK_main AND KBK_Main <> KBK_fine ) then 'Y'
																						when (PayCurr.cls_kbk_id =  KBK_percent AND  KBK_percent <> KBK_main) then 'P'
																						when (PayCurr.cls_kbk_id =  KBK_main AND  KBK_percent = KBK_main AND KBK_fine <> KBK_main AND PayCurr.MAINPAY in ('Y','P','M')) then PayCurr.MAINPAY -- <<< 29.10.2013 
--																						when (PayCurr.cls_kbk_id =  KBK_main AND  KBK_percent = KBK_main AND (KBK_fine <> KBK_main /*AND PayCurr.MAINPAY = 'Y'*/)) then 'M' -- <<< 23.05.2013 Условие может нарушать принцип "КБК - высший приоритет" (если например MAINPAY <> 'D')
																						when (PayCurr.cls_kbk_id is null AND  NVL(KBK_percent,0) = NVL(KBK_main,0) AND (NVL(KBK_fine,0) <> NVL(KBK_main,0) /* OR PayCurr.MAINPAY <> 'N'*/ )
																							and PayCurr.MAINPAY not in ('D', 'N') -- <<< Added 12.12.2011 - so that payments to be distributed on FINE too.
																							) then 'M'
--																						when (PayCurr.cls_kbk_id is null AND  KBK_percent = KBK_main AND KBK_fine = KBK_main AND PayCurr.MAINPAY <> 'N') then 'D'
																						else  PayCurr.MAINPAY end)
																						into MAINPAY from dual;
										-- Вызов private функции - основного блока распределения
									PAYMENT_DISTRIBUTE_SINGLE(PayCurr.ID, PayCurr.PayVal, AMovesetID, AObligtypeID, sm.getpaydateforpayment(PayCurr.ID), MAINPAY,  PayDistrPolicy, A_PAY_DISTR_PRIM_BY_DATE, APercents_Instant, ADistrDirect );
									
									-- VVV -- 08.05.2013 -- Контрольный выстрел - формирование "Учетной записи" по платежу ЕСЛИ она почему-либо отсутствует (такое бывало)
										select count (*) into ntmp from sm.CHARGE_APPLIES cha where cha.PAYMENT_ID = PayCurr.ID;
											if ntmp = 0 then
				      								insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
																																description, charge_id, corr_flag, cls_kbk_id, obligations_id,
																																payments_distribution_id, reversal_role, reversallink_id, payment_id)
																values (sm.SEQCHARGE_APPLIES.nextval, PayCurr.APPLY_DATE, PayCurr.SUM , AObligtypeID,	AMovesetID, PayCurr.MAINPAY,
																																'Платеж - ' || sm.ExpandDoc(PayCurr.DOCUMENTS_ID), null, 'N',  PayCurr.Cls_Kbk_Id,  AOBLIG_ID,
																																 null,  '',  null, PayCurr.ID);
											elsif ntmp=1 then
														-- VVV -- 17.05.2013 -- Контрольный выстрел - корректировка "Учетной записи" по платежу ЕСЛИ ее сумма не соответствует сумме платежа  (такое бывало)
															select cha.summ into ntmp from sm.CHARGE_APPLIES cha where cha.PAYMENT_ID = PayCurr.ID;
																if ntmp <> PayCurr.SUM then
														          Update sm.CHARGE_APPLIES cha set cha.SUMM =  PayCurr.SUM  where PAYMENT_ID = PayCurr.ID and cha.APPLY_DATE  > G_CloseDate;-- 27.03.2014 to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy');
																end if;			
											end if;
 
      end loop;

end;


--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- Распределение одного платежа - основной блок действий - !!! внутренняя (непубличная) функция !!!
 -- ( Если платеж начинает распределяться на основание с условиями начисления пени на день платежа, или на продажу с рассрочкой
 --   - происходит еще начисление пени и процентов соответственно. )
        -- Параметры:
            -- PayID                     -- ID распределяемого платежа
            -- PayValParam      -- Сумма платежа к распределению (т.е. еще не распределенная)
            -- MoveSetID        -- Нада чобы знать чо к чему относится
            -- PayDate               -- Дата платежа
 Procedure PAYMENT_DISTRIBUTE_SINGLE(PayID in number, PayValParam in number, MoveSetID  in number, ObligTypeID in number, PayDate date, PayDistrTarget char,  PayDistrPolicy char, A_PAY_DISTR_PRIM_BY_DATE char, APercents_Instant char, ADistrDirect char)
   is
 FirstCharge varchar2(1); --- <<< TODO: - заменить на внешний параметр, и контролировать сверху - включая только для САМОГО ПЕРВОГО платежа. (+ еще такое же при аренде....)
   PayVal  number(27,2) := PayValParam;
   ValToDistribute number(27,2);           -- Сумма к записи в текущее распределение.
   PayPalnID number := 0;                         -- Прошлый ID - для определения факта смены очередного плана
   DateToRecalc date;
   itmp number(27);
   itmpFine number(27);
   finesAdded boolean;
   percentAdded boolean := false;
   PayDescr varchar(100);
  -- PayDistrPolicy CHAR(3) := 'NPY';
   PayPlanPrevDate date := null;
	 ATypeToDistr varchar2(20) := 'OBLIGATION'; -- расшифровка типа обязательства - на который относить переплату
--nDiag number(27,4);
   iii NUMBER(27);
	 idNext number(27);
	 OBLIG_ID NUMBER(27);
   PercentsAfterEnddatems char(1) :='N';      --- начисление процентов после окончания действия ОД: Y - да,  N - нет    ---------16.01.2014 Morozova 
   CHARGE_FINE_ASSANCTION char(1);
 --  ADistrDirect char(1) := 'N';
   itmpPay number(27,2); --- Morozova
  
	begin
 -- Контрольный выстрел - проверка параметров:
    if PayID is null then
        raise_application_error(-20001, 'ID платежа NULL!!! Фигня-с-с, аднака...' );
    end if;
    -- Если суммы к распределению не осталось - выходим.
    if PayValParam = 0 then return;
    end if;

--- <<< 27.04.2012  >>> --- Разделение логики распределения входящих платежей, и возвратов.
if PayValParam > 0 then

-------------Предварительно основному распределению -  Цикл начисления процентов ------------------------------------
if APercents_Instant = 'N' then
--FirstCharge := 'Y';  --- первое начисление процентов -- Не надо, аднака!!! (иначе начисления стираются последующими платежами)
--  if PayDistrTarget in ( 'Y', 'D') then -- 08.11.2011  -- Оптимизация не удалась пока. Надо продолжить заниматься. Аднака.
          for pay_plan  in
          (
                Select pp.ID,
                NVL(ppd.FINEDATE, pp.FINEDATE) as FINEDATE,
                (pp.VAL - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)) as PlanVal,
                trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID, pp.PAYMENTS_PLAN_DRAFT_ID
                from SM.PAYMENTS_PLAN pp
                inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
        --   16.06.2011      left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
                inner join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
								inner join SM.OBLIGATIONS ob on ob.MOVESET_ID = ch.MOVESETS_ID and ob.OBLIGATIONTYPE_ID = ch.OBLIGATIONTYPE_ID
                where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
        --       Т.к. они переплачивают!!!       and  pp.VAL >  NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)
                      and  trim(ch.CHARGE_TYPE) in ('OBLIGATION', 'OTHER')
                      and  ch.FACTCHARGE = 'Y'
                      AND ch.CHARGEDATE > ob.RECALC_START_DATE  --- <<<  14.12.2012 --Не делаем начислений до даты начала пересчета. Делаем только после нее------
        -- 17.01.2014  Morozova ---- несколько платежей одной датой
        -- добавляем условие проверки: в начислениях на дату платежа не должны быть уже записи по начисленным процентам!
                      and not exists ( select * from sm.charges cha 
                                        where cha.MOVESETS_ID = MoveSetID 
                                        and cha.OBLIGATIONTYPE_ID = ObligTypeID
                                        and trunc(cha.chargedate) = trunc(PayDate)
                                        and cha.charge_type = 'PERCENT'
                                        and cha.factcharge = 'Y')
        ------------------   
                order by  FINEDATE, ID
           )
          loop
--               if (pay_plan.PlanVal > 0) then
                        select count(*) into itmp
                        from SM.PAYMENTS pm inner join SM.DOCUMENTS doc on pm.DOCUMENTS_ID = doc.ID
                        where pm.ID =  PayID;
                        if itmp = 1 then
                                  Select trim(doc.DOCNO) || ' от ' || to_char(doc.DOCDATE, 'DD.MM.YYYY') into PayDescr
                                  from SM.PAYMENTS pm inner join SM.DOCUMENTS doc on pm.DOCUMENTS_ID = doc.ID where pm.ID =  PayID;
                          else
                                 PayDescr := null;
                         end if;

                           -- Собственно начисление процентов
                          percentAdded := PAYMENT_ADD_PERCENTS(pay_plan.ID, trunc(pay_plan.FINEDATE), trunc(PayDate), PayPlanPrevDate, MoveSetID, pay_plan.OBLIGATIONTYPE_ID, pay_plan.PAYMENTS_PLAN_DRAFT_ID, 'Y',  PayDescr,PayID, FirstCharge );
                          FirstCharge := 'N';
                          PayPlanPrevDate := pay_plan.FINEDATE;
--                  end if;
                  itmp := 0;
          end loop;
          
          --- 09.07.2014 Morozova
          --- выявляем параметр продолжать ли начисления процентов после окончания ОД
          select obp.percents_after_enddatems, obp.charge_fine_assanction  
            into PercentsAfterEnddatems, CHARGE_FINE_ASSANCTION
          from sm.obligations og
            inner join sm.oblig_presets obp
            on og.oblig_presets_id = obp.id
          where og.moveset_id = MoveSetID and og.obligationtype_id = ObligTypeID;
          
          -- если платеж проходит датой, после окончания действия ОД     --- 16,01,2014
          -- начисление %% в закрытой ОД до полного погашения долга
          if PercentsAfterEnddatems = 'Y' and PayDate >= getmovesetenddate(MoveSetID)
          then
             percentAdded := 
             PAYMENT_ADD_PERCENTS(PayPalnID, trunc(to_date('01.01.3000', 'dd.mm.yyyy')), 
                                  trunc(PayDate), PayPlanPrevDate,
                                  MoveSetID, ObligTypeID, 
                                  null, 
                                  'Y',  PayDescr,PayID, FirstCharge );
          end if;
          --------------
 end if;

 FirstCharge := 'Y';  --- первое начисление пени  -- Не надо, аднака!!! (иначе начисления стираются последующими платежами) -- НЕТ НАДО иначе размножаются проводки.

   ---- <<< 13.02.2012 <<<  А не было ли ранее недоразнесеных платежей, а не разнести ли их на только что начисленные в связи с ДАННЫМ платежом проценты?
	 ---- рекурсивный вызов!!! Но вроде проверено, мин нет.
	 if percentAdded then  -- <<< 01.03.2012 <<< Уточнено условие, иначе при обязательствах без обязательств но из одних платежей (вот так!) - получали как-раз мертвый цикл...
            PAYMENTS_PROCEED(MoveSetID, ObligtypeID, to_date('01.01.1900', 'dd.MM.yyyy'), PayDate-1); -- << 03.10.2012 << Иначе текущий платеж разносился дважды - в вызове, а потом ниже...
	 end if;

------------------------------------------------ Теперь собственно распределение -------------------------------------------------------------------
-- Организуем выборку еще незакрытых планов поступлений, на которые будем последовательно в цикле распределять наш платеж
-- (пока хватит его суммы, (может всего на 1 план...), или не кончатся планы - тогда остаток зависнет, и надо процедуру зачисления как аванса.)
  for pay_plan  in
    (
          Select pp.ID,
         nvl(NVL(ppd.FINEDATE, pp.FINEDATE), ch.chargedate) as FINEDATE, --- 18.06.2014 Morozova  иначе не распределялся платеж на доп начисление без пени
       --   NVL(ppd.FINEDATE, pp.FINEDATE) as FINEDATE,  ---
          (pp.VAL - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)) as PlanVal,
          trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID, pp.PAYMENTS_PLAN_DRAFT_ID
          from SM.PAYMENTS_PLAN pp
          inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
          left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
          where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
          and  pp.VAL >  NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)
          and  ch.FACTCHARGE = 'Y'
				--	and pp.FINEDATE is not null
          and (pp.FINEDATE is not null or ch.charge_type = 'OTHER') --- 18.06.2014 Morozova  иначе не распределялся платеж на доп начисление без пени
          --- 16.09.2011 -- Доп. уточнение распределения на осн.долг/проценты
          and (decode(trim(ch.CHARGE_TYPE),'OBLIGATION', 'Y', 'OTHER', 'Y', 'PERCENT','P', 'FINE', 'N', 'D' ) = PayDistrTarget  OR decode(trim(ch.CHARGE_TYPE),'OBLIGATION', 'M', 'OTHER', 'M', 'PERCENT', 'M', 'FINE', 'N', 'D' ) =PayDistrTarget  OR (PayDistrTarget = 'D')
          OR (PayDistrTarget = 'N')) -- <<<< 12.12.2011 - Иначе - первый платеж по пене (в отсутствие пени) не пройдет.
          order by
              (case when  (PayDistrTarget = 'N' and trim(ch.CHARGE_TYPE)='FINE') then 1 else 0 end), -- <<< 18.06.2012 -- Для пени - все-таки в первую очередь на пеню!
              (case  when (A_PAY_DISTR_PRIM_BY_DATE = 'Y') then NVL(ppd.FINEDATE, pp.FINEDATE) else to_date('01.01.1917','dd.MM.yyyy') end), --<< 18.09.2012 Дата или до порядка
              (case  when (A_PAY_DISTR_PRIM_BY_DATE = 'N' and NVL(ppd.FINEDATE, pp.FINEDATE) <= PayDate) then 0 else 1 end), --<< 18.09.2012 Или дата после порядка
						  (case when PayDistrPolicy = 'NPY' then (case when trim(ch.CHARGE_TYPE) = 'FINE' then 1  when trim(ch.CHARGE_TYPE) = 'PERCENT' then 2 else 3 end)
												when PayDistrPolicy = 'NYP' then (case when trim(ch.CHARGE_TYPE) = 'FINE' then 1  when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 2 else 3 end)
												when PayDistrPolicy = 'PNY' then (case when trim(ch.CHARGE_TYPE) = 'PERCENT' then 1  when trim(ch.CHARGE_TYPE) = 'FINE' then 2 else 3 end)
												when PayDistrPolicy = 'PYN' then (case when trim(ch.CHARGE_TYPE) = 'PERCENT' then 1  when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 2 else 3 end)
												when PayDistrPolicy = 'YPN' then (case when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 1  when trim(ch.CHARGE_TYPE) = 'PERCENT' then 2 else 3 end)
												when PayDistrPolicy = 'YNP' then (case when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 1  when trim(ch.CHARGE_TYPE) = 'FINE' then 2 else 3 end)
												else 0 end ) ,
						    nvl(NVL(ppd.FINEDATE, pp.FINEDATE), ch.chargedate),  ch.FINEDATE,  --- 18.06.2014 Morozova  иначе не распределялся платеж на доп начисление без пени
							--	NVL(ppd.FINEDATE, pp.FINEDATE),  ch.FINEDATE,  --<< 18.09.2012 Или дата после порядка
								ID
      )
     LOOP

          -- Если платежа не осталось, или назначение платежа не соотвесттвует виду начисления - прерываем цикл (и всю процедуру).
           if  PayVal <= 0  then
                      exit;
           end if;
--- VVVV Невероятная проверка !!!  (Как может отсутствовать толко что выбранный pay_plan.ID ??? Но - факт.)
Select count(*) into iii  from SM.PAYMENTS_PLAN pp where pp.ID= pay_plan.ID;
 if iii =1 then

               -- Проверяем, и если платеж больше всех начислений (переплата)
               --  - то будем относить весь остаток на последнее начисление.
               -- (Используется ниже, но определяется тут. (Так нада, аднака!))
               Select count(*) into itmp
               from SM.PAYMENTS_PLAN pp
               inner join  SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                          and  ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
              where pp.FINEDATE > pay_plan.FINEDATE;

           -- Определяем остаток чего больше - нераспределенная часть платежа, или выбранная в цикле неоплаченная часть плана, и на сумму меньшего из них будем писать распределение.
           if (PayVal > pay_plan.PlanVal ) then
                 ValToDistribute := pay_plan.PlanVal;
           else
                 ValToDistribute :=  PayVal;
            end if;

           -- raise_application_error(-20001,'PAYMENT_DISTRIBUTE_SINGLE - Дата конца периода ' || to_char(pay_plan.FINEDATE, 'DD.MM.YYYY') );
         if (pay_plan.ID <>  PayPalnID and  trim(pay_plan.CHARGE_TYPE) in ('OBLIGATION', 'OTHER', 'PERCENT','FINE')) then --07062011
                 PayPalnID := pay_plan.ID;

                     -- !!!  Начисляем ПЕНИ  !!! ----------------
                     if ( IsCalcFineNeed and PayDistrTarget in ('Y', 'P', 'M', 'D',    'N'   )-- and trim(pay_plan.CHARGE_TYPE) in ('OBLIGATION', 'OTHER', 'PERCENT')  --19.05.2014 Morozova иначе дополнительно начислялась пеня в периодических обязательствах на доп начисления при авторазноске
                          and (trim(pay_plan.CHARGE_TYPE) in ('OBLIGATION', 'PERCENT') -- 19.05.2014 Morozova
                                or (trim(pay_plan.CHARGE_TYPE) = 'OTHER' and CHARGE_FINE_ASSANCTION = 'Y'  and PayDistrTarget <> 'N'))  --- 09.07.2014 Morozova иначе не начислялась пеня на доп начисление по ставке рефинансирования на день платежа
	   										  and pay_plan.FINEDATE < PayDate  and (PayDistrTarget <> 'N' OR FirstCharge = 'Y')) then -- <<< 17.05.2012 << Оптимизация чтобы не пытаться начислять пеню на будущее
												-- <<<< 12.12.2011 - 'N' added - Иначе - первый платеж по пене не пройдет.
												-- <<< 13.03.2012 <<< - IsCalcFineNeed проверка добавлена
                            finesAdded := ADD_FINES( ValToDistribute, pay_plan.ID, trunc(pay_plan.FINEDATE), trunc(PayDate), MoveSetID, pay_plan.OBLIGATIONTYPE_ID, pay_plan.PAYMENTS_PLAN_DRAFT_ID, PayID, FirstCharge);
                            FirstCharge := 'N';   --27.10.2011 -- Иначе - стирались все предыдущие начисления пени!!!
                     end if;

                      -- И доп. распределение - сначала на возможно сделанные только что в ADD_FINES начисления !!!
                      if ( PayDistrTarget = 'N'  OR  (PayDistrTarget = 'D'     and (PayDistrPolicy in ('NPY','NYP') ) ) ) then
                                  for pay_plan_inner  in
                                  (
                                        Select pp.ID,
                                        pp.Val as PlanVal,
                                       ch.paysize - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0) as PlanValFine,
                                        trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID
                                        from SM.PAYMENTS_PLAN pp
                                        inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
                                        where ch.MOVESETS_ID = MoveSetID  and ch.OBLIGATIONTYPE_ID = ObligTypeID
                                       and trim(ch.CHARGE_TYPE) ='FINE' -- 07062011 and pp.PAYMENTS_PLAN_DRAFT_ID is not null
                                        and  (ch.paysize - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_PLAN_ID = pp.ID ), 0)) > 0
                                        and  ch.FACTCHARGE = 'Y'
                                        and nvl(ch.FINEDATE, to_date('01.01.1900')) <=  (PayDate + 0.01) ---19.05.2014 Morozova иначе терялась сумма пени от доп начисления по пене
--																			 and ch.FINEDATE <=  (PayDate + 0.01) -- 01.08.2012/ 17.07.2013 (так правильней чем ниже!)  - Чтобы разносился на пени начисленные только тут же (или ранее), в то цикл закрывал ВСЕ пени, нарушая последовательность при наличие пеней начисленных позже
--                                       and ch.FINEDATE <=  pay_plan.FINEDATE   -- <<< 13.01.2013/ 21.02.2013  -- Чтобы соблюдался приоритет периодов (ато вэтом цикле всегда оплачивалась вся ранняя пеня
																				and  (
																				( (pp.FINEDATE <=  (PayDate + 0.01) OR ch.FINEDATE <=  (PayDate + 0.01) OR ch.CHARGEDATE <=  (PayDate + 0.01)) and (PayDistrPolicy in ('NPY','NYP')  OR  PayDistrTarget = 'N') )
																				OR
																				((PayDistrTarget = 'D' and PayDistrPolicy not in ('NPY','NYP'))  and NVL(pp.FINEDATE,ch.CHARGEDATE)  <  pay_plan.FINEDATE)
																				)
                                        order by  ch.CHARGEDATE, pp.FINEDATE, ch.ID
                                  )
                                  loop
                                                -- Если платежа не осталось - прерываем цикл (и всю процедуру).
                                             if PayVal <= 0 then exit;
                                             end if;
                                             if pay_plan_inner.PlanValFine <= 0 then exit;
                                             end if;

                                             -- Определяем остаток чего больше - нераспределенная часть платежа, или выбранная в цикле неоплаченная часть плана, и на сумму меньшего из них будем писать распределение.
                                             if (PayVal > pay_plan_inner.PlanValFine) then
                                                   ValToDistribute := pay_plan_inner.PlanValFine;
                                                   PayVal := PayVal  -  pay_plan_inner.PlanValFine;
                                             else
                                                   ValToDistribute :=  PayVal;
                                                   PayVal := 0;   -- Все. Платеж (или его остаток) сделал все что мог, поэтому - ему ба-а-льшой кердык.
                                              end if;
                                             -- Пишем распределение
                                              Select count(*) into itmpFine from SM.PAYMENTS_DISTRIBUTION pd
                                              where PAYMENTS_ID=PayID and PAYMENTS_PLAN_ID = pay_plan_inner.ID and  VAL= ValToDistribute and ISAUTO= 'Y' ;
                                              if (itmpFine = 0) then
                                                        Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
                                                        values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, pay_plan_inner.ID, ValToDistribute, 'Y');
                                               end if;
                                  end loop;

                                   -- Восстанавливаем возможно порушенное предыдущим циклом ValToDistribute
                                   if (PayVal > pay_plan.PlanVal) then
                                         ValToDistribute := pay_plan.PlanVal;
                                   else
                                         ValToDistribute :=  PayVal;
                                   end if;
                       end if;
            end if;

       -- Пишем распределение (в данном случае только НЕ на пеню - на нее уже был вложенный цикл)
        if (PayDistrTarget in ('Y', 'P', 'M', 'D')) then   --- <<< 16.02.2012 <<< Перемещено сюда снизу, т.к. раньше ПРИ ПЕНЕ сумма уменьшалась, а распределение не писалось...
           -- Определяем остаток чего больше - нераспределенная часть платежа,
           -- или выбранная в цикле неоплаченная часть плана,
           -- и на сумму меньшего из них будем писать распределение.
           -- К тому же проверяем, и если платеж больше всех начислений (переплата)
               --  - то будем относить весь остаток на последнее начисление.
							 --VVVVVVVVVVV  29.08.2012 к 4.7.5  - Все ниже - оказалось не актуально из-за обработки переплат ниже.
           if itmp = 0 /* and  pay_plan.CHARGE_TYPE = 'OBLIGATION' /*and PayDistrTarget in ('Y', 'P', 'M')*/  then  -- <<< 29.08.2012 к 4.7.5  - Иначе на пеню не разносилось (если она НЕ погашается сразу (по политике YPN)
                                   if (PayVal > pay_plan.PlanVal) then
                                        ValToDistribute := pay_plan.PlanVal;
                                   else
                                         ValToDistribute :=  PayVal;
                                   end if;
 --  								 ValToDistribute := PayVal;
--									 PayVal := 0;
           end if;
           itmp := 0;

        -- Пишем собственно распределение
      --  if (PayDistrTarget in ('Y', 'P', 'M', 'D')) then   --- <<< 16.02.2012 <<< Перемещено вверх, т.к. раньше ПРИ ПЕНЕ сумма уменьшалась, а распределение не писалось...
              Select count(*) into itmpFine from SM.PAYMENTS_DISTRIBUTION pd
              where pd.PAYMENTS_ID=PayID and pd.PAYMENTS_PLAN_ID =  pay_plan.ID and  pd.VAL= ValToDistribute and pd.ISAUTO= 'Y';
              if (itmpFine = 0  and ValToDistribute <> 0) then      --- <<< 07.03.2012 -- <<< добавлена проверк на 0
								        ---VVVVV---- 27.04.2012 ---VVVVV----- Вставлена невероятная проверка по прецеденту - факту нарушения FK по pay_plan.ID...
								        Select count(*) into itmpFine  from SM.PAYMENTS_PLAN pp where pp.ID= pay_plan.ID;
												if itmpFine <> 1 then
													    raise_application_error(-20001, 'Не найден план погашения с ID=' || to_char(pay_plan.ID) ||'для ОД с ID=' || to_char(MoveSetID) ||  '!  Фигня-с-с, аднака...' );
												end if;
												--- ^^^^ ----
                       ------VVV --- 18.09.2012 --- (было раньше)
											 if (PayVal > pay_plan.PlanVal ) then
															PayVal := PayVal -  pay_plan.PlanVal;
											 else
														 PayVal := 0;   -- Все. Платеж (или его остаток) сделал все что мог, поэтому - ему ба-а-лшой кердык, аднака.
												end if;
                        -----------------------------
                        Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
                        values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, pay_plan.ID, ValToDistribute, 'Y');
               end if;
        end if;
        itmpFine := 0;
        FirstCharge := 'N';

 end if;
	END LOOP;

   select nvl(sum(pd.val), 0) into itmpPay from sm.payments_distribution pd where pd.payments_id = PayID;  --- 08.12.2014 Morozova  получаем распределенную сумму платежа
    ------- Особый случай - распределение платежа при переплате - искусственно привязать к последнему периоду.--------
	 if PayVal > 0 and PayValParam > itmpPay then ---	признак что платеж недоразнесен   ---28.11.2014 Morozova точное задание условия что платеж не дораспределен

					 if PayDistrTarget = 'P' then
						        ATypeToDistr := 'PERCENT';
						elsif  PayDistrTarget = 'N' then
						        ATypeToDistr := 'FINE';
						elsif  PayDistrTarget = 'Y' OR PayDistrTarget = 'M' OR PayDistrTarget = 'D'  then
						        ATypeToDistr := 'OBLIGATION';
					 end if;
					 Select max(pp.ID)  into itmp
						from SM.PAYMENTS_PLAN pp
						inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
						where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID and  ch.FACTCHARGE = 'Y' and trim(ch.CHARGE_TYPE) = trim(ATypeToDistr);
					 if itmp > 0 then
										 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
											values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp,  PayVal, 'Y');
						elsif ADistrDirect = 'N' then  -- Если не нашлось начисления нужного типа, на которое можно отнести переплату - то на основной долг.
        					 Select max(pp.ID)  into itmp
				      	 	from SM.PAYMENTS_PLAN pp
						       inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
					      	where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID and  ch.FACTCHARGE = 'Y' and ch.CHARGE_TYPE in ( 'OBLIGATION', 'OTHER'); -- <<< 04.04.2013 - Добавлено OTHER
									 if itmp > 0 then
													 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
														values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp, PayVal, 'Y');
									 else 			 -- Если не нашлось начисления по осн.долгу -  то ХОТЬ НА ЧТО!!! последнее.
													 Select max(pp.ID)  into itmp
														from SM.PAYMENTS_PLAN pp
														 inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
														where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID;
														 if itmp > 0 then
																		 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
																			values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp, PayVal, 'Y');
														 else     -- Если вообще нет начислений - то создаем фиктивное пустое (на 0) начисление, и относим на него . (24.12.2012)
															     Select ob.ID into OBLIG_ID from SM.OBLIGATIONS ob  where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID ;
		                               Select sm.seqcharges.nextval into idNext from dual;
	                                 INSERT INTO Charges (id, chargedate, movesets_id, document_id, comments, paysize, charge_type, obligationtype_id, Finedate, Discountsize,Paydoc_Id,calperiod_start,Calperiod_End,Cls_Kbk_Id,Redir_Flag,redir_paydoc_id)
                                      Select idNext, PayDate, MoveSetID, max((Select max(d.ID) from SM.DOCUMENTS d inner join SM.DOCTYPES  dt on dt.ID=d.DOCTYPES_ID and dt.GUID = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE')),  'Технич. для разноски платежей в отсутствие начислений', 0, 'OTHER',
                                        ObligTypeID, PayDate, 0, min(pd.ID), PayDate, PayDate, null, 'N', null
																			 --from SM.PAYDOCS pd inner join SM.OBLIGATIONS ob on ob.ID =  OBLIG_ID;
                                       from SM.PAYDOCS pd  --- 12.11.2014 Morozova составлена правильная связка для выбора paydocId
                                       inner join sm.moveperiods mp on mp.id = pd.moveperiod_id
                                       inner join SM.OBLIGATIONS ob on  pd.obligationtype_id = ob.obligationtype_id  and ob.moveset_id = mp.moveset_id
                                       where ob.ID =  OBLIG_ID;

																	 INSERT INTO SM.PAYMENTS_PLAN (ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL )
                                      VALUES(SM.seqpayments_plan.nextval, idNext, OBLIG_ID, PayDate, 0);

  /* Оставлено из остроржности		                             Select SM.seqpayments_plan.currval into idNext from dual;
																	 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
																			values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, idNext, PayVal, 'Y');
  */														 end if;
								  end if;
					else -- при жестком распределении на "свою" статью....
								 Select ob.ID into OBLIG_ID from SM.OBLIGATIONS ob  where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID ;
								 Select sm.seqcharges.nextval into idNext from dual;
								 INSERT INTO Charges (id, chargedate, movesets_id, document_id, comments, paysize, charge_type, obligationtype_id, Finedate, Discountsize,Paydoc_Id,calperiod_start,Calperiod_End,Cls_Kbk_Id,Redir_Flag,redir_paydoc_id)
									 Select idNext, PayDate, MoveSetID, max((Select max(d.ID) from SM.DOCUMENTS d inner join SM.DOCTYPES  dt on dt.ID=d.DOCTYPES_ID and dt.GUID = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE')),  
												'Технич. для разноски платежей в отсутствие начислений', 0,  ATypeToDistr,
												ObligTypeID, PayDate, 0, min(pd.ID), PayDate, PayDate, null, 'N', null
										  --  from SM.PAYDOCS pd inner join SM.OBLIGATIONS ob on ob.ID =  OBLIG_ID; 
                   from SM.PAYDOCS pd  --- 12.11.2014 Morozova составлена правильная связка для выбора paydocId
                   inner join sm.moveperiods mp on mp.id = pd.moveperiod_id
                   inner join SM.OBLIGATIONS ob on  pd.obligationtype_id = ob.obligationtype_id  and ob.moveset_id = mp.moveset_id
                   where ob.ID =  OBLIG_ID;

								 INSERT INTO SM.PAYMENTS_PLAN (ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL )
										VALUES(SM.seqpayments_plan.nextval, idNext, OBLIG_ID, PayDate, 0);
					end if;
 	 end if;

--- <<< 27.04.2012  >>> ----------------------- !!!  Если платеж исходящий !!! ----------------------------------------------------------------------
else
--- Для отрицательных платежей (возвратов) - отдельная логика:
--- Они распределяются на ранее сделанные нормальные распределения в обратном порядке, погашая тем самым их.
	  for pay_plan  in
    (
          Select pp.ID,
          NVL(ppd.FINEDATE, pp.FINEDATE) as FINEDATE,
          - pd.VAL as PlanVal,
          trim(ch.CHARGE_TYPE) as CHARGE_TYPE, ch.OBLIGATIONTYPE_ID, pp.PAYMENTS_PLAN_DRAFT_ID
          from SM.PAYMENTS_DISTRIBUTION pd
					inner join SM.PAYMENTS_PLAN pp on pd.PAYMENTS_PLAN_ID = pp.ID
          inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
          left join SM.PAYMENTS_PLAN_DRAFT ppd on ppd.ID = pp.PAYMENTS_PLAN_DRAFT_ID
          where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID
					and pd.VAL > 0
          and  (Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr
					           where pdistr.PAYMENTS_PLAN_ID = pp.ID
											and pdistr.payments_id <> PayID ) > 0
          and  ch.FACTCHARGE = 'Y'
          --- 16.09.2011 -- Доп. уточнение распределения на осн.долг/проценты
          and (decode(trim(ch.CHARGE_TYPE),'OBLIGATION', 'Y', 'OTHER', 'Y', 'PERCENT','P', 'FINE', 'N', 'D' ) = PayDistrTarget  OR decode(trim(ch.CHARGE_TYPE),'OBLIGATION', 'M', 'OTHER', 'M', 'PERCENT', 'M', 'FINE', 'N', 'D' ) =PayDistrTarget  OR (PayDistrTarget = 'D')
        -- OR (PayDistrTarget = 'N') -- <<<< 18.06.2012 - Возврат в отсутствии начислений пени - делаем - импоссибл.
				 )
         order by  NVL(pp.FINEDATE, ch.CHARGEDATE) desc,
               (case when PayDistrPolicy = 'NPY' then (case when trim(ch.CHARGE_TYPE) = 'FINE' then 1  when trim(ch.CHARGE_TYPE) = 'PERCENT' then 2 else 3 end)
                          when PayDistrPolicy = 'NYP' then (case when trim(ch.CHARGE_TYPE) = 'FINE' then 1  when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 2 else 3 end)
                          when PayDistrPolicy = 'PNY' then (case when trim(ch.CHARGE_TYPE) = 'PERCENT' then 1  when trim(ch.CHARGE_TYPE) = 'FINE' then 2 else 3 end)
                          when PayDistrPolicy = 'PYN' then (case when trim(ch.CHARGE_TYPE) = 'PERCENT' then 1  when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 2 else 3 end)
                          when PayDistrPolicy = 'YPN' then (case when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 1  when trim(ch.CHARGE_TYPE) = 'PERCENT' then 2 else 3 end)
                          when PayDistrPolicy = 'YNP' then (case when trim(ch.CHARGE_TYPE) = 'OBLIGATION' then 1  when trim(ch.CHARGE_TYPE) = 'FINE' then 2 else 3 end)
                          else 0 end ) desc,
								PD.ID desc
      )
      loop
                          
           -- Если платежа не осталось, или назначение платежа не соотвесттвует виду начисления - прерываем цикл (и всю процедуру).
           if  PayVal >= 0 then 
                      exit;
           end if;

           if (PayVal < pay_plan.PlanVal ) then
                  PayVal := PayVal - pay_plan.PlanVal;
      			     ValToDistribute := pay_plan.PlanVal;
           else
      			     ValToDistribute := PayVal;
                 PayVal := 0;   -- Все. Платеж (или его остаток) сделал все что мог, поэтому - ему ба-а-лшой кердык, аднака.
            end if;

						Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
					 values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, pay_plan.ID, ValToDistribute, 'Y');
     end loop;

--- Если возврат больше всех ранее сделанных платежей - то он связывается с первым начислением на сумму остатка.
	 if PayVal < 0 then 		-- признак что платеж скомпенсировал предыдущие платежи, и еще остался
					 if PayDistrTarget = 'P' then
						        ATypeToDistr := 'PERCENT';
						elsif  PayDistrTarget = 'N' then
						        ATypeToDistr := 'FINE';
					 end if;
					 Select min(pp.ID)  into itmp
						from SM.PAYMENTS_PLAN pp
						inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
						where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID and  ch.FACTCHARGE = 'Y' and ( trim(ch.CHARGE_TYPE) = trim(ATypeToDistr)
						OR trim(ch.CHARGE_TYPE) = 'OTHER' and  trim(ATypeToDistr) = 'OBLIGATION') ; -- <<< 12.11.2013 -- Иначе на доп.начисления на срабатывало!
					 if itmp > 0 then
										 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
											values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp,  PayVal, 'Y');
						else   -- Если не нашлось начисления нужного типа, на которое можно отнести переплату - то на основной долг.
        					 Select min(pp.ID)  into itmp
				      	 	from SM.PAYMENTS_PLAN pp
						       inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
					      	where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID and  ch.FACTCHARGE = 'Y' and ch.CHARGE_TYPE  in ('OBLIGATION', 'OTHER')
                    and not (pp.val = 0 and ATypeToDistr = 'FINE'); -- <<< 12.11.2013 -- Иначе на доп.начисления на срабатывало!
									 if itmp > 0 and not(PayVal < 0 and PayDistrTarget = 'N') then  --- 27.11.2014 Morozova исключаем распределение на обязательство отрицательного платежа строго по пене not (PayVal < 0 and PayDistrTarget = 'N')
													 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
														values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp, PayVal, 'Y');
									 else 			 -- Если не нашлось начисления по осн.долгу -  то ХОТЬ НА ЧТО!!! последнее.
													 Select max(pp.ID)  into itmp
													 from SM.PAYMENTS_PLAN pp
														 inner join SM.CHARGES ch on ch.ID = pp.CHARGES_ID
													 where ch.MOVESETS_ID = MoveSetID and ch.OBLIGATIONTYPE_ID = ObligTypeID and not (pp.val = 0 and ATypeToDistr = 'FINE'); --- 12.11.2014 Morozova not (pp.val = 0 and ATypeToDistr = 'FINE') 
													 if itmp > 0 and PayDistrTarget <> 'Y' and not(PayVal < 0 and PayDistrTarget = 'N') then  ---01.08.2014 / 27.11.2014 Morozova добавлено  and PayDistrTarget <> 'Y' отрицательное начисление не должно идти на начисление по пене 
																		 Insert into SM.PAYMENTS_DISTRIBUTION (ID, PAYMENTS_ID, PAYMENTS_PLAN_ID, VAL, ISAUTO)
																			values (SM.SEQPAYMENTS_DISTRIBUTION.NEXTVAL, PayID, itmp, PayVal, 'Y');
													 else --- 01.08.2014 Morozova  Если нет начислений по обязательству, а отрицательный платеж явно указан на обязательство - то создаем фиктивное пустое (на 0) начисление, и относим на него
															     Select ob.ID into OBLIG_ID from SM.OBLIGATIONS ob  where ob.MOVESET_ID = MoveSetID and ob.OBLIGATIONTYPE_ID = ObligTypeID ;
		                               Select sm.seqcharges.nextval into idNext from dual;
	                                 INSERT INTO Charges (id, chargedate, movesets_id, document_id, comments, paysize, charge_type, obligationtype_id, Finedate, Discountsize,Paydoc_Id,calperiod_start,Calperiod_End,Cls_Kbk_Id,Redir_Flag,redir_paydoc_id)
                                      Select idNext, PayDate, MoveSetID, max((Select max(d.ID) from SM.DOCUMENTS d 
                                      inner join SM.DOCTYPES  dt on dt.ID=d.DOCTYPES_ID and dt.GUID = '8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE')),  
                                      'Технич. для разноски платежей в отсутствие начислений', 0, --'OTHER',
                                      case when ATypeToDistr in ('PERCENT', 'OBLIGATION') then 'OTHER' else ATypeToDistr end,
                                        ObligTypeID, PayDate, 0, min(pd.ID), PayDate, PayDate, null, 'N', null
																				from SM.PAYDOCS pd  --- 12.11.2014 составлена правильная связка для выбора paydocId
                                             inner join sm.moveperiods mp on mp.id = pd.moveperiod_id
                                             inner join SM.OBLIGATIONS ob on  pd.obligationtype_id = ob.obligationtype_id  and ob.moveset_id = mp.moveset_id
                                             where ob.ID =  OBLIG_ID;

																	 INSERT INTO SM.PAYMENTS_PLAN (ID, CHARGES_ID, OBLIGATIONS_ID, FINEDATE, VAL )
                                      VALUES(SM.seqpayments_plan.nextval, idNext, OBLIG_ID, PayDate, 0);
                           end if;
								  end if;
					end if;
 	 end if;

end if;

     -- Дату актуальности переставляем на самую позднюю из планов на которые распределялся данный или следующие за ним платежи (если он вставляется ДО существующих позже датированных платежей)
     DateToRecalc := PayDate;
    Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = DateToRecalc where  MOVESET_ID = MoveSetID and OBLIGATIONTYPE_ID = ObligTypeID;

end; -- PAYMENT_DISTRIBUTE_SINGLE


--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- Распределение одного платежа
        -- Параметры:
            -- PayID      -- Идентификатор платежа к распределению
   Procedure PAYMENT_DISTRIBUTE_SINGLE(PayID NUMBER, APercents_Instant char, ADistrDirect char )
   is

  PayVal               SM.PAYMENTS.SUM%type;         -- Сумма платежа к распределению (т.е. еще не распределенная)
  MoveSetID  number(27);              -- Оно нада чобы знать  к чему оно все относится
  ObligTypeID   number(27);
  PayDate date;                                                                 -- Дата платежа
  PayDistrTarget char(1);
begin

  -- Выбираем дополнительные данные платежа - для вызова private функции - основного блока распределения
   Select (pm.SUM - NVL((Select sum(pdistr.VAL) from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pm.ID ), 0)), pm.MOVESETS_ID, pm.OBLIGATIONTYPE_ID, sm.getpaydateforpayment(pm.ID), pm.MAINPAY
   into PayVal, MoveSetID, ObligTypeID, PayDate, PayDistrTarget
   from SM.PAYMENTS pm
   where pm.ID = PayID;
   -- Если суммы к распределению не осталось - выходим.
   if PayVal = 0 then return;
   end if;
--- TODO - !!! Ф-ю реанимировать на предмет полной добычи параметров для вызова PAYMENT_DISTRIBUTE_SINGLE. Она кое-где используется!!!
 -- Вызов  основного блока распределения
  PAYMENT_DISTRIBUTE_SINGLE( PayID, PayVal, MoveSetID, ObligTypeID, PayDate, PayDistrTarget, 'NPY', 'Y', APercents_Instant, ADistrDirect);

 -- ?????????? Question - is that below actual, аднака? ПОСЛЕ КАЖДОГО ПЛАТЕЖА??? (Были причины???)
  sm.FINE_PERCENT_ON_DATE_PKG.CALC_PERSENS_FINES_FOR_DATE(MoveSetID, ObligTypeID, trunc(sysdate));

  end;


--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- Распределение платежей для определенного обязательства - вариант исполльзуемый для рассрочки
  -- ( Организуем цикл по всем платежам данного обязательства, для каждого вызывая функцию его распределения )
        -- Параметры:
            -- ObligID      -- Идентификатор обязательства для которого выполнить распределение его платежей
Procedure PAYMENTS_DISTRIBUTE(ObligID number)
is
itmp number;
AMovesetID number(27);
AObligtypeID number(27);
IsCredit integer;
ARecalc_Start_Date date;

  begin

 Select ob.MOVESET_ID, ob.OBLIGATIONTYPE_ID, ob.RECALC_START_DATE
   into  AMovesetID, AObligtypeID, ARecalc_Start_Date
   from SM.OBLIGATIONS ob where ob.ID = ObligID;

-- Подчищаем ранее сделанные распределения - для рассрочки
Select count(*) into IsCredit from SM.PAYMENTS_PLAN_DRAFT ppd
where ppd.MOVESETS_ID =  AMovesetID
and ppd.OBLIGATIONTYPE_ID =  AObligtypeID;

if (IsCredit  > 0   and IsCalcFineNeed   ) then
      Delete from SM.CHARGES
              where MOVESETS_ID = AMovesetID
              and OBLIGATIONTYPE_ID =  AObligtypeID
              and DOCUMENT_ID is null
               and CHARGE_TYPE <> 'OBLIGATION'
							        and  CHARGE_TYPE <> 'PERCENT'  -- <<< 04.04.2013 - Не надо удалять проценты, в частности при их фиксированном варианте
							        and  CHARGE_TYPE <> 'OTHER'  -- <<< 04.04.2013 - Не надо удалять доп.начислене НИКОГДА
							AND CHARGEDATE > ARecalc_Start_Date;   ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.

      Delete  from SM.PAYMENTS_DISTRIBUTION  where PAYMENTS_ID in
          (
          Select pm.ID  from SM.PAYMENTS pm
          where pm.MOVESETS_ID = AMovesetID and pm.OBLIGATIONTYPE_ID = AObligtypeID
          );
end if;

         PAYMENTS_PROCEED(AMovesetID, AObligtypeID, to_date('01.01.1900', 'dd.MM.yyyy'), to_date('01.01.3000', 'dd.MM.yyyy'));

 end;

--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- Распределение платежей для определенного обязательства:
  -- ( Организуем цикл по всем платежам данного обязательства, для каждого вызывая функцию его распределения )
Procedure PAYMENTS_DISTRIBUTE(AMoveperiod_ID in number, AObligType_ID in number, NowOnDate in char )
  is
    AMoveSet_ID number(27);
    BegDate date;
    EndDate date;
    itmp number(27);
    IsCredit integer;
    dTmp date;
		ARecalc_Start_Date date;

 begin


Select count(*) into itmp  from SM.MOVEPERIODS where ID = AMoveperiod_ID; -- <<< Уж на невероятный случай проверка.
if (itmp = 1) then
          Select MOVESET_ID, SINCEDATE, NVL(ENDDATE, to_date('01.01.3000', 'dd.MM.yyyy')) into AMoveSet_ID, BegDate, EndDate  from SM.MOVEPERIODS where ID = AMoveperiod_ID;
					--- Если период последний и закрытый - то конечная дата - MAX.
					if EndDate <  to_date('01.01.3000', 'dd.MM.yyyy') then
									-- VVV 13.12.2012 Ранее последний период определялся по max(ID), что не всегда так!!!
									-- VVV 02.10.2013 Еще уточнение - если просто последний период с ЛЮБЫМ обязательством (они могли кончаться до последнего периода).
											Select MAX(mp.SINCEDATE) into dTmp  
											from SM.MOVEPERIODS mp 
											inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID = mp.ID -- >>>   02.10.2013 А вот так - НЕ НАДА! and pd.OBLIGATIONTYPE_ID = AObligType_ID
											where mp.MOVESET_ID = AMoveSet_ID; 
												if dTmp = BegDate then
                               	EndDate := to_date('01.01.3000', 'dd.MM.yyyy');
												-- VVV 21.10.2013 -- Если обязательство вида AObligType_ID отсутствует в последнем периоде, 
												--           И последний период закрыт 
												--           И есть	начисления по данному обязательству ПОСЛЕ даты закрытия ОД  (например доп.)
												--  ТО без этой проверки платежи	после даты последнего начисления не распределялись => игнорировались	
											 else  		
															Select MAX(mp.SINCEDATE) into dTmp  
															from SM.MOVEPERIODS mp 
															inner join SM.PAYDOCS pd on pd.MOVEPERIOD_ID = mp.ID  and pd.OBLIGATIONTYPE_ID = AObligType_ID -- <<<   А вот здесь  - как раз ТАК НАДА!
															where mp.MOVESET_ID = AMoveSet_ID; 
															if dTmp <= BegDate then                                                                 -- <<< 17.12.2013 --  Добавлено условие меньше (иначе при входе в периоде УЖЕ не содержащем данное обязательство - равенство не сработает)
                                  	EndDate := to_date('01.01.3000', 'dd.MM.yyyy');
                              end if;
											 end if;
					end if;
else
          RETURN;
end if;

-- Подчищаем ранее сделанные распределения - для "не-рассрочки" (для рассрочки все чо нада уже сделано
Select count(*) into IsCredit from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID =  AMoveSet_ID and ppd.OBLIGATIONTYPE_ID = AObligType_ID;

if (IsCredit = 0         and IsCalcFineNeed    )   then
	     Select ob.RECALC_START_DATE into  ARecalc_Start_Date
             from SM.OBLIGATIONS ob
						 inner join SM.MOVEPERIODS mp on mp.ID = AMoveperiod_ID and mp.MOVESET_ID  = ob.MOVESET_ID
						 where OB.OBLIGATIONTYPE_ID = AObligType_ID;

       Delete from SM.CHARGES where MOVESETS_ID = AMoveSet_ID  and OBLIGATIONTYPE_ID = AObligType_ID
              and DOCUMENT_ID is null  -- <<< Ни в коем случае не трогаем ручные начисления!
              and CHARGEDATE  >=  begdate
              and CHARGE_TYPE = 'FINE'
              -- VVV -- Чистим только пени и только начисленные при разноске платежа.
							-- VVV -- Или - все начисленные пени - если данный период на условиях "пеня на день оплаты..."
							and ( NowOnDate='N' and (COMMENTS like '%(на день платежа)%') OR (NowOnDate='Y')	)
             -- VVV и только для "своего" (того же) периода
             and PAYDOC_ID = (Select ID from SM.PAYDOCS PD where PD.MOVEPERIOD_ID = AMoveperiod_ID and PD.OBLIGATIONTYPE_ID = AObligType_ID)
             AND CHARGEDATE > ARecalc_Start_Date;  ---<<< 14.12.2012 -- Не удаляем начислений до даты начала пересчета.


       Delete  from SM.PAYMENTS_DISTRIBUTION  where PAYMENTS_ID in
              (
                    Select pm.ID  from SM.PAYMENTS pm
                     where pm.MOVESETS_ID =  AMoveSet_ID and pm.OBLIGATIONTYPE_ID = AObligType_ID
                     and  sm.getpaydateforpayment(pm.ID) between BegDate and EndDate
              );
end if;

   -- Основной цикл распределения платежкей...
    PAYMENTS_PROCEED(AMoveset_ID, AObligtype_ID, to_date('01.01.1900', 'dd.MM.yyyy'), EndDate);  -- <<< 13.03.2012 <<< Унифицировано с другим вариантом аналогичной функции выше.
		-- ^^^ 19.03.2012 ^^^ - Начальная дата - с амого начала, чтобы не оставались недоразнесенные платежи с прошлых периодов (либо вообще - до заключения сделки)
end;

END;  -- END of PAYMENTS_DISTRIBUTE_PKG
/
grant execute on SM.PAYMENTS_DISTRIBUTE_PKG to SM_ALLUSERS;
grant execute on SM.PAYMENTS_DISTRIBUTE_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body PK_UTILS
prompt ==============================
prompt
CREATE OR REPLACE PACKAGE BODY SM."PK_UTILS"
IS

   FUNCTION is_role_enabled (role_name IN VARCHAR2)
      RETURN VARCHAR2
   is
       ret Varchar2(1);
   begin
       ret := 'N';
       if sys.dbms_session.is_role_enabled(role_name) then
           ret := 'Y';
       end if;
       return ret;
   exception
       when OTHERS then
           return ret;
   end;

-- (c) Gleb V. Levin 1998
   FUNCTION int2speech (dig IN NUMBER, sex IN VARCHAR2)
      RETURN VARCHAR2
   IS
      ret                           VARCHAR2(300);
      remainder                     NUMBER;
   BEGIN
      remainder := TRUNC (MOD (dig, 1000) / 100);
      SELECT DECODE (
                remainder,
                1, 'сто ',
                2, 'двести ',
                3, 'триста ',
                4, 'четыреста ',
                5, 'пятьсот ',
                6, 'шестьсот ',
                7, 'семьсот ',
                8, 'восемьсот ',
                9, 'девятьсот '
             )
        INTO ret
        FROM dual;
      remainder := TRUNC (MOD (dig, 100) / 10);
      SELECT ret ||
             DECODE (
                remainder,
                1, DECODE (
                      MOD (dig, 10),
                      0, 'десять ',
                      1, 'одиннадцать ',
                      2, 'двенадцать ',
                      3, 'тринадцать ',
                      4, 'четырнадцать ',
                      5, 'пятнадцать ',
                      6, 'шестнадцать ',
                      7, 'семнадцать ',
                      8, 'восемнадцать ',
                      9, 'девятнадцать '
                   ),
                2, 'двадцать ',
                3, 'тридцать ',
                4, 'сорок ',
                5, 'пятьдесят ',
                6, 'шестьдесят ',
                7, 'семьдесят ',
                8, 'восемьдесят ',
                9, 'девяносто '
             )
        INTO ret
        FROM dual;
      IF remainder = 1
      THEN
         RETURN ret;
      END IF;
      remainder := MOD (dig, 10);
      SELECT ret ||
             DECODE (
                remainder,
                1, DECODE (UPPER (sex), 'M', 'один ', 'F', 'одна '),
                2, DECODE (UPPER (sex), 'M', 'два ', 'F', 'две '),
                3, 'три ',
                4, 'четыре ',
                5, 'пять ',
                6, 'шесть ',
                7, 'семь ',
                8, 'восемь ',
                9, 'девять '
             )
        INTO ret
        FROM dual;
      RETURN ret;
   END;

   FUNCTION float2speech (value IN NUMBER, sex IN VARCHAR2, POWER IN
INTEGER)
      RETURN VARCHAR2
   IS
      ret                           VARCHAR2(300);
      p                             VARCHAR2(1);
      i                             INTEGER;
   BEGIN
      IF POWER = 0
      THEN
         ret := '';
         p := sex;
      ELSE
         IF POWER > 1
         THEN
            p := 'M';
         ELSE
            p := 'F';
         END IF;
         i := TRUNC (value);
         IF TRUNC (MOD (i, 100) / 10) = 1
         THEN
            i := 5;
         ELSE
            i := MOD (i, 10);
         END IF;
         IF i = 1
         THEN
            SELECT DECODE (p, 'M', ' ', 'F', 'а ') || ret
              INTO ret
              FROM dual;
         ELSIF  (  i >= 2)
               AND  (i <= 4)
         THEN
            SELECT DECODE (p, 'M', 'а ', 'F', 'и ') || ret
              INTO ret
              FROM dual;
         ELSE
            SELECT DECODE (p, 'M', 'ов ', 'F', ' ') || ret
              INTO ret
              FROM dual;
         END IF;
         SELECT DECODE (
                   POWER,
                   1, 'тысяч',
                   2, 'миллион',
                   3, 'миллиард',
                   4, 'триллион'
                ) ||
                ret
           INTO ret
           FROM dual;
      END IF;
      ret := int2speech (TRUNC (value) MOD 1000, p) || ret;
      IF value >= 1000
      THEN
         ret := float2speech (value / 1000, p, POWER + 1) || ret;
      END IF;
      RETURN ret;
   END;

   FUNCTION inttospeech (dig IN NUMBER, sex IN VARCHAR2)
      RETURN VARCHAR2
   IS
      ret                           VARCHAR2(300);
   BEGIN
      ret := float2speech (ABS (dig), sex, 0);
      IF ret IS NULL
      THEN
         RETURN 'ноль';
      ELSIF dig < 0
      THEN
         RETURN 'минус ' || ret;
      ELSE
         RETURN ret;
      END IF;
      RETURN ret;
   END;

   FUNCTION moneytospeechshort (quant IN NUMBER)
      RETURN VARCHAR2
   IS
      ret                           VARCHAR2(500);
      q                             NUMBER;
   BEGIN
      q := ROUND (quant, 2);
      ret :=
         inttospeech (q, 'm') ||
         ' руб. ' ||
         TO_CHAR (ABS (q - TRUNC (q)) * 100, '00') ||
         ' коп.';
      RETURN NLS_UPPER (SUBSTR (ret, 1, 1)) || SUBSTR (ret, 2);
   END;
END pk_utils;
/
grant execute on SM.PK_UTILS to SM_ALLUSERS;
grant execute on SM.PK_UTILS to SM_ALL_SELECT;


prompt
prompt Creating package body PLUGIN_AUTOPAYMENT_PKG
prompt ============================================
prompt
create or replace package body sm.plugin_autopayment_pkg is

  splitPat varchar2(7) := '|$#%*@|';

  function GetSplitter(args varchar2) return varchar2 is
    pos number;
  begin
    pos := instr(args, ' ');
    if pos = 0 then
      return null;
    end if;
    return substr(args, 1, pos - 1);
  end;

  -- Количество элементов в строке аргументе
  function GetCountArgs(args varchar2) return number is
    spl varchar2(30);
    s varchar2(32767);
    pos number;
    c number;
  begin
    spl := GetSplitter(args);
    if spl is null then
      s := substr(args, 2);
      if length(s) > 0 then
        return 1;
      end if;
      return 0;
    else
      c := 1;
      s := substr(args, length(spl) + 2);
      while length(s) > 0 loop
        pos := instr(s, spl);
        if pos > 0 then
          s := substr(s, pos + length(spl));
          if length(s) > 0 then
            c := c + 1;
          end if;
        else
          exit;
        end if;
      end loop;
    end if;
    return c;
  end;

  -- Получить значение конкретного элемента в строке аргументе
  function GetValueArgs(args varchar2, ind number) return varchar2 is
    c number;
    n number;
    pos number;
    spl varchar2(30);
    s varchar2(32767);
    sf varchar2(32767);
  begin
    c := GetCountArgs(args);
    if (ind > 0) and (ind <= c) then
      spl := GetSplitter(args);
      if spl is null then
        return substr(args, 2);
      else
        n := 0;
        s := substr(args, length(spl) + 2);
        sf := null;
        while length(s) > 0 loop
          n := n + 1;
          pos := instr(s, spl);
          if pos > 0 then
            sf := substr(s, 1, pos - 1);
            s := substr(s, pos + length(spl));
          else
            sf := s;
            exit;
          end if;
          if ind = n then
            return sf;
          end if;
        end loop;
        return sf;
      end if;
    end if;
    return null;
  end;

  -- Создать строку заготовку для результатов
  function GetNewResult return varchar2 is
  begin
    return splitPat || ' ';
  end;

  -- Добавить к строке результату дополнительный элемент
  function AddValue(result varchar2, val varchar2) return varchar2 is
  begin
    return result || val || splitPat;
  end;

  function GetMainPay(args varchar2) return varchar2 is
    c number;
    s varchar2(3000);
    r varchar2(3000);
  begin
    r := GetNewResult;

    c := GetCountArgs(args);
    for i in 1..c loop
      s := lower(GetValueArgs(args, i));
      if (s = 'пе') or (s = 'пц') then
        r := AddValue(r, 'N');
        exit;
      end if;

      if (instr(s, 'пеня') > 0) or (instr(s, 'пени') > 0) or
        (instr(s, 'пене') > 0) or (instr(s, 'пеню') > 0) then
        r := AddValue(r, 'N');
        exit;
      end if;

    end loop;
    r := AddValue(r, 'Y');
    return r;
  end;

  -- Для МУГИ Волгоградской области (clients.id = 3220) =>
  -- функция определения вида платежа на основании КБК
  function GetMainPayKBK(args varchar2) return varchar2 is
    c number;
    s varchar2(3000);
    r varchar2(3000);
  begin
    r := GetNewResult;
    s := lower(GetValueArgs(args, 1));
    if s in ('81811690020020000140', '81811690040040000140') then
      --пени
      r := AddValue(r, 'N');
    elsif trim(s) in ('81811406022020000430', '81811105012040000120', '81811105022000000120') then
      r := AddValue(r, 'Y');
    elsif trim(s) in ('81811406012040000430') then
      r := AddValue(r, 'N');
      r := AddValue(r, 'Y');
    else
      r := AddValue(r, 'N');
      r := AddValue(r, 'Y');
    end if;
    return r;
  end;
  -- <= Для МУГИ Волгоградской области (clients.id = 3220)

  function GetDocType(args varchar2) return varchar2 is
  begin
    return ' ' || sm.GetParameter('AUTOPAYMENT_DOCTYPE');
  end;

  function GetNowDate(args varchar2) return varchar2 is
  begin
    return ' ' || sysdate;
  end;

  function GetNDoc(args varchar2) return varchar2 is
    r varchar2(3000);
  begin
    r := GetNewResult;
    r := AddValue(r, 'Y');
    r := r;
    return r;
  end;

  function GetDescriptionObj(idObj number, type number) return varchar2 is
    descr varchar2(500);
  begin
    descr := '';
    if type = 3 then
      begin
        select c.name into descr from sm.clients c where c.id = idObj and rownum = 1;
      exception
        when OTHERS then
          descr := 'Error';
      end;
    end if;
    if type = 9 then
      descr := sm.GetMoveSetMainDocDescription(idObj);
    end if;
    return descr;
  end;

  function GetDescription(oldVal varchar2, fieldName varchar2) return varchar2 is
    descr varchar2(500);
  begin
    descr := oldVal;
    if upper(fieldName) = 'MAINPAY' then
      if oldVal = 'Y' then
        descr := 'Основной';
      else
        descr := 'Пеня';
      end if;
    end if;
    if upper(fieldName) = 'OBLIGATIONTYPE_ID' then
      begin
        select name into descr from sm.obligationtype where id = oldVal;
      exception
        when OTHERS then
          descr := oldVal;
      end;
    end if;
    if upper(fieldName) = 'PAYMETHOD_ID' then
      begin
        select name into descr from sm.paymethods where id = oldVal;
      exception
        when OTHERS then
          descr := oldVal;
      end;
    end if;

    return descr;
  end;
  
  function GetGmpMainPay(args varchar2) return varchar2 is
    r varchar2(3000);
    s varchar2(3000);
  begin
    r := GetNewResult;
    s := upper(GetValueArgs(args, 1));
    if s = 'OBLIGATION' or s = 'OTHER' then
      r := AddValue(r, 'Y');
    elsif s = 'FINE' then
      r := AddValue(r, 'N');
    elsif s = 'PERCENT' then
      r := AddValue(r, 'P');
    else
      r := AddValue(r, 'Y');
    end if;
    return r;
   end;
      
  function GetGmpChargeInfoId(args varchar2) return varchar2 is
    r varchar2(3000);
    supplier_id varchar2(50);
    chargeId sm.gmp_charge.gmp_chargeidinfo_id%type;
    cnt integer := 0;
  begin
    r := GetNewResult;
    supplier_id := GetValueArgs(args, 1);
    select count(*) into cnt from sm.gmp_charge t join sm.gmp_bill t1 on t.id = t1.id where t1.supplierbillid = supplier_id and rownum = 1;
    if cnt = 1 then
      select /*+ FIRST_ROWS(1) */ t.gmp_chargeidinfo_id into chargeId from sm.gmp_charge t join sm.gmp_bill t1 on t.id = t1.id where t1.supplierbillid = supplier_id and rownum = 1;
      r := AddValue(r, TO_CHAR(chargeId));
    end if;
    return r;
  end;

  -- Преобразует дату найденую в комментарии к платежу в правильный вид
  function GetCorrectDate(args varchar2) return varchar2 is
    c number;
    s varchar2(3000);
    r varchar2(3000);
    sys_year number;
  begin
    r := GetNewResult;

    c := GetCountArgs(args);
    for i in 1..c loop

      s := lower(GetValueArgs(args, i));

      -- название месяца в цисло
      s := replace(s, 'января', '01');
      s := replace(s, 'февраля', '02');
      s := replace(s,'марта', '03');
      s := replace(s, 'апреля', '04');
      s := replace(s, 'мая', '05');
      s := replace(s, 'июня', '06');
      s := replace(s, 'июля', '07');
      s := replace(s, 'августа', '08');
      s := replace(s, 'сентября', '09');
      s := replace(s, 'октября', '10');
      s := replace(s, 'ноября', '11');
      s := replace(s, 'декабря',' 12');

      -- избавляемся от обозначения года
      s := replace(s, 'г.', '');
      s := replace(s, 'г', '');
      s := replace(s, 'r.', '');
      s := replace(s, 'r', '');

      -- преобразуем все разделители года к точке
      s := replace(s, '-', '.');
      s := replace(s, ',', '.');
      s := replace(s, '/', '.');
      s := replace(s, '\', '.');
      s := replace(s, ' ', '.'); -- правильнее удалять все пробелы

      -- удаление повторных точек
      while instr(s, '..') > 0 loop
        s := replace(s, '..', '.');
      end loop;

      s := replace(s, 'о', '0'); -- русская буква о
      s := replace(s, 'o', '0'); -- английская буква о
      s := replace(s, 'u', '0');

      s := replace(s, 'б', '6');
      s := replace(s, 'з', '3');

      -- если год обозначен как 00 преобразовать к 2000 году
      if substr(s, instr(s, '.', 1, 2) + 1) = '00' then
        s := substr(s, 1, instr(s, '.', 1, 2)) || '2000';
      end if;

      -- если год задан двумя цифрами, то приводим к четырем. 
      -- При этом предполагаем, что платеж не может быть на будущую дату 
      select substr(to_char(sysdate, 'DD.MM.YYYY'), instr(to_char(sysdate, 'DD.MM.YYYY'), '.', 1, 2) + 3)
      into sys_year
      from dual;
      if length(substr(s,instr(s, '.', 1, 2) + 1)) = 2 then
        if to_number(substr(s, instr(s, '.', 1, 2) + 1)) > sys_year then
          s := substr(s, 1, instr(s, '.', 1, 2)) || '19' || substr(s, instr(s, '.', 1, 2) + 1);
        else
          s := substr(s, 1, instr(s, '.', 1, 2)) || '20' || substr(s, instr(s, '.', 1, 2) + 1);
        end if;
      end if;

      r := AddValue(r, s);

    end loop;
    return r;
  end;

  -- возвращает список полей и их порядок которые будут переданы
  -- для преобработки в функцию precheck_pre_check_payment
  function precheck_get_check_fields(args varchar2) return varchar2 is
    r varchar2(3000);
  begin
    r := GetNewResult;
    r := AddValue(r, '');
    return r;
  end;

  -- получает значения свойств платежа и возвращает название группы или
  -- список групп в которые попадает данный платеж
  function precheck_pre_check_payment(args varchar2) return varchar2 is
    r varchar2(3000);
  begin
    r := GetNewResult;
    r := AddValue(r, '1');
    return r;
  end;

  -- возвращает название группы, платежи из которой будут
  -- переданы на обработку в программу автоматической разноски платежей
  function precheck_get_result_payments(args varchar2) return varchar2 is
    r varchar2(3000);
  begin
    r := GetNewResult;
    r := AddValue(r, '1');
    return r;
  end;

  function ExtractPayerFullNameFromValue(args varchar2) return varchar2 is
    countArgs number;
    fullPayerName varchar2(300);
  begin
    fullPayerName := '';
    countArgs := GetCountArgs(args);
    if countArgs >= 2 then
      fullPayerName := GetValueArgs(args, 2);
      return fullPayerName;
    end if;
    return fullPayerName;
  end;

  function CheckIsInnOnPayerBank(bankInns varchar2, clientInn varchar2) return boolean is
    pos number;
    inns varchar2(3000);
    countInns number;
    currentInn varchar2(30);
  begin
    inns := '; ' || bankInns;
    countInns := GetCountArgs(inns);
    for i in 1..countInns loop
      currentInn := GetValueArgs(inns, i);
      if currentInn = clientInn then
        return true;
      end if;
    end loop;
    return false;
  end;

  function ExtractPayerFromSADPayment(args varchar2) return varchar2 is
    countArgs number;
    inn varchar2(30);
    fullPayerName varchar2(3000);
    r varchar2(3000);
    countItems number;
    realFullName varchar2(300);
    payerBanksInns varchar2(3000);
    splitterSymbol varchar2(10);
  begin
    r := GetNewResult;
    -- Получаем количество аргументов
    countArgs := GetCountArgs(args);
    -- Их должно быть ровно 4
    if countArgs = 4 then
      begin
        -- Выделяем символ разделения (идет параметром №1)
        splitterSymbol := GetValueArgs(args, 1);
        -- Выделяем набор ИНН банков-заместителей (параметр №2)
        payerBanksInns := GetValueArgs(args, 2);
        -- ИНН текущего платежа (параметр №3)
        inn := GetValueArgs(args, 3);
        -- Полное наименование платильщика(параметр №4)
        fullPayerName := GetValueArgs(args, 4);
        -- Проверяем, находится ли ИНН текущего платежа в списке банков заместителей
        if CheckIsInnOnPayerBank(payerBanksInns, inn) then
          -- Если да, то выделяем имя реального плательщика
          -- Берем символ разделения (параметр №1) и мы знаем, что в данном случае реальное имя идет от начала строки и до первого символа разделения
          fullPayerName := splitterSymbol || ' ' || fullPayerName;
          countItems := GetCountArgs(fullPayerName);
          if countItems >= 1 then
            -- Имя реального плательщика
            realFullName := GetValueArgs(fullPayerName, 1);
            -- Формируем результат
            r := AddValue(r, realFullName);
          end if;
        end if;
      end;
    end if;
    return r;
  end;

  function SplitByWords(args varchar2) return varchar2 is
     i number := 1;
     part varchar2(50);
     res varchar2(3000);
     str varchar2(3000);
   begin
     res := GetNewResult();
     str := GetValueArgs(args, 1);
     loop
       part := regexp_substr(str, '\w{4,}', 1, i);
       exit when part is null;
       res := AddValue(res, part);
       i := i + 1;
     end loop;
     return res;
   end;

end plugin_autopayment_pkg;
/
