         r := AddValue(r,'N');
      elsif trim(s) in ('81811406022020000430','81811105012040000120','81811105022000000120') then
          r := AddValue(r,'Y');
      elsif trim(s) in ('81811406012040000430') then
         r := AddValue(r,'N');
         r := AddValue(r,'Y');
      else
         r := AddValue(r,'N');
         r := AddValue(r,'Y');
      end if;

     /* c := GetCountArgs(args);
      for i in 1..c loop
          s := lower(GetValueArgs(args,i));
          if (s = 'пе') or (s = 'пц') then
              r := AddValue(r,'N');
              exit;
          end if;

          if (instr(s,'пеня')>0) or (instr(s,'пени')>0) or
              (instr(s,'пене')>0) or (instr(s,'пеню')>0) then
              r := AddValue(r,'N');
              exit;
          end if;

      end loop;*/
      --r := AddValue(r,'Y');
      return r;
  end;

  function GetDocType(args varchar2) return varchar2 is
    res varchar2(10);
  begin
      select sm.getparameter('AUTOPAYMENT_DOCTYPE') into res from dual;
      return res;
  end;

    function GetNDoc(args varchar2) return varchar2 is
      r varchar2(3000);
  begin
     r :=GetNewResult;
     r:=AddValue(r,'Y');
     r:=r;
     return r;
  end;

  function GetNowDate(args varchar2) return varchar2 is
  d date;
  begin
      select sysdate into d from dual;
      return ' '||d;
  end;

  function GetDescriptionObj(idObj number, type number) return varchar2 is
    descr varchar2(500);
  begin
    descr := '';
    if type = 3 then
        begin
            select c.name into descr from sm.clients c where c.id=idObj and rownum=1;
        exception
           when OTHERS then
               descr:='Error';
        end;
    end if;
    if type = 9 then
        descr := sm.GetMoveSetMainDocDescription(idObj);
    end if;
    return(descr);
  end;

  function GetDescription(oldVal varchar2, fieldName varchar2) return varchar2 is
    descr varchar2(500);
  begin
    descr:=oldVal;
    if upper(fieldName) = 'MAINPAY' then
        if oldVal = 'Y' then
            descr := 'Основной';
        else
            descr := 'Пеня';
        end if;
    end if;
    if upper(fieldName) = 'OBLIGATIONTYPE_ID' then
        begin
            select name into descr from sm.obligationtype where id=oldVal;
        exception
            when OTHERS then
                descr := oldVal;
        end;
    end if;
    if upper(fieldName) = 'PAYMETHOD_ID' then
        begin
            select name into descr from sm.paymethods where id=oldVal;
        exception
            when OTHERS then
                descr := oldVal;
        end;
    end if;

    return descr;
  end;

  -- Преобразует дату найденую в комментарии к платежу в правильный вид
  function GetCorrectDate(args varchar2) return varchar2 is
  c number;
  s varchar2(3000);
  r varchar2(3000);
  sys_year number;
  begin
      r :=GetNewResult;

      c := GetCountArgs(args);
      for i in 1..c loop

          s := lower(GetValueArgs(args,i));

          -- название месяца в цисло
          s := replace(s,'января','01');
          s := replace(s,'февраля','02');
          s := replace(s,'марта','03');
          s := replace(s,'апреля','04');
          s := replace(s,'мая','05');
          s := replace(s,'июня','06');
          s := replace(s,'июля','07');
          s := replace(s,'августа','08');
          s := replace(s,'сентября','09');
          s := replace(s,'октября','10');
          s := replace(s,'ноября','11');
          s := replace(s,'декабря','12');

          -- избавляемся от обозначения года
          s := replace(s,'г.','');
          s := replace(s,'г','');
          s := replace(s,'r.','');
          s := replace(s,'r','');

          -- преобразуем все разделители года к точке
          s := replace(s,'-','.');
          s := replace(s,',','.');
          s := replace(s,'/','.');
          s := replace(s,'\','.');
          s := replace(s,' ','.'); -- правильнее удалять все пробелы

          -- удаление повторных точек
          s := replace(s,'..','.'); -- правильнее повторять такую операцию до победного

          s := replace(s,'о','0'); -- русская буква о
          s := replace(s,'o','0'); -- английская буква о
          s := replace(s,'u','0');

          s := replace(s,'б','6');
          s := replace(s,'з','3');

          -- если год обозначен как 00 преобразовать к 2000 году
          if substr(s,instr(s,'.',1,2)+1) = '00' then
              s := substr(s,1,instr(s,'.',1,2))||'2000';
          end if;
          
          -- если год задан двумя цифрами, то приводим к четырем. 
          -- При этом предполагаем, что платеж не может быть на будущую дату 
          select substr(to_char(sysdate,'DD.MM.YYYY'),instr(to_char(sysdate,'DD.MM.YYYY'),'.',1,2)+3) 
          into sys_year 
          from dual;
          if length(substr(s,instr(s,'.',1,2)+1))=2 then
            if to_number(substr(s,instr(s,'.',1,2)+1))>sys_year then
               s:=substr(s,1,instr(s,'.',1,2))||'19'|| substr(s,instr(s,'.',1,2)+1);
            else 
               s:=substr(s,1,instr(s,'.',1,2))||'20'|| substr(s,instr(s,'.',1,2)+1);   
            end if;
          end if;
          

          r := AddValue(r,s);

      end loop;
      return r;
  end;

end plugin_autopayment_pkg_484a;
/
grant execute on SM.PLUGIN_AUTOPAYMENT_PKG_484A to SM_ALL_SELECT;


prompt
