----------------------------------------------------------------------
FUNCTION GetObjKadastrNo(ObjID NUMBER) return varchar2 is
--
-- функция возвращает кадастровый номер объекта недвижимости ObjID
--
  recv VARCHAR2(4000);
begin
  select
      (case
      when o.OBJTYPES_ID=7 then (select g.KADASTRNO from sm.GROUNDS g where g.objects_id=o.ID)
      when o.OBJTYPES_ID=5 then (select e.KADASTRNO from sm.ENGINF e where e.objects_id=o.ID)
      when o.OBJTYPES_ID=4 then (select u.KADASTRNO from sm.UNCONSTR u where u.objects_id=o.ID)
      when o.OBJTYPES_ID=3 then (select b.KADASTRNO from sm.BUILDINGS b where b.objects_id=o.ID)
       else '' end)
  into
       recv
  from
       sm.objects o
  where
        o.ID=ObjID;

  return(trim(recv));

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN '';

end GetObjKadastrNo;

----------------------------------------------------------------------
FUNCTION GetObjSharesDescr(ObjID NUMBER) return varchar2 is
--
-- функция возвращает описание пакета акций(долей) ObjID на дату QueryDate
--
 rObjshares sm.objshares%rowtype;
 S1 sm.sharecategory.name%type;
 S2 sm.sharetypes.Name%type;
 S3 sm.organisations.name%type;
 SmallInfo varchar2(1000);
 sGUID varchar2(40);
 bCapital char(1);
 typeInfo varchar2(100);
 addtypeInfo varchar2(100);
begin
  select * into rObjshares from sm.objshares osh where osh.objects_id=ObjID;

  -- эмитент name с ОПФ
  select cl.name, f.hasauthcapital
     into S3, bCapital 
  from 
     sm.ORGANISATIONS org, sm.CLIENTS cl, sm.orgforms f 
  where   
     cl.ID=org.CLIENTS_ID and f.id=org.orgform and org.ID=rObjshares.ORGANISATIONS_ID;  

  -- вид участия
  select sht.name, sht.guid into S2, sGUID from sm.SHARETYPES sht where sht.id=rObjshares.SHARETYPES_ID;
  
  -- имеем дело с долями
  if (sGUID = '19BD2FD84F5E4B7D85575A1388CC0A24')
  then
    if (bCapital = 'Y') then  
       typeInfo := ' в уставном (складочном) капитале ';
    else
       typeInfo := ' в ';
    end if;    
     
    SmallInfo:= RTRIM(S2 || typeInfo ||S3);
     
   -- имеем дело с акциями
  else    
     S1 := '';
     if (rObjshares.SHARECATEGORY_ID is not null) then     
       -- категория акций
       select shc.name into S1 from sm.SHARECATEGORY shc where shc.id=rObjshares.SHARECATEGORY_ID;
     end if;
     
     -- информация о выпуске акций
     if (rObjshares.OPERSHARES_ID is not null) then   
         select
               RTRIM(opertype.code) 
               ||' ' ||to_char(opershares.operdate,'DD.MM.YYYY')
               || (case when opershares.code is not null then ' рег. №' || RTRIM(opershares.code) else '' end)
          into addtypeInfo
         from
          sm.opershares,
          sm.opertype
         where
          opertype.id=opershares.opertype_id and
          opershares.id=rObjshares.opershares_id;
     end if;

     SmallInfo := RTRIM(S2||' '||S1||' - '||S3 ||(case when addtypeInfo is not null then ' ('||rtrim(addtypeInfo)||')' else '' end));
 end if;
 
 return(trim(SmallInfo));
  
end GetObjSharesDescr;

----------------------------------------------------------------------
FUNCTION GetObjSharesInfo(ObjID NUMBER, QueryDate DATE) return varchar2 is
--
-- функция возвращает доп. информацию о пакете акций(долей) ObjID на дату QueryDate
--
  recv VARCHAR2(4000);
  qDate DATE;
begin
  qDate := trunc(QueryDate);
  select
      (case
       when sht.guid='6B1E81B10EAD422697278563AD148DB7'
            then ' ОГРН ' ||nvl(rtrim(org.ogrn),' - НЕ УКАЗАН ') ||', выпущено акций ' || SM.OrgState_And_Share_PKG.GetOrgStateValue(s.organisations_id, qDate, 'N')
            ||' шт., в т.ч. привилегированных ' ||nvl(SM.OrgState_And_Share_PKG.GetOrgStateValue(s.organisations_id, qDate, 'S'),0) ||' шт.'
       when sht.guid='19BD2FD84F5E4B7D85575A1388CC0A24' and f.hasauthcapital = 'Y'
            then ' ОГРН ' ||nvl(rtrim(org.ogrn),' - НЕ УКАЗАН ') ||', уставный (складочный) капитал ' ||SM.OrgState_And_Share_PKG.GetOrgStateValue(s.organisations_id, qDate, 'C') ||' руб.'
       when sht.guid='19BD2FD84F5E4B7D85575A1388CC0A24' and f.hasauthorizedfund = 'Y'
            then ' ОГРН ' ||nvl(rtrim(org.ogrn),' - НЕ УКАЗАН ') ||', уставный фонд ' ||SM.OrgState_And_Share_PKG.GetOrgStateValue(s.organisations_id, qDate, 'C') ||' руб.'
       when sht.guid='19BD2FD84F5E4B7D85575A1388CC0A24' and f.is_publicoffice = 'Y'
            then ' ОГРН ' ||nvl(rtrim(org.ogrn),' - НЕ УКАЗАН ') 
       else '' end)
  into
       recv
  from sm.Objshares s, sm.sharetypes sht, sm.organisations org, sm.orgforms f
  where s.objects_id=ObjID and sht.id=s.sharetypes_id and org.id=s.organisations_id and f.id=org.orgform;

  return(trim(recv));

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN '';

end GetObjSharesInfo;

----------------------------------------------------------------------
FUNCTION GetObjPropertyInfo(ObjID NUMBER, QueryDate DATE) return varchar2 is
--
-- функция возвращает доп. информацию об объекте ObjID на дату QueryDate
--
  recv VARCHAR2(4000);
  qDate DATE;
begin
  qDate := trunc(QueryDate);
  select
      (case
      when o.OBJTYPES_ID=1 then (select
                                                    (case when p.propgroups_id is not null then (Select pg.name from sm.propgroups pg where pg.id=p.propgroups_id) else '' end) ||
                                                    (case when p.propsections_id is not null then ' / ' || (Select ps.name from sm.propsections ps where ps.id=p.propsections_id) else '' end)
                                                   from sm.PROPERTY p where p.objects_id=o.ID)
      when o.OBJTYPES_ID=2 then (select
                                                    (case when t.fedno is not null then '  Гос.номер: ' || rtrim(t.fedno) else '' end) ||
                                                    (case when t.motorno is not null then '  № двигателя: ' || rtrim(t.motorno) else '' end) ||
                                                    (case when t.chassisno is not null then '  № шасси: ' || rtrim(t.chassisno) else '' end) ||
                                                    (case when t.bodyno is not null then '  № кузова: ' || rtrim(t.bodyno) else '' end) ||
                                                    (case when t.relyear is not null then ' Год выпуска: ' || t.Relyear else '' end) ||
                                                    (case when t.ps_color_id is not null then '  Цвет: ' || nvl((select max(cl.name) from sm.Colors cl where t.ps_color_id=cl.id and t.Objects_ID=o.ID), '-') else '' end)
                                                   from sm.TRANSPORT t where t.objects_id=o.ID)
      --when o.OBJTYPES_ID=3 then (select (case when b.Square is not null then 'Площадь ' || b.Square || ' кв.м; ' else '' end) from sm.BUILDINGS b where b.objects_id=o.ID)
      when o.OBJTYPES_ID=3 then (select 'Площадь ' || case when sum(case when ii.SQUARE=999999 then 0 else ii.SQUARE end)=0 then 'НЕТ СВЕДЕНИЙ' else to_char(sum(case when ii.SQUARE=999999 then 0 else ii.SQUARE end))|| ' кв.м' end 
                                                 from 
                                                    sm.MoveSets ss,sm.MovePeriods pp,sm.MoveItems ii 
                                                 where 
                                                     pp.moveset_id=ss.id and ii.MovePeriod_ID = pp.id and ii.object_id=o.ID and 
                                                     ss.movetype_id=1 and ss.client_id=sm.multiowning_pkg.GetCurrentOwnerID() and 
                                                     pp.id = 
                                                     (select max(p.id)
                                                      from 
                                                         sm.MoveSets s, sm.MovePeriods p, sm.Moveitems i 
                                                      where 
                                                         p.moveset_id=s.id and p.Moveset_id=pp.Moveset_id and i.moveperiod_id=p.id and i.object_id=ii.object_id and p.Sincedate<=qDate and nvl(p.EndDate,TO_DATE('01.01.3000','DD.MM.YYYY'))>=qDate)
                                                 )
      when o.OBJTYPES_ID=4 then (select
                                                    (case when u.Square is not null then 'Площадь застройки по проекту ' || u.Square || ' кв.м; ' else '' end) ||
                                                    (case when u.BuildingSquare is not null then 'Общая площадь помещений по проекту ' || u.BuildingSquare || ' кв.м; ' else '' end)
                                                   from sm.UNCONSTR u where u.objects_id=o.ID)
      when o.OBJTYPES_ID=5 then (select
                                                    (case when e.Length is not null then 'Длина ' || e.length || ' м; ' else '' end) ||
                                                    (case when e.Width is not null then 'Ширина ' || e.Width || ' м; ' else '' end) ||
                                                    (case when e.Square is not null then 'Площадь ' || e.Square || ' кв.м; ' else '' end)
                                                   from sm.ENGINF e where e.objects_id=o.ID)
      --when o.OBJTYPES_ID=7 then (select 'Площадь ' || g.SQUARE || ' кв.м' from sm.GROUNDS g where g.objects_id=o.ID)
      when o.OBJTYPES_ID=7 then (select 'Площадь ' || case when sum(nvl(ii.SQUARE,0))=0 then 'НЕТ СВЕДЕНИЙ' else to_char(sum(nvl(ii.SQUARE,0)))|| ' кв.м' end 
                                                 from 
                                                    sm.MoveSets ss,sm.MovePeriods pp,sm.MoveItems ii 
                                                 where 
                                                     pp.moveset_id=ss.id and ii.MovePeriod_ID = pp.id and ii.object_id=o.ID and 
                                                     ss.movetype_id=1 and ss.client_id=sm.multiowning_pkg.GetCurrentOwnerID() and 
                                                     pp.id = 
                                                     (select max(p.id)
                                                      from 
                                                         sm.MoveSets s, sm.MovePeriods p, sm.Moveitems i 
                                                      where 
                                                         p.moveset_id=s.id and p.Moveset_id=pp.Moveset_id and i.moveperiod_id=p.id and i.object_id=ii.object_id and p.Sincedate<=qDate and nvl(p.EndDate,TO_DATE('01.01.3000','DD.MM.YYYY'))>=qDate)
                                                 )
      when o.OBJTYPES_ID=21 then sm.Reestr_rpt_func_PKG.GetObjSharesInfo(ObjID, QueryDate)
       else '' end)
  into
       recv
  from
       sm.objects o
  where
        o.ID=ObjID;

  return(trim(recv));

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN '';

end GetObjPropertyInfo;

----------------------------------------------------------------------
FUNCTION GetObjLastMVID(ObjID NUMBER, MoveTypesID NUMBER, QueryDate DATE, ClientsToID NUMBER) return NUMBER is
--
-- Функция возвращает ID последней операции вида MoveTypesID субъекта ClientsToID с объектом ObjID на дату QueryDate
--
  recvID NUMBER(27);
  qDate DATE;
begin
  qDate := trunc(QueryDate);
       
  for x in (select s.id
       from
           sm.MoveItems i,
           sm.MovePeriods p,
           sm.MoveSets s
        where
           i.MovePeriod_ID = p.id and p.MoveSet_ID = s.ID and  
           i.Object_Id = ObjID and
           s.Client_id = ClientsToID and
           p.Sincedate <= qDate and
           s.Movetype_id = MoveTypesID
        order by
           p.Sincedate desc)
  loop  
      recvID := x.ID;
      exit;
  end loop;
  return(recvID);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end GetObjLastMVID;

----------------------------------------------------------------------
FUNCTION GetFirstKumiMoviedByDate(ObjID NUMBER,
                                                                                MoveTypesID NUMBER,
                                                                                QueryDate DATE,
                                                                                ClientsToID NUMBER,
                                                                                MSIDReturn char,
                                                                                isChild char) return NUMBER is
--
-- Функция возвращает ID объекта, на который оформлено движение вида MoveType_ID,
-- или ID последней ОД с этим объектом,
-- где субъект-текущий базовый собственник на дату CDate (даже если ОД закрыта).
-- Для зданий и помещений, для частей ЗУ будет найден объект верхнего уровня,
-- если на сам объект не оформлена ОД данного вида
--
  recv NUMBER:=null;
  qDate DATE;
  objTypeID NUMBER;
  baseBuildID NUMBER;
  baseGroundID NUMBER;
  baseObjID NUMBER;
  moveSetID NUMBER;  
  TYPE cv_type IS REF CURSOR;
  cv cv_type;
  xobjID number(27);
  xmsID number(27);
  strWhereEnd varchar2(4000) := '';
  childView char(1) := 'N';
begin
  qDate := trunc(QueryDate);
  
  --если рекурсивный проход для определения "движения" объекта верхнего уровня
  if (isChild = '1') then
    strWhereEnd := ' and (mv.EndDate>=''' || to_char(qDate) || ''' or mv.EndDate is null)';
  end if;
               
  open cv for 
            'select ' ||
               'mv.OBJECTS_ID, '||
               'mv.MoveSet_ID '||
             'from '||
               'sm.movements mv '||
             'where '||
               'mv.OBJECTS_ID=' || to_char(ObjID) || ' and '||
               'mv.MoveType_ID=' || to_char(MoveTypesID) || ' and '||
               'mv.CLIENTSTO_ID=' || to_char(ClientsToID) || ' and '||
                  'mv.POSTINGDATE<=''' || to_char(qDate) || ''''||
                  strWhereEnd|| 
            'order by '||
               'mv.POSTINGDATE desc';
    loop
      fetch cv  into xobjID, xmsID;
      exit when cv%notfound;
      if cv%rowcount > 0 then  
        If (MSIDReturn = 'Y') then
           moveSetID := xmsID;
        end if;
    
        recv:=xobjID;
    
        exit;
      end if;
    end loop;
             


 if recv is not null then
   If (MSIDReturn = 'Y') then
       recv := moveSetID;
    end if;
   return(recv);
 end if;

 -- цикл по структуре зданий или ЗУ
 if (childView = 'Y') then
     select ObjTypes_ID into objTypeID from sm.Objects where ID=ObjID;
    
     -- разбор случая, если это здание
     if objTypeID = 3 then
       select
         Basebuilding
       into
         baseBuildID
       from
         sm.Buildings
       where
         Objects_ID=ObjID;
    
       if (baseBuildID is not null) then
         select
           Objects_ID
         into
           baseObjID
         from
           sm.Buildings
         where
           ID=baseBuildID;
    
         Return (sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(baseObjID,MoveTypesID,QueryDate,ClientsToID,MSIDReturn,1));
       end if;
     -- разбор случая, если это части ЗУ
     elsif objTypeID = 7 then
       select
         baseground
       into
         baseGroundID
       from
         sm.Grounds
       where
         Objects_ID=ObjID;
    
       if (baseGroundID is not null) then
         select
           Objects_ID
         into
           baseObjID
         from
           sm.Grounds
         where
           ID=baseGroundID;
    
         Return (sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(baseObjID,MoveTypesID,QueryDate,ClientsToID,MSIDReturn,1));
       end if;
     end if;
 end if; -- if (childView = 'Y') 
 
 return(recv);

exception
 when NO_DATA_FOUND then return null;

end GetFirstKumiMoviedByDate;

----------------------------------------------------------------------
FUNCTION GetObjMVDateBeg(ObjID NUMBER,
                                                                     MoveTypes_ID NUMBER,
                                                                     QueryDate DATE,
                                                                     ClientsToID NUMBER) return date is
--
-- Функция возвращает Дату начала последней операции вида MoveTypesID
-- субъекта ClientsToID с объектом ObjID на дату QueryDate
--
  recvDate DATE;
  msID NUMBER(27);
begin
  --msID := sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(ObjID, MoveTypes_ID, QueryDate, ClientsToID, 'Y',0);
  msID := sm.Reestr_rpt_func_PKG.GetObjLastMVID(ObjID, MoveTypes_ID, QueryDate, ClientsToID);
  if (msID is not null) then
      select
        min(p.SinceDate) into recvDate
      from
        sm.MovePeriods p,sm.MoveItems i
      where
        p.Moveset_Id=msID and i.MovePeriod_ID = p.id and i.Object_Id = ObjID;
  end if;
  return(recvDate);

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN null;
end GetObjMVDateBeg;

----------------------------------------------------------------------
FUNCTION GetObjMVDateEnd(ObjID NUMBER,
                                                                     MoveTypes_ID NUMBER,
                                                                     QueryDate DATE,
                                                                     ClientsToID NUMBER) return date is
--
-- Функция возвращает Дату окончания последней операции вида MoveTypesID
-- субъекта ClientsToID с объектом ObjID на дату QueryDate
--
  recvDate DATE;
  msID NUMBER(27);
begin
  --msID := sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(ObjID, MoveTypes_ID, QueryDate, ClientsToID, 'Y',0);
  msID := sm.Reestr_rpt_func_PKG.GetObjLastMVID(ObjID, MoveTypes_ID, QueryDate, ClientsToID);
  if (msID is not null) then
      for x IN (select p.EndDate
                   from
                     sm.Moveperiods p,sm.MoveItems i
                   where
                      p.Moveset_Id=msID and i.MovePeriod_ID = p.id and i.Object_Id = ObjID
                   order by p.SinceDate desc)
      loop
        recvDate:=x.EndDate;
        exit;
      end loop;
  end if;
  return(recvDate);

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;
end GetObjMVDateEnd;

----------------------------------------------------------------------
FUNCTION GetObjMVBegDocInfo(ObjID NUMBER,
                                                                         MoveTypes_ID NUMBER,
                                                                         QueryDate DATE,
                                                                         ClientsToID NUMBER) return varchar2 is
--
-- Функция возвращает информацию об основном документе первого периода
-- последней операции вида MoveTypesID субъекта ClientsToID
-- с объектом ObjID на дату QueryDate
--
  recvDocInfo varchar2(2000);
  --docsetID number(27);
  msID NUMBER(27);
begin
  --msID := sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(ObjID, MoveTypes_ID, QueryDate, ClientsToID, 'Y',0);
  msID := sm.Reestr_rpt_func_PKG.GetObjLastMVID(ObjID, MoveTypes_ID, QueryDate, ClientsToID);
  if (msID is not null) then
      for x in (select p.Docset_id
                  from
                    sm.MovePeriods p,sm.MoveItems i
                  where
                    p.Moveset_Id=msID and i.MovePeriod_ID = p.id and i.Object_Id = ObjID
                  order by
                    p.SinceDate)
      loop
          select sm.ExpandDocNotPodp(dsm.Document_id)
            into recvDocInfo
          from
            sm.Docset_members dsm
          where
            dsm.Docrole_id=1 and
            dsm.Docset_id=x.Docset_id;
          exit;
      end loop;
  end if;
  return(trim(recvDocInfo));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;
end GetObjMVBegDocInfo;

----------------------------------------------------------------------
FUNCTION GetObjMVEndDocInfo(ObjID NUMBER,
                                                                         MoveTypes_ID NUMBER,
                                                                         QueryDate DATE,
                                                                         ClientsToID NUMBER) return varchar2 is
--
-- Функция возвращает информацию о документе последнего периода
-- последней операции вида MoveTypesID субъекта ClientsToID
-- с объектом ObjID на дату QueryDate
--
  recvDocInfo varchar2(2000);
  msID NUMBER(27);  
  i integer;
begin
  --msID := sm.Reestr_rpt_func_PKG.GetFirstKumiMoviedByDate(ObjID, MoveTypes_ID, QueryDate, ClientsToID, 'Y',0);
  msID := sm.Reestr_rpt_func_PKG.GetObjLastMVID(ObjID, MoveTypes_ID, QueryDate, ClientsToID);
  if (msID is not null) then
      for x IN (select p.docset_id, p.EndDate
           from
                 sm.Moveperiods p,sm.MoveItems i
           where
                 p.Moveset_Id=msID and i.MovePeriod_ID = p.id and i.Object_Id = ObjID
           order by
                 p.SinceDate desc)
      loop
        if (x.enddate is not null) then 
            --Основание прекращ.правоотнош
            select count(*) into i from sm.Docset_members dsm,sm.Docroles dr where dsm.Docrole_id=dr.id and dr.guid='8DC4C286EA674444AFEFC999E87B6EA3' and dsm.Docset_id=x.docset_id;
            if (i > 0) then
                select sm.ExpandDocNotPodp(dsm.Document_id)
                  into recvDocInfo
                from
                  sm.Docset_members dsm,
                  sm.Docroles dr
                where
                  dsm.Docrole_id=dr.id and
                  dr.guid='8DC4C286EA674444AFEFC999E87B6EA3' and
                  dsm.Docset_id=x.docset_id;
            --либо основной документ последнего периода
            else
                select sm.ExpandDocNotPodp(dsm.Document_id)
                  into recvDocInfo
                from
                  sm.Docset_members dsm
                where
                  dsm.Docrole_id=1 and 
                  dsm.Docset_id=x.docset_id;
            end if;  
        end if;  
        
        exit;
      end loop;
  end if;
  return(trim(recvDocInfo));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;
end GetObjMVEndDocInfo;

----------------------------------------------------------------------
FUNCTION GetObjRightHoldingInfo(ObjID NUMBER, QueryDate DATE) return varchar2 is
--
-- Функция возвращает информацию о субъекте-"правообладателе" объекта ObjID на дату QueryDate
--
  Result varchar2(4000);
  msInfo varchar2(2000);
  clientInfo varchar2(2000);
  qDate date;
  clientsID number(27);
begin
  Result:='';
  qDate := trunc(QueryDate);
  for x in (select
               ms.client_id,
               (case when ms.movetype_id=2 then tb.name else mt.name end) as TypeName,
               mp.sincedate
             from
               sm.Movesets ms,
               sm.Moveitems mi,
               sm.Moveperiods mp,
               sm.Movetype mt,
               sm.Transferbasis tb
             where
               ms.movetype_id in (Select t.ID from sm.movetype t where t.ObjRightHolding = 'Y') and ms.movetype_id <> 1 and
               mt.id=ms.movetype_id and
               tb.id=ms.transferbasis_id and
               mp.moveset_id = ms.id and mi.moveperiod_id = mp.id and mi.object_id = ObjID and
               mp.sincedate<= qDate and nvl(mp.EndDate, qDate) >= qDate
             order by mp.sincedate desc, ms.ID desc
              )
  loop
      if (x.client_id is not null) then
        clientsID := x.client_id;
        msInfo := rtrim(x.typename) || ' c ' || to_char(trunc(x.sincedate));
        exit;
      end if;
  end loop;

  if (clientsID is null) then
        clientsID := sm.multiowning_pkg.GetCurrentOwnerID();
  end if;

  select
          (case
                when c.client_types_id=3 then a.fullname
                when c.client_types_id=2 then o.fullname
                when c.client_types_id=1 then p.fullname || decode(p.businessman, 'Y', ' ИП', '')
           end)
        into clientInfo
        from
          sm.clients c, sm.organisations o, sm.ato a, sm.privates p
        where
          c.id=clientsID and
          o.clients_id(+)=c.id and
          a.clients_id(+)=c.id and
          p.clients_id(+)=c.id;

  Result :=  msInfo || ' - ' || Rtrim(clientInfo);

  return(Result);

EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN null;

end GetObjRightHoldingInfo;

----------------------------------------------------------------------
FUNCTION GetObjRightRestrictionInfo(ObjID NUMBER,
                                                                                QueryDate DATE,
                                                                                showInfo char) return varchar2 is
  Result varchar2(4000);
  i number;
  nDocEndRoleID number := 0;
  qDate date;
  endDate date;
  endInfo varchar2(200) := '';
--
-- Функция возвращает информацию об установленных обременениях
-- в отношении объекта муниципальной собственности
--
begin
  Result:='';
  qDate := trunc(QueryDate);

  Select count(*) into i from sm.Docroles dr where dr.guid='8DC4C286EA674444AFEFC999E87B6EA3';
  if (i > 0) then
    --Основание прекращ.правоотнош
    Select dr.id  into nDocEndRoleID from sm.Docroles dr where dr.guid='8DC4C286EA674444AFEFC999E87B6EA3';
  end if;

  i:=1;
  for x in (Select t.ID from sm.movetype t where t.ObjRightRestriction = 'Y')
  loop
      for xx in (select
               ms.id as msID,
               mp.ID as mpID,
               mp.docset_id,
               (case when ms.movetype_id=2 then tb.name else mt.name end) as TypeName,
               cl.Name as ClientName,
               mp.SinceDate
             from
               sm.Movesets ms,
               sm.Moveitems mi,
               sm.Moveperiods mp,
               sm.Movetype mt,
               sm.Clients cl,
               sm.Transferbasis tb
             where
               ms.movetype_id=x.ID and mt.id=ms.movetype_id and
               cl.id=ms.client_id and
               tb.id=ms.transferbasis_id and
               mp.moveset_id = ms.id and mi.moveperiod_id = mp.id and mi.object_id = ObjID and
               mp.sincedate<= qDate and nvl(mp.EndDate, qDate) >= qDate
             order by mp.sincedate)
      loop

         if (showInfo = 'N') then
               Result := 'С обременением';
               return(Result);
         end if;

         select pp.EndDate into endDate
           from sm.MovePeriods pp,sm.MoveItems ii
           where ii.MovePeriod_ID = pp.id and ii.Object_Id = ObjID and
               pp.Moveset_id=xx.msID and
               pp.Sincedate = (select max(p.Sincedate)  from sm.MovePeriods p,sm.Moveitems i where p.Moveset_id=pp.Moveset_id and i.moveperiod_id=p.id and i.object_id=ObjID);
         if (endDate is not null) then
            endInfo := ' по ' || to_char(trunc(endDate));
         end if;


         Result := Result||' '||i||'. '||RTRIM(xx.TypeName)||' с '||to_char(trunc(xx.SinceDate))||endInfo||' '||RTRIM(xx.ClientName)||chr(13);
         for xxx in (select
                      sm.ExpandDocNotPodp(dsm.Document_id) doc
                    from
                      sm.docset_members dsm
                    where
                      dsm.docset_id=xx.docset_id and dsm.docrole_id in (1,2,nDocEndRoleID)
                    order by dsm.docrole_id)
         loop
           Result:=Result||'   '||xxx.doc||';'||chr(13);
         end loop; --xxx
         i:=i+1;
         exit;

      end loop; --xx

  end loop; --x

  return(Result);
end GetObjRightRestrictionInfo;

----------------------------------------------------------------------
FUNCTION GetObjTreeRightRestrictionInfo(ObjID NUMBER,
                                                                                      QueryDate DATE,
                                                                                      showInfo char) return varchar2 is
  Result varchar2(4000);
  objectID number(27);
  objName varchar2(300);
  nObjTypeID number := 0;
  strSQL varchar2(4000) := '';
  strRightRestrictionInfo varchar2(4000) := '';
  TYPE cv_type IS REF CURSOR;
  cv cv_type;
--
-- Функция возвращает информацию об установленных обременениях
---в отношении объекта (ObjID) на заданную дату QueryDate,
-- в т.ч. в отношении частей структурного объекта (частей ЗУ либо встроенных помещений здания)
--
begin
  Result:='';

  Select t.objtypes_id into nObjTypeID from sm.Objects t where t.id=ObjID;
  if (nObjTypeID = 3) then
    --Здания и помещения
    strSQL := 'select ' ||
                   ' oTree.objectID, o.description ' ||
                  'from ' ||
                   '(select bld.objects_id as objectID ' ||
                              ' from sm.Buildings bld start with bld.objects_id =  ' || to_char(ObjID) || --( select CONNECT_BY_ROOT rootbld.objects_id as root' ||
                                                                                                            --' from sm.Buildings rootbld' ||
                                                                                                            --' where rootbld.objects_id = ' || to_char(ObjID) ||
                                                                                                            --' start with rootbld.basebuilding is null' ||
                                                                                                            --' connect by prior rootbld.id = rootbld.basebuilding)' ||
                                                                              ' connect by prior bld.id=bld.basebuilding) oTree' ||
                    ' inner join sm.objects o on o.ID=oTree.objectID';

  elsif (nObjTypeID = 7) then
    --Земельные участки
    strSQL := 'select ' ||
                   ' oTree.objectID, o.description ' ||
                  'from ' ||
                  '(select gr.objects_id as objectID' ||
                              ' from sm.Grounds gr start with gr.objects_id =  ' || to_char(ObjID) || --( select CONNECT_BY_ROOT rootgr.objects_id as root' ||
                                                                                                           -- ' from sm.Grounds rootgr' ||
                                                                                                           -- ' where rootgr.objects_id = ' || to_char(ObjID) ||
                                                                                                           -- ' start with rootgr.baseground is null' ||
                                                                                                           -- ' connect by prior rootgr.id = rootgr.baseground)' ||
                                                                              'connect by prior gr.id=gr.baseground) oTree' ||
                    ' inner join sm.objects o on o.ID=oTree.objectID';
  else
      strSQL := 'select o.ID as objectID, o.description as name from sm.objects o where o.id=' || to_char(ObjID);
  end if;

  open cv for strSQL;
  loop
    fetch cv into objectID, objName;
    exit when cv%notfound;
    if cv%rowcount > 0 then
      if objectID is not null  then
         strRightRestrictionInfo := sm.Reestr_rpt_func_PKG.GetObjRightRestrictionInfo(objectID, QueryDate, showInfo);
         if (length(strRightRestrictionInfo) >0) then

            if (showInfo = 'N') then
               Result := strRightRestrictionInfo;
               exit;
            end if;

            Result := Result ||objName ||':' ||chr(13) || strRightRestrictionInfo ||chr(13);
         end if;
      end if;
    end if;
  end loop;

  return(Result);
end GetObjTreeRightRestrictionInfo;

----------------------------------------------------------------------
FUNCTION GetOrgCreateDocInfo(OrgID NUMBER) return varchar2 is
--
-- Функция возвращает информацию об документе - основании создания ЮЛ
-- и основании участия МО в создании ЮЛ
--
  recvDocInfo varchar2(4000);
  tmpInfo varchar2(2000);
  nTmp number;
  nRoleID number;
  docsetID number(27);
begin
  --пакет документов ЮЛ
  for x in (select c.regdoc_id as docsets_id
       from
           sm.clients c,
           sm.organisations org
        where
           c.id=org.clients_id and
           org.id = OrgID)
  loop
    docsetID := x.docsets_id;
    exit;
  end loop;

  --основание создания ЮЛ
  if (docsetID is not null) then
    tmpInfo := sm.Extractdoc(docsetID,nTmp);
    if (tmpInfo is not null) then
      recvDocInfo := sm.Extractdoc(docsetID,1);
    end if;
  end if;

  --основание участия МО в создании ЮЛ
  Select count(*) into nRoleID from SM.DOCROLES where GUID='FABEB54A73AC4616AF6EF010B648484C';
  if (nRoleID > 0) then
    Select ID into nTmp from SM.DOCROLES where GUID='FABEB54A73AC4616AF6EF010B648484C';
    tmpInfo := sm.Extractdoc(docsetID,nRoleID);

    -- если не найдено в пакете документов ЮЛ, поищем в пакете документов ОД Собственность на долю участия
    if (tmpInfo is null) then
       select count(*) into nTmp 
          from
            sm.moveitems mi, sm.moveperiods mp, sm.movesets ms, sm.objshares osh 
          where
            mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and osh.objects_id = mi.object_id and 
            osh.organisations_id = OrgID and 
            ms.movetype_id = 1 and 
            mp.prev_moveperiod_id is null and 
            ms.client_id=sm.multiowning_pkg.GetCurrentOwnerID();
       if (nTmp = 1) then
          select ms.docset_id into docsetID 
          from
            sm.moveitems mi, sm.moveperiods mp, sm.movesets ms, sm.objshares osh 
          where
            mi.moveperiod_id = mp.id and mp.moveset_id = ms.id and osh.objects_id = mi.object_id and 
            osh.organisations_id = OrgID and 
            ms.movetype_id = 1 and 
            mp.prev_moveperiod_id is null and 
            ms.client_id=sm.multiowning_pkg.GetCurrentOwnerID();
          if (docsetID > 0) then
              tmpInfo := sm.Extractdoc(docsetID,nRoleID);
              if (tmpInfo is null) then
                tmpInfo := sm.Extractdoc(docsetID,1);
              end if;
          end if;
       end if;
    end if;
         
    --найдено основание участия
    if (tmpInfo is not null) then
      --найдено основание создания ЮЛ
      if (recvDocInfo is not null) then
        if (tmpInfo not like recvDocInfo) then
          --возвращаем оба основания
          recvDocInfo := '1. '||recvDocInfo||chr(13)||'2. '||tmpInfo;
        end if;
      else
          --возвращаем только основание участия
          recvDocInfo := tmpInfo;
      end if;
    end if;
  end if;

  return(trim(recvDocInfo));

EXCEPTION
 WHEN NO_DATA_FOUND THEN RETURN NULL;

end GetOrgCreateDocInfo;

----------------------------------------------------------------------
Function GetOrgGoldStockOwnerName(OrgID IN NUMBER, QueryDate IN DATE) return varchar2
--Возвращает наименование владельца золотой акции ЮЛ на заданную дату
--Параметры:
--  OrgID - ID организации
--  StateDate - дата
IS
  nClientID number(27);
  nameClients varchar2(200);
begin  
  nClientID := sm.OrgState_And_Share_PKG.GetOrgGoldStockOwnerID(OrgID, QueryDate);
  if (nClientID is not null) then 
     Select t.name into nameClients from sm.clients t where t.ID = nClientID;
  end if; 
  
  return nameClients;
end GetOrgGoldStockOwnerName;                                                                                      
                                                                                      
----------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------
end; -- пакета
/
grant execute on SM.REESTR_RPT_FUNC_PKG to SM_ALLUSERS;
grant execute on SM.REESTR_RPT_FUNC_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body SALDO_PKG_KR
prompt ==================================
prompt
create or replace package body sm.SALDO_PKG_KR is

function Acc_GetObligationSaldo(AMoveset_ID in NUMBER, 
                                AOblType_ID in NUMBER, 
                                AChargeType in varchar2, 
                                ADate date default sysdate) return number is
  Charged number(27,2);
  Payed number(27,2);

begin

-- функция рассчитывает сальдо по данному обязательству на момент ADate

    select nvl(sum("SUMM"),0) into Charged
    from sm.charge_applies c
    where
      moveset_id=AMoveset_ID and
      obligtype_id=AOblType_ID and
      apply_date<Trunc(ADate) and
      charge_type=AChargeType;

    select nvl(sum("SUM"),0) into Payed
    from sm.Payments
    where
      movesets_id=AMoveset_ID and
      payments.obligationtype_id=AOblType_ID and
      APPLY_DATE<Trunc(ADate) and
      Mainpay =decode(AChargeType,'O','Y','N');

  return(Payed-Charged);

end;

function Acc_GetObligationPays(AMoveset_ID in NUMBER, 
                               AOblType_ID in NUMBER, 
                               AChargeType in varchar2, 
                               AStartDate date, 
                               AEndDate Date) return number is

  Payed number(27,2);

begin
-- функция подсчитывает сумму платежей по данному обязательству
    select sum("SUM") into Payed
    from sm.Payments
    where
      movesets_id=AMoveSet_ID and
      obligationtype_id=AOblType_ID and
      APPLY_DATE>=Trunc(AStartDate) and
      APPLY_DATE<Trunc(AEndDate+1) and
      Mainpay =decode(AChargeType,'O','Y','N');

  return(Payed);

end;

function Acc_GetObligationPayCorrect(AMoveset_ID in NUMBER, 
                                     AOblType_ID in NUMBER, 
                                     AChargeType in varchar2, 
                                     AStartDate date, 
                                     AEndDate Date) return number is
  Payed number(27,2);
  PayMethod number :=3; -- списание долга

begin
  -- функция рассчитывает сумму уменьшения (платежи с Paymethod_id=3 - "Списание долга")
  -- по конкретному обязательству с AStartDate по AEndDate

    select sum("SUM") into Payed
    from sm.Payments
    where
      movesets_id=AMoveSet_ID and
      obligationtype_id=AOblType_ID and
      paymethod_id=PayMethod and
      APPLY_DATE>=Trunc(AStartDate) and
      APPLY_DATE<Trunc(AEndDate+1) and
      Mainpay =decode(AChargeType,'O','Y','N');

  return(nvl(Payed,0));

end;

function Acc_GetObligationCharges(AMoveset_ID in NUMBER, 
                                  AOblType_ID in NUMBER, 
                                  AChargeType in varchar2, 
                                  AStartDate date, 
                                  AEndDate Date) return number is
  Charged number(27,2);
begin
  -- функция рассчитывает начиления по данному обязательству
  -- за период с AStartDate по AEndDate

  select sum("SUMM") into Charged
  from sm.charge_applies
  where
    charge_type=AChargeType and
    moveset_id=AMoveset_ID and
    obligtype_id=AOblType_ID and
    apply_date>=Trunc(AStartDate) and
    apply_date <Trunc(AEndDate+1);

   return(nvl(Charged,0));

end;

begin
  null;
end SALDO_PKG_KR;
/
grant execute on SM.SALDO_PKG_KR to SM_ALLUSERS;
grant execute on SM.SALDO_PKG_KR to SM_ALL_SELECT;


prompt
prompt Creating package body SD3_UTILS
prompt ===============================
prompt
create or replace package body sm.sd3_utils is

  --
  -- Рабочая схема
  --
  o_name varchar2(2) := 'SM';

  --
  -- Название колонки с геометриями в таблицах для версий и координатных систем
  --
  c_name varchar2(8) := 'GEOMETRY';

  --
  -- Создать таблицу для определенной версии и координатной системы
  --
  procedure create_sd3_og_table(version_id number, srid number) as
    st_name varchar2(100);
    t_name varchar2(100);
  begin
    st_name := 'SD3_OG_'||version_id||'_'||srid;
    t_name := o_name||'.'||st_name;

    -- Create table
    execute immediate('create table '||t_name
      ||' ('
      ||'   ID                   NUMBER not null,'
      ||'   IS_GENERATED         CHAR(1) default ''Y'' not null,'
      ||'   '||c_name||'         MDSYS.SDO_GEOMETRY not null,'
      ||'   ORIGINAL_GEOMETRY_ID NUMBER not null'
      ||' )');

    -- Create/Recreate primary, unique and foreign key constraints
    execute immediate('alter table '||t_name
      ||'   add constraint '||st_name||'$PK primary key (ID)');

    execute immediate('alter table '||t_name
      ||'   add constraint '||st_name||'$FK foreign key (ORIGINAL_GEOMETRY_ID)'
      ||'   references SM.SD3_OG_ORIGINAL (ID) on delete cascade');

    -- Create/Recreate indexes
    execute immediate('create index '||t_name||'$OG_ID on '||t_name||' (ORIGINAL_GEOMETRY_ID)');

    -- Grant/Revoke object privileges
    execute immediate('grant select on '||t_name||' to SM_CANGIS');
    execute immediate('grant select, insert, update, delete on '||t_name||' to SM_CANGIS_WRITE');
  end;

  --
  -- Создать(Пересоздать) индекс для таблиц определенной версии и координатной системы
  -- Для закрепления результата требуется вызвать commit
  --
  procedure create_sd3_og_geo_index(version_id number, srid number) as
    t_name varchar2(100);
    c number;
  begin
    t_name := 'SD3_OG_'||version_id||'_'||srid;

    -- Найдем уже существующий индекс и убьем его
    for indx in (select aic.index_owner, aic.index_name
        from sys.all_indexes ai, sys.all_ind_columns aic
        where ai.ityp_owner='MDSYS' and ai.ityp_name='SPATIAL_INDEX'
            and ai.owner = aic.index_owner and ai.index_name=aic.index_name
            and aic.table_owner = o_name and aic.table_name=t_name and aic.column_name=c_name)
    loop
        execute immediate('DROP INDEX '||indx.index_owner||'.'||indx.index_name||' FORCE');
    end loop;

    -- Если нет, то создадим запись в таблице all_sdo_geom_metadata
    select count(*) into c from mdsys.all_sdo_geom_metadata t
      where t.OWNER=o_name and t.TABLE_NAME = t_name and t.COLUMN_NAME = c_name;

    /*23.10.2018 Твердохлеб, временно закомментировал код*/
   /* if c=0 then

      -- Для значений dim_info используем границы int32
      insert into MDSYS.SDO_GEOM_METADATA_TABLE (SDO_OWNER, SDO_TABLE_NAME, SDO_COLUMN_NAME, SDO_DIMINFO, SDO_SRID)
        values(o_name, t_name, c_name
          , MDSYS.SDO_DIM_ARRAY(
              MDSYS.SDO_DIM_ELEMENT('X', -2147483648, 2147483647, 0.05),
              MDSYS.SDO_DIM_ELEMENT('Y', -2147483648, 2147483647, 0.05)
            )
          , srid);

        insert into mdsys.all_sdo_geom_metadata_t (OWNER, TABLE_NAME, COLUMN_NAME, DIMINFO, SRID)
        values(o_name, t_name, c_name
          , MDSYS.SDO_DIM_ARRAY(
              MDSYS.SDO_DIM_ELEMENT('X', -2147483648, 2147483647, 0.05),
