    -- Создадим индекс
    execute immediate('create index '||o_name||'.'||t_name||'$SP_AUTO'
      ||' ON '||o_name||'.'||t_name
      ||' ('||c_name||') indextype is mdsys.spatial_index');
  end;

  --
  -- Проверить что строка состоит только из цифр
  --
  function is_only_number(v varchar2) return boolean as
    i number;
    vi varchar2(1);
  begin

    if v is null then
        return false;
    end if;

    if length(v)=0 then
        return false;
    end if;

    for i in 1 .. length(v) loop

      vi := substr(v,i,1);
      if (vi<>'0')
        and (vi<>'1')
        and (vi<>'2')
        and (vi<>'3')
        and (vi<>'4')
        and (vi<>'5')
        and (vi<>'6')
        and (vi<>'7')
        and (vi<>'8')
        and (vi<>'9') then
          return false;
      end if;

    end loop;

    return true;
  end;

  --
  -- Из навзания таблицы получить ид версии и srid
  -- Если название таблицы не соответствует шаблону то вернуть false
  --
  function parse_v_cs(table_name varchar2, version_v out number,srid_v out number) return boolean as
    l number;
    prefix_l number;
    sep_p number;
    v varchar2(100);
    srid varchar2(100);
  begin
    l := length(table_name);
    prefix_l := length('SD3_OG_')+1;
    sep_p := instr(table_name,'_',prefix_l,1);
    v:=substr(table_name,prefix_l,sep_p-prefix_l);
    srid:=substr(table_name,sep_p+1,l-sep_p);
    if sd3_utils.is_only_number(v) and sd3_utils.is_only_number(srid) then
        version_v:=to_number(v);
        srid_v:=to_number(srid);
        return true;
    end if;
    return false;
  exception
    when OTHERS then
      return false;
  end;

  --
  -- Удалить больше не используемые таблицы с координатными системами и версиями
  --
  procedure drop_not_used_sd3_og_tables as
    c1 number;
    c2 number;
    version_v number;
    srid_v number;
  begin
    -- Пройтись по всем таблицам соответствующим шаблону
    for t in (select * from sys.all_tables a
                where a.owner=o_name and a.table_name like 'SD3_OG_%_%') loop

      -- Извлечь из имени таблицы ид версии и srid
      if sd3_utils.parse_v_cs(t.table_name, version_v, srid_v) then

          -- Проверить есть ли версия и координатная система среди используемых
          select count(*) into c1 from sm.sd3_versions v where v.id=version_v;
          select count(*) into c2 from sm.sd3_used_coord_systems cs where cs.srid=srid_v;
          if (c1=0) or (c2=0) then

            -- Если нет то таблица удаляется
            execute immediate('drop table '||t.owner||'.'||t.table_name);

          end if;

      end if;

    end loop;
  end;

  procedure fill_sd3_og_table(version_id number, srid_value number) as
    current_rev_seq number;
    insert_table_name varchar2(40);
    self_cs varchar2(6);
    table_cs varchar2(6);
    transformed_geom mdsys.sdo_geometry;
    is_generated char(1);
    generated_id number;
    c_srid number;
    skip boolean;
  begin
    insert_table_name := o_name||'.SD3_OG_'||version_id||'_'||srid_value;
    c_srid := null;
    skip := true;

    -- получаем revision_seq и сохраняем его в таблицу sd3_geometry_revision_seq
    select current_value into current_rev_seq from sm.sd3_geometry_revision_seq for update;
    current_rev_seq:=current_rev_seq+1;

    select substr(t.wktext,0,6) into self_cs from mdsys.cs_srs t where t.srid=srid_value;

    -- Проходим по всем оригинальным геометриям отсортированным по srid и версии
    for og in (select * from sm.sd3_og_original order by geometry.sdo_srid, sd3_version_id) loop

      -- Если оригинальны срид не совпадает с обрабатываемым
      if (c_srid<>og.geometry.sdo_srid) or (c_srid is null) then

        -- Оригинальнй срид делаем обрабатываемым
        c_srid := og.geometry.sdo_srid;
        skip := true;

        -- И проверяем совместим ли новый обрабываемый срид со целевым сридом новой таблицы
        select substr(t.wktext,0,6) into table_cs from mdsys.cs_srs t where t.srid=og.geometry.sdo_srid;
        if (self_cs = table_cs) or (self_cs <>'LOCAL_' and table_cs<>'LOCAL_') then
            skip := false;
        end if;

      end if;

      -- Проверяем надо ли пропускать текущую строку с оригинальной геометрией
      -- Это может быть в том случаи когда оригинальная геометрия не может быть трансформирована
      -- в целевую координатную систему
      if not skip then

        -- Если необходимо преобразовываем координатные системы
        if c_srid = srid_value then
            transformed_geom := og.geometry;
        else

          begin
            transformed_geom := mdsys.sdo_cs.transform(og.geometry,srid_value);
          exception
            when OTHERS then
              transformed_geom :=null;
          end;
        end if;

        if transformed_geom is not null then

          transformed_geom.SDO_POINT := SDO_GEOM.SDO_CENTROID(SDO_GEOM.SDO_MBR(transformed_geom),0.0005).SDO_POINT;

        -- !!! >> здесь еще надо вставить преобразование геометрий когда трансформация будет зависеть от версии

        -- определяем оригинальная ли геометрия будет помещаться в текущую таблицу
        if (c_srid = srid_value) and (og.sd3_version_id = version_id) then
            is_generated := 'N';
        else
            is_generated := 'Y';
        end if;

        --получаем id для сгенерированной геометрии
        select sm.seqsd3_og_generated.nextval into generated_id from dual;

        -- вставляем новые данные в таблицу соответствующую текущей версии и текущей координатной системе
        execute immediate 'insert into '||insert_table_name||'(id, is_generated, geometry, original_geometry_id)'
            ||'values(:1,:2,:3,:4)'
            using generated_id, is_generated, transformed_geom, og.id;

        -- вствляем данные в таблицу sd3_geometry_revision
        insert into sm.sd3_geometry_revision(id, srid, version_id, revision_number, original_geometry_id, sd3_geometry_metadata_id)
               values(generated_id, srid_value, version_id, current_rev_seq, og.id, og.sd3_geometry_metadata_id);
      end if;
      end if;
    end loop;

    --вставляем новый номер ревизии в sd3_geometry_revision_seq
    update sm.sd3_geometry_revision_seq set current_value = current_rev_seq;

  end;

  --
  -- Создать если необходимо таблицы для новых версий и координатных систем
  --
  procedure create_new_sd3_og_tables as
    c number;
  begin
    -- Проходим по всем версиям и координатным системам
    for v in (select * from sm.sd3_versions) loop
      for cs in (select * from sm.sd3_used_coord_systems) loop

        -- Если соответствующей таблицы не найдено то она создается
        select count(*) into c from sys.all_tables a where a.owner='SM' and a.table_name = 'SD3_OG_'||v.id||'_'||cs.srid;

        if c=0 then
          -- Создание таблицы
          sm.sd3_utils.create_sd3_og_table(v.id, cs.srid);

          -- Заполнение ее уже существующими геоданными
          sd3_utils.fill_sd3_og_table(v.id, cs.srid);

          -- Создание индекса
          sm.sd3_utils.create_sd3_og_geo_index(v.id, cs.srid);

          commit;
        end if;

      end loop;
    end loop;
  end;

  --
  -- Процедура для обновления таблиц при изменении списка доступных версий
  --
  procedure update_geometry_versions as
  begin
    sd3_utils.drop_not_used_sd3_og_tables;
    sd3_utils.create_new_sd3_og_tables;
    return;
  end;

  --
  -- Процедура для обновления таблиц при изменении списка используемых координатных систем
  --
  procedure update_used_coordinate_systems as
  begin
    sd3_utils.drop_not_used_sd3_og_tables;
    sd3_utils.create_new_sd3_og_tables;
    return;
  end;

  --
  -- Добавить в массив GEOMETRY_METADATA_IDs идентификатор
  -- С отслеживанием уникальности значений в этом массиве
  --
  procedure add_geometry_metadata_id_uniq(id number) as
    i number;
  begin
    for i in 1..sm.sd3_utils.GEOMETRY_METADATA_IDs.count
    loop
      if sm.sd3_utils.GEOMETRY_METADATA_IDs(i)=id then
        return;
      end if;
    end loop;
    sm.sd3_utils.GEOMETRY_METADATA_IDs(sm.sd3_utils.GEOMETRY_METADATA_IDs.count+1):=id;
  end;

  --
  -- Создать геометрию на основе параметров и данных из временной таблицы sm.sd3_temp_points
  --
  function create_sdo_geometry(geom_id number, gtype number, srid number, x number, y number) return mdsys.sdo_geometry as
    elem MDSYS.SDO_ELEM_INFO_ARRAY;
    ord MDSYS.SDO_ORDINATE_ARRAY;
  begin
    elem := MDSYS.SDO_ELEM_INFO_ARRAY();
    ord := MDSYS.SDO_ORDINATE_ARRAY();

    for e in (select * from sm.sd3_temp_points tp
        where tp.geometry_id=geom_id and tp.type='ELM'
        order by tp.val_index)
    loop
      elem.EXTEND(1);
      elem(elem.Last) := e.value;
    end loop;

    for e in (select * from sm.sd3_temp_points tp
        where tp.geometry_id=geom_id and tp.type='ORD'
        order by tp.val_index)
    loop
      ord.EXTEND(1);
      ord(ord.Last) := e.value;
    end loop;

    return MDSYS.SDO_GEOMETRY(gtype, srid, MDSYS.SDO_POINT_TYPE(x,y,null),elem, ord);
  end;

  function calc_geometry_x(geom mdsys.sdo_geometry) return number as
    i number;
    min_x number;
    max_x number;
    t_x number;
  begin
      if geom.SDO_ORDINATES.count=0 then
          raise_application_error(-20101,'Геометрия не содержит точек.');
      end if;

      i:=geom.SDO_ORDINATES.First;
      min_x :=geom.SDO_ORDINATES(i);
      max_x :=geom.SDO_ORDINATES(i);
      while i<=geom.SDO_ORDINATES.Last loop
          t_x := geom.SDO_ORDINATES(i);
          if t_x<min_x then
              min_x := t_x;
          end if;
          if t_x>max_x then
              max_x := t_x;
          end if;
          i:=i+2;
      end loop;
      return min_x+((max_x-min_x)/2);
  end;

  function calc_geometry_y(geom mdsys.sdo_geometry) return number as
    i number;
    min_y number;
    max_y number;
    t_y number;
  begin
      if geom.SDO_ORDINATES.count=0 then
          raise_application_error(-20101,'Геометрия не содержит точек.');
      end if;

      i:=geom.SDO_ORDINATES.First;
      min_y :=geom.SDO_ORDINATES(i+1);
      max_y :=geom.SDO_ORDINATES(i+1);
      while i<=geom.SDO_ORDINATES.Last loop
          t_y := geom.SDO_ORDINATES(i+1);
          if t_y<min_y then
              min_y := t_y;
          end if;
          if t_y>max_y then
              max_y := t_y;
          end if;
          i:=i+2;
      end loop;
      return min_y+((max_y-min_y)/2);
  end;

begin
  stop_triggers := 0;
end;
/
grant execute on SM.SD3_UTILS to SM_ALL_SELECT;
grant execute on SM.SD3_UTILS to SM_CANGIS;


prompt
prompt Creating package body SDO_UTIL
prompt ==============================
prompt
create or replace package body sm.SDO_UTIL as


  function f_dgls_pkr(in_geom IN mdsys.sdo_geometry, tol IN number)  return mdsys.sdo_geometry is
    -- f_dgls_pkr
    -- March 2003
    -- Glen Smith
    -- Function to perform Douglas-Peuker line generalization
    -- on gtype() = 2
    -- tolerance in metres
    geom_head  mdsys.sdo_geometry;
    geom_tail  mdsys.sdo_geometry;
    col_head   mdsys.sdo_ordinate_array := mdsys.sdo_ordinate_array();
    col_tail   mdsys.sdo_ordinate_array := mdsys.sdo_ordinate_array();
    col_all    mdsys.sdo_ordinate_array := mdsys.sdo_ordinate_array();
    --coord_head int := 1;
    coord_tail int := in_geom.sdo_ordinates.COUNT / 2;
    coord_far  int;
    x          number;
    y          number;
    dist_now   number;
    dist_max   number := 0;
    srid       number;
  begin
    if in_geom.SDO_GTYPE<>2002 then
     raise_application_error(-20101,'Неверный тип геометрии GTYPE='||in_geom.SDO_GTYPE||' для преобразования линии по алгоритму Дугласа-Пекера');
    end if;
    if in_geom.SDO_SRID is null then
     raise_application_error(-20101,'Невозможно выполнять симплификацию, не зная КС');
    end if;
    srid := in_geom.SDO_SRID;

    --check number of coords (must be at least 3 to generalize)
    if coord_tail < 3 then
      --first and last points
      col_all.EXTEND(4);
      col_all(col_all.COUNT - 3) := in_geom.sdo_ordinates(1);
      col_all(col_all.COUNT - 2) := in_geom.sdo_ordinates(2);
      col_all(col_all.COUNT - 1) := in_geom.sdo_ordinates(3);
      col_all(col_all.COUNT) := in_geom.sdo_ordinates(4);
    else
      --get furthest orthogonal point from baseline
      for i in 2 .. coord_tail - 1 loop
        x := in_geom.sdo_ordinates(i * 2 - 1);
        y := in_geom.sdo_ordinates(i * 2);
        SELECT SDO_GEOM.SDO_DISTANCE(mdsys.sdo_geometry(2001,
                                                        srid,
                                                        mdsys.sdo_point_type(x,
                                                                             y,
                                                                             NULL),
                                                        NULL,
                                                        NULL),
                                     mdsys.sdo_geometry(2002,
                                                        srid,
                                                        NULL,
                                                        mdsys.sdo_elem_info_array(1,
                                                                                  2,
                                                                                  1),
                                                        mdsys.sdo_ordinate_array(in_geom.sdo_ordinates(1),
                                                                                 in_geom.sdo_ordinates(2),
                                                                                 in_geom.sdo_ordinates(coord_tail * 2 - 1),
                                                                                 in_geom.sdo_ordinates(coord_tail * 2))),
                                     tol, 'unit=M' )
          INTO dist_now
          FROM dual;
        if dist_now > dist_max then
          dist_max  := dist_now;
          coord_far := i;
        end if;
      end loop;
      if dist_max > tol then
        --recurse
        --build head
        for i in 1 .. coord_far loop
          col_head.EXTEND(2);
          col_head(col_head.COUNT - 1) := in_geom.sdo_ordinates(i * 2 - 1);
          col_head(col_head.COUNT) := in_geom.sdo_ordinates(i * 2);
        end loop;
        --build tail
        for i in coord_far .. coord_tail loop
          col_tail.EXTEND(2);
          col_tail(col_tail.COUNT - 1) := in_geom.sdo_ordinates(i * 2 - 1);
          col_tail(col_tail.COUNT) := in_geom.sdo_ordinates(i * 2);
        end loop;
        --recurse head & tail
        geom_head := f_dgls_pkr(mdsys.sdo_geometry(2002,
                                                   srid,
                                                   NULL,
                                                   mdsys.sdo_elem_info_array(1,
                                                                             2,
                                                                             1),
                                                   col_head),
                                tol);
        geom_tail := f_dgls_pkr(mdsys.sdo_geometry(2002,
                                                   srid,
                                                   NULL,
                                                   mdsys.sdo_elem_info_array(1,
                                                                             2,
                                                                             1),
                                                   col_tail),
                                tol);
        --merge result
        for i in 1 .. geom_head.sdo_ordinates.COUNT loop
          col_all.EXTEND;
          col_all(col_all.COUNT) := geom_head.sdo_ordinates(i);
        end loop;
        for i in 3 .. geom_tail.sdo_ordinates.COUNT loop
          col_all.EXTEND;
          col_all(col_all.COUNT) := geom_tail.sdo_ordinates(i);
        end loop;
      else
        --generalize
        col_all.EXTEND(4);
        col_all(col_all.COUNT - 3) := in_geom.sdo_ordinates(1);
        col_all(col_all.COUNT - 2) := in_geom.sdo_ordinates(2);
        col_all(col_all.COUNT - 1) := in_geom.sdo_ordinates(coord_tail * 2 - 1);
        col_all(col_all.COUNT) := in_geom.sdo_ordinates(coord_tail * 2);
      end if;
    end if;
    return(mdsys.sdo_geometry(in_geom.SDO_GTYPE,
                              in_geom.SDO_SRID,
                              in_geom.SDO_POINT,
                              in_geom.SDO_ELEM_INFO,
                              col_all));
  END;

  function f_dgls_pkr_poly(in_geom IN mdsys.sdo_geometry, tol IN number)  return mdsys.sdo_geometry
  is
    out_geom mdsys.sdo_geometry;
  begin
    if in_geom.SDO_GTYPE<>2003 then
     raise_application_error(-20101,'Неверный тип геометрии GTYPE='||in_geom.SDO_GTYPE||' для преобразования полигона по алгоритму Дугласа-Пекера');
    end if;

    out_geom:=in_geom;
    out_geom.SDO_GTYPE:=2002;
    out_geom:=f_dgls_pkr(out_geom,tol);
    --насильно замкнем полигон
    out_geom.SDO_ORDINATES(out_geom.SDO_ORDINATES.count-1):=out_geom.SDO_ORDINATES(1);
    out_geom.SDO_ORDINATES(out_geom.SDO_ORDINATES.count):=out_geom.SDO_ORDINATES(2);
    out_geom.SDO_GTYPE:=2003;

    return out_geom;
  end;

  function get_diminfo(geometry IN MDSYS.SDO_GEOMETRY) return MDSYS.SDO_DIM_ARRAY
  is
   dim MDSYS.SDO_DIM_ARRAY;
   EX MDSYS.SDO_DIM_ELEMENT;
   EY MDSYS.SDO_DIM_ELEMENT;
   ord_cnt integer;
   i integer;
  begin
   ord_cnt:=geometry.SDO_ORDINATES.count/2;

   EX:=MDSYS.SDO_DIM_ELEMENT(
    'X',
    geometry.SDO_ORDINATES(1),
    geometry.SDO_ORDINATES(1),
    0.005);

   EY:=MDSYS.SDO_DIM_ELEMENT(
    'Y',
    geometry.SDO_ORDINATES(2),
    geometry.SDO_ORDINATES(2),
    0.005);

   for i in 2..ord_cnt loop
     ex.SDO_UB:=greatest(ex.SDO_UB,geometry.SDO_ORDINATES(i*2-1));
     ex.SDO_LB:=least(ex.SDO_LB,geometry.SDO_ORDINATES(i*2-1));

     ey.SDO_UB:=greatest(ey.SDO_UB,geometry.SDO_ORDINATES(i*2));
     ey.SDO_LB:=least(ey.SDO_LB,geometry.SDO_ORDINATES(i*2));
   end loop;

   dim:=MDSYS.SDO_DIM_ARRAY();
   dim.extend(2);
   dim(1):=EX;
   dim(2):=EY;

   return dim;
  end;

  function SIMPLIFY(in_geometry IN MDSYS.SDO_GEOMETRY,  threshold IN NUMBER) RETURN MDSYS.SDO_GEOMETRY
  is
    out_geom mdsys.sdo_geometry;
    dim mdsys.sdo_dim_array;

    hole mdsys.sdo_geometry;
    geometry mdsys.sdo_geometry;
    holes_cnt integer;
    hole_num integer;

    part mdsys.sdo_geometry;
    parts_cnt integer;
    part_num integer;
  begin
    geometry := in_geometry;
    out_geom:=geometry;

    --2002 - полилиния
    if    geometry.SDO_GTYPE=2002 then out_geom:=f_dgls_pkr(geometry,threshold);

    --2003 - полигон с дырками
    elsif geometry.SDO_GTYPE=2003 then
      --Делаем что первый элемент это оболочка а все остальные элементы это дырки
      for index_type in 0 .. geometry.SDO_ELEM_INFO.count/3-1 loop
          if index_type=0 then
              geometry.SDO_ELEM_INFO(index_type*3+2):=1003;
          else
              geometry.SDO_ELEM_INFO(index_type*3+2):=2003;
          end if;
      end loop;
      
      holes_cnt:=(geometry.SDO_ELEM_INFO.count/3)-1;
      --если дырок нет, генерализуем простой полигон
      if holes_cnt=0 then
        -- все равно делаем екстракт чтобы точки вернулись в правильном порядке
        out_geom:=f_dgls_pkr_poly(mdsys.sdo_util.extract(geometry,1,1),threshold);
      else
        dim:=get_diminfo(geometry);
        out_geom:=mdsys.sdo_util.extract(geometry,1,1);
        out_geom:=f_dgls_pkr_poly(out_geom,threshold);
        -- todo: проверить количество дырок в результате
        for hole_num in 1..holes_cnt-1 loop
          hole:=mdsys.sdo_util.extract(geometry,1,hole_num+1);
          hole:=f_dgls_pkr_poly(hole,threshold);
          out_geom:=mdsys.sdo_geom.sdo_difference(out_geom,dim,hole,dim);
        end loop;
      end if;

    --2006 - мультилиния
    elsif geometry.SDO_GTYPE=2006 then
      --мультилинию надо раскидать на линии и прогнать по отдельности
      dim:=get_diminfo(geometry);
      parts_cnt:=geometry.SDO_ELEM_INFO.count/3;
      out_geom:=mdsys.sdo_util.extract(geometry,1);
      out_geom:=f_dgls_pkr(out_geom,threshold);
      for part_num in 2..parts_cnt loop
          part:=mdsys.sdo_util.extract(geometry,part_num);
          part:=f_dgls_pkr(part,threshold);
          out_geom:=mdsys.sdo_geom.sdo_union(out_geom,dim,hole,dim);
      end loop;

    --2007 - мультиполигон
    elsif geometry.SDO_GTYPE=2007 then
      --мультиполгинон надо раскидать на полигоны и рекурсивно прогнать
      dim:=get_diminfo(geometry);
      --посчитаем количество экстерьеров (ETYPE=1003)
      parts_cnt:=0;
      for part_num in 1..geometry.SDO_ELEM_INFO.count/3 loop
        if geometry.SDO_ELEM_INFO((part_num-1)*3+2)=1003 then
          parts_cnt:=parts_cnt+1;
        end if;
      end loop;

      out_geom:=mdsys.sdo_util.extract(geometry,1);
      for part_num in 2..parts_cnt loop
        part:=mdsys.sdo_util.extract(geometry,1);
        part:=simplify(part,threshold);
        out_geom:=mdsys.sdo_geom.sdo_union(out_geom,dim,hole,dim);
      end loop;

    end if;

    return out_geom;

  end;

  procedure UpdateBoundsMetadata (in_table_name in VARCHAR default 'SD_OBJECT_GEOMETRIES',
                                  in_owner in VARCHAR default 'SM',
                                  TOLERANCE IN NUMBER default 0.05)
  is
    DIM_X MDSYS.SDO_DIM_ELEMENT;
    DIM_Y MDSYS.SDO_DIM_ELEMENT;
    DIM_ARR MDSYS.SDO_DIM_ARRAY;
    c_cursor integer;
    ignore integer;
    minx integer;
    maxx integer;
    miny integer;
    maxy integer;
  begin
    DIM_ARR:=MDSYS.SDO_DIM_ARRAY();
    DIM_ARR.Extend(2);

    for item in (
    select m.* from mdsys.all_sdo_geom_metadata m, sys.all_tab_columns c
    where
     c.OWNER = m.owner and
     c.TABLE_NAME = m.table_name and
     c.COLUMN_NAME = m.COLUMN_NAME and
     Upper(m.owner)=Upper(in_owner) and
     Upper(m.table_name)=Upper(in_table_name)) loop


      DIM_X:=MDSYS.SDO_DIM_ELEMENT('X',0,0,TOLERANCE);
      DIM_Y:=MDSYS.SDO_DIM_ELEMENT('Y',0,0,TOLERANCE);

      c_cursor := DBMS_SQL.open_cursor;
      dbms_sql.parse(c_cursor,
      'select min(c.x), max(c.x), min(c.y), max(c.y) '||
      'from '||
       in_owner||'.'||in_table_name||' s,'||
      'TABLE(MDSYS.SDO_UTIL.GetVertices('||item.column_name||')) c', dbms_sql.native);

      dbms_sql.define_column(c_cursor, 1, minx);
      dbms_sql.define_column(c_cursor, 2, maxx);
      dbms_sql.define_column(c_cursor, 3, miny);
      dbms_sql.define_column(c_cursor, 4, maxy);

      ignore := dbms_sql.execute(c_cursor);

      loop
        if dbms_sql.fetch_rows(c_cursor) = 0 then
          exit;
        else
          dbms_sql.column_value(c_cursor, 1, DIM_X.SDO_LB);
          dbms_sql.column_value(c_cursor, 2, DIM_X.SDO_UB);
          dbms_sql.column_value(c_cursor, 3, DIM_Y.SDO_LB);
          dbms_sql.column_value(c_cursor, 4, DIM_Y.SDO_UB);
        end if;
      end loop;
      dbms_sql.close_cursor(c_cursor);
      DIM_X.SDO_LB := nvl(DIM_X.SDO_LB,0.000001);
      DIM_X.SDO_UB := nvl(DIM_X.SDO_UB,0.000002);
      DIM_Y.SDO_LB := nvl(DIM_Y.SDO_LB,0.000001);
      DIM_Y.SDO_UB := nvl(DIM_Y.SDO_UB,0.000002);

      DIM_ARR(1):=DIM_X;
      DIM_ARR(2):=DIM_Y;

      update mdsys.all_sdo_geom_metadata m
      set m.DIMINFO=DIM_ARR
      where
       m.owner=in_owner and
       m.table_name=in_table_name and
       m.column_name=item.column_name;
    end loop;


  end;

  procedure UpdateBoundsMetadataRowChanged(in_rowid in number, in_pk_name in VARCHAR default 'ID',
    in_table_name in VARCHAR default 'SD_OBJECT_GEOMETRIES', in_owner in VARCHAR default 'SM',
    TOLERANCE IN NUMBER default 0.05)
  is
    DIM_X MDSYS.SDO_DIM_ELEMENT;
    DIM_Y MDSYS.SDO_DIM_ELEMENT;
    DIM_ARR MDSYS.SDO_DIM_ARRAY;
    c_cursor integer;
    ignore integer;
  begin
    DIM_ARR:=MDSYS.SDO_DIM_ARRAY();
    DIM_ARR.Extend(2);

    for item in (
    select * from mdsys.all_sdo_geom_metadata m
    where
      Upper(m.owner)=Upper(in_owner) and
      Upper(m.table_name)=Upper(in_table_name)) loop

      c_cursor := DBMS_SQL.open_cursor;
      dbms_output.put_line('select min(c.x), max(c.x), min(c.y), max(c.y) '||
      'from '||
       in_owner||'.'||in_table_name||' s,'||
      'TABLE(MDSYS.SDO_UTIL.GetVertices('||item.column_name||')) c where s.' || in_pk_name || '=' || in_rowid);
      dbms_sql.parse(c_cursor,
      'select min(c.x), max(c.x), min(c.y), max(c.y) '||
      'from '||
       in_owner||'.'||in_table_name||' s,'||
      'TABLE(MDSYS.SDO_UTIL.GetVertices('||item.column_name||')) c where s.' || in_pk_name || '=' || in_rowid,
      dbms_sql.native);

      dbms_sql.define_column(c_cursor, 1, DIM_X.SDO_LB);
      dbms_sql.define_column(c_cursor, 2, DIM_X.SDO_UB);
      dbms_sql.define_column(c_cursor, 3, DIM_Y.SDO_LB);
      dbms_sql.define_column(c_cursor, 4, DIM_Y.SDO_UB);

      ignore := dbms_sql.execute(c_cursor);

      DIM_X:=MDSYS.SDO_DIM_ELEMENT('X',0,0,TOLERANCE);
      DIM_Y:=MDSYS.SDO_DIM_ELEMENT('Y',0,0,TOLERANCE);

      loop
        if dbms_sql.fetch_rows(c_cursor) = 0 then
          dbms_output.put_line('ok 1');
          exit;
        else
          dbms_sql.column_value(c_cursor, 1, DIM_X.SDO_LB);
          dbms_sql.column_value(c_cursor, 2, DIM_X.SDO_UB);
          dbms_sql.column_value(c_cursor, 3, DIM_Y.SDO_LB);
          dbms_sql.column_value(c_cursor, 4, DIM_Y.SDO_UB);
        end if;
      end loop;

      dbms_output.put_line('ok 2');
      dbms_sql.close_cursor(c_cursor);
      DIM_X.SDO_LB := nvl(DIM_X.SDO_LB,0.000001);
      DIM_X.SDO_UB := nvl(DIM_X.SDO_UB,0.000002);
      DIM_Y.SDO_LB := nvl(DIM_Y.SDO_LB,0.000001);
      DIM_Y.SDO_UB := nvl(DIM_Y.SDO_UB,0.000002);

      if item.diminfo is not null then
        if item.diminfo(1).SDO_LB < DIM_X.SDO_LB then DIM_X.SDO_LB := item.diminfo(1).SDO_LB; end if;
        if item.diminfo(1).SDO_UB > DIM_X.SDO_UB then DIM_X.SDO_UB := item.diminfo(1).SDO_UB; end if;
        if item.diminfo(2).SDO_LB < DIM_Y.SDO_LB then DIM_Y.SDO_LB := item.diminfo(2).SDO_LB; end if;
        if item.diminfo(2).SDO_UB > DIM_Y.SDO_UB then DIM_Y.SDO_UB := item.diminfo(2).SDO_UB; end if;
      end if;
      DIM_ARR(1):=DIM_X;
      DIM_ARR(2):=DIM_Y;

      update mdsys.all_sdo_geom_metadata m
      set m.DIMINFO=DIM_ARR
      where
       m.owner=in_owner and
       m.table_name=in_table_name and
       m.column_name=item.column_name;
    end loop;

  end;

  procedure save_geometry (geometry in MDSYS.Sdo_Geometry, column_name in varchar2, id in number) is
  begin
   
   -- DELETE FROM sm.sd_geometry_tmp;

   -- insert into sm.sd_geometry_tmp values(geometry);

   -- execute immediate 'UPDATE sm.SD_OBJECT_GEOMETRIES SET '|| column_name ||' = '||
   --                   '(select geometry from sm.sd_geometry_tmp where rownum=1)'||
   --                   'WHERE id='||id;

   -- DELETE FROM sm.sd_geometry_tmp;
   

    execute immediate 'UPDATE sm.SD_OBJECT_GEOMETRIES SET '|| column_name ||' = :1 WHERE id = : 2'
      using geometry, id;
  end;

   -- Задача - изменить все несгенерированные масшатбные версии начиная с main_geo_id
   -- main_geo_id in integer  - Гео-Объект с которого начинать пересчет всех масштабных версий закрепленного объекта
   -- is_recalc_all_scales    - Пересчитывать все масштабные или только добавлять несуществующие в пределах объекта
   -- column_names            - Пересчтывать геометрию только для определленых колонокё
 
  procedure regenerate_geometry (main_geo_id in integer,
                                is_recalc_all_scales in CHAR,
                                column_names in columns_array default empty_columns_array)
  is
    current_scale integer;
    geo_id integer;
    css integer;
    transformed MDSYS.SDO_GEOMETRY;
    original_geodata MDSYS.SDO_GEOMETRY;
    fake_geometry MDSYS.SDO_GEOMETRY;
    missing_parametr_ex EXCEPTION;
    is_include CHAR(1);
    main_geo sd_object_geometries%ROWTYPE;
    stop_move_up Boolean;
    stop_move_down Boolean;
    my_sqlerrm VARCHAR2(500);
  begin
    if  (not ((is_recalc_all_scales = 'Y') or (is_recalc_all_scales = 'N'))) then
             raise missing_parametr_ex; --('Неправильно переданы аргументы. Либо Y, либо N');
    end if;
    --ставим блокировку на триггеры
    sm.sdo_util.is_block_main_trigger := 1;
    begin
      select * into main_geo from sm.sd_object_geometries where id = main_geo_id;

      -- Получить значение масштаба текущей геометрии
      select a.scale into current_scale
      from
        sm.sd_scales a,
        sm.sd_object_geometries b
      where
         a.id=b.sd_scale_id and
         b.id = main_geo.id;

      stop_move_up := false;
      stop_move_down := false;
      --Изменяем все связанные объекты
      -- Получить созданные и не созданные геометрии для текущего масштаба и меньши
      -- Потом больше
      for geo in (
          select * from (--(движение вверх) меньшие масштабы 1000, 5000, 10000 и т.д.
          select b.*, a.scale, a.id scale_id
                  from sm.sd_scales a
                  left join (select * from sm.sd_object_geometries
                     where data_id = main_geo.data_id AND
                     dictionary_id = main_geo.dictionary_id AND
                     version_date = main_geo.version_date) b
                  on a.id = b.sd_scale_id
                  where
                    a.scale >= current_scale
                  order by a.scale
          )
          union all
          select * from (--(движение вниз) большие масштабы 500, 300, 100 и т.д.
          select b.*, a.scale, a.id scale_id
                  from sm.sd_scales a
                  left join (select * from sm.sd_object_geometries
                     where data_id = main_geo.data_id AND
                     dictionary_id = main_geo.dictionary_id AND
                     version_date = main_geo.version_date) b
                  on a.id = b.sd_scale_id
                  where
                    a.scale < current_scale
                  order by a.scale desc
          )
      )
      loop
        -- Движение вверх
        if (geo.scale>=current_scale) then
            if (main_geo.id <> geo.id) and (geo.is_generated='N') then
              stop_move_up := true;
            end if;
            if stop_move_up then
                goto continue;
            end if;
        end if;

        -- Движение вниз
        if (geo.scale<current_scale) then
            if (main_geo.id <> geo.id) and (geo.is_generated='N') then
              stop_move_down := true;
            end if;
            if stop_move_down then
                goto continue;
            end if;
        end if;

        geo_id := geo.id;
        --Если для какой-то масштабной версии объекта не существует геометрии, то ее нужно создать
        if geo_id is null then
          --Вначале вставим fake-овый объект, который далее общий алгоритм подменит чем нужно
          --fake_geometry := MDSYS.SDO_GEOMETRY(null,null,null,null,null);
          fake_geometry := main_geo.original_geodata;
          select seqsd_object_geometries.nextval into geo_id from dual;
          INSERT INTO sm.sd_object_geometries(id,data_id,sd_scale_id,version_date,original_geodata, dictionary_id, is_generated)
          VALUES(geo_id,main_geo.data_id,geo.scale_id,main_geo.version_date,fake_geometry, main_geo.dictionary_id, 'Y');
          --Даты должны соответствовать оригинальной версии, т.к геометрии создаются именно в пределах текущей версии
          --VALUES(geo_id,main_geo.data_id,geo.scale_id,SYSDATE,fake_geometry, main_geo.dictionary_id, 'Y');
        else
          --Если стоит флаг только на добавление, то смотрим следующее значение
          if is_recalc_all_scales = 'N' then
              goto continue;
          end if;
        end if;

        --делаем симплификацию если необходимо
        -- необходимо это когда создается геометрия для менее подробного масштаба
        if (main_geo.id <> geo_id) and (geo.scale>=current_scale) then
          original_geodata := sm.sdo_util.SIMPLIFY(main_geo.original_geodata, sm.SDO_UTIL.SIMPLIFY_SCALE_FACTOR*geo.scale);
          --original_geodata := mdsys.sdo_util.simplify(main_geo.original_geodata, sm.SDO_UTIL.SIMPLIFY_SCALE_FACTOR*geo.scale);
          sm.sdo_util.save_geometry(original_geodata, 'ORIGINAL_GEODATA', geo_id);
        else
          original_geodata := main_geo.original_geodata;
        end if;

        --находим все колонки с геоданными кроме original_geodata
        for item in (
          select * from sm.sd_used_srs)
        loop

          --если явно проставленно какие колонки изменять, то проверяем входит текущая колонка в массив
          --if column_names.count > 0 then
          --  is_include := 'N';
          --  for i in 1 .. column_names.count loop
          --    if UPPER(column_names(i)) = UPPER(item.column_name) then
          --       is_include := 'Y';
          --       exit;
          --    end if;
          --  end loop;
          --  exit when is_include = 'N';
          --end if;

          --выясняем координатную систему
          css := item.srid;

          begin
              --создаем и присваеваем проекцию.
              --
              --По непонятным пока причинам в 10 версии оракла
              --при преобразовании координатной системы самой в себя
              --происхдит изменение геометрии (вроде бы сдвиг)
              --
              if css = original_geodata.SDO_SRID then
                  transformed := original_geodata;
              else
                  transformed := mdsys.sdo_cs.transform(original_geodata, css);
              end if;

              sm.sdo_util.save_geometry(transformed, item.column_name, geo_id);
          exception
              when OTHERS then
                  null;
                  -- my_sqlerrm := SUBSTR('Scale='||geo.scale||', SRID='||css||', ERROR - '||SQLERRM, 1, 500);
                  -- insert into SD_REGENERATE_MESS (message_time, message) values(sysdate, my_sqlerrm);
          end;

        end loop;

        <<continue>>
        null; -- Это конечно загадочно, но иначе не работает
      end loop;--geo
      --снимаем блокировку на триггеры
      sm.sdo_util.is_block_main_trigger := null;
    exception
      when others then begin
        --снимаем блокировку на триггеры
        sm.sdo_util.is_block_main_trigger := null;
        raise;
      end;
    end;
  end;


   --
   --Задача - изменить все несгенерированные масшатбные версии начиная с main_geo_id
   --main_geo_id in integer  - Гео-Объект с которого начинать пересчет всех масштабных версий закрепленного объекта
   --is_recalc_all_scales    - Пересчитывать все масштабные или только добавлять несуществующие в пределах объекта
   --column_names            - Пересчтывать геометрию только для определленых колонокё
   --
  procedure regenerate_geometry_old (main_geo_id in integer,
                                is_recalc_all_scales in CHAR,
                                column_names in columns_array default empty_columns_array)
  is
    current_scale integer;
    geo_id integer;
    css integer;
    transformed MDSYS.SDO_GEOMETRY;
    original_geodata MDSYS.SDO_GEOMETRY;
    fake_geometry MDSYS.SDO_GEOMETRY;
    missing_parametr_ex EXCEPTION;
    is_include CHAR(1);
    main_geo sd_object_geometries%ROWTYPE;
  begin
    if  (not ((is_recalc_all_scales = 'Y') or (is_recalc_all_scales = 'N'))) then
             raise missing_parametr_ex; --('Неправильно переданы аргументы. Либо Y, либо N');
    end if;
    --ставим блокировку на триггеры
    sm.sdo_util.is_block_main_trigger := 1;
    begin
      select * into main_geo from sm.sd_object_geometries where id = main_geo_id;

      -- Получить значение масштаба текущей геометрии
      select a.scale into current_scale
      from
        sm.sd_scales a,
        sm.sd_object_geometries b
      where
         a.id=b.sd_scale_id and
         b.id = main_geo.id;

      --Изменяем все связанные объекты
      -- Получить созданные и не созданные геометрии для текущего масштаба и меньших
      for geo in (
        select b.*, a.scale, a.id scale_id
        from sm.sd_scales a
        left join (select * from sm.sd_object_geometries
                   where data_id = main_geo.data_id AND
                   dictionary_id = main_geo.dictionary_id AND
                   version_date = main_geo.version_date) b
        on a.id = b.sd_scale_id
        where
          a.scale >= current_scale
        order by a.scale)
      loop
        --Выходим когда встречаем первую несгенерированную версию
        if (main_geo.id <> geo.id) and (geo.is_generated='N') then
          exit;
        end if;


        geo_id := geo.id;
        --Если для какой-то масштабной версии объекта не существует геометрии, то ее нужно создать
        if geo_id is null then
          --Вначале вставим fake-овый объект, который далее общий алгоритм подменит чем нужно
          --fake_geometry := MDSYS.SDO_GEOMETRY(null,null,null,null,null);
          fake_geometry := main_geo.original_geodata;
          select seqsd_object_geometries.nextval into geo_id from dual;
          INSERT INTO sm.sd_object_geometries(id,data_id,sd_scale_id,version_date,original_geodata, dictionary_id, is_generated)
          VALUES(geo_id,main_geo.data_id,geo.scale_id,main_geo.version_date,fake_geometry, main_geo.dictionary_id, 'Y');
          --Даты должны соответствовать оригинальной версии, т.к геометрии создаются именно в пределах текущей версии
          --VALUES(geo_id,main_geo.data_id,geo.scale_id,SYSDATE,fake_geometry, main_geo.dictionary_id, 'Y');
        else
          --Если стоит флаг только на добавление, то выходим
          exit when is_recalc_all_scales = 'N';
        end if;

        --делаем симплификацию если необходимо
        if (main_geo.id <> geo_id) then
          original_geodata := sm.sdo_util.SIMPLIFY(main_geo.original_geodata, sm.SDO_UTIL.SIMPLIFY_SCALE_FACTOR*geo.scale);
          sm.sdo_util.save_geometry(original_geodata, 'ORIGINAL_GEODATA', geo_id);
        else
          original_geodata := geo.original_geodata;
        end if;

        --находим все колонки с геоданными кроме original_geodata
        for item in (
          select * from sm.sd_used_srs)
        loop

          --если явно проставленно какие колонки изменять, то проверяем входит текущая колонка в массив
          --
          --if column_names.count > 0 then
          --  is_include := 'N';
          --  for i in 1 .. column_names.count loop
          --    if UPPER(column_names(i)) = UPPER(item.column_name) then
          --       is_include := 'Y';
          --       exit;
          --    end if;
          --  end loop;
          --  exit when is_include = 'N';
          --end if;

          --выясняем координатную систему
          css := item.srid;

          --создаем и присваеваем проекцию.
          transformed := mdsys.sdo_cs.transform(original_geodata, css);

          sm.sdo_util.save_geometry(transformed, item.column_name, geo_id);

        end loop;
      end loop;--geo
      --снимаем блокировку на триггеры
      sm.sdo_util.is_block_main_trigger := null;
    exception
      when others then begin
        --снимаем блокировку на триггеры
        sm.sdo_util.is_block_main_trigger := null;
        raise;
      end;
    end;
  end;

  procedure disable_trigger(name in varchar2)
  is
  begin
    execute immediate 'alter trigger ' || name || ' disable';
  end;
  
  procedure enable_trigger(name in varchar2)
  is
  begin
    execute immediate 'alter trigger ' || name || ' enable';
  end;
  
  procedure disable_geometry_triggers
  is
  begin
    disable_trigger('SM.SD_OBJ_GEOM_BEFORE_UPDATE_CS');
    disable_trigger('SM.SD_OBJ_GEOM_PREPARE_UPDATE_CS');
    disable_trigger('SM.SD_OBJ_GEOM_UPDATE_CS');
  end;
  
  procedure enable_geometry_triggers
  is
  begin
    enable_trigger('SM.SD_OBJ_GEOM_BEFORE_UPDATE_CS');
    enable_trigger('SM.SD_OBJ_GEOM_PREPARE_UPDATE_CS');
    enable_trigger('SM.SD_OBJ_GEOM_UPDATE_CS');
  end;
  
  procedure regenerate_all_geometry
  is
    geo_id number;
    original_geodata MDSYS.SDO_GEOMETRY;
    transformed MDSYS.SDO_GEOMETRY;
    ignore integer;
  begin
    disable_geometry_triggers;
        
    sdo_util.is_block_main_trigger := 1;
  
    for c in (

      select og.id, og.dictionary_id, og.data_id, og.version_date, og.original_geodata, t.to_scale_id, t.from_scale, t.to_scale
      from sd_object_geometries og inner join sd_scales ss on og.sd_scale_id = ss.id, (
        select fs.scale to_scale, fs.id to_scale_id, g.dictionary_id, g.data_id, g.version_date,
          nvl(
            max(case when s.scale <= fs.scale then s.scale else null end),
            min(case when s.scale > fs.scale then s.scale else null end)) from_scale
        from sd_scales fs, sd_object_geometries g inner join sd_scales s on g.sd_scale_id = s.id
        where g.is_generated = 'N'
        group by fs.scale, fs.id, g.dictionary_id, g.data_id, g.version_date
      ) t
      where og.dictionary_id = t.dictionary_id and og.data_id = t.data_id
        and og.version_date = t.version_date and ss.scale = t.from_scale

    ) loop

      original_geodata := c.original_geodata;

      -- данная геометрия сгенерирована?
      if c.from_scale <> c.to_scale then
        begin
          -- может быть данный масштаб уже имеется и его нужно только обновить
          select id into geo_id from sd_object_geometries
            where data_id = c.data_id and dictionary_id = c.dictionary_id and version_date = c.version_date and sd_scale_id = c.to_scale_id;
        exception
          when NO_DATA_FOUND then
          begin
            -- создаем новую запись
            select seqsd_object_geometries.nextval into geo_id from dual;
            insert into sd_object_geometries (id, data_id, sd_scale_id, version_date, original_geodata, dictionary_id, is_generated)
            values (geo_id, c.data_id, c.to_scale_id, c.version_date, original_geodata, c.dictionary_id, 'Y');
          end;
        end;
        -- упрощаем если нужно
        if c.to_scale > c.from_scale then
          original_geodata := sdo_util.SIMPLIFY(c.original_geodata, SDO_UTIL.SIMPLIFY_SCALE_FACTOR*c.to_scale);
        end if;
        sdo_util.save_geometry(original_geodata, 'ORIGINAL_GEODATA', geo_id);
      else
        geo_id := c.id;
      end if;

      -- создаем остальные геометрии, вдруг они не созданы
      for item in (select * from sd_used_srs) loop
        begin
          --создаем и присваеваем проекцию.
          if item.srid = original_geodata.SDO_SRID then
              transformed := original_geodata;
          else
              transformed := mdsys.sdo_cs.transform(original_geodata, item.srid);
          end if;
          sdo_util.save_geometry(transformed, item.column_name, geo_id);
        exception
          when OTHERS then
            null;
        end;
      end loop;
    end loop;

    sm.sdo_util.is_block_main_trigger := null;

    sdo_util.UpdateBoundsMetadata;
  
    enable_geometry_triggers;
  exception
    when others then begin
      --снимаем блокировку на триггеры
      sm.sdo_util.is_block_main_trigger := null;
      enable_geometry_triggers;
      raise;
    end;
  end;
  
