  procedure log_message(msg in varchar2)
  is
    ignore float;
  begin
    --dbms_pipe.pack_message(msg);
    --ignore := dbms_pipe.send_message('sdo_util');
    null;
  end;

  function getTilingLevel(in_table_name in varchar2, in_column_name in varchar2, in_owner in varchar2 default 'SM') return number
  is
    N number; --количество точек
    quadro_k number;
  begin

    --Вычисляем параметры квадроиндекса, из расчета плотности точек
    --Если плотность карты в четыре раза мееньше чем площадь то коэфициент квадроиндекса = 1
    execute immediate 'select count(b.x) into sm.SDO_UTIL.tmp_points_count from '''||
                      in_owner||'.'||in_table_name||
                      ''' a,TABLE(MDSYS.SDO_UTIL.GetVertices(a.'''|| in_column_name ||''')) b';
    N := sm.SDO_UTIL.tmp_points_count;
    quadro_k := Round(1/log(N,4));
    return quadro_k;
  end;


  procedure DropIndex(arg_table_name in varchar2, arg_column_name in varchar2, arg_owner in varchar2 default 'SM')
  is
    in_owner varchar(32);
    in_table_name varchar(32);
    in_column_name varchar(32);
  begin
    in_owner := upper(arg_owner);
    in_table_name := upper(arg_table_name);
    in_column_name := upper(arg_column_name);
    for indx in (select index_name, index_owner from sys.all_ind_columns
                where table_owner=in_owner and
                      table_name=in_table_name and
                      column_name=in_column_name)
     loop
       execute immediate 'DROP INDEX '||indx.index_owner||'.'||indx.index_name||' FORCE'  ;
     end loop;
  end;

  function lazy_set_count_obj(din_count number) return number
  is
  begin
      sm.SDO_UTIL.tmp_count_objects := din_count;
      return din_count;
  end;

  function is_saumi_data_linked(in_dictionary_id in number, in_data_id in number) return number
  is
    cnt number;
    t_name varchar2(32);
  begin
    sm.SDO_UTIL.log_message('Check geo object on link dictionary_id='||in_dictionary_id||' data_id='||in_data_id);
    if (in_dictionary_id = -1) then
      select count(*) into cnt from sm.objects where id = in_data_id;
    else
      select count(*) into cnt from sm.dictionaries where id = in_dictionary_id;
      if cnt <> 1 then
        return 0;
      end if;
      select table_name into t_name from sm.dictionaries where id = in_dictionary_id;
      execute immediate
       'select sm.SDO_UTIL.lazy_set_count_obj(cc) from (select count(*) cc  from '
       ||t_name||' where id='||in_data_id||')';
       --'select count(*) into sm.SDO_UTIL.tmp_count_objects from '||t_name||' where id='||in_data_id;
       cnt := sm.SDO_UTIL.tmp_count_objects;
     end if;
     if cnt <> 1 then
       return 0;
     else
       return 1;
     end if;
  end;

  procedure ReSnapRawTable(rawitem_id in number)
  is
    dynamic_pl varchar(4000);
    ri sd_rawitems%ROWTYPE;
  begin
    begin
      sm.SDO_UTIL.is_update_bounds:='N';

      select * into ri from sm.sd_rawitems where id = rawitem_id;

      dynamic_pl :=
      'declare nid number; v_date date; i number; og sd_object_geometries%ROWTYPE; '||
      'begin '||
      'i := 1; '||
      'select version_date into v_date from sm.sd_rawitems where id='||rawitem_id||
      ';for geo in (select * from '||ri.owner||'.'||ri.table_name||' where not SAUMI_DATA_ID is NULL ) loop '||

        'if (sm.SDO_UTIL.is_saumi_data_linked('||ri.dictionary_id||', geo.saumi_data_id) = 1) then '||

          'sm.SDO_UTIL.log_message(''snap raw geometry ''||geo.saumi_id||'' to object ''||geo.saumi_data_id); '||

          'begin select id into nid  from sm.sd_object_geometries '||
            'where data_id = geo.saumi_data_id and '||
            'dictionary_id = '||ri.dictionary_id||' and '||
            'sd_scale_id='||ri.scale_id||' and '||
            'version_date=v_date; '||
          'exception when others then nid:=null; end; '||
          'sm.SDO_UTIL.log_message(''nid = ''||nid); '||

          'if (nid is null) then '||
            'sm.SDO_UTIL.log_message(''object don`t exists INSERTING''); '||
            'select seqSD_OBJECT_GEOMETRIES.nextval into nid from dual; '||
            'INSERT INTO sm.SD_OBJECT_GEOMETRIES '||
            '(ID, DATA_ID, VERSION_DATE,SD_SCALE_ID, ORIGINAL_GEODATA , DICTIONARY_ID, IS_GENERATED) '||
            'VALUES (nid, '||
            'geo.SAUMI_DATA_ID, v_date, '||
            ri.scale_id||', geo.'||
            ri.column_name||', '||
            ri.dictionary_id||', ''N''); '||
          'else '||
            'sm.SDO_UTIL.log_message(''object exists UPDATING''); '||
            'UPDATE sm.SD_OBJECT_GEOMETRIES SET '||
            'DATA_ID = geo.SAUMI_DATA_ID, VERSION_DATE = v_date'||
            ',SD_SCALE_ID = '||ri.scale_id||
            ',ORIGINAL_GEODATA = geo.'||ri.column_name||
            ',DICTIONARY_ID = '||ri.dictionary_id||
            ',IS_GENERATED = ''N'' WHERE ID = nid; '||
          'end if; '||
        'end if; '||

      'end loop; '||
      'end;';
      execute immediate dynamic_pl;
      sm.SDO_UTIL.is_update_bounds:='Y';
      sm.SDO_UTIL.UpdateBoundsMetadata;
    exception
      when others then begin
        sm.SDO_UTIL.is_update_bounds:='Y';
        sm.SDO_UTIL.UpdateBoundsMetadata;
      end;
    end;
  end;

  procedure raise_not_object_exception is
  begin
     raise_application_error(-20111, 'Для геометрии не существует объекта');
  end;
  
  function move(geom in mdsys.sdo_geometry, move_x in number, move_y in number) return mdsys.sdo_geometry
  is
      geom2 mdsys.sdo_geometry;
      i number;
  begin
      if geom.SDO_GTYPE<>2003 then
          return geom;
      end if;
      
      geom2 := geom;
      if geom2.SDO_POINT is not null then
          geom2.SDO_POINT.X := geom2.SDO_POINT.X+move_x;
          geom2.SDO_POINT.Y := geom2.SDO_POINT.Y+move_y;
      end if;
      
      i:=1;
      while i<=geom2.SDO_ORDINATES.count loop
          geom2.SDO_ORDINATES(i) := geom2.SDO_ORDINATES(i)+move_x;
          i:=i+2;
      end loop;
      i:=2;
      while i<=geom2.SDO_ORDINATES.count loop
          geom2.SDO_ORDINATES(i) := geom2.SDO_ORDINATES(i)+move_y;
          i:=i+2;
      end loop;
      
      return geom2;
  end;
  
  function scale(geom in mdsys.sdo_geometry, scale_x in number, scale_y in number) return mdsys.sdo_geometry
  is
      geom2 mdsys.sdo_geometry;
      i number;
  begin
      if geom.SDO_GTYPE<>2003 then
          return geom;
      end if;
      
      geom2 := geom;
      if geom2.SDO_POINT is not null then
          geom2.SDO_POINT.X := geom2.SDO_POINT.X*scale_x;
          geom2.SDO_POINT.Y := geom2.SDO_POINT.Y*scale_y;
      end if;
      
      i:=1;
      while i<=geom2.SDO_ORDINATES.count loop
          geom2.SDO_ORDINATES(i) := geom2.SDO_ORDINATES(i)*scale_x;
          i:=i+2;
      end loop;
      i:=2;
      while i<=geom2.SDO_ORDINATES.count loop
          geom2.SDO_ORDINATES(i) := geom2.SDO_ORDINATES(i)*scale_y;
          i:=i+2;
      end loop;
      
      return geom2;
  end;
end;
/
grant execute on SM.SDO_UTIL to SM_ALLUSERS;
grant execute on SM.SDO_UTIL to SM_ALL_SELECT;


prompt
prompt Creating package body SHARESVALUE_PKG
prompt =====================================
prompt
create or replace package body sm.SharesValue_PKG is
----------------------------------------------------------------------------------------------------------------------------------------------------------------
Function GetSharesNumberSum(OperSharesID IN NUMBER, CalcDate IN DATE) RETURN NUMBER
--Возвращает сумму уже распределенных акций эмиссии OperSharesID на дату CalcDate
IS
  d DATE;
  nResultValue number(27,6);
  rowOpershares sm.opershares%rowtype;
begin
     select op.* into rowOpershares from sm.opershares op where op.id=OperSharesID;
     d:=trunc(CalcDate);
     -- сумма уже распределенных акций данной эмиссии на момент d
      select nvl(sum(st.sharesnumber),0) into nResultValue
      from sm.states st
      where
            st.objects_id in
                          (select osh.objects_id from sm.objshares osh
                           where
                                osh.opershares_id=rowOpershares.id and
                                osh.owner_id<>rowOpershares.organisations_id)
            and st.calcdate <=
                           (select max(xst.calcdate) from sm.states xst
                            where
                                 xst.objects_id=st.objects_id and xst.calcdate <= d);
 return nResultValue;
end;


Function GetIssuerSharesNumberSum(OperSharesID IN NUMBER, CalcDate IN DATE) RETURN NUMBER
--Возвращает сумму акций эмиссии OperSharesID в собственности эмитента на дату CalcDate
IS
  d DATE;
  nResultValue number(27,6);
  rowOpershares sm.opershares%rowtype;
begin
     select op.* into rowOpershares from sm.opershares op where op.id=OperSharesID;
     d:=trunc(CalcDate);
     -- сумма акций данной эмиссии в собственности эмитента на момент d
      select nvl(sum(st.sharesnumber),0) into nResultValue
      from sm.states st
      where
            st.objects_id in
                          (select osh.objects_id from sm.objshares osh
                           where
                                osh.opershares_id=rowOpershares.id and
                                osh.owner_id=rowOpershares.organisations_id)
            and st.calcdate <=
                           (select max(xst.calcdate) from sm.states xst
                            where
                                 xst.objects_id=st.objects_id and xst.calcdate <= d);
 return nResultValue;
end;


Function GetSharesAmountSum(OrgID IN NUMBER, CalcDate IN DATE) RETURN NUMBER
--Возвращает сумму уже распределенных долей ЮЛ на дату CalcDate
IS
  d DATE;
  nResultValue number(27,6);
begin
        d:=trunc(CalcDate);
        select nvl(sum(st.Amount),0) into nResultValue
        from sm.states st
        where
              st.objects_id in
                            (select osh.objects_id from sm.objshares osh
                             where
                                  osh.organisations_id=OrgID and
                                  osh.owner_id<>OrgID)
              and st.calcdate <=
                             (select max(xst.calcdate) from sm.states xst
                              where
                                   xst.objects_id=st.objects_id and xst.calcdate <= d);
 return nResultValue;
end;


Function GetSharesValue(ObjID IN NUMBER, SharesNumber IN NUMBER) RETURN NUMBER
-- Функция рассчитывает и возвращает размер доли в рублях исходя из количества акций объекта ObjID
--Параметры:
--  ObjSharesID - ID объекта "Пакеты акций, доли в капитале";
--  SharesNumber - количество акций;
is
  nResultValue number(27,6);
  rowObjshares sm.objshares%rowtype;
  nNominal number(27,2);
  iTmp integer;
begin
  select count(*)
         into iTmp
         from sm.objshares osh, sm.organisations org, sm.orgforms f
         where org.id=osh.organisations_id and f.id=org.orgform and f.is_jsc='Y' and osh.objects_id=ObjID;
  if (iTmp > 0) then
      select osh.* into rowObjshares from sm.objshares osh where osh.objects_id=ObjID;
      select (case when op.currency_id=1 then op.nominal else round(op.nominalcost/op.amount, 2) end)
               into nNominal
               from sm.opershares op
               where op.id=rowObjshares.Opershares_Id;
      nResultValue := round(SharesNumber * nNominal, 2);
  end if;

  return nResultValue;
end;


Function GetSharesNominalCost(ObjID IN NUMBER, Amount IN NUMBER, CalcDate IN DATE) RETURN NUMBER
-- Функция рассчитывает и возвращает размер доли в рублях на дату CalcDate исходя из размера доли в процентах в капитале ЮЛ OrgID
--Параметры:
--  ObjSharesID - ID объекта "Пакеты акций, доли в капитале";
--  Amount - размер доли в процентах;
--  CalcDate - дата;
is
  d DATE;
  nResultValue number(27,2);
  rowObjshares sm.objshares%rowtype;
  nCost number(27,2);
  iTmp integer;
begin
  select count(*)
         into iTmp
         from sm.objshares osh, sm.organisations org, sm.orgforms f
         where org.id=osh.organisations_id and f.id=org.orgform and f.hasauthcapital='Y' and f.is_jsc='N' and osh.objects_id=ObjID;
  if (iTmp > 0) then
      select osh.* into rowObjshares from sm.objshares osh where osh.objects_id=ObjID;
      d:=trunc(CalcDate);
      --размер уставного капитала, руб на заданную дату
      nCost := SM.OrgState_And_Share_PKG.GetOrgStateValue(rowObjshares.Organisations_Id, d, 'C');
      if (nvl(nCost, 0) <> 0) then
        --доля в уст. капитале хоз.общества (руб)
        nResultValue := round(nCost * Amount / 100, 2);
      end if;
  end if;

  return nResultValue;
end;
----------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------
end; -- пакета SharesValue_PKG
/
grant execute on SM.SHARESVALUE_PKG to SM_ALLUSERS;
grant execute on SM.SHARESVALUE_PKG to SM_ALL_SELECT;


