prompt
prompt Creating package body UPDATE_DB_PKG
prompt ===================================
prompt
create or replace package body sm.UPDATE_DB_PKG is

  cur_hdl NUMBER;
  rows_processed NUMBER;
  i NUMBER;

  ----------------------------------------------------------------

  function GetMaxID(ATableName in varchar2) return number is
    Result number;
    str varchar2(400);
  begin

    str:='select nvl(max(id),0)from '||ATableName;
    cur_hdl := DBMS_SQL.OPEN_CURSOR;

    DBMS_SQL.PARSE( cur_hdl,str, DBMS_SQL.NATIVE);
    DBMS_SQL.define_column(cur_hdl,1,Result);
    rows_processed := dbms_sql.execute(cur_hdl);
    if DBMS_SQL.fetch_rows(cur_hdl)=0 then
      return(0);
    end if;
    DBMS_SQL.column_value(cur_hdl,1,Result);

    DBMS_SQL.CLOSE_CURSOR(cur_hdl);

    return(Result);

  end;
  ----------------------------------------------------------------

  procedure DoSQL(ASQLtext IN VARCHAR2) is
  begin

    cur_hdl := DBMS_SQL.OPEN_CURSOR;
      DBMS_SQL.PARSE( cur_hdl, ASQLtext, DBMS_SQL.NATIVE);
      rows_processed := dbms_sql.execute(cur_hdl);
    DBMS_SQL.CLOSE_CURSOR(cur_hdl);

  end;

  -----------------------------------------------------------------

  procedure DisableTriggers(ATableName IN VARCHAR2) is
  begin

    TriggerNames:=emptyTable;


    for xx in (select tr.trigger_name TRNAME
                 from all_triggers tr
                where tr.owner='SM'
                  and tr.table_name=Upper(ATableName)
                  and tr.status='ENABLED')
    loop
      update_db_pkg.DoSQL('alter trigger '||xx.TRNAME||' disable');
      TriggerNames(TriggerNames.count+1):=xx.TRNAME;
    end loop;

  end;

  -----------------------------------------------------------------

  procedure EnableTriggers is
  begin

    if TriggerNames.count<>0 then

      for i in 1..TriggerNames.count
      loop
        update_db_pkg.DoSQL('alter trigger '||TriggerNames(i)||' enable');
      end loop;

    end if;

    TriggerNames:=emptyTable;

  end;

  -----------------------------------------------------------------
  
  procedure DisableConstraints(ATableName in varchar2) is
  begin
  
    ConstraintNames:=emptyTable;


    for xx in (select ac.constraint_name CSNAME
                 from all_constraints ac
                where ac.owner = 'SM' 
                  and ac.table_name = Upper(ATableName) 
                  and ac.constraint_name not in (select a.R_constraint_name
                                                   from all_constraints a
                                                  where a.owner = 'SM' 
                                                    and a.Constraint_Type = 'R' 
                                                    and a.table_name <> Upper(ATableName)))
    loop
      update_db_pkg.DoSQL('alter table '||ATableName||' disable constraint '||xx.CSNAME);
      ConstraintNames(ConstraintNames.count+1):=xx.CSNAME;
    end loop;
    
  end;
  
  -----------------------------------------------------------------
  
  procedure EnableConstraints(ATableName in varchar2) is
  begin
  
    if ConstraintNames.count<>0 then

      for i in 1..ConstraintNames.count
      loop
        update_db_pkg.DoSQL('alter table '||ATableName||' enable constraint '||ConstraintNames(i));
      end loop;

    end if;

    ConstraintNames:=emptyTable;
    
  end;
  
  -----------------------------------------------------------------
  
  procedure PutFindChecks (ATable_Name varchar2, 
                           AColumn_name varchar2,
                           AHistory char,
                           ASearch_part char,
                           ASearch_full char,
                           AFromList char ) is
    col_index number;                      
    cursor ftc_rows(ATable_name varchar2, AColumn_name varchar2) is
      select ftc.* 
      from 
        sm.fm_tab_columns ftc, 
        sm.fm_tables ft
      where 
        ftc.fm_tables_id=ft.id and
        ft.table_name=ATable_name and
        ftc.columns_id=(
                        select c.column_id 
                        from 
                          all_tab_columns c 
                        where 
                          c.OWNER='SM' and c.TABLE_NAME=ATable_name and 
                          c.column_name=AColumn_name
                        );
                        
     cur_ftc_row ftc_rows%rowtype;
     TID number;
  begin
  
    open ftc_rows(ATable_Name,AColumn_name);
    fetch ftc_rows into cur_ftc_row;
    if ftc_rows%notfound then
      for xx in (select c.column_id 
                 from 
                   all_tab_columns c 
                 where 
                 c.OWNER='SM' and c.TABLE_NAME=ATable_name and 
                 c.column_name=AColumn_name)
      loop  
      
        select ft.ID into TID from sm.fm_tables ft where ft.table_name=ATable_name;
        insert into sm.fm_tab_columns (id,fm_tables_id,columns_id,search_part,search_full,history,from_list) 
          values (sm.seqfm_tab_columns.nextval,TID,xx.column_id,ASearch_part,ASearch_full, AHistory, AFromList);
        
      end loop;
    else
      update sm.fm_tab_columns f 
      set 
        f.search_part=ASearch_part, 
        f.search_full=ASearch_full,
        f.history=AHistory,
        f.from_list=AFromList 
      where f.fm_tables_id=cur_ftc_row.fm_tables_id and f.columns_id=cur_ftc_row.columns_id;
    end if;
    close ftc_rows;
    commit;
    
  end PutFindChecks;
  
  -----------------------------------------------------------------
  function CheckExistance(
                          AType varchar2,        
                          AName varchar2,
                          DropIfExists boolean:=false
                         ) return boolean is
  cnt number;
  begin
    
    select count(*)
    into cnt
    from
      all_objects ao
    where
      ao.owner='SM' and
      ao.Object_Type=Upper(AType) and   
      ao.object_name=Upper(AName);
    
    if cnt<>0 then
      if DropIfExists then
        -- не даём удалить таблицу, если она прописана в FM_TABLES
        if Upper(AType)='TABLE' then
          select count(*)
          into cnt
          from
            sm.fm_tables ft
          where
            ft.table_name=Upper(AName);
            
          if cnt<>0 then
            return(true);
          end if;     
        end if;
        
        execute immediate ('drop '||AType||' SM.'||AName);
        return(false);
      end if;
      
      return(true);
    else
      return(false);  
    end if;
        
  end;
  -----------------------------------------------------------------
begin
  TriggerNames:=emptyTable;
  ConstraintNames:=emptyTable;
end UPDATE_DB_PKG;
/
grant execute on SM.UPDATE_DB_PKG to SM_ALLUSERS;
grant execute on SM.UPDATE_DB_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body VER_FILES_MD5_PKG
prompt =======================================
prompt
create or replace package body sm.ver_files_md5_pkg is

  --
  -- Пересчет MD5 для тех файлов у которых md5 еще не посчитан
  --
  procedure recalc_ver_files_md5 as
  begin
    update SM.VER_FILES f set f.MD5HASH = sys.dbms_crypto.Hash(f.filebody,2), f.FILESIZE = sys.dbms_lob.getlength(nvl(f.filebody,empty_blob()))
      where (f.MD5HASH is null) and (f.FILEBODY is not null);

    commit;
  end;
end;
/
grant execute on SM.VER_FILES_MD5_PKG to SM_ALLUSERS;
grant execute on SM.VER_FILES_MD5_PKG to SM_ALL_SELECT;


prompt
prompt Creating package body XMLROSREESTR_PKG
prompt ======================================
prompt
create or replace package body sm.xmlRosreestr_pkg is

function CheckStates(ObjectID number, VDate varchar2, UseEndStates number default 0) return number
is
States_Date date;
ReportDate date;
cnt number;
retval number(27);
begin
  begin
     States_Date:=to_date(VDate, 'dd.mm.YYYY');
  exception
    when others then States_Date:='';
  end;

  --проверяем наличие состояния
  select count(*)
  into cnt
  from sm.states s
  where s.objects_id=ObjectID
  and s.calcdate=States_Date
  and  (s.cadastralvalue is not null or s.kadastr_cost is not null);

  if cnt=0 then
      if UseEndStates=1 then
         --запрашиваем последнее известное состояние
         select max(s.calcdate)
         into ReportDate
         from sm.states s
         where s.objects_id=ObjectID
         and (s.cadastralvalue is not null or s.kadastr_cost is not null)
         and s.calcdate<=States_Date;
         
         if ReportDate is not null then
                  --
                  select max(doc.id)
                  into retval
                  from sm.docset_members dm,
                  sm.documents doc
                  where dm.docrole_id=1
                  and dm.document_id=doc.id
                  and dm.docset_id=
                  (select s.documents_id
                  from sm.states s
                  where s.objects_id=ObjectID
                  and s.calcdate=ReportDate
                  and  (s.cadastralvalue is not null or s.kadastr_cost is not null));
                   --
                  return(retval);
           else return(-7); --вообще нет стоимости
         end if;
      else
         return(-1);
      end if;
  else
   --
  select doc.id
  into retval
  from sm.docset_members dm,
  sm.documents doc
  where dm.docrole_id=1
  and dm.document_id=doc.id
  and dm.docset_id=
  (select s.documents_id
  from sm.states s
  where s.objects_id=ObjectID
  and s.calcdate=States_Date
  and  (s.cadastralvalue is not null or s.kadastr_cost is not null));
   --
  return(retval);
  end if;

exception
when others then return(-1);
end;
--------------------------------------------------------------------------
function GetMaxStates(ObjectID number) return varchar2
is
retval varchar2(10);
begin
 select max(calcdate)
 into retval
 from sm.states s
 where s.objects_id=ObjectID and
 (s.cadastralvalue is not null or s.kadastr_cost is not null);

return(To_char(retval));
exception
  when others then return(-1);
end;
--------------------------------------------------------------------------------
function GetKadastrStruct(ObjectID in number, key_pars char, usetabchar char default 'Y') return varchar2
is

  v_kadastrNo varchar2(50);
  v_Fed_no varchar2(2);
  v_Reg_no varchar2(2);
  v_Quart_no varchar2(7);
  Obj_types number(27);

begin
  select o.objtypes_id
  into Obj_types
  from sm.objects o
  where o.id=ObjectID;


  --если земельный участок
  if Obj_types=7 then

      select g.kadastrno
      into v_kadastrNo
      from sm.grounds g
      where g.objects_id=ObjectID;
  end if;

  --здания
  if Obj_types=3 then
      select b.kadastrno
      into v_kadastrNo
      from sm.buildings b
      where b.objects_id=ObjectID;
  end if;


  --незавершенка
    if Obj_types=4 then
      select u.kadastrno
      into v_kadastrNo
      from sm.unconstr u
      where u.objects_id=ObjectID;
  end if;

    --инженерка
    if Obj_types=4 then
      select e.kadastrno
      into v_kadastrNo
      from sm.enginf e
      where e.objects_id=ObjectID;
  end if;


  if trim(v_kadastrNo) is null then return(''); end if;

  v_kadastrNo:=trim(regexp_replace(REGEXP_REPLACE(v_kadastrNo,':'),' '));

  --кадастровый оруг
  v_Fed_no:=substr(v_kadastrNo,1,2);
    if key_pars='F' then
       return(v_Fed_no);
    end if;

  --кадастровый район
  v_Reg_no:=substr(v_kadastrNo,3,2);
   if key_pars='R' and v_Reg_no is not null then
       if usetabchar='Y' then return(v_Fed_no||':'||v_Reg_no); end if;
       if usetabchar='N' then return(v_Fed_no||v_Reg_no); end if;
   end if;

  --кадастровый квартал
  v_Quart_no:=substr(v_kadastrNo,5,7);

   if key_pars='Q' and v_Reg_no is not null and  v_Quart_no is not null then
     if usetabchar='Y' then    return(v_Fed_no||':'||v_Reg_no||':'||v_Quart_no);  end if;
     if usetabchar='N' then    return(v_Fed_no||v_Reg_no||v_Quart_no);  end if;
   end if;

  --кадастровый номер

  v_kadastrNo:=replace(v_kadastrNo,v_Fed_no||v_Reg_no||v_Quart_no);
  if key_pars='N' and v_Reg_no is not null and  v_Quart_no is not null and v_kadastrNo is not null  then

     if usetabchar='Y' then return(v_Fed_no||':'||v_Reg_no||':'||v_Quart_no||':'||v_kadastrNo); end if;
     if usetabchar='N' then return(v_Fed_no||v_Reg_no||v_Quart_no||v_kadastrNo); end if;
  end if;

   return('');
end;

---------------------------------------------------------------------------
procedure InsertDictEl(v_TableName varchar2, v_DictName varchar2, v_code varchar2, v_root_code varchar2)
is
seqval number;
cont number;
rootID number;
begin
  --проверяем, существует ли значение в справочнике
  execute immediate ' select count(*) from sm.'||v_TableName||' where Code='''||v_code||'''' into cont;
     if cont=0 then
     --добавляем новый элемент в справочник
     execute immediate ' select sm.seq'||v_TableName||'.nextval from dual' into seqval;



        if v_root_code is null then
            execute immediate ' insert into sm.'||v_TableName||' (id, name, code) values ('||seqval||', '''||v_DictName ||''', '''||v_code||''')';
        else
            --определяем ид главного элемента
             execute immediate ' select ID from sm.'||v_TableName||' where Code='''||v_root_code||'''' into rootID;
             if rootID is not null then
                execute immediate ' insert into sm.'||v_TableName||' (id, name, code, root) values ('||seqval||', '''||v_DictName ||''', '''||v_code||''','||rootID||')';
             end if;
        end if;
    -- end if;

     end if;


exception
  when others then raise_application_error(-20101,SQLERRM);
end;
-------------------------------------------------------------------------------------------
function GetNameFile(typefile number, v_reportDate string, ObjID number, v_lavel char) return varchar2
is
--i number;
cnt number;
kadastrNo varchar2(50);
retval varchar2(50);
begin
 if typefile is null then return(''); end if;

 if v_reportDate is null then return(''); end if;

 if typefile=3 then
          --получаем кадастровый номер
      begin
      
       if v_lavel='Q' then
          kadastrNo:=GetKadastrStruct(ObjID,'Q','N');
       end if;

       if v_lavel='D' then
          kadastrNo:=GetKadastrStruct(ObjID,'R','N');
       end if;
      exception
        when others then kadastrNo:='';
      end;

       --  if kadastrNo is null then   end if;

       --порядковый номер для файлан на дату
         select count(*)
         into cnt
         from sm.xmlrr_files f
         where f.filetype=typefile
         and to_char(f.date_create,'dd.mm.YYYY')=v_reportDate;


         retval:=kadastrNo||'_'||
               substr(v_reportDate,1,1)||
               substr(v_reportDate,2,1)||
               substr(v_reportDate,4,1)||
               substr(v_reportDate,5,1)||
               substr(v_reportDate,7,1)||
               substr(v_reportDate,8,1)||
               substr(v_reportDate,9,1)||
               substr(v_reportDate,10,1)||
           '_'||to_char(cnt+1,'FM0000');
        return(retval);
 end if;
 if typefile=5 then
         select count(*)
         into cnt
         from sm.xmlrr_files f
         where f.filetype=typefile
         and to_char(f.date_create,'dd.mm.YYYY')=v_reportDate;


         retval:=to_char(cnt+1,'FM0000');
        return(retval);
 end if;

return('');
exception
  when others then return('');
end;
---------------------------------------------------------------------
function ParsHouse(object_id number) return varchar2
is
n_house number(27);
liter_house varchar2(23);
n_liter number(27);
retval varchar2(50);
begin
  select a.house, a.house_char
  into n_house, liter_house
  from sm.objects o,
  sm.address a
  where o.id=object_id
  and o.address_id=a.id;

      begin
       n_liter:=To_Number(liter_house);
       if n_liter is not null then
       retval:=n_house||'/'||n_liter;
       else
       retval:=n_house;
       end if;
       return(retval);

      exception
        when others then null;
      end;
--n_house:=null;
retval:=n_house|| liter_house;
return(retval);

exception
  when others then return('');
end;

-------------------------------------------------------------------------
function CheckObjType(ObjectID number) return number
is
objtype number(27);
GroundTypeID number(27);
RootID number(27);
GrounTypeName varchar2(400);
CurID number(27);
begin
   select o.objtypes_id
   into objtype
   from sm.objects o
   where o.id=ObjectID;

   --земельный участок
  if objtype=7 then
      --определяет категрию зу
      select g.groundtypes_id
      into GroundTypeID
      from sm.grounds g
      where g.objects_id=ObjectID;


      select  gt.name, gt.root
      into GrounTypeName, RootID
      from sm.groundtypes gt
      where gt.id=GroundTypeID;

     WHILE (RootID is not null)
     loop
      CurID:=RootID;
          select gt.name, gt.root
          into GrounTypeName, RootID
          from sm.groundtypes gt
          where gt.id=CurID;
     end loop;

    if (trim(GrounTypeName)='ЗЕМЛИ СЕЛЬСКОХОЗЯЙСТВЕННОГО НАЗНАЧЕНИЯ')then return(1); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ СЕЛЬСКОХОЗЯЙСТВЕННОГО НАЗНАЧЕНИЯ')  then return(2); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ НАСЕЛЁННЫХ ПУНКТОВ')  then return(3); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ ПРОМЫШЛЕННОСТИ, ЭНЕРГЕТИКИ, ТРАНСПОРТА, СВЯЗИ, РАДИОВЕЩАНИЯ, ТЕЛЕВИДЕНИЯ, ИНФОРМАТИКИ, ЗЕМЛИ ДЛЯ ОБЕСПЕЧЕНИЯ КОСМИЧЕСКОЙ ДЕЯТЕЛЬНОСТИ, ЗЕМЛИ ОБОРОНЫ, БЕЗОПАСНОСТИ И ЗЕМЛМ ИНОГО СПЕЦИАЛЬНОГО НАЗНАЧЕНИЯ')  then return(4); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ ОСОБООХРАНЯЕМЫХ ТЕРРИТОРИЙ И ОБЪЕКТОВ')  then return(5); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ ЛЕСНОГО ФОНДА')  then return(6); end if;
    if (trim(GrounTypeName)='ЗЕМЛИ ВОДНОГО ФОНДА')  then return(7); end if;
    --if (trim(GrounTypeName)='ЗЕМЛИ НАСЕЛЁННЫХ ПУНКТОВ')  then return(8); end if;

   end if;
return(-1);
exception
  when others then return(-1);
end;
--------------------------------------------------------------------------------------------
