   for i in (select ch.name
             from sm.xmlrr_changes xch,
             sm.xmlrr_curchanges ch
             where xch.xmlrr_curchange_id=ch.id and
             xch.object_id=ObjID and
             to_date(xch.activation_date,'dd.mm.yyyy') between beginDate and endDate)
             
        loop
           begin
        
            retval:=retval||i.name||', ';       
