prompt
prompt Creating trigger ADDRESS_UPDOBJ
prompt ===============================
prompt
create or replace trigger "SM".ADDRESS_UPDOBJ
  after update on sm.address 
   -- заставляем измениться поле DISCRIPTION таблицы sm.OBJECTS при изменении адреса


declare
  i number;
  cur_ number;
  rows_processed number;   
begin
  if addr_state_pkg.skip_trigger is null then 
    if addr_state_pkg.updRows.count>0 then
     cur_:=DBMS_SQL.OPEN_CURSOR;
     for i in 1..addr_state_pkg.updRows.count
     loop
       for xx in(   
         select 
          'UPDATE  sm.'||c.TABLE_NAME||' set ID=ID  where '||c.COLUMN_NAME||'=:ADDRID' as SQL_txt
         from all_cons_columns c
         where  TABLE_NAME IN (select TABLE_NAME
                               from all_cons_columns c1
                               where c1.constraint_name IN (
                                 select constraint_name
                                 from all_constraints
                                 where R_CONSTRAINT_NAME=
                                      (select constraint_name
                                       from all_constraints
                                       where TABLE_NAME='ADDRESS' and
                                       CONSTRAINT_TYPE='P' and OWNER='SM'))and c1.OWNER='SM'
                                       minus
                                       select 'CLIENTS' from dual
                                       minus
                                       select 'ADDRESS' from dual) and
                 c.constraint_name IN (select ac.constraint_name
                                       from all_constraints ac
                                       where ac.R_CONSTRAINT_NAME=
                                       (select ac1.constraint_name
                                        from all_constraints ac1
                                        where ac1.TABLE_NAME='ADDRESS' and
                                       ac1.CONSTRAINT_TYPE='P' and ac1.OWNER='SM'))and c.OWNER='SM'
                 )
     loop
       DBMS_SQL.PARSE( cur_,xx.sql_txt, DBMS_SQL.NATIVE);
       DBMS_SQL.BIND_VARIABLE(cur_, ':ADDRID', addr_state_pkg.updRows(i)); -- привязка переменных
       rows_processed := dbms_sql.execute(cur_);
     end loop; 
  
      end loop;
      DBMS_SQL.CLOSE_CURSOR(cur_);
    end if;
  end if; --if skip_trigger is null

end;
/

prompt
prompt Creating trigger ADDRESS_XMLRR_SAVECHANGES
prompt ==========================================
prompt
create or replace trigger "SM".ADDRESS_XMLRR_SAVECHANGES
after  update on sm.address
FOR EACH ROW
declare
ObjTypeID number(27);
ObjectID number(27);
ChangeID number(27);
--ClientID number(27);
tblID number(27);
UserName varchar2(150);
begin

--Изменение собственного адреса объекта недвижимости

begin
    select o.objtypes_id, o.id
    into ObjTypeID, ObjectID
    from sm.objects o
    where o.address_id=:new.id;
exception
   when others then null;
end;

  

    if ObjTypeID in (3,4,5,7,22) then
           
           tblID:=sm.xmlrosreestr_pkg.GetTableID('ADDRESS');
               if nvl(tblID,-1)<>-1 then
                   select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
                   
                     --Изменение номера дома
                     if ((:new.house<>:old.house) or
                        (:new.house is not null and :old.house is null) or
                        (:new.house is null and :old.house is not null))
                     then
                        if ChangeID is null then 
                           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
                           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
                           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284004000000'), sysdate, UserName, 'U',tblID,ObjectID);
                        end if;
                        
                        insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
                        values( sm.seqxmlrr_changes_log.nextval, ChangeID, 2,:old.house, :new.house);
                     end if;


                       --Изменение номера квартиры
                     if ((:new.appartment<>:old.appartment) or
                        (:new.appartment is not null and :old.appartment is null) or
                        (:new.appartment is null and :old.appartment is not null))
                     then
                      if ChangeID is null then 
                           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
                           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
                           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284004000000'), sysdate, UserName, 'U',tblID,ObjectID);
                        end if;
                        insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
