                        values( sm.seqxmlrr_changes_log.nextval, ChangeID,10,:old.addon, :new.addon);
                     end if;
                     
                     

              end if;

    end if;
 



exception
 when others then null;
end ADDRESS_XMLRR_SAVECHANGES;
/

prompt
prompt Creating trigger AFTER_INS_UPD_DEL_SD3_OG
prompt =========================================
prompt
CREATE OR REPLACE TRIGGER "SM".AFTER_INS_UPD_DEL_SD3_OG
  after insert or update or delete on sm.sd3_og_original
declare   
  prev_og sm.sd3_og_original%ROWTYPE;
  i number;
  current_rev_seq number;
  update_rev_seq boolean;
  last_date date;
begin
  if sm.sd3_utils.stop_triggers = 1 then
      return;
  end if;
  --
  -- Синхронизация сроков существования геометрий
  --  
  sm.sd3_utils.stop_triggers := 1;
  if sm.sd3_utils.GEOMETRY_METADATA_IDs.count>0 then
    
    -- Возможно нам не придеться обновлять ревизию
    update_rev_seq := false;
    select current_value into current_rev_seq from sm.sd3_geometry_revision_seq for update;
    current_rev_seq:=current_rev_seq+1;

    -- для всех метаданных для которых было изменения
    for i in 1..sm.sd3_utils.GEOMETRY_METADATA_IDs.count
    loop
        
        -- получаем все геометрии связанные с текущими метаданными
        -- отсортированные по дате
        prev_og.id := null;
        for og in (select * from sm.sd3_og_original t
                     where t.sd3_geometry_metadata_id=sm.sd3_utils.GEOMETRY_METADATA_IDs(i)
                     order by t.begin_date)
        loop
            
            -- обрабатывается предыдущая геометрия
            if prev_og.id is not null then
            
                -- Дата завершения существования берется от даты начала существования текущей геометрии
                prev_og.end_date := og.begin_date-1;
                if prev_og.begin_date>=prev_og.end_date then
                  raise_application_error(-20101, 'Нарушение времени существования геометрии #'||prev_og.id);
                end if;
                
                -- Будем обновлять ревизию
                -- и обновляемя сроки существоания предыдущей геометрии и таблице
                update_rev_seq := true;
                update sm.sd3_og_original set end_date=prev_og.end_date where id=prev_og.id;
            end if;
            prev_og:=og;
        end loop;
        
        -- У последней геометрии дата завершения пустая, т.е. никогда
        -- не завершается
        if (prev_og.id is not null) then
            begin
                select o.exists_end into last_date
                from sm.objects o, sm.sd3_geometry_metadata m
                where m.data_id=o.id and m.type_id=1 and m.id=sm.sd3_utils.GEOMETRY_METADATA_IDs(i);
            exception
                when OTHERS then
                    last_date := null;
            end;
        
            if last_date<=prev_og.begin_date then
                last_date := null;
            end if;
            
            update_rev_seq := true;
            update sm.sd3_og_original set end_date=last_date where id=prev_og.id;
        end if;

        -- Если будем обновлять ревизию то обновляем ее
        if update_rev_seq then
          update sm.sd3_geometry_revision set revision_number = current_rev_seq where sd3_geometry_metadata_id = sm.sd3_utils.GEOMETRY_METADATA_IDs(i);
        end if;
    end loop;
    
    -- Если не надо обвнолять ревизию то уменьшаем на единицу
    if not update_rev_seq then
      current_rev_seq:=current_rev_seq-1;
    end if;
    
    --вставляем новый номер ревизии в sd3_geometry_revision_seq
    update sm.sd3_geometry_revision_seq set current_value = current_rev_seq;
    
  end if;
  sm.sd3_utils.stop_triggers := 0;
exception
  when others then
  begin
    --снимаем блокировку на триггеры
    sm.sd3_utils.stop_triggers := 0;
    raise;
  end;
     
end;
/

prompt
prompt Creating trigger ATO_OBJ
prompt ========================
prompt
CREATE OR REPLACE TRIGGER "SM".ATO_Obj AFTER UPDATE OR INSERT ON sm.ATO FOR EACH ROW
--
-- by XSGROUP ver.24.09.2009
-- триггер формирует описание Административно-территориального образования в таблице CLIENTS
--
Declare
  S1 ATO.NAME%type;
  SmallInfo sm.Clients.Name%type;
  Cl_col_length number;
Begin

  select att.data_length 
  into Cl_col_length
  from all_tab_columns att 
  where 
   att.owner='SM' and 
   att.table_name='CLIENTS' and
   att.column_name='NAME';
   
  S1 := RTRIM(LTRIM(:new.Name));
  if Length(S1)>Cl_col_length then
    S1:=SUBSTR(S1,1,Cl_col_length-2)||'..';
  end if;  
 
  SmallInfo :=S1;
  
  UPDATE Clients 
  SET 
    Name = SmallInfo
  WHERE 
    ID=:new.Clients_ID;
  
End;
/

