prompt
prompt Creating trigger BUILDINGS_AFTER_OBJPKG
prompt =======================================
prompt
CREATE OR REPLACE TRIGGER "SM".BUILDINGS_AFTER_OBJPKG
  after insert on sm.buildings
declare
  --редакция v. 4.8.5 (04.03.2015)
  --Purpose: Для зданий и помещений производим корректировку сроков существования объетка с проверкой на ОД

root_since date; --дата начала существования контейнера ЗУ
root_end date; --дата окончания существования контейнера ЗУ
--
root_SINCE_DATE DATE;  --дата начала срока существования владельца данного объекта
root_END_DATE DATE;    --дата окончания срока существования владельца данного объекта
cntMoves INTEGER;      --количество зарегистрированных движений
cntChild INTEGER;      --количество дочерних объектов
oldEXISTS_SINCE date;
oldEXISTS_END date;
begin
 for i in 1 .. sm.obj_pkg.BuildingExDateRows.count loop --LOOP 1 читаем данные из bld_state_pkg 
  for new in (select b.BASEBUILDING, o.exists_since, o.exists_end
              from sm.buildings b,
                   sm.objects o
              where o.id=b.objects_id and
              o.id=sm.obj_pkg.BuildingExDateRows(i)) loop --LOOP2
   oldEXISTS_SINCE:=null;
   oldEXISTS_END:=null;

  IF ((nvl(oldEXISTS_SINCE,TO_DATE('01-01-1000','dd-mm-yyyy'))<>nvl(new.EXISTS_SINCE, TO_DATE('01-01-1000','dd-mm-yyyy')))and(new.EXISTS_SINCE IS NOT NULL))
     or
     ((nvl(oldEXISTS_END,TO_DATE('01-01-1000','dd-mm-yyyy'))<>nvl(new.EXISTS_END, TO_DATE('01-01-1000','dd-mm-yyyy')))and(new.EXISTS_END IS NOT NULL)) THEN--IF2 обработка нужна только, если хотя бы одна из дат меняется

   IF new.BASEBUILDING IS NOT NULL THEN --IF3 если помещение не является помещением верхнего уровня
    root_SINCE_DATE:=null;
    root_END_DATE:= null;

   --ищем установленные даты EXISTS_SINCE и EXISTS_END у объектов верхнего уровня
   SELECT MAX(o.EXISTS_SINCE), MIN(o.EXISTS_END)
   INTO root_SINCE_DATE, root_END_DATE
   FROM sm.Buildings b,
        sm.objects o
   WHERE o.id=b.objects_id
   START WITH b.ID=new.BASEBUILDING CONNECT BY PRIOR BASEBUILDING=b.ID;

    --проверяем, не выходит ли новая дата за пределы допустимого
    IF (root_SINCE_DATE IS NOT NULL) THEN --IF4
     IF (root_SINCE_DATE>new.EXISTS_SINCE) THEN --IF5
      raise_application_error(-20101, 'Дата начала срока существования объекта не может быть'||chr(13)
                                    ||'ранее даты начала срока существования объекта верхнего уровня!' );
     END IF; --IF5
    END IF; --IF4
    
    --проверяем, дата начала существования объекта не должна быть позже даты прекращения
    -- существования контейнера.
    IF (root_END_DATE IS NOT NULL) THEN --IF4
     IF (root_END_DATE<new.EXISTS_SINCE) THEN --IF5
      raise_application_error(-20101, 'Дата начала срока существования объекта не может быть'||chr(13)
                                    ||'позже даты окончания срока существования объекта верхнего уровня!' );
     END IF; --IF5
    END IF; --IF4

    IF root_END_DATE IS NOT NULL THEN --IF5
     IF (root_END_DATE<new.EXISTS_END) THEN --IF6
      raise_application_error(-20101, 'Дата окончания срока существования объекта не может быть установлена'||chr(13)
                                    ||'позже даты окончания срока существования объекта верхнего уровня!' );
     END IF; --IF6
    END IF; --IF5
   END IF; --IF3
  END IF; --IF2
  end loop; --LOOP2
 end loop;  --LOOP1
end;
/

prompt
prompt Creating trigger BUILDINGS_CHECKADDRESS
prompt =======================================
prompt
CREATE OR REPLACE TRIGGER "SM".Buildings_CheckAddress BEFORE INSERT ON Buildings FOR EACH ROW

DECLARE
 IsContainer varchar2(1);
 AddrRep integer;
 ObjType integer;
 SS varchar2(4000);
 cur_ number;
 rnum number;
BEGIN
  -- проверяем и не даем регистрировать здания и помещения по
  -- уже регистрированным адресам
  select Objects.Objtypes_Id into ObjType from Objects where ID=:new.Objects_ID;
  if ObjType=3 then
  
    select CONTAINER into IsContainer from BuildTypes where ID=:new.BuildTypes_ID;
    if IsContainer='Y' then -- проверяем только у отдельностоящих
    
      SS:='SELECT * FROM Address a, Address b, Buildings, BuildTypes WHERE a.id=:NewAddrId and b.id != a.id and Buildings.Address_Id=b.id and BuildTypes.Id=Buildings.Buildtypes_Id and BuildTypes.Container=''Y''';
      for xx in (select * from sm.un_buildaddr) 
      loop
        SS:=ConCat(SS, ' and (a.'); SS:=ConCat(SS, xx.name); SS:=ConCat(SS, '=b.'); SS:=ConCat(SS, xx.name);
        SS:=ConCat(SS, ' or  (a.'); SS:=ConCat(SS, xx.name); SS:=ConCat(SS, ' is null and b.');
        SS:=ConCat(SS, xx.name); SS:=ConCat(SS, ' is null))');
      end loop;
  
      AddrRep:=0;
      cur_:=DBMS_SQL.OPEN_CURSOR;
      DBMS_SQL.PARSE( cur_, SS, DBMS_SQL.NATIVE);
      dbms_sql.bind_variable(cur_, ':NewAddrId', :new.Address_id);
      rnum := dbms_sql.execute(cur_);
      rnum := dbms_sql.fetch_rows(cur_);
      AddrRep := dbms_sql.last_row_count;
      DBMS_SQL.CLOSE_CURSOR(cur_);
      
      if AddrRep>0 then
        raise_application_error(-20101, 'Объект верхнего уровня с таким адресом уже существует.');
      end if;
      
    end if; --if IsContainer='Y'
    
  end if; --if ObjType=3

END;
/

prompt
prompt Creating trigger BUILDINGS_CHECKAREA
prompt ====================================
prompt
create or replace trigger "SM".Buildings_CheckArea
  after insert or update of
  SQUARE,  
  BASEBUILDING
  on buildings
-- by XSGROUP Ver. 12.05.2009
-- ver. 4.8.5 (04.03.2015) со сроками существования в табл. Objects
-- проверяем общую плошадь одновременно существующих помещений и не даём зарегистрировать новое помещение
-- если новая суммарная площадь будет превышать площадь уровня

declare

   existsSquare REAL;     -- площадь всех помещений уже зарегистрированных на данном уровне
   rootSquare REAL;       -- максимально возможная площадь уровня
   i INTEGER;
begin

 for i in 1 .. bld_state_pkg.updRows.count loop --LOOP 1 читаем данные из bld_state_pkg
  for new in (select b.BASEBUILDING,b.SQUARE, Upper(bt.is_bti_object) as is_bti_object,
              nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) exists_since,
              nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) exists_end
              from sm.buildtypes bt, sm.Buildings b, sm.objects o 
              where b.Buildtypes_Id=bt.id and b.rowid=bld_state_pkg.updRows(i)
              and o.id=b.objects_id
              ) loop --LOOP2
  IF new.BASEBUILDING IS NOT NULL and (new.SQUARE<999999.00) THEN -- IF2 если помещение не является помещением верхнего уровня, его площадь задана и изменяется
   begin

    IF new.SQUARE=0 THEN --IF13 не даём создать объект с площадью, равной 0 кв.м.
     raise_application_error(-20101, 'Нельзя создать объект, у которого площадь равна 0 кв.м.!' );
    END IF; --13

    IF UPDATING('SQUARE') and not (nvl(new.EXISTS_SINCE, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate and nvl(new.EXISTS_END, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate) THEN
      raise_application_error(-20101, 'Невозможно установить площадь! Объект в настоящее время не существует!' );
    END IF;

-- !!!!!!!!!!  НУЖНА ЛИ ЗДЕСЬ ПРОВЕРКА НА СРОКИ СУЩЕСТВОВАНИЯ ОБЪЕКТА ВЕРХНЕГО УРОВНЯ !!!!!!!!!!
    --rootSquare:=0;
    SELECT SQUARE -- находим общую площадь уровня
    INTO rootSquare
    FROM
     sm.buildings
    WHERE ID=new.BASEBUILDING /*and nvl(b.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<sysdate
      and nvl(b.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>sysdate*/;
    /*if rootSquare=0 then
      raise_application_error(-20101, 'Невозможно установить площадь! Объект расположен на уровне, который в настоящее время не существует!' );
    end if;*/

    -- для не БТИ-объектов проверку делаем на превышение площади уровня
    IF not new.is_bti_object='Y' THEN
      if new.Square>rootSquare then
        raise_application_error(-20101, 'Выделенная площадь превышает площадь уровня, на котором расположена!' );
      end if;
      GOTO quit;
    END IF;

    IF (new.EXISTS_SINCE IS NULL) and (new.EXISTS_END IS NULL) THEN --IF4
    -- в запросе не участвуют даты, поскольку ВСЕ записи данного уровня являются в тот или иной период современниками
     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений данного уровня
     INTO existsSquare
     FROM
      sm.buildings b,
      sm.buildtypes bt,
      sm.objects o
     WHERE
      b.buildtypes_id=bt.id
      and o.id=b.objects_id
      and (b.BASEBUILDING=new.BASEBUILDING)
      and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate
      and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
      and (b.SQUARE<999999.00)-- игнорируем неопределённую площадь
      and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты

    ELSIF (new.EXISTS_SINCE IS NULL) and (new.EXISTS_END IS NOT NULL) THEN

     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений данного уровня
     INTO existsSquare
     FROM
      sm.buildings b,
      sm.buildtypes bt,
      sm.objects o
     WHERE
      b.buildtypes_id=bt.id
      and o.id=b.objects_id
      and (BASEBUILDING=new.BASEBUILDING)
      and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate
      and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
      and (SQUARE<999999.00) -- игнорируем неопределённую площадь
      and not (nvl(o.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')) > nvl(new.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy')))
      and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты


    ELSIF (new.EXISTS_SINCE IS NOT NULL) and (new.EXISTS_END IS NULL) THEN

     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений данного уровня
     INTO existsSquare
     FROM
      sm.buildings b,
      sm.buildtypes bt,
      sm.objects o
     WHERE
      b.buildtypes_id=bt.id
      and o.id=b.objects_id
      and (BASEBUILDING=new.BASEBUILDING)
      and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate
      and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
      and (SQUARE<999999.00) -- игнорируем неопределённую площадь
      and not(nvl(o.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy'))<nvl(new.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')))
      and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты

    ELSIF (new.EXISTS_SINCE IS NOT NULL) and (new.EXISTS_END IS NOT NULL) THEN
     begin
      IF (new.EXISTS_SINCE > new.EXISTS_END) THEN --IF5
       raise_application_error(-20101, 'Дата начала срока существования объекта не может превышать дату конца!' );
      END IF; --IF5
      SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений данного уровня
      INTO existsSquare
      FROM
        sm.buildings b,
        sm.buildtypes bt,
        sm.objects o
      WHERE
        b.buildtypes_id=bt.id
        and o.id=b.objects_id
        and (BASEBUILDING=new.BASEBUILDING)
        and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate
        and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
        and (SQUARE<999999.00) -- игнорируем неопределённую площадь
        and not ((nvl(o.EXISTS_END,To_Date('01-01-3000','dd-mm-yyyy')) < nvl(new.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')))
        or(nvl(o.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')) > nvl(new.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy'))))
        and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты
     end;
    END IF; --IF4
    existsSquare:=existsSquare-new.SQUARE; --надо исключить площадь самого объекта
    IF (rootSquare<999999.00) and ((rootSquare-nvl(existsSquare,0))<new.SQUARE) THEN --IF3
     raise_application_error(-20101, 'Объект не может иметь указанную площадь для указанного срока существования!'|| chr(13) ||'.' );
    END IF; --IF3
    <<quit>>
    null;
   end;
  END IF; --IF2

  end loop; --LOOP2
 end loop;  --LOOP1
end Buidings_CheckArea;
/

prompt
prompt Creating trigger BUILDINGS_CHECKAREA_ROOT
prompt =========================================
prompt
create or replace trigger "SM".BUILDINGS_CHECKAREA_ROOT
  after update of
  SQUARE, 
  BASEBUILDING
  on buildings
-- By XSGROUP 12.05.2009
-- ver. 4.8.5 (04.03.2015) со сроками существования в табл. Objects
-- проверяем общую плошадь одновременно существующих помещений уровнем ниже
-- и не даем изменять площадь, если новая площадь будет меньше площади нижнего уровня
-- на нижнем уровне суммируются только БТИ-объекты
-- для не БТИ-объектов проверку не делаем
declare
   existsSquare REAL;     -- площадь всех зарегистрированных помещений уровнем ниже
   i INTEGER;
begin



 for i in 1 .. bld_state_pkg.updRows.count loop --LOOP 1 читаем данные из bld_state_pkg
  for new in (select b.basebuilding,b.square,b.id, Upper(bt.is_bti_object) as is_bti_object,
              nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) exists_since,
              nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) exists_end
              from sm.buildtypes bt, sm.Buildings b, sm.objects o 
              where o.id=b.objects_id and b.Buildtypes_Id=bt.id and b.rowid=bld_state_pkg.updRows(i) ) loop --LOOP2
  IF new.SQUARE<999999.00 THEN -- IF2
   begin

    IF new.SQUARE=0 THEN --IF13 не даём создать объект с площадью, равной 0 кв.м.
     raise_application_error(-20101, 'Нельзя установить площадь равной 0 кв.м.!' );
    END IF; --13

    -- для не БТИ-объектов проверку не делаем
    IF not new.is_bti_object='Y' THEN
      GOTO quit;
    END IF;
    
    -- если изменяется площадь, а объект не существует на данный момент, то сообщаем это
    IF UPDATING('SQUARE') and not (nvl(new.EXISTS_SINCE, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate and nvl(new.EXISTS_END, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate) THEN
      raise_application_error(-20101, 'Невозможно установить площадь! Объект в настоящее время не существует!' );
    END IF;
 
    IF (new.EXISTS_SINCE IS NULL) and (new.EXISTS_END IS NULL) THEN --IF4
    -- в запросе не участвуют даты, поскольку ВСЕ записи данного уровня являются в тот или иной период современниками
     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений нижнего уровня
     INTO existsSquare
     FROM
      sm.buildings b,
      sm.buildtypes bt,
      sm.objects o
     WHERE
       b.buildtypes_id=bt.id
       and o.id=b.objects_id
       and (BASEBUILDING=new.ID) 
       and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate 
       and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
       and (SQUARE<999999.00)-- игнорируем неопределённую площадь
       and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты

    ELSIF (new.EXISTS_SINCE IS NULL) and (new.EXISTS_END IS NOT NULL) THEN

     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений нижнего уровня
     INTO existsSquare
     FROM
      sm.buildings b,
      sm.buildtypes bt,
      sm.objects o
     WHERE
       b.buildtypes_id=bt.id       
       and o.id=b.objects_id
       and (BASEBUILDING=new.ID) 
       and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate 
       and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
       and (SQUARE<999999.00) -- игнорируем неопределённую площадь
       and not (nvl(o.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')) > nvl(new.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy')))
       and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты

    ELSIF (new.EXISTS_SINCE IS NOT NULL) and (new.EXISTS_SINCE<sysdate) THEN

     SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений нижнего уровня
     INTO existsSquare
     FROM
       sm.buildings b,
       sm.buildtypes bt,
       sm.objects o
     WHERE
       b.buildtypes_id=bt.id
       and o.id=b.objects_id
       and (BASEBUILDING=new.ID) 
       and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate 
       and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
       and (SQUARE<999999.00) -- игнорируем неопределённую площадь
       and not(nvl(o.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy'))<nvl(new.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')))
       and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты

    ELSIF (new.EXISTS_SINCE IS NOT NULL) and (new.EXISTS_END IS NOT NULL) THEN
     begin
      SELECT Sum(b.SQUARE) -- находим площадь уже зарегистрированных помещений нижнего уровня
      INTO existsSquare
      FROM
        sm.buildings b,
        sm.buildtypes bt,
        sm.objects o
      WHERE
        b.buildtypes_id=bt.id
        and o.id=b.objects_id
        and (BASEBUILDING=new.ID) 
        and nvl(o.exists_since, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate 
        and nvl(o.exists_end, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate   -- выбираем существующие помещения
        and (SQUARE<999999.00) -- игнорируем неопределённую площадь
        and not ((nvl(o.EXISTS_END,To_Date('01-01-3000','dd-mm-yyyy')) < nvl(new.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')))
        or(nvl(o.EXISTS_SINCE,To_date('01-01-0001','dd-mm-yyyy')) > nvl(new.EXISTS_END,To_date('01-01-3000','dd-mm-yyyy'))))
        and bt.is_bti_object='Y'; -- выбираем только БТИ-объекты
     end;
    END IF; --IF4
    IF ((new.SQUARE-existsSquare)<0) THEN --IF3
     raise_application_error(-20101, 'Объект не может иметь указанную площадь для указанного срока существования!'|| chr(13) ||'.' );
    END IF; --IF3
    <<quit>>
    null;
   end;
  END IF; --IF2

  end loop; --LOOP2
 end loop;  --LOOP1

end BUILDINGS_CHECKAREA_ROOT;
/

prompt
prompt Creating trigger BUILDINGS_CHECKLIVINGSQUARE
prompt ============================================
prompt
create or replace trigger "SM".BUILDINGS_CHECKLIVINGSQUARE
  before insert or update of LIVING_SQUARE on buildings  
  for each row
--
-- by XSGROUP 27.04.2005
-- триггер проверяет корректность размера жилой площади помещения
-- жилая площадь помещения не должна превышать его общую площадь 
--  
begin
  
  if nvl(:new.LIVING_SQUARE,0)>0 then
    if :new.SQUARE<>999999 then
      if :new.LIVING_SQUARE>:new.SQUARE then
        raise_application_error(-20101, 'Жилая площадь помещения не может превышать его общую площадь!' ); 
      end if;  
    end if; 
  end if;
  
end BUILDINGS_CHECKLIVINGSQUARE;
/

