prompt
prompt Creating trigger BUILDINGS_OBJ
prompt ==============================
prompt
CREATE OR REPLACE TRIGGER "SM".BUILDINGS_OBJ AFTER UPDATE OR INSERT ON BUILDINGS FOR EACH ROW
Declare
 S1 CHAR(40);
 S2 CHAR(300);
 SQ varchar2(20);
 qStreet CHAR(50);
-- qHouse INT;
 qHouse VARCHAR2(30);
 qHouseChar VARCHAR2(10);
 qTank CHAR(30);
-- qAppartment INT;
 qAppartment VARCHAR2(20);
-- qRoom INT;
 qRoom VARCHAR2(20);
 SmallInfo CHAR(100);
 IsContainer VARCHAR2(1);
 AddrRep INTEGER;
 ObjType INTEGER;
 HCC INTEGER;
Begin

-- далее обновляем OBJECTS.DESCRIPTION
 -- Тип здания
 SELECT BuildTypes.Name INTO S1 FROM BuildTypes WHERE ID=:new.BuildTypes_ID;

 -- Вычисление адреса
 SELECT Streets.Name, Address.House, Address.House_Char, Address.Tank, Address.Appartment, Address.Room
  INTO qStreet, qHouse, qHouseChar, qTank, qAppartment, qRoom
  FROM Address, Streets
  WHERE Address.ID=:new.Address_ID and
    Streets.ID(+)=Address.Streets_ID;

 HCC:= ASCII(Substr(qHouseChar, 1, 1));
 if (HCC>47 and HCC<58) then
   qHouseChar:= '/' || qHouseChar;
 end if;
 S2 := SUBSTR(RTRIM(S1) || ' (' || RTRIM(qStreet) || ', ' || RTRIM(TO_CHAR(qHouse)) || RTRIM(qHouseChar),1,100);

 if not (qTank IS NULL) then
  S2 := SUBSTR(RTRIM(S2) || '/' || RTRIM(qTank),1,100);
 END IF;

 if :new.Square=999999 then SQ:='';
  else SQ:=' - ' || rtrim(TO_CHAR(:new.Square)) || 'кв.м.';
 end if;

 S2 := SUBSTR(RTRIM(S2) || RTRIM(SQ) || ')',1,100);

 SmallInfo := SUBSTR(S2,1,100);

 UPDATE Objects SET Description = SmallInfo  , Address_ID=:new.ADDRESS_ID WHERE ID=:new.Objects_ID;

End;
/

