prompt
prompt Creating trigger BUILDINGS_TYPES
prompt ================================
prompt
create or replace trigger "SM".BUILDINGS_TYPES
  before insert or update on sm.buildings
  for each row
declare
  typeBuildings sm.buildtypes.name%type;
  containerBuildings sm.buildtypes.container%type;
begin
     select bt.name, bt.container
     into typeBuildings, containerBuildings
     from sm.buildtypes bt
     where bt.id = :new.buildtypes_id;
     if containerBuildings = 'Y'
          and (lower(typeBuildings) like '%квартира%'
          or lower(typeBuildings) like '%помещение%'
          or lower(typeBuildings) like '%встроенное%'
          or lower(:new.levelname) like '%квартира%'
          or (lower(:new.levelname) like '%помещение%'
             and lower(replace(:new.levelname, ' ','')) not like '%бытовоепомещение%')
          or lower(:new.levelname) like '%встроенное%')
     then
          raise_application_error(-20101, 'Нельзя создать отдельностоящую квартиру / помещение!' || chr(13)
                                  || 'Квартира / помещение должны быть расположены в структуре здания!' || chr(13)
                                  || 'Для этого:' || chr(13)
                                  || '1. Создайте отдельностоящее здание ' || chr(13)
                                  || '2. Перейдите в окне свойств объекта "Здание и помещения" на вкладку "Структура"' || chr(13)
                                  || '3. Выделите здание и вызовите контекстное меню с помощью мышки' || chr(13)
                                  || '4. Выберите пункт меню "Выделить конструктивный элемент" ("Выделить этаж/уровень")' || chr(13)
                                  || '5. Создайте квартиру (этаж/уровень).');
     end if;
end;
/

prompt
prompt Creating trigger BUILDINGS_UPD_ENTERYEAR
prompt ========================================
prompt
create or replace trigger "SM".BUILDINGS_UPD_ENTERYEAR
  before insert or update of enteryear, enter_date
  on sm.buildings
  for each row
declare
  enterdate_str varchar2(20);
  EnterDateChanging boolean;
begin
  if (:new.enter_date is null)and(:new.enteryear is null) then
    GOTO quit;
  end if;

  if UPDATING then
    EnterDateChanging:= (nvl(:new.enter_date,to_date('01.01.1700','DD.MM.YYYY'))<>nvl(:old.enter_date,to_date('01.01.1700','DD.MM.YYYY')));
  end if;

  if INSERTING then
    EnterDateChanging:=(:new.enter_date is not null);
  end if;

  if EnterDateChanging then
    enterdate_str:=to_char(:new.enter_date,'DD.MM.YYYY');
    :new.enteryear :=to_number(SUBSTR(enterdate_str,-4,4));
  else begin
    if (:new.enteryear is null )then
       :new.enter_date := to_date('01.01.1700','DD.MM.YYYY');
    else
       :new.enter_date:=to_date('01.01.'||to_char(:new.enteryear),'DD.MM.YYYY');
    end if;
  end;
  end if;

  <<quit>>
  null;

end BUILDINGS_UPD_ENTERYEAR;
/

