prompt
prompt Creating trigger BUILDINGS_XMLRR_SAVECHANGES
prompt ============================================
prompt
create or replace trigger "SM".Buildings_XMLRR_SaveChanges
after insert or update on buildings
for each row

declare
 ChangeID integer;
 tblID number(27);
 UserName varchar2(250);
 cnt integer;
 bildTypes char;
begin

if updating then

  --Если изменилась площадь
  if :new.square<>:old.square
  and :new.square<>999999

  then
     tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
     select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
     select sm.seqxmlrr_changes.nextval into ChangeID from dual;
     insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
     values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284001000000'), sysdate, UserName, 'U',tblID,:new.objects_id);

     insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_num,new_value_num)
     values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'SQUARE'),:old.square, :new.square);
      
  end if;


  --изменение года ввода в эксплуатацию
  if :new.enter_date<>:old.enter_date
  then
    
     tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284021000000'), sysdate, UserName, 'U',tblID,:new.objects_id);

           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_date,new_value_date)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID,sm.xmlrosreestr_pkg.GetColumnID(tblID,'enter_date'),:old.enter_date, :new.enter_date);

        end if;
  end if;


  --изменение материала наружных стен только для здания
    if (:new.buildmaterial_id<>:old.buildmaterial_id)
  then
    
     tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
     select t.container
     into bildTypes
     from buildtypes t
     where t.id=:new.BUILDTYPES_ID;
        if nvl(tblID,-1)<>-1 and bildTypes='Y' then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284019000000'), sysdate, UserName, 'U',tblID,:new.objects_id);

           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'buildmaterial_id'),:old.buildmaterial_id, :new.buildmaterial_id);

        end if;
  end if;



  --сведения об этажности
  if :new.floorcount<>:old.floorcount
  then
    
     tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284018000000'), sysdate, UserName, 'U',tblID,:new.objects_id);

           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'floorcount'),:old.floorcount, :new.floorcount);

        end if;
  end if;



  --сведения о назначении здания
  if :new.build_purpose_id<>:old.build_purpose_id
  then
     
     tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER')into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284017000000'), sysdate, UserName, 'U',tblID,:new.objects_id);

           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'build_purpose_id'),:old.build_purpose_id, :new.build_purpose_id);

        end if;

  end if;




end if; --end updating


if inserting then

     --образование части объекта недвижимости
     if :new.basebuilding is not null then

       --проверка уровня выделяемого элемента

              select count(*)
              into cnt
              from buildtypes t
              where t.container='N' and
              t.is_level='N' and
              t.is_liter='N' and
              t.id=:new.buildtypes_id;
        if cnt<>0 then

       
        tblID:=sm.xmlrosreestr_pkg.GetTableID(upper('buildings'));
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id, object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284010001000'), sysdate, UserName, 'I',tblID, :new.objects_id);

        end if;
      end if;
     end if;

 end if; --end inserting
exception 
when others then null;
end;
/

prompt
prompt Creating trigger CHARGES_ACC_BEFORE
prompt ===================================
prompt
CREATE OR REPLACE TRIGGER "SM".CHARGES_ACC_BEFORE after insert on  Charges
 for each row

declare
 CloseDate DATE;
 Charge_Date DATE;
 CorrSumm number(27,2);
 ChType char(1);
 ca_exists integer;
 CurDate DATE;
 NextDate DATE;
 CurPaySize number(27,2);
 SumPaySize number(27,2);
 Comments varchar2(150);
 n integer;
 astr_pos integer;
 equal_pos integer;
 Comments_part sm.charges.comments%type;
begin
  if RTRIM(:new.Charge_Type)='FINE' then
    ChType:='F';
  else
    ChType:='O';
  end if;

  CloseDate:=Getparameter('ENDPERIOD');

  --сводим корректирующие проводки в одну
  select nvl(sum(summ),0) into CorrSumm from Charge_Applies
    where Apply_Date>CloseDate and MoveSet_ID=:new.MoveSets_ID and ObligType_ID=:new.ObligationType_ID and Charge_Type=ChType and Charge_ID is null;
  delete from Charge_Applies
    where Apply_Date>CloseDate and MoveSet_ID=:new.MoveSets_ID and ObligType_ID=:new.ObligationType_ID and Charge_Type=ChType and Charge_ID is null;

  --в самом простом случае предполагаем, что проводка будет в день начисления
  Charge_Date:=:new.ChargeDate;

  if Charge_Date<=CloseDate then
    --если дата проводки попадает в закрытый период - ставим дату проводки на сегодняшний день
    Charge_Date:=trunc(SysDate);
   end if;

  -- проверим, вдруг существует проводка точно такая же как и эта, но в закрытом периоде
  select
    count(*) into ca_exists
  from Charge_Applies
  where
   Summ=:new.PaySize and
   ObligType_ID=:new.ObligationType_ID and
   MoveSet_ID=:new.MoveSets_ID and
   Description=:new.comments and
   Charge_Type=ChType and
   Apply_Date<=CloseDate;

  -- если существует, не будем её создавать снова, включим её в коррекцию
  if ca_exists=1 then
   CorrSumm:=CorrSumm+:new.PaySize;  
  else
   -- если начисление проводится с её реальной датой, создадим для нее отдельную проводку, так будет красивее
   if (:new.ChargeDate=Charge_Date) then
     -- для пени делаем разбивку проводок по месяцам
     if (ChType='O') or (:new.CALPERIOD_START is null) or (:new.CALPERIOD_END is null) then
      -- для обязательств не делаем
      insert into Charge_Applies(ID,Apply_Date,Summ,ObligType_ID,MoveSet_ID,Description,Charge_Type,Charge_ID,Corr_Flag,Cls_Kbk_Id)
       values(seqCharge_Applies.NextVal,Charge_Date,:new.PaySize, :new.ObligationType_ID,:new.MoveSets_ID,:new.comments, ChType,:new.ID,'N',:new.cls_kbk_id);
     else
       -- для пени - делаем разбивку по границам месяцев (для правильного исчисления сальдо по пене на конец месяца
      CurDate:=:new.CALPERIOD_START;

      astr_pos:=instr(:new.Comments,'*',1,1);
      equal_pos:=instr(:new.Comments,'=',1,1);
      Comments_part:=substr(:new.Comments,astr_pos,equal_pos-astr_pos+1);
      SumPaySize:=0.0;
      while true loop
        -- расчитаем дату конца текущего месяца
        NextDate:=TRUNC(ADD_MONTHS(CurDate,1),'MONTH')-1;
        
        -- если конец текущего месяце позже или совпадает с концом периода
        -- размером оплаты за этот период назначается оставшаяся сумма
        if NextDate>=:new.Calperiod_End then
            NextDate:=:new.Calperiod_End;
            CurPaySize :=:new.PaySize - SumPaySize;

            -- количество дней чтобы сформировать правильный комментарий
            n:=NextDate-CurDate+1;
            if n=0 then
                n:=1;
            end if;
            
        else
            -- количество дней
            n:=NextDate-CurDate+1;
            if n=0 then
                n:=1;
            end if;
            
            -- расчитываем размер оплаты за не последний период
            CurPaySize:=:new.PaySize/(:new.calperiod_end-:new.calperiod_start+1)*n;
            -- суммируем уже учтенную оплату для корректного расчета суммы последнего периода
            SumPaySize:=SumPaySize+CurPaySize;
        end if;    

        if n=1 then
          Comments:='Пеня: за '||CurDate||' ('||to_char(n)||'д'||Comments_part||To_char(CurPaySize,'FM99999990.00')||'р.)';
        else
          Comments:='Пеня: c '||CurDate||' по '||NextDate||' ('||to_char(n)||'д'||Comments_part||To_char(CurPaySize,'FM99999990.00')||'р.)';
        end if;
----------------------------------------------------новый блок
   if (NextDate<=CloseDate) then
     CorrSumm:=CorrSumm+CurPaySize;
   else
----------------------------------------------------старый бллок     
    insert into Charge_Applies(ID,Apply_Date,Summ,ObligType_ID,MoveSet_ID,Description,Charge_Type,Charge_ID,Corr_Flag,cls_kbk_id)
         values(seqCharge_Applies.NextVal,NextDate,CurPaySize, :new.ObligationType_ID,:new.MoveSets_ID,comments, ChType,:new.ID,'N',:new.cls_kbk_id);
----------------------------------------------------новый блок         
   end if;
----------------------------------------------------старый блок
        CurDate:=NextDate+1;
 
        exit when CurDate>:new.CALPERIOD_END;
      end loop;

     end if;
 
   else
     CorrSumm:=CorrSumm+:new.PaySize;
   end if;
  end if;

  --NEW для того, чтобы корректировка попала на сегодняшний день,
  -- если расчет до конца действия договора
   if Charge_Date>=trunc(sysdate) then
    Charge_Date:=trunc(SysDate);
   end if;
   --NEW 
 
  -- в корректирующую проводку включены все суммы, которые не отражают собой цельные начисления
  if CorrSumm<>0 then
    insert into Charge_Applies(ID,Apply_Date,Summ,ObligType_ID,MoveSet_ID,Description,Charge_Type,Charge_ID,Corr_Flag,cls_kbk_id)
    values(seqCharge_Applies.NextVal,Charge_Date,CorrSumm, :new.ObligationType_ID,:new.MoveSets_ID,'Корректирующая проводка', ChType,null,'Y',:new.cls_kbk_id);
  end if;
end;
/

prompt
prompt Creating trigger CHARGES_ACC_DELETE
prompt ===================================
prompt
create or replace trigger "SM".CHARGES_ACC_DELETE after delete on Charges
 for each row
declare
  CloseDate DATE;
	iTmp INTEGER;
begin

CloseDate :=  to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy'); -- Getparameter('ENDPERIOD');


-- Логика:
-- 1. Удаляем ВСЕ в открытом периоде. (Во всех случаях. Если все в открытом периоде - то на этом и конец).
-- 2. Находим в закрытом периоде оригинальную, ИЛИ  последнюю из "исправляющих".
-- 3. Если нашлась - пишем на нее "сторнирующую" текущей датой. (а лучше - началом открытого периода).
-- The End. (Happy End!!!) --

----- VVVVV Temporary TEST Code ----------
--if (:old.factcharge <> 'N') then
--         RAISE_APPLICATION_ERROR(-20101, ' НУ УДАЛЯИТ-ЖЕ!!! <'||:old.comments || '>???  ');
--				 Insert into SM.X_SM_MESSAGES (MSG_TIME, TEXT_MESSAGE, PROC_NAME, USER_NAME, MSG_CRITICAL, MSG_TYPE, MSG_KIND, DATA_ID, TYPE_ID, IS_SOLVED )
--				 values (sysdate,'НУ УДАЛЯИТ-ЖЕ!!! <'||:old.comments , 'TEST', 'SM', 2, 2, 1, :old.MOVESETS_ID, 5, 'N');
--end if;
------- ^^^^ End of TEST Code ------------------

-- Поехали:
-- 1. Удаляем все в открытом периоде (во всех случаях) -- VVV- 17.12.2013 -- Добавлено условие на НЕстирание сторнирующих имеющих сторнированные в закрытом периоде.
Delete from SM.CHARGE_APPLIES cha where cha.CHARGE_ID=:old.ID and cha.APPLY_DATE > CloseDate
AND   nvl(cha.reversallink_id, 0) not in (select id from sm.charge_applies cha1
                                                          where cha1.moveset_id = cha.moveset_id
                                                             and cha1.obligtype_id = cha.obligtype_id
                                                             and trim(cha1.charge_type) = trim(cha.charge_type)
                                                             and trim(cha1.reversal_role) = 'Сторнированная'
																														 and cha1.APPLY_DATE <= CloseDate);

-- 2. Находим в закрытом периоде оригинальную, ИЛИ  последнюю из "исправляющих". -- VVV- 17.12.2013 -- Добавлено условие на REVERSAL_ROLE
Select count(*) into iTmp from SM.CHARGE_APPLIES cha_cha_cha where cha_cha_cha.CHARGE_ID = :old.ID and APPLY_DATE <= CloseDate and ( cha_cha_cha.REVERSAL_ROLE is null OR  cha_cha_cha.REVERSAL_ROLE = 'Исправляющая');

-- 3. Если нашлась - пишем на нее "сторнирующую" текущей датой. (Хотя лучше бы - началом открытого периода).
if iTmp > 0 then
		 FOR xxrow in (
				Select ID  from SM.CHARGE_APPLIES cha
	     	 where cha.CHARGE_ID = :old.ID and cha.APPLY_DATE <= CloseDate
									and ( cha.REVERSAL_ROLE is null OR  cha.REVERSAL_ROLE = 'Исправляющая')
				order by cha.APPLY_DATE desc, cha.ID		-- <<< 16.12.2013 -- Добавлено desc - чтобы сторнировалось последнее а не более раннее									
			)
		 LOOP
							-- Пишем сторнирование
							if (xxrow.ID > 0) then -- (на всякий случАй)
										 Insert into CHARGE_APPLIES (ID, APPLY_DATE, SUMM, OBLIGTYPE_ID, MOVESET_ID, DESCRIPTION, CHARGE_TYPE, CORR_FLAG, CLS_KBK_ID,
																																				 charge_id, obligations_id, reversal_role, reversallink_id, payment_id)
														Select 	SM.SEQCHARGE_APPLIES.nextval, trunc(sysdate), - SUMM, OBLIGTYPE_ID, MOVESET_ID,  'Сторнирующая: ' || replace(DESCRIPTION, 'Сторнирующая: '), CHARGE_TYPE, 'Y', CLS_KBK_ID,
																																				 :old.ID,  obligations_id,  'Сторнирующая',   xxrow.ID,  null
														from 	SM.CHARGE_APPLIES cha_cha_cha
														where cha_cha_cha.ID = xxrow.ID;
											-- И подправляем ее статус (даже если она была исправляющей)
										 Update SM.CHARGE_APPLIES set
														CORR_FLAG = 'Y',
													 REVERSAL_ROLE = 'Сторнированная',
													 DESCRIPTION =  'Сторнированная: ' || replace(replace(DESCRIPTION, 'Сторнированная: '), 'Сторнированная - ')
													 where ID = 	xxrow.ID;
						 end if;
			 END LOOP;
end if;

end;  -- The End. (Happy End!!!) --
/

prompt
prompt Creating trigger CHARGES_ACC_UPDATE
prompt ===================================
prompt
create or replace trigger "SM".CHARGES_ACC_UPDATE before update on Charges
 for each row
declare
 CloseDate DATE;
begin
  CloseDate:=Getparameter('ENDPERIOD'); 

  --если дата проводки попадает в закрытый период - ставим дату проводки на сегодняшний день
  if (:new.CHARGEDATE<>:old.CHARGEDATE) then
     raise_application_error(-20101,'Дату начисления изменять нельзя. Удалите и создайте новое начисление с новой датой.' );
  end if;

  if :new.CHARGEDATE<=CloseDate then
    if :new.PaySize<>:old.PaySize then
      raise_application_error(-20101,'Сумму начисления в закрытом бухгалтерском периоде изменять нельзя. Удалите и создайте новое начисление с новой суммой.' );
    end if;
   else
     update Charge_Applies set Summ=:new.PaySize where Charge_ID=:new.ID;

  end if;

end;
/

