prompt
prompt Creating trigger CHARGES_CUSTOM_ACC
prompt ===================================
prompt
CREATE OR REPLACE TRIGGER "SM".CHARGES_CUSTOM_ACC AFTER INSERT or UPDATE or DELETE ON SM.Charges
 for each row
--
-- by XSGROUP ver.18.10.2011
-- Отражение в учетных данных доп.начислений
--
declare
      G_CloseDate DATE := trunc(to_date(sm.getparametersimple('ENDPERIOD'),'dd.MM.yyyy'));
       itmp integer;

      A_comments VARCHAR2(100) := '';
      A_corr_flag CHAR(1) := 'N';
      A_chargedate DATE;
      A_reversal_role VARCHAR2(100) := '';
			Ch_appl_type CHAR(1) := 'O';
      Saldo number(27,2);
      A_document_id number(27);

begin

 -- VVV Все делается для доп.начислений
if  ((INSERTING or UPDATING) and :new.charge_Type='OTHER' or :new.document_id is not null )
    OR
     (DELETING and :old.charge_Type='OTHER' or :old.document_id is not null )
    then


if ((DELETING AND :old.charge_Type = 'FINE' )  -- <<< 31.05.2013 -- добавлено правильное определение типа уч.записи
	OR ((INSERTING or UPDATING) and :new.charge_Type = 'FINE' )) then    -- <<< 31.10.2013 -- Доработано...
     Ch_appl_type := 'F';
end if;

----------------------------------------------------------------------------------------------------------------------
--------------------------------------- Закрытый период ----------------------------------------------------
if (((INSERTING or UPDATING) and G_CloseDate >= :new.chargedate)
    OR
     (DELETING  and G_CloseDate >= :old.chargedate ))
 then    -- Начисление добавлено/изменено/удалено в закрытом периоде

    if INSERTING then

            A_comments := 'Прошлым периодом: ';
            A_corr_flag :='Y';
            A_chargedate := G_CloseDate + 1;
            A_reversal_role := 'Исправляющая';
            A_document_id := nvl(:new.document_id, 0);
            if A_document_id > 0 then
                insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                payments_distribution_id, reversal_role, reversallink_id, payment_id)
                 values (sm.seqcharge_applies.nextval, A_chargedate, :new.paysize, :new.obligationtype_id, :new.movesets_id, Ch_appl_type,
                                                A_comments || :new.comments, :new.ID, A_corr_flag,  :new.cls_kbk_id,
                                               null, null, A_reversal_role, null, null);
            end if;
    elsif UPDATING then

      if (:new.chargedate<>:old.chargedate)or(:new.paysize<>:old.paysize) then
   		 A_chargedate := G_CloseDate + 1;
                 begin
                      -- CloseDate := to_date(sm.getparameter('ENDPERIOD'), 'DD.MM.YYYY');

                      --- 22.01.2014 Morozova ---- в закрытом периоде выбираем начисление, если оно не было старнироввано и проводим его сторнирование
                      Select max(ID) into itmp  from SM.CHARGE_APPLIES cha
                             where cha.charge_id = :old.ID and (trim(cha.reversal_role)='Исправляющая' OR cha.reversal_role is null)
                                   and cha.apply_date <= G_CloseDate ;
                      sm.OBLIG_ACC_PKG.STORNO(itmp, G_CloseDate+1);
                  exception
                    when no_data_found then
                      null;
                  end;

                  --- 22.01.2014 Morozova ---- проверяем наличие исправляющих записей в открытом периоде
                  ------ если находим, то просто корректируем, если нет - то добавляем.
                  Select count(*) into itmp from   sm.charge_applies cha
                         where cha.charge_id = :old.id and cha.apply_date > G_CloseDate
                               and (trim(cha.reversal_role)='Исправляющая' OR cha.reversal_role is null);
                  if itmp = 1 then
                            Update sm.charge_applies cha
                            set cha.summ = :new.paysize,
                                cha.charge_type = Ch_appl_type,
                               -- cha.description = 'Начисление: ' || sm.ExpandDoc(:new.document_id),
                                cha.cls_kbk_id = :new.cls_kbk_id,
                                cha.apply_date = A_chargedate
                            where cha.charge_id = :old.id and (trim(cha.reversal_role)='Исправляющая' OR cha.reversal_role is null);
                   elsif itmp = 0 then
                              A_comments := 'Исправляющая: ';
                              A_corr_flag :='Y';
                              A_reversal_role := 'Исправляющая';
                              insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                   description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                   payments_distribution_id, reversal_role, reversallink_id, payment_id)
                               values (sm.seqcharge_applies.nextval, A_chargedate, :new.paysize, :new.obligationtype_id, :new.movesets_id, Ch_appl_type,
                                               A_comments || :new.comments, :new.ID, A_corr_flag,  :new.cls_kbk_id,
                                                null, null, A_reversal_role, itmp, null);
                   end if;
      end if;
   elsif DELETING then

       begin
            sm.OBLIG_ACC_PKG.StornoCharge(:old.ID);
        exception
            when no_data_found then
            null;
        end;
    end if;
    
   -- Открытый период
   else

         if INSERTING then

            A_comments := '';
            A_corr_flag := 'N';
            A_chargedate := :new.chargedate;
            A_reversal_role := '';
            A_document_id := nvl(:new.document_id, 0);
           if A_document_id > 0 then
                insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                     description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                     payments_distribution_id, reversal_role, reversallink_id, payment_id)
                 values (sm.seqcharge_applies.nextval, A_chargedate, :new.paysize, :new.obligationtype_id, :new.movesets_id, Ch_appl_type,
                                  A_comments || :new.comments, :new.ID, A_corr_flag,  :new.cls_kbk_id,
                                  null, null, A_reversal_role, itmp, null);
            end if; 
          elsif UPDATING then
									Select count(*) into itmp from   sm.charge_applies cha where cha.charge_id = :old.id; -- <<< 01.06.2013  -- Дополнено заполнением, если по-какой-то причине отсутствовало...
									if itmp = 1 then
														Update sm.charge_applies cha
														set cha.summ = :new.paysize,
																cha.charge_type = Ch_appl_type,
																cha.description = 'Начисление: ' || sm.ExpandDoc(:new.document_id),
																cha.cls_kbk_id = :new.cls_kbk_id,
																cha.apply_date = :new.chargedate
														where cha.charge_id = :old.id;
									 elsif itmp = 0 then
														A_comments := '';
														A_corr_flag := 'N';
														A_chargedate := :new.chargedate;
														A_reversal_role := '';
														Insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
																								 description, charge_id, corr_flag, cls_kbk_id, obligations_id,
																								 payments_distribution_id, reversal_role, reversallink_id, payment_id)
														 values (sm.seqcharge_applies.nextval, A_chargedate, :new.paysize, :new.obligationtype_id, :new.movesets_id, Ch_appl_type,
																							A_comments || :new.comments, :new.ID, A_corr_flag,  :new.cls_kbk_id,
																							null, null, A_reversal_role, itmp, null);
									 end if;

         elsif DELETING then
             delete from sm.charge_applies cha  where cha.charge_id = :old.id; --  and cha.apply_date > CloseDate and cha.Reversal_Role <> 'Сторнирующая';
         end if;
    end if;
  end if;
end;
/

prompt
prompt Creating trigger CHARGES_PLAN
prompt =============================
prompt
create or replace trigger "SM".CHARGES_PLAN
  after insert or update on SM.CHARGES
  for each row
declare
  OBL_ID number(27);
begin
  if :new.document_id is not null then
  
     if INSERTING then      
  			select o.id into OBL_ID  from sm.obligations o where o.moveset_id=:new.movesets_id and o.obligationtype_id=:new.obligationtype_id;
       insert into sm.payments_plan(id,charges_id,obligations_id,finedate,val,payments_plan_draft_id,comments)
            values(sm.seqpayments_plan.nextval,:new.id,OBL_ID,:new.finedate,:new.paysize,null,:new.comments);
     else
         update sm.payments_plan pp set pp.finedate=:new.finedate, pp.val=:new.paysize, pp.comments=:new.comments
            where pp.CHARGES_ID = :new.ID;
     end if;   
  end if;        
end;
/

prompt
prompt Creating trigger CHARGES_UPDATEFINES
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER "SM".Charges_UpdateFines AFTER INSERT or UPDATE or DELETE ON SM.Charges 

BEGIN
 if INSERTING then
   if sm.charge_state_pkg.newRows.count<>0 then
     for i in 1 .. sm.charge_state_pkg.newRows.count 
     loop
       begin
         if  sm.charge_state_pkg.newRows(i).charge_Type='OTHER' or sm.charge_state_pkg.newRows(i).document_id is not null then
           begin
             Update SM.OBLIGATIONS  set RECALC_ACTUAL_DATE = null   where MOVESET_ID=sm.charge_state_pkg.newRows(i).movesets_id and  OBLIGATIONTYPE_ID=sm.charge_state_pkg.newRows(i).obligationtype_id;
           exception
             when others then  null;  
           end;  

           sm.FullRecalcFines(sm.charge_state_pkg.newRows(i).movesets_id, sm.charge_state_pkg.newRows(i).obligationtype_id);
         end if;
       exception
         when NO_DATA_FOUND then
           null;  
       end;  
     end loop;
   end if;
 elsif UPDATING then
   if sm.charge_state_pkg.updRows.count<>0 then
     for i in 1 .. sm.charge_state_pkg.updRows.count 
     loop
       begin
         if  sm.charge_state_pkg.updRows(i).charge_Type='OTHER' or sm.charge_state_pkg.updRows(i).document_id is not null  then
           begin
             Update SM.OBLIGATIONS  set RECALC_ACTUAL_DATE = null   where MOVESET_ID=sm.charge_state_pkg.updRows(i).movesets_id and  OBLIGATIONTYPE_ID=sm.charge_state_pkg.updRows(i).obligationtype_id;
           exception
             when others then  null;
           end;    
           sm.FullRecalcFines(sm.charge_state_pkg.updRows(i).movesets_id, sm.charge_state_pkg.updRows(i).obligationtype_id);  
         end if;
       exception
         when NO_DATA_FOUND then
           null;  
       end;  
     end loop;
  end if;
 elsif DELETING then
   if sm.charge_state_pkg.delRows.count<>0 then
     for i in 1 .. sm.charge_state_pkg.delRows.count 
     loop
       begin
         if  sm.charge_state_pkg.delRows(i).charge_Type='OTHER' or sm.charge_state_pkg.delRows(i).document_id is not null then
           begin
             Update SM.OBLIGATIONS  set RECALC_ACTUAL_DATE = null   where MOVESET_ID=sm.charge_state_pkg.delRows(i).movesets_id and  OBLIGATIONTYPE_ID=sm.charge_state_pkg.delRows(i).obligationtype_id;
           exception
             when others then  null;
           end;    
           sm.FullRecalcFines(sm.charge_state_pkg.delRows(i).movesets_id, sm.charge_state_pkg.delRows(i).obligationtype_id);
         end if;
       exception
         when NO_DATA_FOUND then
           null;  
       end;  
     end loop;
   end if;
 end if;

END;
/

prompt
prompt Creating trigger CHARGES_UPDATEPKG
prompt ==================================
prompt
CREATE OR REPLACE TRIGGER "SM".Charges_UpdatePKG AFTER INSERT or UPDATE or DELETE ON sm.Charges    for each row 
 
when ((new.charge_type = 'OTHER') or (old.charge_type = 'OTHER') or (new.document_id is not null) or (old.document_id is not null))
BEGIN
 if INSERTING then
   sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count+1 ).id := :new.id;
   sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count).movesets_id := :new.movesets_id;
   sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).obligationtype_id  := :new.obligationtype_id;
   sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).charge_type  := :new.charge_type;
   sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).document_id  := :new.document_id;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).chargedate  := :new.chargedate;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).comments  := :new.comments;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).paysize  := :new.paysize;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).finedate  := :new.finedate;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).discountsize  := :new.discountsize;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).paydoc_id  := :new.paydoc_id;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).calperiod_start  := :new.calperiod_start;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).calperiod_end  := :new.calperiod_end;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).cls_kbk_id  := :new.cls_kbk_id;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).redir_flag  := :new.redir_flag;
  sm.charge_state_pkg.newRows(charge_state_pkg.newRows.count ).redir_paydoc_id  := :new.redir_paydoc_id;
  elsif UPDATING then
   sm.charge_state_pkg.updRows(charge_state_pkg.updRows.count+1 ).id := :new.id;
   sm.charge_state_pkg.updRows(charge_state_pkg.updRows.count ).movesets_id := :new.movesets_id;
   sm.charge_state_pkg.updRows(charge_state_pkg.updRows.count ).obligationtype_id  := :new.obligationtype_id ;
   sm.charge_state_pkg.updRows(charge_state_pkg.updRows.count ).charge_type  := :new.charge_type ;
