prompt
prompt Creating trigger CHECKFIRSTMOVEPERIODS
prompt ======================================
prompt
create or replace trigger "SM".CheckFirstMovePeriods
  after insert or delete on sm.moveperiods

  -- замена DOCSET_ID в MOVESETS при вставке или удалении первого периода 

declare
  i number;
  Prev_DocSet number;
  str varchar2(4000);
begin
 for i in 1 .. sm.movper_pkg.updRows.count loop --LOOP 1 читаем данные из movper_pkg
   for new in (select * from sm.moveperiods where rowid = sm.movper_pkg.updRows(i) )
   loop --LOOP2
       if new.prev_moveperiod_id is null then --if00
           update sm.movesets set docset_id=new.docset_id where id=new.moveset_id;
       end if; --if00
    end loop; -- LOOP2
 end loop; -- LOOP1
 
 str:=to_char(sm.movper_pkg.oldRows.count); 
 for i in 1 .. sm.movper_pkg.oldRows.count loop --LOOP 1 читаем данные из movper_pkg
    if sm.movper_pkg.oldRows(i).prev_moveperiod_id is null then --if00
       select p.docset_id
       into Prev_DocSet
       from sm.moveperiods p
       where p.moveset_id=sm.movper_pkg.oldRows(i).moveset_id and 
             p.sincedate in (select min(mp.sincedate) 
                             from sm.moveperiods mp 
                             where mp.moveset_id=sm.movper_pkg.oldRows(i).moveset_id and mp.id<>sm.movper_pkg.oldRows(i).id);
       update sm.movesets set docset_id=Prev_DocSet where id=sm.movper_pkg.oldRows(i).moveset_id;
     end if;  
  end loop; -- LOOP1
  
  exception
        when NO_DATA_FOUND then
           null;
end;
/

