prompt Creating trigger CLIENT_AFTER_DELETE
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER "SM".CLIENT_AFTER_DELETE
  after delete on CLIENTS
declare
  i number;  
begin

  if storage_pkg.AddressIDs.count>0 then
    for i in 1..storage_pkg.AddressIDs.count
    loop
      begin
        delete from sm.ADDRESS a where a.ID=storage_pkg.AddressIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
                                    
  if storage_pkg.ObjectsIDs.count>0 then
    for i in 1..storage_pkg.ObjectsIDs.count
    loop
      begin
        delete from sm.Objects o where o.ID=storage_pkg.ObjectsIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
  
  if docsets_state_pkg.ClientsDocSetIDs.count>0 then
    for i in 1..docsets_state_pkg.ClientsDocSetIDs.count
    loop
      begin
        delete from sm.DocSets ds where ds.ID=docsets_state_pkg.ClientsDocSetIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
  
  storage_pkg.ClientsSelf:=false;

end;
/

