prompt
prompt Creating trigger CLIENT_FILL_STORAGE
prompt ====================================
prompt
create or replace trigger "SM".CLIENT_FILL_STORAGE
  before delete on sm.CLIENTS for each row
declare
  cnt number;
  cl_subtype number;
begin
  
  cl_subtype:=:old.client_types_id;
  
  cnt:=0;
  for xx in (select atp.grantee
             from all_tab_privs atp 
             where 
               atp.table_schema='SM' and 
               atp.table_name=( select
                                  UPPER(ft.table_name)
                                from 
                                  sm.fm_tables ft
                                where
                                  ft.type_id=3 and
                                  ft.subtype=cl_subtype) and
               atp.privilege='DELETE')
  loop
    if Dbms_Session.is_role_enabled(xx.grantee) then
      cnt:=1;
      exit;
    end if;       
  end loop;  

  if cnt=0 then
    raise_application_error(-20101, 'У Вас нет прав на удаление субъектов права данного типа!'||chr(10)||chr(13) );
  end if;

  sm.storage_pkg.AddressIDs(sm.storage_pkg.AddressIDs.count+1):=:old.ADDRESS_ID;
  sm.docsets_state_pkg.ClientsDocSetIDs(sm.docsets_state_pkg.ClientsDocSetIDs.count+1):=:old.REGDOC_ID;

end;
/

