prompt
prompt Creating trigger COMPLEX_PROPERTY_OBJ
prompt =====================================
prompt
CREATE OR REPLACE TRIGGER "SM".COMPLEX_PROPERTY_Obj AFTER UPDATE OR INSERT ON COMPLEX_PROPERTY FOR EACH ROW

Declare
 SmallInfo sm.objects.description%type;
 Len number;
 s varchar2(60);
 CP_Name sm.complex_property.namecomplex%type;
Begin

  select atc.DATA_LENGTH
  into Len
  from
    all_tab_columns atc
  where
    atc.OWNER='SM' and
    atc.TABLE_NAME='OBJECTS' and
    atc.COLUMN_NAME='DESCRIPTION';

  S:='Имуществ. комплекс ';
  if :new.NAMECOMPLEX is null then
    CP_Name:='#'||:new.NAMECOMPLEX;
  else
    CP_Name:=:new.NAMECOMPLEX;
  end if;
  
  if instr(CP_Name,S)<>0 then
    SmallInfo :=substr(CP_Name,1,Len);
  else
    SmallInfo :=S||substr(CP_Name,1,Len-length(S));
  end if;
  
  UPDATE Objects SET Description = SmallInfo
    WHERE ID=:new.Objects_ID;

End;
/

