prompt
prompt Creating trigger DOCTYPES_CHECK_GUID
prompt ====================================
prompt
create or replace trigger "SM".DOCTYPES_CHECK_GUID
   after update of GUID, Name or delete on SM.DOCTYPES
   for each row
--
-- by XSGROUP 06.03.2009
-- триггер предотвращает изменение поля GUID таблицы DOCTYPES
-- и не позволяет удалить строку из DOCTYPES, для которой задан GUID
--
begin

  if UPDATING then
    if :old.GUID is not null then
      if nvl(:old.name,'NNN')=nvl(:new.name,'NNN') then
        raise_application_error(-20101, 'Запрещается изменять уже установленное значение поля GUID в справочнике Типы документов!');
      elsif :old.GUID='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE' then
          raise_application_error(-20101, 'Запрещается изменять название для элемента ''Неизвестный документ''!');
      end if;
    end if;
  end if;

  if DELETING then
    if :old.GUID is not null then
      raise_application_error(-20101, 'Запрещается удалять элемент справочника Типы документов с установленным значением поля GUID!');
    end if;
  end if;

end;
/

prompt
prompt Creating trigger DOCTYPES_CHECK_NAME
prompt ====================================
prompt
create or replace trigger "SM".DOCTYPES_CHECK_NAME
   after insert or update of Name, GUID on SM.DOCTYPES
--
-- by XSGROUP 06.03.2009
-- триггер предотвращает внесение в таблицу DOCTYPES
-- ещё одного элемента 'Неизвестный элемент'
--
declare
  cnt number;
begin

  select count(*)
  into
    cnt
  from
    sm.doctypes dt
  where
    UPPER(trim(dt.name))='НЕИЗВЕСТНЫЙ ДОКУМЕНТ';

  if cnt>1 then
    raise_application_error(-20101,'Элемент ''Неизвестный документ'' уже имеется в справочние Виды документов.'||
                                                    chr(13)||chr(10)||' Не допускается иметь ещё один элемент справочника c таким же имененм!''');
  end if;

end DOCTYPES_CHECK_NAME;
/

prompt
prompt Creating trigger DOCTYPES_POST
prompt ==============================
prompt
create or replace trigger "SM".DOCTYPES_POST
  after insert or update  on doctypes for each row

begin

  -- by XSGROUP, ver.01.04.2009
  -- триггер корректирует таблицы, реализующие
  -- механизм автонумерации документов

  -- если это новый тип документа
  if INSERTING then
    if :new.RESERVING='Y' then
      INSERT INTO sm.docnums (doctypes_id, docsubscr_id, curr_no) values(:new.ID,null,0);
    end if;
  end if;

  -- если убрали/выставили флаг автонумерации для данного типа документа
  if UPDATING then
    if :old.RESERVING<>:new.RESERVING then
      if :new.RESERVING='N' then
        delete from sm.docnums where DOCTYPES_ID=:new.ID;
        delete from sm.reserved_doc_num where doctype_id=:new.ID;
      else
        INSERT INTO sm.docnums (doctypes_id, docsubscr_id, curr_no) values(:new.ID,null,0);
      end if;
    end if;
  end if;

end DOCTYPES_POST;
/

