prompt
create or replace trigger "SM".DOCUMENT_CHECK_DOCNO
  before insert or update of docno on sm.documents for each row
--
-- by XSGROUP 18.11.2009
-- отсекание пробелов в номере документа
--
declare
  docnom sm.documents.docno%type;
begin
  :new.docno:=trim(:new.docno);
end;
/

prompt
prompt Creating trigger DOCUMENT_CHECK_DOCTYPE
prompt =======================================
prompt
create or replace trigger "SM".DOCUMENT_CHECK_DOCTYPE
  after insert or update or delete on documents
--
-- by XSGROUP 05.03.2009
-- проверка на уникальность документа с типом "Неизвестный документ"
-- запрет на удаление документа с типом "Неизвестный документ"
--


declare
  cnt integer;
begin

  select count(*)
  into
    cnt
  from
    sm.documents doc,
    sm.doctypes dt
  where
    doc.doctypes_id=dt.id and
    dt.guid='8B01A0C4-07A4-4C9E-B11F-7FD7801CFDFE';


  if INSERTING or UPDATING then
    if cnt>1 then
      raise_application_error(-20101,'Не допускается наличие в базе данных двух документов вида ''Неизвестный документ''!');
    end if;
    if UPDATING then
      if cnt=0 then
        raise_application_error(-20101,'Не допускается редактировать ''Неизвестный документ''!');      
      end if; 
    end if;
  end if;

  if DELETING then
    if cnt=0 then
      raise_application_error(-20101,'Запрещено  удаление из базы данных документа ''Неизвестный документ''!');
    end if;
  end if;

end DOCUMENT_CHECK_DOCTYPE;
/

