prompt
prompt Creating trigger DOCUMENT_POST
prompt ==============================
prompt
create or replace trigger "SM".DOCUMENT_POST
  after insert on documents
  for each row
declare
  DocTypeID number;
  PureDocNo varchar2(400);
begin

  -- by XSGROUP ver. 15.05.2009
  -- триггер должен удалить использованный зарезервированный номер
  -- из таблицы зарезервированных номеров
  --

  -- очистим номер документа от суффикса и префикса
  PureDocNo:=sm.Unwrap_Docno(:new.DOCTYPES_ID,:new.DOCNO);
 
  -- получим тип документа, для которого установлено резервирование номеров
  DocTypeID:=sm.Getrootdoctypeid(:new.DOCTYPES_ID);
  
  -- снять резервирование документа
  delete from reserved_doc_num rdm
  where
    rdm.DOCTYPE_ID=DocTypeID and
    rdm.DOCNO=TO_NUMBER(trim(PureDocNo));
    
exception
  when others THEN
     null;-- ничего страшного
   
end DOCUMENT_POST;
/

