prompt Creating trigger ENGINF_OBJ
prompt ===========================
prompt
CREATE OR REPLACE TRIGGER "SM".ENGINF_OBJ AFTER UPDATE OR INSERT ON ENGINF FOR EACH ROW
Declare
 S1 sm.enginf.name%type;
 S2 sm.enginf.name%type;
 S3 sm.enginf.name%type;
 SmallInfo sm.objects.description%type;
Begin
 -- Название объекта
 S1 := :new.Name;
 S2 := RTRIM(S1);

 SELECT igr.Name INTO S3 FROM InfGroups igr WHERE igr.ID=:new.infgroups_id ;
 
 S1:=SUBSTR(RTRIM(S2) || ' (' || RTRIM(S3) || ')',1,60);

 SmallInfo := S1;

 UPDATE Objects SET Description=SmallInfo , Address_ID=:new.ADDRESS_ID WHERE ID=:new.OBJECTS_ID;
		
End;
/

