prompt
prompt Creating trigger GROUNDS_CHECKAREA
prompt ==================================
prompt
create or replace trigger "SM".Grounds_CheckArea
  after insert or update of
  SQUARE
  on grounds

declare

   root_since   DATE;                       -- дата начала существования ЗУ-контейнера
   root_end     DATE;                       -- дата окончания существования ЗУ-контейнера
   root_square  sm.Grounds.square%type;     -- площадь ЗУ-контейнера
   square_summ  sm.Grounds.square%type;     -- сумма площадей всех одновременно существующих частей земельного участка,
                                            -- за исключением данной части ЗУ
   info_str     varchar2(1000);              -- сообщение об ошибке                           
   i INTEGER;
begin

-- by XSGROUP Ver. 12.09.2011
-- проверяем общую плошадь одновременно существующих частей земельного участка и не даём зарегистрировать часть зесельного участка
-- если новая суммарная площадь будет превышать площадь участка-контейнера

 for i in 1 .. grnd_state_pkg.updRows.count --читаем данные из grnd_state_pkg
 loop --LOOP 1 
  for this in (select g.*, 
                     nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) exists_since,
                     nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) exists_end
               from 
                 sm.Grounds g,
                 sm.objects o 
               where 
                 g.rowid=grnd_state_pkg.updRows(i) and
                 g.objects_id=o.id)
  loop --LOOP2
    IF (this.BASEGROUND IS NOT NULL) and (this.Square IS NOT NULL) THEN -- IF2 если это часть участка и у него задана площадь
       IF this.SQUARE=0 THEN --IF13 не даём создать объект с площадью, равной 0 кв.м.
         raise_application_error(-20101, 'Нельзя создать часть земельного участка, у которого площадь равна 0 кв.м.' );
       END IF; 
    
      -- находим даты существования ЗУ-контейнера
       select
         g.square,
         nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')),
         nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))
       into
         root_square, 
         root_since,
         root_end  
       from sm.objects o, sm.grounds g where  o.id=g.objects_id and g.id=this.baseground; 

       IF root_since>this.exists_since THEN 
         raise_application_error(-20101, 'Дата начала существования части земельного участка, не может быть раньше даты начала существования базового участка.' );
       END IF; 
    
       IF root_end<this.exists_end THEN 
         raise_application_error(-20101, 'Дата окончания существования части земельного участка, не может быть позже даты окончания существования базового участка.' );
       END IF; 

       select
         sum(nvl(g.square,0))
       into
         square_summ  
       from
         sm.grounds g
       where
         g.objects_id in (select o.id
                          from
                            sm.objects o,
                            sm.grounds gr
                          where
                            gr.objects_id=o.id and 
                            gr.baseground=this.baseground and
                            not (
                                ((nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))<nvl(this.exists_since,to_date('01.01.0001','dd.mm.yyyy')))and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))<=nvl(this.exists_since,to_date('01.01.0001','dd.mm.yyyy')))) 
                                or
                                ((nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))>nvl(this.exists_end,to_date('01.01.0001','dd.mm.yyyy')))and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))>=nvl(this.exists_end,to_date('01.01.0001','dd.mm.yyyy'))))      
                                ))
         and g.id<>this.id;
         
       IF (root_square-nvl(square_summ,0))<this.square THEN
         if (root_square-nvl(square_summ,0))<=0 then
           info_str:='Объект не может иметь площадь '||this.square||' кв.м. для указанного срока существования.'||chr(13)||
                     'Вся свободная площадь базового участка уже распределена.';
         else
           info_str:='Объект не может иметь площадь '||this.square||' кв.м. для указанного срока существования.'||chr(13)||
                     'Максимально возможная площадь для этого срокa составляет '||(root_square-nvl(square_summ,0))||' кв.м.';  
         end if;
         raise_application_error(-20101, info_str);
       END IF;                   

    END IF; --IF2

  end loop; --LOOP 2
 end loop;  --LOOP 1
end;
/

prompt
prompt Creating trigger GROUNDS_CHECKAREA_ROOT
prompt =======================================
prompt
create or replace trigger "SM".GROUNDS_CHECKAREA_ROOT
  after update of
  SQUARE
  on grounds

declare
   square_summ sm.grounds.square%type; -- сумма площадей частей ЗУ
   i INTEGER;
begin

-- By XSGROUP 12.09.2011
-- проверяем общую площадь частей, составляющих земельный участок
-- и не даем изменять площадь, если новая площадь будет меньше суммы площадей частей

 for i in 1 .. grnd_state_pkg.updRows.count
 loop --LOOP 1 читаем данные из bld_state_pkg
  for this in (select g.*, 
                      nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) exists_since,
                      nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) exists_end
               from 
                 sm.Grounds g,
                 sm.objects o 
               where 
                 g.rowid=grnd_state_pkg.updRows(i) and
                 g.objects_id=o.id)
   loop --LOOP2
     IF (this.baseground is null)and(this.SQUARE is not null) THEN -- IF2 проверяем только для ЗУ-контейнера с какой-то установленной площадью
       IF this.SQUARE=0 THEN --IF13 не даём создать объект с площадью, равной 0 кв.м.
         raise_application_error(-20101, 'Для земельного участка нельзя установить площадь равной 0 кв.м.');
       END IF; --13
       
       -- если изменяется площадь, а объект не существует на данный момент, то сообщаем это
       IF UPDATING('SQUARE') and not (nvl(this.EXISTS_SINCE, to_date('01.01.0001','dd.mm.yyyy'))<=sysdate and nvl(this.EXISTS_END, to_date('01.01.3000','dd.mm.yyyy'))>=sysdate) THEN
         raise_application_error(-20101, 'Объект в настоящее время не существует! Устанавливать площадь несуществующего в данный момент объекта запрещено.' );
       END IF;
     
       IF (this.EXISTS_SINCE IS NULL) and (this.EXISTS_END IS NULL) THEN --IF4
            -- в запросе не участвуют даты, поскольку ВСЕ записи данного уровня являются в тот или иной период современниками
            -- находим площадь уже зарегистрированных частей данного ЗУ
         select
           sum(nvl(g.square,0))
         into
           square_summ  
         from
           sm.grounds g
         where
           g.objects_id in (select o.id
                            from
                              sm.objects o,
                              sm.grounds gr
                            where
                              gr.objects_id=o.id and 
                              gr.baseground=this.id and
                              (nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))<=sysdate)and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))>=sysdate) 
                           );

       ELSIF (this.EXISTS_SINCE IS NULL) and (this.EXISTS_END IS NOT NULL) THEN
         -- находим площадь уже зарегистрированных частей данного ЗУ
         select
           sum(nvl(g.square,0))
         into
           square_summ  
         from
           sm.grounds g
         where
           g.objects_id in (select o.id
                            from
                              sm.objects o,
                              sm.grounds gr
                            where
                              gr.objects_id=o.id and 
                              gr.baseground=this.id and
                              (nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))<=sysdate)and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))>=sysdate) and
                              not (nvl(o.EXISTS_SINCE,To_date('01.01.0001','dd.mm.yyyy')) > nvl(this.EXISTS_END,To_date('01.01.3000','dd.mm.yyyy')))
                           );

       ELSIF (this.EXISTS_SINCE IS NOT NULL) and (this.EXISTS_SINCE<sysdate) THEN
        -- находим площадь уже зарегистрированных частей данного ЗУ
         select
           sum(nvl(g.square,0))
         into
           square_summ  
         from
           sm.grounds g
         where
           g.objects_id in (select o.id
                            from
                              sm.objects o,
                              sm.grounds gr
                            where
                              gr.objects_id=o.id and 
                              gr.baseground=this.id and
                              (nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))<=sysdate)and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))>=sysdate)and
                              not(nvl(o.EXISTS_END,To_date('01.01.3000','dd.mm.yyyy'))<nvl(this.EXISTS_SINCE,To_date('01.01.0001','dd.mm.yyyy'))) 
                           );

       ELSIF (this.EXISTS_SINCE IS NOT NULL) and (this.EXISTS_END IS NOT NULL) THEN
         -- находим площадь уже зарегистрированных частей данного ЗУ
         select
           sum(nvl(g.square,0))
         into
           square_summ  
         from
           sm.grounds g
         where
           g.objects_id in (select o.id
                            from
                              sm.objects o,
                              sm.grounds gr
                            where
                              gr.objects_id=o.id and 
                              gr.baseground=this.id and
                              (nvl(o.exists_since,to_date('01.01.0001','dd.mm.yyyy'))<=sysdate)and(nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))>=sysdate) and
                              not ((nvl(o.EXISTS_END,To_Date('01.01.3000','dd.mm.yyyy')) < nvl(this.EXISTS_SINCE,To_date('01.01.0001','dd.mm.yyyy')))
                              or(nvl(o.EXISTS_SINCE,To_date('01.01.0001','dd.mm.yyyy')) > nvl(this.EXISTS_END,To_date('01.01.3000','dd.mm.yyyy'))))                               
                           );
       END IF; --IF4
    IF ((this.SQUARE-square_summ)<0) THEN --IF3
     raise_application_error(-20101, 'Земельный участок не может иметь площадь '||this.Square||' кв.м. для указанного срока существования'|| chr(13) ||
                                      'Суммараная площадь составляющих его частей в эти сроки равна '||square_summ||'кв.м., что превышает указанную площадь.'  );
    END IF; --IF3
  END IF; --IF2

  end loop; --LOOP2
 end loop;  --LOOP1

end;
/

