prompt
prompt Creating trigger GROUNDS_XMLRR_SAVECHANGES
prompt ==========================================
prompt
create or replace trigger "SM".Grounds_XMLRR_SaveChanges
  after insert or update  on grounds
  for each row

declare
 ChangeID integer;
 tblID number(27);
 UserName varchar2(250);
begin

if updating then

  --Если изменилась площадь
  if :new.square<>:old.square then
    
  
     tblID:=sm.xmlrosreestr_pkg.GetTableID('GROUNDS');
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284001000000'), sysdate, UserName, 'U',tblID,:new.objects_id);
           
           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_num,new_value_num)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'SQUARE'),:old.square, :new.square);      
     
        end if;
  end if;
  
  --Изменение категории  
  if :new.groundtypes_id<>:old.groundtypes_id then
     
  
     tblID:=sm.xmlrosreestr_pkg.GetTableID('GROUNDS');
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id, object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284002000000'), sysdate, UserName, 'U',tblID, :new.objects_id);
           
           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'groundtypes_id'),:old.groundtypes_id, :new.groundtypes_id);      
     
        end if;
  end if;
  
  --Изменение вида разрешенного использования
    if :new.release_id<>:old.release_id then
     
  
     tblID:=sm.xmlrosreestr_pkg.GetTableID('GROUNDS');
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id, object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284003000000'), sysdate, UserName, 'U',tblID, :new.objects_id);
           
           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,old_value_int,new_value_int)
           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'release_id'),:old.release_id, :new.release_id);      
     
        end if;
  end if;
  

  
end if; --end updating

if inserting then

     --образование части ЗУ
     if :new.baseground is not null then
     
     tblID:=sm.xmlrosreestr_pkg.GetTableID('GROUNDS');
        if nvl(tblID,-1)<>-1 then
           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id, object_id)
           values(ChangeID,:new.ID,sm.xmlrosreestr_pkg.GetChangeCode('284010001000'), sysdate, UserName, 'I',tblID, :new.objects_id);
           
        end if;
     end if;    
     
     
end if; --end inserting
exception
  when others then null;
end Grounds_XMLRR_SaveChanges;
/

prompt
prompt Creating trigger GROUND_OBJ
prompt ===========================
prompt
CREATE OR REPLACE TRIGGER "SM".GROUND_OBJ AFTER UPDATE OR INSERT ON sm.GROUNDS FOR EACH ROW
Declare
  S1 varchar2(4000);

  p number;

  grtCode sm.groundtypes.code%type;
  grtRootName sm.groundtypes.name%type;

  qStreet sm.streets.name%type;
  qHouse sm.address.house%type;
  qHouse_Char sm.address.house_char%type;
  qTank sm.address.tank%type;

 -- qKadastrNo sm.grounds.kadastrno%type;

  SmallInfo sm.objects.description%type;
  DescrLength number;
Begin
 /* 17/01/2014 Твердохлеб: запрос поиска типа зем. участка почему то 
   возвращал в триггре больше одной записи, хотя в тесте 1. 
   Сделал ограничение выборки одной записи*/
   
 -- обновляем OBJECTS.DESCRIPTION для земельных участков

 -- запросим размерность поля DESCRIPTION таблицы OBJECTS
  SELECT
    atc.DATA_LENGTH
  INTO
    DescrLength
  FROM
    all_tab_columns atc
  WHERE
    atc.OWNER='SM' and
    atc.TABLE_NAME='OBJECTS' and
    atc.COLUMN_NAME='DESCRIPTION';

 --RAISE_APPLICATION_ERROR(-20101, :new.groundtypes_id);
 -- Тип земельного участка. Отображать будем название раздела, в скобках - код подраздела
  SELECT
    gt.Code, gt1.name
  INTO
    grtCode,
    grtRootName
  FROM
    sm.groundtypes gt,
    sm.groundtypes gt1
  WHERE
    gt.ID=:new.groundtypes_id and
    gt1.name in (
                 SELECT
                   gt2.name
                 FROM
                   groundtypes gt2
                 WHERE
                   gt2.root is null
                 START WITH gt2.id = gt.ID
                 CONNECT BY PRIOR gt2.root = gt2.id
                ) and
     rownum <=1 ;
  -- Сократим назание типа земель
  p:=INSTR(grtRootName,',');
  if p<>0 then
    grtRootName:=SUBSTR(grtRootName,1,p)||' ..';
  end if;

  S1:=SUBSTR(TRIM(grtRootName),1,1)||TRIM(SUBSTR(LOWER(grtRootName),2,length(grtRootName)));
  --S1:=TRIM(S1)||' ('||grtCode||')';

  -- Вычисление адреса
  SELECT
    Streets.Name,
    Address.House,
    Address.House_Char,
    Address.Tank
  INTO
    qStreet,
    qHouse,
    qHouse_Char,
    qTank
  FROM
    sm.Address, sm.Streets
  WHERE
    Address.ID=:new.Address_ID and
	  Streets.ID(+)=Address.Streets_ID;

  S1:=TRIM(S1)||' ('|| RTRIM(TO_CHAR(:new.Square)) || ' кв.м.)';

  if :new.KadastrNo is not null then
    S1:=TRIM(S1)||' кад.№:'||:new.KadastrNo;
  end if;

  if qStreet is not null then
     S1:=TRIM(S1)||', '||TRIM(qStreet);
    if qHouse is not null then
      S1:=TRIM(S1)||', '||TRIM(TO_CHAR(qHouse));
      if qHouse_Char is not null then
        S1:=TRIM(S1)||'-'||TRIM(qHouse_Char);
      end if;
    end if;
    if qTank is not null then
      S1:=TRIM(S1)||'/'||TRIM(qTank);
    end if;
  end if;


 SmallInfo := SUBSTR(S1,1,DescrLength);

 UPDATE sm.Objects SET Description = SmallInfo  , Address_ID=:new.ADDRESS_ID WHERE ID=:new.Objects_ID;

End;
/

prompt
prompt Creating trigger MI_AFTER_DELETE
prompt ================================
prompt
CREATE OR REPLACE TRIGGER "SM".MI_AFTER_DELETE
  after delete on sm.MOVEITEMS
declare
  i number;  
  nTmp number(27); 
begin   
  if sm.mi_objstate_pkg.statesList.count>0 then
    for i in 1..sm.mi_objstate_pkg.statesList.count
    loop
      begin   
          --поиск ссылок на данное состояние
          select count(*) into nTmp from sm.MOVEITEMS mi where mi.state_id=sm.mi_objstate_pkg.statesList(i);
          if (nTmp = 0) then
              --проверка заполненности полей состояния, не связанных с количеством пакетов акций и долей
              --достаточно startpay проверить, поскольку только startpay доступно в окне св-в состояния для данного типа объекта
              select count(*) into nTmp 
                  from sm.STATES st 
                  where 
                      st.id=sm.mi_objstate_pkg.statesList(i) and  
                      st.startpay is not null;
              if (nTmp = 0) then
                 --удаление состояния
                 delete from sm.states s where s.ID=sm.mi_objstate_pkg.statesList(i);    
              end if;
          end if;
      exception
        when others then
          null;  
      end;  
    end loop;
  end if;

  sm.mi_objstate_pkg.statesList := sm.mi_objstate_pkg.empty;  
end;
/

