prompt ========================================
prompt
create or replace trigger "SM".MI_BEF_DEL_Fill_Storage
  before delete on sm.MOVEITEMS for each row
  --
  -- XSGROUP ver. 23.04.2012
  --
declare
  nTmp number(27);  
begin        
  select nvl(o.objtypes_id,0) into nTmp from sm.objects o where o.id=:old.object_id;
  --только если тип объекта "Пакеты акций, доли в капитале"
  if (nTmp = 21) then
     sm.mi_objstate_pkg.statesList(sm.mi_objstate_pkg.statesList.count+1) := :old.state_id;
  end if;
end;
