prompt
prompt Creating trigger MOVEITEMS_BEFORE_INS_UPD
prompt =========================================
prompt
CREATE OR REPLACE TRIGGER "SM".MOVEITEMS_BEFORE_INS_UPD
       before insert or update on sm.MOVEITEMS for each row
--
-- XSGROUP ver. 4.7.5
--  Запрещает изменение ссылки на состояние объекта.
--  Устанавливает ед.изм. количества.
--  Устанавливает размер доли в % и руб. по количеству акций,
--  для долевого участия устанавливает размер доли в руб. по количеству %.
Declare
  objTypesID number(27);
  nTmp number;
  orgform  sm.orgforms%ROWTYPE;
  OrgID number(27);
  nCost number(27,2);
  qDate date;
  nSharesNumber number(27,6);
  nNominal number(27,2);
  OperSharesID number(27);
Begin

  if (:new.OBJECT_ID is not null) then
      select o.OBJTYPES_ID into objTypesID from sm.OBJECTS o where o.ID=:new.OBJECT_ID;
      if (objTypesID <> 21) then
         :new.UNIT_ID := 3;  --шт.
         -- :new.AMOUNT := 1;

      -- для "движения" объекта типа 21
      else
          select count(*) into nTmp from sm.objshares osh where osh.objects_id=:new.OBJECT_ID;
          if (nTmp > 0) then
              select osh.organisations_id into OrgID from sm.objshares osh where osh.objects_id=:new.OBJECT_ID;
              if (OrgID is null) then
                  raise_application_error(-20101, 'Не указано юридическое лицо (эмитент) в объекте  .');
              end if;
          end if;

          select count(*) into nTmp from sm.organisations org, sm.orgforms f where f.id=org.orgform and org.id=OrgID;
          if (nTmp > 0) then
             select f.* into orgform from sm.organisations org, sm.orgforms f where f.id=org.orgform and org.id=OrgID;
          end if;

          -- если ОПФ ЮЛ с признаком "УП (может иметь уставной фонд)" или "хоз. общ-во (может иметь уставный капитал)"
          if (orgform.HASAUTHORIZEDFUND = 'Y' or orgform.HASAUTHCAPITAL = 'Y') then

               select count(*) into nTmp from sm.moveperiods mp where mp.id= :new.moveperiod_id;
               if (nTmp = 0) then -- if (INSERTING) then
                  qDate := sysdate;  -- before insert MI при создании ОД приходится брать sysdate
               else
                  select mp.sincedate into qDate from sm.moveperiods mp where mp.id= :new.moveperiod_id;
               end if;

               -- проверяем, наличие УК(УФ) ЮЛ
               nCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID,qDate,'C'),0);
               if (nCost <= 0) then
                  select count(*) into nTmp
                         from sm.moveperiods mp
                         where mp.moveset_id=(select mpp.moveset_id from sm.moveperiods mpp where mpp.id=:new.moveperiod_id) and mp.prev_moveperiod_id is null;
                  if (nTmp = 0) then
                     raise_application_error(-20101, 'Движение не сохранится. Сначала сформируйте уставный '||chr(10)
                                                  ||(case when orgform.HASAUTHORIZEDFUND='Y' then 'фонд' else '(складочный) капитал' end)
                                                  ||' юридического лица (эмитента) .');
                  end if;
               end if;

               -- если действие не в контексте операции с УК
               if (sm.opershares_pkg.opersharesContext is null or sm.opershares_pkg.opersharesContext <> 'Y') then
                if (nCost <> 0) then
                  -- УЧАСТИЕ АКЦИЯМИ и не "закрытие" ОД (0 - при закрытии)
                  if (orgform.IS_JSC = 'Y') then                           
                      -- если не "закрытие" ОД (0 - при закрытии)
                      if (nvl(:new.SHARESNUMBER,0) <> 0) then
                             -- если АО, то заполнение поля "количество акций" обязательно
                             if (nvl(:new.SHARESNUMBER,0) = 0) then
                                raise_application_error(-20101, 'Не указано количество акций  на ' ||to_char(qDate, 'dd.MM.yyyy') );
                             end if;

                            -- проверяем, правильно ли указано количество акций
                            select count(*) into nTmp
                               from sm.opershares opsh, sm.objshares osh
                               where opsh.id=osh.opershares_id and osh.objects_id=:NEW.object_id;
                            if (nTmp > 0) then
                                 -- количество выпущенных акций, номинал данной эмиссии
                                 select nvl(opsh.amount,0),
                                           (case when opsh.currency_id=1 then nvl(opsh.nominal,0)
                                                    when opsh.currency_id<>1 and nvl(opsh.amount,0)<>0 then round(nvl(opsh.nominalcost,0)/opsh.amount, 2)
                                                    else 0 end),
                                           obsh.opershares_id
                                        into nSharesNumber, nNominal, OperSharesID
                                        from sm.opershares opsh, sm.objshares obsh
                                        where opsh.id=obsh.opershares_id and obsh.objects_id=:NEW.object_id;
                                 if (:new.SHARESNUMBER > nSharesNumber) then
                                      raise_application_error(-20101, 'Указанное количество акций '  ||:new.SHARESNUMBER || ' превышает ' ||chr(10)
                                                                      ||' количество выпущенных акций данной эмиссии на ' ||to_char(qDate, 'dd.MM.yyyy') );
                                 end if;
                                 if (nNominal = 0) then
                                     raise_application_error(-20101, 'Неизвестен номинал акций на ' ||to_char(qDate, 'dd.MM.yyyy') );
                                 end if;

                                -- общее количество выпущенных акций
                                nSharesNumber := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(OrgID,qDate,'N'),0);
                                if (nSharesNumber <> 0) then
                                   -- рассчет размера доли в % и руб. по количеству акций (введенные вручную значения игнорируются)
                                   -- 13/01/2015 Твердохлеб, если передали стоимость, то не рассчитываем ее
                                   if (:new.NOMINALCOST is null)then
                                      :new.NOMINALCOST := round(:new.SharesNumber * nNominal, 2);
                                   end if;
                                   :new.AMOUNT := round(:new.NOMINALCOST * 100 / nCost, 6);
                                else
                                    raise_application_error(-20101, 'Неизвестно общее количество выпущенных акций на ' ||to_char(qDate, 'dd.MM.yyyy') );
                                end if;
                            else
                                raise_application_error(-20101, 'Не удалось определить количество выпущенных акций и номинал данной эмиссии на ' ||to_char(qDate, 'dd.MM.yyyy') );
                            end if;

                      -- при "закрытии" ОД
                      else
                            :new.NOMINALCOST := 0;
                            :new.AMOUNT := 0;
                      end if;

                      --- Измененн блок 21/05/2015

                  -- ДОЛЕВОЕ УЧАСТИЕ  (ЮЛ с уставным (складочным) капиталом) и не "закрытие" ОД (0 - при закрытии)
                  elsif (orgform.HASAUTHCAPITAL = 'Y') then
                      -- изменено 26/05/2015 Твердохлеб: приоритет по размеру доли
                      if (nvl(:new.NOMINALCOST,0) <> 0 and nvl(:new.AMOUNT,0) = 0)then
                         :new.AMOUNT := round(nvl(:new.NOMINALCOST,0) * 100 / nCost, 6);
                      elsif (nvl(:new.NOMINALCOST,0) = 0 and nvl(:new.AMOUNT,0) <> 0) then
                         :new.NOMINALCOST := sm.SharesValue_PKG.GetSharesNominalCost(:NEW.object_id, :new.AMOUNT, qDate);
                      end if;

                    -- изменено 26/05/2015 Твердохлеб: закоментил простым коментарием и сделал приоритет по размеру доли (блок выше)
                    --   if (nvl(:new.AMOUNT,0) <> 0) then
                        /* -- Проверяем поля и требуем ввода
                         if (nvl(:new.AMOUNT,0) = 0 ) then
                            raise_application_error(-20101, 'Не указан размер доли в процентах  .');
                         end if;*/
                         -- рассчет размера доли в руб. по количеству % (введенное вручную значение игнорируется)
                    --     :new.NOMINALCOST := sm.SharesValue_PKG.GetSharesNominalCost(:NEW.object_id, :new.AMOUNT, qDate);
                    --  elsif (nvl(:new.NOMINALCOST,0)<>0) then
                    --     :new.AMOUNT := round(nvl(:new.NOMINALCOST,0) * 100 / nCost, 6);
                    -- end if;
                      -- при "закрытии" ОД
                    /*  else
                            :new.NOMINALCOST := 0;
                      end if;*/

                  end if;  --end АКЦИИ и ДОЛЕВОЕ УЧАСТИЕ

                  -- 26/05/2015 Твердохлеб: убрал проверку так как мы имеем размер доли и высчитываем процент
                  -- но процент при расчете с большим количеством знаков. а у нас хранится всего лишь 6

                  -- проверяем, правильно ли указан размер доли и номинальная стоимость
                  /*
                  if (orgform.HASAUTHCAPITAL = 'Y') then
                     if (:new.NOMINALCOST > nCost) then
                        raise_application_error(-20101, 'Указанная номинальная стоимость всей доли ' ||chr(10)
                                                        ||' превышает размер уставного (складочного) капитала на ' ||to_char(qDate, 'dd.MM.yyyy') );
                     end if;
                     if (:new.AMOUNT > 100) then
                        raise_application_error(-20101, 'Размер доли не должен превышать 100%');
                     end if;
                     --if (trunc(:new.AMOUNT, 4) <> trunc(:new.NOMINALCOST * 100 / nCost, 4)) then
                     --   raise_application_error(-20101, 'Проверьте номинальную стоимость и размер доли на ' ||to_char(qDate, 'dd.MM.yyyy') );
                     --end if;
                  end if;*/
                 end if; -- end nCost<>0
               end if; --end  если действие не в контексте операции с УК
          end if;
          -- ед. изм. - %
          :new.UNIT_ID := 4;
      end if; --if (objTypesID <> 21)
  end if;
End;
/

