prompt
prompt Creating trigger MOVEITEMS_SHAREPERCENT_UPD
prompt ===========================================
prompt
create or replace trigger "SM".MoveItems_SHAREPERCENT_UPD
  before insert or update on moveitems
  for each row

declare  
  ObjT number;
begin
  if INSERTING then
    if :new.SQUARE is null then
    
      select ob.objtypes_id into ObjT from sm.objects ob where ob.id=:new.object_id;
      if  ObjT=3 then 
        select bld.square into :new.SQUARE from sm.buildings bld where bld.objects_id=:new.object_id;  -- здания и помещения 
      elsif ObjT=5 then 
        select eng.square into :new.SQUARE from sm.enginf eng where eng.objects_id=:new.object_id;     -- инж.инфраструктура
      elsif ObjT=7 then 
        select gr.square into :new.SQUARE from sm.grounds gr where gr.objects_id=:new.object_id;       -- земельные участки
      end if;

    end if;
      
  end if;
  if (:new.share_num /:new.share_denom )>1.000 then
    raise_application_error(-20101, 'Доля не может быть больше целого!' );
  end if;
  :new.sharepercent:=(:new.share_num /:new.share_denom )*100;
end MISHAREPERCENTUPD;
/

