prompt
prompt Creating trigger MOVEMENTS_DEL
prompt ==============================
prompt
create or replace trigger "SM".Movements_Del
  instead of delete on sm.movements
  for each row

declare
  FMovePerCnt number;
  FMoveItemCnt number;
begin
  select count(mp.id) into FMovePerCnt
  from
    sm.moveperiods mp
  where
    mp.moveset_id=:old.moveset_id;

  select count (*) into FMoveItemCnt
  from
  (
    select mi.id 
    from
      sm.moveitems mi,
      sm.links_mi_objects mio
    where
      mi.id=mio.moveitems_id and
      mi.moveperiod_id=:old.moveperiod_id
    union all 
    select mi.id 
    from
      sm.moveitems mi
    where
      mi.moveperiod_id=:old.moveperiod_id
  );
    
  if FMovePerCnt>1 then
    raise_application_error(-20101, 'Невозможно удалить операцию движения - '||chr(13)||'Обнаружено более одного периода.');
  end if;
  if FMoveItemCnt>1 then
    raise_application_error(-20101, 'Невозможно удалить операцию движения - '||chr(13)||'Обнаружено более одного объекта.');
  end if;

  delete from sm.moveitems mi
  where
    mi.moveperiod_id=:old.moveperiod_id;

  delete from sm.moveperiods mp
  where
    mp.moveset_id=:old.moveset_id;

  delete from sm.movesets ms
  where
    ms.id=:old.moveset_id;

end;
/

prompt
prompt Creating trigger MOVEMENTS_TO_MOVESETS
prompt ======================================
prompt
create or replace trigger "SM".Movements_to_Movesets
  instead of insert on sm.movements
  for each row
--
--  by XSGROUP ver. 15.10.2012
-- триггер для подстановки в соответствующие таблицы значений при попытке вставки записи в представление movements
--
--
declare

  i integer;
  FullUserName sm.Registeredusers.fullname%type;
  len number;
begin

  i:=:new.id;
  if i is null then
   select Seqmovements.Nextval into i from dual;
  end if;

  -- подпись
  SELECT ru.FullName INTO FullUserName FROM sm.RegisteredUsers ru WHERE ru.UserName=USER;
  -- определяем размерность поля CHANGEDBY таблицы MOVEPERIODS
  select
    atc.DATA_LENGTH
  into
    len
  from
    all_tab_columns atc
  where
    atc.OWNER='SM' and
    atc.TABLE_NAME='MOVEPERIODS' and
    atc.COLUMN_NAME='CHANGEDBY';
  -- укорачиваем до размерности поля CHANGEDBY таблицы MOVEPERIODS
  FullUserName:=SUBSTR(FullUserName,1,len);

  insert into sm.docsets (id)
    values (sm.seqdocsets.nextval);
  insert into sm.docset_members (docset_id,document_id,docrole_id)
    values (sm.seqdocsets.currval,:new.documents_id,1);
  insert into sm.movesets (id,movetype_id,client_id,docset_id,transferbasis_id,sharemove_id,hideinreports,verified,munreport_id)
    values (sm.seqmovesets.nextval,:new.movetype_id,:new.clientsto_id,sm.seqdocsets.currval,:new.transfbasis_id,:new.sharemove_id,:new.hideinreports,:new.verified,:new.munreport_id);
  insert into sm.moveperiods (id,sincedate,enddate,moveset_id,docset_id,prev_moveperiod_id,changedby,writedate)
    values (sm.seqmoveperiods.nextval,:new.postingdate,:new.enddate,sm.seqmovesets.currval,sm.seqdocsets.currval,null,FullUserName,sysdate);
  insert into sm.MoveItems (id,object_id,moveperiod_id,leasepurpose_id,square,params,share_num,share_denom,price,state_id)
    values (i,:new.objects_id,sm.seqmoveperiods.currval,:new.leasepurpose_id,:new.square,:new.params,nvl(:new.share_num,1),nvl(:new.share_denom,1),:new.price,:new.state_id);
end;
/

prompt
prompt Creating trigger MOVEPERIODS_BEFORE_UPD
prompt =======================================
prompt
CREATE OR REPLACE TRIGGER "SM".MOVEPERIODS_BEFORE_UPD 
       before update on sm.MOVEPERIODS for each row
--
-- XSGROUP ver. 23.04.2012 patch 1.
--  Запрещает изменять период для ОД Собственность 
-- с объектами "Пакеты акций и долей в уставном капитале"
--
Declare 
 iTmp number(27);
Begin
  if (:NEW.SINCEDATE <> :OLD.SINCEDATE) then
      select count(*) into iTmp 
             from sm.moveitems mi, sm.objects o
             where    
                   o.id=mi.object_id and o.OBJTYPES_ID=21 and mi.moveperiod_id = :NEW.ID
                   and exists (select * from sm.movesets ms where ms.MOVETYPE_ID=1 and ms.id=:NEW.moveset_id);                      
      if (iTmp > 0) then
           raise_application_error(-20101, 'Нельзя изменять период операции движения ''Собстенность''' ||chr(10) ||
                                                     ' с объектами типа ''Пакеты акций, доли в капитале''');  
      end if;      
  end if;  
End;
/

prompt
prompt Creating trigger MOVEPERIODS_CHECKS
prompt ===================================
prompt
create or replace trigger "SM".MovePeriods_Checks
  after insert or update on sm.moveperiods
  
  -- by XSGROUP ver.15.02.2012
  -- проверка корректности установления дат начала и окончания периодов операций движения

declare
  i number;
  MIN_DATE varchar2(20):='01.01.1900';
  MAX_DATE varchar2(20):='31.12.2100';

begin
 
  if not sm.movper_pkg.DoNotFillStorage then 
    
     for i in 1 .. sm.movper_pkg.updRows.count loop --LOOP 1 читаем данные из movper_pkg
       for new in (select * from sm.moveperiods where rowid = sm.movper_pkg.updRows(i) ) 
       loop --LOOP2
         if new.SinceDate is not null then
           if new.SinceDate<to_date(MIN_DATE,'DD.MM.YYYY') then
             raise_application_error(-20101, 'Дата начала периода операции движения '||to_char(new.SinceDate,'DD.MM.YYYY')||' противоречит минимально допустимому знвачению: '||MIN_DATE);
           end if;
           if new.SinceDate>to_date(MAX_DATE,'DD.MM.YYYY') then
             raise_application_error(-20101, 'Дата начала периода операции движения '||to_char(new.SinceDate,'DD.MM.YYYY')||' противоречит максимально допустимому знвачению: '||MAX_DATE);
           end if;
         end if; 
          
         if nvl(new.SinceDate,to_date('01-01-1000','DD-MM-YYYY'))>nvl(new.EndDate,to_date('31-12-4000','DD-MM-YYYY')) then
           raise_application_error(-20101, 'Дата окончания периода операции движения'||chr(13)||'не может быть раньше даты его начала!' );
         end if;
         if new.prev_moveperiod_id is not null then --if00
    
           for xxx in (select *
                       from
                         sm.moveperiods mp
                       where
                         mp.id=new.prev_moveperiod_id)
           loop --xxx
             if xxx.sincedate>=new.sincedate then
               raise_application_error(-20101, 'Дата начала периода операции движения'||chr(13)||'противоречит срокам предыдущего периода!' );
             else
            -- устанавливаем срок окончания предыдущего периода
               if xxx.enddate<>new.sincedate-1 then
                 sm.movper_pkg.DoNotFillStorage:=true;
                 update sm.moveperiods set enddate=new.sincedate-1 where id=new.prev_moveperiod_id;
                 sm.movper_pkg.DoNotFillStorage:=false;
               end if;
             end if;
           end loop; --xxx
    
           end if; --if00
           --sm.FullRecalcCharges(new.moveset_id);
        end loop; -- LOOP2
      end loop; -- LOOP1
      
  end if;
  
end;
/

