prompt Creating trigger MOVEPERIODS_SAVE_USERNAME
prompt ==========================================
prompt
create or replace trigger "SM".MOVEPERIODS_SAVE_USERNAME
  before insert or update on moveperiods
  for each row

  -- by XSGROUP ver. 15.02.2012
  -- триггер фиксирует пользователя, внёсшего изменения в период операции движения

declare
  FullUserName sm.registeredusers.fullname%type;
  len integer;
begin

  if not sm.movper_pkg.DoNotFillStorage then
    select
      atc.DATA_LENGTH
    into
      len
    from
      all_tab_columns atc
    where
      atc.OWNER='SM' and
      atc.TABLE_NAME='MOVEPERIODS' and
      atc.COLUMN_NAME='CHANGEDBY';  
    
    select ru.FullName into FullUserName 
    from 
      RegisteredUsers ru 
    where 
      upper(trim(ru.Username))=upper(trim(USER));
  
    begin
      :new.changedby:=SUBSTR(FullUserName,1,len);
    exception
      when others then
        :new.changedby:=user;
    end;
  
    :new.writedate:=sysdate;
 
  end if; 

end;
/

