prompt
prompt Creating trigger MOVESETS_BEFORE_INS_UPD
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER "SM".MOVESETS_BEFORE_INS_UPD 
       before insert or update on sm.MOVESETS for each row
--
-- XSGROUP ver. 23.04.2012
-- Проверяет и принудительно исправляет
-- флаги ISFOUNDER и ISCONTRIBUTION
-- в ОД Собственность 
--
Declare 
 iTmp integer;
Begin
  if (:new.movetype_id = 1) then
     
     -- "в роли учредителя"
     if (:new.ISFOUNDER = 'Y') then
              -- отчуждение(продажа)
         if (:new.CLIENT_ID <> sm.multiowning_pkg.GetCurrentOwnerID()) then
              -- очистим флаг принудительно
              :new.ISFOUNDER := 'N';
         end if;
         
     end if; 
     
     -- "в качестве вклада" приобретение (покупка)   
     if (:new.ISCONTRIBUTION = 'Y' and 
         :new.CLIENT_ID = sm.multiowning_pkg.GetCurrentOwnerID()
        ) then
          -- очистим флаг принудительно
          :new.ISCONTRIBUTION := 'N';
     end if; 
     
 end if; 
End;
/

prompt
prompt Creating trigger MOVESETS_BEFORE_UPD
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER "SM".MOVESETS_BEFORE_UPD 
       before update on sm.MOVESETS for each row
--
-- XSGROUP ver. 23.04.2012
--  Запрещает изменение субъекта в ОД Собственность 
--  с объектами "Пакеты акций и долей в уставном капитале"
--
Declare 
 iTmp number(27);
Begin
  if (:new.movetype_id = 1) then
     
      if (:new.client_id <> :old.client_id) then             
          select count(*) into iTmp 
          from sm.moveperiods mp, sm.moveitems mi, sm.objects o
          where 
                 mi.moveperiod_id=mp.id and 
                 o.id=mi.object_id and 
                 mp.moveset_id=:new.ID and 
                 o.OBJTYPES_ID=21;
          if (iTmp > 0) then
             raise_application_error(-20101, 'Нельзя изменять субъекта операции движения ''Собстенность''' ||chr(10) ||
                                                       ' с объектами типа ''Пакеты акций, доли в капитале''');
          end if; 
     end if; 
     
 end if; 
End;
/

