prompt Creating trigger MOVESETS_FILL_STORAGE
prompt ======================================
prompt
create or replace trigger "SM".MOVESETS_FILL_STORAGE
  before insert or update or delete on MOVESETS for each row
declare
  MS_ID number;  
  iTmp integer;
begin
  /*if INSERTING then
    insert into test (id,name) values (sm.seqaddress.nextval,'MOVESETS_FILL_STORAGE - insert');
  else
    insert into test (id,name) values (sm.seqaddress.nextval,'MOVESETS_FILL_STORAGE - update');
  end if;*/
  
  if inserting or updating then
   MS_ID:=:new.id;
  else
   MS_ID:=:old.id;
  end if;
  
  for xx in (select distinct 
              mi.object_id 
            from
              sm.moveperiods mp,
              sm.moveitems mi
            where
              mi.moveperiod_id=mp.id and
              mp.moveset_id=MS_ID)
  loop
    sm.moveitems_state_pkg.ObjList(moveitems_state_pkg.ObjList.count+1):=xx.object_id;
    
    -- XSGROUP ver. 23.04.2012
    --флаг "в роли учредителя" устанавливается только с объектом "Пакет акций, доли"
    if (:new.movetype_id = 1 and :new.ISFOUNDER = 'Y') then
        select count(*) into iTmp from sm.objects o where o.id=xx.object_id and o.objtypes_id=21;
        if (iTmp = 0) then
            -- очистим флаг принудительно
            :new.ISFOUNDER := 'N';
        end if;
    end if;
                    
  end loop;
  
end;
/

