prompt
prompt Creating trigger OBJECT_AFTER_CHANGE_EX_CHECK
prompt =============================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJECT_AFTER_CHANGE_EX_CHECK
  after insert or update of EXISTS_SINCE, EXISTS_END on sm.objects
declare
  -- v. 4.8.4 (20.06.2014)
  -- редакция v. 4.8.5 (04.03.2015)
  --Purpose: Для земельных участков и зданий и помещений производим корректировку сроков существования объетка с проверкой на ОД
cnt integer;
root_since date; --дата начала существования контейнера ЗУ
root_end date; --дата окончания существования контейнера ЗУ
--
root_SINCE_DATE DATE;  --дата начала срока существования владельца данного объекта
root_END_DATE DATE;    --дата окончания срока существования владельца данного объекта
cntMoves INTEGER;      --количество зарегистрированных движений
cntChild INTEGER;      --количество дочерних объектов
oldEXISTS_SINCE  DATE; --старое значение начала срока существования объекта
oldEXISTS_END DATE;    --старое значение конца срока существования объекта
ids number(27);
begin
---==================Для земельных участков==========================---
    if sm.obj_pkg.GroundExDateRows.count>0 then
        for i in 1..sm.obj_pkg.GroundExDateRows.count
        loop        
             for x in (select g.*,
                     nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) exists_since,
                     nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) exists_end
               from
                 sm.Grounds g,
                 sm.objects o
               where
                 o.id=sm.obj_pkg.GroundExDateRows(i) and
                 g.objects_id=o.id)
             loop 
               
                    -- 1) находим все ЗУ, которые являются частью от данного участка и проверяем их даты существования
                    for c in ( select o.exists_since, o.exists_end,o.id
                              from sm.objects o,
                              sm.grounds g
                              where o.id=g.objects_id and
                              g.baseground=x.id)
                    loop
                      if nvl(x.exists_since,to_date('01.01.0001', 'dd.mm.yyyy'))>nvl(c.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')) then 
                        --Проверяем, существуют ли ОД для частей, которые могут препятсвовать 
                        --изменению даты начала существования
                        select count(ms.id)
                        into cnt
                        from sm.movesets ms,
                        sm.moveperiods mp,
                        sm.moveitems mi
                        where ms.id=mp.moveset_id and
                        mp.id=mi.moveperiod_id and
                        mi.object_id=c.id and
                        mp.sincedate<nvl(x.exists_since,to_date('01.01.0001', 'dd.mm.yyyy'));
                          if cnt=0 then  
                              if c.exists_since is not null then                            
                                   raise_application_error(-20101, 'Дата начала существования базового земельного участка ('||x.exists_since||') позже даты начала существования одной из частей этого земельного участка ('||c.exists_since||').');
                                 --update sm.objects o set o.exists_since=x.exists_since where o.id=c.id;
                              end if;  
                          else
                             raise_application_error(-20101, 'Невозможно изменить дату начала существования базового земельного участка ('||x.exists_since||') т.к. имеются части этого земельного участка с операциями движения, дата начала которых раньше нового срока существования объекта.');
                           end if;
                       end if;
                      
                       if nvl(x.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))<nvl(c.exists_end,to_date('01.01.3000', 'dd.mm.yyyy')) then 
                            select count(ms.id)
                            into cnt
                            from sm.movesets ms,
                            sm.moveperiods mp,
                            sm.moveitems mi
                            where ms.id=mp.moveset_id and
                            mp.id=mi.moveperiod_id and
                            mi.object_id=c.id and
                            mp.sincedate>nvl(x.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'));
                            if cnt=0 then 
                               if c.exists_end is not null then 
                                 raise_application_error(-20101, 'Дата окончания существования базового земельного участка ('||x.exists_end||') раньше даты окончания существования одной из частей этого земельного участка ('||c.exists_end||').'); 
                                  --update sm.objects o set o.exists_end=x.exists_end where o.id=c.id;
                               end if;
                            else
                              raise_application_error(-20101, 'Невозможно изменить дату окончания существования базового земельного участка ('||x.exists_end||') т.к. имеются части этого земельного участка с операциями движения, дата начала которых позже нового срока существования объекта.');
                            end if;
                     end if;                      
                    end loop; 
                    
                    --2) находим базовый участок (контейнер) для данного 
                   if x.baseground is not null then                     
                         select                    
                           nvl(o.exists_since,to_date('01.01.0001', 'dd.mm.yyyy')),
                           nvl(o.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'))
                         into                  
                           root_since,
                           root_end  
                         from sm.objects o, sm.grounds g where  o.id=g.objects_id and g.id=x.baseground; 
                         
                          IF root_since>x.exists_since THEN 
                             raise_application_error(-20101, 'Дата начала существования части земельного участка, не может быть раньше даты начала существования базового участка.' );
                           END IF; 
                        
                           IF root_end<x.exists_end THEN 
                             raise_application_error(-20101, 'Дата окончания существования части земельного участка, не может быть позже даты окончания существования базового участка.' );
                           END IF; 
                    end if;
                  
                  --3) проверка на  собственные ОД ЗУ  
                  select count(ms.id)
                  into cnt
                  from sm.movesets ms,
                  sm.moveperiods mp,
                  sm.moveitems mi
                  where ms.id=mp.moveset_id and
                  mp.id=mi.moveperiod_id and
                  mi.object_id=x.objects_id and
                  mp.sincedate<nvl(x.exists_since,to_date('01.01.0001', 'dd.mm.yyyy'));
                  if cnt>0 then 
                      raise_application_error(-20101, 'Невозможно изменить дату начала существования земельного участка ('||x.exists_since||') т.к. имеются оформленные операции движения, дата начала которых раньше нового срока существования объекта.');
                  end if;
                  
                  select count(ms.id)
                  into cnt
                  from sm.movesets ms,
                  sm.moveperiods mp,
                  sm.moveitems mi
                  where ms.id=mp.moveset_id and
                  mp.id=mi.moveperiod_id and
                  mi.object_id=x.objects_id and
                  mp.sincedate>nvl(x.exists_end,to_date('01.01.3000', 'dd.mm.yyyy'));
                  if cnt>0 then 
                      raise_application_error(-20101, 'Невозможно изменить дату окончания существования земельного участка ('||x.exists_end||') т.к. имеются оформленные операции движения, дата начала которых позже нового срока существования объекта.');
                  end if; 
                  
                  --4) проверка на корректность сроков существования
                  if x.exists_end<x.exists_since then 
                      raise_application_error(-20101, 'Дата окончания существования земельного участка ('||x.exists_end||') не может быть раньше даты начала его существования ('||x.exists_since||').');
                  end if;                                             
            end loop;          
        end loop;
    end if;
    
 -------===================Для зданий и помещений ================================-------
 for i in 1 .. sm.obj_pkg.BuildingExDateRows.count loop --LOOP 1 читаем данные из bld_state_pkg
   ids:=sm.obj_pkg.BuildingExDateRows(i);
  for new in (select b.BASEBUILDING, b.OBJECTS_ID, b.id, o.exists_since, o.exists_end 
              from sm.buildings b,
                   sm.objects o
              where o.id=b.objects_id and
              o.id=sm.obj_pkg.BuildingExDateRows(i)) loop --LOOP2
   oldEXISTS_SINCE:=sm.obj_pkg.ExSINCE(i);
   oldEXISTS_END:=sm.obj_pkg.ExEND(i);

  IF ((nvl(oldEXISTS_SINCE,TO_DATE('01-01-1000','dd-mm-yyyy'))<>nvl(new.EXISTS_SINCE, TO_DATE('01-01-1000','dd-mm-yyyy')))and(new.EXISTS_SINCE IS NOT NULL))
     or
     ((nvl(oldEXISTS_END,TO_DATE('01-01-1000','dd-mm-yyyy'))<>nvl(new.EXISTS_END, TO_DATE('01-01-1000','dd-mm-yyyy')))and(new.EXISTS_END IS NOT NULL)) THEN--IF2 обработка нужна только, если хотя бы одна из дат меняется

   IF new.BASEBUILDING IS NOT NULL THEN --IF3 если помещение не является помещением верхнего уровня
    root_SINCE_DATE:=null;
    root_END_DATE:= null;

   --ищем установленные даты EXISTS_SINCE и EXISTS_END у объектов верхнего уровня
   SELECT MAX(o.EXISTS_SINCE), MIN(o.EXISTS_END)
   INTO root_SINCE_DATE, root_END_DATE
   FROM sm.Buildings b,
        sm.objects o
   WHERE o.id=b.objects_id 
   START WITH b.ID=new.BASEBUILDING CONNECT BY PRIOR BASEBUILDING=b.ID;

    --проверяем, не выходит ли новая дата за пределы допустимого
    IF (root_SINCE_DATE IS NOT NULL) THEN --IF4
     IF (root_SINCE_DATE>new.EXISTS_SINCE) THEN --IF5
      raise_application_error(-20101, 'Дата начала срока существования объекта не может быть'||chr(13)
                                    ||'ранее даты начала срока существования объекта верхнего уровня!' );
     END IF; --IF5
    END IF; --IF4

    IF root_END_DATE IS NOT NULL THEN --IF5
     IF (root_END_DATE<new.EXISTS_END) THEN --IF6
      raise_application_error(-20101, 'Дата окончания срока существования объекта не может быть установлена'||chr(13)
                                    ||'позже даты окончания срока существования объекта верхнего уровня!' );
     END IF; --IF6
    END IF; --IF5
    
    --проверяем, дата начала существования объекта не должна быть позже даты прекращения
    -- существования контейнера.
    IF (root_END_DATE IS NOT NULL) THEN --IF4
     IF (root_END_DATE<new.EXISTS_SINCE) THEN --IF5
      raise_application_error(-20101, 'Дата начала срока существования объекта не может быть'||chr(13)
                                    ||'позже даты окончания срока существования объекта верхнего уровня!' );
     END IF; --IF5
    END IF; --IF4


    IF updating THEN --IF7 ТОЛЬКО ПРИ ИЗМЕНЕНИИ ЗАПИСИ!!!
   
   -- для работы с новой структурой операций движения
      IF (new.EXISTS_SINCE IS NOT NULL)and(new.EXISTS_END IS NOT NULL) THEN --IF10 для обеих непустых дат
       SELECT Count(*) INTO cntMoves
       FROM
         sm.moveitems mi,
         sm.moveperiods mp
       WHERE
         mi.object_id=new.OBJECTS_ID and
         mi.moveperiod_id=mp.id and
        ((mp.sincedate<new.EXISTS_SINCE)or(nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>new.EXISTS_END));
      ELSIF (new.EXISTS_SINCE IS NULL)and(new.EXISTS_END IS NOT NULL) THEN --не задана дата начала срока существования
       SELECT Count(*) INTO cntMoves
       FROM
         sm.moveitems mi,
         sm.moveperiods mp
       WHERE
         mi.object_id=new.OBJECTS_ID and
         mi.moveperiod_id=mp.id and
         nvl(mp.enddate,to_date('01.01.3000','dd.mm.yyyy'))>new.EXISTS_END;
      ELSIF (new.EXISTS_SINCE IS NOT NULL)and(new.EXISTS_END IS NULL) THEN  --не задана дата окончания срока существования
       SELECT Count(*) INTO cntMoves
       FROM
         sm.moveitems mi,
         sm.moveperiods mp
       WHERE
         mi.object_id=new.OBJECTS_ID and
         mi.moveperiod_id=mp.id and
         mp.sincedate<new.EXISTS_SINCE;
      END IF; --F10*/

      IF cntMoves<>0 THEN --IF9
       raise_application_error(-20101, 'Обнаружены зарегистрированные операции движения,'||chr(13)
                                     ||'чьи сроки противоречат вносимым изменениям!');
      ELSE
     --и устаналиваем сроки жизни  для  детей данного объекта уровнем ниже (если открыты и если не противоречат устанавливаемым)
       begin
         IF new.EXISTS_END IS NOT NULL THEN --IF0
          begin
           SELECT Count(*) INTO cntChild --есть ли дети у которых проставлены даты конца срока жизни?
           FROM sm.Buildings b,
                sm.objects o
           WHERE o.id=b.objects_id and (BASEBUILDING=new.ID)and((o.EXISTS_END IS NULL)or(o.EXISTS_END>new.EXISTS_END));
           IF cntChild<>0 THEN --IF00 если есть
            UPDATE sm.objects SET EXISTS_END=new.EXISTS_END WHERE ID in (SELECT o.id FROM sm.Buildings b,sm.objects o WHERE o.id=b.objects_id and (BASEBUILDING=new.ID)and((o.EXISTS_END IS NULL)or(o.EXISTS_END>new.EXISTS_END)));
           END IF; --IF00
          end;
         END IF; --IF0
         IF new.EXISTS_SINCE IS NOT NULL THEN --IF01
          begin
           SELECT Count(*) INTO cntChild --есть ли дети у которых проставлены даты начала срока жизни?
           FROM sm.Buildings b,
                sm.objects o
           WHERE b.objects_id=o.id and  (BASEBUILDING=new.ID)and((o.EXISTS_SINCE IS NULL)or(o.EXISTS_SINCE<new.EXISTS_SINCE));
           IF cntChild<>0 THEN --IF001 если есть
            UPDATE sm.objects SET EXISTS_SINCE=new.EXISTS_SINCE WHERE  ID in (SELECT o.id FROM sm.Buildings b,sm.objects o  WHERE b.objects_id=o.id and  (BASEBUILDING=new.ID)and((o.EXISTS_SINCE IS NULL)or(o.EXISTS_SINCE<new.EXISTS_SINCE)));
           END IF; --IF001
          end;
         END IF; --IF01
       end;
      END IF; --IF9
    END IF; --IF7
   END IF; --IF3
  END IF; --IF2  
  end loop; --LOOP2
 end loop;  --LOOP1   
end;
/

