prompt Creating trigger OBJECT_AFTER_CHANGE_EX_END
prompt ===========================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJECT_AFTER_CHANGE_EX_END
  after insert or update of EXISTS_SINCE, EXISTS_END on sm.objects  
declare
  -- local variables here
 
begin
    if sm.sd3_utils.ObjectsIDs.count>0 then
        for i in 1..sm.sd3_utils.ObjectsIDs.count 
        loop
          begin
              update sm.sd3_og_original oo set oo.sd3_geometry_metadata_id=oo.sd3_geometry_metadata_id
              where oo.sd3_geometry_metadata_id
                  in (select gm.id from sm.sd3_geometry_metadata gm where gm.data_id=sm.sd3_utils.ObjectsIDs(i) and gm.type_id=1);
          exception
            when others then null;
          end;  
        end loop;
    end if;  
end;
/

