prompt Creating trigger OBJECT_AFTER_DELETE
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJECT_AFTER_DELETE
  after delete on objects  

begin

  if storage_pkg.AddressIDs.count>0 then
    for i in 1..storage_pkg.AddressIDs.count 
    loop
      begin
        delete from sm.ADDRESS a where a.ID=storage_pkg.AddressIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;

  if docsets_state_pkg.ObjectsDocSetIDs.count>0 then
    for i in 1..docsets_state_pkg.ObjectsDocSetIDs.count 
    loop
      begin
        delete from sm.DocSets ds where ds.ID=docsets_state_pkg.ObjectsDocSetIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
  
  sm.storage_pkg.ObjectsSelf:=false;

  storage_pkg.AddressIDs:=storage_pkg.empty;
  storage_pkg.ObjectsIDs:=storage_pkg.empty;

  
end OBJECT_AFTER_DELETE;
/

