prompt Creating trigger OBJECT_CHECK_ADDR_UNIC
prompt =======================================
prompt
create or replace trigger "SM".OBJECT_CHECK_ADDR_UNIC
  after insert or update of Address_ID on objects
declare   
  cnt integer;
  i   integer;
begin
 
  -- осуществление проверки на уникальность значений в поле Address_ID
  if object_state_pkg.ADDRESS_IDs.count>0 then
    for i in 1..object_state_pkg.ADDRESS_IDs.count
    loop
     
        select count(*)
        into cnt
        from sm.objects o
        where o.address_id=object_state_pkg.ADDRESS_IDs(i);
       
        if cnt>1  then
          raise_application_error(-20101, 'Нарушено ограничение уникальности для поля Objects.Address_ID.');
        end if;
          
    end loop;
  end if;
  exception  
    when NO_DATA_FOUND then
    null;
     
end OBJECT_CHECK_ADDR_UNIC;
/

