prompt
prompt Creating trigger OBJECT_FILL_STORAGE
prompt ====================================
prompt
create or replace trigger "SM".OBJECT_FILL_STORAGE
  before delete on OBJECTS for each row
declare
  cnt number;
  obj_type number;
  obj_subtype number;
begin
  
  obj_type:=1;
  obj_subtype:=:old.objtypes_id;
  
  if :old.objtypes_id=6 then
    obj_type:=3;
    obj_subtype:=2;
  end if;
  
  cnt:=0;
  for xx in (select atp.grantee
             from all_tab_privs atp 
             where 
               atp.table_schema='SM' and 
               atp.table_name=( select
                                  UPPER(ft.table_name)
                                from 
                                  sm.fm_tables ft
                                where
                                  ft.type_id=obj_type and
                                  ft.subtype=obj_subtype) and
               atp.privilege='DELETE')
  loop
    if Dbms_Session.is_role_enabled(xx.grantee) then
      cnt:=1;
      exit;
    end if;       
  end loop;  

  if cnt=0 then
    raise_application_error(-20101, 'У Вас нет прав на удаление объектов данного типа!'||chr(10)||chr(13) );
  end if;
   
  docsets_state_pkg.ObjectsDocSetIDs(docsets_state_pkg.ObjectsDocSetIDs.count+1):=:old.DOCSET_ID;

end;
/

