prompt
prompt Creating trigger OBJECT_XMLRR_SAVECHANGES
prompt =========================================
prompt
create or replace trigger "SM".Object_XMLRR_SaveChanges
after  update  on sm.objects
declare
 cnt integer default 0;
 ChangeID integer;
 tblID number(27);
 UserName varchar2(250);
 CodeChange varchar2(12) default '284014000000';
 ObjectTypeID number(27);
 DateExists date;
begin
 if sm.xmlrosreestr_pkg.ObjList.count>0 then
 
     for i in 1..sm.xmlrosreestr_pkg.ObjList.count
       loop
          -- прекращения существования объекта
           select o.objtypes_id, o.exists_end
           into ObjectTypeID, DateExists
           from sm.objects o
           where o.id=sm.xmlrosreestr_pkg.ObjList(i);
              --если это часть здания
              if (ObjectTypeID =3) then
                        select count(*)
                        into cnt
                        from buildtypes t
                        where t.container='N' and
                        t.is_level='N' and
                        t.is_liter='N' and
                        t.is_bti_object='Y' and
                        t.id=(
                              select b.buildtypes_id
                              from sm.buildings b
                              where b.objects_id=sm.xmlrosreestr_pkg.ObjList(i));
               if cnt=1 then CodeChange:='284010003000'; end if;
              end if;
              
              --если часть земельного участка
              if (ObjectTypeID =7) then
                  select g.baseground
                  into cnt
                  from sm.grounds g
                  where g.objects_id=sm.xmlrosreestr_pkg.ObjList(i);
                if cnt is not null then CodeChange:='284010003000'; end if;
              end if;
          
          
              
                       
                        tblID:=sm.xmlrosreestr_pkg.GetTableID('OBJECTS');
                        if nvl(tblID,-1)<>-1 then
                           select sys_context ('USERENV','CURRENT_USER') into UserName from dual;
                           select sm.seqxmlrr_changes.nextval into ChangeID from dual;
                           insert into sm.xmlrr_changes(id,id_value,xmlrr_curchange_id,activation_date,user_changed,action,table_id,object_id)
                           values(ChangeID,sm.xmlrosreestr_pkg.ObjList(i),sm.xmlrosreestr_pkg.GetChangeCode(CodeChange), sysdate, UserName, 'U',tblID,sm.xmlrosreestr_pkg.ObjList(i));
          
                           insert into sm.xmlrr_changes_log(id,changes_id,column_name_id,new_value_date)
                           values( sm.seqxmlrr_changes_log.nextval, ChangeID, sm.xmlrosreestr_pkg.GetColumnID(tblID,'exists_end'), DateExists);
                        end if;
              
         end loop;


end if;
exception
  when others then null;
end;
/

prompt
prompt Creating trigger OBJSHARES_AFTER_INS_UPD
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJSHARES_AFTER_INS_UPD 
  AFTER UPDATE OR INSERT ON sm.OBJSHARES FOR EACH ROW
--
-- XSGROUP ver. 4.7.5
--  Формирует описание объекта
--   и устанавливает ед.изм.
--
Declare
 S1 sm.sharecategory.name%type;
 S2 sm.sharetypes.Name%type;
 S3 sm.organisations.name%type;
 SmallInfo sm.Objects.description%type;
 sGUID varchar2(40);
 nUnitID number(27);
 bCapital char(1);
 typeInfo varchar2(100);
 addtypeInfo varchar2(100);
Begin 
  -- эмитент name с ОПФ
  select cl.name, f.hasauthcapital
     into S3, bCapital 
  from 
     sm.ORGANISATIONS org, sm.CLIENTS cl, sm.orgforms f 
  where   
     cl.ID=org.CLIENTS_ID and f.id=org.orgform and org.ID=:new.ORGANISATIONS_ID;  

  -- вид участия
  select sht.name, sht.guid into S2, sGUID from sm.SHARETYPES sht where sht.id=:new.SHARETYPES_ID;
  
  -- имеем дело с долями
  if (sGUID = '19BD2FD84F5E4B7D85575A1388CC0A24')
  then
    if (bCapital = 'Y') then  
       typeInfo := ' в уставном (складочном) капитале ';
    else
       typeInfo := ' в ';
    end if;    
     
    SmallInfo:= SUBSTR(RTRIM(S2 || typeInfo ||S3), 1, 60);
    nUnitID := 4;
     
   -- имеем дело с акциями
  else    
     S1 := '';
     if (:new.SHARECATEGORY_ID is not null) then     
       -- категория акций
       select shc.name into S1 from sm.SHARECATEGORY shc where shc.id=:new.SHARECATEGORY_ID;
     end if;
     
     -- информация о выпуске акций
     if (:new.OPERSHARES_ID is not null) then   
         select 
               RTRIM(opertype.code) 
               ||' ' ||to_char(opershares.operdate,'DD.MM.YYYY') 
               || (case when opershares.code is not null then ' рег. №' || RTRIM(opershares.code) else '' end)
          into addtypeInfo
         from
          sm.opershares,
          sm.opertype
         where
          opertype.id=opershares.opertype_id and
          opershares.id=:new.opershares_id;
     end if;

     SmallInfo := SUBSTR(RTRIM(S2||' '||S1||' - '||S3 ||(case when addtypeInfo is not null then ' ('||rtrim(addtypeInfo)||')' else '' end)), 1, 60);
     nUnitID := 4;
 end if;
 
 SmallInfo:=SUBSTR(RTRIM(SmallInfo),1,60);

 UPDATE Objects SET Description = SmallInfo, Unit_ID = nUnitID 
   WHERE ID=:new.Objects_ID;
End;
/

prompt
prompt Creating trigger OBJSHARES_BEFORE_INS
prompt =====================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJSHARES_BEFORE_INS
  BEFORE INSERT ON sm.OBJSHARES FOR EACH ROW
--
-- XSGROUP ver. 4.7.5
--  Проверяет реквизиты  объекта типа "Пакеты акций, доли в капитале" и запрещает создание дублей.
Declare
  iTmp integer;
Begin
  --  запрещает создание дублей
  select count(*) into iTmp
         from sm.objshares o
         where
               o.organisations_id=:new.organisations_id and
               (o.owner_id =:new.owner_id or o.owner_id is null) and
               o.sharetypes_id=:new.sharetypes_id and
               (o.sharecategory_id=:new.sharecategory_id or o.sharecategory_id is null) and
               (o.opershares_id=:new.opershares_id or o.opershares_id is null);
  if (iTmp > 0) then
     raise_application_error(-20101, 'Подобный объект уже существует в базе данных');
  end if;
End;
/

prompt
prompt Creating trigger OBJSHARES_BEFORE_INS_UPD
prompt =========================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJSHARES_BEFORE_INS_UPD
       before insert or update on sm.OBJSHARES for each row
--
-- XSGROUP ver. 4.7.5
--  Проверяет заполнение реквизитов 
-- объекта "Пакеты акций, доли в капитале".
--
declare
  nShareTypeTmp number;
  orgform	sm.orgforms%ROWTYPE;
  opershares sm.opershares%ROWTYPE;
  iTmp integer;
  nTmp number(27);
Begin
  select f.* into orgform
  from
    sm.organisations org, sm.orgforms f
  where
    f.id=org.orgform and org.id=:new.organisations_id;

  -- вид участия - акции
  select count(*) into nShareTypeTmp
         from sm.SHARETYPES sht
         where sht.GUID = '6B1E81B10EAD422697278563AD148DB7' and sht.id=:new.SHARETYPES_ID;

  if (orgform.IS_JSC = 'Y' and nShareTypeTmp = 0) then
     raise_application_error(-20101, 'Организационно-правовая форма ЮЛ не соответствует виду участия -' ||chr(10) ||
                                               ' должны быть акции.');
  elsif (orgform.IS_JSC = 'N' and nShareTypeTmp > 0) then
     raise_application_error(-20101, 'Организационно-правовая форма ЮЛ не соответствует виду участия -' ||chr(10) ||
                                               ' должны быть не акции.');
  end if;

  if (nShareTypeTmp > 0 and :new.sharecategory_id is null) then
     raise_application_error(-20101, 'Укажите категорию акций.');
  end if;

  if (orgform.IS_JSC = 'Y') then
       if (:NEW.opershares_id is null) then
         raise_application_error(-20101, 'Укажите операцию эмиссии акций.');
       end if;
  end if;      

  if (:NEW.opershares_id is not null) then
     select * into opershares from sm.opershares where opershares.id=:NEW.opershares_id;
     if (opershares.organisations_id <> :NEW.organisations_id) then
        raise_application_error(-20101, 'Эмитент операции эмиссии акций не совпадает с указанным ЮЛ.');
     end if;
     if (opershares.sharetypes_id <> :NEW.sharetypes_id) then
        raise_application_error(-20101, 'Вид участия в операции эмиссии акций не совпадает с указанным видом участия.');
     end if;
     if (opershares.sharecategory_id <> :NEW.sharecategory_id) then
        raise_application_error(-20101, 'Категория акций операции эмиссии акций не совпадает с указанной категорией акций.');
     end if;
     if (opershares.opertype_id not in (1,2) and nShareTypeTmp > 0) then
        raise_application_error(-20101, 'В поле "Эмисссия акций" следует указывать только первичную или дополнительную эмиссию акций.');
     end if;
  end if;

End;
/

prompt
prompt Creating trigger OBJSHARES_BEFORE_UPD
prompt =====================================
prompt
CREATE OR REPLACE TRIGGER "SM".OBJSHARES_BEFORE_UPD 
       before update on sm.OBJSHARES for each row
--
-- XSGROUP ver. 23.04.2012
--  Запрещает изменять изменять вид участия и категорию
-- объекта "Пакеты акций, доли в капитале"
--
Begin  
  if (:NEW.sharetypes_id <> :OLD.sharetypes_id) then
     raise_application_error(-20101, 'Нельзя изменять вид участия' ||chr(10) ||
                                               ' объекта типа ''Пакеты акций, доли в капитале''');
  end if;   
  
  if (:NEW.sharecategory_id <> :OLD.sharecategory_id) then
     raise_application_error(-20101, 'Нельзя изменять категорию акций (ЦБ)' ||chr(10) ||
                                               ' объекта типа ''Пакеты акций, доли в капитале''');
  end if;  
  
  if (:NEW.organisations_id <> :OLD.organisations_id) then
     raise_application_error(-20101, 'Нельзя изменять юридическое лицо' ||chr(10) ||
                                               ' объекта типа ''Пакеты акций, доли в капитале''');
  end if;  
  
  if (:NEW.opershares_id <> :OLD.opershares_id) then
     raise_application_error(-20101, 'Нельзя изменять ссылку на операцию эмиссии акций ' ||chr(10) ||
                                               ' объекта типа ''Пакеты акций, доли в капитале''');
  end if;  
End;
/

prompt
prompt Creating trigger OBLIGATIONS_DEL
prompt ================================
prompt
create or replace trigger "SM".OBLIGATIONS_DEL
  before delete on SM.obligations
  for each row


declare

  cnt number;
  FMoveSetID number;
  FOblTypeID number;
begin
  FMoveSetID:=:old.moveset_id;
  FOblTypeID:=:old.obligationtype_id;
  select count(*) into cnt
  from sm.payments pay
  where
    pay.obligationtype_id=FOblTypeID and
    pay.movesets_id=FMoveSetID;

  if cnt>0 then
    raise_application_error(-20101, 'По обязательству зарегистрированы платежи.'||'Удаление невозможно!' );
  else
    delete
    from sm.charges ch
    where
      ch.obligationtype_id=FOblTypeID and
      ch.movesets_id=FMoveSetID;
      
    begin
      delete
      from sm.payments_plan_draft pd
      where
        pd.obligationtype_id=FOblTypeID and
        pd.movesets_id=FMoveSetID;
    exception
      when others then  null;  
    end;  

  end if;
end;
/

prompt
prompt Creating trigger OBLIGATIONS_UIN
prompt ================================
prompt
create or replace trigger "SM".OBLIGATIONS_UIN
before insert or update of OBLIGATION_UIN on SM.obligations
for each row
   ----by XSGroup v. 4.8.5
   ----Триггер обеспечивает УИН в рамках операции движения и типа обязательства
   ----При отсутсвующих значениях производится генерация.
begin

--генерация УИН при регистрации обязательств
if :new.OBLIGATION_UIN is null then 
   :new.OBLIGATION_UIN:=sm.gmp_pkg.GenerateGMPUin(:new.MOVESET_ID,'OBLIGATION');
    if (length(:new.OBLIGATION_UIN)<>20) then 
        :new.OBLIGATION_UIN:='';
    end if;  
end if;

--УИН для пени
if :new.fine_uin is null and :new.OBLIGATION_UIN is not null then 
  :new.fine_uin:=sm.gmp_pkg.GenerateGMPUin(:new.MOVESET_ID,'FINE',:new.OBLIGATION_UIN);
end if;
     
--УИН для процентов
if :new.percent_uin is null and :new.OBLIGATION_UIN is not null then 
   :new.percent_uin:=sm.gmp_pkg.GenerateGMPUin(:new.MOVESET_ID,'PERCENT',:new.OBLIGATION_UIN);
end if;
end;
/

