prompt
prompt Creating trigger OPERSHARES_AFTER_INS_UPD
prompt =========================================
prompt
CREATE OR REPLACE TRIGGER "SM".OPERSHARES_AFTER_INS_UPD
  after update or insert on sm.OPERSHARES for each row
--
-- XSGROUP ver. 4.7.5
--  Изменение состояния объекта "Организация"
-- в результате создания или изменения Операций с уставным капиталом
--
Declare
  nObjID number(27);
  sAction char(1);
  nDocsetID number(27);

  sharesNumber_NEW number(27,6);
  sharesPrevNumber_NEW number(27,6);
  nominalCost_NEW number(27,2);
  sharesNumber_OLD number(27,6);
  sharesPrevNumber_OLD number(27,6);
  nominalCost_OLD number(27,2);

  nGSOwnerID number(27);

  nSharetypesID number(27);
  nSharecategoryID number(27);
  orgform	sm.orgforms%ROWTYPE;

Begin
  --Объект-ЮЛ
  Select t.objects_id into nObjID from sm.Organisations t where t.ID = :new.Organisations_ID;
  if (nObjID is null) then
     raise_application_error(-20101,'Невозможно найти объект-ЮЛ.');
  end if;

  --Вид участия "Акции"
  Select t.ID into nSharetypesID from sm.ShareTypes t where t.guid like '6B1E81B10EAD422697278563AD148DB7';
  if (nSharetypesID is null) then
     raise_application_error(-20101,'В справочнике видов участия в уставном капитале отсутствует запись "Акции" с GUID=' || '6B1E81B10EAD422697278563AD148DB7');
  end if;

  --Категория "Привилегированные"
  Select t.ID into nSharecategoryID from sm.ShareCategory t where t.guid like '3C417627105E4339BBF88AA979254BAD';
  if (nSharecategoryID is null) then
     raise_application_error(-20101,'В справочнике категорий акций и ЦБ отсутствует запись ''Привилегированные'' с GUID=' || '3C417627105E4339BBF88AA979254BAD');
  end if;


  --ОПФ ЮЛ
  select f.* into orgform
  from
    sm.organisations org, sm.orgforms f
  where
    f.id=org.orgform and org.id=:new.Organisations_ID;

  -- Запрет выполнения операций, если не выставлены признаки ОПФ ЮЛ
  if (orgform.IS_PUBLICOFFICE = 'N' and orgform.HASAUTHCAPITAL = 'N' and orgform.HASAUTHORIZEDFUND = 'N')
    then
      raise_application_error(-20101,' Для ЮЛ с указанной организационно-правовой формой операции не выполняются. '||chr(10)
                                             ||'Укажите правильно организационно-правовую форму или'||chr(10)
                                             ||' настройте справочник организационно-правовых форм. ');
  end if;

  -- Запрет выполнения операций Увеличения/уменьшения акционерного капитала
  if (orgform.IS_JSC = 'Y'
      and :new.OperType_ID in (5,6))
    then
      raise_application_error(-20101,'Операция указанного вида для акционерного капитала не выполнится.');
  end if;

  -- Запрет выполнения операций Погашения акций, если ОПФ ЮЛ = ООО и вид участия не акции
  if (orgform.IS_JSC <> 'Y'
      and  orgform.HASAUTHCAPITAL = 'Y'
      and :new.sharetypes_id <> nSharetypesID
      and :new.OperType_ID = 4)
    then
      raise_application_error(-20101,'Операция указанного вида для долевого участия не выполнится.');
  end if;

  -- Операции "Выпуск/Погашение Золотой акции" ------------------------------------------
  if (:new.OperType_ID in (7,8)) then
     if (INSERTING) then
         sAction := 'I';
     else
         sAction := 'U';
     end if;

     --Выпуск Золотой акции - спец. право базового собственника, Погашение - убираем спец. право
     if (:new.OperType_ID = 7) then
         nGSOwnerID := sm.multiowning_pkg.GetCurrentOwnerID();
     else
         nGSOwnerID := null;
     end if;

     --Сохранение в STATES ссылки на владельца Золотой акции данного ЮЛ
     sm.ChangeORGStates(
                                       :new.OperType_ID,
                                       sAction,
                                       nObjID,
                                       :new.OperDate, :old.OperDate,
                                       nDocsetID, null,
                                       null, null,
                                       null, null,
                                       null, null,
                                       nGSOwnerID
                                       );

  -- Все другие операции---------------------------------------------------------
  else
     --Создание - определяем, на сколько изменится объект в результате операции
     if (INSERTING) then

         sAction := 'I';

         --В результате операций Увеличение/уменьшение капитала количество не меняется
         if (:new.OperType_ID not in (5,6,9,10,11)) then
               --Кол-во всех акций
               if (:new.sharetypes_id = nSharetypesID) then
                 sharesNumber_NEW := :new.Amount;
               end if;
               --Кол-во привилегированных акций
               if (:new.sharecategory_id = nSharecategoryID) then
                 sharesPrevNumber_NEW := :new.Amount;
               end if;
         end if;

         -- номинальная стоимость
         nominalCost_NEW := :new.NominalCost;

     --Корректировка - вычисляем разницу между первоначальным и исправленным значением
     else

       sAction := 'U';
       --nStateID := :new.States_ID;

       --В результате операций Увеличение/уменьшение капитала количество не меняется
       if (:new.OperType_ID not in (5,6,9,10,11)) then
           --Кол-во всех акций
           if (:new.sharetypes_id = nSharetypesID) then
              sharesNumber_NEW := :new.Amount;
              sharesNumber_OLD := :old.Amount;
           end if;
           --Кол-во привилегированных акций
           if (:new.sharecategory_id = nSharecategoryID) then
              sharesPrevNumber_NEW := :new.Amount;
              sharesPrevNumber_OLD := :old.Amount;
           end if;
       end if;

       -- номинальная стоимость
       nominalCost_NEW := :new.NominalCost;
       nominalCost_OLD := :old.NominalCost;

     end if;
     ---------------------------------------------------------------------
     -- Изменение состояния объекта "Организация" -----------------------------------------------------------------------------
     if (sAction = 'I') then

         sm.ChangeORGStates(
                                       :new.OperType_ID,
                                       sAction,
                                       nObjID,
                                       :new.OperDate, null,
                                       nDocsetID, null,
                                       sharesNumber_NEW, null,
                                       SharesPrevNumber_NEW, null,
                                       nominalCost_NEW, null,
                                       null
                                       );

     -- проверяем, есть ли изменения (ничего не изменилось - обход ненужного update, который идет в паре с insert)
     elsif (sAction = 'U'
         and ((:new.OperDate <> :old.OperDate and :old.OperDate is not null)
           OR nvl(sharesNumber_NEW,0) <> nvl(sharesNumber_OLD,0)
           OR nvl(SharesPrevNumber_NEW,0) <> nvl(SharesPrevNumber_OLD,0)
           OR nvl(nominalCost_NEW,0) <> nvl(nominalCost_OLD,0))
         ) then

         sm.ChangeORGStates(
                                       :new.OperType_ID,
                                       sAction,
                                       nObjID,
                                       :new.OperDate, :old.OperDate,
                                       nDocsetID, null,
                                       sharesNumber_NEW, sharesNumber_OLD,
                                       SharesPrevNumber_NEW, SharesPrevNumber_OLD,
                                       nominalCost_NEW, nominalCost_OLD,
                                       null
                                       );
     end if; -- end Изменение состояния объекта "Организация"--------------------------------------------------------------

     -- Изменение пакетов акций(долей) организации --------------------------------------------------------------------------
     if (:new.OperType_ID in (2,4,5,6,10,11) --and oldShareCost <> 0
        ) then

        sm.opershares_pkg.opersharesContext := 'Y';

        -- при выпуске уменьшается, при погашеннии увеличивается, размер долей (%)
        if (:new.OperType_ID in (2,4)) then
            for xxObj in (
                select o.objects_id as ID
                from
                     sm.objshares o
                where
                      o.organisations_id=:new.Organisations_ID and
                      nvl(sm.OrgState_And_Share_PKG.GetObjSharesStateValue(o.objects_id, :new.OperDate, 'P'),0)<>0
                        )
            loop
                 sm.RecalcMIOwnerObjState(
                                                   xxObj.ID,
                                                   trunc(:new.OperDate),  nvl(trunc(:old.OperDate), trunc(:new.OperDate)),  
                                                   null, -- гл. документ в пакете операции с УК
                                                   'N'  -- участие акциями
                                                  );
                 sm.RecalcMIBalanceObjState(
                                                   xxObj.ID,
                                                   trunc(:new.OperDate),  nvl(trunc(:old.OperDate), trunc(:new.OperDate)),  
                                                   null, -- гл. документ в пакете операции с УК
                                                   'N'  -- участие акциями
                                                  );
            end loop;             -- при доп.выпуске

        -- при увеличении или уменьшении уставного (складочного) капитала меняется стоимость доли
        elsif (:new.OperType_ID in (5,6,10,11)) then
            for xxObj in (
                select o.objects_id as ID
                from
                     sm.objshares o
                where
                      o.organisations_id=:new.Organisations_ID and
                      (case when :new.sharetypes_id is null then 1 else (case when o.sharetypes_id=:new.sharetypes_id then 1 else 0 end) end)=1 and
                      (case when :new.sharecategory_id is null then 1 else (case when o.sharecategory_id=:new.sharecategory_id then 1 else 0 end) end)=1 and
                      nvl(sm.OrgState_And_Share_PKG.GetObjSharesStateValue(o.objects_id, :new.OperDate, 'C'),0)<>0
                        )
            loop
                 sm.RecalcMIOwnerObjState(
                                                   xxObj.ID,
                                                   trunc(:new.OperDate),  nvl(trunc(:old.OperDate), trunc(:new.OperDate)),  
                                                   null, -- гл. документ в пакете операции с УК
                                                   'P'  -- долевое участие
                                                  );
                 sm.RecalcMIBalanceObjState(
                                                   xxObj.ID,
                                                   trunc(:new.OperDate),  nvl(trunc(:old.OperDate), trunc(:new.OperDate)),  
                                                   null, -- гл. документ в пакете операции с УК
                                                   'P'  -- долевое участие
                                                  );                                                  
            end loop;    -- при увеличении или уменьшении уставного (складочного) капитала
        end if;
     end if;  -- end Изменение пакетов акций(долей) организации -----------------------------------------------------------

  end if;  -- Все другие операции -------------------------------------------------------------------
End;  --- END TRIGGER  OPERSHARES_AFTER_INS_UPD
/

prompt
prompt Creating trigger OPERSHARES_BEFORE_DEL
prompt ======================================
prompt
CREATE OR REPLACE TRIGGER "SM".OPERSHARES_BEFORE_DEL
  before delete on sm.OPERSHARES for each row
--
-- XSGROUP ver. 4.7.5
--  Изменение состояния объекта "Организация"
-- в результате удаления Операций с уставным капиталом
--
Declare
  nObjID number(27);
  nDocsetID number(27);
  nTmp number(27);
  sharesNumber_OLD number(27,6);
  sharesPrevNumber_OLD number(27,6);

  nSharetypesID number(27);
  nSharecategoryID number(27);
  nShareP number(27,6);
  nShareC number(27,2);
  nRate number(27,20);
  oldShareCost number(27,2);
  nValue number;
Begin
  --Вид участия "Акции"
  Select t.ID into nSharetypesID from sm.ShareTypes t where t.guid like '6B1E81B10EAD422697278563AD148DB7';
  if (nSharetypesID is null) then
     raise_application_error(-20101,'В справочнике видов участия в уставном капитале отсутствует запись с GUID=' || '6B1E81B10EAD422697278563AD148DB7');
  end if;

  --Категория "Привилегированные"
  Select t.ID into nSharecategoryID from sm.ShareCategory t where t.guid like '3C417627105E4339BBF88AA979254BAD';
  if (nSharecategoryID is null) then
     raise_application_error(-20101,'В справочнике категорий акций и ЦБ отсутствует запись с GUID=' || '3C417627105E4339BBF88AA979254BAD');
  end if;

  --Объект-ЮЛ
  Select t.objects_id into nObjID from sm.Organisations t where t.ID = :old.Organisations_ID;

  -- Операция "Выпуск/Погашение Золотой акции" ------------------------------------------
  if (:old.OperType_ID in (7,8)) then
     --Очистка в STATES ссылки на владельца Золотой акции данного ЮЛ
     sm.ChangeORGStates(
                                       :old.OperType_ID,
                                       'D',
                                       nObjID,
                                       null, :old.OperDate,
                                       null, null,
                                       null, null,
                                       null, null,
                                       null, null,
                                       null
                                       );

  -- Все другие операции---------------------------------------------------------
  else
     -- размер УК на дату операции
     oldShareCost := nvl(sm.OrgState_And_Share_PKG.GetOrgStateValue(:old.Organisations_ID, :old.OperDate, 'C'),0);

      Select count(*)  into nTmp from sm.States t where t.objects_id = nObjID and t.calcdate=:old.operdate;
      if (nTmp >0) then
          Select
             t.documents_id
          into
             nDocsetID
          from sm.States t where t.objects_id = nObjID and t.calcdate=:old.operdate;

          --В результате операций Увеличение/уменьшение капитала количество не меняется
          if (:old.OperType_ID not in (5,6,9,10,11)) then
              --Кол-во всех акций
              if (:old.sharetypes_id = nSharetypesID) then
                sharesNumber_OLD := :old.Amount;
              end if;
              --Кол-во привилегированных акций
              if (:old.sharecategory_id = nSharecategoryID) then
                sharesPrevNumber_OLD := :old.Amount;
              end if;
          end if;

          -- Изменение состояния объекта "Организация"
           sm.ChangeORGStates(
                               :old.OperType_ID,
                               'D',
                               nObjID,
                               null, :old.OperDate,
                               nDocsetID, null,
                               null, sharesNumber_OLD,
                               null, SharesPrevNumber_OLD,
                               null, :old.NominalCost,
                               null
                               );
      end if;
     ------------------------------------------------------------------
     -- Изменение соответствующих пакетов акций(долей) организации
     if (:old.OperType_ID in (2,4,5,6,10,11) and oldShareCost <> 0) then

        sm.opershares_pkg.opersharesContext := 'Y';

        -- коэффициент изменения УК в результате операции
        nValue := nvl(oldShareCost - (case when :old.OperType_ID in (2,5,10) then :old.NominalCost else :old.NominalCost*(-1) end), 0);
        if (nValue <> 0) then
           nRate := oldShareCost / nValue;
        else
           nRate := 0;
        end if;

        -- при отмене выпуска или погашения акций увеличивается размер долей (%)
        if (:old.OperType_ID in (2,4)) then
                 for xxObj in (
                    select o.objects_id as ID
                    from
                         sm.objshares o
                    where
                          o.organisations_id=:old.Organisations_ID and
                          nvl(sm.OrgState_And_Share_PKG.GetObjSharesStateValue(o.objects_id, :old.OperDate-1, 'P'),0)<>0
                            )
                 loop
                     -- размер доли до операции
                     nShareP := sm.OrgState_And_Share_PKG.GetObjSharesStateValue(xxObj.ID, :old.OperDate-1, 'P');

                     --Приводим в соответствие "движение" объекта - передаем дельту (на сколько изменится значение)
                     sm.ChangeMIOwnerObjState(
                                                       'N', -- флаг, что процедура вызвана не из ОД, а из операции с УК
                                                       xxObj.ID,
                                                       trunc(:old.OperDate), trunc(:old.OperDate),
                                                       null, -- гл. документ в пакете операции с УК
                                                       null,   -- количество акций  не меняется
                                                       ((case when nRate=0 then 0 else round(nShareP / nRate, 6) end) - nShareP)*(-1),
                                                       null,
                                                       null
                                                      );
                     sm.RecalcMIBalanceObjState(
                                                   xxObj.ID,
                                                   trunc(:old.OperDate), trunc(:old.OperDate),
                                                   null, -- гл. документ в пакете операции с УК
                                                   'N'  -- участие акциями
                                                  );            
                 end loop;         -- при отмене доп.выпуска или погашения акций

        -- при увеличении или уменьшении уставного (складочного) капитала меняется стоимость доли
        elsif (:old.OperType_ID in (5,6,10,11)) then
                 for xxObj in (
                    select o.objects_id as ID
                    from
                         sm.objshares o
                    where
                          o.organisations_id=:old.Organisations_ID and
                          (case when :old.sharetypes_id is null then 1 else (case when o.sharetypes_id=:old.sharetypes_id then 1 else 0 end) end)=1 and
                          (case when :old.sharecategory_id is null then 1 else (case when o.sharecategory_id=:old.sharecategory_id then 1 else 0 end) end)=1 and
                          nvl(sm.OrgState_And_Share_PKG.GetObjSharesStateValue(o.objects_id, :old.OperDate-1, 'C'),0)<>0
                            )
                 loop
                     -- стоимость доли до операции
                     nShareC := sm.OrgState_And_Share_PKG.GetObjSharesStateValue(xxObj.ID, :old.OperDate-1, 'C');

                     --Приводим в соответствие "движение" объекта - передаем дельту (на сколько изменится значение)
                     sm.ChangeMIOwnerObjState(
                                                       'N', -- флаг, что процедура вызвана не из ОД, а из операции с УК
                                                       xxObj.ID,
                                                       trunc(:old.OperDate), trunc(:old.OperDate),
                                                       null, -- гл. документ в пакете операции с УК
                                                       null,   -- количество акций  не меняется
                                                       null,
                                                       (round(nShareC * nRate, 2) - nShareC)*(-1),
                                                       null
                                                      );
                     sm.RecalcMIBalanceObjState(
                                                   xxObj.ID,
                                                   trunc(:old.OperDate), trunc(:old.OperDate),
                                                   null, -- гл. документ в пакете операции с УК
                                                   'P'  -- долевое участие
                                                  );                                          
                 end loop;       -- при увеличении или уменьшении уставного (складочного) капитала
        end if;
     end if;  -- end -- Изменение соответствующих пакетов акций(долей) организации
     ------------------------------------------------------------------
  end if;  -- Все другие операции -------------------------------------------------------------------
End;   --- END TRIGGER  OPERSHARES_BEFORE_DEL
/

prompt
prompt Creating trigger OPERSHARES_BEFORE_INS
prompt ======================================
prompt
CREATE OR REPLACE TRIGGER "SM".OPERSHARES_BEFORE_INS
  before insert on sm.OPERSHARES for each row
--
-- XSGROUP ver. 23.04.2012 patch 1.
--
declare
  nTmp number;
begin
    --Операция Первичная эмиссия акций одной категории должна быть единственной
    if (:new.opertype_id = 1) then
       select count(*) into nTmp
              from sm.opershares op
              where op.organisations_id = :new.organisations_id and op.opertype_id = 1 and op.sharecategory_id = :new.sharecategory_id;

        -- если уже существует
        if (nTmp > 0) then
          raise_application_error(-20101, '  Операция первичной эмиссии акций данной категории '||chr(10)||
                                        ' уже существует. Измените вид операции на "Дополнительная эмиссия".  ');
        end if;        

    -- дополнительная эмиссия оформляется при наличии первичной
    elsif (:new.opertype_id = 2) then
       select count(*) into nTmp
              from sm.opershares op
              where op.organisations_id = :new.organisations_id and op.opertype_id = 1 and op.sharecategory_id = :new.sharecategory_id;

        -- если не существует первичной эмиссии
        if (nTmp = 0) then
          raise_application_error(-20101, '  Оформите сначала операцию первичной эмиссии акций данной категории. ');
        end if;
        
    --Операция формирования УФ должна быть единственной
    elsif (:new.opertype_id = 9) then
       select count(*) into nTmp
              from sm.opershares op
              where op.organisations_id = :new.organisations_id and op.opertype_id = 9;

        -- если уже существует
        if (nTmp > 0) then
          raise_application_error(-20101, '  Операция формирования уставного фонда уже существует, '||chr(10)||
                                        'если уставной фонд изменился - оформите операцию увеличения или уменьшения уставного фонда.  ');
        end if;
        
    end if;
end;
/

prompt
prompt Creating trigger OPERSHARES_BEFORE_INS_UPD
prompt ==========================================
prompt
CREATE OR REPLACE TRIGGER "SM".OPERSHARES_BEFORE_INS_UPD
  before insert or update on sm.OPERSHARES for each row
--
-- XSGROUP ver. 4.7.5 
--  Проверка обязательных реквизитов Операций с уставным капиталом
--  Установка реквизитов по умолчанию, если не заданы
--
Declare
 nTmp number;
Begin
  if (UPDATING) then
     if (:new.opertype_id <> :old.opertype_id) then
         raise_application_error(-20101,'Вид операции изменять нельзя.');
     end if;    
     if (:new.sharecategory_id <> :old.sharecategory_id) then
         raise_application_error(-20101,'Категорию акций изменять нельзя.');
     end if;
     if (:new.opertype_id in (7,8) and :new.operdate <> :old.operdate) then
         raise_application_error(-20101,'Дату операций с золотой акцией изменять нельзя.');
     end if;    
  end if;

  --Если вид участия - акции
  select count(*) into nTmp from sm.sharetypes t where t.id=:new.sharetypes_id and t.GUID='6B1E81B10EAD422697278563AD148DB7';  
  if (nTmp>0) then     
     -- категория для акций(ЦБ) обязательна (кроме операций с Золотой акцией)
     if (:new.sharecategory_id is null and :new.opertype_id not in (7,8)) then      
       raise_application_error(-20101,'Укажите категорию акций(ЦБ)');     
     end if;  
     -- ед.изм = шт.
     :new.unit_id := 3;
  end if; 
  
  --Если вид участия - доля
  select count(*) into nTmp from sm.sharetypes t where t.id=:new.sharetypes_id and t.GUID='19BD2FD84F5E4B7D85575A1388CC0A24';  
  if (nTmp>0) then 
    -- ед.изм = %  
    :new.unit_id := 4;    
  end if;
  
  --Для операций кроме выпуска/погашения Золотой акции
  if (:new.opertype_id in (1,2,3,4,5,6,9,10,11)) then 
      --номинальная стоимость обязательна
    if (:new.nominalcost is null or :new.nominalcost=0) then
      raise_application_error(-20101,'Укажите номинальную стоимость, руб.');
    end if;  
  end if;  
   
  --Операция opertype_id = 3 ("Первоначальное формирование уставного (складочного) капитала")
  if (:new.opertype_id = 3) then  
    -- ID доли
    select t.id into nTmp from sm.sharetypes t where t.GUID='19BD2FD84F5E4B7D85575A1388CC0A24';  
    
    -- вид участия = доли   
    :new.sharetypes_id := nTmp;    
    -- ед.изм = %
    :new.unit_id := 4;  
    -- количество %     
    :new.amount := 100;    --end if;
    
    --валюта номинальной цены (номинала)
    if (:new.nominal is not null and :new.nominal<>0) then
      if (:new.currency_id is null) then
          -- валюта = рубль
        :new.currency_id := 1;
      else
        --если указана не валюта
        select count(*) into nTmp from sm.Unit u where u.UnitGroup_ID=1 and u.id=:new.currency_id;
        if (nTmp = 0) then
          -- переустанавливаем: валюта = рубль
          :new.currency_id := 1;
        end if;
      end if; 
    end if; -- end валюта номинальной цены (номинала)
    
  end if;   -- end Операция opertype_id = 3
  
  -- Проверка значений в операциях с акциями
  if (:new.opertype_id in (1,2,4) and :new.currency_id = 1) then
     if (round(nvl(:new.amount,0) * nvl(:new.nominal,0),6) <> round(nvl(:new.nominalcost,0),6)) then
        raise_application_error(-20101, '  Проверьте количество, цену и стоимость. ');       
     end if;
  end if;    
   
End;
/

