prompt
prompt Creating trigger OPERSHARES_PKG_USE
prompt ===================================
prompt
create or replace trigger "SM".OPERSHARES_PKG_USE
  after insert or update or delete on sm.OPERSHARES
--
-- XSGROUP ver. 4.7.5
--
declare
  i integer;
  nSumAmount number(27,6);
begin

  if (INSERTING or UPDATING) then
      -- проверки
      if (sm.opershares_pkg.orgID is not null) then
          -- проверка суммы долей при определении долей в УК
          if (sm.opershares_pkg.typeID = 3) then
              select sum(op.amount) into nSumAmount
                    from sm.opershares op
                    where op.organisations_id = sm.opershares_pkg.orgID and op.opertype_id=3;

              if (nvl(nSumAmount,0) > 100) then
                raise_application_error(-20101, 'В результате данной операции размер долей в уставном капитале превысит 100%.');
              end if;
          end if;
      end if;

      -- ссылки на States
      if (sm.opershares_pkg.opersharesIDs.count>0 and
          sm.opershares_pkg.opersharesIDs.count=sm.opershares_pkg.stateIDs.count) then
        for i in 1..sm.opershares_pkg.opersharesIDs.count loop
            begin
              update sm.OPERSHARES o set o.states_id=sm.opershares_pkg.stateIDs(i) where o.ID=sm.opershares_pkg.opersharesIDs(i);
            exception
              when others then
                null;
            end;
        end loop;
      end if;

  elsif (DELETING) then
      -- удаление States
      if sm.opershares_pkg.stateIDs.count>0 then
        for i in 1..sm.opershares_pkg.stateIDs.count loop
            begin
              sm.DropEmptyState(sm.opershares_pkg.stateIDs(i));
            exception
              when others then
                null;
            end;
        end loop;
      end if;

  end if;

  sm.opershares_pkg.opersharesIDs := sm.opershares_pkg.empty;
  sm.opershares_pkg.stateIDs := sm.opershares_pkg.empty;

  sm.opershares_pkg.opersharesContext := null;
  sm.opershares_pkg.orgID := null;
  sm.opershares_pkg.typeID := null;
end;
/

prompt
prompt Creating trigger OPSHARES_NAME_BEFORE_INS_UPD
prompt =============================================
prompt
CREATE OR REPLACE TRIGGER "SM".OPSHARES_NAME_BEFORE_INS_UPD
  before update or insert on sm.OPERSHARES for each row
--
-- XSGROUP ver. 4.7.5 
--  Заполняет значение полей Name
--
Declare 
  sName sm.opertype.code%type; 
  sSharetype sm.sharetypes.name%type;
  sCategory sm.sharecategory.name%type;
  sOrg sm.organisations.name%type;
Begin 
  if (:new.opertype_id is not null and 
     :new.organisations_id is not null and 
     :new.operdate is not null
     ) 
    then
       --Наименование типа Операции с УК
      select t.code into sName from sm.Opertype t where t.id = :new.opertype_id;
      
      if (:new.opertype_id <> 3) then
          if (:new.SHARETYPES_ID is not null) then 
            select t.name into sSharetype from sm.sharetypes t where t.id = :new.SHARETYPES_ID;
          end if;
          
          if (:new.sharecategory_id is not null) then 
            select t.name into sCategory from sm.sharecategory t where t.id = :new.sharecategory_id;
          end if;
      end if;
       
       --Наименование эмитента
      select t.name into sOrg from sm.organisations t where t.id = :new.organisations_id;
  
      --Значение поля Name
      :new.Name := sName ||nvl(' '||sSharetype,'') 
                                      ||nvl(' '||sCategory,'') 
                                      ||' от ' || to_Char(trunc(:new.operdate)) 
                                      || (case when :new.code is not null then ' рег. №' || RTRIM(:new.code) else '' end) 
                                      || ' - ' || sOrg; 
  end if;
  
End;
/

