prompt
prompt Creating trigger PAYDOCS_CHECK_FINEMONTHS
prompt =========================================
prompt
create or replace trigger "SM".PAYDOCS_CHECK_FINEMONTHS
  before insert or update on paydocs  
  for each row


declare
  Max_m number;
  PerChar char(1);
begin
  
  select opt.max_months, opt.periodical
  into Max_m, PerChar 
  from
    sm.obl_periodtypes opt
  where
    opt.periodical=:new.periodical;
    
  if :new.finemonths>Max_m then
    :new.finemonths:=Max_m;
  end if; 
  
  if PerChar='Y' then
    if :new.last_finedate is not null then
      :new.last_finemonths:=1;
    end if;  
  end if;
  
  if PerChar='T' then
    :new.kind:='A';
  end if;
  
  -- дата начисления пени в последнем периоде имеет смысл не во всех случаях  
  if (nvl(:new.last_finedate,0)=0)
     or
    (nvl(:new.last_finemonths,0)=0)
     or (PerChar='G') or (PerChar='T') or (PerChar='N') then 
    :new.last_finedate:=null;
    :new.last_finemonths:=null; 
  end if;
  
  if :new.last_finemonths is not null then
    if :new.last_finemonths>Max_m then
      :new.last_finemonths:=Max_m;
    end if; 
  end if; 
  
end PAYDOCS_CHECK_FINEMONTHS;
/

