prompt
prompt Creating trigger PAYMENTS_ACC
prompt =============================
prompt
create or replace trigger "SM".PAYMENTS_ACC before insert or delete or update on Payments
 for each row
-- VVV СТАРЫЙ СМЫСЛ! СЕЙЧАС- НЕ ТАК!!!
-- by XSGROUP ver.11.12.2008
-- блокировка внесения, изменения, удаления платежей
-- в рамках закрытого бухгалтерского периода отчётности.
-- Допускается только переназначение платежа внутри закрытого периода.
-- ^^^ END СТАРЫЙ СМЫСЛ!
---  ТЕПЕРЬ: ---
-- 1. Платежи реально отражаются в учетных данных (чего раньше не было!)
-- 2. Изменения проводок при любых изменениях Оплаты, в окрытом и закрытом периодах (в последнем случае - со сторнированием).
------

declare
  D1 DATE;            -- новая дата фактического поступления на счет
  D2 DATE;            -- старая дата фактического поступления на счет
  G_CloseDate DATE;
  ex integer;
  S1 number;
  S2 number;

  d3 date;  -- дата документа платежа старая
  d4 date;  -- дата документа платежа новая
--  idOld integer;    -- ID сторнируемой проводки
  A_type_new char(1);
  A_type_old char(1);
  A_date_charge_applies date;
  itmp integer;
  
--- 03.02.2015 Morozova(параметры используются для переносе платежа на другое обязательство в открытом периоде)   
  obligationTypeIdNew number;   --- тип нового обязательства 
  moveSetsIdNew number;         --- новая ОД  
  obligationsIdNew number;      --- новое обязательство

begin

  -- по виду платежа определяем вид начисления
  -- (Оплата по договору Y (вид начисления - "по обязательству")
  -- / Оплата пени N (вид начисления - "по пени")
  -- /Распределённый D (вид начисления - D "виртуальный" )


  -- если платеж был внесен намного раньше, чем приминяется эта схема,
  -- то данные найдены в таблице charge_applies не будут

  -- если платеж удаляется, то в процедуре расчета начислений необходимо добавить блок,
  -- в котором для каждого начисления будет указан ID платежа из-за которого оно возникло (ерунлда какая-то)

  -- если изменилась дата платежного документа, то стоит ли менять documents_id  ???

  if INSERTING then
    D1:=:new.APPLY_DATE;
    D2:=D1;
    select d.docdate into d3 from sm.documents d where d.id = :new.documents_id;
    d4 := d3;
    A_Type_new := :new.mainpay;
    A_Type_old := A_Type_new;
  elsif UPDATING then
    D1:=:new.APPLY_DATE;
    D2:=:old.APPLY_DATE;
    S1:=:new.sum;
    S2:=:old.sum;
    select d.docdate into d3 from sm.documents d where d.id = :new.documents_id;
    select d.docdate into d4 from sm.documents d where d.id = :old.documents_id;

    A_Type_new := :new.mainpay;
    A_Type_old := :old.mainpay;
    
    --- 03.02.2014 Morozova
    obligationTypeIdNew := :new.obligationtype_id;
    moveSetsIdNew := :new.movesets_id;
    obligationsIdNew := :new.obligations_id;
  elsif DELETING then
    D1:=:old.APPLY_DATE;
    D2:=D1;
    select d.docdate into d4 from sm.documents d where d.id = :old.documents_id;
    d3 := d4;
    A_Type_old := :old.mainpay;
    A_Type_new := A_Type_old;
  end if;


  G_CloseDate:=to_date(GetparameterSimple('ENDPERIOD'),'dd.MM.yyyy') ;
  if D1 <= G_CloseDate or D2 <= G_CloseDate  or
     d3 <= G_CloseDate or d4 <= G_CloseDate
  then
    
-------------------------------- Платеж добавлен/изменен/удален в закрытом периоде ---------------------------------
    if INSERTING then
--      raise_application_error(-20101,'Невозможно внести платеж в рамках закрытого бухгалтерского периода (по '|| TO_CHAR(G_CloseDate,'DD.MM.YYYY')|| ' включительно).' );

    insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                              description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                              payments_distribution_id, reversal_role, reversallink_id, payment_id)
              values (sm.seqcharge_applies.nextval, trunc(sysdate), :new.sum , :new.obligationtype_id,
                                              :new.movesets_iD, A_Type_new, 'Платеж добавлен в закрытом периоде - ' ||sm.ExpandDoc(:new.documents_id), null, 'N',
                                              :new.Cls_Kbk_Id, :new.obligations_id, null, 'исправляющая', null, :new.id);

    elsif UPDATING then
      if (D1<>D2)or(S1<>S2) then -- это не переназначаемый платёж - запрет
--        raise_application_error(-20101,'Невозможно изменить платеж в рамках закрытого бухгалтерского периода (по '|| TO_CHAR(G_CloseDate,'DD.MM.YYYY')|| ' включительно).' );
        begin
             Select max(ID) into itmp from sm.charge_applies cha where cha.payment_id = :OLD.ID and reversal_role <> 'Сторнированная' and reversal_role <> 'Сторнирующая';
            insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                      description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                      payments_distribution_id, reversal_role, reversallink_id, payment_id)
                      values (sm.seqcharge_applies.nextval, trunc(sysdate), -:old.sum , :old.obligationtype_id,
                                                      :old.movesets_iD, A_Type_Old,
                                                      'Сторнирующий - ' || sm.ExpandDoc(:new.documents_id),
                                                      null, 'N',
                                                      :old.Cls_Kbk_Id, :old.obligations_id, null, 'Сторнирующая', itmp, :new.id);  -- <<< 07.12.2012 Почему-то  payment_id заполнялся в null???

            update sm.charge_applies cha
            set cha.reversal_role = 'Сторнированная',
  --               cha.payment_id = null,  -- <<< 07.12.2012 Почему-то  payment_id заполнялся в null???
                reversallink_id = sm.seqcharge_applies.currval,
                cha.description = 'Сторнирован: ' || trim(replace(description,  'Сторнирован: '))
            where cha.payment_id = :OLD.ID
                  and reversal_role <> 'Сторнирующая'; ---13.03.2014 Morozova  иначе к пояснению сторнирующией проводки добавлялось "Сорнирован"

            insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                      description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                      payments_distribution_id, reversal_role, reversallink_id, payment_id)
                      values (sm.seqcharge_applies.nextval, trunc(sysdate), :new.sum , :new.obligationtype_id,
                                                      :new.movesets_iD, A_Type_new,
                                                      'Исправляющий - '|| sm.ExpandDoc(:old.documents_id),
                                                       null, 'N',
                                                      :new.Cls_Kbk_Id, :new.obligations_id, null, 'Исправляющая', itmp, :new.id);

        exception
        when no_data_found then
            null;
        end;

      end if;
    else

    -- платеж удален из закрытого периода
        begin
       --  raise_application_error(-20101,'Невозможно удалить платеж в рамках закрытого бухгалтерского периода (по '|| TO_CHAR(G_CloseDate,'DD.MM.YYYY')|| ' включительно).' );

            -- найти дату проводки платежа из таблицы charges_applies
            select max(cha.apply_date) into A_date_charge_applies
            from sm.charge_applies cha
            where cha.payment_id is not null
                  and cha.charge_id is null
                  and cha.payment_id = :old.id
                   and reversal_role <> 'Сторнированная' and reversal_role <> 'Сторнирующая' ;

            if  A_date_charge_applies > G_CloseDate then
               -- если платеж был проведен в открытом периде
               -- удаляем проводки, которые возникли в результате проведения платежа
               delete from sm.charge_applies cha where cha.payment_id = :OLD.ID;
            else
               --  если платеж был проведен в закрытом периоде, то сторнируем проводку платежа
               -- и всех начислений с ним связанных
               update sm.charge_applies cha
                  set cha.reversal_role = 'Сторнированная'
  --                    , cha.payment_id = null   -- <<< 07.12.2012 Почему-то  payment_id заполнялся в null???
--                      , cha.description = 'Был удален: ' || trim(cha.description)
                  where cha.payment_id = :OLD.ID;


               insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                                  description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                                  payments_distribution_id, reversal_role, reversallink_id, payment_id)
                          values (sm.seqcharge_applies.nextval, trunc(sysdate), -:old.sum , :old.obligationtype_id,
                                                  :old.movesets_iD, A_Type_new, 'Платеж удален в закрытом периоде - ' ||sm.ExpandDoc(:old.documents_id), null, 'N',
                                                  :old.Cls_Kbk_Id, :old.obligations_id, null, 'Сторнирующая', null, :old.id);  -- <<< 07.12.2012 Почему-то  payment_id заполнялся в null???
            end if;
        exception
          when no_data_found then
            null;
        end;


    end if;
  else
  --
  --------------------- Открытый период --------------------------------------------------
        Select count(*) into itmp from sm.charge_applies cha where cha.payment_id = :OLD.ID;

         if INSERTING OR itmp = 0 then
         -- добавляем проводку с реквизитами платежа
            insert into sm.charge_applies (id, apply_date, summ, obligtype_id, moveset_id, charge_type,
                                              description, charge_id, corr_flag, cls_kbk_id, obligations_id,
                                              payments_distribution_id, reversal_role, reversallink_id, payment_id)
              values (sm.seqcharge_applies.nextval, D1, :new.sum , :new.obligationtype_id,
                                              :new.movesets_iD, A_Type_new,
                                              'Платеж - ' || sm.ExpandDoc(:new.documents_id), null, 'N',
                                              :new.Cls_Kbk_Id, :new.obligations_id, null, '', null, :new.id);
         elsif UPDATING then
         -- обновляем в проводке платежа реквизиты
            update sm.charge_applies cha
            set cha.summ = :new.sum,
                cha.description = 'Платеж - ' || sm.ExpandDoc(:new.documents_id),
                cha.cls_kbk_id = :new.cls_kbk_id,
                cha.charge_type = A_Type_new
                , cha.apply_date = :new.apply_date
                , cha.moveset_id = moveSetsIdNew
                , cha.obligtype_id = obligationTypeIdNew
                , cha.obligations_id = obligationsIdNew
            where cha.payment_id = :old.id;
    --              and cha.charge_type = 'D'; <<<  --- 02.11.2012 ---
         else

            delete from sm.charge_applies cha
            where cha.payment_id = :old.id;
         end if;
  end if;

end;
/

prompt
prompt Creating trigger PAYMENTS_CLEARPKG
prompt ==================================
prompt
CREATE OR REPLACE TRIGGER "SM".Payments_ClearPKG BEFORE INSERT or UPDATE or DELETE ON Payments 


BEGIN
 pay_state_pkg.newRows:=pay_state_pkg.empty;
 pay_state_pkg.updRows:=pay_state_pkg.empty;
 pay_state_pkg.delRows:=pay_state_pkg.empty;
 
END;
/

prompt
prompt Creating trigger PAYMENTS_FILL_OBLIGATION_ID
prompt ============================================
prompt
create or replace trigger "SM".payments_fill_obligation_id
  before insert or update on sm.payments  
  for each row
declare
  -- local variables here
  ob_id number(27);
begin
  if :new.obligations_id is null then
      begin
      select o.id into ob_id from sm.obligations o where o.moveset_id=:new.movesets_id and o.obligationtype_id=:new.obligationtype_id;
      :new.obligations_id := ob_id;
      exception
          when NO_DATA_FOUND then
              null;
          when TOO_MANY_ROWS then
              null;
      end;
  end if;
end;
/

prompt
prompt Creating trigger PAYMENTS_ID
prompt ============================
prompt
CREATE OR REPLACE TRIGGER "SM".Payments_id BEFORE INSERT or UPDATE ON Payments FOR EACH ROW

Declare
  FullUserName sm.registeredusers.fullname%type;
  len integer;
BEGIN

  select
    atc.DATA_LENGTH
  into
    len
  from
    all_tab_columns atc
  where
    atc.OWNER='SM' and
    atc.TABLE_NAME='PAYMENTS' and
    atc.COLUMN_NAME='CHANGEDBY';  
    

 SELECT FullName INTO FullUserName FROM RegisteredUsers WHERE UserName=USER;
 :new.ChangedBy:= SUBSTR(FullUserName,1,len);
 :new.WriteDate:= SYSDATE;

 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   raise_application_error(-20101, 'Вы не прописаны в расширенном списке пользователей системы. Обратитесь к администратору');
END;
/

prompt
prompt Creating trigger PAYMENTS_KBK_CONTROL
prompt =====================================
prompt
create or replace trigger SM.PAYMENTS_KBK_CONTROL before insert or update on Payments for each row
-- Чувыкин 180725 - для контроля соответствия между направлением платежа и его КБК, во избежание постоянных методических ошибок отдела арендных отношений при вводе или редактировании платежей
BEGIN
if INSERTING then
 if :new.mainpay = 'Y' and :new.cls_kbk_id <> 39 and :new.cls_kbk_id <> 166 and :new.cls_kbk_id <> 186 then
    raise_application_error(-20101, 'Платеж разносится на обязательство, а КБК не соответствует!');
 end if;
 if :new.mainpay = 'N' and :new.cls_kbk_id <> 148 then
    raise_application_error(-20101, 'Платеж разносится на пеню, а КБК не соответствует!');
 end if;
elsif UPDATING then
 if :new.mainpay = 'Y' and :new.cls_kbk_id <> 39 and :new.cls_kbk_id <> 166 and :new.cls_kbk_id <> 186 then
    raise_application_error(-20101, 'Платеж разносится на обязательство, а КБК не соответствует!');
 end if;
 if :new.mainpay = 'N' and :new.cls_kbk_id <> 148 then
    raise_application_error(-20101, 'Платеж разносится на пеню, а КБК не соответствует!');
 end if;
end if;
END;
/

prompt
prompt Creating trigger PAYMENTS_PLAN_DRAFT_DEL
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER "SM".PAYMENTS_PLAN_DRAFT_DEL
AFTER DELETE
ON SM.PAYMENTS_PLAN_DRAFT
REFERENCING OLD AS OLD
FOR EACH ROW

Begin
   Delete from SM.PAYMENTS_PLAN pp where PAYMENTS_PLAN_DRAFT_ID = :OLD.ID and pp.MAIN_PLAN_ID is null and pp.COMMENTS like 'Планируемое погашение%';
End;
/

prompt
prompt Creating trigger PAYMENTS_REJECT_SUM_CHANGING
prompt =============================================
prompt
create or replace trigger SM.PAYMENTS_REJECT_SUM_CHANGING before update on Payments for each row
BEGIN
 if :new.Sum <> :old.Sum and :new.bankitems_id is not null then
    raise_application_error(-20101, 'Платеж был создан с использованием модуля "Менеджер финансовых поступлений". Изменение суммы такого платежа недопустимо');
 end if;
END;
/

prompt
prompt Creating trigger PAYMENTS_UPDATEFINES
prompt =====================================
prompt
CREATE OR REPLACE TRIGGER SM.Payments_UpdateFines AFTER INSERT or UPDATE or DELETE ON SM.PAYMENTS

declare
 P number(27,0) := -1;
 S number(27,2) := 0;
 ntmp integer := 0;

BEGIN
 if INSERTING then
  for i in 1 .. pay_state_pkg.newRows.count loop
        -- Для рассрочки - payments_distribute_pkg.PAYMENT_DISTRIBUTE_SINGLE
       -- Select count(*) into ntmp  from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = pay_state_pkg.newRows(i).movesets_id and ppd.OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id and ROWNUM=1;
       -- if ntmp > 0 then
      --           Select NVL(ID, -1) into P from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = pay_state_pkg.newRows(i).movesets_id and ppd.OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id and ROWNUM=1;
      --  end if;

       -- Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = null where  MOVESET_ID = pay_state_pkg.updRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.updRows(i).obligationtype_id;

        if  P = -1 then
                  -- По-старому
                Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = null where  MOVESET_ID = pay_state_pkg.newRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id;
                FullRecalcFines(pay_state_pkg.newRows(i).movesets_id, pay_state_pkg.newRows(i).obligationtype_id);
        else
                  -- Для рассрочки
                  Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = pay_state_pkg.newRows(i).APPLY_DATE-1 where  MOVESET_ID = pay_state_pkg.newRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id;
                  FullRecalcFines(pay_state_pkg.newRows(i).movesets_id, pay_state_pkg.newRows(i).obligationtype_id);
                  --PAYMENTS_DISTRIBUTE_PKG.PAYMENT_DISTRIBUTE_SINGLE(pay_state_pkg.newRows(i).ID, pay_state_pkg.newRows(i).SUM, pay_state_pkg.newRows(i).MOVESETS_ID, pay_state_pkg.newRows(i).obligationtype_id, pay_state_pkg.newRows(i).APPLY_DATE);
                  --PAYMENTS_DISTRIBUTE_PKG.CALC_PERSENS_FINES_FOR_DATE(pay_state_pkg.newRows(i).MOVESETS_ID, pay_state_pkg.newRows(i).obligationtype_id, trunc(sysdate));
        end if;
  end loop;
 elsif UPDATING then
  for i in 1 .. pay_state_pkg.updRows.count loop
        -- Для рассрочки - payments_distribute_pkg.PAYMENT_DISTRIBUTE_SINGLE
         --Select count(*) into ntmp  from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = pay_state_pkg.newRows(i).movesets_id and ppd.OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id and ROWNUM=1;
       -- if ntmp > 0 then
       --          Select NVL(ID, -1) into P from SM.PAYMENTS_PLAN_DRAFT ppd where ppd.MOVESETS_ID = pay_state_pkg.newRows(i).movesets_id and ppd.OBLIGATIONTYPE_ID = pay_state_pkg.newRows(i).obligationtype_id and ROWNUM=1;
       -- end if;
        if  P = -1 then
                  -- По-старому
                  --Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = pay_state_pkg.updRows(i).APPLY_DATE-10 where  MOVESET_ID = pay_state_pkg.updRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.updRows(i).obligationtype_id;
                  -- Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = null where  MOVESET_ID = pay_state_pkg.updRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.updRows(i).obligationtype_id;
                  Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = null where  MOVESET_ID = pay_state_pkg.updRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.updRows(i).obligationtype_id;
                  FullRecalcFines(pay_state_pkg.updRows(i).movesets_id, pay_state_pkg.updRows(i).obligationtype_id);
        else
                  -- Для рассрочки - при апдейте еще определяем возможно уже распределенную сумму
                -- Select NVL(sum(pdistr.VAL),0) into S from SM.PAYMENTS_DISTRIBUTION pdistr where pdistr.PAYMENTS_ID = pay_state_pkg.updRows(i).ID;
                Update SM.OBLIGATIONS set RECALC_ACTUAL_DATE = pay_state_pkg.updRows(i).APPLY_DATE-1 where  MOVESET_ID = pay_state_pkg.updRows(i).movesets_id and OBLIGATIONTYPE_ID = pay_state_pkg.updRows(i).obligationtype_id;
                FullRecalcFines(pay_state_pkg.updRows(i).movesets_id, pay_state_pkg.updRows(i).obligationtype_id);
               --PAYMENTS_DISTRIBUTE_PKG.PAYMENT_DISTRIBUTE_SINGLE(pay_state_pkg.updRows(i).ID, pay_state_pkg.updRows(i).SUM - S, pay_state_pkg.updRows(i).MOVESETS_ID, pay_state_pkg.newRows(i).obligationtype_id, pay_state_pkg.updRows(i).APPLY_DATE);
               -- PAYMENTS_DISTRIBUTE_PKG.CALC_PERSENS_FINES_FOR_DATE(pay_state_pkg.updRows(i).MOVESETS_ID, pay_state_pkg.updRows(i).obligationtype_id, trunc(sysdate));
       end if;
  end loop;
 elsif DELETING then
       for i in 1 .. pay_state_pkg.delRows.count loop
               Update SM.OBLIGATIONS set OBLIGATIONS.RECALC_ACTUAL_DATE = pay_state_pkg.delRows(i).APPLY_DATE-1 where OBLIGATIONS.MOVESET_ID = pay_state_pkg.delRows(i).movesets_id and OBLIGATIONS.OBLIGATIONTYPE_ID = pay_state_pkg.delRows(i).obligationtype_id;
               FullRecalcFines(pay_state_pkg.delRows(i).movesets_id, pay_state_pkg.delRows(i).obligationtype_id);
       end loop;
 end if;

END;
/

prompt
prompt Creating trigger PAYMENTS_UPDATEPKG
prompt ===================================
prompt
CREATE OR REPLACE TRIGGER "SM".Payments_UpdatePKG AFTER INSERT or UPDATE or DELETE ON SM.Payments for each row

BEGIN
 if INSERTING then
   pay_state_pkg.newRows(pay_state_pkg.newRows.count+1 ).movesets_id := :new.movesets_id;
   pay_state_pkg.newRows(pay_state_pkg.newRows.count ).obligationtype_id  := :new.obligationtype_id ;
   pay_state_pkg.newRows(pay_state_pkg.newRows.count ).ID := :new.ID;
   pay_state_pkg.newRows(pay_state_pkg.newRows.count ).SUM := :new.SUM;
   pay_state_pkg.newRows(pay_state_pkg.newRows.count ).APPLY_DATE := :new.APPLY_DATE;
   pay_state_pkg.newRows(pay_state_pkg.newRows.count ).BankItems_Id := :new.BankItems_Id;
elsif UPDATING then
   pay_state_pkg.updRows(pay_state_pkg.updRows.count+1 ).movesets_id := :new.movesets_id;
   pay_state_pkg.updRows(pay_state_pkg.updRows.count ).obligationtype_id  := :new.obligationtype_id ;
   pay_state_pkg.updRows(pay_state_pkg.updRows.count ).ID := :new.ID;
   pay_state_pkg.updRows(pay_state_pkg.updRows.count ).SUM := :new.SUM;
   pay_state_pkg.updRows(pay_state_pkg.updRows.count ).APPLY_DATE := :new.APPLY_DATE;
   pay_state_pkg.updRows(pay_state_pkg.updRows.count ).BankItems_Id := :new.BankItems_Id;
 elsif DELETING then
   pay_state_pkg.delRows(pay_state_pkg.delRows.count+1 ).movesets_id := :old.movesets_id;
   pay_state_pkg.delRows(pay_state_pkg.delRows.count ).obligationtype_id  := :old.obligationtype_id ;
   pay_state_pkg.delRows(pay_state_pkg.delRows.count ).ID := :old.ID;
   pay_state_pkg.delRows(pay_state_pkg.delRows.count ).APPLY_DATE := :old.APPLY_DATE;
   pay_state_pkg.delRows(pay_state_pkg.delRows.count ).BankItems_Id := :old.BankItems_Id;
 end if;
END;
/

prompt
prompt Creating trigger PAYMENTS_UPD_BANKITEM_STATE
prompt ============================================
prompt
create or replace trigger "SM".PAYMENTS_UPD_BANKITEM_STATE
  after INSERT OR DELETE on Sm.Payments
DECLARE
  type numbersDict is table of payments.bankitems_id%type index by BINARY_INTEGER;
  type numbersArray is table of payments.bankitems_id%type;
  ids numbersArray;
  -- Функция выбирает значения поля BankItems_Id из переданного массива
  -- и убирает дублирующие значения
  function DistinctBankItemsIds(paymentRows in pay_state_pkg.ridArray) return numbersArray is
      bankItemsIdsDict numbersDict;
      bankItemsIds numbersArray;
      currentIndex integer := 0; 
    begin
      bankItemsIds := numbersArray();
      for i in 1 .. paymentRows.count loop
        if paymentRows(i).BankItems_Id is not null then 
           if bankItemsIdsDict.exists(paymentRows(i).BankItems_Id) = FALSE then
              bankItemsIdsDict(paymentRows(i).BankItems_Id) := paymentRows(i).BankItems_Id;
              currentIndex := currentIndex + 1;
              bankItemsIds.Extend();
              bankItemsIds(currentIndex):= paymentRows(i).BankItems_Id;
           end if;
        end if;
      end loop;
      return bankItemsIds;
    end;   
  procedure UpdateBankItemsState(bankItemId in sm.bankitems.id%type, operationDirection in number) is
     -- bankItemId  - идентификатор связанного поступления
     -- operationDirection - направление операции: -1 - разнесение поступления, 1 - удаление ранее связанного платежа
     bankItemAmount  number(27,2) :=0;
     bankItemSum     sm.bankitems.sum_pp%type := 0.0;
     bankItemState   sm.bankitemdistributionstates.id%type := 0;
     paymentsSum     sm.payments.sum%type := 0.0;
     cnt             integer :=0;
    begin
      -- Если нет ссылки на BankItem.Id, то платеж обрабатывать не нужно
      if bankItemId is not null then
         -- Получаем количество связанных платежей
         select count(*) into cnt from sm.payments t where t.bankitems_id = bankItemId;
         if cnt = 0 then
           -- Если нет связанных платежей, то состояние платежа = "Не разносилось"
           bankItemState := 0;
         else
           -- Есть связанные платежи считаем общую сумму
           select sum(t.sum) into paymentsSum from sm.payments t where t.bankitems_id = bankItemId;
           select t.sum_pp into bankItemSum from sm.bankitems t where t.id = bankItemId;
           -- Вычисляем остаток с учетом последнего изменения (применяем коэффициен operationDirection)
           -- 1 - если происходит удаление и -1 при вставка платежа
           bankItemAmount := bankItemSum + paymentsSum * operationDirection;
           if bankItemAmount = 0 then
             -- Остаток равен нулю - состояние "Разнесено полностью"
             bankItemState := 2;
           else
             -- Если есть связанные платежи и остаток не нулевой, то состояние - "Частично разнесено"
             bankItemState :=1;
           end if;
         end if;
       -- Обновляем состояние BankItem
       update sm.bankitems t set t.distribution_state = bankItemState where t.id = bankItemId;
       end if;
    end;
BEGIN
 -- Вызываем обновления состояния для каждого BankItem, связанного с обновляемым платежом
 if INSERTING then
  ids := DistinctBankItemsIds(pay_state_pkg.newRows);
  for i in 1 .. ids.count loop
      UpdateBankItemsState(ids(i), -1);
  end loop;
 elsif DELETING then
  ids := DistinctBankItemsIds(pay_state_pkg.delRows);
  for i in 1 .. ids.count loop
      UpdateBankItemsState(ids(i), 1);
  end loop;
 end if;
END;
/

