prompt
CREATE OR REPLACE TRIGGER "SM".Privates_Obj AFTER UPDATE OR INSERT ON Privates FOR EACH ROW

Declare
  S1 Privates.Fullname%type;
  SmallInfo Clients.Name%type;
  LastPart varchar2(3):=' ИП';
  Cl_col_length number;
Begin

  select att.data_length 
  into Cl_col_length
  from all_tab_columns att 
  where 
   att.owner='SM' and 
   att.table_name='CLIENTS' and
   att.column_name='NAME';
   
  S1 := RTRIM(LTRIM(:new.FullName));
  if Length(S1)+Length(LastPart)>Cl_col_length then
    S1:=SUBSTR(S1,1,length(S1)-Length(LastPart));
  end if;  
 
  if :new.BUSINESSMAN='Y' then
    SmallInfo := S1 || LastPart;
    UPDATE Clients SET Name = SmallInfo
      WHERE ID=:new.Clients_ID;
  else
    SmallInfo :=S1;
    UPDATE Clients SET Name = SmallInfo
      WHERE ID=:new.Clients_ID;
  end if;
  
End;
/

