prompt Creating trigger SD3_OG_ORIGINAL_DELETE
prompt =======================================
prompt
create or replace trigger "SM".sd3_og_original_delete
  after delete on sm.sd3_og_original  
  for each row
declare
  -- local variables here
  current_rev_seq number;
begin
  if sm.sd3_utils.stop_triggers = 1 then
      return;
  end if;

  sm.sd3_utils.add_geometry_metadata_id_uniq(:old.sd3_geometry_metadata_id);
  
  select current_value into current_rev_seq from sm.sd3_geometry_revision_seq for update;
  current_rev_seq:=current_rev_seq+1;
  
  update sm.sd3_geometry_revision set revision_number = current_rev_seq where original_geometry_id = :old.id;
  
   --вставляем новый номер ревизии в sd3_geometry_revision_seq
   update sm.sd3_geometry_revision_seq set current_value = current_rev_seq;
end;
/

prompt
prompt Creating trigger SD3_OG_ORIGINAL_INSERT
prompt =======================================
prompt
create or replace trigger "SM".SD3_OG_ORIGINAL_INSERT
  after insert on sm.sd3_og_original  
  for each row
declare
  -- local variables here
  -- переменная для текущего revision_seq
  current_rev_seq number;
  table_count number;
  insert_table_name varchar2(40);
  self_cs varchar2(6);
  table_cs varchar2(6);
  transformed_geom mdsys.sdo_geometry;
  is_generated char(1);
  generated_id number;
begin
  if sm.sd3_utils.stop_triggers = 1 then
      return;
  end if;

  sm.sd3_utils.add_geometry_metadata_id_uniq(:new.sd3_geometry_metadata_id);
  
  -- получаем revision_seq и сохраняем его в таблицу sd3_geometry_revision_seq
  --select sm.seqsd3_geometry_revision_seq.nextval into current_rev_seq from dual;
  select current_value into current_rev_seq from sm.sd3_geometry_revision_seq for update;
  current_rev_seq:=current_rev_seq+1;
  
  select substr(t.wktext,0,6) into self_cs from mdsys.cs_srs t where t.srid=:new.GEOMETRY.SDO_SRID;
  
  -- цикл по всем координатным системам
  for cs in (select * from sm.sd3_used_coord_systems) loop
  
      -- проверяем соответствует ли тип координатной системы типу координатной системы текущей геометрии
      select substr(t.wktext,0,6) into table_cs from mdsys.cs_srs t where t.srid=cs.srid;
      -- если да или обе координатные системы нелокальные, то продолжаем
      if (self_cs = table_cs) or (self_cs <>'LOCAL_' and table_cs<>'LOCAL_') then

        -- преобразовываем геометрию
        -- !!! Внимание сейчас это сделано здесь потому что
        -- нет трансформации в зависимости от версии !!!
        if cs.srid = :new.GEOMETRY.SDO_SRID then
            transformed_geom := :new.GEOMETRY;
        else
          begin
            transformed_geom := mdsys.sdo_cs.transform(:new.GEOMETRY, cs.srid);
          exception
            when OTHERS then
              transformed_geom :=null;
          end;
        end if;
        
        if transformed_geom is not null then

          transformed_geom.SDO_POINT := SDO_GEOM.SDO_CENTROID(SDO_GEOM.SDO_MBR(transformed_geom),0.0005).SDO_POINT;
        -- цикл по всем версиям
        for v in (select * from sm.sd3_versions) loop

          -- проверяем существует ли таблица
          insert_table_name := 'SD3_OG_'||v.id||'_'||cs.srid;
          select count(*) into table_count from sys.all_tables t where t.owner='SM' and t.table_name = insert_table_name;

          -- таблица существует - отлично!!!
          if table_count>0 then

            -- !!! >> здесь еще надо вставить преобразование геометрий когда трансформация будет зависеть от версии
            
            -- определяем оригинальная ли геометрия будет помещаться в текущую таблицу
            if (cs.srid = :new.GEOMETRY.SDO_SRID) and (v.id = :new.SD3_VERSION_ID) then
                is_generated := 'N';
            else
                is_generated := 'Y';
            end if;

            --получаем id для сгенерированной геометрии
            select sm.seqsd3_og_generated.nextval into generated_id from dual;
            
            -- вставляем новые данные в таблицу соответствующую текущей версии и текущей координатной системе
            execute immediate 'insert into SM.'||insert_table_name||'(id, is_generated, geometry, original_geometry_id)'
                ||'values(:1,:2,:3,:4)'
                using generated_id, is_generated, transformed_geom, :new.id;
                
            -- вствляем данные в таблицу sd3_geometry_revision         
            insert into sm.sd3_geometry_revision(id, srid, version_id, revision_number, original_geometry_id, sd3_geometry_metadata_id)
                   values(generated_id, cs.srid, v.id, current_rev_seq, :new.id, :new.sd3_geometry_metadata_id);                               
          end if;         
        end loop;
        end if;
      end if;
   end loop;
   
   --вставляем новый номер ревизии в sd3_geometry_revision_seq
   update sm.sd3_geometry_revision_seq set current_value = current_rev_seq;
   
  return;
end;
/

prompt
prompt Creating trigger SD3_OG_ORIGINAL_UPDATE
prompt =======================================
prompt
create or replace trigger "SM".SD3_OG_ORIGINAL_UPDATE
  after update on sm.sd3_og_original
  for each row
declare
  -- local variables here
  -- переменная для текущего revision_seq
  current_rev_seq number;
  table_count number;
  insert_table_name varchar2(40);
  self_cs varchar2(6);
  table_cs varchar2(6);
  transformed_geom mdsys.sdo_geometry;
  is_generated char(1);
begin
  if sm.sd3_utils.stop_triggers = 1 then
      return;
  end if;
  sm.sd3_utils.add_geometry_metadata_id_uniq(:new.sd3_geometry_metadata_id);
  
  -- получаем revision_seq и сохраняем его в таблицу sd3_geometry_revision_seq
  --select sm.seqsd3_geometry_revision_seq.nextval into current_rev_seq from dual;
  select current_value into current_rev_seq from sm.sd3_geometry_revision_seq for update;
  current_rev_seq:=current_rev_seq+1;
  
  select substr(t.wktext,0,6) into self_cs from mdsys.cs_srs t where t.srid=:new.GEOMETRY.SDO_SRID;
  
  -- цикл по всем координатным системам
  for cs in (select * from sm.sd3_used_coord_systems) loop
  
      -- проверяем соответствует ли тип координатной системы типу координатной системы текущей геометрии
      select substr(t.wktext,0,6) into table_cs from mdsys.cs_srs t where t.srid=cs.srid;
      -- если да или обе координатные системы нелокальные, то продолжаем
      if (self_cs = table_cs) or (self_cs <>'LOCAL_' and table_cs<>'LOCAL_') then

        -- преобразовываем геометрию
        -- !!! Внимание сейчас это сделано здесь потому что
        -- нет трансформации в зависимости от версии !!!
        if cs.srid = :new.GEOMETRY.SDO_SRID then
            transformed_geom := :new.GEOMETRY;
        else
           begin
            transformed_geom := mdsys.sdo_cs.transform(:new.GEOMETRY, cs.srid);
           exception
             when others then 
               transformed_geom:=null;
           end; 
        end if;
        
        if transformed_geom is not null then
        -- цикл по всем версиям
        for v in (select * from sm.sd3_versions) loop

          -- проверяем существует ли таблица
          insert_table_name := 'SD3_OG_'||v.id||'_'||cs.srid;
          select count(*) into table_count from sys.all_tables t where t.owner='SM' and t.table_name = insert_table_name;

          -- таблица существует - отлично!!!
          if table_count>0 then

            -- !!! >> здесь еще надо вставить преобразование геометрий когда трансформация будет зависеть от версии
            
            -- определяем оригинальная ли геометрия будет помещаться в текущую таблицу
            if (cs.srid = :new.GEOMETRY.SDO_SRID) and (v.id = :new.SD3_VERSION_ID) then
                is_generated := 'N';
            else
                is_generated := 'Y';
            end if;
                        
            -- обновляем данные в таблице соответствующей текущей версии и текущей координатной системе
            execute immediate 'update SM.'||insert_table_name||' set is_generated=:1, geometry=:2'
                ||' where original_geometry_id='||:new.id
                using is_generated, transformed_geom;
                
            -- обновляем данные в таблице sd3_geometry_revision                                                
            update sm.sd3_geometry_revision
                   set revision_number = current_rev_seq,
                       sd3_geometry_metadata_id = :new.sd3_geometry_metadata_id
                   where original_geometry_id = :new.id;      
                   
          end if;         
        end loop;
        end if;
      end if;
   end loop;
   
   --вставляем новый номер ревизии в sd3_geometry_revision_seq
   update sm.sd3_geometry_revision_seq set current_value = current_rev_seq;
   
  return;
end;
/

