prompt
CREATE OR REPLACE TRIGGER "SM".SD_OBJ_GEOM_BEFORE_UPDATE_CS before insert or update on sm.SD_OBJECT_GEOMETRIES
begin
  --выходим если триггер заблокирован
  if sm.sdo_util.is_block_main_trigger = 1 then
    return;
  end if;
  
  sm.sdo_util.ids_to_change := sm.sdo_util.empty_ids;
  
  null;
end;
/

prompt
prompt Creating trigger SD_OBJ_GEOM_PREPARE_UPDATE_CS
prompt ==============================================
prompt
create or replace trigger "SM".SD_OBJ_GEOM_PREPARE_UPDATE_CS before insert or update on sm.SD_OBJECT_GEOMETRIES for each row
declare
 res number;
begin

 if sm.sdo_util.is_block_main_trigger = 1 then
   goto END_OF_TRIGGER;
 end if;
  
 -- Делаем проверку существования объектов
 res := sm.SDO_UTIL.is_saumi_data_linked(:new.dictionary_id, :new.data_id);
 if (res <> 1) then
   sm.SDO_UTIL.log_message('Объект не прошел проверку целостности. Справочник '||:new.dictionary_id||' id ='||:new.data_id);
   sm.SDO_UTIL.raise_not_object_exception;
 end if;
 -- Делаем проверку существования объектов

 --определяем нужно ли нам пересчитывать геометрию объектов
 if (UPDATING and
    (SDO_GEOM.RELATE(:old.original_geodata ,'EQUAL',:new.original_geodata,0.005)='FALSE')) or
    INSERTING then
     sm.sdo_util.ids_to_change(sm.sdo_util.ids_to_change.count+1) := :new.id;
 end if;


 <<END_OF_TRIGGER>>
 null;
end;
/

