prompt Creating trigger SHAREMOVE_AFTER_DELETE
prompt =======================================
prompt
CREATE OR REPLACE TRIGGER "SM".SHAREMOVE_AFTER_DELETE
  after delete on SHAREMOVE 
declare
  i number;  
begin
  
  if docsets_state_pkg.ShareMovocSetIDs.count>0 then
    for i in 1..docsets_state_pkg.ShareMovocSetIDs.count
    loop
      begin
        delete from sm.DocSets ds where ds.ID=docsets_state_pkg.ShareMovocSetIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
 
end;
/

