  after update on sm.SM_SETTINGS_TAB for each row

declare

 -- by XSGROUP 15.01.2010
 -- проверка установки даты закрытия бух. периода 
begin

 If (trim(:new.KEY_NAME) like 'ENDPERIOD') and (:new.VALUE>sysdate) then
         raise_application_error(-20101, 'Дата закрытия бухгалтерского периода не может быть в будущем!');
    end if;

end;
