prompt Creating trigger STATES_AFTER_DELETE
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER "SM".STATES_AFTER_DELETE
  after delete on STATES
declare
  i number;  
begin
  
  if docsets_state_pkg.StatesDocSetIDs.count>0 then
    for i in 1..docsets_state_pkg.StatesDocSetIDs.count
    loop
      begin
        delete from sm.DocSets ds where ds.ID=docsets_state_pkg.StatesDocSetIDs(i);
      exception
        when others then null;
      end;  
    end loop;
  end if;
 
end;
/

