prompt
CREATE OR REPLACE TRIGGER "SM".STATES_BEFORE_DELETE
  before delete on STATES
begin
 
  docsets_state_pkg.StatesDocSetIDs:=docsets_state_pkg.empty;
  
end;
/

prompt
prompt Creating trigger STATES_BEFORE_INS_UPD
prompt ======================================
prompt
CREATE OR REPLACE TRIGGER "SM".STATES_BEFORE_INS_UPD
  before update or insert on sm.STATES for each row
--
-- XSGROUP ver. 4.7.5 
--  Вычисляет и сохраняет кадастровую стоимость ЗУ, если она не указана напрямую.
--  Запрещает изменять дату состояния объекта "Пакеты акций,доли в капитале", 
--   если состояние связано с позицией ОД Собственность.
Declare 
  kCost number(27,6);
  gSquare sm.grounds.square%type;
  objTypesID number(27);
  iTmp integer;
	
Begin
  if (UPDATING) then
     -- Запрещает изменять дату состояния объекта "Пакеты акций,доли в капитале", 
     -- если состояние связано с позицией ОД Собственность.
     if (:new.calcdate <> :old.calcdate) then
        select o.OBJTYPES_ID into objTypesID from sm.OBJECTS o where o.ID=:new.OBJECTS_ID;    
        if (objTypesID = 21) then
           select count(*) into iTmp from sm.moveitems mi where mi.object_id=:new.OBJECTS_ID and mi.state_id=:new.id;   
           if (iTmp > 0) then
              for xx in (select mp.sincedate 
                            from 
                                sm.moveitems mi, sm.moveperiods mp 
                            where 
                                 mi.moveperiod_id=mp.id and mi.object_id=:new.OBJECTS_ID and mi.state_id=:new.id
              ) loop
                      if (xx.sincedate <> :new.calcdate) then
                         raise_application_error(-20101, 'Нельзя изменять дату состояния объекта типа ''Пакеты акций, доли в капитале'',' ||chr(10)
                                                                 ||' т.к. оно связано с движением объекта в ОД Собственность. ' );
                      end if;    
              end loop;               
           end if; 
        end if;
     end if;    
  end if; -- UPDATING

  --Вычисляет и сохраняет кадастровую стоимость ЗУ, если она не указана напрямую.
  if (:new.kadastr_cost is not null and :new.cadastralvalue is null and :new.kadastr_cost<>0) then  
     --Если тип объекта ЗУ и известна площадь
    select count(*) into iTmp from sm.grounds g where g.objects_id = :new.objects_id and g.square is not null;
    if (iTmp > 0) then 
        select g.square into gSquare from sm.grounds g where g.objects_id = :new.objects_id and g.square is not null;
        if gSquare is not null then
           --кадастровая стоимость ЗУ
           kCost := gSquare * :new.kadastr_cost;
        end if;     
    
        if kCost is not null then
           :new.cadastralvalue := round(kCost,2); 
        end if;      
    end if;      
     
  end if;    
End;
/

