prompt Creating trigger STATES_ID
prompt ==========================
prompt
CREATE OR REPLACE TRIGGER "SM".States_id BEFORE INSERT ON States FOR EACH ROW
--
-- by XSGROUP ver.29.01.2009
-- записываем информацию о том, кто и когда зарегистрировал состояние объекта
--
Declare
  FullUserName sm.registeredusers.fullname%type;
  len integer;
BEGIN

  select
    atc.DATA_LENGTH
  into
    len
  from
    all_tab_columns atc
  where
    atc.OWNER='SM' and
    atc.TABLE_NAME='STATES' and
    atc.COLUMN_NAME='CHANGEDBY';  

 SELECT ru.FullName INTO FullUserName FROM RegisteredUsers ru WHERE ru.UserName=USER;
 
 :new.WriteDate:=SYSDATE;
 :new.ChangedBy:=SUBSTR(FullUserName,1,len);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    raise_application_error(-20101, 'Вы не прописаны в расширенном списке пользователей системы. Обратитесь к администратору');
END;
/

prompt
prompt Creating trigger STATES_ORG_AFTER_INS_UPD
prompt =========================================
prompt
CREATE OR REPLACE TRIGGER "SM".STATES_ORG_AFTER_INS_UPD
  after update or insert on sm.STATES
--
-- XSGROUP ver. 4.8.2 (Patch от 13.11.2013)
-- редакция  ver. 4.8.3 (06.05.2014)

Declare
  ObjID number(27);
  dCalcdate date;

Begin
   if OrgState_And_Share_PKG.StateIDList.count>0 then
      for i in 1..OrgState_And_Share_PKG.StateIDList.count
        loop
            begin
               select s.objects_id, s.calcdate
               into ObjID,dCalcdate
               from sm.states s
               where s.id=OrgState_And_Share_PKG.StateIDList(i);            
            exception
              when others then null;
            end;
               for xxST in (
                        select * from sm.states st
                          where
                            st.objects_id = ObjID and
                            st.calcdate < dCalcdate
                          order by st.calcdate DESC
                       )
                loop
                    if (xxST.sharesNumber is not null or
                        xxST.sharesPrevNumber is not null or
                        xxST.nominalCost is not null or
                        xxST.goldstockowner_id is not null)
                    then
                      update sm.states s set
                       s.Sharesnumber=xxST.sharesNumber,                     
                       s.sharesPrevNumber = xxST.sharesPrevNumber,
                       s.nominalCost = xxST.nominalCost,
                       s.goldstockowner_id = xxST.goldstockowner_id
                      where s.id=OrgState_And_Share_PKG.StateIDList(i);
                       exit;
                    end if;
                end loop;
        end loop;
   end if;
End;
/

