prompt
CREATE OR REPLACE TRIGGER "SM".STATES_ORG_BEFORE_INS_UPD
  after update or insert on sm.STATES for each row
--
-- XSGROUP ver. 4.8.2 (Patch от 13.11.2013)
-- редакция  ver. 4.8.3 (06.05.2014)
-- Только для организаций  
--  переносит значения полей nominalcost,sharesnumber,sharesprevnumber,goldstockowner_id
--  из предыдущего состояния объектов-организаций, 
--  если данные поля предыдущего состояния заполнены, а в текущего - нет
-- (случай ввода через окно свойств состояния объекта-организации).
Declare
  objTypesID number(27);  
Begin  
  select o.objtypes_id into objTypesID from sm.objects o where o.id=:new.objects_id;
    
  if (objTypesID = 6) then
    if (:new.nominalcost is null and :new.sharesnumber is null and :new.sharesprevnumber is null) then
        OrgState_And_Share_PKG.StateIDList(OrgState_And_Share_PKG.StateIDList.count+1):=:new.id;
    end if;
  end if;    
End;
/

