prompt
prompt Creating trigger TAIS_CHMOVETYPE_MOVEITEMS
prompt ==========================================
prompt
create or replace trigger "SM".TAIS_CHMOVETYPE_MOVEITEMS
  after insert or update on moveitems
declare
  cnt integer;
  i   integer;
  Aleasepurpose_id integer;
begin
  --контролируем перессечение периодов с ОД
  if check_movetype_for_object_pkg.OBJECT_ID.count > 0 then --если есть объекты
    if check_movetype_for_object_pkg.MOVETYPE_ID.count > 0 then --если есть тип
      if check_movetype_for_object_pkg.SINCEDATE.count > 0 then --если есть период
         for i in 1..check_movetype_for_object_pkg.OBJECT_ID.count
         loop
          /* if INSERTING then
             insert into test (id,name) values (sm.seqaddress.nextval,'TAIS_CHMOVETYPE_MOVEITEMS - insert');
           else
              insert into test (id,name) values (sm.seqaddress.nextval,'TAIS_CHMOVETYPE_MOVEITEMS - update');
           end if;*/
           begin
            select count(*)
              into cnt
              from sm.movesets ms
              join sm.moveperiods mp on mp.moveset_id = ms.id
              join sm.moveitems mi on mi.moveperiod_id = mp.id
             where ms.movetype_id = check_movetype_for_object_pkg.MOVETYPE_ID(i)
               and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
               and ms.id <> check_movetype_for_object_pkg.MOVESETS_ID(i)
               and (
                   mp.sincedate between sm.check_movetype_for_object_pkg.SINCEDATE(i)and coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                   or
                   coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')) between check_movetype_for_object_pkg.SINCEDATE(i) and coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                   or
                   coalesce(mp.sincedate, TO_DATE('31.12.2050','DD.MM.YYYY')) <= check_movetype_for_object_pkg.SINCEDATE(i)
                   and
                   coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')) >= coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                   );
            if (cnt>0)  then
              raise_application_error(-20101, 'Объект уже имеет оформляемую ОД');
            end if;
            cnt:=0;
            select mi.leasepurpose_id
              into Aleasepurpose_id
              from sm.movesets ms
              join sm.moveperiods mp on mp.moveset_id = ms.id
              join sm.moveitems mi on mi.moveperiod_id = mp.id
             where ms.movetype_id = check_movetype_for_object_pkg.MOVETYPE_ID(i)
               and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
               and ms.id = check_movetype_for_object_pkg.MOVESETS_ID(i);
            if (Aleasepurpose_id is null)  then
              raise_application_error(-20101, 'Не заполнено Целевое назначение');
            end if;
            exception
            when NO_DATA_FOUND then
            null;
            end;
         end loop;

      end if;
    end if;
  end if;
end TAIS_CHMOVETYPE_MOVEITEMS;
/

prompt
prompt Creating trigger TAIS_CHMOVETYPE_MOVEPERIODS
prompt ============================================
prompt
create or replace trigger SM.TAIS_CHMOVETYPE_MOVEPERIODS
  after insert or update on moveperiods
declare
  cnt integer;
  cnt2 integer;
  i   integer;
  Aleasepurpose_id integer;
begin
  --контролируем перессечение периодов с ОД
  if check_movetype_for_object_pkg.OBJECT_ID.count > 0 then --если есть объекты
    if check_movetype_for_object_pkg.MOVETYPE_ID.count > 0 then --если есть тип
      if check_movetype_for_object_pkg.SINCEDATE.count > 0 then --если есть период
         for i in 1..check_movetype_for_object_pkg.OBJECT_ID.count
         loop
           /* if INSERTING then
              insert into test (id,name) values (sm.seqaddress.nextval,'TAIS_CHMOVETYPE_MOVEPERIODS - insert');
            else
              insert into test (id,name) values (sm.seqaddress.nextval,'TAIS_CHMOVETYPE_MOVEPERIODS - update');
            end if;*/
            begin
            if (check_movetype_for_object_pkg.MOVETYPE_ID(i) in (29,30,31,34)
                and check_movetype_for_object_pkg.Sharepercent(i) = 100) then
                cnt := 0;
               
                select count(*)
                  into cnt
                  from sm.movesets ms
                  join sm.moveperiods mp on mp.moveset_id = ms.id
                  join sm.moveitems mi on mi.moveperiod_id = mp.id
                 where ms.movetype_id = check_movetype_for_object_pkg.MOVETYPE_ID(i)
                   and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
                   and ms.id <> check_movetype_for_object_pkg.MOVESETS_ID(i)
                   and (
                       mp.sincedate between sm.check_movetype_for_object_pkg.SINCEDATE(i)and coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                       or
                       coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')) between check_movetype_for_object_pkg.SINCEDATE(i) and coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                       or
                       coalesce(mp.sincedate, TO_DATE('31.12.2050','DD.MM.YYYY')) <= check_movetype_for_object_pkg.SINCEDATE(i)
                       and
                       coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')) >= coalesce(check_movetype_for_object_pkg.ENDDATE(i), TO_DATE('31.12.2050','DD.MM.YYYY'))
                       );
                                       
                if (cnt > 0) then
                  if (check_movetype_for_object_pkg.MOVETYPE_ID(i) not in (31,34)) then
                     raise_application_error(-20101, 'Объект уже имеет оформляемую ОД');
                  end if;
                  
                  -- если Забалансовый учет, то смотрим, если есть Концессия, то Забалансовых может быть много, если Концессии нет. то забалансовый только 1
                  if (check_movetype_for_object_pkg.MOVETYPE_ID(i) in (31)) then
                     cnt2 := 0;
                     -- найдем концессию
                     select count(*)
                      into cnt2
                      from sm.movesets ms
                      join sm.moveperiods mp on mp.moveset_id = ms.id
                      join sm.moveitems mi on mi.moveperiod_id = mp.id
                     where ms.movetype_id = 34 -- Концессия
                       and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
                       and mp.sincedate <= coalesce(check_movetype_for_object_pkg.enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY')) 
                       and coalesce(mp.enddate,TO_DATE('31.12.2050','DD.MM.YYYY')) >= check_movetype_for_object_pkg.SINCEDATE(i);   
                       
                     if (cnt2 is null) then                      
                         cnt2 := 0;  
                     end if;  
                     
                     -- если нет Концессии и при этом более одного Забалансового, то ошибка  -- отменено в апреле 2021 в связи с изменением логики
                     /*if (cnt2 = 0) then
                         raise_application_error(-20101, 'Объект уже имеет оформляемую ОД*****');
                     end if;*/
                  end if;
                end if;                                
            end if;

            if (check_movetype_for_object_pkg.MOVETYPE_ID(i) in (29,31)
                and check_movetype_for_object_pkg.Sharepercent(i) = 100) then
              select mi.leasepurpose_id
                into Aleasepurpose_id
                from sm.movesets ms
                join sm.moveperiods mp on mp.moveset_id = ms.id
                join sm.moveitems mi on mi.moveperiod_id = mp.id
               where ms.movetype_id = check_movetype_for_object_pkg.MOVETYPE_ID(i)
                 and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
                 and ms.id = check_movetype_for_object_pkg.MOVESETS_ID(i);
              if (Aleasepurpose_id is null)  then
                raise_application_error(-20101, 'Не заполнено Целевое назначение');
              end if;
            end if;
            
            cnt := 0;
            
            --если казна и ее закрывают, проверим чтобы не было открытого забалансового учета
            if (check_movetype_for_object_pkg.old_enddate.count > 0)  then
              if (check_movetype_for_object_pkg.MOVETYPE_ID(i) in (10)
                  and coalesce(check_movetype_for_object_pkg.enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY')) <> coalesce(check_movetype_for_object_pkg.old_enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY'))
                   and check_movetype_for_object_pkg.Sharepercent(i) = 100
                  ) then
                    select count(*)
                      into cnt
                      from sm.movesets ms
                      join sm.moveperiods mp on mp.moveset_id = ms.id
                      join sm.moveitems mi on mi.moveperiod_id = mp.id
                     where ms.movetype_id = 31 --забалансовый
                       and mi.object_id = check_movetype_for_object_pkg.OBJECT_ID(i)
                       and coalesce(mp.enddate,TO_DATE('31.12.2050','DD.MM.YYYY')) > coalesce(check_movetype_for_object_pkg.enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY'));
                    if (cnt>0)  then
                      raise_application_error(-20101, 'Невозможно закрыть ОД Казна/Бюджетный учет/Аренда, так как есть ОД Забалансовый учет');
                    end if;
              end if;
              
              -- если закрытвают бюджетный учет, то смотрим чтобы была для этого роль
              -- которая это разрешает
              -- тут может быть две роли
              -- роль которая позволяет создавать/удалять/изменять БУ
              -- и если это делают каскадом при списании то это могут сдулать только
              -- определенные люди
              if (check_movetype_for_object_pkg.MOVETYPE_ID(i) in (29)
                  and coalesce(check_movetype_for_object_pkg.enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY')) <> coalesce(check_movetype_for_object_pkg.old_enddate(i),TO_DATE('31.12.2050','DD.MM.YYYY'))) then
                 if (not dbms_session.is_role_enabled('SM_MOVE29_BUDGACCOUNT') and not dbms_session.is_role_enabled('SM_CASCADE_BUDG')) then
                   raise_application_error(-20001,'Невозможно закрыть ОД Бюджетный учет. Нет прав.');
                 end if;
              end if;
            end if;
            cnt:=0;
            exception
            when NO_DATA_FOUND then
            null;
            end;
         end loop;

      end if;
    end if;
  end if;
end TAIS_CHMOVETYPE_MOVEITEMS;
/

