prompt
prompt Creating trigger TAIU_SET_REALESTATE
prompt ====================================
prompt
create or replace trigger "SM".TAIU_SET_REALESTATE
  after insert or update on moveperiods  
  for each row
declare
  Aisrealestate char(1);
begin
  Aisrealestate := 'N';
  
  -- если есть документы
  if (:new.docset_id is not null) then
    -- проверим наличие документов свидетельство 
    -- или 
    -- Свидетельство о гос. рег-ции права
    for yyy in (
               select d.*
                 from sm.docset_members dm
                 join sm.documents d on d.id = dm.document_id and d.doctypes_id in (748, 1742, 3117)  
                where dm.docset_id = :new.docset_id 
              )
    loop 
      Aisrealestate := 'Y';
    end loop;
    
    if (Aisrealestate = 'Y') then
      -- получим тип объекта
      for xxx in ( 
                 select o.objtypes_id,
                        o.id
                   from sm.moveitems mi
                   join sm.objects o on o.id = mi.object_id
                   join sm.movesets ms on ms.id = :new.moveset_id
                  where mi.moveperiod_id = :new.id
                    and ms.movetype_id in (1,2) -- собственность или баланс  
                    and o.objtypes_id in (4,5) -- инженерка и незавершенное
                    )
       loop  
        if (xxx.objtypes_id = 5) then
           update sm.enginf e
              set e.isrealestate = 'Y'
            where e.objects_id = xxx.id
              and e.isrealestate <> 'Y';  
        end if;
        if (xxx.objtypes_id = 4) then
           update sm.unconstr e
              set e.isrealestate = 'Y'
            where e.objects_id = xxx.id
              and e.isrealestate <> 'Y';
        end if; 
       end loop; 
     end if;               
   end if;     
end TAIU_SET_REALESTATE;
/

