prompt
prompt Creating trigger TAI_CASCADE_UPDATE
prompt ===================================
prompt
create or replace trigger SM.TAI_CASCADE_UPDATE
  after update on objects
  for each row
declare
  -- local variables here
begin
  if (:new.id <> :old.id) then
    --Прочее движимое имущество
    if (:old.objtypes_id = 1)then
       update sm.property p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Транспортные средства
    if (:old.objtypes_id = 2)then
        update sm.transport p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Здания и помещения
    if (:old.objtypes_id = 3)then
       update sm.buildings p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Незавершенное строительство
    if (:old.objtypes_id = 4)then
        update sm.unconstr p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Инженерная инфраструктура
    if (:old.objtypes_id = 5)then
        update sm.enginf p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Организации
    if (:old.objtypes_id = 6)then
        update sm.organisations p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;
    --Земельные участки
    if (:old.objtypes_id = 7)then
        update sm.organisations p
          set p.objects_id = :new.id
        where p.objects_id = :old.id;
    end if;

    update sm.moveitems m
       set m.object_id = :new.id
     where m.object_id = :old.id;

    update sm.states m
       set m.objects_id = :new.id
     where m.objects_id = :old.id;
  end if;
end TAI_CASCADE_UPDATE;
/

