prompt
create or replace trigger "SM".TAU_OBJECT_SET_MONUMENT
  after update on Objects
declare
objects_id numeric(27);
begin
  -- идем по всему списку
  if OBJECT_LIST_PKG_1.OBJECT_ID.count > 0 then -- если есть объекты
     for i in 1..OBJECT_LIST_PKG_1.OBJECT_ID.count
     loop
        objects_id := OBJECT_LIST_PKG_1.OBJECT_ID(i);
        begin
          sm.OBJECT_LIST_PKG_1.OBJECT_ID := sm.OBJECT_LIST_PKG_1.EmptyID;
