prompt
prompt Creating trigger TBD_CHECK_MOVEITEMS
prompt ====================================
prompt
create or replace trigger "SM".TBD_CHECK_MOVEITEMS
  before delete on moveitems
  for each row
declare
 pragma autonomous_transaction;
 Amovetype_id number;
 Asincedate date;
 Aenddate date;
 cnt number;
begin
  /*21/09/2014 Твердохлеб: Данный триггер заполняет пакет если удаляют ОД аренда*/

  -- если аренда
  select mp.sincedate,
         coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')),
         ms.movetype_id
    into Asincedate,
         Aenddate,
         Amovetype_id
    from sm.moveperiods mp
    join movesets ms on ms.id = mp.moveset_id
   where mp.id = :old.moveperiod_id;

  if (Amovetype_id in (4,22)) then
    -- идем по самому объекту и его родителям
      for xxx in (
                 select b.objects_id
                   from sm.Buildings b
                  start with b.objects_id = :old.object_id
                  connect by prior  b.basebuilding  = b.id
                 )
      loop
         cnt := 0;
         select count(*)
                into cnt
                from sm.movesets ms
                join sm.moveperiods mp on mp.moveset_id = ms.id
                join sm.moveitems mi on mi.moveperiod_id = mp.id
               where ms.movetype_id in (31)
                 and mi.object_id = xxx.objects_id
                 and mp.sincedate <= Aenddate
                 and coalesce(mp.enddate, TO_DATE('31.12.2050','DD.MM.YYYY')) >= Asincedate;
              if (cnt > 0)  then
                raise_application_error(-20101, 'Нельзя удалить ОД Аренда/Безвозмездное пользование, так как у объекта или его родителя есть Забалансовый учет');
              end if;
      end loop;
    end if;
end TBD_CHECK_MOVEITEMS;
/

