prompt
prompt Creating trigger TBIR_CHMOVETYPE_MOVEITEMS
prompt ==========================================
prompt
create or replace trigger "SM".TBIR_CHMOVETYPE_MOVEITEMS
  before insert or update on moveitems
  for each row
declare
 Amovetype_id number;
 Amovesets_id number;
 Asincedate date;
 Aenddate date;
begin
 /* if INSERTING then
    insert into test (id,name) values (sm.seqaddress.nextval,'TBIR_CHMOVETYPE_MOVEITEMS - insert');
  else
    insert into test (id,name) values (sm.seqaddress.nextval,'TBIR_CHMOVETYPE_MOVEITEMS - update');
  end if;*/
    
  sm.check_movetype_for_object_pkg.MOVETYPE_ID := sm.check_movetype_for_object_pkg.EmptyMT;
  sm.check_movetype_for_object_pkg.OBJECT_ID := sm.check_movetype_for_object_pkg.EmptyO;
  sm.check_movetype_for_object_pkg.SINCEDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.ENDDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.OLD_ENDDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.OLD_SINCEDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.MOVESETS_ID := sm.check_movetype_for_object_pkg.EmptyMT;

 select ms.movetype_id,
        ms.id,
        mp.sincedate,
        mp.enddate
   into Amovetype_id,
        Amovesets_id,
        Asincedate,
        Aenddate
   from sm.moveperiods mp
   join sm.movesets ms on ms.id = mp.moveset_id
  where mp.id = :new.moveperiod_id;
 if (Amovetype_id in (29,30,31)) then
   --идем по всем объектам периода ОД, у которых полная доля права
   sm.check_movetype_for_object_pkg.MOVETYPE_ID(sm.check_movetype_for_object_pkg.MOVETYPE_ID.count + 1) := Amovetype_id;
   sm.check_movetype_for_object_pkg.OBJECT_ID(sm.check_movetype_for_object_pkg.OBJECT_ID.count + 1) := :new.OBJECT_ID;
   sm.check_movetype_for_object_pkg.SINCEDATE(sm.check_movetype_for_object_pkg.SINCEDATE.count + 1) := Asincedate;
   sm.check_movetype_for_object_pkg.ENDDATE(sm.check_movetype_for_object_pkg.ENDDATE.count + 1) := Aenddate;
   sm.check_movetype_for_object_pkg.MOVESETS_ID(sm.check_movetype_for_object_pkg.MOVESETS_ID.count + 1) := Amovesets_id;
 end if;
 --если забалансовый учет, то заполним Целевое назначение, если не заполнено и возьмем его с Бюджетного учета
 if check_movetype_for_object_pkg.MOVETYPE_ID.count > 0 then --если есть тип
   if (check_movetype_for_object_pkg.MOVETYPE_ID(1) = 31 and :new.leasepurpose_id is null) then
       select mi.leasepurpose_id
         into :new.leasepurpose_id
         from sm.Movesets ms,
              sm.moveitems mi,
              sm.moveperiods mp
        where ms.movetype_id = 29  and
              mp.moveset_id = ms.id and
              mi.moveperiod_id = mp.id and
              mi.object_id = :new.object_id and
              trunc(mp.sincedate) <= trunc(sysdate) and
              (trunc(mp.enddate) >= trunc(sysdate) or mp.enddate is null);
   end if;
 end if;
 exception
 when NO_DATA_FOUND then
 null;
end TBIR_CHMOVETYPE_MOVEPERIODS;
/

prompt
prompt Creating trigger TBIR_CHMOVETYPE_MOVEPERIODS
prompt ============================================
prompt
create or replace trigger "SM".TBIR_CHMOVETYPE_MOVEPERIODS
  before insert or update on moveperiods
  for each row
declare
 Amovetype_id number;
 Amovesets_id number;
 Aleasepurpose_id number;
 i number;
begin
  /*if INSERTING then
    insert into test (id,name) values (sm.seqaddress.nextval,'TBIR_CHMOVETYPE_MOVEPERIODS - insert');
  else
    insert into test (id,name) values (sm.seqaddress.nextval,'TBIR_CHMOVETYPE_MOVEPERIODS - update');
  end if;*/

  sm.check_movetype_for_object_pkg.MOVETYPE_ID := sm.check_movetype_for_object_pkg.EmptyMT;
  sm.check_movetype_for_object_pkg.OBJECT_ID := sm.check_movetype_for_object_pkg.EmptyO;
  sm.check_movetype_for_object_pkg.SINCEDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.ENDDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.OLD_ENDDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.OLD_SINCEDATE := sm.check_movetype_for_object_pkg.EmptyD;
  sm.check_movetype_for_object_pkg.MOVESETS_ID := sm.check_movetype_for_object_pkg.EmptyMT;
  sm.check_movetype_for_object_pkg.Sharepercent := sm.check_movetype_for_object_pkg.EmptyMT;
 select ms.movetype_id,
        ms.id
   into Amovetype_id,
        Amovesets_id
   from sm.movesets ms
  where ms.id = :new.moveset_id;

 if (Amovetype_id in (10,29,30,31,34)) then
   i := 1;
   --идем по всем объектам периода ОД, у которых полная доля права
   for xx in (
              select mi.object_id,
                     mi.leasepurpose_id,
                     mi.id,
                     mi.sharepercent
                from sm.moveitems mi
               where mi.moveperiod_id = :new.id
                 --and mi.sharepercent = 100
              )
   loop
     sm.check_movetype_for_object_pkg.MOVETYPE_ID(sm.check_movetype_for_object_pkg.MOVETYPE_ID.count + 1) := Amovetype_id;
     sm.check_movetype_for_object_pkg.OBJECT_ID(sm.check_movetype_for_object_pkg.OBJECT_ID.count + 1) := xx.OBJECT_ID;
     sm.check_movetype_for_object_pkg.SINCEDATE(sm.check_movetype_for_object_pkg.SINCEDATE.count + 1) := :new.sincedate;
     sm.check_movetype_for_object_pkg.ENDDATE(sm.check_movetype_for_object_pkg.ENDDATE.count + 1) := :new.enddate;
     sm.check_movetype_for_object_pkg.OLD_SINCEDATE(sm.check_movetype_for_object_pkg.OLD_SINCEDATE.count + 1) := :old.sincedate;
     sm.check_movetype_for_object_pkg.OLD_ENDDATE(sm.check_movetype_for_object_pkg.OLD_ENDDATE.count + 1) := :old.enddate;
     sm.check_movetype_for_object_pkg.MOVESETS_ID(sm.check_movetype_for_object_pkg.MOVESETS_ID.count + 1) := Amovesets_id;
     sm.check_movetype_for_object_pkg.Sharepercent(sm.check_movetype_for_object_pkg.Sharepercent.count + 1) := xx.sharepercent;

    --если забалансовый учет, то заполним Целевое назначение, если не заполнено и возьмем его с Бюджетного учета
     if (check_movetype_for_object_pkg.MOVETYPE_ID.count > 0 and sm.check_movetype_for_object_pkg.Sharepercent(i) = 100) then --если есть тип
       if (check_movetype_for_object_pkg.MOVETYPE_ID(i) = 31 and xx.leasepurpose_id is null) then
           select mi.leasepurpose_id
             into Aleasepurpose_id
             from sm.Movesets ms,
                  sm.moveitems mi,
                  sm.moveperiods mp
            where ms.movetype_id = 29  and
                  mp.moveset_id = ms.id and
                  mi.moveperiod_id = mp.id and
                  mi.object_id = xx.object_id and
                  trunc(mp.sincedate) <= trunc(sysdate) and
                  (trunc(mp.enddate) >= trunc(sysdate) or mp.enddate is null);
            if (Aleasepurpose_id is not null) then
              update sm.moveitems mi
                 set mi.leasepurpose_id = Aleasepurpose_id
               where mi.id = xx.id;
            end if;
       end if;
     end if;
     i := i + 1;
   end loop;
 end if;
 exception
 when NO_DATA_FOUND then
 null;
end TBIR_CHMOVETYPE_MOVEPERIODS;
/

prompt
prompt Creating trigger TBIU_ARENDA_DOCSET_MEMBERS
prompt ===========================================
prompt
CREATE OR REPLACE TRIGGER SM.TBIU_ARENDA_DOCSET_MEMBERS
BEFORE INSERT OR UPDATE ON SM.DOCSET_MEMBERS FOR EACH ROW
DECLARE
  Amovetype_id NUMBER;
BEGIN
  /*26/10/2015 При добавлении документа в пакет смотрим на ОД. Если это Аренда, то запрещаем добавлять доки без скана*/
  
  IF (:NEW.DOCSET_ID IS NOT NULL) THEN
    FOR 
       yyy IN (
              SELECT d.BODY,
                     d.FILE_EXTENTION
                FROM DOCUMENTS d   
               WHERE d.id = :NEW.DOCUMENT_ID
                 AND d.DOCTYPES_ID IN (823,1655,1579,1713,1204,3017,1602,1739,862,882)
              )
    LOOP   
      FOR xxx 
              IN (SELECT mp.moveset_id
                    FROM moveperiods mp
                   where mp.DOCSET_ID = :NEW.DOCSET_ID   
                 ) 
      LOOP
          SELECT ms.movetype_id
            INTO Amovetype_id
            FROM sm.movesets ms
            WHERE ms.id = xxx.moveset_id;
          -- если аренда
          IF (Amovetype_id IN (3, 4, 5, 11, 22))
          THEN
            IF ((dbms_lob.getlength(yyy.BODY) = 0 OR yyy.BODY IS NULL)
              AND yyy.FILE_EXTENTION IS NULL)
            THEN
              RAISE_APPLICATION_ERROR(-20001, 'Необходимо загрузить скан документа');
            END IF;
          END IF;
      END LOOP;
    END LOOP;         
  END IF;
END;
/

prompt
prompt Creating trigger TBIU_ARENDA_MOVEPERIODS
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER SM.TBIU_ARENDA_MOVEPERIODS
BEFORE INSERT OR UPDATE ON SM.MOVEPERIODS FOR EACH ROW
DECLARE
  Amovetype_id NUMBER;
  cnt          NUMBER;
BEGIN
  /*26/10/2015 Контролирует прикладываение скана в документ*/

  SELECT ms.movetype_id
    INTO Amovetype_id
    FROM sm.movesets ms
    WHERE ms.id = :new.moveset_id;
 
  IF (Amovetype_id IN (3, 4, 5, 11, 22)
    AND :NEW.DOCSET_ID IS NOT NULL)
  THEN
    -- в документе должне быть скан прикреплен   
    FOR xxx IN (SELECT d1.BODY,
                       d1.FILE_EXTENTION,
                       d1.DOCTYPES_ID 
                  FROM DOCSET_MEMBERS dm
                  JOIN DOCUMENTS d1 ON d1.ID = dm.DOCUMENT_ID
                 WHERE dm.DOCSET_ID = :NEW.DOCSET_ID
                   AND d1.DOCTYPES_ID IN (823,1655,1579,1713,1204,3017,1602,1739,862,882)
                )
    LOOP
      IF ((dbms_lob.getlength(xxx.BODY) = 0 OR xxx.BODY IS NULL)
        AND xxx.FILE_EXTENTION IS NULL)
      THEN
        RAISE_APPLICATION_ERROR(-20001, 'Необходимо загрузить скан документа');
      END IF;
    END LOOP;
  END IF;
END;
/

