prompt Creating trigger TBIU_DOCUMENTS
prompt ===============================
prompt
CREATE OR REPLACE TRIGGER SM.TBIU_DOCUMENTS
BEFORE INSERT OR UPDATE ON SM.DOCUMENTS FOR EACH ROW
BEGIN
  -- если роль аренды
  IF (dbms_session.is_role_enabled('SM_MOVE11_AREND_FOND')
    OR dbms_session.is_role_enabled('SM_MOVE3_POLSOVANIE')
    OR dbms_session.is_role_enabled('SM_MOVE22_BVOZMPOLZ')
    OR dbms_session.is_role_enabled('SM_MOVE4_ARENDA')
    OR dbms_session.is_role_enabled('SM_MOVE5_SUBARENDA')
    )
  THEN 
    IF (dbms_lob.getLength(:NEW.BODY) = 0
      AND :NEW.FILE_EXTENTION IS NULL)
    THEN
      RAISE_APPLICATION_ERROR(-20001, 'Необходимо загрузить скан документа');
    END IF;
  END IF;
END;
/

