prompt
create or replace trigger "SM".TBIU_OBJECTS
  before insert or update or delete on Objects
  for each row
declare
  Amovetype integer;
begin
  /*проверяем можно ли редактировать статус Памятник*/
  if (inserting) then
    if (:new.is_monument = 'Y') then
        if not dbms_session.is_role_enabled('SM_MONUMENT') then
           raise_application_error(-20001,'Нет прав на создание объекта Памятник');
        end if;
    end if;
  end if;
  if (updating) then
    if (:new.is_monument <> :old.is_monument) then
        if not dbms_session.is_role_enabled('SM_MONUMENT') then
           raise_application_error(-20001,'Нет прав на изменение объекта Памятник');
        end if;
    end if;
  end if;

end TBIU_STATES;
