prompt
prompt Creating trigger TBIU_STATES
prompt ============================
prompt
create or replace trigger "SM".TBIU_STATES
  before insert or update or delete on states
  for each row
declare
  is_allowed_edit char(1);
  Aobjects_id integer;
  Amovetype_id integer;
begin
  /*проверяет если есть ОД Бюджетный учет и Забалансовый учет,
  то при отсутствии роли SM_STATES_BUDG редактировать состояние объектов (стоимость) запрещено*/
  begin
    is_allowed_edit := 'N'; 
    if (inserting) then
      Aobjects_id := :new.objects_id;
    end if;
    if (updating or deleting) then
      Aobjects_id := :old.objects_id;
    end if;   
    
    for xx in (
                select m.MoveType_ID,
                       ms.is_allowed_edit
                  from sm.movements m
                  join sm.movesets ms on ms.id = m.MoveSet_ID
                 where m.OBJECTS_ID = Aobjects_id
                   and m.POSTINGDATE <= sysdate
                   and (m.EndDate >= sysdate or m.EndDate is null)
                   and m.MoveType_ID in (29,31)
                 order by m.MoveType_ID 
                   )
     loop 
        if (xx.is_allowed_edit = 'Y')then
            is_allowed_edit := xx.is_allowed_edit;
        end if;
        Amovetype_id := xx.movetype_id;
     end loop; 
                  
     exception
    when NO_DATA_FOUND then
    null;
  end;
  
  if (Amovetype_id is not null and (is_allowed_edit = 'N' or is_allowed_edit is null)) then
      if not dbms_session.is_role_enabled('SM_STATES_BUDG') then
         raise_application_error(-20001,'Невозможно изменить состояние объекта, так как есть ОД Бюджетный учет/Забалансовый учет');
      end if;
  end if;
end TBIU_STATES;
/

