prompt
prompt Creating trigger TRANSPORT_OBJ
prompt ==============================
prompt
CREATE OR REPLACE TRIGGER "SM".Transport_Obj AFTER UPDATE OR INSERT ON Transport FOR EACH ROW



Declare
 S1 CHAR(100);
 S2 CHAR(100);
 SmallInfo CHAR(100);
Begin
 SELECT TranspType.Name INTO S1 FROM TranspType WHERE ID=:new.TranspType_ID;
 SELECT BrandNames.Name INTO S2 FROM BrandNames WHERE ID=:new.BrandNames_ID;

 SmallInfo := SUBSTR(RTRIM(S2) || ' ' || RTRIM(:new.Model) || ' (' || RTRIM(S1) || ')',1,60);

 UPDATE Objects SET Description = SmallInfo
   WHERE ID=:new.Objects_ID;
		
End;
/

