prompt
create or replace trigger "SM".TRANSPORT_USE_STORAGE 
  after delete on TRANSPORT


declare
  i integer;
begin 

  if storage_pkg.ObjectsIDs.count>0 and not storage_pkg.ObjectsSelf then
    for i in 1..storage_pkg.ObjectsIDs.count loop
      begin
        delete from sm.OBJECTS o where o.ID=storage_pkg.ObjectsIDs(i);
      exception
        when others then
          null;  
      end;  
    end loop;
  end if;

end;
/

