prompt
create or replace trigger SM.VER_EXT_FILES_SET_ID
  before insert on SM.VER_EXT_FILES
  for each row
declare
begin
  if :new.ID is not null then
    -- установка значения для поля типа 'счетчик' (когда значение получается из соответствующей последовательности) запрещена,
    -- при возбуждении ошибки подобного типа используем код ошибки -20100
    RAISE_APPLICATION_ERROR(-20100, 'Insert is denied! Can not insert value to field VER_EXT_FILES.ID, this field value should be automatically generated from sequence SEQVER_EXT_FILES!');
  end if;
  -- получаем значение ID из соответствующей последовательности
  select SM.SEQVER_EXT_FILES.NEXTVAL into :new.ID from dual;
end;
