prompt
create or replace trigger "SM".ver_updates_guid
before insert on sm.ver_updates
for each row
declare
 l_guid varchar2(50);  
begin  
     l_guid:=sys_guid(); 
     :new.updatecode:=substr(l_guid,1,8)||'-'||
                      substr(l_guid,9,4)||'-'||
                      substr(l_guid,13,4)||'-'||
                      substr(l_guid,17,4)||'-'||
                      substr(l_guid,21,12);
 
end;
/

prompt
prompt Creating trigger X_ON_ALTER_SM
prompt ==============================
prompt
create or replace trigger "SM".X_ON_ALTER_SM before ALTER on SCHEMA 
--------------------------------------------------------------------------------------------------
-- Author  : XSGROUP
-- Created : 19.02.2004 
-- Purpose : триггер реагирует на удаление столбца из какой-либо таблицы схеы SM.
--           если по этому столбцу ведётся история реквизитов - удаление отменяется;
--           если удаляется столбец, по которому велась история реквизитов - удаление отменяется;
--           если в таблице имеются столбцы, по которым ведётся (или велась) история реквизитов,
--           и id  удаляемого столбца меньше id  колонок с историей - осуществляется корректировка
--           таблиц SM_CHANGES и SM_TAB_COLUMNS, в X_SM_LOG_TRIGGERS заносится название изменяемой
--           таблицы, чтобы утилита FldMan.exe  смогла скорректировать необходимые триггеры.
--------------------------------------------------------------------------------------------------

--IGNORE 04072
--IGNORE 00406


declare

  cnt integer;
  tab_id integer;
  col_id integer;
  tab_name varchar2(200);
  col_name varchar2(200);

  
begin
  if ora_dict_obj_type='TABLE' then
  
    tab_name:=ora_dict_obj_name;
    
    for xx in (select * from all_tab_columns tc where tc.owner='SM' and tc.table_name=tab_name)
    loop
      if ora_is_drop_column(xx.column_name) then
        col_name:=xx.column_name;
        col_id:=xx.column_id;
        if (Upper(col_name)='CHANGE_DATE')or(Upper(col_name)='CHANGE_DOC') then
          raise_application_error(-20101,'Нельзя удалить поле '||col_name||' таблицы '||tab_name||chr(13)||'т.к. оно необходимо для ведения истории значений');
        end if;
        
        select count(*) into cnt
        from 
          sm.fm_tables 
        where 
          table_name=tab_name;
          
        if cnt<>0  then
        
          select
            ID into tab_id 
          from 
            sm.fm_tables 
          where 
            table_name=tab_name;
        
        
          -- проверяем таблицу SM_CHANGES
          select 
            count(*) into cnt
          from 
            sm.Sm_Changes sc 
          where 
            sc.fm_tables_id=tab_id and
            sc.column_id=col_id;
            
          if cnt<>0 then  
            raise_application_error(-20101,'Нельзя удалить поле '||col_name||' таблицы '||tab_name||chr(13)||'т.к. по нему ведётся история значений');
          end if;
          
          -- проверяем таблицу FM_TAB_COLUMNS
          select 
            count(*) into cnt  
          from
            sm.Fm_Tab_Columns ftc
          where
            ftc.fm_tables_id=tab_id and
            ftc.columns_id=col_id and
            UPPER(ftc.history)='Y';
            
           if cnt<>0 then
             raise_application_error(-20101,'Нельзя удалить поле '||col_name||' таблицы '||tab_name||chr(13)||'пока для него ведётся история изменений');
          end if;
          
          -- удаляем запись из FM_ТАВ_COLUMNS
          delete from sm.fm_tab_columns t where t.fm_tables_id=tab_id and t.columns_id=col_id;
          
          -- уменьшаем ID колонок в таблице SM_CHANGES
          update sm.Sm_Changes t set t.column_id=t.column_id-1 where t.fm_tables_id=tab_id and t.column_id>col_id;
          
          -- уменьшаем ID колонок в таблице FM_TAB_COLUMNS
          update sm.fm_tab_columns t set t.columns_id=t.columns_id-1 where t.fm_tables_id=tab_id and t.columns_id>col_id;
          
          -- вносим название таблицы в X_SM_LOG_TRIGGERS (если хотя бы по одному из полей ведётся история
          select 
            count(*) into cnt  
          from
            sm.Fm_Tab_Columns ftc
          where
            ftc.fm_tables_id=tab_id and
            UPPER(ftc.history)='Y';
          if cnt<>0 then
            insert into sm.x_sm_log_triggers (table_name) values (tab_name);
          end if;  
          
        end if;  
      end if;
    end loop;  
  end if;   
end;
/

prompt
prompt Creating trigger X_SM_MESSAGES_TRANCATE
prompt =======================================
prompt
CREATE OR REPLACE TRIGGER "SM".X_SM_MESSAGES_TRANCATE
  BEFORE INSERT  ON SM.X_SM_MESSAGES
  REFERENCING OLD AS OLD NEW AS NEW
FOR EACH ROW
--declare iTmp number;
begin
      Select SM.SEQX_SM_MESSAGES_ERR.NEXTVAL into :NEW.ID from DUAL;
       if MOD(:NEW.ID, 1000)=0 then
              -- Для некритичных сообщений - удаляем старше 10 дней.
              Delete from SM.X_SM_MESSAGES where MSG_TYPE<3 and MSG_TIME < sysdate-10;
              -- Для критичных ошибок - удаляем старше 356 дней.
             Delete from SM.X_SM_MESSAGES where MSG_TYPE=3 and MSG_TIME < sysdate-365;
               -- Для всех сообщений - удаляем  до 20 тыс. записей.
              Delete from SM.X_SM_MESSAGES where ID < (Select Min(ID) from (Select ID, ROWNUM from SM.X_SM_MESSAGES order by ID desc) where ROWNUM < 20000);
     end if;
end;
/


spool off
